INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('56a631cbc051408bae2cb54f4e6c68ed','4ff53dd874e141ef96803ca1d78fd200',1938,'伪上海特别市市长','投靠日军，出任伪上海市长，协助日伪统治上海，镇压抗日活动；曾任伪上海市长，在徐汇区有官邸活动，协助日军推行殖民统治，普陀地区归其管辖，配合日军经济掠夺和治安维持。为日军统治上海服务，其活动范围涉及杨浦区（原公共租界东区及华界）；协助日伪统治上海，镇压抗日活动，原中国通商银行董事长，为日军征粮征税，管辖包括闵行在内的上海地区，推行日伪统治政策，征收苛捐杂税，压制民众反抗。；投靠日军，管辖包括青浦在内的上海地区，为日军提供物资和情报，积极推行日伪政权政策，镇压抗日活动，后因投敌被军统刺杀于静安住宅。协助日军维持占领区秩序，镇压抗日活动，征收苛捐杂税，为日军提供物资支持。属汪伪体系，其伪政权与华南伪政权有联系。；原上海总商会会长，1938年投敌出任伪上海特别市市长；浙江镇海人，长期在上海活动，镇压抗日力量，1940年被军统策反的仆人刺杀。虽非九江籍，但属江西周边省份及长江下游伪政权体系中的知名汉奸。早年在江西九江、庐山一带经营实业并参与地方事务，配合日军在华中包括江西九江地区的经济掠夺与物资统制，其伪政权体系与九江伪维持会有联系。协助日军控制上海及周边地区，包括浙江部分地区。；浙江镇海人，早年在上海经商，抗战期间投靠日军，1940年被军统策反的仆人刺杀。1940年被军统策反的仆人刺杀。配合日军统治，其伪政权与华中各地伪组织有联系，间接影响湖南。属汪伪体系。；其伪政权与贵州部分商会勾结，通过贵阳口岸进行物资资敌活动。其附逆行为对全国包括陕西有示范影响，配合日军在华东及华北包括陕西周边地区进行统治，配合日军在华东及华北包括陕西周边地区进行殖民统治。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b0a767a5363b41fabac48d8c67b7ad79','62a6d6c8e7ab4bbfbc92c5b14abbde74',1940,'伪上海市长（汪伪政权）','汪精卫政权核心人物，曾任伪上海市长，推行清乡和奴化政策，协助日军控制上海。；汪精卫政权核心人物，曾任伪上海市长，推行“清乡”政策，协助日军搜刮物资，迫害抗日人士。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('62a6eadee0a24d9b904766b721c2e43c','a2e4190c87b449e685d78c118a6801b5',1940,'伪行政院副院长兼伪上海市长','汪伪政权要员，兼任伪上海市长，主持上海日伪政务，参与经济掠夺和特务活动。；汪伪政权核心人物，后期主持上海政务，控制包括杨浦在内的沪东地区，镇压抗日力量。；汪伪政权要员，兼任伪上海市长，控制上海金融与特务机构，参与对抗日力量的镇压。；虽非余姚人，但曾在余姚活动，作为汪伪政权核心人物，协助日军统治浙江地区，推行清乡政策。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7ea6d66f586e4dee845dc56ef2ceab44','9910c48b9b394ffa8c73439ed0a473b0',1939,'伪浙江省长（曾活动于上海）','原军统特务，投日后任汪伪特工总部主任，在上海制造多起暗杀和恐怖事件，后任伪浙江省长。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1250d00229054a5c88a291dd994810a7','07ff958e7f18410f864975f09234ac7e',1939,'伪特工总部（76号）主任','投靠日本，组建上海极司菲尔路76号特工机构，残害抗日志士，制造血案，后因内讧被毒杀。；汪伪特务头子，其特工在杨浦地区（如平凉路、杨树浦路）设立秘密据点，暗杀、绑架抗日志士。；其特工总部设在静安附近，指挥暗杀、绑架抗日人士，制造多起血案，是汪伪特务头目。；在黄浦区极司菲尔路76号设立特工总部，指挥暗杀、绑架抗日志士，制造多起血案，是日军在沪恐怖统治的重要工具。；虽为江苏人，但曾在宁波、宁海地区活动，指挥76号特工在浙东地区破坏地下抗日组织，逮捕杀害多名爱国人士。','特工总部主任','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b5c58588d2c84242a88fc3f3890e0dd3','95e4356f12fb4832b18ecbad49cf091a',1939,'伪76号特工总部警卫队长','李士群手下打手，在上海横行霸道，参与绑架、暗杀和敲诈，恶名昭彰。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7ce081e5a5764b80b6687778d5d2ad0e','3b28a0ae9ced49f4bd465270bab0c94a',1938,'伪嘉定县知事','日军占领嘉定后出任伪县知事，协助日军维持治安、征粮征税，镇压当地抗日武装。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7933e9c86f114a94a48dba4da59ee821','4c0724ba86184ad9aea99954ed4e044b',1940,'伪嘉定县知事（继任）','继任伪嘉定县知事，推行保甲制度，配合日军清乡，强征民夫和物资。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('11e6325d291d429591dfb17a75129de1','40a321f3b2fb4082a88908f431076243',1938,'伪嘉定县警察局长','担任伪嘉定警察局长，搜捕抗日分子，协助日军进行治安肃正，欺压百姓。','市县厅局级','hanjian');
