INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('adc225fc49b64d9c9308dbbe603c2767','1a9b49639f7d4f6aa0ced79d4bcfa373',1938,'伪奉贤县财政科长','为伪政权征收苛捐杂税，侵吞抗日物资，资助日军军费。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a0ed9dc93ca24143acf871154360b105','a8481ebd2a9441349a9cfd5910c4da33',1937,'伪奉贤县维持会会长','日军占领初期出任维持会长，协助日军建立伪政权，强迫百姓“欢迎皇军”，提供劳役。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4ac6b6486b33428e8e1df9ee0c47e843','07ff958e7f18410f864975f09234ac7e',1940,'伪特工总部（76号）驻奉贤特派员','在奉贤设立特务据点，诱捕抗日志士，策反国民党游击队，制造多起暗杀事件。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f8470179cb094f6e915a2ebb7d1f9c88','95e4356f12fb4832b18ecbad49cf091a',1942,'伪奉贤县“清乡”行动队队长','率行动队配合日军“清乡”，焚烧村庄，屠杀无辜百姓，抢夺财物。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a101a223b7f84c54aa1790d2c4dafc80','a2e4190c87b449e685d78c118a6801b5',1943,'伪中央税警总团驻奉贤指挥官','指挥伪税警部队在奉贤沿海封锁抗日运输线，截留物资，协助日军控制港口。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7da9d13dfd1f49f5b7a15d1c6d01d200','28c69a91441d4439abc95701e2c6787a',1941,'伪奉贤县教育督办','推行奴化教育，强制学校使用伪满教材，宣扬“中日亲善”，迫害爱国教师。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('477a679ad5d34033b5c9d70e8e05d32e','0d2d2045fc1d498dab9499e43abcb3de',1942,'伪奉贤县“和平救国军”司令','收编散兵游勇组成伪军，协助日军“扫荡”，在奉贤东部地区烧杀抢掠。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3da65ac2b4bc4662948edfd67eb96839','a8481ebd2a9441349a9cfd5910c4da33',1937,'宝山地区伪保长','日军占领宝山后，出任伪保长，协助日军征粮、拉夫，迫害抗日群众，多次向日军报告抗日武装动向。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('636b1124d0f3415aa524368ee6d2b610','4d50f61a18e842c1bf1f31c1c1e0fbc9',1938,'伪宝山县政府维持会会长','投靠日军，组织维持会，为日军筹款、提供物资，镇压抗日活动，强征民夫修筑工事。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('10ebcd042f104812bffe241ec73c01fe','e2aa6d5adf4a4a1eb2b0e261d3bc0232',1939,'伪宝山保安队队长','率领伪保安队配合日军扫荡，抓捕抗日志士，抢劫百姓财物，民愤极大。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a5afdc192de74973906bf0ae353eb3b1','40a321f3b2fb4082a88908f431076243',1940,'伪宝山警察局巡官','为日军充当耳目，侦缉抗日地下人员，多次带队搜查民宅，逮捕进步人士。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f5c85a43e1d349e5bb7cb373d6429e5e','d12ace54557b469898e7082ec4b63509',1941,'伪宝山税务所主任','为日军征收苛捐杂税，强征粮食，中饱私囊，导致当地百姓生活困苦。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('91ada4a04fc545eba575106f5c11376a','3a8d556cda074bbc94e262319ad90c80',1942,'伪宝山情报组组长','专门收集新四军及游击队情报，多次导致抗日武装遭袭，杀害多名抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e851665397f2480ebf54997ebc5433b3','fa302357fc4d42f1beb8659f6a69e665',1943,'伪宝山乡联防团长','组织乡联防团，配合日军清乡，烧毁村庄，强抓壮丁补充伪军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('60953998e4394d92bbaa197a766147b3','f50cf011f8f842fc8d69caa402ffbf67',1938,'汪伪国民政府内政部长、江苏省长','在崇明及上海地区推行汪伪政权统治，组织清乡，镇压抗日力量，征收苛捐杂税。；曾任汪伪政权要职，在长宁区愚园路一带活动，参与伪政权对上海的控制和镇压抗日力量。；曾任汪伪政权要职，参与清乡运动，镇压抗日力量，在青浦等地推行伪化统治。；曾任伪维新政府内政部长，后任汪伪江苏省长，在江苏推行伪化统治，协助日军清乡，镇压抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('df42c388a4034aaaa9df6507d2cc6148','cebb4769b324411abb6e1f5a0f26ecf6',1938,'汪伪第一方面军总司令、伪江苏省保安司令','指挥伪军在上海崇明等地扫荡抗日游击队，协助日军建立伪政权，控制长江口航道。；驻防南京及江苏，在玄武区一带设立军事机构，协助日军清乡扫荡。；率伪军驻防江苏，参与清剿新四军，在如皋、南通一带多次扫荡。；原国民党军官，投敌后任伪军要职，在镇江、苏南一带配合日军进攻抗日武装，残害百姓。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('64d41942e04441f2a0c9d0fb9c3c93a4','4c0724ba86184ad9aea99954ed4e044b',1941,'汪伪崇明县知事（县长）','在崇明岛推行保甲制度，强征壮丁，配合日军“清乡”，迫害抗日家属。','基层头目','hanjian');
