INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('248f50e957c4416fa59aa0781fb1e6dd','aee70e7afe9e4ccbac9071205bb3f0b3',1943,'汪伪崇明县保安大队长','带领伪保安队配合日军在崇明东部地区“扫荡”，烧毁民房，抢劫物资，杀害抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('028bdd3caf1244c9ae63110c7909e05a','eee6d4f5b7f34d6cadde3250a8b9b049',1939,'伪崇明县商会会长','为日军和汪伪政权筹款，强制商户捐献，垄断粮食贸易，向日军提供军需物资。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('51f459269d6a4413aa0017e39e12d5a1','790f270d584f4863833cd7a8664cd347',1941,'伪崇明县教育督办','推行奴化教育，强制学校使用汪伪教材，宣扬“中日亲善”，迫害爱国教师。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('29172eace0ff4a46a56ac6a67c3184a8','3750bb2a94b64c5e8002d23d1566aa10',1940,'汪伪崇明县税务局长','增设各种苛捐杂税，盘剥百姓，为伪政权和日军搜刮钱财，导致崇明民生凋敝。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b589b60b2d1740bda6e8bc06fc385f5d','5f7e9c77266c43a2aa09fe79ca5a5c5c',1942,'伪崇明县司法承审员','以“通匪”罪名滥捕无辜，刑讯逼供，判处抗日志士死刑，协助日军镇压反抗。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('53b4ae5b97744c219d3d9c2b46192111','a2e4190c87b449e685d78c118a6801b5',1940,'汪伪行政院副院长兼财政部长（曾管辖上海地区）','虽非崇明本地人，但作为汪伪高层，其政策直接覆盖崇明，支持清乡，控制金融掠夺物资。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c9804b61623e44c0837907e984577a46','f50cf011f8f842fc8d69caa402ffbf67',1938,'伪江苏省省长、伪内政部长','早年活动于上海，后投靠汪伪政权，在徐汇地区参与清乡和特务活动，迫害抗日志士。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('03b48a81003f4bd1b08da8fb186c01a2','8204200f4e3242699f2503c2c4b2708e',1938,'伪上海市警察局局长','在徐汇区设立警察机构，配合日军搜捕抗日分子，镇压民众反抗。；投靠汪伪，任伪警察局长，在虹口等地大肆搜捕抗日地下工作者，配合日军进行“清乡”行动。；任伪警察局长期间，在静安等区域设立特务机构，搜捕抗日志士，协助日军维持殖民统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4cfc1186881146709bbf77bf7644b818','3b28a0ae9ced49f4bd465270bab0c94a',1940,'伪上海特别市社会局局长','在徐汇地区推行奴化教育，控制社会团体，为汪伪政权服务。；负责伪政权社会控制，在静安地区推行保甲制度，监控民众，配合日军经济统制。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6f1b301f29084f71a63d8f4612430147','a7e83207d27c44cb9b0eda4dfd99a112',1938,'伪上海特别市政府秘书长','参与伪政府行政事务，在徐汇区协助日伪征收捐税，压迫市民。；长期担任伪市政府秘书长，参与策划对静安等地的“清乡”行动，协助汪伪政权镇压抗日力量。；协助傅筱庵管理伪市政府，参与制定奴化教育政策，迫害爱国师生，为日军征用民房和物资。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4d67db7bf9b247a08c36f580492ae47f','07ff958e7f18410f864975f09234ac7e',1939,'汪伪特工总部（76号）主任','其特工组织在徐汇区设有据点，绑架、暗杀抗日人士，制造白色恐怖。；在虹口及上海设立特工据点，指挥暗杀、绑架抗日志士，制造多起血案，后因内讧被毒杀。；在长宁区设有秘密据点，指挥特务活动，迫害爱国人士，是上海汉奸特务体系的核心人物。；负责汪伪特务活动，在青浦及上海周边地区捕杀抗日志士，制造白色恐怖。','特工总部主任','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ac46df3c24bf446e9326ed77118fda8f','9910c48b9b394ffa8c73439ed0a473b0',1938,'汪伪特工总部副主任、伪社会部长','在徐汇地区指挥特务活动，破坏地下抗日组织，罪行累累。；湖南常德人，抗战期间投靠汪精卫，与李士群共同组建伪特工总部，任副主任，后任伪社会部长等职，参与镇压抗日活动。籍贯湖南，与湖南有直接关联。；湖南常德人，早年加入中共后叛变，抗战期间投靠汪伪，与李士群共同组建汪伪特工总部，任副主任、伪社会部长等职，参与汪伪政权对沦陷区的特务统治。；参与伪特工活动，迫害抗日人员，战后以汉奸罪被处决。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7878d119738f4fe5ae410c91188b88df','0d2d2045fc1d498dab9499e43abcb3de',1940,'伪上海特别市副市长','在徐汇区协助傅筱庵管理市政，推行日伪政策，参与经济掠夺。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ed1735d8c96c47128e8afc66c80c9745','ed0d68ce0e0f4e40ba88774709d7fea6',1941,'伪上海特别市警察局副局长','在徐汇区指挥警察镇压罢工和抗日活动，抓捕进步人士。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0798d6e993e64eba9766b8043d8ffbf9','d3256e7274c448058c67c4d51c3fa885',1940,'汪伪宣传部政务次长','曾在徐汇区居住，从事文化宣传，为汪伪政权鼓吹“和平运动”。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c7fb309de1eb455185c1962f2f65a406','a2e4190c87b449e685d78c118a6801b5',1939,'汪伪行政院副院长、财政部长','虽主要活动于南京，但在上海徐汇区拥有房产，参与日伪金融统制，间接影响该区。；虽为中央级，但直接控制上海包括普陀的伪政权运作，支持特工活动。；虽主要在上海活动，但通过伪政权系统控制青浦县财政和物资征调。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d50b1f2954e44e65afea722fb10e06d6','28c69a91441d4439abc95701e2c6787a',1940,'汪伪中央执行委员、实业部长','在徐汇区参与经济统制，协助日军掠夺物资，支持伪政权运作。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c485e15e7bc9477c8312b8990acf111d','d1abe59a5d664bf18b442130fc0478a1',1940,'汪伪宣传部部长','在徐汇区推动奴化宣传，控制报刊广播，为日伪张目。；在青浦地区进行奴化宣传，控制地方教育。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b8592d89924544a48018fc5230ba0a61','62a6d6c8e7ab4bbfbc92c5b14abbde74',1944,'伪上海市长（1940年代后期）','在徐汇区推行“清乡”和保甲制度，强化日伪统治，镇压抗日力量。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8b49079e83394b5a873dfe213592384b','664d3df731bb4293bee63eea6deacb2d',1940,'汪伪外交部长、广东省长','曾在徐汇区活动，参与汪伪政权对外交涉，协助日本侵略政策。；虽非直接驻青浦，但参与汪伪高层决策，影响青浦伪政权。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4ee0cdbe36434600905021a8f49cd505','cebb4769b324411abb6e1f5a0f26ecf6',1940,'伪第一方面军总司令','其部队在徐汇区驻扎，协助日军维持治安，镇压抗日游击队。；率伪军驻江苏安徽交界，多次进犯安庆地区，协助日军扫荡。；率伪军驻防安徽，在芜湖鸠江地区清乡扫荡，杀害抗日军民。；其伪军部队驻扎浙江，曾参与对宁波、镇海地区的扫荡和清剿。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('26f824b8ec1843f7b466c4570524043a','bb34b45b44c34a018d410cde66579fb1',1940,'伪陆军部长','在徐汇区参与军事训练和治安维持，为日军提供军事支持。；汪伪军事要员，负责整编伪军，其军事部署涉及安徽，包括安庆、大观。；负责伪军整编，其指挥的伪军部队在浙江包括绍兴、诸暨驻防。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cbf6cd9f395449b0adf0f6fb94eb4b49','67197bb8299842ec9bb45a68c808f099',1941,'伪上海特别市地政局局长','在徐汇区强征土地，为日军和伪军建设设施，侵害居民利益。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('875ca3fb87a64e6abfd693381ca19628','f38e9756e9e84914a0729c52ab4b23a4',1942,'伪上海特别市卫生局局长','在徐汇区推行日伪卫生政策，控制医疗资源，为日军服务。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('26a3ad7b75564837b3acb2fa0e5ec3dc','cd5e7ea304eb427ab2364bdecd6fd730',1940,'伪上海特别市教育局长','在徐汇区学校推行奴化教育，篡改历史，灌输亲日思想。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2a8a1cbc4e5049c898e9a3eda149f4ab','f50cf011f8f842fc8d69caa402ffbf67',1938,'汪伪政府内政部长、江苏省长','曾任伪维新政府内政部长，后任汪伪江苏省长，在普陀地区推行伪化统治，镇压抗日活动。；曾任伪维新政府内政部长，后任汪伪江苏省长，在闵行地区推行清乡政策，镇压抗日力量。；曾任伪维新政府内政部长，后任汪伪江苏省长，在无锡、宜兴等地推行清乡政策，镇压抗日力量。；曾任伪维新政府内政部长，后任汪伪江苏省长，在镇江地区推行伪化统治，协助日军清乡扫荡。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d1b0a268292f4b55869a31f32993e903','8204200f4e3242699f2503c2c4b2708e',1940,'汪伪上海特别市警察局局长','负责上海（含普陀地区）伪警察系统，协助日军搜捕抗日志士，实施保甲制度。；管辖包括长宁区在内的伪警察系统，配合日军推行“清乡”和治安强化运动，逮捕抗日分子。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('17090154624c4b1682c786588b861a08','3b28a0ae9ced49f4bd465270bab0c94a',1941,'汪伪上海特别市普陀区区长','担任伪普陀区区长，推行日伪征粮、劳役政策，迫害当地居民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5dcc495fd4b840289ad4e92e755bb57e','95e4356f12fb4832b18ecbad49cf091a',1939,'汪伪76号特工总部行动队长','率特工在普陀地区绑架、暗杀抗日人士，制造多起恐怖事件。；率特务在长宁区（如愚园路、兆丰公园附近）绑架、暗杀抗日人士，制造多起恐怖事件。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('94752673d0064d95b38a565818748fd8','07ff958e7f18410f864975f09234ac7e',1939,'汪伪特工总部主任','指挥76号特工在普陀及上海各地破坏地下抗日组织，残害进步人士。；在湖南沦陷区建立特务网络，与邵阳地区伪政权合作，镇压抗日活动，迫害抗日人士。；组建伪特工组织，镇压抗日人士，后与日方矛盾被毒杀。','特工总部主任','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d7b46da37e7c4b1289613251c50f8f95','9910c48b9b394ffa8c73439ed0a473b0',1939,'汪伪社会部长、特工总部副主任','参与策划对普陀地区抗日力量的镇压，推行奴化教育。；其特务网络延伸至苏北，在东台、盐城布置情报点，破坏抗日组织。；其特工网络延伸至盐城、阜宁，暗杀抗日人士，破坏地下组织。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9d59c91858044639b8d1dc113d06e150','96b96eb8f5414a1f874f70f38feb0054',1938,'伪上海特别市副市长','协助傅筱庵管理普陀等区，推行伪政令。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a3b715d8c45a4c06bef6c83ae0b376e1','0a4924f6632d45fa995bce0378e07a94',1941,'汪伪普陀区警察署署长','指挥伪警在普陀地区抓捕抗日嫌疑犯，协助日军清乡。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a82194e4013d4c3aadda915cf8db63f1','62a6d6c8e7ab4bbfbc92c5b14abbde74',1940,'伪上海市长（兼）','汪伪政权要员，兼任伪上海市长期间，推行清乡和奴化政策，杨浦地区在其管辖下。；汪伪政权核心人物，兼任伪上海市长，推行“清乡”政策，配合日军搜捕抗日人士，强化殖民统治。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('669aa43435b846ec98988cd2cbe7e2e0','a7e83207d27c44cb9b0eda4dfd99a112',1940,'伪上海特别市警察局局长','负责伪上海警察系统，在杨浦地区设立分局，协助日军搜捕抗日人士，残害百姓。','市县厅局级','hanjian');
