INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e5f4764f79bf4c2e83ba5e930300595f','3b28a0ae9ced49f4bd465270bab0c94a',1942,'伪上海特别市沪东区公署署长','管辖杨浦地区（沪东区），推行日伪保甲制度，强征粮食和劳工，为日军服务。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('97fb4c59e319400fad846302c41464df','0a4924f6632d45fa995bce0378e07a94',1943,'伪上海特别市沪东区公署副署长','协助潘达管理杨浦地区，参与镇压抗日活动，征收苛捐杂税。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bfe67da740294cb0ae00daf4462eab45','9910c48b9b394ffa8c73439ed0a473b0',1939,'伪特工总部（76号）副主任','与李士群共同指挥特务活动，在杨浦地区制造白色恐怖。；与李士群共同领导76号，策划破坏中共地下组织，残害进步人士，参与“清乡”行动。','特工总部主任','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c66392a6545343d39f7228a5c6baaf0f','ebe896a3d1334faaaa5c0b701b122f47',1940,'伪江苏省政府委员兼伪上海特别市社会局局长','负责伪社会事务，在杨浦地区推行奴化教育，组织汉奸团体。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8469874cdb8243878a998dcba257e9ca','0d2d2045fc1d498dab9499e43abcb3de',1940,'伪上海特别市秘书长','协助陈公博处理伪市府事务，参与对杨浦地区工厂的掠夺和控制。；协助周佛海管理伪上海事务，在闵行地区推行保甲制度，强化汉奸统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8f057f53464043199626ef02a67d65d1','ed0d68ce0e0f4e40ba88774709d7fea6',1941,'伪上海特别市保安司令部副司令','指挥伪保安队在杨浦地区巡逻、镇压罢工和抗日活动。','市县厅局级','hanjian');
