INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c59dfe6dcf414de787337d5871beec4b','3b28a0ae9ced49f4bd465270bab0c94a',1943,'伪虹口区公署署长','继苏锡文后任伪虹口区署长，管理虹口地区民政，强制推行“市民证”，协助日军征用物资。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1472d0fea9404ce2bef1c76042eac844','9910c48b9b394ffa8c73439ed0a473b0',1939,'汪伪特工总部（76号）副主任、伪社会部部长','与李士群共同控制76号，在虹口地区残害进步人士，后任伪社会部长，推行“新国民运动”。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b5ef47d523a943e69b9dd653dc649a46','a2e4190c87b449e685d78c118a6801b5',1944,'汪伪行政院副院长、伪上海市市长（兼任）','汪伪政权核心人物，兼任伪上海市长期间，加强对虹口等地的控制，协助日军搜刮战略物资。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7da5db4e6fea413096b14ae5920111af','0d2d2045fc1d498dab9499e43abcb3de',1940,'伪上海特别市政府秘书长、伪司法行政部部长','周佛海亲信，代理伪上海市政事务，在虹口推行“米粮统制”，导致民不聊生。；曾任伪市政府秘书长，在静安区域推行日伪法令，参与经济掠夺和镇压抗日运动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f1d46ce0a5ad49179e6529965cb64d3b','d4166b7f27b84e4092215bec1daf09de',1940,'伪上海特别市参事会参事、伪虹口区顾问','参与伪虹口区行政决策，为日军提供情报，协助管理“日侨区”事务。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ab431c41f31e46ff8ececc3176fa7979','ebe896a3d1334faaaa5c0b701b122f47',1940,'伪上海特别市社会运动指导委员会主任','在虹口组织“和平救国”游行，破坏抗日宣传，协助日伪控制工人运动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9e393cb0ab4843e68d1f01b3eeecc838','26ee1b3bf7624eecb241c56d93677fc4',1939,'伪虹口区警察署署长','直接指挥虹口地区伪警，多次围捕抗日分子，参与“虹口大逮捕”事件。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d604ed4db04845e3a47cacc20fd1908c','0a4924f6632d45fa995bce0378e07a94',1940,'伪虹口区保安队队长','率领伪保安队协助日军巡逻虹口，镇压民众反抗，强征壮丁。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c3c02a3178894d08b0ea8049cf638cba','6b77db7f8b95433a9a22ee22bf0512fb',1941,'伪虹口区税务局局长','在虹口增设各种苛捐杂税，为日伪政权筹集军费，中饱私囊。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0ba83375ee9a43b98458d679fed42dde','4e3bfa46f6b94e4691c2887e1ee4a585',1943,'伪上海特别市粮食管理局局长','在虹口实施粮食配给制，克扣口粮，导致大量市民饿死，与日军勾结倒卖粮食。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5dd42f9f38d74f05a5024b62461869b6','f2d71aacccf2408ca8a3b9e5238ee019',1943,'伪上海特别市清乡事务局局长','在虹口及周边推行“清乡”，设立封锁线，搜捕抗日游击队和地下党。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9085884c0986423fb53762a0fe4bde74','8a4a65c59beb4c3f9cabed02ac3f57ba',1939,'汪伪特工总部76号行动队长','原军统叛徒，在虹口地区执行多次暗杀和绑架，杀害多名抗日志士。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('337b71c67faf4713a334b8f7d8fef4ae','f93912e8e2a041ee84289c2a3b463a68',1942,'伪虹口区宣传科长','负责虹口地区日伪宣传，发行《新申报》虹口版，散布“大东亚共荣”谎言。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('852d29eac0cc417ea1b6a9575618bca6','993e4eff978c4539b275a1e53335a341',1937,'伪浙江省政府参议、伪上海特别市参议','青帮头目，投靠日伪，协助日军控制上海码头，镇压抗日活动，1940年被暗杀。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b3bb0b9caa89493fb8ab77161ad8840a','f50cf011f8f842fc8d69caa402ffbf67',1938,'伪内政部长、伪江苏省长（辖金山）','曾任伪维新政府内政部长，后任伪江苏省长，在金山地区推行清乡和奴化教育。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5af5b15ad80444e994af2efea95c3976','07ff958e7f18410f864975f09234ac7e',1941,'伪江苏省长、特工总部主任','76号特工头目，兼任伪江苏省长，在金山等地残酷镇压抗日力量，1943年被毒杀。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ea01e31bb02144e99392ae06b046e87f','9910c48b9b394ffa8c73439ed0a473b0',1939,'伪浙江省长、伪社会部长','76号特工首脑之一，后任伪浙江省长，曾参与对金山地区抗日武装的围剿。；与李士群共同控制76号，后任伪浙江省长，战后被处决','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1c7e33e531d2494db50d044598f025a6','a2e4190c87b449e685d78c118a6801b5',1940,'伪行政院副院长、伪上海市长（1945）','汪伪政权核心人物，1945年兼任伪上海市长，管辖包括金山在内的上海地区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2079c4f0515b42ebb193dcf86c35f88c','0d2d2045fc1d498dab9499e43abcb3de',1940,'伪安徽省长、伪司法行政部长','汪伪骨干，曾任伪安徽省长，后调任伪司法行政部长，参与清乡计划，涉及金山地区。；汪伪核心成员，曾任伪安徽省长，在安徽推行伪化教育、征粮与清乡。；汪伪政权要员，曾任伪安徽省长，直接参与对安徽沦陷区（含宣城）的统治。；曾任伪安徽省长，在安徽沦陷区推行伪政，宣城一带受其管辖。；曾任汪伪安徽省长，直接负责安徽沦陷区伪化统治，其辖区涉及宣城一带，推行征粮、清乡等政策。；湖南人，但在汪伪政权中曾任伪安徽省长，对安徽沦陷区包括宣城、郎溪一带实施伪化统治。；汪伪政权核心成员，曾任伪安徽省长，在安徽推行伪政令，强化对滁州、凤阳等地的控制，参与征粮、清乡等行动。；湖南湘乡人，汪伪政权要员。曾任伪安徽省长，在安徽沦陷区实施伪化统治，其势力覆盖黄山、休宁一带。；湖南湘乡人，汪伪政权要员，曾任伪安徽省长，在安徽推行伪政权的各项政策，协助日军维持占领区秩序。；随汪精卫投敌，曾任伪安徽省长，在安徽推行伪政权统治。；原为国民党官员，后投日，曾任伪浙江省政府顾问，参与宁波地区日伪统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b446a5eb995e49189ad73f6efe0bcc06','28c69a91441d4439abc95701e2c6787a',1940,'伪内政部长、伪浙江省长','汪伪政权重要成员，曾任伪内政部长，后任伪浙江省长，对金山地区有行政管辖。；参与汪日密约谈判，历任伪内政部长等职，战后被处决','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('34572b006edd4143906fbc3fd400a871','d1abe59a5d664bf18b442130fc0478a1',1940,'伪宣传部长','汪伪宣传部长，在金山等地推行奴化宣传，鼓吹“和平建国”。；负责汪伪宣传，在安徽包括安庆、大观地区推行奴化教育，美化日军侵略。；负责汪伪宣传，在安徽等地推行奴化教育，影响安庆迎江地区民众思想。；负责汪伪宣传，在安徽芜湖鸠江地区散布亲日言论，美化侵略。；主管汪伪宣传，鼓吹“和平反共”，战后被处决；广东人，汪伪政权宣传部长，控制沦陷区舆论，进行亲日宣传。；汪伪宣传头目，在江西九江等沦陷区推行奴化教育、伪化宣传，控制报刊与学校。；广东人，但长期在浙江活动，负责汪伪宣传，在奉化等地散布亲日言论。；原为汪精卫亲信，投日后负责伪宣传，在浙江宁波地区散布亲日言论，破坏抗日舆论。；负责汪伪宣传，在浙江宁波地区发行汉奸报刊，美化日军侵略。；负责汪伪宣传，在绍兴、诸暨等地散布“和平建国”言论，麻痹民众抗日意志。；在舟山地区推行奴化宣传，控制当地报纸和广播。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5aff89e281014ccf88852f848e231773','62a6d6c8e7ab4bbfbc92c5b14abbde74',1940,'伪国民政府代主席、伪上海市长（1940-1941）','汪伪二号人物，曾任伪上海市长，对金山地区实施日伪统治政策。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e33916aede4d482e8b0331377b604146','664d3df731bb4293bee63eea6deacb2d',1938,'伪外交部长、伪广东省长','汪伪亲日派，曾任伪外交部长，后调任伪广东省长，未直接管辖金山但参与汪伪高层决策。；汪伪政权要员，曾参与对安徽地区的伪政权组织活动，间接影响安庆、大观。；汪伪政权要员，曾参与对安徽沦陷区的行政协调，间接涉及安庆地区。；汪伪政权要员，安徽宣城泾县人，参与对日外交与伪政权运作。；汪伪政权要员，曾参与策划对安徽地区的伪化统治，其政策影响芜湖鸠江地区。；安徽籍（一说浙江），汪伪政权要员，任伪外交部长、伪广东省长等职，参与对日外交卖国活动，1946年以汉奸罪被处决。；汪伪要员，曾任伪广东省长，在广东协助日军维持统治。；汪精卫连襟，长期担任伪外交部长，出卖国家主权，战后被处决；浙江湖州人，汪伪政权外交部长，参与签订卖国条约，其伪政权体系影响江西沦陷区。；浙江湖州人，汪精卫连襟，投敌后任伪外交部长等职，参与签订卖国条约。；汪伪政权要员，配合日军在华中包括江西沦陷区的伪化宣传与外交欺骗。；浙江吴兴人，汪伪政权要员，任伪外交部长等职，参与伪政权对河南等沦陷区的统治。；浙江吴兴人，虽主要任职广东，但曾参与对浙江宁波的日伪合作，协助日军经济掠夺。；原为国民党元老，后投日，虽主要活动于广东，但曾参与汪伪对浙江宁波的统治策划。；虽主要任职广东，但曾以汪伪代表身份到宁波、镇海活动，协助日军建立伪政权。；浙江吴兴人，汪伪政权要员，曾任伪外交部长，虽主要活动于南京、广东，但曾参与浙江伪政权高层决策，影响杭州地区。；汪伪政权要员，曾参与对浙江地区的“和平运动”宣传，为日军占领绍兴、诸暨制造舆论。；浙江吴兴人，抗战期间投靠汪精卫伪政权，历任伪外交部长、伪广东省长等职，参与汪伪政权对湖南等地的伪化统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('37ff333089c94e5881c9fec3a9078bc0','cebb4769b324411abb6e1f5a0f26ecf6',1938,'伪第一方面军总司令、伪海军部长','原国民党将领，投敌后任伪军头目，在金山沿海地区协助日军清剿游击队。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('829c852bcb4043949a7bfdc48f1f0420','2da345b6c2e840b18cda3eba84087f6b',1938,'伪金山县知事（县长）','投靠日伪，任伪金山县知事，为日军征粮、抓壮丁，镇压当地抗日民众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f22befd0ccd447dba4cd519b2c7da626','0a4924f6632d45fa995bce0378e07a94',1941,'伪金山县知事（继任）','继任伪金山县知事，推行保甲制度，协助日军“清乡”，迫害抗日家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('822869361c44436894faba1012b731b0','d4658c60fe664645a15fc8b3c34f247d',1943,'伪金山县知事（后期）','后期伪金山县知事，配合日军掠夺粮食资源，压制抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8cea9099b24649278cf572470e73951c','c2ccd6b18f4d489f96b18edb8f87de38',1938,'伪金山县警察局长','任伪警察局长，抓捕抗日志士，为日军提供情报，参与屠杀平民。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5c54bb21318142c0ad0c2869840409aa','008f5176fd8f4b5aa187caafb5c10bb7',1939,'伪金山县保安队长','地方恶霸投敌，任伪保安队长，率队袭击抗日游击队，残害百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('96495a1dfafb484b8dcac79cda61bc94','0e9ef635240240c3bed86731748bb69a',1940,'伪金山县商会会长','投靠日伪，任伪商会会长，为日军筹集物资，强迫商户“献金”。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2278db6233fe46b1a6adab4f13a3de02','be969933cd3247029b8e2d69f1f2c1b2',1937,'伪金山县维持会会长（初期）','日军占领金山后率先组织维持会，为日军带路、征夫，协助建立伪政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6de8c46af2174272acc359718638743d','e1edba3cde9e497b8e44cbf62955479a',1938,'伪金山县漕泾镇镇长','在漕泾镇为日军效劳，强征民夫修筑工事，告密杀害抗日分子。','无明确职位或一般帮凶','hanjian');
