INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('47f3f705cce446fa9590fcfe1a10ca5b','28c69a91441d4439abc95701e2c6787a',1940,'伪上海特别市市长（未到任）','曾被任命为伪上海市长，虽未实际到任，但参与策划对静安等地的伪化统治方案。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5282aecd0adb47afafc0b87facb0ab4f','d4166b7f27b84e4092215bec1daf09de',1938,'伪上海特别市财政局局长','在静安地区征收苛捐杂税，为日伪政权筹措军费，侵吞抗日财产。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('03ea44e9c6094b999b2767732949e54e','ff7e839d04e04c73833b017b9cee9c9d',1938,'伪上海特别市教育局长','在静安等区推行奴化教育，强制学校教授日语，篡改历史教材。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d86b5ff0b7e84cd2a53774b6689a54d6','500f0af67cb94ff488f07851a8825f02',1940,'伪上海特别市警察局副局长','协助卢英管理静安地区警务，参与搜捕抗日地下党员，破坏情报网络。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d7f7f4636932488c8f542e548a904504','8a4a65c59beb4c3f9cabed02ac3f57ba',1939,'伪特工总部行动队队长','在静安地区指挥暗杀、绑架活动，杀害多名抗日爱国人士，后投靠日军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('07c5cb42e2f54046a4d4f347ee6d756d','f2d71aacccf2408ca8a3b9e5238ee019',1939,'伪特工总部警卫队长','负责76号在静安一带的武装行动，参与镇压学生运动和工人罢工。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9ee1e68e112d4848a2169c9b7c138af3','9a6ddf69575e488480603c12171ac907',1941,'伪上海特别市地政局局长','在静安地区强占民房土地，为日军修建军事设施，迫害原住民。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b06d238a1807429a87fad4b1dec57b6c','6b77db7f8b95433a9a22ee22bf0512fb',1942,'伪上海特别市卫生局局长','在静安区域推行日军防疫政策，强制居民接受人体实验相关检查，配合细菌战研究。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('007b2908e2ac4090b065df4fe0b9a951','0a4924f6632d45fa995bce0378e07a94',1940,'伪上海特别市公用局局长','控制静安地区水电交通，为日军军事运输和物资调配提供便利。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a1e0838e948d43d6b6c0705b5438450f','a2e4190c87b449e685d78c118a6801b5',1944,'伪上海市长（后期）','汪伪政府要员，后期兼任伪上海市长，主持“和平救国”运动，协助日军经济掠夺，镇压地下抗日力量。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7b3fc320d55d48a49ab54e1bcf4f2774','0e80f903b43d43379872095d5014aa4b',1938,'伪上海特别市财政局局长','为日军筹集军费，推行“中储券”强制兑换，掠夺上海金融资产，导致民生凋敝。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('118c1fad7cde48e78c4a6b55a83186a9','f50cf011f8f842fc8d69caa402ffbf67',1938,'伪上海特别市教育局长','推行奴化教育，修改教科书，强制学校教授日语，禁止抗日思想传播，迫害爱国教师。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c70b99cfaf8843c8ab2f99972aaafebd','96b96eb8f5414a1f874f70f38feb0054',1939,'伪上海特别市社会运动指导委员会主任','组织汉奸团体，破坏工人罢工，煽动市民支持日伪政权，协助日军控制舆论。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7db0b687d87e42b98ffc8bb84139522e','ebe896a3d1334faaaa5c0b701b122f47',1940,'伪上海特别市地政局局长','协助日军强征黄浦区土地，用于军事设施和日侨居住，驱逐原住民，造成大量难民。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('87d9f15454244de888fa64ead71b39de','0d2d2045fc1d498dab9499e43abcb3de',1941,'伪上海特别市司法局局长','设立伪法院，审判抗日人士，判处“思想犯”重刑，为日军镇压提供法律借口。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ebd75788bf7e4bb0bd620e51ef2c894d','500f0af67cb94ff488f07851a8825f02',1940,'伪上海特别市宣传处处长','控制《新申报》等汉奸报刊，散布“大东亚共荣”谬论，污蔑抗日力量，美化日军暴行。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c48671e0d81b4e849b98359123f2b861','cd5e7ea304eb427ab2364bdecd6fd730',1938,'伪上海特别市卫生局局长','配合日军防疫部队，在黄浦区强制推行“防疫”措施，实则进行细菌实验，导致平民死亡。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7f77bb318c0f423f8b94182fafa5eb80','be538adcf62d4869b07b3b7c7cc0790d',1938,'伪上海特别市公用局局长','管理水电交通，优先保障日军和日侨需求，限制中国居民用电用水，配合经济封锁。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('988871031a8448c2a275be45a3d5d634','f2d71aacccf2408ca8a3b9e5238ee019',1940,'伪上海特别市保安司令部副司令','指挥伪保安队参与“清乡”，在黄浦区及周边扫荡抗日游击队，屠杀无辜百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e723b0b3820e4ba8a02295f7a8048451','845de899b20e4631bbf68676aa47dec8',1941,'伪上海特别市党部主任委员','组织伪国民党，拉拢社会败类入党，为汪伪政权制造民意假象，监视市民言行。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a9f15e8bb727478fae03a63cdcd57019','5660223d0fec4787abc580c10ee4c9a6',1939,'伪上海特别市政府顾问','作为日本顾问团成员，参与制定殖民政策，协调日军与伪政府关系，推动“以华制华”。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c3185218248740818b2c971ba942226a','f19b05dde9eb4bafb71e5fedcd5a10a8',1931,'未任伪职，但曾被日方拉拢未成','作为云南省主席，龙云始终未附逆，但日方曾多次试图拉拢；此条仅作排除性说明，非汉奸。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('734f6cc526054a5084f63d0b6deecee9','c78f7cbace5745088165e412807d4ba1',1931,'无伪职','云南籍元老，坚持抗日，未附逆；此条仅作排除性说明，非汉奸。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('898830284bc34a45a38516d9641a095d','fa2f1833bce1467bb91079eceb0f8e9f',1931,'无伪职','云南籍人士，未见可靠汉奸记录；此条仅作排除性说明，非汉奸。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d8fba7fa9cc448c7b8138f53cc9ccefe','c818d21e85994bec9f1c88e3d94165e1',1931,'无伪职','云南籍人士，未见可靠汉奸记录；此条仅作排除性说明，非汉奸。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cc1f5d23109445f6ba562c0eefa55a59','caf555a200b74b67a472c28f902ab9fb',1942,'维持会成员（姓名多不可考）','1942年日军侵占滇西怒江以西地区后，保山、腾冲、龙陵等地曾出现维持会、伪政权组织，但具体姓名多散佚，可靠名录极少。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0027b115a4f0491790a56dadfe0f153a','e43ac9edf0814337ae8a6d3d22488cc6',1942,'伪腾冲县维持会/伪政权人员（姓名多不可考）','日军占领腾冲期间，当地曾建立维持会及伪政权，但除少数回忆资料外，可靠姓名与职务记载有限。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('438f3f7dbbf246508473bcd3878a25e2','67d708398fca43e18289449e87428540',1942,'伪龙陵县维持会/伪政权人员（姓名多不可考）','日军占领龙陵期间，当地曾出现维持会及伪组织，具体人员姓名多不可考。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0f22bb91abcb492eb265ce6e91d62b48','c05710af9dd848dcb4703f924a5bf76c',1942,'伪军/伪警察头目（姓名多不可考）','滇西沦陷区曾出现伪军、伪警察及便衣队等组织，但除零星记载外，可靠姓名与职务资料很少。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f0c3042cbffd45be980b79d6cba260cb','887a12115f7c4f1faadc7f22193f7337',1942,'滇西伪政权相关人物、地方武装头目','龙云之子，抗战时期在滇西一带拥有地方武装。日军侵占腾冲、龙陵后，其部在滇西局势混乱中一度与日伪方面有接触和妥协传闻，后离开滇西。相关记载多与滇西失守后地方势力动摇、附敌嫌疑有关。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('859fa1b78a12470fb5be22dd8ed9f9b3','aa97f0db7da847e095b67ffeddb0712a',1942,'滇西边地土司、伪维持会相关人物','滇西边地土司势力代表之一。日军侵入滇西后，部分边地土司在威逼利诱下与日军合作，参与维持会或伪政权活动。刀京版常被列入滇西边地附日势力相关记载中。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('96b1ad2de9014462af6ff1d3f0acb4ac','64250c97c26d43e483d8a71f50a892a3',1942,'滇西边地土司、伪政权合作者','滇西沦陷期间，部分土司在日军控制下出任伪职或协助征粮、维持地方秩序。线光天在相关史料中曾被提及与日军占领当局合作。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1bd558c5b43f4fc6b2892b6d40ed8421','dc94893581a2428c9783cde9c8541f0c',1942,'滇西边地土司、伪维持会成员','日军侵占滇西后，腾冲、龙陵及周边边地出现维持会组织。龚绶作为地方土司势力人物，被部分史料列为与日伪合作、参与维持地方治安者。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('db3d2430fb644a319638d8419888197d','a3336fdfda49429bba323ee0f05d92fb',1942,'腾冲伪维持会成员','1942年日军占领腾冲后，当地成立维持会以协助日军统治。杨绍诚被记载为参与维持会事务、为日军筹粮派款的地方附逆者之一。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0a2575d6ee5c4f66843e4106df322682','c78f7cbace5745088165e412807d4ba1',1942,'腾冲地方士绅（附逆嫌疑，史料有争议）','李根源为腾冲著名士绅，抗战时期主要在外从事抗日活动。部分地方史料中曾出现其亲属或地方关系人与日伪接触的记载，但李根源本人并非公认汉奸，此处仅列相关争议线索。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f0369b52ec584fc5a2411863e7ceccd0','9e072d80aa7b4da6b90de10af430d7a3',1942,'腾冲抗日县长（非汉奸，相关对照人物）','张问德在腾冲沦陷后坚持抗日，拒绝与日军合作，并发表《答田岛书》。其事迹常被用于对照当地附逆者，故不作为汉奸列入，仅说明腾冲伪政权相关背景。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('989e7db66b26407eabaf67cf38dfb242','5d298ee4725b4bafbd4f45cddd4b8dc4',1942,'腾冲伪警察或伪维持会头目','腾冲沦陷期间，日军扶植伪警察和维持会维持城区秩序。董友芹在部分地方文史资料中被提及为协助日军搜捕抗日人员、催征物资的附逆人员。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ec024bfab5ef463e9711fb0e6390f452','b042eab93e204143a03cce46ae260d81',1942,'滇西伪政权工作人员（待考）','滇西沦陷区伪政权档案中，部分基层人员姓名散见于维持会、伪乡保组织记载。尹明德被部分资料提及与腾冲伪组织有关，但可靠细节有限。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('901fde0292df4840b4aac606c02f1bb0','eeeb8c3c2bc9498fa146e556955947b1',1942,'龙陵伪维持会成员','龙陵与腾冲同属滇西沦陷区。杨吉品在相关史料中被列为龙陵伪维持会人员，协助日军征粮、派夫和维持占领秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('44bae0285ad3407383f58773f0200f93','be2f8ce389f343f89323e15fc263d881',1942,'滇西伪军头目','滇西沦陷后，日军收编地方武装组成伪军。赵伯钧被部分资料记载为参与伪军活动，配合日军对腾冲、龙陵周边进行扫荡。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d689c37b946d4935ac9491e0ce4c7416','289ae8c3458f4609a800c782181fba46',1942,'保山地区伪保甲长','保山及滇西沦陷区边缘地带，部分保甲长在日军压力下协助征粮、派款、传递情报。李国清被地方史料提及为保山一带附逆基层人员。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6e1183510d4f49868661eae1f9823a97','8195010184b14f89aab25439c52be786',1942,'滇西伪维持会成员','在腾冲、龙陵沦陷区，维持会负责为日军筹措物资。王开基被部分文史资料列为参与维持会、协助日军统治的地方人员。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f3da0bc6f4f54c8c9dbdfa26584f2bab','067b8e028f5740dfa47b25db64ed7534',1942,'云南沦陷区伪教育界附逆者','日军在滇西占领区推行奴化教育，部分教育界人士参与伪学校或伪教育组织。刘明德被相关记载提及在滇西附逆教育机构任职。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('12f1ae94f53844b3a36550123841e6a8','014286f31f23468380cad1e9befe9daa',1942,'滇西边地伪政权合作者','段承钧为滇西边地地方势力人物，日军侵入后被指与占领当局合作，参与维持地方秩序和征调物资。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dd11e26b75ac405ca13c165e56d2ca76','887a12115f7c4f1faadc7f22193f7337',1942,'滇西伪政权相关人物（未直接任伪职，但与日方有接触）','龙云之子，抗战期间在滇西与日军有接触，其活动范围涉及保山、腾冲一带，但具体附逆行为史料记载有限。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a465ec841eb944499d4192b6078638e7','289ae8c3458f4609a800c782181fba46',1942,'腾冲维持会会长','日军占领腾冲后，出面组织维持会，协助日军维持地方秩序、征派粮秣，活动范围属保山地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ce8192d9df9942bbba24093b23b5cc74','eeeb8c3c2bc9498fa146e556955947b1',1942,'腾冲伪警察局长','在日军占领腾冲期间任伪警察局长，协助日军搜捕抗日人员、维持治安，属保山地区伪政权人物。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('03c04ce5f3ba437f91eda59f6d9fc034','ab28eebcbeb24e28b2eb21a075fc6936',1942,'龙陵维持会会长','日军占领龙陵后组织维持会，为日军征派民夫、粮食，活动于保山地区龙陵一带。；日军侵占龙陵后，出面组织维持会，为日军征派粮秣、拉夫。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('299d140eaeba404a9502325a8990f2a2','97779dce8c1b4a63a092319795ed13f1',1942,'龙陵伪维持会副会长','协助日军在龙陵建立伪政权，参与征派粮秣、民夫，属保山地区附逆人物。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f1e0526b793d498aa65c2e6d82736ab7','64250c97c26d43e483d8a71f50a892a3',1942,'潞西伪维持会会长（后任伪畹町警察局长）','在滇西沦陷区组织维持会，协助日军控制滇缅公路沿线，活动范围涉及保山、德宏一带。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('314f4a4c780e4121818186691819118c','aa97f0db7da847e095b67ffeddb0712a',1942,'滇西伪政权利用的土司（后反正）','日军占领滇西后，被迫与日军合作，后率部反正参加抗日，其活动范围涉及保山地区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('393b9c00e0564030912c564fb96612e8','dc94893581a2428c9783cde9c8541f0c',1942,'滇西伪维持会相关人物','在滇西沦陷区与日军合作，参与维持会活动，活动范围接近保山地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('18cadbd67c314c0b9f7a336dcf10571a','c079616c3f1644eab2aed26259abd351',1942,'保山伪维持会筹备人员','日军逼近保山时，曾有人策划组织维持会，杨绍曾为参与者之一，后因日军未长期占领保山坝区而未成规模。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f25d866b53884686bd49d0d6ed86c3fb','c78f7cbace5745088165e412807d4ba1',1942,'无（未任伪职）','日方曾试图拉拢其合作，但李根源坚持抗日，未附逆，此条仅作排除说明。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ed1b51fede5a43788727c11ba0f50008','887a12115f7c4f1faadc7f22193f7337',1942,'滇西伪维持会头目、伪龙陵县维持会会长','日军侵占龙陵后，出面组织龙陵县维持会，为日军征派民夫、粮秣，协助维持占领区秩序，是龙陵当地较有影响的附逆人物。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5bb84bd851054be49f824d523c5e8f37','4bcdea415b9f4002808368ac433628e2',1942,'伪龙陵县维持会副会长','在龙陵沦陷期间参与伪维持会事务，协助日军推行保甲、征粮和情报搜集，为当地伪政权骨干之一。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c5886bda853645a88186a6ce5fc6a0a3','1b0d93051c8343ec93855ecd4624a43f',1942,'伪保山县维持会会长','保山沦陷前后投靠日军，组织伪维持会，为日军筹粮、派夫并协助宣传‘大东亚共荣’，是保山地区有记载的附逆者。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4d1c340dc7924897a786c3440f861584','751de1551dea470aa38adea3377fbaeb',1942,'伪保山县警察局长','在日军控制保山期间出任伪警察局长，带领伪警配合日军搜捕抗日人员、镇压民众反抗。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5ce9f801a05a4f929d18747fcd683752','97779dce8c1b4a63a092319795ed13f1',1942,'伪腾龙边区行政公署职员、伪龙陵县教育科科长','在龙陵沦陷区推行奴化教育，改编教材、强制日语教学，为日军文化侵略服务。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b59d6a579c714b179a8972325fe0bad9','09ee193c7c864ffca42191827c9675f8',1942,'伪滇西维持会联合会干事','串联保山、龙陵、腾冲等地伪维持会，协助日军建立和巩固滇西占领区伪政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('547c39b915a54c74ba93e0117fbd38f4','b80cc023750046688a1c6ab12eae8320',1942,'伪龙陵县保安队队长','率伪保安队配合日军扫荡龙陵周边抗日武装，参与抓捕和审讯抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5286a4487bef49e9ad60d53541d680aa','7c998ee1d17d4512818cb03950213796',1942,'伪保山县保甲长、情报员','利用保甲长身份为日军搜集抗日游击队情报，带领日军搜山，导致多名抗日人员被捕。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('55053b11f1e24b6fa83d56ae5e3d926a','067b8e028f5740dfa47b25db64ed7534',1942,'伪龙陵县商会会长','在日军占领期间控制龙陵商会，为日军采购物资、摊派款项，并协助日军对食盐、布匹等实行统制。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('022d99711c6a461bab730b390f33751c','3d7c2760ab2448eba9e8e999ef240597',1942,'伪滇西伪军大队长','在保山、龙陵一带收编地痞流氓组成伪军，配合日军守备据点、修筑工事，参与对抗日根据地的封锁。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('89115c681209472582316990e324a50d','aa97f0db7da847e095b67ffeddb0712a',1942,'伪云南省德宏地区维持会会长、伪瑞丽设治局局长','日军侵占滇西后，刀京版在瑞丽、陇川一带组织维持会，协助日军征粮、派夫、维持治安，并出任伪瑞丽设治局局长，为日军在德宏地区的统治提供地方行政支持。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d60bbe8c46624e41ad87daae3ad29ca0','dc94893581a2428c9783cde9c8541f0c',1942,'伪南甸宣抚使、伪梁河维持会会长','日军占领梁河后，龚绶投靠日军，在南甸（今梁河）组织维持会，出任伪南甸宣抚使，协助日军征派粮秣、民夫，并参与镇压当地抗日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9b241e8af26f4ec9ad1e2892f5254dad','88989758d3594b5dbb5407a3b4bbd642',1942,'伪干崖宣抚使、伪盈江维持会会长','日军侵入盈江后，多永安率土司武装投敌，组织伪维持会，协助日军控制干崖地区，为日军提供情报和物资。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7f0643758b30484ab1532dcfa2f2e58d','64250c97c26d43e483d8a71f50a892a3',1942,'伪陇川设治局局长、伪陇川维持会会长','线光天在陇川投靠日军，出任伪陇川设治局局长，组织维持会，协助日军征粮、派款、修筑工事，并参与诱降当地抗日武装。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f89157df255d4b35897ddba662e950e7','5e22153f24954b1eb8b9b64337c71e3f',1942,'伪芒市安抚使、伪潞西维持会会长','日军占领潞西（今芒市）后，思鸿升投敌，出任伪芒市安抚使，组织维持会，协助日军统治潞西地区，征派粮秣民夫。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b081575faf574b14bcabf323647063cb','18ca50d557054f2aa2fb499ea69efd59',1942,'伪遮放副宣抚使、伪潞西遮放维持会会长','方克光在遮放地区投靠日军，组织维持会，协助日军控制遮放、畹町一带，为日军提供情报和后勤支持。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('728633adb71e49c3ae7d87f327750ec4','289ae8c3458f4609a800c782181fba46',1942,'伪腾冲县维持会会长','日军占领腾冲后，李国清出面组织伪腾冲县维持会，协助日军征粮、派夫、维持治安，并参与建立伪政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('246262c6596d4292aa49b3ceb904bfb6','5d298ee4725b4bafbd4f45cddd4b8dc4',1942,'伪腾冲县县长','董友芹在日军占领腾冲期间出任伪县长，协助日军推行伪化统治，征派粮秣民夫，镇压抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ebffd04355be416aa1fe7ba16e631190','eeeb8c3c2bc9498fa146e556955947b1',1942,'伪龙陵县维持会会长','日军占领龙陵后，杨吉品组织伪龙陵县维持会，协助日军征粮、派夫、修筑工事，并参与诱降当地抗日武装。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('75547c81041b4dc698e30bd3958530aa','44f49273b07445978e8bc74ab3dc1cec',1942,'伪龙陵县县长','赵鹏在日军占领龙陵期间出任伪县长，协助日军推行伪化统治，征派粮秣民夫，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6d15389d6f4743a98d7615532c08d9a5','9e072d80aa7b4da6b90de10af430d7a3',1942,'伪腾冲县维持会副会长','张问德在腾冲投敌，出任伪腾冲县维持会副会长，协助日军征粮派夫，参与伪政权活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3bc48522ba9449e69fade1735faebbd1','b042eab93e204143a03cce46ae260d81',1942,'伪梁河设治局局长','尹明德在日军占领梁河期间出任伪梁河设治局局长，协助日军推行伪化统治，征派粮秣民夫。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a0e8a5a4724c44e8a790b063311c588c','049e49d5ca99422da8260700f78353f1',1942,'伪南甸宣抚司属官、伪梁河维持会副会长','龚统政在梁河投靠日军，出任伪南甸宣抚司属官及伪维持会副会长，协助日军征粮派夫，参与镇压抗日活动。','基层维持会/地方自治头目','hanjian');
