INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('72c1940d6d3b4267a348fe02c2647430','2cc5719bb38c4ef698de445a7ae9a9c0',1942,'伪潞西设治局维持会副会长','排启仁在潞西投靠日军，出任伪维持会副会长，协助日军征粮派夫，参与伪政权活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f3a78fb025f34123961653e4f3be3f65','aa97f0db7da847e095b67ffeddb0712a',1942,'伪云南省德宏地区维持会会长、伪瑞丽安抚使','日军侵占滇西后，刀京版在瑞丽、畹町一带组织维持会，协助日军推行‘以华制华’政策，为日军征派粮秣、民夫，并参与组建伪地方武装，配合日军对滇西抗日游击区进行扫荡。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('83c45d3e8756473f9a219a8cda46cba6','dc94893581a2428c9783cde9c8541f0c',1942,'伪芒市安抚使、伪潞西维持会会长','日军占领潞西（今芒市）后，龚绶率先投敌，出任伪芒市安抚使，主持伪维持会，为日军搜集情报、征粮派款，并诱降当地土司头人，协助日军控制芒市、遮放一带。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8770d2b1aa35440ba2c67d9c36d28747','18ca50d557054f2aa2fb499ea69efd59',1942,'伪潞西设治局维持会副会长','在芒市地区协助龚绶组织伪维持会，负责摊派粮款、登记民户，为日军提供劳工，并参与镇压当地抗日民众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0ba03ff936da4022a6a0eb08117955e0','a852f826a41246dba7d33a731d114f0e',1942,'伪遮放维持会会长','日军侵占遮放后，多英培出面组织维持会，为日军筹集粮食、修筑工事，并带领伪军配合日军巡逻，搜捕抗日人员。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4ed8d6413c044ece977d5ba69186da93','64250c97c26d43e483d8a71f50a892a3',1942,'伪陇川维持会会长','在陇川地区组织伪维持会，协助日军征调民夫、粮食，并参与诱降当地景颇族、傣族头人，为日军提供情报。','基层维持会/地方自治头目','hanjian');
