INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('10b8e9db022e42b4948516fcda57b0ab','88989758d3594b5dbb5407a3b4bbd642',1942,'德宏地区伪维持会成员','在德宏地区参与伪维持会活动，协助日军征粮、派夫，并为日军提供情报。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1f11ff9583f74b0f9817dad819fef021','5e22153f24954b1eb8b9b64337c71e3f',1942,'德宏地区伪军头目','在德宏地区组织伪军，配合日军扫荡抗日武装，参与维持会活动，为日军统治服务。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ce99456219cb4367ba7338db1c8937c2','289ae8c3458f4609a800c782181fba46',1942,'云南日伪政权任职者','在云南日占区参与伪政权工作，协助日军进行经济掠夺和物资征调，活动范围涉及德宏地区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('315944b3ec9c4dadb0fea7b62e793e32','c079616c3f1644eab2aed26259abd351',1942,'云南伪维持会成员','在云南日占区参与维持会活动，协助日军征粮派款，并为日军提供地方情报。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6f97d5a70ce5487c8738c17536ab3e28','c78f7cbace5745088165e412807d4ba1',1942,'未任伪职，但曾被日伪拉拢未从','此条为误列示例，李根源为爱国士绅，未附逆，不应列入汉奸名录。；此条为误列风险项，李根源为抗日爱国人士，不应列入汉奸名录。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('eacf2b08cc1c41e0a1c470c815893822','9086c25bb20948259b1ab2e2f0c5f592',1940,'伪云南省维持会会长、伪云南省政府主席','抗战期间投靠日伪，参与组织伪云南省维持会，后任伪云南省政府主席，协助日军在云南推行殖民统治，镇压抗日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('46cd8366224e4073b385c73b893d7d60','c818d21e85994bec9f1c88e3d94165e1',1940,'伪云南省警务处处长','在日伪控制下担任伪云南省警务处处长，负责伪警察系统，配合日军搜捕抗日人士，维持沦陷区治安。；在日伪控制云南部分地区期间，出任伪警务处处长，指挥伪警察配合日军搜捕抗日人士、镇压民众抗日活动，维护日伪统治秩序。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9163f43d1a1d4d158735e0426f0e7714','558ea77322f541fcb3af2e1e162cd89f',1940,'伪昆明市维持会会长','组织伪昆明市维持会，为日军筹集物资、拉拢地方士绅，协助日军在昆明地区的统治。；昆明沦陷期间（注：昆明实际未被日军长期占领，此处指日伪渗透时期或周边地区），组织伪维持会，为日军提供情报、物资，协助推行保甲连坐，压迫昆明市民。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8c6e41b4c0374d10b96cdeb8f97eccb3','299a945cb934453782078b1443063a44',1940,'伪东川维持会会长','在东川地区组织伪维持会，配合日军和伪政权征粮派款，压制当地抗日力量。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f20918addcd8482fb71ee1cf7181fbe8','b033e3a0a52b404b824064c65572c7f5',1940,'伪云南省教育厅督学、附逆教育人士','在日伪统治时期参与推行奴化教育，编写亲日教材，协助日伪控制云南教育界。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('20bb8e7028144391b24f4d7691d8def1','332c8160857542c29c2b123e6e339e1e',1940,'伪云南省商会会长','作为商界附逆者，为日军采购物资、筹措资金，协助日伪在经济领域控制云南。','基层头目','hanjian');
