INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('63f2621bb85849cf89bb752ced8a6ac0','fe7588d226fa430ea2eda3d08a162f2f',1940,'伪昆明市警察局局长','担任伪昆明市警察局局长，指挥伪警察镇压抗日群众，搜捕地下抗日人员。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2981efd02a6546809fb87b611ba332c0','9c838699bd764601adeab3c900458700',1940,'伪云南省宣传处处长','负责日伪宣传工作，创办亲日报刊，散布投降言论，为日军侵略辩护。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('27dcf9e303a440c8bef9c25ab11f1bd3','120e272c27bd4070a1e811a14b308119',1940,'伪东川矿务督办','在日伪支持下控制东川铜矿等资源，强迫矿工为日军生产战略物资，压榨当地民众。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('88554405f12743be8379dcb89bb937f9','fa2f1833bce1467bb91079eceb0f8e9f',1940,'伪云南省维持会会长、伪云南省政府委员','抗战期间投靠日伪，参与组织伪云南省维持会，协助日军在云南推行殖民统治，后任伪云南省政府委员，为日伪政权筹措物资、宣传‘大东亚共荣圈’。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('40d9e800f5f7412bb5f4797edffdccf7','299a945cb934453782078b1443063a44',1940,'伪云南省保安司令部司令','率部投敌，改编为伪军，配合日军在滇西、滇南地区扫荡抗日武装，残害百姓，掠夺资源。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3e8e76d6417b4821971fea3af4e239db','524503e462964922a3509303c3d50c30',1940,'伪云南省教育厅督学、伪昆明县维持会教育股长','在教育领域附逆，推行奴化教育，篡改教材，向学生灌输亲日思想，协助日伪控制昆明及周边学校。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2ce7f235ad9f4920b5fa9329ea902294','9c838699bd764601adeab3c900458700',1940,'伪云南省商会会长','在经济领域与日伪合作，强制商户缴纳‘献金’，为日军采购军需物资，垄断昆明部分商业，牟取暴利并资助伪政权。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f25df250d9a7451e9c5406cc2c44a470','120e272c27bd4070a1e811a14b308119',1940,'伪昆明市警察局局长','担任伪警察局长期间，带领伪警察配合日军宪兵队抓捕抗日志士和无辜群众，实施酷刑，制造多起血案。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cc423ca5542f449da93018eb5e3988b4','332c8160857542c29c2b123e6e339e1e',1940,'伪云南省回教联合会会长','利用宗教身份为日伪服务，在回族群众中散布亲日言论，协助日军招募伪军，破坏抗日民族统一战线。；云南回族上层人士，抗战期间与日伪合作，利用宗教身份为日军宣传‘大东亚共荣圈’，动员回族青年参加伪军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('54a35b5282cd46be9bce7782d538a40b','09ee193c7c864ffca42191827c9675f8',1940,'伪云南省财政厅厅长','主持伪财政，为日伪政权搜刮民财，滥发伪币，导致云南部分地区经济混乱，民众生活困苦。；原云南财政官员，投敌后出任伪职，为日伪政权筹措经费，加重云南民众税负，支持日军侵略战争。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8bdbd00c6fdd42d7885e3b5385b2a032','e9ffcf106b04408dae2c0afad0abea5c',1940,'伪昆明县县长','出任伪昆明县县长，推行日伪政令，征发民夫、粮食供给日军，协助建立伪保甲制度，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5a62fe9caf6b49ac9736dc4ad90ab0bf','5f82d23ccd2e45fd9e59f76c92bcc9ad',1933,'伪蒙古军政府/伪蒙古联合自治政府要员、伪军头目','热河失守后投敌，组织伪军配合日军进攻察哈尔、绥远等地，后任伪蒙古军总司令等职，是华北、西北地区重要伪军头目之一；其活动主要不在云南，但属于抗战时期有明确记载的著名汉奸。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c4a99190af114861a1f3c8bd9eda7359','529eba01fd3844d2a4780badaf25cb50',1936,'伪绥西联军总司令、伪军头目','绥远地区投敌，组织伪军配合日军进犯绥西，曾任伪绥西联军总司令等职，属华北、西北伪军系统。；绥远地区伪军头目，投靠日军后组织伪军，在绥远、察哈尔一带配合日军作战，其活动范围与内蒙古中西部及锡林郭勒盟西部邻近。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f55c570ab7874ba9afa50f063d1bdf27','78198cf336e24d25a8e52cd58ddf4575',1936,'伪蒙古联合自治政府主席','即德王，在日军扶植下成立伪蒙古军政府、伪蒙古联合自治政府，任主席，是内蒙古地区重要汉奸政权头目。；即德王，在日军扶植下成立伪蒙古军政府、伪蒙古联合自治政府。；蒙古王公，投靠日本建立伪蒙政权，是华北伪政权重要头目，其伪政权与汪伪有联系。；蒙古王公，投靠日本，成立伪蒙疆政权，统治察哈尔、绥远等地，与陕西北部接壤，配合日军封锁陕甘宁边区，推行奴化政策。；在内蒙古建立伪政权，投靠日本，其势力范围接近陕西北部。；投靠日本，在内蒙古建立伪政权，配合日军侵略，其活动范围与陕西北部接壤。；蒙古王公，投靠日本建立伪蒙政权，协助日军侵略华北，对陕西宝鸡抗日后方构成威胁。；投靠日本，在内蒙古建立伪政权，其势力范围与陕西北部接壤，参与日军对西北的封锁与进攻。；在日军扶植下成立伪蒙古军政府，后任伪蒙古联合自治政府主席，分裂中国。；在内蒙古建立伪政权，投靠日本，其势力范围接近陕西北部，对陕西抗日根据地构成威胁。；投靠日本，在内蒙古建立伪政权，配合日军侵略华北和西北。；投靠日本，成立伪蒙古政权，配合日军在内蒙古及陕西周边地区的殖民统治。；在内蒙古、察哈尔、绥远一带建立伪政权，配合日军统治，其活动区域与陕西北部邻近。；在内蒙古地区建立伪政权，投靠日本，其活动范围与陕西北部接壤。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ac59f531be3a459fa5105e80b1631b6d','b5ba32ac9dee4113808d7f1e4475b119',1935,'伪冀东防共自治政府主席','在日军策动下成立伪冀东防共自治政府，任主席，割裂冀东，是华北早期伪政权头目之一。；在华北建立伪政权，是抗战时期早期汉奸头目之一，其活动区域与内蒙古邻近。；在冀东（含宝坻）建立伪政权，宣布脱离中国，为日军提供统治基础，推行奴化教育。；虽早于全面抗战，但其汉奸行为影响后续，其组织模式被汪伪在安徽复制，包括安庆、大观。；其伪政权与山东伪政权有联系，影响波及济南地区，配合日军侵华。；早期汉奸，其伪政权模式影响山东，后任伪华北政务委员会要职，间接涉及济宁地区日伪统治。；早期华北汉奸政权头目，其附逆活动影响华北包括山西北部日伪政权建立。；虽以冀东为主，但1938年后投靠汪伪，曾在南京鼓楼区活动。；在冀东（含唐山玉田）建立伪政权，推行奴化教育，协助日军控制冀东地区。；在河北东部建立伪冀东防共自治政府，公开投敌，为日军侵华提供基地，影响波及河北全省。；虽为冀东全区，但直接管辖廊坊、大厂等地，推行亲日政策，出卖华北主权，为日军侵华提供便利。；在河北东部包括廊坊周边地区建立伪冀东防共自治政府，公开投敌，为日军侵华服务。；在河北东部建立伪政权，后与伪华北政权合流，其附逆活动对河北全省包括张家口地区的伪化统治有影响。；在河北东部成立伪政权，推行亲日卖国政策，其伪政权与承德伪满势力相呼应，为日军在河北的侵略提供行政与后勤支持。；虽非承德籍，但所辖冀东地区包括今承德部分区域，与日军勾结，建立伪政权，破坏抗日活动。；在冀东建立伪政权，配合日军侵华，战后以汉奸罪被处决。；1935年成立伪冀东防共自治政府，任主席，是华北地区最早投敌的汉奸之一，后任伪华北政务委员会委员等职。；1935年成立伪冀东防共自治政府，任主席，是华北地区最早投敌的汉奸之一。；伪冀东政权首脑，主要活动于河北东部，与重庆沙坪坝无直接关联。；早年在华北活动，1935年成立伪冀东防共自治政府，公开投敌，后任伪华北政务委员会要职，协助日军控制华北交通与经济，其伪政权与陕西周边沦陷区有联系。；在冀东建立伪政权，为日军侵华服务，其活动对华北包括陕西周边地区产生负面影响。；在华北建立伪自治政权，配合日军侵略，其活动虽主要在冀东，但作为华北伪政权早期代表，对包括陕西在内的华北地区产生示范性附逆影响。；在华北建立伪政权，配合日军侵略，其活动影响波及陕西等地的抗日局势，后任伪山西煤矿公司董事长等职。；在华北建立伪政权，配合日军侵略，其活动对陕西等地的抗日形势产生间接影响。；在华北建立伪政权，配合日军侵略，其伪政权模式影响华北各地，包括陕西沿边地区的维持会组织。；华北早期伪政权头目，其“防共自治”模式被推广至华北各地，包括陕西黄河沿岸日占区，对榆林、神木一带的伪维持会组织有示范和策动作用。；华北早期伪政权头目，其伪化活动对陕西、渭南一带的汉奸势力有示范和联络作用。；在华北建立伪自治政权，配合日军侵略，其活动区域与陕西邻近，对西北地区伪政权有示范影响。；在日军扶植下于冀东成立伪冀东防共自治政府，割裂华北，后并入伪中华民国临时政府，继续附逆。；在华北建立伪自治政权，配合日军侵略，其活动虽主要在冀东，但作为华北伪政权早期代表，对包括陕西在内的华北抗日局势产生负面影响。；在华北建立伪政权，配合日军侵略，其伪政权与陕西等地伪组织有联系。；1935年成立伪冀东防共自治政府，是华北最早公开投敌的汉奸政权头目，其伪化模式对陕西等地伪政权有示范影响。；在日军扶植下成立伪冀东防共自治政府，是华北早期汉奸政权头目之一，其活动对华北包括陕西抗日局势产生负面影响。；在日军扶植下成立伪冀东政权，后参与伪华北政务，其活动对华北包括陕西地区产生波及影响。；在华北建立伪自治政权，为日军侵华服务，是华北地区早期汉奸头目之一。；在华北建立伪自治政权，配合日军侵略，其伪政权与陕西同属北方地区，对华北抗日力量造成威胁。','地方伪政权首脑','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8025555c45f14950b6381f3ac38c9fa4','31abdc5e4e0a4ebdbe5f0b715a509863',1937,'伪中华民国临时政府行政委员会委员长','北平沦陷后组织伪中华民国临时政府，任行政委员会委员长，后并入汪伪政权，是华北伪政权核心人物。；在北平（今北京）组织伪政权，为日本侵略者服务，推行奴化政策，镇压抗日活动。；抗战期间投敌，在北平组建伪临时政府，为日军侵华提供行政支撑，其伪政权名义上管辖包括四川在内的沦陷区相关事务。；伪临时政府首脑，其政权虽以华北为主，但与四川成都、邛崃地区的伪维持会及伪军有联系，推动地方附逆势力配合日军。；华北伪政权头目，其伪政权与四川无直接关联，但作为全国性汉奸代表，其活动影响波及四川。；伪临时政府首脑，其伪政权体系延伸至四川部分地区，对成都地区伪政权有名义上的统辖关系。；1937年12月在北平成立伪临时政府，任行政委员会委员长，后并入汪伪政权，任伪华北政务委员会委员长。；伪临时政府首脑，其政权覆盖华北包括山东聊城，推行保甲和治安强化。；华北伪政权首脑，其伪政权管辖包括山东，推行日军殖民政策。；华北伪政权首要人物，其伪政权统辖包括山东在内的华北地区，青岛、平度等地伪政权受其节制。；在北平组建伪临时政府，统辖包括山东在内的华北沦陷区，青岛、胶州伪政权受其节制。；华北伪政权首要人物，其伪政权管辖范围包括山东，推行日军殖民统治，镇压抗日力量。；华北伪政权头目，其统治范围涵盖山东，与青岛伪政权有隶属关系。；组织伪临时政府，任行政委员会委员长，为华北地区头号汉奸之一。；华北伪政权头目，活动于北平、华北，未见与广西柳州直接关联。；华北伪政权头目，配合日军侵略，其伪政权与南方伪组织有联系，对广西等地有政治诱降宣传。；华北伪政权头目，其伪政权与汪伪合流后，对广西有名义影响，但直接关联较弱。；华北伪政权头目，后并入汪伪政权，属全国性汉奸。；广西籍（桂林）汉奸，组织伪临时政府，后并入汪伪政权，任伪华北政务委员会委员长。；曾到南京鼓楼区与维新政府协调，后并入汪伪。；伪临时政府头目，其伪政权体系影响华中、江西沦陷区，协助日军建立伪秩序。；组织伪临时政府，后与伪维新政府合并为汪伪政权，其伪化体系延伸至江西九江沦陷区，配合日军维持会与保甲制度。；浙江杭州人，抗战期间投敌，组织伪中华民国临时政府，任行政委员会委员长，其伪政权覆盖华北，与江西无直接关联，但属全国性知名汉奸。；华北伪政权首脑，其统治覆盖廊坊全境，推动“新民会”在基层建立汉奸组织。；在北平成立伪政权，其势力范围延伸至冀东及秦皇岛，配合日军对海港地区进行经济掠夺。；华北伪政权头目，其伪政权管辖范围包括河南北部，对河南沦陷区推行伪化统治。；浙江杭州人，抗战期间投敌，先后在伪临时政府、伪华北政务委员会任职，协助日军统治华北。；虽为华北伪政权头目，但曾插手浙江舟山地区日伪事务，协助日军维持沿海统治。；浙江杭州人，抗战期间出任伪临时政府首脑，后任汪伪政权要职，1945年被捕后自杀。；临时政府头目，其伪政权体系对湖北北部沦陷区有影响，黄冈等地部分伪政权受其间接管辖。；浙江杭县人，抗战期间投靠日军，历任伪中华民国临时政府行政委员会委员长等职，在华北地区推行伪化统治，其伪政权与湖南地区伪政权有联系。；浙江杭县人，伪华北政权头目。活动于北平、华北，与湖南株洲石峰无直接关联。；华北伪政权头目，其伪政权模式对湖南沦陷区维持会等组织有示范影响。；浙江人，华北伪政权头目，与湖南无直接关联。；华北伪政权头目，与湖南无直接关联，但属全国性知名汉奸。；浙江杭县人，华北伪政权头目，活动于北平、华北，与湖南郴州、桂阳无直接关联。；浙江杭县人，华北伪政权头目，与湖南郴州、汝城无直接关联。；浙江杭县人，伪临时政府头目，其伪政权对湖南北部沦陷区有名义上的管辖影响，与长沙有间接关联。；虽主要活动于北平，但其伪政权体系曾向贵州派遣联络人员，拉拢地方士绅附逆。；华北伪政权头目，与重庆、万州无直接关联，但属全国性汉奸。；1937年北平成立伪临时政府，任行政委员会委员长，与日本合作统治华北，后并入汪伪政权，任伪华北政务委员会委员长。；伪临时政府首脑，主要活动于北平，与重庆沙坪坝无直接关联。；抗战初期在华北组织伪政权，其伪政权势力范围涵盖华北包括陕西周边地区，对陕西等地有政治渗透企图。；华北伪政权首要人物，虽主要活动于北平，但其伪政权体系覆盖陕西部分沦陷区及邻近地区，对渭南、华州一带的伪化渗透有间接影响。；1937年12月在北京成立伪中华民国临时政府，任行政委员会委员长，统辖包括陕西在内的华北伪政权事务，是华北地区最高汉奸头目之一。；抗战期间投靠日本，在北平组建伪临时政府，其伪政权势力范围一度涵盖华北包括陕西部分沦陷区，是华北地区重要汉奸头目。；在北平组建伪临时政府，其伪政权势力覆盖华北，对陕西等抗日后方有政治渗透和破坏。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5a819493a93c463b8a56a06f6cf1c5a6','4f8793c77ca74d3dbe773329337bfbb0',1938,'伪中华民国维新政府行政院院长','南京沦陷后组织伪中华民国维新政府，任行政院院长，后并入汪伪政权，是华中伪政权头目之一。；投靠日军，在南京组建伪维新政府，配合日军侵略，其伪政权对包括四川在内的后方进行政治渗透与诱降活动。；1938年在南京成立伪维新政府，任行政院院长，管辖江苏、浙江、安徽等沦陷区，后并入汪伪政权，任伪监察院院长。；1938年在南京成立伪维新政府，任行政院院长，其伪政权势力范围包括安徽部分地区，推行附日伪化统治。；伪维新政府头目，其政权覆盖华中、华北部分地区，包括山东聊城一带的伪维持会受其影响。；华中伪政权头目，与山东伪政权有联系，协助日军统治。；维新政府管辖包括青岛在内的华中、华北部分地区，与日军合作推行伪化，间接影响崂山地区。；组织华中伪政权，与华北伪政权配合，其影响波及山东青岛等地，协助日军维持占领秩序。；华中伪政权头目，其势力与华北伪政权在山东地区有交叉，影响青岛等地伪组织。；在南京组建伪维新政府，其势力一度影响山东南部及青岛地区。；华中伪政权头目，其势力范围一度涉及山东部分地区，配合日军侵华。；华中伪政权头目，与山东、青岛伪政权有联系。；福建人，但在江苏南京组建伪政权，统辖江苏沦陷区，推行伪化统治，为日军掠夺资源、镇压抗日服务。；华中伪政权头目，其势力范围涉及河南部分地区，协助日军维持占领区。；维新政府头目，其伪政权一度管辖湖北部分地区，协助日军维持占领区。；维新政府头目，其伪政权在湖北沦陷区建立初期有影响，黄冈等地维持会受其体系指导。；华中伪政权头目，其伪化统治波及湖南部分沦陷区。；其伪政权曾试图向西南扩展，在贵州安插情报与宣传人员，配合日军对贵阳的策反活动。；华中伪政权头目，后并入汪伪政权，其活动与陕西宝鸡抗日后方有间接关联。；华中伪政权头目，与陕西渭南地区无直接关联。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('04ccae5f1d9646e9904e7a62fd76c257','c12e72a145724c39b755a2a16dce9a71',1938,'伪国民政府主席、行政院院长','1938年公开投敌，1940年在南京成立伪国民政府，任主席兼行政院院长，是抗战时期最大汉奸政权头目。；1938年12月发表艳电公开投敌，1940年在南京成立伪国民政府，自任主席兼行政院长，全面推行亲日卖国政策，其伪政权统治范围涵盖安徽等地。；1938年12月公开投敌，1940年在南京成立伪国民政府，任主席兼行政院院长，成为全国性汉奸政权首脑；其伪政权统治范围涵盖安徽，对安徽沦陷区实施伪化统治。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('28ce482672e44c3ea5f606e8f6fae198','62a6d6c8e7ab4bbfbc92c5b14abbde74',1940,'伪国民政府立法院院长、伪国民政府代主席','追随汪精卫投敌，任伪立法院院长等职，汪死后任伪国民政府代主席，是汪伪政权核心人物。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9fc8b327ff974ed1847ceec866320b20','a2e4190c87b449e685d78c118a6801b5',1940,'伪国民政府财政部长、伪上海市长','汪伪政权核心成员，任伪财政部长、伪警政部长、伪上海市长等职，掌握伪政权财政与特务系统。；汪伪政权核心，参与对安徽等沦陷区的经济掠夺和伪军调度。；汪伪政权核心人物，其财政体系覆盖潮汕沦陷区，协助日军经济掠夺。；湖南沅陵人，但长期在浙江活动，汪伪政权核心人物，曾任伪财政部长、伪上海市长，控制浙江经济，1946年病死狱中。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('37c429ce1aa84fdc8a986adfad3ba859','664d3df731bb4293bee63eea6deacb2d',1940,'伪国民政府外交部长','汪伪政权要员，任伪外交部长等职，参与对日妥协外交。；负责伪政权外交，与日本签订卖国条约，协助日本控制中国。；代表汪伪与日本交涉，签署卖国条约，战后以汉奸罪被处决。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('30b4c887f34b4d99866e1d09675b409b','28c69a91441d4439abc95701e2c6787a',1938,'伪国民政府工商部长、伪浙江省长','汪伪政权要员，参与汪精卫投敌活动，后任伪工商部长、伪浙江省长等职。；浙江永嘉人，抗战期间投敌，参与汪伪政权组建，任伪工商部长、伪浙江省长，其伪政权活动与江西邻近地区有关联。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('15777146e50d4310ba48823ccabb4162','07ff958e7f18410f864975f09234ac7e',1938,'伪特工总部主任、伪江苏省长','汪伪特务头目，组建伪特工总部，镇压抗日力量，后任伪江苏省长。；汪伪特工头目，其特务网络覆盖安徽沦陷区，在宣城等地进行侦缉、镇压抗日人员。；汪伪特务头子，其特工网络延伸至安徽宣城等地，镇压抗日力量。；汪伪特务头目，其特工网络延伸至安徽沦陷区，在宣城等地进行侦缉、镇压抗日活动。；汪伪特务头目，活动于安徽及江苏部分地区，镇压抗日力量。；汪伪特务头子，其特工网络覆盖安徽部分地区，镇压抗日人士。；汪伪特务头子，建立‘76号’特工总部，残酷镇压抗日力量，后任伪江苏省长，1943年被日军毒杀。；浙江遂昌人，汪伪特务头子，建立“76号”特工总部，其特务网络曾渗透江西等地，镇压抗日力量。；汪伪特务头目，其特工网络延伸至江西九江等地，镇压抗日力量，诱降国民党军政人员。；浙江遂昌人，汪伪特工头目，在浙江、江苏等地进行特务活动，镇压抗日人士。；汪伪政权特工头目，任伪特工总部主任、伪江苏省长等职，残酷镇压抗日力量，后因内部矛盾被日军毒死。；汪伪政权特工头目，任伪特工总部主任、伪江苏省长等职，残酷镇压抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6dda53f165ec4471b321f6a41b7b31df','9910c48b9b394ffa8c73439ed0a473b0',1938,'伪特工总部主任、伪社会部长','汪伪特务头目之一，参与组建伪特工总部，后任伪社会部长等职。；汪伪特工头目之一，参与在华中沦陷区（含安徽）的特务统治。；汪伪特务头目，参与在安徽等地的侦缉与镇压抗日活动。；汪伪特务头目，参与对安徽等地沦陷区的特务统治，战后以汉奸罪被处决。；汪伪特务头目，参与镇压安徽等地抗日活动。；汪伪特务头目，参与对安徽等地抗日力量的侦捕与镇压。；汪伪特务头子，与李士群共同主持‘76号’，后任伪社会部长，抗战胜利后被处决。；湖南常德人，汪伪特务头目之一，参与“76号”特工总部，其特务活动波及江西沦陷区。；湖南常德人，汪伪政权特务头目，与李士群共同主持“76号”，参与镇压抗日活动，后任伪社会部长等职。；汪伪特务头目，参与伪化江西沦陷区的情报与镇压活动，与九江伪警察系统有联系。；湖南常德人，汪伪特工总部主任，其特务活动覆盖河南沦陷区。；湖南常德人，抗战期间投靠汪精卫伪政权，历任伪特工总部主任、伪社会部长等职，在华中地区包括湖南进行特务活动和伪化统治，其家乡常德与怀化同属湖南。；汪伪政权特工头目，任伪特工总部主任、伪社会部长等职，参与镇压抗日活动。；与李士群共同组建伪特工总部，进行恐怖活动，后任伪社会部长。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('35f34cdc3c564fd49ef64dfff73817fd','77a789268c6f47b4a617cdb9e41180bd',1931,'伪满洲国国务总理大臣','九一八事变后投敌，历任伪满洲国参议府议长、国务总理大臣等职，是伪满洲国核心汉奸。；原奉系军阀，九一八后投敌，虽主要活动于新京（长春），但其势力范围涉及吉林全省，包括白城、大安地区，支持日军殖民统治。；虽为奉系元老，但1932年公开投敌，任伪满军政部总长、国务总理，其势力范围曾涉及吉林西部及白城地区，推行日满亲善政策。；虽为伪满中央高官，但曾长期控制吉林地区军政，其政策直接影响辽源、东辽，支持日军“治安肃正”，镇压当地抗日力量。；曾任东三省特别区长官，后投敌，历任伪参议府议长、军政部总长、国务总理，全面配合日本侵略政策。；原吉林军将领，后投敌任伪满总理，全面配合日本对东北的军事占领、经济统制和思想奴役，是吉林长春地区最高级别汉奸。；曾任东省特别区长官，后投靠日本，历任伪满参议府议长、军政部总长、国务总理，全面配合日本侵略政策。；长期担任伪满总理，配合日本对东北的殖民统治，并参与对关内包括四川在内的抗战力量进行政治诱降。；虽主要活动于东北，但作为四川籍（或与四川有联系）的汉奸，其伪满政权与四川成都、邛崃地区的附逆者有往来，影响当地伪政权建设。；东北伪政权头目，与四川无直接关联，但作为全国性汉奸代表，其活动影响波及四川。；伪满洲国首脑，虽主要活动于东北，但其伪政权模式被四川地区伪组织效仿，间接关联成都附逆活动。；伪满头目，其政权与华北伪政权有联系，间接影响山东聊城地区。；东北伪满洲国头目，属东北伪政权，与广西无直接关联。；九一八事变后投敌，长期担任伪满洲国要职，是东北伪政权头目，属于抗战时期有明确记载的汉奸。；东北伪政权头目，属全国性汉奸。；原奉系军阀，后任伪满洲国总理，虽驻长春，但参与制定对热河省（含承德、滦平）的殖民政策，支持日军“治安肃正”行动。；原东北军将领，九一八事变后投敌，任伪满最高行政长官，其管辖范围包括热河省（今承德、隆化一带），支持日军对当地抗日武装的镇压。；虽为伪满总理，但伪满势力曾延伸至山海关一带，对当地有间接统治影响；原东北军将领，九一八后投日，曾任伪满参议府议长、军政部总长，后任伪满国务总理大臣，是日伪在东北（含辽宁）的最高傀儡。；虽为伪满中央高官，但多次到安东、宽甸视察，推动“治安强化”政策，对当地抗日力量进行系统性镇压。；原奉系将领，九一八事变后投敌，任伪满最高行政长官，协助日本统治东北，镇压抗日力量。；曾任伪满洲国总理，积极推行日本殖民政策，协助日本统治东北，包括辽宁地区。；原奉系军阀，后投靠日本，任伪满最高行政长官，全面配合日本侵略政策，对东北人民实施奴役统治。；曾任奉天省长，九一八事变后投敌，任伪满洲国军政部总长、国务总理，推行奴化政策，协助日本统治东北。；辽宁台安人，九一八后投敌，任伪满最高行政长官，协助日本统治东北，镇压抗日力量。；出生于辽宁台安，曾任奉系将领，后投靠日本，任伪满洲国总理，推行奴化政策，协助日本殖民统治东北，包括大连地区。；出生于辽宁台安（旧属奉天省），曾任伪满洲国军政部总长、国务总理，全面协助日本关东军统治东北，推行奴化政策，镇压抗日力量。；曾任奉天省长，九一八事变后投敌，任伪满国务总理，推行殖民统治，镇压抗日力量。；曾任奉天省长，后投靠日本，任伪满总理，推行奴化政策，协助日本掠夺辽宁资源。；曾任奉天省长，后投靠日本，任伪满洲国总理，推行奴化政策，协助日本掠夺东北资源。；出生于辽宁台安（原属沈阳地区），九一八事变后投靠日本，历任伪满参议府议长、军政部总长、国务总理大臣，积极推行日本殖民政策，镇压东北抗日力量。；九一八事变后投敌，任伪满军政部总长、国务总理，协助日本殖民统治东北，镇压抗日力量。；出生于辽宁台安（原属奉天省），曾任奉军将领，后投靠日本，出任伪满洲国最高行政长官，协助日本统治东北，包括康平地区，推行殖民政策。；原奉系将领，九一八事变后投敌，任伪满最高行政首脑，协助日本殖民统治东北，镇压抗日力量。；原奉系将领，九一八事变后投敌，任伪满最高行政长官，协助日本殖民统治东北，镇压抗日力量。；原奉系军阀，投日后任伪满洲国总理，虽为中央级汉奸，但其伪政权统治覆盖辽宁全省，包括盘锦、兴隆台地区，签署多项卖国条约。；虽为伪满最高汉奸之一，但曾多次巡视盘锦、双台子地区，督促地方伪政权强化殖民统治，推行“粮谷出荷”政策；原东北军将领，后任伪满总理，其政策覆盖辽宁全境，包括盘锦、大洼，推行“粮谷出荷”和“劳工供出”，导致当地民众饥寒交迫。；原奉系将领，投敌后任伪满最高行政长官，其政策覆盖营口、大石桥地区，支持日军侵略。；原东北军将领，九一八后投敌，虽为伪满中央高官，但其势力范围及伪军行动覆盖辽宁全境，包括兴城、葫芦岛地区，支持日军“讨伐”义勇军。；原奉系军阀，全面投日，作为伪满最高行政首脑，其政策覆盖辽宁全省包括绥中，支持日军侵略。；原奉系将领，九一八后投敌，任伪满总理，其势力范围涵盖辽宁，支持日军在葫芦岛等地修建军事设施。；原奉系军阀，九一八后投日，曾任伪奉天省长，后升任伪满国务总理，全面协助日本统治东北。；原奉系将领，九一八事变后公开投敌，任伪满军政部总长、国务总理大臣，全面配合日本侵略政策，镇压东北抗联。；原奉系军阀，后投日，虽主要活动于新京，但曾多次到铁岭地区视察“治安”，推动“日满亲善”和殖民统治。；原东北军将领，九一八后投敌，历任伪满参议府议长、国务总理，在辽宁各地推行殖民统治，包括阜新地区。；长期担任伪满总理，推行日本殖民政策，战后被苏联俘虏。；伪满洲国要员，主要活动于东北，与重庆沙坪坝无直接关联。；长期担任伪满洲国要职，协助日本统治东北，其伪政权与华北伪政权有联系，间接影响陕西周边。；虽为伪满中央高官，但曾多次到黑龙江东部（含七台河地区）视察“治安肃正”，推动建立伪政权和保甲制度，是最高层汉奸代表。；原东北军将领，九一八后投敌，历任伪满参议府议长、国务总理大臣，全面推行日本殖民政策，其政令覆盖黑龙江全境包括伊春地区。；出生于辽宁台安，但长期在东北任职，曾任伪满军政部总长、国务总理，推行日满亲善，镇压抗日力量，其势力影响覆盖佳木斯地区，支持日军对三江省的殖民统治。；出生于辽宁台安，曾任奉系将领，九一八后投敌，1935年任伪满国务总理，推行殖民政策，协助日本统治东北，包括佳木斯、富锦地区。；出生于辽宁台安，曾任奉系将领，1932年投靠日本，任伪满国务总理，推行殖民政策，协助日本统治东北，包括佳木斯、桦川地区。；原东北军将领，九一八后投敌，任伪满最高行政长官，推行殖民政策，镇压抗日力量。；原东北军将领，1932年投敌，任伪满国务总理，协助日本统治东北，镇压抗日力量。；原东北军将领，1932年投敌，历任伪满洲国参议府议长、军政部总长、国务总理大臣，积极推行日本殖民政策，镇压抗日力量。；曾任东三省特别区长官，1935年投敌任伪满总理，协助日本统治东北，镇压抗日力量。；原东北军将领，九一八后投敌，任伪满最高行政长官，协助日本统治东北，镇压抗日力量。；原奉系军阀，九一八后投敌，任伪满最高行政长官，全面配合日本侵略政策，对黑龙江地区抗日活动进行残酷镇压。；曾任东北保安副总司令，1932年投敌，后任伪满国务总理，协助日本统治东北，镇压抗日力量。；原东北军将领，九一八后投敌，任伪满最高行政首脑，协助日本统治东北，镇压抗日力量。；原奉系军阀，九一八后投日，任伪满最高行政长官，全面推行殖民政策，对黑龙江地区抗日活动进行残酷镇压。；虽为伪满中央高官，但原籍辽宁，曾长期在黑龙江地区活动，其伪政权对牡丹江、穆棱地区实行殖民统治，支持日军镇压抗联，是东北最大汉奸之一。；辽宁台安人，原东北军将领，九一八事变后公开投敌，历任伪参议府议长、军政部大臣、国务总理大臣，为伪满最高汉奸之一，其伪政权统治覆盖黑龙江全境，包括绥化、海伦地区。；原为奉系军阀，九一八事变后公开投敌，历任伪参议府议长、军政部总长、国务总理大臣，是伪满洲国最高级别的汉奸之一，对包括黑龙江绥化地区在内的东北全境实行殖民统治负有责任。；虽为全国伪满首脑，但原籍辽宁，曾多次视察黑龙江及鹤岗矿区，支持殖民政策。；原东北军将领，九一八后投敌，任伪满最高行政长官，推行殖民政策，镇压抗日力量，涉及黑龙江全省包括黑河、嫩江地区；原奉系将领，九一八事变后投敌，任伪满最高行政长官，协助日本殖民统治东北，包括齐齐哈尔地区，推行奴化政策与资源掠夺。；出生于辽宁台安，曾任奉军将领，后投靠日本，任伪满总理，推行殖民政策，协助日本统治东北，包括黑龙江地区。；出生于辽宁台安，但长期在黑龙江任职，曾任东省特别区行政长官，后投靠日本，任伪满最高行政首脑，协助日本统治东北，包括齐齐哈尔地区，推行殖民政策。；出生于辽宁台安，曾任奉系将领，后投靠日本，历任伪满洲国参议府议长、军政部总长、国务总理大臣，积极推行日本殖民政策，镇压东北抗日力量。虽非齐齐哈尔本地人，但作为伪满中央高官，其势力影响覆盖黑龙江全省，包括齐齐哈尔地区。；原奉系将领，九一八后投敌，任伪满军政部总长、国务总理，推行殖民政策，镇压抗日力量，其势力涉及黑龙江地区','伪政权最高层/元首级','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('08752c1f60ec41e2bdc0c7c9ace800df','c6f27713c97e47d4802d65204111d7bf',1931,'伪满洲国国务总理大臣','协助溥仪建立伪满洲国，任国务总理大臣，是伪满洲国初期重要汉奸。；协助日本建立伪满洲国，担任伪总理，属于抗战时期有明确记载的汉奸。；东北伪政权头目，属全国性汉奸。；投日文人，任伪满首任总理，推行“王道乐土”欺骗宣传，其政策覆盖营口、大石桥。；协助日本建立伪满洲国，出任首任总理，推行亲日政策。；清末遗老，九一八事变后投敌，任伪满洲国首任国务总理大臣，参与伪满政权对东北包括黑龙江地区的统治。；福建人，清末遗老，积极参与伪满洲国建立，任首任国务总理大臣，为伪满政权核心人物。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d0aa407bb73a45728b84d8bd2570312d','875c22d678e24c21834a32caae69933c',1931,'伪满洲国财政部总长、伪吉林省长','九一八事变后率先投敌，引日军进入吉林，后任伪吉林省长、伪财政部总长等职。；清朝宗室后裔，九一八事变后率先投敌，组织伪吉林省政权，后任伪满财政总长等职，参与伪满统治体系构建，影响遍及东北各省包括黑龙江地区。；清朝宗室后裔，九一八事变后率先投敌，组织伪吉林省政权，后任伪满财政总长等职，参与伪满对东北包括黑龙江地区的殖民统治。；清末宗室，九一八事变后率先投敌，组织伪吉林省政权，后任伪满洲国财政部总长等职，积极协助日本侵略者控制东北财政与经济，其伪政权体系延伸至黑龙江各地包括佳木斯地区。；清朝宗室，九一八事变后率先投敌，组织伪吉林省政权，后任伪满财政部总长等职，参与伪满统治体系构建，影响波及黑龙江地区。；清末宗室，九一八事变后率先投敌，组织伪吉林省政权，后任伪满洲国财政部总长等职，其附逆活动影响波及黑龙江地区。；清末宗室，九一八事变后率先投敌，任伪吉林省长官公署长官，后任伪满洲国财政部总长、宫内府大臣等职，积极参与伪满政权建设，其附逆行为对包括黑龙江在内的东北地区沦陷负有责任。；清末宗室，九一八事变后率先投敌，组织伪吉林省政权，后任伪满洲国财政部总长等职，积极协助日本侵略者控制东北财政与经济，其影响波及黑龙江地区。；清末宗室，九一八事变后率先投敌，组织伪吉林省政权，后任伪满洲国财政部总长、宫内府大臣等职，参与伪满统治体系构建，影响波及黑龙江地区。；清朝宗室，九一八事变后率先投敌，组织伪吉林省政权，后任伪满财政部总长等职，参与伪满政权对东北包括黑龙江地区的统治。；清朝宗室，九一八事变后率先投敌，以吉林省长名义诱降各地，其影响波及黑龙江绥化一带，后任伪满财政部长、宫内府大臣。；清末宗室，九一八事变后率先投敌，组织伪吉林省政权，后任伪满洲国财政部总长等职，参与伪满统治体系构建，影响波及黑龙江地区。；清朝宗室，九一八事变后率先投敌，组织伪吉林省政权，后任伪满财政部总长、宫内府大臣等职，积极参与伪满统治，影响波及黑龙江。；清末宗室，九一八事变后率先投敌，组织伪吉林省政权，后任伪满财政总长等职，其附逆行为对包括黑龙江在内的东北全境沦陷有直接影响。；清朝宗室，九一八事变后率先投敌，组织伪吉林省政权，后任伪满洲国财政部总长等职，其附逆行为对包括黑龙江在内的东北地区伪政权建立有重要影响。；清朝宗室后裔，九一八事变后率先投敌，在吉林组织伪政权，后任伪满洲国财政总长等职，其附逆行为对包括黑龙江在内的东北地区伪政权建立起到推动作用。；清末宗室，九一八事变后率先投敌，组织伪吉林省政权，后任伪满财政部总长等职，参与伪满统治体系构建，影响波及黑龙江地区。；清朝宗室后裔，九一八事变后率先投敌，组织伪吉林省政权，后任伪满洲国财政部总长等职，积极参与伪满政权建设，其影响波及东北各省包括黑龙江地区。；清朝宗室后裔，九一八事变时任东北边防军驻吉林副司令长官公署参谋长，主动开门揖盗迎接日军进入吉林，组织伪吉林省政权，后任伪满洲国财政部总长、宫内府大臣等职，积极参与伪满殖民统治。；清末宗室，九一八事变后率先投敌，组织伪吉林省政权，后任伪满洲国财政部总长、宫内府大臣等职，积极参与伪满统治，影响波及黑龙江地区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('864c7331aaf74b9a8844e3d4daebecff','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满洲国军政部大臣、伪军头目','原东北军将领，九一八后投敌，任伪奉天警备司令、伪军政部大臣等职，率伪军镇压东北抗日武装。；原东北军将领，九一八后投敌，任伪满军政要职，参与指挥伪军在热河、赤峰一带围剿抗日力量。；伪满洲国要员，主要活动于东北，与重庆沙坪坝无直接关联。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3a71c4d0f7494892bdb576cc07904cf7','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洲国洮辽镇守使、伪军头目','九一八后投敌，率伪军配合日军进攻黑龙江，任伪洮辽镇守使等职。；原东北军将领，1931年投敌，任伪洮辽镇守使，率伪军进攻通辽、开鲁等地，配合日军侵占内蒙古东部，后任伪满洲国军政部大臣。；原东北军将领，九一八事变后投靠日本，任伪洮辽镇守使等职，率伪军配合日军进攻热河、通辽及内蒙古东部地区，参与镇压抗日武装。；原东北军将领，九一八后投敌，率伪军配合日军进攻黑龙江、吉林等地，是早期伪军重要头目。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9db5e7ff5d424e1ea70a0db1e5bd7ba5','084a8b66c5e446d3a73b6e2d5205b4d8',1938,'汪伪政权要员、伪中央监察委员','汪精卫之妻，积极参与汪精卫投敌活动，任伪中央监察委员等职，是汪伪政权重要成员。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e59aaf96d10442b0b427b50c8a0ff9ea','d1abe59a5d664bf18b442130fc0478a1',1940,'伪国民政府宣传部长','汪伪政权宣传头目，控制伪宣传机构，进行亲日卖国宣传。；汪伪宣传系统负责人，在芜湖等地推行奴化宣传，控制舆论，美化日军侵略。；控制伪宣传机构，鼓吹“和平反共”，为日本侵略辩护。；在南京控制舆论，鼓吹“和平反共”，为日军侵略辩护；控制南京及江苏舆论，宣传“大东亚共荣”，为日本侵略辩护。；在南京控制舆论宣传，鼓吹“中日亲善”，麻痹民众抗日意志。；主管汪伪宣传，在南京鼓楼区设立宣传机构，鼓吹“和平反共”卖国理论。；广东信宜人，但长期在浙江活动，汪伪宣传部长，控制浙江舆论，1946年被处决。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('253c3a1b163e4f8abacd8ebb00185677','4ff53dd874e141ef96803ca1d78fd200',1938,'伪上海市长','上海沦陷后投敌，任伪上海市长，后被刺杀。；原上海总商会会长，投敌任伪上海市长，1940年被刺身亡。；上海伪市长，活动于上海，与广西玉林无直接关联。；浙江镇海人，抗战期间任伪上海市长，配合日军统治，其伪政权与江西沦陷区有经济联系。；浙江镇海人，抗战期间投靠日军，任伪上海市长，在华中地区推行伪化统治，其活动与湖南地区伪政权有联系。；投靠日伪，任伪上海市长，后被军统刺杀。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6bf86baa95b44eb183f0f09899d1ce9f','96b96eb8f5414a1f874f70f38feb0054',1937,'伪上海特别市市长','上海沦陷后组织伪上海大道市政府，任伪市长，是上海早期伪政权头目。；日军占领上海后组织伪上海特别市，任市长，为上海地区早期汉奸。；上海伪政权头目，属华中伪政权体系。；上海伪政权头目，与重庆地区无直接关联。；投靠日本，在上海组建伪政权，配合日军统治，对陕西有间接影响。；投靠日本，任伪上海市长，配合日军在华东及华北包括陕西周边地区进行殖民统治。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('380598501a7340cc9e17be28ee0c8f12','3f934b1c263b4cd78c73d9700621e7bd',1938,'伪南京市长、伪江苏省长','伪维新政府及汪伪政权要员，历任伪南京市长、伪江苏省长等职。；汪伪地方大员，参与伪政权运作。；抗战期间投敌，历任伪南京市长、伪江苏省长等职，协助日军统治江苏。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('15fe417ea84847ff83b02ee71dfff91b','f62754ef8d4a41f58e3b8f1b4bd4ab3a',1940,'伪国民政府考试院院长','汪伪政权要员，任伪考试院院长，进行亲日文化宣传。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a7145c5ed72847a0988336b268981985','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满洲国立法院长','九一八后投敌，参与伪满洲国建立，任伪立法院长等职。；九一八事变后积极参与伪满建国活动，起草伪满法律，为日本殖民统治提供法理支持，其政治活动覆盖吉林全省。；参与策划伪满洲国成立，在伪政权中担任要职，为日本侵略吉林等地提供法律和制度支持。；积极参与伪满洲国筹建，为日本侵略东北提供法律和舆论支持，是伪满高层汉奸之一。；东北伪政权头目，属全国性汉奸，与广西无直接关联但属抗战时期汉奸名录。；伪满洲国要员，主要活动于东北，与重庆沙坪坝无直接关联。；辽宁人，九一八事变后投敌，参与策划伪满洲国成立，任伪立法院长，为伪满政权重要汉奸之一。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c345dcab4a83471fa5344db6ae2227fd','44e5f00b1df64ad0b7492bfbdfcec121',1932,'伪满洲国外交部总长','伪满洲国外交部总长，参与伪满对外卖国外交。；台湾人，投敌后任伪满洲国外交部总长，参与伪满政权外交与统治活动。；台湾人，投敌后任伪满外交部总长，参与伪满对外交涉与卖国活动。；原为张勋复辟参与者，后投靠日本，任伪满洲国外交部总长，代表伪满与日本签订多项卖国条约。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4f9436058a2f4785b203d58101714d08','3bf604436ded42d99cdb3360887a08c5',1932,'伪满洲国参议府参议、伪满文化机构要员','清遗老，积极参与伪满洲国建立，任伪参议府参议等职，在文化教育领域附逆。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dfe99086df4f451c847b2aef96a7a157','2acba151834b4857b8b6e41c12ee546c',1932,'伪满洲国邮政总局局长','郑孝胥之子，任伪满洲国邮政总局局长等职，属伪满政权成员。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4e8cf915bfe145c68c73e105a89c522b','6876b4dc973441299b47d406050a627f',1932,'伪满洲国实业部大臣','张之洞之子，投敌后任伪满洲国实业部大臣等职。；伪满要员，后调任伪华北政务委员会，其活动涉及山东聊城地区经济掠夺。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a5d8450c2c634ccaaa633e9518b7131a','e409ef959281461b91e8ce1eef37d186',1937,'伪华北政务委员会委员、伪河北省长','原东北军将领，投敌后任伪华北政务委员会委员、伪河北省长等职。；在河北伪政权中任职，配合日军对包括张家口在内的华北占领区进行控制与掠夺。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2f43ba4a917b4882848ce8c25744dfc1','da58b77853f14ce7b32f7f6b3305b75a',1937,'伪华北政务委员会治安总署督办、伪军头目','华北伪军头目，任伪治安总署督办，组建伪治安军配合日军扫荡。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f42e0e9470464141aea54b2da8a498c1','d2b840cc6fa142c8b5c30c100a11b64d',1937,'伪华北政务委员会绥靖总署督办','华北伪政权要员，任伪绥靖总署督办，统辖伪军。；参与伪华北政权，协助日军在华北包括陕西周边地区维持殖民统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b8c22fecbde54c28b1a8f97a1921d5b5','10b88f41fdee46778f29f60ae3d41741',1935,'伪天津市市长','华北伪政权要员，任伪天津市长等职。；曾任冀察政务委员会政务处长，后投靠日军，任伪天津市市长，参与签订卖国协定，协助日军控制天津。；在南京鼓楼区与汪伪高层会面，协调华北与华中伪政权。；投敌后任伪天津市市长，参与华北伪政权活动，协助日军镇压抗日力量。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3eec1b688c6848d59219790b962b908b','5b2f7fb20693426f81f3853beb962949',1937,'伪天津市市长','华北伪政权要员，任伪天津市长等职。；继任伪天津市市长，协助日军进行经济掠夺和殖民统治，迫害抗日人士。；长期担任伪市长，为日军提供粮食和物资，协助建立保甲制度，镇压反日力量。；抗战期间任伪天津市市长，配合日军统治，影响天津及廊坊周边地区。；天津伪政权头目，其统治区域与廊坊地区相邻，配合日军在河北的侵略。；投敌后任伪天津市市长，配合日军经济封锁，对华北抗日根据地包括陕西周边实施物资禁运。；投敌后任伪天津市市长，协助日军搜刮物资、镇压抗日活动。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('395b708a99a341a181274af551414954','4cc5391bc78947fa9bf1a4b59e0f5371',1939,'伪武汉特别市市长、伪天津市长','张之洞之子，投敌后历任伪武汉特别市市长、伪天津市长等职。；张之洞之子，抗战期间投敌，历任伪武汉特别市市长、伪天津市长等职，战后被处决。；张之洞之子，投靠汪伪，曾任伪武汉市长，在湖北地区为日军服务。；河北人，伪地方要员，活动于武汉、天津，与湖南无直接关联。；张之洞之子，抗战期间投敌，历任伪武汉特别市市长、伪天津市长等职，协助日军维持占领区统治。；在华中、华北伪政权中历任要职，配合日军推行殖民统治，其活动范围涉及华北包括陕西周边。；在华中、华北沦陷区任伪职，配合日军统治。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d55c36e233354f8e8123ea86a29e7dab','26a40096acd9428f88ebde3e69fecb20',1938,'伪湖北省长','武汉沦陷后投敌，任伪湖北省长，后死于日军之手。；伪维新政府及汪伪政权湖北省长，其伪省政与江西九江邻近，配合日军对赣北的物资掠夺。；湖北伪政权头目，与万州邻近，曾试图向四川东部渗透。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2f8543dd47914cb4b1765e7c1ee3f21c','506df7877e6b4b589f0df223e5da77c6',1940,'伪湖北省长、伪参谋总长','汪伪政权要员，任伪湖北省长、伪参谋总长等职。；历任伪湖北省长、伪参谋总长，战后被捕；汪伪政权要员，参与对四川地方势力的策反。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9603d102b53c40cc874c4db0f2f4aea8','bb34b45b44c34a018d410cde66579fb1',1939,'伪武汉绥靖公署主任、伪陆军部长','原国民党将领，投敌后任伪武汉绥靖公署主任、伪陆军部长等职。；湖北黄陂人，原国民党武汉警备司令，投敌后任伪武汉绥靖公署主任、陆军部长，在华中地区配合日军。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3e4a24880c3a4c879c25f3ca53fed41e','915bcf11429e46bc80172aede7ac2e64',1940,'伪陆军部长、伪驻日大使','汪伪政权要员，任伪陆军部长、伪驻日大使等职。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('931e9404705b44a0899f169af3aa9b73','41d2b197fedd4eefa3bd64d7cebe1523',1940,'伪陆军部长、伪参谋总长','原东北军将领，投敌后任汪伪政权陆军部长、参谋总长等职。；辽宁人，原东北军将领，投敌后任汪伪陆军部长、参谋总长，指挥伪军配合日军。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ac964b2c9f6a49f483c135cb1f8f9966','fefd7f9ddbac40469c751144d6cbd784',1940,'伪军委会委员、伪军头目','原东北军将领，投敌后任汪伪军委会委员等职。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('572827d71e854a5688a60341bd785345','259163e844a045a9964a8dfa9d5dd306',1940,'伪军委会委员、伪军头目','原东北军将领，投敌后任汪伪军委会委员等职。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0d73774a11324ff5bdfc69c86b95e625','903f92a867db4e77abb94dac1ad28168',1937,'伪第一集团军总司令','原国民党苏鲁皖边游击军副总指挥，1941年率部投敌，任伪第一集团军总司令，配合日军进攻苏中抗日根据地。；原国民党苏鲁皖游击副总指挥，投日后任伪军总司令，其部队在安徽、江苏交界活动，对皖东、皖西抗日根据地形成压力，间接影响六安地区。；率伪军驻苏皖边界，多次侵入安庆地区进行“清剿”。；率伪军驻防苏皖边境，曾进犯安庆、大观地区。；原国民党苏鲁皖边区游击副总指挥，1941年率部投敌，所部伪军活动范围包括安徽东部。；原国民党军将领，1941年率部投敌，任伪第一集团军总司令，其伪军活动范围包括安徽部分地区，配合日军进攻抗日根据地。；原国民党苏鲁皖边区游击副总指挥，1941年率部投敌，所部在苏皖北部活动，与阜阳地区抗日力量为敌。；原国民党军将领，投敌后任伪第一集团军总司令，活动于苏中、皖南一带，对安徽沦陷区包括黄山、休宁地区有影响。；原国民党苏鲁皖边区游击副总指挥，1941年率部投汪伪，所部活动于苏北泰州、扬州及淮海地区，与宿迁一带伪军有协同。；原国民党苏鲁皖边区游击副总指挥，1941年率部投汪伪，所部在苏北包括宿迁、泗阳地区活动，配合日军进攻新四军根据地。；江苏泰州人，原国民党鲁苏皖边区游击副总指挥，1941年率部投敌，任伪第一集团军总司令，配合日军进攻苏中、苏北抗日根据地。；原国民党将领投敌，任伪第一集团军总司令，其部队在长江中下游地区配合日军作战。；江苏人，原国民党将领，抗战期间投靠日军，任伪第一集团军总司令，在华东地区进行伪化统治。；投降日军后，在江苏、安徽、湖南等地组织伪军，配合日军作战，参与伪政权军事活动。；在江苏投敌，率伪军配合日军，其活动主要在华东，与陕西无直接关联。','省部级/大军区级要员','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ea42b3f88a434b9b915918324cc42e82','5a14726dc0a944709762daf466d4cd08',1941,'伪苏皖边区绥靖军总司令','原国民党军将领，投敌后任伪苏皖边区绥靖军总司令。；原国民党军将领，投敌后任伪苏皖边区绥靖军总司令，在苏皖交界包括六安、霍邱附近进行伪化活动。；原国民党军将领，投敌后任伪苏皖边区绥靖军总司令，活动于苏皖边区包括宣城一带。；原国民党军官，投敌后任伪苏皖边区绥靖军总司令，其伪军活动范围覆盖安徽滁州、来安等县，协助日军维持占领区治安。；投敌后任伪苏皖边区绥靖军总司令，在皖北、苏北地区收编土匪武装，配合日军对阜阳、颍上等地的抗日力量进行扫荡。；汪伪伪军头目，率部在苏皖边区活动，马鞍山、当涂沿江一带为其伪军活动范围之一，配合日军清乡。；投敌后驻苏北、山东交界，与聊城地区伪军有协同。；在江苏北部组织伪军，配合日军扫荡。；江苏人，原国民党军将领，投敌后任伪苏皖边区绥靖军总司令，在苏皖赣边区配合日军扫荡。；伪军头目，其部队在长江中下游地区包括湖北东部配合日军清乡。；投靠日本，在华中及华北包括陕西周边地区配合日军进行统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('79ae512ee5004304a5c213d4ba1ef503','bacadba533394b3bb79fb5b9c5b66118',1940,'伪浙江省长、伪军头目','原国民党军将领，投敌后任伪浙江省长等职。；浙江杭州人，抗战期间任伪浙江省长、伪军师长等职，在浙江地区配合日军扫荡抗日武装。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2daf528b283c4736b22854c630c916fb','d823baec96e04682bca33413f02ae20d',1940,'伪浙江省长','汪伪政权要员，任伪浙江省长等职。；浙江乐清人，汪伪政权浙江省长，配合日军在浙江沦陷区推行伪化统治。；浙江乐清人，汪伪浙江省长，在浙江沦陷区推行伪化统治。；浙江乐清人，抗战期间投靠汪伪政权，出任伪浙江省长，协助日军在浙江的统治。；继任伪浙江省长，在诸暨、绍兴等地实施“清乡”和“治安强化”运动，配合日军扫荡。；作为伪浙江省最高行政长官，直接管辖舟山地区，配合日军“治安强化”运动。；浙江乐清人，抗战期间出任伪浙江省长，协助日军统治浙江，1947年以汉奸罪被处决。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6d906438d3294770b3df2417cb2410e9','3f934b1c263b4cd78c73d9700621e7bd',1938,'伪江苏省长、伪南京市长','伪维新政府及汪伪政权要员，历任伪南京市长、伪江苏省长等职。；在镇江地区推行汪伪政权法令，协助日军征粮、拉夫，镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4e90423928d142b8ae424b4faa66b3d1','50380aeea4d040e7b7134a1f53cc71e3',1938,'伪江苏省长','伪维新政府要员，任伪江苏省长。；伪维新政府要员，参与华中沦陷区伪化统治，其体系影响江西九江一带的维持会组织。；江苏伪政权头目，与重庆地区无直接关联。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9f58d9c564544bf1a5d07dad11ab5bb6','a06c0041e5294f2987f746729e510de9',1943,'伪淮海省长、伪军头目','原国民党军将领，投敌后任伪淮海省长、伪军头目，后反复无常。；原国民党军官，投敌后任伪淮海省长，在江苏北部组织伪军，配合日军作战。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('089822a608f74894b41a52104302af4d','63006a4879fb4f49ad97a1e88c8c5d69',1942,'伪第二方面军总司令','原国民党军将领，1942年率部投敌，任伪第二方面军总司令，配合日军进攻抗日根据地。；原国民党军将领，1942年率部投敌，所部伪军在苏皖北部活动，曾窜扰六安、霍邱一带。；率伪军驻扎安徽西部，多次进犯安庆周边抗日根据地。；率伪军驻防安徽部分地区，包括安庆附近，参与对抗日根据地的进攻。；原国民党军将领，1942年投敌，所部伪军活动于鲁西、皖北、豫东，曾配合日军扫荡阜阳周边抗日根据地，征收粮秣。；原国民党第三十九集团军副总司令，1942年投敌，所部驻防苏北、苏中，参与日军“扫荡”和“清乡”行动。；原国民党军将领，投汪伪后任伪第二方面军总司令，所部驻防苏北，包括宿迁、泗阳一带，配合日军作战。；率部驻防苏北、徐州地区，在邳州境内设立据点，参与“扫荡”八路军和地方游击队。；原国民党军将领，1942年在河南投敌，任伪第二方面军总司令，所部在河南、山东一带配合日军作战，镇压抗日力量。；原国民党将领投敌，任伪第二方面军总司令，其部队在华中地区配合日军作战。；天津人，原国民党将领，抗战期间投靠日军，任伪第二方面军总司令，在华中地区包括湖南北部进行伪化统治。；率部投敌，在华北地区配合日军作战，其伪军活动范围涉及华北，对陕西抗日根据地有间接威胁。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2b485c795ebe43589f5477c8e42505a9','40ceda4a3fba43bb8c30faefaa993de4',1943,'伪第三方面军总司令','原国民党军将领，1943年率部投敌，任伪第三方面军总司令，配合日军扫荡山东抗日根据地。；原国民党军将领，1943年投敌，所部伪军在安徽北部活动，与六安、霍邱地区伪军有协同。；其伪军部队曾调至安徽，在安庆附近与抗日武装作战。；原国民党军将领，投敌后任伪军要职，其部队在安徽及山东交界活动，对安徽沦陷区有影响。；原国民党军新编第四师师长，1943年投敌，所部伪军活动于鲁南、皖北，曾参与对阜阳周边地区的扫荡与清乡。；原国民党军将领，1943年率部投敌，任伪第三方面军总司令，所部在鲁苏皖边区活动，其势力范围覆盖皖北阜阳周边。；原国民党军将领，投敌后任伪第三方面军总司令，活动于山东、安徽北部，对安徽沦陷区有影响，间接涉及黄山、休宁地区。；原国民党新编第四师师长，1943年投敌，率部在苏北、皖北一带配合日军作战，残害新四军及百姓。；原国民党军将领，投汪伪后任伪第三方面军总司令，部队在苏北、鲁南活动，曾涉及宿迁、泗阳周边地区。；所部曾调防徐州一带，配合日军对邳州、宿迁等地进行“清乡”，杀害抗日群众。；原国民党军将领，1943年在山东投敌，任伪第三方面军总司令，其伪军活动范围涉及河南东部，配合日军扫荡抗日根据地。；原国民党将领投敌，任伪第三方面军总司令，其部队在华中地区配合日军行动。；山东人，原国民党将领，抗战期间投靠日军，任伪第三方面军总司令，在华东地区进行伪化统治。；在山东投敌，率伪军配合日军扫荡，其活动区域与陕西无直接关联，但属华北伪军网络。；在山东地区投敌，组织伪军配合日军扫荡抗日根据地。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b54241d525b84dea9c03357b9b2204a4','fabd450d8480433fb1634895d3c43510',1938,'伪山东保安军头目','山东伪军头目，长期配合日军进攻山东抗日根据地。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1fe9ff8654964a8481388c2a334bdfd5','b1e2c050fe6449ff84cb46f64f24d30e',1938,'伪山东保安军头目','山东伪军头目，长期配合日军进攻胶东抗日根据地。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c540a052efce462ba56bd617f286f84e','b19edc2e16ec4c7d9462b01fbba0f27f',1943,'伪军头目','原国民党军将领，被俘后投敌，任伪军头目。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d6ad350c8d3c4fb687466bfa1e248c0e','5ec2ad124b2f429482b1a90a7f8d4a92',1943,'伪第二十四集团军总司令','原国民党军将领，1943年被俘后投敌，任伪第二十四集团军总司令，配合日军进攻太行山区。；原国民党河北省主席、第二十四集团军总司令，1943年在河南林县被俘后投敌，任伪第二十四集团军总司令，率部在豫北、豫西配合日军行动。；原国民党军将领，1943年在河南投日，任伪第二十四集团军总司令，所部活动于豫北、豫东地区，协助日军维持占领区。；1943年投敌后，在河南平顶山、林县等地率伪军配合日军扫荡，镇压抗日武装。；原国民党河北省主席、集团军总司令，1943年投日，任伪职，其伪军活动范围包括豫北新乡地区。；1943年在豫北被俘后投敌，任伪第二十四集团军总司令，率伪军配合日军在豫北作战，新乡、延津地区受其伪军活动影响。；原国民党河北省主席、第24集团军总司令，1943年在河南林县被俘后投敌，任伪职，率伪军配合日军在豫北、新乡地区“扫荡”。；原国民党河北省主席、第二十四集团军总司令，1943年在河南林县被俘后投敌，率部伪化，活动于豫北新乡等地，协助日军维持占领。；1943年在河南投敌，率部编入伪军，活动于豫北、豫西地区，配合日军维持占领区秩序并进攻抗日武装。；投敌后统率伪军活动于豫北、豫西，其势力范围一度接近洛阳，协助日军进攻抗日根据地。；1943年投降日军，在豫北地区收编伪军，协助日军维持占领区治安，镇压抗日力量。；1943年在河南投敌，率部降日，所部伪军活动于豫北、焦作一带。；原国民党军将领，1943年在河南投敌，被汪伪政权委任为伪第二十四集团军总司令，率部配合日军进攻抗日根据地。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('75a44e432c524e4ca199d78e3e4fc617','9f7b3ed9c76f4eea8211fd8ebc40a461',1943,'伪第二十四集团军副总司令','原国民党军将领，1943年被俘后投敌，任伪第二十四集团军副总司令。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a0baa714e13a413a8eaad37089fa6b13','5f82d23ccd2e45fd9e59f76c92bcc9ad',1930,'伪蒙古军总司令','热河投敌，组织伪军配合日军进攻察哈尔、绥远，任伪蒙古军总司令。；原为热河土匪，后投靠日军，任伪蒙古军总司令，在察哈尔、绥远（含乌兰察布、卓资地区）协助日军镇压抗日力量，参与“治安肃正”行动。；率伪蒙古军在乌兰察布、四子王旗一带协助日军扫荡抗日武装，镇压当地民众，掠夺资源。；率伪蒙古军驻防察哈尔地区，配合日军扫荡抗日根据地，在乌兰察布及察哈尔右翼后旗一带实施“治安肃正”，残害抗日军民；原为热河土匪，后投靠日军，任伪蒙古军总司令，配合日军进攻绥远、乌海及河套地区，镇压抗日力量，掠夺资源。；投靠日本关东军，任伪蒙古军总司令，参与绥远事变，协助日军进攻绥远、内蒙古西部，镇压抗日力量。；率伪蒙古军协助日军在兴安盟、乌兰浩特一带扫荡抗日武装，参与建立伪蒙疆政权，残害当地民众。；率伪蒙古军配合日军在内蒙古东部及兴安地区作战，其部队活动范围曾覆盖兴安南省，包括科尔沁右翼前旗周边，参与镇压抗日武装。；投靠日军，任伪蒙古军总司令，参与镇压内蒙古东部抗日力量，其部队曾活动于兴安盟及阿尔山周边地区，配合日军“讨伐”东北抗日联军。；原东北军军官，投靠日军后组建伪蒙古军，在包头及绥远地区协助日军进攻抗日武装，参与建立伪蒙疆政权，镇压抗日力量。；原东北军将领，投靠日军后组建伪蒙古军，在绥远（含包头、东河）地区配合日军进攻抗日武装，参与“治安肃正”行动，残害抗日军民。；原东北军将领，1933年投靠日军，组建伪蒙古军，任总司令，配合日军进攻绥远、包头等地，镇压抗日力量，协助日本殖民统治内蒙古地区。；原为东北军军官，后投靠日军，组建伪蒙古军，在绥远（含固阳、包头）一带配合日军进攻抗日武装，镇压抗日力量。；土默特右旗人，早年投靠日军，组建伪蒙古军，任总司令，配合日军进攻绥远地区，参与建立伪蒙疆政权，镇压抗日力量。；原东北军将领，后投靠日本，任伪蒙古军总司令，在包头、绥远一带配合日军进攻抗日武装，参与建立伪蒙疆政权。；原为热河土匪，后投靠日本关东军，组建伪蒙古军，在察哈尔、绥远（含包头、白云鄂博一带）配合日军进攻抗日武装，镇压蒙汉民众，掠夺矿产资源。；率部投日，任伪蒙古军总司令，参与镇压抗日力量，在内蒙古东部及呼伦贝尔一带协助日军维持治安；率部投靠日军，任伪蒙古军总司令，在内蒙古地区配合日军作战，影响波及呼伦贝尔。；原东北军将领，投靠日军后任伪蒙古军总司令，在呼伦贝尔及内蒙古东部地区协助日军镇压抗日力量，参与“满洲国”边境军事行动。；原东北军将领，投靠日本后任伪蒙古军总司令，参与侵占绥远（今呼和浩特地区），配合日军进攻归绥（今呼和浩特），镇压抗日力量。；原为热河土匪，后投靠日本关东军，组建伪蒙古军，配合日军进攻察哈尔、绥远等地，在呼和浩特及周边地区协助日军维持殖民统治，镇压抗日力量。；原东北军将领，后投靠日本，组建伪蒙古军，在土默特左旗及绥远地区协助日军清剿抗日武装，参与“治安强化”运动，残害抗日军民。；原东北军军官，后投靠日军，任伪蒙古军总司令，在武川、百灵庙一带配合日军进攻抗日武装，参与‘治安肃正’计划，残害蒙汉民众。；原东北军军官，后投靠日本关东军，在乌拉特前旗及周边地区协助日军建立伪蒙古军政权，参与镇压抗日力量，配合日军“扫荡”河套地区。；原为热河土匪，后投靠日军，任伪蒙古军总司令，在通辽、库伦旗等地协助日军镇压抗日力量，参与‘治安肃正’行动。；原东北军军官，后投靠日军，任伪蒙古军总司令，在通辽、开鲁等地协助日军镇压抗日力量，参与建立伪满洲国和伪蒙疆政权。；率伪蒙古军活动于山西北部及吕梁部分地区，配合日军进攻抗日根据地，为日军征集物资。；率伪蒙古军活动于晋北、朔州、右玉一带，配合日军扫荡抗日根据地，抢掠民财。；原为东北军军官，后投靠日军，在平鲁及周边地区协助日军扫荡，残害抗日军民。；原为东北军军官，后投靠日军，在绥远、山西北部（含朔州、怀仁一带）协助日军进攻抗日武装，建立伪政权，参与“治安强化运动”，残害抗日军民。；活动于察哈尔、绥远，与广西玉林无关。；广西籍（贺州）汉奸，投靠日军，组织伪蒙古军，配合日军侵略华北。；原为东北军军官，后投靠日军，在察哈尔（含张家口、万全）地区组建伪蒙古军，配合日军进攻抗日武装，镇压当地民众，曾任伪蒙古联合自治政府副主席。；原为热河地方军阀，1933年投靠日军，任伪蒙古军总司令，在察哈尔（含康保、张家口地区）配合日军进攻抗日武装，参与建立伪蒙疆政权，镇压当地抗日力量。；原为热河地方军阀，1933年投靠日军，任伪蒙古军总司令，在察哈尔（含张家口、怀安一带）配合日军进攻抗日武装，参与建立伪蒙疆政权，镇压当地抗日活动。；原为热河地方军阀，1933年投靠日军，任伪蒙古军总司令，在察哈尔（含怀来周边）配合日军进攻抗日武装，参与建立伪蒙疆政权，协助日军推行“治安肃正”计划。；原为热河地方军阀，1933年投靠日军，任伪蒙古军总司令，参与侵占察哈尔（含沽源）地区，配合日军扫荡抗日武装。；原为热河土匪，后投靠日军，任伪蒙古军总司令，在察哈尔（含张家口、阳原一带）配合日军扫荡抗日武装，残害百姓。；原热河地方军阀，投日后任伪蒙古军总司令，多次率部进攻围场抗日根据地，屠杀抗日军民；率伪蒙古军配合日军在热河、承德一带进攻抗日游击队，参与制造多起屠杀事件。；长期在华北、河南北部活动，配合日军进攻抗日根据地。；长期充任伪军头目，其部曾配合日军在华北、河南等地作战。；内蒙古人，长期在伪蒙疆政权任职，其伪军活动范围主要在察哈尔、绥远一带，但曾配合日军在河南北部地区进行扫荡作战。；内蒙古人，抗战期间投靠日军，任伪蒙古军总司令，在华北地区进行伪化统治。；蒙古伪军头目，配合日军侵略华北，其活动范围与陕西宝鸡抗日后方形成对抗。；在内蒙古及华北地区组织伪军，配合日军进攻抗日根据地，其活动范围接近陕西北部。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('279ee237dce1441aae25ba248fdec9df','529eba01fd3844d2a4780badaf25cb50',1936,'伪绥西联军总司令','绥远投敌，组织伪军配合日军进犯绥西。；绥远地区土匪出身，投靠日军后组织伪军，活动于绥远、察哈尔一带，配合日军进攻抗日根据地，与锡林郭勒盟邻近地区有军事联系。；在山西、绥远交界地区组织伪军，配合日军扫荡吕梁山区抗日力量，残害抗日群众。；率伪军配合日军在华北及河南部分地区进行军事行动。；内蒙古人，抗战期间投靠日军，任伪绥西联军总司令，在华北地区进行伪化统治。；在绥远地区组织伪军，配合日军进攻绥西，活动区域与陕西邻近。；投靠日本，在绥远地区组建伪军，配合日军侵略，其活动范围与陕西北部邻近。；绥远伪军头目，配合日军侵略绥西，其活动与陕西宝鸡抗日后方有间接关联。；绥远伪军头目，活动于陕西邻近的绥西地区，与渭南、华州无直接关联但属陕西周边汉奸。；在绥远、陕西邻近地区组织伪军，配合日军进攻绥西，对陕西榆林、神木等地构成威胁。；在绥远投敌，组建伪军，配合日军进攻绥西。；在绥远地区组织伪军，配合日军进攻，绥远与陕西相邻，其活动对陕西北部有影响。；在绥远、陕西交界地区组织伪军，配合日军进攻绥西抗日根据地。；在绥远、陕西周边组织伪军，配合日军进攻绥西及陕北抗日力量。；投靠日本，组建伪军在绥远及陕西周边地区配合日军作战和统治。；在绥远、内蒙古西部组织伪军，配合日军进攻绥西，其活动区域与陕西北部邻近。；在绥远地区组织伪军，配合日军侵略，其活动范围与陕西北部接近。','基层头目','hanjian');
