INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('47193a5539b54d0ca59df298bd6ac67a','c78f7cbace5745088165e412807d4ba1',1931,'未任伪职，但曾被日伪拉拢未成','云南腾冲人，辛亥革命元老。日军侵占腾龙地区后曾企图拉拢其出面维持，李根源坚决拒绝并避走昆明，未附逆。；云南腾冲人，辛亥革命元老，抗战期间在云南主张抗日，日伪曾试图拉拢其附逆，未从。此条为排除性说明，非汉奸。；云南腾冲人，辛亥革命元老。抗战期间在云南主张抗日，日伪曾试图拉拢其合作，但其拒绝附逆。此条仅作排除性说明，非汉奸。；云南腾冲人，辛亥革命元老。日军侵占滇西期间曾试图拉拢其附逆，李根源坚决拒绝，未任伪职。此条为排除性说明，非汉奸。；云南腾冲人，辛亥革命元老。日军侵占滇西期间，日伪曾企图拉拢其出任伪职，李根源坚决拒绝，未附逆。此条为排除性说明，非汉奸。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e1ab7e1b661448e2a1f64dc3776d0260','f19b05dde9eb4bafb71e5fedcd5a10a8',1927,'云南省政府主席（抗战时期）','主政云南期间坚持抗日，组织滇军出滇抗战，支持滇缅公路修建，未附逆。；云南昭通人，主政云南期间坚持抗日，派滇军出滇抗战，未附逆。此条为排除性说明，非汉奸。；主政云南期间坚持抗战，未附逆；但其所部部分地方势力在滇西沦陷区与日伪有暧昧接触。','无明确职位或一般帮凶','hanjian');
