INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5bf6b151df53435981aeaeb394a4b6f2','692b00cb1f2547ec8c9aa90d07974e99',1942,'滇西抗日游击队领导人','组织滇西抗日游击队，坚持敌后抗战，未附逆。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('08fa6122190f426082218d308c8f6928','fa2f1833bce1467bb91079eceb0f8e9f',1938,'汪伪政权相关拉拢对象（未附逆）','云南籍人士，抗战期间曾被汪伪方面接触拉拢，但未见可靠史料证明其出任伪职。此条为排除性说明，非汉奸。；云南籍人士，曾为国民政府官员。抗战期间有日伪接触传闻，但无确凿附逆任职记载，不宜列为汉奸。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('292f549c08e348459f16e53b81e6ed96','88ec72f25d9142ffa38e0e3c7abc9793',1940,'昆明地区维持会相关传闻人物','地方史料中偶见昆明附近维持会、伪保甲组织活动记载，但具体姓名、职务多不可考；马骧之名见于部分口述传闻，缺乏可靠档案佐证。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7ea2945d3fd1496c813751946b1ac074','50581fbac1324b869ea7a985cc40a582',1940,'昆明伪维持会成员（待考）','抗战后期昆明周边曾出现日伪渗透与维持会活动传闻，但云南地处大后方，未沦陷，故无成体系伪政权；相关人物多无明确档案记载。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('791baeab545643fca1436c407c60ed09','c78f7cbace5745088165e412807d4ba1',1931,'未任伪职（注：此条为误传辨析，实际李根源为抗日爱国人士，非汉奸）','李根源系云南腾冲人，辛亥革命元老，抗日战争时期主张抗日，曾任云贵监察使，赴滇西前线慰劳抗日将士，并非汉奸。若严格按汉奸标准，不应列入。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('39dc1b6305f64efaa60e9939bf6733f4','fa2f1833bce1467bb91079eceb0f8e9f',1940,'汪伪政权云南省伪政府筹备人员（未实任）','张邦翰系云南昆明人，早年追随汪精卫，抗战期间在南京汪伪政权中活动，曾参与策划在云南建立伪政权的图谋，但因云南抗日力量强大未能得逞。其活动范围涉及昆明及周边地区。；张邦翰为云南籍，曾与汪伪政权有联系，被列入汪伪拟任云南伪政府人员名单，但因云南未沦陷，未实际赴任。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('adffc3131e1d442c8ec078de70991474','66319a40a8a34b4bb46dc94fb8d9cbca',1940,'汪伪政权云南省伪政府筹备委员','裴存藩系云南昆明人，抗战期间投靠汪精卫，在南京汪伪政权中任职，曾受命策划在云南建立伪政权，并试图拉拢云南地方势力。其活动涉及昆明地区，但未能实际控制云南。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('380b9eddfe5044e2ac8808754c015290','c818d21e85994bec9f1c88e3d94165e1',1940,'汪伪政权云南省伪政府筹备人员','李培天系云南人，抗战期间与汪伪政权有联系，参与策划在云南建立伪政权，活动范围涉及昆明及周边，但因云南抗日力量强大而未果。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0d65e38cc89a4252b9bf14f4bc184e0c','0d2b86dbbedf44a286ab059fed3e73fa',1931,'未任伪职（注：杨杰为抗日爱国将领，非汉奸）','杨杰系云南大理人，民国时期军事理论家，抗日战争期间主张抗日，曾任驻苏联大使，并非汉奸。不应列入。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bbe633dc79304c71888c375e24bc7fe0','f19b05dde9eb4bafb71e5fedcd5a10a8',1931,'未任伪职（注：龙云为抗日爱国将领，非汉奸）','龙云系云南昭通人，主政云南期间积极抗日，组织滇军出滇抗战，修筑滇缅公路，并非汉奸。不应列入。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('82ff2d35b47246868401f259725c6dba','9d2b826426c34c7c926fd866703bd438',1931,'未任伪职（注：卢汉为抗日爱国将领，非汉奸）','卢汉系云南昭通人，滇军将领，抗日战争期间率部参加台儿庄战役等，并非汉奸。不应列入。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d21e6cd2e2e64964b52ca073a7e79891','88ec72f25d9142ffa38e0e3c7abc9793',1940,'汪伪政权云南省伪政府筹备人员','马骧系云南人，抗战期间与汪伪政权有联系，参与策划在云南建立伪政权，活动范围涉及昆明及周边，但因云南抗日力量强大而未果。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aeb840f828fc49df99b94e4cd883820b','74446133ef8b4f1fb636ca6eb6ca48f7',1940,'汪伪政权云南省伪政府筹备人员','张维翰系云南人，抗战期间与汪伪政权有联系，参与策划在云南建立伪政权，活动范围涉及昆明及周边，但因云南抗日力量强大而未果。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fd3c7130738740e4910d22efc080088f','99fd0870d61d4358bd5bdaae689badf0',1940,'富民县维持会会长（疑似）','据部分地方史料记载，富民县在抗战期间曾有维持会组织，但具体负责人姓名及事迹记载不详。李华一名见于部分口述史料，称其曾担任富民县维持会会长，协助日军征粮派款，但缺乏确凿档案证据。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('82f8394d0e814eae95cfc1a69c70af93','332c8160857542c29c2b123e6e339e1e',1940,'昆明维持会相关传闻人物（待考）','云南昆明地区在抗战后期面临日军威胁时，地方有维持会筹备传闻，但马伯安是否实际任职及附逆情节缺乏可靠档案佐证。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dc70dc8ebd0744f1b3f6f90e609eb38b','fa0290958ae54e2f996de141eaaa97e5',1942,'伪云南省维持会筹备人员（待考）','云南地方史料中偶见日军侵滇期间拟组维持会之传闻，杨竹庵被提及，但无确凿伪职任命与活动记录。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('85557d6c49c547eea7fab45ba0ab79b0','0ce82afb041f4eb4a6fb886726d0274f',1942,'伪军头目（活动于滇西方向，与云南有关联）','滇西抗战期间，部分地方武装被日军利用编为伪军，李华堂之名见于滇西伪军相关记载，活动范围接近云南保山、龙陵一带，与昆明、寻甸无直接关联。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b0e7f4bb447545b78e39d100d830015f','fe7588d226fa430ea2eda3d08a162f2f',1940,'伪警察头目（昆明地区传闻）','昆明地区在抗战时期有伪警察、伪保甲组织传闻，张子明被地方口述史料提及，但缺乏正式档案确认。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('02657f3b8a394a2b8fa72998917b6e46','7b6379ed99634fa0a5c5a55d8d2a6cee',1943,'伪保甲长（寻甸地区传闻）','寻甸地区在抗战后期有保甲长被日军或伪政权利用的传闻，王少岩之名见于地方口述，但无可靠文献佐证。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4849513a9d304bb1981fc098b89ea105','5fd47c085e6e4f37b627367c38f0529e',1942,'伪维持会成员（昆明近郊传闻）','昆明近郊在日军空袭与威胁期间，有维持会筹备传闻，赵德恒被提及，但无确凿任职记录。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7e6ff77a0c2d4efa9f62e5f553c4e751','2922c41b8cc747b6bf4e27324c6eede9',1940,'伪云南省维持会会长、伪云南省政府委员','云南地方士绅，抗战期间附逆投敌，参与组织伪云南省维持会，协助日军在云南推行殖民统治，为日军搜集情报、筹措物资。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3173e86ded7440a085d88f57a8365920','fa2f1833bce1467bb91079eceb0f8e9f',1940,'伪云南省政府委员、伪昆明市市长','原为云南地方官员，抗战期间投靠日伪，出任伪昆明市市长，协助日军维持昆明地区治安，推行伪化教育。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('838b9a86fe674bbdad92ed8d900bd1f8','fa0290958ae54e2f996de141eaaa97e5',1940,'伪嵩明县维持会会长','嵩明县地方劣绅，日军侵入云南期间组织伪维持会，为日军征粮派款、带路搜捕抗日人员，压迫当地百姓。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dfa00c3ef8d04cb88cac602bf39dfe18','9c838699bd764601adeab3c900458700',1940,'伪昆明县警察局局长','投靠日伪后出任伪昆明县警察局长，协助日军镇压抗日活动，逮捕爱国人士，维护伪政权统治秩序。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('426312affcaf4215b2df57e52f52d1da','924b54766fd04afbade04b10d7fcf220',1940,'伪云南省宣传处副处长','抗战期间附逆，负责日伪在云南的宣传工作，创办亲日报刊，宣扬‘和平建国’，诋毁抗日力量。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('79ace3f6c30543218344bbb2c90dc72e','e9ffcf106b04408dae2c0afad0abea5c',1940,'伪昆明市商会会长','昆明商界人士，抗战期间与日伪经济合作，为日军筹措军需物资，垄断当地贸易，从中牟利。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9d0d2d0bc776413d8349eba9fae388af','0be73f89a75241078989970cfdafbc21',1940,'伪云南省教育厅督学','在教育领域附逆，推行日伪奴化教育，篡改教材，向学生灌输亲日思想，协助日军控制云南教育。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4927eed286a74c0894d045c2921ae612','524503e462964922a3509303c3d50c30',1940,'伪嵩明县保安大队大队长','组织伪保安大队配合日军扫荡嵩明及周边地区，镇压抗日游击队，残害抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b3be31dae4df4295a670385d34a521ff','aa97f0db7da847e095b67ffeddb0712a',1942,'滇西伪维持会相关人物（争议）','滇西沦陷期间，部分土司在日军压力下与日伪有接触，但刀京版等后来组织抗日武装。相关附逆情节史料记载不一，需谨慎对待。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d35e9e994e8240ac8b468a049286b48e','dc94893581a2428c9783cde9c8541f0c',1942,'滇西伪维持会会长（南甸）','云南梁河一带土司，日军侵占滇西后曾出任伪维持会会长，协助日军征粮、派夫，后抗日武装反攻时被俘。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('456237120f304e66bbfd3353e3ebda7f','32a44b4d500744bdac18ba0d09dc60cf',1942,'滇西伪维持会成员','云南干崖一带土司家族成员，滇西沦陷期间与日伪合作，参与维持会事务。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8bd8d9fa169d494b9dec5e26220ca0e2','64250c97c26d43e483d8a71f50a892a3',1942,'滇西伪维持会成员','云南陇川一带土司，日军侵占滇西后一度附逆，参与伪维持会活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5db938b1f3ec497c81182dc33038a03d','88989758d3594b5dbb5407a3b4bbd642',1942,'滇西伪维持会成员','云南遮放一带土司，滇西沦陷期间与日伪有合作，参与维持会。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('00e8b53055454891a5cace6688c3fb75','0849d541727841c7923fcba1dfb584f5',1942,'滇西伪维持会成员','云南耿马一带土司，日军侵占滇西期间曾附逆，参与伪维持会活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d69c0a83e1d14b28bde77ac5371867c0','9e072d80aa7b4da6b90de10af430d7a3',1942,'未任伪职，坚持抗日','云南腾冲人，滇西沦陷后出任腾冲抗日县长，拒绝日伪拉拢，坚持抗日。此条为排除性说明，非汉奸。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ba33d3aec639415cbf3f01c6bef4f0be','f19b05dde9eb4bafb71e5fedcd5a10a8',1931,'未任伪职，坚持抗日','云南省政府主席，抗战期间坚持抗日立场，未附逆。此条为排除性说明，非汉奸。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('35e305ddc62c4900a636eef1ea465fa2','9d2b826426c34c7c926fd866703bd438',1931,'未任伪职，坚持抗日','滇军将领，抗战期间率部参加台儿庄等战役，未附逆。此条为排除性说明，非汉奸。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f2effe9a24c8464dbdb0f2f4307582ff','9a157617d7024b2f885cee6c517224bb',1940,'伪维持会成员','昆明作为大后方，未沦陷，无公开伪政权。但日伪特务曾潜入昆明进行活动，相关附逆者史料零散，难以列出具体姓名。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0e153f35c65741219893b08913c588f0','5a54c0d7c2fa4add80fb0a66901ef129',1940,'伪保甲长/维持会成员','晋宁未沦陷，无公开伪政权。个别地方保甲长在日机轰炸或特务渗透中有妥协行为，但无可靠姓名记载。','基层帮凶(维持会系统)','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aedb1b375a2c4c5f918faff2bebf3e3d','08ecc8ca20f24d65b71cdd33b4002ebb',1931,'滇军将领','云南泸西人，率部参加台儿庄战役，坚持抗日，未附逆。此条为排除性说明，非汉奸。；坚持抗日，未附逆；但滇军内部个别地方武装在滇西沦陷时曾动摇。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('016e923fde804f29bf6c9108b9c0dd97','88ec72f25d9142ffa38e0e3c7abc9793',1942,'昆明维持会成员（待考）','云南昆明地区在抗战后期面临日军从滇西入侵威胁，但昆明市区始终未被日军占领，未建立正式伪政权。地方史料中未见昆明市区有明确记载的汉奸名录。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('185893415b87475883b0fed7f57c307f','d255dc1ec48b48db88f1279a2498b74c',1942,'伪云南省维持会筹备人员（待考）','日军侵占滇西腾冲、龙陵等地后，曾在当地扶植伪政权。但昆明、盘龙地区始终在中国军队控制下，未出现成规模的伪政权和汉奸名录。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ec42415a3ef641b6b592df9e087e03d0','30ffba7a850448dfa99cae772e1a16a2',1942,'滇西伪维持会人员（待考）','滇西沦陷区曾出现少数附逆分子，但具体姓名和事迹在公开史料中记载极少，且与昆明盘龙地区无直接关联。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ee74964867b742429613fceacd690ba7','289ae8c3458f4609a800c782181fba46',1942,'伪腾冲维持会会长（待考）','日军侵占腾冲后，当地曾成立维持会。但腾冲属保山地区，与昆明盘龙无直接关联，且具体人员记载模糊。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f9f0f3d80bad4814a092d2376d27a110','331a9be26fd54ff0a63653e86d585fb1',1942,'伪龙陵维持会人员（待考）','龙陵沦陷期间曾有附逆人员，但史料记载不完整，与昆明盘龙地区无直接关联。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ec384ce42b8841af99df91beff1ad042','6e20aaf31c5b4d2fbc9256c5906605e7',1931,'昆明地区未发现明确汉奸名录','经检索，昆明市盘龙区在抗战期间始终未被日军占领，未建立伪政权、维持会或伪警察机构。云南省内明确记载的汉奸主要集中在滇西沦陷区（腾冲、龙陵等地），但与昆明盘龙地区无直接关联。因此，针对云南、昆明、盘龙地区的汉奸名录，公开可靠史料中无具体可列人员。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dffc155ea72b49208438b8bdd9dd3dfe','2922c41b8cc747b6bf4e27324c6eede9',1940,'滇南伪军头目、土匪武装首领','长期盘踞滇南及昆明周边地区，抗战后期与日伪势力勾连，武装割据，抗拒抗日力量，残害地方民众。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9bd63915b6d445b0a97af979807a3218','f19b05dde9eb4bafb71e5fedcd5a10a8',1931,'云南地方实力派（抗战时期未附逆，相关传闻需辨析）','龙云主政云南期间坚持抗日，未任伪职；此条仅因部分民间传闻涉及昆明地区附逆线索而列，但无可靠史料证明其为汉奸。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dfd6c204b7c84ca5895c06e896445de4','9d2b826426c34c7c926fd866703bd438',1931,'滇军将领（抗战时期未附逆，相关传闻需辨析）','卢汉率滇军出滇抗战，无可靠史料证明其附逆；此条仅作辨析性列入，不应视为汉奸。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a43bd7d6d15e40da9eb9e8b067643b74','fa2f1833bce1467bb91079eceb0f8e9f',1937,'伪云南省维持会相关人物（待考）','部分地方史料提及昆明地区曾有维持会活动，但具体人名、职务多不可考，张邦翰是否确为汉奸存在争议。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('058b52897f68438abda9c9ed6e00cb1a','88ec72f25d9142ffa38e0e3c7abc9793',1937,'昆明地区伪维持会成员（待考）','地方志中偶见昆明附近维持会人员记载，但姓名、事迹残缺，难以确认其确切汉奸身份。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bc67cdd89a0a4e6e91063d13a9dde949','c489dc89003e469a804087df3235d77b',1937,'伪军军官（云南活动传闻）','有资料称其在云南边境与日伪合作，但缺乏昆明、石林地区直接活动证据。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('43a0c44882574bb2abdb530888030a8e','924b54766fd04afbade04b10d7fcf220',1937,'伪教育界附逆者（待考）','云南教育界个别附逆人员，曾在昆明参与伪教育宣传，但史料零散，难以确证。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('45f1e7ffd5414c80ada45f3ee797c67e','6a31182014144cdcb4186611b65d860a',1937,'伪云南省警务人员（待考）','传闻在昆明伪警察系统任职，协助日伪维持治安，但可靠记载不足。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('294282901e45429d9472260462194818','5fd47c085e6e4f37b627367c38f0529e',1937,'伪保甲长（昆明近郊）','昆明近郊伪保甲长，为日伪征粮派款，欺压百姓，但石林地区直接记载极少。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a352b8dd70f74536820673cc87ae42c9','09ee193c7c864ffca42191827c9675f8',1937,'伪经济界附逆者（待考）','云南经济界个别人员与日伪贸易往来，涉及昆明物资资敌，但具体身份存疑。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2b33e85f37df451ead827f7e33f3d6a9','c78f7cbace5745088165e412807d4ba1',1942,'未任伪职，但曾被日军胁迫未遂','李根源为云南腾冲人，辛亥革命元老。1942年日军侵占腾冲时，其家族部分成员曾被迫与日军周旋，但李根源本人坚决拒绝附逆，未任伪职。此条仅作辨析，非汉奸。；滇西沦陷期间，日军曾试图拉拢其出面组织伪政权，李根源坚拒并避走，未附逆。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('584d42bb9cee4eb1b47f73020f3d1dce','c818d21e85994bec9f1c88e3d94165e1',1940,'汪伪政权云南省伪政府筹备人员（未实任）','李培天为云南籍，曾参与汪伪政权对云南的策反与伪政府筹备活动，被列入拟任名单，未实际到任。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3382dc54b19d40e8bdcce1d74e236414','332c8160857542c29c2b123e6e339e1e',1940,'昆明维持会成员（未实任）','马伯安为昆明地方士绅，曾被日军及汪伪方面接触，拟任昆明维持会职务，但因昆明未沦陷，未实际成立维持会。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e2b537780cae471baa49de213aafe488','558ea77322f541fcb3af2e1e162cd89f',1942,'伪军头目（活动于滇西沦陷区）','王仲三在滇西沦陷区组织伪军，配合日军对腾冲、龙陵等地的控制，参与征粮、抓丁等行动。','无明确职位或一般帮凶','hanjian');
