INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2229ddb715174066a0f0c59086301f3b','49e11bcaeb2d4cec82a9144121d217f3',1942,'滇东伪合作社理事长','控制物资流通，为日军收购粮食、矿产。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6f5517206a1646268e573d9caf255017','3d2200381fdd4186aa372c02646d3fec',1942,'曲靖伪自卫团团长','率部投敌，配合日军维持治安，镇压抗日民众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('80d0379664834fdb8e41104ef9aac9a8','7912d5c535944fbdbbfdc3f577d5a4b9',1942,'滇西伪政权翻译','为日军审讯、劝降抗日人员提供翻译服务。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bb5c2f9a0177491fba917fe1d80e3c01','2829afcfc2794f7196f692e7b767bcdd',1942,'曲靖地区伪区长','在日军占领下出任伪区长，征粮派夫，压制抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7f003d727e9c4aca974449bde888a432','5f82d23ccd2e45fd9e59f76c92bcc9ad',1933,'伪蒙古军总司令、伪蒙古联合自治政府副主席','原为东北军军官，后投靠日本关东军，在乌兰察布地区（今乌兰察布市及周边）参与组建伪蒙古军，协助日军镇压抗日力量，推行“蒙古自治”傀儡政权，多次配合日军扫荡绥东地区。；原东北军军官，1933年投靠日军，组建伪蒙古军，在乌兰察布、丰镇等地协助日军扫荡抗日武装，镇压民众，后任伪蒙疆政府要职。；原为热河地方军阀，1933年投靠日军，组建伪蒙古军，在察哈尔、绥远（含乌兰察布、兴和一带）配合日军进攻抗日武装，后任伪蒙疆政府要职，协助日本殖民统治。；原东北军将领，1933年投日，在内蒙古东部及乌海、海勃湾周边地区协助日军镇压抗日力量，参与建立伪蒙古军政府，后任伪蒙疆政权要职，为日军提供兵员和情报。；热河土匪出身，投日后组织伪蒙古军，活动于内蒙古东部及兴安地区，配合日军进攻抗日根据地，其势力范围覆盖科尔沁右翼中旗一带。；原东北军将领，1933年投靠日军，组建伪蒙古军，配合日军进攻察哈尔、绥远（今内蒙古中西部），在包头、九原一带驻军并协助日军清剿抗日武装，后任伪蒙疆政权要职。；原东北军将领，投靠日本后组建伪蒙古军，在包头、青山地区配合日军进攻抗日武装，参与建立伪蒙疆政权，镇压当地抗日力量。；原东北军军官，1933年投靠日军，组建伪蒙古军，参与侵占察哈尔、绥远地区，镇压抗日力量，后任伪蒙疆政府要职。；热河卓索图盟人，早年在内蒙古东部组织伪军，后任伪蒙古军总司令，率部配合日军进攻绥远、察哈尔等地，控制包括呼和浩特在内的绥远大部分地区，推行伪蒙疆政权统治，镇压抗日力量。；原东北军将领，1933年投靠日军，组建伪蒙古军，在绥远（今呼和浩特、托克托一带）配合日军进攻抗日武装，参与建立伪蒙疆政权，镇压当地抗日力量。；热河、察哈尔、绥远地区蒙古族汉奸，率伪蒙古军配合日军侵占绥远大部，其势力范围覆盖巴彦淖尔地区，参与建立伪政权和伪军组织。；原为东北军军官，后叛变投日，任伪蒙古军总司令，其部队长期活动于绥远（含巴彦淖尔地区），协助日军控制河套平原，多次进攻抗日武装，并推行奴化教育。；原热河省军阀，1933年投日，组建伪蒙古军，配合日军侵占赤峰、围场等地，后任伪蒙疆政权军事要职，参与镇压抗日力量。；原热河省地方军阀，1933年投靠日军，组建伪蒙古军，参与侵占赤峰、元宝山地区，镇压抗日力量，协助日军推行殖民统治。；原为热河地方军阀，1933年投靠日本关东军，参与侵占热河、察哈尔等地，所部伪蒙古军配合日军在赤峰、昭乌达盟一带清乡、镇压抗日武装，后任伪蒙疆政权要职，是蒙疆地区最大的汉奸头目之一。；原为热河地方军阀，1933年投靠日军，任伪热河游击司令，后任伪蒙古军总司令，参与镇压抗日力量，协助日军控制赤峰、林西等地区，推行殖民统治。；热河蒙古族军阀，投靠日本后任伪蒙古军总司令，其部队活动范围包括通辽、科尔沁左翼中旗一带，参与日军对内蒙古东部抗日武装的围剿，后任伪蒙疆政权要职。；率伪蒙古军活动于热河、通辽及科尔沁左翼后旗一带，配合日军进攻抗日根据地，收编土匪武装，残害民众。；原东北军军官，后投靠日军，组建伪蒙古军，在通辽及内蒙古东部地区协助日军镇压抗日力量，参与“治安肃正”行动，掠夺资源，迫害民众。；原为东北军骑兵，后投靠日本，参与组建伪蒙古军，率部配合日军侵占察哈尔、锡林郭勒盟等地，长期在伪蒙疆政权中任军政要职，镇压抗日力量。；原东北军军官，后投靠日军，参与组建伪蒙古军，率部配合日军侵占察哈尔、锡林郭勒等地，任伪蒙古军总司令，是伪蒙疆政权主要军事头目之一。；率伪蒙古军配合日军进攻绥远、宁夏北部，在贺兰山以西及阿拉善地区活动，参与对宁夏的军事威胁和情报搜集。；率伪蒙古军配合日军在晋西北、吕梁一带进行扫荡，参与对抗日根据地的进攻，掠夺物资、残害民众。；蒙古地区伪军头目，属华北伪政权体系，与广西无直接关联。；蒙古伪军头目，长期在华北伪政权任职，其伪军系统曾配合日军南下作战。；原为热河地方军阀，1933年投靠日军，在张家口及察哈尔地区组建伪蒙古军，配合日军进攻抗日武装，参与建立伪蒙疆政权，镇压当地抗日力量。；原热河地方军阀，1933年投日，在赤城、沽源一带配合日军进攻抗日武装，后任伪蒙古军总司令，参与“治安肃正”扫荡，残害抗日军民。；内蒙古人，长期在伪蒙疆政权任职，其伪军曾配合日军在河南北部及豫西地区作战，间接影响南阳一带。；长期在内蒙古及华北地区为日军效力，其伪军活动范围涉及河南北部，配合日军对河南抗日根据地的进攻。；热河人，长期在伪蒙疆政权任职，其伪军活动范围涉及华北，包括河南北部边缘地区，配合日军对华北抗日力量进行扫荡。；原东北军骑兵，1933年投靠日军，任伪蒙古军总司令，后任伪蒙古联合自治政府副主席，其伪军活动主要在察哈尔、绥远一带，但作为伪蒙疆政权要员，与河南沦陷区伪政权有联系，间接影响河南包括南阳地区的伪化统治。；内蒙古人，长期在伪蒙疆政权任职，其伪军活动范围主要在察哈尔、绥远一带，与河南无直接关联，但作为华北伪军体系的一部分，与河南伪政权有联系。；热河人，长期在伪蒙疆政权任职，其伪军活动范围涉及华北，包括河南北部边缘地区，配合日军对抗日力量进行扫荡。；热河人，长期在伪蒙疆政权任职，其伪军活动范围涉及华北，包括河南北部边缘地区，配合日军作战。；热河人，长期在伪蒙疆政权任职，其伪军曾活动于河南北部及平汉铁路沿线，配合日军作战。；热河人，长期充当伪蒙军头目，其部曾配合日军在华北、河南北部等地作战，对河南部分地区有军事侵扰。；内蒙古卓索图盟人，在察哈尔、绥远一带活动；与湖南衡阳无直接关联。；原为东北军骑兵，后投靠日本，组建伪蒙古军，控制察哈尔、绥远一带，配合日军进攻陕西、绥远抗日根据地，参与掠夺资源、镇压抗日力量。；在内蒙古地区组建伪军，配合日军侵华，其活动范围与陕西北部接壤。；投靠日本，在内蒙古地区组建伪军，配合日军侵略华北，其活动范围与陕西北部邻近。；蒙古伪军头目，配合日军侵略华北，其活动范围与陕西宝鸡抗日后方形成对抗。；蒙疆伪军头目，其伪军活动范围与陕西北部邻近，对渭南、华州无直接活动但属陕西周边重要汉奸。；在内蒙古及华北地区组织伪军，配合日军进攻，其活动范围接近陕西北部，对陕北抗日根据地构成威胁。；在内蒙古投敌，组建伪蒙古军，配合日军侵略绥远、察哈尔等地。；在内蒙古地区组建伪军，配合日军侵略，其活动范围与陕西北部接壤，对陕西抗日后方有骚扰。；在内蒙古及华北地区组织伪军，配合日军进攻抗日根据地，其活动范围接近陕西。；投靠日本，组建伪蒙古军，配合日军在内蒙古及陕西周边地区进行侵略和统治。；在内蒙古、察哈尔、绥远一带组织伪军，配合日军侵略，其活动区域与陕西北部邻近。；投靠日本，在内蒙古地区建立伪军，配合日军侵略，其活动范围与陕西北部接近。；原东北军骑兵团长，投敌后任伪蒙古军总司令，配合日军在热河、察哈尔及东北西部地区作战，其伪军活动范围接近大庆、杜尔伯特地区。；内蒙古人，1933年投敌，任伪蒙古军总司令，活动于热河、察哈尔及黑龙江西部一带，配合日军进攻抗日武装，后任伪蒙古联合自治政府副主席。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7d46ea44a40a440cad7d8dbd132c4876','78198cf336e24d25a8e52cd58ddf4575',1933,'伪蒙古联盟自治政府主席、伪蒙疆联合自治政府主席','虽为察哈尔部贵族，但其伪政权势力覆盖乌兰察布地区，在四子王旗、达尔罕茂明安联合旗等地设立伪行政机构，为日军提供兵员和物资，协助日军统治蒙汉民众。；蒙古王公，长期策划“蒙古独立”，1936年成立伪蒙古军政府，1939年任伪蒙疆政府主席，其势力覆盖乌兰察布、兴和地区，为日军提供兵员和情报，镇压抗日活动。；蒙古王公，投靠日本，建立伪蒙政权，其势力范围包括乌兰察布盟及凉城一带，配合日军“治安肃正”，征粮抓丁，迫害抗日军民。；蒙古王公，策划内蒙古独立，投靠日本，建立伪蒙政权，其势力范围包括乌兰察布、商都地区，推行日伪统治，协助日军掠夺资源。；内蒙古王公贵族，积极投靠日本，策划内蒙古独立，在乌海、海勃湾一带推行日伪统治，组织伪蒙古军，协助日军控制河套及鄂尔多斯地区，对抗中国抗日武装。；内蒙古王公，策划内蒙古独立，1936年成立伪蒙古军政府，后与日军合作，在包头、九原地区推行殖民统治，建立伪政权机构，协助日军征兵征粮。；领导内蒙古西部（包括包头、石拐地区）的伪蒙政权，与日军合作，组织伪蒙古军，实施奴化教育，配合日军经济掠夺。；在内蒙古地区策划“蒙古自治运动”，投靠日本关东军，建立伪蒙政权，配合日军统治和掠夺内蒙古资源，组织伪蒙古军协助日军作战。；内蒙古王公，积极策划内蒙古独立，投靠日本，建立伪蒙疆政权，配合日军统治绥远、察哈尔等地，推行奴化政策。；蒙古王公，1936年在日军扶植下成立伪蒙古军政府，后任伪蒙疆政权首脑，在呼和浩特、托克托地区推行日伪统治，协助日军清乡、征粮、抓捕抗日人士。；蒙古王公，在日本扶持下建立伪蒙政权，首府设于归绥（今呼和浩特），在新城地区推行奴化教育，为日军提供兵员和物资，协助日军统治绥远。；蒙古王公，在日本扶植下建立伪蒙政权，其势力范围涵盖呼和浩特、清水河等地，推行奴化教育，为日军提供兵员和物资，协助日军清剿抗日武装。；内蒙古王公贵族，全面投靠日本，在呼和浩特（归绥）建立伪蒙疆政权，推行奴化教育，配合日军“治安强化”运动，迫害抗日军民，其伪政府机构曾驻于旧城（今玉泉区一带）。；内蒙古王公贵族，积极投靠日本，在呼和浩特（归绥）及周边地区建立伪政权，配合日军“以蒙治蒙”策略，组织伪蒙古军，协助日军清剿抗日武装，推行奴化教育。；蒙古王公，积极投靠日本，建立伪蒙政权，其势力范围涵盖绥西地区，支持日军在临河等地设立伪警察署和保甲制度，镇压抗日活动，强征粮草。；蒙古族王公，投靠日本后建立伪蒙政权，其行政管辖名义上包括五原地区，支持日军在绥西的军事行动，并推行奴化教育。；蒙古王公，积极投靠日本，策划内蒙古独立，建立伪蒙政权，其势力范围包括巴彦淖尔地区，支持日军对绥西的军事行动，推行奴化政策。；蒙古王公，与日军合作，在内蒙古地区建立伪政权，其势力范围涉及通辽一带，推行奴化教育，配合日军经济掠夺和军事统治。；在鄂尔多斯及内蒙古西部策划“蒙古独立”，投靠日本关东军，建立伪蒙政权，配合日军对伊克昭盟（今鄂尔多斯）进行殖民统治和军事镇压。；蒙古王公，1936年成立伪蒙古军政府，1939年任伪蒙疆联合自治政府主席，控制张家口及察哈尔地区，为日本殖民统治服务。；蒙古王公，策划内蒙古独立，1936年投日，建立伪蒙古军政府，后任伪蒙疆联合自治政府主席，管辖张家口、张北等地，推行日伪殖民政策。；察哈尔部蒙古王公，1933年策动“内蒙古自治运动”，后与日军合作，在张家口成立伪蒙疆政权，统治察北地区，配合日军“治安肃正”和物资掠夺。；蒙古王公，投靠日本，在张家口成立伪蒙疆政权，其势力范围包括赤城地区，推行奴化政策，协助日军镇压抗日力量。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5ce03206e2ad459c9a1e31d76063f2b4','b86083bd13c04af7ae64c9ee8b5ee802',1936,'伪蒙古军参谋长、伪蒙古联合自治政府政务院院长','参与策划伪蒙古军西进，在乌兰察布地区组织伪警察和保安队，镇压当地抗日游击队，强制推行“蒙疆”币和日伪法令。；参与伪蒙疆政权建设，在丰镇、乌兰察布等地组织伪行政机构，配合日军“治安强化”运动，迫害抗日军民。；参与伪蒙疆政权高层决策，在包头地区组织伪行政机构，协助日军清乡、征粮，迫害抗日军民。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('336521b96c4e4fd4ab7e339f8190edeb','77857f075ce44761869c5724589a4545',1937,'伪蒙古军第1师师长','率伪蒙古军驻扎乌兰察布南部（今卓资县、凉城县一带），配合日军进攻大青山抗日根据地，多次参与“清乡”行动，杀害抗日军民。；率伪蒙古军在乌兰察布、丰镇一带驻防，多次参与对八路军和游击队的“围剿”，烧杀抢掠，残害百姓。；率伪蒙古军在乌兰察布、商都地区驻防，参与围剿八路军大青山支队，残害抗日军民。；率伪蒙古军驻扎包头、九原地区，配合日军扫荡抗日游击队，多次参与围剿大青山抗日根据地，残害抗日军民。；率伪蒙古军驻扎包头地区，配合日军清乡、征粮，捕杀抗日地下工作者，参与“治安强化运动”。；率伪蒙古军驻防绥远地区，多次参与“扫荡”大青山抗日根据地，在呼和浩特回民区强征壮丁，迫害抗日家属。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('440f730df62c47c5b6208095ba0539a3','b002e65e42f14f4fbbadc0ebf8786c9e',1937,'伪蒙古军第2师师长','在乌兰察布东部（今商都县、化德县）驻防，协助日军封锁交通线，抓捕抗日地下工作者，向日军提供情报。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e5492bf47fec4a84a8e7f9cf13ef46d9','3a09ae0f7f294a118069ecfbec5ba35b',1937,'伪蒙古军第3师师长','活动于乌兰察布北部（今四子王旗、达茂旗），参与围剿八路军大青山支队，强征牧民马匹和粮食，迫害抗日家属。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fbb8f7d2b6a04ea5b40537a1269ef545','26647d4bb91f4086a567e1a461c53d38',1937,'伪蒙古军第4师师长','在乌兰察布中西部（今察右中旗、察右后旗）推行保甲制度，组织“自卫团”，协助日军破坏地下抗日组织。；投日后在呼和浩特周边活动，协助日军建立伪政权，参与抓捕和杀害抗日志士，强征粮食。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e067a20ac69e410d97b6e9d6b288ff1f','6eb9588d93e34ee29372e09eff64d5d0',1939,'伪蒙古联合自治政府兴蒙委员会副委员长','负责在乌兰察布地区推行奴化教育，强令学校使用日语和蒙奸教材，煽动民族分裂，为日军征兵征粮。','机构委员长(非国家首脑)','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('05545104175646bda741a56d6e63b853','2e047aa1489e418db87b0daa26378d58',NULL,'',NULL,'无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8cd29c28a5ef4dc6ba1e6d822db8399e','78198cf336e24d25a8e52cd58ddf4575',1933,'伪蒙古联合自治政府主席','蒙古王公，长期与日本关东军勾结，在乌兰察布地区推行“蒙古自治”，建立伪政权，为日军提供兵员和情报，协助统治当地。；蒙古王公，策划内蒙古独立，与日本关东军合作，在包头及周边推行伪蒙疆政权，为日军提供兵员和情报，协助统治占领区。；锡林郭勒盟苏尼特右旗札萨克郡王，抗战期间与日军合作，建立伪蒙疆政权，其统治范围包括绥远西部（含巴彦淖尔地区），推行伪蒙疆自治。；在日本扶持下建立伪蒙政权，其势力范围延伸至宁夏北部和贺兰山地区，配合日军对宁夏进行政治渗透和军事骚扰。；蒙古王公，在日军扶植下于张家口成立伪蒙古军政府及伪蒙疆联合委员会，推行奴化教育，协助日军掠夺资源，是蒙疆地区最高傀儡首领。；蒙古王公，在张家口成立伪蒙疆政权，与日军合作，推行殖民统治，为日军提供兵员和物资，镇压抗日活动。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8cd6b779c78b4aa99fc14259530cbd1c','ec26ab26d6bb4c4b8f8348f1bb125cd7',1938,'伪丰镇县县长','任伪丰镇县长期间，推行日伪苛政，强征粮税，抓捕抗日志士，协助日军建立保甲制度，镇压当地反抗。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a0041072b01f4cf4bfa2f6a0bd89cdd2','529eba01fd3844d2a4780badaf25cb50',1930,'伪绥西联军司令','原土匪出身，投日后在乌兰察布、丰镇一带活动，率伪军配合日军进攻大青山抗日根据地，劫掠民众，罪行累累。；原土匪出身，投日后任伪绥西联军司令，活动于乌兰察布南部及商都一带，配合日军袭击抗日游击队。；在乌兰察布及四子王旗地区为日军效力，参与围剿抗日游击队，残害百姓，充当日军帮凶。；在察哈尔右翼后旗及绥东地区为日军效力，组织伪军袭扰抗日武装，参与日军“清乡”行动，掠夺民间财物；伪军头目，虽主要活动于绥西，但其伪军系统与伪兴安地区伪军有协同，间接涉及内蒙古东部，包括兴安、科尔沁右翼前旗一带的治安作战。；在内蒙古西部及呼伦贝尔南部活动，率伪军配合日军进攻抗日武装，残害百姓；在内蒙古西部投靠日军，组织伪军，虽主要活动于绥远，但属于内蒙古范围内有记载的汉奸。；原为绥远地方军阀，投日后任伪绥西联军司令，在呼和浩特西部及回民聚居区设卡收税，配合日军清乡，杀害抗日军民。；绥远人，组织伪军配合日军在绥远、山西北部等地活动，参与日军对晋绥抗日根据地的进攻。；率伪军活动于晋北、绥远交界包括右玉附近，协助日军进攻抗日武装。；在绥远、陕西北部一带组织伪军，配合日军侵扰陕西边境。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('97664d19246a431aa6a39122c6175771','47cac7a73af140d39ff53133e8cfe760',1937,'伪东亚同盟军总司令','原国民党将领，投敌后在乌兰察布地区组织伪军，参与对抗日武装的“讨伐”，后因内部矛盾被日军处决。；投日后任伪东亚同盟军总司令，在内蒙古西部及绥远地区配合日军作战，围剿抗日武装。；原东北军将领，叛变投日后在包头地区组织伪军，参与日军对河套地区的扫荡，后因内部矛盾被日军处决。；原国民党将领，叛变投日后在绥远地区（含包头）组织伪军，多次进攻八路军大青山支队，制造多起惨案。；原东北军骑兵师长，后投敌，任伪东亚同盟军总司令，在包头地区参与日军对绥西的进攻，后因内部矛盾被日军处决。；原国民党军官，投日后在绥远地区组织伪军，配合日军围剿八路军大青山支队。；原东北军将领，投敌后任伪东亚同盟军总司令，在绥远地区协助日军进攻抗日武装，曾率部在呼和浩特周边制造多起惨案。；原为国民党将领，后叛变投日，在绥远（含清水河一带）组织伪军，多次进犯抗日根据地，杀害抗日干部和群众。；在绥远、陕西一带活动，后投靠日军，组织伪军，对陕西地区有直接威胁。；投靠日本，在华北地区组建伪军，配合日军作战，其活动范围涉及陕西周边。；原东北军将领，投敌后任伪军头目，在华北活动，与陕西宝鸡抗日后方有间接关联。；原东北军将领，后投敌组织伪军，活动于华北、西北边缘，与陕西渭南地区有间接联系。；原为抗日将领，后投敌，在华北、西北组织伪军，其活动范围涉及陕西邻近地区。；在华北组织伪军，后活动于绥远一带，与陕西抗日力量有间接对抗。；在华北、西北地区组织伪军，协助日军作战。；投靠日本，在华北及陕西周边地区组建伪军配合日军行动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('51961fc1ee974a0d8eac37cfd3b5ce00','09e65a7dbae748caa1181ab2c8844755',1938,'伪蒙古军第2师师长','率部驻防丰镇周边，多次袭击抗日游击队，杀害抗日干部，强征民夫修筑日军工事。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7e284a206e82457a976230e66fa01693','d566dc108e3e455eb9267bb5683e9461',1939,'伪乌兰察布盟盟长','投靠日伪，任伪盟长期间，推行奴化教育，组织伪警察镇压抗日活动，为日军提供物资和劳役。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('825e6fe6680d4e8aba5e799ce4f01cd6','12a8b4767b1e4a989997caabbb41d83a',1939,'伪晋北自治政府参议（后投敌）','原晋军将领，被俘后变节，在乌兰察布地区协助日伪收编散兵，参与“清乡”行动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9676abfc22054064b31b8684933761be','529eba01fd3844d2a4780badaf25cb50',1937,'伪绥西自治联军总司令、伪东亚同盟军总司令','原绥远地方土匪/军阀，1937年投日，在乌兰察布、兴和及绥远地区组织伪军，配合日军扫荡抗日根据地，残害百姓，后任伪绥西联军司令。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dee43fe1d7b1444ca9a563b614a0e3dd','47cac7a73af140d39ff53133e8cfe760',1938,'伪东亚同盟军副总司令','原东北军将领，后投靠日军，在绥东（含兴和、乌兰察布）一带协助日军围剿八路军游击队，参与“治安肃正”行动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3f22986aca5c455cacea7447fa142cf3','fc69c98db6304cccbd2075c295573b10',1936,'伪蒙古军第1军军长','蒙古族上层，投靠德王和日军，率伪蒙古军在乌兰察布北部及兴和地区驻防，协助日军镇压抗日民众，征收粮草。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('64e36bd0562e4bf7a1b732b3438b634e','2659053ec01b4b489c2d157baa24ee77',1937,'伪蒙古军第2军军长','伪蒙古军高级军官，活动于绥远东部（含兴和、商都、化德一带），配合日军进攻大青山抗日游击队，参与“清乡”屠杀。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('28ced0215abe4d66831761d84740bbc9','77857f075ce44761869c5724589a4545',1938,'伪蒙古军第3军军长','伪蒙古军将领，在乌兰察布地区驻防，协助日军维持殖民秩序，抓捕抗日地下工作者，参与经济掠夺。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('74b3a10f1fd14514af01573bb17a49c3','26647d4bb91f4086a567e1a461c53d38',1939,'伪蒙古军第4军军长','伪蒙古军高级指挥官，活动于乌兰察布南部及兴和一带，多次率部袭击八路军大青山支队，破坏抗日政权。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f03523d7b58a4efcabeccc39438294a4','3a09ae0f7f294a118069ecfbec5ba35b',1939,'伪蒙古军第5军军长','伪蒙古军将领，在乌兰察布、兴和地区参与“扫荡”，强征民夫修筑公路和碉堡，配合日军推行“保甲制”。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5538f26d00284264a4878dbad67a7ffe','a4a0b90fb3c141f8939b220dafdfb71f',1939,'伪蒙疆政府兴和县县长','在兴和县任伪县长期间，为日军征粮派款，组织伪警察镇压抗日群众，协助日军建立情报网。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5b7fd490d59f417c911105b786a7f9fa','2e047aa1489e418db87b0daa26378d58',1940,'伪绥东保安司令（后投日）','原国民党军官，1940年投日，在乌兰察布东部（兴和、丰镇）组织伪保安队，配合日军“蚕食”抗日根据地。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('02f425aa674b4b9f8c80c98864ba8d07','9fa33aff764242e9a9cba71f35e1a08d',1941,'伪兴和县警察署署长','在兴和县任伪警察署长，抓捕抗日军民，严刑逼供，直接参与多起屠杀事件。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0e90297966514bba9a5107e0c3a574b2','6687a4d3a75b4c3099f7cb5005501a4e',1940,'伪乌兰察布盟公署参事','在乌兰察布盟伪政权中负责“宣抚”工作，为日军宣传“大东亚共荣”，协助推行奴化教育。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2d09486a6e2a468b9a0f443fe146b228','12a8b4767b1e4a989997caabbb41d83a',1939,'伪晋北政厅顾问（兼绥东事务）','原晋军将领，投日后任伪职，参与对乌兰察布、兴和地区的军事“讨伐”和物资掠夺。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8a254e93c68e43ce9ecc1e19c5b589dc','87e5121f4b3b403b908a4c2705738cd3',1941,'伪蒙古军第6师师长','率伪蒙古军第6师驻防兴和、尚义一带，多次袭击八路军游击队，杀害抗日干部和群众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b30c98fafa934faa8030fc3ced602a68','b86083bd13c04af7ae64c9ee8b5ee802',1939,'伪蒙疆政府内政部长','作为伪蒙疆高层，参与制定对乌兰察布、兴和地区的“治安强化”政策，支持日军“三光”作战。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('83c82a0b000645f69bd9bbe22c89932a','5f82d23ccd2e45fd9e59f76c92bcc9ad',1933,'伪蒙古军总司令、伪蒙古联盟自治政府副主席','原为热河土匪，后投靠日军，任伪蒙古军总司令，参与侵占绥东（含凉城）地区，协助日军镇压抗日力量，推行殖民统治。；原为热河土匪，后投靠日军，任伪蒙古军总司令，在商都、乌兰察布一带配合日军扫荡抗日武装，镇压蒙汉民众，参与建立伪蒙政权。；原为东北军军官，后投靠日军，在内蒙古东部及包头、石拐地区协助日军建立伪蒙古军，参与镇压抗日力量，推行殖民统治。；原东北军将领，叛国投日后任伪蒙古军总司令，率伪军在察哈尔、绥远及呼伦贝尔周边地区配合日军进攻抗日武装，镇压蒙汉民众。；原东北军将领，投靠日本后组建伪蒙古军，在绥远（今呼和浩特）及新城地区协助日军镇压抗日力量，参与“治安肃正”行动，残害当地民众。；原为东北军军官，后投靠日本关东军，在内蒙古东部及呼和浩特、清水河一带组织伪蒙古军，协助日军镇压抗日力量，参与“治安肃正”行动，残害当地民众。；原东北军军官，后投靠日本关东军，组建伪蒙古军，参与侵占察哈尔、绥远（今呼和浩特地区），协助日军镇压抗日力量，并在玉泉区（旧归化城）设立伪政权机构。；原为东北军军官，后投靠日本关东军，在内蒙古东部及呼和浩特、赛罕地区协助日军建立伪蒙古军，参与镇压抗日力量，推行“蒙疆自治”政策，为日军提供兵员和情报。；原为东北军军官，后投靠日本关东军，参与组建伪蒙古军，多次率部进犯绥西地区，协助日军镇压抗日力量，是蒙奸头目之一。；原热河省军阀，1933年投日，在赤峰、宁城一带协助日军镇压抗日武装，组建伪蒙古军，参与对热河地区的殖民统治和“清乡”行动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('212ec6d302144a579828be89ae0e3307','b86083bd13c04af7ae64c9ee8b5ee802',1936,'伪蒙古军政府参谋部长、伪蒙疆政府政务院院长','参与伪蒙政权决策，协助日军在乌兰察布、凉城等地推行保甲制度，组织伪警察镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('adabd3b1abd9451bb6c931c3657f8895','529eba01fd3844d2a4780badaf25cb50',1937,'伪绥西联军总司令、伪东亚同盟军总司令','绥远土匪出身，投日后率伪军多次进犯凉城、蛮汉山一带，配合日军扫荡八路军大青山支队，烧杀抢掠。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c1bf3cf3062c4738bb3c8b10ae17c052','09e65a7dbae748caa1181ab2c8844755',1938,'伪凉城县县长','任伪凉城县长期间，为日军征粮派款，组织伪警察抓捕抗日地下人员，破坏中共凉城抗日根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('64b2966aa3c44c409adbf0a482a7ce7d','12a8b4767b1e4a989997caabbb41d83a',1939,'伪晋绥军（投日部队）将领（注：其投日行为存争议，但曾与日军合作）','原晋绥军将领，一度与日军合作，其部队活动于绥南（含凉城），参与对八路军游击区的“围剿”。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7d239e17a36c4da9b9dfe95bc4eba70a','47cac7a73af140d39ff53133e8cfe760',1938,'伪东亚同盟军副司令','原东北军将领，投日后在绥东、凉城一带收编土匪，配合日军进攻大青山抗日游击根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3790bd348d124c7f90b95a5b2412aad6','7ff87fe9d1674c1b87d740313f09bffa',1940,'伪凉城县保安队队长','率伪保安队多次袭击凉城乡村抗日政权，杀害抗日干部和群众，抢夺物资。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a430db961c4d41fc942e875565baaa7f','8f4c6a82abd7490ab754fe15d2224dd0',1937,'伪蒙古军师长（驻乌兰察布）','率伪蒙古军驻防乌兰察布南部，参与对凉城、卓资山等地抗日武装的“清剿”。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1a682ed1ca5c4d108d5f08faf8e41335','ac4503acc4ce4970a71743948ebfc732',1938,'伪绥远省防共自治军头目','原国民党军官，投日后在凉城、和林格尔一带组织伪军，协助日军建立据点，破坏抗日交通线。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6c22042974f34e3688d200cbf5cfd808','78198cf336e24d25a8e52cd58ddf4575',1933,'蒙疆联合自治政府主席','在化德（当时称嘉卜寺）建立伪蒙古军政府，后任蒙疆联合自治政府主席，积极投靠日本，组织伪蒙古军配合日军进攻绥远等地。；在四子王旗及乌兰察布地区推行亲日政策，组织蒙古军配合日军侵略，建立伪蒙疆政权，分裂中国领土。；在察哈尔右翼后旗及周边地区推行日本殖民政策，组织伪蒙疆政权，协助日军镇压抗日力量，强征劳工和物资；在察哈尔、绥远（含今乌兰察布地区）组织蒙古自治运动，投靠日本，建立蒙疆政权，配合日军统治与掠夺资源。；在乌兰浩特及兴安盟地区推行亲日政策，组建蒙疆政权，配合日军统治内蒙古东部地区，镇压抗日力量。；在内蒙古地区策划‘蒙古自治运动’，投靠日本，建立蒙疆政权，配合日军统治内蒙古中西部，包括呼伦贝尔周边地区；在内蒙古地区策划‘蒙古自治运动’，投靠日本，建立蒙疆政权，配合日军统治绥远（含今巴彦淖尔地区），推行奴化政策。；在锡林郭勒盟（含今二连浩特地区）发起‘蒙古自治运动’，后投靠日本，建立蒙疆政权，配合日军统治内蒙古地区。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('76f42b525b454555b6115bb9a4aabf44','5f82d23ccd2e45fd9e59f76c92bcc9ad',1933,'伪蒙古军总司令、蒙疆联合自治政府副主席','原东北军将领，后投日，在化德一带协助德王组建伪蒙古军，多次率部进攻察哈尔、绥远抗日武装，镇压抗日力量。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5763b028a374455493783f463cb147c4','b86083bd13c04af7ae64c9ee8b5ee802',1936,'伪蒙古军政府参谋部长、蒙疆联合自治政府总务委员','参与策划伪蒙古军政府成立，在化德地区协助日伪政权推行殖民统治，参与“防共”和镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b35d6718ded546f48b69a3e6d9282888','993cd83aa8c54ff38e0622e1de731309',1936,'伪蒙古军第1军军长','率伪蒙古军驻扎化德、商都一带，配合日军“扫荡”抗日游击队，残害当地民众。；率伪蒙古军驻防绥西地区，多次配合日军扫荡包头、固阳、白云鄂博周边抗日游击队，掠夺牲畜和矿产。；原内蒙古地方武装头目，投日后率伪蒙古军驻扎绥远地区，多次配合日军扫荡大青山抗日游击根据地，在归化城（玉泉区）一带抓捕抗日人员。；率伪蒙古军驻扎张家口地区，多次参与对八路军和抗日游击队的扫荡，残害抗日军民。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('49638b62e4ee41bbaa39dfac1c1713f1','77857f075ce44761869c5724589a4545',1936,'伪蒙古军第2军军长','在乌兰察布及化德地区指挥伪军参与多次进攻八路军和国民党抗日部队的行动。；在包头、萨拉齐一带驻防，协助日军清剿抗日力量，参与对白云鄂博矿区劳工的军事管制。；投靠日军后驻防绥西及归绥周边，参与镇压民众反抗，协助日军强征粮草，其部队曾在玉泉区（旧城）设卡盘查，迫害无辜百姓。；在万全、怀安等地配合日军作战，镇压民众反抗，参与建立伪保甲制度。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3c2079751c4d4c77a84171cd96d4530b','3a09ae0f7f294a118069ecfbec5ba35b',1936,'伪蒙古军第3军军长','率部在化德、张北一带协助日军维持治安，镇压抗日民众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('93ab176b912e47a08254d200e925fe43','2659053ec01b4b489c2d157baa24ee77',1936,'伪蒙古军第4军军长','在乌兰察布地区活动，参与围剿抗日武装，为日军提供情报。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('47c7d84fcbd24fa3ba43389484737f4f','26647d4bb91f4086a567e1a461c53d38',1936,'伪蒙古军第5军军长','在化德及周边地区驻防，配合日军“清乡”，迫害抗日家属。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('612ccc6044ef4f6e99f288666a220e59','a4a0b90fb3c141f8939b220dafdfb71f',1938,'伪蒙疆政府政务院院长秘书','在化德参与伪政权行政事务，协助推行日伪奴化教育。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d93a30e2f6ea435683702a27d709fb8c','4ee9f09877a14175b82dc79fea5dcee8',1939,'伪蒙疆联合自治政府司法部长','参与制定镇压抗日活动的伪法律，在乌兰察布地区设立伪法庭迫害爱国人士。','省部级/大军区级要员','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0d85cbb9e0194ff58541a5fc9a90d68d','c94f058ddf0448068e37a5d4ac1c1a8d',1941,'伪蒙疆政府兴蒙委员会委员长','在化德地区推行“蒙地奉上”政策，为日军征粮派夫，压榨当地牧民。','机构委员长(非国家首脑)','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b9dd569136ab4f35a9b47f0b1b95f1f9','398386654d2a48f4adf3224253a66ebb',1937,'伪蒙疆政府察哈尔盟盟长','管辖化德、商都等旗县，积极执行日军“治安肃正”计划，捕杀抗日分子。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b7252b05e375481a88227580918be4dc','dd8c71d66e0841399bb26d229b5ac4ef',1937,'伪蒙疆政府察哈尔盟副盟长','协助日军在乌兰察布北部地区建立伪警察机构，参与“大东亚圣战”宣传。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('06ca88b05bc24271a95ac40186f8bbc4','4f4f30ff0aad4326bfbfbd1371d7f371',1937,'伪化德县县长','在化德县内推行日伪统治，强征劳工，为日军修建军事设施。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('77f8ab4e7c754ed390e864014c360c6b','1525e16ff20b436b8d968f84ebaaac6d',1938,'伪商都县县长（化德邻近地区）','在乌兰察布东部地区配合日军“扫荡”，搜刮民财，迫害抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('807b9278bce243428caceee579ed153f','b2c6142dabeb4ac78a0a05ad8abc5952',1937,'伪蒙古军第6师师长','率部在化德、镶黄旗一带活动，多次袭击八路军游击队。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1e0a0d0ec79a4fbe8b95fa7d0fa6389e','593d6fcbfc5441379dd2cfbafa1bb50e',1938,'伪蒙古军第7师师长','在乌兰察布地区参与“铁壁合围”行动，围剿抗日武装。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9b14645e171e4fa08f74a21dbc5fbfa8','68ac65da02354ebfaa344c965ac9b439',1940,'伪蒙疆政府参议','在化德参与伪政权决策，为日军提供蒙古族地区情报。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('411c53db2bbe44199918d928c46d4c26','8050c807ef7e4052bc227bfc45d10f9d',1939,'伪化德保安队队长','率保安队协助日军维持化德治安，抓捕抗日地下工作者。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('34839b68e010413d98b48a28ae9956c3','194f9301b50649e8b6a5002dc017ad7b',1941,'伪乌兰察布盟盟长','管辖乌兰察布地区，推行日伪“保甲制度”，强征青年加入伪军。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('71b35115c0bb45b7b116e8c960529646','78198cf336e24d25a8e52cd58ddf4575',1933,'伪蒙疆联合自治政府主席','蒙古族王公，组织伪蒙疆政权，与日军合作，在乌兰察布、卓资一带推行殖民统治，征粮征兵，协助日军清剿抗日武装。；蒙古王公，策划内蒙古独立，投靠日本，建立伪蒙疆政权，其势力范围包括乌海周边地区，协助日军统治和殖民掠夺。；在内蒙古地区组织伪蒙政权，与日本关东军合作，推行“蒙疆自治”，协助日军统治内蒙古中西部，但未直接管辖兴安、阿尔山地区，主要活动于锡林郭勒、乌兰察布等地。；蒙古王公，策划内蒙古独立，与日军合作成立伪蒙疆政权，管辖包括包头在内的绥远地区，推行奴化教育，协助日军统治。；蒙古王公，与日军合作建立伪蒙疆政权，其势力范围覆盖包头、东河地区，推行奴化教育，为日军提供情报和物资支持。；蒙古王公，与日军合作建立伪蒙疆政权，其势力范围包括包头、固阳等地，推行日伪统治，征粮派款，协助日军清剿抗日游击队。；虽为察哈尔部贵族，但长期在土默特右旗及包头地区活动，与日军合作，建立伪蒙疆政权，推行“蒙独”分裂活动，为日军提供兵源和情报。；蒙古王公，日本扶植的蒙疆政权首脑，其势力范围包括包头、昆都仑地区，推行日伪统治，协助日军镇压抗日力量。；蒙古王公，在日本扶植下成立伪蒙疆政权，管辖包括包头、白云鄂博在内的绥远地区，推行奴化教育，协助日军控制矿产和交通线。；蒙古王公，组织伪蒙疆政权，与日军合作，在内蒙古地区推行殖民统治，其势力范围曾延伸至呼伦贝尔西部边缘，配合日军“治安肃正”。；蒙古王公，在日本扶植下成立伪蒙疆政权，首府驻张家口，但势力范围涵盖呼和浩特及绥远地区，推行亲日政策，协助日军统治。；蒙古王公，策划内蒙古独立，后投靠日本，建立伪蒙疆政权，在呼和浩特（归绥）设立伪政府机构，推行奴化教育，协助日军掠夺资源。；蒙古王公，与日本合作建立伪蒙疆政权，其势力范围覆盖土默特左旗，推行奴化教育，为日军提供情报和兵源。；蒙古族贵族，与日本合作建立“蒙疆政权”，其势力范围包括乌拉特前旗一带，推行奴化教育，为日军提供兵员和物资，协助日军控制河套地区。；虽主要活动于锡林郭勒，但其伪蒙疆政权势力延伸至奈曼旗、通辽一带，支持伪军和特务机构在该地区镇压抗日活动。；蒙古王公，投日建立伪蒙疆政权，其势力范围涉及河北北部（张家口、承德一带），配合日军控制长城沿线。；蒙古族王公，投靠日本，建立伪蒙疆政权，其势力范围包括大同、浑源等晋北地区，协助日军统治和掠夺资源。；在日本扶植下建立伪蒙疆政权，管辖包括张家口、下花园在内的察哈尔地区，推行奴化教育，配合日军经济掠夺和军事镇压。；领导伪蒙疆政权，管辖张家口、宣化等地，配合日军推行殖民统治，建立伪军和警察机构，迫害抗日民众。；在日军扶植下成立伪蒙疆政权，管辖张家口、崇礼等地，推行奴化教育，配合日军经济掠夺和军事镇压。；蒙古王公，与日军合作在张家口成立伪蒙疆政府，管辖包括康保在内的察哈尔地区，推行奴化教育，为日军提供兵员和物资。；蒙古族王公，在日本扶植下成立伪蒙疆政权，总部设于张家口，积极与日军合作，推行奴化教育，为日军提供兵源和物资。；蒙古王公，1936年在日军扶植下成立伪蒙古军政府，后任伪蒙疆联合自治政府主席，管辖张家口及怀安地区，推行奴化教育，协助日军掠夺资源，镇压抗日力量。；蒙古王公，1936年投日，在张家口成立伪蒙疆政府，管辖察哈尔（含怀来）等地，推行奴化教育，为日军提供兵员和物资，镇压抗日活动。；蒙古王公，在日本扶植下于张家口成立伪蒙疆政府，管辖察哈尔等地，在桥东地区设立伪机构，配合日军经济掠夺和殖民统治。；蒙古王公，在日本扶植下成立伪蒙疆政权，以张家口为重要活动中心，配合日军统治察哈尔、绥远等地，提供兵员和物资，协助日军清剿抗日武装。；在张家口建立伪蒙疆政权，与日军合作，推行奴化教育，为日军提供兵员和物资，是涿鹿地区伪政权的最高象征。；蒙古王公，在日军扶植下建立伪蒙疆政权，管辖张家口、大同、归绥等地，配合日军推行殖民统治，组织伪军协助日军作战。；蒙古王公，在日军扶植下成立伪蒙疆政权，管辖张家口及周边地区，推行奴化政策，协助日军统治。；与日本合作，其势力曾延伸至河北北部，间接影响秦皇岛地区','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cedf92857bef4df78f9436313b0ad8b6','b86083bd13c04af7ae64c9ee8b5ee802',1937,'伪蒙疆政府政务院院长','德王亲信，参与伪蒙疆政府行政事务，在乌兰察布地区推行日伪政策，强征劳工，压迫民众。；德王亲信，参与伪蒙疆政权运作，在乌海及鄂尔多斯地区推行日伪政策，征粮派款，协助日军维持治安。；曾任伪蒙疆政府高级官员，在包头地区协助日军推行殖民政策，管理行政事务，镇压抗日活动。；德王亲信，参与伪蒙疆政权行政运作，在包头地区推行日伪法令，征派劳役开采白云鄂博铁矿资源。；参与伪蒙疆政权高层决策，在呼和浩特地区推行奴化教育和经济掠夺，协助日军维持殖民统治。；曾任伪蒙疆联合自治政府政务院长，在呼和浩特地区推行日伪法令，组织保甲制度，镇压抗日活动，协助日军征粮征兵。；参与德王伪政权，负责行政事务，在锡林郭勒盟推行日本殖民政策。；原国民党蒙藏委员会官员，投日后任伪蒙疆政府政务院院长，推行日伪法令，协助日本对内蒙古西部进行殖民统治。；长期在张家口担任伪蒙疆政府高级职务，负责行政事务，配合日军实施治安强化运动，迫害抗日军民。；协助德王管理伪蒙疆政权，在张家口地区实施日伪法令，强征劳工，配合日军“扫荡”抗日根据地。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bde2aa7ff89147448c747316d65aa91a','529eba01fd3844d2a4780badaf25cb50',1937,'伪绥西自治联军总司令','绥远土匪出身，投日后任伪绥西自治联军总司令，活动于绥远中东部（含卓资、乌兰察布），多次配合日军进攻抗日根据地，残害百姓。；原土匪出身，投日后在绥远西部（含今乌海、海勃湾地区）组织伪军，多次进攻抗日根据地，协助日军控制黄河渡口，为日军运输军需。；在日军指使下组建伪绥西自治联军，活动于绥远西部（含今乌海、海南一带），劫掠民众，协助日军控制河套地区。；原土匪出身，投日后在包头、五原一带组建伪军，多次配合日军进攻傅作义部抗日军队，残害百姓。；原土匪武装头目，投日后在包头、九原一带组建伪军，配合日军进攻绥西抗日力量，劫掠百姓，曾参与围攻大青山支队。；土匪出身，投日后在包头、五原一带活动，组建伪绥西自治联军，配合日军进攻河套地区，烧杀抢掠。；原土匪武装头目，投日后任伪绥西自治联军总司令，活动于包头、昆都仑一带，多次配合日军扫荡抗日根据地，残害百姓。；原土匪出身，投日后在包头以西地区组建伪军，多次袭击抗日武装，为日军勘探白云鄂博矿提供情报和护卫。；原为土匪头目，后投靠日军，在包头、石拐及绥西地区组织伪军，协助日军扫荡抗日根据地，残害百姓。；原土匪武装头目，投日后在包头、青山一带活动，率伪军配合日军扫荡大青山抗日游击根据地，残害百姓。；在绥远（含今呼伦贝尔部分相关区域）组织伪军，充当日军“以华制华”工具，多次进犯抗日根据地，劫掠百姓。；原土匪出身，投日后在绥远西部组织伪军，进攻大青山抗日根据地，烧杀抢掠。；原土匪出身，抗战期间投靠日军，在托克托、呼和浩特一带组织伪军，多次配合日军扫荡大青山抗日根据地，残害百姓，抢劫物资。；原土匪出身，投日后在绥远（含新城）地区活动，率伪军配合日军进攻大青山抗日根据地，烧杀抢掠。；原土匪头目，投日后在绥远（含武川）一带活动，率伪军袭击八路军大青山支队，残害地方干部，后因内部矛盾被日军弃用。；原为土匪武装头目，后投靠日军，在清水河、托克托及呼和浩特南部地区活动，配合日军进攻八路军大青山抗日根据地，烧杀抢掠，破坏抗日组织。；原绥远地方土匪武装头目，投日后编为伪军，活动于归绥（今呼和浩特）及绥西地区，多次进攻抗日游击队，在玉泉区周边村庄烧杀抢掠。；原为土匪武装头目，投日后在呼和浩特、赛罕地区活动，协助日军控制交通线，袭击抗日武装，掠夺民间财物，充当日军“以华制华”工具。；在乌拉特中旗及河套地区为日军效力，组织伪军袭扰抗日部队，破坏中共地下组织，残害抗日军民。；在绥西（含巴彦淖尔地区）组织伪军，配合日军进攻河套抗日根据地，劫掠百姓，破坏抗战。；在绥西地区组织伪军，活动于包头、五原、临河及鄂尔多斯北部一带，配合日军扫荡抗日根据地，残害百姓。；率伪军多次进犯平鲁、朔县一带，配合日军“治安肃正”，抓捕抗日干部。；原为土匪出身，后投日，在晋北（含朔州、怀仁地区）配合日军扫荡，劫掠百姓，袭击八路军游击队，为日军提供情报。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0b68dc85f1d740eb8a2ce22864b4583b','09e65a7dbae748caa1181ab2c8844755',1938,'伪绥东保安队队长','原为地方民团头目，投日后任伪绥东保安队队长，在卓资、旗下营一带为日军搜集情报，抓捕抗日人员，欺压乡民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ad251d4c23d243018d19b21fa4ffcec3','9fa33aff764242e9a9cba71f35e1a08d',1939,'伪卓资县维持会会长','日军占领卓资后出任维持会长，为日军征粮派款，组织伪保甲制度，协助日军“扫荡”周边村庄。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('91eac374e7214cd481f3c40eb747328f','0c6efd582776435ba8c9b1044dc5a75f',1940,'伪乌兰察布盟警察署署长','投靠日伪，任乌兰察布盟警察署长，参与镇压抗日活动，逮捕并杀害多名抗日志士，强征民夫修筑工事。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9a089e3613a347169d7cdef82743d725','d1a8778b8ca043688fd9fe9e33865efc',1937,'伪绥东宣抚使','原为国民党地方官员，投日后任伪绥东宣抚使，在卓资、集宁一带进行亲日宣传，瓦解民众抗日意志，协助日军建立伪政权。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ecaea5ec033e43f7aa5a0ed2a458f844','b8a63ee7224043ba8d5b34e6c030cce4',1938,'伪蒙古军第7师师长','率伪蒙古军驻防乌兰察布南部，多次参与对八路军大青山支队的围剿，在卓资地区烧杀抢掠。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('92e775d4972c434aa5cc4c04bface09e','77857f075ce44761869c5724589a4545',1937,'伪蒙古军第9师师长','在乌兰察布、卓资一带驻防，配合日军“铁壁合围”战术，袭击抗日游击队，强征马匹和粮食。；率伪蒙古军在集宁、丰镇一带驻防，配合日军进攻八路军大青山支队，参与“扫荡”和屠杀。；原地方武装头目，投日后率部驻防内蒙古西部，在乌海、海勃湾及周边地区配合日军扫荡抗日游击队，残害百姓，抢掠物资。；土默特左旗人，率伪军多次扫荡大青山抗日根据地，烧毁村庄，杀害八路军伤员和群众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b6b7c9a31b14463db97078c44b3ffd9d','b86083bd13c04af7ae64c9ee8b5ee802',1937,'伪蒙古联盟自治政府总务部长、伪蒙疆政府内政部长','德王亲信，参与伪蒙政权运作，在乌兰察布、商都等地推行保甲制度，协助日军征粮派款，镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aa58b4b5ad68426bbeb34b0494745f5f','c94f058ddf0448068e37a5d4ac1c1a8d',1936,'伪蒙古军副司令、伪蒙疆政府参议','原察哈尔蒙古族上层，投日后任伪蒙古军副司令，在商都、化德一带组织伪军，配合日军进攻抗日根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b7cba72020f948b2ac5f04cc27523e85','b002e65e42f14f4fbbadc0ebf8786c9e',1937,'伪商都县县长','投靠日军，任商都县伪县长，推行日伪法令，强征民夫，搜刮粮食，镇压当地抗日力量。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('517643487fc54d87a3886ddc1237e242','9fa33aff764242e9a9cba71f35e1a08d',1938,'伪商都县警察署署长','充当日军爪牙，在商都地区抓捕抗日志士，破坏地下组织，协助日军进行“清乡”行动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8360a54bb70049b49fed6ffe3caeb750','09e65a7dbae748caa1181ab2c8844755',1938,'伪蒙古军第5师师长','率伪军驻扎商都、化德地区，参与日军“治安强化”运动，屠杀抗日群众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('00e8a63cef5d4810bc7e8573ab2ba906','12a8b4767b1e4a989997caabbb41d83a',1939,'伪晋北自治政府顾问（后投日）','原国民党将领，后投靠日军，在乌兰察布东部地区协助日军建立伪政权，参与对抗日武装的围剿。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('75da069427b441538ba6dc933aaa82e6','77857f075ce44761869c5724589a4545',1936,'伪蒙古军师长','在四子王旗一带驻防，配合日军清乡，抓捕抗日人员，强征民夫和物资。；任伪蒙古军师长，驻防内蒙古西部地区，配合日军“扫荡”抗日游击队，残害当地百姓。；土默特右旗人，任伪蒙古军师长，率部参与日军对绥西地区的“扫荡”，杀害抗日军民，掠夺物资。；率伪蒙古军驻扎武川地区，多次配合日军‘清乡’，烧杀抢掠，强征民夫修筑工事，破坏大青山抗日游击根据地。；伪蒙古军高级将领，率部在绥西地区活动，配合日军进攻五原、临河等地，参与伪政权的地方统治。；率伪蒙古军部队在绥西及鄂尔多斯北部活动，配合日军进攻抗日根据地，执行烧杀抢掠。；在张家口塞北地区驻防，参与日军“治安肃正”行动，围剿抗日武装。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9d25c0d89b344a6b836f618b2789f196','3a09ae0f7f294a118069ecfbec5ba35b',1937,'伪四子王旗札萨克（旗长）','投靠日伪政权，在旗内推行奴化教育，强迫牧民献粮献畜，协助日军维持殖民统治。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('80d5235e06d54fe988e7953750660d85','c94f058ddf0448068e37a5d4ac1c1a8d',1939,'伪蒙疆政府参议','参与伪蒙疆政权活动，在乌兰察布地区为日军搜集情报，破坏抗日地下组织。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('86f51dff68264928b91243d04977ece3','993cd83aa8c54ff38e0622e1de731309',1940,'伪蒙古军团长','在四子王旗边境地区袭击抗日武装，杀害抗日军民，抢劫牲畜和财物。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5472483495544a93a32360ae7d02c22e','5f82d23ccd2e45fd9e59f76c92bcc9ad',1933,'伪蒙古军总司令、伪察哈尔盟盟长','热河阜新人，早年为土匪，后投靠日军。1933年任伪察哈尔盟盟长，1936年任伪蒙古军总司令，率部配合日军进攻绥远、察哈尔等地，其势力范围覆盖乌兰察布及察哈尔右翼各旗。1945年抗战胜利后被俘。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('158b5df4a6dd440eae806e4325ab9248','78198cf336e24d25a8e52cd58ddf4575',1936,'伪蒙疆联合自治政府主席、伪蒙古联盟自治政府主席','锡林郭勒盟苏尼特右旗人，蒙古王公。1936年成立伪蒙古军政府，1937年任伪蒙古联盟自治政府主席，1939年任伪蒙疆联合自治政府主席，统治范围包括乌兰察布盟、察哈尔盟等地，察哈尔右翼中旗在其伪政权管辖之下。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('df66bef539084a82ae1dc20cc44bbf9f','c94f058ddf0448068e37a5d4ac1c1a8d',1937,'伪蒙古联盟自治政府最高法院院长、伪蒙疆联合自治政府参议','察哈尔部蒙古贵族，曾任伪蒙古联盟自治政府最高法院院长，后任伪蒙疆联合自治政府参议，参与伪蒙疆政权对察哈尔右翼各旗的统治。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('095dbed6e3574817bf893ecbbfa490a0','dd8c71d66e0841399bb26d229b5ac4ef',1936,'伪察哈尔盟盟长、伪蒙疆联合自治政府参议','察哈尔蒙古贵族，1936年任伪察哈尔盟盟长，管辖察哈尔右翼正黄、正红、镶红、镶蓝等旗，包括察哈尔右翼中旗地区，积极推行日军殖民统治政策。；原察哈尔部上层，投靠日军后任伪察哈尔盟盟长，管辖区域与锡林郭勒盟南部接壤，配合日军推行伪政，镇压抗日活动。；在察哈尔盟及锡林郭勒盟南部地区为日军效力，管理伪政权事务，其辖区与太仆寺旗相邻。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7beef9db14e6431ba097c85e4c16b55a','529eba01fd3844d2a4780badaf25cb50',1937,'伪绥西联军总司令、伪蒙古军副总司令','绥远人，早年投靠日军，1937年后任伪绥西联军总司令，配合日军进攻绥远、乌兰察布等地，在察哈尔右翼地区亦有活动。；绥远省五原人，早年即为地方武装头目，抗战爆发后投靠日军，任伪绥西联军总司令，率部在绥远西部、包头、呼和浩特一带配合日军作战，袭击抗日武装，残害民众。；原为绥远地方武装头目，抗战爆发后投靠日军，组织伪军配合日军进攻绥远、察哈尔等地，其部曾在昭乌达盟、赤峰一带参与对抗日武装的扫荡和治安强化运动。；绥远地区著名汉奸，组织伪军配合日军进攻绥西，在包头、五原、东胜及鄂尔多斯北部一带活动，参与维持会与伪政权建设，残害抗日军民。；绥远地区著名汉奸，投靠日军后组织伪军，活动于绥西、鄂尔多斯北部及杭锦旗沿河一带，配合日军进攻抗日根据地，残害民众。；绥远地区著名汉奸，投靠日军后组织伪军，在绥西、鄂尔多斯北部一带配合日军作战，残害抗日军民，掠夺地方资源。；率伪军配合日军进攻绥西和宁夏北部，在石嘴山、磴口一带活动，组织维持会，征粮抓丁，残害抗日军民。；率伪军配合日军进攻绥西和宁夏北部，在磴口、石嘴山、贺兰山一带活动，烧杀抢掠，协助日军推行治安强化运动。；率伪军在晋西北吕梁地区配合日军作战，参与对抗日根据地的扫荡和掠夺。；绥远地方武装头目，投敌后任伪绥西联军总司令，在绥远、陕西北部一带配合日军进攻抗日根据地，掠夺物资，残害百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dd52ab2bbc76479ebab366a2ab38fcd2','7fe60a0e08e747819e43053afc3d9d27',1937,'伪察南自治政府最高委员、伪蒙疆联合自治政府副主席','1937年任伪察南自治政府最高委员，后任伪蒙疆联合自治政府副主席，参与伪蒙疆政权对察哈尔地区（含察哈尔右翼）的统治。；在伪蒙疆政权中担任要职，参与制定对内蒙古西部包括伊克昭盟地区的统治政策，推行亲日卖国路线。；投靠日军后参与组建伪察南自治政府，后任伪蒙疆联合自治政府副主席，协助日军统治察哈尔南部及邻近的锡林郭勒盟地区。；在伪蒙疆政权中任要职，活动范围包括察哈尔与锡林郭勒盟南部，协助日军推行伪政、掠夺资源。；原察哈尔省商人，投靠日军，任伪察南自治政府最高委员，后任伪蒙疆联合自治政府副主席，参与伪蒙疆政权，其活动范围覆盖察哈尔、锡林郭勒盟一带。；张家口沦陷后出面组织伪察南自治政府，后任伪蒙疆联合自治政府副主席，协助日军统治察哈尔南部及张家口地区，推行伪化政策、征发物资与劳工。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('da89a9c42bd74b049ce46c7ffd9ae259','f27fdea68c0f4c87901d2593feda5141',1937,'伪晋北自治政府最高委员、伪蒙疆联合自治政府副主席','1937年任伪晋北自治政府最高委员，后任伪蒙疆联合自治政府副主席，与察哈尔右翼地区伪政权有行政关联。；原为山西大同地方士绅，日军占领大同后组织维持会，后任伪晋北自治政府最高委员、伪蒙疆联合自治政府副主席，配合日军在晋北、察南及内蒙古中东部地区推行保甲制度、征粮征兵。；在伪蒙疆政权中任职，协助日军统治绥远及内蒙古西部，其政策影响波及鄂尔多斯地区。；投靠日军后任伪晋北自治政府最高委员，后任伪蒙疆联合自治政府副主席，参与蒙疆伪政权的统治，其政权体系覆盖内蒙古中西部。；在伪蒙疆政权中任要职，参与伪蒙疆联合自治政府决策，其政策影响覆盖锡林郭勒盟地区。；原晋北官员，投靠日军，任伪晋北自治政府最高委员，后任伪蒙疆联合自治政府副主席，参与伪蒙疆政权，其政权管辖范围涉及内蒙古中西部。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8e12c6dbf9bf40499445d5cefddf67f6','2659053ec01b4b489c2d157baa24ee77',1936,'伪蒙古军副总司令、伪察哈尔盟警备司令','蒙古族，曾任伪蒙古军副总司令，后任伪察哈尔盟警备司令，负责察哈尔右翼各旗的治安与军事，镇压抗日力量。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('af077e00a89c440e98950348939bdcb5','77857f075ce44761869c5724589a4545',1936,'伪蒙古军参谋长、伪蒙古军第九师师长','蒙古族，曾任伪蒙古军参谋长，后任伪蒙古军第九师师长，在乌兰察布、察哈尔右翼地区驻防，配合日军作战。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c601b019f6db451b877266214844f3bb','188e53b892a04f628776743bbe3f7af7',1936,'伪蒙古军第一师师长','蒙古族，伪蒙古军第一师师长，驻防察哈尔右翼地区，参与对抗日武装的围剿。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3453779e93764e57951792abdb6700d3','838979c5881d455d9908a863bc24d449',1936,'伪蒙古军第三师师长','蒙古族，伪蒙古军第三师师长，活动于乌兰察布、察哈尔右翼一带，协助日军维持殖民统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('80232224204643f7a7d58006427216d3','ae3b48ea9e8040088090d6b3522682e5',1936,'伪察哈尔盟副盟长','察哈尔蒙古贵族，任伪察哈尔盟副盟长，协助卓特巴扎普管理察哈尔右翼各旗，推行伪政权政策。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('98f20887ddf042f9b5419ae5bc9651ff','2107c2bcc66a4134b2b779fbbb3015d4',1936,'伪察哈尔右翼正黄旗总管','察哈尔右翼正黄旗蒙古贵族，任伪旗总管，在察哈尔右翼中旗邻近地区推行伪蒙疆政权政策，征粮征兵。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('551162e80ff24c1ebacacd5ad17de557','62df5801e3994d7689d34b7f503e286c',1936,'伪察哈尔右翼镶红旗总管','察哈尔右翼镶红旗蒙古贵族，任伪旗总管，与察哈尔右翼中旗同属察哈尔右翼，协助日军统治。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('75107a57c2d94f7e91d9281fe03d4086','c3839a77877445c6a45ac40cd133f007',1937,'伪乌兰察布盟盟长','乌兰察布盟蒙古王公，任伪乌兰察布盟盟长，管辖包括察哈尔右翼中旗在内的乌兰察布地区，推行伪蒙疆政权法令。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('67a7988bb9d64e7b87e813302e1c6f31','4f4f30ff0aad4326bfbfbd1371d7f371',1937,'伪乌兰察布盟副盟长','乌兰察布盟蒙古贵族，任伪乌兰察布盟副盟长，协助巴彦孟克管理乌兰察布盟各旗，包括察哈尔右翼中旗。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5ebe1664a8b24443b92e4e312f14a53a','ef6c08d0f52941eb82c78030ddb226af',1937,'伪厚和浩特市市长、伪乌兰察布盟公署参事','绥远人，曾任伪厚和浩特（今呼和浩特）市市长，后任伪乌兰察布盟公署参事，参与伪政权对乌兰察布地区的管理。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('37b956649c1b4d059a3539114605eaa7','25561457344c435aaa3b812455c00558',1937,'伪厚和浩特市商会会长、伪蒙疆联合自治政府经济委员','归绥（今呼和浩特）商人，任伪厚和浩特市商会会长，后任伪蒙疆联合自治政府经济委员，为日军经济掠夺服务，影响范围包括乌兰察布地区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('87eddc1142bd4a1fb0d6400185292161','78198cf336e24d25a8e52cd58ddf4575',1933,'伪蒙疆联合自治政府主席、伪蒙古军总司令','在察哈尔右翼前旗及乌兰察布地区积极推行日本侵略者的“蒙疆自治”政策，组织伪蒙古军配合日军进攻抗日武装，并在当地实施殖民统治和奴化教育。；在乌拉特中旗及内蒙古西部策划“蒙古自治”，组建伪蒙古军，配合日军进攻绥远，建立傀儡政权，压迫抗日力量。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7be9f4ebb2a5470ba1d2a95002f3b6aa','5f82d23ccd2e45fd9e59f76c92bcc9ad',1933,'伪蒙古军副总司令、伪蒙疆联合自治政府副主席','作为日本扶植的蒙古军头目，在察哈尔右翼前旗及周边地区协助日军镇压抗日力量，参与“清乡”和掠夺资源，为日军提供情报和兵力支持。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('123d51f1b5394a1eae89a16c8da9270a','b86083bd13c04af7ae64c9ee8b5ee802',1938,'伪蒙疆联合自治政府政务院院长','在乌兰察布及察哈尔右翼前旗地区推行伪政权法令，组织汉奸团体协助日军维持治安，强征民夫和粮食，迫害抗日军民。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('398192b47ea74fc194cbb96efea3181f','c94f058ddf0448068e37a5d4ac1c1a8d',1937,'伪察哈尔盟盟长、伪蒙疆政府参议','在察哈尔右翼前旗一带为日军效劳，参与建立伪旗公署，强迫当地民众“归顺”日伪，并协助日军围剿八路军游击队。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5feb3f6510c3413788129f5b06ffd291','2659053ec01b4b489c2d157baa24ee77',1939,'伪察哈尔右翼前旗旗长','直接管理察哈尔右翼前旗日伪政权，向日军提供当地抗日活动情报，强征壮丁和牲畜，实施保甲连坐制度，镇压反抗民众。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('68736167bfe7469d93a3d2a3872c2376','dd8c71d66e0841399bb26d229b5ac4ef',1937,'伪察哈尔盟副盟长、伪蒙古军师长','在乌兰察布东部及察哈尔右翼前旗地区率伪军参与“扫荡”，烧毁村庄，杀害抗日干部，并协助日军建立特务情报网。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('97a700e228724fe0b80c973ef6ab26bf','593d6fcbfc5441379dd2cfbafa1bb50e',1940,'伪察哈尔右翼前旗警察署署长','指挥伪警察在旗内搜捕抗日地下工作者，严刑逼供，并配合日军进行“治安强化运动”，残害无辜百姓。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('213323b022944c38a8d8a4ba3c68646b','1525e16ff20b436b8d968f84ebaaac6d',1941,'伪蒙疆政府驻乌兰察布办事处主任','负责协调日伪军与地方汉奸势力，在察哈尔右翼前旗推行“以华制华”政策，组织汉奸武装“自卫团”袭扰抗日根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6661b19e93234406952de8618ca5eafe','993cd83aa8c54ff38e0622e1de731309',1939,'伪察哈尔盟公署参事','在察哈尔右翼后旗协助日伪推行保甲制度，强征壮丁，搜集抗日情报，迫害当地进步人士','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6ea0f88fdbee4ad78c595fb3a83526f7','c94f058ddf0448068e37a5d4ac1c1a8d',1940,'伪察哈尔右翼后旗旗长','作为伪旗长，执行日伪“蒙地政策”，强占牧民土地，强迫民众种植鸦片，为日军提供后勤支持','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9d04de5513ac4c3da8e053da71be15f8','2107c2bcc66a4134b2b779fbbb3015d4',1941,'伪察哈尔右翼后旗保安队队长','率伪保安队协助日军围剿八路军游击队，在乌兰察布南部地区抓捕抗日群众，实施酷刑逼供','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7cf70ef4769847e0b20acff319bd412c','5f82d23ccd2e45fd9e59f76c92bcc9ad',1933,'蒙疆联合自治政府副主席/伪蒙古军总司令','原东北军将领，后投日，在绥东（含集宁一带）率伪蒙古军协助日军进攻抗日武装，镇压民众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f16b40164e0142488a7b6a054fef1c71','529eba01fd3844d2a4780badaf25cb50',1937,'伪绥西自治联军司令','绥远地区土匪出身，投日后在乌兰察布、集宁周边为日军效力，参与扫荡和清乡，残害抗日军民。；绥远地方军阀，投日后在包头、东河一带活动，协助日军围剿大青山抗日游击队，参与“清乡”和掠夺资源。；原土匪出身，投日后在包头、固阳一带组织伪军，多次进攻大青山抗日根据地，残害抗日军民，抢劫百姓财物。；原土匪武装头目，投日后在绥远（含呼和浩特周边）组织伪军，多次配合日军扫荡抗日根据地，残害百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('90c40a5a61f843fd9abd6e3b7b004c70','fc69c98db6304cccbd2075c295573b10',1937,'伪蒙疆政府要员/伪锡林郭勒盟盟长','在德王政权中任职，协助日军控制乌兰察布北部牧区，征粮派款，镇压牧民反抗。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('54a85c8d43ac47d48293375556cbdea7','dd8c71d66e0841399bb26d229b5ac4ef',1938,'伪蒙疆政府政务院院长','参与蒙疆政权核心决策，在乌兰察布地区推行日伪法令，组织伪警察和保甲制度。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('47659bb9300846c0b695d47c4d7bd119','b86083bd13c04af7ae64c9ee8b5ee802',1939,'伪蒙疆政府参议/伪察哈尔盟盟长','在察哈尔右翼（今乌兰察布部分旗县）协助日军推行“治安肃正”，抓捕抗日地下人员。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1c30321f37fc4818b07d6da6c5c31766','ec26ab26d6bb4c4b8f8348f1bb125cd7',1938,'伪绥远省公署警务厅长','在绥东（含集宁）组织伪警察，协助日军搜捕抗日分子，破坏地下组织。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0697f84ffd2a41febcebb5f8e4e1e9d0','25561457344c435aaa3b812455c00558',1938,'伪集宁县知事（县长）','在集宁县城为日军征粮、征夫，推行奴化教育，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('638e89378c234f9f87d927b12956a587','12a8b4767b1e4a989997caabbb41d83a',1940,'伪绥东保安司令','原晋军军官，投日后在乌兰察布东部组织伪保安队，配合日军封锁根据地。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6210c8205cb44894a0159de4c37aa7f4','c94f058ddf0448068e37a5d4ac1c1a8d',1937,'伪蒙疆政府副主席','蒙古贵族，投靠日本，在伪蒙疆政权中任职，参与对乌海地区蒙古族民众的奴化宣传和物资搜刮。；蒙古族上层，投靠日本，在包头及乌兰察布一带协助日军维持治安，参与镇压抗日活动。；蒙古族上层，投靠日本后任伪蒙疆副主席，参与对呼和浩特回民区的管控，强迫回民捐献物资，破坏回民抗日组织。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8341529d8cc8458ab3aed4d09bcbef81','993cd83aa8c54ff38e0622e1de731309',1937,'伪蒙古军第1师师长','率伪蒙古军驻扎绥西及乌海一带，配合日军扫荡抗日游击队，欺压百姓，强征民夫修筑工事。；率伪蒙古军驻扎鄂尔多斯北部，配合日军“扫荡”达拉特旗、杭锦旗等地，杀害抗日游击队成员。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('61b09dbe011b4435a4377b4dce872333','26647d4bb91f4086a567e1a461c53d38',1937,'伪蒙古军第2师师长','在乌海及周边地区协助日军作战，参与围剿抗日武装，劫掠民间财物，为日军提供情报。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('eba9d414ca94487687b67131e223fac9','77857f075ce44761869c5724589a4545',1937,'伪蒙古军第3师师长','率部在乌海、磴口一带活动，配合日军封锁抗日通道，迫害进步人士，强征牲畜和粮食。；在包头、固阳地区驻防，参与日军“治安肃正”行动，屠杀抗日嫌疑分子，强征马匹和粮草。；在绥西地区活动，协助日军围剿抗日游击队，参与建立伪乡村政权，强迫民众充当苦力，修筑军事工事。；驻防乌拉特中旗期间，配合日军建立伪警察机构，强迫牧民“归顺”，镇压抗日游击队。；在绥西地区率伪军配合日军“扫荡”，参与杀害抗日军民，掠夺财物，破坏抗日组织。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fac31af04a224b2aa9203e10b74e6575','3a09ae0f7f294a118069ecfbec5ba35b',1937,'伪蒙古军第4师师长','在乌海地区参与日伪军事行动，镇压当地民众反抗，协助日军建立伪保甲制度。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7845baa069514b42a310ba46eb3952ad','a4a0b90fb3c141f8939b220dafdfb71f',1939,'伪蒙疆政府教育顾问','在乌海地区推行奴化教育，强迫蒙古族学生学日语，宣传“日蒙亲善”，为日本殖民统治服务。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('92d12119a8144df5a72c166fc1c13c1d','2e047aa1489e418db87b0daa26378d58',1940,'伪绥西自治联军司令（后投日）','原国民党将领，后投靠日军，在乌海及河套地区组织伪军，配合日军进攻抗日根据地，残害百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9e8dfe541e614580b0751c59ace48ff3','b86083bd13c04af7ae64c9ee8b5ee802',1936,'伪蒙古军政府总务部长、伪蒙疆政府内政部长','蒙古族官僚，追随德王投日，在内蒙古西部包括乌海、海勃湾地区参与建立伪政权，负责行政和治安，协助日军征粮征税，镇压当地抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('699c47b344b849d9855d155d01f9984e','78198cf336e24d25a8e52cd58ddf4575',1936,'伪蒙古联盟自治政府主席','在日军扶植下成立伪蒙古联盟自治政府，任主席，推行“蒙疆自治”，配合日本殖民统治，征发蒙汉民众为日军服务。；蒙古王公，1936年投日，组织伪蒙古军政府，后任伪蒙古联盟自治政府主席，与日军合作，在包头及内蒙古西部推行殖民政策，招募汉奸充实伪政权。；蒙古王公，与日军合作建立伪蒙政权，其势力范围包括武川地区，推行奴化教育，协助日军征粮征兵，镇压抗日活动。；蒙古王公，组织伪蒙古军政府，与日军合作控制察哈尔北部及沽源一带，推行奴化政策。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('147026640a94404eb57e86f51f9d2a99','b86083bd13c04af7ae64c9ee8b5ee802',1937,'伪蒙古军参谋长','任伪蒙古军参谋长，协助李守信、德王组织伪军，参与对抗日武装的围剿，为日军提供情报和后勤支持。；曾任伪蒙古军参谋长，协助李守信、德王组织伪军，参与对包头、固阳等地的“扫荡”，迫害抗日军民。；德王亲信，参与策划伪蒙军对武川、归绥（今呼和浩特）一带的扫荡，为日军提供情报，迫害抗日军民。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cf2cf45eb2fe47e59913b5381a85cd6c','09e65a7dbae748caa1181ab2c8844755',1938,'伪绥西自治联军副司令','协助王英统领伪军，在乌海、海南周边地区设卡收税，强征民夫，为日军修筑工事。；王英的副手，在临河、五原一带协助日军维持治安，参与屠杀抗日群众，并负责为日军征收粮食和牲畜。；王英的副手，长期盘踞五原地区，为日军搜集情报，并参与对抗日根据地的封锁和破坏。；王英部下，在杭锦后旗一带协助日军维持治安，镇压抗日活动，参与抓捕和杀害抗日志士。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('41e351ade344497ba87b517ebd6c800a','b20b75e3a839472699d4a3cb0593b9fe',1939,'伪蒙古军旅长','任伪蒙古军旅长，活动于鄂尔多斯及乌海一带，参与镇压当地抗日游击队，掠夺牲畜和粮食。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('940d843eda414194aaeb99404d83ef76','529eba01fd3844d2a4780badaf25cb50',1937,'伪东亚同盟军总司令','在乌兰浩特及周边地区为日军效力，组织伪军进攻抗日根据地，协助日军进行“治安肃正”行动。；原土匪武装头目，投日后在张家口、察北地区组织伪军，进攻八路军和抗日游击队，烧杀抢掠。；原土匪武装头目，投日后在张家口一带活动，率伪军袭击抗日根据地，劫掠百姓，后任伪绥西联军司令。；原绥远土匪头目，投日后在张家口、康保一带活动，率伪军骚扰抗日根据地，参与“扫荡”行动。；原土匪出身，投日后在张家口一带组织伪军，多次进攻抗日根据地，烧杀抢掠。；原为土匪武装头目，投日后在张家口、怀安一带活动，率伪军进攻八路军，制造多起惨案。；原为绥西土匪，投日后在张家口、怀来一带活动，率伪军配合日军进攻平西抗日根据地，烧杀抢掠。；原为绥远土匪，投日后在张家口地区组织伪军，参与对抗日根据地的进攻，在桥东地区设据点，欺压百姓。；原为绥西土匪，投日后在张家口地区组建伪军，参与对抗日根据地的进攻，烧杀抢掠，为日军充当鹰犬。；原土匪武装头目，投日后任伪东亚同盟军总司令，活动于张家口、沽源等地，参与“扫荡”八路军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f5c890201ffc4c369aeebbeec0e13bb7','b002e65e42f14f4fbbadc0ebf8786c9e',1932,'伪兴安总省省长','作为伪满兴安总省（辖今兴安盟、乌兰浩特）最高行政长官，推行日本殖民政策，强征劳工，镇压反满抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('07fe90f080dd4885a0f96d8dbf8c6e67','328c16b7cce14a88803101ac039f03d5',1932,'伪兴安南省省长','在兴安南省（含乌兰浩特地区）协助日军实施“蒙地分治”，征收粮草，迫害抗日志士。','省部级/大军区级要员','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0ac554f498024adcac4304463a97c9dc','4ff98a4e38cc4aacb41680dcb877f683',1932,'伪兴安西省省长','在兴安盟西部及乌兰浩特周边配合日军清乡，组织伪警察队，参与围剿东北抗联部队。','省部级/大军区级要员','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('914516a65d99477d929963010d71a0a0','b075a66e35f745e182db23a12f857035',1935,'伪兴安总省参事官','在乌兰浩特地区为伪满政权效力，参与制定“蒙人治蒙”政策，协助日军控制蒙古族民众，破坏抗日组织。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('93901dc5f655480bad743323fdef9c52','26647d4bb91f4086a567e1a461c53d38',1938,'伪兴安军管区司令','指挥伪兴安军驻守乌兰浩特，多次配合日军进攻抗联三路军，屠杀抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7d5bd2c49249416d85d3db546fe5d043','25e14c6523f347349389d63d8a7056ac',1940,'伪兴安军第1师师长','率伪军在兴安盟、乌兰浩特一带执行“讨伐”任务，制造多起惨案，强征民夫修筑军事工事。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3428ebf5ec014ed781b883f794f52b04','64f7e2c362324f7c8ebbecd6fb02d6e4',1941,'伪兴安军第2师师长','在乌兰浩特地区协助日军进行“特别治安”行动，逮捕并杀害抗联地下工作者。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7ff69cd0e55a4f08842472f4f7cf5783','f4208529cb14438593c9984febac079f',1932,'伪兴安南省省长、伪满洲国参议府议长','蒙古族王公，投靠日本后任伪兴安南省省长，协助日军在扎赉特旗及兴安盟地区推行殖民统治，镇压抗日力量，参与伪满洲国傀儡政权建设。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f6f78ab806c44485b6fb02191c28230f','c751942e2e3b40dc8fc490a7a38da75f',1932,'伪兴安南省警备军司令官','原扎赉特旗札萨克，叛国投敌后任伪兴安南省警备军司令，率伪军配合日军围剿抗日武装，在扎赉特旗地区实施“清乡”和“讨伐”，残害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3bb77bff0a7b4446b8e5d03e844c34e5','cce0beb18f6444d29b255fd8e4458a06',1933,'伪兴安南省民政厅长、伪扎赉特旗旗长','蒙古族官僚，投日后历任伪职，在扎赉特旗推行日伪“土地奉上”政策，强征民夫和物资，协助日军建立保甲制度，镇压当地反抗活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2d20945e450e4bc291077850f868d201','6dec6f2201c84d729ec0c0b13ca17e6e',1932,'伪兴安南省总务厅长','参与伪兴安南省行政事务，积极执行日本关东军指令，在扎赉特旗地区推行奴化教育和经济掠夺，为日军提供情报和后勤支持。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cadd10411def4efb8811f3b22a718f66','4ff98a4e38cc4aacb41680dcb877f683',1934,'伪兴安南省参事官','作为蒙古族上层投靠日本，在扎赉特旗参与组织伪警察和自卫团，协助日军抓捕抗日志士，强征“国兵”和劳工。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ec29dbf164124b37abca3677756eeadb','a538250160da4bfbabeeecbf23766d8b',1935,'伪扎赉特旗警务科长','负责扎赉特旗伪警察机构，多次率警队配合日军“扫荡”，逮捕和刑讯抗日地下人员，参与“治安肃正”行动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6ce39b61056f4ff8a9db8eee40abd12f','eb166a17cf664e83aa52590be3bac98d',1932,'伪满洲国兴安南分省省长、伪兴安局总裁','蒙古族王公出身，九一八事变后投靠日本，参与策划内蒙古东部‘独立’活动，历任伪兴安南分省省长、伪兴安局总裁等职，协助日本在兴安地区推行殖民统治，管辖范围包括科尔沁右翼中旗一带。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5c18e7c7c0e84ae6ad262cb314d07513','f4208529cb14438593c9984febac079f',1932,'伪满洲国兴安南分省警备军司令、伪兴安军管区司令官','原扎赉特旗王公，投日后任伪兴安南分省警备军司令，率伪军配合日军镇压抗日武装，其部队活动于兴安南地区，包括科尔沁右翼中旗周边。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('19710e71251c43909a31fd6987db1c9a','cce0beb18f6444d29b255fd8e4458a06',1932,'伪满洲国兴安南分省参与官、伪兴安总省民生厅长','蒙古族上层人物，投靠日本后历任伪兴安南分省参与官等职，参与推行‘蒙地奉上’等殖民政策，在兴安地区协助日伪统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5aebba32ceb04957bf7393106c912846','328c16b7cce14a88803101ac039f03d5',1932,'伪满洲国兴安南分省民政厅长、伪兴安总省省长','早年参与内蒙古自治运动，后投靠日伪，历任伪兴安南分省民政厅长、伪兴安总省省长，在兴安地区推行日本殖民统治政策。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('50eebaf96cfb4b6da7ac405cf33cc24f','4ff98a4e38cc4aacb41680dcb877f683',1932,'伪满洲国兴安南分省总务厅长、伪兴安局参与官','蒙古族官僚，投日后在伪兴安南分省任职，参与管理科尔沁右翼中旗等地的行政与警务，协助日军征发物资、镇压抗日力量。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ac282fdd21dc4a9792c7b720993ec884','82a28e1bf3114256b2f73824a84188b9',1932,'伪满洲国兴安南分省警备军参谋长、伪兴安军管区参谋长','原内蒙古东部蒙古族军官，投日后任伪兴安南分省警备军参谋长，参与指挥伪军配合日军在兴安地区‘讨伐’抗日武装。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4dea9643e34e4ed38d220498411698c3','78198cf336e24d25a8e52cd58ddf4575',1936,'伪蒙古联合自治政府主席、伪蒙疆联合自治政府主席','锡林郭勒盟苏尼特右旗札萨克亲王，投靠日本后建立伪蒙疆政权，虽中心在察哈尔、绥远，但与兴安地区伪政权有联系，其伪蒙古军活动范围涉及内蒙古东部。；在日军扶植下建立伪蒙疆政权，其势力范围覆盖内蒙古东部及通辽地区，与科尔沁左翼后旗伪旗政权有隶属或协作关系，推行亲日殖民政策。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('72d0314f3cb24bb390540391ee7f0c72','529eba01fd3844d2a4780badaf25cb50',1933,'伪蒙古军副总司令、伪绥西联军司令','绥远地区土匪头目，投日后任伪蒙古军副总司令，率部在内蒙古西部及兴安地区配合日军作战，参与镇压抗日武装。；绥远地区土匪出身，投日后任伪蒙古军副总司令，其部队在内蒙古东部及通辽一带活动，配合日军扫荡抗日根据地，后任伪绥西联军司令。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ced221d3a1604199a32fe1b8b9790fe7','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满洲国奉天省警备司令、伪满洲国军政部大臣','原东北军将领，九一八事变后投敌，历任伪奉天省警备司令、伪军政部大臣，其指挥的伪军活动范围包括兴安南地区，参与‘讨伐’抗日武装。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e0b9fbfaf5454f278783a11753122a4a','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洲国洮辽镇守使、伪满洲国热河省省长','原东北军洮辽镇守使，九一八事变后投敌，率伪军进攻热河、察哈尔，其活动区域与兴安南地区相邻，配合日军镇压抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3fc42ed2e1224321b44d9ccd7db306f0','dddf6075e9614f79add415cba2b3c0c4',1932,'伪满洲国兴安北分省省长','达斡尔族上层，投日后任伪兴安北分省省长，虽后期因‘凌升事件’被日本处决，但前期在兴安地区协助日伪统治，与兴安南地区有行政联系。；达斡尔族上层，曾任伪满洲国兴安北分省省长，驻海拉尔，管辖包括新巴尔虎右旗在内的呼伦贝尔地区，后因与日本矛盾被处决，但其前期附逆行为明确。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('750b3011943e4c81b9c3ca34149c7402','8625223b5393415fabb6dcd24b19bf94',1932,'伪满洲国兴安南分省科尔沁右翼中旗旗长','科尔沁右翼中旗蒙古族上层，投日后任该旗伪旗长，协助日军征发物资、推行保甲制度，镇压当地抗日活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('92499c1d42154334a718b582bdd6c5b2','62df5801e3994d7689d34b7f503e286c',1935,'伪满洲国兴安南分省科尔沁右翼中旗警务科长','在科尔沁右翼中旗任伪警务科长，指挥伪警察配合日军‘讨伐’抗日游击队，迫害抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8ce838ff537c4143b279274fdb193cfc','5432fbdab70b4846bf4358ef4c3d0c29',1932,'伪满洲国兴安南分省科尔沁右翼中旗维持会会长','科尔沁右翼中旗地方豪绅，日军占领后组织维持会，协助日军维持治安、征发粮草，后转入伪旗公署任职。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('15074bc4fa574c48a26a6d8c7bb0d8b1','eb166a17cf664e83aa52590be3bac98d',1932,'伪兴安南分省省长、伪兴安局总裁','蒙古族上层亲日派，参与策划伪满洲国成立，历任伪兴安南分省省长、伪兴安局总裁等职，协助日本在兴安地区推行殖民统治，管辖范围包括科尔沁右翼前旗一带。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('08d0214e012d415c93c151ee965c7f39','f4208529cb14438593c9984febac079f',1932,'伪兴安南省警备军司令、伪兴安军管区司令官','原扎赉特旗王公，投靠日本后任伪兴安南省警备军司令等职，率伪军配合日军在兴安地区镇压抗日武装，其活动覆盖科尔沁右翼前旗周边。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3b0d1c6e341f4b6c9895ad0b7a5ed77e','328c16b7cce14a88803101ac039f03d5',1932,'伪兴安南省民政厅长、伪兴安局参与官','蒙古族亲日文人，在伪兴安南省任职期间推行日本殖民教育、文化政策，协助日伪在兴安地区建立基层伪政权，涉及科尔沁右翼前旗。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c48b43dcfd624e79adcb7786ab758d1e','cce0beb18f6444d29b255fd8e4458a06',1932,'伪兴安南省警备军参谋长、伪兴安军管区参谋长','蒙古族伪军头目，长期在伪兴安南省警备军任职，参与指挥对兴安地区抗日游击队的围剿，活动范围包括科尔沁右翼前旗。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('98c9db37efbc4d8ba02c203ffbec24bc','82a28e1bf3114256b2f73824a84188b9',1932,'伪兴安南省警备军骑兵团长、伪兴安军管区部队长','蒙古族伪军军官，在伪兴安南省警备军任职期间率部配合日军在兴安地区进行治安肃正，镇压抗日力量，活动于科尔沁右翼前旗一带。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('73bad2f488284525abb43c9976040c54','f59ccdd9a4164c3ea3b028cb6cdac5be',1932,'伪兴安南省总务厅长、伪兴安局理事官','蒙古族亲日官僚，在伪兴安南省任职期间负责行政、财政事务，协助日本掠夺兴安地区资源，推行保甲制度，涉及科尔沁右翼前旗。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f9651bccd6914837a35385661047ec6e','c6294457b2f2458d8f85e6a3418803b4',1932,'伪科尔沁右翼前旗旗长、伪兴安南省参事官','直接于科尔沁右翼前旗任职的伪旗长，协助日伪推行旗政、征粮、征兵，镇压当地抗日活动，是当地伪政权核心人物。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4f51d3c9e045403d99f3571477f2bb12','cd643d8a8b3e49bf9014b89d375c75d0',1932,'伪科尔沁右翼前旗警务科长、伪兴安南省警务厅警正','在科尔沁右翼前旗担任伪警务科长，负责伪警察队伍，配合日军搜捕抗日人员，推行保甲连坐，直接镇压当地民众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('48c829e0749e4890ab9bdecb9dae841f','4a03e421a6d14d5ab048a82a56012a44',1932,'伪科尔沁右翼前旗维持会会长','在科尔沁右翼前旗组织维持会，协助日军维持占领秩序，征派劳役、物资，为伪旗政权建立铺路。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bc4537eba46b46d7a43cca994d63a491','4ae3c4ced72842be9465b8ecc9068b6f',1935,'伪科尔沁右翼前旗保甲长、伪兴安南省协和会分会会长','在科尔沁右翼前旗担任保甲长并兼任协和会分会会长，推行保甲制度、宣传亲日思想，协助日伪征粮征兵，监控当地民众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('321efc8d0a0848dab3ee81a9cb5530ee','5432fbdab70b4846bf4358ef4c3d0c29',1936,'伪兴安南省协和会事务长','在伪兴安南省协和会任职，负责亲日宣传、组织民众训练，活动覆盖科尔沁右翼前旗，协助日伪进行思想控制。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9808373653184ef28a44ff054405011d','86537c8591e647e2bc790f9bf8fa7805',1935,'伪兴安南省教育会会长、伪科尔沁右翼前旗国民学校校长','在科尔沁右翼前旗推行日本殖民教育，强制教授日语、篡改历史，培养亲日青少年，属教育领域附逆者。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0f1bcd8d9f064b56ac245366404a67df','78198cf336e24d25a8e52cd58ddf4575',1930,'伪蒙疆联合自治政府主席','蒙古族上层亲日派首领，虽主要活动于察哈尔、绥远，但其伪蒙疆政权与伪兴安地区有联系，影响覆盖内蒙古东部，包括兴安、科尔沁右翼前旗一带的蒙古族亲日势力。；即德王，在内蒙古中西部建立伪蒙疆政权，与日本合作；其影响及于内蒙古地区，是抗战时期内蒙古范围内最重要的附逆头目之一。；蒙古王公，投靠日本，建立伪蒙疆政权，其势力范围覆盖内蒙古中东部，与呼伦贝尔地区有联系。；在日军扶植下于张家口建立伪蒙疆政权，统治包括察哈尔北部、张家口周边地区，推行亲日附逆政策。；在察哈尔、热河及河北北部建立伪蒙疆政权，与承德伪满势力勾结，配合日军进攻抗日根据地，推行殖民统治。；内蒙古人，抗战期间投靠日军，任伪蒙疆联合自治政府主席，在华北地区进行伪化统治。；伪蒙疆政权首脑，主要活动于内蒙古、察哈尔等地，与重庆沙坪坝无直接关联。；在日军扶植下成立伪蒙疆政权，配合日军在华北、西北的侵略，对陕西北部有威胁。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f6ce0e4a545046e4818b63d5a40c13a3','eb166a17cf664e83aa52590be3bac98d',1932,'伪兴安南省警备军司令、伪兴安军管区司令','蒙古族上层出身，九一八事变后投靠日本，参与策划内蒙古东部独立活动，历任伪兴安南省警备军司令等职，率伪军配合日军镇压抗日武装，控制兴安盟一带，包括突泉地区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8cd31f18c0be414f83fcf3027fb029a8','f4208529cb14438593c9984febac079f',1932,'伪兴安南省省长、伪兴安局总裁','原扎赉特旗王爷，投日后任伪兴安南省省长、伪兴安局总裁等职，协助日本在兴安盟推行殖民统治，征发劳工、物资，镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e3223d612c6e4c16b611aa7771e85c9f','cce0beb18f6444d29b255fd8e4458a06',1932,'伪兴安南省民政厅长、伪兴安总省民生厅长','蒙古族官僚，在伪兴安南省任职期间推行日本殖民政策，管理民政、警察事务，配合日军在突泉等地的保甲连坐和物资统制。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5044b5d770184f90bf996dff92522070','c6294457b2f2458d8f85e6a3418803b4',1932,'伪兴安南省警备军军官、伪兴安军骑兵团长','在伪兴安南省警备军任职，率部在兴安盟及突泉周边地区配合日军围剿抗日游击队，强征民夫、牲畜。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a0875c189b1e4604bfba48d23bbd6cd6','5f82d23ccd2e45fd9e59f76c92bcc9ad',1933,'伪蒙古军总司令、伪察南自治政府要员','热河土匪出身，投靠日本后任伪蒙古军总司令，活动范围覆盖内蒙古东部及兴安盟周边，配合日军进攻抗日根据地，在突泉一带征粮征兵。；热河人，长期在伪蒙疆和华北伪军中任职，其伪军活动范围涉及山西北部及华北地区，配合日军作战，对山西抗日力量构成威胁。；热河地区蒙古族伪军头目，长期在承德、赤峰及河北北部活动，配合日军围剿抗日武装，推行保甲连坐，掠夺物资，镇压民众。；内蒙古人，长期在伪蒙疆政权任职，其伪军曾参与对河南北部地区的策应行动，与河南伪政权有联系。；内蒙古人，长期在伪蒙疆政权任职，其伪军曾配合日军在河南北部活动，间接影响南阳地区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('caa64edb4dcd45d898d9c2582bde76c5','529eba01fd3844d2a4780badaf25cb50',1936,'伪绥西自治联军总司令、伪蒙古军师长','绥远地区汉奸武装头目，投日后率伪军在内蒙古中东部活动，曾配合日军在兴安盟附近扫荡，参与镇压抗日力量。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('60d64a0c2d594c0a80bf3b9ac67729fe','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪奉天省警备司令、伪满洲国军政部大臣','原东北军将领，九一八后投敌，任伪奉天省警备司令等职，其伪军活动范围包括内蒙古东部与兴安盟接壤地区，配合日军镇压抗日武装。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a8419d106b2a40adb137720d8b0f328c','1ba31d558b934fbd83a28a8c2b446022',1931,'伪洮辽镇守使、伪满洲国热河省省长','原东北军骑兵师长，投日后任伪洮辽镇守使，率伪军进攻热河、兴安盟一带，在突泉周边地区配合日军作战，镇压抗日军民。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c750d8ea0e3d42e6a5b8e25ab21d4399','dddf6075e9614f79add415cba2b3c0c4',1932,'伪兴安北省省长','达斡尔族上层，曾任伪兴安北省省长，参与伪满洲国初期统治，后因与日本矛盾被处决；其活动范围主要在呼伦贝尔，但与兴安盟伪政权有联系。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ed5b1503b14640d4bdadf33eefcda119','577e5f2815ac45bba40e354cc47cd980',1932,'伪兴安局总裁、伪满洲国参议','蒙古族王公，投日后任伪兴安局总裁等职，参与制定对内蒙古东部地区的殖民统治政策，影响覆盖兴安盟及突泉一带。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1c161d1153804c9abf629a31a31fd210','bd61065e408c4c6787b26e455669fa32',1932,'伪突泉县维持会会长','九一八事变后，突泉县地方士绅组织维持会，迎接日军占领，协助建立伪政权，维持地方治安并征发物资。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('898680c14dd746a0854e9c3b7104a45a','27dd7fbf09674fef88b7993a8a7c1b75',1933,'伪突泉县县长','伪满洲国时期由日方委任的突泉县县长，推行保甲制、粮谷出荷、劳工征发等政策，配合日军在兴安南省西部的统治。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('047b7999a3ad432c8568357722ad1690','eb166a17cf664e83aa52590be3bac98d',1932,'伪兴安军指挥官','日本关东军扶植的蒙古族汉奸，参与组建伪兴安军，在兴安、阿尔山一带协助日军维持治安，围剿抗日武装。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('419d4e5c6d654b1cb29da9c35b58461a','64f7e2c362324f7c8ebbecd6fb02d6e4',1932,'伪兴安军高级军官','甘珠尔扎布之弟，任伪兴安军要职，在兴安盟地区协助日军进行军事行动，镇压当地抗日活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3275832b9f2f4feba64c0adeaae9e5bd','26647d4bb91f4086a567e1a461c53d38',1932,'伪兴安南省省长','伪满洲国兴安南省（辖今兴安盟及阿尔山部分地区）省长，推行日伪殖民政策，强征劳工，协助日军统治当地蒙汉民众。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8d19d82aace64ecaa1f2bcf0b60fc618','cce0beb18f6444d29b255fd8e4458a06',1932,'伪兴安南省警务厅长','在兴安南省（含阿尔山地区）担任伪警务厅长，组织伪警察镇压抗日分子，抓捕并杀害抗联地下工作人员。','市县厅局级','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('795c443a5db74333961cc36a1ae1bee6','c751942e2e3b40dc8fc490a7a38da75f',1933,'伪兴安南省参事官','投靠日伪，在兴安南省（阿尔山一带）任参事官，协助日军推行“治安肃正”，迫害当地抗日群众。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ae11119d6c51412e947709bfc194bdb0','aa71e47cfe244100b9bcd57165d54b9f',1934,'伪兴安军团长','率伪兴安军驻扎于阿尔山附近，参与对苏联、蒙古边境的侦察及对抗日游击队的围剿。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b9f9990decfb46bbaeedc15ca5ec5f22','6dec6f2201c84d729ec0c0b13ca17e6e',1932,'伪兴安东省省长','伪满洲国兴安东省（部分辖区与兴安盟接壤）省长，虽主要活动于扎兰屯一带，但曾参与协调兴安、阿尔山地区的日伪军事行动。；在呼伦贝尔东部地区推行伪满统治，协助日军清剿抗联部队，征收粮草','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2cc474abc93646d2951db14f6bd33638','f4208529cb14438593c9984febac079f',1935,'伪兴安军骑兵师长','在兴安盟及阿尔山地区率伪骑兵师配合日军“扫荡”，破坏抗联根据地，掠夺当地物资。','市县厅局级','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('248102ff522742f48b57d5e9878d284d','09e65a7dbae748caa1181ab2c8844755',1939,'伪包头市市长','在日军占领包头期间出任伪市长，协助日军维持治安，推行保甲制度，强征劳工，为日军提供物资。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('043d5b09cd2142daaa18593a88d7c210','6687a4d3a75b4c3099f7cb5005501a4e',1939,'伪包头警察局局长','在包头伪政权中负责警察事务，抓捕抗日地下人员，协助日军进行特务活动，镇压民众反抗。；指挥伪警察在包头、九原地区搜捕抗日分子，破坏地下交通线，多次参与日军“治安强化运动”，杀害无辜百姓。；任伪包头警察局长期间，大肆搜捕抗日地下工作者，严刑逼供，破坏抗日组织，在固阳、包头一带制造多起血案。；协助日军在包头及白云鄂博矿区建立特务网络，抓捕抗日志士，镇压矿工反抗。；指挥伪警察在包头、青山地区搜捕抗日地下人员，破坏地下组织，协助日军实施“治安强化”运动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8bccdaf3bca042679ce737c5f13620cf','166623f268054f8b838c98e4da47eeb2',1938,'伪包头商会会长','投靠日军后控制包头商会，为日军筹集军饷和物资，强迫商户缴纳各种捐税，从中牟利。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3e866ee197444b0e91c9ad1624529e68','b8a63ee7224043ba8d5b34e6c030cce4',1938,'伪蒙疆银行包头分行经理','负责发行伪蒙疆货币，搜刮包头地区财富，配合日军经济掠夺，导致当地通货膨胀，民生凋敝。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e93b19b46e29430b9806a517c8bd0d35','26647d4bb91f4086a567e1a461c53d38',1937,'伪蒙古军参谋长','蒙古族军官，投靠德王后任伪军参谋长，在包头地区参与军事指挥，协助日军围剿抗日游击队。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d028c6fc78264257a80cbbad5d121ea7','1909708d9e93492fa066691261f33b0c',1939,'伪蒙疆政府包头市市长','蒙古贵族，任伪包头市长期间，推行日伪法令，强征劳工，协助日军控制包头及东河地区经济命脉。','市县厅局级','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4ace5ab91e894352b3d28dc849d4b313','25561457344c435aaa3b812455c00558',1940,'伪包头警察局局长','在包头、东河地区充当日军鹰犬，搜捕抗日地下工作者，镇压民众反抗，参与“特别治安”行动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fd9a537da60d402cb0740b34cce35248','8f4c6a82abd7490ab754fe15d2224dd0',1938,'伪包头保安队队长','率伪保安队在东河一带巡逻，配合日军“扫荡”，抢劫民财，杀害抗日家属，罪行累累。','基层头目','hanjian');
