INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4fd8c21a2642479f973ed62741f35a54','8f4c6a82abd7490ab754fe15d2224dd0',1941,'伪石拐矿区维持会会长','在石拐煤矿区为日军服务，组织矿工劳动，镇压矿工反抗，向日军提供煤炭资源。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('16d288f36fa34bbbb5689f50cf5f91ab','12a8b4767b1e4a989997caabbb41d83a',1942,'伪绥西保安队队长','在包头、石拐地区带领伪保安队，配合日军清乡，杀害抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c38c1c650cc94d97a53913357a05ba4f','b8a63ee7224043ba8d5b34e6c030cce4',1939,'伪蒙疆政府包头特务机关长','在包头、石拐地区从事特务活动，搜集情报，破坏抗日组织。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d69503049e644e08bccef50b3dbdf9d8','78198cf336e24d25a8e52cd58ddf4575',1933,'伪蒙古军政府总裁、伪蒙疆联合自治政府主席','在日军扶植下于百灵庙发动蒙古自治运动，后成立伪蒙疆政权，统辖包括包头、达尔罕茂明安在内的内蒙古中西部，推行亲日政策，配合日军统治。；在日军扶植下于内蒙古西部建立伪蒙疆政权，统辖察哈尔、绥远等地蒙古盟旗，鄂尔多斯部分旗县亦在其伪政权影响或控制范围内，推行亲日卖国政策，配合日军统治与掠夺。；在日军扶植下于内蒙古地区建立伪蒙疆政权，统辖察哈尔、绥远等地，鄂尔多斯部分地区受其伪政权影响，推行亲日卖国政策，配合日军侵略。；在日军扶植下于内蒙古西部建立伪蒙疆政权，统辖察哈尔、绥远等地，鄂尔多斯北部及杭锦旗一带曾受其伪政权影响，推行亲日附逆政策，配合日军统治与掠夺。；锡林郭勒盟苏尼特右旗人，抗日战争时期投靠日本，先后组织伪蒙古军政府、伪蒙古联盟自治政府、伪蒙疆联合自治政府，任主席，配合日军统治内蒙古中西部，其势力范围覆盖锡林郭勒盟及周边地区。；察哈尔部正白旗人，长期在锡林郭勒盟及察哈尔地区活动，1936年在德化（今化德）成立伪蒙古军政府，后任伪蒙疆联合自治政府主席，统辖包括锡林郭勒盟在内的蒙疆地区，与日军合作推行殖民统治。；在锡林郭勒盟及察哈尔地区组织伪蒙政权，与日本关东军合作，统辖包括太仆寺旗在内的察锡地区，推行亲日政策并协助日军统治。；锡林郭勒盟苏尼特右旗人，长期在锡林郭勒盟及察哈尔北部活动，1930年代投靠日本，先后组织伪蒙古军政府、伪蒙古联盟自治政府、伪蒙疆联合自治政府，统辖包括锡林郭勒盟在内的蒙疆地区，为日本侵略势力服务。；察哈尔部正白旗人，在锡林郭勒盟及察哈尔地区组织伪蒙政权，投靠日本，任伪蒙疆联合自治政府主席，配合日军统治内蒙古中西部，其势力范围覆盖锡林郭勒盟及正镶白旗一带。；锡林郭勒盟苏尼特右旗人，世袭苏尼特右旗札萨克郡王。1933年发起内蒙古自治运动，1936年在日本扶持下成立伪蒙古军政府，1937年改组为伪蒙古联盟自治政府，1939年任伪蒙疆联合自治政府主席，统治察哈尔、锡林郭勒等地，配合日军镇压抗日力量、推行殖民统治。；锡林郭勒盟苏尼特右旗人，抗战期间投靠日本，先后组织伪蒙古军政府、伪蒙古联盟自治政府、伪蒙疆联合自治政府，统治包括锡林郭勒盟在内的内蒙古中西部及察哈尔、晋北地区，配合日军镇压抗日力量。；察哈尔部正白旗人，长期在锡林郭勒盟及察哈尔地区活动，1936年成立伪蒙古军政府，1939年任伪蒙疆联合自治政府主席，辖锡林郭勒盟等地区，推行亲日政策，配合日军统治内蒙古中西部。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('08b28163051d4f76ad0a77acfd70609e','5f82d23ccd2e45fd9e59f76c92bcc9ad',1933,'伪蒙古军总司令、伪蒙疆联合自治政府副主席','率部投靠日军，参与组建伪蒙古军，驻防包头及绥远地区，配合日军进攻抗日武装，控制达尔罕茂明安一带。；率伪蒙古军多次进犯鄂尔多斯地区，参与围剿抗日武装，协助日军在伊克昭盟推行“治安肃正”，残害抗日军民。；率部投靠日军，参与组建伪蒙古军，在绥远、察哈尔及内蒙古西部配合日军作战与统治，其伪军活动范围覆盖鄂尔多斯周边地区。；率部投降日军，编入伪蒙古军，在绥远、鄂尔多斯周边地区配合日军作战，镇压抗日力量，残害百姓。；率部投靠日军，参与组建伪蒙古军，活动于绥远、察哈尔及内蒙古西部，其伪军势力曾覆盖鄂尔多斯周边地区，协助日军镇压抗日力量。；率部投降日军，组建伪蒙古军，配合日军进攻绥远、察哈尔等地，参与对鄂尔多斯及内蒙古西部抗日力量的镇压和扫荡。；原为东北军军官，后投靠日军，在锡林郭勒盟、察哈尔一带组建伪蒙古军，任总司令，参与日军对内蒙古中东部地区的控制与扫荡。；原东北军军官，后投靠日军，参与组建伪蒙古军，任总司令，率部配合日军侵占察哈尔、锡林郭勒等地，后任伪蒙疆联合自治政府副主席，是蒙疆伪政权主要军事头目。；原为东北军骑兵，1933年投靠日军，在热河、察哈尔、锡林郭勒一带组建伪军，任伪蒙古军总司令，配合日军进攻绥远、察哈尔等地，参与建立伪蒙疆政权。；率部在锡林郭勒、察哈尔一带配合日军作战，参与建立伪蒙政权，其伪军活动范围覆盖太仆寺旗周边地区。；原东北军骑兵，后投靠日军，在察哈尔、锡林郭勒一带组建伪蒙古军，配合日军侵占和统治内蒙古中西部，曾任伪蒙古军总司令，活动范围包括锡林郭勒盟地区。；原为东北军骑兵，1933年投靠日军，在热河、察哈尔、锡林郭勒一带组织伪军。1936年任伪蒙古军总司令，配合日军侵占绥远、锡林郭勒等地，参与百灵庙战役等，后任伪蒙疆联合自治政府副主席，为蒙疆伪政权主要军事头目。；原东北军骑兵，后投靠日军，在锡林郭勒盟、察哈尔一带组建伪蒙古军，配合日军侵占察哈尔、绥远等地，任伪蒙古军总司令，参与伪蒙疆政权，镇压抗日力量。；率部投靠日军，活动于察哈尔、张家口及周边地区，参与日军对察南、坝上地区的控制与扫荡，是伪蒙疆政权重要军事头目。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('796bce9b70b34841a46bce00126b3f98','529eba01fd3844d2a4780badaf25cb50',1937,'伪绥西联军总司令、伪包头维持会头目','包头沦陷后组织维持会，后任伪绥西联军总司令，在包头、固阳、达尔罕茂明安等地配合日军清乡、掠夺资源。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f529cbe5df984602894fd169e92286f2','7fe60a0e08e747819e43053afc3d9d27',1937,'伪包头维持会会长、伪蒙疆联合自治政府委员','包头沦陷后出面组织维持会，协助日军维持地方秩序，后进入伪蒙疆政权，参与对包头及周边旗县的殖民统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a12b27b77c924d0586d654b49fd6bb5e','25561457344c435aaa3b812455c00558',1937,'伪包头县县长','日军占领包头后出任伪县长，推行保甲制，征发劳工、粮食，配合日军对达尔罕茂明安等地的控制。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('18661a0eb312472f88102ecb00587d01','6687a4d3a75b4c3099f7cb5005501a4e',1937,'伪固阳县县长','在固阳及邻近达尔罕茂明安地区推行伪政，组织伪保安队，协助日军镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0c235c945ba142a48e07eda11243976b','7f72947b8e0948a785e49bb6979bf8fb',1937,'伪萨拉齐县县长','在萨拉齐及包头周边地区为日军征粮、征税，维持伪政权，间接控制达尔罕茂明安南部一带。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0d1d06ef894b4470bc6975cb19076943','838979c5881d455d9908a863bc24d449',1936,'伪蒙古军政府参议、伪蒙疆政权官员','参与百灵庙蒙古自治运动，后投靠日军，在伪蒙疆政权中任职，活动于包头、达尔罕茂明安等蒙古族聚居区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3aff2ecb3a034097bfa00096a34e91cb','c94f058ddf0448068e37a5d4ac1c1a8d',1936,'伪蒙古军政府委员、伪蒙疆联合自治政府参议','协助德穆楚克栋鲁普建立伪蒙政权，在包头及乌兰察布盟各旗包括达尔罕茂明安旗推行亲日政策。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5abf2c51c1ea4d648d84b99d24e61202','ae3b48ea9e8040088090d6b3522682e5',1937,'伪乌兰察布盟盟长','在日军支持下出任伪乌兰察布盟盟长，管辖达尔罕茂明安等旗，为日军征发牲畜、物资，镇压抗日力量。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9cf534a8058b40d9925d17c13e7156ea','0bd9c46f86d241fcb5b040ae9753ac3e',1937,'伪达尔罕茂明安旗旗长','在日军控制下出任伪旗长，协助日军在达尔罕茂明安草原建立据点、征收赋税、组织伪保安队。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6bb913dc71e34096a22f7565393dbdf5','2702b121aecb4d06983f5aa2899a28b3',1937,'伪达尔罕茂明安旗保安队队长','组织伪保安队配合日军巡逻，监视抗日活动，在达尔罕茂明安及包头北部地区为日军效力。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4f46537656a84d3089ff49fea3485473','ef6c08d0f52941eb82c78030ddb226af',1937,'伪包头警察局局长','在包头及周边旗县建立伪警察网络，搜捕抗日人员，协助日军维持殖民统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4568881b3b224f91ba05f5729916c0d2','3badb60840f84fca8e8d50b44ca905f1',1937,'伪包头商会会长','协助日军控制包头经济，为日军筹集物资、资金，参与对达尔罕茂明安等地畜产品的掠夺。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d8fef3af703942c48d87994056fcd4fc','164a8cacc10e44e098fbc2ca7d40df19',1937,'伪包头县教育会会长','在包头推行亲日奴化教育，编写伪教材，向包括达尔罕茂明安在内的周边地区传播亲日思想。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d03cca86116148b0aebc2299e8cc126e','47cac7a73af140d39ff53133e8cfe760',1938,'伪东亚同盟军总司令（后反正）','原东北军师长，投敌后任伪军职，在包头地区参与对抗日根据地的进攻，后因被日军猜忌而反正，但前期有助敌行为。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7dec60613c9a40d3921ee8672168cdfb','09e65a7dbae748caa1181ab2c8844755',1939,'伪包头市公署市长','在包头市任伪市长期间，推行日伪殖民政策，组织保甲制度，强征劳工，为日军提供物资，镇压抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('810225b4b7ec4cb792d53aa8d699ee04','8f4c6a82abd7490ab754fe15d2224dd0',1938,'伪蒙古军第1师师长','率伪蒙古军在包头周边驻防，多次参与对大青山游击队的围剿，杀害抗日干部和群众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('533166ed7b9e4d7eaaee1973b75d2951','77857f075ce44761869c5724589a4545',1937,'伪蒙古军第2师师长','在青山地区配合日军“扫荡”，烧毁村庄，掠夺牲畜，强迫牧民迁移，制造无人区。；蒙古族军官，投日后在呼和浩特、托克托一带驻防，配合日军进行“治安肃正”，屠杀抗日军民，强征民夫修筑工事。；在归绥（今呼和浩特）及周边地区率伪军配合日军作战，围剿大青山抗日根据地，破坏地下抗日组织，强征民夫修筑军事工事。；在张家口北部及赤城周边参与围剿八路军游击队，制造多起惨案。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('89522c577d9a4559a62df64198d68bb6','658599cc30054a62a54d125d10ea5a3a',1938,'伪绥西自治联军参谋长','协助王英指挥伪军，参与制定针对大青山抗日游击根据地的军事行动，多次率部袭击抗日武装。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('087450d8d25d45b8aa1016934a0f7d5d','26647d4bb91f4086a567e1a461c53d38',1936,'伪蒙古军参谋长、伪蒙疆政府军事部长','协助德王、李守信整编伪蒙古军，参与策划对呼伦贝尔及兴安北省等地的军事控制，为日军提供情报和兵员。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('23c44d0e76734fe78d1c841fee08c813','993cd83aa8c54ff38e0622e1de731309',1932,'伪兴安北省省长（呼伦贝尔地区）','在日本关东军扶植下出任伪兴安北省（今呼伦贝尔大部）省长，推行殖民政策，强制收缴民间枪支，组织伪警察镇压抗联和民众反抗。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c11e68d377044a49a4452c78d9099c4d','6dec6f2201c84d729ec0c0b13ca17e6e',1932,'伪兴安北省警务厅长','在呼伦贝尔地区主持伪警务，协助日军搜捕抗日分子，参与“清乡”行动，迫害达斡尔、鄂温克等各族群众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bfd15aa7fcab45ae81e487ff124dea3b','dddf6075e9614f79add415cba2b3c0c4',1932,'伪兴安北省省长（早期）','曾任伪兴安北省省长，后因对日本关东军不满被日军以“通苏”罪名处决，但其前期在伪职期间执行了日本殖民统治政策。；曾任伪兴安北省省长，后因与日本关东军产生矛盾，被指控“通苏通蒙”罪名，于1936年被日军处决，但其前期曾协助日伪建立统治。；曾任伪兴安北省省长，后因与日本关东军矛盾被处死，但前期曾协助日军建立伪政权','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('63870fe04087433eb64ffa0040b98454','56be20121a7140d6a08fc09b8cf74edb',1932,'伪兴安北省参事官','作为日本驻伪兴安北省参事官（实际为日本人，但此处按历史记录列入），协助日军控制呼伦贝尔行政和军事，镇压抗联三进呼伦贝尔的行动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fcd85d17d2f64bd199414a7f53006864','b4228f779da94d8393d6fc8edea729d0',1932,'伪索伦旗旗长（今鄂温克旗）','在呼伦贝尔索伦旗（今鄂温克族自治旗）任伪职，强迫牧民缴纳“出荷粮”，为日军提供畜力、皮毛等战争物资。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5ea0d142b0a8404f9bdb6db93d4d6142','47de464a48a642ae8ef54e5ee842ae8e',1932,'伪布特哈旗旗长（今莫力达瓦旗）','在呼伦贝尔布特哈旗推行日伪“保甲制度”，组织伪自卫团，协助日军围剿抗联小分队，迫害达斡尔族抗日群众。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cb8ff55097364a4382c4c3d1645f5262','dddf6075e9614f79add415cba2b3c0c4',1932,'伪满洲国兴安北省省长','达斡尔族，原为呼伦贝尔副都统衙门帮办，1932年伪满洲国成立后出任兴安北省省长，驻海拉尔，管辖今呼伦贝尔地区。参与伪满地方政权建设，后因在1936年与日本关东军矛盾激化被处决。；达斡尔族上层，曾任伪兴安北省省长，驻海拉尔，管辖包括新巴尔虎左旗在内的呼伦贝尔地区，后因与日本矛盾被处决；其任职期间代表伪政权对当地进行统治。；达斡尔族上层，曾任伪兴安北省省长，驻海拉尔，参与伪满洲国对呼伦贝尔地区的统治；后因与日本矛盾被处死。；达斡尔族上层，曾任伪兴安北省省长，管辖呼伦贝尔地区，后因与日本矛盾被处决，但此前曾附逆任职。；达斡尔族上层，曾任伪兴安北省省长，驻海拉尔，协助日本统治呼伦贝尔地区；后因与日本矛盾被处决，但其前期附逆活动明确。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d0ed8fce295c40c0a9ea242b2c9e99c1','8625223b5393415fabb6dcd24b19bf94',1936,'伪满洲国兴安北省省长、伪满参议','凌升被处决后接任伪兴安北省省长，继续为伪满洲国统治呼伦贝尔地区服务，直至1945年日本投降。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ac225a346ff942e2910540871ec694f7','0b434528d9424531a735ad31e505d490',1932,'伪满洲国兴安北省警备军司令官','蒙古族，曾任伪兴安北省警备军司令官，统率伪军配合日军在呼伦贝尔地区维持治安、镇压抗日活动。；蒙古族上层，任伪兴安北省警备军司令官，统领伪军配合日军在呼伦贝尔地区镇压抗日力量，维持殖民统治。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6d666d34308d4f06a45035cf1c2b3a01','2eb96a1f022e434e830b2d5e2d6b720b',1932,'伪满洲国兴安北省警备军司令官、伪满军事部大臣','达斡尔族，曾任伪兴安北省警备军司令官，后升任伪满军事部大臣，参与伪满军事统治，其活动范围包括呼伦贝尔地区。；达斡尔族，曾任伪兴安北省警备军司令官，后升任伪满军事部大臣，在呼伦贝尔地区招募伪军，配合日军作战。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c93f4a906db048d6a156eec8af913090','25e14c6523f347349389d63d8a7056ac',1932,'伪满洲国兴安北省警备军军官','达斡尔族，在伪兴安北省警备军中任职，参与伪军活动，配合日军在呼伦贝尔地区的统治。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fd607fd8718243919ab3182a40a32ad0','64f7e2c362324f7c8ebbecd6fb02d6e4',1930,'伪满洲国兴安北省警备军军官','蒙古族，在伪兴安北省警备军中任职，参与伪军活动，其活动范围覆盖呼伦贝尔地区。；甘珠尔扎布之弟，在伪兴安北省警备军任职，参与日军在呼伦贝尔地区的军事行动。','无明确职位或一般帮凶','hanjian');
