INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aaa108552b0f40e49b27021aa08c2143','3a6b32dfcd8d4574b517f12a262e67d0',1932,'伪扎兰屯维持会会长','扎兰屯地区在1932年日军占领后成立维持会，会长由当地士绅担任，协助日军维持地方秩序、征发物资，具体姓名史料记载不详。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a9e95948c5d54a19a0f2f5ce82265ba5','c43ce121efa84a0c83c453f0175dc0d5',1932,'伪扎兰屯警察署长','伪满洲国在扎兰屯设立警察署，署长由当地人担任，负责地方治安、镇压抗日活动，具体姓名史料记载不详。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9e2bbcd73e5f4a34a28f4a00a67671ef','9f819e267ddb48a3bfd565fd44fd40aa',1932,'伪扎兰屯保甲长','伪满洲国在扎兰屯推行保甲制度，保甲长负责户口管理、征发劳工、协助日军统治，具体姓名史料记载不详。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1be88cc2487241c1b0029d6ee33d8c4f','dddf6075e9614f79add415cba2b3c0c4',1932,'伪满洲国兴安北省省长、伪满参议府参议','达斡尔族上层人物，九一八事变后投靠日本，参与筹建伪满洲国，任伪兴安北省省长，管辖包括呼伦贝尔地区在内的兴安北省，推行日本殖民统治政策，后因与日本发生矛盾被处决。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('53333d7deed34850a3709beee259ef28','8625223b5393415fabb6dcd24b19bf94',1936,'伪满洲国兴安北省省长','继凌升之后任伪兴安北省省长，继续为日本侵略者服务，在呼伦贝尔地区推行伪满政令，协助日本掠夺当地资源。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('61ff9601919e4add9ecb30fe3d46dc56','25e14c6523f347349389d63d8a7056ac',1940,'伪满洲国兴安北省警备军司令官','达斡尔族，任伪兴安北省警备军司令官，在呼伦贝尔地区指挥伪军协助日军维持治安，镇压抗日活动。','基层头目','hanjian');
