INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d3965a18e8d844f2bfe2706aa049b439','eb166a17cf664e83aa52590be3bac98d',1932,'伪满洲国兴安局官员、伪兴安军将领','蒙古族上层人物，九一八事变后投靠日本，参与策划内蒙古独立活动，任伪满洲国兴安南分省省长、兴安局总裁等职，组织伪兴安军配合日军在呼伦贝尔及内蒙古东部地区进行统治和镇压抗日力量。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aa04698e5e1f4876b045830c0bb8e1ea','64f7e2c362324f7c8ebbecd6fb02d6e4',1930,'伪满洲国兴安军军官','甘珠尔扎布之弟，投靠日本，在伪兴安军中任职，参与日军在呼伦贝尔地区的军事行动和对当地蒙古族民众的控制。；甘珠尔扎布之弟，投靠日本，在伪兴安军系统任职，参与呼伦贝尔地区的伪军活动，协助日军控制地方。；甘珠尔扎布之弟，参与伪兴安军组建，配合日军在呼伦贝尔地区镇压抗日力量。；甘珠尔扎布之弟，投靠日本，在伪兴安军任职，参与日军对呼伦贝尔及内蒙古东部地区的统治和军事行动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8caa0e8fdcf24f9382d3ed178ebd6f2c','8625223b5393415fabb6dcd24b19bf94',1932,'伪满洲国兴安北分省官员、伪呼伦贝尔地方维持会头目','呼伦贝尔地区蒙古族上层，投靠日本，在伪兴安北分省任职，参与伪政权对呼伦贝尔各旗包括新巴尔虎右旗的统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dab0595be97841eb8be25f57cc3967f7','241cbddbaf1c440da9f2f071dcc10b8a',1930,'伪新巴尔虎右旗旗长','在新巴尔虎右旗担任伪旗长，听命于伪满洲国兴安北分省，协助日军和伪政权在当地推行保甲制度、征收物资、控制牧民。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2c4cc1c772574f199131550b31ac0dea','d1407109012845639fa3ebd4ce16cf0d',1930,'伪满洲国兴安北分省警备队军官','在呼伦贝尔地区担任伪警备队军官，配合日军维持治安，镇压抗日活动，活动范围覆盖新巴尔虎左右旗一带。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('135fb0240037449e9a9eb2bc2250fb2c','25e14c6523f347349389d63d8a7056ac',1930,'伪满洲国兴安北分省警备队司令','曾任伪兴安北分省警备队司令，驻海拉尔，统辖呼伦贝尔地区伪军，参与对苏蒙边境的警戒和对当地抗日力量的镇压。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('47f9bc9230df4daaa8d8d17ca7200b74','22362eee60eb4601831c89c88ad17084',1932,'伪呼伦贝尔地方维持会成员','呼伦贝尔地区蒙古族上层，参与组织伪维持会，协助日军接管地方政权，在新巴尔虎右旗等牧区推行伪政权的政策。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d6b32981747841499ed6c4d990c93226','69cf3b2287e546e59fa4554583af0c6f',1930,'伪新巴尔虎右旗伪警察署长','在新巴尔虎右旗担任伪警察署长，负责当地治安，协助日军征用牧民牲畜、物资，监控牧民行动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('16b76332b58148c59ff6241c643ca18a','6ac45c4c648e4eb5afbd66ec5b651229',1930,'伪满洲国兴安北分省教育官员','在呼伦贝尔地区担任伪教育官员，推行奴化教育，向蒙古族青少年灌输亲日思想，活动范围包括新巴尔虎右旗。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ee59c0a2eca4499b92be586cd2bfc8da','eb166a17cf664e83aa52590be3bac98d',1930,'伪满洲国兴安军军官、伪兴安北省警备军司令','蒙古族上层出身，早年参与策划内蒙古独立活动，后投靠日本关东军，在伪满洲国任职，参与组建和指挥伪兴安军，配合日军在呼伦贝尔及新巴尔虎左旗一带维持统治、镇压抗日力量。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fd24c75c58234a1daf0e66dd4f9e67be','8625223b5393415fabb6dcd24b19bf94',1930,'伪兴安北省省长、伪满洲国参议','继凌升后任伪兴安北省省长，继续在海拉尔及呼伦贝尔地区为伪满洲国和日本统治服务。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b9f31ba1627a4b6b902714f481348b52','25e14c6523f347349389d63d8a7056ac',1930,'伪兴安北省警备军军官','在伪兴安军系统任职，参与呼伦贝尔地区伪军警活动，配合日军维持地方治安。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b6e7357d832d418c86d9b41304216619','22362eee60eb4601831c89c88ad17084',1930,'伪新巴尔虎左旗旗长','在伪满洲国时期担任新巴尔虎左旗旗长，执行伪政权政令，协助日本控制当地牧区。','无明确职位或一般帮凶','hanjian');
