INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1ac9c02e446d40eaa7531235fa2179b1','eb86eab7b26f434da97dd77ce00b4c8c',1930,'伪新巴尔虎左旗维持会成员','在伪政权基层维持会中任职，协助日军征发物资、控制牧民。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4c5d2eeaf9b444d099adc7e246245a9c','5caa65ca4b9a4b0fa899f44f4c660d59',1930,'伪呼伦贝尔地区保甲长','在呼伦贝尔牧区担任伪保甲长，执行伪满洲国保甲连坐制度，协助日军统治基层。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dd335d2927e14ebb859285db0b8f8736','7fbc5bba07664eaeb5bb4b15cbd692f7',1930,'伪兴安北省官员','在伪兴安北省任职，参与呼伦贝尔地区行政事务，为伪满洲国和日本侵略者服务。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1f09d1713e1b4db0b131140eda27efc6','6e20aaf31c5b4d2fbc9256c5906605e7',1932,'伪兴安北省警务厅特务科人员','在根河地区（时属伪兴安北省）参与镇压抗日联军和当地民众，协助日军搜集情报，迫害抗联地下工作者。具体姓名因档案缺失未能确认。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('87cc031107cf47bca0b17ceaf03812bd','6e20aaf31c5b4d2fbc9256c5906605e7',1932,'伪额尔古纳左翼旗（今根河市一带）旗公署官员','在伪满统治下，参与推行殖民政策，强征劳工，配合日军“讨伐”抗联小部队，并参与对鄂温克、鄂伦春等民族的监控。具体姓名未见于公开史料。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('87979474bbfd4097a63094c73ec93ea8','37fae451a3544b8d965985a7bc6905f0',1932,'伪海拉尔市市长','任伪满海拉尔市市长期间，推行日伪殖民政策，协助日本关东军镇压当地抗日力量，强征劳工修建军事设施。','市县厅局级','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c6cf8d563ded4a97882e883da1b5eb09','6dec6f2201c84d729ec0c0b13ca17e6e',1932,'伪兴安北省省长','作为蒙古族上层投靠日本，任伪兴安北省省长，配合日军在呼伦贝尔地区实施“治安肃正”，迫害抗日志士，强制推行奴化教育。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cab422b7a5474622be5403e273fcff57','56be20121a7140d6a08fc09b8cf74edb',1932,'伪兴安北省警务厅长','掌管伪兴安北省警察机构，协助日本宪兵队搜捕抗日地下人员，参与镇压海拉尔地区反满抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9440a7cfb4614f51a7cdfe73c8a1ef5d','7c05802530934763a5d6c820db0bac2f',1933,'伪海拉尔警察署署长','效忠日伪政权，指挥警察镇压当地民众反抗，为日军提供情报，参与抓捕苏联间谍和抗日分子。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4bcdad78fb31456bb17fbacd420760b8','0b877cf604a04a3cb0bf8f6eb26dff85',1932,'伪兴安北省参事官','作为日伪政权在呼伦贝尔的蒙古族官员，积极推行“日蒙亲善”宣传，协助日军收编地方武装，破坏抗日联军活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b6496b6b27124c9db7f28f488f9d155f','bea392fa224248a8a2326ba2ffe52e16',1935,'伪海拉尔市公署总务科长','管理伪市公署日常事务，配合日军经济掠夺，强制收缴民间金属和粮食，供日军军需。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ddb61593cd6248e7bb541f1cbe5b7fe7','25e14c6523f347349389d63d8a7056ac',1938,'伪兴安军第10团团长（后反正）','曾任伪兴安军军官，初期效忠日伪，参与镇压抗日武装，1944年率部起义反正，但此前有助纣为虐行为。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2bffea6eee214b3bb784684e8130ceed','64f7e2c362324f7c8ebbecd6fb02d6e4',1931,'伪兴安军军官','蒙古族贵族出身，投靠日本后任伪兴安军军官，参与围剿东北抗日联军在呼伦贝尔的游击活动。；在呼伦贝尔地区统领伪兴安军，配合日军进攻苏联边境及抗日武装；与甘珠尔扎布同为早期投日蒙古王公子弟，在伪兴安省及赤峰周边地区协助日军维持治安、清剿抗日力量。；甘珠尔扎布之弟，九一八事变后投日，在伪兴安军任职，参与内蒙古东部地区伪军活动，配合日军控制赤峰及周边旗县。','无明确职位或一般帮凶','hanjian');
