INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('804b10da576e4b96abebfda93413bc0e','31c8c265db4b476d8224873c1e01d81c',1930,'伪蒙疆政权官员','在伪蒙疆政权中任职，参与日本对内蒙古的殖民行政。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('566ae64b3d3d4d25ad43f110ba18c12c','8e74fddbe3c3430485da2d99f77c25e9',1930,'伪蒙疆政权官员','在伪蒙疆政权中任职，协助日伪统治内蒙古地区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e65e1ff4d4374c5f8b295b5230775f0d','8f1dd12e548b4c4f866dd743c3377896',1937,'伪华北政务委员会委员长','华北地区重要汉奸头目，其伪政权体系影响波及内蒙古中东部部分地区。；作为华北伪政权最高头目，其统治范围包括顺义，推行治安强化运动，配合日军“扫荡”顺义抗日根据地。；虽主要管华北，但其伪政权与安徽伪政权有协作，影响安庆、大观。；安徽合肥人，北洋政客，抗战后投敌，任伪华北政务委员会委员长，统辖华北伪政，与安徽沦陷区伪政有联系。；安徽合肥人，投敌后任伪职，在华北推行附日政策，与安徽籍汉奸网络有联系。；安徽合肥人，投靠日本，在华北伪政权中任要职，对安徽籍人员有影响，其活动与安徽沦陷区有间接关联。；虽主要活动于华北，但其伪政权影响安徽北部，与芜湖鸠江地区汉奸有勾结。；华北头号汉奸，其伪政权统治范围覆盖山东，包括威海、文登地区，推行保甲、治安强化运动，镇压抗日活动。；虽主要活动于北平，但其伪政权体系覆盖山东济南，推行治安强化运动，镇压抗日。；华北头号汉奸，推行日伪政令至山东济宁，进行奴化宣传和经济掠夺。；华北地区最高伪政权头目之一，其统治涵盖山东，推行治安强化运动，配合日军在山东包括济宁地区的殖民统治。；北洋政客，抗战期间投敌，主持伪华北政务，推行保甲、治安强化运动，其伪政权体系覆盖山东聊城、茌平等地，征粮征丁，镇压抗日力量。；华北伪政权后期首要人物，统辖包括山东在内的华北沦陷区，青岛、平度伪政权受其节制。；统辖华北伪政权，包括山东、青岛，推行治安强化运动，镇压抗日。；接替王克敏任伪华北政务委员会委员长，统辖包括山东在内的华北伪政权，推行日军政策。；继王克敏后任伪华北政务委员会委员长，继续推行华北伪化统治，影响覆盖山东、青岛地区。；华北伪政权后期头目，其管辖范围包括山东，与青岛伪政权有上下级关系。；华北地区重要汉奸头目，其伪政权体系覆盖山西北部，推行日军殖民政策。；虽以华北为主，但多次到南京鼓楼区与汪伪政权协调合作。；安徽合肥人，北洋旧官僚，抗战期间投敌，在华北伪政权中任要职，配合日军掠夺资源、镇压抗日。；华北伪政权头目，其伪化体系与华中包括江西九江的伪政权有联系，配合日军掠夺物资。；作为华北伪政权最高头目，其统治范围涵盖廊坊地区，支持日军“三光政策”，并组织伪军配合扫荡。；作为华北伪政权最高头目，其统治范围覆盖廊坊经开区，推行奴化政策，协助日军征粮征兵。；统辖华北伪政权，包括河南部分地区，推行奴化教育，征敛物资支持日军。；华北伪政权头目，其政令覆盖河南部分地区，推行治安强化运动与物资统制。；安徽合肥人，抗战期间投敌，任伪华北政务委员会委员长，管辖包括河南在内的华北地区伪政权，推行奴化教育、经济掠夺，对河南民众造成深重灾难。；虽驻北平，但其伪政权统辖河南，开封伪政权受其节制，推行华北伪化政策。；虽主要在华北活动，但其伪政权体系影响波及湖北部分沦陷区，参与日伪统治与资源掠夺。；华北伪政权头目，其伪政权体系与湖北伪政权有联系，参与日军对沦陷区的整体统治。；安徽合肥人，北洋旧官僚，抗战期间投敌，任伪华北政务委员会委员长等职，其活动虽主要在华北，但与湖北黄冈地区无直接关联，仅作为湖北籍相关汉奸背景列出。；伪华北政权头目，其伪化政策与湖南沦陷区伪政权有呼应，间接影响岳阳地区伪统治。；安徽合肥人，抗战期间投靠日军，历任伪华北政务委员会委员长等职，在华北地区推行伪化统治。；其伪政权曾向贵州派遣密使，拉拢地方军阀，息烽附近有其联络人员出没。；在华北伪政权中任职，推行日军侵略政策，其伪政权体系延伸至陕西沿黄河地区，对榆林、府谷一带进行政治渗透。；长期在华北伪政权中任职，配合日军推行治安强化运动，镇压抗日力量，其伪政权体系对陕西周边及华北地区有影响。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1060a55e52a945d5ab8cf05eac58701a','a52029b094a745e58352e53920a36323',1930,'伪蒙疆联合自治政府主席','即德穆楚克栋鲁普，内蒙古最重要的附逆头目之一，建立伪蒙疆政权，配合日本统治内蒙古。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cf6b5684856244a29ed743e9707aea2f','6dec6f2201c84d729ec0c0b13ca17e6e',1932,'伪满洲国兴安北省省长','曾任伪满洲国兴安北省省长，在呼伦贝尔地区推行日伪殖民统治，协助日本关东军镇压当地抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('121bb10419df4967a236d42b3847551e','dddf6075e9614f79add415cba2b3c0c4',1932,'伪满洲国兴安北省省长（后因反日被处决）','初期投靠日本，任伪兴安北省省长，后因反对日本移民政策及秘密联络抗日势力，于1936年被日本关东军以“通苏”罪名处决。；原呼伦贝尔副都统，初期投日任伪省长，后因暗中支持抗联及蒙古独立运动，被日军以“通苏”罪名处决于齐齐哈尔。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0862cca8a6be416e884219b4effcf2a1','56be20121a7140d6a08fc09b8cf74edb',1932,'伪满洲国兴安北省警务厅厅长','在呼伦贝尔地区担任伪警务厅长，协助日本宪兵队搜捕抗日分子，镇压牧民反抗。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0e587bd276014d51a304ca367fa6f510','7c05802530934763a5d6c820db0bac2f',1932,'伪满洲国兴安北省公署参事','参与伪满政权在呼伦贝尔的行政事务，为日军提供当地情报，协助推行“治安肃正”政策。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fa7eab98369e42a3a2f750a71ae4e931','0b877cf604a04a3cb0bf8f6eb26dff85',1932,'伪满洲国兴安东省莫力达瓦旗旗长','在莫力达瓦地区任伪旗长，强制征收粮食和牲畜，为日军提供物资，镇压当地达斡尔族抗日活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b7a42899de56421cb74916c1f36076bb','bea392fa224248a8a2326ba2ffe52e16',1933,'伪满洲国莫力达瓦旗警察署署长','在莫力达瓦旗组织伪警察，协助日军清乡，逮捕并杀害抗日地下工作者。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9ebb3b1f3dd14a36ac63f2260e8e11a6','9a71a3b895854c0496b76fe9a6fc7449',1932,'伪满洲国兴安东省警备军军官','在呼伦贝尔地区指挥伪军参与“讨伐”抗日游击队，烧毁村庄，掠夺财物。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bf46c2e337f7467dbfbc180759c6632a','8007ee226eb84783b2102ba10d92cc43',1935,'伪满洲国莫力达瓦旗公署财务科长','负责为日伪政权征收苛捐杂税，强征劳工，导致当地民众负担沉重。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3e00fdbad1cf4b2a8eeab577c7aad987','eb166a17cf664e83aa52590be3bac98d',1930,'伪满洲国兴安局官员、伪兴安军军官','蒙古族上层人物，投靠日本关东军，参与策划内蒙古独立活动，在伪满洲国任职，协助日军控制呼伦贝尔及内蒙古东部地区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7a394bf15d114ba494944b01903fed40','25e14c6523f347349389d63d8a7056ac',1930,'伪兴安军军官、伪第十军管区司令','达斡尔族，在伪兴安军任职，后任伪第十军管区司令，驻防呼伦贝尔，配合日军维持统治。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3c87ea829656457d91e18654832d3e9b','7de94d0fd0d741a0a5a02241c87f3514',1930,'伪兴安北省警备队军官','在伪兴安北省警备队任职，参与维持呼伦贝尔地区治安，协助日军镇压抗日活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('61a4f25ed8bb444594fedb368574bbe3','0e9b16f3dd4144fb86128a233efe964f',1930,'伪满洲国地方维持会头目','在呼伦贝尔地区组织维持会，协助日军占领和控制地方。；在呼伦贝尔地区参与伪政权维持会活动，协助日军征粮、派夫和治安控制。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5869549b7b31489a9669dee1e3d67732','eb166a17cf664e83aa52590be3bac98d',1931,'伪满洲国兴安局官员、伪兴安军头目','蒙古族上层人物，九一八事变后投靠日本，参与策划内蒙古东部地区所谓‘自治’，在伪满洲国任职，协助日军控制呼伦贝尔及兴安地区，组织伪军警镇压抗日力量。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('591b923f69e548d1b13a69e81a22233c','8625223b5393415fabb6dcd24b19bf94',1930,'伪满洲国兴安北省官员','在伪兴安北省任职，参与日本对呼伦贝尔地区的殖民统治和基层控制。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8d5bf9c6c5d04071b7be08cef961785a','25e14c6523f347349389d63d8a7056ac',1930,'伪满洲国兴安军军官','在伪兴安军任职，参与日军在呼伦贝尔地区的军事行动和治安肃正。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('543d15ff6a284a49b1b1259e6c5845c7','f59ccdd9a4164c3ea3b028cb6cdac5be',1930,'伪满洲国兴安北省警正','在伪兴安北省警察系统任职，协助日军镇压呼伦贝尔地区抗日活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('406e84896cda4244aab74056da324ab2','c904a3bb584e47459dd2323f9459412e',1930,'伪满洲国阿荣旗伪警察署长','在阿荣旗地区担任伪警察头目，配合日军和伪兴安军对当地抗日武装进行搜捕和镇压。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fb8b9da0ee6b4366b2a99b237a36830d','ba307a71c66a4d0995686ad3b1fc5f41',1930,'伪满洲国阿荣旗伪保长','在阿荣旗基层担任伪保长，协助日伪政权征粮、抓丁、监视民众，维持殖民统治秩序。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('046cd5922b8b4deb8f1fdec7a267bafe','a8d01b3043bf49f0afdda54d2807c7e0',1930,'伪满洲国呼伦贝尔地区维持会会长','在呼伦贝尔地区组织维持会，协助日军接管地方、维持治安和征集物资。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ce3f302aada944cdbac7a4ef1a360fa5','6dec6f2201c84d729ec0c0b13ca17e6e',1932,'伪满洲国兴安北分省省长','在陈巴尔虎旗及呼伦贝尔地区推行日本殖民政策，协助日伪政权统治当地蒙古族牧民，镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0bd7c92a73514827b2f3d6b5b0aae24d','dddf6075e9614f79add415cba2b3c0c4',1932,'伪满洲国兴安北分省省长（后任）','初期为日伪效力，后因与日本关东军产生矛盾被处决，但此前在陈巴尔虎旗地区执行过日伪行政命令。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e01aa2e9f42644a484cb75f5461f9395','a015466a3993464aadf4ecc5bf243e6d',1930,'伪兴安北省警务厅厅长','在陈巴尔虎旗地区组织伪警察力量，协助日军清剿抗日武装，抓捕抗日志士。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1f7cc8b918f5420483b556c1362ffa77','6715ff6a053b416c9deef129b169c6a9',1932,'伪陈巴尔虎旗旗长','作为伪旗长，直接执行日伪征粮、征兵及“治安肃正”政策，压迫当地牧民。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7f1956e6fbca4a08b2cce314fca933c0','4230c96db2c241ff9eee17c2fd43bc2b',1930,'伪陈巴尔虎旗副旗长兼警务科长','协助日军在陈巴尔虎旗建立情报网络，参与镇压当地反抗活动。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0b16d0702f11436cb1d162c8139ed60f','26647d4bb91f4086a567e1a461c53d38',1932,'伪满洲国兴安北省省长','呼伦贝尔地区（今额尔古纳市及周边）的蒙古族上层，任伪满兴安北省省长，协助日本关东军管理额尔古纳河沿岸防务，镇压当地抗联及牧民反抗。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cbab89a44ea34faca631b0fc39b05c3c','dddf6075e9614f79add415cba2b3c0c4',1932,'伪满洲国兴安北省省长（前期）','呼伦贝尔索伦旗贵族，初任伪兴安北省省长，后因与日本关东军矛盾被处决，但其任职期间曾配合日军清剿额尔古纳地区抗日武装。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('631ee23828964060a59da63df40a5ebf','6dec6f2201c84d729ec0c0b13ca17e6e',1932,'伪满洲国兴安北省警务厅长','呼伦贝尔籍，在额尔古纳及三河地区组织伪警察，协助日军搜捕抗联地下人员，参与“讨伐”苏联间谍网络。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('22e0ab62b29449139ea1a6f8b19f639f','a015466a3993464aadf4ecc5bf243e6d',1935,'伪满洲国额尔古纳左翼旗旗长','额尔古纳本地蒙古族头人，投靠日伪后任旗长，强制推行“粮谷出荷”，为日军提供物资，并举报抗日民众。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2d84d3747e8f4c4aa805d0404805c857','6fd63b9448604ccd970dd311162f77e0',1937,'伪满洲国额尔古纳右翼旗旗长','在额尔古纳河右岸地区协助日军建立“集团部落”，隔离民众与抗联联系，参与迫害苏联侨民及抗日嫌疑者。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fa21e4341bd04773a91dcac06bf5e787','25e14c6523f347349389d63d8a7056ac',1938,'伪满洲国兴安军第9团团长','呼伦贝尔籍达斡尔族军官，率伪兴安军驻防额尔古纳地区，参与对苏边境侦察及镇压当地抗联小分队，后于1945年反正。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('63b41165f7d94640b8b196925697a9df','c904a3bb584e47459dd2323f9459412e',1940,'伪满洲国额尔古纳地区保安队队长','汉族，原为地方土匪，投靠日军后任保安队长，在三河、室韦一带抓捕抗联交通员，协助日军建立“防谍网”。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0f1afe72f34147e8a1ff054739ceef1e','5ab361f3d1a54b50854f97f3f2aa96ce',1939,'伪满洲国额尔古纳警察署署长','朝鲜族，在额尔古纳地区残酷镇压抗日活动，多次带队突袭抗联宿营地，并参与“特别治安”行动。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5a783b57128647d3ae5a8a670798271c','b86083bd13c04af7ae64c9ee8b5ee802',1936,'伪蒙古军政府秘书长、伪蒙疆政府政务院院长','德王心腹，参与伪蒙政权组织与运作，协助日军管理内蒙古地区，镇压抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1fede55ca2334e008c1abf243193ea8b','c94f058ddf0448068e37a5d4ac1c1a8d',1936,'伪蒙古军政府财政部长、伪蒙疆政府经济部长','蒙古族上层，投靠日本，负责伪蒙政权财政与经济掠夺，为日军侵华提供物资支持。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b681bf4ffc344538843090ea3f717e85','993cd83aa8c54ff38e0622e1de731309',1936,'伪蒙古军第一军军长','原地方武装头目，投日后任伪蒙古军高级军官，参与进攻绥远抗日部队，残害百姓。；率伪蒙古军驻防绥远及新城一带，多次参与日军对抗日游击队的“扫荡”，在归绥周边制造多起屠杀事件。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('44898a93130a4e9aa4e8cbc06132e5a5','77857f075ce44761869c5724589a4545',1936,'伪蒙古军第二军军长','投靠日军，率伪蒙古军配合日军扫荡呼和浩特周边地区，参与镇压抗日游击队。；驻扎呼和浩特新城地区，协助日军维持治安，抓捕并刑讯抗日地下工作者，向日军提供情报。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e9597f5393c740948dd48ec52891d8e5','27fc6b8271be48088866d95a04838ec2',1937,'伪蒙古军师长','蒙古族军官，投靠日军，在呼和浩特及乌兰察布一带驻防，协助日军维持殖民统治。','市县厅局级','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a9ac86b1c61a4db5815b4924d08c9f01','13e803496ecd49b288e5106f48f4ba29',1937,'伪绥远省公署警务厅长','原绥远警察头目，投日后任伪警务厅长，协助日军搜捕抗日人士，镇压民众反抗。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5f9f0ce172d04bbe9dfaea210fdb19c0','25561457344c435aaa3b812455c00558',1937,'伪归绥市市长','投靠日军，任伪归绥（今呼和浩特）市长，推行日伪政令，强征劳工，搜刮民财。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('05e7ceaee8f54aff8585db20f87fd852','6a264c1418d54ed0837465ea0e5b3da0',1937,'伪归绥县知事','投日任伪归绥县知事，协助日军实施保甲制度，迫害抗日家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('108d582a7c3e49088390d98c66b3f8aa','5c3a0b5fe8c74170af1cdfe57ab6537e',1938,'伪蒙疆政府司法部长','原绥远地方官僚，投日后任伪蒙疆司法部长，制定镇压抗日法令，迫害进步人士。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0c1032bd89324192b08fe6365443c623','6ad1b280d7654edd89e3b7c53bf3e430',1938,'伪蒙疆政府交通部长','投靠日本，负责伪蒙疆交通建设，为日军军事运输提供便利。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b0f5aa03e92148ea94c64bbb48387dc5','26647d4bb91f4086a567e1a461c53d38',1937,'伪蒙古军总参谋长','蒙古族军官，投日后任伪蒙古军总参谋长，策划军事行动对抗抗日武装。；原东北军军官，投日后任伪蒙古军总参谋长，策划多次对绥远抗日根据地的“围剿”，在归绥城防和玉泉区一带布设特务网。；在呼和浩特地区参与策划多次对抗日游击队的围剿，协助日军建立伪警察体系，迫害抗日家属，为日军提供蒙古族士兵招募服务。；参与策划伪蒙古军在锡林郭勒及二连浩特地区的军事行动，协助日军建立情报网。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('865c7f09a1f94b8ead63a21cd6d1508a','3a09ae0f7f294a118069ecfbec5ba35b',1937,'伪蒙古军第三军军长','德王亲信，率伪蒙古军驻守绥东地区，参与多次扫荡行动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5bf09a9dd6344a3cbe39bc8dd1296192','838979c5881d455d9908a863bc24d449',1938,'伪蒙疆政府内政部长','投日任伪内政部长，推行户籍管制和奴化教育，镇压抗日宣传。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e7a48a32090945eaafd10f64488e9419','ae3b48ea9e8040088090d6b3522682e5',1937,'伪蒙古军师长','率伪军驻呼和浩特周边，协助日军清乡，杀害抗日群众。','市县厅局级','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2cc9ac0746e24d299a184fd86c598975','d566dc108e3e455eb9267bb5683e9461',1937,'伪绥远省公署民政厅长','投日后管理伪绥远民政，推行日伪保甲连坐制度，迫害百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('96579e89f5d640bbb53cc39654ce896d','12a8b4767b1e4a989997caabbb41d83a',1939,'伪绥西自治联军副司令','原晋军军官，投日后协助王英指挥伪军，进攻大青山游击队。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6013363bf68e45ed9f3c8a7d783dd0b1','b20b75e3a839472699d4a3cb0593b9fe',1937,'伪归绥市（今呼和浩特）警察局长','在归绥市任职期间，为日军搜捕抗日志士，镇压民众反抗，协助维持伪政权治安。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('96392725d6d54e949e0cfe5779b84ab9','35fa6f7aec904e2e92846140741b1499',1938,'伪归绥县知事','任伪归绥县知事期间，强征民夫、粮食供日军使用，推行保甲制度，迫害抗日家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f69402e9de11459ea76750d7d751083f','12a8b4767b1e4a989997caabbb41d83a',1939,'伪绥远省公署参事','原晋军军官，投日后在绥远省公署任职，参与策划对抗日武装的围剿行动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('35cd4b75c8804529a19735294914c99a','78198cf336e24d25a8e52cd58ddf4575',1936,'伪蒙古联合自治政府主席、伪蒙疆政府主席','锡林郭勒盟苏尼特右旗人，在日本支持下先后建立伪蒙古军政府、伪蒙古联合自治政府，定都归绥（今呼和浩特），统治包括和林格尔在内的绥远地区，推行亲日卖国政策，征粮征兵，镇压抗日活动。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('890e38343dc84ec389ed61862d47fc3f','7fe60a0e08e747819e43053afc3d9d27',1937,'伪蒙古联合自治政府副主席、伪察南自治政府最高委员','原为察哈尔省商人，日军占领张家口后组织维持会，后任伪察南自治政府最高委员、伪蒙疆政府副主席，参与伪蒙疆政权对绥远、呼和浩特地区的统治与经济掠夺。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1e886f0b76d4450492a1d70d44aa6338','f27fdea68c0f4c87901d2593feda5141',1937,'伪蒙古联合自治政府副主席、伪晋北自治政府最高委员','原为山西大同地方士绅，日军占领大同后组织维持会，后任伪晋北自治政府最高委员、伪蒙疆政府副主席，配合日军在绥远、内蒙古中西部推行伪化统治。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('def055c67dd541b3af3164fc0aef53b6','ef6c08d0f52941eb82c78030ddb226af',1937,'伪蒙古军师长、伪绥远省保安队头目','在伪蒙古军中任职，率部驻防绥远地区，参与对呼和浩特周边及和林格尔等地的控制与扫荡，配合日军维持伪蒙疆政权统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fdae6d23542b45f1b80d785237b65f0e','13e803496ecd49b288e5106f48f4ba29',1937,'伪蒙古军师长','伪蒙古军高级将领，率部在绥远地区活动，参与日军对绥远抗日根据地的扫荡，控制呼和浩特及周边旗县。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fe703fa175b64cadad9099aa9b0c8a26','838979c5881d455d9908a863bc24d449',1936,'伪蒙古军参谋长、伪蒙疆政府官员','内蒙古东部人，参与伪蒙古军组建，任参谋长等职，协助德穆楚克栋鲁普和李守信推行伪蒙疆政权，在绥远地区进行亲日宣传和军事镇压。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1266a66f81d242fcb3933216cc433908','b86083bd13c04af7ae64c9ee8b5ee802',1936,'伪蒙古联合自治政府参议、伪蒙疆政府官员','原为内蒙古地方知识分子，投靠日军后参与伪蒙疆政权，负责文教、宣传等事务，在呼和浩特等地推行奴化教育，为伪政权培养亲日人员。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('79144b8ad6634994b730aa734e4d3749','993cd83aa8c54ff38e0622e1de731309',1936,'伪蒙古军政治部主任、伪蒙疆政府官员','参与伪蒙古军和伪蒙疆政权，负责政治宣传和情报工作，在绥远地区配合日军镇压抗日力量，推行伪化政策。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ad866311cbca4a098e50c4a89389d48a','ae3b48ea9e8040088090d6b3522682e5',1936,'伪蒙古军师长、伪蒙疆政府官员','伪蒙古军将领，率部在绥远、察哈尔一带活动，参与对呼和浩特周边地区的控制，配合日军扫荡抗日武装。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('13d90973758b4b6282e2afe9bf70a344','73cefe13290d40d8a53bc2dcee0095c7',1937,'伪和林格尔县维持会会长','和林格尔本地士绅，日军占领和林格尔后组织维持会，任会长，协助日军征粮、征夫，维持地方伪秩序，镇压抗日群众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e2aad786243d402fad0a7655e5174352','8ab5989d0f874110915fb964af2edae0',1938,'伪和林格尔县公署县长','在伪蒙疆政权下任和林格尔县县长，推行日伪政令，配合日军清乡、扫荡，搜捕抗日人员，压迫当地民众。','基层头目','hanjian');
