INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('58a53f3680834adb864f270909965968','13e803496ecd49b288e5106f48f4ba29',1938,'伪归绥市警察局局长','在呼和浩特（归绥）任伪警察局长，专门搜捕抗日分子，在回民区设立特务据点，多次逮捕并刑讯回民爱国人士。','市县厅局级','hanjian');
