INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8160774d00f54b86bde9050d3596e12a','4dc8222f0d0b4040ac8709e9d115e9cb',1937,'伪蒙古军第2师副师长','土默特左旗人，早年参加抗日，后叛变投日，参与围剿绥远抗日游击队，后因内讧被日军处决。','市县厅局级','hanjian；traitors');
