INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('75e0afb747874d36a4866e7323d3ee0f','09e65a7dbae748caa1181ab2c8844755',1938,'伪绥远省公署警务厅长','在呼和浩特及清水河地区建立日伪警察网络，搜捕抗日地下人员，参与“大检举”行动，致使多名抗日志士牺牲。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fc065f4b25684faf8fdc9acc7c25897e','25561457344c435aaa3b812455c00558',1938,'伪清水河县知事（县长）','在清水河县推行日伪统治，强征粮食和壮丁，组织汉奸情报网，向日军报告抗日武装动向，导致多起袭击事件失败。','基层头目','hanjian');
