INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a0235166dbee4779a65b844ca9c763d6','12a8b4767b1e4a989997caabbb41d83a',1939,'伪绥西自治军副司令','原为晋军军官，投日后在清水河、和林格尔一带活动，率部袭击八路军小分队，并参与日军“三光”政策行动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('37e107ad99544c50a93bdc347a964148','b86083bd13c04af7ae64c9ee8b5ee802',1937,'伪蒙古军政府秘书长、伪蒙疆联合自治政府总务委员长','原北洋政府官员，投日后参与伪蒙疆政权高层决策，在归绥（今呼和浩特）协助日伪推行殖民统治，参与经济掠夺和“清乡”行动。','机构委员长(非国家首脑)','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('308c40b0d0df4106af70ca45fb1ff9d2','47cac7a73af140d39ff53133e8cfe760',1937,'伪蒙古军第3军军长（后反正）','原东北军将领，投日后任伪职，驻扎归绥期间曾协助日军维持治安，后因日军猜忌被软禁，1939年反正失败被杀，但其前期行为已构成汉奸事实。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e897a7f2fcbc4282a24ec93734bbd7ce','09e65a7dbae748caa1181ab2c8844755',1938,'伪归绥县知事（县长）','在日伪统治下任归绥县（含今玉泉区大部）伪县长，推行保甲制度，强征捐税，为日军提供粮食和情报，协助镇压抗日地下组织。；在呼和浩特（归绥）城区及赛罕地区推行日伪保甲制度，强征粮食和劳役，协助日军建立情报网，镇压抗日群众运动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('af044c407e09427ebdd0af5a4210c9d8','25561457344c435aaa3b812455c00558',1939,'伪归绥市公署市长（旧城区域）','任伪归绥市市长期间，管理旧城（玉泉区）行政事务，执行日伪“治安肃正”计划，强制居民领取“良民证”，并参与奴化宣传。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f525c91ddafd44e083ae388c1686fef0','280453e0c6ba4fe4b8bb6745048c4fab',1938,'伪巴彦塔拉盟盟长（辖归绥地区）','投日后任伪巴彦塔拉盟盟长，管辖今呼和浩特及周边旗县，在玉泉区设立伪盟公署分支机构，配合日军推行“蒙地奉上”和鸦片专卖政策。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6cbcea7716454786abcbcea89334e886','c94f058ddf0448068e37a5d4ac1c1a8d',1937,'伪蒙古联盟自治政府司法部长','参与伪蒙疆政权立法和司法镇压，在归绥（今呼和浩特）设立伪法院，迫害抗日嫌疑人员，其活动范围涉及玉泉区旧城监狱。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c0b036fe21684ff6b2d375cb0cea0514','b86083bd13c04af7ae64c9ee8b5ee802',1937,'伪蒙古联盟自治政府总务部长、伪蒙疆政府政务院院长','原为国民党地方官员，后投日，在呼和浩特地区主持伪政府行政事务，协助日军征粮、征税，镇压抗日活动，参与制定“蒙疆”地区殖民政策。；作为德王主要幕僚，参与伪政权对鄂尔多斯各旗的行政控制，推行奴化教育和物资掠夺政策。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('818aa9ba29694c0398f75057a8aea67b','993cd83aa8c54ff38e0622e1de731309',1936,'伪蒙古军第1师师长、伪蒙疆政府军事顾问','在呼和浩特、赛罕一带协助日军训练伪军，多次参与“扫荡”抗日游击队，残害当地百姓，为日军提供后勤支持。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('13112edf5c5d4676881ae018c3088dda','47cac7a73af140d39ff53133e8cfe760',1938,'伪蒙古军第3师师长','在呼和浩特南部及赛罕地区驻防，配合日军“治安肃正”行动，逮捕抗日志士，强迫农民种植鸦片，为日军筹措军费。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c13e9026f04b49fdab6cfc7124b8929e','6687a4d3a75b4c3099f7cb5005501a4e',1939,'伪巴彦塔拉盟盟长','管辖包括呼和浩特、赛罕在内的地区，积极执行日本殖民政策，推行“蒙地奉上”运动，强占农民土地，配合日军“三光政策”清剿抗日根据地。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a7ef44bcb8244f08bb70b9166018f364','529eba01fd3844d2a4780badaf25cb50',1937,'伪绥西联军司令、伪蒙古军副总司令','绥远地区著名汉奸，抗战期间投靠日军，组织伪军配合日军进攻绥西，在巴彦淖尔、五原、临河一带活动，参与日军对绥西的扫荡和统治。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3b1859a67c9c4720810b54822c65fd57','7fe60a0e08e747819e43053afc3d9d27',1937,'伪蒙古联合自治政府副主席','察哈尔地区汉奸，参与伪蒙疆政权，协助日军在绥远、察哈尔一带推行殖民统治，与巴彦淖尔地区伪政权有隶属关系。；张家口伪蒙疆政权中的汉奸头目之一，参与伪蒙疆对内蒙古东部包括赤峰地区的殖民统治。；投敌后任伪蒙古联合自治政府副主席，协助日军统治察哈尔、绥远。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('07d10131bda741db81cec374ff8e21de','f27fdea68c0f4c87901d2593feda5141',1937,'伪蒙古联合自治政府最高检察厅厅长','绥远地区汉奸，在伪蒙疆政权中任职，参与司法镇压抗日力量，其管辖范围涉及绥西包括巴彦淖尔地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7d1d8666328242499270f9ad6b4ee77a','ec26ab26d6bb4c4b8f8348f1bb125cd7',1936,'伪蒙古军参谋长','协助李守信统率伪蒙古军，参与日军对绥西的军事行动，在巴彦淖尔、五原一带配合日军作战。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f6a2810ed7444117b201722b209ffec4','d566dc108e3e455eb9267bb5683e9461',1937,'伪五原县维持会会长','五原地区汉奸，日军侵占五原后组织维持会，协助日军征粮、派夫、维持地方秩序，为日军统治服务。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ab2f794263c744fcb117b88f228f9b6d','69b8481dbe4c4d10889beb2fb6ed82ad',1937,'伪临河县维持会会长','临河地区汉奸，组织维持会迎接日军，协助日军在临河一带建立伪政权，压迫当地民众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c741b2192bc049bf976446628333eea2','9e03328469564423be9509ff63c083ec',1937,'伪安北县（今乌拉特前旗一带）维持会会长','安北地区汉奸，日军入侵后组织维持会，为日军筹集物资、情报，协助日军控制乌拉特前旗一带。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('236e8c3fd7dd47c18998e670c55649e2','5ae6b456b7434fdca844ecd7aada9d7d',1937,'伪绥西自治联军司令','绥西地区汉奸武装头目，组织伪军配合日军在巴彦淖尔、包头一带进行扫荡，残害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('11e3c29d3fad439298fa5f6c5925f653','3badb60840f84fca8e8d50b44ca905f1',1937,'伪包头县县长','包头地区汉奸，伪政权地方官员，其管辖范围与巴彦淖尔东部接壤，协助日军在绥西推行保甲制度和经济掠夺。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6f80c4daa1d94bd6a44ca6afdfe8805b','b20b75e3a839472699d4a3cb0593b9fe',1937,'伪萨拉齐县县长','萨拉齐地区汉奸，伪政权地方官员，配合日军在绥西地区的统治，参与征粮、抓丁等压迫民众活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('96a2f220308345aa90ef9fd922874fab','1d30d9583f6e4c45a5821363f47d9038',1937,'伪蒙古联合自治政府民政部部长','绥远地区汉奸，在伪蒙疆政权中负责民政，推行日军殖民政策，其政策覆盖巴彦淖尔在内的绥西地区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c2de4387fc01408d9d3c9fe59f73db6d','188d07d789aa410490711b02bbdfddbd',1936,'伪蒙古军总司令部副官长','协助李守信、德王处理伪蒙古军军务，参与绥西地区伪军部署和日军协同作战。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0a2efa02c7df4b8e9e8e30403f7ef88e','26647d4bb91f4086a567e1a461c53d38',1937,'伪蒙古军师长','伪蒙古军将领，率部在绥西巴彦淖尔一带配合日军作战，参与对抗日武装的围剿。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1bfa5937dd584baea0db1e2d6bcaf280','838979c5881d455d9908a863bc24d449',1937,'伪蒙古军师长','伪蒙古军将领，在绥西地区活动，协助日军维持伪政权统治，参与地方伪军组织。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('be694c13217a49e49879bb562a420175','47cac7a73af140d39ff53133e8cfe760',1937,'伪绥西联军副司令','绥西地区汉奸武装头目，与王英合作组织伪军，在巴彦淖尔、五原一带配合日军行动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0e3a883594d149acb5510aacecf7204b','529eba01fd3844d2a4780badaf25cb50',1936,'伪蒙古军第1军军长、伪绥西自治联军总司令','原为土匪出身，后投靠日军，任伪蒙古军第1军军长，在绥西（包括临河、五原一带）配合日军进攻傅作义部，烧杀抢掠，残害百姓，并参与组织伪政权，镇压抗日力量。；原为土匪出身，后投靠日军，在五原、临河一带组织伪军，配合日军进攻绥西，多次参与对五原地区的扫荡和破坏，是当地主要的汉奸武装头目。；原为土匪出身，后投靠日军，在鄂尔多斯及东胜地区协助日军进攻抗日武装，镇压民众，掠夺物资，是当地主要汉奸头目之一。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2f27a970ef84498c98a62989b402cd4e','b86083bd13c04af7ae64c9ee8b5ee802',1937,'伪蒙古军第2军军长','投靠日军后任伪蒙古军第2军军长，曾率部驻扎绥西一带，配合日军扫荡临河、陕坝等地，杀害抗日军民，掠夺财物。；原为绥西地方武装头目，后投日，任伪蒙古军第2军军长，驻防绥西，协助日军清剿抗日游击队，强征民夫粮草，欺压当地民众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('17b068f32dfa4d20a8951d5b47f35b86','8f4c6a82abd7490ab754fe15d2224dd0',1940,'伪临河县县长','日军占领临河期间任伪县长，推行日伪政策，组织汉奸保安队，协助日军清乡，逮捕抗日地下工作者，强征壮丁。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('38f1fa08a4654b6cb513740f829b8787','d252e91d960944729c486ac402d8479f',1941,'伪五原县县长（兼管临河部分地区）','在日伪政权下任职，配合日军对河套地区进行经济掠夺，强制推行“治安强化运动”，迫害抗日家属。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c0aebf5a5af14732b9a71b722fb7cf30','12a8b4767b1e4a989997caabbb41d83a',1942,'伪绥西警备司令（后投日）','原为晋军将领，后投靠日军，任伪绥西警备司令，在临河、狼山一带协助日军防守，镇压当地抗日武装。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('327f778263604442bbb9223ac208515b','3a9e402192aa460fb51a927d874bb93e',1938,'伪蒙古军骑兵第5团团长','长期在巴彦淖尔地区活动，率部袭击抗日游击队，抢劫村庄，并参与日军“扫荡”行动，杀害无辜百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7c12e422ebd847ff95b3652cdb6c2105','5f82d23ccd2e45fd9e59f76c92bcc9ad',1933,'伪蒙古军副总司令、伪蒙疆政府副主席','率伪蒙古军侵占乌拉特中旗等地，协助日军清剿抗日武装，镇压蒙汉民众反抗，参与奴化统治。；原东北军军官，后投靠德王和日军，任伪蒙古军副总司令，参与对绥远、察哈尔等地的军事行动，协助日军维持殖民统治。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('752cf5dafea447a48cc6c43a84a9609d','47cac7a73af140d39ff53133e8cfe760',1938,'伪绥西自治联军副司令','随王英在乌拉特中旗一带活动，参与“清乡”行动，搜捕抗日分子，强征民夫，掠夺物资。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8449860836cd41e4907a5299fa373deb','3a09ae0f7f294a118069ecfbec5ba35b',1937,'伪蒙古军第4师师长','在乌拉特中旗及乌拉特后旗一带活动，为日军提供情报，围剿抗日武装，推行“保甲制度”。','市县厅局级','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9c0912c396044e5ba220372e17040382','12b44502ad7244db80cc0e698c79f09a',1938,'伪蒙古军第9师师长（前期）','在乌拉特中旗驻防期间曾执行日军命令，参与对抗日根据地的封锁，但后期于1945年率部反正（仍列入前期汉奸行为）。','市县厅局级','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('91e9be4f13ba486baaf1f690db39201c','a4a0b90fb3c141f8939b220dafdfb71f',1939,'伪蒙疆政府政务院参议','参与伪蒙疆政权在乌拉特中旗的行政建设，协助推行奴化教育，宣传“日蒙亲善”。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('48b437667dc6400bb40e80b702cd1f48','993cd83aa8c54ff38e0622e1de731309',1938,'伪乌拉特中旗旗长','作为伪旗长，为日军征收粮草、牲畜，强抓壮丁，破坏抗日地下活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7488c44d645f4b12b82cdb8479e51493','544bbb34392047ce8428facb9167a464',1939,'伪乌拉特中旗警察署署长','指挥伪警察搜捕抗日分子，严刑逼供，协助日军“扫荡”周边村落。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2bea10ed7cb449309fa94ecbb3173566','188e53b892a04f628776743bbe3f7af7',1940,'伪乌拉特中旗保安队队长','率保安队配合日军围剿大青山抗日游击队，杀害多名交通员和群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('10f9c25c0e924f75b7e8f28230eedea1','993cd83aa8c54ff38e0622e1de731309',1937,'伪蒙古军师长','率伪蒙古军驻扎乌拉特前旗一带，配合日军围剿傅作义部抗日武装，残害当地抗日军民。；率伪蒙古军在张家口、察北地区配合日军扫荡抗日游击队，残害百姓。','市县厅局级','hanjian');
