INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('91157a07b9094e8d98988d888a0acbe1','3a09ae0f7f294a118069ecfbec5ba35b',1939,'伪乌拉特前旗旗长','作为伪旗长，协助日军在乌拉特前旗推行“治安强化运动”，强征劳工修建军事设施，压榨当地牧民。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b199a33ca80a40a2b52fe683297425b9','544bbb34392047ce8428facb9167a464',1940,'伪乌拉特前旗保安队长','率伪保安队为日军站岗放哨，参与围捕抗日游击队，多次向日军报告抗日活动线索。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a473ba01d69043a089359ef7a8298bc1','5f82d23ccd2e45fd9e59f76c92bcc9ad',1933,'蒙疆联合自治政府副主席、伪蒙古军总司令','率伪蒙古军侵占绥远北部（含乌拉特后旗一带），协助日军‘清剿’抗日武装，镇压蒙汉民众。；原为热河地方军阀，后投靠日本，在锡林郭勒及察哈尔地区组织伪蒙古军，协助日军镇压抗日力量。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4ec57be20fba4b1cb9103d9482d0c57f','47cac7a73af140d39ff53133e8cfe760',1938,'伪绥西联军副司令（后反正）','一度投靠日军，在乌拉特后旗及周边地区参与伪军活动，后反正抗日（但前期有汉奸行为）。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('041519d9d3334b65b2bcca64ef42d928','088320714ff747b3a87cd7d2fc54ab67',1939,'伪乌拉特后旗保安队队长','在乌拉特后旗为日军效力，协助维持伪政权，镇压当地抗日牧民，征收苛捐杂税。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b8335b33828e44ea847130fc26339445','c7d694b2b1e142bd994011d2918cf246',1940,'伪乌拉特后旗旗长（日伪任命）','在日伪统治下担任旗长，推行‘保甲制度’，强迫牧民供粮供畜，配合日军‘治安肃正’。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1e05b2b5d0ef43a39e88db864c74a5bf','194f9301b50649e8b6a5002dc017ad7b',1941,'伪乌拉特中旗（含后旗部分地区）协理','协助日伪在乌拉特地区征募伪军，提供情报，参与围剿抗日游击队。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cc6af808bc114cc28cde7536488c0a89','e30cdedf3b9b4398838b6b011c52a9c6',1942,'伪乌拉特后旗警察署署长','指挥伪警察抓捕抗日志士，破坏地下抗日组织，为日军提供劳役。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a3b1994c0bdc4857a3b60b12e99d4661','5f82d23ccd2e45fd9e59f76c92bcc9ad',1933,'伪蒙古军副总司令、伪蒙古联盟自治政府副主席','热河人，投日后成为伪蒙疆政权核心人物，其势力范围曾延伸至绥西五原地区，协助日军控制该区域，并组织伪军对抗抗日武装。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b60960ac4e814bc582cc92d94cae0be7','b86083bd13c04af7ae64c9ee8b5ee802',1938,'伪蒙古军第9师师长','在五原、安北一带驻防，协助日军清剿抗日游击队，曾参与1939-1940年日军对五原的进攻，并纵容部下掠夺百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a9d04457d3ed4a94b834e66037cc9efe','77857f075ce44761869c5724589a4545',1939,'伪蒙古军第5师师长','率部在绥西地区活动，多次配合日军扫荡五原周边村庄，杀害抗日军民，并强征民夫修筑工事。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a7c6e7f374b24ffbbb2f0c7b6d8200c3','8f4c6a82abd7490ab754fe15d2224dd0',1940,'伪五原县县长','日军占领五原期间任伪县长，推行保甲制度，强征粮食和劳役，协助日军维持殖民统治，并迫害抗日家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('39e918a6adbc441aaed798047dbdb289','68086e4a08ed423aa788864a68f28ed6',1940,'伪五原县警察局长','为日军效忠，搜捕抗日地下人员，破坏地下交通线，并参与镇压当地民众的反抗。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a4364f27178140c382fc16dc8c76c618','32632fc447184a04b53cab7b29fb4a88',1939,'伪安北县（今属五原）维持会会长','日军占领安北后组织维持会，为日军筹粮派款，并引导日军袭击抗日武装驻地。','基层维持会/地方自治头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d74862f00c1f4e7bb998728fafe94f9d','529eba01fd3844d2a4780badaf25cb50',1937,'伪蒙古军第1军军长、绥西自治联军总司令','原为土匪出身，后投靠日军，任伪蒙古军第1军军长，率部在绥西（今巴彦淖尔、杭锦后旗一带）配合日军扫荡抗日武装，残害百姓，制造多起惨案。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9a17deea03324208b6d4d4c5047360c5','ec26ab26d6bb4c4b8f8348f1bb125cd7',1933,'伪赤峰县县长','日军侵占赤峰后出任伪县长，推行日伪殖民政策，强征民夫、收缴民间武器，协助日军维持统治。；任伪赤峰县县长期间，为日军征粮派夫，强征劳工，协助日军建立保甲制度，迫害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b752eb2443004ef0b3e74c2ceccab181','3a9e402192aa460fb51a927d874bb93e',1933,'伪赤峰警察局局长','效忠日伪当局，指挥警察抓捕抗日志士，参与“治安肃正”行动，迫害无辜百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('29118a04e4f64a2480989d664efe3350','1ba31d558b934fbd83a28a8c2b446022',1933,'伪热河省省长（辖区含赤峰）','原奉系军阀，九一八后投日，任伪热河省省长，协助日军统治赤峰地区，推行奴化教育，镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4803d3eb596c4d0bb77df079c978b070','03214a24b080428583bfed7e21cd444e',1935,'伪赤峰协和会会长','负责日伪“协和会”赤峰分会，宣传“日满亲善”，组织汉奸团体，搜集抗日情报。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3025f3e7c9574e9b80456c21562c0a00','15aba61e822c4e50a3d0ac9384c005f1',1933,'伪赤峰保安队队长','率保安队配合日军“扫荡”，烧杀抢掠，多次参与围剿赤峰周边的抗日游击队。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d68e1ac458974bf0ac2503227d60eafa','328f6cb60ea243d0a7dda3e54edb87d3',1934,'伪赤峰税务局局长','为日伪征收苛捐杂税，强征粮食、牲畜，导致百姓负担沉重，间接支持日军战争经济。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('792f6196ce48428fbbca5914884a7483','9f7b3ed9c76f4eea8211fd8ebc40a461',NULL,'',NULL,'无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d9e3f8c8a5d24a4b95a0992b58ea2594','5f4f267ed5614f2687e3430a6654b3c9',1933,'伪热河省公署参事','在伪热河省任职期间，参与策划对赤峰、元宝山地区的“治安肃正”行动，协助日军清剿抗日游击队。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('56822b49a84141009b69db25ef96e2fb','3a9e402192aa460fb51a927d874bb93e',1937,'伪元宝山维持会会长','在元宝山矿区组织伪维持会，为日军提供煤炭资源情报，强迫矿工为日军服务，镇压矿工反抗。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('816bb5841835472f85092c1ee3f9d044','1ba31d558b934fbd83a28a8c2b446022',1933,'伪热河省警备军司令','率伪军驻防赤峰一带，多次配合日军扫荡元宝山周边村庄，杀害抗日群众，掠夺物资。；原为奉系军阀，1933年投敌，任伪热河省警备军司令，其部队驻扎赤峰、林西等地，多次参与围剿抗日游击队，协助日军建立伪政权。；原东北军将领，投日后任伪热河省警备军司令，在承德、兴隆一带配合日军‘扫荡’，围剿抗日武装，残害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7357e582705a4ab9be79d3ba0422a303','38a3dacd45834c858a732edd8e6fde72',1938,'伪赤峰警察局局长','在赤峰及元宝山地区建立特务网络，抓捕抗日地下工作者，协助日军进行“大检举”行动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('308e7cc897a249f7a291eed691c6d6e3','38a3dacd45834c858a732edd8e6fde72',1933,'伪克什克腾旗旗长','投靠日军，任伪旗长，协助日伪推行殖民统治，强征民夫、粮食，镇压抗日活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('efa43f50767545258e50fdb0cec01235','ae85c6eee7964d81b87a3fd2f21e155a',1935,'伪克什克腾旗警务科长','效忠日本特务机关，组织伪警察抓捕抗日志士，参与“治安肃正”行动。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c1032c9dec7b4aaa8f180dac26bdf802','2c58430b56e4445aa4cf1b96fa396d59',1937,'伪克什克腾旗保安队队长','率伪保安队配合日军扫荡，烧毁村庄，掠夺牲畜，迫害当地民众。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5a9a381449834dce8aac8a55e89ffc03','188e53b892a04f628776743bbe3f7af7',1938,'伪克什克腾旗协和会会长','宣传“日满亲善”，组织奴化教育，强迫民众参加“协和会”活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('74536f060a884bbc990bfb4eea3fcba9','5f82d23ccd2e45fd9e59f76c92bcc9ad',1933,'伪蒙古军政府/伪蒙古联合自治政府军事头目、伪蒙古军总司令','热河抗战后投敌，率部配合日军侵占赤峰及昭乌达盟一带，参与组建伪蒙古军，长期在内蒙古东部包括赤峰地区进行殖民统治和军事镇压。；热河抗战后投敌，组织伪蒙古军，配合日军侵占赤峰及昭乌达盟一带，在巴林右旗等旗县推行伪旗县公署和保甲制度，强征民夫、牲畜，镇压抗日武装。；蒙古族出身，早年在热河、哲里木盟一带活动，1933年投靠日军，参与组建伪蒙古军，长期在内蒙古东部包括通辽、开鲁周边地区配合日军围剿抗日武装，推行伪蒙疆统治。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('50e0c02b2ffe4c19aad17102919621dc','78198cf336e24d25a8e52cd58ddf4575',1936,'伪蒙古军政府主席、伪蒙古联合自治政府主席','在日军扶植下建立伪蒙政权，统治范围覆盖内蒙古东部，赤峰及喀喇沁旗一带受其伪政权影响，推行亲日殖民政策。；即德王，锡林郭勒盟苏尼特右旗札萨克郡王，1936年起在日军扶植下建立伪蒙古政权，其统治范围及于内蒙古东部，通辽、开鲁一带亦受其伪政权影响，配合日军进行殖民统治。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d3616d6b2fda4ddca0ed9b6e14caf4b3','eb166a17cf664e83aa52590be3bac98d',1931,'伪兴安军/伪蒙古军将领','九一八后投靠日本，参与组织伪军，在内蒙古东部包括赤峰地区配合日军作战和维持殖民秩序。；九一八后投日，参与组建伪军，在内蒙古东部包括赤峰一带进行殖民统治和镇压抗日活动。；参与策划内蒙古东部独立活动，投靠关东军，在赤峰、通辽一带组织伪军，配合日军进攻抗日武装。；蒙古族，早年参与策划内蒙古“独立”活动，九一八事变后投靠日本，在伪兴安军、伪蒙古军中任职，活动于内蒙古东部包括赤峰、昭乌达盟一带，参与镇压抗日力量。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('14c06fc1c437408d905d686da0678fef','f4208529cb14438593c9984febac079f',1932,'伪兴安南分省省长、伪兴安局总裁','投靠日本，任伪满兴安省要职，管辖包括赤峰在内的内蒙古东部地区，推行日本殖民统治政策。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f816aa3f8f5d4714a260242219b2baa3','cce0beb18f6444d29b255fd8e4458a06',1932,'伪兴安南分省省长、伪兴安总省省长','在伪满洲国任职，管理兴安南地区，赤峰一带在其管辖范围内，协助日军征发物资、镇压抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('946232f71e9f4e6da6c6b5ce4507bb5c','328c16b7cce14a88803101ac039f03d5',1932,'伪兴安南省民政厅长、伪兴安总省民生厅长','在伪满兴安省系统任职，参与对内蒙古东部包括赤峰地区的殖民行政管理和亲日宣传。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6cad536619dc4895b963d7ced49b038e','4ff98a4e38cc4aacb41680dcb877f683',1932,'伪满洲国兴安局官员、伪蒙古联合自治政府官员','在伪蒙、伪满政权中任职，活动于内蒙古东部，参与日本殖民统治下的行政与联络事务。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7719931804b2444da141d553a6779ae8','26647d4bb91f4086a567e1a461c53d38',1932,'伪兴安军军官','在伪兴安军任职，配合日军在赤峰及昭乌达盟地区进行军事行动和治安镇压。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0d79701d1fea44339f65245183f1bc98','6ad1b280d7654edd89e3b7c53bf3e430',1936,'伪蒙古军政府/伪蒙古联合自治政府官员','参与伪蒙政权，在内蒙古东部包括赤峰地区进行亲日政治活动，协助日军统治。；蒙古族，投靠日本，在德王伪政权中任职，参与伪蒙古联合自治政府的政务活动，其伪政权影响覆盖内蒙古中东部包括赤峰地区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0b9d72a4a9464f37b15c8f50fd1c5309','529eba01fd3844d2a4780badaf25cb50',1931,'伪绥西联军司令、伪军头目','长期投靠日军，在内蒙古中西部及东部部分地区活动，配合日军进攻和镇压抗日武装，其势力曾波及赤峰周边。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7ce2af51e69749bf8055dd779f9682cc','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洲国热河省省长、伪军头目','投靠日本，率伪军参与侵占热河，赤峰地区在其伪省管辖范围内，协助日军镇压抗日活动。；率部投敌，配合日军进攻热河，任伪省長。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1ae9f5c09cd347329e4d54e1f584f3c3','177c17b9b440453fa41ed47b9ebbd502',1930,'伪军头目、土匪武装首领','曾投靠日军，率部在热河、赤峰一带流窜，配合日军骚扰抗日根据地，后又被抗日武装打击。；绰号刘黑七，长期在山东胶东一带流窜，后投靠日军，配合日军进攻招远、烟台等地的抗日根据地。；绰号刘黑七，长期在山东胶东一带活动，后投降日军任伪军师长，在烟台、栖霞周边地区烧杀抢掠，配合日军扫荡抗日根据地。；长期在山东胶东及鲁中南地区流窜，曾投靠日军任伪军师长，配合日军扫荡胶东抗日根据地，1943年被八路军击毙。；绰号刘黑七，抗战时期率部投敌，在山东胶东及鲁中南一带流窜，配合日军袭扰抗日根据地，活动范围接近烟台、莱阳地区。；原为山东巨匪，抗战期间投靠日军，率部在胶东及鲁中南地区活动，配合日军扫荡抗日根据地，残害民众。；长期在鲁南、鲁西南及菏泽周边活动，抗战期间投靠日军，所部被编为伪军，配合日军扫荡抗日根据地，残害民众。；长期在河北、察哈尔、张家口一带流窜，曾投靠日军任伪军头目，配合日军扫荡抗日根据地，残害民众。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('df0b71c187484812ac1bf968f4a39a48','ba307a71c66a4d0995686ad3b1fc5f41',1930,'伪喀喇沁旗旗长','在伪满洲国时期任喀喇沁旗伪旗长，协助日军推行保甲、征发劳役和物资，维持当地殖民统治。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('442113699e724c418258a9b9787d9ac4','10595860987147a0a24c6815061e8fce',1930,'伪喀喇沁旗公署官员','在喀喇沁旗伪政权中任职，参与亲日宣传、物资征调和地方治安维持。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4ea11ae7948949338e042e1ac0d60ceb','50789647a08643c2af5f199ff8c39b26',1933,'伪赤峰县县长','日军侵占赤峰后任伪县长，协助日军建立殖民秩序，推行保甲连坐，镇压抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('70f1e8d4ef4e4a8b96c410ffb5765919','667c6ec8bde743f5ab4bf8054b130acc',1933,'伪赤峰县维持会会长','日军侵占赤峰初期组织维持会，为日军筹粮筹款、维持地方秩序，协助殖民接管。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3b26e42275454ad68ab144a31c2621a6','faf1e7317adc4737b491d3a86435b024',1930,'伪赤峰县警察署长','在伪赤峰县警察系统任职，参与搜捕抗日人员、镇压民众反抗，维护日伪统治。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7bc5e8e5960d476e8d13b571a3b3adb9','188e53b892a04f628776743bbe3f7af7',1933,'伪热河省警务厅官员','在伪热河省警务系统任职，负责赤峰等地治安，参与围剿抗日武装和镇压民众。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('427a76e772d440e4820ad7929cfed128','5e3c03e59a9d4a4f81ce0c0f481fb548',1933,'伪热河省教育厅官员','在伪热河省教育系统推行奴化教育，赤峰地区学校受其政策影响，宣传亲日思想。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('83f340d468f44ebab64fe6dcf6da87af','ec26ab26d6bb4c4b8f8348f1bb125cd7',1937,'伪宁城县县长','任伪宁城县县长期间，推行日伪保甲制度，强征劳工，配合日军“治安肃正”，抓捕抗日军民，并强迫民众种植罂粟。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1771e49d58ec4b659cd8c905b1b829ef','6907c9ae1353426b887f50f548459bf1',1938,'伪赤峰县县长','在赤峰地区为日军征粮派款，组织伪警察队协助日军扫荡，破坏中共地下组织，曾亲自带队抓捕抗日干部。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3be0e02b774640679687020f8fbad0a8','3a9e402192aa460fb51a927d874bb93e',1939,'伪热河省警务厅特务科长（活动于赤峰、宁城）','指挥特务情报网，在宁城、赤峰等地侦捕抗日地下人员，制造多起惨案，如“五家村惨案”中提供情报并参与屠杀。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e61a3305646b487fbca065e71846c61e','38a3dacd45834c858a732edd8e6fde72',1940,'伪宁城县保安队队长','率保安队多次袭击八路军游击队，烧毁村庄，杀害抗日家属，并配合日军在宁城西部山区推行“无人区”政策。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ec159b51ae9e4ad9a3d52d67faa632f0','c692801ac2c3420b89c5234722019808',1935,'伪赤峰街公所所长、汉奸商会会长','为日军筹集军需物资，垄断粮食贸易，压低收购价盘剥农民，并举报抗日商人，导致多人被日军宪兵队杀害。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('da1fbb2454a3446ba80892d8277bfb15','af96068e274a4fdfb011573dd045f17a',1937,'伪热河省协和会赤峰支部长','宣传“日满亲善”，组织“协和青年团”刺探抗日活动，在宁城地区煽动民众告密，致使多个抗日联络点被破坏。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1d1c1e9569114b0a97ed641af6afb0a7','9f7b3ed9c76f4eea8211fd8ebc40a461',1933,'原国民革命军将领（后投日，活动于热河边缘）','虽主要活动在河北，但曾与日军勾结，在赤峰南部边境为日军提供情报，并收编伪军骚扰抗日武装。注：其投日行为存在争议，部分史料未完全确认。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6fff513e644d42f0921188a054c15de3','78198cf336e24d25a8e52cd58ddf4575',1936,'伪蒙古军政府总裁、伪蒙古联合自治政府主席','在日军扶植下建立伪蒙政权，管辖包括赤峰、昭乌达盟在内的内蒙古东部地区，推行亲日政策，协助日军征发物资、控制蒙旗，巴林右旗等旗在其伪政权体系内。；即德王，锡林郭勒盟苏尼特右旗札萨克。在日本支持下先后建立伪蒙古军政府、伪蒙古联合自治政府，统治范围涵盖内蒙古中东部，赤峰、翁牛特旗一带亦受其伪政权影响，推行亲日附逆政策。；在日军扶植下建立伪蒙政权，势力范围涉及宁夏北部及石嘴山周边，配合日军对宁夏进行军事威胁和政治渗透，招募当地蒙汉败类充当伪军。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bd642938a4c94a1e94780350727352d4','eb166a17cf664e83aa52590be3bac98d',1931,'伪兴安军/伪蒙古军将领、伪兴安局官员','参与策划蒙旗独立活动并投靠日本，在伪兴安省、伪蒙古军任职，活动于昭乌达盟、赤峰一带，协助日军控制巴林右旗等蒙旗。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a681c9477fda4c7eb24596bf2dee1eff','64f7e2c362324f7c8ebbecd6fb02d6e4',1931,'伪兴安军军官、伪蒙古军参谋','与甘珠尔扎布等投日，参与组织伪蒙武装，在赤峰、昭乌达盟地区配合日军行动，镇压抗日力量。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3a7a7d6833fe4c32bfa9e9394b0324ee','f4208529cb14438593c9984febac079f',1932,'伪兴安局总裁、伪兴安总省省长','作为伪满洲国兴安省系统高官，管辖包括赤峰、昭乌达盟在内的东蒙地区，推行日伪政策，控制巴林右旗等旗县。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cdafea23320542788669ff0a649637c7','cce0beb18f6444d29b255fd8e4458a06',1932,'伪兴安局官员、伪旗长','在伪兴安省系统任职，参与昭乌达盟地区伪政权建设，协助日军征发物资、推行保甲。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('faf6f6191fb14cbfb18cfd03aa8565af','c751942e2e3b40dc8fc490a7a38da75f',1932,'伪兴安军军官、伪旗长','投靠日伪，在昭乌达盟、赤峰一带任职，参与伪军警活动，镇压抗日群众。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2d35a37a47ec4fa689afd14f2ff5cc81','26647d4bb91f4086a567e1a461c53d38',1933,'伪蒙古军军官、伪兴安军将领','在伪蒙古军和伪兴安军任职，活动于赤峰、昭乌达盟地区，配合日军扫荡抗日武装。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b4247ab7ec7f4e6f88eedef316925cd3','1b364e4416e748f8a75965b89cc5b90d',1931,'伪兴安军/伪蒙古军将领','投日后在伪蒙武装中任职，参与控制东蒙地区，包括赤峰、昭乌达盟一带，协助日军维持统治。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b028711bab3f451598ddcf796f92c6e2','91f1b0f271fc45e08b71fe859fb3a159',1933,'伪蒙古军军官','在伪蒙古军任职，活动于昭乌达盟、赤峰地区，参与伪军行动和物资征发。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ed894ea4ecec49bf92e36edb51f250d4','8d7ffc5cb6ac4a9ea9f5dd5a37ed8cc4',1933,'伪旗长、伪维持会头目','在昭乌达盟某旗任伪职，协助日军建立保甲、征发牲畜粮食，镇压抗日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8d258dbeb45045478dcac14e1a4b2662','5432fbdab70b4846bf4358ef4c3d0c29',1933,'伪巴林右旗旗长或伪旗公署官员','在巴林右旗伪旗公署任职，执行日伪政令，推行保甲连坐，征发民夫物资，配合日军控制当地。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('23dd1e3dd0a54555b1facf7f12efc1cf','fa3775ec09fd4591ba5c931174929c88',1933,'伪巴林右旗旗公署官员','在巴林右旗伪政权中任职，协助日军和伪兴安省控制地方，参与征发与镇压。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5c1c26484add4e0091f6dc9b70f42ea6','8c752e677e2744f183398498bb5e3ff6',1933,'伪昭乌达盟旗长、伪维持会头目','在昭乌达盟地区任伪职，组织维持会，协助日军维持治安、征发物资。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4c3dbcda410043f9805525eb57b7fce2','fa557afa474045dbb2dcc220f3e11f25',1932,'伪旗长、伪兴安省官员','在昭乌达盟、赤峰一带伪政权任职，推行日伪政策，控制巴林右旗等旗县。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('76c6ed2e35ec4cf9b4972e2d37ab83b3','62df5801e3994d7689d34b7f503e286c',1933,'伪旗公署官员、伪保甲长','在巴林右旗或邻近旗县任伪保甲长，协助日军征发粮食、民夫，监视抗日群众。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('28c2aab757644a8ab150b90d9d8cb966','224924331d2b4338bdd6ad0e7b6826ce',1933,'伪兴安军军官、伪警察头目','在赤峰、昭乌达盟地区任伪军警职务，参与扫荡抗日武装，镇压群众。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('abb2200d17f94f7caeb3efcce1e73856','6ac45c4c648e4eb5afbd66ec5b651229',1932,'伪兴安省官员、伪旗长','在伪兴安省系统任职，管辖昭乌达盟部分旗县，协助日军控制巴林右旗一带。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('309452ab114d4f12b35266aa2274bc63','813eb9eb990440f9bef4adc4c277616e',1933,'伪旗长、伪维持会头目','在昭乌达盟地区任伪职，组织维持会，协助日军征发物资、推行保甲。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d996891032e74cc9a5b83aeaf4c62292','a75490d1ee3f4a66a878100e4b7ac1b6',1932,'伪满洲国参议、伪旗长','虽早年有维新活动，但晚年投靠伪满洲国，在昭乌达盟地区有影响，协助日伪控制蒙旗。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4c1b5130c2514324b308455719412fb9','188d07d789aa410490711b02bbdfddbd',1933,'伪热河省公署官员、伪旗长','在伪热河省任职，管辖包括赤峰、昭乌达盟部分地区，推行日伪政令，控制巴林右旗等旗县。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('086d991c1e39415a8303936eb3b07901','1ba31d558b934fbd83a28a8c2b446022',1931,'伪热河省省长、伪军头目','投敌后任伪热河省省长，配合日军侵占赤峰及昭乌达盟，建立伪政权，征发民夫物资。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b29ba6c849d34ac6af30c07302148e95','177c17b9b440453fa41ed47b9ebbd502',1933,'伪军头目','投日后率伪军活动于热河、赤峰一带，骚扰抗日根据地，镇压群众。；山东人，抗战期间投靠日军，组织伪军，在华东地区进行伪化统治。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('45bc736ba32a400a86a0140ac48c0292','ba307a71c66a4d0995686ad3b1fc5f41',1933,'伪热河省警备军头目','在伪热河省警备系统任职，活动于赤峰、昭乌达盟地区，参与扫荡抗日武装。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9569c229e4ba4e6698c307ed8ba31584','ecc046d8cc954a9ab4bd503a315c97cb',1932,'伪旗长、伪兴安省官员','在昭乌达盟地区任伪职，协助日军控制巴林右旗等旗县，推行保甲。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a08715abc14342bca05889818ea6e666','28112ca7edcc48bd9b79e5f072c968e4',1933,'伪旗长、伪维持会头目','在昭乌达盟地区任伪职，组织维持会，协助日军征发物资、镇压抗日。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a47ee7dee92942ddadccca7ac8dabb9d','e4793077f0bd4308adee8c9c96381d5a',1933,'伪旗公署官员、伪保甲长','在巴林右旗或邻近地区任伪保甲长，协助日军征发粮食民夫，监视群众。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0005ba2dfb6f4f159fc213beb881b1c4','ff05d880fc4d45d4adc4b639631a77ab',1933,'伪兴安军军官、伪警察头目','在赤峰、昭乌达盟地区任伪军警职务，参与扫荡抗日武装。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2138980c2c9d4b409ee0e19426c6d669','0b877cf604a04a3cb0bf8f6eb26dff85',1932,'伪旗长、伪兴安省官员','在昭乌达盟地区任伪职，协助日军控制巴林右旗等旗县。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7088cb383fbf4fc0a0e87050913f6eb3','681f5fcb1e2546ae9736d3e130047844',1933,'伪旗公署官员、伪维持会头目','在昭乌达盟地区任伪职，组织维持会，协助日军征发物资。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7770a021a29a4b0a989e8794a797992a','78198cf336e24d25a8e52cd58ddf4575',1936,'伪蒙古军政府总裁、伪蒙疆联合自治政府主席','锡林郭勒盟苏尼特右旗札萨克郡王，1936年在日本支持下成立伪蒙古军政府，后任伪蒙疆联合自治政府主席，其伪政权统治范围涵盖今内蒙古中东部包括赤峰部分地区，推行亲日卖国政策，协助日军征粮、征兵、镇压抗日力量。；在日军扶植下建立伪蒙疆政权，其统治范围覆盖赤峰及阿鲁科尔沁旗等昭乌达盟地区，推行亲日政策，协助日军控制内蒙古中东部。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aa4e2dbca6e9450fbfa6c9cc248b6049','7fe60a0e08e747819e43053afc3d9d27',1936,'伪蒙疆联合自治政府副主席','原为张家口商会会长，1937年日军占领张家口后出面组织维持会，后任伪察南自治政府最高委员、伪蒙疆联合自治政府副主席，积极为日军筹粮筹款，推行经济统制，协助日军在蒙疆地区进行殖民统治。；原为商人，后投靠日军，在伪蒙疆政权中担任要职，协助日军在内蒙古中西部推行殖民统治和经济掠夺，活动范围涉及鄂尔多斯周边地区。；河北人，抗战期间投靠日军，任伪蒙疆联合自治政府副主席，在华北地区进行伪化统治。；伪蒙疆政权要员，主要活动于内蒙古、察哈尔等地，与重庆沙坪坝无直接关联。；在察绥伪政权中任职，参与日军对晋陕绥边区的政治控制，其活动范围接近榆林、府谷一带。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f31725eb5de84350affce4f2a47694ac','6ad1b280d7654edd89e3b7c53bf3e430',1936,'伪蒙古军政府军事部长、伪蒙疆联合自治政府参议','蒙古族，早年参与内蒙古自治运动，后投靠日本，任伪蒙古军政府军事部长，协助德王组建伪蒙古军，参与日军在昭乌达盟、赤峰地区的治安作战和情报搜集。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4a4337231e8a42f19a47d65b0edd3444','c94f058ddf0448068e37a5d4ac1c1a8d',1936,'伪蒙古军政府办公厅主任、伪蒙疆联合自治政府最高法院院长','蒙古族，德王亲信，任伪蒙古军政府办公厅主任，后任伪蒙疆联合自治政府最高法院院长，参与伪蒙疆政权的立法与司法，为日军殖民统治提供所谓法律依据，其活动范围涉及昭乌达盟等地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e4e59645deab44d7b9df485d0af8cc75','993cd83aa8c54ff38e0622e1de731309',1936,'伪蒙古军政府参议、伪蒙疆联合自治政府交通部长','蒙古族，早年从事内蒙古自治运动，后投靠日本，任伪蒙古军政府参议，后任伪蒙疆联合自治政府交通部长，负责蒙疆地区交通建设以配合日军军事运输，其管辖范围包括赤峰一带。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('638044ee96ee4c5b96268824f2d130e6','b86083bd13c04af7ae64c9ee8b5ee802',1936,'伪蒙古军政府参议、伪蒙疆联合自治政府民政部长','蒙古族，原为南京国民政府蒙藏委员会官员，后投靠日本，任伪蒙古军政府参议，后任伪蒙疆联合自治政府民政部长，推行亲日教育、户籍管理，协助日军在蒙疆地区征兵征粮。；原为内蒙古自治运动成员，后投靠日本，在伪蒙古军政府和伪蒙疆联合自治政府中历任参议、民政部长等职，参与制定伪政权政策，推行日语教育、征粮征丁等殖民措施。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6b993f2cd556498096c2a7eb4cb0e176','6687a4d3a75b4c3099f7cb5005501a4e',1933,'伪热河省公署警务厅长、伪满热河省警务厅厅长','伪满洲国热河省警务头目，负责热河省（含今赤峰大部）的警察、特务系统，推行保甲连坐、治安肃正，残酷镇压抗日武装和民众，是赤峰地区伪警系统的核心汉奸之一。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('29b9184ca34d41eea59b00c1734e5654','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洲国热河省警备司令、伪满军洮辽警备司令','原为东北军将领，1931年九一八后投靠日军，任伪满军洮辽警备司令，1933年率部配合日军进攻热河，参与侵占赤峰、昭乌达盟等地，后任伪热河省警备司令，镇压抗日武装。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e4b6dce6dd7b47f084dc3833e8ac6f25','b13717d0c73e4b4dab35109ce0057aba',1933,'伪满洲国热河省军管区司令、伪满军热河警备司令','伪满军热河地区高级将领，负责热河省（含今赤峰）的伪军警备和治安作战，配合日军对抗日根据地和游击区进行扫荡，推行集家并村、制造无人区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7e1a35d6949f403d8e5923f21e0a6068','c9dffc071fec4ce58fe1d611f26c28da',1933,'伪满洲国热河省公署民生厅长','伪满热河省公署官员，负责民生、物资统制，配合日军在热河省（含赤峰地区）征粮、征劳工，推行经济掠夺政策，为日军侵略战争提供物资保障。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('741ea4b35ef14fb586a062047c0ea34d','26647d4bb91f4086a567e1a461c53d38',1933,'伪满洲国兴安西省警备军司令、伪满军兴安军管区司令','蒙古族，伪满洲国兴安西省（辖今赤峰北部、巴林左旗等地）警备军司令，后任兴安军管区司令，统率伪蒙古族部队配合日军在昭乌达盟、赤峰一带进行治安肃正，镇压抗日武装。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('af906012d4e34279a532b15cae787659','eb166a17cf664e83aa52590be3bac98d',1932,'伪满洲国兴安南省警备军司令、伪满军兴安军管区司令','蒙古族，早年参与策划内蒙古独立运动，后投靠日本，任伪满兴安南省警备军司令，后任兴安军管区司令，其部队在昭乌达盟、哲里木盟一带配合日军作战，镇压抗日力量。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('124b3c74731743b8a3ba1ffdfa8aaa14','f4208529cb14438593c9984febac079f',1933,'伪满洲国兴安西省省长、伪满兴安局总裁','蒙古族，原为扎鲁特旗札萨克，投靠日本后任伪满兴安西省省长，管辖今赤峰北部、巴林左旗等地，推行亲日政策，协助日军征粮征兵、建立保甲制度。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dcf99499bec641159bebf4051646009a','f07bef0259cc4d5aa08520b690aa4740',1933,'伪满洲国兴安西省警备军参谋长、伪满军兴安西省警备军司令','蒙古族，伪满兴安西省警备军高级军官，参与指挥伪军在巴林左旗、林西、经棚等地对抗日武装的扫荡，推行治安强化运动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('22a8fd12009b46d681d9be32e6528e3d','28f376a2fd604ddf8f53bf32a987dd7e',1933,'伪满洲国兴安西省巴林左翼旗旗长','蒙古族，伪满兴安西省巴林左翼旗（今巴林左旗）旗长，直接在当地推行伪满政令，组织保甲、征粮征畜、征集劳工，协助日军和伪警镇压抗日民众。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1cdcea9b9c844cde8b2fba7ddedccb7a','fa3775ec09fd4591ba5c931174929c88',1933,'伪满洲国兴安西省巴林右翼旗旗长','蒙古族，伪满兴安西省巴林右翼旗旗长，配合日军在巴林地区推行殖民统治，征粮征兵，镇压抗日活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('25be9548aefe4096be980fe214f84079','8c752e677e2744f183398498bb5e3ff6',1933,'伪满洲国兴安西省克什克腾旗旗长','蒙古族，伪满兴安西省克什克腾旗旗长，在克什克腾旗（邻近巴林左旗）推行伪满政策，协助日军征粮、征劳工，镇压抗日武装。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f361101323f64a98a81e40d82fe52c8e','188e53b892a04f628776743bbe3f7af7',1933,'伪满洲国热河省赤峰县县长','伪满热河省赤峰县县长，在赤峰县城及周边地区推行保甲制度、物资统制，协助日军征粮征款，镇压抗日民众和地下工作者。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0ffa055e533549c6a3cb23258dba7672','15aba61e822c4e50a3d0ac9384c005f1',1933,'伪满洲国热河省赤峰县警务科长','伪满赤峰县警务头目，负责赤峰地区警察特务系统，搜捕抗日人员，推行连坐法，配合日军扫荡抗日游击区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('65f5cb1fe3934f52924ce77fa6cc929e','11a53228a1f04138b78497d7c99cffe7',1933,'伪满洲国热河省林西县县长','伪满林西县县长，在林西（邻近巴林左旗）推行伪满政令，征粮征畜，组织保甲，协助日军镇压抗日武装。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c02227190b904c5c81020cb0a70096c8','012ae4987f7f45728d8b2aaef79eeda5',1933,'伪满洲国热河省经棚县县长','伪满经棚县（今克什克腾旗）县长，配合日军在经棚地区推行治安肃正，征粮征劳工，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('492e7fd33ce5415d8919b07b17182bf9','e522b6ab522f49069eec5b5c41bfd50f',1933,'伪满洲国热河省乌丹县县长','伪满乌丹县（今翁牛特旗）县长，在乌丹地区推行保甲制度，协助日军征粮征兵，镇压抗日民众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1858d0bce01e4b9aba3a7799b7e7759d','2f5eea6a482341d593f47d54e93defd6',1933,'伪满洲国热河省宁城县县长','伪满宁城县县长，在宁城地区推行伪满政策，征粮征款，协助日军扫荡抗日根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('67f6c2ddec614478a0adc3ed336d688e','fe7588d226fa430ea2eda3d08a162f2f',1933,'伪满洲国热河省赤峰县商会会长、维持会会长','赤峰县商会会长，日军占领赤峰后出面组织维持会，为日军筹粮筹款，协助日军维持地方秩序，是赤峰地区经济界附逆代表。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d8baf920a66e49d89746151e4b66994f','ec93a293db184a58ad8d17904057585b',1933,'伪满洲国热河省赤峰县教育局长','伪满赤峰县教育局长，推行亲日奴化教育，强制学校教授日语和伪满建国精神，篡改历史教材，毒害青少年，是赤峰地区教育界附逆代表。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bd0c65de30854239a81cb40319cceba8','f126bfccba21490f9263837a904b70db',1933,'伪满洲国兴安西省巴林左翼旗警务科长','蒙古族，伪满巴林左翼旗警务科长，负责当地警察特务系统，搜捕抗日人员，推行保甲连坐，配合日军和伪兴安军扫荡抗日武装。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2b4332cc7b6b464982d9d95199a252bb','224924331d2b4338bdd6ad0e7b6826ce',1933,'伪满洲国兴安西省巴林左翼旗自卫团团长','蒙古族，伪满巴林左翼旗自卫团头目，组织地方伪武装，配合日军和伪警维持治安，镇压抗日民众，征粮征畜。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9a683046f6ac45029193c8619b3c19f0','f3570c15e17a4ba4a318204458cf18c2',1933,'伪满洲国热河省赤峰县警察署长','伪满赤峰县警察署长，直接指挥警察在赤峰城乡搜捕抗日人员，推行治安强化运动，制造白色恐怖。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a0450c92d05441838df0eb1f8c8d8481','903927f67ccb4497af93b39c850dc3c8',1933,'伪满洲国热河省赤峰县协和会会长','伪满赤峰县协和会会长，利用协和会组织进行亲日宣传，协助日军征集劳工、物资，推行奴化教育，是赤峰地区文化宣传领域附逆代表。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e0fbb614b29f4aa9a377b0491faff1a8','df4ac79bd5494ff9b25803f1ffee94c7',1933,'伪满洲国热河省林西县警务科长','伪满林西县警务科长，在林西地区搜捕抗日人员，配合日军扫荡，推行保甲连坐，镇压抗日民众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1b38f93631a349b9891875691cf14e88','4a95cfec15a24a8c80e8a4edac712d00',1933,'伪满洲国热河省经棚县警务科长','伪满经棚县警务科长，在经棚地区负责警察特务工作，搜捕抗日人员，协助日军维持殖民统治。','基层头目','hanjian');
