INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('59d4524c3acd44b8b26cd3c54605893f','237102c0c000415083eb9599a504f23f',1936,'伪蒙疆联合自治政府参议、伪蒙古军政府参议','蒙古族，早年从事内蒙古自治运动，后投靠日本，任伪蒙古军政府参议、伪蒙疆联合自治政府参议，为日军在蒙疆地区殖民统治出谋划策，其活动范围涉及昭乌达盟等地。','无明确职位或一般帮凶','hanjian');
