INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7bcb9cc46e9b4969a8a13b5cdbeaf19a','759cfb5f46624562bc0d114d5292cbca',1933,'伪满洲国热河省宁城县协和会会长','伪满宁城县协和会会长，在宁城地区进行亲日宣传，协助日军征集劳工和物资，推行殖民统治。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b17882587f67433da9afed4e089d3799','5f82d23ccd2e45fd9e59f76c92bcc9ad',1933,'伪蒙古军总司令、伪满洲国兴安西省省长','原为热河地方军阀，1933年投靠日军，任伪蒙古军总司令，参与侵占赤峰、敖汉旗等地，镇压抗日力量，协助日军推行殖民统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9b8ccf3da9d74f04ac6d93e70e9e5cce','ec26ab26d6bb4c4b8f8348f1bb125cd7',1937,'伪敖汉旗公署旗长','任伪敖汉旗旗长期间，积极推行日伪“治安肃正”政策，强征劳工，搜刮粮食，配合日军“讨伐”抗日武装。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('78e74925c849456ea003d96cc813175d','ab28ae6889664fc4aba73830c62a3525',1938,'伪敖汉旗警察署署长','效忠日伪政权，指挥警察抓捕抗日志士，破坏地下抗日组织，参与“清乡”行动，残害百姓。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('22dcddbef9b4479c825484bb3542f66f','3a9e402192aa460fb51a927d874bb93e',1939,'伪敖汉旗保安队队长','率保安队协助日军“扫荡”，在敖汉旗南部山区多次袭击抗日游击队，杀害多名抗日人员及群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('458912d142174e6182e88d2957150dda','13debc192e144894821da88a09c34c76',1940,'伪敖汉旗教育督学','推行奴化教育，强制学校使用日语教材，宣扬“日满亲善”，迫害有爱国倾向的教师和学生。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('158c488e74f24b25b6ca1d81515f1071','af96068e274a4fdfb011573dd045f17a',1941,'伪敖汉旗协和会事务长','负责协和会宣传，组织“勤劳奉仕”运动，强迫民众为日军修路筑堡，收集情报供日军使用。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dbb1f870471947b782607728b2d97cc8','5f82d23ccd2e45fd9e59f76c92bcc9ad',1933,'伪蒙古军政府/伪蒙古联合自治政府副主席、伪蒙古军总司令','热河抗战后投靠日军，参与组建伪蒙古军，长期在赤峰、昭乌达盟一带配合日军围剿抗日武装，推行伪蒙疆政权统治。；热河抗战后投敌，组织伪军配合日军侵占赤峰及昭乌达盟地区，在赤峰一带推行伪蒙疆统治，强征物资、镇压抗日民众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ebee72439a7044d99f664ced43d41ec1','78198cf336e24d25a8e52cd58ddf4575',1936,'伪蒙古军政府主席、伪蒙古联合自治政府主席','在日军扶植下建立伪蒙疆政权，其势力范围覆盖内蒙古中东部，包括赤峰及昭乌达盟部分地区，推行亲日附逆政策。；在日军扶植下建立伪蒙疆政权，其势力范围覆盖赤峰及昭乌达盟，推行亲日卖国政策，协助日军控制内蒙古东部地区。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6f55d48ed4bf4c1386b80375dbec3c34','529eba01fd3844d2a4780badaf25cb50',1936,'伪绥西联军司令、伪蒙古军参议','绥远、内蒙古西部投日汉奸武装头目，其活动与伪蒙疆政权关联，间接影响赤峰地区伪蒙统治体系。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('623c1419104446fab74adae7a5647fee','f27fdea68c0f4c87901d2593feda5141',1937,'伪蒙古联合自治政府参议、伪大同省省长','伪蒙疆政权汉奸官员，协助日军在内蒙古及周边推行保甲、征粮、劳工等政策。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('35c7610ee9004a218f0c718e412953cc','ec26ab26d6bb4c4b8f8348f1bb125cd7',1936,'伪蒙古军政府/伪蒙疆政权官员','参与伪蒙疆政权警务与地方行政，在赤峰等地的伪警察系统中配合日军镇压抗日人员。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4ecd3934e3404229af723cffcd5e2edb','62417760c1864e2e8457d56b115babbd',1933,'伪热河省公署官员（日伪时期）','热河沦陷后附逆，参与伪热河省政权，赤峰属热河省，其行政体系覆盖赤峰地区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('01ba1e9f7b794b8aa393162928977761','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洲国热河省警备司令、伪军头目','九一八后投日，率伪军参与侵占热河，赤峰地区沦陷后其伪军配合日军维持统治、讨伐抗日武装。；率部投敌，参与日军进攻热河，其伪军活动范围包括赤峰地区，配合日军镇压抗日力量。；原东北军将领，九一八后投敌，率伪军配合日军进攻热河，参与攻占承德等地，在承德及河北北部地区进行殖民统治与军事镇压。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d1e3a4c0260a47b4a949fbfba9e7a8d7','177c17b9b440453fa41ed47b9ebbd502',1933,'伪军头目（曾投日）','流窜热河、赤峰一带的武装匪首，曾投靠日军任伪职，在赤峰周边烧杀抢掠并配合日伪行动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6b4858c3d1f049a1810e7d61ee6272de','56e668bf262e4d84a8cfe302e67fed6a',1933,'伪赤峰县公署县长（日伪时期）','赤峰沦陷后出任伪县长，推行日伪政令、征粮征丁，协助日军控制赤峰地区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2008feb655504b139f98f1dc3388d6eb','faf1e7317adc4737b491d3a86435b024',1933,'伪赤峰县警务科/伪警察头目','在赤峰地区充任伪警察官员，参与搜捕抗日人员、维持保甲连坐制度。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('88b71cfa2f3748e496a477a6a575e495','e34a65e1af1741468aca97b6d3b72f26',1933,'伪赤峰县维持会会长','赤峰沦陷初期组织维持会，为日军筹粮筹款、招募伪职人员，协助建立殖民秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ca898ba67fbe421aa87a122dd33388a0','8b7be2b481084758b6da84f745fc62df',1933,'伪赤峰县商会会长（附逆）','作为赤峰商界附逆代表，为日伪筹集物资、摊派款项，协助经济统制。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b3cd71f134b946d38fd3244b3b221a9a','774fb6d910c54de7bdee32de25a7e58b',1933,'伪昭乌达盟/伪兴安西省旗长','赤峰北部昭乌达盟地区蒙古王公附逆，出任伪旗长，配合日军推行伪蒙疆统治。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d7d0337c5d564b23ad13b7e347e6e74f','8c752e677e2744f183398498bb5e3ff6',1933,'伪昭乌达盟旗札萨克/伪旗长','在赤峰附近昭乌达盟旗地投日，协助日伪征收牲畜、粮食，维持地方伪政权。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('51c07dcf16764e518d7a76880e9dec23','fa557afa474045dbb2dcc220f3e11f25',1933,'伪兴安西省官员','在伪兴安西省（辖赤峰北部）任职，参与日伪对昭乌达盟地区的行政与警务控制。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('af106d97be634f3aaeca1cddb3a5aa34','6ad1b280d7654edd89e3b7c53bf3e430',1930,'伪蒙古军政府/伪蒙疆政权官员','伪蒙疆政权中的汉奸官员，参与对内蒙古东部包括赤峰地区的殖民宣传与行政。；投靠日本，参与伪蒙古军政府及伪蒙疆政权活动，在内蒙古东部与西部之间进行联络与统治，其活动与通辽一带蒙旗有间接关联。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('20de38b61ea041fc80bd04e388841ba3','993cd83aa8c54ff38e0622e1de731309',1936,'伪蒙古军政府官员','早期蒙古独立运动投日分子，在伪蒙疆政权中任职，其活动范围涉及赤峰周边。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a08a3468fa9e49a0915655c1f77a55fa','b002e65e42f14f4fbbadc0ebf8786c9e',1933,'伪林西县县长','任伪林西县县长期间，为日军征粮派夫，强征民力修建军事设施，协助日伪政权推行保甲制度，镇压当地抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c003be0a67254fa6bf4b18c5e373afbd','3a9e402192aa460fb51a927d874bb93e',1933,'伪赤峰地区保安队队长','原为地方土匪头目，投日后任伪保安队队长，率部配合日军“扫荡”赤峰、林西一带抗日武装，残害百姓，掠夺财物。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4d1801888a68489f955f6d0baa8d19b2','03214a24b080428583bfed7e21cd444e',1935,'伪林西县警察署署长','任伪警察署长期间，积极搜捕抗日地下人员，破坏抗日组织，为日军提供情报，并参与强迫民众种植鸦片等殖民经济政策。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3593cb8a66fd4b40abdde5e303994105','1bf856505e3c422aa408d2d00dc1810c',1933,'伪赤峰县维持会会长','日军占领赤峰后，率先组织维持会，为日军筹粮筹款，协助建立伪县公署，后任伪赤峰县协和会会长，推行奴化宣传。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('79d70bce720b42cfbf06bd81ea23982c','6d910a45b1a7467fb82c0cb49240ddc5',1938,'伪林西县协和会事务长','负责伪协和会在林西的日常事务，组织“宣抚班”进行亲日宣传，强迫民众参加“勤劳奉仕”劳动，为日军提供劳役。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bc07facfb35d4aa0bd3184f639dceb6f','1f7b7d3c61834160b2dec5b3755c3c15',1935,'伪赤峰地区特务机关翻译','为日军特务机关担任翻译，参与审讯、迫害抗日志士，多次带领日军搜查林西、赤峰周边村庄，导致多名抗日人员被捕牺牲。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b1594bec61bd455ca505f353b8c39edd','64f7e2c362324f7c8ebbecd6fb02d6e4',1931,'伪兴安军军官、伪满军政部官员','与甘珠尔扎布共同投日，在昭乌达盟及赤峰地区协助日军建立伪政权、编练伪军。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ca72101a9bf14f97b1dfaf809c9f9ad6','f4208529cb14438593c9984febac079f',1932,'伪兴安南省警备军司令、伪兴安军管区司令','率部投靠伪满洲国，在赤峰及周边地区镇压抗日武装，维持日伪统治。；扎赉特旗王公出身，投靠日军，任伪兴安南省警备军司令等职，活动范围包括哲里木盟、通辽一带，率伪军配合日军“讨伐”抗日武装。','基层头目','hanjian');
