INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e1ac1d1a8e114e4d8abdb6cbf6bfb450','91f1b0f271fc45e08b71fe859fb3a159',1933,'伪赤峰县维持会会长、伪县长','日军侵占赤峰后出面组织维持会，后任伪县长，为日军筹粮筹款、镇压抗日群众。','基层维持会/地方自治头目','hanjian');
