INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e4fa3734811842129c2a549667a6d753','26647d4bb91f4086a567e1a461c53d38',1932,'伪兴安军军官、伪蒙古军将领','在赤峰及昭乌达盟一带率伪军配合日军作战，镇压抗日武装。','无明确职位或一般帮凶','hanjian');
