INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b5d8f797668d44ce9236039c50fb1b9a','c751942e2e3b40dc8fc490a7a38da75f',1932,'伪兴安军/伪满官员','蒙古族上层，投靠日本，在伪兴安系统任职，参与伪满对内蒙古东部地区的控制，与赤峰、昭乌达盟一带伪政权有联系。','无明确职位或一般帮凶','hanjian');
