INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ef0ad6e592ab48cdba8a0c66a48d5004','5f82d23ccd2e45fd9e59f76c92bcc9ad',1933,'伪蒙古军政府/伪蒙疆联合自治政府蒙古军总司令、伪蒙古联合自治政府副主席','热河抗战后投敌，组织伪蒙古军，配合日军侵占赤峰及昭乌达盟地区，在阿鲁科尔沁旗一带推行伪蒙疆政权统治，强征物资、镇压抗日力量。','基层头目','hanjian');
