INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4bcc83cbdec248fe9fd49f3418a03453','64f7e2c362324f7c8ebbecd6fb02d6e4',1931,'伪兴安军军官、伪满兴安省官员','与甘珠尔扎布共同投日，在伪满洲国兴安地区任职，参与对昭乌达盟及阿鲁科尔沁旗一带的殖民统治和军事镇压。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b92c7f99fb1a4ee5b057f51c813c59f5','f4208529cb14438593c9984febac079f',1932,'伪兴安军司令、伪满兴安省省长','投靠伪满洲国，任伪兴安军要职，在昭乌达盟及赤峰地区协助日军维持治安，镇压抗日武装。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fef6c38e8e554229b302f91ca192163b','8625223b5393415fabb6dcd24b19bf94',1930,'伪阿鲁科尔沁旗旗长','在伪满洲国时期任阿鲁科尔沁旗旗长，执行日伪政令，征派劳工、物资，配合日军对当地抗日力量进行压制。','无明确职位或一般帮凶','hanjian');
