INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3cc2555811594ad19fab9e5cd4c8241f','10595860987147a0a24c6815061e8fce',1933,'伪赤峰县县长','日军侵占赤峰后出任伪县长，推行伪满政令，协助日军征粮、派工，镇压当地抗日活动。','基层头目','hanjian');
