INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7df194f23de04fbdac2c7d1aa048c5a8','ec93a293db184a58ad8d17904057585b',1933,'伪赤峰县商会会长、伪协和会成员','在赤峰商界为日伪服务，协助经济统制、物资征集，支持日军殖民经济政策。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('85e1f1ede59744c2b7a22c7b2626013d','177c17b9b440453fa41ed47b9ebbd502',1933,'伪军头目、伪满军旅长','曾投靠日军，率部在赤峰、昭乌达盟一带流窜，配合日军扫荡抗日根据地，残害民众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bb9023918308492aa06904e34b19982e','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洲国热河省省长、伪军司令','投靠日军，参与侵占热河，其伪军活动范围包括赤峰及昭乌达盟地区，协助日军镇压抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e592c7021051475d9594484d0590487f','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满洲国军政部大臣、伪军将领','原东北军将领投日，任伪满军政要职，其指挥的伪军参与热河、昭乌达盟地区治安肃正，涉及赤峰一带。','无明确职位或一般帮凶','hanjian');
