INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('33af9077440d4bd99684b7f975582d03','eb166a17cf664e83aa52590be3bac98d',1931,'伪兴安南省警备军司令','蒙古族投日分子，参与组建伪兴安军，镇压抗日力量，协助日军统治通辽地区。；蒙古族贵族，投靠日本关东军，在通辽地区组织伪兴安军，配合日军围剿抗日武装，镇压当地民众反抗。','基层头目','hanjian');
