INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6d75961bd3ed4a4a8b83b7326efc1dd7','01270fb209c3423ba7bb9f6ce1282f12',1932,'伪通辽县县长','投靠日军后任伪县长，推行保甲制度，强征粮食物资，协助日军建立殖民秩序。','基层头目','hanjian；traitors');
