INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1726ded492b9469c81e2ad182e727a5e','177c17b9b440453fa41ed47b9ebbd502',1933,'伪满‘讨伐’军头目','土匪出身，投靠日军后率伪军在库伦旗、通辽一带‘讨伐’抗日武装，屠杀百姓，掠夺牲畜。','无明确职位或一般帮凶','hanjian');
