INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('30d9cec1ab07490ea96fe0a9faae7f3d','cce0beb18f6444d29b255fd8e4458a06',1932,'伪兴安南省警备军军官、伪地方政权官员','在伪兴安南省及哲里木盟地区任职，参与伪军警活动，配合日军维持通辽、开鲁周边治安，镇压抗日力量。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6ecae19f4a9f4e85bd0f3d841391c128','6687a4d3a75b4c3099f7cb5005501a4e',1933,'伪开鲁县维持会会长、伪开鲁县县长','开鲁沦陷后出面组织维持会，后任伪开鲁县县长，为日军征集物资、推行保甲制度，协助日伪统治开鲁地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ad35edb70e194aaa886902b1096350a2','0994eab753184b9793af3c811589fe29',1932,'伪通辽县维持会成员、伪通辽县公署官员','通辽沦陷后在伪政权中任职，参与维持会及伪县公署事务，协助日军征粮、派夫，推行殖民统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5fcbf60ffd9c4e808a71a978c7bc1d50','60b87ec0dfdb497288f3591064964994',1932,'伪满洲国地方伪军头目（后反正）','曾一度附逆，在通辽、开鲁一带活动，后率部抗日；其附逆期间配合日军维持地方治安，属于该地区有记载的伪军人员。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d28b75c7c6bd451aab13662970760798','26647d4bb91f4086a567e1a461c53d38',1933,'伪蒙古军军官、伪兴安军军官','蒙古族，投靠日军，在伪蒙古军及伪兴安军系统任职，活动于内蒙古东部，包括通辽、开鲁周边，参与对抗日武装的军事行动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('12788b823aba4667b90aa3f5af9db9e9','1b364e4416e748f8a75965b89cc5b90d',1932,'伪哲里木盟警备军司令、伪地方武装头目','哲里木盟蒙古族地方武装首领，投靠日军后任伪警备军司令，控制通辽、开鲁一带，配合日军“治安肃正”，镇压抗日民众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5e05c5392e7847599f4422892eb8baea','91f1b0f271fc45e08b71fe859fb3a159',1932,'伪哲里木盟警备军军官、伪地方政权官员','在伪哲里木盟地区任职，参与伪军警活动，协助日军控制通辽、开鲁等旗县，推行保甲与物资统制。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b74863cc39d74cd2b637fbf9c4e37fb9','7093eefa17974f1fadbd9bd539b96680',1932,'伪哲里木盟地方伪军头目','哲里木盟一带蒙古族地方武装头目，投靠日军后编入伪军，在通辽、开鲁周边配合日军行动，骚扰抗日根据地。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dbf32c37c49c4f7681aec7e400381182','5f82d23ccd2e45fd9e59f76c92bcc9ad',1933,'伪蒙古军政府/伪蒙古联合自治政府军事头目、伪蒙疆政权高级将领','原为东北军骑兵军官，后投靠日本，参与组织伪蒙古军，任伪蒙古军总司令等职，配合日军在内蒙古东部及热河、察哈尔一带作战与统治，其势力活动范围涉及通辽及周边蒙旗地区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c55df119559644bc97726af0a3ed295d','eb166a17cf664e83aa52590be3bac98d',1931,'伪满洲国兴安局/兴安总署官员、伪蒙古军头目','蒙古王公出身，九一八事变后投靠日本，参与策划内蒙古东部‘独立’活动，后在伪满洲国任职，参与统治包括通辽一带在内的东蒙古地区，协助日军镇压抗日力量。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9a64aabae8184531aeb53085e4b44f70','f4208529cb14438593c9984febac079f',1932,'伪满洲国兴安南分省省长、伪兴安局官员','原哲里木盟科尔沁左翼中旗札萨克，投靠日本后任伪兴安南分省省长等职，管辖范围包括今通辽一带，推行伪满政策，协助日军控制东蒙古地区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c555b026b3b34538b9f568027d00d551','cce0beb18f6444d29b255fd8e4458a06',1932,'伪满洲国兴安南省官员、伪旗长','在伪满洲国时期于兴安南省任职，参与管理今通辽及周边蒙旗事务，执行日本殖民统治政策，属于当地附逆政权人物。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bcfab93afaf341d4ad4ffdbd17b94ae8','df1707c172784b80bcaa9bcbbf010375',1932,'伪满洲国兴安南省官员、伪蒙旗札萨克','作为东蒙古王公之一，投靠伪满洲国，在兴安南省范围内协助日军和伪政权管理地方，其活动区域与今通辽市及扎鲁特旗周边有交集。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('34e1f585a00142d6810043bca8d7a983','1d9c4d774696466e8f5d26e655bb9b30',1930,'伪满洲国兴安南省警备军军官','曾在伪满洲国兴安南省警备军任职，参与维持日伪在东蒙古地区的统治秩序，活动范围涉及通辽一带；后于1945年后转向内蒙古自治运动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b01b0f8303724efea55fce1787e90de0','ee355c103d84497b9d13add34596e6b0',1930,'伪满洲国兴安南省地方官员、伪旗长','在伪满洲国时期担任兴安南省地方旗县职务，协助日伪推行保甲、征粮、劳工等政策，属于通辽周边地区附逆地方头目。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3f307102fd424ef69b626902f69e8a27','5432fbdab70b4846bf4358ef4c3d0c29',1930,'伪满洲国兴安南省官员、伪蒙旗协理','在伪满洲国东蒙古地区任职，参与地方行政与治安维持，配合日军对通辽及周边蒙旗的控制。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4f7b2db6e0de41f78c2f14cc889f8e8b','1bf856505e3c422aa408d2d00dc1810c',1930,'伪满洲国通辽县公署官员、伪警察头目','在伪满洲国通辽县任职，参与伪政权地方行政与警察事务，协助日军维持统治、镇压抗日活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f24f8524cbd845e1baceb73f9d9186f6','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满洲国奉天警备司令、伪军头目','原东北军军官，投靠日本后任伪奉天警备司令等职，其伪军活动范围覆盖辽宁、内蒙古东部及通辽周边，协助日军维持殖民统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b2f0eacbb00440dc96b95c8576eda479','c9dffc071fec4ce58fe1d611f26c28da',1930,'伪满洲国军军官、伪辽西地区警备头目','在伪满洲国军中任职，参与辽西及内蒙古东部地区治安作战，活动范围接近通辽一带，协助日军镇压抗日力量。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0b2baa8499d84737a7a73c4f9c729164','26647d4bb91f4086a567e1a461c53d38',1930,'伪满洲国兴安南省警备军军官','在伪满洲国兴安南省警备军任职，参与东蒙古地区治安与军事行动，活动范围包括通辽周边蒙旗。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('42c7ac2c81b84cd5a1a11f9290e41cf5','78198cf336e24d25a8e52cd58ddf4575',1933,'伪蒙古军政府主席、伪蒙疆联合自治政府主席','锡林郭勒盟苏尼特右旗札萨克，投靠日本，主导伪蒙古军政府及伪蒙疆政权，虽主要活动于察哈尔、锡林郭勒一带，但其伪蒙政权名义上覆盖内蒙古东部，与通辽地区有政治关联。；在锡林郭勒盟及察哈尔、绥远一带组织伪蒙政权，投靠日本关东军，建立伪蒙古军政府并任主席，后任伪蒙疆联合自治政府主席，配合日军统治内蒙古中东部地区。；在察绥地区建立伪政权，其势力与晋陕绥边区接壤，配合日军对榆林、府谷方向进行政治渗透和军事袭扰。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('96c4cc456d64459cab54c0b7bd5b4a0f','eb166a17cf664e83aa52590be3bac98d',1932,'伪兴安南省省长、伪满洲国陆军中将','科尔沁左翼中旗人，蒙古族。九一八事变后投靠日本关东军，参与组建伪兴安军，任伪兴安南省省长，协助日军镇压蒙古族抗日武装，推行奴化教育，强征劳工，为日军提供物资和情报。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a494aab885c44be2990fa449f8df0f72','64f7e2c362324f7c8ebbecd6fb02d6e4',1932,'伪兴安军总参谋长、伪满洲国陆军少将','科尔沁左翼中旗人，甘珠尔扎布之弟。长期在伪兴安军任职，参与指挥伪军围剿抗日游击队，配合日军“治安肃正”行动，残害抗日军民。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a9a9fa83e1e64d769a3c9de24a998ecc','e3fb45039e084f0cb65ade10e5bd480e',1933,'伪兴安南省警备军司令','科尔沁左翼后旗人，蒙古族。投靠日军后任伪警备军司令，多次率伪军袭击抗日武装，协助日军建立“集团部落”，制造无人区，强征牧民从军。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('89333410687845f0bde48e69826dff5f','a538250160da4bfbabeeecbf23766d8b',1934,'伪兴安西省省长（后并入兴安总省）','科尔沁右翼前旗人，蒙古族。任伪省长期间，推行日本殖民政策，强征土地，组织伪警察镇压反抗，为日军提供粮食和牲畜。','省部级/大军区级要员','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2ef02ad4d3d047efba988cfd96f81128','ab966a2270544625a04f537eaf5faf8a',1935,'伪通辽县公署参事官、伪兴安南省民政厅长','科尔沁左翼中旗人。在通辽地区协助日军建立保甲制度，强征劳工修建军用公路和机场，参与“清乡”行动，逮捕抗日地下工作者。','市县厅局级','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('475fd544481d406e8dc83dc49fffa558','838979c5881d455d9908a863bc24d449',1936,'伪兴安南省警务厅长','科尔沁左翼后旗人。主持伪警务，组织特务网，破坏抗日地下组织，多次率警察队围剿抗日游击队，刑讯逼供抗日志士。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('00253d41975f416bac74124be2239722','c6294457b2f2458d8f85e6a3418803b4',1937,'伪科尔沁左翼中旗旗长','在旗内强制推行“出荷粮”制度，搜刮民财，强征青年加入伪满军，协助日军镇压蒙古族民众的反抗运动。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d3d63fbfe22846bd86d1f9a4e0855afa','6ac45c4c648e4eb5afbd66ec5b651229',1938,'伪科尔沁左翼后旗旗长','积极执行日本“开拓团”移民政策，强占牧民草场，组织伪旗公署武装配合日军“讨伐”，杀害抗日群众。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('02a08214364c4ad0aa14660d2e9bec67','1d9c4d774696466e8f5d26e655bb9b30',1939,'伪兴安南省警备军团长（后反正）','科尔沁左翼中旗人。早期在伪军中任职，参与镇压抗日活动，但后期于1945年8月率部反正，故仅列其投敌时期行为。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1a2dbd7d61f6484ea465d6847fd2e680','78b88211e51b47ba881800e4ea3c6860',1940,'伪通辽地区保安队队长','在通辽县城及周边为日军充当鹰犬，搜捕抗日分子，参与“三光”政策下的扫荡行动，抢劫百姓财物。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2dea311af9a947c68d2fa505a1302a7b','eb166a17cf664e83aa52590be3bac98d',1931,'伪满洲国兴安南省警备军司令、伪兴安局总裁','蒙古族上层亲日派，参与策划‘内蒙古独立’活动，任伪满兴安南省警备军司令，率伪军配合日军在通辽、科尔沁左翼中旗一带围剿抗日武装，后任伪兴安局总裁，推行日本殖民统治政策。；蒙古族上层亲日派，参与策划‘内蒙古独立’活动，投靠日本关东军，在伪满洲国任职，统辖包括科尔沁左翼后旗在内的东蒙古地区伪军警，配合日军镇压抗日力量。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c0d03b2512414d43a99da5b6c38d4c56','64f7e2c362324f7c8ebbecd6fb02d6e4',1931,'伪满洲国兴安南省警备军参谋长、伪第十军管区司令','甘珠尔扎布之弟，长期在伪兴安南省警备军任职，参与指挥伪军在通辽、科尔沁左翼中旗地区镇压抗日力量，后任伪第十军管区司令，协助日军维持对东蒙古地区的控制。；甘珠尔扎布之弟，长期在伪兴安南省及通辽一带任职，指挥伪军配合日军‘讨伐’抗日武装，控制科尔沁左翼后旗等地的治安。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cfe3ce4e85704a3c9971944742631fb7','f4208529cb14438593c9984febac079f',1932,'伪满洲国兴安南省省长、伪兴安局总裁','原哲里木盟科尔沁左翼中旗札萨克亲王，投靠日本后任伪兴安南省省长，在通辽、科尔沁左翼中旗等地推行保甲制、征集劳工和物资，支持日军‘治安肃正’。；原哲里木盟科尔沁左翼后旗札萨克郡王，投靠日本，出任伪兴安南省省长等职，协助日本在通辽及科尔沁左翼后旗推行殖民统治、征发劳工和物资。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('299530b76c6149c1aa1b5158cfac3859','6ac45c4c648e4eb5afbd66ec5b651229',1932,'伪满洲国兴安南省警备军团长、伪科尔沁左翼中旗旗长','在科尔沁左翼中旗任职期间，组织伪自卫团配合日军扫荡，强征粮食和牲畜，镇压当地抗日群众，是通辽地区较有影响的附逆者。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('524f81aedb4e4e2284f26ad5ecb5a70c','1b364e4416e748f8a75965b89cc5b90d',1932,'伪满洲国兴安南省警备军统领、伪哲里木盟盟长','原科尔沁左翼中旗蒙古族武装头目，投日后任伪兴安南省警备军统领，率部在通辽、科尔沁左翼中旗一带配合日军作战，后任伪哲里木盟盟长，推行殖民统治。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3a8e07ccc3484adabefa1b0837a94e5f','78198cf336e24d25a8e52cd58ddf4575',1936,'伪蒙古联合自治政府主席、伪蒙疆政权首脑','锡林郭勒盟苏尼特右旗札萨克亲王，在日本支持下成立伪蒙疆政权，其势力范围覆盖内蒙古东部，包括通辽、科尔沁左翼中旗地区，推行亲日殖民政策，协助日军征调物资和兵员。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2f37096dceaf4fd59778f4c73e15699f','6687a4d3a75b4c3099f7cb5005501a4e',1932,'伪满洲国通辽县县长','在通辽县任职期间，推行保甲连坐制度，强征劳工和粮食，配合日军‘治安肃正’，镇压当地抗日活动，是通辽地区伪政权核心人物之一。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4ec2c3c21c084c549f65df878144425e','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洲国洮辽镇守使、伪热河省省长','原东北军将领，九一八后投敌，任伪洮辽镇守使，其防区包括通辽、科尔沁左翼中旗一带，率伪军配合日军进攻抗日武装，后任伪热河省省长。；辽宁盖平人，原东北军将领，九一八事变后投敌，任伪洮辽镇守使，率部进攻锦州、热河等地，配合日军作战。；原东北军将领，九一八后投敌，率伪军进攻黑龙江，参与围剿马占山等抗日部队。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9d0d8529c74648b3b966c4ab67334fff','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满洲国奉天省警备司令、伪第一军管区司令','原东北军东边道镇守使，投日后任伪奉天省警备司令，其部队在通辽、科尔沁左翼中旗地区参与围剿抗日义勇军，后任伪第一军管区司令。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a9a749d8ec80467295893deb6268f51f','26647d4bb91f4086a567e1a461c53d38',1932,'伪满洲国兴安南省警备军参谋、伪第十军管区参谋长','在伪兴安南省警备军任职期间，参与制定对通辽、科尔沁左翼中旗地区抗日武装的作战计划，协助日军维持殖民统治。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('067f504df17f4340a18cbc20b9a9c4d5','1d9c4d774696466e8f5d26e655bb9b30',1935,'伪满洲国兴安南省警备军连长、伪科尔沁左翼中旗自卫团团长','在科尔沁左翼中旗组织伪自卫团，配合日军征粮、抓劳工，镇压当地抗日群众，是旗内较活跃的附逆者。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('03b34e3d5f8341ea9c216d906a7d0726','5432fbdab70b4846bf4358ef4c3d0c29',1932,'伪满洲国科尔沁左翼中旗旗长','任伪科尔沁左翼中旗旗长期间，推行日本殖民教育，强征物资，组织伪警察维持治安，协助日军镇压抗日活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a307781df24e4a24aacf4810c919feaa','91f1b0f271fc45e08b71fe859fb3a159',1931,'伪满洲国通辽县维持会会长','九一八后组织通辽县维持会，迎接日军进城，协助日军建立伪政权，后任伪通辽县参事。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2c78f97fd4324d43b308d042249719c2','82a28e1bf3114256b2f73824a84188b9',1932,'伪满洲国兴安南省警备军骑兵第三团团长、伪科尔沁左翼后旗旗长','在科尔沁左翼后旗及通辽地区任职，组织伪旗政权和伪警察队，配合日军维持‘治安’，镇压当地抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('be1af072d09e4a6f976f4f77ef450984','5432fbdab70b4846bf4358ef4c3d0c29',1933,'伪科尔沁左翼后旗旗长、伪兴安南省参事官','在科尔沁左翼后旗充任伪旗长，推行保甲连坐，协助日军征粮、征兵，控制当地民众。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('16df0e98801544dcb20e38a3b40d348e','ab966a2270544625a04f537eaf5faf8a',1935,'伪科尔沁左翼后旗警务科长、伪警察大队长','掌管科尔沁左翼后旗伪警察武装，多次配合日军和伪兴安南省警备军搜捕抗日人员，迫害当地百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6b77412480774289a9b7d95958a75387','529eba01fd3844d2a4780badaf25cb50',1937,'伪绥西联军司令、伪蒙古军第一军军长','率伪军活动于内蒙古西部及通辽一带，配合日军扫荡抗日武装，在科尔沁左翼后旗附近参与‘治安肃正’。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('64a09a6d074d496eb0f8bfa136ef18c4','1b364e4416e748f8a75965b89cc5b90d',1932,'伪科尔沁左翼后旗保安队队长、伪兴安南省警备军骑兵第四团团长','在科尔沁左翼后旗组织伪保安队，协助日军维持地方秩序，镇压抗日群众，征发民夫和物资。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('689532f74b444527814cc37e258f318d','a054a23514d54325b60b7af72c017186',1934,'伪科尔沁左翼后旗参事官、伪兴安南省民政厅官员','在科尔沁左翼后旗伪旗公署任职，推行日本殖民教育、经济统制政策，协助日军掠夺当地资源。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fbb6588c112d4434a80c35d88d7b8484','62df5801e3994d7689d34b7f503e286c',1936,'伪科尔沁左翼后旗保甲长、伪警察分驻所所长','在科尔沁左翼后旗基层推行保甲制度，监视民众，向日军举报抗日人员，配合伪警察抓捕抗日群众。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('eb1de8b2fd3047308ab3d0daa137c3d0','b86083bd13c04af7ae64c9ee8b5ee802',1936,'伪蒙古军政府总参谋长、伪蒙古军中将','参与伪蒙古军组建，在通辽及哲里木盟地区协助日军清剿抗日武装，强征民夫，为日军提供情报和后勤支持。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f6408308a9e64bcf82068a4c76ca5c28','26647d4bb91f4086a567e1a461c53d38',1937,'伪蒙古军第1师师长、伪蒙古军第9师师长','在通辽、开鲁等地率伪军配合日军“扫荡”，屠杀抗日军民，抢夺牲畜粮食，破坏抗日根据地。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0da7524263ce4efd93ac07ea61696883','838979c5881d455d9908a863bc24d449',1932,'伪兴安西省省长、伪满洲国兴安总署参事','在通辽所属的兴安西省（今通辽部分地区）任伪职，推行伪满洲国殖民政策，强征土地，组织伪警察镇压反抗。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('344e25949fa14441933d4177d5fe6397','46bdbef915d04290844d3ac5b0822ea5',1932,'伪通辽县县长','任伪通辽县县长期间，为日军征收粮饷，抓捕抗日志士，协助日军建立保甲制度，实施“连坐”统治。；在通辽县任伪县长期间，推行日伪殖民政策，强征劳工，搜刮民财，协助日军维持治安，镇压抗日活动。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('97fe4b76b95545b0bd13f0f0799d241e','591d4a21312043d6ba673fbb1ee7d66d',1933,'伪通辽县警务科科长','指挥伪警察在通辽城区及周边搜捕地下抗日人员，刑讯逼供，多次参与日军“讨伐”行动。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dcdf3c061c5444b7b51f5cbdc3967217','a8113b07673245d9a6314719dff943a0',1935,'伪兴安南省警备军团长','在通辽、科尔沁左翼后旗等地驻防，参与日军“治安肃正”，围剿抗日游击队，残害蒙汉民众。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('89361b802f784b5cab0f9f43a8f1f7ea','6dec6f2201c84d729ec0c0b13ca17e6e',1932,'伪兴安西省警务厅长','在通辽地区推行伪满警察制度，组织特务网络，破坏抗日组织，协助日军强征劳工。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('323e11e249954e7fa25cbd4e7cede8c7','e3fb45039e084f0cb65ade10e5bd480e',1931,'伪兴安军顾问（死后追认）','曾为匪首，其子甘珠尔扎布等继承其投日路线，巴布扎布本人早年即与日本勾结，在内蒙古东部地区活动，为日军提供情报和武装支持。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4e27522fada04a6885dadd3592d6a987','1ba31d558b934fbd83a28a8c2b446022',1933,'伪满热河省警备司令（曾辖通辽部分地区）','原奉系军阀，后投敌，在热河及通辽周边地区担任伪职，配合日军进攻抗日武装，参与“治安肃正”行动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0ad9410ecaf14e228fece17aedef1d9f','26647d4bb91f4086a567e1a461c53d38',1934,'伪兴安西省省长（辖通辽西部）','蒙古族投日分子，在兴安西省（含今霍林郭勒附近区域）推行日伪统治，组织伪警察和保甲制度，迫害抗日群众。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('63eddc61e6144a5bbf6cb6d3076f2a8d','9a71a3b895854c0496b76fe9a6fc7449',1932,'伪兴安南省警务厅厅长','在通辽、哲里木盟一带负责伪警务，协助日军搜捕抗日志士，参与“讨伐”活动，残害当地百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e08889da0f1445ebb299df2a0506b38b','c94f058ddf0448068e37a5d4ac1c1a8d',1936,'伪蒙古军政府秘书长、伪蒙疆政府参议','在鄂尔多斯地区为日军搜集情报，协助伪政权征粮派款，破坏当地抗日地下组织。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b3a86ef9533e48b38d5fb77e8b960455','3a09ae0f7f294a118069ecfbec5ba35b',1938,'伪伊克昭盟盟长（后任）','在日军扶植下担任伪伊克昭盟盟长，强迫各旗王公向日军效忠，组织伪警察镇压反抗民众。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('78c3fbbf87d643dfa75db4883107f785','b2c6142dabeb4ac78a0a05ad8abc5952',1939,'伪伊克昭盟副盟长、伪鄂尔多斯保安队指挥官','协助日军在鄂尔多斯建立伪保安队，参与抓捕抗日志士，为日军提供劳役和粮食。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fedf868a156d421bb1c4edda0135c2fc','c7d694b2b1e142bd994011d2918cf246',1937,'伪达拉特旗扎萨克（旗长）','投靠日军，在达拉特旗推行“保甲制度”，强征壮丁补充伪军，并配合日军对黄河以南地区进行经济封锁。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('071c9e6111e4482ea5b580faf9a73f95','b2cf09cadc5f425583887274017cb840',1938,'伪杭锦旗协理、伪蒙古军第9师军官','在杭锦旗为日军征收牲畜和皮毛，参与围剿中共领导的桃力民抗日游击队。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c7c5e26cf4fd4f4a9f39bdc3ca80cdf5','e1fb3b340a0442438c3b78ea466d0018',1939,'伪乌审旗保安团长、伪伊克昭盟警备军指挥官','在乌审旗残酷镇压牧民抗日活动，多次袭击八路军骑兵支队，杀害多名革命干部。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('509632acd0ae4afeb62f07720cfbc1ba','088320714ff747b3a87cd7d2fc54ab67',1940,'伪鄂托克旗保安司令','依附日军，在鄂托克旗设立伪警察所，禁止牧民与抗日武装接触，并参与日军“清边”行动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('75d24e83a7b542c497668ea1a3abf7e5','2c4129b4e319444ca3f8347012c04c83',1937,'伪准格尔旗协理','为准格尔旗日军据点提供情报，协助伪军强征民夫修筑工事，迫害倾向抗日的蒙古族青年。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dc9cdef8c95641b5ad1927551321c0dd','57b39a02f01842edaa731a99bee9fca9',1938,'伪郡王旗（今伊金霍洛旗）扎萨克','公开投日，在郡王旗悬挂日本旗，强迫旗民向日军献马献粮，并阻挠成吉思汗陵西迁中的抗日宣传。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c1e3dce9039a4089ad060a8017eef613','7fbc5bba07664eaeb5bb4b15cbd692f7',1941,'伪札萨克旗（今属伊金霍洛旗）保安队长','率伪保安队配合日军“扫荡”札萨克旗南部，抓捕并杀害抗日地下交通员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('86912404b50b449fa83528435f92ff8f','8c62f1b3cf2c4ce0a5bd4d41e3c0130a',1937,'伪伊克昭盟盟长（初期）','在日军威逼下曾出任伪盟长，默许日军在鄂尔多斯设立特务机关，后因国民党争取而动摇，但前期行为已构成附逆。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3c5a6724c50046b985644cc5b6f5424e','b2e5621efda2431aaad68631f85c6b8f',1938,'伪伊克昭盟盟长、伪蒙古军第2军军长','蒙古族贵族，投靠日本后任伪伊克昭盟盟长，在鄂尔多斯地区推行日伪统治，强迫牧民缴粮纳税，协助日军清剿抗日力量。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('58cf3fbf9f7a47f09250404b38915119','b2cf09cadc5f425583887274017cb840',1939,'伪伊克昭盟副盟长、伪蒙古军第3师师长','在鄂尔多斯地区组织伪蒙古军，配合日军扫荡东胜周边，残害抗日军民，强征民夫修筑工事。','市县厅局级','hanjian');
