INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7b2f46cfa2064376b819a934a73af84d','78c89201b0364968b429bfeffecc66b2',1940,'伪杭锦旗保安队头目','率杭锦旗地方武装投靠日伪，配合伪蒙疆政权维持当地统治，镇压抗日群众。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8ec0b8bdda97410c87982e94d862a993','c7d694b2b1e142bd994011d2918cf246',1939,'伪鄂托克旗维持会成员','在鄂尔多斯鄂托克旗一带为日伪政权服务，协助控制基层、征派粮草，支持日军对周边地区的扫荡。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('38b6f81d14624083a2f315d218eb670f','7f72947b8e0948a785e49bb6979bf8fb',1937,'伪绥远省公署官员','在伪绥远省政权中任职，参与对鄂尔多斯及杭锦旗等地的行政控制，推行日伪法令，协助经济掠夺。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dbab619c9dfc4d298ca04f4c0678c694','b2cf09cadc5f425583887274017cb840',1937,'伪达拉特旗保安司令','投靠日军，任伪伊克昭盟达拉特旗保安司令，协助日军镇压抗日力量，强征民夫修建军事设施。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9b45f3d7bc7543148a7b894d130591f9','b2e5621efda2431aaad68631f85c6b8f',1938,'伪达拉特旗西协理兼保安团长','投靠日伪，任伪达拉特旗西协理，配合日军“扫荡”抗日根据地，向日军提供情报并征收粮草。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7b898543dbaa4ccda6ebddf9397d248b','f3fe76047ec646ee864d30265e2995c9',1939,'伪达拉特旗东协理','充当日军傀儡，参与组织伪旗公署，协助日军推行“治安强化运动”，迫害抗日军民。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3d11fbcbc00544baa682c900ce3df23d','1768a5e0688444da8a81d37c3cf764cf',1940,'伪达拉特旗保安队副官','为日军效力，参与围剿八路军游击队，抓捕并杀害抗日群众，充当日军翻译和密探。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d7589b77bf7c463e9452d9ff64d89aeb','0ea96cb441d14cb585bf8b339780a9e8',1941,'伪达拉特旗警察署署长','效忠日伪政权，指挥伪警察镇压抗日活动，强征壮丁，勒索百姓，协助日军掠夺当地资源。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c85ecec883da4a1ab18e56922fafda9d','78198cf336e24d25a8e52cd58ddf4575',1933,'伪蒙疆联合自治政府主席、伪蒙古军政府总裁','在日军扶植下于内蒙古中西部建立伪蒙疆政权，统辖察哈尔、绥远等地，推行亲日政策，配合日军对绥蒙地区进行统治和掠夺，其势力范围覆盖鄂尔多斯北部及邻近地区。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('316c2de5862c429d81b9dcd6e723814d','f27fdea68c0f4c87901d2593feda5141',1937,'伪蒙古联合自治政府最高检察厅厅长、伪大同省省长','在伪蒙疆政权中担任司法和行政要职，为日军统治内蒙古中西部提供法律和行政支持，其管辖区域与鄂尔多斯地区有交集。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6197a2e14b7e4a9083f7e7c07e5a69b2','121c3c7b38f845d094cb4b86de3e60a0',1937,'伪鄂尔多斯右翼中旗（鄂托克旗）札萨克、伪蒙疆政权官员','作为鄂托克旗蒙古王公，投靠日军和伪蒙疆政权，在鄂托克旗及邻近地区协助日伪推行统治，维持地方治安，镇压抗日活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e6405a4b5bd6483daee21ecf23cd4772','b2e5621efda2431aaad68631f85c6b8f',1937,'伪准格尔旗保安队司令、伪蒙疆政权官员','准格尔旗蒙古族上层，投靠日伪，组织伪保安队，在准格尔旗及鄂尔多斯东部地区配合日军行动，对抗抗日武装。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5098ce231df640bba295aeecfd17c32e','7e6677f8b2ac46e19a52d965a2a7ef99',1937,'伪准格尔旗协理、伪蒙疆政权官员','准格尔旗蒙古族上层，与奇子祥一同投靠日伪，在准格尔旗及周边地区协助日伪统治，参与镇压抗日力量。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('da4d780b8e2c4af2a82d3607f1286633','096f9b5d1d104fb7b04d130c259ca44b',1937,'伪乌审旗札萨克、伪蒙疆政权官员','乌审旗蒙古王公，投靠日伪，在乌审旗及鄂尔多斯西南部地区协助日军统治，维持伪政权地方秩序。','无明确职位或一般帮凶','hanjian');
