INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('74e94f404f034637939ac18a00390a0b','66066bac37dd47d882181942bce384bc',1937,'伪包头市市长、伪绥西自治联军官员','在包头地区投靠日伪，担任伪职，协助日军在绥西及鄂尔多斯北部进行统治和经济掠夺。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('267bf895da934471b6df1f99a60dec18','6687a4d3a75b4c3099f7cb5005501a4e',1937,'伪萨拉齐县县长、伪绥西自治联军官员','在萨拉齐（今土默特右旗）地区投靠日伪，担任伪县长，协助日军在绥西及鄂尔多斯北部推行保甲制度和掠夺资源。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('585f35b39a494af7ab130b0b6687842a','ef6c08d0f52941eb82c78030ddb226af',1937,'伪固阳县县长、伪绥西自治联军官员','在固阳地区投靠日伪，担任伪县长，配合日军在绥西及鄂尔多斯北部进行统治和扫荡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4b918b1d11c4453daa3a0b8209fc5bd4','157dbf7ebb014a6fb22f7d4fbbc0d056',1937,'伪东胜县维持会会长','在东胜（今鄂尔多斯市东胜区）地区组织维持会，投靠日军，协助日伪在鄂尔多斯中部地区推行统治，维持地方治安。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b9d425e9f9c94a228dec313e70cfb3d4','cd8e5ab701f04770ad28171753ae1ceb',1937,'伪东胜县县长','在东胜地区担任伪县长，协助日军在鄂尔多斯中部地区进行统治，推行保甲制度，掠夺地方资源。','基层头目','hanjian');
