INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('387c6a94ff4347d893ee92aa6149b221','0fd76ff229dc4c61a9a687b820ff1440',1937,'伪达拉特旗维持会会长','在达拉特旗地区组织维持会，投靠日军，协助日伪在鄂尔多斯北部推行统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e3deb06edf5d402cb3489dc7dc910f91','8271af03169441cf827c223f7d310dec',1937,'伪郡王旗保安队队长','在郡王旗（今伊金霍洛旗）地区投靠日伪，组织伪保安队，配合日军在鄂尔多斯中部地区进行统治和扫荡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c7bb538e96954788a25b88a9b40cf73a','b31ae09109e44d79b10ffeae9658f239',1938,'鄂托克旗保安司令部副官、日伪“绥西自治联军”团长','投靠日军后，在鄂托克旗及周边地区为日军搜集情报，协助日军镇压抗日力量，并参与日伪军对当地牧民的掠夺和迫害。','市县厅局级','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('47fa721271634f198c06b9ea3b8ebe2a','a873266d88ed41f08be2837a16f3d6ee',1937,'鄂托克旗保安司令、后投日任伪“伊克昭盟公署”顾问','原为地方武装首领，1938年后暗中与日军勾结，向日军提供军需物资和情报，并阻挠抗日武装在鄂托克旗的活动，1943年被抗日力量处决。','市县厅局级','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('74a42d1173df4ce7a4f74d8eefc20d18','b988f88ff3d54998a3c05446e5264757',1940,'鄂托克旗伪警察署署长','在日军扶植下建立伪警察机构，负责搜捕抗日分子，强征民夫为日军修筑工事，并参与对当地民众的敲诈勒索。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8f14adaa4f0b4679a7bfeadf2cad1361','e1fb3b340a0442438c3b78ea466d0018',1941,'鄂托克旗伪旗长（日伪时期）','在日本顾问控制下出任伪旗长，推行日伪“蒙疆”政策，强制收缴民间枪支，强迫牧民“捐献”牲畜支持日军，并协助日军镇压反日牧民。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('14b40908f06e43509e5dfcea8a49e4f8','9f16ba14d85142c7b863867c5bb17aca',1939,'日伪“鄂托克旗维持会”会长','组织维持会为日军提供粮草和向导，配合日军“扫荡”抗日游击队，并参与诱捕抗日地下工作人员。','基层维持会/地方自治头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6f3bfdbf828b4808834fbf8f828ea556','eb166a17cf664e83aa52590be3bac98d',1931,'伪蒙古军政府军事部长、伪兴安军军官','参与策划内蒙古东部独立活动，投靠日本关东军，在伪蒙政权和伪兴安军中任职，协助日军控制内蒙古东部及锡林郭勒盟周边地区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6bbc3742a85248dd9aac51d31c299ce3','f05e72c0bca8418198140483cdcacc10',1936,'伪蒙古军政府成员、伪蒙疆联合自治政府官员','在锡林郭勒盟一带参与伪蒙政权活动，投靠日本，协助日军在内蒙古中东部推行殖民统治。；锡林郭勒盟人，参与德穆楚克栋鲁普的伪蒙自治活动，在伪蒙古军政府及伪蒙疆联合自治政府中任职，协助日军控制锡林郭勒盟一带。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e191308b676d4843958141ae2886d8e4','dd8c71d66e0841399bb26d229b5ac4ef',1936,'伪察哈尔盟盟长、伪蒙疆联合自治政府官员','在察哈尔、锡林郭勒盟一带任伪职，配合日军统治，参与伪蒙疆政权的行政与治安活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('379fdf238b7b481aa02f27f90abb673e','398386654d2a48f4adf3224253a66ebb',1936,'伪锡林郭勒盟盟长','在锡林郭勒盟任伪盟长，投靠日本，协助日军在锡林郭勒盟各旗推行伪政权的统治政策。；锡林郭勒盟王公，投靠日军后出任伪锡林郭勒盟盟长，协助日伪在锡林郭勒草原推行保甲、征畜、征兵等政策，直接涉及乌拉盖周边地区。；在锡林郭勒盟地区担任伪职，协助日军控制当地旗县，包括太仆寺旗一带的行政与治安。；锡林郭勒盟王公，投靠日军，出任伪锡林郭勒盟盟长，协助日伪政权在锡林郭勒盟各旗征收赋税、征发劳工，正镶白旗在其管辖范围内。；在日军占领锡林郭勒盟后，出任伪锡林郭勒盟盟长，协助日伪推行旗县制、征收赋税、控制牧区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ec7acbad3d094823a8b7b37500738739','3a09ae0f7f294a118069ecfbec5ba35b',1936,'伪锡林郭勒盟副盟长、伪蒙疆联合自治政府官员','在锡林郭勒盟参与伪蒙政权，任伪副盟长等职，配合日军在锡林郭勒盟地区的统治。；锡林郭勒盟上层人物，在伪锡林郭勒盟公署任职，配合日军统治锡林郭勒盟各旗，包括乌拉盖地区。；在锡林郭勒盟参与伪政权管理，配合日军征发物资、维持治安，活动涉及太仆寺旗周边。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('12fdedff8a694c50a5344405b9b76501','5dc7479e5b0a41ee81122a95de599560',1936,'伪东乌珠穆沁旗旗长','在东乌珠穆沁旗任伪旗长，投靠日本，协助日军在乌珠穆沁地区推行伪政权的行政、治安与物资征集。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('551b6af909fa4185aa154bb019e62adc','e93fe3e83fa74cad8fbad7da574799c3',1936,'伪乌珠穆沁左旗旗长','在乌珠穆沁左旗任伪旗长，配合日军和伪蒙疆政权，在锡林郭勒盟东部地区推行殖民统治。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bbed2c99692749b39f24abacf6d2b29e','194f9301b50649e8b6a5002dc017ad7b',1936,'伪蒙疆联合自治政府官员、伪锡林郭勒盟职员','在锡林郭勒盟及伪蒙疆政权中任职，协助日军在内蒙古中东部进行行政控制与情报活动。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('16c8552fa0334189b8835134e5f001d8','2107c2bcc66a4134b2b779fbbb3015d4',1937,'伪锡林郭勒盟官员、伪旗长','在伪锡林郭勒盟公署及所属旗任职，协助日伪征收牲畜、物资，维持地方伪秩序，活动范围覆盖锡林郭勒盟东部。','无明确职位或一般帮凶','hanjian');
