INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d342f642a240451d94104452434e9f6d','6ad1b280d7654edd89e3b7c53bf3e430',1930,'伪蒙疆联合自治政府官员','参与伪蒙疆政权，在德穆楚克栋鲁普政权中任职，协助日本在内蒙古中东部包括锡林郭勒盟一带推行殖民统治。；投靠日伪，在伪蒙疆联合自治政府中任职，参与伪蒙疆政权事务，协助日军在内蒙古中西部包括锡林郭勒盟一带推行殖民统治。；伪蒙疆政权要员，主要活动于内蒙古、察哈尔等地，与重庆沙坪坝无直接关联。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c97c5d06ef5f4eb48e7c69d50cbfb26d','993cd83aa8c54ff38e0622e1de731309',1930,'伪蒙疆联合自治政府官员、伪蒙古军人员','参与伪蒙疆政权和伪蒙古军，在锡林郭勒盟及察哈尔一带活动，协助日军维持殖民秩序。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b1ef454d049d45938ed409895e375ad8','ae3b48ea9e8040088090d6b3522682e5',1930,'伪蒙疆政权官员、锡林郭勒盟地方附逆者','锡林郭勒盟地方王公或官员，投靠日本，在伪蒙疆政权中任职，参与对锡林郭勒盟的殖民管理。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d6c0c46951e0430eb775f4c7da6a859d','f4208529cb14438593c9984febac079f',1930,'伪蒙疆政权官员、锡林郭勒盟地方附逆者','锡林郭勒盟地方势力人物，附逆日本，在伪蒙疆政权中任职，协助日本控制锡林郭勒盟地区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e14fe1f07a304fa59bf94950248f2b1d','c94f058ddf0448068e37a5d4ac1c1a8d',1936,'伪蒙古军政府成员、伪蒙疆政权要员','锡林郭勒盟苏尼特右旗人，参与德穆楚克栋鲁普的伪蒙自治运动，在伪蒙古军政府和伪蒙疆联合自治政府中任职，协助日军控制锡林郭勒盟各旗。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('808bc812a45e48539d9978e7cd45b9d2','dd8c71d66e0841399bb26d229b5ac4ef',1936,'伪察哈尔盟盟长、伪蒙疆政权官员','察哈尔部人，投靠日本，任伪察哈尔盟盟长，管辖范围与锡林郭勒盟南部及正镶白旗邻近，配合日军推行伪政。；原察哈尔部上层，投靠日军后任伪察哈尔盟盟长，管辖区域与锡林郭勒盟相邻，配合伪蒙疆政权推行殖民统治。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('18ffdd5f15394ea487f86a1e81a664a7','2107c2bcc66a4134b2b779fbbb3015d4',1937,'伪正白旗旗长','在日伪统治时期出任伪正白旗（今正镶白旗部分地区）旗长，执行日伪政令，征派牲畜、劳工，协助日军控制当地。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1c911d44c852412cbeb51ed40d3441e0','121c3c7b38f845d094cb4b86de3e60a0',1937,'伪锡林郭勒盟官员、伪蒙疆政权参议','锡林郭勒盟王公，投靠日伪，在伪蒙疆联合自治政府中任职，参与对锡林郭勒盟各旗的统治，与正镶白旗有行政关联。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4fd7865062b046848186e81374b52390','f4208529cb14438593c9984febac079f',1932,'伪兴安军军官、伪满政权官员','原扎赉特旗王公，投靠日本，在伪满洲国任兴安军军官，其活动范围涉及内蒙古东部，与锡林郭勒盟日伪政权有联系。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bb0f3827741d488ea4c194f8d633f52e','eb166a17cf664e83aa52590be3bac98d',1932,'伪兴安军司令、伪满军政官员','巴林部人，投靠日本，在伪满洲国任兴安军司令，参与日军对内蒙古地区的控制，与锡林郭勒盟日伪势力有协同。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('54269a1c3f224550855b1fca7c95c327','c94f058ddf0448068e37a5d4ac1c1a8d',1936,'伪蒙古军政府办公厅主任、伪蒙疆联合自治政府参议','锡林郭勒盟苏尼特右旗人，德穆楚克栋鲁普的亲信。1936年参与筹建伪蒙古军政府，任办公厅主任，后任伪蒙疆联合自治政府参议等职，协助德王推行伪政权的行政与联络事务。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9642338b8920475d9377aeed962631fd','993cd83aa8c54ff38e0622e1de731309',1936,'伪蒙古军政府参议、伪蒙疆联合自治政府治安部长','锡林郭勒盟人，德王亲信之一。在伪蒙疆政权中负责治安、警察事务，参与镇压抗日活动，强征民夫、物资支持日军。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('000a5483ca3042c692d3dbc641cbf727','6ad1b280d7654edd89e3b7c53bf3e430',1936,'伪蒙古军政府参议、伪蒙疆联合自治政府交通部长','在伪蒙疆政权中历任参议、交通部长等职，负责铁路、公路运输，保障日军军事运输和资源掠夺。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6bef8cf02ab74ad1b24616cb36976d0a','188d07d789aa410490711b02bbdfddbd',1937,'伪锡林郭勒盟公署盟长','在伪蒙疆政权中任锡林郭勒盟公署盟长，直接管辖苏尼特右旗等旗县，推行保甲制、征粮征畜，配合日军维持地方治安。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a93d63a33c0844ab9079bf121effeb3e','2107c2bcc66a4134b2b779fbbb3015d4',1937,'伪苏尼特右旗札萨克、伪锡林郭勒盟副盟长','苏尼特右旗本地王公，投靠日伪，任伪苏尼特右旗札萨克并兼任伪锡林郭勒盟副盟长，协助德王政权在本地征丁征粮、推行奴化教育。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d20493f34089410b833cbb7d67dfb58d','121c3c7b38f845d094cb4b86de3e60a0',1937,'伪锡林郭勒盟帮办盟务','锡林郭勒盟王公，在伪蒙疆政权中任帮办盟务，参与地方行政与治安，为日军搜集情报、征调物资。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3ec409714ef84469b3fd91a97852a2a6','ae3b48ea9e8040088090d6b3522682e5',1939,'伪蒙疆联合自治政府畜产部长','在伪蒙疆政权中任畜产部长，负责掠夺锡林郭勒盟等地牲畜、皮毛等战略物资，供应日军。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('64ca1ae4e94f4b3a8636453de1bf6403','398386654d2a48f4adf3224253a66ebb',1937,'伪蒙疆联合自治政府参议、伪锡林郭勒盟盟长','锡林郭勒盟王公，投靠日伪，历任伪锡林郭勒盟盟长、伪蒙疆联合自治政府参议，在本地推行伪政权的法令，协助日军维持统治。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c02447223cbb4a45a0f90753f03a285c','78c89201b0364968b429bfeffecc66b2',1938,'伪苏尼特右旗伪警察署长','在苏尼特右旗任伪警察署长，直接负责地方治安，搜捕抗日人员，配合日军和伪蒙军行动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('42e9e5d4d0294949bf2084c1ef266ba3','78198cf336e24d25a8e52cd58ddf4575',1933,'蒙疆联合自治政府主席、伪蒙古军总司令','苏尼特右旗扎萨克亲王，1933年策动内蒙古独立，后投靠日本，组建伪蒙古军，任蒙疆联合自治政府主席，配合日军统治内蒙古地区，镇压抗日力量。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5998220b6d4747d8a6207fc9201657d3','c94f058ddf0448068e37a5d4ac1c1a8d',1937,'伪蒙疆政府参议、苏尼特左旗伪旗长','苏尼特左旗贵族，投靠日本后任伪旗长，协助日军征粮派款、强征劳工，镇压当地抗日活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3be31f98020345e7b68d3defe00fe512','2659053ec01b4b489c2d157baa24ee77',1937,'伪蒙疆政府察哈尔盟盟长','原察哈尔部总管，投日后任伪察哈尔盟盟长，管辖苏尼特左旗等地区，推行日伪保甲制度，搜刮民财。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0952fee4e6464e98816202dc7efba21f','dd8c71d66e0841399bb26d229b5ac4ef',1938,'伪蒙疆政府司法部长','原锡林郭勒盟副盟长，投日后任伪司法部长，参与制定镇压抗日民众的法令，迫害蒙汉进步人士。','省部级/大军区级要员','hanjian');
