INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('048f955a84f24816a7af7db459c0ebe1','c94f058ddf0448068e37a5d4ac1c1a8d',1936,'伪蒙古军政府成员、伪蒙古联盟自治政府官员','锡林郭勒盟人，参与德穆楚克栋鲁普的伪蒙自治活动，在伪蒙疆政权中任职，协助日军控制锡林郭勒盟各旗。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5a29ee5828664971805e546db450e070','5dc7479e5b0a41ee81122a95de599560',1937,'伪锡林郭勒盟官员','锡林郭勒盟王公，附逆日伪，在伪锡林郭勒盟政权中任职，协助日军控制当地牧民和资源。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ad2e5b74815f4934805ac0d3281d195b','121c3c7b38f845d094cb4b86de3e60a0',1937,'伪伊克昭盟盟长、伪蒙疆政权官员','内蒙古王公，投靠日伪，任伪伊克昭盟盟长，虽主要活动于伊克昭盟，但属于伪蒙疆政权体系，与锡林郭勒盟伪政权有联系。','无明确职位或一般帮凶','hanjian');
