INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('20668a40c3d14c86ba4a9708b4aada02','398386654d2a48f4adf3224253a66ebb',1936,'伪锡林郭勒盟副盟长、伪蒙疆联合自治政府官员','锡林郭勒盟乌珠穆沁旗人，投靠日伪，任伪锡林郭勒盟副盟长，参与伪蒙疆政权，协助日军在锡林郭勒盟各旗推行保甲制度、征集劳役。','无明确职位或一般帮凶','hanjian');
