INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a2c7e775960647f9b304eee6e2d573bf','2107c2bcc66a4134b2b779fbbb3015d4',1936,'伪锡林郭勒盟官员','锡林郭勒盟浩齐特旗人，投靠日伪，在伪锡林郭勒盟任职，协助日军在锡林郭勒盟推行殖民政策。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a9a5ff24800f492db1f284701b6ed801','121c3c7b38f845d094cb4b86de3e60a0',1936,'伪锡林郭勒盟官员、伪蒙疆联合自治政府官员','锡林郭勒盟人，投靠日伪，在伪锡林郭勒盟及伪蒙疆政权中任职，协助日军统治锡林郭勒盟地区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c05f6479537a4895a8be673add8c3d7a','529eba01fd3844d2a4780badaf25cb50',1937,'伪绥西联军总司令、伪蒙古军将领','绥远人，投靠日军，在绥远、察哈尔、锡林郭勒盟一带活动，任伪绥西联军总司令，配合日军进攻绥远抗日根据地，镇压抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('731801711af44880ba9d6a395f399126','993cd83aa8c54ff38e0622e1de731309',1936,'伪蒙疆联合自治政府官员','投靠日伪，在伪蒙疆联合自治政府中任职，参与伪蒙疆政权，协助日军在内蒙古中西部包括锡林郭勒盟一带活动。；伪蒙疆政权要员，主要活动于内蒙古、察哈尔等地，与重庆沙坪坝无直接关联。','无明确职位或一般帮凶','hanjian');
