INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f1df556980b34a12879063e7b36d689f','26647d4bb91f4086a567e1a461c53d38',1936,'伪蒙古军将领','投靠日伪，在伪蒙古军中任职，参与日军在锡林郭勒盟、察哈尔一带的军事行动，镇压抗日力量。','无明确职位或一般帮凶','hanjian');
