INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d086bdfbf99847db8849d15aedb4700a','838979c5881d455d9908a863bc24d449',1936,'伪蒙疆联合自治政府官员','投靠日伪，在伪蒙疆联合自治政府中任职，参与伪蒙疆政权，协助日军在内蒙古中西部包括锡林郭勒盟一带推行殖民统治。；伪蒙疆政权要员，主要活动于内蒙古、察哈尔等地，与重庆沙坪坝无直接关联。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1f1741ff3b20485c8eb2ac263fa82e8c','69db90f376bd4cd189ca4593d5c6f582',1937,'伪蒙疆联合自治政府官员','投靠日伪，在伪蒙疆联合自治政府中任职，参与伪蒙疆政权，协助日军在内蒙古中西部包括锡林郭勒盟一带活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('555448ce75714ed88e60c598e746fb58','7b1bc57ea5874652adecdac7d616b504',1930,'阿拉善旗札萨克（旗王）','在抗日战争期间，虽名义上隶属国民政府，但为保全自身利益，与日本特务机关及伪蒙疆政权保持暧昧关系，曾接待日本特务人员，并默许日伪势力在旗内活动，未积极抗日。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('77bf8e8ccc714c8eb63228fc56cf7e7f','145e984fe99940c2babc5480aee540f0',1930,'阿拉善旗协理','协助达理札雅处理旗务，与日本特务及伪蒙疆政权有暗中往来，曾为日军搜集阿拉善地区情报，并协助日伪人员渗透旗境。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('33037585e1f1486b9350c4a0237cbef8','a7c43e77f6a047e3ab36f0a221c65640',1930,'阿拉善旗喇嘛庙上层喇嘛','利用宗教身份为日本特务机关传递情报，煽动部分蒙古族民众对日伪政权持友好态度，并参与接待日本考察团。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('04006d6de998424fb9ddc8aa7933364d','5ddbfc86cb854f1fb3f8f42ae0c6b013',1930,'阿拉善旗保安队军官','在日伪势力拉拢下，曾向伪蒙疆政权提供阿拉善旗军事布防信息，并协助日伪人员偷运武器进入旗境。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0b85cd1ad66d4c2b928030b6c016635b','31abdc5e4e0a4ebdbe5f0b715a509863',1937,'伪华北政务委员会委员长','1937年北平沦陷后出任伪中华民国临时政府行政委员会委员长，后任伪华北政务委员会委员长，积极推行日本殖民统治，镇压抗日活动。；虽主要活动于华北，但曾参与南京伪政权协调，长期为日军效力；原北洋政客，1937年北平沦陷后出任伪中华民国临时政府行政委员会委员长，后任伪华北政务委员会委员长，管辖包括河北在内的华北地区，推行日伪统治政策，协助日军经济掠夺和治安强化运动。；华北伪政权首脑，其统治范围覆盖秦皇岛、抚宁，支持日军“治安强化运动”，在抚宁等地增设伪军据点。；华北伪政权最高头目之一，其伪政权管辖包括河南北部，对河南沦陷区伪政权有统辖关系。；虽为华北汉奸，但曾与浙江日伪势力勾结，在宁波设立商务机构，为日军服务。；原为北洋政客，投日后虽主要活动于华北，但与浙江宁波汉奸有联系，支持日伪在东南沿海的统治。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3ef6e47d08da465c86d1fdfba8d9a1c0','8f1dd12e548b4c4f866dd743c3377896',1937,'伪华北政务委员会内政总署督办、伪国民政府考试院院长','曾任伪中华民国临时政府议政委员会常务委员，后任伪华北政务委员会内政总署督办，协助日军在北平及华北地区推行治安强化运动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3d70fd0cf5d546a1b4af34a37a124b5e','da58b77853f14ce7b32f7f6b3305b75a',1937,'伪华北治安军总司令','北平沦陷后投敌，任伪华北治安军总司令，组织伪军协助日军清剿抗日武装，在北平及周边地区实施“扫荡”。；组织伪军协助日军清乡扫荡，残害抗日军民。；指挥伪治安军在顺义地区多次围剿八路军游击队，制造多起惨案。；指挥伪治安军在天津东丽等地区驻防，参与“扫荡”抗日武装，杀害无辜百姓。；其伪军曾南下配合日军，在安徽安庆地区有协同作战。；指挥伪治安军在保定及冀中地区多次进攻八路军，制造多起惨案。；原直系军阀，投日后组织伪治安军，在保定及周边地区多次配合日军扫荡，围剿八路军和抗日游击队，制造多起惨案。；组建伪治安军，在河北唐山、滦南等地驻军，配合日军“扫荡”，围剿八路军冀东抗日根据地。；虽总部在北平，但指挥伪治安军多次对冀东路南地区进行大规模“扫荡”，是华北头号汉奸之一。；其麾下治安军多次在唐山、迁安地区驻防和作战，配合日军围剿八路军冀东军区，制造多起惨案。；指挥伪治安军在廊坊及周边地区频繁“清剿”，杀害抗日干部，掠夺物资，并参与制造多起惨案。；指挥伪治安军在廊坊及周边地区多次“清乡”，杀害抗日军民，破坏地下组织。；河北宁河人，组织伪治安军配合日军扫荡冀东、热河等地，残害抗日军民。；原直系军阀，投日后任伪华北治安军（绥靖军）总司令，在河北、石家庄等地组织伪军配合日军扫荡抗日根据地，镇压抗日力量。；指挥华北伪治安军，在河北包括秦皇岛、北戴河地区多次配合日军进行“扫荡”，屠杀抗日军民。；组织伪华北治安军，在河北、秦皇岛、山海关一带配合日军扫荡，屠杀抗日军民；指挥伪华北治安军在冀东地区（含抚宁）多次围剿八路军，制造多起惨案，强征民夫修筑碉堡。；指挥伪治安军在冀东及秦皇岛地区扫荡抗日武装，在海港地区设立据点，残害百姓。；组建伪治安军，配合日军在华北包括河南部分地区进行扫荡与清乡。；统辖华北伪军，河南开封一带伪军受其指挥，配合日军扫荡。；组建伪华北治安军，其部队驻防河南北部包括新乡地区，配合日军扫荡。；组建伪华北治安军，其伪军部队活动于华北包括河南北部，配合日军扫荡抗日根据地。；河北宁河人，抗战期间投靠日军，任伪华北治安军总司令，在华北地区组织伪军进行伪化统治。；华北伪军主要头目，其伪治安军体系覆盖华北，与陕西渭南地区有间接关联。；投靠日军后任伪华北治安军总司令，统率伪军配合日军在华北包括陕西周边地区进行扫荡和治安强化运动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('01858d5d1b654af99782c891672ed4ba','b5ba32ac9dee4113808d7f1e4475b119',1935,'伪冀东防共自治政府委员长','1935年成立伪冀东防共自治政府，管辖包括北平东部地区，后并入伪中华民国临时政府，长期为日本侵略服务。；早年在冀东成立伪政权，其势力范围曾涉及北平近郊及丰台一带，为日军提供情报和后勤支持。；在冀东地区建立亲日政权，后参与北平伪政权活动，出卖国家利益。；原国民党官员，1935年与日军勾结成立冀东伪政权，辖冀东22县（含天津北部、河北东部），协助日军控制冀东地区，破坏抗日。；1935年成立冀东伪政权，管辖包括廊坊部分县区（如香河、三河等），推行奴化教育，为日军提供粮秣和情报。；1935年11月成立冀东防共自治政府，公开投敌，管辖包括秦皇岛在内的冀东22县，为日军提供后勤和情报支持。；冀东伪政权最高头目，其辖区包括秦皇岛、抚宁，公开投敌，配合日军“华北自治”阴谋，镇压当地抗日力量。','地方伪政权首脑','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c7c7cd79668046f2978485d74f848722','83b067447f4744f7b527179c4d9524d4',1935,'伪冀东防共自治政府秘书长','协助殷汝耕管理伪冀东政权，参与对北平东部地区的殖民统治和物资掠夺。；协助殷汝耕管理平谷等县政务，组织伪警察和保甲制度，监控抗日分子，强迫民众悬挂伪旗。；协助殷汝耕推行亲日政策，参与华北伪政权事务。；协助殷汝耕管理伪政权，在宝坻等县推行日伪法令，镇压抗日活动。；协助殷汝耕管理冀东伪政权，在蓟县等地推行日伪法令，参与镇压抗日民众。；参与冀东伪政权运作，在玉田等地组织伪警察和自卫团，镇压抗日力量。；协助殷汝耕管理唐山地区伪行政，参与镇压路北抗日武装。；殷汝耕的得力助手，参与伪政权行政运作，在香河等地推行日伪法令。；协助殷汝耕管理伪政府，在抚宁地区组织伪自卫团，协助日军清乡，迫害抗日家属。；协助殷汝耕建立伪政权，参与亲日活动。；协助殷汝耕组织伪冀东政权，配合日军统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('60256be367e541d4b3c35fc624614f65','ad65aa69fa0c4f84aa598321e8c96ad1',1938,'伪华北政务委员会常务委员、伪北京市长','曾任伪中华民国临时政府司法委员会委员长，后任伪华北政务委员会常务委员，并一度兼任伪北京市长，推行日伪法令。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('daba6ac9a3974462baad100789283450','eb97867e737c44e4944e71b5792c1f23',1938,'伪北京市市长','1938年出任伪北京市市长，在任期间配合日军实施保甲制度、粮食统制，镇压北平城内抗日地下活动。；投靠日本，在北京伪政权中任职，参与日伪统治，对陕西有间接影响。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f19069db447b4e2f99e7cd1c161cd99f','9a58a6d0ca124e4e8470270a43ef0a46',1938,'伪北京市警察局局长','任伪北京市警察局局长，负责北平城内的治安监控，大肆搜捕抗日志士，协助日军进行“思想战”。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7282f99baf524c2886c3802b0cea5c9c','1faedd8cdd3645bc9f7cadb419ee99d9',1937,'伪华北政务委员会治安总署督办','曾任伪华北治安军高级将领，参与指挥伪军在北平东城及周边地区镇压抗日力量。；在华北伪政权中负责治安，配合日军统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bf9eb9392cd0461190d2c782fb10c878','e409ef959281461b91e8ce1eef37d186',1940,'伪华北政务委员会绥靖总署督办','在北平任职期间，负责伪军整编和“剿共”军事行动，对东城地区的地下抗日组织进行破坏。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('668beec6a75443b09cd94a7a4344aeb0','1bea23fefee9462fab8d11fc69a557b9',1938,'伪中国联合准备银行总裁','在北平东城设立伪中国联合准备银行总部，发行伪币，掠夺中国资财，为日军侵华战争提供经济支持。；在北平设立伪银行，发行伪币，在丰台地区强制兑换，掠夺经济资源。；在北平发行伪币，在延庆等县强制兑换法币，掠夺民间财富，造成通货膨胀，破坏抗日经济基础。；发行伪币，在石景山地区强制兑换法币，造成当地经济混乱，掠夺物资支持日军。；发行伪币，搜刮民财，为日军提供军费。；发行伪币，在安庆等沦陷区强制流通，掠夺民间财富。；控制伪华北金融，发行伪币，在山东聊城地区掠夺物资，破坏经济。；发行伪币，在唐山、滦南地区强制兑换，搜刮民财，造成严重通货膨胀。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('878f196906a747e3bb01ca7e8c21e6a5','892cdd9ae3d2444996fbaf7f65134db1',1937,'伪华北政务委员会咨询委员','北洋时期政客，北平沦陷后接受伪职，虽未直接掌权，但利用旧关系为日伪政权笼络人心。；北洋政客，投靠日伪，为伪政权出谋划策。；北洋旧官僚，抗战期间附逆，挂名伪华北政务委员会，为日军在华北包括山东的统治提供支持。；虽无实权，但作为汉奸头面人物，为日伪在华北（含廊坊）统治提供政治支持。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('15470c3463494b9a822039a8946db505','3fef5234abca416989d5067495ea377b',1937,'伪华北政务委员会顾问','曾任北洋政府官员，后投靠日伪，在北平担任顾问，参与策划经济统制政策。；原亲日外交官，投日后任伪顾问，参与对北平及昌平地区的殖民政策制定。；在北平担任日伪顾问，参与策划奴化政策，涉及海淀地区学校和文化机构；亲日派人物，参与伪政权活动，协助日本经济掠夺。；参与日伪对冀中地区的经济掠夺，支持“以战养战”政策。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bf18765bb87c4306800e7af8f0c5ace2','9d4da38d6dd54a8d954f03b493371758',1937,'伪华北政务委员会咨询委员','北洋政府前官员，北平沦陷后出任伪职，为日伪政权提供政治咨询，协助维持殖民秩序。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8ad83d8e512b498993366de7d825baf9','bbc7d2d2f1174918a3a12cc3ce766af2',1937,'伪北平维持会会长','1937年北平沦陷后率先组织伪北平维持会，迎接日军进城，后任伪临时政府顾问，是东城地区早期汉奸头目。；北平维持会头目，与重庆地区无直接关联。；组织北平维持会，协助日军维持治安，后任伪职。；北平沦陷后组织维持会，协助日军维持占领秩序，其伪政权体系与华北各地包括陕西周边有联系。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bebb26e904df46b4a8859dbf149097d0','4854fcea9b2649ac839eb227047c42b5',1938,'伪北平市商会会长','任伪北平商会会长期间，强迫商户为日军提供物资，协助日伪进行经济掠夺和粮食配给。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7aac11f7bbaa4eb2952fe71f9312deda','7777aa506f28464b99a778cee79ef88f',1940,'伪华北政务委员会实业总署督办','在北平主管伪实业部门，推动华北资源对日输出，参与对东城工商业的统制。；在北平主管实业，控制昌平矿产和农产品，为日军提供战略物资。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8cb5cb738c8443399900b917d84228dd','e1badd3fe14246acb4a3d2bf765b2db2',1940,'伪华北政务委员会外交总署督办','负责伪华北政权对外事务，协助日本控制北平外交资源，镇压抗日外交活动。；在北平处理伪政权外交，协助日军与伪满等傀儡政权协调，影响昌平边境事务。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b862e27b6b1d4b068f9bc96da864979a','f2c99eb1b0d343818114b39936365e43',1938,'伪华北政务委员会教育总署督办','在北平推行奴化教育，修改教科书，强制学校教授日语，破坏东城地区教育体系。；推行奴化教育，在大兴各中小学强制使用日伪教材，删除中国历史内容，强迫学生参加“新民会”活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0690dde49b3f47cd9e0ef530da5fa2aa','f724b4f7519147ba93e302a475b2a225',1938,'伪北京市工务局局长','负责北平市政工程，为日军修建军事设施，强征民夫，破坏城市基础设施。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('53deabc146674b5dbc9c0e885c6b015f','8f1dd12e548b4c4f866dd743c3377896',1937,'伪华北政务委员会内务总署督办、伪华北政务委员会委员长','原北洋政客，投日后任伪华北政务委员会要职，在北平（今北京）及丰台地区推行日伪统治，协助日军征粮、镇压抗日活动。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('85647e3a5f974aa3b511ae42deb0c0fe','da58b77853f14ce7b32f7f6b3305b75a',1937,'伪华北治安军总司令、伪华北政务委员会治安总署督办','原直系军阀，投日后负责华北伪军，在丰台及北平周边配合日军“扫荡”，镇压抗日武装。；北洋直系军阀，投日后在北平组建伪治安军（绥靖军），配合日军“扫荡”冀中、平郊抗日根据地，在大兴一带多次清剿抗日武装。；原直系军阀，投日后组建伪华北治安军，在北平及周边地区配合日军“扫荡”，围剿八路军和抗日游击队。；原直系军阀，投日后在北平组建伪治安军，配合日军“扫荡”抗日根据地，镇压北平及周边地区抗日力量。；在北平及华北地区组织伪治安军，配合日军“扫荡”，镇压北平及海淀周边抗日武装；原直系军阀，投日后任伪华北治安军总司令，其部队在石景山及周边地区驻防，参与“扫荡”抗日武装，镇压当地民众。；原直系军阀，投日后组建伪华北治安军，在门头沟山区参与“扫荡”八路军游击队，协助日军封锁抗日根据地。；组织伪华北治安军，配合日军在华北包括山东北部德州、禹城地区进行清乡、扫荡，镇压抗日武装。；组建并统辖华北伪治安军，其部队部署于山东各地包括聊城、莘县周边，配合日军进行治安战与扫荡。；组织伪华北治安军，配合日军在河北等地扫荡抗日武装，镇压民众抗日活动。；组建伪华北治安军，配合日军在河北包括廊坊地区进行扫荡和治安强化运动。；河北宁河人，组建伪华北治安军，在河北及承德周边地区配合日军扫荡抗日根据地，推行治安强化运动，抓捕杀害抗日军民。；组建伪华北治安军，其伪军部署于华北各地包括豫东商丘、民权一带，配合日军扫荡抗日根据地，维持伪统治。；北洋旧军阀，抗战期间投敌，统辖华北伪治安军，其伪军系统延伸至河南豫东地区，商丘一带伪军多受其体系影响。；原北洋军阀，抗战期间投敌，任伪华北治安军总司令，其伪军势力活动于华北包括豫北濮阳地区，配合日军扫荡抗日武装。；在华北伪政权中负责伪军建设，其伪治安军活动范围包括河南北部地区，配合日军扫荡抗日力量。；北洋军阀，投敌后组建伪华北治安军，配合日军在华北包括陕西周边地区进行扫荡、清乡，镇压抗日武装，强征劳工，罪行累累。；组建伪华北治安军，配合日军在华北地区包括陕西邻近区域进行扫荡和镇压抗日力量。；组建伪军配合日军扫荡华北抗日根据地，其伪军活动对陕西宝鸡等后方构成威胁，是华北重要汉奸军事头目。；华北伪军最高头目之一，其伪治安军部署于华北各地，包括山西、陕西黄河沿岸，对榆林、神木一带抗日根据地构成军事威胁。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ff0e2835ac4d426cb659036cc559cbdc','83b067447f4744f7b527179c4d9524d4',1935,'伪冀东防共自治政府秘书长、伪北平市警察局局长','殷汝耕亲信，后任伪北平警察局长，在丰台地区协助日军维持治安，镇压抗日民众。；在北平任职期间，指挥伪警察在门头沟矿区及乡村搜捕抗日分子，强征劳工，为日军提供煤炭资源。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b01652f54479492ca7b2d260b3c98583','4cc5391bc78947fa9bf1a4b59e0f5371',1937,'伪北平市市长','投日后任伪北平市长，管辖包括丰台在内的北平地区，推行日伪法令，强征物资。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6557545003594523bcc10caf5d834813','eb97867e737c44e4944e71b5792c1f23',1938,'伪北平市市长、伪华北政务委员会常委','继任伪北平市长，在丰台地区设立伪警察机构，配合日军“清乡”和粮食统制。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('362c3bb4882c4f228d43207af1a178d5','9a58a6d0ca124e4e8470270a43ef0a46',1937,'伪北平市警察局局长','长期任伪北平警察头目，在丰台地区抓捕抗日地下人员，执行日伪保甲制度。；在任期间指挥伪警察在大兴等地抓捕抗日志士，破坏地下组织，协助日军设立“爱护村”和封锁沟。；在北平（含昌平）任伪警察头目，协助日军搜捕抗日分子，镇压民众反抗，维护殖民秩序。；在北平（含朝阳地区）任伪警察头目，协助日军特务机关抓捕抗日人士，镇压民众反抗。；在北平（含海淀）指挥伪警察，搜捕抗日分子，破坏地下党组织，协助日军进行“治安肃正”；在石景山地区设立伪警察分所，协助日军抓捕抗日分子，强制推行“良民证”制度，镇压工人反抗。；协助日军控制北平，参与镇压抗日地下活动。；在门头沟矿区及斋堂等地部署伪警，镇压矿工罢工，协助日军抓捕八路军地下交通员。；掌管伪北平警察，配合日军镇压抗日活动，向四川等后方派遣特务进行破坏。；在北平伪警察系统中任职，参与镇压抗日活动，其活动属华北伪政权体系，与陕西有间接关联。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3d7e7493e9864901b1db06f52877f3ec','4b89b0b1aadc4aa2b3384379d6297cd7',1938,'伪华北政务委员会教育总署督办','在北平及丰台推行奴化教育，控制学校，强迫学生参加日伪活动。；推行奴化教育，篡改历史教材，为日本侵略张目。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('554669dd5ca647f19b1eccef347adebc','31abdc5e4e0a4ebdbe5f0b715a509863',1937,'伪华北政务委员会委员长（首任）','原北洋政客，投日后主持伪华北政权，管辖北平及丰台，组织伪军和警察协助日军。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c820a554294841a9ac02d9ae7fdd1a80','ad65aa69fa0c4f84aa598321e8c96ad1',1940,'伪华北政务委员会常务委员、伪北平特别市市长','在任期间强化丰台地区日伪统治，推行“治安强化运动”，镇压抗日力量。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('15482c12cb2a4d81b8abf7f34dd324c5','9192833e19cc4b5cb50e7c82f5e5afd9',1944,'伪北平市市长（末任）','抗战末期任伪北平市长，在丰台地区继续维持日伪秩序，直至日本投降。','核心城市市长/省部级','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7ee26c3059c348cb9acbec6d023a3557','10b88f41fdee46778f29f60ae3d41741',1937,'伪天津市市长（曾兼北平地区职务）','虽主要任伪天津市长，但曾参与北平及丰台地区的日伪协调，协助日军镇压抗日活动。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('00c99130a884449788b38a8f98e33c1b','f724b4f7519147ba93e302a475b2a225',1938,'伪北平市社会局局长','在丰台地区推行日伪社会控制，组织“新民会”分会，进行奴化宣传。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b16c4e8d27194274b80f7c9ff304e4c6','56b7d146cc554e51b0e7b263ead18f3f',1938,'伪北平市新闻检查所所长','控制北平及丰台地区报刊舆论，查禁抗日言论，为日伪宣传服务。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ae874ba3c8634441b456f8868a723dd3','8f1dd12e548b4c4f866dd743c3377896',1937,'伪华北政务委员会内政总署督办、伪华北政务委员会委员长','原北洋政客，七七事变后投敌，在北平组织伪政权，任伪华北政务委员会要职，推行奴化教育，协助日军经济掠夺，镇压抗日力量。；原北洋政客，投日后任伪华北政务委员会要职，在北平推行奴化教育，协助日军经济掠夺，镇压抗日活动。；原北洋政客，投日后任伪华北政务委员会要职，在北平（今北京）推行日伪统治政策，参与奴化宣传和物资统制。；在北平（今北京）主持伪华北政务委员会，推行日伪统治，镇压抗日活动，参与“治安强化运动”；原北洋政客，投日后任伪华北政务委员会要职，在北平（今北京）及门头沟地区推行日伪统治，镇压抗日活动，协助日军经济掠夺与治安维持。；原北洋政客，投日后任伪华北政权要职，在北平、天津、河北推行奴化政策，协助日军经济掠夺和治安强化运动。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('19ee76aa25e34ff79cf616904b65c854','b5ba32ac9dee4113808d7f1e4475b119',1935,'伪冀东防共自治政府政务长官（后并入北平伪政权）','早年在冀东成立伪政权，后活动于北平，协助日军控制平津地区，参与对大兴等县的伪化统治，推行保甲制度。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('45e1945c825d468f96ef76258c2508af','83b067447f4744f7b527179c4d9524d4',1935,'伪冀东防共自治政府秘书长、伪北平市政府参事','殷汝耕心腹，参与冀东伪政权，后转任北平伪职，协助日军管理大兴等县行政，强征民夫和粮食。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6d7b37496a964ed99acb46394f1a3a44','eb97867e737c44e4944e71b5792c1f23',1938,'伪北平市市长（1938-1943）','原国民党官员，投日后任伪北平市长，管辖包括大兴在内的郊区，推行日伪法令，镇压抗日活动，组织“献铜献铁”等物资搜刮。；原国民党官员，投日后任伪北平市长，在昌平等郊区推行保甲制度，强征劳工，为日军提供物资。；原国民党官员投日，任伪北平市长期间，在朝阳地区推行日伪经济统制，强征劳工。；作为伪北平市长，直接管辖石景山地区行政事务，配合日军征用土地、劳工，用于石景山制铁所（今首钢前身）的扩建和军事物资生产。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('48ba8f3bf5784a2aa08086d936853ee0','1faedd8cdd3645bc9f7cadb419ee99d9',1937,'伪北平维持会会长（1937年短暂）','七七事变后率先组织北平地方维持会，迎接日军进城，协助维持治安，后因权力斗争失势，但前期对大兴地区伪政权建立有直接影响。；原北洋将领，北平沦陷初期组织伪维持会，为日军稳定昌平等郊区秩序服务。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c67cb2be674d4edb882c797045f6edb8','10b88f41fdee46778f29f60ae3d41741',1937,'伪天津市市长（曾兼管平郊）、伪华北政务委员会委员','原宋哲元部幕僚，投日后在北平、天津活动，参与制定对大兴等县的“治安强化”计划，提供抗日武装情报。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('920ebdbc5f0b4beba562a41a759faecd','31abdc5e4e0a4ebdbe5f0b715a509863',1937,'伪中华民国临时政府行政委员会委员长、伪华北政务委员会委员长','伪华北最高傀儡头目，在北平设立伪政权，统辖大兴等县，推行“新民会”奴化宣传，配合日军“三光”政策。；原北洋财政官僚，投日后主持伪华北政权，其统治范围覆盖北平及朝阳地区，推行奴化教育和经济掠夺。；在北平建立伪中华民国临时政府，后任伪华北政务委员会委员长，为日本侵略者搜刮资源、奴化北平民众；作为华北伪政权最高头目，统辖门头沟地区行政，支持日军对平西抗日根据地的多次“讨伐”。；原北洋财政官僚，投日后组建伪华北政权，管辖河北、天津等地，为日军提供财政和物资支持，镇压抗日活动。；抗战期间投靠日本，在华北主持伪政权，推行日伪统治，其伪政权势力覆盖山东等地，对包括济宁、曲阜在内的华北地区实施殖民统治与掠夺。；北洋旧官僚，抗战期间投敌，主导伪华北政权，其伪政权统治范围覆盖山东，聊城、临清等地亦在其伪政权体系之下。；华北地区最高伪政权头目之一，统辖包括山东在内的华北伪政权体系，其伪政权架构覆盖聊城、莘县等地，为日军在华北推行殖民统治、征粮征丁提供政治支撑。；华北地区最高伪政权头目，统辖包括山东在内的华北伪政权，推行日军侵略政策。；华北伪政权首脑，其统治范围涵盖山东，推行伪化政策，支持日军在山东包括青岛、即墨地区的殖民统治。；华北伪政权首脑，其政令覆盖山东及青岛，支持日军在崂山地区的扫荡与治安强化运动。；华北地区最高伪政权头目之一，其伪政权统辖包括青岛在内的华北占领区，推行奴化教育与经济掠夺。；华北伪政权首要人物，其政权统辖包括山东、青岛在内的华北占领区，推行亲日卖国政策。；华北地区最高伪政权头目之一，其伪政权统辖包括青岛在内的华北占领区，对山东、青岛伪化统治负有责任。；华北伪政权首要人物之一，统辖包括河北在内的华北占领区，推行亲日卖国政策。；华北伪政权首要人物，统辖包括河北廊坊在内的华北沦陷区，推行日伪统治。；华北首要汉奸之一，在北平建立伪政权，统治范围涵盖河北、张家口等地，推行亲日附逆政策。；华北伪政权最高头目，统辖河北包括秦皇岛、山海关，全面推行汉奸统治；浙江杭县人，主持伪华北政权，协助日军在河南等地推行保甲、征粮、奴化教育，南阳地区亦受其伪政权管辖。；浙江杭县人，抗战期间投靠日军，组织伪中华民国临时政府，后任伪华北政务委员会委员长，其伪政权管辖范围包括河南北部。；浙江杭县人，抗战期间组织伪临时政府，后并入汪伪政权，任伪华北政务委员会要职，其伪政权对河南北部沦陷区实施统治，协助日军征粮、征丁。；浙江杭县人，抗战期间组织伪中华民国临时政府，后任伪华北政务委员会委员长，其伪政权覆盖河南北部，配合日军统治。；浙江杭县人，抗战期间组织伪临时政府，后并入汪伪政权，任伪华北政务委员会委员长，其伪政权管辖范围包括河南北部地区。；浙江杭县人，抗战期间组织伪临时政府，管辖华北包括河南部分地区，协助日军掠夺资源、镇压抗日活动。；浙江杭县人，华北伪政权头目；与湖南衡阳无直接关联。；北洋旧官僚，抗战爆发后投敌，在北平组建伪临时政府，后任伪华北政务委员会委员长，统辖华北沦陷区伪政权，为日军筹措物资、推行奴化教育，其伪政权势力覆盖陕西周边及华北地区。；抗战期间投靠日本，在华北组建伪政权，推行日伪统治，其伪政权势力范围涵盖陕西部分沦陷区及邻近地区。；抗战期间投靠日本，在华北组建伪政权，推行日伪统治，其伪政权势力范围涵盖华北包括陕西周边地区，对包括陕西在内的华北民众进行压迫与掠夺。；抗战期间投靠日本，主导华北伪政权，推行奴化统治与经济掠夺，其伪政权势力范围涵盖陕西周边及华北地区。；华北伪政权最高头目之一，其伪政权体系覆盖华北日占区，包括山西、陕西黄河沿岸部分区域，对榆林、神木一带伪维持会有间接管辖关系。；抗战期间投靠日本，在华北组建伪政权，推行日伪统治，其伪政权势力范围涵盖陕西部分沦陷区及邻近区域。；北洋旧官僚，抗战爆发后投敌，在北平组建伪中华民国临时政府，后任伪华北政务委员会委员长，统辖华北沦陷区伪政权，为日军搜刮物资、推行奴化教育。；抗战期间在华北组织伪政权，推行日伪统治，其伪政权势力覆盖包括陕西在内的华北、西北部分沦陷区。；抗战期间投靠日本，在华北组建伪政权，推行日伪统治，其伪政权势力范围涵盖华北包括陕西周边地区。；抗战期间在华北组织伪政权，其伪政权势力覆盖包括陕西在内的华北、西北部分沦陷区，是华北地区头号汉奸之一。；抗战期间投靠日本，在华北建立伪政权，推行奴化统治，其伪政权势力范围涵盖陕西周边及华北地区，对包括陕西在内的北方沦陷区实施殖民统治。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3be1ffc031774d9eb2237d5fec8abffc','ad65aa69fa0c4f84aa598321e8c96ad1',1943,'伪华北政务委员会常务委员、伪北京市长（1943-1945）','继余晋龢后任伪北平市长，强化对大兴等郊区的控制，增设伪警察分驻所，搜捕八路军地下工作人员。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5d2fc6f5bc464c639f9c5470e2593f39','4b89b0b1aadc4aa2b3384379d6297cd7',1939,'伪山西省长（后调北平伪华北政务委员会任职）','虽主政山西，但后期在北平参与伪华北政务，曾到大兴视察“治安强化”成果，支持日军建立“模范村”。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('09b22a399bfc4139ab90d1312eb43b57','1bea23fefee9462fab8d11fc69a557b9',1938,'伪中国联合准备银行总裁、伪华北政务委员会经济顾问','在北平发行伪币，掠夺大兴等县物资，导致当地经济崩溃，间接支持日军战争机器。；通过金融控制掠夺门头沟煤矿资源，为日军战争机器提供资金，间接支持对当地抗日力量的镇压。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e233c2ce871b41539d100614dd11ae9a','56b7d146cc554e51b0e7b263ead18f3f',1938,'伪《新民报》社长、伪华北宣传联盟负责人','在北平控制舆论，在大兴地区散发汉奸报纸，美化日军侵略，污蔑抗日军民。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a16aef1eee3246dfa8d183ccfad8a2ac','49efdf8c61584b0bbb73ec85cdc6f12a',1938,'伪大兴县知事（县长）','直接统治大兴县，组织伪县公署，配合日军修建炮楼和封锁沟，强征壮丁，镇压当地抗日游击队。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7cbce9d336094e4080869300fef0bef3','6efd8b07afa9443aa37b3a64e9e23aa0',1940,'伪大兴县知事（继任）','任内推行“保甲连坐”，在大兴各村设立伪保长，搜捕抗日干部，向日军提供粮食和情报。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('419671c0de4d441e9fb2ba1adf844a5d','8dd71bba0484426388d6dbcfae15bd52',1942,'伪大兴县知事（后期）','在任期间配合日军“五次治安强化运动”，在大兴南部地区制造无人区，杀害抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c355abbdb6b04d43895f3ba7edac559b','4cc5391bc78947fa9bf1a4b59e0f5371',1939,'伪北平特别市警察局督察长（分管郊区）','专门负责大兴、宛平等郊县“剿共”，指挥伪军警突袭村庄，逮捕抗日家属。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4603d83a533a4ae4b18bc51b0d38825d','ec3effc6feb44bd5bf146df810a892a9',1940,'伪大兴县保安队队长','率伪保安队多次进攻大兴采育、青云店一带的抗日武装，烧毁村庄，杀害民兵。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3dcacc059cd44cdbaf920a1ce00bb79e','c6a682cb9d834e4a910285cc9abb8db2',1940,'伪华北治安军第1集团军司令（驻防平郊）','所部驻大兴黄村、南苑等地，参与“扫荡”平南根据地，制造多起惨案。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dcca886c289640b3954f17b62dacac94','a976a94be0bf4b76b621948c0802222f',1935,'伪冀东防共自治政府保安司令','在密云地区协助日军镇压抗日武装，推行“治安肃正”，残害抗日军民。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2e3b5915805146abb641e34fe7ca66ad','b5ba32ac9dee4113808d7f1e4475b119',1935,'伪冀东防共自治政府政务长官（管辖密云）','策划冀东事变，使密云等22县脱离中国行政管辖，沦为日本傀儡统治区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2650e6514825451cbba92d97fd91164d','83b067447f4744f7b527179c4d9524d4',1935,'伪冀东防共自治政府秘书长兼密云县知事','在密云推行奴化教育，强征民夫修建日军据点，协助日军“清乡”。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bd466d84934a43bf8bd6b8aece3757a0','8f1dd12e548b4c4f866dd743c3377896',1940,'伪华北政务委员会委员长（管辖密云）','在密云地区推行保甲制度，组织伪军配合日军扫荡八路军根据地。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cbb0e7e12fc146b58620678f17e6441b','da58b77853f14ce7b32f7f6b3305b75a',1939,'伪华北治安军总司令（在密云驻有部队）','派遣伪治安军驻防密云，多次参与围剿密云抗日游击队，杀害无辜百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8efa481d1d2c4069bdad61533365b5c9','5f82d23ccd2e45fd9e59f76c92bcc9ad',1937,'伪蒙古军总司令（曾窜扰密云北部）','率伪蒙古军配合日军在密云北部山区烧杀抢掠，破坏抗日根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6cc61a028c1f48d88e71b17906675cf4','c962700c3422426b946336b59832e9d0',1938,'伪密云县保安队队长','充当日军鹰犬，搜捕抗日干部，刑讯逼供，多次带队突袭密云村庄。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dad695739cd54f9597851e0cd74fb97f','8fdb75c63ff4478aa86d74431b472cde',1935,'伪冀东保安队总队长（活动于密云）','在密云一带强征壮丁，配合日军建立“无人区”，制造多起惨案。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1e6f52cea1944dffa82522a8b8e4ddc0','7ecf38311c27407bbb44fdd793ae7b5b',1935,'伪冀东保安队第一总队队长（驻密云）','初期为殷汝耕效力，在密云镇压抗日活动，后反正但影响有限。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3fd1b2e1652f4e9bbdbed3bb79769850','bb9e9304c2d945acb5bbb0cf1cd2a2c0',1938,'伪密云县知事（1938-1940）','推行日伪“粮食统制”，强征密云农民粮食，导致大量饥荒。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dfc9b7713c014f7596f9467941ec91b1','b2870c4c1e634ac391ca7e790e93f57c',1939,'伪密云县警察局局长','协助日军抓捕抗日家属，破坏地下交通线，残害进步群众。','市县厅局级','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0a6ea4160ad943248f775da5a56fe1ae','b1303da80b994629ba3bf2748d8842c1',1941,'伪华北“剿共”军指挥官（曾活动于密云）','率伪军配合日军“铁壁合围”，在密云云蒙山区烧毁村庄数十个。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('162995233ca64113b16068f453070fda','7ecf38311c27407bbb44fdd793ae7b5b',1935,'伪冀东防共自治政府保安队第一总队总队长','1935年参与殷汝耕成立的伪冀东防共自治政府，驻防平谷、密云一带，协助日军维持治安，镇压抗日活动。1938年反正后投靠国民党，但此前已造成抗日力量损失。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('895db15e398f45bbab0e30f2e2e989bd','ce9e90f94a5d49b1bfa7d545908262bf',1935,'伪冀东防共自治政府保安队第二总队总队长','率部驻守平谷地区，配合日军清剿抗日游击队，多次参与“扫荡”行动，抓捕并杀害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8de76cbfca6345c1a30b098d3c241906','c962700c3422426b946336b59832e9d0',1935,'伪冀东防共自治政府保安队第三总队总队长','在平谷及周边地区执行日军命令，强征民夫修筑炮楼和公路，破坏抗日根据地交通线。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fa9bd63f1e734020a98b630f2007e003','b5ba32ac9dee4113808d7f1e4475b119',1935,'伪冀东防共自治政府政务长官','虽非平谷本地人，但其建立的伪政权直接管辖平谷，推行“自治”卖国政策，为日军提供粮秣和劳役，是平谷地区汉奸体系的最高后台。；虽非顺义籍，但其伪政权管辖顺义，推行奴化教育，强征粮税，配合日军控制顺义地区。；策划冀东独立，使宁河等地脱离中国管辖，为日军提供战略基地，残害抗日群众。；冀东伪政权首脑，管辖包括蓟县在内的22县，推行亲日政策，为日军提供后勤支持。；1935年11月在通州成立冀东防共自治政府，辖冀东22县（含唐山地区），公开投敌，配合日军侵略，后任伪华北政务委员会顾问等职。；1935年11月在通州成立冀东防共自治政府，辖冀东22县（含唐山、丰南一带），公开投敌，为日军提供粮饷和劳役，协助镇压抗日活动。；1935年11月在通州成立伪冀东防共自治政府，辖冀东22县（含丰润），公开投敌，为日军提供粮饷和劳役，镇压抗日活动。；1935年11月在通州成立伪冀东防共自治政府，辖冀东22县（含唐山、汉沽一带），推行日伪统治，配合日军经济掠夺与“治安肃正”。；1935年11月在通州成立伪冀东防共自治政府，管辖包括唐山、秦皇岛在内的冀东22县，推行亲日政策，镇压抗日活动。；1935年11月在通州成立伪冀东防共自治政府，辖冀东22县（含唐山、芦台一带），推行日伪统治，协助日军镇压抗日力量。；1935年11月在通州成立冀东防共自治政府，管辖包括唐山、开平在内的冀东22县，公开投敌，为日军提供粮饷和劳役，镇压抗日活动。；1935年11月在通州成立伪冀东防共自治政府，管辖包括唐山、滦县（今滦南）在内的冀东22县，推行日伪统治，协助日军镇压抗日力量。；1935年11月在通州成立伪冀东防共自治政府，辖冀东22县（含唐山、滦州地区），公开投敌，为日军侵华提供行政支持。；1935年11月在通州成立冀东防共自治政府，管辖包括唐山、迁西在内的冀东22县，公开投敌，为日军提供粮秣和劳役，镇压抗日活动。；1935年11月在通州成立伪冀东防共自治政府，管辖包括唐山、遵化在内的冀东22县，公开投敌，为日军提供粮秣、劳役，并镇压抗日活动。；策划冀东独立，其辖区包括廊坊部分地区，为日军提供行政和军事支持。；1935年成立冀东伪政权，管辖包括香河在内的22县，推行奴化教育，协助日军控制冀东地区。；1935年11月在通州成立伪冀东防共自治政府，管辖包括秦皇岛、北戴河在内的冀东22县，公开投敌，为日军提供行政和资源支持。；在日本唆使下成立冀东防共自治政府，首府通州，辖秦皇岛、山海关等地，公开投敌，成为华北最大汉奸政权头目；在通州成立伪冀东政府，管辖包括秦皇岛在内的冀东22县，为日军提供后勤支持。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f2287500cc5c450fbce6b06bf1024dac','fe3714834b1947b889499c395158f675',1936,'伪平谷县知事（县长）','在平谷县内推行伪政权法令，征收苛捐杂税，强征壮丁补充伪军，并配合日军“治安肃正”行动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c31f2c6fe98f4b5eac82f94a5047ba2a','a910bc7ef4a74141a554e23f9f71fad3',1937,'伪平谷县保安团团长','组织地方伪武装，多次袭击八路军游击队，破坏中共地下组织，杀害抗日干部和群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('895df807afca44c6b052026bb9102cb8','00fcfa514aea475d897a0ab357c022ce',1938,'伪平谷县警察局局长','指挥伪警察搜捕抗日人员，严刑逼供，并协助日军建立“人圈”隔离区，导致大量平民死亡。','市县厅局级','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f7fef1133159458898398cfa5ce2ba6a','db1e6092738e4391abcefa7a088da25f',1939,'伪平谷县新民会会长','推行奴化教育，宣传“中日亲善”，强迫学生和民众参加反共集会，搜集抗日情报供日军使用。','基层维持会/地方自治头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f9a1cf94f31847b2a0c44ee34faab987','7840583523b447a6999d9c07357583ec',1937,'伪平谷县维持会会长','日军占领平谷初期，组织维持会为日军筹粮筹款，提供向导，并劝降当地武装力量。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4e93113eee094cdc837b79f7d583f15d','a7845bbb3e9840399dafb60db4c5d083',1940,'伪平谷县自卫团总团长','率自卫团配合日军“扫荡”盘山、鱼子山等抗日根据地，烧毁村庄，抢掠物资。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cfff02a9890e4664ba78788b0d2ef0b5','b38f0f5b5fbd4d19800645006923a50a',1941,'伪平谷县特务队队长','专门刺探八路军情报，诱捕抗日家属，多次带队突袭中共秘密联络点。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('60dd6d5ebc6b429584c7ab3ee55e7ab9','b5ba32ac9dee4113808d7f1e4475b119',1935,'伪冀东防共自治政府委员长（后并入北平伪政权）','早年亲日，1935年成立冀东伪政权，后参与华北伪政权活动，在北平、延庆一带协助日军推行“自治”和殖民统治。；虽以冀东为主，但活动范围涉及北平及海淀，与日伪合作，破坏抗日力量','地方伪政权首脑','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e9b273e63f354a3fbcc736852c8965bf','83b067447f4744f7b527179c4d9524d4',1937,'伪冀东防共自治政府秘书长、伪北平特别市市长','殷汝耕亲信，后任伪北平市长，在北平市区及延庆等郊县推行保甲制度，强征粮食物资，镇压抗日分子。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3921dcbde93c4d5b8d53928a8dafb0ba','eb97867e737c44e4944e71b5792c1f23',1938,'伪北平特别市市长（1938-1943年）','原国民党官员，投日后任伪北平市长，在延庆等辖区推行日伪法令，组织“献铜献铁”，协助日军强化治安。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5f88f66810c84a69aee2a699e0fd8e0f','9a58a6d0ca124e4e8470270a43ef0a46',1937,'伪北平特别市警察局局长','在北平及延庆地区指挥伪警察，搜捕抗日地下人员，破坏中共地下组织，参与“治安强化运动”。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4e76af48be6940f38ebe46666ca2822c','1faedd8cdd3645bc9f7cadb419ee99d9',1937,'伪北平维持会会长（1937年）','七七事变后率先投敌，组织北平维持会，为日军提供粮食、劳力和情报，协助建立伪政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a6ca3530d25f403abe79dcba8b07e83f','10b88f41fdee46778f29f60ae3d41741',1937,'伪北平维持会委员、伪华北政务委员会教育总署督办','参与北平维持会，后主管伪教育，在延庆等县推行奴化教育，强制学习日语，篡改历史教材。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('263d86d54464481b88e803983731d35f','f724b4f7519147ba93e302a475b2a225',1943,'伪北平特别市市长（1943-1945年）','继任伪北平市长，在延庆等地区继续推行日伪“粮食统制”，强征农民粮食，配合日军“扫荡”。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f064248f51824f809ba967f3403ed766','51ceebe33eeb4f9cb54cb104d5f88f7c',1938,'伪华北政务委员会实业总署督办','在北平及延庆地区控制矿山、土地资源，为日军开采铁矿石等战略物资，剥削当地劳工。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bf848bfa05634c0db9eb568d9c54d55d','ad65aa69fa0c4f84aa598321e8c96ad1',1937,'伪华北政务委员会常务委员、伪司法委员会主任','参与北平伪政权司法系统，在延庆等地设立伪法院，迫害抗日群众，判处抗日志士死刑或劳役。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4b4238e007cc4c31a0bfac37e1ad5277','31abdc5e4e0a4ebdbe5f0b715a509863',1937,'伪华北政务委员会委员长（1937-1940年）','原北洋财政官僚，投日后任伪华北政务委员会委员长，在北平及延庆地区全面推行日伪统治，组织“新民会”进行奴化宣传。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1902285e3bf147f997831a5a7bacb74d','e1badd3fe14246acb4a3d2bf765b2db2',1940,'伪华北政务委员会常务委员、伪外交总署督办','在北平参与伪政权外交事务，协助日本与汪伪政权协调，在延庆等县推行“中日亲善”宣传。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1b24c5db586b4132af7b73c3938a6020','4b89b0b1aadc4aa2b3384379d6297cd7',1938,'伪山西省长（曾兼北平伪职）','虽主政山西，但曾参与北平伪政权高层会议，其势力范围涉及延庆西部山区，协助日军封锁抗日根据地。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('72856df3a4eb451a96d3ac0dd34103c6','0f151e47db9644d9ace941df70ec928e',1938,'伪延庆县知事（县长）','在延庆县任伪县长期间，强征民夫修筑炮楼和公路，组织伪自卫团，配合日军对南山（平北根据地）进行“蚕食”。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aab0bc0a9770416886b34d72ed5c7765','6e325888a6184fba8b9a24fff2d06259',1940,'伪延庆县知事（县长）','在延庆推行“保甲连坐”制度，搜捕八路军侦察员，向日军提供抗日武装活动情报，并强征粮食支援日军。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('54a84773e90342b99f65135882ed38ad','0721d11b69354e76be459073ddfed089',1943,'伪延庆县知事（县长）','在延庆县实施“集家并村”，制造无人区，强迫村民迁入“人圈”，以切断八路军与群众联系，导致大量平民死亡。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f5cef3dcf8f444c4923de69d3597ecbf','98806a70e2a5421093e5f8e97c85b408',1939,'伪延庆县保安队队长','率伪保安队多次袭击延庆南山抗日游击队，杀害抗日干部家属，参与日军“扫荡”时烧毁村庄。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2838cf2d8e7242a2acf69838dde1dbd9','ca98b51623614f28884f4acd68101522',1940,'伪延庆县警察所所长','在延庆县城及各乡镇设立警察分所，抓捕中共地下党员，刑讯逼供，破坏平北地委在延庆的交通站。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('96b8c2a8fcad4e17bd425dfc9f9ab6b8','794da95164184f74a08235220228dd72',1938,'伪延庆县新民会会长','在延庆组织新民会分会，推行“中日满提携”宣传，强迫青年参加“青少年团”，为日军募集“国防献金”。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('39cf20723fcd47819189b982246efe89','c7a7c0df655541829963ae618c4d77f5',1941,'伪延庆县自卫团总团长','组织地方自卫团，在延庆各要道设卡盘查，截获八路军物资，并配合日军对海坨山根据地进行封锁。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('344dcc57df704c5d9cee2ecf2165f724','ef5a687241184544b6cc872ace3c202f',1939,'伪延庆县财政科科长','负责为日军征收田赋和苛捐杂税，在延庆地区强征“治安费”，中饱私囊，导致农民破产。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3d7ab8417c834ba7b48a5734f19ff3af','42380c2514e24c09b091dccbae095ab8',1940,'伪延庆县教育科督学','在延庆各小学推行日语教育，强迫学生唱日本国歌，检举有抗日思想的教师，导致多名教师被捕。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5479186f0c214d3f8b3b47029540bbdf','d255dc1ec48b48db88f1279a2498b74c',1942,'伪延庆县情报班班长','专门收集平北八路军情报，多次带领日军偷袭延庆北部村庄，造成抗日干部牺牲。','无明确职位或一般帮凶','hanjian');
