INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cc718d7369a546058808e59aa24fdf6e','4cc5391bc78947fa9bf1a4b59e0f5371',1943,'伪北平市市长（1943-1945）','原北洋官僚，投日后任伪北平市长，管辖包括昌平在内的北平郊区，配合日军征粮、抓夫和“治安强化”运动。；投日后任伪北平市长，管辖包括朝阳区在内的北平城郊，推行保甲制度，配合日军搜捕抗日分子。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ef7f49f8627849f8acdc18db407b959b','10b88f41fdee46778f29f60ae3d41741',1937,'伪北平市警察局局长（早期）','原宋哲元部参谋，七七事变后投日，任伪北平警察局长，协助日军控制北平及昌平治安。','市县厅局级','hanjian');
