INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dddc684729d94acf80dd0110f11f713a','06c4f35ee78346faad09f9021d8bd970',1940,'伪华北政务委员会司法委员会委员长','原北洋司法总长，投日后在北平参与伪司法体系，对昌平地区抗日民众进行“审判”镇压。','机构委员长(非国家首脑)','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('75ed627674a54ec2b8952a616ea71725','8c3fc817fd6c4eb0bfe45745acc26067',1937,'伪华北政务委员会教育总署督办','原北大教授，投日后主管北平及昌平教育，推行奴化教育，删改历史教材。；投敌后负责伪华北教育，推行奴化教育，影响包括聊城、茌平在内的山东沦陷区学校。；在廊坊各学校强制推行日语教育，灌输“大东亚共荣”思想。；在伪华北政权中负责教育，推行奴化教育，影响河北等地。；投靠日本，参与伪华北政权，推行亲日教育，配合日军在华北包括陕西周边地区进行文化殖民。','省部级/大军区级要员','hanjian；traitors');
