INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5cf6be62308043b0bb9b2bfd88b38d7e','d86ac8e46e324096940ee6de177c0b2d',1940,'伪昌平县保安队队长','率伪保安队配合日军“扫荡”昌平西山抗日根据地，杀害无辜百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('619ab6f26bd14cd3b0a60f10ac79e3bc','8f1dd12e548b4c4f866dd743c3377896',1937,'伪华北政务委员会内政总署督办、伪中华民国临时政府议政委员会常务委员','原北洋政客，投日后任伪华北政权要职，在北平（今北京）推行日伪统治政策，协助日军镇压抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('be86522f63914158a882dbf241b5f7b9','da58b77853f14ce7b32f7f6b3305b75a',1937,'伪华北政务委员会治安总署督办、伪华北绥靖军总司令','原直系军阀，投日后在北平组建伪华北绥靖军，配合日军在华北地区（含朝阳地区）进行“扫荡”和清乡。；伪华北治安与伪军头目，配合日军‘扫荡’与‘治安强化运动’，对四川等后方进行军事威胁。；原北洋直系将领，投日后组织伪华北治安军，在河北、天津地区协助日军扫荡抗日根据地，残害抗日军民。；原为北洋军阀，抗战期间投靠日本，在华北组建伪军，配合日军对山东、河北等地进行扫荡和治安强化运动，其伪军系统曾活动于鲁西北聊城一带。；原北洋军阀，投日后任伪华北最高军事长官，在河北（含石家庄地区）推行“治安强化运动”，组织伪军配合日军扫荡抗日根据地。；原北洋军阀，投日后任伪华北最高军事长官，在河北等地组织伪军配合日军扫荡，镇压抗日力量。；组建并统辖华北伪军，推行日军治安强化运动，其伪军系统覆盖河南沦陷区包括信阳一带。；在华北伪政权中负责伪军和治安，组建伪绥靖军，其伪军系统扩展至河南沦陷区，商丘、虞城一带伪军多受其节制或影响。；投靠日本，组建伪军，在华北地区配合日军扫荡抗日力量，其伪军活动范围涉及陕西周边，对陕西抗日根据地构成威胁。；在华北伪政权中负责军事，统辖伪军配合日军作战，其伪军活动范围涉及晋陕绥边区，对榆林、府谷构成威胁。；组建伪军配合日军扫荡抗日根据地，其伪军活动范围涉及华北，对陕西周边抗日力量构成威胁。；在华北伪政权中负责治安与伪军，配合日军扫荡抗日根据地，其活动对陕西周边有威胁。；投靠日本，组建伪军配合日军在华北地区进行治安战和扫荡，势力范围涉及陕西周边。；在华北伪政权中负责治安与伪军，配合日军进攻抗日根据地。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('65567a3ba9ba4df4a89827faeb80d621','b5ba32ac9dee4113808d7f1e4475b119',1935,'伪冀东防共自治政府政务长官（后并入伪华北政权）','早年亲日，1935年成立冀东伪政权，辖区包括北平东部及朝阳地区，协助日军控制冀东，镇压抗日活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('16309b82f3534bcaaf4c7b8723807f1c','83b067447f4744f7b527179c4d9524d4',1935,'伪冀东防共自治政府秘书长、伪华北政务委员会参议','殷汝耕亲信，参与冀东伪政权运作，在朝阳地区推行日伪法令，协助日军征粮派夫。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f02d4f04521847928c1ef149ed8ba580','10b88f41fdee46778f29f60ae3d41741',1937,'伪北平市警察局局长（后任伪天津市市长）','七七事变后投日，在北平（含朝阳）任伪警察局长，协助日军维持治安，迫害抗日群众。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('035ad50bad114647a6f95e46fbc9fd09','bbc7d2d2f1174918a3a12cc3ce766af2',1937,'伪北平维持会会长（1937年短暂）','北洋遗老，北平沦陷初期出任伪维持会会长，为日军在朝阳地区建立秩序提供协助。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d1eb7ff0e3e747ffaae17f9f560f5b9e','bbc7d2d2f1174918a3a12cc3ce766af2',1937,'伪北平维持会会长、伪北平市市长','七七事变后出任伪北平维持会会长，后任伪北平市长，协助日军维持北平（含海淀）秩序，镇压抗日民众；组织北平维持会，投降日军，维持日伪在北平的统治，其行为对华北包括陕西地区有示范性附逆影响。；在北平组织维持会，协助日军维持占领区秩序，其活动范围接近陕西，对华北地区抗日力量构成威胁。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e36498c782d24f89919b4865916c1061','eb97867e737c44e4944e71b5792c1f23',1938,'伪北平市市长（继江朝宗后）','在任伪北平市长期间，推行日伪奴化教育，在北平及海淀地区实施保甲制度，协助日军征粮抓夫','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cd6f095ed4a54e90a29650f780231b81','1faedd8cdd3645bc9f7cadb419ee99d9',1937,'伪北平市社会局局长、伪华北政务委员会教育总署督办','在北平推行奴化教育，控制学校（包括海淀的燕京大学、清华等周边），迫害爱国师生','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ab4de3353d2b4b778f039e2312f82ca6','56b7d146cc554e51b0e7b263ead18f3f',1937,'伪北平市宣传处处长、伪《新民报》社长','在北平（含海淀）控制舆论，宣传“大东亚共荣”，为日伪张目，污蔑抗日活动','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d33e0ffb54204c288eda87196dfb40ea','ad65aa69fa0c4f84aa598321e8c96ad1',1937,'伪华北政务委员会司法总署督办','在北平主持伪司法系统，审判抗日志士，迫害海淀及北平地下党员和进步人士','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0fc8f838067a42989c25d1d11165c699','1bea23fefee9462fab8d11fc69a557b9',1937,'伪华北政务委员会财务总署督办、伪中国联合准备银行总裁','在北平发行伪币，搜刮民财，包括海淀地区，为日军侵略提供经济支持；华北金融界汉奸，把持伪中国联合准备银行，为日军掠夺华北经济服务。；投靠日本，在华北伪政权中任职，控制金融，配合日军经济掠夺，对陕西有间接影响。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('209baad32e0a42258d0756c7037d747d','4b89b0b1aadc4aa2b3384379d6297cd7',1937,'伪华北政务委员会实业总署督办','在北平及海淀地区掠夺工农业资源，强征劳工，服务于日军战争需求；负责华北工矿资源统制，直接管理石景山制铁所的生产计划，强迫中国工人劳动，为日军提供军工原料。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e1dca7852021491dbbee454c9a5a8efb','51ceebe33eeb4f9cb54cb104d5f88f7c',1938,'伪北平市秘书长','协助伪市长管理北平（含海淀）行政，推行日伪各项政策，参与镇压抗日活动','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('89b2ce8a16484fe0b8f8a22f033aff79','2065d53788cb446db1cb50dcd0173c1f',1939,'伪北平市警察局特务科科长','在北平及海淀地区指挥特务活动，抓捕抗日地下工作者，破坏中共平西根据地联络点','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('72cf814af2b1468b8dc95bc45a429e91','6efd8b07afa9443aa37b3a64e9e23aa0',1940,'伪华北政务委员会教育总署督办（继张璧后）','在北平（含海淀）推行日本化教育，强制学生学日语，迫害拒绝合作的教师学生','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('02626da3c3954f7697fe75c8a5a4fe31','e1badd3fe14246acb4a3d2bf765b2db2',1943,'伪华北政务委员会委员长（后期）','在北平主持伪华北政务委员会，继续配合日军“治安强化”，镇压海淀及周边抗日力量','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c4cad965175b460bab64e37e1ba0a2a1','892cdd9ae3d2444996fbaf7f65134db1',1937,'伪华北政务委员会咨询委员（未实际就任但参与活动）','虽未任实职，但在北平与日伪高层往来，为日伪政权提供政治咨询，影响海淀地区亲日势力','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('594a2272321d4ab8a9af8c25320508d8','8f1dd12e548b4c4f866dd743c3377896',1937,'伪华北政务委员会内政总署督办、伪华北防共委员会会长','原北洋政客，抗战期间投敌，任伪华北政务委员会要职，在北平（含石景山地区）推行日伪统治政策，协助日军进行经济掠夺和奴化宣传。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('13d2a1f0f74d441db03ba5e79b9dae91','b5ba32ac9dee4113808d7f1e4475b119',1935,'伪冀东防共自治政府委员长（后并入华北伪政权）','早年亲日，1935年成立冀东伪政权，后参与华北伪政权活动，其势力范围曾涉及北平近郊（含石景山一带），协助日军控制平西地区。；虽以冀东为主，但其势力曾延伸至北平郊区（含门头沟），协助日军在平西地区推行伪化统治，破坏抗日组织。','地方伪政权首脑','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bac157b7264b4117885fae844fe0584c','6876b4dc973441299b47d406050a627f',1938,'伪华北政务委员会教育总署督办','在北平推行奴化教育，其管辖学校包括石景山地区的小学和中学，强制推行日语教学和“中日亲善”宣传。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('726d561032c34c38aea726febf3922de','1faedd8cdd3645bc9f7cadb419ee99d9',1937,'伪北平维持会会长（初期）','七七事变后组织北平维持会，为日军提供后勤支持，其势力渗透至石景山地区，协助日军接管当地工矿企业。；七七事变后组织北平维持会，协助日军维持门头沟等郊区秩序，为日军征粮派款。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0bb31882d3184bae829d452471a66b78','83b067447f4744f7b527179c4d9524d4',1935,'伪冀东防共自治政府秘书长、后任伪华北政务委员会参议','参与冀东伪政权，后转任华北伪职，曾参与策划对平西（含石景山）抗日根据地的经济封锁。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7796656daac54f068dc601b705ec5770','31abdc5e4e0a4ebdbe5f0b715a509863',1937,'伪华北政务委员会委员长（1937-1940）','作为华北伪政权最高头目，其政策直接覆盖石景山地区，包括强制征用石景山铁厂为日军生产军需钢铁。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1008de79f7974e6baf782fa582afb8f0','ad65aa69fa0c4f84aa598321e8c96ad1',1938,'伪华北政务委员会常务委员、伪司法总署督办','在北平推行伪司法体系，对石景山地区抗日群众进行“审判”和迫害。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c66a9c0cfa614821847718450df1ab85','f724b4f7519147ba93e302a475b2a225',1938,'伪北平市工务局局长','在石景山地区强征民夫修建军事道路和碉堡，服务于日军对平西根据地的“扫荡”。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('071c29943d4446d3bdaa74f54c5f2f4c','10b88f41fdee46778f29f60ae3d41741',1938,'伪北平市社会局局长','在石景山地区推行保甲制度，监控居民活动，协助日军抓捕抗日地下工作者。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4dbd930400ac473d88541d0a633a9212','080f0af97574403ebef192e3d9a63acb',1938,'伪北平市财政局局长','在石景山地区强征各种苛捐杂税，包括“国防献金”，搜刮民财供日军使用。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e738a61857584cea86daa0aaf18606c1','8f1dd12e548b4c4f866dd743c3377896',1937,'伪中华民国临时政府议政委员会委员长、伪华北政务委员会内政总署督办','积极参与伪政权，协助日本控制华北地区，迫害抗日人士。','机构委员长(非国家首脑)','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('836f40f09a2e4c30a0f1bcf60f6962d5','1faedd8cdd3645bc9f7cadb419ee99d9',1937,'伪北平维持会会长','七七事变后投靠日军，组织维持会为日军服务。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d846a2d5923340f5be66015fabaa304d','10b88f41fdee46778f29f60ae3d41741',1937,'伪北平警察局局长','协助日军维持北平治安，镇压抗日活动，逮捕爱国人士。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aa47031e215f4cf4b9b7ea128d50228a','eb97867e737c44e4944e71b5792c1f23',1937,'伪北平市市长','任伪北平市长期间，推行日伪政策，强征物资，奴化市民。；任伪北平市长期间，管辖门头沟地区，推行保甲制度，强征民夫修筑碉堡，配合日军对平西根据地的“囚笼政策”。；在北平伪政权任职，影响河北周边地区。；接任伪北平市长，继续推行日伪政策，镇压抗日活动，其统治区域与陕西同属华北伪政权影响范围。；长期担任伪北平市市长，配合日军在华北的统治，其伪政权体系延伸至陕西部分地区。；投靠日本，任伪北平市长，协助日军在华北包括陕西周边维持统治。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('79205e677d444d14b51b2f2ead5353ec','bbc7d2d2f1174918a3a12cc3ce766af2',1937,'伪北平维持会副会长','协助张璧维持北平秩序，为日军服务。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0a44aa4157a24183b381e59053723e6e','7777aa506f28464b99a778cee79ef88f',1938,'伪北平市社会局局长','推行日伪社会政策，镇压民众反抗。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('093f9bc9de83448fa1d4a3266c949453','a686547c9dc04e8db95ac9b7663d7b9b',1938,'伪北平市财政局局长','为伪政权征收苛捐杂税，搜刮民脂民膏。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b81b7999a9ac455383ec89b7d8e49824','ad65aa69fa0c4f84aa598321e8c96ad1',1940,'伪华北政务委员会常务委员','参与伪政权决策，协助日本控制华北。；参与决策对冀中抗日根据地的“毁灭性扫荡”，包括廊坊地区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dcc8bca2424340d1a6a65315f507c989','e1badd3fe14246acb4a3d2bf765b2db2',1937,'伪华北政务委员会实业总署督办','协助日本掠夺华北资源，控制工矿企业。；多次到南京鼓楼区与汪伪商谈经济合作，掠夺资源。；负责在廊坊地区掠夺棉花、粮食等战略物资，支持日军战争经济。；投靠日本，参与伪华北政权，配合日军在华北包括陕西周边地区进行经济掠夺和殖民统治。；投靠日本，参与伪华北政权，配合日军在华北包括陕西周边地区进行经济掠夺。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b4e1a5b40aa9403292f1ac988f3bfc54','b5ba32ac9dee4113808d7f1e4475b119',1935,'冀东防共自治政府政务长官','1935年11月在通州成立冀东防共自治政府，公开投日，管辖冀东22县，配合日军侵略，镇压抗日活动。；1935年11月在通州成立冀东防共自治政府，辖冀东22县（含唐山、乐亭），公开投日，推行奴化教育，协助日军镇压抗日力量。；1935年11月在通州成立冀东防共自治政府，辖冀东22县（含唐山、丰润、滦县等地），公开投日，推行奴化教育，协助日军镇压抗日力量。；1935年11月在通州成立冀东防共自治政府，辖冀东22县（含唐山、迁安一带），公开投日，推行奴化教育，协助日军镇压抗日力量。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5b29c6e8a5274ca483f00ea24119e726','83b067447f4744f7b527179c4d9524d4',1935,'冀东防共自治政府秘书长、代理政务长官','殷汝耕的主要助手，参与冀东政权运作，后接替殷汝耕主持伪政府，协助日军征粮征税、推行奴化教育。；殷汝耕的主要助手，参与冀东伪政权运作，管理唐山地区伪行政事务，协助日军征粮派款。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9384a362c366431da748cde598eb75a2','fe3714834b1947b889499c395158f675',1935,'冀东防共自治政府财政厅长','负责伪政权财政，为日军搜刮民财，发行伪币，强征捐税，支持日本侵华战争。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d9a5aed760734e02aff2f53e7c906e17','4cc5391bc78947fa9bf1a4b59e0f5371',1935,'冀东防共自治政府民政厅长','参与伪政权民政管理，推行保甲制度，协助日军控制民众，镇压抗日力量。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b52c7a8a7d004c16b6ba355caaa38730','9dc3aaa23c914c94acade8c943435489',1935,'冀东防共自治政府建设厅长','负责伪政权建设事务，为日军修建军事设施、公路，强征劳工，服务日军侵略。；负责伪政权下唐山矿区及交通设施管理，配合日军掠夺开滦煤矿资源。；主持伪政权交通、工矿建设，强迫劳工修筑公路、炮楼，服务日军军事行动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('86cc4edebed34c13924cb6fbe21dbab2','7ecf38311c27407bbb44fdd793ae7b5b',1935,'冀东保安队第一总队队长（后反正）','原为冀东伪军头目，1937年7月通州事变中率部反正，杀死日军和汉奸，但此前曾为伪政权效力。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2c5a43dcea084227b8a51289e4069700','14a8c9f458644409a01ba33a632897c7',1935,'冀东保安队第二总队队长（后反正）','与张庆余共同参与通州事变，但事变前长期担任伪军职务，参与镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('51f030a2b98e4127b9554e7806da23d1','f2cea8604a98415bbecbe97950aa5b7c',1937,'通县伪县长','在日军占领通县后出任伪县长，推行日伪政策，强征粮食和壮丁，协助日军维持治安。','基层头目','hanjian；traitors');
