INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a3c8e1b7c6734b75b609f5041b6c5990','8fdb75c63ff4478aa86d74431b472cde',1935,'伪冀东自治政府顾问','日本顾问的帮凶，参与策划冀东独立，为日军提供情报，协助镇压反日运动。；作为日本顾问的帮凶，参与策划唐山地区“自治”运动，煽动地方武装投日。；参与策划冀东独立，在秦皇岛海港区为日军搜集情报，破坏抗日组织。','无明确职位或一般帮凶','hanjian');
