INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f46dc74a61a14758be3ffeac761d4602','5e3c03e59a9d4a4f81ce0c0f481fb548',1938,'伪顺义县知事（1938-1940）','在顺义县内积极推行日伪政策，强征粮食，破坏抗日组织，残害抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('562501530e5542518c8781c63cc85e24','b77a9c0384c94aa5bcd13e6c90ce35f9',1941,'伪顺义县知事（1941-1943）','配合日军“治安强化运动”，在顺义各乡建立伪自卫团，抓捕抗日干部。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f2136df24c304230a793664c725776ed','a33d9d33d4314a7596a98c96c5411050',1940,'伪顺义县保安队队长','率伪保安队多次袭击顺义抗日游击队，杀害多名抗日战士，烧毁村庄。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8491125de3f940238a567158b0107e7f','f661374d03de470a9598decac6bb7127',1939,'伪顺义县警察局局长','协助日军搜捕抗日分子，严刑拷打被捕人员，提供情报给日军。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cc92a328a8884af5bee1105792518cfb','1de4a2fe5c5d4e588f4afda8126cfbf5',1940,'伪顺义县新民会会长','推行奴化宣传，组织“新民会”分会，强迫百姓参加反共集会，收集抗日情报。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('16192fa946b84494a1f33a5715f67eba','d255dc1ec48b48db88f1279a2498b74c',1937,'伪顺义县维持会会长（1937-1938）','日军占领顺义后率先投敌，组织维持会，为日军筹集粮款，引导日军清乡。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2b52dd0ab9b04bf9ac7e1b1fd06b18a3','cd0961240f5a402b99d07be615a555e2',1941,'伪顺义县联庄会总会长','组织地主武装联庄会，配合日军封锁抗日根据地，杀害过路抗日人员。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c6ab34a80c8b453abc737fcbe6bf9261','875c22d678e24c21834a32caae69933c',1931,'伪满洲国财政部总长、吉林省省长','九一八事变后投靠日本，协助建立伪满洲国，任吉林省伪省长，镇压抗日力量，推行殖民政策。；九一八事变后叛国投敌，协助日军占领吉林，任伪吉林省长官，推行殖民统治，镇压抗日力量。；九一八事变后投靠日本，协助日军占领吉林，积极推行伪满洲国殖民统治，出卖吉林地区主权和资源。；九一八事变后投敌，出卖吉林军政，协助日军占领吉林，后任伪满要职，推行殖民统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c8395a1d8db44734ab97cdf8b75d7a49','77a789268c6f47b4a617cdb9e41180bd',1931,'伪满洲国国务总理大臣（曾任吉林地区军政职务）','原东北军将领，后投敌，历任伪参议府议长、军政部总长、国务总理，在吉林地区协助日军清剿抗日武装。；原东北军将领，投日后成为伪满最高行政首脑，参与签订卖国条约，镇压抗日力量。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d3221373f579420595e164afc2287a4a','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满洲国治安部大臣、伪奉天省省长（曾在吉林任职）','原东北军旅长，投日后在吉林地区组织伪军，参与围剿东北抗日联军。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('75086959372344d1b5db716b8ac4f1c9','c0860f9060d74dfba1674157f4596712',1931,'伪满洲国吉林警备军司令官','原吉林陆军军官，投日后任伪吉林警备司令，协助日军镇压吉林抗日义勇军和抗联。；原吉林陆军军官，投日后任伪吉林警备军司令，率伪军配合日军在延边、安图等地“讨伐”抗联第一路军。；满族贵族，投日后任伪吉林警备司令，配合日军在延边、珲春等地“讨伐”抗日游击队；率伪军驻守吉林地区，多次参与“围剿”东北抗联，屠杀抗日志士。；原吉林陆军将领，投敌后负责黑龙江东部及哈尔滨周边治安，配合日军围剿抗联。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2552f524e1ee4fc1adc879092d9b27d1','2acf7a5b9b5341578e1066b27394b2eb',1930,'伪满洲国吉林省省长（后期）','曾任伪吉林省长，推行日伪统治政策，参与经济掠夺和奴化教育。；继熙洽后任伪吉林省长，推行日伪法令，强征劳工，搜刮粮食支援日军。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cd8f6f8ddd454ef28574654ac398bdc9','350822a1078340679fd657c16a793993',1932,'伪满洲国吉林省警务厅长','负责吉林地区伪警察系统，搜捕抗日分子，协助日军实施“治安肃正”。；组织伪警察协助日军“讨伐”抗联，在长春、公主岭等地实施特务监控和逮捕抗日志士。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('09e96d28e868460593020d97cc328a6b','41502657c6b84465aa2ff94e620ed234',1932,'伪满洲国吉林省财政厅长','管理伪省财政，为日军侵略战争筹措资金，参与鸦片专卖等掠夺政策。；为伪政权搜刮民财，强征捐税，支持日军军费，导致民生凋敝。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e136354bdfd241d38003d3c0e6637991','caae33d173854bf0a1b2b4f0db4f585a',1932,'伪满洲国吉林省民政厅长','推行保甲制度，强化殖民统治，协助日军建立“集团部落”以隔离抗联。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ab89e0af0f3244a7b0487fe5e6f26ae9','70cbcc058e6648678fa022e3a64b9cea',1932,'伪吉林市市长','任伪吉林市长期间，推行日伪市政管理，镇压反满抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8219ed0776614ef1adc2389baaa463a4','c276a824877f4dce865833533f6312bf',1932,'伪吉林省教育厅长','推行奴化教育，强制学校教授日语，篡改历史教材。','市县厅局级','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cccea1d760684e86b4b642d8b0b11cfd','6876b4dc973441299b47d406050a627f',1932,'伪满洲国吉林省实业厅长','协助日本掠夺吉林森林、矿产等资源，组织劳工为日军服务。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ada377f1093e47f2aed99386257dd9ce','3eb966fdcf364389b5302ef8a669f7ac',1932,'伪吉林省高等法院院长','利用司法系统迫害抗日人士，判处大量爱国者死刑或长期监禁。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c5fe5161698a4f91b64b4306173d651f','b21d5a4d224a4173bdb0f2b366c98d70',1932,'伪吉林省协和会本部副本部长','在吉林地区组织协和会，进行反动宣传，搜集抗日情报。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6f88b6863e804fde809583647cd4132e','5e9cb4e347ef4eca9f361ebe4a80f840',1933,'伪吉林省警务厅特务科长','指挥特务活动，破坏抗联地下组织，逮捕杀害多名共产党员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8f57477e60814653b2a0d3422a78c1e0','3eaf116c87a7417fadcbf5fe87b56f23',1932,'伪吉林省保安队队长','率伪保安队多次进攻抗联根据地，烧毁村庄，屠杀百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e398602643df4be4ade2697de03ee642','3cd55e29febc489d9f9a7f2f88db31bb',1932,'伪吉林市警察局长','在吉林市实施白色恐怖，搜捕抗日学生和地下工作者。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('06bae10679514bd995640c5625c775b0','58810d67711e4176a4293723665a9ab6',1932,'伪吉林省延吉地区行政专员','在延边地区推行“间岛”政策，镇压朝鲜族抗日武装。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2b4fd9bda4a8409da4d1d9f928dd38cf','6efa2b05428f4ce7bca190966f945873',1934,'伪吉林省间岛省省长（今延边地区）','协助日军在延边建立“集团部落”，围剿抗联第二军。','省部级/大军区级要员','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('15e6af07acb84370b0560489e8158563','cb533c0f884642bbba0b4cbc47fa1713',1934,'伪吉林省间岛省警务厅长','在延边地区大肆逮捕抗日志士，破坏抗联地下交通线。','市县厅局级','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('90c69599b6484a78aa6fb3bd672a1de7','e1f79d7adf2d407393f6feedc366834e',1934,'伪吉林省间岛省协和会头目','组织亲日朝鲜人团体，协助日军进行“思想战”和情报活动。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('727ecfccf3de4630b21c578a43480503','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满吉林省省长、伪满军政部大臣','九一八事变后投靠日本，任伪吉林省长官，协助日军镇压抗日武装，推行殖民统治，参与“讨伐”东北抗日联军。；九一八事变后投靠日军，任伪吉林省长官，镇压抗日武装，协助日军建立伪满政权，在吉林地区推行殖民统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('931160e37b73479ab09878404df419d4','875c22d678e24c21834a32caae69933c',1931,'伪满吉林省长官公署长官、伪满宫内府大臣','原吉林省政府委员，1931年叛国投敌，迎接日军占领吉林，后任伪吉林省长，积极推行伪满政权各项政策，镇压抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('81bf4d4154db473596de2e6e54985ee7','e25c85c91f604ceda710a0637532c900',1931,'伪满吉林警备军司令、伪满陆军上将','原东北军将领，投日后任伪吉林警备军司令，多次率伪军“围剿”抗日游击队，在丰满一带参与清乡和屠杀抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b3ead842da864aa3a91948cf308847d8','350822a1078340679fd657c16a793993',1931,'伪满吉林省警务厅长、伪满热河省省长','原吉林警察机构官员，投日后任伪吉林省警务厅长，组织警察特务搜捕抗日分子，破坏地下组织，在丰满地区实施高压统治。；原吉林警察头目，投日后在吉林、四平建立伪警察体系，抓捕抗日地下工作者，参与“归屯并户”政策。；满族汉奸，在吉林省（含白山、长白）组织伪警察，协助日军搜捕抗联，破坏地下组织。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5e594245e7c7443ebc1bf266f691b235','142849ebf8614017a075f60e0d2e7e40',1932,'伪满吉林市市长（丰满地区属吉林市管辖）','任伪吉林市市长期间，配合日军修建丰满水电站，强征劳工，造成大量劳工死亡，并协助日军推行“治安肃正”政策。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('89b554e136024913a297719c9eec6564','448cf19f40334f31b9f5d71d601929ab',1933,'伪满吉林市警察局长','在丰满地区设立警察分所，抓捕抗日地下工作者，参与“归屯并户”行动，迫害百姓，为日军提供情报。','市县厅局级','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('92aef91877914a6f9c92aa37f9a21ee0','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满吉林省高等法院院长（后任伪满立法院院长）','参与伪满司法体系建立，审判抗日志士，以“反满抗日”罪名判处多人死刑或重刑，在吉林及丰满地区制造冤狱。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d1827a8c4bda4ff5a3eb30049c16ed53','41502657c6b84465aa2ff94e620ed234',1932,'伪满吉林省财政厅长、伪满民生部大臣','负责为日军和伪满政权搜刮吉林地区资源，包括丰满水电站建设资金和粮食征购，间接导致当地民众饥荒。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('04b61619a77345c1920c524f4de3f336','3eb966fdcf364389b5302ef8a669f7ac',1932,'伪满吉林省教育厅长','推行奴化教育，在丰满及吉林地区学校强制灌输“日满亲善”，禁止使用中文教材，迫害爱国教师。；在昌邑地区推行日语教育，篡改历史教材，强迫学生效忠日本天皇。；原吉林教育界人士，投日后推行奴化教育，在吉林、辽源各学校强制教授日语和“王道乐土”思想，迫害爱国师生。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9112ef63c43c45e98e81cff5c272bbd5','b21d5a4d224a4173bdb0f2b366c98d70',1935,'伪满吉林市丰满区协和会会长','组织协和会分会，为日军募集物资，监视居民言行，举报抗日嫌疑人员，协助日军强征丰满水电站劳工。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ce18d6f6b661466d82472a4371c08704','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满热河省省长、伪满第5军管区司令','原东北军将领，九一八后投日，在四平、洮南一带协助日军镇压抗日武装，后任伪满热河省长，参与“围剿”抗联及热河抗战部队。；原东北军将领，九一八后投敌，曾任伪满热河省省长，在宽甸、丹东一带协助日军镇压抗日武装，推行殖民统治。；原东北军将领，九一八后投敌，在盘山、营口一带协助日军镇压抗日武装，后任伪满热河省省长，围剿抗日义勇军。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0673b91676164657a1fb42929eec7d7e','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满奉天省省长、伪满治安部大臣','原东北军旅长，投日后在四平地区（原属奉天省）协助日军建立伪政权，镇压抗日义勇军，后任伪满军政要职。；原东北军旅长，后投靠日军，曾任伪满奉天省省长，镇压抗日力量，后升任伪满治安部大臣，负责伪满军警事务。；原东北军旅长，投日后在吉林、四平地区协助日军清剿抗联，后任伪满高官，参与“治安肃正”行动。；原东北军旅长，叛国投敌后任伪满奉天省省长，后升任伪满治安部大臣，积极协助日军清剿抗日力量。；原东北军旅长，叛国投敌，在吉林、通化（含白山）一带围剿抗联，推行保甲制度，残害抗日军民。；原东北军旅长，投日后在辽源一带参与清剿抗日武装，后任伪满高官。；原东北军将领，投日后任伪满奉天省省长，在辽宁地区推行殖民统治，镇压抗日力量，后升任伪满治安部大臣。；原东北军旅长，投日后任伪满奉天省省长，积极推行日伪政策，镇压抗日活动，后升任伪满治安部大臣。；原东北军旅长，投日后任伪满奉天省省长，管辖包括宽甸在内的辽东地区，配合日军“讨伐”抗联，强征劳工。；原东北军将领，九一八后投敌，任伪奉天省省长期间积极推行日伪殖民政策，镇压抗日力量，后升任伪满治安部大臣，是辽宁地区最高级别汉奸之一。；九一八事变后投靠日本，任伪奉天省省长，镇压抗日义勇军，推行日伪殖民政策，后升任伪满治安部大臣。；原东北军将领，九一八后投敌，任伪奉天省省长，镇压抗日义勇军，推行日伪殖民政策。；九一八事变后投靠日本，任伪奉天省省长，协助日军统治辽宁地区，镇压抗日力量，推行殖民政策。；原东北军旅长，投降日军后任伪奉天省省长，推行殖民统治，镇压抗日力量。；九一八事变后投靠日本，任伪奉天省省长，镇压抗日力量，推行殖民统治。；原东北军将领，九一八事变后投敌，任伪奉天省省长，协助日军镇压抗日武装，推行殖民统治。；原东北军旅长，九一八后投降日军，任伪满奉天省（含辽阳地区）省长，推行殖民政策，镇压抗日力量，后升任伪满治安部大臣。；九一八事变后投靠日本，历任伪奉天省省长、伪满治安部大臣，积极协助日军镇压东北抗日武装，推行殖民统治。；原东北军旅长，1931年投敌，在辽宁地区（包括铁岭、开原）组织伪军，配合日军“讨伐”抗日义勇军，后任伪满奉天省省长，残酷统治辽宁人民。；原东北军旅长，投日后在辽宁地区组织伪军，参与围剿义勇军和抗联，对凌海地区抗日活动进行清剿。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0b32eb745dc4458c81c3ff67d91990d9','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满立法院院长、伪满宪法起草委员会主任','原奉系法律人士，九一八后积极参与伪满建国，在四平、长春等地为日本殖民统治提供法律与行政支持。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('91ac294b3d474915bf8136497befd2c1','875c22d678e24c21834a32caae69933c',1931,'伪满财政部总长、伪满宫内府大臣','原吉林副司令长官公署参谋长，1931年投降日军，打开吉林城门，并协助日军占领四平、吉林等要地，后任伪满高官。；原吉林副都统，九一八事变时在吉林投降日军，建立伪吉林省政权，后任伪满高官，推行殖民政策，协助日本掠夺东北资源。；原吉林副都统，九一八事变时在吉林开城迎敌，组织伪吉林省政权，为日军侵占吉林、四平地区提供便利。；吉林籍满清皇族，九一八事变时在吉林开城迎敌，促成日军占领吉林，后长期担任伪满要职。；原吉林省政府委员兼吉林陆军训练处总监，九一八事变时在吉林市投降日军，宣布吉林独立，后任伪满要职，是吉林地区首要汉奸之一。；原吉林副司令长官公署参谋长，1931年叛变，引日军占领吉林市，后任伪满高官，其叛变行为导致吉林地区迅速沦陷。；清皇室后裔，原吉林副司令长官公署参谋长，1931年投敌，参与策划吉林独立，协助日军占领吉林全境，其势力影响覆盖白山、江源地区，为伪满核心汉奸之一。；原吉林省政府委员，九一八事变后主动开城迎敌，协助日军占领吉林，后任伪满高官，对吉林、辽源地区抗日力量进行残酷镇压。；原吉林副都统，九一八事变后主动开城迎降日军，策划吉林独立，建立伪吉林省政权，是吉林地区首要汉奸。；原吉林副司令长官，投日后参与策划伪满建国，虽主要在吉林活动，但曾参与对辽宁地区抗日力量的围剿。；原吉林副司令长官，投日后成为伪满核心汉奸，虽主要活动在吉林，但参与策划对辽宁地区抗日力量的围剿，其影响涉及铁岭、昌图。；原吉林副司令长官，投敌后任伪满财政总长，参与策划伪满建国，其势力影响吉林及黑龙江部分地区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('22aaaa0b94ed4760ba68f109f7c1f4dc','236b09af126745e997e5603fc3f56d0e',1931,'伪满新京特别市市长、伪满交通部大臣','清肃亲王善耆之子，投日后在四平、长春一带协助日军管理铁路与城市，镇压反满抗日活动。；清肃亲王善耆之子，投靠日本后历任伪满要职，在吉林龙潭地区推行殖民政策，协助日军镇压抗联。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7f4061a229e44a5095eb341d31af3d6d','3bf604436ded42d99cdb3360887a08c5',1931,'伪满监察院院长、伪满参议府参议','原清朝遗老，积极参与伪满建国，在四平地区活动，为日本侵略提供“历史依据”和意识形态支持。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f0ae16b2c6a04cfba26a67b63a6f1730','c6f27713c97e47d4802d65204111d7bf',1931,'伪满国务总理大臣','原清朝遗老，伪满首任总理，在四平、吉林等地推行奴化教育，协助日本殖民统治。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4e2541572cf7428aaabb42190ec0bc30','77a789268c6f47b4a617cdb9e41180bd',1935,'伪满国务总理大臣（继任）','原东北军将领，投日后在四平地区协助日军“清乡”，后任伪满总理，全面配合日本侵略政策。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b483f2759bf34b0ba3a4e7427007e644','79b17193512846a1a5bde9f5df22c926',1931,'伪满奉天省省长、伪满参议府议长','原奉天省主席，投日后在四平（原属奉天）等地组织伪警察与保甲制度，镇压抗日力量。；原奉天省长，投日后任伪满要职，在吉林、四平地区参与“治安肃正”，镇压抗日武装。；原奉系将领，被日军软禁后投降，任伪奉天省省长，推行殖民政策，强征劳工，配合日军“讨伐”抗日武装。；原辽宁省主席，投敌后任伪满奉天省省长，管辖盘山、盘锦地区，推行奴化教育和经济掠夺政策。；原奉天省省长，九一八后投降，在辽宁各地（含铁岭、开原）推行日伪法令，协助日军“清乡”和“治安肃正”。；原辽宁省政府主席，九一八被俘后投敌，任伪奉天省省长，在铁岭、昌图等地推行日伪殖民政策，后任伪满参议府议长。；原奉天省省长，九一八后投降，任伪满奉天省省长，在鞍山铁东地区推行“保甲制度”和“连坐法”，强化殖民统治。；原奉天省省长，投敌后任伪满要职，虽主要活动于奉天，但作为伪满中央高官，对黑龙江地区有管辖影响。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('484a6563a76b4691a7c0d298dd5f4257','87b0aba74b9b4c5f8a515bd9270d23b4',1931,'伪满参议府参议、伪满尚书府大臣','原奉系官僚，在四平地区参与伪政权建设，协助日军推行“治安肃正”计划。；原东北地方士绅，九一八后投敌，任伪满参议，参与伪满政权建设，为日本殖民统治出谋划策。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d7ea6149bf264140a52fa10829ab9ea5','e913aea565d54f398ad14deb4526d3a9',1931,'伪满交通部大臣、伪满奉天省省长','原东北交通官员，投日后管理四平铁路枢纽，为日军运输兵员物资，并参与镇压铁路沿线抗日游击队。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8a236627727f43bcaa05319a8aab6836','589ab27feed347c6944e6c001125dc02',1941,'伪满四平省省长（伪满后期设四平省）','伪满四平省（辖今四平、梨树、双辽等地）首任省长，推行粮食“出荷”政策，强征劳工，协助日军“讨伐”抗联。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('583462c719de4d58b5cd8e8b65437464','eb688993f9ee49a7bbacda2253de406a',1941,'伪满四平省次长（实际掌权者，日系官员）','日本关东军指派，实际控制四平省政务，实施经济统制，抓捕抗日分子，强征慰安妇。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7734a5059ae34fb0a03794dd1c68bb66','b21d5a4d224a4173bdb0f2b366c98d70',1937,'伪满四平市市长','伪满四平市（今四平市）市长，配合日军建立“集团部落”，制造无人区，迫害抗日群众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ad2ddb5b1e8b4b168146fe7e4a22e0bb','3cd55e29febc489d9f9a7f2f88db31bb',1932,'伪满四平市警察局局长','在四平地区组织伪警察，协助日军“讨伐”抗联，抓捕地下党员，实施白色恐怖。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f71d239331dc413e927700d31c7f74cc','c9dffc071fec4ce58fe1d611f26c28da',1931,'伪满四平地区保安队队长','原土匪头目，投日后在四平、梨树一带为日军充当“讨伐队”向导，屠杀抗日义勇军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3228747955824cb886892e96a6cee6db','36bc60b1acff4430b9068f55ca67281b',1932,'伪满梨树县县长','在梨树县（今属四平）推行伪满苛政，强征粮食，镇压农民反抗。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4ba049a364e646319ff912986f522bcb','baf51df720e54165b100f8dadc437b91',1933,'伪满双辽县县长','在双辽（今属四平）协助日军建立“治安维持会”，参与杀害抗联伤员。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fa138e321d86449b8feae3ae5d316c7b','41502657c6b84465aa2ff94e620ed234',1932,'伪满伊通县县长','在伊通（今属四平）强征民夫修建军事工事，并配合日军“清剿”抗联杨靖宇部。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e8c7348b13a5404ab670f61fedd7dc11','3b74f508628f475a8777ffb7e38a48a0',1941,'伪满四平省实业厅厅长','负责四平省粮食统制，强征农民余粮，导致大量平民饿死。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3ca296ea1e2b4ed8b397af2b9afc11bc','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满热河省省长、伪满军政部大臣','原东北军将领，九一八事变后投敌，曾任伪满热河省省长，参与镇压抗日武装，后任伪满军政部大臣，积极协助日军统治东北。；原东北军将领，九一八后投敌，在四平、双辽一带协助日军镇压抗日武装，后任伪满高官，推行殖民政策。；原东北军将领，九一八后投敌，在吉林、四平一带协助日军镇压抗日武装，后任伪满高官，推行殖民统治。；原东北军将领，九一八后投敌，在吉林、昌邑一带协助日军镇压抗日武装，后任伪满高官。；原东北军将领，九一八后投敌，曾任伪满热河省省长，镇压抗日武装，协助日军统治吉林西部及松原一带；原东北军将领，九一八后投敌，曾任伪满热河省省长，参与镇压抗日武装，后任伪满军政部大臣，协助日军统治东北。；原东北军将领，九一八后投敌，曾任伪满热河省省长，参与镇压抗日武装，后任伪满军政部大臣，是吉林地区早期投敌的高级军官。；原东北军将领，九一八事变后投敌，任伪满热河省省长，参与镇压抗日武装，协助日军统治吉林西部及松原地区。；原东北军将领，九一八后投敌，曾任伪满热河省省长，后任伪满军政部大臣，协助日军镇压抗日力量，在吉林、松原、扶余地区活动并参与清乡扫荡。；原东北军将领，九一八后投敌，曾任伪满热河省省长，镇压抗日武装，协助日军进攻热河，后任伪满军政部大臣，为日本殖民统治效力。；原东北军将领，九一八事变后投敌，曾任伪满热河省省长，后任伪满军政部大臣，参与镇压抗日武装，在吉林、白山地区协助日军清剿抗联部队。；原东北军将领，九一八后投敌，曾任伪满热河省省长，参与镇压抗日武装，后任伪满军政部大臣，协助日军统治东北，包括吉林、白山、江源地区在内的伪满辖区均受其管辖影响。；原东北军将领，九一八事变后投敌，曾任伪满热河省省长，参与镇压抗日武装，后任伪满军政部大臣，为日军效力。；原东北军将领，九一八后投敌，曾任伪满热河省省长，镇压抗日武装，协助日军统治吉林、白山地区。；原东北军将领，九一八后投敌，在吉林地区参与镇压抗日武装，后任伪满高官，协助日军统治东北。；原东北军将领，九一八事变后投敌，任伪满热河省省长，镇压抗日武装，协助日军进攻热河。虽籍贯辽宁盖平，但长期在吉林、辽源一带活动，曾参与围剿辽源地区抗日游击队。；原东北军将领，九一八事变后投敌，曾任伪满热河省省长，后任伪满军政部大臣，积极协助日军镇压抗日武装，在辽源、东丰一带参与“讨伐”抗日义勇军。；原东北军将领，九一八后投敌，在辽源、西安（今辽源市东辽县一带）参与镇压抗日武装，协助日军建立伪满统治，后任伪满热河省省长，推行殖民政策。；原东北军将领，九一八后投敌，任伪满要职，镇压抗日力量，协助日军统治吉林地区。；原东北军将领，九一八后投敌，曾任伪满热河省省长，参与镇压抗日武装，后任伪满军政部大臣，在吉林、通化地区协助日军清剿抗联；原东北军将领，九一八后投敌，曾任伪满热河省省长，后任伪满军政部大臣，参与镇压抗日武装，在通化、集安一带协助日军清剿抗联部队。；原东北军将领，九一八事变后投敌，曾任伪满热河省省长，参与镇压抗日武装，协助日军统治吉林地区。；原东北军将领，九一八事变后投敌，曾任伪满热河省省长，参与镇压抗日武装，后任伪满军政部大臣，为日本侵略者效力。；原东北军将领，九一八事变后投敌，曾任伪满热河省省长，协助日军镇压抗日武装，后任伪满军政部大臣，参与伪满政权核心决策。；原东北军将领，九一八事变后投敌，曾任伪满热河省省长，参与镇压抗日义勇军，后任伪满军政部大臣，协助日军统治辽宁地区。；原洮辽镇守使，九一八后率先投敌，虽主要活动于热河，但其部队曾参与对辽宁东部抗日根据地的“围剿”。；原东北军将领，九一八后投敌，曾任伪满热河省省长，参与镇压抗日武装，后任伪满军政部大臣，在辽宁及本溪、桓仁地区协助日军清剿抗联部队。；原东北军将领，九一八后投敌，任伪满热河省省长，参与镇压抗日义勇军，协助日军进攻热河。；原奉系军阀，投日后在辽西及辽阳周边地区协助日军清剿抗日义勇军。；原东北军将领，九一八后投敌，曾任伪满热河省省长，参与镇压抗日义勇军，后任伪满军政部大臣，协助日军统治辽宁地区。；原东北军将领，九一八后投敌，曾任伪满热河省省长，参与镇压抗日武装，后任伪满军政部大臣，是辽宁地区重要汉奸头目。；原东北军将领，九一八事变后投敌，曾任伪满热河省省长，协助日军镇压抗日武装，后任伪满军政部大臣，参与伪满政权军事决策。；原东北军将领，九一八事变后投敌，曾任伪满热河省省长、伪满军政部大臣，在辽宁及鞍山地区协助日军镇压抗日力量，推行“治安肃正”。；原东北军将领，九一八事变后投敌，曾任伪满热河省省长，后调任伪满军政部大臣，在辽宁、鞍山等地协助日军清剿抗日武装。；原东北军将领，九一八后投敌，曾任伪满热河省省长，后调任伪满军政部大臣，参与镇压抗日武装，其势力曾涉及黑龙江东部地区。；原东北军将领，九一八后投敌，曾任伪满热河省省长，后调任伪满军政部大臣，参与镇压抗日武装，其活动范围涉及东北多地，包括双鸭山岭东地区所在的伪三江省一带；原东北军将领，九一八后投敌，任伪满热河省省长，协助日军镇压抗日武装，后任伪满军政部大臣，参与“讨伐”东北抗联。其活动范围涉及黑龙江部分地区（如齐齐哈尔周边）及伪满全境。；原东北军将领，1931年九一八事变后投敌，任伪满热河省省长，后任伪满军政部大臣，参与镇压抗日武装，协助日军统治黑龙江地区。；原东北军将领，1931年九一八事变后投敌，曾任伪满热河省省长，后任伪满军政部大臣，参与镇压抗日武装，其势力曾涉及黑龙江地区。；原东北军将领，1931年投敌，后任伪满热河省省长，参与镇压抗日武装，在黑龙江地区协助日军清剿抗联部队。；原东北军将领，九一八后投敌，曾任伪满热河省省长，后任伪满军政部大臣，在黑龙江及绥化地区协助日军清剿抗日武装，镇压民众反抗。；原东北军将领，九一八事变后投敌，曾任伪满热河省省长，后任伪满军政部大臣，协助日军镇压抗日力量。虽主要活动于热河，但原籍黑龙江绥化地区，曾参与对北满抗联的围剿。；原东北军将领，1931年九一八事变后投敌，曾任伪满热河省省长，后任伪满军政部大臣，参与镇压抗日武装，其活动范围涉及黑龙江地区，但非鹤岗南山籍贯，因史料记载其曾指挥伪军对北满抗联进行围剿。；原东北军将领，九一八后投敌，曾任伪满热河省省长，后调任伪满军政部大臣，在黑龙江地区协助日军镇压抗日武装。；原东北军将领，九一八后投敌，曾任伪满热河省省长，参与镇压抗日武装，其势力曾涉及黑河地区边境活动。；原洮辽镇守使，1931年叛国投日，在齐齐哈尔周边配合日军进攻，后任伪满要职，镇压抗日武装。；原奉系军阀，后投敌，在黑龙江、齐齐哈尔一带参与镇压抗日武装，为日军效力。；原东北军将领，1931年投敌，后任伪满要职，协助日军镇压抗日力量，其势力曾涉及黑龙江地区；原东北军将领，九一八事变后投敌，曾任伪满热河省省长，后任伪满军政部大臣，参与镇压抗日武装，在黑龙江地区协助日军维持殖民统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cf1966bbca13436da16627f973a5cf2e','c0860f9060d74dfba1674157f4596712',1931,'伪满吉林警备军司令官','原吉林陆军军官，投日后任伪满吉林警备军司令，协助日军围剿东北抗日联军，在吉林、四平、伊通一带多次参与“讨伐”行动。；原吉林陆军将领，投日后负责吉林地区治安，多次围剿杨靖宇等抗联部队。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7bf8a5fd13824a63b1291c73040f4184','2acf7a5b9b5341578e1066b27394b2eb',1932,'伪满吉林省省长','原东北军将领，投日后任伪满吉林省省长，在吉林地区推行日伪统治，强征劳工，镇压抗日活动。；原吉林省警务处长，投日后任伪吉林省省长，管辖包括松原在内的吉林西部，推行日伪殖民政策；原东北军将领，投日后任伪满吉林省省长，推行日伪殖民政策，强征劳工，镇压吉林地区抗日活动。；原吉林省政府官员，投敌后任伪满吉林省省长，推行日伪殖民政策，镇压吉林地区抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('482b81064e2d485da374833d2cb06712','350822a1078340679fd657c16a793993',1932,'伪满吉林省警务厅厅长','原吉林警察头目，投日后任伪满吉林省警务厅厅长，组织警察特务，在四平、伊通等地搜捕抗日志士，破坏地下组织。；汉奸警察头目，在吉林、松原一带组织伪警察队，配合日军搜捕抗日地下工作者，制造多起惨案。；在吉林、辽源、东丰地区任伪警务要职，组织伪警察和特务，搜捕抗日地下工作者，破坏抗日组织，制造多起惨案。；原吉林警察头目，投日后任伪吉林省警务厅长，组织警察特务在通化、辉南地区搜捕抗日分子，破坏地下组织','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a040f39245a646ff9cec8bba4c6b35a1','589ab27feed347c6944e6c001125dc02',1932,'伪满四平街市市长','原地方官僚，投日后任伪满四平街市（今四平市）市长，推行日伪奴化教育，协助日军征粮征税，镇压当地反抗。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7be516ccef1b4bbda68ad721a65ee1fc','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满立法院院长','原奉系法律人士，投日后任伪满立法院院长，参与制定伪满法律，为日本殖民统治提供法理依据，其活动涉及吉林地区。；原奉系法律顾问，投日后参与策划伪满政权，在吉林、四平地区协助建立伪司法体系，迫害抗日志士。；原吉林律师，投日后参与制定伪满法律，为日本殖民统治提供法理依据，其活动涉及吉林全省。；原奉系官员，投日后参与策划伪满建国，虽主要活动于新京，但其势力涉及吉林全省，支持在辽源、东丰等地建立伪政权。；原奉系律师，九一八后投日，参与起草伪满洲国《建国宣言》，任伪满立法院院长，曾为日军在辽宁的殖民统治提供法律支持。；原奉系法律人士，投日后任伪满立法院院长，为日伪统治提供法律依据，其立法影响安东省（含丹东、振安）的统治。；曾任伪奉天市市长，后任伪满立法院院长，积极参与伪满立法，为日本殖民统治提供法律依据。；原律师，九一八后投敌，曾任伪奉天市市长、伪满立法院院长，积极为日伪立法服务。；原奉系法律顾问，九一八后投敌，参与起草伪满建国文件，任伪立法院院长，积极为伪满政权提供法律依据。；原奉系政客，九一八后投敌，参与伪满政权建立，虽主要活动于长春，但曾参与对黑龙江地区抗日活动的镇压策划。；原奉系政客，九一八后积极投靠日本，参与策划伪满建国，虽主要任职于新京，但曾多次到黑龙江绥化地区推行殖民政策，协助日军“治安肃正”。；曾任伪满要职，参与制定殖民法律，支持日本对黑龙江的统治。；原奉系政客，参与伪满建国，在黑龙江地区推行殖民政策，协助日本关东军统治；原奉系法律顾问，后投靠日本，任伪满立法院院长，参与制定伪满法律，为日本侵略合法化服务。','伪政权最高层/元首级','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('74890b81612c4ec1aa4ebe3f262cb4db','87b0aba74b9b4c5f8a515bd9270d23b4',1931,'伪满参议府议长','原奉系政客，投日后任伪满参议府议长，在吉林、四平一带鼓吹“日满亲善”，协助日军稳定殖民秩序。；清末举人，曾任奉天省议会议长，九一八后投靠日本，参与策划伪满洲国成立，任伪满参议府议长，为日伪统治出谋划策。；原奉系文人，投日后任伪满参议府议长，参与制定殖民政策，支持对安东地区的经济掠夺和思想控制。；原奉系政客，九一八后组织“辽宁地方维持会”，投靠日军，后任伪满参议府议长，为日本侵略张目。；原奉系元老，投日后任伪满参议府议长，支持日军在辽西的军事行动，对南票矿区实行奴化统治。；奉系旧官僚，投日后任伪满高官，为日本侵略政策服务，影响黑龙江地区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2bb56bb13e894d4a80f4f76bfa2e810e','84779a454ec74ec19985a1b53e006685',1931,'伪满监察院院长','原奉系官员，投日后任伪满监察院院长，参与伪满政权建设，在吉林地区推行“协和会”活动，麻痹民众抗日意识。；在吉林地区协助日军建立情报网，迫害抗日爱国人士。；原奉系政客，投日后任伪满高官，曾参与策划对辽西地区（含葫芦岛、南票）的“治安肃正”行动。；原奉系政客，九一八后投敌，任伪满监察院院长，为日本监督伪满官员，维护殖民秩序。；原奉系外交官，投日后任伪满监察院院长，曾多次到辽宁各地（包括铁岭、开原）督导伪政权建设，镇压抗日分子。；原奉系外交官，投日后任伪满监察院院长，曾参与“日满议定书”签订，协助日本控制辽宁经济，对铁岭、昌图地区资源掠夺负有责任。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('75f18a80b516494dbdf3181723713992','77a789268c6f47b4a617cdb9e41180bd',1931,'伪满国务总理大臣','原东北军将领，九一八事变后投敌，曾任伪满军政部总长，后任伪满国务总理，全面协助日本统治东北，其势力范围涵盖吉林、四平、伊通等地。；原东北军将领，投日后任伪满总理，虽主要活动于新京，但其政策覆盖吉林、四平、梨树，支持日军殖民统治。；原东北军将领，九一八后投敌，虽为伪满总理，但曾长期控制吉林地区军政，支持日军镇压抗日武装。；原东北军将领，全面投日后总揽伪满政务，对吉林、辽源地区抗日活动进行残酷镇压。；原东北军将领，九一八后投敌，任伪满最高行政长官，其政策覆盖安东省（含丹东、振安），支持日军对辽东的殖民统治。；原奉系将领，后投靠日本，任伪满最高行政长官，全面配合日本侵略政策，对辽宁地区抗日力量进行镇压。；虽为伪满中央高官，但其势力范围覆盖辽宁，曾多次到本溪、南芬地区视察“治安肃正”，推动建立保甲制度，强化对当地民众的统治。；原奉系军阀，后任伪满最高行政长官，虽不直接驻本溪，但作为伪满中央头目，其政策直接导致本溪、溪湖地区抗日力量遭受镇压。；原奉系将领，九一八后投日，历任伪满军政部总长、国务总理大臣，是伪满最高汉奸之一。；虽非盘山籍，但作为伪满最高汉奸之一，其势力覆盖辽宁全省，包括盘锦地区，支持日军对当地抗日力量的镇压。；原东北军将领，九一八后投敌，任伪满最高行政长官，全面协助日本统治东北，包括辽宁葫芦岛地区。；原奉系将领，投日后任伪满总理，全面推行殖民政策，其管辖范围涵盖辽西地区，支持对南票资源的掠夺。；原奉系军阀，九一八后投敌，虽为伪满中央高官，但其势力及政策影响辽宁全境，包括葫芦岛连山地区，支持日军“讨伐”抗日力量。；原奉系将领，后投敌，任伪满最高行政长官，全面配合日本侵略政策。；原奉系将领，九一八后投敌，虽主要活动于伪满中央，但其势力范围覆盖辽宁全省，包括铁岭、开原，支持日军对当地抗日力量的镇压。；原奉系军阀，九一八后投敌，任伪满军政部总长、国务总理大臣，是伪满最高汉奸之一，其势力范围覆盖辽宁全省，包括铁岭、昌图地区。；原奉系军阀，九一八后投敌，任伪满最高行政长官，虽非直接活动于铁岭银州，但其政策覆盖该地区，支持日军对辽宁的殖民统治。；作为伪满最高汉奸之一，虽常驻新京，但其政策影响辽宁锦州地区，支持日伪军对凌海等地的“治安肃正”。；原奉系军阀，九一八后投日，虽为伪满中央高官，但曾在辽宁鞍山、岫岩地区部署伪军镇压抗日力量，其势力影响该地区。；原奉系军阀，九一八后投敌，任伪满国务总理大臣，虽主要活动于新京（长春），但其影响覆盖辽宁鞍山地区，支持日本对鞍山钢铁资源的全面控制。；原东北军将领，投敌后任伪满最高行政长官，其政策覆盖辽宁鞍山铁西地区，支持日军经济掠夺。；原奉系军阀，九一八后投敌，任伪满最高行政长官，其伪政权统治范围覆盖包括双鸭山岭东在内的整个东北，推行“日满亲善”政策，协助日军镇压抗日力量；原奉系将领，九一八后投敌，虽主要活动于新京（长春），但其伪满政权对黑龙江、大庆地区实施全面殖民统治，负有最高责任。；原东北军将领，九一八后投敌，虽为伪满中央高官，但其起家于黑龙江，曾参与对肇源地区抗日武装的围剿决策。；原东北军政要员，九一八后投敌，虽名义上在长春，但其伪政权政策直接管辖黑龙江、牡丹江、东宁地区，支持日军对东宁要塞的建设和对抗联的围剿。；原奉系军阀，九一八后投敌，任伪满最高行政长官，虽主要活动于新京，但其政策直接覆盖黑龙江绥化北林地区，支持日军殖民统治，是最大汉奸之一。；原东北军将领，九一八后投敌，虽为伪满最高汉奸之一，但早年曾活动于黑龙江地区，其伪政权政策直接影响到绥化、肇东，支持日军对北满的“讨伐”。；原东北军将领，九一八后投敌，曾任伪满黑龙江省长，后升任伪满国务总理，虽主要活动于新京，但曾多次巡视黑河、五大连池地区，督导日伪统治。；虽为伪满中央高官，但曾多次视察黑河、逊克地区，推动“治安肃正”计划，间接指挥当地伪军警围剿抗联。；原奉系将领，九一八后投敌，曾任伪满黑龙江省长（1932年），后升任伪满国务总理，全面协助日本统治东北，包括齐齐哈尔、泰来地区。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0774b938d7204a17a4a5363cc985e62c','caae33d173854bf0a1b2b4f0db4f585a',1932,'伪满吉林省财政厅厅长','原吉林地方官员，投日后任伪满吉林省财政厅厅长，负责为日军搜刮吉林、四平、伊通地区的粮食和物资，支持侵略战争。；原吉林地方官僚，投敌后负责伪满吉林省财政，为日军搜刮民财，强征捐税，支持侵华战争。；在吉林地区任职期间，为日军筹措军费，强征粮税，掠夺东丰、辽源一带资源，间接支持日军侵华战争。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2ba414e69d4b42efaa18a3d6545b4aea','b21d5a4d224a4173bdb0f2b366c98d70',1932,'伪满伊通县县长','原伊通地方士绅，投日后任伪满伊通县县长，推行保甲制度，组织汉奸武装，协助日军在伊通地区“清乡”，迫害抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a6780c9d2d984da49589eaa75fbe5c19','d5f8717058654c37a56ff29410e99525',1941,'伪满四平省省长','原伪满地方官员，后任伪满四平省省长，管辖四平、伊通等县，积极推行日伪“粮谷出荷”政策，强征农民粮食，镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dc63831109da4a1d9b6290ac3723764b','eb688993f9ee49a7bbacda2253de406a',1941,'伪满四平省警务厅厅长','原伪满警察，投日后任四平省警务厅厅长，在四平、伊通地区建立情报网，多次破坏抗日地下组织，逮捕爱国人士。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fa5c9d7561854878adb5475ae7ab1804','3cd55e29febc489d9f9a7f2f88db31bb',1932,'伪满伊通县警务科科长','原伊通县警察，投日后任伪满伊通县警务科科长，亲自带队搜捕抗日联军联络员，在伊通山区多次参与“讨伐”行动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f64027e7a1cc43d48be1e16b604b36cf','257bc97b2b934e538c388d33e09f39d4',1932,'伪满吉林省公署参事','原吉林省政府官员，投日后任伪满吉林省公署参事，参与策划对吉林、四平地区抗日武装的围剿，并协助日军建立“集团部落”。；参与策划吉林地区“治安肃正”，协助日军推行“集团部落”政策，导致大量百姓流离失所。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0458b6cd5e4040d0b7d2bba53466ac50','41502657c6b84465aa2ff94e620ed234',1932,'伪满吉林省实业厅厅长','原吉林实业界人士，投日后任伪满吉林省实业厅厅长，在四平、伊通等地强占土地，开办日伪企业，掠夺当地资源。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ffc41b856d044688aa3c50ce4a11b21b','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满黑龙江省省长（曾活动于吉林）','原东北军将领，投日后历任伪满要职，曾在吉林、四平地区参与“治安工作”，协助日军镇压抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a98bed75c9c34b00aa54bd5677d2252f','875c22d678e24c21834a32caae69933c',1931,'伪满财政部总长、宫内府大臣','原吉林副都统，九一八事变时在吉林投降日军，建立伪吉林省政权，参与策划伪满洲国成立，其势力范围涉及吉林、四平地区。；原吉林省政府委员，九一八后主动投敌，参与策划吉林独立，任伪满财政总长，为日本掠夺东北资源服务。；原吉林副司令长官公署参谋长，1931年叛变，引日军占领吉林，建立伪吉林省政权，是吉林地区首要汉奸。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('87af4136dc844ca48ee92d00a5b7f120','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满第一军管区司令官、伪满治安部大臣','原东北军旅长，投日后在吉林、四平一带围剿抗日游击队，后任伪满军事要职，屠杀抗日军民。；原东北军旅长，投日后任伪满第一军管区司令，管辖包括吉林、松原在内的中西部区域，多次率伪军“讨伐”抗日游击队。；原东北军旅长，投日后任伪满第一军管区司令官，驻防吉林地区，多次率伪军围剿抗日游击队，后升任伪满治安部大臣，对吉林、松原、扶余一带抗日武装进行残酷镇压。；原东北军旅长，1932年投敌，任伪满第一军管区司令官，负责吉林东南部（含今白山、江源一带）的“讨伐”行动，屠杀抗日军民，后升任伪满治安部大臣。；原东北军旅长，投日后任伪满第一军管区司令官，驻防吉林、辽源地区，多次率伪军“讨伐”抗日义勇军和抗联部队，屠杀抗日军民。；原东北军旅长，投日后任伪满第一军管区司令官，管辖吉林、通化地区，多次率伪军围攻杨靖宇部抗联，制造多起惨案。；原东北军旅长，投日后任伪满第一军管区司令官，负责吉林、通化一带“讨伐”东北抗日联军，制造多起屠杀事件；原东北军旅长，投日后任伪满第一军管区司令官，管辖吉林、通化地区，多次指挥伪军围剿杨靖宇领导的东北抗联第一路军。；原东北军旅长，1932年投敌，任伪满第一军管区司令官，负责辽东包括丹东、振安一带的“讨伐”抗日义勇军，后升任伪满治安部大臣。；原东北军旅长，投日后任伪满第一军管区司令官，管辖辽宁东部地区，多次指挥伪军对抗联杨靖宇部进行围剿，活动范围涉及本溪、桓仁一带。；原东北军旅长，叛变后任伪满第一军管区司令官，管辖辽宁地区，多次派兵围剿本溪、溪湖地区的抗日游击队和抗联第一军。；原东北军旅长，1932年投敌，任伪满第一军管区司令官，在辽宁、铁岭、昌图一带围剿抗日义勇军，后升任伪满治安部大臣。；原东北军旅长，1931年率部投敌，任伪满第一军管区司令官，负责辽宁地区“讨伐”抗日义勇军，后升任伪满治安部大臣，推行殖民统治。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5546bc387b614bbeaef7732479a01653','c0860f9060d74dfba1674157f4596712',1931,'伪满吉林警备司令官、伪满第2军管区司令','原吉林陆军混成旅旅长，投日后驻防吉林、四平，多次率伪军进攻抗日根据地，逮捕杀害抗联人员。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('409803a3b4364821878a0759ff3e92fe','2acf7a5b9b5341578e1066b27394b2eb',1931,'伪满吉林省省长、伪满民生部大臣','原东北军将领，投日后在吉林地区推行奴化教育，协助日军“讨伐”抗联，镇压民众反抗。；原吉林省政府官员，投日后推行奴化教育，协助日军在四平铁西地区建立伪政权。；原东北军将领，投日后任伪吉林省长，管辖包括白山、长白地区，配合日军“讨伐”抗联，强征劳工。；原吉林陆军军官，投日后历任伪满吉林省警务厅长、省长，在吉林、辽源地区推行保甲制度，强征劳工，协助日军清剿抗联。；原东北军将领，投日后任伪满吉林省省长，管辖吉林、通化等地，推行殖民政策，配合日军镇压抗日力量。；原吉林陆军军官，投日后任伪吉林省省长，在吉林、辉南等地推行殖民统治，强征劳工，配合日军围剿抗联；原吉林省政府参议，投日后任伪吉林省长，在龙潭地区推行保甲制度，强征劳工，协助日军经济掠夺。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c165b327082a424b9482b182bb831f17','589ab27feed347c6944e6c001125dc02',1932,'伪满四平街市长（四平市）','伪满时期四平地区行政官员，协助日军征粮、抓劳工，镇压当地抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('349deb68dedc4c79bcbe5183a90634ca','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满立法院院长、伪满司法部大臣','原奉系法律人士，投日后参与伪满立法，其活动涉及吉林、四平地区，为殖民统治提供法律依据。；参与策划伪满建国，在吉林地区推行殖民法律，迫害抗日人士。；原奉系法律顾问，投日后参与伪满立法，在吉林地区推行奴化教育，协助日本殖民统治。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('916567b00c9043f180d8acda9366c175','3b74f508628f475a8777ffb7e38a48a0',1931,'伪满吉林省财政厅长、伪满经济部大臣','原吉林商人，投日后在吉林、四平地区为日军搜刮物资，控制经济命脉，剥削百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dde626b624a044f49f761ed2804308ef','9fdf72cacfcf4c72a1c4a279be3c42c2',1932,'伪满四平地区保安团长','在双辽、四平一带组织伪保安队，配合日军扫荡，杀害抗联战士及无辜群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e92c6d7fbea24847afd4837ce6c5c4b4','c0860f9060d74dfba1674157f4596712',1931,'伪满吉林警备司令官','原吉林陆军军官，投日后任伪吉林警备司令，在四平、梨树一带围剿抗日义勇军和抗联部队。；原吉林陆军军官，投日后任伪满吉林警备司令官，协助日军维持吉林地区殖民统治，镇压抗日活动。；协助日军清剿抗联，在吉林、长春周边设立“集团部落”，制造无人区。；原吉林军将领，投敌后任伪满吉林警备司令，曾率伪军进入黑龙江地区镇压抗日武装。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('24b8a8ca1eb64e4f9f2d0d317c8c01ce','3a9e402192aa460fb51a927d874bb93e',1932,'伪满梨树县县长','梨树本地人，投靠日军后任伪县长，强制推行“归屯并户”，配合日军抓捕抗日人员，征收粮税。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dddce129d83e4c77b71b812fc5ab407e','3cd55e29febc489d9f9a7f2f88db31bb',1937,'伪满四平街市市长','四平街（今四平市）伪市长，积极推行日伪“国策”，组织劳工为日军修建军事设施，镇压反满抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('476b49811e2143ae8a1021e9a64607a6','350822a1078340679fd657c16a793993',1932,'伪满吉林省省长','原吉林省政府官员，投日后任伪吉林省长，管辖四平、梨树等地，推行“粮谷出荷”和“勤劳奉仕”制度。；原吉林省政府官员，投日后历任伪吉林省长，推行日伪殖民政策，镇压抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bcfef0a72f114b28820565673b9b2e51','3eb966fdcf364389b5302ef8a669f7ac',1941,'伪满四平省省长','伪满四平省（辖四平、梨树等县）省长，配合日军“讨伐”抗联，强征民夫修筑战备工事。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ece91073bd2b4a658e4ff008cb82c08b','21853206ad2b417598d1af0b4b3a4782',1932,'伪满梨树县警务科长','梨树县伪警务负责人，直接指挥警察特务搜捕地下抗日组织，多次参与屠杀抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c650d6286f84449f9235cb37e4fe880e','79b17193512846a1a5bde9f5df22c926',1931,'伪满参议府议长','原奉天省长，投日后参与伪满高层决策，对吉林、四平地区伪政权建设有直接影响。；原吉林督军署参谋长，投日后任伪满参议府议长，参与制定殖民政策，对吉林地区统治有重要影响。；参与伪满政权决策，支持日军在吉林、辽源地区的殖民统治。；原奉天省长，投日后任伪满参议府议长，参与制定对黑龙江地区的“治安肃正”政策，间接导致大庆周边抗联部队遭受重大损失。；原奉天省长，投敌后任伪满参议府议长，虽主要任职于新京，但曾参与策划对黑龙江地区抗联的“围剿”方案，涉及绥化、肇东一带。；参与伪满高层决策，支持对鹤岗等地的资源掠夺。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c5d99c1128da4642a2f05b677416feed','875c22d678e24c21834a32caae69933c',1931,'伪满洲国财政部总长、吉林省长','九一八事变后率先投敌，以吉林省军政长官身份迎接日军，参与策划成立伪满洲国，是东北早期核心汉奸之一，其伪政权管辖范围覆盖四平地区。；九一八事变后率先投敌，以吉林省军政长官身份迎接日军占领吉林，参与策划成立伪满洲国，长期担任伪满要职，是东北早期附逆的核心人物之一。；九一八事变后率先投敌，组织伪吉林省政权，协助日军侵占吉林各地，为伪满核心汉奸之一。；东北伪政权头目，属全国性汉奸。；九一八事变后投敌，参与建立伪满，负责财政与地方政务。；原东北军吉林副司令长官，九一八事变后率先投敌，引日军进入吉林，后任伪满洲国财政总长、宫内府大臣，积极参与伪满殖民政权建设。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('321eaff934de44b189a9191c0aea7caa','77a789268c6f47b4a617cdb9e41180bd',1931,'伪满洲国参议府议长、国务总理大臣','原东北军将领，九一八后投敌，历任伪满要职，最终任伪国务总理大臣，全面推行日本殖民政策，其政权体系延伸至四平、铁东一带。；原东北军将领，九一八后投敌，历任伪满军政要职，后任伪满国务总理大臣，全面推行日本殖民统治政策，是伪满政权最高层汉奸之一。；原东北军将领，九一八后投敌，历任伪满要职，参与签署卖国条约，推行日伪统治政策。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('074394e99ef540418e8fa8933f724372','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满军政部大臣、伪奉天警备司令','原东北军东边道镇守使，1931年投敌，率部配合日军镇压东北抗日武装，其伪军活动范围包括四平及周边地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f9cfce3f8ad24765abb3fdd9924c66cd','c0860f9060d74dfba1674157f4596712',1931,'伪满吉林省警备司令、伪满军政部大臣','原东北军延吉镇守使，随熙洽投敌，长期在吉林省内指挥伪军围剿抗日力量，四平地区在其伪警备管辖范围内。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('384f3d88a41d4637ac29598a3ade3fbd','af99649b3f3a4c5382ec79666bf2647d',1941,'伪满四平省省长','伪满设立四平省后任省长，直接负责四平及铁东地区的殖民行政，推行粮谷出荷、劳工征发等政策，配合日军经济掠夺。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('39807823ae63457980295b7cf6510cda','eb688993f9ee49a7bbacda2253de406a',1930,'伪满四平省次长、伪满吉林省次长','长期在伪满地方政权任职，曾任四平省次长，实际掌控四平地区行政，推行日本殖民法令，压榨当地民众。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('41747589950d44d79db2d63908dfb9f0','d2b7a71572c34ce0943d2a891b842d96',1930,'伪满四平市市长','任伪四平市市长期间，配合日军在铁东等城区实施保甲连坐、物资统制，协助征发劳工，是四平城区直接附逆者。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('db1f02bbeba84e8c9f08001d656aded3','612f81ddddda4b5e9bc51c07125b4977',1940,'伪满四平省警务厅长','掌管四平省伪警察系统，在铁东等地搜捕抗日人员，镇压民众反抗，推行治安肃正政策。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c534f8dfedf741d98ca46b3658662a87','3cd55e29febc489d9f9a7f2f88db31bb',1931,'伪满四平街维持会会长','九一八后四平街成立维持会，刘德权任会长，为日军筹粮筹款、维持地方秩序，协助日军接管四平及铁东地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('350696b5824a4634bfc8dc13479b9cf0','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洮辽镇守使、伪军头目','原东北军洮辽镇守使，1931年投敌，率伪军进攻黑龙江，其部队活动于吉林西部及四平周边，配合日军镇压抗日武装。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8b73d5c7e2cd42e6901182ed15a2fd56','c864056eff7343cc9fa5a6209818cc19',1930,'伪满吉林省长、伪满宫内府大臣','清室后裔，投靠日本，曾任伪吉林省长，参与殖民统治，其管辖范围包括四平地区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4444b97c352d44719e782f9be1ab45e5','3eb966fdcf364389b5302ef8a669f7ac',1930,'伪满吉林省长、伪满司法部大臣','长期在伪满吉林省任职，推行日本殖民政策，参与镇压抗日活动，四平地区在其省长任内受其管辖。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('632145e6792b490ba67e94d74958db88','3954cf6c52e9432eae4f94e815aa72ef',1930,'伪满经济部大臣、伪满吉林省长','曾任伪吉林省长，配合日本经济掠夺，推行物资统制，四平地区的粮食、煤炭等资源被其政策搜刮。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('51bf4489c8be461e8f6146c21b8be267','448cf19f40334f31b9f5d71d601929ab',1940,'伪满四平省民生厅长','负责四平省教育、文化、民生等殖民事务，推行奴化教育，在铁东等地学校强制日语教学，毒化民众思想。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('899479ca282345a098a46ea3f0abdd8e','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满热河省省长、伪满第四军管区司令官','原东北军将领，九一八后投敌，在四平、铁西一带协助日军镇压抗日武装，推行殖民统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('64bdaf00be9e49f0b380f0f0e468f32a','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满治安部大臣、伪满第一军管区司令官','原东北军旅长，投日后在四平、铁西地区参与“讨伐”抗日义勇军，屠杀抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b74abbc77a4c4ee3919eb2d352b311c0','a984ebfabbf64a5b8e1dfef2d68daa53',1931,'伪满吉林陆军中将、伪满军事咨议官',NULL,'无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5cc56846414e49fd947aecb493bc6ff7','350822a1078340679fd657c16a793993',1931,'伪满吉林省警务厅长','在四平、铁西地区组织伪警察，抓捕抗日地下工作者，破坏抗联交通线。；满族汉奸，任伪吉林省警务厅长，组织警察特务镇压松原、扶余等地抗日活动；原吉林警察头目，投日后任伪满吉林省警务厅长，组织伪警察和特务在吉林、松原、扶余地区搜捕抗日志士，破坏地下抗日组织，制造多起惨案。；原吉林警察系统官员，投日后任伪满吉林省警务厅长，组织伪警察协助日军搜捕抗日志士。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a94a5cae7c7c4f698fd805302b2d9d6b','41502657c6b84465aa2ff94e620ed234',1931,'伪满吉林省财政厅长','为日军筹措军费，强征四平铁西地区粮食物资，支持侵华战争。；为日军筹措军费，在昌邑强征捐税，掠夺粮食资源，支持侵华战争。；原吉林省官员，投日后负责伪吉林省财政，在松原地区强征捐税，搜刮民财；原吉林省财政官员，投日后任伪满吉林省财政厅长，在吉林、松原、扶余地区征收苛捐杂税，为日军筹措军费，搜刮民财。；负责伪满吉林财政，为日军战争筹款，强征苛捐杂税，压榨吉林、松原地区百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bef4cbbe33dd466fb4134e8f56baff86','caae33d173854bf0a1b2b4f0db4f585a',1941,'伪满四平省省长','伪满四平省（辖今四平、铁西一带）首任省长，推行“粮谷出荷”政策，导致当地民众饥荒。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0d9ad8e2fd4441e3b50eb15d5ae39fc3','eb688993f9ee49a7bbacda2253de406a',1941,'伪满四平省次长','协助荣厚管理四平省，强制征召劳工，镇压反抗民众。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('070e03e9b7104d2bbcb202189bc2a0a3','9d25e1d3d8e543ee84de82f230352248',1937,'伪满四平市市长','在四平市（含铁西区）推行日伪法令，组织“协和会”，迫害爱国人士。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('17191efde17c476290a1f1f5abe01842','21853206ad2b417598d1af0b4b3a4782',1932,'伪满四平地区保安团长','率伪军多次袭击抗联小分队，在铁西区设立据点，杀害抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d95d8a98998d4baebdc40bbe04d444e1','3b74f508628f475a8777ffb7e38a48a0',1931,'伪满经济部大臣','原吉林商人，投日后控制四平铁西地区工商业，为日军掠夺资源。；原奉天商会会长，投日后任伪满经济部大臣，在辽宁推行经济统制，强征铁岭、昌图粮食和矿产，支持日本侵华战争。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3e8c67f98234457690b01caaccb02eb1','9fdf72cacfcf4c72a1c4a279be3c42c2',1941,'伪满四平省警务厅长','在四平铁西地区建立特务网络，抓捕抗联联络员，刑讯逼供。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('08d5422a519c4f79951ea2e71a843740','6efa2b05428f4ce7bca190966f945873',1932,'伪满和龙县县长','任伪和龙县县长期间，积极推行日伪殖民政策，强征劳工，镇压抗日军民，协助日军搜捕抗联人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('65f6e0649c4d4ef4ac9874b0bb50d80d','558f4182cff0432494b6678d2cdad70a',1933,'伪满延吉县警务科科长','在延吉地区组织警察特务，破坏抗日地下组织，多次参与围剿东北抗日联军，残害抗日志士。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7bb28647ac31410487dd505b3cd12999','31811f4e9e174971aaa99b16edcdaf2d',1935,'伪满和龙县协和会会长','利用协和会组织，向当地朝鲜族和汉族民众灌输奴化思想，告密抗日分子，协助日军建立“集团部落”。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f4ace0d8024a48fb8bc20cb115879efa','a3b8bf7f477a4aa7b8df146ccba20d14',1936,'伪满延边地区警备队队长','率警备队多次袭击抗联游击队，烧毁村庄，屠杀无辜百姓，并参与“讨伐”长白山区的抗联部队。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8e2f2d05919e42d29b7664635fef1ec3','3b69971403194ddf951aeb6d1885666e',1937,'伪满和龙县警察署署长','亲自审讯和拷打被捕的抗联战士及地下党员，提供情报导致多处秘密联络点被破坏。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8ecfa2a8550c41e6a2bdd1265f391827','1e3574205eaf4248bee1b3c27d18e551',1938,'伪满延吉县自卫团团长','组织地方自卫团，配合日军封锁山区，搜查抗日物资，抓捕为抗联提供粮食的农民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dca33af385c94c57878e64000a72b5c1','e15c702f049a4ef4b0666e2e5b3ea2d6',1939,'伪满和龙县“讨伐队”副队长','参与多次对和龙、安图一带抗联密营的突袭，杀害抗联伤员，并掠夺群众财物。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6a6e89f9ce7e4a72ab6ee48df29602a5','a07f52084fc6406a9d50e895a343e40a',1940,'伪满延边地区宪兵队翻译','为日军宪兵队充当翻译，参与审讯和诱降抗联人员，帮助日军识别和抓捕朝鲜族抗日志士。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4c92702b474d4ab7a3c0a2d6d5800c5f','e620294791874f81929883c1f18fda81',1941,'伪满和龙县“思想矫正院”院长','管理关押抗日嫌疑人的矫正院，实施酷刑和强制劳动，造成多名被关押者死亡。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0a9240cb2fef495aa1150ff4dceb33ac','20d6e41594d94afc871d2f44cee85f73',1942,'伪满延吉县“协和义勇奉公队”队长','组织青年队为日军搜集情报，破坏抗联地下交通线，并参与强征当地劳工赴东北边境军事工程。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3604f2d85f8e4a46abbe10e799688465','875c22d678e24c21834a32caae69933c',1931,'伪满洲国财政部总长、吉林省伪省长','九一八事变后投靠日本，促成吉林地区迅速沦陷，积极推行伪满洲国殖民政策，镇压抗日力量。；九一八事变后投靠日本，协助日军占领吉林，参与建立伪满洲国，任伪吉林省长期间推行殖民统治，镇压抗日力量。；九一八事变后投降日军，协助建立伪满洲国，任吉林省伪省长，镇压抗日力量，推行奴化政策。；九一八事变后投敌，出卖吉林军政，协助日军占领吉林，后任伪吉林省长，推行殖民统治；九一八事变后叛国投敌，主动迎接日军占领吉林，协助建立伪吉林省政权，为日军提供财政和行政支持。；九一八事变后率先投敌，出卖吉林军政，协助日军占领吉林，后任伪吉林省长，推行殖民统治；九一八事变后投降日军，协助建立伪满洲国，任伪吉林省长，推行殖民统治，镇压抗日力量。；九一八事变后率先投敌，出卖吉林军政大权，协助日军占领吉林，后任伪满要职，推行殖民统治。；九一八事变后率先投敌，出卖吉林军政，协助日军占领吉林，后任伪吉林省长，推行殖民统治。；九一八事变后投靠日本，出卖吉林军政大权，协助日军占领吉林，后任伪满要职，推行殖民统治。；九一八事变后投靠日本，出卖吉林军政，协助日军占领吉林，后任伪吉林省长，推行殖民统治。；九一八事变后投降日军，协助建立伪满洲国，任吉林省伪省长，镇压抗日力量，推行殖民统治。；九一八事变后率先投敌，出卖吉林军政，协助日军占领吉林，后任伪满要职，推行殖民统治。；九一八事变后叛国投敌，协助日军占领吉林，出任伪吉林省长官，推行殖民统治，镇压抗日力量。；九一八事变后投靠日本，协助建立伪满洲国，任伪吉林省长官，镇压抗日力量，推行殖民统治。；九一八事变后投敌，出卖吉林军政，协助日军占领吉林，后任伪吉林省长，推行殖民统治。；九一八事变后叛国投敌，主动迎接日军占领吉林，协助建立伪满洲国，任伪吉林省长期间残酷镇压抗日力量，推行殖民统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('953b40302f1849098b7250ebe5908e2b','77a789268c6f47b4a617cdb9e41180bd',1931,'伪满洲国国务总理大臣（曾任吉林地区伪职）','原东北军将领，后投敌，长期担任伪满最高行政职务，协助日本统治东北，包括吉林、延边地区。；原东北军将领，后投敌，历任伪参议府议长、军政部总长、国务总理，在吉林、延边等地协助日军“讨伐”抗日武装。；原东北军将领，投日后任伪满要职，参与签订卖国条约，协助日本统治东北；原东北军将领，投日后成为伪满最高行政首脑，参与签订卖国条约，镇压抗日力量。；原东北军将领，后投敌，历任伪参议府议长、军政部总长、国务总理，全面配合日本侵略政策。；原东北军将领，叛变后投靠日本，历任伪参议府议长、军政部总长、国务总理，在长春（伪新京）主持伪满政权，协助日本掠夺东北资源。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('37b6f009d61140a8b8de67d8130ec344','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满洲国军政部大臣、伪奉天省省长（曾涉吉林）','原东北军旅长，叛变后参与围剿抗日义勇军，在吉林、延边等地协助日军维持治安。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6100b71fd52d4998baad28a4e682e6d2','c864056eff7343cc9fa5a6209818cc19',1932,'伪满洲国新京（长春）特别市市长、吉林地区伪警务要职','清皇室后裔，投靠日本，在吉林、长春等地推行奴化统治，镇压反满抗日活动。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b1e55b7a3578426289232ea33778a2d7','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满洲国立法院院长（曾参与吉林地区司法镇压）','原奉系法律人士，投日后为伪满立法，协助日本在吉林、延边地区建立殖民法律秩序。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d8979b7a7abf4c60826898bafcb076ee','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满洲国经济部大臣、伪吉林省财政顾问','原吉林商人，投靠日本，负责为日军和伪满搜刮吉林、延边地区资源，压榨民众。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3cc11284fa7048ffbf75b03c45453e6a','a984ebfabbf64a5b8e1dfef2d68daa53',1932,'伪满洲国吉林地区警备军司令（后投敌）','原东北军将领，曾抗日后叛变，在吉林、延边地区率伪军围剿抗联部队。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d6efc9cd0d1b4496940825262150b88c','2acf7a5b9b5341578e1066b27394b2eb',1931,'伪满洲国吉林地区治安维持会会长','原吉林士绅，组织地方伪政权，协助日军清乡，迫害抗日家属。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('93c9badded9e40e69f896ce118775d1e','b21d5a4d224a4173bdb0f2b366c98d70',1932,'伪吉林省延吉县（今延边）伪县长','在延边地区推行“集团部落”政策，强迫民众归屯并户，切断抗联与百姓联系。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2b3944cd337a4db58aa6bae2f6ee6239','31811f4e9e174971aaa99b16edcdaf2d',1934,'伪满洲国间岛省（今延边）警务厅厅长','朝鲜族投日分子，在延边、图们地区残酷镇压朝鲜族抗日武装，协助日本宪兵抓捕抗联地下组织。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2aa0f82119914066b38433ba3d12123c','6efa2b05428f4ce7bca190966f945873',1935,'伪间岛省（延边）协和会会长','在延边、图们地区组织协和会，进行奴化宣传，诱骗青年加入伪军，破坏抗日运动。','基层头目','hanjian');
