INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('98d8419d26a4497f96b67705fcc28043','cb533c0f884642bbba0b4cbc47fa1713',1933,'伪图们江地区警察署署长','在图们、珲春一带设立检查站，截获抗日物资，逮捕并刑讯抗联交通员。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1266fbf7b6b84963ae69d0a107cfdc45','2acba151834b4857b8b6e41c12ee546c',1932,'伪满洲国吉林市市长','在吉林市推行保甲制度，组织“自卫团”协助日军扫荡，镇压学生抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('826421d6f44f47b5a36bfd1ea6a88826','6876b4dc973441299b47d406050a627f',1932,'伪满洲国吉林省教育厅厅长','在吉林、延边地区推行殖民教育，篡改历史，禁止使用朝鲜语和汉语教学。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('45c459753fee4ac9b32c8e2968fe9045','41502657c6b84465aa2ff94e620ed234',1932,'伪满洲国吉林地区实业厅厅长','协助日本掠夺延边地区木材、矿产和粮食，强迫农民种植鸦片。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('793408fe1e3d4a73bfa99dd6277d83ba','b8f5150658fd47f0a48c92aacb628181',1932,'伪满洲国军政部顾问（短暂投敌时期）','曾一度投降日本并参与伪满活动，但不久反正，在吉林、延边地区影响有限，故列此备查。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('69c3b9d3b57c4a59a4dd0fe688ea16b9','aeff6d8a430a403b81f5d6fedbae77e7',1933,'伪间岛省（延边）参事官','在延边地区协助日本殖民机构处理朝鲜族事务，参与“间岛移民”计划，分化抗日力量。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fd5e0e62c7604cf2a0d5ff598ebe49a9','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满洲国军政部大臣、伪奉天省长（曾涉吉林南部）','原东北军旅长，投日后任伪职，参与围剿东北抗日联军，在吉林南部及安图周边协助日军清乡。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d5bc2072703d4792818e3ac7fd1a1709','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1933,'伪满洲国延边地区警务统制委员长','在延边地区组织伪警察和自卫团，实施“集团部落”政策，迫害抗日群众，围捕抗联交通员。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8941a185dac24e93a9c5f5d148492df1','6efa2b05428f4ce7bca190966f945873',1934,'伪满洲国间岛省（今延边）警务厅长','朝鲜族亲日分子，在延边推行“皇民化”政策，组织特务网络，破坏抗日地下组织，参与制造多起屠杀事件。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4cbbbba6791248eb9a5c289fc0d15430','cb533c0f884642bbba0b4cbc47fa1713',1935,'伪满洲国间岛省协和会参与','在延边地区宣传“日满亲善”，协助日军强征劳工，搜集抗联情报，迫害反满抗日人士。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6d9d744f173f444c88d694ae63e641f7','31811f4e9e174971aaa99b16edcdaf2d',1936,'伪满洲国安图县县长','在安图县推行日伪“治安肃正”，组织保甲连坐，配合日军烧毁抗联密营，抓捕并杀害抗联后勤人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e26970f654844983b7fb760e5b75c9af','e1f79d7adf2d407393f6feedc366834e',1937,'伪满洲国间岛省教化科科长','在延边推行奴化教育，强迫朝鲜族改用日本姓名，禁止使用朝鲜语，协助日本宪兵镇压学生反日运动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('783a9352a9ad46a6bbcb3c026b10d5e9','d73b90e6ce27454f9f7b4e2502850c0c',1932,'伪满洲国吉林地区宪兵队翻译官','为日本宪兵队充当翻译，参与刑讯逼供抗日志士，在延边、安图等地多次带队搜捕抗联地下联络站。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2261b57f5e434c37aab3bf5eb9581a2f','2ced595bfc314a60adc5c52f33a8bec9',1933,'伪满洲国吉林市警察署署长','在吉林市及周边县镇残酷镇压抗日活动，多次组织“夜袭队”袭击抗联小分队，杀害无辜百姓。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c733cb6957c842378e26ae6e9688fa28','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满洲国立法院院长（曾任吉林地区司法职务）','早年留学日本，投日后参与伪满立法，为日本殖民统治提供法律依据，间接支持吉林、延边地区的“讨伐”行动。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6ba39f3906c546de8ded36aaad4c0425','875c22d678e24c21834a32caae69933c',1931,'伪吉林省长官公署长官、伪满洲国财政部总长、伪宫内府大臣','九一八事变后率先投敌，在吉林市组织伪吉林省政权，通电脱离南京国民政府，协助日军侵占吉林全境，并参与筹建伪满洲国，是东北早期核心汉奸之一。；九一八事变后率先投敌，以吉林省军政长官身份宣布吉林“独立”，组织伪吉林省政权，为日本侵占吉林全省及扶植伪满洲国效力；其伪政权体系覆盖今松原、长岭一带。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('587711ed224f4bb0aee6232c0a9b50e6','6876b4dc973441299b47d406050a627f',1931,'伪吉林省长官公署实业厅长、伪满洲国实业部总长、伪外交部大臣','熙洽亲信，参与伪吉林省政权组建，后长期在伪满中央任职，推行日本殖民经济政策，为日军掠夺东北资源服务。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8027ec0b2479463c8bff82cdb61bf782','caae33d173854bf0a1b2b4f0db4f585a',1931,'伪吉林省长官公署副长官、伪满洲国参议','原吉林省官员，九一八事变后附逆，协助熙洽维持伪吉林省统治，参与镇压抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d19a81da547a4e188d1c0185ee3b1ee8','b21d5a4d224a4173bdb0f2b366c98d70',1931,'伪吉林省长官公署民政厅长、伪满洲国间岛省省长','在伪吉林省及伪间岛省任职，负责民政与地方治安，配合日军在延边地区推行保甲连坐、集团部落政策，镇压抗日群众。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f227917a1c22430caac14f2a93d427ac','3954cf6c52e9432eae4f94e815aa72ef',1931,'伪吉林省长官公署交涉员、伪满洲国间岛省省长、伪经济部大臣','长期在伪吉林省和伪间岛省任职，处理对日交涉与地方行政，参与延边地区殖民统治，后升任伪满中央经济部门要职。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f91a9b541c4d44edac7858213dcff51d','350822a1078340679fd657c16a793993',1931,'伪间岛省省长、伪吉林省省长、伪满洲国民生部大臣','伪满重要汉奸官僚，曾任伪间岛省省长，直接负责延边地区殖民统治，推行日本语教育、征发劳工、镇压抗日武装。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('060c7d1392604944b9692f8c77009187','0f74f0feff11477097e45df1ca6a4971',1934,'伪间岛省次长（日本人）','作为伪间岛省实际控制者之一，主导延边地区行政、警察与经济掠夺，配合关东军围剿抗日联军。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('98cb3a7ba7ca47cd9a743b0e2dabbd2a','ba267e3aad044ab78d40dc8898a8736d',1930,'伪间岛省次长、伪吉林省次长（日本人）','在伪间岛省和伪吉林省担任次长，掌握实权，推行日本殖民政策，镇压延边抗日活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8e84eedfbd8544c086ff727dfdcb4edd','f87c32e3cfd34c3db4ef08c6befef768',1930,'伪延吉县县长、伪间岛省民政厅长','在延吉县及伪间岛省任职，执行日军指令，组织自卫团、保甲制，协助搜捕抗日人员。','市县厅局级','hanjian');
