INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e5808aff76ed48798e3f92719f1810c6','2d35dddfc3534cfa92d27bf11bfa1edc',1930,'伪延吉县警务局长、伪间岛省警务厅长','长期在延边地区担任伪警察头目，指挥伪警配合日军围剿抗日游击队，逮捕杀害抗日志士。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7942c1eb230c4aa0ada6d05f9a2735b3','b7a8079e178045ffb53f700e87433c5f',1930,'伪延吉县警务局长','在延吉地区负责伪警察事务，参与破坏中共地下组织，镇压抗日群众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f3968979653840e2856514e2b8190e79','5e6571131af64621a9b6e5a8be96e25e',1930,'伪间岛省协和会事务长、伪延吉县协和会会长','朝鲜族亲日分子，通过协和会组织在延边地区进行亲日宣传、情报收集和劳工动员，协助日军统治。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('68cac16ddbcd4b6ca1bb430575999258','0de491690f8046dc820cd0a0ec9f1de4',1930,'伪间岛省协和会干部、伪延吉县协和会理事','在延边地区从事亲日文化活动，配合日伪推行皇民化教育，动员朝鲜族青年加入伪军。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('14b944ae8b82421680b082f52ab47108','640c6fec801247e0af7dfdc1c7b14ca4',1930,'伪间岛省警务厅特务科长','在延边地区负责特务情报工作，搜捕抗日地下人员，破坏中共延边党组织。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('054bb82cc7c643be9888ef7aded41523','e1f79d7adf2d407393f6feedc366834e',1930,'伪满洲国协和会中央本部干部、亲日文化人','朝鲜族亲日文人，虽主要在伪满中央活动，但其亲日言论和协和会工作覆盖延边地区，影响当地文化教育界。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('735d1f80256a45a7ac64c37df3684a22','611c3a4928674f06aaff60c1a1a52ad2',1930,'伪间岛省协和会青年训练所所长','在延边地区负责青年训练，灌输亲日思想，为日军培养伪军和劳工骨干。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ab2a0f22353a46ee98066d5af8180437','77a789268c6f47b4a617cdb9e41180bd',1931,'伪满洲国参议府议长、伪国务总理大臣','原东北军将领，九一八事变后投敌，历任伪满要职，其统治覆盖吉林全省，为日本殖民统治服务。；原东北军将领，九一八后投敌，历任伪满要职，代表伪满签署多项卖国协定，推行日本殖民统治，其政权统治范围包括吉林省及今松原地区。；奉系旧军阀，九一八事变后公开投敌，历任伪满要职，参与推行殖民统治，其势力与影响覆盖辽宁各地，包括抚顺地区。；原东北军将领，九一八事变后投敌，历任伪满要职，主导推行保甲连坐、粮谷出荷等政策，对辽宁包括阜新地区实施殖民统治。；辽宁台安人，长期在伪满中央任职，为日本殖民统治服务，其势力影响覆盖黑龙江地区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('438c8e1748a84d928f993408efe6e09e','79b17193512846a1a5bde9f5df22c926',1931,'伪满洲国民政部大臣、伪参议府议长','原辽宁省官员，后成为伪满核心汉奸，参与制定殖民政策，影响包括吉林、延边在内的东北各地。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('15713e16281245c7810ea9cd2e39279e','4b486850921b4f33b616f1f8dcdef313',1931,'伪满洲国产业部大臣、伪民生部大臣','长期在伪满中央任职，推行经济统制政策，掠夺吉林、延边地区资源，征发劳工。','无明确职位或一般帮凶','hanjian');
