INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('52cd755abebf479c81fc0b7ceb7c668c','5a42f897a627483f9ceda7a629ea37f8',1930,'伪吉林省省长、伪哈尔滨市市长','曾任伪吉林省省长，负责吉林地区殖民行政，配合日军征发劳工、粮食，镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f56d09770cf64c29ac66ebeafc7dfc92','3eb966fdcf364389b5302ef8a669f7ac',1930,'伪吉林省省长、伪司法部大臣','在伪吉林省省长任内推行保甲制、集团部落，镇压吉林及延边地区抗日力量。','省部级/大军区级要员','hanjian');
