INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3aafa75ebd9d4d89bba1b2197675f277','c864056eff7343cc9fa5a6209818cc19',1930,'伪间岛省省长','曾任伪间岛省省长，在延边地区推行殖民统治，配合日军围剿抗日武装。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6a080bb91d8c4401b5813dccd0bb274a','1eb3ba4bfbdd4b01a2c999042542f201',1930,'伪间岛省省长','在伪间岛省省长任内，执行日本指令，征发劳工、粮食，镇压延边抗日群众。','省部级/大军区级要员','hanjian');
