INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f81645ed10c945d091ac54ae12b5a1ad','0828d505b2f14261b72798c67f3b0e26',1930,'伪延吉县协和会会长','朝鲜族亲日分子，在延吉地区组织协和会活动，进行亲日宣传和情报收集。','基层头目','hanjian');
