INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0a5d1fc1db4d4c74a60135bbba5da0fe','2f8f6aebc0ab40a18cb66c98b870f15c',1930,'伪间岛省警务厅保安科长','在延边地区负责保安事务，参与镇压抗日游击队，管理伪警察队伍。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b0237f7248944bf98fac9fdfda91e5ad','150a02a0556f454889aa4bd9ab5d9dfa',1930,'伪延吉县自卫团团长','组织并指挥伪自卫团，配合日军搜捕抗日人员，欺压当地百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('495bead3d9c54b73ab429330d09028e4','8741f44499164417a5792a43caf1501c',1930,'伪间岛省协和会事务长','在延边地区负责协和会事务，推行皇民化运动，动员朝鲜族民众支持日军。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fa4b6e67ce5f45a69b730c4f6c729e8c','7fb1c8f4fe8249fbaa6d00f4b7c043f8',1930,'伪延吉县教育局长','在延吉地区推行日本语教育和亲日课程，篡改历史，奴化青少年。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9be86f5d3324419caeacc9eef3feeab6','2c175700b8b342cf9287673776898de4',1930,'伪间岛省协和会顾问','朝鲜族亲日头目，在延边地区协助日军进行思想宣传和民众控制。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5bf579e273fd492daa89eb2569233a5c','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洲国热河省省长、伪军将领','原东北军将领，投敌后率伪军配合日军进攻吉林、延边等地抗日武装。；原东北军将领，1933年投日，任伪热河省省长，直接管辖承德、滦平地区，镇压抗日武装，推行保甲制度，强征劳工。；原东北军将领，九一八事变后投靠日本，曾任伪满洲国热河省省长，参与镇压抗日武装，其势力范围曾涉及辽宁西部地区。；原东北军将领，九一八事变后投敌，曾任伪满热河省省长，参与镇压抗日武装，在盘锦、双台子一带协助日军清乡；原东北军将领，九一八后投敌，任伪热河省省长，参与镇压抗日义勇军，在绥中、朝阳一带协助日军清剿抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a6ccef6ac27146b3b91ce1b397872c7a','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满洲国奉天省警备司令、伪军政部大臣','原东北军将领，投敌后指挥伪军围剿东北抗日联军，其部队活动范围包括吉林、延边地区。；原东北军东边道镇守使，1931年投敌，所辖伪军控制辽宁多地包括阜新一带，配合日军围剿抗日义勇军。；原东北军东边道镇守使，1931年投敌，组建伪军，长期在辽宁地区配合日军围剿抗日义勇军，其势力范围涉及阜新、朝阳等辽西地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('012a35bafbce4dc3937525c598a68601','c9dffc071fec4ce58fe1d611f26c28da',1930,'伪满洲国军管区司令','伪军头目，率部在吉林、延边地区配合日军围剿抗日武装。；原东北军军官，投日后任伪军司令，驻防辽宁中南部，参与围剿盘锦、营口一带的抗日义勇军。；投敌后任伪满军管区司令，参与镇压黑龙江地区抗日武装。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f4e6a38db4d7447dab7c487496446f35','a979dd19db7944cd9480e25931212232',1930,'伪满洲国间岛地区伪军指挥官','在延边地区指挥伪军，配合日军对抗日联军进行讨伐作战。','基层头目','hanjian');
