INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5e4d1ad7f71c42eb9f36996738032f8c','350822a1078340679fd657c16a793993',1932,'伪吉林省公署参事官、伪延边地区行政长官','在延边地区推行日伪殖民统治，镇压朝鲜族和汉族抗日活动，强征劳工。','无明确职位或一般帮凶','hanjian');
