INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('58bf218f97b44cc89d1b370789d18a50','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满立法院院长（原吉林籍）','积极鼓吹“满蒙独立”，为日伪统治吉林、延边提供法律和舆论支持。；参与伪满建国，长期在长春（新京）任职，为日本殖民统治提供法律依据。','伪政权最高层/元首级','hanjian');
