INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b563a0b80a75421bbae328979339e476','cefdf137ca6e4da48157b00005b64944',1936,'伪满间岛省参事官','协助日军制定“治安肃正”计划，在延吉、汪清等地实施大搜捕，逮捕抗日群众数百人。','无明确职位或一般帮凶','hanjian');
