INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('195cd77d521a44c096957ad17c5752bc','77a789268c6f47b4a617cdb9e41180bd',1931,'伪满洲国国务总理大臣（曾任东省特别区长官）','原奉系将领，后投靠日本，在吉林地区协助日军镇压抗日力量，长期担任伪满最高行政首脑；虽主要活动于长春，但曾控制吉林西部及白城地区，全面投靠日本，签署多项卖国协定，协助日军统治吉林、白城等地。；原东北军将领，后投敌，长期担任伪满最高行政职务，在长春（新京）主持伪满政府，协助日本奴役东北人民。；在长春任伪国务总理，全面配合日本关东军控制伪满政权，签署多项卖国条约；原东北军将领，后投敌，长期担任伪满最高行政长官，配合日本侵略政策，镇压东北抗日力量。；原奉系将领，后投靠日本，在长春（新京）任伪满最高行政首脑，全面配合日本侵略政策，奴役东北人民。；原奉系将领，1931年投日，后任伪满最高行政长官，长期为日本侵略服务，虽主要活动于新京（长春），但吉林地区为其势力范围。；虽总部在长春，但多次巡视辽宁及锦州地区，督促伪军配合日军“讨伐”，其伪政权体系直接管辖锦州、古塔的行政与军事。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1b4c778427034125b62232a57061ce3b','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满洲国军政部大臣、伪第一军管区司令','原东北军旅长，叛变后驻防吉林，多次围剿抗日武装，屠杀抗日军民','基层头目','hanjian');
