INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('61db741f9249451b97c2110dc61f91fa','2acf7a5b9b5341578e1066b27394b2eb',1932,'伪满吉林省长、伪满治安部大臣','原东北军旅长，投日后任伪吉林省长，在昌邑及周边推行保甲制度，协助日军清乡。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('46cc073025a7439ca729fe8cfda9a6df','350822a1078340679fd657c16a793993',1932,'伪满吉林市市长、伪满民生部大臣','满族亲日分子，在吉林市及昌邑区实施奴化教育，强征劳工，镇压反满抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3481680ed7664fd6aa2975b9d5329a13','9fdf72cacfcf4c72a1c4a279be3c42c2',1932,'伪满吉林警察厅厅长','在吉林昌邑地区组织特务警察，抓捕抗日地下工作者，破坏抗联联络站。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('efc193a86b494b9faaecdf8084a4277b','3eaf116c87a7417fadcbf5fe87b56f23',1933,'伪满吉林宪兵队队长','在昌邑一带残害抗日军民，参与制造多起屠杀事件，协助日军“讨伐”抗联。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f2e437e1b4824c7bb152550ac63e1e0d','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满立法院院长（曾活动于吉林）','原奉系律师，投日后在吉林地区为伪满政权立法，协助日伪统治，参与“治安肃正”。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4642aa8d3f0f4794b0af9b4ec0ec19ec','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满黑龙江省长（曾兼任吉林地区清乡督办）','在吉林昌邑周边推行“集团部落”，烧毁民房，制造无人区，切断抗联补给。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a4d3538c4b3d4e96a91202bf0eb07ae4','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满第一军管区司令官','原东北军旅长，投日后任伪满第一军管区司令，负责吉林中西部（含松原地区）治安，围剿抗联部队；原东北军旅长，投敌后任伪满第一军管区司令，驻防吉林地区，多次率伪军“讨伐”抗日游击队，杀害抗日军民。；原东北军旅长，投日后任伪满第一军管区司令官，驻防吉林地区，参与围剿东北抗日联军，残害抗日志士。；原东北军旅长，投敌后任伪满第一军管区司令官，驻防吉林地区，多次率伪军配合日军围剿杨靖宇领导的抗联第一路军，在临江、抚松等地制造多起惨案。；原东北军旅长，1931年投敌，任伪满第一军管区司令官，驻防辽宁地区，多次率伪军围剿抗日义勇军和抗联部队。；原东北军旅长，投敌后任伪满第一军管区司令，驻防辽宁，多次率伪军围剿鞍山、铁西地区的抗日游击队。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('eba6749ff7234dfb92043e319c379840','9fdf72cacfcf4c72a1c4a279be3c42c2',1932,'伪满扶余县县长','在松原扶余县任伪县长，协助日军强征粮食、劳工，迫害抗日群众','基层头目','hanjian');
