INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c6d4537e48e3469da70f44d2dcca1937','b21d5a4d224a4173bdb0f2b366c98d70',1932,'伪满长岭县县长','长岭县（今松原辖）伪县长，配合日军“讨伐”抗联，强征民夫修筑公路和军事设施','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6abd2ab2f4af4471acef12c8619bcc7e','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满立法院院长（曾涉吉林事务）','原奉系法律人士，投日参与伪满政权，曾协助策划吉林地区伪政权的建立，影响松原一带；原奉系法律人士，投日后任伪满立法院院长，曾参与吉林地区伪政权法律体系构建，为日本殖民统治提供法理支持。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('58cf111b6dab4f30a4d2ab0ac0f66756','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满经济部大臣（曾管吉林西部）','原吉林省实业厅长，投日后任伪满经济部大臣，主导松原地区粮食统制和经济掠夺','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b738881d33644db8ae459bc45741a0f0','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满立法院院长（曾任吉林地区司法要职）','原奉系法律人士，投日后参与伪满立法，曾协助日军在吉林地区建立伪司法体系，迫害抗日人士。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('603e5a92a029406bb89ffb72f908c15d','41502657c6b84465aa2ff94e620ed234',1932,'伪满吉林省民政厅厅长','原吉林省官员，投日后任伪民政厅长，推行保甲制度，组织“自卫团”，协助日军清乡，迫害百姓。','市县厅局级','hanjian');
