INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1779e343696a452ebc23768f866b84fa','b21d5a4d224a4173bdb0f2b366c98d70',1932,'伪满乾安县县长','乾安本地汉奸，投日后任伪县长，协助日军在乾安地区建立伪政权，强征粮食，迫害抗日群众。','基层头目','hanjian');
