INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3d9582b4f70f43cf90625b08b6d8973a','3cd55e29febc489d9f9a7f2f88db31bb',1933,'伪满乾安县警务科科长','乾安伪警察头目，参与“讨伐”抗日武装，严刑拷打抗日嫌疑犯，直接参与多起屠杀事件。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('418024abb1564e3f99c51b36f7d0af1a','543b88d602304be1ae0013f9e015553e',1935,'伪满吉林省协和会事务长','在吉林地区推行协和会奴化宣传，组织“勤劳奉仕”，为日军提供劳力和情报。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e141028d77e74a76b5cf8b0df1dbef64','db46f683d7524311bc88d91f051f20d7',1932,'伪满吉林地区保安队队长','率伪保安队在吉林、松原交界地带袭击抗日游击队，烧毁村庄，抢夺财物。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('289a3549fa9a42a5a2da1239269696bc','3a9e402192aa460fb51a927d874bb93e',1933,'伪满乾安县自卫团团长','组织地方自卫团，配合日军“扫荡”，在乾安农村抓捕抗日积极分子，实施连坐。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a53fb22294a14da894d329594c8e63c8','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满吉林省实业厅厅长','原吉林实业界人士，投日后控制吉林地区工矿资源，为日军生产军需物资，压榨劳工。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('11541a26a1224374858517e7e3b1f05a','236b09af126745e997e5603fc3f56d0e',1932,'伪满吉林省省长','清室后裔，投靠日本后任伪满吉林省省长，积极推行日伪殖民政策，协助日军镇压吉林抗日军民。','省部级/大军区级要员','hanjian');
