INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('32d925332a874e409c03ba6bdcb7b7b7','2acf7a5b9b5341578e1066b27394b2eb',1932,'伪满吉林省警务厅长','原吉林警察头目，投日后任伪满吉林省警务厅长，组织警察特务搜捕抗日志士，破坏地下抗日组织。；原吉林警察头目，投日后负责吉林地区伪警察系统，搜捕抗日地下人员，协助日军推行保甲连坐制度。；主持吉林伪警察系统，大肆搜捕抗日地下党，破坏抗联交通线。','市县厅局级','hanjian');
