INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('09dcc7017d2347a1adcbc733861f0f73','fd2c5f0abda941079651ec9eb1cc5c31',1932,'伪满前郭尔罗斯旗旗长','蒙古族投日分子，任伪满前郭尔罗斯旗旗长，协助日军在该旗强征粮食、劳工，镇压蒙古族抗日活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('92b6e32b52e947219ee137f7044f9110','838979c5881d455d9908a863bc24d449',1933,'伪满郭尔罗斯前旗警务科长','蒙古族汉奸，任伪警务科长，参与组建伪警察队，在松原、前郭尔罗斯地区抓捕抗日地下人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('26516d199173496bbbe761382fc66e8c','12baef8ee0934c9d8c53c8b049f5e14d',1932,'伪满松原地区（扶余县）县长','原扶余县地方士绅，投日后任伪县长，强征民夫修建日军工事，并协助日军清乡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b829d0067a09401eb2cea5ea71f5630a','ba135ba1ef794aeba0fdad0065a31974',1935,'伪满吉林市宪兵队翻译官','为日军宪兵队充当翻译，参与审讯、刑讯抗日志士，多次指认地下党员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2b6f14b608d44c38ad61ca2f96ce992e','77a789268c6f47b4a617cdb9e41180bd',1935,'伪满国务总理大臣（曾管辖吉林地区）','原东北军将领，投日后任伪满最高行政长官，全面推行日本殖民政策，对吉林、松原地区抗日活动进行残酷镇压。','伪政权最高层/元首级','hanjian');
