INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('be4ea5142e2a4798bac1c1a9c7e7ad75','9fdf72cacfcf4c72a1c4a279be3c42c2',1937,'伪满吉林省协和会总务部长','在吉林地区组织协和会，宣传“日满亲善”，搜集抗日情报，破坏群众抗日组织。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('402a6e261f02428482488c294638da4f','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满吉林省实业厅长','协助日本掠夺吉林地区粮食、木材资源，为日军提供经济物资支持。；在吉林地区为日军经济掠夺服务，强征农民土地，控制粮食贸易，导致当地民众饥荒。','市县厅局级','hanjian');
