INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7a2ff6ce62e84366b278632affd12896','6960ecf5067148b08c7571d02c447623',1938,'伪满吉林地区保安队队长','率伪保安队多次袭击抗日联军小分队，在松原、扶余一带杀害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1c3d9adfea7a4c2c9009be7b059a5337','257bc97b2b934e538c388d33e09f39d4',1935,'伪满吉林省教育厅长','推行奴化教育，强制学校教授日语，删除中国历史内容，毒害吉林青少年。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c685aecf58554a39ae2c81d8776cdd04','2acf7a5b9b5341578e1066b27394b2eb',1932,'伪满吉林省省长、伪满民政部大臣','原吉林省政府官员，投日后历任伪吉林省长，在吉林、宁江（今松原宁江区）一带推行殖民政策，强征劳工，镇压反满抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('02aab704ba174b23b793484728e5465b','350822a1078340679fd657c16a793993',1931,'伪满吉林省警务厅长、伪满奉天省省长','原吉林警察机构官员，投日后负责吉林省（含宁江地区）警务，组织伪警察配合日军清乡，抓捕抗日志士。；满族贵族，投日后任伪满吉林省警务厅长，在吉林、辽源地区建立伪警察网络，抓捕抗日地下工作者，参与制造多起惨案。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fa7ca931bbfd4f52a2ccede9aa5ecb6d','3eb966fdcf364389b5302ef8a669f7ac',1932,'伪满吉林省公署参事官、伪满国务院总务厅次长','原东北地方官员，投日后在吉林省公署任职，参与制定“治安肃正”计划，对松原、宁江等地的抗日武装进行围剿。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('eaf89128d91b42688eafc87cc186032b','70cbcc058e6648678fa022e3a64b9cea',1933,'伪满吉林省公署警务厅特务科科长','在吉林、松原地区指挥特务活动，破坏地下抗日组织，逮捕并刑讯抗日人员，罪行累累。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('36a8d4f15efb4291b84220467434252e','21853206ad2b417598d1af0b4b3a4782',1932,'伪满吉林地区保安队队长','原地方土匪头目，投日后组织伪保安队，在宁江、扶余（今松原）一带协助日军“扫荡”，残害百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c9eeb2e1178f4c989191b65d381a457c','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满立法院院长、伪满吉林省高等法院院长','原东北法律界人士，投日后任伪满司法高官，在吉林、松原地区推行伪满法律，迫害抗日人士。；原奉系法律顾问，投日后任伪满吉林省高等法院院长，在吉林、辽源地区审判抗日志士，以“反满抗日”罪名判处多人死刑。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8e432392d2b042f093db8bd752cc2ebf','caae33d173854bf0a1b2b4f0db4f585a',1931,'伪满吉林省财政厅长、伪满中央银行副总裁','原吉林财政官员，投日后负责伪满在吉林、松原地区的经济掠夺，强征粮食和物资，支持日军战争。；原吉林官银号总办，投日后负责伪满在吉林、辽源地区的财政搜刮，发行伪币，掠夺粮食和物资，支持日军战争。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('113c1404bbab42148cc02053cf1e9a17','41502657c6b84465aa2ff94e620ed234',1932,'伪满吉林省教育厅长、伪满民生部大臣','原吉林教育界官员，投日后推行奴化教育，在宁江等地学校强制灌输“日满亲善”，抹杀民族意识。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f993084766f442258860dff462efe3fc','2acf7a5b9b5341578e1066b27394b2eb',1931,'伪满吉林省省长、伪满交通部大臣','原吉林省警务处长，投日后任伪满吉林省省长，在吉林、松原、扶余地区推行保甲制度，强征劳工，协助日军建立殖民统治，镇压反满抗日活动。；原东北军将领，投日后任伪满吉林省省长，在吉林地区推行殖民政策，协助日军镇压抗日活动，并参与对通化、集安一带的“讨伐”。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cd0cce122b16483b807cdd69a886bcf4','3a9e402192aa460fb51a927d874bb93e',1931,'伪满吉林地区保安队头目','原地方土匪头目，投日后被日军收编为保安队，在扶余、松原一带活动，配合日军扫荡，残害百姓，抢夺物资，杀害抗日军民。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9e8084089e0b4ed687273be09abe7215','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满立法院院长、伪满吉林省参议','原奉系政客，投日后任伪满立法院院长，曾参与策划吉林地区伪政权建立，为日军侵华提供法律和舆论支持，其势力涉及吉林、松原、扶余。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('61114f0c1c7d4c5d852fda879577070d','3b74f508628f475a8777ffb7e38a48a0',1931,'伪满黑龙江省省长（曾管辖扶余地区）','原黑龙江省实业厅长，投日后任伪满黑龙江省省长，扶余地区曾属其管辖范围，推行日伪经济统制，强征粮食，压迫民众。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('61889e5dea3b476bbb096cf3da969899','b21d5a4d224a4173bdb0f2b366c98d70',1932,'伪满扶余县县长','投日后任伪满扶余县县长，在扶余地区推行日伪殖民政策，组织伪县公署，协助日军清乡，强征劳工，镇压当地抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('792e150c93c440aa9886a6984d9fcebd','257bc97b2b934e538c388d33e09f39d4',1932,'伪满松原地区（前郭旗）旗长','投日后任伪满前郭旗旗长（今松原地区），在蒙古族聚居区推行日伪统治，协助日军建立情报网，迫害抗日分子。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d452f5887f7746a6a8a283aaec45e09f','3cd55e29febc489d9f9a7f2f88db31bb',1931,'伪满吉林地区宪兵队翻译官','为日军宪兵队担任翻译，在吉林、松原、扶余地区参与审讯和刑讯抗日人士，直接参与多起屠杀事件。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7eae1e1432fb4d1da1ae1f2d684b2fe4','da81f2be49ba477e9dfca29887ad5a09',1932,'伪满扶余县警察署长','投日后任扶余县警察署长，带领伪警察在扶余、松原一带抓捕抗日地下党员，破坏抗日联络站，残害群众。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('311307f27e124adaaafdbf9d25ab8797','875c22d678e24c21834a32caae69933c',1931,'伪满吉林省长官、伪满宫内府大臣','原吉林副司令长官公署参谋长，1931年叛国投敌，打开吉林城门迎日军入城，后任伪吉林省长，协助日军清剿抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1088d53816cf44e38c64a6b94b007b2c','1d67ff455ffc47b8addcc485beb0ca34',1932,'伪满第一军管区司令（驻吉林）','原东北军将领，投日后任伪满军职，在吉林、松原一带率伪军围剿抗日游击队，屠杀抗日军民。；率伪军配合日军在船营及周边“讨伐”抗日武装，制造多起屠杀事件。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6937dfda27aa4448aa6ac8121afea364','350822a1078340679fd657c16a793993',1932,'伪满吉林省公署参事官','吉林本地汉奸，积极参与伪满行政建设，为日军征粮派夫，镇压当地反满抗日活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cc2fc26210254459aac665853dd38aed','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满哈尔滨特别市市长（曾管辖松原部分地区）','原奉系官员，投日后在伪满任职，曾参与对吉林西部（含松原）的殖民统治，协助日军掠夺资源。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('13dd156e740a405b95f21714570b2519','9fdf72cacfcf4c72a1c4a279be3c42c2',1932,'伪满松原（扶余）县县长','在松原地区（原扶余县）任伪县长，协助日军建立伪政权，组织伪警察镇压抗日活动，强征劳工。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b45d5491da404ad7b32f117ac4abfad3','d5f8717058654c37a56ff29410e99525',1932,'伪满松原（前郭旗）旗长','在松原前郭尔罗斯地区任伪旗长，推行日满亲善政策，为日军提供情报，迫害蒙古族抗日志士。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('09adb82045b448cebbe8507c0f477b31','b21d5a4d224a4173bdb0f2b366c98d70',1933,'伪满松原（乾安）县参事官','在乾安地区协助日军清乡，组织汉奸武装，杀害抗日联军联络员。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('273789a090c340189017d7c263556c69','3cd55e29febc489d9f9a7f2f88db31bb',1934,'伪满松原（长岭）县警务科长','在长岭县率伪警多次围剿抗日武装，逮捕并刑讯抗日群众，罪行累累。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1e55782c2be44208ad7afaef040c2e75','77a789268c6f47b4a617cdb9e41180bd',1935,'伪满国务总理大臣（曾管辖吉林全省）','原奉系军阀，全面投日后任伪满总理，对吉林、松原地区推行奴化教育，签署多项卖国条约。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5f523edd9a734871a60b7e37edece83f','79b17193512846a1a5bde9f5df22c926',1932,'伪满参议府议长（吉林籍）','原吉林督军署参谋长，投日后在伪满中央任职，但曾参与吉林地区伪政权组建，为日军出谋划策。','无明确职位或一般帮凶','hanjian');
