INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9279df8f598e47239678f3b77eb84eb1','589ab27feed347c6944e6c001125dc02',1932,'伪满松原（扶余）商务会长','在扶余县为日军征购军粮，垄断商业，向日军提供抗日分子名单，导致多人被捕。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c5366a13090641cebf6e018ae724c022','a2c03b81e5f2412bb86f5d5599c1687b',1933,'伪满松原（前郭）警察署长','在前郭旗残酷镇压蒙古族牧民反抗，参与“治安肃正”行动，烧毁村庄，强征民夫。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('496604edb6a241a892d293f755b306e8','5eedc8643ca5483ca76fdb221e54973d',1932,'伪满吉林宪兵队顾问','原吉林军官，投日后任宪兵队顾问，参与策划多次大搜捕，在吉林市区及松原地区杀害抗日志士。','无明确职位或一般帮凶','hanjian');
