INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6f6f8175ba0045fe92d030915b0f7cf4','e25c85c91f604ceda710a0637532c900',1931,'伪吉林省剿匪司令、伪军将领','九一八后投敌，率伪军配合日军进攻吉林各地抗日武装，参与镇压吉林、松原一带抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ce453a91fa484d1b939847f6d8427e5f','c0860f9060d74dfba1674157f4596712',1931,'伪吉林省警备司令、伪满军政部大臣','原东北军吉林部队将领，投敌后任伪吉林省警备司令，协助日军控制吉林地方，镇压抗日力量。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9ecf0353c4a74f938ad0f36ea42c4875','b21d5a4d224a4173bdb0f2b366c98d70',1931,'伪吉林省公署厅长、伪满官员','在伪吉林省政权中任职，参与推行日本殖民政策，管理地方行政，涉及今松原、长岭一带的伪政权运作。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d42beb597474450d9b18007b45b6d217','beec1d9af727487490bbd352fb194f47',1931,'伪扶余县县长、伪松原地区地方伪政权头目','在伪满时期任扶余县伪县长，扶余即今松原市辖区，参与征粮、抓丁、镇压抗日群众，为日军维持地方统治。','基层头目','hanjian');
