INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('efadd10ea3a940989109aecff809c62d','1bf856505e3c422aa408d2d00dc1810c',1931,'伪长岭县县长、伪地方维持会会长','伪满时期任长岭县伪县长或维持会头目，直接参与长岭地区的伪政权统治，为日军征粮、派夫、镇压抗日活动。','基层维持会/地方自治头目','hanjian');
