INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('17adbd283d024f8583750b116cffbd08','105c4446aaf347b2a0ed658ef91afcc1',1931,'伪长岭县自卫团团长、伪地方武装头目','在伪满长岭县组织伪自卫团，配合日军和伪警察搜捕抗日人员，控制地方。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3b8d941087d2489db111b327c26c192f','3a9e402192aa460fb51a927d874bb93e',1932,'伪桦甸县警务科科长','在桦甸县任职期间，积极协助日军镇压抗日武装，多次率伪警察讨伐抗日游击队，抓捕并杀害抗日军民数十人。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c2c8e9bedc2147fe90537c19f09f0c06','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满吉林军区司令（曾驻桦甸一带）','原东北军将领，九一八后投敌，任伪满军事要职，其部队在桦甸、吉林地区参与“讨伐”东北抗日联军，烧杀抢掠，破坏抗日根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9e1bfc57b6fc4095ae7913aa85a4dd39','e25c85c91f604ceda710a0637532c900',1932,'伪满吉林剿匪总司令','率伪军多次进攻桦甸、磐石一带的抗日游击队和抗联部队，制造多起惨案，是日寇在吉林地区的主要帮凶。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('12ab37b5d4cb491bb193230c4edb2a9e','2acf7a5b9b5341578e1066b27394b2eb',1932,'伪满吉林警备司令','在吉林地区推行“治安肃正”，指挥伪军配合日军对桦甸山区进行反复“扫荡”，杀害抗联战士及无辜百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a15f230064614feeab9dc5b58f123d29','31f5d1beddc247798a41ecf2ef35664c',1933,'伪桦甸县县长','在任期间强征劳工修建警备道路和碉堡，为日军提供粮食和物资，并组织汉奸情报网，破坏抗日地下组织。','基层头目','hanjian');
