INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('976abf7b9d8e4955abd01910bf42b12c','d7404e20b4894fc5b66a2d88c815fd9a',1937,'伪桦甸县保安队队长','率保安队配合日军在桦甸夹皮沟、老金厂等地围剿抗联第一路军，多次提供日军情报，并杀害抗联侦察员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('52793c31d56e460b9f465f6fd5f4a8ef','af96068e274a4fdfb011573dd045f17a',1940,'伪桦甸县司法矫正局局长','将抓捕的抗联嫌疑人和无辜百姓投入矫正院，实施酷刑和劳役，致多人死亡，是日伪法西斯统治的忠实执行者。','市县厅局级','hanjian');
