INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d1601698fbc042f4b2b393626e6b6b22','350822a1078340679fd657c16a793993',1940,'伪满吉林省长（1940-1942）','原吉林交涉署署长，投敌后任伪吉林省长，在任期间强化对白城、大安地区的粮食统制，压迫民众。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e2c9401904a84da4976e3372b91d3aa8','448cf19f40334f31b9f5d71d601929ab',1942,'伪满吉林省长（1942-1945）','原吉林高等法院院长，投敌后任伪吉林省长，协助日军在白城、大安地区强征劳工，镇压反满抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0231f2f5772f4d57a5fdbe37b83af957','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满立法院院长（早期）','原奉天律师，投敌后参与伪满立法，其活动涉及吉林全省，支持日伪对白城、大安地区的殖民统治。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6c70266ee48044078b00e02f2d847959','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满经济部大臣、伪满黑龙江省长','原哈尔滨商会会长，投敌后历任伪职，曾管辖白城、大安地区（原属黑龙江省），推行经济掠夺政策。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('98a5e73bed5245f98b9c8d2667b65f16','41502657c6b84465aa2ff94e620ed234',1931,'伪满财政部大臣、伪满吉林省长（早期）','原吉林省政府委员，投敌后任伪吉林省长（1932年短暂），后任伪满财政部大臣，参与对吉林西部地区的经济压榨。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cb38199b21c949a99dfa36fdf68c3f76','caae33d173854bf0a1b2b4f0db4f585a',1931,'伪满吉林省长（1931-1932）','原吉林省政府主席，九一八后投敌，任伪吉林省长，在任期间向日军提供白城、大安地区情报，协助占领。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('529f05c498584ba5867f8841f99e89dd','a984ebfabbf64a5b8e1dfef2d68daa53',1932,'伪满吉林警备军司令（后投敌）','原东北军将领，一度抗日，后于1933年投敌，任伪满吉林警备军司令，在洮南（白城）一带围剿抗日武装。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0926e122798e4355a48e55bb16bce967','2acf7a5b9b5341578e1066b27394b2eb',1932,'伪满军政部大臣、伪满第5军管区司令','原东北军旅长，投敌后任伪满军职，曾驻防吉林西部，指挥伪军在白城、大安地区对抗联进行“讨伐”。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1c6bcf0b12c74508a9e2cb3c2c9ea158','8bd659b1a1f24d64ae2bf011c50d3980',1932,'伪满吉林警备军参谋长','原东北军军官，投敌后任伪满吉林警备军参谋长，参与策划对白城、大安地区抗日游击队的围剿。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2ddaf0548e6f46c3a724bdd9f5b8d4ba','b8f5150658fd47f0a48c92aacb628181',1932,'伪满黑龙江省长（短暂投敌）','曾抗日，但1932年一度投敌任伪黑龙江省长，管辖范围包括白城、大安地区，后反正，但期间有附逆行为。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c8bfcf7c537a41cf94f7731a4beb8717','3c793b1442ef48298a262b0d57814cab',1932,'伪满黑龙江省警备司令','原黑龙江省防军旅长，投敌后任伪职，在洮南（白城）地区协助日军镇压抗日义勇军。；原黑龙江省骑兵师长，1932年随马占山投日，后任伪省警备司令，马占山反正后仍效忠日军，参与围剿抗日部队。；原马占山部属，投日后任伪军司令，在肇州、安达一带围剿义勇军。；原马占山部将，随马占山投日后，在齐齐哈尔、绥化等地协助日军进攻抗日义勇军。；原马占山部旅长，1932年随马占山投日，后任伪警备司令，在齐齐哈尔、富裕一带协助日军围剿抗联','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('79ac3fc026dc4c72b6a0b006f82bd8d9','12571fd3a6fa42cf9581b18a4b27a94e',1933,'伪满第3军管区司令官（驻齐齐哈尔，辖白城）','原东北军团长，投敌后任伪满军职，其辖区包括白城、大安，多次派伪军配合日军扫荡抗联。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('06165b45e0ee4b2cb0323c1681caea2f','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洲国洮辽警备司令、伪满军政部大臣','原东北军将领，九一八后投敌，在洮南、白城一带镇压抗日武装，协助日军建立伪政权，后任伪满军政部大臣，积极推行日满亲善政策。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('da42f99d8d614255bee349ac23aad91b','875c22d678e24c21834a32caae69933c',1931,'伪满洲国财政部总长、宫内府大臣','原吉林副司令长官公署参谋长，1931年叛变投日，引日军占领吉林市，其势力影响吉林全省，包括白城、洮北地区，参与建立伪满政权。；原吉林副司令长官，九一八后投敌，曾协助日军占领吉林全省，其势力范围覆盖辽源、东辽，参与组织伪军对抗抗联。；九一八事变后投靠日本，促成吉林地区迅速沦陷，积极推行伪满殖民统治，参与经济掠夺和奴化教育。；原吉林副司令长官，率先投日，促成吉林沦陷，后长期任伪满高官。；辽宁沈阳人（满族），原吉林军参谋长，投日后任伪满财政总长，参与经济掠夺，影响大连港贸易及税收。；清室后裔，投日后任伪满高官，曾参与策划对辽宁南部（含盘锦、大洼）的军事“讨伐”，并协助日军掠夺当地资源。；原吉林副司令长官，投日后虽主要活动于吉林，但曾参与辽宁地区伪军整编，协助日军控制辽西走廊。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6b1dfad6b61748ba84135ebfc0763305','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满洲国奉天警备司令、治安部大臣','原东北军旅长，投日后曾参与对吉林西部（白城、洮南）抗日义勇军的围剿，后任伪满治安部大臣，镇压抗日力量。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5bd7981b40c343029dc69a086ddbc252','c0860f9060d74dfba1674157f4596712',1931,'伪满洲国吉林警备司令、第1军管区司令','原吉林陆军第5旅旅长，投日后负责吉林全省治安，多次派兵在白城、洮北地区清剿抗日游击队，杀害抗日军民。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a751bef60ac941759559f3f1e361035c','3a9e402192aa460fb51a927d874bb93e',1932,'伪满洮南县长、伪警察局长','在洮南（今白城洮北区一带）任伪职，为日军征粮派夫，抓捕抗日地下人员，协助日军建立保甲制度，欺压百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('54ef043faef641fd90164143d9dd988e','21853206ad2b417598d1af0b4b3a4782',1933,'伪满洮北县县长','在洮北地区（今白城市洮北区）任伪县长，推行奴化教育，强征劳工，配合日军“治安肃正”行动，残害抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f305354593af4bd48442f42199a9df43','77aa4951751342b79a81e38d021b4396',1931,'伪满白城子地区维持会会长','九一八后率先组织维持会欢迎日军，为日军提供白城地区情报和物资，帮助日军迅速占领洮南、白城等地。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aaf48719b2da4654aa97b0d756caf331','3cd55e29febc489d9f9a7f2f88db31bb',1932,'伪满洮南警备军团长','率伪军多次进攻白城、洮北抗日义勇军，烧毁村庄，屠杀抗日家属，是当地著名的汉奸武装头目。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6b10513ce776408e936ca11cc59f5c19','15bce57e594e4d2baa94695c4c20822e',1935,'伪满白城地区特务机关长','为日本关东军特务机关效力，在白城、洮北建立情报网，破坏抗日地下组织，逮捕并杀害多名抗日志士。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c06be223ef8f4e489ebc8a05e61a6f1e','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洮辽警备司令、伪满热河省省长','九一八事变后投靠日军，在洮南、白城一带镇压抗日武装，后任伪满热河省省长，协助日军统治热河地区。；原东北军将领，九一八后投敌，在洮南（今白城地区）一带组织伪军，镇压抗日武装，后任伪满热河省省长，协助日军进攻热河及冀东。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('210a44f7e6ad4977b46c9d60154981f3','875c22d678e24c21834a32caae69933c',1931,'伪满吉林省省长、伪满宫内府大臣','九一八事变时在吉林率先投降日军，建立伪吉林省政权，其统治区域包括白城、洮南等地，协助日军清剿抗日力量。；清朝宗室，九一八时在吉林投降日军，建立伪吉林省政权，积极协助日军殖民统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8637938fd01c45d4897365f1c8a4cfda','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满奉天省警备司令、伪满治安部大臣','原东北军将领，投日后在吉林西部及白城一带参与围剿抗日义勇军，后任伪满治安部大臣，负责镇压东北抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8aa17589d91c40edb15d6a85aa8dfea2','c0860f9060d74dfba1674157f4596712',1931,'伪满吉林警备司令、伪满陆军上将','原吉林陆军军官，投日后任伪满吉林警备司令，在洮南、白城地区多次率伪军进攻抗日游击队。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9c432295f8384641b36d5d6d3dc96274','3a9e402192aa460fb51a927d874bb93e',1932,'伪满洮南县长','在洮南任职期间，积极推行日伪殖民政策，强征劳工，协助日军建立保甲制度，镇压当地抗日民众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('27372f1936344806ad96aa0c075e8e66','21853206ad2b417598d1af0b4b3a4782',1933,'伪满白城地区警察署长','在白城地区充当日军鹰犬，多次带队搜捕抗日地下工作者，破坏抗日组织，残害无辜百姓。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('49110305869549df85a34c2075868dec','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满立法院院长（曾涉吉林西部事务）','作为伪满高层汉奸，参与制定镇压东北抗联的政策，其影响覆盖包括白城、洮南在内的吉林西部。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('50d67f2380cb405ab827f4cb67576dca','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满黑龙江省省长（曾管辖白城部分地区）','投日后任伪黑龙江省省长，其辖区包括今白城部分区域，推行日伪经济掠夺政策，强征粮食和物资。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('478a01374d554b8dbe05cf7737012439','41502657c6b84465aa2ff94e620ed234',1932,'伪满财政部大臣（曾参与吉林西部事务）','作为伪满财政高官，协助日本在洮南、白城地区实施经济统制，搜刮民间财富，支持日军战争。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1edf874a0ab248a3b345a8969b598d12','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满立法院院长（曾涉白城地区行政）','曾任伪满要职，参与策划伪满政权对白城等地的殖民统治，推行奴化政策。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1c9a5ade29f34b2caf58a3864db082df','1d67ff455ffc47b8addcc485beb0ca34',1932,'伪满第一军管区司令（辖白城地区）','原东北军旅长，投日后任伪满第一军管区司令，驻防吉林西部及白城一带，围剿抗联和抗日义勇军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d4d087de46d745e3a82582f3c87fea1d','2acf7a5b9b5341578e1066b27394b2eb',1934,'伪满治安部大臣（曾管辖白城驻军）','原东北军将领，投日后任伪满高官，参与指挥伪军对白城、洮南等地的“讨伐”行动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d02da03792344d3bb97fe1bb3e4e906e','8bd659b1a1f24d64ae2bf011c50d3980',1932,'伪满吉林警备军司令（活动于白城一带）','原吉林省防军军官，投日后任伪吉林警备军司令，多次率伪军在白城、洮南、开通等地清剿抗日力量。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('93cc2fba74e649dda62b491f0937241c','350822a1078340679fd657c16a793993',1937,'伪满吉林省政府省长（管辖白城地区）','伪满高级汉奸，任伪吉林省长期间，推行日军“治安肃正”政策，在白城地区强征劳工、建立伪警察体系。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('73ad332c2e6140d89c599d70d9b9b4e8','3eb966fdcf364389b5302ef8a669f7ac',1932,'伪满吉林省警务厅长（白城地区警务负责人）','负责白城地区伪警察机构，协助日军抓捕抗日志士，镇压白城、洮南等地民众反抗。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9b7dd8f6c97d42158bfb1428ca1cc0e3','b21d5a4d224a4173bdb0f2b366c98d70',1932,'伪洮安县（今白城）县长','投日后任伪洮安县县长，为日军征粮派夫，镇压当地抗日活动，推行保甲制度。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2571374f01a14f93bd5b4fbc56cf6991','77a789268c6f47b4a617cdb9e41180bd',1935,'伪满国务总理大臣（曾涉及白城地区行政）','伪满最高行政汉奸，虽驻长春，但通过伪国务院对白城地区下达各项殖民统治政策，支持日军“讨伐”抗联。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a24188fb70fc4810a161c76d18d5cbfc','875c22d678e24c21834a32caae69933c',1931,'伪满财政部总长、吉林地区投日首脑','原吉林省政府参谋长，九一八后叛国，协助日军占领吉林全省，其势力范围包括白城地区，为日军提供当地情报和伪军。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4651cc8aa65348f393a80f843fdfee84','caae33d173854bf0a1b2b4f0db4f585a',1932,'伪满吉林省长（早期）','投日后任伪吉林省长，管辖白城地区，推行“归屯并户”，制造无人区，破坏抗日根据地。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aba718e21fa54337ab757a5c406e0037','41502657c6b84465aa2ff94e620ed234',1935,'伪满吉林省长（中期）','继任伪吉林省长，在白城地区强化日伪统治，组织“自卫团”协助日军。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('357d07531bfb48a391f94ff67977a283','448cf19f40334f31b9f5d71d601929ab',1932,'伪洮南府知府（伪满时期）','在洮南（今白城下辖）任伪职，为日军提供粮秣，镇压当地抗日义勇军。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5effbd478c84459d9615805bd235f94b','142849ebf8614017a075f60e0d2e7e40',1933,'伪白城子（今白城）警察署长','充当日军鹰犬，在白城子地区大肆搜捕抗日分子，刑讯逼供，杀害多名爱国群众。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('142a37ca20364f59bc3c9786c5bea0c1','3cd55e29febc489d9f9a7f2f88db31bb',1932,'伪洮安县保安队长','率伪保安队配合日军“扫荡”白城周边村庄，烧杀抢掠，参与制造多起惨案。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('20c43707d08a4401981a3b437c4bb802','875c22d678e24c21834a32caae69933c',1931,'伪吉林省长官公署长官、伪满洲国财政部总长','九一八事变后率先投敌，组织伪吉林省政权，为伪满洲国成立和日本控制吉林地区提供关键支持。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4adbedf8a55e4b13b4cefcd17617f89b','77a789268c6f47b4a617cdb9e41180bd',1931,'伪满洲国参议府议长、伪满洲国国务总理大臣','原东北军将领，九一八事变后投敌，长期在伪满洲国高层任职，协助日本统治东北包括吉林、白城地区。；辽宁台安人，九一八事变后投敌，历任伪满洲国军政部总长、参议府议长、国务总理大臣等职，为伪满政权核心人物之一，其活动范围覆盖辽宁及锦州地区。；长期在伪满洲国任职，为日本侵略服务，虽主要活动于东北，但其伪政权与华北伪政权有联系，对陕西籍人员亦有招降纳叛行为。；原东北军将领，投靠日本后成为伪满核心人物，协助日军镇压东北及华北抗日力量，其伪政权与陕西宝鸡地区抗日后方形成对立。；投靠日本，在东北伪满洲国担任要职，虽主要活动于东北，但其伪政权与陕西同属北方，对全国抗日形势产生负面影响。；九一八事变后投敌，历任伪满要职，最终任伪国务总理大臣，全面推行日本侵略政策，统治范围涵盖黑龙江全省。；辽宁台安人，九一八事变后投敌，历任伪满军政部总长、参议府议长、国务总理大臣等职，是伪满洲国最高层汉奸之一，其伪政权统治覆盖黑龙江全境，包括伊春、大箐山地区。；原为奉系军阀张作霖部下，九一八事变后公开投敌，历任伪满参议府议长、军政部总长、国务总理大臣等要职，全面推行日本殖民政策，是伪满洲国最高级别的汉奸之一，对包括黑龙江在内的东北全境实行傀儡统治。；九一八事变后投敌，历任伪满军政部总长、国务总理大臣等职，是伪满政权核心汉奸之一，积极推行日本殖民政策，镇压东北抗日力量。；辽宁台安人，九一八事变后公开投敌，历任伪东北行政委员会委员长、伪满洲国参议府议长、军政部总长、国务总理大臣等职，是伪满洲国最高层汉奸之一。其伪政权统治范围覆盖黑龙江全境，包括伊春、铁力地区，当地伪县公署、伪警察、保甲体系均受其伪中央政权统辖。；辽宁台安人，九一八事变后投敌，历任伪满军政部总长、参议府议长、国务总理大臣等职，为伪满政权核心人物之一，其伪政权统治覆盖包括佳木斯在内的东北全境。；辽宁台安人，九一八事变后投敌，历任伪满洲国军政部总长、参议府议长、国务总理大臣等职，为伪满政权核心人物之一，其伪政权统治覆盖包括佳木斯在内的东北全境。；辽宁台安人，早年与张作霖结拜，九一八事变后公开投敌，任伪东北行政委员会委员长、伪满洲国参议府议长，后任伪满洲国国务总理大臣，全面推行日本殖民统治政策，为伪满傀儡政权核心人物之一，其势力与影响覆盖包括佳木斯在内的东北全境。；辽宁台安人，九一八事变后投敌，历任伪满军政部总长、参议府议长、国务总理大臣等职，为伪满洲国最高层汉奸之一，其伪政权统治覆盖黑龙江、佳木斯、抚远地区。；辽宁台安人，九一八事变后投敌，历任伪满洲国军政部总长、参议府议长、国务总理大臣等职，为伪满最高层汉奸之一，其伪政权统治覆盖包括佳木斯在内的东北全境。；辽宁台安人，九一八事变后公开投敌，历任伪满军政部总长、参议府议长、国务总理大臣等职，成为伪满政权核心人物之一，参与推行日本殖民统治政策。；辽宁台安人，九一八事变后公开投敌，历任伪东北行政委员会委员长、伪满洲国参议府议长、军政部总长、国务总理大臣等职，为伪满政权核心人物之一，其伪政权统治范围覆盖黑龙江地区，包括双鸭山、友谊一带。；辽宁台安人，早年与张作霖结拜，九一八事变后公开投敌，任伪东北行政委员会委员长、伪满洲国参议府议长、军政部总长，后长期任伪国务总理大臣，为伪满政权核心人物之一，参与推行日本殖民统治政策。；辽宁台安人，早年与张作霖结拜，九一八事变后公开投敌，任伪东北行政委员会委员长、伪满洲国参议府议长、军政部总长，后长期任伪满洲国国务总理大臣，成为日本殖民统治东北的最高傀儡之一，其伪政权统治覆盖黑龙江、大庆、杜尔伯特地区。；辽宁台安人，九一八事变后投敌，历任伪满洲国军政部总长、参议府议长、国务总理大臣等职，为伪满政权核心人物之一，参与推行日本殖民统治政策，其活动范围覆盖东北全境，包括今黑龙江大庆地区。；辽宁台安人，九一八事变后投敌，历任伪东北行政委员会委员长、伪满洲国参议府议长、军政部总长、国务总理大臣等职，是伪满洲国最高层汉奸之一，其伪政权统治覆盖黑龙江地区。；辽宁台安人，九一八事变后投敌，历任伪满军政部总长、参议府议长、国务总理大臣等职，为伪满政权核心人物之一，其伪政权统治覆盖包括黑龙江地区在内的东北全境。；辽宁台安人，九一八事变后投敌，历任伪满洲国军政部总长、参议府议长、国务总理大臣等职，为伪满政权核心人物之一，其伪政权统治覆盖黑龙江地区。；辽宁台安人，九一八事变后投敌，历任伪东北行政委员会委员长、伪满洲国参议府议长、军政部总长、国务总理大臣等职，为伪满最高层汉奸之一，其伪政权统治覆盖黑龙江地区。；辽宁台安人，九一八事变后投敌，历任伪满军政部总长、参议府议长、国务总理大臣等职，为伪满洲国最高层汉奸之一，其伪政权统治覆盖黑龙江地区。；辽宁台安人，九一八事变后投敌，历任伪满洲国军政部总长、参议府议长、国务总理大臣等职，为伪满最高层汉奸之一，其伪政权统治覆盖黑龙江地区，包括鹤岗、兴山一带。；辽宁台安人，九一八事变后公开投敌，历任伪东北行政委员会委员长、伪满洲国参议府议长、军政部总长、国务总理大臣等职，为伪满政权核心人物之一，其伪政权统治覆盖黑龙江地区，包括鹤岗一带。；辽宁台安人，九一八事变后公开投敌，历任伪满洲国军政部总长、参议府议长、国务总理大臣等职，成为伪满政权核心人物之一，其统治范围覆盖黑龙江地区，包括鹤岗、萝北一带的伪政权运作均受其影响。；辽宁台安人，九一八事变后投敌，历任伪满洲国军政部总长、参议府议长、国务总理大臣等职，为伪满最高层汉奸之一，其伪政权统治覆盖黑龙江、齐齐哈尔地区。；辽宁台安人，九一八事变后投敌，历任伪满洲国军政部总长、参议府议长、国务总理大臣等职，为伪满政权核心人物之一，参与推行日本殖民统治政策，其活动范围覆盖东北全境，包括黑龙江、齐齐哈尔地区。；辽宁台安人，早年与张作霖结拜，九一八事变后公开投敌，任伪东北行政委员会委员长、伪满洲国参议府议长，1935年起任伪满洲国国务总理大臣，全面推行日本殖民统治政策，是伪满洲国最高级别的汉奸之一，其伪政权统治覆盖黑龙江、齐齐哈尔地区。；辽宁台安人，早年与张作霖结拜，九一八事变后公开投敌，任伪东北行政委员会委员长、伪满洲国参议府议长、军政部总长，后长期任伪国务总理大臣，为伪满政权核心汉奸之一，其伪政权统治覆盖黑龙江、齐齐哈尔地区。；辽宁台安人，九一八事变后投敌，历任伪东北行政委员会委员长、伪满洲国参议府议长、军政部总长、国务总理大臣等职，是伪满洲国最高层汉奸之一，其伪政权统治覆盖黑龙江、齐齐哈尔地区。；辽宁台安人，早年与张作霖结拜，九一八事变后公开投敌，任伪东北行政委员会委员长、伪满洲国参议府议长、军政部总长，后长期任伪国务总理大臣，为伪满政权核心人物之一，其伪政权统治覆盖黑龙江、齐齐哈尔地区。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('68af929fd19c4bfe8d0be0c692b2b59c','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪奉天警备司令、伪满洲国军政部大臣','原东北军将领，投敌后率部配合日军镇压东北抗日武装，其伪军活动范围涉及吉林西部和白城一带。；九一八事变后投敌，组织伪军配合日军进攻辽宁东部抗日武装，长期在抚顺、本溪、通化一带镇压抗日力量，后任伪满军政部大臣。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4da92764668d419da422d6876f5efc17','c0860f9060d74dfba1674157f4596712',1931,'伪吉林省警备司令、伪满洲国尚书府大臣','原东北军吉林部队将领，九一八事变后投敌，参与组建伪吉林军，配合日军控制吉林及白城地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c987bd5f48ec4cb5ac56eeeaf3291e98','e913aea565d54f398ad14deb4526d3a9',1931,'伪满洲国交通部大臣','投敌后在伪满洲国任职，参与管理东北交通，便利日军对吉林、白城等地的军事和经济控制。；负责伪满交通建设，在长春（新京）及吉林地区修建军用铁路和公路，服务于日军侵略。；原吉长铁路局长，投日后任伪满交通部大臣，协助日军管理铁路，运输军需。；伪满要员，其交通政策与华北伪政权有联系，间接影响山东聊城地区。；原奉系铁路官员，投日后任伪满交通部长，控制东北铁路运输，服务日军军事调动。；原东北交通官员，投日后控制伪满铁路、公路，为日军军事运输提供便利。；辽宁营口人，原奉系官员，投日后任伪交通大臣，控制东北铁路及大连港运输，为日军军事运输提供便利。；原奉系官员，投日后主管伪满交通，曾主持修建通过盘锦、双台子地区的军用公路和铁路，便利日军军事运输；负责伪满交通建设，在营口、大石桥地区修建军用公路和铁路，服务日军运输。；负责伪满交通，在绥中地区修建军用公路和铁路，便利日军运输。；原东北交通委员会负责人，投日后负责伪满交通，在辽宁及葫芦岛地区修建战略公路、铁路，服务日军侵略。；原东北交通委员会成员，投日后负责伪满交通，在黑龙江修建军事铁路供日军使用。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('74e7c36801de47d0b22ddd2342c7691d','af99649b3f3a4c5382ec79666bf2647d',1931,'伪满洲国邮政总局局长、伪满洲国交通部大臣','长期在伪满洲国交通、邮政系统任职，协助日本控制东北通信和交通网络，涉及吉林白城地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('26092bd31e5840728ef74017db3d88af','360451ccb61f491bafdc1b28af3c6799',1931,'伪满洲国文教部大臣、伪满洲国经济部大臣','在伪满洲国文教和经济部门任职，推行奴化教育 and 经济掠夺政策，影响吉林、白城等地。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('134a3afcba3341e9ba6f06dc95bf2268','9d25e1d3d8e543ee84de82f230352248',1931,'伪满洲国新京特别市市长、伪满洲国经济部大臣','投敌后在伪满洲国任职，参与经济统制和物资掠夺，其政策覆盖吉林、白城地区。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('44ec3cada9924584a1262a91740f8c50','3b74f508628f475a8777ffb7e38a48a0',1931,'伪满洲国滨江省省长、伪满洲国经济部大臣','投敌后历任伪省长和伪部大臣，协助日本在东北包括吉林地区推行经济掠夺和殖民统治。','省部级/大军区级要员','hanjian');
