INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('47e7b3e316164069be432f066049d305','3954cf6c52e9432eae4f94e815aa72ef',1931,'伪满洲国间岛省省长、伪满洲国经济部大臣','投敌后在伪满洲国任职，参与吉林地区殖民统治和经济掠夺。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1f8fd4ee688048bbb52a4cfde1a1dd6a','41502657c6b84465aa2ff94e620ed234',1931,'伪满洲国吉林省省长、伪满洲国财政部大臣','曾任伪吉林省省长，协助日本控制吉林地区财政和经济，影响白城一带。','省部级/大军区级要员','hanjian');
