INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c4444e509af541f58472a8649a90e534','f4208529cb14438593c9984febac079f',1931,'伪兴安南省警备军司令、伪满洲国兴安局总裁','蒙古王公出身，投敌后组建伪兴安军，配合日军在吉林西部、白城及内蒙古东部镇压抗日武装。','基层头目','hanjian');
