INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('406017b9f8d442e7af3d7d1f9d60c5b5','177c17b9b440453fa41ed47b9ebbd502',1931,'伪军司令、伪满洲国热河省警备军司令','土匪出身，投敌后率伪军活动于热河、吉林西部一带，配合日军骚扰抗日根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('52721c27988f4a799229c388edb6da84','5f82d23ccd2e45fd9e59f76c92bcc9ad',1931,'伪蒙古军总司令、伪满洲国兴安军管区司令','投敌后组建伪蒙古军，在吉林西部、白城及内蒙古东部配合日军作战，镇压抗日武装。；热河地区投敌的蒙古族军阀，后任伪蒙古军总司令等职，配合日军在东北、内蒙古地区镇压抗日力量。其伪军活动曾涉及黑龙江西部及小兴安岭周边，与伊春、铁力地区有间接关联。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('df56a66a6cba42d383db069e417349cf','c9dffc071fec4ce58fe1d611f26c28da',1931,'伪白城子警察署署长、伪白城县警务科科长','在白城地区担任伪警察头目，协助日军搜捕抗日人员，推行保甲连坐，镇压当地民众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('daeaa8f32ca3424899e348fe5a6c9a96','1ba31d558b934fbd83a28a8c2b446022',1931,'伪洮辽镇守使、伪满洲国热河省警备军司令','原东北军将领，投敌后率部配合日军进攻吉林西部和白城地区，镇压抗日武装。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('30853c60c99148588003ba9ea63b85fb','3c793b1442ef48298a262b0d57814cab',1931,'伪黑龙江省警备军司令、伪满洲国军政部大臣','投敌后率伪军配合日军控制黑龙江和吉林西部，其活动范围接近白城地区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('49f48858ae3a48f48f104f65604038c1','b8f5150658fd47f0a48c92aacb628181',1932,'伪黑龙江省省长（后反正抗日）','曾短暂投敌任伪黑龙江省省长，后反正抗日；其投敌期间伪政权影响涉及吉林西部和白城一带。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('171548d769d947338fd2a0fdb7a4c349','350822a1078340679fd657c16a793993',1932,'伪满吉林省长','原吉林地方官员，投日后任伪满吉林省长，推行日本殖民政策，强征劳工，镇压抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e14310af46a84f64afeaef4dd59533f5','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1935,'伪满白城地区警务处长','在白城地区担任伪警务处长，协助日军建立保甲制度，搜捕抗日地下人员，参与“讨伐”抗日武装。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('80e9340cf03f4f5bbaf338cd2e341aa3','21853206ad2b417598d1af0b4b3a4782',1932,'伪满镇赉县县长','任镇赉县伪县长期间，强征农民土地，推行“粮谷出荷”，配合日军清乡，迫害当地抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d9e58bec89204256a8d92a8513c06348','9f6435babca8474caa7e795c474b02fa',1933,'伪满白城地区保安团长','组织伪保安团，多次参与围剿抗日游击队，在洮南、白城一带杀害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('88963990bd9a4a08b4d90e864481ceda','41502657c6b84465aa2ff94e620ed234',1931,'伪满吉林省警务厅长','原吉林警察头目，投日后任伪省警务厅长，建立特务网络，破坏抗日组织，逮捕爱国人士。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('68738f21e4bb4f61ad4641be799c09a0','2acf7a5b9b5341578e1066b27394b2eb',1931,'伪满治安部大臣','原东北军旅长，投日后任伪满治安部大臣，指挥伪军在白城、镇赉等地“讨伐”抗日联军。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c3a2dc9158574eeb84eb8d3ffc004369','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满洮南地区警备司令','驻守洮南（今白城一带），多次率伪军袭击抗日义勇军，烧毁村庄，屠杀百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f230f891be2e4ad2a0c57e3800bf8596','3cd55e29febc489d9f9a7f2f88db31bb',1936,'伪满镇赉县警察署长','在镇赉县残酷镇压抗日活动，抓捕并杀害多名抗联交通员，强征劳工修筑军事工事。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5d9025bb8db341b1878f8c0ce098fd75','fd2c5f0abda941079651ec9eb1cc5c31',1937,'伪满白城地区宪兵队长','指挥伪宪兵在白城、镇赉一带搜捕抗日分子，严刑逼供，制造多起惨案。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9181dcea8d9440bc8f42b101e8962c67','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满洲国军政部大臣、伪奉天警备司令','原东北军将领，1931年后投降日军，参与镇压东北抗日武装，长期在伪满军中担任高级职务，是伪军系统重要头目。；辽宁台安人，原东北军将领，1931年投敌，历任伪奉天警备司令、伪军政部大臣等职，率伪军镇压辽宁抗日武装。；原东北军将领，1931年后投敌，任伪奉天警备司令、伪军政部大臣等职，率伪军配合日军在东北包括黑龙江地区进行围剿抗日武装。；原东北军将领，九一八事变后投敌，任伪奉天警备司令、伪满洲国军政部大臣，统辖伪军配合日军镇压东北抗日武装，其伪军活动范围覆盖黑龙江、大庆一带。；辽宁台安人，原东北军将领，1931年投敌，历任伪奉天警备司令、伪满军政部大臣等职，率伪军镇压东北抗日武装，活动范围包括黑龙江地区。；原东北军将领，1931年后投敌，历任伪奉天警备司令、伪军政部大臣等职，参与镇压东北抗日武装，其伪军活动范围涉及黑龙江、齐齐哈尔一带。；辽宁台安人，原东北军将领，九一八事变后投敌，历任伪奉天警备司令、伪满洲国军政部大臣等职，率伪军配合日军镇压东北抗日武装，活动范围包括黑龙江地区。；原东北军将领，1931年投敌，历任伪奉天警备司令、伪满洲国军政部大臣等职，率伪军配合日军镇压东北抗日武装，活动范围包括黑龙江地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a79fea6c278c4a24a4958bbb2c18bb11','c0860f9060d74dfba1674157f4596712',1931,'伪满洲国吉林省警备司令、伪满军政部大臣','原东北军吉林部队将领，随熙洽投敌，参与组建伪吉林军，镇压吉林、白山地区抗日力量，后任伪满军政部大臣。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('670d8f53a6eb4b71b910a41371f28c9f','b21d5a4d224a4173bdb0f2b366c98d70',1930,'伪吉林省公署厅长、伪通化省省长','在伪吉林省、伪通化省任职，协助日军推行保甲、集家并屯和治安肃正，对白山、通化一带抗日根据地造成破坏。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('78ca61bf6efd4314935b03e56b601b85','db75fdf090814fd8944c2f268193bf69',1930,'伪临江县县长、伪通化省官员','在临江、通化等白山周边地区任伪职，配合日军实施经济封锁、保甲连坐和情报搜集，镇压当地抗日民众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8ba1e6a387df42ee99d9c7ca2258b5b3','62624699627c4e00b365d5f12508b94b',1930,'伪抚松县县长','在抚松地区推行伪满政令，协助日军征发劳工、物资，参与对长白山抗日游击区的封锁与围剿。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5abf96ce6b5341fd85c860a50798f89e','7d0260b3409645639620a7b37d0c8f5f',1930,'伪濛江县县长','在濛江（今靖宇）地区任伪县长，配合日军对杨靖宇部抗日联军进行围剿，参与保甲、归屯并户等殖民统治措施。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5341b2e3e98544f3a932c4bb785e5f42','338628f1c81b466eaa07f94c29339381',1930,'伪长白县县长','在长白县任伪职，协助日军控制中朝边境，封锁抗日联军补给线，镇压当地抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aa5093d3323c42edb7e9e802b4afd4f0','d9bb7f270e97437ba2d41b2afdb1e972',1930,'伪军团长、伪通化地区警备头目','原土匪武装头目，投靠日军后任伪军团长，在通化、白山、临江一带疯狂围剿抗日联军，后被抗日联军击毙。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('af5064d808b34536b37b64074a67d91e','21853206ad2b417598d1af0b4b3a4782',1930,'伪军司令、伪安图地区警备头目','投敌后组织伪军，在长白山周边地区配合日军讨伐抗日武装，参与制造多起屠杀和烧村事件。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2e9d99405cea4a5a8b6ad42047e56953','5b5a96ec971749d098a69b71889fb400',1930,'伪通化省警务厅厅长','掌管伪通化省警察系统，推行治安肃正，组织伪警察队配合日军围剿抗日联军，镇压白山地区民众。','市县厅局级','hanjian');
