INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2f474f13144c435b99193220fe065fd8','9371eb94ef6548c6887387e706c61a27',1930,'伪满洲国协和会中央本部要员、伪吉林省官员','在伪满协和会系统担任要职，参与对吉林、通化、白山地区民众的殖民宣传和思想控制。','无明确职位或一般帮凶','hanjian');
