INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0198da9cce4b4731b1522eb45632aaca','acf7dcdffeda4a0a87c947be2dd7f78a',1930,'伪满洲国文教部大臣','推行日本殖民奴化教育，在吉林、通化、白山等地学校强制日语教学和亲日思想灌输。；伪满文教部大臣，推行奴化教育，其教育政策覆盖黑龙江各地包括大庆地区，毒害当地青少年。','无明确职位或一般帮凶','hanjian');
