INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cba62c0eb6e04798a62e9b42d796d827','ba135ba1ef794aeba0fdad0065a31974',1930,'伪临江县维持会会长','日军占领临江后组织维持会，为日军筹粮筹款、提供情报，协助建立伪政权。','基层维持会/地方自治头目','hanjian');
