INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('29112d1346da49a98d65b3928c6a8124','e5ff2b454eba4117a505af9540a764ef',1930,'伪长白县协和会会长','在长白地区开展协和会活动，进行亲日宣传、劳工征发和情报搜集。','基层头目','hanjian');
