INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7e155284ff0845f5a257084fa44f2a6b','90680bd6f72e42f4b7f1458e6c254836',1930,'伪通化县县长','在通化县任伪县长，配合日军治安肃正，实施保甲连坐和物资统制，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e3fda70e634f40448df3c34bce4f9da9','25e14c6523f347349389d63d8a7056ac',1930,'伪通化省警务厅特务','从事情报和抓捕活动，破坏中共通化、白山地区地下组织，迫害抗日人员。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('03508de2456545d492722b8127258c65','350822a1078340679fd657c16a793993',1930,'伪满洲国吉林省长、伪司法部大臣','在伪吉林省长任内推行日本殖民法令，镇压吉林、通化、白山地区抗日运动，后任伪满司法部大臣。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('17b2a913fe564bec8a3115c8533147a6','3eb966fdcf364389b5302ef8a669f7ac',1930,'伪满洲国吉林省长、伪司法部大臣','历任伪吉林省长等职，协助日军实施治安肃正和经济掠夺，对白山地区抗日力量进行镇压。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('97ef9daa43db4de8bcd1aa38957e5dfd','3954cf6c52e9432eae4f94e815aa72ef',1930,'伪满洲国经济部大臣、伪吉林省官员','参与伪满经济统制，在吉林、通化、白山地区推行物资配给和资源掠夺政策。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('be4e2c630b91498eb4fb03c483050249','d9bb7f270e97437ba2d41b2afdb1e972',1932,'伪满东边道讨伐司令','原土匪头目，投日后任伪满东边道讨伐司令，活动于吉林、白山、临江一带，专门围剿抗联，曾多次与杨靖宇部交战，后于1938年被抗联击毙。；原东北军军官，投日后任伪满东边道讨伐司令，专门在通化、梅河口一带追击杨靖宇抗联，后因作战不力被日军毒杀。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e65350092d114e108d329eb7c38c9ffc','3a9e402192aa460fb51a927d874bb93e',1935,'伪满通化省警务厅长','伪满通化省（辖今白山、临江地区）警务厅长，组织警察和特务，配合日军推行“归屯并户”，切断抗联与群众联系，抓捕并杀害大量抗联地下工作者。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2d7b19ef0e3d46388a3bac8427922af6','e61b7012a0b742d7ba5768b424516445',1932,'伪满临江县县长','伪满临江县（今临江市）县长，积极推行日伪殖民政策，强征劳工修建警备道路和碉堡，协助日军“讨伐”抗联，并参与镇压当地民众反日运动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('485f765d1b534d2d94c766278263c1e8','0ffd03d7727147fcabefe08f384204dd',1936,'伪满抚松县警务科科长','在抚松县（今属白山市）任职期间，多次率警察队袭击抗联密营，逮捕并刑讯抗日群众，提供情报给日军，导致抗联多处秘密联络点被破坏。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('16a23064bfd442d5a2b8ecc167dce68d','b362faface5242b8b18c07756afaa2f9',1937,'伪满长白县协和会会长','在长白县（今属白山地区）担任协和会会长，积极宣传“日满亲善”，组织汉奸团体刺探抗联情报，并参与“治安肃正”行动，迫害抗日家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bcb00becb1224d6992502f42e2eb5392','aea3838771d8458ba6073d341943bb27',1933,'伪满靖安军团长','伪满靖安军（驻吉林地区）团长，多次率部参与对白山、临江一带抗联的“大讨伐”，烧毁村庄，抢夺粮食，杀害抗联伤员和百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c10544d74dc148cc810acf36ca5040a9','3260a4da10c443ba839c918719b9646a',1938,'伪满通化省地方保安局局长','在通化省（含白山、临江）任保安局长，建立地方汉奸武装，配合日军封锁山区，并亲自审讯、杀害被俘的抗联战士和进步群众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('faea3b62748445dea1d61c9b6e642cab','257bc97b2b934e538c388d33e09f39d4',1932,'伪满吉林市警察厅厅长','在吉林市任职期间，大肆搜捕抗日分子，向日军提供抗联活动情报，并参与“集团部落”建设，迫使山区居民迁移，孤立抗联部队。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5ad1b3b3858045e3bde49e4e49bf72bb','3a9e402192aa460fb51a927d874bb93e',1932,'伪抚松县县长','投靠日军，任伪抚松县县长，协助日伪推行“治安肃正”，镇压抗日武装，强征劳工，掠夺当地资源。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4e252d6820824eb1a33f6e87fffe6cbf','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满热河省省长（原吉林籍，曾活动于白山地区）','原东北军将领，九一八后投敌，任伪满要职，曾参与对吉林、白山地区抗日联军的围剿，屠杀抗日军民。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2a0d97d4798a4f0d911d7a052dbef90a','1d67ff455ffc47b8addcc485beb0ca34',1932,'伪满第一军管区司令官（管辖吉林、白山地区）','原东北军旅长，叛变投日，任伪满第一军管区司令，指挥伪军多次“讨伐”抚松、白山一带的东北抗联部队。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bf64d7c91e8a44599fc677174550806b','2acf7a5b9b5341578e1066b27394b2eb',1932,'伪满吉林警备司令官','原吉林军将领，投日后负责吉林地区“剿匪”，在抚松、靖宇等地设立“集团部落”，制造无人区，迫害百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d964526af38d4bbdbf25710f2ac4cdb9','31f5d1beddc247798a41ecf2ef35664c',1933,'伪抚松县警务科科长','充当日军爪牙，组织伪警察队，搜捕抗日地下工作者，参与“三光”政策，残害抚松地区群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('75b97fb4cdff4fda8a75b973c66d6bca','21853206ad2b417598d1af0b4b3a4782',1935,'伪满吉林地区“讨伐队”队长','率伪军常驻白山、抚松山区，专门袭击抗联密营，杀害抗联伤员和百姓，烧毁村屯。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('750ea9b2e8d34253875d4c8f9e4350e3','ab3dded23c7447adb919b9a8705e1bf9',1937,'伪抚松县协和会会长','为日伪宣传“王道乐土”，组织汉奸团体，强迫民众捐献物资，告密抗日分子，导致多人被捕牺牲。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('000366d305d8431fad33059c3401871d','1733efb4824a42ddbf9cb8c18b981fa4',1934,'伪满吉林山林警察队队长','率山林警察在白山、抚松林区设卡，截断抗联补给线，参与诱降和暗杀抗联干部。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ecdf84d0e1814d84b38c90fa8fac2ef2','2acf7a5b9b5341578e1066b27394b2eb',1932,'伪满吉林省政府省长、伪满交通部大臣','原东北军将领，投日后任伪满吉林省省长，管辖范围包括今吉林市、通化、白山等地区，推行殖民政策，强征劳工，配合日军清剿抗日游击队。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f19501009e794f538b35885ce9e0385f','31f5d1beddc247798a41ecf2ef35664c',1937,'伪满通化省省长（辖区含今白山、江源）','原东北地方官员，投日后任伪满通化省省长，直接管辖今白山、江源一带，推行“集团部落”政策，制造无人区，协助日军围剿杨靖宇等抗联部队。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c49692fcd8194e69a26b8bec5a4e5ec7','3951963964a94498a774c966bfe9bc97',1935,'伪满通化省警务厅厅长','原奉系警察头目，投日后任伪满通化省警务厅厅长，在江源、临江等地建立特务网络，多次参与抓捕抗联地下交通员，直接迫害当地抗日群众。；原东北警察，投日后任伪满通化省警务厅厅长，组织特务和警察抓捕抗联地下人员，破坏抗日组织，在梅河口一带残害百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7bc1c15590e348c6bec038710152ae21','3a9e402192aa460fb51a927d874bb93e',1936,'伪满通化省保安队队长','原土匪头目，投日后任伪满通化省保安队队长，率汉奸武装在江源、抚松一带烧杀抢掠，配合日军“大讨伐”，杀害抗联伤员及支持抗联的百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8f3b7629ec23495babf4f556fc4d50bc','21853206ad2b417598d1af0b4b3a4782',1932,'伪满临江县（今白山江源区）县长','原临江县地方士绅，投日后任伪县长，强制推行“保甲连坐”，强征民夫修筑警备道路，多次向日军报告抗联活动情报，导致多处抗联密营被毁。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('26570171320a4dc6a22ecec6f95d1dcf','ab3dded23c7447adb919b9a8705e1bf9',1933,'伪满抚松县（今属白山）警察署署长','原抚松县警察，投日后任伪警察署长，在江源、抚松边界多次伏击抗联小分队，亲手杀害抗联战士多人，并参与“归屯并户”迫害村民。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b9799871058641edb0c00e4adf74a8ef','599d91e5861b49d89d9656e0812bf1a3',1938,'伪满长白县（今属白山）协和会会长','原长白县商人，投日后任协和会会长，为日军筹集粮饷，组织“宣抚班”瓦解抗联意志，并告密导致抗联联络站被破坏，多名交通员牺牲。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d7e6b6785a5f43c69ca1273651cd2213','589ab27feed347c6944e6c001125dc02',1937,'伪满通化省省长','原奉系官员，投敌后任伪满通化省省长（辖今白山、浑江地区），推行“集团部落”政策，制造无人区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ec16c727ea5c44ba9f48def17281e383','3951963964a94498a774c966bfe9bc97',1932,'伪满通化省警务厅长','原东北军军官，投日后任伪满通化省警务厅长，指挥伪警察围剿杨靖宇等抗日联军。；原东北军军官，投日后在通化、白山地区组织伪警察队，多次参与对抗日联军的“讨伐”行动。；原通化地区警察头目，投日后任伪满通化省警务厅长，组织警察队和特务队，多次参与围剿抗联，在集安一带制造多起屠杀事件。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('43333b10cda7439fbe36b655375e001f','d9bb7f270e97437ba2d41b2afdb1e972',1933,'伪满通化地区讨伐队长','原土匪头目，投日后任伪满通化地区讨伐队长，多次率部袭击抗日联军，杀害抗联战士，后被抗联击毙。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('29366025c4ae460ca8ea6e286eb716fa','c59f373a897d4178ab10e417b811be44',1938,'伪满通化省警察大队长','原抗联第一军第一师师长，1938年叛变投敌，任伪满通化省警察大队长，熟悉抗联情况，多次带日军破坏抗联密营。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a013a536073e4bb5bc96f7c29fcc4d8a','55c4927d9e4a41deb7080d12f0db3b2a',1940,'伪满通化省保安团长','原抗联干部，叛变后任伪满通化省保安团长，参与围捕杨靖宇将军，提供关键情报。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('410b88a2e3744533a5567a3f4dddae7e','50d91bce55c44eca9317a74f1edfc03a',1939,'伪满浑江地区自卫团长','原地方豪绅，投日后组织自卫团，配合日军在浑江流域“讨伐”抗联，烧毁民房，残害百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f9fb9de2e59e4abeaa77ea22b7207f54','0bb742c3fa5947b6826ad06890c95853',1932,'伪满临江县（今白山）伪县长','原临江地方官员，投日后任伪县长，推行日伪“治安肃正”，协助日军镇压当地抗日义勇军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e6e643effce64e8f957fd2a9c1700b00','08cf2daf57624bc0bd6648341fc817bd',1935,'伪满抚松县伪警察署长','原抚松县警察，投日后任伪警察署长，多次带队搜捕抗联交通员，破坏地下组织。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('72b264cce2ab4ffcbce5459063fbbf63','b362faface5242b8b18c07756afaa2f9',1936,'伪满长白县伪保安队长','原长白县民团头目，投日后任伪保安队长，配合日军在长白山地区“讨伐”抗联，杀害无辜群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('37759be16ac247379d6b2016ae53fd36','70cbcc058e6648678fa022e3a64b9cea',1937,'伪满通化省省长（后改称通化地区）','在通化省（辖今白山、长白）推行“集团部落”，制造无人区，配合日军围剿杨靖宇部。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4ab557c7c56f4ad0ae7febe64febb1b0','e61b7012a0b742d7ba5768b424516445',1932,'伪满长白县县长','在长白县任伪县长，强制推行“归屯并户”，烧毁民房，切断抗联与群众联系。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('29f0212f906a4c0aae548c3ffbea0793','0ffd03d7727147fcabefe08f384204dd',1933,'伪满临江县（今白山）县长','在临江地区积极执行日伪“治安肃正”政策，抓捕抗日群众，提供情报给日军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f3ebdcbdf3a1455fa8d96663b0a17a2f','6a27ced07c2b45059759de8f69010e3c',1935,'伪满抚松县（属白山）警务科长','在抚松县组织伪警察，多次袭击抗联小分队，杀害抗联伤员和联络员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('588227115a3e4cb68c2f7bd77f3d92c3','599d91e5861b49d89d9656e0812bf1a3',1936,'伪满靖安县（今靖宇县，属白山）保安队长','率伪保安队配合日军在濛江（靖宇）地区搜山，直接参与围捕杨靖宇将军的行动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('870dc94416514382879fae94788bdd4c','3a9e402192aa460fb51a927d874bb93e',1932,'伪靖宇县警务科科长','在靖宇县（原濛江县）任职期间，积极协助日军“讨伐”东北抗日联军，多次率伪警察队袭击抗联密营，抓捕并杀害抗联战士及地方群众，是杨靖宇将军牺牲时的直接围捕参与者之一。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e4f6ba956510492dba0dbf015b276afc','c59f373a897d4178ab10e417b811be44',1938,'伪通化省警察厅警佐、伪“讨伐”队队长','原东北抗联第一军第一师师长，1938年叛变投敌。叛变后组建伪“程斌讨伐队”，熟悉抗联战术，多次带日军在濛江（今靖宇）、抚松、桦甸等地破坏抗联密营，切断补给，直接导致杨靖宇部陷入绝境。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('99f4fc31554b4a8fa2a112e8d460dbfd','8aa328dd41d14eecb422bf7558488c93',1940,'伪“讨伐”队向导、叛徒','原为抗联第一军警卫排排长，1940年2月携带机密文件及枪支叛变投敌，向日军供出杨靖宇的行踪和密营位置，引导伪军警在濛江县三道崴子包围杨靖宇，是杨靖宇牺牲的关键告密者。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('43dc3e8341414bbd86d3b8efbb192e71','0be7d095e845405b99dd69ba4ef9aa84',1940,'伪濛江县保安队队员','1940年2月23日在濛江县保安村附近发现杨靖宇，后向日军告密并引导日伪军包围，直接导致杨靖宇将军被杀害。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('55de61282f2a4651b5e549b3e518c1dc','bfcbdf91d0714612bef9262266f4db26',1939,'伪濛江县警务科警尉','长期参与对靖宇地区抗联部队的“围剿”，多次率伪警察搜山、烧毁密营，逮捕抗联交通员，并参与对杨靖宇牺牲后遗体的辨认和处置。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0bd9c8b89b134792bdbcdd932c58bcd2','b08a977fca6f4cf3872153ece948e00b',1938,'伪濛江县警察署署长','在濛江（今靖宇）地区积极推行日伪“保甲连坐”制度，组织伪警察配合日军“大讨伐”，多次抓捕抗联地下工作者和爱国群众，是当地有名的汉奸头目。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b9d0d5d36fcb4fafa2c7fa6f8721a2bc','23a720dc726b4d8bb3ca6975071c001f',1941,'伪靖宇县协和会会长','在靖宇县宣传“日满亲善”，强迫民众捐献物资支援日军，并组织“协和义勇队”协助日伪军警搜捕抗联残余人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c14c68230935422eb22804b351988fe4','715be267e9314951b3ffef123ae47054',1937,'伪抚松县（今属白山市）警务科警佐','在抚松、靖宇交界地带多次率伪警察袭击抗联小分队，杀害抗联伤员，并参与破坏抗联在长白山区的后方基地。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3e2094b067834e979f4cc81c676cf86e','971d6063842b42c09458000fc5043c7a',1936,'伪临江县（今白山市临江）警务科科长','在临江地区残酷镇压抗日活动，多次组织“搜山队”围剿抗联，逮捕并杀害数十名抗联战士及支持抗联的农民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d19b1e26720344d789d1530481515665','1e54500c401c434486b34d8492fafd8c',1937,'伪长白县（今属白山市）警察署署长','在长白县配合日军“集团部落”政策，强迫村民迁入“人圈”，并率伪警察多次袭击抗联密营，烧毁粮食和物资。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ca12c821e6d34177ab5b3f462a3f8fe3','3951963964a94498a774c966bfe9bc97',1932,'伪磐石县警务局指导官','协助日军镇压磐石抗日游击队，多次参与“讨伐”杨靖宇领导的南满抗日武装，抓捕抗日群众并刑讯逼供。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0b61051249a4459c95b409094dcf1813','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洲国热河省省长（原籍磐石，曾活动于磐石）','九一八事变后公开投敌，在磐石一带招募伪军，配合日军围剿抗日义勇军，并参与建立伪满地方政权。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c9017553c46f4cc49167f142a58a6cc5','1d67ff455ffc47b8addcc485beb0ca34',1932,'伪满洲国军政部大臣（曾驻磐石地区）','作为伪满高级将领，指挥伪军多次对磐石玻璃河套、红石砬子等抗日根据地发动“大讨伐”，杀害抗日军民。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5dd9199a37d54bc4b1a3bc53450cd026','3a9e402192aa460fb51a927d874bb93e',1933,'伪磐石县保安队队长','率保安队为日军带路，破坏磐石地下党组织，参与制造“磐石惨案”，逮捕并杀害多名抗日联军联络员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('49cb41ba1e4a4025ba58495d760fc336','21853206ad2b417598d1af0b4b3a4782',1934,'伪磐石县警察署署长','积极推行“归屯并户”，切断抗日武装与群众联系，多次率警察袭击磐石抗日游击队营地，并实施“连坐”政策。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9be445b8305d43e69073d08c97df9c99','c772e3008dae44d1bf0d75c1a527b16c',1935,'伪磐石县协和会会长','组织汉奸宣传队，鼓吹“日满亲善”，搜集抗日情报提供给日军，并强迫百姓捐献物资支援伪军“讨伐”。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('783915e25bf04eda815ef3fe5becd670','234634910eee40ddbd3896c4f6989e7e',1932,'伪磐石县自卫团团长','率自卫团配合日军在磐石山区搜捕抗联战士，曾参与袭击杨靖宇部队后方医院，杀害伤员和医护人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1aca76272a504a42be47888aaa38ed33','599d91e5861b49d89d9656e0812bf1a3',1933,'伪磐石县司法科科长','审判并迫害抗日志士，以“反满抗日”罪名判处多人死刑或长期监禁，并协助日军建立“思想矫正院”。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1d2d30bda686489aaec04c1a88ac37be','aea3838771d8458ba6073d341943bb27',1934,'伪磐石县税捐局局长','为日军强征苛捐杂税，搜刮民财充作军费，并参与“粮谷出荷”政策，导致磐石地区百姓饿殍遍野。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('35563ab3372d427b80373eaf903b7e91','82c8dc8c68f3449d85ce6770c252b411',1936,'伪磐石县教育会会长','推行奴化教育，强制学校教授日语和“满洲国”历史，检举爱国教师，并组织学生为日军“献金”活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fb0fe5e6269241698952ff0b9f57177e','79b17193512846a1a5bde9f5df22c926',1931,'伪满洲国民政部总长、奉天省长','辽宁沦陷后投敌，历任伪满民政、参议等职，协助日军维持东北殖民统治。；原辽宁省政府主席，被俘后投敌，历任伪奉天省长、民政部总长、参议府议长，参与伪满殖民统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ac169125778340ddbdfd5285f67cc7bd','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满洲国军政部大臣、伪军上将','原东北军将领，投敌后组建伪军，参与围剿东北抗日武装，镇压抗日民众。','无明确职位或一般帮凶','hanjian');
