INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b1463fe57c8d4f5c852bef722f77e09e','3a9e402192aa460fb51a927d874bb93e',1932,'伪满西安县（今辽源市）县长','在西安县（今辽源市）任伪县长期间，强征民夫、搜刮粮食，配合日军“讨伐”抗日游击队，多次向关东军提供抗日人员情报，导致多名抗联战士被捕牺牲。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('724f06c21bbb42f1913e6fcdf17e047e','ab3dded23c7447adb919b9a8705e1bf9',1933,'伪满辽源县警务科长','在辽源县（今双辽市一带）组织伪警察队，参与围剿杨靖宇领导的抗联第一路军，曾率队袭击抗联密营，烧毁粮食和物资，并抓捕抗日群众送交日军宪兵队。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a45c4d628c3347e993b9bee201b5184c','21853206ad2b417598d1af0b4b3a4782',1934,'伪满西安县保安队队长','在西安县（今辽源市）组建汉奸保安队，配合日军“集家并屯”，制造无人区，多次参与对磐石、桦甸一带抗联游击队的“扫荡”，杀害抗联伤员和群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c96cc458429447ab801e6c24c70b2019','bedc991fdcff4254a3e2b0b24052d010',1935,'伪满辽源县协和会会长','在辽源县（今双辽市）推行奴化教育，组织“协和会”宣传“日满亲善”，强迫民众捐献铜铁支援日军，并告密检举反满抗日分子，导致多名爱国人士被捕。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('62632117242e444db85f69034e5b202a','af96068e274a4fdfb011573dd045f17a',1936,'伪满西安县宪兵队翻译','在西安县（今辽源市）宪兵队任翻译，参与审讯和刑讯抗日志士，多次歪曲供词陷害无辜百姓，协助日军制造多起惨案，如“西安县大逮捕”事件。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('52f9f49a9b574fb797905978e1751676','e406c61d49114819898f3c8c9a345092',1937,'伪满辽源县自卫团团长','在辽源县（今双辽市）组织自卫团，为日军提供劳力和情报，参与破坏抗联地下交通线，曾率团袭击抗联小分队，抢掠群众财物，并强征青年充当伪军。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('044ab5be44494d2aa40bc5fefb3ba189','b8f5150658fd47f0a48c92aacb628181',1938,'伪满西安县税务局长','在西安县（今辽源市）任伪税务局长期间，巧立名目征收“出荷粮”和“国防献金”，盘剥农民，导致当地粮荒，并将搜刮的物资无偿供给日军。','市县厅局级','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2398d65a30f54dd293375bd6cc3be0b8','aea3838771d8458ba6073d341943bb27',1939,'伪满辽源县警察署署长','在辽源县（今双辽市）警察署任职期间，多次率警队抓捕抗联交通员，破坏地下组织，并参与“归屯并户”，烧毁民房，造成大量平民流离失所。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8f7f8584649b4a6ca7fda918827446c0','3ecd2d6597904f268fe7636e66faec27',1940,'伪满西安县“讨伐队”队长','在西安县（今辽源市）率“讨伐队”多次进山搜剿抗联残部，曾于1941年在东辽河沿岸伏击抗联小分队，杀害抗联战士5人，并割下首级向日军邀功。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5933282845204ae397c279e2bee145b3','589ab27feed347c6944e6c001125dc02',1932,'伪满吉林省警务厅长','在吉林、辽源地区组织伪警察，协助日军搜捕抗日志士，镇压民众反抗。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('130ae63395f1460ebb92244a4dfa65e5','caae33d173854bf0a1b2b4f0db4f585a',1932,'伪满吉林省财政厅长','为日军在吉林、辽源地区征收苛捐杂税，掠夺资源，支持侵略战争。；在长春协助日本掠夺吉林粮食、矿产，强征捐税，压榨百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3a8107c5cbf04150bb8c37f1521322ff','350822a1078340679fd657c16a793993',1932,'伪满吉林省民政厅长','协助日军推行保甲制度，在龙山地区组织汉奸特务，破坏抗日地下组织。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('437adbc4ef26435497368313c0db5212','41502657c6b84465aa2ff94e620ed234',1932,'伪满吉林省教育厅长','推行奴化教育，在吉林、辽源学校中强制宣传“日满亲善”，抹杀民族意识。；在吉林推行奴化教育，强制学习日语，篡改历史教材。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('42885034f11d484c9b120af224a5d437','a984ebfabbf64a5b8e1dfef2d68daa53',1932,'伪满吉林地区警备司令','原东北军将领，投日后在辽源、龙山一带率伪军围剿抗日游击队，制造多起惨案。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ac02349dfd764c6bb3278420aa51c201','2acf7a5b9b5341578e1066b27394b2eb',1932,'伪满吉林省保安司令','在吉林、辽源地区指挥伪军“讨伐”抗日武装，屠杀无辜百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1e1571e1baf04003ab3d3a2f64c3be8c','21853206ad2b417598d1af0b4b3a4782',1933,'伪满辽源县县长','在辽源地区积极推行日伪政策，强征劳工，为日军提供粮食和物资。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3b9da463f6a7474785ed4234112f8ac4','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满龙山地区维持会会长','在龙山地区组织汉奸武装，协助日军维持治安，镇压抗日群众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('95e9b10e9b454e35ae81067bd82ee5e5','d9bb7f270e97437ba2d41b2afdb1e972',1931,'伪东边道讨伐司令','率伪军多次围剿杨靖宇领导的东北抗联第一路军，在通化、辑安（今集安）等地制造多起惨案，后因作战不力被日军冷落，1938年病死（一说被日军毒死）。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e7a960f5f51b4cc7836ec6d702a8b46d','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪通化省警务厅长','在通化地区推行保甲连坐制度，组织汉奸特务网，协助日军抓捕抗联地下工作者，参与“集团部落”建设，导致大量平民伤亡。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6cf86225b41c43629348f84f035cdd57','e61b7012a0b742d7ba5768b424516445',1933,'伪通化县县长','积极为日军征粮派夫，强征民夫修筑警备道路和碉堡，镇压当地抗日民众，曾亲自带队烧毁抗联联络点村庄。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dbc3027a52ea4bafad4d6498067d0900','54ed3d5811124de1a4f4c9e1d7ad39d8',1934,'伪东边道保安司令','率伪军配合日军“大讨伐”，在柳河、金川（今辉南）一带追击抗联部队，杀害抗联伤员及地方群众，后升任伪满少将。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a5f196ae86e649b1a77fd44b3ddecf7b','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满热河省警备司令（曾驻通化）','九一八后投敌，曾率部在通化、临江等地协助日军镇压抗日义勇军，其部队烧杀抢掠，民愤极大。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('374dd6958ee743e39fc6168ba060904b','1d67ff455ffc47b8addcc485beb0ca34',1932,'伪满第一军管区司令（辖通化）','原东北军将领，投日后负责通化、吉林地区“治安肃正”，指挥多次大规模围剿抗联，并推行“归屯并户”政策。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6615a30575504f9cace1a23eb10c9230','2acf7a5b9b5341578e1066b27394b2eb',1931,'伪满吉林警备司令（兼辖通化）','在吉林、通化地区组织伪军，配合日军进攻抗日武装，曾下令处决多名抗联嫌疑分子，是伪满早期重要军事汉奸。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('25821150447241c0afdb119e7f185819','350822a1078340679fd657c16a793993',1940,'伪通化省省长','任内强化日伪统治，推行“粮谷出荷”政策，搜刮民粮供给日军，并协助关东军镇压通化地区剩余抗联小分队。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('68792e75008b42eea71c392618a31991','3951963964a94498a774c966bfe9bc97',1933,'伪通化地区警备队队长','原为土匪头目，投日后充当日军鹰犬，专门负责搜捕抗联交通员，曾亲手杀害抗联第一路军后勤人员多人。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('53b63e10df3d41be8d2080a38932ed00','21853206ad2b417598d1af0b4b3a4782',1937,'伪通化省协和会本部部长','利用协和会组织进行奴化宣传，煽动民众告发抗联活动，参与组建“自卫团”，协助日军进行经济封锁。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3315be34f7894fd4a2f31dda82068dbe','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满热河省省长、伪满通化省省长','原东北军将领，九一八后投敌，历任伪满热河省省长、通化省省长，镇压抗日武装，推行日伪殖民政策。；原东北军将领，九一八后投敌，历任伪满热河省省长、伪满通化省省长，在通化地区推行日伪殖民统治，镇压抗日武装。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e3c9b796f41549df86ca157ba3307228','3a9e402192aa460fb51a927d874bb93e',1932,'伪满通化省警务厅厅长','在通化地区组织伪警察力量，多次参与围剿杨靖宇领导的东北抗联第一路军，残害抗日军民。；在通化、二道江地区组织伪警察和讨伐队，多次参与围剿杨靖宇领导的东北抗联第一路军，残害抗日军民。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('328b068425734ca8838f730cfb9fa735','cd2db705de474fed8b739e4ca61c47ae',1933,'伪满通化县县长','任伪通化县县长期间，强征劳工，推行“归屯并户”，协助日军制造无人区，破坏抗联根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c3823e8753a746c49d27baf2ba522a1c','de55e53c81594df6ae61cd5e2e30ac72',1935,'伪满东边道开发株式会社理事','参与日伪对通化、东昌地区矿产资源的掠夺，为日军提供战略物资，并协助经济封锁抗联。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0dd8681526aa4d268867dda451879208','ab3dded23c7447adb919b9a8705e1bf9',1937,'伪满通化省协和会事务长','在通化地区积极推行奴化教育，组织协和会宣传“日满亲善”，搜集抗日情报，破坏地下抗日组织。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a422530f0ea74c6f9b42baf9b884ea08','ba135ba1ef794aeba0fdad0065a31974',1938,'伪满东昌区保安队队长','率保安队多次袭击抗联小分队，抓捕并杀害抗日群众，烧毁村屯，配合日军“讨伐”行动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b949b28f569546a5bfd3abe2ca8eaa18','1733efb4824a42ddbf9cb8c18b981fa4',1938,'伪满通化省司法矫正局局长','管理通化地区矫正院，关押迫害抗日嫌疑犯及无辜百姓，实施非人虐待，致多人死亡。；在通化地区设立矫正辅导院，关押和虐待抗日嫌疑人员及普通百姓，强迫劳役，致多人死亡。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a4eca715fc5e4fcd9783bfd900718ff6','aea3838771d8458ba6073d341943bb27',1936,'伪满通化省宪兵队翻译官','为日军宪兵队充当翻译，参与审讯和刑讯逼供抗日志士，直接导致多名抗联联络员牺牲。；为日军宪兵队充当翻译，参与审讯和刑讯抗联被俘人员，多次带队指认抗联秘密联络点，导致多名地下党员牺牲。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c04924ccc394455f8f14b86ada6d8097','e61b7012a0b742d7ba5768b424516445',1933,'伪满通化县县长','任伪通化县长期间，强征民夫修建警备道路和碉堡，配合日军“归屯并户”，制造无人区，迫害抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fe59bb86088d45eabe6afb2c816026b8','ab3dded23c7447adb919b9a8705e1bf9',1934,'伪满二道江警察署署长','在二道江地区设立多个警察分驻所，抓捕抗联交通员和地下工作者，直接参与杀害抗联伤员和进步群众。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('58e754fb4439413ea1c1725ca9be8952','9b555462dae94e0a8839531af6b3d300',1935,'伪满通化省协和会事务长','在通化、二道江地区组织协和会宣传“日满亲善”，刺探抗联情报，协助日军进行“思想战”和“宣抚工作”。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4d9304abfc8447e29ddc7aee66449e25','ba135ba1ef794aeba0fdad0065a31974',1932,'伪满通化省保安队队长','率伪保安队在通化、二道江山区反复“扫荡”，烧毁抗联密营，杀害抗联后勤人员，曾参与诱捕抗联干部。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('85bf65cde1c9425a80c402b9fbc97ff8','77a789268c6f47b4a617cdb9e41180bd',1935,'伪满国务总理大臣（曾管辖通化地区）','作为伪满最高汉奸之一，其政策直接覆盖通化、二道江地区，支持“治安肃正”和“粮谷出荷”，加剧当地民众苦难。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('18f52f94ef6c43b5bed03a0ec278fe97','1d67ff455ffc47b8addcc485beb0ca34',1932,'伪满第一军管区司令官（驻通化）','率伪军驻防通化，多次组织大规模“讨伐”抗联，在二道江一带制造多起屠杀事件，是当地主要军事汉奸头目。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cbe820ad774d4ace83aa177667ae76fe','4a71ce857bc64724acfaa74f2868edfd',1932,'伪满吉林省公署警务厅厅长','在伪满吉林省任职期间，积极执行日本关东军命令，镇压抗日武装，抓捕并杀害多名抗日志士，协助日军推行“治安肃正”计划。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6c5448b45d694e1a9de174dc5b57255c','1d67ff455ffc47b8addcc485beb0ca34',1932,'伪满吉林省省长','投靠日本后出任伪吉林省长，协助日军建立伪政权，强制推行“保甲制度”和“连坐法”，残酷镇压通化、柳河地区的抗日游击队。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('48d30cb83dfe4275bfaf76e1bae13bb7','589ab27feed347c6944e6c001125dc02',1937,'伪通化省省长（后改称通化地区）','在通化地区任职期间，积极配合日军“讨伐”杨靖宇领导的东北抗联第一路军，组织汉奸特务搜集抗联情报，导致多支抗联小分队被围歼。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2a68d399b8f349eeb25ac07ad8e16070','257bc97b2b934e538c388d33e09f39d4',1938,'伪通化省警务厅厅长','指挥伪警察和特务在柳河、通化一带搜捕抗联地下联络站，亲自参与审讯和酷刑，杀害抗联战士及无辜百姓数百人。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2ac4a07211df4d5abd6200a9a8afe7d7','ab3dded23c7447adb919b9a8705e1bf9',1932,'伪柳河县县长','在柳河县推行日伪“归屯并户”政策，制造无人区，切断抗联与百姓联系，并组织汉奸武装“自卫团”配合日军扫荡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a0995493db224141848a6f37ae8e790c','21853206ad2b417598d1af0b4b3a4782',1933,'伪柳河县警察署署长','长期在柳河地区追捕抗联交通员，曾率警察队突袭抗联密营，抢掠物资，并杀害被俘的抗联伤员。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('27338472d38f4c41b55c4e2317d73c1a','af96068e274a4fdfb011573dd045f17a',1935,'伪通化县保安队队长','带领保安队多次参与对通化山区抗联部队的“围剿”，并负责在柳河边界设卡盘查，截获抗联运送的粮食和药品。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('628407c1bc1246d49b05bbf3770078f4','599d91e5861b49d89d9656e0812bf1a3',1936,'伪吉林省警务厅特务科科长','专门负责吉林、通化地区抗日分子的侦缉工作，建立庞大特务网络，曾策划诱捕抗联干部多名，并参与制造多起惨案。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0aa86c86034b4ec3845935f66c043b3e','aea3838771d8458ba6073d341943bb27',1939,'伪通化省协和会会长','利用协和会组织在通化、柳河进行奴化宣传，强迫百姓检举抗日分子，并协助日军强征劳工修筑军事工事。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e64c10f490cb4a069c27a880c99b2c26','17d3295e4953477490a5e308984d957d',1940,'伪柳河县警务科科长','在柳河县实施“连坐”政策，多次带队突袭抗联外围组织，逮捕抗日群众并移送日军宪兵队，导致数十人被处决。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b25078c8faad41798055c2120e74e4c6','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满热河省省长、伪满军事部大臣','原东北军将领，九一八后投敌，曾任伪满热河省省长，参与镇压抗日武装，后任伪满军事部大臣，在通化、梅河口一带协助日军清剿抗联。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f303fdbff0d5425498579afbb9c5f633','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满第二军管区司令官','原东北军营长，投日后任伪满第二军管区司令官，驻防吉林地区，参与“讨伐”南满抗联，在通化、梅河口一带烧杀抢掠。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2a81570a5bb14848bf897635fde51ca5','350822a1078340679fd657c16a793993',1937,'伪满通化省省长','满族汉奸，曾任伪满通化省省长，在通化、梅河口地区推行“集团部落”政策，协助日军围剿抗联，导致大量平民死亡。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e5d618782cc344ca854c86aab73fb32b','21853206ad2b417598d1af0b4b3a4782',1933,'伪满通化地区警备司令','原土匪头目，投日后任伪满通化地区警备司令，率伪军多次袭击抗联营地，在梅河口、柳河等地屠杀抗日群众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3be966c6b951449d9c7d3051ea4c0930','cd2db705de474fed8b739e4ca61c47ae',1938,'伪满通化省协和会事务长','汉奸文人，任伪满通化省协和会事务长，在梅河口、通化等地宣传“日满亲善”，组织奴化教育，协助日军征粮抓丁。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3cd93606e9ca4253af2b19ecf72cfb1f','54ed3d5811124de1a4f4c9e1d7ad39d8',1935,'伪满梅河口警察署署长','原地方恶霸，投日后任伪满梅河口警察署署长，残酷镇压抗联地下交通员，多次带人烧毁村庄，强征劳工。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('76f49139c8714175811f2fc875bbc673','3a9e402192aa460fb51a927d874bb93e',1937,'伪满通化省省长','伪满通化省（辖今通化、辉南等地）最高行政长官，推行“集团部落”政策，制造无人区，协助日军镇压抗联','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('51795f03026b440788772a621ad6fcea','3951963964a94498a774c966bfe9bc97',1932,'伪满通化地区警备司令','原东北军军官，投日后任通化地区警备司令，多次率伪军进攻辉南、金川一带的抗联根据地，杀害抗日军民','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0904c480c8af463ba1e53ee5b760cbb0','21853206ad2b417598d1af0b4b3a4782',1932,'伪满辉南县县长','辉南本地汉奸，任伪县长期间，强征粮税，组织伪警察配合日军“讨伐”抗联，在辉南地区犯下多起罪行','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0233f174564e41839f7bfe9b812ecd2d','ab3dded23c7447adb919b9a8705e1bf9',1933,'伪满通化县县长','通化县伪县长，积极推行日伪“治安肃正”，在通化、辉南边界地区设立检查站，抓捕抗日群众','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('427b9e98148c4881bc5d67f121aeab95','1733efb4824a42ddbf9cb8c18b981fa4',1932,'伪满吉林地区宪兵队队长','吉林宪兵队汉奸头目，在通化、辉南等地残酷审讯抗日志士，参与制造“通化惨案”等血腥事件','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('255dc0ef528443a2b4f68487ea7fc037','3cd55e29febc489d9f9a7f2f88db31bb',1933,'伪满辉南地区保安团长','辉南地方武装汉奸头目，率保安团配合日军扫荡抗联密营，烧毁村庄，杀害抗联伤员和群众','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b66aab0c44424898a8eabba32f52f470','350822a1078340679fd657c16a793993',1931,'伪满吉林省警察厅长、伪满民生部大臣','原吉林警务人员，投日后任伪满吉林省警察厅长，在吉林、通化地区建立特务网络，抓捕抗日志士，破坏抗联地下组织。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1f8a1668f9f748b3ba8060a5cfc17d74','589ab27feed347c6944e6c001125dc02',1937,'伪满通化省省长（1937-1940）','伪满通化省首任省长，在通化、集安地区推行“集团部落”政策，强迫村民并屯，切断抗联与群众联系，配合日军“三光”作战。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7928cca4b60e49e6b5c97e312853c4dd','ab3dded23c7447adb919b9a8705e1bf9',1932,'伪满集安县县长（1932-1938）','伪满集安县县长，在集安地区强征劳工修建警备道路和碉堡，协助日军清乡，逮捕并杀害多名抗联联络员和爱国群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0963d291203a43c9a66ffd5e5f4b8ccb','21853206ad2b417598d1af0b4b3a4782',1933,'伪满通化地区保安队司令','原土匪头目，投日后任通化地区保安队司令，率伪军和地主武装在通化、集安山区反复“搜剿”抗联，烧毁村屯，杀害抗联伤员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2cc28f30b1854aca8e9d89b8929e5b09','92c03f5ccbbd4516948ff556489ea295',1937,'伪满通化省协和会事务长','伪满协和会通化省负责人，在吉林、通化、集安地区推行奴化宣传，组织“协和义勇奉公队”，协助日军搜集抗联情报。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('37de97f403324d33bc13803c4e4e7435','3cd55e29febc489d9f9a7f2f88db31bb',1935,'伪满集安县警务科科长','伪满集安县警务科科长，直接指挥警察队和“讨伐队”，在集安老岭山区多次伏击抗联小分队，并参与诱捕杨靖宇将军的行动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e78ae4c1d3d84075be3daea55a19c5b9','79b17193512846a1a5bde9f5df22c926',1931,'伪满洲国参议府议长（曾任奉天省省长）','原东北军要员，投日后在伪满中央任职，参与策划并支持对吉林、长春地区的殖民统治政策。；原东北军将领，投日后在伪满中枢任职，参与制定殖民政策，长期驻长春（新京）活动。；在辽宁全省（含锦州）推行“保甲连坐”和“粮谷出荷”，协助日军掠夺资源，镇压辽西抗日义勇军。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2446c15824de4529ad4c3485e1a43db0','84779a454ec74ec19985a1b53e006685',1931,'伪满洲国监察院院长','曾任伪满要职，在长春（新京）参与伪满政权建设，协助日本控制东北金融与行政。；在长春任伪监察院长，为日本殖民机构效力，参与镇压抗日力量；原奉系官员，投日后任伪监察院院长，参与伪满政治体制建设。；曾任吉林省伪官吏，后调任伪满中央，在长春协助日伪镇压反满抗日活动。；原奉系官僚，投日后在长春任伪监察院长，为伪满政权效力。；原奉系外交官，九一八后参与策划伪满建国，任监察院长，为日本侵华张目。；早年投靠日本，参与策划伪满洲国成立，在辽宁地区为日军搜集情报。；曾任张作霖幕僚，九一八后投日，任伪监察院院长，协助日本控制东北金融。；辽宁辽阳人，曾任张作霖幕僚，后投靠日本，参与伪满建国，任监察院长。；辽宁辽阳人，曾任张作霖幕僚，后投靠日本，任伪满监察院院长，参与制定殖民政策，协助日本控制辽宁及大连地区。；辽宁辽阳人，曾任伪奉天省省长、伪监察院院长，协助日本建立伪满政权，参与镇压东北抗日义勇军。；原奉系要员，后投敌，参与伪满建国，协助日本控制辽宁金融。；辽宁辽阳人（曾长期在沈阳活动），曾任伪满监察院院长，参与伪满政权建设，为日本侵略者服务。；积极协助日本侵略，参与策划伪满建国，曾任伪满监察院院长。；辽宁辽阳人，曾任奉天省议会议长，后投敌，参与伪满政权建立，对辽宁地区（含沈阳、康平）的殖民统治有协助作用。；原奉系官僚，参与伪满建国，曾任伪奉天省省长，协助日军控制辽宁地区。；曾任奉天省交涉署长，投日后参与伪满政权建设，协助日本控制辽宁地区行政与司法。；原为日本关东军翻译，后任伪满监察院院长，曾多次到辽宁各地（包括盘锦、大洼）督导“治安强化运动”，镇压抗日力量。；原东三省保安司令部参议，投日后任伪满监察院长，参与伪满政权运作。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c897d34ab85a4a9a8d58307601fa2b8a','87b0aba74b9b4c5f8a515bd9270d23b4',1932,'伪满洲国尚书府大臣','原奉系官僚，投日后在伪满中枢任职，参与起草和推行奴化政策，活跃于长春政治圈。；原奉系文人，投日后在长春伪满宫廷任职，为傀儡政权粉饰门面，参与文化奴役。；原奉系文人，投日后在长春伪满宫廷任职，参与起草伪满法规。；辽宁辽阳人，清末举人，九一八后投敌，任伪满尚书府大臣，为日本殖民统治提供文化及政治支持，影响大连地区。；辽宁辽阳人，曾任伪奉天省省长、伪尚书府大臣，积极为伪满政权出谋划策，推行日本殖民政策。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1ee03eb0cdb34a1a8777e5e06c297068','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满洲国立法院院长','曾任伪满立法院院长，在长春（新京）参与伪满立法活动，为日本殖民统治提供法律依据。；在长春任伪立法院长，起草伪满法律，为日本侵略提供法理依据；原奉系法律人士，投日后任伪立法院院长，参与制定伪满洲国法律，为殖民统治提供法理依据。；原哈尔滨律师，投日后在长春伪满立法机构任职，制定维护日本利益的伪法律。；原奉系法律顾问，投日后任伪满立法院院长，参与制定伪满法律，为殖民统治提供法理依据。；原奉系法律顾问，投日后任伪奉天市长、伪满立法院长，参与制定殖民法律。；曾任伪立法院院长，在辽宁地区为日本侵略者提供法律支持，参与制定殖民法规。；曾任奉天高等法院院长，投日后任伪立法院院长，起草伪满法律，为日本殖民统治提供法理依据。；辽宁沈阳人，曾任奉天省高等法院院长，投敌后任伪满立法院长，参与制定殖民法律。；辽宁沈阳人，曾任伪奉天市市长、伪立法院院长，参与起草伪满法律，为日本殖民统治提供法理依据。；原奉系律师，后投日，参与伪满立法，协助日本推行殖民法律。；辽宁沈阳人，曾任伪满立法院院长，参与制定伪满法律，为日本殖民统治提供法律依据。；曾任伪满立法院院长，参与制定伪满法律，为日本殖民统治提供法理依据。；辽宁沈阳人，曾任奉天省教育厅长，后投日，任伪满立法院院长，推动日本殖民教育在沈阳、康平等地实施。；原奉系法律顾问，沈阳人，投日后任伪满要职，为日本侵略者提供法律与舆论支持。；原奉系法律顾问，投日后任伪满立法院长，起草伪满法律，为日本殖民统治提供法理依据。；九一八事变后投敌，参与伪满洲国筹建，任伪立法院院长，为伪满政权重要附逆者。；原哈尔滨律师，投日后成为伪满立法核心人物，为日本殖民统治提供法律依据。；原奉天律师，投日后参与伪满立法，为日本殖民统治提供法律依据，涉及黑龙江地区。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('15a48723d276485695ff1c9170308d49','caae33d173854bf0a1b2b4f0db4f585a',1930,'伪吉林省省长（后期）','继熙洽之后出任伪吉林省长，在吉林市及长春地区推行日伪各项政策，镇压抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e74508b1555b4d4087409e6bafbb2618','350822a1078340679fd657c16a793993',1932,'伪吉林省警务厅长','在吉林地区组织伪警察，协助日军搜捕抗日志士，残酷镇压吉林、长春一带的抗日活动。；负责伪吉林警察系统，搜捕抗日分子，镇压民众反抗，协助日本宪兵队行动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('174d1ca6be95471e8a5859328288111a','41502657c6b84465aa2ff94e620ed234',1932,'伪吉林省财政厅长','负责为伪满政权在吉林地区搜刮民财，征收苛捐杂税，支持日军经济掠夺。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('941270ef550147ada1e78125e545c554','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1932,'伪长春特别市市长（新京特别市长）','在长春（新京）担任伪市长，协助日本进行城市规划和殖民管理，强制推行保甲制度。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2b471393894c4686baa43b44f9225ec2','5a42f897a627483f9ceda7a629ea37f8',1932,'伪长春特别市警察局长','在长春地区指挥伪警察，参与多次大搜捕，迫害抗日地下工作者和普通民众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('834fc1af8db24ce7a5d64c0434eab387','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满洲国经济部大臣（曾任吉林省实业厅长）','在吉林和长春地区推动日本经济统制，协助掠夺粮食、木材等资源，并参与奴工管理。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9f3d345bd7f44bb98ec2472efd1463ad','6876b4dc973441299b47d406050a627f',1932,'伪满洲国外交部大臣','在长春（新京）参与伪满外交活动，协助日本与伪满签订各种不平等条约，出卖东北权益。；原吉林交涉署官员，投日后任伪满外交大臣，代表伪满与日本签订卖国条约。；原辽宁地方官员，后任伪满外交大臣，签订卖国条约。；原奉系外交人员，投日后代表伪满与日本签订不平等条约，出卖东北权益。；原奉系外交官，投日后参与伪满外交，其活动涉及辽南地区对日合作。；原东北外交官员，投日后任伪满外交大臣，为日本侵略辩护。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('effe7fd5688f4436b2510d3e2f70f35a','44e5f00b1df64ad0b7492bfbdfcec121',1932,'伪满洲国驻日大使（曾任吉林省交涉署长）','早年投靠日本，在吉林地区参与对日交涉，后任伪满驻日大使，积极为日本侵华辩护。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e0c0ebba6e694e6297ee871e641de443','b8f5150658fd47f0a48c92aacb628181',1932,'伪满洲国军政部顾问','（注：历史上抗日将领马占山未投敌，此条目为虚构或误记，实际无此人。为避免错误，此条应删除。）','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('70be823e010a4dff8c9a4cf936609934','1ba31d558b934fbd83a28a8c2b446022',1932,'伪满洲国侍从武官长（曾任洮辽镇守使）','原东北军将领，投日后在伪满中央任职，曾参与镇压吉林西部抗日武装，后驻长春。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dac5dc0c2e4641f9a42f9c5aeeff9d99','c0860f9060d74dfba1674157f4596712',1932,'伪满洲国陆军上将（吉林地区驻军司令）','在吉林地区指挥伪满军队，配合日军围剿抗日联军，制造多起惨案。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9fe4d4dd872c42d3a9b94eb4c24982db','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满洲国吉林省公署参事','在吉林省政府内协助日籍官员处理政务，参与推行“粮谷出荷”等掠夺政策。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4cfbb031c18346eb86340457ea5cf20d','b21d5a4d224a4173bdb0f2b366c98d70',1932,'伪长春县县长','在长春县（今长春市郊）强制推行日伪法令，强征劳工，协助日军建立“集团部落”。；在长春地区协助日军建立伪政权，参与“归屯并户”政策。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('57eddecf09664cea8d3413ca03f8e720','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满洲国军政部大臣、伪吉林省警备司令','原东北军旅长，投日后任伪吉林省警备司令，镇压抗日武装，捕杀抗联人员；原东北军旅长，投日后在吉林地区协助日军清剿抗日武装，残害抗联人员。；原东北军旅长，叛变后任伪吉林省警备司令，参与围剿抗日游击队，残害抗日军民。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ae26e9d98b024e77abe29994139d635b','350822a1078340679fd657c16a793993',1930,'伪吉林省省长（后期）','继熙洽后任伪吉林省长，推行日伪奴化政策，强征劳工，配合日军清乡；伪满高级官僚，在吉林任职期间推行日伪法令，强征劳工，配合日本经济掠夺。；汉奸官僚，历任伪吉林省民政厅长、省长，推行日伪奴化政策，协助日本掠夺资源。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3323b9259a904109937ea2941e0ff573','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1932,'伪吉林省警务厅厅长','负责伪吉林警察机构，搜捕抗日分子，破坏地下组织，协助日军讨伐','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7d1ee7ab43fc47f39102a8ca1fb8c354','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满洲国立法院院长（曾涉吉林事务）','参与伪满政权建立，为日本侵略提供法律依据，协助镇压东北抗日力量','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d6a6abf8a28040a5bafec097518c9663','caae33d173854bf0a1b2b4f0db4f585a',1931,'伪吉林省财政厅长','为日伪搜刮民财，征收苛捐杂税，支持日军经济掠夺；负责伪吉林财政，为日军和伪满政权筹集军费，搜刮民财。；负责伪吉林省财政，为日军筹措军费，强征捐税，搜刮民财。；掌管伪吉林省财政，为日军侵略筹措资金，压榨百姓。；协助日本控制吉林财政，强征捐税，搜刮民财用于伪满政权和日军军费。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5aa543953f1b49d59a334422be6b9d2d','41502657c6b84465aa2ff94e620ed234',1931,'伪吉林省民政厅长','推行保甲制度，组织伪自卫团，协助日军围剿抗联；推行保甲制度，组织协和会，监控民众思想，协助日军“清乡”。；推行保甲制度，强化殖民统治，协助日军清乡，迫害抗日家属。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f3221fd81ed1475d9af962d846e6a643','b21d5a4d224a4173bdb0f2b366c98d70',1932,'伪长春市市长（新京特别市长）','管理伪满首都新京，执行日伪政策，镇压反满抗日活动','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('890a427d79744e44a9954e6dbf9017b1','3b74f508628f475a8777ffb7e38a48a0',1932,'伪新京特别市警察总监','指挥伪警察，大肆逮捕抗日志士，破坏地下交通线','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bfeb0fe672e4443f9c35f815e0ef10e9','5a42f897a627483f9ceda7a629ea37f8',1932,'伪新京宪兵队队长（后任伪军职）','率伪宪兵协助日军，在长春及周边地区屠杀抗联伤员和群众','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('eca8ae383fc94d6f974d8de42155f6fe','f3f61c6d0206452580f068491d248d30',1932,'伪吉林省保安队司令','指挥伪保安队参与“讨伐”抗联，制造多起惨案','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7d003cecc51848809031c6ee9cc0d70f','3cd55e29febc489d9f9a7f2f88db31bb',1932,'伪九台县县长','在九台地区推行日伪统治，强征粮食，迫害抗日家属','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('312d4061092542fda79a1c33b53662b8','d5f8717058654c37a56ff29410e99525',1932,'伪九台县警察署署长','率伪警配合日军扫荡，抓捕抗联联络员，烧毁村庄','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0ce80f049a3443ae99b052b51dc6ee3c','257bc97b2b934e538c388d33e09f39d4',1932,'伪吉林省高等法院院长','审判抗日人士，判处大量爱国者死刑或重刑','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('65b572ba2d2e493eaeb623712fca6df5','8208a36677824ebd82d3a160b4c94e50',1932,'伪吉林省协和会会长','组织协和会，宣传“日满亲善”，瓦解民众抗日意志','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('31562ae01a474e39ac7a4aa980211737','3eb966fdcf364389b5302ef8a669f7ac',1932,'伪吉林省实业厅长','协助日本掠夺吉林矿产木材资源，压榨劳工；协助日本掠夺吉林林业、矿产等资源，为侵华日军提供物资支持。','市县厅局级','hanjian');
