INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('52b39548143d4844937a6d5a8ac6df92','87b0aba74b9b4c5f8a515bd9270d23b4',1931,'伪满洲国参议府参议','原奉系官僚，投日后任伪参议，积极鼓吹“日满亲善”，协助日本控制东北。；原奉天省议会议长，投日后任伪满参议，鼓吹“日满亲善”，协助日本控制东北舆论。；辽宁辽阳人，清末举人，九一八后参与伪满筹建，任参议，为日本侵略张目。；辽宁辽阳人，清末举人，九一八后投靠日本，任伪满参议，参与制定奴化政策，影响沈阳及康平地区。；清末举人，曾任奉天省议长，投日后为伪满政权出谋划策，参与奴化教育宣传。','无明确职位或一般帮凶','hanjian');
