INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('40fd20737a48461b9be27f2b7a45186d','360451ccb61f491bafdc1b28af3c6799',1932,'伪满洲国交通部大臣（曾在长春任职）','原铁路官员，投日后任伪满交通部大臣，在长春管理伪满铁路，为日军运输兵力和物资。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9ffe403f337b41f0ab54c345626297c7','e913aea565d54f398ad14deb4526d3a9',1932,'伪满洲国司法部大臣（曾在长春任职）','原法官，投敌后任伪满司法部大臣，在长春推行伪满法律，迫害抗日人士。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('59eee087bf34428f8bf6279677b2e76d','41502657c6b84465aa2ff94e620ed234',1932,'伪满洲国文教部大臣（曾在长春任职）','原教育界人士，投日后任伪满文教部大臣，在长春推行奴化教育，篡改历史。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7dcabea9ddb8471d87125316f5ef80d4','6876b4dc973441299b47d406050a627f',1932,'伪满洲国外交部大臣（曾在长春任职）','原外交官，投敌后任伪满外交部大臣，在长春代表伪满与日本签订卖国条约。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7c79d85188bd4142a14f758f8693fa85','44e5f00b1df64ad0b7492bfbdfcec121',1932,'伪满洲国驻日大使（曾在长春任职）','原台湾籍官僚，投日后任伪满驻日大使，在长春和东京间活动，为日本侵略政策辩护。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('30e06a58856148e586f477bcb262f894','79b17193512846a1a5bde9f5df22c926',1931,'伪满洲国参议府议长、奉天省省长','原辽宁省政府主席，被日军扣押后变节，出任伪奉天省长，后任伪满参议府议长，协助日本统治东北。；原辽宁省政府主席，被俘后变节，历任伪奉天省长、伪满参议府议长，推行殖民政策。；原奉天省省长，九一八后被日军软禁后变节，出任伪职，协助日伪政权维持辽宁地区统治。；辽宁沈阳人，九一八事变后投敌，历任伪奉天省省长、伪参议府议长，参与伪满政权建设，对辽宁（含大连）地区抗日力量进行镇压。；辽宁沈阳人，九一八事变后投敌，历任伪奉天省省长、伪民政部大臣、参议府议长，参与签订卖国条约，为日本掠夺东北资源服务。；九一八事变时被日军俘虏后变节，历任伪奉天省长、伪满参议府议长，协助日本控制辽宁地区。；原奉天省省长，九一八后投日，任伪奉天省省长，管辖辽宁中南部，包括盘锦地区，推行“保甲连坐”制度，镇压抗日群众。；原东北军将领，投敌后任伪奉天省长，在营口地区推行保甲制度，镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d1394742e3d540e28f07320260b0d1ab','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满洲国军政部大臣、第一军管区司令','原东北军旅长，投日后任伪满军政部大臣，镇压抗日武装，参与“讨伐”抗联。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d04f8ee290db4792bef8b6fbe8d007db','c0860f9060d74dfba1674157f4596712',1931,'伪满洲国吉林警备司令、第二军管区司令','原吉林陆军训练处总监，投日后任伪吉林警备司令，率伪军围剿抗日游击队。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7aa8e8e410314e5787c8b17590f1ad33','350822a1078340679fd657c16a793993',1932,'伪满洲国吉林省省长','原吉林省政府官员，投日后历任伪吉林省公署厅长、省长，推行日伪“治安肃正”政策。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6458744363ff479d870f4a25c64d325d','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1932,'伪满洲国吉林市市长','投日后任伪吉林市长，协助日军建立殖民秩序，强征劳工，镇压反满抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('64bbddb0400145efa9603703db88b7ff','caae33d173854bf0a1b2b4f0db4f585a',1932,'伪满洲国吉林省财政厅长','原吉林财政官员，投日后主管伪省财政，为日军搜刮民财，供应军需。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bf7a44cbaa1c478da296e8f8a1eced9b','41502657c6b84465aa2ff94e620ed234',1932,'伪满洲国吉林省民政厅长','原吉林民政官员，投日后推行保甲制度，协助日军清乡，迫害抗日家属。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fa459037b1c147cd8ddf27ddc48dc0c6','b21d5a4d224a4173bdb0f2b366c98d70',1932,'伪满洲国吉林高等法院院长','投日后任伪吉林高等法院院长，审判抗日志士，以“反满抗日”罪名判刑。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3365840c32f44b188d10a0ae6cb24dcf','3eb966fdcf364389b5302ef8a669f7ac',1932,'伪满洲国吉林省警务厅长','投日后任伪省警务厅长，指挥伪警察搜捕地下党，破坏抗日组织。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a565f27a0cb1498cb2043de4531e6be8','9fdf72cacfcf4c72a1c4a279be3c42c2',1932,'伪满洲国吉林协和会会长','投日后任伪吉林协和会头目，宣传“王道乐土”，组织奴化活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ad78b6efac62412fb531f0f5d7d9bc5c','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满洲国经济部大臣','原吉林实业家，投日后任伪满经济部大臣，控制东北经济命脉，为日本掠夺资源。；辽宁金县（今大连金州）人，原奉天省财政厅长，投敌后任伪经济大臣，推行日本经济统制政策，控制大连金融。；原辽宁实业家，后任伪满经济大臣，协助日本掠夺鞍山铁矿等资源。；辽宁沈阳人，投日后任伪满经济部大臣，推行“产业开发计划”，在康平地区强占土地和矿产。；原大连实业家，投日后负责伪满经济统制，在沈阳设立配给制度，压榨百姓。；曾到盘锦、双台子地区推行经济统制，强征当地大米、大豆等农产品，导致百姓饥荒，并协助日军掠夺资源；负责伪满经济统制，在辽南地区控制粮食和物资，导致民众饥荒。；参与伪满经济掠夺，在辽宁绥中地区强征粮食资源供给日军。；原哈尔滨商会会长，投日后任伪满经济要职，在黑龙江协助日本掠夺资源。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d6c2b27299324c6ba1df99022a36ee6e','360451ccb61f491bafdc1b28af3c6799',1932,'伪满洲国文教部大臣','原吉林教育界人士，投日后推行奴化教育，删改历史教材，宣扬“日满一体”。；推行奴化教育，在营口、大石桥地区学校强制日语教学，篡改历史。；原东北大学教授，投日后任伪满文教大臣，推行奴化教育。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c69970cd77be4d72923c389bf3675720','70cbcc058e6648678fa022e3a64b9cea',1932,'伪满洲国吉林省实业厅长','投日后主管伪省实业，协助日本开采吉林矿产，强征农民土地。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a489af19c84c481282c22d62def5efb0','46a50b616c68419e99a3d9a77644267b',1932,'伪满洲国吉林省教育厅长','投日后推行奴化教育，强制学校教授日语，灌输“忠君爱国”思想。','市县厅局级','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f9aa08939805485c972ac963a6e293a6','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满治安部大臣、伪满第一军管区司令','原东北军旅长，投敌后任伪满第一军管区司令，驻防吉林，多次率伪军围剿东北抗日联军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f031b51958514005a78017c3e1b16721','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1932,'伪满吉林市警察局局长','原吉林警察系统官员，投日后任伪吉林市警察局长，在龙潭地区大肆搜捕抗日分子，破坏地下组织。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('48e0e8ef3b4040409219f67eccf53cef','1a8847af165d4d648f62d949fad6cb5a',1933,'伪满吉林省警务厅厅长','原吉林警察厅官员，投日后任伪省警务厅长，在龙潭区设立多个警察分所，残酷镇压抗日群众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6c032bdd10ee4e3283629ed643708f2e','41502657c6b84465aa2ff94e620ed234',1932,'伪满吉林省财政厅厅长','原吉林财政官员，投日后负责为日军筹措军费，在龙潭地区强征捐税，掠夺资源。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9fa86c7b6dc94e5c87c980675ee5f904','9fdf72cacfcf4c72a1c4a279be3c42c2',1934,'伪满吉林市协和会会长','原吉林士绅，投日后任伪协和会会长，在龙潭地区组织汉奸团体，宣传“日满亲善”，瓦解抗日意志。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fcfb8a636eea46db872e4ab3a3aef18d','c24c1757f2264fe39617bbd224f5e4f9',1931,'无（未任伪职）','南充籍爱国民主人士，抗战期间坚持抗日民主立场，未附逆；此处列出以说明南充地区知名人物中无其汉奸记录。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('851b9797a6a54eea9b8e87c0ee35705f','b44f81bd93214bf3a30de8419135fb64',1931,'川军将领（后脱离军职）','南充籍川军将领，抗战期间未在伪政权任职；无可靠史料记载其附逆。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6cb289afe2554207a1368d8621befb06','87d513b1b0bc40599473bc4cf994dd4c',1937,'南充县维持会成员（待考）','地方史料中偶见南充地区维持会、伪保甲人员姓名，但多缺乏完整职务与事迹，难以确证为知名汉奸。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5cc8b92ac0cb49549a79d21479b53138','6058a91b52fd4d0aa64aeeea901b2fe1',1938,'川军将领、四川省政府主席（后投伪）','四川籍军政人物，抗战后期有与日伪接触传闻，但未形成明确伪政权任职记录；南充地区关联有限。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1edd2d05e6694f42af89a2b68d594eb5','56429dccc41e483ea421341bf9daced6',1937,'四川袍哥头目、伪军收编对象','四川地方帮会势力头目，抗战期间有与日伪、伪军勾结的传闻，活动范围涉及川北南充一带，但可靠史料不足。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5f655574ef264e8586eef2b14c6423b3','45550a123f584eaa88f365d3c2081f43',1937,'川军将领（后附逆传闻）','四川籍军人，抗战期间有投伪传闻，但与南充直接关联证据薄弱。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ff378c34a52b4143a06421bf6dc69aee','d751601a38e6452bb3813157e529cd9c',1938,'南充县维持会会长','南充地区在抗战期间未长期沦陷，但日机轰炸与伪组织渗透传闻中存在维持会人员，具体姓名与事迹缺乏可靠档案。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2cc61477c9c643c39639dd3d09d53b88','f630fd38caf04763ba7503f05a3b5382',1938,'伪警察所负责人','地方伪警察、保甲附逆人员多散见于未刊档案，南充地区无广泛知名汉奸名录传世。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f756128f42364b7191af73c57b2bf5ca','98a50d8aa14b439c9577d375e95dd116',1938,'伪四川省政府筹备成员','日军未占领四川全省，伪四川省政权未正式成立，仅有零星汉奸活动与传闻，南充地区无确证知名汉奸。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('58c18b02e9f04e1c9459461b8cbd1cf5','c12e72a145724c39b755a2a16dce9a71',1940,'伪国民政府主席兼行政院院长','公开叛国投敌，在南京建立伪国民政府，推行‘和平反共建国’路线，对四川等大后方进行诱降与情报渗透。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('460e7568d76248f99c7a7d90674d0d07','62a6d6c8e7ab4bbfbc92c5b14abbde74',1938,'伪国民政府立法院院长、伪上海市市长','追随汪精卫投敌，参与伪政权核心决策，负责伪政权与日军联络，对包括四川在内的抗战后方进行政治破坏。；汪伪政权要员，其伪政权对山东聊城地区有名义管辖权，推行亲日政策。；汪伪政权核心人物，虽非湖南籍，但其伪政权政策直接影响湖南沦陷区，包括怀化、溆浦等地的伪维持会活动。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9340dc7627154925a0132b604b30bd1c','a2e4190c87b449e685d78c118a6801b5',1938,'伪国民政府财政部长、伪警政部长','汪伪政权核心人物，掌管财政与警政，配合日军经济掠夺与特务活动，对四川等后方进行经济封锁与情报搜集。；湖南沅陵人，汪伪政权核心成员，掌握伪财政与警政，其伪政权体系对江西沦陷区实施经济统制与特务统治。；汪伪政权核心，掌管伪财政与警察系统，其伪警政体系涉及江西九江沦陷区的伪警察与保甲组织。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a911cd6c754742d7aeec1ae41b81d0e6','07ff958e7f18410f864975f09234ac7e',1939,'伪国民政府特工总部主任','组建汪伪‘76号’特工总部，大肆捕杀抗日人士，向四川等大后方派遣特务进行破坏与暗杀活动。；汪伪特务头目，在湖北宜昌等地建立特务组织，搜捕抗日人士，破坏地下抗日网络。','特工总部主任','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('62b73af303c8419f8b3ce9bd39eb7f4f','9910c48b9b394ffa8c73439ed0a473b0',1939,'伪国民政府社会部部长、伪浙江省省长','汪伪特工头目之一，参与‘76号’特务活动，对包括四川在内的抗战后方进行渗透与破坏。；汪伪特务与行政头目，其势力涉及湖北沦陷区，参与镇压宜昌等地抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dc36afd4b08f4a458818535c551cc955','8f1dd12e548b4c4f866dd743c3377896',1937,'伪中华民国临时政府内政部部长、伪华北政务委员会委员长','投敌后历任伪职，推行奴化教育，配合日军‘治安强化运动’，对四川等后方进行政治宣传与渗透。；华北伪政权核心人物，参与推行伪化教育、经济掠夺，其伪政权势力范围涉及陕西东部邻近区域。；参与组建伪中华民国临时政府，后任伪华北政务委员会委员长，负责华北沦陷区包括陕西部分地区的伪化统治。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7aa564c27f09418d835e36300fd54275','bbc7d2d2f1174918a3a12cc3ce766af2',1937,'伪北平市市长、伪华北政务委员会委员','北平沦陷后出面组织维持会，后任伪市长，协助日军维持占领秩序，对包括四川在内的抗战后方进行舆论诱降。；北洋旧官僚，投敌后任伪北平市长，协助日军维持治安、征粮征工，对华北包括陕西周边地区实施殖民统治。；投靠日本，在北平伪政权中任职，配合日军统治，对陕西有间接影响。；北平沦陷后组织维持会，出任伪市长，协助日军维持华北占领区秩序，对陕西等后方抗日活动进行封锁与破坏。；在北平沦陷后组织伪维持会，后任伪市长，配合日军统治，其伪政权体系与华北包括陕西地区有行政联系。；抗战期间在北平出任伪职，协助日军维持占领区秩序。；投靠日本，在北平组织伪政权，配合日军在华北的殖民统治。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f5fa75334e2e44d0b861c2c03f57ee5f','10b88f41fdee46778f29f60ae3d41741',1937,'伪天津市市长、伪华北政务委员会委员','投敌后任伪职，配合日军在华北的统治，参与对四川等大后方的政治渗透与情报活动。；七七事变后投敌，任伪天津市市长，协助日军推行治安强化运动，镇压抗日力量，征收苛捐杂税，出卖天津资源给日本；投敌后参与伪华北政权，其政策影响包括山东聊城在内的华北地区，推行奴化教育。；在天津及冀东地区活动，协助日军控制秦皇岛等沿海城市；华北伪政权要员，参与伪政权统治，其活动与华北包括河南沦陷区伪政权体系相关。；抗战期间投敌，任伪天津市市长、伪华北政务委员会委员等职，协助日军统治天津，镇压抗日力量。；北洋政客，投敌后任伪天津市市长，推行保甲制，配合日军经济掠夺，其伪政权与陕西周边沦陷区有行政联系。；华北汉奸，参与伪政权建设，推行日军经济统制政策，镇压天津及周边抗日活动，影响波及陕西宝鸡等后方。；投敌后任伪天津市市长，后任伪华北政务委员会委员，配合日军统治天津。；投靠日本，在华北伪政权中任职，参与经济掠夺与治安强化运动，其政策影响波及陕西周边。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('01c3cab4b55c41e684f22e3a9fda883a','eb97867e737c44e4944e71b5792c1f23',1938,'伪北平市市长、伪华北政务委员会建设总署督办','在伪华北政权中任职，协助日军进行城市建设与资源掠夺，对四川等后方进行经济封锁配合。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d38fdd4963df46e7a697f580d836264e','4b89b0b1aadc4aa2b3384379d6297cd7',1938,'伪山西省省长、伪华北政务委员会委员','投敌后任伪山西省长，配合日军在山西的统治与‘扫荡’，对四川等后方进行政治诱降与情报搜集。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c23a9f32ea134aae847eecf0abbbe7dd','1a5f254b2f68424a91a5fbf85fece5e1',1940,'伪山西省省长、伪华北政务委员会委员','接替苏体仁任伪山西省长，继续配合日军统治，参与对包括四川在内的抗战后方的政治破坏。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9f7d7af0fd264b018dd0ff313ea7501f','0367758e6b0a4e6e9be4392582958ec0',1938,'伪河南省省长、伪华北政务委员会委员','投敌后任伪河南省长，配合日军在河南的统治与掠夺，对四川等后方进行经济封锁与情报渗透。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('52a20fadcc3e4595af6c6a154edd4bc2','793dba30c5cd4e9ab0835412a8dc7906',1937,'伪河南省省长、伪华北政务委员会委员','在伪河南省政权中任职，协助日军维持占领区秩序，对四川等抗战后方进行政治诱降。；投敌后任伪河南省省长，推行保甲制，协助日军扫荡河南、陕西边境抗日武装。；在河南担任伪职，配合日军统治，河南与陕西接壤，其活动对陕西周边有影响。；在华北伪政权中任职，配合日军统治河南，其伪政权与陕西邻近，对陕西抗日根据地有威胁。；河南伪政权头目，配合日军扫荡，掠夺物资，对陕西宝鸡抗日后方构成威胁。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('face279660794aa7a9a1c90eff2c7c03','fcb3e5ff966f4327a818cbc1e3244da5',1937,'伪河南省省长、伪华北政务委员会委员','后期任伪河南省长，继续配合日军统治，参与对四川等大后方的渗透与破坏。；华北汉奸，在河南推行伪化统治，协助日军镇压抗日力量，其活动与陕西宝鸡地区有间接关联。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c8b5c2fcad1843a690f0454db9a77304','a1da16c8e56e480dac4f7b8ce876b429',1938,'伪河南省警务厅厅长','掌管伪河南警务，配合日军镇压抗日活动，向四川等后方派遣特务进行破坏。；掌管河南沦陷区伪警察系统，督导各县伪警察所配合日军搜捕抗日人员，周口、商水等地伪警察活动受其节制。；在开封等地掌管伪警察系统，镇压抗日活动，搜捕抗日人员，推行日军治安政策。；河南伪警察头目，其伪警体系与陕西渭南地区有间接关联。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5324d49a483d434a9da660195c4bc2c3','ef676fac9bb24126bcc992f39c87c979',1937,'伪开封绥靖公署主任、伪河南省省长','投敌后任伪职，配合日军在河南的军事行动，对四川等后方进行政治诱降与情报搜集。；原西北军将领，投敌后任伪河南省省长，在河南沦陷区推行奴化教育、经济掠夺，其政令覆盖周口、鹿邑等豫东地区。；原西北军将领，投敌后任伪河南省省长，统治河南沦陷区，与陕西接壤，配合日军进攻陕西抗日根据地，镇压抗日力量。；在河南地区担任伪职，协助日军维持占领区统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('56a6ce304608444db07a5e25fe576961','63006a4879fb4f49ad97a1e88c8c5d69',1942,'伪和平建国军第三方面军总司令、伪苏北绥靖公署主任','率部投敌，任伪军头目，配合日军在苏北、河南等地‘扫荡’，对四川等后方进行军事威胁与渗透。；原国民党将领，后投靠日本，率部伪化，在华北、苏北地区配合日军作战，其伪军活动对陕西抗日根据地有间接威胁。；原西北军将领，后投敌，在苏北、豫东组织伪军，其活动范围与陕西邻近，配合日军作战。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f0da40f84cc5455c8812ad469df45455','5ec2ad124b2f429482b1a90a7f8d4a92',1943,'伪和平建国军第二十四集团军总司令、伪河南省省长','被俘后投敌，任伪军头目与伪省长，配合日军在河南的统治，对四川等后方进行军事与政治破坏。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f23977e78ec1428fbb0094f388ba6800','9f7b3ed9c76f4eea8211fd8ebc40a461',1943,'伪和平建国军新编第五军军长、伪豫北保安司令','投敌后任伪军头目，配合日军在豫北的统治与掠夺，对四川等后方进行情报渗透。；投敌后在豫北安阳、汤阴等地驻防，为日军维持占领区，参与对抗日根据地的封锁。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('167e39d0204d45309604ed342da2e1b0','40ceda4a3fba43bb8c30faefaa993de4',1943,'伪和平建国军第三方面军总司令、伪山东省省长','率部投敌，任伪军头目与伪省长，配合日军在山东的‘扫荡’，对四川等后方进行军事威胁。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6dd5e8599f9f490996dc614f2461bf1c','a06c0041e5294f2987f746729e510de9',1943,'伪淮海省省长、伪和平建国军第八方面军总司令','投敌后任伪省长与伪军头目，配合日军在淮海地区的统治，对四川等后方进行政治渗透。；原国民党军将领，1943年投敌，任伪淮海省省长，管辖苏北、皖北部分地区，配合日军统治。；投敌后任伪淮海省省长，所部活动于苏北、皖东北地区，配合日军扫荡，滁州地区受其伪政权和伪军影响。；原国民党军官，投伪后任伪淮海省省长，所部在苏鲁豫皖边区配合日军扫荡，活动范围包括菏泽东部及鄄城邻近地区。；在苏北、河南一带任伪职，配合日军统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('46c0b13d9edb4107800ee91d62a190b0','bacadba533394b3bb79fb5b9c5b66118',1943,'伪浙江省省长、伪和平建国军第五军军长','投敌后任伪职，配合日军在浙江的统治，对四川等后方进行经济封锁与情报活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5196b74f54c04821869e103f5f179784','d823baec96e04682bca33413f02ae20d',1940,'伪浙江省省长、伪建设部部长','汪伪政权要员，任伪浙江省长期间配合日军统治，对四川等后方进行政治诱降。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c71e263255f944d68e43fae73d4c9ad0','3f934b1c263b4cd78c73d9700621e7bd',1938,'伪江苏省省长、伪安徽省省长','历任伪省长，配合日军在华中地区的统治与掠夺，对四川等后方进行经济封锁与情报渗透。；投敌后任伪江苏省省长、伪安徽省省长，配合日军统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e3f4048330bb4e2da147c19b87507db8','0d2d2045fc1d498dab9499e43abcb3de',1940,'伪司法行政部部长、伪安徽省省长','汪伪政权核心成员，任伪部长与伪省长，配合日军统治，对四川等后方进行政治破坏。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7e51f5cd659645adba97baf75c7627ed','d1abe59a5d664bf18b442130fc0478a1',1940,'伪宣传部部长、伪安徽省省长','掌管汪伪宣传，推行奴化教育，对四川等后方进行舆论渗透与诱降宣传。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e62b4de860f44f38864fa5c8b499d022','28c69a91441d4439abc95701e2c6787a',1940,'伪实业部部长、伪浙江省省长','汪伪政权要员，参与对日经济合作与掠夺，对四川等后方进行经济封锁与情报活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('184e378c246f46638baf99dfb247ed53','5f856dffd503467b9f14213451f88d21',1940,'伪教育部部长、伪外交部部长','汪伪政权教育、外交负责人，推行奴化教育，对四川等后方进行文化渗透与政治诱降。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4b72e3fccfe048259c4a9d18256725d6','3eff5eff7c6843f4a65435548f2d1f74',1940,'伪教育部部长、伪国民政府委员','参与汪伪教育政策制定，推行亲日奴化教育，对四川等后方进行文化破坏。','省部级/大军区级要员','hanjian');
