INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d4623300b9604bcd8d1dd4d84dfa1e01','e409ef959281461b91e8ce1eef37d186',1938,'伪华北政务委员会绥靖总署督办、伪河北省省长','投敌后任伪职，配合日军在河北的统治与‘扫荡’，对四川等后方进行军事与政治破坏。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c4e877ac7b6940c5a283530be65214cb','bf398d44782c4c1594ef5ef1eecbf521',1937,'伪河北省省长、伪华北政务委员会委员','任伪河北省长，配合日军统治与掠夺，对四川等后方进行经济封锁与情报渗透。；担任伪河北省省长，协助日军在河北进行殖民统治，活动范围接近陕西。；在华北伪政权中任职，推行日伪政策，其活动区域与陕西邻近，对陕西抗日力量有间接压制。；河北伪政权头目，推行保甲制度，配合日军掠夺资源，对华北抗日根据地及陕西宝鸡后方造成压力。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4d763b8bbb514664ae5c2fe462beec23','d2b840cc6fa142c8b5c30c100a11b64d',1940,'伪河北省省长、伪华北政务委员会委员','在伪河北省政权中任职，协助日军维持占领区秩序，对四川等后方进行政治诱降。','省部级/大军区级要员','hanjian');
