INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('56f9b5da720b41108de1213d38cfb83e','ad65aa69fa0c4f84aa598321e8c96ad1',1937,'伪华北政务委员会委员长、伪治安总署督办','伪华北政权核心人物，掌管治安，配合日军‘治安强化运动’，对四川等后方进行政治破坏。；华北汉奸政权要员，参与伪华北政务和治安强化运动，其政策覆盖河北各地。；原北洋政府官员，抗战期间投敌，任伪华北政务委员会委员长等职，协助日军维持华北治安。；原北洋政府官员，抗战期间投敌，任伪华北政务委员会委员长等职。','伪政权最高层/元首级','hanjian');
