INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('46b1696de84d4d46a80d6d19f63bac93','5b2f7fb20693426f81f3853beb962949',1938,'伪天津市市长、伪华北政务委员会委员','任伪天津市市长，配合日军统治与掠夺，对四川等后方进行经济封锁与政治诱降。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4e2d2a36de5f4b8f805977b4cd08e7d7','4cc5391bc78947fa9bf1a4b59e0f5371',1937,'伪天津市市长、伪华北政务委员会委员','在伪天津市政权中任职，协助日军维持占领区秩序，对四川等后方进行政治破坏。；张之洞之子，投敌后任伪天津市市长，协助日军掠夺物资，推行保甲连坐，镇压抗日活动。','核心城市市长/省部级','hanjian');
