INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3017c88de45447c29974cb3d5bb42372','0e0670b899174301ac71539770f221b7',1938,'伪成都市维持会会长、伪成都市长','抗战初期在成都组织维持会，后出任伪成都市长，协助日军及伪政权维持地方统治，推行奴化教育，为日军搜集物资。；抗日战争期间投靠日军，在成都组织伪维持会，后任伪成都市长，协助日军维持占领区秩序，推行奴化教育，为日军征集物资。；抗日战争期间投靠日伪，参与组织伪成都市维持会，后任伪成都市长，协助日军维持占领区秩序，推行伪化统治。','基层维持会/地方自治头目','hanjian');
