INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('63c6f6a8f5c44e9a8eb0d27dc933deec','2a262f27f5df4bb493c9cf9285d13aa5',1938,'伪四川省保安司令（部分部下附逆）','其部分旧部在成都地区组织伪保安队，协助日军维持治安，征收苛捐杂税。','市县厅局级','hanjian');
