INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('763d136b961b438c88c1a7ebe700e40d','77b5e02c10e946949dc322ae2ba6b26d',1940,'伪西康省政府主席（与成都伪政权关联）','在成都与伪政权保持联系，允许伪军过境，为日军提供西康物资，镇压抗日活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2a323e20abc14a2c831200bf01cb2b78','511617b48a6e4b238f35e1b1653d9982',1938,'伪成都商会会长','在成都商界为日军筹款筹粮，组织物资统制，协助伪政权经济掠夺。','基层头目','hanjian');
