INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('109a0cc77d0f4cffa867acd585027da0','059cb7c58256416b928cf3da0e1b94dd',1940,'伪成都保甲长','在成都基层推行保甲连坐，协助日军征丁征粮，举报抗日人员。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2eff797a073347cf977fa19a1d4aa5de','cf9c2787697940409d9ee50b722c515a',1938,'伪成都维持会干事','在成都组织维持会，为日军带路，协助建立伪政权，参与镇压抗日宣传。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('90c3f906dd61448b828909e27c61f275','ffb85ba87f9547bc8327bec487f2c0fb',1941,'伪成都特务机关长','在成都负责伪特务活动，破坏抗日组织，暗杀抗日人士，为日军搜集情报。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('eab603deb7ca4a0992be3cc58260e0dd','ac3d5ad7e92c4fb1b8f75209f6831ab0',1939,'伪成都县知事','在成都县推行伪政，征收赋税，强征劳工，协助日军扫荡周边抗日根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('170ce97ea26c46e2bf7e6a44ffb2ec85','a1ea2e5a54264f47b2bd01144ab2137e',1940,'伪成都地区伪军团长','率伪军在成都周边清乡，烧杀抢掠，配合日军进攻抗日游击队。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c2e77afd162845d199f8f93d3db6e9f5','56429dccc41e483ea421341bf9daced6',1938,'伪成都维持会会长、伪成都市市长','抗日战争期间投靠日军，参与组织伪成都维持会，后任伪成都市市长，协助日军维持占领区秩序、推行奴化教育、征敛物资。；成都沦陷后（注：成都实际未被日军占领，此处指其附逆筹备活动）参与组织伪政权，协助日军维持地方秩序，推行奴化教育，为日军征集物资。；成都本地帮会头目，抗战期间投靠日伪，参与组织伪成都维持会并出任伪市长，协助日军维持成都地区治安、征发物资，镇压抗日活动。；抗日战争期间投靠日军，参与组织伪成都维持会，后任伪成都市市长，协助日军维持占领区秩序、推行伪化统治。；抗日战争期间投靠日军，参与组织伪成都维持会，后任伪成都市市长，协助日军维持占领区秩序、推行奴化教育、征发物资。；四川成都人，抗战期间投靠日军，参与组织伪成都维持会，后任伪成都市市长，协助日军维持占领区秩序、征敛物资。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dc5777c7c42942c1b31d7ac1c025cb36','b6a25045085d423088ff41b10028e291',1938,'伪四川省政府委员、伪成都市市长','在日伪扶持下出任伪成都市市长，配合日军实施经济统制，强征粮食与劳工，镇压抗日活动。；在日军占领武汉后，于四川地区参与伪政权活动，曾任伪成都市市长，协助日军推行伪化政策。；在四川日占区参与伪政权，任伪四川省政府委员、伪成都市市长，推行日军殖民统治政策。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f357ca2a422a48219e38536a53f1c1f0','b68fe6aca12447d495affdbdc9eaaad6',1938,'伪成都警察局局长','任伪成都警察局局长期间，搜捕抗日志士，镇压学生抗日运动，为日军提供情报。；在成都地区组织伪警察队伍，配合日军搜捕抗日人士，镇压民众抗日活动。；抗战期间在成都地区投敌，担任伪警察局局长，参与镇压抗日活动、维护日伪统治。；任伪成都警察局局长期间，配合日军搜捕抗日人士、维持治安，镇压民众反抗。；抗战期间在成都日占区任伪警察局局长，协助日军镇压抗日活动、搜捕抗日人士。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b2074c17f4ea4700b7fe4a5f53060b38','d8938a31d44b481b84cb62c3b499a5bf',1940,'伪双流县维持会会长','在双流县组织伪维持会，为日军征粮派款，协助建立伪保甲制度，迫害抗日家属。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b502ce7da6e54c148ee326f9dd043827','83947059f06b4724a74c84f142f9909f',1941,'伪双流县保安大队大队长','率伪保安大队配合日军扫荡双流周边抗日游击队，捕杀抗日人员，强征民夫。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a36ea616a8674caeb20ac632a6cfe865','6058a91b52fd4d0aa64aeeea901b2fe1',1938,'伪四川省政府主席','投靠汪伪政权，任伪四川省政府主席，推行日军政策，在成都及周边地区实施奴化统治。；抗战初期在四川地区与日伪势力勾结，曾任伪四川省政府主席，推行伪化政策，后因内部矛盾被撤换。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('48cc3901fb1a44909453cb1e1683efb0','62a6d6c8e7ab4bbfbc92c5b14abbde74',1940,'伪国民政府立法院院长（活动涉及四川）','作为汪伪政权核心人物，其政策影响四川沦陷区，在成都等地推行伪化教育、经济掠夺。；作为汪伪政权核心人物，其伪化政策影响四川地区，间接推动成都、郫都等地伪政权建立。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5a3bcd7786d54de68959ef12063706de','664d3df731bb4293bee63eea6deacb2d',1940,'伪国民政府外交部长（活动涉及四川）','参与汪伪政权对四川沦陷区的控制，协助日军在成都等地实施文化侵略与经济统制。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ad739126d6f04901843642e8405c5c0e','b6a25045085d423088ff41b10028e291',1938,'伪四川省政府筹备委员','在日军策动下参与伪四川省政府筹备活动，联络地方士绅为日军提供情报与物资支持。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3272841263284c31bec785360d54022b','82c8dc8c68f3449d85ce6770c252b411',1940,'伪彭县维持会会长','在彭县（今彭州）组织维持会，为日军征粮派款，协助日军管理地方，迫害抗日家属。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('37f8d2a4387744d7a84c6d7ba9c0d149','77b5e02c10e946949dc322ae2ba6b26d',1939,'伪西康省政府委员（附逆嫌疑）','虽名义上为西康省主席，但曾与日军暗中联络，允许日军特务在成都、彭县一带活动，未积极抗日。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ee29d6957bef4617b021b180a7361fde','e63d5ea4717d4e168e4521b90283e2fc',1940,'伪四川省政府主席（附逆嫌疑）','在任期间对日军空袭成都、彭县等地应对不力，且与日方有秘密接触，被指消极抗日。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d0e0732bc04549c6baabaaffa7bc16a8','6058a91b52fd4d0aa64aeeea901b2fe1',1938,'伪成都警备司令（附逆嫌疑）','在成都地区镇压抗日群众，与日军特务机关有往来，为日军提供情报。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6eb1255251554e7589cd38a33a06cca5','fdd53bdcc70045969a774251d6838ef5',1937,'伪川康绥靖公署主任（附逆嫌疑）','在成都、彭县等地驻军期间，对日军侵略采取不抵抗政策，部分部下投敌。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a2f457b89de54f1b953322a1d653e4a8','c7b45efca7e349e7ac5a4104aac4c510',1938,'伪川陕鄂边区绥靖公署主任（附逆嫌疑）','在成都地区与日军特务有联系，纵容部下与伪军合作，破坏抗日统一战线。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e8f16f08eb9f4878835cd60cab299fbd','f2047645e60c49a4a3097aafe9dd87e5',1939,'伪贵州省主席（附逆嫌疑）','在四川、贵州交界地区与日军有秘密往来，其部队在成都附近曾与伪军配合行动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3e5955d0804147879001c3a1e6ad1813','82c8dc8c68f3449d85ce6770c252b411',1940,'伪四川省政府委员、伪成都市警察局局长','在成都地区充当日伪警察头目，负责搜捕抗日人士、监控市民，配合日军实施保甲连坐，迫害成都及武侯一带抗日群众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('31059f328f754173ae5857cfa0c9554b','79a1d0bfb70948939f91674397492343',1939,'伪成都县维持会副会长','成都县（含今武侯区部分区域）维持会骨干，为日军征集粮食、劳工，协助建立伪保甲制度，压制当地抗日宣传。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('12afcecf12734b97a14187e775049a03','1e21d27bd48647688dd41417c10de2a1',1941,'伪成都警察局特高课课长','在成都及武侯地区负责情报与镇压，逮捕抗日地下工作者，破坏成都抗日救亡团体，直接参与多起迫害事件。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3088bf259ed349a4b6552b445040d1b2','a60614ed1fbb4dc19cb5ca73a5defb77',1940,'伪四川省教育厅督学、伪成都中学校长','在成都教育界推行奴化教育，篡改教材，组织学生参加亲日游行，监视进步师生，为日伪培养亲日分子。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0ee050c72e104c359f8ac2a8df31b6d6','ecc969f1737c465bb38dc9ddf42d3960',1939,'伪成都商会会长','控制成都及武侯地区商业物资，为日军采购军需，强制商户缴纳“治安捐”，协助日伪经济掠夺。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('33d8fc0e0c0949e2a18deaa52f9abc45','c692801ac2c3420b89c5234722019808',1940,'伪成都保甲长、伪武侯乡维持会干事','在武侯乡（今武侯区）担任伪保甲长，登记户口、征发劳役，举报抗日家属，配合日伪清乡。','基层帮凶(维持会系统)','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ce4121fccdb04ebe8f197dfdc07f7124','759cfb5f46624562bc0d114d5292cbca',1941,'伪成都警察局武侯分驻所所长','在武侯地区直接指挥伪警察搜捕抗日人员，勒索商户，维持日伪统治秩序，迫害当地百姓。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fa5c68075d184b80907abccd469c529d','6fee2b329ee54681a24b19e7abf091b7',1942,'伪四川省宣传处成都分处处长','在成都及武侯地区组织亲日宣传，散发奴化传单，控制报刊广播，为日军侵略辩护，诋毁抗日力量。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dd2fdb5edf484bee8342d16c8e80d57e','046136a98d584e22aa075b053297ae5f',1941,'伪成都劳工协会会长','在成都及武侯一带强征劳工，送往日军工矿和军事工程，克扣口粮，导致大量劳工死亡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('81cd103d74b74a0d9cf7aa6625f13a90','62a6d6c8e7ab4bbfbc92c5b14abbde74',1938,'伪南京国民政府立法院长、伪上海市长','虽主要活动于南京、上海，但作为四川籍（或与四川有联系）的汪伪政权核心人物，其伪政权体系覆盖四川，间接影响成都、邛崃地区，推行亲日卖国政策。；汪伪政权核心人物，其伪政权体系覆盖山东包括威海地区，推行亲日卖国政策。；汪伪政权核心人物，曾派人到广西南宁、上林一带联络地方势力，策动‘和平救国’活动。；汪伪政权核心人物，活动于南京、上海，与广西玉林无直接关联。；汪伪政权核心人物，其伪政权名义上统辖包括河南在内的华中沦陷区，对河南伪政权有影响。；汪伪政权核心人物，其伪政权试图向陕西等后方渗透。；汪伪政权核心人物之一，参与汪精卫投敌集团，其伪政权对全国包括陕西的抗日力量进行政治诱降和破坏。；汪伪政权核心人物之一，参与伪政权统治，其伪政权名义上覆盖包括陕西在内的沦陷区。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b8b48764cd4a4bb992d756ee993f447b','a2e4190c87b449e685d78c118a6801b5',1938,'伪南京国民政府财政部长、伪警政部长','汪伪政权核心成员，其财政与警政体系延伸至四川，对成都、邛崃地区的伪政权运作有间接影响，参与对日经济合作与物资统制。；汪伪政权要员，其财政与警政体系延伸至山东各地，包括威海环翠地区，协助日军经济掠夺与治安控制。；汪精卫伪政权核心人物，掌管伪政权财政与警察系统，其政策影响包括河南在内的沦陷区，推行经济掠夺与特务统治。；湖南沅陵人，汪伪政权要员，负责伪财政与警政，其政策波及河南，包括南阳地区的经济掠夺与伪警察体系。；汪伪政权核心人物，参与统治华中沦陷区，其财政、警政体系延伸至河南部分沦陷区。；汪伪政权要员，参与伪政权对陕西等地的政治宣传与渗透。；汪伪政权重要成员，负责伪财政与警政，配合日军在沦陷区推行殖民统治，对陕西等后方有情报与破坏活动。；汪伪政权核心成员，负责财政与警政，配合日军在沦陷区的统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d87d164f54be469a938469325dbfc906','4f8793c77ca74d3dbe773329337bfbb0',1938,'伪中华民国维新政府行政院长','伪维新政府首脑，其势力范围涉及华中，与四川成都、邛崃地区的伪政权有间接联系，协助日军在占领区推行殖民统治。；华中伪政权头目，其伪政权与四川无直接关联，但作为全国性汉奸代表，其活动影响波及四川。；伪维新政府首脑，其伪政权与四川地区伪组织有联系，影响成都地区附逆势力。；福建长乐人，1938年在南京成立伪维新政府，统辖包括安徽在内的华中沦陷区伪政。；在南京组织伪维新政府，其统治区域包括安徽部分地区，后并入汪伪政权。；福建人，但在安徽及周边地区有伪政权活动，后并入汪伪政权，其统治范围涉及安徽部分地区。；组织伪维新政府，其伪政权下辖安徽沦陷区，滁州、凤阳等地维持会与伪县政权在其体系内运作，为日军侵华提供行政支持。；1938年在南京成立伪维新政府，任行政院长，后并入汪伪政权，任伪监察院长，抗战胜利后被处决。；福建长乐人，1938年在南京成立伪维新政府，任行政院长。该伪政权控制江苏、安徽等沦陷区，黄山、休宁地区在其势力范围内。；安徽籍（一说福建），1938年在南京成立伪维新政府，任行政院长，后并入汪伪政权，任伪监察院长，1946年以汉奸罪被处决。；安徽合肥人，1938年在南京成立伪维新政府，任行政院长，后并入汪伪政权，任伪监察院长等职，是华中伪政权重要头目。；安徽籍，抗战初期在南京组织伪维新政府，任行政院长，后并入汪伪政权。；伪维新政府首脑，其政权影响覆盖山东部分地区，配合日军在青岛及周边地区的统治与掠夺。；组织华中伪政权，与日军合作，其伪政权体系对包括广西在内的南方地区有政治诱降与渗透影响。；华中伪政权头目，后并入汪伪，对广西无直接活动，但作为汉奸整体名录可列。；华中伪政权头目，后并入汪伪政权，其伪政权体系影响华南包括广西周边。；活动于南京，与广西玉林无直接关联。；广西籍（桂林）汉奸，组织伪维新政府，后并入汪伪政权，任伪监察院长。；在南京建立伪维新政府，与日本合作，推行奴化政策，镇压抗日活动。；在南京成立伪维新政府，与日本签订卖国条约，征收苛捐杂税，迫害爱国人士；在南京成立伪维新政府，与日本合作，推行奴化政策，镇压抗日活动。；在南京建立伪维新政府，与日本合作推行奴化政策，镇压抗日活动。；在南京成立伪维新政府，推行汉奸政策，协助日军统治江苏及南京地区，后并入汪伪政权。；在南京建立伪维新政府，统治江苏包括南通、如皋，为日军服务。；福建长乐人，抗战初期在上海组织伪维新政府，后并入汪伪政权，任监察院长等职，其伪政权势力曾覆盖包括江西在内的华中沦陷区。；福建长乐人，1938年在南京成立伪维新政府，后并入汪伪政权，任监察院长等职，为华中沦陷区重要汉奸头目。；伪维新政府头目，其政权在华中沦陷区包括江西部分地区推行伪政，为日军服务。；组织伪维新政府，管辖华中沦陷区，包括江西九江部分沦陷区，推行伪化统治，为日军搜刮物资、征发劳工。；福建长乐人，抗战期间组织伪维新政府，后并入汪伪政权，任监察院长等职，其伪政权势力范围涉及华中、华东包括江西部分地区。；抗战初期投敌，组织伪维新政府，管辖华中地区，其势力范围涉及河南南部，配合日军统治沦陷区。；华中伪政权头目，其伪政权管辖包括河南部分地区，后并入汪伪政权。；福建长乐人，生于浙江，抗战期间组织伪维新政府，后任伪监察院长，为日军侵华提供政治支持。；福建长乐人，但长期在浙江活动，曾任伪维新政府首脑，后并入汪伪政权，任伪监察院长，1946年被处决。；其伪政权势力曾延伸至浙江沿海，包括舟山，组织伪军和税收机构。；福建长乐人，抗战期间投靠日军，历任伪中华民国维新政府行政院长等职，在华中地区推行伪化统治，其活动范围涉及湖南。；福建长乐人，伪华中政权头目。活动于南京、上海，与湖南株洲石峰无直接关联。；华中伪政权头目，其伪政权体系曾覆盖湖南部分沦陷区，对永州地区伪维持会有间接影响。；福建人，华中伪政权头目，其伪政权影响范围包括湖南部分沦陷区。；福建长乐人，华中伪政权头目，活动于南京、上海，与湖南郴州、桂阳无直接关联。；福建长乐人，华中伪政权头目，与湖南郴州、汝城无直接关联。；福建长乐人，伪维新政府头目，其伪政权与湖南长沙地区有间接统治关联，后并入汪伪。；早期伪政权头目，其势力未直接进入万州，但与重庆方面有情报往来。；伪维新政府头目，其伪政权与重庆地区有地下联系，战后被处决。；在南京组建伪政权，后并入汪伪政权，战后以汉奸罪被处决。；1938年在南京成立伪维新政府，任行政院长，与日本合作，后并入汪伪政权，任伪监察院长等职，是华中地区重要汉奸。；伪维新政府首脑，主要活动于南京、上海，与重庆沙坪坝无直接关联。；在华中组织伪政权，与华北伪政权呼应，对包括陕西在内的抗战后方构成威胁。；在南京组建伪维新政府，与华北伪政权呼应，其伪政权网络涉及华中、华北，对陕西等地抗日后方有渗透和破坏。；投靠日本，组建伪维新政府，配合日军在华东及华北包括陕西周边地区进行殖民统治。；在华中、华北沦陷区组织伪政权，配合日军统治。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7805489bd7514c19a728e0087edcb6b6','2a262f27f5df4bb493c9cf9285d13aa5',1937,'川军将领（后投敌）','原为川军领袖，抗战初期曾率部出川，但后与日军秘密接触，意图投敌，其活动范围覆盖成都、邛崃，对当地抗日力量造成破坏。','无明确职位或一般帮凶','hanjian');
