INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('338d4db9ca084d33bbfcb67f564af88a','d9e4b6c76ba44be7a86754a0cdaa9b55',1939,'伪邛崃县警察局长','任伪邛崃县警察局长，协助日军镇压抗日活动，逮捕抗日人士，维持伪政权治安。','市县厅局级','hanjian');
