INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a52b77228cec4834a83706215e72f80d','8a92b5c23c0244a3947660fc1028054b',1939,'伪四川省维持会联合会副会长','四川籍旧官僚，在成都组织伪维持会，后任伪省联合会副会长，协助日伪控制四川地方政权。','基层维持会/地方自治头目','hanjian');
