INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('67b62bb5f09b4beea825f1436590916b','4cc5391bc78947fa9bf1a4b59e0f5371',1937,'伪天津特别市市长','曾任伪天津市市长，推行日伪统治政策，协助日军控制天津地区，包括东丽（时属天津县）的治安与经济掠夺。；曾任伪天津特别市市长，在任期间配合日军强化治安，迫害抗日人士。；曾任伪天津市市长，推行日伪统治政策，协助日军进行经济掠夺和治安维持。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a61c682f3d1440f6b72fb57799b5e200','5b2f7fb20693426f81f3853beb962949',1937,'伪天津特别市市长','继任伪市长，继续为日本侵略服务，强化对天津及周边地区（含东丽）的殖民管理，征粮派款，镇压抗日活动。；继任伪天津特别市市长，协助日军实施经济掠夺和殖民统治，参与奴化教育推广。；投靠日军，任伪天津市市长，推行奴化教育，镇压抗日活动，协助日军经济掠夺。；任伪天津特别市市长，积极推行日本殖民政策，组织保甲制度，搜刮民财，镇压抗日力量。；投靠日本，出任伪天津特别市市长，协助日军管理天津，推行奴化教育，强征物资，迫害抗日人士。；曾任伪天津市长，积极推行日伪政权各项政策，配合日军“治安强化运动”，镇压抗日力量，出卖天津利益。；管辖包括红桥在内的全市，推行奴化教育，强征劳工，为日军提供粮食和军需，镇压抗日活动。；与冀东伪政权合作，参与对河北东部沿海地区的统治；投靠日本，在天津伪政权中任职，配合日军统治，对陕西有间接影响。；在天津伪政权中任职，配合日军经济统制，其活动与陕西无直接关联。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('659af049fe5d459db314b282d449595a','51192a4e4b374279b0ff570839a34590',1938,'伪天津县知事/县长','作为伪天津县行政长官，管辖包括东丽在内的区域，配合日军清乡，强征民夫，实施保甲制度。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('44d04f02a2d94a0e957cde7197537c60','5e3c03e59a9d4a4f81ce0c0f481fb548',1940,'伪天津县知事','在任期间协助日军推行“治安强化运动”，在东丽地区（如军粮城、赤土一带）设立据点，搜捕抗日分子。','基层头目','hanjian');
