INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('19117d0b75bd4bbd980c7fbed5fd27a5','a23958f2a093468d8476a9eec1ddb6a8',1937,'伪华北政务委员会委员长（曾兼天津地区事务）','作为华北伪政权高层，其政策直接影响天津及东丽地区，支持建立各级伪政权，协助日军经济掠夺。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f3df61268fc94090b14430270ce32238','ac60ab9d3fbd4dc298e96a4ed6ba2090',1938,'伪天津特别市警察局局长','在天津及东丽地区建立特务网络，抓捕抗日志士，协助日军宪兵队进行残酷镇压。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f521883943a64e23a4603bbc3bf2171d','0e99e1bdfa104024a691cc686112827c',1937,'伪天津青帮头目/汉奸特务','在天津东丽一带经营赌场烟馆，为日军搜集情报，参与迫害抗日群众，是地方恶霸型汉奸。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('db5017a99d184c68a7987c630c054d85','3367084ffd7a4ca385f4b2b235cedadb',1940,'伪天津县保安队队长','率伪保安队在东丽地区（如大毕庄、金钟河沿岸）巡逻，协助日军封锁交通，抓捕抗日人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e3e7be8a49804896a0d4d6ea31b38517','51192a4e4b374279b0ff570839a34590',1937,'伪天津特别市市长','曾任伪天津市治安维持会委员长，后任伪天津特别市市长，积极推行日伪政权统治，镇压抗日活动。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f4b2b3d280b94f00b33179468d5f2558','d213e678be7a4643aa692cec4094c637',1937,'伪天津特别市警察局局长','长期担任伪天津警察机构负责人，协助日军搜捕抗日分子，镇压民众反抗。','市县厅局级','hanjian');
