INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5df61b4e8f0a4d848bf4c309428bec41','a23958f2a093468d8476a9eec1ddb6a8',1937,'伪天津特别市公署顾问','曾任北洋政府总理，后投靠日伪，在天津担任顾问，为日伪政权出谋划策。；为日伪政权出谋划策，参与制定奴化教育政策。','无明确职位或一般帮凶','hanjian');
