INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ea652bd93267447488618e78ee779d71','c962700c3422426b946336b59832e9d0',1935,'伪冀东保安队司令','率伪保安队在宝坻、宁河一带扫荡抗日武装，杀害无辜百姓，为日军充当帮凶。；率伪保安队配合日军在唐山、丰润、汉沽一带“扫荡”，屠杀抗日军民，制造多起惨案。；原为冀东保安队头目，投日后任伪司令，在唐山、芦台一带协助日军清乡，镇压抗日游击队。；指挥伪冀东保安队，协助日军维持治安，在秦皇岛、北戴河地区镇压抗日武装，抓捕爱国人士。','基层头目','hanjian');
