INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2e749545cbd74398b2d18a9b87328764','e7a1b79fb7384e32a3ad68a5f1ebfd36',1938,'伪天津河东区税务局长','为日军征收各种苛捐杂税，强征民间财产，导致河东地区民生凋敝，民众苦不堪言。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('823f92ccc3a340489db00228f61e0dd1','83b067447f4744f7b527179c4d9524d4',1935,'伪冀东防共自治政府秘书长、代理委员长','殷汝耕亲信，参与冀东伪政权运作，在冀东地区推行亲日政策，协助日军清剿抗日力量。','机构委员长(非国家首脑)','hanjian');
