INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('965c0d9b15364d2baf25dca0501be784','5f82d23ccd2e45fd9e59f76c92bcc9ad',1936,'伪蒙古军政府总司令、伪华北绥靖军副司令','原热河地方军阀，投日后在察哈尔、河北北部（含天津北部）配合日军作战，参与“治安肃正”行动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8c314216b19249b0b50b50b885f34889','bf398d44782c4c1594ef5ef1eecbf521',1937,'伪河北省省长','原北洋军官，投日后任伪河北省长，在保定、石家庄等地推行保甲制度，强征粮食，协助日军“扫荡”冀中、冀南根据地。；伪河北省长，与山东聊城地区伪政权有协同，推行治安强化。；原国民党地方官员，投日后任伪河北省省长，在石家庄、井陉矿区强化日伪统治，配合日军对冀中、冀西抗日根据地进行“扫荡”和“清剿”。；作为河北伪政权最高头目之一，推行日军政策，在包括邢台、南和在内的河北各地建立伪组织，征发劳工与物资。；作为伪河北省最高行政长官，推行日军政策，在包括邢台、柏乡在内的河北各地强化伪政权，镇压抗日运动。；投敌后任伪河北省省长，协助日军在河北推行治安强化运动。；在河北沦陷区任伪省长，协助日军征粮、征兵。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b83e759d1c114321aadd501e94a8299c','51ceebe33eeb4f9cb54cb104d5f88f7c',1943,'伪河北省省长（继任）','投日后接任伪河北省长，在河北推行“新国民运动”，配合日军抓丁拉夫，镇压抗日群众。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ade385908c804a5fbabb7b8416f7fa6e','e409ef959281461b91e8ce1eef37d186',1938,'伪河北省保安司令、伪华北绥靖军第1军军长','原东北军将领，投日后在河北组织伪保安队，多次参与对冀中、冀西抗日根据地的进攻。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('beda43e0df994504bab7809e47186d83','a23958f2a093468d8476a9eec1ddb6a8',1937,'伪天津特别市市长（首任）','原北洋政客，天津沦陷后投日，任伪天津市长，协助日军接管天津，推行殖民统治，镇压抗日活动。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('659a5e902b264fc892b28983a361cc82','10b88f41fdee46778f29f60ae3d41741',1938,'伪天津特别市市长（第二任）','原北洋官员，投日后任伪天津市长，在天津实施粮食统制，配合日军经济掠夺，逮捕抗日志士。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d4b79bcb44a64f9689fee20539003d9a','5b2f7fb20693426f81f3853beb962949',1943,'伪天津特别市市长（第三任）','原外交官，投日后任伪天津市长，推行奴化教育，为日军提供劳工和物资，镇压地下抗日组织。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('015d991da0484e189372ae1f867c67ec','979aa5c5b60a46e19b1eee8673025156',1937,'伪天津特别市公署顾问、伪华北政务委员会参议','原天津文化界名人，投日后为日军在天津的文化侵略和殖民宣传服务，协助伪政权管理天津。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7e733a2e08b943d2966176b947848c68','4cc5391bc78947fa9bf1a4b59e0f5371',1938,'伪冀东道尹、伪唐山市长','原北洋官僚张弧之子，投日后在冀东（唐山、秦皇岛一带）任伪职，协助日军控制冀东矿区，镇压工人抗日运动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c96c5c49756243cca0cdc0f0ad008288','d4758e42e7f24310a9f4549105631eab',1939,'伪冀南道尹','投日后任伪冀南道尹，管辖邢台、邯郸等地，推行“治安强化”运动，配合日军对冀南根据地的“囚笼政策”。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b813087f0773401c8f4eb6230c0f3823','a33454260f164ccbaf804a92bde3f82e',1938,'伪保定道尹','投日后任伪保定道尹，在冀中地区建立伪组织，强征民夫修筑碉堡公路，协助日军封锁抗日根据地。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4e14239d7f5f4b8fbc7b7efc86cc8ebb','c705615e41c244a09a562a3159d22710',1938,'伪津海道尹（天津周边地区）','投日后任伪津海道尹，管辖天津周边各县，推行伪政权法令，配合日军“清乡”行动。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('55ce1084e7ad4edeb0972972d8873715','892cdd9ae3d2444996fbaf7f65134db1',1937,'伪华北政务委员会咨询委员（未正式就任但参与活动）','原北洋交通系领袖，虽未任实职，但多次为伪华北政权出谋划策，在天津、河北有广泛人脉，协助日军拉拢旧官僚。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9e868660ea08490da4e842171780baf0','3fef5234abca416989d5067495ea377b',1937,'伪华北政务委员会经济顾问','原北洋外交官，投日后在天津、河北为日军经济统制提供方案，参与掠夺华北资源。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e20a3b2aa52f494a971e28a47ab0c5b0','9d4da38d6dd54a8d954f03b493371758',1937,'伪华北政务委员会法制顾问','原北洋政客，投日后在北平、天津参与伪政权法律制定，为日军殖民统治提供合法性包装。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ed83d6e90525414b9abdf3c37844da21','2ee2f8df0cc74ae0900efaa9d71d9a23',NULL,'（本人未投日，其旧部如）','（此条为说明：孙传芳本人拒绝投日，但其旧部如周荫人、卢香亭等部分在河北投日，但无具体任职记录，故不列入。）','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1ff02dd629b54c5480d0b3a1aafbeb2e','848cb7360b764d3ebafb57e017371c2a',1938,'伪华北绥靖军高级顾问（未公开任职但参与）','原直系将领，投日后在天津、河北为伪军训练提供军事指导，协助齐燮元整编伪治安军。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f6a3509fa6b14efabc2f536d543296eb','3f4c3c87f5104ccda461fdb2390d2a6e',1937,'伪冀东保安队顾问','原孙传芳部将，投日后在冀东地区协助日军训练伪军，参与镇压冀东抗日暴动。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8c47837d28164dfe99e463fa8fb2dcf6','a976a94be0bf4b76b621948c0802222f',1933,'伪华北绥靖军总参议（未及就任被刺杀）','原北洋皖系军阀，1933年受日军指使在天津、河北策划华北自治，被军统刺杀于北平六国饭店。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8d6273f4cee54a97ba37d020368fb55a','a52d82089a804187b2198be492c8000a',1940,'伪冀察战区副总指挥（投日未遂被处决）','原西北军将领，在河北南部与日军秘密勾结，企图投敌，被高树勋处决，未及正式投日。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ff317a116d2e41b58cd9eaa8b5b8bfd5','5ec2ad124b2f429482b1a90a7f8d4a92',1943,'伪第五方面军总司令（投日后）','原国民党第24集团军总司令，1943年在太行山被俘投日，其部队活动范围涉及河北南部，协助日军进攻冀鲁豫根据地。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('74e767585d134be39cb593ec56d1436b','9f7b3ed9c76f4eea8211fd8ebc40a461',1943,'伪新编第五军军长（投日后）','原国民党将领，1943年投日，在河北、河南交界地区配合日军作战，袭击八路军。；1943年在河南投日，所部被编为伪军，驻防豫西、豫北，其活动与洛阳、新安地区日军占领体系相配合。','市县厅局级','hanjian');
