INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ba9a9adfd8e24edc8ef3c664368001f2','458c76dce77443c2a54babb18e339db0',1939,'伪华北绥靖军第2军军长','原西北军将领，投日后在河北保定、石家庄一带驻防，多次率伪军进攻冀中根据地。','市县厅局级','hanjian');
