INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('969ff8d77def41c7a78442496aca6c5e','2065d53788cb446db1cb50dcd0173c1f',1941,'伪华北绥靖军第4军军长','原直系军官，投日后在天津以南地区驻防，协助日军“清剿”冀中八路军。','市县厅局级','hanjian');
