INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cc0c43a5aee14d6485306052acdf0133','0e99e1bdfa104024a691cc686112827c',1937,'伪天津青帮头目、特务','天津青帮头子，投靠日军，在天津开设赌场烟馆，协助日本宪兵队抓捕抗日分子，参与“治安维持会”。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cfd032226af74174afce28500f5716ee','f5b897c8eed441daad9392929fd1abfa',1938,'伪天津警察局特高课课长','投日后在天津警察局特高课任职，专门破坏中共地下组织，逮捕多名抗日志士。','无明确职位或一般帮凶','hanjian；traitors');
