INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2969bf30ba4b4c42b50087c56b43ded5','9a58a6d0ca124e4e8470270a43ef0a46',1937,'伪天津特别市警察局局长','任伪警察局长期间，协助日军搜捕抗日志士，破坏地下抗日组织，实施白色恐怖统治。；统领伪警察，协助日军抓捕抗日地下工作者，破坏中共地下组织，实施白色恐怖。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a661e2b515454ae8be4792a8fa3fc43a','10b88f41fdee46778f29f60ae3d41741',1937,'伪天津特别市公署秘书长、伪河北省省长','早年参与亲日活动，后任伪职，参与签订卖国协定，协助日军管理天津及河北地区，迫害抗日民众。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('14a26a2830b243f0a785d2044b1bce4a','a23958f2a093468d8476a9eec1ddb6a8',1937,'伪天津治安维持会会长','天津沦陷初期组织伪治安维持会，为日军建立殖民秩序提供帮助，协助日军接管市政。；日军占领初期在红桥地区组织维持会，为日军提供向导和情报，协助清剿抗日武装。；日军占领天津后组织维持会，为日军征粮派款，维持殖民秩序，后任伪河北省省长。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('23dc1d632908491c8694ffd377cc8f41','979aa5c5b60a46e19b1eee8673025156',1937,'伪天津特别市公署顾问、伪华北政务委员会委员','长期在天津为日本侵华效力，参与伪政权决策，为日军提供情报和治理建议。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('16e729e8d82a42119df7c295d6cb2cac','834538baa9d748099421f383f0d31b7d',1938,'伪天津特别市财政局局长','负责为日伪政权搜刮天津财税，发行伪币，掠夺民间财富，支持日军战争经济。','市县厅局级','hanjian');
