INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4bd1c04b9bc64a5d9cdc9c494326e81b','e37d968a5b0a4fdab1bf9c0699b25ee1',1938,'伪蓟县县长','在蓟县（今蓟州）任伪县长，组织伪警备队，配合日军扫荡抗日根据地，强征民夫。','基层头目','hanjian');
