INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('587833b192f64d62bb1b570c71a7707f','51192a4e4b374279b0ff570839a34590',1937,'天津商会会长、伪天津市治安维持会委员','七七事变后投靠日军，参与组织伪天津市治安维持会，协助日军维持占领区秩序，后遭抗日志士刺杀身亡。','基层维持会/地方自治头目','hanjian');
