INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('16408643adc447eba1e215f2656e472f','5e3c03e59a9d4a4f81ce0c0f481fb548',1938,'伪天津市商会会长','为日军筹措军费，强制摊派商业捐税，协助日伪经济掠夺。','基层头目','hanjian');
