INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('24fe7f22dcb2401ba428c6714208d1d4','958126f1f3204c0dbf95ed387984c6ad',1938,'伪天津特别市财政局局长','为日军搜刮钱财，发行伪币，控制税收，支持侵华战争经费。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2c745d789c0a4458bcf0a442b882583d','979aa5c5b60a46e19b1eee8673025156',1938,'伪天津教育督办','推行奴化教育，篡改历史教材，强迫学生参拜日本神社，打压爱国师生。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7fd9aae32db940b79d43339212cff082','913f76cdd83b406aa50aefce29389ccb',1938,'伪静海县知事','在静海县任伪知事，为日军征粮、抓夫，建立伪乡村政权，镇压抗日游击队。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ec3f3128ce934a41afc8a225dea28250','27fb3fce28864568aac4081b36d83aad',1942,'伪静海县公署县长','继任静海伪县长，配合日军“扫荡”，强征民夫修筑炮楼，迫害抗日家属。','基层头目','hanjian；traitors');
