INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2dc19c499d79431594da02ef8203453f','75a43f442f1b4be4ac05571d8e7cddae',1940,'伪静海县警察所所长','指挥伪警察搜捕地下党员，破坏静海地区抗日联络站，参与刑讯逼供。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4e2c063cd2164106ab5b4ddd65d2faaf','2ee56f844baf4bca92d298be46e2c451',1938,'伪静海县新民会会长','组织新民会宣传“中日亲善”，诱骗青年参加伪军，收集抗日情报。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('05945ac7f046469ea74191c522892765','6a89fad0f513410089f90e82d3e7934f',1941,'伪天津地区剿共司令','统率伪军多次对静海、大港等地区进行“清乡”，烧杀抢掠，制造无人区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6bd3718ada9e4107947078a8b7dd2503','ac60ab9d3fbd4dc298e96a4ed6ba2090',1939,'伪天津特别市社会局局长','控制社会团体，强制推行“治安维持会”制度，迫害进步工人和市民。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ac17befa6daa468489f76a80e8ddde38','da58b77853f14ce7b32f7f6b3305b75a',1939,'伪华北治安军总司令（兼天津驻军）','虽总部在北平，但多次指挥伪治安军在天津、静海地区作战，围剿抗日武装。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cef5597f88244bb8aa01a018e4aa9e57','8f1dd12e548b4c4f866dd743c3377896',1940,'伪华北政务委员会委员长（影响天津）','作为华北伪政权首脑，直接管辖天津伪政府，推动“强化治安”运动。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b00595e63d664fbfafe501b1b5db64b4','b5ba32ac9dee4113808d7f1e4475b119',1935,'伪冀东防共自治政府主席（影响静海）','虽以冀东为主，但曾将静海部分地区纳入伪政权势力范围，协助日军控制交通线。','地方伪政权首脑','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('54f682ba79e14976af431dc475189f0d','f963dffd622f436095c6b9c772ecf7db',1933,'宁夏省政府主席、国民党军第八战区副司令长官兼第十七集团军总司令','长期主政宁夏，抗战期间虽名义上隶属国民政府抗日阵营，但实行军阀割据，消极抗日、积极反共，与日伪方面存在秘密接触和妥协，纵容部下与沦陷区日伪势力进行走私贸易，对宁夏及吴忠地区民众横征暴敛。；长期主政宁夏，抗战期间虽名义上隶属国民政府抗日序列，但消极抗日、积极反共，与日伪方面存在秘密接触和妥协，纵容部下与日军暗通款曲，保存实力，对宁夏及石嘴山地区抗日力量进行压制。；长期主政宁夏，抗战期间虽名义上隶属国民政府抗日阵营，但实行高度独裁统治，消极抗日、积极反共，与日伪方面存在秘密接触和暧昧关系，纵容部下与沦陷区日伪势力进行走私贸易，搜刮民财，镇压进步力量。；长期主政宁夏，对日妥协倾向明显，消极抗日、积极反共，压制宁夏抗日救亡运动，与日伪方面有秘密接触和情报往来，其统治被视为对宁夏抗战力量的严重削弱。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('63e78490893e423882b22e2328f1f6ce','381b7663b3a3429f8889b35efd6a7a77',1930,'国民党军第八十一军军长、宁夏省政府委员','宁夏地方军阀，抗战期间率部在绥西一带抗日，但同时在宁夏吴忠等地维持军阀统治，与日伪方面有暗中往来，其部属中存在与伪蒙疆政权勾结的情形。；抗战期间在宁夏地区虽曾参与绥西抗战，但立场摇摆，与日伪势力有暧昧关系，对辖区内抗日活动限制较多，其部属在石嘴山一带与伪蒙军有接触。；宁夏地方军阀，抗战期间率部在绥西一带驻防，与日伪军有局部接触，曾参与对日作战，但同时也存在保存实力、与伪蒙疆政权方面人员进行私下联络的行为。；在宁夏及绥西地区与日军作战中态度摇摆，部分部队与伪蒙军有默契，对抗日力量支持有限，其部属在绥西与日伪势力有妥协行为。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2918486900dc49e0866000794d06b6b2','f28330eb828a4a6bab2717ec3e6a91e4',1938,'伪宁夏回教联合会会长、日伪策反对象','抗战期间被日军特务机关拉拢，参与策划在宁夏吴忠、灵武一带煽动回民脱离中国，配合日军建立伪回教政权的图谋，后因事泄未果。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f8f4c7818b3c45bfb1c4857dca221915','4e9cdf8ff81d4a01b96c713085ea4a3c',1939,'伪蒙疆联合自治政府宁夏工作员','受伪蒙疆政权派遣，潜入宁夏吴忠、金积、灵武等地，联络地方士绅和回教上层，宣传日伪‘回回国’计划，搜集情报并策反地方武装。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2c30e87f25b5454bbf14c9a73192f9e7','c8fa03f5c44b431494d779d80e51c17d',1938,'吴忠堡维持会会长','在日军进犯绥西、威胁宁夏期间，于吴忠堡组织维持会，准备迎接日军，协助日伪征收粮草、拉夫，后因日军未占领宁夏而解散。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4d343443417a4c7a8b5bcd2006a6aab4','c79cb2a87fab4bb1b321d76dbdd71100',1939,'金积县伪警察队队长','被日伪特务收买，在金积、吴忠一带组织伪警察武装，为日伪搜集宁夏军事情报，并参与走私鸦片和军需物资。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5ca73be91a954ee6b66c69fd6e3d4971','f9dff5cb6ff446ffb3c2c2908970c2c0',1940,'伪宁夏回民自治军司令','受日军特务机关指使，在吴忠、同心一带招募回民武装，企图配合日军进攻宁夏，建立伪回民自治政权，多次与国民党宁夏驻军发生冲突。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fa4b3b553b7c49159b738f7a35208abe','198f8336419043a3b5dc1ff6e589e3d4',1938,'伪蒙疆政府宁夏联络员','在吴忠、中宁、中卫等地活动，联络地方帮会和土匪，组织伪军，为日军提供宁夏黄河防务情报，并协助日伪在沦陷区训练回民特务。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dbf2d1f8c92b42cd905b2ff1d4a4531c','5568636875d04d38aa4cbdf969885441',1939,'吴忠堡伪保甲长','在吴忠堡担任伪保甲长期间，为日伪特务提供落脚点，协助其进行策反和情报搜集，并向当地商户摊派‘抗日捐’中饱私囊。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('902f7b463970429bb0d7790eef3f8018','51b9a9aeb6ab4cf1a14ea7c01f5ec704',1938,'灵武县伪维持会副会长','与吴忠堡维持会勾结，在灵武、吴忠一带为日军筹备粮秣、船只，准备协助日军渡黄河进攻宁夏，后因日军撤退而中止。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('76ba2155e67c4682a57daf3ebe54cc3b','4e9cdf8ff81d4a01b96c713085ea4a3c',1938,'伪宁夏维持会会长','日军侵占绥远后，在包头、五原一带活动，受日军指使筹组伪宁夏政权，拉拢宁夏地方士绅，企图在石嘴山、银川等地建立伪组织，为日军西侵服务。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e716395cc6c04179a4380702ae3f1840','5f82d23ccd2e45fd9e59f76c92bcc9ad',1936,'伪蒙古军政府副主席、伪蒙古联合自治政府副主席','率伪蒙古军配合日军进攻绥西，多次进犯宁夏北部石嘴山、磴口一带，烧杀抢掠，扶植伪政权，是活动于宁夏周边地区的重要汉奸头目。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6e8eebe443654ed0bf6d2a1bcc50343c','47cac7a73af140d39ff53133e8cfe760',1939,'伪宁夏边防军司令','原为东北军将领，后投靠日军，被派往宁夏北部石嘴山一带收编土匪武装，组织伪军，企图配合日军进攻宁夏。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e92240f1aa7849ce887f7c261a56f7d1','d085ed8229db48b4beb902c85269a925',1938,'伪宁夏回民自治政府筹备委员','受日军特务机关指使，在石嘴山、吴忠等地拉拢回族上层，筹组伪回民政权，为日军西进提供情报和物资。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4188a8b10930422ba14344ff70ceaeae','1e0a0160d8e04572acdaac1ebb169e3e',1938,'伪石嘴山维持会会长','日军进犯绥西时，在石嘴山地区组织维持会，为日军筹集粮草、情报，协助日军管理地方，压迫当地民众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c4e37959f97a4602b31626af4ecc0b06','15aba61e822c4e50a3d0ac9384c005f1',1939,'伪石嘴山警察局局长','在日军控制时期担任伪警察局长，配合伪政权镇压抗日活动，抓捕抗日人员，勒索百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('121008603d3c42d5b9b9fdda199131c3','82c8dc8c68f3449d85ce6770c252b411',1938,'伪宁夏保安队队长','率部投靠日军，在石嘴山、平罗一带为日军搜集情报，袭击抗日游击队，保护日军运输线。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7fbbd19321d0435ba625aed78bbd2a36','f9dff5cb6ff446ffb3c2c2908970c2c0',1938,'伪平罗县维持会会长','在平罗县组织维持会，为日军征粮派款，协助日军建立保甲制度，压制民众抗日。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('405ca239e5f5428e93dc6d64c29ad699','5d8f31a996174e0fbfe2713a13aa30e6',1939,'伪惠农县保甲长','在惠农县（今石嘴山地区）担任伪保甲长，为日军提供情报，协助抓捕抗日分子，催缴粮款。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4ce4779897d94e609c865516fc620360','ae8da03748604bd79c91e296c24b8341',1938,'伪宁夏教育会会长','在日军占领区推行奴化教育，编写亲日教材，组织学生参加亲日活动，为伪政权培养顺民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('52d4411ac0af4bcc8cc688cee5f16ac0','490a6af51377442cb708a6a47760ae2a',1938,'伪宁夏商会会长','为日军筹集物资，控制石嘴山地区商业，协助日军经济掠夺，压榨商户和百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5f377d91ab9f485aa5b31909c0455331','f28330eb828a4a6bab2717ec3e6a91e4',1938,'伪宁夏维持会会长（未实际就任，但曾与日方接洽）','日军侵占绥远部分地区后，曾试图在宁夏建立伪政权，马全良被日方拉拢，参与策划在银川地区组织维持会，后因马鸿逵控制严密未能公开就任，但曾向日军提供宁夏军政情报。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a2272fdc7af64530a3a5e0752f2f1f9b','4e9cdf8ff81d4a01b96c713085ea4a3c',1939,'伪蒙疆联合自治政府宁夏联络员','受伪蒙疆政权派遣，潜入宁夏银川及周边地区，联络地方士绅和回族上层，策动建立亲日伪组织，收集宁夏驻军情报，并协助日伪进行经济渗透和走私活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9d66cdda571649048f6d8aeec58af039','15ea40782cab4aeeaf9bc5cfb1c06443',1938,'宁夏省教育厅督学、伪银川维持会筹备委员','在日军空袭银川及周边期间，暗中与日伪特务机关联系，参与筹备伪银川维持会，并在教育界散布亲日言论，拉拢部分教师为日伪服务。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4ef85054bae346e2b5518010a1cb7ba9','3823c259ac6041f5aa72c29b47af4774',1939,'伪宁夏商会会长（日伪控制下）','在日伪势力渗透宁夏期间，利用商会身份为日伪采购物资、输送情报，组织商户与沦陷区进行非法贸易，从中牟利，并协助日伪在银川设立秘密联络点。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9ba7e0bf12174db39c9e4cda6d8a32bd','74372cb84947420a8ab2ca2f06fb28c8',1940,'伪蒙疆军宁夏支队支队长','率伪蒙疆军一部在宁夏北部与绥远交界地区活动，配合日军扫荡抗日武装，袭击八路军和地方抗日游击队，并在银川周边村镇强征粮草、抓捕抗日人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('af1ca09bf0e6421eaac8b32e54d2d05a','198f8336419043a3b5dc1ff6e589e3d4',1941,'伪宁夏保甲长、日伪情报员','在银川郊区担任保甲长期间，为日伪特务机关收集抗日军民活动情报，协助日伪抓捕进步人士，并组织村民为日军修筑工事、运送物资。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8e74aa80695e4917bcd0f78b9d88d968','c5bc1de2c4af4485be96a2fc0467cf4e',1942,'伪宁夏青年团团长','受日伪宣传机构指使，在银川及周边地区组织亲日青年团体，进行奴化宣传，拉拢青年学生赴沦陷区接受训练，为日伪培养后备人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('759be6767f4b4882a109f785a0d7b2db','6375fdd9ddc94d44bfc0cb3025879d65',1940,'伪宁夏警察局巡官（日伪控制时期）','在日伪势力短暂控制银川部分区域期间，担任伪警察巡官，带领伪警搜捕抗日分子，镇压民众抗日活动，并参与征收苛捐杂税。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0badb557329d419e89905f934f6a56f3','2e76231301494145a9d8177ef49c8fa6',1938,'伪西北回军总司令、伪宁夏省主席（未实际到任）','投靠日军，在包头、归绥等地组织伪回军，配合日军向宁夏、绥西渗透，企图在宁夏建立伪政权，从事分裂和破坏抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('52d0374d36b14aff8b526350e65afa89','ef6c08d0f52941eb82c78030ddb226af',1938,'伪宁夏省警务处长、伪银川市警察局长','在日军占领包头期间，受命筹建伪宁夏警察机构，在银川、贺兰等地招募伪警，镇压抗日分子，推行保甲连坐。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f73413f9d0a74719a084c076985acef5','0806580d2c7a479e84a3ccdbd55c1bd4',1938,'伪宁夏省维持会会长','在日军策动下于包头成立伪宁夏维持会，联络宁夏各地士绅，为日军提供情报和物资，协助建立伪基层政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e6459b4a3b25459180f2171289a8da6b','d085ed8229db48b4beb902c85269a925',1939,'伪宁夏回民自治会会长','在日军支持下组织伪回民自治会，在银川、贺兰、永宁等地进行亲日宣传，诱骗回族青年参加伪军。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0beac2d5d18646ad8f36a39bdab578d4','8b56c02e7e8549078859a9f6a821290e',1938,'伪宁夏省教育会会长、伪银川中学校长','在日伪控制区推行奴化教育，在银川、贺兰等地学校强制使用伪满教材，宣传“日满华亲善”，毒害青少年。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cdc57b0128d34761bc8a2bc0f579d820','f733a30af91543778c1525a94eeacc0c',1938,'伪贺兰县维持会会长','在贺兰县为日军征集粮食、牲畜和劳工，协助日军修筑工事，镇压当地抗日群众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5764a175a6f04337901f4f1a9b47a79f','51b9a9aeb6ab4cf1a14ea7c01f5ec704',1938,'伪银川市商会会长','为日军采购军需物资，垄断银川市场，配合日伪经济掠夺，压榨商户和百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2f7442b1f88e4409ad8d33ed5197de9b','f9dff5cb6ff446ffb3c2c2908970c2c0',1939,'伪宁夏省保安队队长','率伪保安队在贺兰山沿山地区搜捕抗日游击队员，配合日军扫荡，杀害抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a2e6a61ec4cf4373b47da040da719c84','0c9d9be7baba497bac5b4c4c48d4839b',1938,'伪宁夏省宣传处处长','在银川、贺兰等地散发亲日传单，组织“新民会”活动，为日军侵略辩护，瓦解民众抗日意志。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('defba133b2ab485998dd7b3265f6d730','8f1dd12e548b4c4f866dd743c3377896',1937,'伪安徽省省长、伪国民政府委员','安徽合肥人，北洋旧官僚，抗战期间投靠日本，任伪安徽省省长、伪国民政府委员等职，推行伪化统治，协助日军掠夺安徽资源。；安徽合肥人，北洋旧官僚，抗战期间投敌，任伪中华民国临时政府内政部长、伪安徽省省长等职，在安徽推行伪化统治，为日军搜刮物资、镇压抗日力量。；安徽合肥人，北洋旧官僚，抗战期间投靠日本，历任伪中华民国临时政府内政部长、伪安徽省省长、伪国民政府委员等职，在安徽推行伪化统治，为日军搜刮物资、镇压抗日力量。；安徽合肥人，北洋旧官僚，抗战期间投敌，任伪安徽省省长、伪国民政府委员等职，推行日伪统治，协助日军征粮、拉夫、清乡。；安徽合肥人，抗战期间投靠日本，历任伪中华民国临时政府内政部长、伪安徽省省长等职，在安徽推行日伪统治，搜刮民财，镇压抗日力量。；安徽合肥人，北洋政客，抗战期间投靠日本，任伪安徽省省长等职，推行伪化统治，协助日军搜刮物资、镇压抗日力量。；安徽合肥人，北洋政客，抗战期间投敌，任伪安徽省省长等职，推行伪化统治，为日军搜刮物资、镇压抗日力量。；安徽合肥人，北洋旧官僚，抗战期间投靠日本，任伪安徽省省长等职，推行伪化统治，为日军搜刮物资、镇压抗日活动。；安徽合肥人，北洋政客，抗战期间投靠日本，任伪安徽省省长等职，推行伪化统治，搜刮民财，配合日军清乡。；安徽合肥人，抗战期间投靠日本，任伪安徽省省长等职，推行伪化统治，配合日军在安徽各地包括宿州一带进行清乡、征粮和镇压抗日力量。；安徽合肥人，北洋旧官僚，抗战期间投敌，任伪安徽省省长、伪国民政府委员等职，推行伪化统治，协助日军掠夺安徽资源。；安徽合肥人，抗战期间投靠日军，历任伪中华民国临时政府内政部长、伪安徽省省长等职，在安徽推行伪化统治，搜刮民财，配合日军清乡。；安徽合肥人，北洋政客，抗战期间投靠日本，任伪安徽省省长、伪国民政府委员等职，推行伪化统治，为日军搜刮物资、镇压抗日力量。；安徽合肥人，北洋政客，抗战期间投靠日本，任伪安徽省省长等职，推行伪化统治，为日军搜刮物资、镇压抗日力量。；安徽合肥人，北洋旧官僚，抗战期间投靠日军，任伪安徽省省长等职，推行伪化统治，协助日军征粮、征丁，镇压抗日力量。；安徽合肥人，北洋政客，抗战期间投靠日伪，任伪安徽省省长等职，推行日伪统治，搜刮民财，镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cefc29def386411ba0d0e5277a7e6fee','83a92f4d9e894ddc95c8e9a351babc4f',1937,'伪安徽省省长、伪蚌埠维持会会长','安徽阜阳人，抗战期间组织蚌埠维持会，后任伪安徽省省长，配合日军在皖北推行伪政，搜刮民财，镇压抗日活动。；安徽阜阳人，抗战期间组织伪维持会，后任伪安徽省省长，协助日军维持占领区秩序，镇压抗日活动。；安徽阜阳人，抗战期间组织伪维持会，后任伪安徽省省长，协助日军控制安徽沦陷区，包括宿州、萧县周边地区的伪政权运作。；安徽阜阳人，北洋皖系旧官僚，抗战期间投敌，任伪蚌埠维持会会长、伪安徽省省长，在皖北地区推行伪政，为日军筹粮筹款。；安徽阜阳人，抗战期间投敌，历任伪蚌埠维持会会长、伪安徽省省长，在皖北地区推行伪政，配合日军清乡与物资征调。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('796719e192c048aab3d47c9d02cb8d01','3f934b1c263b4cd78c73d9700621e7bd',1938,'伪安徽省省长、伪南京特别市市长','原为北洋军人，投敌后历任伪安徽省省长等职，在安徽推行伪化教育、经济统制，协助日军维持占领区秩序。；抗战期间投敌，曾任伪安徽省省长，在安徽推行伪化教育、经济统制，协助日军维持占领区秩序。；抗战期间投靠汪伪政权，曾任伪安徽省省长，配合日军在安徽沦陷区推行伪化统治，后任伪南京特别市市长等职。；江苏崇明人，抗战期间附逆，曾任伪安徽省省长、伪南京特别市市长等职，参与汪伪政权，协助日军在安徽等地推行伪化统治。；江苏崇明人，抗战期间投敌，曾任伪安徽省省长，参与汪伪政权在安徽的统治，配合日军清乡与物资统制。；江苏崇明人，抗战期间投敌，曾任伪安徽省省长，协助日军在安徽沦陷区建立伪政权、征收粮赋、清乡扫荡，其辖区包括六安周边沦陷地带。；抗战期间投靠日军，曾任伪安徽省省长，协助日军在安徽沦陷区建立伪政权、维持会体系，镇压抗日力量，其辖区涉及皖中、皖西部分沦陷区域。；辽宁人，抗战期间投敌，曾任伪安徽省省长，参与组建安徽伪政权，配合日军清乡与物资统制，对安徽沦陷区民众实施压迫。；原北洋军人，投日后任伪安徽省省长，协助日军维持安徽沦陷区统治，后调任伪南京市长，其伪政权体系延伸至六安、合肥一带。；原为北洋及国民政府官员，抗战后投敌，曾任伪安徽省省长，参与组建安徽伪政权，协助日军维持占领区秩序、征粮征丁，其伪省政权对六安、霍山周边沦陷区有行政影响。；原为北洋军人，抗战后投敌，曾任伪安徽省省长，参与组建安徽伪政权，配合日军清乡与治安强化运动，其辖区涉及六安周边沦陷区域。；抗战期间任伪安徽省省长等职，参与汪伪政权在安徽的统治，推行奴化教育与经济掠夺。；抗战期间投靠汪伪政权，曾任伪安徽省省长，在安徽占领区推行伪化统治，配合日军清乡与物资统制。；原为北洋及国民政府官员，抗战期间投敌，曾任伪安徽省省长，后任伪南京特别市市长，参与汪伪政权在安徽的统治，其伪省政权对安庆地区实施控制与征敛。；抗战期间投靠汪伪政权，曾任伪安徽省省长，在安徽境内配合日军清乡、扫荡，镇压抗日活动。；原为北洋及国民政府官员，抗战后投敌，曾任伪安徽省省长，参与组建安徽伪政权，配合日军在安庆等地推行治安强化与清乡。；辽宁人，早年参加辛亥革命后投敌，曾任伪维新政府绥靖部长、伪安徽省省长，后任伪南京市长，参与汪伪政权对安徽沦陷区的统治，安庆一带在其伪省府管辖范围内。；原为北洋及国民政府官员，抗战后投敌。曾任伪维新政府绥靖部长、伪安徽省长，后任伪南京市长、伪江苏省长等职，参与汪伪政权对安徽沦陷区的统治与治安强化运动。；原为北洋及国民政府官员，抗战期间投敌，曾任伪安徽省省长，参与组建安徽伪政权，配合日军清乡、掠夺物资。；原为北洋军官，抗战后投敌，曾任伪安徽省省长，协助日军维持安徽沦陷区统治，后调任伪南京市长，其伪省政权对安庆、桐城地区有管辖权。；抗战期间投靠汪伪政权，曾任伪安徽省省长，在安徽境内推行伪化政策，协助日军征粮征税、清乡扫荡。；抗战期间附逆，曾任伪维新政府绥靖部长、伪安徽省长等职，参与安徽沦陷区伪政权建设，为日军统治提供行政支持。；抗战期间投敌，曾任伪安徽省省长，参与安徽沦陷区伪政权建设，配合日军进行经济掠夺与治安强化。；抗战期间投敌，曾任伪安徽省省长，后任伪南京特别市市长，参与汪伪政权，协助日军统治安徽部分地区。；抗战期间投敌，曾任伪安徽省省长，参与伪政权统治，配合日军在安徽占领区的行政控制与经济掠夺。；抗战期间历任伪安徽省省长等职，在安徽推行伪政权统治，配合日军经济掠夺和治安强化运动。；抗战期间历任伪职，曾任伪安徽省省长，参与安徽沦陷区伪政权建设，配合日军在宿州等地推行保甲制和征粮。；江苏崇明人，抗战期间投敌，曾任伪维新政府绥靖部长、伪安徽省省长、伪南京特别市市长等职，参与汪伪政权统治，为日军维持占领区秩序。；原为北洋军人，抗战后投敌，曾任伪安徽省省长，协助日军维持安徽沦陷区统治，在皖南包括池州一带推行伪化政策，后调任伪南京市长。；抗战期间在华中伪政权任职，曾任伪安徽省长，参与日伪对安徽地区的控制。；抗战期间投敌，历任伪维新政府绥靖部长、伪安徽省省长、伪南京特别市市长等职，参与汪伪政权，协助日军在安徽等地推行殖民统治。；原为北洋及国民政府官员，抗战爆发后投敌，曾任伪安徽省省长，参与组建伪政权，推行日军政策，后调任伪南京特别市市长。；原为北洋及国民政府官员，抗战后投敌，曾任伪安徽省省长，在安徽沦陷区建立伪政权体系，配合日军清乡、征粮、抓丁，滁州、凤阳一带在其伪省政权管辖之下。；原为北洋及国民政府官员，抗战期间投敌，曾任伪维新政府绥靖部长、伪安徽省省长、伪南京市长等职，参与安徽沦陷区伪政权建设，其辖区包括滁州一带。；原为北洋及国民政府官员，抗战后投敌，曾任伪维新政府绥靖部长、伪安徽省长，后任伪南京市长，参与安徽沦陷区伪政权建设，影响涉及滁州地区。；辽宁人，抗战期间投敌，曾任伪安徽省省长，主持安徽沦陷区政务，配合日军清乡与物资统制，其辖区包括滁州、明光一带。；原为北洋及国民政府官员，抗战后投敌，曾任伪安徽省省长，协助日军维持安徽沦陷区统治，其辖区包括滁州、来安等县。；原为北洋及国民政府官员，抗战爆发后投敌。曾任伪维新政府绥靖部长、伪安徽省省长，后任伪南京特别市市长。在安徽任内协助日军维持占领区秩序，镇压抗日活动。；原为北洋及国民政府官员，抗战后投敌。曾任伪维新政府绥靖部长、伪安徽省省长，后任伪南京特别市市长。在安徽任内配合日军维持沦陷区统治，滁州一带在其伪省政权名义管辖之下。；原为北洋及国民政府官员，抗战爆发后投敌，曾任伪安徽省省长，配合日军在安徽各地建立伪政权、维持会，推行保甲连坐，镇压抗日活动。；抗战期间投靠日军，曾任伪安徽省省长，参与组建安徽沦陷区伪政权，配合日军清乡、征粮与治安强化运动，其辖区包括蚌埠地区。；原为北洋及国民政府官员，抗战期间投敌，曾任伪安徽省省长，在安徽沦陷区建立伪政权机构，配合日军清乡与物资统制，蚌埠为其伪省政权重要活动区域之一。；抗战期间投敌，曾任伪安徽省省长，在安徽境内推行伪化教育、经济统制，配合日军清乡。；抗战期间投敌，曾任伪安徽省省长，在安徽境内推行伪政，配合日军征粮、征丁，镇压抗日活动。；抗战期间投靠汪伪政权，曾任伪安徽省省长，在安徽境内推行伪化行政，协助日军维持占领区秩序。；抗战期间投敌，曾任伪安徽省省长、伪南京特别市市长等职，在安徽地区推行日伪政策，配合日军清乡与治安强化运动。；抗战期间投敌，历任伪维新政府绥靖部长、伪安徽省长、伪南京市长等职，参与安徽沦陷区伪政权建设与清乡活动，对皖北地区抗日力量进行镇压。；抗战期间投敌，曾任伪安徽省省长，在安徽沦陷区建立伪政权机构，协助日军维持占领秩序。；抗战期间投敌，曾任伪维新政府绥靖部长、伪安徽省省长、伪南京特别市市长等职，在安徽沦陷区推行伪化统治，配合日军经济统制与治安强化运动。；曾任伪安徽省长，在安徽沦陷区推行伪化统治，配合日军清乡、征粮，其伪政权覆盖马鞍山、当涂地区。；原为北洋军人，抗战后投敌，曾任伪安徽省省长，协助日军维持安徽沦陷区统治，后调任伪南京市长，是汪伪政权在安徽地区的重要人物。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ed72a7366c834b57b265bcd96406556d','d1abe59a5d664bf18b442130fc0478a1',1940,'伪安徽省省长、伪宣传部部长','汪伪政权核心成员，1944年任伪安徽省省长，在安徽推行亲日宣传与伪化统治，配合日军“清乡”运动。；广东信宜人，汪伪政权宣传系统负责人，后任伪安徽省省长，在安徽进行亲日宣传与思想控制。；广东信宜人，汪伪政权宣传系统负责人，后任伪安徽省省长，在安徽沦陷区推行亲日宣传与奴化教育，其伪政权体系延伸至六安部分区域。；汪伪宣传系统头目，后任伪安徽省省长，在安徽沦陷区推行亲日宣传与奴化教育，其宣传网络覆盖六安部分区域。；汪伪宣传系统头目，后任伪安徽省省长，在安徽推行亲日宣传与奴化教育，其政策覆盖六安沦陷区。；汪伪政权宣传系统负责人，后任伪安徽省省长，在安徽推行亲日宣传与思想控制。；汪伪政权宣传系统负责人，后任伪安徽省省长，在安徽进行亲日宣传与奴化教育，配合日军统治。；汪伪政权要员，曾任伪安徽省省长，负责伪宣传与地方行政，配合日军进行思想控制与占领区统治。；汪伪政权要员，曾任伪安徽省省长，在安徽进行亲日宣传和伪化教育，配合日军统治。；广东人，汪伪政权宣传系统负责人，后任伪安徽省省长，在安徽沦陷区推行亲日宣传与奴化教育，影响滁州、明光等地。；汪伪政权宣传干将，后任伪安徽省省长，在安徽沦陷区推行亲日宣传与奴化教育，其伪政权覆盖滁州、来安等地。；汪伪政权宣传系统负责人，后任伪安徽省省长，在安徽推行亲日宣传、奴化教育，配合日军清乡扫荡。；汪伪政权核心成员，曾任伪安徽省省长，在安徽推行奴化宣传与伪化统治。；汪伪政权核心人物之一，曾任伪安徽省省长，推行亲日宣传与伪化教育，镇压抗日言论。；汪伪政权核心成员，曾任伪安徽省省长，在安徽推行亲日宣传与伪化教育，配合日军统治。；汪伪政权要员，曾任伪安徽省省长，在安徽推行奴化宣传与伪化行政，配合日军统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7d4586997291497ba936055abf823932','b4da42a8d0a3425abf10522d58c50b00',1938,'伪亳县维持会会长、伪亳县县长','亳县本地士绅，日军占领亳县后出面组织维持会，任伪县长，为日军征粮派款，维持地方伪秩序。；安徽亳县（今亳州谯城）人，抗战期间组织伪维持会，后任伪亳县县长，协助日军维持地方治安、征粮派款，镇压抗日群众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('346fd87233bb4d83b18aa8bd00ef8018','ae4981029ed64c368e40a8f9fd4f386a',1939,'伪亳县警察局局长','在亳县任伪警察局长，协助日军搜捕抗日人员，镇压民众反抗，维护日伪在亳县的统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('97621cb272bf4a58928af563afa18998','7afda6e05b9949d28074a369c144b4b0',1940,'伪亳县保安团团长','亳县本地武装头目，投靠日军后任伪保安团长，配合日军扫荡涡河沿岸抗日武装，残害百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9a590ebfe5b94266ae4ad81fa464c73a','e85c860125784750b27b7949a4e6e8a9',1938,'伪涡阳县维持会会长','涡阳人，日军侵占涡阳后组织维持会，任会长，为日军筹集物资，协助建立伪基层政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6cc1519cf9fe4608b22d42be4db9efdc','304399e6f8f94bd5912316df10e1ac2a',1939,'伪蒙城县县长','蒙城本地人，投敌后任伪县长，在蒙城推行保甲制，配合日军征丁征粮，镇压抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('466a631e67754af3bad524185885affa','0a01be81c0994d8b8574ce85ccb67dc9',1938,'伪阜阳县维持会会长','阜阳士绅，日军占领阜阳期间出面维持，任伪维持会会长，协助日军安民与征发物资。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('81c98eff46ca4212a8da640764f551ba','28b89fcbdbc0426a8e2b2bb23b572ec4',1938,'伪蚌埠市市长','蚌埠人，投敌后任伪蚌埠市市长，在皖北重镇蚌埠推行伪政，为日军提供情报与物资支持。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('619eb39a119d4036af6177634ade9196','ef112d84ad03423b9c9112a9594814bd',1938,'伪蚌埠维持会会长','蚌埠商人，日军初占蚌埠时组织维持会，任会长，协助日军稳定市面，征派粮款。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('36bbd6ee4da94005b7b67eba5cb00ce2','6b186890888c4ef59afd6a82a310d3ad',1943,'伪安徽省保安司令部副司令（后投敌）','原国民党将领，后率部投敌，任伪安徽省保安司令部副司令，在皖北配合日军进攻抗日根据地。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d463136585ad4d36a846cdff8844fe0d','40ceda4a3fba43bb8c30faefaa993de4',1943,'伪和平建国军第三方面军总司令','原国民党新编第四师师长，1943年投敌，所部在安徽、山东交界地区配合日军扫荡，后任伪军要职。；原国民党军将领，1943年投敌，任伪第三方面军总司令，活动于山东、安徽北部地区，配合日军扫荡。；原国民党军将领，1943年投敌，所部伪军活动于山东、安徽北部。；原国民党军将领，投敌后任伪军头目，活动于山东、安徽北部一带，配合日军作战。；原国民党军将领，投敌后所部曾调至安徽境内，在宣城附近参与对抗日武装的作战。；原国民党军将领，投敌后任伪军头目，其部队曾活动于安徽北部及周边，间接影响宣城地区伪军体系。；率部投日，所部在皖北、宿州周边地区配合日军扫荡，后于1945年反正。；原国民党将领，投敌后任伪军头目，活动于安徽、山东交界地区，配合日军扫荡，后于1945年反正。；原国民党军将领，后投敌，所部在安徽、山东交界地区活动，配合日军扫荡抗日根据地，后于1945年反正。；率部投汪伪后活动于安徽、江苏北部一带，配合日军扫荡，后于抗战末期再度倒戈。；其伪军部队活动于安徽沿江地区，包括池州、贵池一带，配合日军扫荡。；原国民党将领，1943年投敌，所部伪军活动于安徽、江苏北部，曾配合日军扫荡滁州周边抗日根据地。；原国民党将领，投日后所部伪军活动于鲁南、皖北、皖东地区，曾对滁州周边抗日力量进行清剿。；原国民党军将领，投敌后任伪军要职，其伪军活动于山东、安徽北部，滁州、凤阳一带曾受其伪军配合日军行动的影响。；率部投敌后驻防安徽、江苏北部，配合日军扫荡，后于1945年反正。；原国民党军将领，1943年率部投敌，所部活动于安徽、江苏北部，包括滁州、明光一带，配合日军进攻抗日根据地，后于1945年反正。；原国民党将领，投敌后任伪军头目，其部队在安徽、江苏交界地区活动，滁州、来安一带曾受其伪军影响，参与对抗日武装的进攻。；原国民党将领，投敌后所部活动于鲁南、皖北、苏北地区，配合日军对抗日根据地进行扫荡，滁州周边亦有伪军活动。；率部投伪，活动于山东、安徽北部，与阜阳地区有军事接触，配合日军作战。；原国民党军将领，抗战期间投靠日伪，任伪和平建国军第三方面军总司令，活动范围包括皖北，配合日军进攻抗日根据地，抗战后所部被国民党收编。；原国民党军将领，投汪伪后率部在安徽、江苏等地活动，其伪军系统对马鞍山、当涂地区有影响。；原国民党军将领，1943年投敌，所部伪军活动于安徽、江苏北部，配合日军扫荡，后于1945年反正。；投敌后率部驻鲁南，配合日军扫荡沂蒙山区，在临沂、蒙阴一带制造无人区。；率部投日，在山东境内配合日军进攻抗日根据地，其伪军活动范围覆盖鲁中、鲁南，对临沂地区亦有影响。；率部投日后在山东地区配合日军扫荡，所部伪军活动于鲁中、鲁北等地，对山东抗日根据地造成危害。；投日后所部在山东鲁南地区活动，配合日军扫荡，枣庄周边曾受其伪军影响。；原国民党军将领，1943年投敌，所部在鲁中、泰安地区配合日军扫荡。；原国民党军将领，1943年投敌，任伪和平建国军第三方面军总司令，活动于山东泰安、新泰、莱芜一带，配合日军扫荡。；原国民党将领，1943年投敌，所部在山东泰安、莱芜、新泰一带配合日军扫荡，后于1945年反正。；原国民党军将领，1943年投敌，驻山东济南及周边，配合日军扫荡抗日根据地。；率部投日，驻山东境内，配合日军扫荡鲁中、鲁南抗日根据地，与济南日伪政权协同行动。；原国民党军将领，1943年率部投日，在山东配合日军扫荡，活动范围包括济南及鲁中地区。；率部投日，驻山东，配合日军扫荡，其势力范围覆盖济南周边。；原国民党将领，1943年投敌，所部在山东地区配合日军扫荡，后于1945年反正。；原国民党将领，1943年投敌，在山东淄博、临朐、沂水一带配合日军扫荡抗日根据地。；原国民党新编第四师师长，1943年投敌，所部在鲁中、淄博一带配合日军扫荡，制造无人区，后于1945年反正。；率部投敌后驻防鲁西，配合日军扫荡聊城、临清一带抗日根据地。；原国民党军将领，1943年率部投日，所部活动于山东境内，曾配合日军在鲁西、聊城周边地区扫荡抗日根据地，后于1945年反正。；原国民党将领，1943年投敌，率部在山东境内配合日军扫荡，活动范围涉及鲁西、鲁中，与聊城、临清地区日伪有协同。；1943年投敌，所部在山东境内活动，曾涉及菏泽、单县地区，配合日军扫荡，制造无人区。；率部投日，活动于山东包括青岛周边，配合日军扫荡崂山地区抗日力量。；活动于山东，后反正，与广西玉林无关。；原国民党将领，投敌后任伪军头目，活动于江苏、山东、安徽交界地区，配合日军作战。；投敌后率伪军在江苏、山东交界地区活动，参与日军清乡，残害抗日群众。；率部降日后在山东、河南交界地区活动，配合日军扫荡抗日根据地。；山东掖县人，原国民党军将领，1943年投敌，任伪军头目，其部队在山东、河南交界地区活动，配合日军扫荡抗日根据地。；原国民党军将领，1943年投敌，所部伪军活动于山东、河南东部地区，配合日军作战，后于1945年反正。；原国民党军将领，1943年在山东投敌，所部伪军活动于鲁豫皖边区，其势力一度延伸至河南东部，对河南沦陷区包括平顶山周边产生间接影响。；率部降日后，其伪军曾在河南境内配合日军行动，部分部队活动于洛阳周边地区。；1943年在山东投敌，所部伪军活动于鲁豫皖边区，曾配合日军在河南东部、南部作战，其势力范围接近漯河地区。；原国民党军将领，1943年投敌，所部伪军在河南、山东交界地区活动，曾配合日军在豫中作战，其势力范围一度接近漯河、舞阳。；原国民党军将领，1943年投敌，所部伪军活动于山东、河南东部一带，配合日军作战。；原国民党军将领，1943年投敌，任伪和平建国军第三方面军总司令，其伪军活动于山东、河南交界地区，曾配合日军在河南沦陷区行动。；山东掖县人，1943年投敌，在山东、安徽一带活动；与湖南衡阳无直接关联。；原国民党将领，投靠日本，率部伪化，在山东地区配合日军扫荡，其活动范围与陕西邻近。；在山东、华北投敌任伪军头目，配合日军进攻抗日根据地，对华北包括陕西抗日形势有影响。；投靠日本，率部投降，在华北及陕西周边地区配合日军进行扫荡。；原国民党将领，1943年投敌，在山东、河南一带配合日军作战。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4a012729a9b3419385032b935879d0b7','a06c0041e5294f2987f746729e510de9',1940,'伪淮海省省长、伪军总司令','原国民党将领，投敌后任伪淮海省省长，辖区包括皖北部分地区，配合日军在亳州周边进行“清乡”。；抗战期间投靠日伪，任伪淮海省省长兼伪军总司令，活动范围包括安徽北部亳州、涡阳一带，配合日军清乡、征粮。；江苏徐州人，抗战期间投敌，任伪淮海省省长兼伪军总司令，其辖区与安徽北部接壤，对六安地区伪政权有辐射影响。；投敌后任伪职，其伪军活动范围包括安徽北部，对宣城地区有间接影响。；原国民党军将领，投敌后任伪淮海省省长，活动于苏皖北部，与安徽沦陷区有联系。；抗战后期投敌，任伪淮海省省长，辖区包括皖北部分地区，配合日军维持占领区，后于1946年反正又叛变。；抗战后期投敌，任伪淮海省省长，辖区包括皖北宿州部分地区，配合日军统治和扫荡。；原国民党军官，投敌后任伪淮海省省长，辖区包括安徽北部，配合日军进攻抗日根据地，后反复无常。；原国民党军将领，投敌后任伪淮海省省长，所部伪军在苏皖北部活动，与阜阳、太和地区邻近，配合日军进攻抗日根据地。；抗战后期投敌，任伪淮海省省长，活动范围包括皖北阜阳周边，配合日军扫荡。；在苏皖北部活动，包括阜阳邻近地区，率伪军配合日军扫荡，后反正又叛变。；原国民党军将领，投敌后任伪淮海省长，所部伪军活动于苏北、皖北，曾进犯阜阳以东地区，配合日军掠夺物资。；抗战后期投敌，任伪淮海省省长兼伪军总司令，在苏皖北部包括阜阳周边地区配合日军行动。；原为国民党军将领，后投靠汪伪政权，任伪淮海省省长兼伪军总司令，在苏北宿迁、泗阳一带配合日军清乡、扫荡，镇压抗日力量。；伪淮海省（辖苏北、皖北、豫东部分地区）省长，其伪政权与河南东部接壤，配合日军统治。；在苏北、豫东一带组织伪军，配合日军进攻抗日根据地，其活动范围接近河南东部。；投敌后任伪职，其伪军势力一度扩展至河南东部及豫南，配合日军对驻马店周边进行扫荡。；原国民党将领投敌，任伪淮海省省长，其部队在华中地区配合日军作战。；投靠日本，在苏北、鲁南、豫东地区组织伪军，其伪政权与陕西邻近，参与日军对西北的封锁。；投靠日本，在华东伪政权中任职，其伪军活动虽主要在华东，但作为伪军体系一部分，与陕西无直接关联，但属华北伪政权网络。；在苏北、鲁南、豫东地区组织伪军，配合日军扫荡抗日根据地。；投靠日本，任伪淮海省长，配合日军在华北及陕西周边地区进行殖民统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9d14122ea63741cebfd38a84a5ad6fa0','fefd7f9ddbac40469c751144d6cbd784',1940,'伪安徽省教育厅厅长','在伪安徽省教育厅任内推行亲日奴化教育，篡改教材，强迫学生学习日语，为日伪培养顺民。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cf101edea9bf4ac38e70498e2514545d','a2e4190c87b449e685d78c118a6801b5',1943,'伪财政部部长、伪安徽省省长（兼任）','汪伪政权核心人物，曾兼任伪安徽省省长，在安徽推行经济统制，为日军搜刮粮食与物资。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2d6a38587f5f4f069f66df725dd83703','41d2b197fedd4eefa3bd64d7cebe1523',1942,'伪河南省省长（辖区含皖北部分）','原东北军将领，投敌后任伪河南省省长，其辖区与皖北亳州接壤，配合日军对亳州周边进行扫荡。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('055d62b860794399bc158a26a1be3533','848992e841c9488c8cdcf56cad9f079c',1938,'伪和平救国军第一军军长','河南柘城人，投敌后组织伪军，活动于豫东、皖北亳州一带，配合日军进攻抗日武装，残害民众。；活动于皖北、皖中一带，其伪军曾进入合肥周边地区配合日军扫荡。；河南人，投敌后组织伪军，活动于豫皖苏交界，对安徽北部沦陷区有影响。；在豫东、皖北包括宿州周边招兵买马，配合日军进攻抗日根据地。；河南人，投敌后组织伪军，活动于豫皖苏边界，其伪军势力范围接近滁州地区，参与日军扫荡与伪化统治。；在皖北、豫东一带组织伪军，配合日军扫荡，残害抗日军民。；河南柘城人，活动于皖北阜阳周边，投敌后组织伪军，配合日军进攻抗日根据地。；在豫东、豫南及豫西部分地区的伪军中任职，配合日军作战，扩大伪化区。；在河南东部及豫西一带活动，率伪军配合日军扫荡，残害抗日军民。；在豫东、豫南一带组织伪军，配合日军扫荡，其势力范围一度延伸至豫西边缘。；长期在豫东、豫西活动，配合日军作战，其势力曾延伸至陕州周边，残害抗日军民。；在河南东部及南部投敌，率伪军配合日军扫荡，其活动范围涉及豫南地区。；在河南东部及豫西部分地区的伪军头目，其势力与河南日伪政权联系密切，间接影响洛阳、新安一带伪化秩序。；在河南东部及豫西部分地区组织伪军，配合日军进攻抗日武装，其活动曾延伸至洛阳附近地区。；在河南商丘一带组织伪军，后势力扩展至豫西，配合日军扫荡。；在河南东部及豫西地区组织伪军，配合日军扫荡，其势力一度延伸至洛阳周边。；在豫东、豫北一带组织伪军，后任伪第四方面军总司令，势力一度覆盖河南多地。；在豫东、豫南包括驻马店一带发展伪军，配合日军清乡、征粮，残害抗日军民。；在河南、安徽一带组织伪军，配合日军进攻，其活动范围接近陕西。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('352c0cead9af43ab9b6ad9b0527221b4','63006a4879fb4f49ad97a1e88c8c5d69',1942,'伪和平建国军第二方面军总司令','原国民党将领，投敌后率部在皖北、苏北活动，配合日军扫荡，其部队曾驻扎亳州周边地区。；原西北军将领，投敌后率伪军活动于苏皖地区，配合日军扫荡，其部队曾进入安庆周边地区。；原国民党军将领，1942年投敌，所部伪军活动于苏北、皖北。；原国民党军将领，投敌后所部在安徽等地配合日军，宣城一带受其伪军威胁。；原西北军将领，投敌后任伪军总司令，所部活动于苏北、皖北，配合日军对滁州周边地区进行清乡。；原国民党将领，1942年投敌，所部伪军活动于苏北、皖东一带，包括滁州、全椒周边地区，配合日军扫荡抗日根据地。；率部投敌，驻防皖北、苏北，配合日军清乡扫荡。；原国民党军将领，投敌后任伪军头目，所部活动于苏皖北部，包括滁州、明光地区，协助日军维持占领区秩序。；原国民党将领，投敌后任伪军头目，其部队在苏皖北部活动，滁州、来安地区曾受其伪军威胁，参与日军清乡行动。；原国民党军将领，投汪伪后率部在苏皖地区活动，其伪军曾控制马鞍山、当涂沿江部分区域，配合日军作战。；原国民党军将领，1942年投敌，所部伪军活动于安徽北部及江苏部分地区，配合日军维持占领区。；原国民党将领，后率部投敌，所部伪军在山东、河北交界一带活动，配合日军进攻抗日根据地，德州、平原周边曾受其伪军影响。；率部投日，所部在山东包括鲁南枣庄一带配合日军作战，进攻抗日根据地。；投敌后所部活动于鲁西地区，协助日军进攻抗日武装，残害民众。；原国民党军将领，1942年投日，任伪第二方面军总司令，所部盘踞山东、河南交界地区，在聊城、濮县、范县一带配合日军进攻抗日根据地。；原国民党将领，1942年率部投敌，所部活动于山东菏泽、单县及豫东地区，配合日军进攻抗日根据地，残害百姓。；率部投靠日军，所部在山西南部及吕梁部分地区活动，配合日军进攻抗日根据地，是山西境内影响较大的伪军头目。；活动于苏北、河南，与广西玉林无关。；原国民党将领，投敌后任伪军头目，活动于江苏、安徽一带。；原国民党将领，投敌后率伪军在苏北、苏中地区活动，配合日军扫荡，镇压抗日武装。；率部投敌，所部伪军活动于河南北部及豫西部分地区，配合日军进攻抗日根据地、镇压民众。；率部投敌后驻防河南，配合日军进攻抗日根据地，其势力范围覆盖豫南部分地区。；率部投日，所部在河南、豫北一带配合日军作战，进攻抗日根据地。；率部投敌，驻防开封、尉氏一带，配合日军进攻抗日根据地。；原国民党将领，1942年率部投汪伪，所部活动于河南、山东交界地区，包括濮阳周边，配合日军扫荡冀鲁豫边区，进攻抗日根据地。；率部投敌，所部伪军曾驻防许昌、漯河一带，配合日军进攻抗日根据地。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3a46384cf0c348b3851e78bdd3406b6c','83a92f4d9e894ddc95c8e9a351babc4f',1938,'伪安徽省省长、伪安徽省政府主席','安徽阜阳人，抗战期间投靠日军，历任伪安徽省维新政府省长、伪安徽省政府主席，在安徽各地建立伪政权，配合日军清乡、掠夺，镇压抗日活动。；安徽阜阳人，抗战期间投敌，曾任伪安徽省省长、伪安徽省政府主席，协助日军维持安徽沦陷区统治，推行保甲、征粮、清乡等政策。；安徽阜阳人，抗战期间投敌，曾任伪安徽省省长、伪安徽省政府主席，协助日军维持皖北及安徽沦陷区统治，参与征粮、拉夫和清乡活动。；安徽阜阳人，抗战期间投靠日军，历任伪安徽省维新政府省长、伪安徽省政府主席等职，协助日军维持占领区统治，推行保甲、征粮、抓丁。；安徽阜阳人，北洋时期政客，抗战期间投敌，历任伪安徽省维新政府省长、汪伪安徽省政府主席等职，主持安徽沦陷区伪政权，推行奴化教育与经济掠夺。；安徽阜阳人，北洋时期政客，抗战期间投靠日军，历任伪安徽省维新政府省长、汪伪安徽省政府主席等职，主持安徽沦陷区伪政权，推行奴化教育与经济掠夺，其伪政权统治范围覆盖六安部分地区。；安徽阜阳人，北洋时期政客，抗战期间投敌，历任伪安徽省维新政府省长、汪伪安徽省政府主席等职，主持安徽沦陷区伪政权，推行奴化教育与经济掠夺，其伪政权统治范围覆盖六安、舒城周边沦陷区。；安徽阜阳人，北洋时期政客，抗战期间投靠日军，历任伪安徽省维新政府省长、伪安徽省政府主席等职，主持安徽沦陷区伪政权，推行奴化教育与经济掠夺，其伪政权势力覆盖六安周边沦陷区。；安徽阜阳人，北洋时期政客，抗战期间投靠日军，历任伪安徽省维新政府省长、汪伪安徽省政府主席等职，主持安徽沦陷区伪政权，推行奴化教育与经济掠夺，其伪政权统治范围覆盖六安周边沦陷区。；安徽阜阳人，北洋时期政客，抗战期间投靠日军，历任伪安徽省维新政府省长、汪伪安徽省政府主席等职，主持安徽沦陷区伪政权，推行奴化教育与经济掠夺，其伪政权势力覆盖六安周边沦陷区。；安徽阜阳人，北洋时期政客，抗战期间投靠日军，历任伪安徽省维新政府省长、汪伪安徽省政府主席等职，主持安徽沦陷区伪政权，推行奴化教育、配合日军清乡与掠夺物资，其伪政权统治范围覆盖六安周边沦陷区。；安徽阜阳人，北洋时期政客，抗战期间投敌，历任伪安徽省维新政府省长、汪伪安徽省政府主席等职，主持安徽沦陷区伪政权，推行奴化教育与经济掠夺，其伪政权统治范围覆盖六安部分沦陷区及周边地区。；安徽合肥人，抗战期间投靠日军，历任伪安徽省维新政府省长、伪安徽省政府主席等职，配合日军统治安徽沦陷区。；安徽合肥人，抗战期间投敌，任伪安徽省省长、伪安徽省政府主席，协助日军维持占领区统治，镇压抗日活动，搜刮民财。；安徽阜阳人，北洋时期政客，抗战期间投靠日军，历任伪安徽省维新政府省长、伪安徽省政府主席等职，主持安徽沦陷区伪政权，推行奴化教育与经济掠夺，其伪政权统治范围覆盖安庆及周边地区。；安徽阜阳人，北洋时期政客，抗战期间投靠日伪，历任伪安徽省维新政府省长、汪伪安徽省政府主席等职，协助日军推行殖民统治，在安庆及安徽多地组织伪政权。；安徽阜阳人，抗战期间投敌，任伪安徽省省长、伪省政府主席，协助日军在安徽建立伪政权，推行奴化教育，征发物资劳工。；安徽阜阳人，北洋时期政客，抗战期间投靠日军，历任伪安徽省维新政府省长、汪伪安徽省政府主席等职，协助日军推行伪化统治，在安庆及皖南、皖中地区组织伪政权、征粮拉夫。；安徽阜阳人，北洋时期政客，抗战期间投敌，历任伪安徽省维新政府省长、汪伪安徽省政府主席等职，主持安徽沦陷区伪政权，推行奴化教育与经济掠夺，其伪政权势力覆盖安庆地区。；安徽阜阳人，北洋时期即任安徽省长。抗战期间投靠日军，1938年后历任伪安徽省维新政府省长、汪伪安徽省政府主席等职，主持安徽沦陷区伪政权，推行奴化教育、配合日军清乡与掠夺，是安徽境内级别最高的汉奸之一。；安徽阜阳人，北洋时期政客，抗战期间投靠日军，历任伪安徽省维新政府省长、伪安徽省政府主席等职，协助日军推行殖民统治、征粮征丁，是安徽沦陷区最高级别的汉奸之一。；安徽阜阳人，北洋时期政客，抗战期间投靠日军，历任伪安徽省维新政府省长、汪伪安徽省政府主席等职，主持安徽沦陷区伪政权，推行奴化教育与经济掠夺，其伪政权管辖范围覆盖安庆、桐城等地。；安徽阜阳人，抗战期间投敌，历任伪安徽省省长、伪省政府主席，在安庆等地建立伪政权，配合日军维持占领区秩序。；安徽沦陷区主要汉奸，曾任伪安徽省省长、伪省政府主席，配合日军在安徽的统治，推行保甲制度，搜刮民财。；北