INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('53b56b3560634ec697cde9e02ce4640b','2ed27fcffce64d3788b4508d0e4437d3',1940,'伪合肥县司法承审员','在伪法庭上以“通匪”罪名判处抗日群众，协助日伪镇压反抗，制造多起冤案。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9e999d7bf4cd470dbeb5520e32424292','5b3187957ade4aa1a703516923e040a3',1938,'伪合肥县维持会会长、伪合肥县县长','合肥沦陷后组织维持会，任伪合肥县县长，为日军征粮派款、维持治安，镇压抗日群众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('405af914b378403cb24ca9b117a07f71','2c1033990a9e41b5844d61303bc382ab',1938,'伪巢县维持会会长、伪巢县县长','巢县沦陷后投敌，组织伪维持会并任伪巢县县长，协助日军统治巢湖地区，搜刮物资。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f54118e23cbd427680c4be67a9087ec2','2bd76bd4f7874f8f8becd896967ac4f3',1939,'伪巢县警察局局长','在巢县任伪警察局长，配合日军清乡，抓捕抗日人员，维持伪政权治安。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b074fcdad683411983d2625562727b4d','e2c66871d6614f4789846b103dc455d9',1938,'伪合肥县商会会长','合肥沦陷后依附日军，任伪商会会长，为日军筹款筹粮，协助经济统制。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('069202b85dd24faeb8b4f648d61d2e67','d8c3493186d94718ad05072d725f4939',1940,'伪安徽省教育厅厅长','在汪伪安徽省教育厅任职，推行亲日奴化教育，篡改教材，毒害青年。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('921dce526f8041d8a46ff79599057c46','70a05a799ab649dcb1e066740c197d1f',1939,'伪合肥县保安团团长','组织伪保安团，配合日军扫荡合肥周边抗日根据地，残害百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('13cfc53d96e448fcb45422a60d3f37fc','5a6b9610b0b54a1f9f33243a1ef1347f',1940,'伪巢县保安大队大队长','任伪巢县保安大队长，协助日军维持巢湖地区治安，参与清乡与搜捕抗日人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ed75cd60a51d408db4f77ca72e6436e6','83a92f4d9e894ddc95c8e9a351babc4f',1938,'伪安徽省省长','投靠日军，任伪安徽省省长，在安徽推行日伪统治，协助日军清乡、征粮，镇压抗日力量。；继任伪安徽省长，积极为日军提供物资和情报，组织伪军配合扫荡。；投靠日伪，任伪安徽省省长，推行日伪统治政策，协助日军在安徽各地建立伪政权，镇压抗日活动。；安徽凤阳人，投日后任伪安徽省省长，管辖安庆等沦陷区，推行保甲制度，镇压抗日活动，为日军征粮派夫。；安徽沦陷区伪政权头目之一，历任伪安徽省维持会会长、伪省长，为日军搜刮物资、推行治安强化运动。；投靠日军，任伪安徽省省长，在蚌埠设立伪政权，推行奴化教育，协助日军征粮征税，镇压抗日活动。；安徽阜阳人，抗战期间投敌，曾任伪安徽省省长，协助日军在安徽推行伪政，组织伪军，镇压抗日活动。；安徽沦陷区伪政权头目之一，历任伪安徽省维持会会长、伪省长，推行日军殖民统治，其辖区包括当涂、马鞍山一带。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6bda284b54124dde8c955c1aae1187d1','d1abe59a5d664bf18b442130fc0478a1',1943,'伪安徽省省长（后任）','汪伪政权要员，曾任伪安徽省省长，在安徽推行奴化教育，配合日军经济掠夺。；汪伪政权要员，曾任伪安徽省长，在安徽推行奴化教育，配合日军经济掠夺。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b9c52d093b614a9699d8e1a6f22c9ee0','3f934b1c263b4cd78c73d9700621e7bd',1940,'伪安徽省省长（代理）','汪伪政权官员，代理安徽省长期间，组织伪保安队，协助日军“扫荡”新四军。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('87a8a04f7a314d5384b50a5567584422','70a05a799ab649dcb1e066740c197d1f',1938,'伪合肥县知事','日军占领合肥后任伪县知事，为日军征粮派夫，建立伪保甲制度，迫害抗日家属。；任伪合肥县长，为日军征收粮食，抓捕抗日嫌疑人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c8ea62c9292f4fef81cf8e0ea68ba285','8f1dd12e548b4c4f866dd743c3377896',1937,'伪华北政务委员会委员长（曾辖皖北部分地区）','安徽合肥人，早年投日，任伪华北政权要职，虽主要活动在华北，但利用其合肥籍身份影响地方，协助日军在皖北招降纳叛。','伪政权最高层/元首级','hanjian');
