INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6f244b5aebc0499f9a7df6b7deba4b6b','8f1dd12e548b4c4f866dd743c3377896',1937,'伪华北政务委员会委员长（合肥籍）','合肥人，早年投日，任伪华北政务委员会委员长，虽主要活动于北平，但利用合肥籍身份影响皖中汉奸势力。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('af354d63a9c74b6184d4fcbb297a4d24','a976a94be0bf4b76b621948c0802222f',1938,'伪合肥县维持会会长','合肥本地士绅，日军占领合肥后出任维持会会长，为日军筹粮、拉夫，协助建立伪政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c1afa57ce1ae4d33bfb051b0b068cd3d','6b186890888c4ef59afd6a82a310d3ad',1940,'伪安徽省保安司令部顾问（合肥籍）','合肥籍，虽名义为桂系将领，但暗中与日军勾结，在蜀山地区提供情报，协助日军扫荡新四军游击队。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3944e7aa8f4a47659860f7dbde0c755b','a2e4190c87b449e685d78c118a6801b5',1940,'伪国民政府财政部长（合肥籍）','合肥人，汪伪政权核心人物，虽常驻南京，但通过其亲信在合肥、蜀山地区发展伪组织，搜刮民财。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cf3bd6c68c1546b4885424d5a2d95984','95f671d50a964fbcbda5c5343b563024',1939,'伪合肥县警察局长','原国民党警察，投日后任伪警察局长，在蜀山一带抓捕抗日分子，残害百姓，为日军特务机关服务。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f40129cd11f24324be055f6daecec04c','f2c99eb1b0d343818114b39936365e43',1938,'伪合肥县商会会长','合肥商人，投靠日军后控制商会，为日军统制物资，强迫商户‘献金’，资助伪军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a8e5011b79fc4d23978ac4d163dd3694','bf398d44782c4c1594ef5ef1eecbf521',1940,'伪合肥县教育督办','在蜀山地区推行奴化教育，删改教材，强迫学生参加‘中日亲善’活动，告发抗日师生。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a13666c9fbc3441a8beebf45d33612a3','8f1dd12e548b4c4f866dd743c3377896',1937,'伪华北政务委员会委员长（原合肥籍）','虽主要在华北活动，但原籍合肥，积极投靠日本，任伪华北政务委员会委员长，推行“治安强化运动”，协助日军清乡扫荡。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ca8315c6ef6a42e09b2eb641cdc11631','bf9d7a2e9ecb4c04b87c7e2ba46557a2',1940,'伪合肥县警察局长','任伪警察局长，协助日军搜捕抗日地下党员，破坏中共地下交通站，镇压群众反抗。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a9924f7a6a04405b975692b2af53a0a7','2ef1d226ccf14ca2b8537de3f219e714',1938,'伪长丰地区（时属寿县、合肥交界）维持会头目','在长丰地区（今属合肥）组织伪维持会，为日军带路，强征粮食，杀害抗日游击队家属。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1400537239bf417b81be0d9b5af1b9e1','8089eae653ff4a0a9a08eacfa48fce76',1939,'伪合肥县商会会长','充当汉奸商人，为日军筹集军饷，垄断粮食贸易，向日军提供经济情报，协助掠夺当地资源。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e3369933a0a8461daa61c04c9b936546','c12e72a145724c39b755a2a16dce9a71',1938,'伪国民政府主席','虽为广东人，但作为伪国民政府首脑，其政权控制范围包括安庆地区，推行“和平反共”政策，协助日军统治安徽沦陷区。；虽为广东人，但作为伪国民政府首脑，其政权控制范围包括安徽，安庆、大观地区在其统治下，推行汉奸政策，配合日军侵略。；虽为广东人，但作为伪国民政府首脑，其政权控制范围包括安徽，安庆迎江地区在其统治下，推行汉奸政策，协助日军进行殖民统治。；虽非芜湖本地人，但作为汪伪政权最高头目，其势力覆盖包括芜湖在内的沦陷区，推行“和平反共”卖国政策，协助日军统治安徽地区。；虽为广东人，但其伪政权统治范围包括安徽，其亲信在芜湖鸠江地区推行汉奸政策，组织伪军和特务活动。；汪伪政权最高头目，其伪政权体系覆盖广东汕头等沦陷区，推行全面附日政策。；建立汪伪政权，广东沦陷区包括深圳、光明一带的伪政权均名义上归其统辖。；建立汪伪政权，广东沦陷区包括广州湾伪政权名义上受其统辖，为日军侵华服务。；建立汪伪政权，其伪广东省政府管辖范围包括湛江地区，推行亲日卖国政策，为日军侵略服务。；虽为全国性汉奸，但与江苏地区伪政权关联密切，其伪府设在南京，对江苏包括南通、如东地区有管辖影响。；虽为广东人，但作为伪国民政府首脑，其政权控制江苏全省，包括南通、海安地区，推行清乡运动，配合日军镇压抗日力量。；建立南京伪国民政府，统辖包括河南在内的沦陷区伪政权，推行全面附逆政策。；伪政权首脑，其政策覆盖浙江宁波余姚，推动与日军全面合作。；中国头号汉奸，建立汪伪政权，其统治范围包括浙江宁波，其政策直接导致当地抗日力量受挫。；虽为广东人，但作为伪国民政府首脑，其政权统治范围包括浙江，其政策影响绍兴、上虞地区，是最大汉奸头目。；虽为广东人，但作为伪国民政府首脑，其政权控制浙江地区，包括绍兴、诸暨，推行“清乡”政策，协助日军镇压抗日力量。；在南京建立伪政权，其势力曾渗透至重庆、万州等地，发展伪组织成员。；建立汪伪政权，推行亲日政策，签订卖国条约，1944年病死。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4e3f7c79c5ba485da96cca509c5587cf','62a6d6c8e7ab4bbfbc92c5b14abbde74',1940,'伪国民政府代理主席、伪上海市长','汪伪政权核心人物，参与对安徽沦陷区的行政管辖与物资掠夺，间接影响安庆地区。；汪伪政权核心人物，其政策影响安徽全省，包括安庆、大观地区，协助日军维持殖民统治。；汪伪政权核心人物，参与对安徽等地的伪化统治，间接影响安庆迎江地区。；汪伪政权核心人物，曾参与对安徽沦陷区的政治控制，其伪政权在芜湖设立行政机构，协助日军征粮征税。；作为汪伪政权核心人物，其势力渗透安徽，在芜湖鸠江地区协助建立伪政权机构，镇压抗日力量。；汪伪政权核心人物，代理主席期间继续推行汉奸政策，战后被处决；广东南海人，但长期在浙江活动，汪伪政权第二号人物，曾任伪上海市长，代理主席，1946年被处决。；汪伪政权核心人物，其行政管辖范围涉及浙江，支持日军在绍兴、诸暨的军事行动和物资掠夺。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e9df759aebf64bc7bad22fee2705f94f','a2e4190c87b449e685d78c118a6801b5',1940,'伪行政院副院长、伪财政部长','汪伪政权经济决策者，通过伪政权机构对安庆等安徽地区进行经济控制和税收榨取。；汪伪政权主要决策者，其经济掠夺政策直接作用于安徽及安庆、大观地区，搜刮民财。；汪伪政权主要头目，负责伪政权财政与特务工作，其势力渗透安徽各地，包括安庆。；汪伪政权主要头目，通过其控制的伪军和特务系统在安徽芜湖鸠江地区征收苛税，迫害抗日民众。；作为汪伪政权核心人物，其政策影响浙江、宁波地区，曾协调日军对镇海港的控制。；湖南沅陵人，汪伪政权核心人物，虽非浙江籍，但多次到杭州、临安视察，指导伪政权强化统治，支持清乡行动。；汪伪政权经济决策者，通过伪政权在浙江地区征收苛捐杂税，为日军提供军费，间接压迫绍兴、诸暨民众。；汪伪政权核心人物，其伪化政策覆盖湖南，间接影响郴州、嘉禾地区伪政权运作。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('29276577965e4db1909f9b87f6913763','d1abe59a5d664bf18b442130fc0478a1',1943,'伪安徽省省长（继任）','汪伪骨干，接任伪安徽省长，继续在安庆地区实施伪化统治，配合日军“清乡”行动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('86c95e901b3c4530a57c874490ca66ee','3f934b1c263b4cd78c73d9700621e7bd',1940,'伪安徽省长（短暂任职）','曾任伪安徽省长，在安庆地区推行伪政权法令，协助日军维持治安。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ce1f707bfe3a40478eab5e264324cb2d','eb97867e737c44e4944e71b5792c1f23',1938,'伪北平市长（曾参与安徽事务）','汪伪系统人物，曾协助协调安徽沦陷区伪政权与日军关系，间接涉及安庆。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('04bda3fabf174839b3c06a694af913e8','07ff958e7f18410f864975f09234ac7e',1939,'伪特工总部主任（76号）','其特工网络延伸至安庆，指挥汉奸特务在安庆地区暗杀、绑架抗日人士，破坏地下组织。','特工总部主任','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ef1041d68fe74b8bb4a9dd55eb120692','9910c48b9b394ffa8c73439ed0a473b0',1939,'伪特工总部副主任','与李士群共同负责特工活动，在安庆地区建立情报站，迫害进步人士。','特工总部主任','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b792fa95ed26442e8ba946cf9af1541f','0d2d2045fc1d498dab9499e43abcb3de',1940,'伪安徽省保安司令','汪伪军事骨干，在安庆地区组织伪保安队，配合日军扫荡抗日根据地。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('59724a7037ad4aed987ececcc1ea3175','ed0d68ce0e0f4e40ba88774709d7fea6',1941,'伪安徽省警察厅长','在安庆推行伪警察统治，设立关卡，盘查抗日人员，参与“清乡”行动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('73945e57fe664f958d2c52c19095172e','506df7877e6b4b589f0df223e5da77c6',1940,'伪湖北省长（曾涉安庆军事）','虽主政湖北，但曾率伪军参与对安徽安庆地区的军事“扫荡”。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1832c14041c346c1abf840599653bbaa','bb34b45b44c34a018d410cde66579fb1',1941,'伪陆军部长（曾驻安庆）','汪伪将领，曾驻防安庆，指挥伪军协助日军镇压当地抗日武装。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('854fb50b825d40e1a47fc62617487367','41d2b197fedd4eefa3bd64d7cebe1523',1940,'伪军事委员会参谋总长','参与策划对安徽包括安庆地区的军事行动，协调伪军与日军合作。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2d7dd544c81c4e85aa6f34c0ba1e6181','ef676fac9bb24126bcc992f39c87c979',1938,'伪华北政务委员会治安总署督办','其势力曾延伸至安徽北部，对安庆地区伪军进行整编和指挥。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1194f44b231c451bbbcfb99969bbc032','da58b77853f14ce7b32f7f6b3305b75a',1937,'伪华北绥靖军总司令','虽主华北，但曾派伪军南下协助安徽伪政权，参与安庆周边治安维持。；曾到南京鼓楼区参加伪军会议，协助日军控制江苏。；在华北伪政权中负责治安与伪军，配合日军扫荡抗日根据地，其活动对陕西周边有威胁。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3622982cfa0340a29e75337121740ef5','848992e841c9488c8cdcf56cad9f079c',1940,'伪第四方面军总司令','其伪军部队曾调至安徽安庆地区，协助日军进攻新四军。；在苏皖地区为日军效力，围剿抗日力量；原国民党将领，投敌后所部活动于苏北、豫东，配合日军进攻抗日武装。；河南人，原国民党将领，抗战期间投靠日军，任伪第四方面军总司令，在华中地区进行伪化统治。；在河南投敌，组织伪军配合日军，河南与陕西相邻，其活动对陕西东南部有间接影响。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d956228bd12e4b3cb86998802ad574fe','5ec2ad124b2f429482b1a90a7f8d4a92',1943,'伪第五方面军总司令','投敌后其部队曾参与对安庆地区的“扫荡”和物资掠夺。；投敌后其部队在安徽境内活动，曾进犯安庆、大观一带，烧杀抢掠。；原国民党将领，投敌后在江苏北部活动；河北人，原国民党将领，抗战期间投靠日军，任伪第五方面军总司令，在华北地区进行伪化统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cff3d8088e694321977a6842cc292891','9f7b3ed9c76f4eea8211fd8ebc40a461',1943,'伪新编第五军军长','率伪军在安徽北部及安庆周边活动，配合日军清剿抗日力量。；投日后率部在安徽北部及安庆周边袭扰抗日力量，危害地方。；率部投敌后被编为伪军，曾驻防豫西一带，配合日军在洛阳周边地区进行扫荡和治安强化。；河南人，被俘后投敌，伪军活动于豫北、太行山区，与湖南无直接关联。；投降日军后，在河南、湖南等地组织伪军，配合日军作战，参与伪政权军事活动。；在河南投敌，率伪军配合日军进攻抗日根据地，其活动区域与陕西接壤，对陕西有间接威胁。','市县厅局级','hanjian');
