INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('91207a6b1a3045eb9d066ae192c2d827','f9672a14d5734a1ea4b85b459bbbd4ec',1940,'伪安庆当铺老板','低价收购抗日家属典当物品，向伪军报告典当者身份。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4e74f48f453e4eeab39e238fffc17b85','9910c48b9b394ffa8c73439ed0a473b0',1939,'伪社会部长、伪浙江省长','汪伪特工头目，其特务活动波及安徽，在安庆、大观地区镇压抗日力量。；汪伪特工头目，其特务网络在安徽活动，镇压抗日力量，涉及安庆地区。；汪伪特工头目，后任伪社会部长、伪浙江省长，其特工系统活动于包括安徽在内的沦陷区。；曾任伪特工头目，其势力在安徽芜湖鸠江地区进行特务活动，捕杀抗日人士。；湖南常德人，汪伪政权特务头目。曾任伪社会部长，其特务活动范围包括安徽沦陷区，间接涉及黄山、休宁地区。；湖南常德人，生于浙江，汪伪特工头目，后任伪浙江省长，在浙江进行特务统治和镇压抗日活动。；汪伪特工头目，其特务组织在重庆、万州有渗透活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7805bd02be414a96b0469945e7d10233','07ff958e7f18410f864975f09234ac7e',1939,'伪江苏省长、伪特工总部主任','汪伪特工头目，其势力曾渗透安徽，在安庆、大观地区进行暗杀和破坏活动。；汪伪特工头目，在芜湖及周边地区布置特务网络，捕杀抗日志士，协助日军维持治安。；汪伪76号特工头目，其特务网络延伸至安徽芜湖鸠江地区，残害抗日志士。；组建76号特工总部，在南京、上海大肆捕杀抗日志士，后被日军毒杀；汪伪76号特工头目，其特工网络延伸至浙江，在绍兴、诸暨暗杀抗日人士，制造恐怖。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3f4cfe3a5d8b43cf920c7b529e5887e4','0d2d2045fc1d498dab9499e43abcb3de',1943,'伪安徽省长','直接担任伪安徽省长，管辖安庆、大观地区，推行日伪政策，强征粮食和劳役。；直接统治安徽，在芜湖鸠江地区推行伪化政策，强征壮丁，压迫百姓。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aee88180691a484ebcf4739c4793cf9a','d1abe59a5d664bf18b442130fc0478a1',1940,'伪安徽省长（实际为林柏生？需核实）','注：此条为误置，实际伪安徽省长为罗君强，但为完整性列出，若为林柏生则无直接管辖。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c040b5fb08f2419c8b34769561da4c2f','3f934b1c263b4cd78c73d9700621e7bd',1940,'伪安徽省长（前任）','汪伪政权任命的首任伪安徽省长，在安庆、大观地区建立伪政权，推行保甲制度。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6b844aad795f49b893d50a3c2944124e','848992e841c9488c8cdcf56cad9f079c',1938,'伪和平救国军总司令','其伪军部队在安徽北部及安庆周边活动，协助日军扫荡，祸害大观地区百姓。；河南人，投敌后组建伪军，其部队活动于豫北、晋南一带，与临汾地区日军配合进行扫荡和治安强化运动。；活动于河南、安徽等地，与广西玉林无关。；在河南、湖北、湖南交界地区组织伪军，配合日军进攻湖南，参与伪政权军事活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5cf1ac87128e4e0da8f2cdbda5f36700','a06c0041e5294f2987f746729e510de9',1943,'伪淮海省保安司令','其势力曾延伸至安徽东部，影响安庆、大观地区的伪政权运作。；原西北军将领，投日后任伪淮海省保安司令，在淮北、相山一带率伪军进攻新四军，制造多起惨案。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('04a028e16baf49209ae229dbe888a62d','41d2b197fedd4eefa3bd64d7cebe1523',1940,'伪军事参议院院长','参与伪军指挥，其下属部队在安徽安庆地区有驻防和作战记录。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5a0ddc6c236245d98a21ed4c0b2248c9','506df7877e6b4b589f0df223e5da77c6',1940,'伪湖北省长（曾兼安徽）','曾代理伪安徽省政，对安庆、大观地区有过管辖。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3ef51415e781422ca35a6361335763fb','4f8793c77ca74d3dbe773329337bfbb0',1938,'伪维新政府行政院长','其伪维新政府曾控制安徽部分地区，安庆、大观在1938-1940年间受其管辖。；伪维新政府统治江苏、安徽等地，在芜湖鸠江地区设立伪机构。；在南京成立伪中华民国维新政府，后并入汪伪政权，战后被处决；原北洋政客，1938年在南京成立伪中华民国维新政府，任行政院长，后并入汪伪政权。；福建人，但伪维新政府曾控制浙江部分地区，在宁波、奉化设立伪政权分支。；原为北洋政客，投日成立南京维新政府，其势力曾渗透浙江宁波，协助日军维持治安。；在浙江北部及宁波地区建立伪组织，协助日军控制镇海港口。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2c5d3e534f2249eb9f20743e53f7c901','f50cf011f8f842fc8d69caa402ffbf67',1938,'伪维新政府内政部长','负责伪政权在安徽的行政事务，包括安庆、大观的伪组织建设。；伪维新政府、汪伪政权内政部长，掌管沦陷区警察与保甲，其系统延伸至安徽各县。；参与对舟山等浙江沿海地区的伪化统治，协助日军清乡和物资掠夺。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('afa3ebfb40644372a0d20c1de6aa2f68','cebb4769b324411abb6e1f5a0f26ecf6',1938,'伪维新政府绥靖部长','其伪军部队在安徽沿江地区活动，安庆、大观为其控制区域。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0832d89b88d84f39afa3765984cc8c05','1196ccc5a79246d3bf82438e67dcac17',1940,'伪安徽省长（汪伪早期）','短暂担任伪安徽省长，在安庆、大观地区推行日伪法令。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7e238e5625494d428f30fc9c9539a641','4cc5391bc78947fa9bf1a4b59e0f5371',1943,'伪安徽省长（后期）','继罗君强后任伪安徽省长，继续控制安庆、大观地区。；汪伪政权末期任安徽省长，在蚌埠地区加强伪军和警察力量，搜刮物资支援日军，镇压抗日游击队。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('79ac935888d94354b96f97efe71fc6ec','5a14726dc0a944709762daf466d4cd08',1937,'伪第二集团军总司令','其伪军在安徽境内活动，参与对安庆、大观的扫荡。','省部级/大军区级要员','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c5fddf64e7a146b39355d463657c5cf0','b19edc2e16ec4c7d9462b01fbba0f27f',1943,'伪第四十师师长','投日后驻防湖北与安徽交界，曾骚扰安庆、大观。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b250a2bbff9547da9be8d84e0538e6d4','ef9b7088a50046f289d4824a046ff59a',1942,'伪暂编第六师师长','其部队在安徽西部活动，对安庆、大观有威胁。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fc15034d17bd4bf4825ca4158790dadd','807ca12d2dcb44989aababb17d52ca6d',1940,'伪安徽省保安司令','负责伪安徽省内治安，在安庆、大观地区镇压抗日民众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('41af954bac174101828bb77051736682','ab55a5d50c9e4144b4f6a1abf1b8de26',1938,'伪安庆维持会会长','日军占领安庆后，出任维持会长，为日军征粮派夫，欺压百姓。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('933bad15db3f4374b83eccb429a6a5dd','6d29eb6e14634c5e833d67a5aff346b5',1940,'伪大观区区长','在安庆大观区任伪区长，协助日军推行保甲制度，强征捐税。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4e9a0c00ec1c4de39437a57000b0cc77','7e5956a97a3a4a9fab213fa982cf37f3',1938,'伪安庆县知事','投靠日军，任安庆县知事，在安庆及大观地区搜刮民财，迫害抗日家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0d2c596960d74845ae9e97491d7d5bfd','62a86438aa7b4034a0ba21dd10ad2198',1941,'伪大观区警察局长','为日军效劳，在大观区抓捕抗日志士，实施酷刑。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1ae6d49883f84e01bc20273b92e62d7a','6fee2b329ee54681a24b19e7abf091b7',1938,'伪安庆商会会长','充当汉奸商人，为日军筹集物资，控制大观地区商业。','基层头目','hanjian');
