INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fe7f6930a4b14eb8b61ccfd60f6f4e8e','51eaa4b1ac7641869b3baeeed576ac4c',1940,'伪华北教育总署督办（非本地但影响）','虽非安庆本地，但其奴化教育政策推广至安徽，包括大观地区学校。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('61d1aac8d9404be7ac95ac06dd6ef3f7','b4da42a8d0a3425abf10522d58c50b00',1940,'伪军师长、伪安庆地区保安司令','原国民党军将领，后率部投敌，任伪军师长，活动于安庆、太湖一带，配合日军清乡扫荡，镇压抗日力量。；原国民党军将领，后率部投敌，任伪军师长，活动于安庆、怀宁、桐城一带，配合日军扫荡抗日根据地，残害抗日军民。；原国民党军将领，1940年前后率部投敌，在安庆、望江一带活动，配合日军扫荡抗日根据地，残害百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b2df6d0a946b46cda74ba78143b4c639','50380aeea4d040e7b7134a1f53cc71e3',1938,'伪安徽省财政厅长、伪安庆维持会会长','安庆沦陷后出面组织伪安庆维持会，后任伪安徽省财政厅长，为日军筹措物资、推行伪币，协助维持安庆地区殖民统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a8e940d669b04927a0e5c13f2ce10f06','2eb09470bb9e449fb8672c06368b3a21',1938,'伪太湖县维持会会长','太湖县沦陷期间出面组织伪维持会，为日军征粮派款、维持地方秩序，协助日军控制太湖地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('734b3a3a87b34df4af636b2f47e59619','38ab65dd8b634b4eb207479a5dbdb897',1938,'伪安庆县知事','安庆沦陷后任伪县知事，执行日军政令，推行保甲制度，协助征发劳工与物资。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7b4f861b64e44897b1b70186cc048117','d8c3493186d94718ad05072d725f4939',1940,'伪安徽省政府委员、伪安庆地区专员','汪伪政权在安徽的地方官员，曾任伪安庆地区专员，负责督导安庆、太湖等县伪政，配合日军清乡。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cc7531e6379b41e0a3ec1a6c6c46ed0a','007e06d315a948b5b3568088b824a1ed',1941,'伪安徽省警务处长','汪伪安徽省警务负责人，统辖伪警察力量，在安庆等地实施特务统治，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5df550be2f3e446d87734763b6c41c01','455643dcc8d948048c745963ebd68c1c',1942,'伪军师长、伪安庆要塞司令','伪军将领，驻防安庆一带，控制长江航运，配合日军封锁抗日根据地。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f1145730d12b4bfa8d7689cb60c03dd2','62a6d6c8e7ab4bbfbc92c5b14abbde74',1940,'伪国民政府主席、伪行政院长','汪伪政权核心头目，其伪政权统治范围包括安徽，对安庆地区伪政权有最高管辖权，推行全面亲日卖国政策。；汪伪政权核心人物，虽非安徽籍，但其伪政权统辖安徽全省，滁州地区在其伪政权体系之内，对安徽沦陷区伪化统治负有总体责任。；汪伪政权核心人物，其政策覆盖安徽沦陷区，推行奴化教育与经济统制。；作为汪伪政权最高领导人之一，对浙江包括宁波余姚的伪化统治负有总责。；广东人，但曾多次到浙江宁波视察，支持伪浙江省府对奉化地区的统治。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f53c2d4796db47689c0a021192cd90a9','a2e4190c87b449e685d78c118a6801b5',1938,'伪财政部长、伪警政部长','汪伪政权核心人物，其财政与警政体系覆盖安徽沦陷区，包括安庆，参与对沦陷区人民的经济掠夺与特务统治。；汪伪政权核心人物，掌控伪军警，在安徽等地配合日军进行清乡与物资统制。；汪伪政权核心成员，掌控伪财政与警政，其政策推行至安徽沦陷区包括滁州，参与经济掠夺与伪军警建设。；汪伪政权核心成员，参与控制华南沦陷区财政与警务，间接影响广东伪政。；汪伪政权核心成员，掌控伪财政与警政，为日军搜刮沦陷区资源，其政策影响包括湛江在内的广东沦陷区。；湖南沅陵人，中共一大代表后叛变，抗战期间投靠汪精卫，任伪财政部长、警政部长等要职，为汪伪政权核心人物之一。；汪伪政权核心人物，曾派人到重庆、万州等地联络地方势力，发展伪军。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('11f69e2cd1994cb19295f1e98ec6930f','3f934b1c263b4cd78c73d9700621e7bd',1938,'伪安徽省政府主席、伪南京特别市市长','原为北洋及国民政府官员，抗战期间投敌，曾任伪安徽省省长、伪安徽省政府主席，配合日军在安徽各地建立伪政权和维持会。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e721ce60140b45d48d6be4921afef21d','d1abe59a5d664bf18b442130fc0478a1',1940,'汪伪宣传部部长、伪安徽省省长','汪伪政权核心人物之一，后任伪安徽省省长，在安徽推行亲日宣传和殖民教育，镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7db228b3f35f47d1b19fc0b6ca77cfea','0d2d2045fc1d498dab9499e43abcb3de',1940,'汪伪安徽省省长、伪司法行政部部长','汪伪政权要员，曾任伪安徽省省长，在安徽推行日伪法令，协助日军征粮、征丁，镇压抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c0dcc10a41ea4c70b959387da1a51c25','b4da42a8d0a3425abf10522d58c50b00',1938,'伪安庆维持会会长、伪安庆县县长','安庆沦陷后出面组织伪安庆维持会，后任伪安庆县县长，协助日军维持治安、征发物资，镇压安庆地区抗日活动。；安庆沦陷后出面组织伪维持会，后任伪安庆县县长，协助日军征粮、征夫，镇压抗日活动，是安庆地区主要汉奸之一。','基层维持会/地方自治头目','hanjian');
