INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('431acb5e2e15497a87d141a8c3486af9','2402233d224a40b3b48c4777c32146ca',1940,'伪安徽省政府委员、伪安庆地区专员','在汪伪安徽省政府任职，负责安庆地区伪政权事务，推行日伪政策，镇压抗日活动。','无明确职位或一般帮凶','hanjian');
