INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0525023a12c1461c9e265b88c79c8cb2','d02cdfc1ffd94d258170bf85de83dca7',1940,'伪宿松县县长','宿松县伪政权头目，配合日军在安庆沿江地区征粮征丁，镇压抗日武装。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c2255e2dd4c44d1e88b3b1d19268eec9','38ab65dd8b634b4eb207479a5dbdb897',1940,'伪望江县县长','望江沦陷期间任伪县长，协助日军控制长江北岸，搜捕抗日人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ef384c38ba4f4ae9a8966599a277cca6','34b437978de7456ead4135526ebbb7d5',1938,'伪安庆维持会会长、伪怀宁县县长','安庆沦陷后出面组织伪维持会，后任伪怀宁县县长，为日军征发物资、劳工，维持安庆地区日伪统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ff1d1ca98bad4e4bb20eece6cdc88a28','28b89fcbdbc0426a8e2b2bb23b572ec4',1938,'伪安庆商会会长','安庆沦陷后投靠日军，任伪安庆商会会长，协助日军对安庆工商业进行控制和掠夺，为日伪筹集军需物资。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ee90339e883e44deb0062857212d79d2','15552eb8ec90448dad5f804c542f7324',1938,'伪安庆维持会副会长','安庆沦陷初期参与组织伪维持会，协助日军维持地方治安，征派民夫物资，为日伪政权服务。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bbf69473d93e4f98af149b74b0445832','2ef1d226ccf14ca2b8537de3f219e714',1938,'伪怀宁县维持会会长','安庆及怀宁沦陷后，出面组织伪维持会，为日军筹粮筹款，协助建立伪基层政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('04170e67dc4f4d2c9e7ad80218400ae5','38ab65dd8b634b4eb207479a5dbdb897',1938,'伪安庆警察局局长','任伪安庆警察局局长期间，配合日军搜捕抗日人员，镇压民众反抗，维持日伪治安。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0cf3b535ba234726b8e2f5fdaa5c5941','2402233d224a40b3b48c4777c32146ca',1938,'伪安徽省政府委员、伪安庆道尹','在汪伪安徽省政权中任职，曾任伪安庆道尹，负责安庆地区日伪行政事务，推行奴化教育。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dd12a1541e594ca8b1d81dbb2f3ee4bd','c78d172e245644f5997374b3b4cf617d',1940,'伪安徽省教育厅厅长','汪伪安徽省教育厅厅长，在安徽推行亲日奴化教育，篡改教材，毒害青少年。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5c0fb176b88a47d29594706cdba91a31','ef112d84ad03423b9c9112a9594814bd',1937,'伪安徽省财政厅厅长','任伪安徽省财政厅厅长，为日伪政权搜刮民财，征收苛捐杂税，支持日军经济掠夺。；安徽沦陷区伪政权财政头目，为日军搜刮物资、征收税款，支持伪政权运转。；安徽附逆官员，负责伪政权财政，为日军搜刮安徽物资、征收苛捐杂税，支持伪军与伪政权运转。；负责汪伪安徽省财政，为日军征粮征税，发行伪币，掠夺沦陷区经济资源。；在安徽推行伪币、统制物资，为日军掠夺安徽粮食、矿产等资源。；为日军筹措军费，在安徽沦陷区横征暴敛，发行伪币。；在安徽沦陷区推行伪币，为日军征粮征税，掠夺物资，支持日军“以战养战”。','市县厅局级','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('42c44d47e0754476b42669c16b2a75d7','e4b3a76b09bb4f10ac1dd4808bba9d30',1940,'伪安徽省警务处处长','汪伪安徽省警务处处长，统管伪警察力量，配合日军清乡扫荡，镇压抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('45fb57aa5ef04ad49d44ba4866696741','70a05a799ab649dcb1e066740c197d1f',1942,'伪安庆地区清乡专员','负责安庆地区日伪清乡事务，配合日军对抗日根据地进行扫荡，推行保甲连坐，镇压抗日力量。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('df03bca7d3304850bc07f3163c8f89bf','d8c3493186d94718ad05072d725f4939',1938,'伪军团长、伪安庆保安团团长','组织伪保安团，配合日军在安庆周边地区进行治安战，袭击抗日游击队，残害百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('10790a4ab5224981aba28ae1208b42c4','4deb0ed7d29b4fe9a5eec880f39ce401',1939,'伪军大队长、伪安庆自卫团团长','率部投敌，任伪安庆自卫团团长，在安庆及宜秀周边地区为日军效力，搜捕抗日人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4c0bb6dbf4484527ac3ebb9c79ecc540','e6b73e7c50914a1aaaeffb2fd39c3b57',1939,'伪怀宁县保安大队大队长','任伪怀宁县保安大队大队长，配合日军在怀宁、宜秀一带清乡，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c88c177df21a4abfa649f5a90864c01b','66705527c6ce4335ba68843a353793c7',1938,'伪桐城县维持会会长','桐城沦陷后组织伪维持会，为日军筹办粮秣，协助建立伪政权，活动范围邻近安庆宜秀地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('45a63faa6d444712a0ea165d20c5adb5','5cbe2be867a345f79dba66529f39bd3e',1940,'伪桐城县县长','任伪桐城县县长，推行日伪政令，征发劳工物资，配合日军对桐城、安庆周边抗日根据地的扫荡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('461527efcfde4e968d52283d20678d61','52a27d93f88547fa8c3eaf613c3d34e3',1940,'伪东流县县长、伪安庆地区专员','在皖南及安庆地区任伪职，协助日军维持占领区统治，镇压抗日力量。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('680d0382df5646fdbb0b7272e81a3651','82622165d609478d8cd82e32959bf08c',1940,'伪安徽省宣传处处长','负责汪伪安徽省宣传工作，在安庆等地散布亲日言论，进行奴化宣传，粉饰日军侵略。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a8145939512c44c3b0c47da18a990bf4','37ec755e8c4e4711b97d4d3708b135f9',1938,'伪安庆日报社社长','主办伪《安庆日报》，为日伪政权进行舆论宣传，鼓吹“大东亚共荣”，麻痹民众抗日意志。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8c6e0f2443cf489280bea03650621ff7','b4da42a8d0a3425abf10522d58c50b00',1938,'伪安庆维持会会长、伪怀宁县政府要职','安庆沦陷后出面组织维持会，协助日军维持安庆城区秩序、征发物资，并参与伪怀宁县政权活动，是安庆本地较有记载的附逆者。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1ec5b4ecbd714af7a58e09777d127a3b','28b89fcbdbc0426a8e2b2bb23b572ec4',1938,'伪安庆商会会长、伪政权合作者','安庆商界人物，日军占领安庆后与伪政权合作，协助筹款筹粮、维持商业秩序，为占领当局服务。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('301f6451f6cd45fe87f910bcc89bcf2e','4deb0ed7d29b4fe9a5eec880f39ce401',1938,'伪军头目、安庆地区伪保安队负责人','在安庆周边收编土匪、游杂武装组成伪保安队，配合日军扫荡抗日根据地，活动范围涉及怀宁、桐城、宿松一带。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ed0e337bc1a2406084ef2a4e0a75c033','d02cdfc1ffd94d258170bf85de83dca7',1938,'伪宿松县维持会会长','宿松沦陷后出面组织维持会，为日军征粮、派夫、维持地方伪秩序，是宿松本地有记载的附逆人物。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9b7e4072c8fd4e38ae6fba14b721c2fa','e749ae9343404a73bb53274df5d1fb1e',1938,'伪宿松县政府县长','汪伪政权委任的宿松县伪县长，在宿松地区推行伪政，协助日军清乡、编查保甲、征发物资。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('95b4bebaf69e4733a51b22e10325c88e','2402233d224a40b3b48c4777c32146ca',1938,'伪怀宁县政府县长','安庆沦陷后任伪怀宁县县长，管辖区域包括安庆城区及周边，配合日军推行保甲、征粮与奴化教育。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('70d965b5751148fba3bf5d881e4f19b5','2ef1d226ccf14ca2b8537de3f219e714',1938,'伪桐城县维持会会长、伪县长','桐城沦陷后组织维持会并任伪县长，活动于桐城、安庆一带，协助日军维持占领区秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3c4f9e2327a74d5c995f9dda378007bf','38ab65dd8b634b4eb207479a5dbdb897',1938,'伪太湖县维持会会长','太湖县沦陷后出面组织维持会，为日军筹粮派款，配合伪政权在安庆西部山区进行伪化活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1ed705c84757492391d59e17730674ef','6f69cb42643545b1af2306bb153ff0df',1938,'伪望江县维持会会长','望江沦陷后组织维持会，协助日军控制长江北岸交通线，征发民夫物资，活动范围邻近宿松。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6ce04d3dec4548298a3e3ec695d9424c','49f2e223283c4544b18a73346a605e97',1938,'伪安徽省教育厅官员、奴化教育推行者','在伪安徽省政权中负责教育事务，在安庆等地推行日语教育与亲日奴化宣传，改编教材，毒化青年。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d526fd745e0f40f3b33bda4e654c58ca','f62754ef8d4a41f58e3b8f1b4bd4ab3a',1940,'汪伪政权考试院院长、安徽籍附逆文人','安徽旌德人，抗战期间投靠汪伪，参与伪政权文化宣传，其附逆活动对安徽沦陷区知识界有影响。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1fb908654778445aa98cf8f97c311264','a2e4190c87b449e685d78c118a6801b5',1938,'汪伪政权财政部长、警政部长','汪伪核心人物，虽非安徽籍，但其伪政权体系覆盖安徽，安庆、宿松等地伪军警受其系统节制，参与清乡与镇压抗日。；汪伪政权核心，掌控伪军警系统，广西沦陷区伪警察、伪维持会受其体系影响。；汪伪政权核心人物，负责财政与特务活动，与重庆方面有秘密联系，战后以汉奸罪被判死刑后改无期。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f5a49f3a5ff84af1bf26069aad811cfd','07ff958e7f18410f864975f09234ac7e',1938,'汪伪特工总部主任、伪江苏省主席','汪伪特务头子，其特工网络延伸至安徽安庆等地，搜捕抗日人员，破坏地下组织，对宿松周边亦有影响。；虽主要活动于上海、江苏，但其特工网络延伸至江西赣州一带，与当地伪政权勾结，镇压抗日力量，迫害爱国人士。；浙江遂昌人，生于江西？实际与江西关联较弱；但汪伪特工势力曾渗透江西国统区进行情报与破坏活动。；湖南长沙人，汪伪特务头子，虽主要活动于上海、江苏，但作为湖南籍汉奸，其特务网络对湖南沦陷区有渗透。；湖南籍汪伪特务头目，虽主要在沪苏活动，但其特工网络延伸至湖南部分沦陷区，与湖南地区伪政权有联系。；浙江遂昌人，汪伪特务头目，其特工网络延伸至湖南部分沦陷区，进行侦缉、镇压抗日活动。；浙江遂昌人，早年加入中共后叛变，抗战期间投靠汪伪，组建汪伪特工总部（76号），任伪江苏省主席等职，其特工网络活动范围涉及华中沦陷区，对湖南籍抗日人员亦有侦捕。；出生于湖南，汪伪76号特工总部负责人，残酷镇压抗日志士，后与日军及汪伪内部矛盾激化被毒杀。；浙江遂昌人，汪伪特务头子，其特务网络延伸至湖南部分沦陷区，与湖南伪政权有联系。；浙江丽水人，活动于上海、南京、江苏，其伪特工体系未直接覆盖郴州宜章，但作为汪伪高层被湖南地方史料在泛述汉奸时提及。；浙江遂昌人，汪伪特务头目，镇压抗日力量，活动于上海、江苏，与湖南郴州、桂阳无直接关联。；浙江遂昌人，汪伪特务头子，镇压抗日力量，虽非湖南籍，但其伪特工网络延伸至湖南部分地区，与郴州、汝城无直接关联。；浙江遂昌人，汪伪特务头目，其特工网络延伸至华中包括湖南部分地区，参与镇压抗日力量，与湖南沦陷区伪政权有联系。；浙江丽水人，但在湖南长沙有过活动经历，后成为汪伪特工头目，其势力范围涉及华中包括湖南部分地区的伪情报与镇压活动。；浙江遂昌人，生于湖南长沙，汪伪76号特工总部头目，镇压抗日力量，后与日军矛盾激化被毒杀。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7a54bbdcf3ac4d448dbd73d16fe09f39','9910c48b9b394ffa8c73439ed0a473b0',1938,'汪伪特工总部主任、伪社会部长','汪伪特务系统负责人之一，其组织在安徽沦陷区活动，安庆等地设有特务据点，参与镇压抗日力量。；汪伪特务头子之一，与李士群共同主持汪伪特工总部，后任伪社会部长等职。；汪伪特工组织头目，镇压抗日力量，其特工网络延伸至华南包括广西地区。；汪伪特务头子，其特工网络渗透广西，搜捕抗日人士，策反地方势力。；湖南常德人，汪伪特务组织头目之一，参与镇压抗日力量，主要在南京、上海活动。；湖南常德人，汪伪特务头子之一，参与伪政权特务活动，战后以汉奸罪被处决。；湖南常德人，汪伪特务头目之一，参与组建伪特工总部，迫害抗日人士。；汪伪特务系统头目之一，其组织在华中沦陷区包括湖南部分城镇活动，协助日军镇压抗日人士。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0cec713d888a4ea88b052c9a449fa28e','63006a4879fb4f49ad97a1e88c8c5d69',1942,'伪第二方面军总司令、伪军头目','原西北军将领，投敌后率部伪化，所部在安徽、江苏北部活动，配合日军扫荡，对安徽沦陷区有影响。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ff1c4902ef98464399222fa0a7918076','34b437978de7456ead4135526ebbb7d5',1938,'伪安庆维持会会长','安庆沦陷后出面组织伪维持会，协助日军维持地方秩序、征粮征夫，为日军侵略服务。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f2d3895d488647aca67b00d3c4763ca5','3f08bb498a84491aaaa44d3c096ddd73',1938,'伪怀宁县知事、伪安庆地区伪政权官员','安庆沦陷区伪政权官员，历任伪怀宁县知事等职，协助日军推行保甲制度、征收赋税，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dce5fd80159549118c91c5897ea4563f','3cad5c7111df4e1d83aca1226d9895ad',1940,'伪岳西县维持会会长','岳西地区投敌分子，组织伪维持会，为日军提供情报、粮秣，配合日伪军对岳西山区抗日武装的扫荡。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2dd9e15259a9457485e3d43cfc90598c','4afaf7ecfe0a448bafa150f23c9fc2ed',1938,'伪桐城县知事','桐城沦陷区伪政权头目，任伪桐城县知事，协助日军统治桐城、枞阳一带，推行奴化教育。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('59504ee9365841e784ef9e6dcc5a7675','4deb0ed7d29b4fe9a5eec880f39ce401',1941,'伪军团长、伪安庆保安团头目','原地方武装头目，投敌后任伪军团长，盘踞安庆周边，配合日军清乡，残害百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9f0d34d0f3fd436f91c0d7d505fc81d8','2402233d224a40b3b48c4777c32146ca',1940,'伪安徽省教育厅长','汪伪安徽省政权教育官员，在安庆等沦陷区推行亲日奴化教育，篡改教材，毒害青少年。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8c86605070164026bbd9af127ba0d395','007e06d315a948b5b3568088b824a1ed',1939,'伪安庆警察局长','安庆沦陷区伪警察头目，协助日军搜捕抗日人员，镇压市民反抗，维护日伪统治秩序。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('94d72c0cd73245918b80c769057e3b0d','0d2d2045fc1d498dab9499e43abcb3de',1940,'伪安徽省省长、伪司法行政部长','汪伪政权要员，曾任伪边疆委员会委员长、伪司法行政部长等。1944年后任伪安徽省长，参与安徽沦陷区行政与治安统治，战后被判处无期徒刑。；汪伪政权重要成员，曾任伪安徽省省长、伪司法行政部长等职，在安徽推行伪化统治，镇压抗日活动。；汪伪政权成员，曾任伪安徽省省长，在安徽沦陷区推行伪政权的行政与治安统治。；湖南湘乡人，汪伪政权核心成员之一，曾任伪安徽省省长、伪司法行政部长等职，参与伪政权决策，推行奴化教育与经济掠夺。；汪伪政权成员，曾任伪安徽省长，参与安徽日伪统治事务。；湖南人，汪伪政权核心成员，曾任伪安徽省省长、伪司法行政部长等职，在安徽推行伪化统治，配合日军清乡与掠夺，滁州地区在其伪省政管辖之下。；汪伪政权核心成员，曾任伪安徽省长，推行汪伪政令，配合日军清乡与掠夺，安徽滁州、定远等地在其伪省政管辖范围内。；湖南人，早年加入中共后叛变，抗战期间投靠汪精卫政权。曾任伪安徽省省长、伪司法行政部长等职，在安徽推行伪政权的行政与治安措施，配合日军对抗日根据地的封锁与扫荡。；汪伪政权核心成员之一，曾任伪安徽省省长、伪司法行政部长等职。在安徽任内推行汪伪政令，协助日军征粮、清乡，滁州地区亦受其伪政权影响。；汪伪政权要员，曾任伪安徽省省长，在安徽实施伪政，配合日军经济掠夺和治安强化运动。；汪伪政权成员，曾任伪安徽省省长，在安徽地区推行日伪法令，配合日军征粮、清乡，镇压抗日活动。；汪伪政权高官，曾任伪安徽省省长，在安徽实施伪政，配合日军征粮、清乡。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d49f228ebef94784be373b6cf3add345','8f1dd12e548b4c4f866dd743c3377896',1938,'伪安徽省长、伪华北政务委员会委员长','安徽合肥人，北洋政客。抗战后投敌，曾任伪临时政府内政部长、伪安徽省长、伪华北政务委员会委员长等职，在安徽及华北推行日军殖民统治，战后被处决。；安徽合肥人，投敌后曾任伪安徽省长，其伪政权影响宣城地区，推行奴化政策。；安徽合肥人，北洋旧官僚，抗战期间投敌，曾任伪安徽省长。；北洋政客，抗战期间投敌，曾任伪安徽省长，在安徽沦陷区推行亲日政策，协助日军征粮、清乡，滁州、凤阳等地在其伪省政权影响范围内。；安徽合肥人，北洋政客，抗战后投敌，曾任伪安徽省长，参与安徽沦陷区伪政权，其影响波及滁州地区。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('80b110f867824097b96c281001c15d69','5b3187957ade4aa1a703516923e040a3',1938,'伪军头目、伪安庆地区保安司令','安庆沦陷后投敌，组织伪保安队，长期在安庆、怀宁、桐城一带活动，配合日军扫荡、征粮、抓丁，残害抗日群众，是安庆地区有记载的伪军头目之一。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ac8358d3363541d6b7e8450a0e8d8c95','28b89fcbdbc0426a8e2b2bb23b572ec4',1938,'伪怀宁县维持会会长、伪怀宁县知事','怀宁本地士绅，1938年安庆沦陷后出面组织伪怀宁县维持会，后任伪怀宁县知事，为日军征粮、派夫、维持治安，是怀宁地区直接附逆的地方伪政权头目。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2069ac62fab74fdeb459bbedb23a8022','4deb0ed7d29b4fe9a5eec880f39ce401',1938,'伪安庆维持会会长','安庆沦陷初期出面组织伪安庆维持会，协助日军维持城区秩序、征发物资、登记户口，是安庆城区早期汉奸组织负责人之一。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('63810d9a88644d9492a32f5657bc9e4e','2ef1d226ccf14ca2b8537de3f219e714',1938,'伪安庆商会会长、伪安庆地方维持会委员','安庆商界人物，抗战期间与日军合作，主持伪商会，为日军筹款筹粮、控制物资流通，并参与伪维持会活动，属经济领域附逆者。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('74e7909871e749a1aa37280ba79c7c38','d8c3493186d94718ad05072d725f4939',1940,'伪安徽省政府委员、伪怀宁县长','汪伪政权时期曾任伪安徽省政府委员，并一度出任伪怀宁县长，在怀宁推行保甲、征粮、奴化教育，配合日军对安庆周边地区的控制。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('92c6101b2680476ab1ffc911d3994347','ac19ad67acd4492fb89544f33b23eea6',1941,'伪安庆地区清乡专员','汪伪政权在安庆地区推行清乡运动时的重要执行者，负责组织伪军警配合日军扫荡抗日武装，在怀宁、桐城、潜山交界地区实施保甲连坐与物资封锁。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2e8b8444c8f1477a9e859b1e70e4245f','38ab65dd8b634b4eb207479a5dbdb897',1939,'伪怀宁县教育局长、伪怀宁中学校长','抗战期间在怀宁附逆，主持伪教育行政，推行日语教学与亲日奴化教育，组织学生参加日军宣传活动，属教育文化领域汉奸。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7d0fcee8af27477aa74716d2ee8df7f0','6f69cb42643545b1af2306bb153ff0df',1938,'伪安庆警察局长','安庆沦陷后任伪警察局长，统领伪警察配合日军搜捕抗日人员、镇压市民反抗、管制交通与物资，是安庆城区伪警特系统的主要负责人。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0582905c26e14d8799db7ec6d94f7ccd','0a726bfefc174ed98503673f34233b9b',1939,'伪怀宁县保安大队长','怀宁本地人，投敌后任伪保安大队长，率伪军配合日军在怀宁石牌、高河、月山等地清剿抗日游击队，强征民夫与粮食，民愤较大。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('875b5f6487644d57a6987397d14bc375','4afaf7ecfe0a448bafa150f23c9fc2ed',1940,'伪安徽省宣传处官员、伪安庆日报社长','汪伪政权在安庆的文化宣传负责人，主办伪《安庆日报》，为日军侵略张目，宣传“大东亚共荣圈”，属文化宣传领域附逆者。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d621c77342e543bb867fa4f8ed77642d','26a40096acd9428f88ebde3e69fecb20',1938,'伪安徽省长、伪湖北省长','原北洋及国民政府官员，抗战后投敌，曾任伪安徽省长，参与组织安徽沦陷区伪政权，后调任伪湖北省长，是华中地区重要汉奸之一。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0046d1501daf410081074e65534a341c','f62754ef8d4a41f58e3b8f1b4bd4ab3a',1940,'伪安徽省长、汪伪考试院长','原社会党领袖，抗战后投靠汪伪，曾任伪安徽省长、伪考试院长等职，在安徽推行伪政权政策，战后被判处无期徒刑。；文化汉奸，曾任伪安徽省长，在安徽推行奴化教育，宣扬“和平反共建国”，其伪政权影响覆盖池州等皖南地区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e365e8255c5a466a8ebfbfc9b0fdfa31','70a05a799ab649dcb1e066740c197d1f',1939,'伪安庆地区税务局长','负责安庆沦陷区伪税务，为日军及伪政权搜刮民财，征收苛捐杂税，控制粮食与食盐专卖，属经济领域附逆者。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('36b88d6752284c4e9257452e24a6af23','e6b73e7c50914a1aaaeffb2fd39c3b57',1940,'伪怀宁县合作社理事长','在怀宁组织伪合作社，配合日军统制物资，低价强购农产品、高价配给日货，剥削沦陷区民众，属经济附逆者。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1510a262466141b5ada9e73720d0bcdb','5a14726dc0a944709762daf466d4cd08',1938,'伪安庆维持会会长、伪怀宁县县长','安庆沦陷后出面组织伪维持会，后任伪怀宁县县长，协助日军维持治安、征发物资，是安庆地区早期汉奸头目之一。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bdf1763d7d4a441cb3a9da556067c94f','4deb0ed7d29b4fe9a5eec880f39ce401',1938,'伪望江县维持会会长','望江沦陷期间出面组织伪维持会，为日军征粮征夫、搜集情报，协助日军控制望江地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('83c41cd4c92b4f8c96171fdf29856f97','2402233d224a40b3b48c4777c32146ca',1938,'伪安庆地区警察局局长','在安庆沦陷区担任伪警察头目，配合日军搜捕抗日人员、镇压民众，维护日伪统治秩序。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('69d37f4396df45e3a512a69bffc2edda','d8c3493186d94718ad05072d725f4939',1938,'伪安徽省政府委员、伪民政厅厅长','安徽沦陷区伪政权要员，参与伪安徽省政，协助日军推行保甲制度、征发劳役。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8481be0d433e4c749e01d87ff4af35b8','007e06d315a948b5b3568088b824a1ed',1938,'伪安庆地区教育会会长','在安庆沦陷区推行奴化教育，编写亲日教材，组织学生参加日伪宣传活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('32eb44da0b4a4eaebf9abf7ed81d7bd9','e4b3a76b09bb4f10ac1dd4808bba9d30',1940,'伪望江县保安大队大队长','望江本地投敌分子，组织伪保安大队，配合日军扫荡望江、太湖一带抗日武装。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b8a80e46b55d4eeca93b26664394871c','4deb0ed7d29b4fe9a5eec880f39ce401',1938,'伪桐城县维持会会长','桐城沦陷期间组织伪维持会，为日军筹粮筹款，维持地方伪秩序，协助日军控制桐城地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4bf2871c3ece4995bacee347303c982f','bb34b45b44c34a018d410cde66579fb1',1939,'伪安徽省保安司令、伪武汉绥靖公署主任','原国民党军官，投敌后任伪安徽省保安司令等职，率伪军配合日军在安徽包括安庆地区进行清乡与扫荡。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('005646e9b8e145c7bf503f1b8cf2d12d','fefd7f9ddbac40469c751144d6cbd784',1938,'伪安徽省保安副司令、伪军头目','抗战期间投敌，在安徽沦陷区统领伪军，配合日军维持治安，镇压抗日武装，活动范围涉及安庆周边。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('754454814ff647d0b4b0d3feb02406cd','f50cf011f8f842fc8d69caa402ffbf67',1938,'伪安徽省民政厅厅长、伪维新政府内政部长','福建人，投敌后参与伪维新政府，曾任伪安徽省民政厅厅长，协助日军在安徽建立伪政权体系，包括安庆、桐城等地。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('47131b0c13ef4780885390c1db2ffa9e','f62754ef8d4a41f58e3b8f1b4bd4ab3a',1940,'伪安徽省教育厅厅长、汪伪考试院院长','原社会党人，投敌后任伪安徽省教育厅厅长，推行奴化教育，后任汪伪考试院院长，其教育政策覆盖安庆、桐城等沦陷区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9b804526c3a342a9aef7e4fd16d02886','95e4356f12fb4832b18ecbad49cf091a',1939,'伪特工总部警卫总队队长','汪伪特工骨干，参与在安徽沦陷区的暗杀与镇压活动，其行动范围包括安庆一带。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('22a609e3a99f4804ac6c6e47d5e74f6f','848992e841c9488c8cdcf56cad9f079c',1938,'伪和平建国军第一方面军总司令','原西北军军官，投敌后统领伪军活动于豫皖地区，与安徽沦陷区包括安庆有军事配合。；河南柘城人，投敌后组建伪军，活动于豫东、皖北，与滁州地区日军有协同扫荡行动。；河南柘城人，投日后所部伪军活动于豫东、皖北，与安徽沦陷区日伪政权配合，参与对皖东抗日根据地的封锁与扫荡。；河南人，投敌后组建伪军，活动于豫皖苏边区，其势力范围一度覆盖安徽滁州、明光等地，配合日军清乡与掠夺。；原国民党军将领，1943年投敌，所部伪军活动于安徽北部、河南东部，配合日军作战。；活动于豫东、鲁西南交界地区，包括菏泽周边，组织伪军配合日军作战。；在江苏、河南、安徽交界地区组织伪军，配合日军统治。；在河南东部及开封一带扩充伪军，配合日军清乡、掠夺物资。；抗战期间投靠日军，任伪和平建国军第一方面军总司令，盘踞豫东、豫南，其伪军活动范围涉及郑州以东地区，协助日军维持沦陷区统治、扫荡抗日武装。；投靠日本，组建伪军，在华北及陕西周边地区配合日军统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5c15af1072534aa1978ef12012758671','807ca12d2dcb44989aababb17d52ca6d',1940,'伪军师长、伪淮海省保安司令','投敌后任伪军师长，在苏皖边界地区配合日军作战，其活动范围接近安庆、桐城。；在江苏北部任伪军头目，配合日军扫荡抗日根据地。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('214f0d1125fe4f6ba49bbd741dd20ed5','9a58a6d0ca124e4e8470270a43ef0a46',1938,'伪安庆警察局局长','安庆沦陷后任伪警察局局长，协助日军维持治安，抓捕抗日人员，是安庆地区伪警头目。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d82e84b2385b448ea27419339c309767','9aa78194c75d41ed93af1ccc8a1ab5c6',1938,'伪桐城县警察局局长','桐城沦陷期间任伪警察局局长，配合日军镇压抗日活动，控制地方伪警力量。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9c9a71be413d4ce0b5f5a67804289a9e','124574ad0a424e7c806d5aa065dad2a1',1938,'伪安庆商会会长','安庆沦陷后出面组织伪商会，为日军筹款筹物，协助经济掠夺，是安庆经济界附逆代表。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('15425f2fc6804648b5ed60831b58f27c','b8753c50dc8f4316ba2ad6b331f5a101',1938,'伪桐城县商会会长','桐城沦陷期间任伪商会会长，为日军征集物资，协助维持伪经济秩序。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('90ecdf437849422585158200089168af','b4da42a8d0a3425abf10522d58c50b00',1938,'伪安庆维持会会长、伪怀宁县政府筹备处主任','安庆沦陷后出面组织伪维持会，后任伪怀宁县政府筹备处主任，为日军筹粮筹款、招募伪军，维持安庆城区伪秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('05713bd9e098402f968411f7fb7ae384','28b89fcbdbc0426a8e2b2bb23b572ec4',1938,'伪安庆商会会长、伪安庆维持会委员','安庆商界附逆人物，参与伪维持会，协助日军控制安庆商业与物资调配，为占领军提供经济支持。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5fe9228db99a4282847e00cd39de2dc2','2ef1d226ccf14ca2b8537de3f219e714',1938,'伪潜山县维持会会长','潜山沦陷期间出面组织伪维持会，为日军征派粮秣、夫役，协助维持潜山地区伪统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('92d405705a104447b69235cd51d6745c','4afaf7ecfe0a448bafa150f23c9fc2ed',1940,'伪潜山县县长','汪伪政权委任的潜山县伪县长，在潜山及周边地区推行伪化行政，配合日军清乡与物资掠夺。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('351ce129d1034f1391e5623d370d6a7a','2402233d224a40b3b48c4777c32146ca',1938,'伪怀宁县县长','安庆沦陷后任伪怀宁县县长，管辖区域包括安庆城区及周边，协助日军征粮、拉夫、维持伪治安。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1549f57e731149e39b63dabaf650e0ff','4deb0ed7d29b4fe9a5eec880f39ce401',1938,'伪桐城县县长','桐城沦陷期间任伪县长，在桐城、安庆一带配合日军行动，推行保甲连坐，镇压抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3cc06ad22da740f4b5862a78788bbf20','6be31947c11346b99840f50f540d787a',1938,'伪安庆警察局局长','任伪安庆警察局局长，协助日军维持城区治安，搜捕抗日人员，管理伪警察队伍。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2d6978442d004f65b938a0983c6ce66a','d8c3493186d94718ad05072d725f4939',1939,'伪安庆地区保安团团长','组织伪保安团配合日军在安庆周边清乡，袭击抗日游击队，强征民夫与物资。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('341319ef03984837b9bfbb235a03b3d5','26a40096acd9428f88ebde3e69fecb20',1938,'伪湖北省省长、伪安徽省省长','曾任伪安徽省省长，在安徽境内推行伪政，后调任湖北，其安徽任内配合日军掠夺资源、镇压抗日。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('968675a6748f4542afbd4bb2deca555b','f62754ef8d4a41f58e3b8f1b4bd4ab3a',1940,'伪安徽省省长、汪伪考试院院长','汪伪政权人物，曾任伪安徽省省长，在安徽推行奴化教育与伪化行政，协助日军统治。；社会党人出身，抗战期间附逆汪伪，曾任伪安徽省长，参与安徽沦陷区伪政权和文化宣传事务。；汪伪政权人物，曾任伪安徽省长，配合日军在安徽推行伪化教育与行政统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c88f936bcb5348d09bd5af919f4aa7dc','07ff958e7f18410f864975f09234ac7e',1939,'伪警政部长、伪江苏省长','汪伪特工总部“76号”实际负责人，在安徽等地设立分支机构，残害抗日志士，安庆地区受其影响。；汪伪特工头目，掌管伪警政，其特工与警察系统延伸至安徽沦陷区。；浙江遂昌人，汪伪政权特务头目。曾任伪警政部长，其特务组织活动范围包括安徽沦陷区，间接涉及黄山、休宁地区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9a33d382c1a74924931bbf734ed5d657','0d2d2045fc1d498dab9499e43abcb3de',1940,'伪司法行政部长、伪安徽省长','曾任伪安徽省长，直接管辖安庆迎江地区，推行伪政权法令，协助日军征粮、抓夫。；汪伪政权要员，曾任伪安徽省长，直接管辖安徽沦陷区。；汪伪政权要员，曾任伪司法行政部长，后任伪安徽省长，抗战胜利后被处决。；周佛海亲信，历任伪司法行政部长等，战后被判无期；汪伪政权法律体系构建者，其伪法律在浙江适用，为日军占领绍兴、诸暨提供“合法”外衣。；汪伪政权要员，任伪司法行政部长、伪安徽省长等职，协助日军统治安徽。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9985d912236c47b1a785de84e862b05f','3f934b1c263b4cd78c73d9700621e7bd',1941,'伪安徽省长（继任）','继罗君强后任伪安徽省长，在安庆地区继续维持伪政权统治，搜刮民财。；任伪安徽省长期间，多次到淮南矿区视察，督促增产煤炭，配合日军“治安强化运动”，在八公山地区组织伪军清乡，杀害抗日游击队员。；继罗君强后任伪安徽省长，在芜湖地区继续推行日伪统治，配合日军“清乡”行动。；继罗君强后任伪安徽省长，在芜湖鸠江地区继续协助日军统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4fb14325ea90478c93d6f625a32b4c4c','4cc5391bc78947fa9bf1a4b59e0f5371',1940,'伪安徽省长（早期）','汪伪政权首任安徽省长，在安庆设立伪省政府，推行保甲制度，镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6bfb9fb1840748279636927b9b0f6a96','80fe7d838ad74b0a85fb052df7042ae3',1938,'伪安庆维持会会长','日军占领安庆后，出任伪维持会会长，为日军提供粮食、情报，协助建立伪政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('82fc30c5eda248daa9e3b8a04b46cdb8','16e0035aed2144fe817582d8480b3b67',1938,'伪安庆县知事','在安庆迎江地区任伪县知事，推行日伪政策，强征劳役，迫害抗日家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('09c432a1df8a4fe18bb125d93f87455a','139410cfb2f9463abacbf741df6394ef',1939,'伪安庆保安司令','组织伪保安队，配合日军清乡扫荡，在迎江地区抓捕抗日分子。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('89ff71fc73a64ea99c9475f2b5fd18e9','cdb86f09c63c42d7bab1ae709ea7b7c1',1940,'伪安庆警察局长','指挥伪警察，在安庆城区及迎江一带镇压抗日活动，协助日军维持治安。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f264ac56ac004eb396072ea82831890a','2bdb92533ee549b7ad2f57af0112f44d',1941,'伪怀宁县（含安庆城）知事','管辖安庆迎江地区，推行日伪户籍制度，强征物资，为日军服务。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2ccf9f70dff34494b4de28481dd95e20','f7561e29d3204274b713e8543dc4117f',1938,'伪怀宁县维持会副会长','协助日军在安庆建立秩序，组织汉奸团体，迫害爱国人士。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c71f6cd03d284269b64b8c5b13590bb5','65a60a99b87b474f8c95370afe267657',1939,'伪安庆商会会长','为日军筹款、采购物资，控制安庆商业，在迎江地区剥削商户。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0f582db6a9cb4551ad291821f6eb6ca1','d6c46b119f9a4a949fb7958a887f2e3c',1940,'伪安庆教育督办','推行奴化教育，在迎江地区学校强制教授日语，删除抗日内容。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4c5e5a59b5f847fbb71a312e722ef5c0','a5115d003a0142829d1e2aef766c38d3',1941,'伪安庆税务局长','为伪政权和日军征收苛捐杂税，在迎江地区搜刮民脂民膏。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bab116bc88594207b05ae5796bdf5dc2','0e27c43ed7d146e2b2c5203a50a1785c',1942,'伪安庆特务队长','率领汉奸特务，在迎江地区刺探抗日情报，逮捕并酷刑审讯抗日志士。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b68ee173d3564bcfa7a945d6959f97a8','62a6d6c8e7ab4bbfbc92c5b14abbde74',1938,'伪国民政府立法院院长、伪行政院院长','追随汪精卫投敌，历任伪立法院院长、伪上海市长、伪行政院院长等职，1944年汪精卫死后继任伪国民政府主席，继续推行卖国政策。；随汪精卫投敌，历任伪立法院院长、伪行政院院长等职，汪死后继任伪国民政府主席，继续推行附日伪化统治，其伪政权覆盖安徽沦陷区。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9f80cf07ea92425f925de632e97f733d','a2e4190c87b449e685d78c118a6801b5',1938,'伪国民政府财政部长、伪警政部长、伪上海市长','汪伪政权核心人物之一，曾任伪财政部长、警政部长、上海市长等职，掌控伪政权财政与特务系统，参与对安徽等沦陷区的控制。；汪伪政权核心人物之一，掌管伪财政与警政，参与伪政权对包括安徽在内沦陷区的统治与搜刮。；湖南沅陵人，中共一大代表后叛党，抗战期间投敌，任伪财政部长、警政部长等职，掌控伪政权财政与警察系统，其伪警政体系延伸至江西沦陷区。；湖南沅陵人，汪伪政权核心人物，负责伪政权财政与警政，其政策影响河南沦陷区，协助日军搜刮物资、维持伪治安。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1fa4c58102d54376bb3f94b25ef483b7','8f1dd12e548b4c4f866dd743c3377896',1937,'伪华北政务委员会委员长、伪内务总署督办','华北地区主要汉奸之一，曾任伪华北政务委员会委员长，推行奴化教育，配合日军对华北及安徽北部等地的统治。；安徽合肥人，北洋旧官僚，抗战期间投敌，在华北伪政权中任要职，配合日军统治，搜刮民财，镇压抗日力量。；安徽合肥人，抗战期间投敌，在华北伪政权任要职，配合日军统治。；华北重要汉奸，虽主要在北平活动，但其伪政权体系覆盖山东，参与推行治安强化运动与掠夺山东资源。；山东济宁人，抗战期间投靠日本，参与伪华北政权，历任伪临时政府内政部长、伪华北政务委员会委员长等职，推行日伪统治政策。；北洋政客，抗战期间附逆，参与伪华北政权，推行日伪统治，山东沦陷区包括聊城、临清一带受其伪政权影响。；继王克敏后任伪华北政务委员会委员长，积极推行日军‘治安强化运动’，其政令下达至山东聊城、莘县一带，配合日军对鲁西北抗日根据地扫荡。；继王克敏后任伪华北政务委员会委员长，管辖山东等省伪政权，推行治安强化运动。；华北伪政权核心人物，参与统治包括山东、青岛在内的沦陷区，推行治安强化与经济掠夺。；华北重要汉奸，虽主要在北平活动，但其伪华北政权统辖河北，参与推行治安强化运动与奴化教育。；河北籍汉奸，华北伪政权核心人物，在河北各地推行伪化教育、经济统制与治安强化运动，其政令覆盖承德及河北大部，配合日军镇压抗日根据地。；作为华北伪政权首要人物之一，推行日军侵略政策，其伪政令覆盖河南沦陷区包括信阳，影响当地伪政权运作。；安徽合肥人，抗战期间在北平主持伪华北政权，推行奴化教育、经济掠夺，其政令覆盖河南全省，包括南阳地区。；安徽合肥人，抗战期间在华北伪政权中担任要职，推行日军侵略政策，其伪政权管辖范围包括河南北部，对河南沦陷区实施殖民统治。；安徽合肥人，抗战期间投靠日军，在伪华北政务委员会任职，参与推行日伪统治政策，其管辖范围覆盖河南北部沦陷区。；安徽合肥人，北洋政客，抗战爆发后投敌，任伪华北政务委员会委员长等职，主持华北沦陷区伪政权，推行奴化教育、经济掠夺，其伪政权管辖范围包括河南北部，对河南全省包括南阳、新野的伪化统治有间接影响。；安徽合肥人，抗战期间在北平主持伪华北政务，推行奴化教育、经济掠夺，其政令覆盖河南沦陷区，包括南阳部分区域。；安徽合肥人，抗战期间投敌，任伪华北政务委员会委员长等职，管辖包括河南在内的华北伪政权，推行奴化教育、经济掠夺。；安徽人，北洋余孽，抗战期间在北平主持伪华北政务，推行奴化教育、经济掠夺，其政令覆盖河南沦陷区包括南阳部分区域。；安徽合肥人，北洋旧官僚，抗战期间投敌，在伪华北政权中任要职，其统治范围覆盖河南北部，推行奴化教育、经济掠夺。；安徽合肥人，北洋政客，抗战期间投敌，任伪华北政务委员会要职，其伪政权管辖范围包括河南北部，推行奴化教育、经济掠夺。；华北地区最高伪政权头目之一，其伪政令覆盖河南沦陷区，推动保甲、治安强化运动，对周口、商水等豫东地区伪政权有统辖影响。；安徽合肥人，北洋政客，抗战后投敌，任伪华北政务委员会委员长，其伪政权体系覆盖河南北部及豫东部分地区，推行奴化教育和物资掠夺政策。；安徽合肥人，北洋旧官僚，抗战期间投敌，任伪华北政务委员会委员长等职，其伪政权体系覆盖河南北部及豫东部分地区，对商丘一带伪政权有统辖影响。；安徽合肥人，北洋旧官僚，抗战期间投敌，任伪华北政务委员会委员长等职，推行奴化教育、经济掠夺，其伪政权管辖范围包括河南沦陷区。；安徽合肥人，北洋政客，抗战期间投敌，任伪华北政务委员会委员长等职，其伪政权统治范围包括河南北部，推行奴化教育、经济掠夺。；华北伪政权要员，参与统治包括河南在内的华北沦陷区，推行奴化教育与经济掠夺。；安徽合肥人，抗战期间投敌，任伪华北政务委员会委员长等职，其伪政权管辖范围包括河南北部濮阳一带，推行奴化教育与经济掠夺。；安徽合肥人，但在华北伪政权中任职，其伪政权管辖范围包括河南北部，推行日军侵略政策。；安徽合肥人，北洋政客，抗战期间投敌，任伪华北政务委员会要职，其伪政权管辖范围包括河南北部，推行奴化教育、经济掠夺，支持日军统治。；安徽合肥人，长期在华北伪政权中任职，其伪华北政务委员会管辖范围包括河南北部及部分中部地区，对河南伪政权体系有统辖影响。；安徽合肥人，北洋余孽，抗战期间投靠日军，任伪华北政务委员会委员长，其伪政权管辖包括河南北部及中部，对河南沦陷区包括驻马店一带实施伪化统治，推行保甲、征粮。；安徽合肥人，北洋旧官僚，抗战期间投靠日本，任伪华北政务委员会要职，其伪政权对河南沦陷区包括驻马店一带实施间接统治。；安徽合肥人，华北地区头号汉奸之一，虽非咸宁籍，但其伪政权体系覆盖湖北部分沦陷区，影响涉及咸宁周边。；安徽合肥人，但与湖北黄冈地区有活动关联，曾参与伪政权对湖北的渗透，推行亲日政策。；安徽合肥人，但在湖北黄冈一带亦有活动记录，投靠日军，参与伪政权，推行奴化教育。；安徽合肥人，北洋余孽，抗战后投敌。虽主要在华北活动，但其伪政权体系与湖北黄冈、黄梅一带的伪组织有人员交流与政策联动，黄梅伪维持会曾受其伪内务总署指导。；安徽合肥人，华北伪政权头目；与湖南衡阳无直接关联。；原北洋政府要员，抗战期间投敌，任伪华北政务委员会委员长等职，协助日军统治华北，推行奴化教育。；北洋政客，抗战期间投靠日本，历任伪临时政府内政部长、伪华北政务委员会委员长等职，推行保甲连坐、经济统制，配合日军扫荡华北抗日根据地，对包括陕西在内的华北地区实施殖民统治。；投靠日本，参与伪华北政权，协助日军在华北包括陕西周边地区进行殖民统治和经济掠夺。；华北著名汉奸，参与组织伪临时政府，推行日军侵略政策，镇压抗日活动，对包括陕西在内的华北民众实施残暴统治。；华北地区最高伪政权头目之一，其伪政权体系延伸至陕西黄河沿岸部分日占区，榆林、神木一带的伪维持会、伪警察系统多受华北伪政权影响。；投靠日本，参与伪华北政权，推行奴化教育与经济掠夺，其伪政权体系延伸至陕西邻近地区。；投靠日本，参与伪华北政权，推行奴化教育与经济掠夺政策，其伪政权体系延伸至华北各地，与陕西地区有间接统治关联。；投靠日本，参与伪华北政权，协助日军推行治安强化运动，镇压抗日力量。；投靠日本，参与伪华北政权，配合日军在华北包括陕西周边进行殖民统治和经济掠夺。；参与伪华北政权，推行日伪统治，其影响范围涉及华北及西北部分区域。；投靠日本，在华北伪政权中担任要职，协助日军推行治安强化运动，镇压抗日力量，其影响波及陕西周边地区。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ed6eccb53f0f4147a85f8d1a6c031dc7','3f934b1c263b4cd78c73d9700621e7bd',1938,'伪安徽省省长、伪南京市长','曾任伪维新政府安徽省省长，后任汪伪政权南京市长、伪江苏省长等职，在安徽任职期间配合日军维持沦陷区秩序。；抗战期间投敌，曾任伪安徽省省长，在安徽沦陷区推行伪化行政，后任伪南京市长等职。；曾任伪安徽省长，协助日军在安徽沦陷区建立伪组织，推行保甲连坐，镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8b06e8bac5454d1eba0e74a587520051','d1abe59a5d664bf18b442130fc0478a1',1940,'伪安徽省省长、伪宣传部长','汪伪政权宣传系统负责人，曾任伪宣传部长、伪安徽省省长，在安徽推行奴化宣传，控制舆论。；汪伪政权宣传系统负责人，后任伪安徽省省长，在安徽推行亲日宣传与伪化统治。；汪伪政权要员，曾任伪安徽省省长，在安徽推行亲日宣传和伪化统治，涉及宿州地区。；广东信宜人，汪伪政权宣传系统负责人，曾任伪安徽省省长、伪宣传部长，控制沦陷区舆论，进行亲日宣传。；汪伪政权宣传系统负责人，后任伪安徽省省长，在安徽沦陷区推行亲日宣传与奴化教育，其伪政权覆盖滁州地区。；汪伪政权宣传系统头目，后任伪安徽省长，在安徽推行亲日宣传与奴化教育，其辖区包括滁州、定远等县。；广东人，汪精卫亲信。曾任伪国民党中央宣传部长、伪安徽省省长。在安徽任内推行亲日宣传与奴化教育，控制舆论，为日军占领政策服务。；汪伪政权宣传系统负责人，后任伪安徽省省长。在安徽推行亲日宣传与奴化教育，配合日军清乡与物资统制，滁州、琅琊一带在其伪省政权管辖范围内。；汪伪政权核心成员，曾任伪安徽省省长，在安徽推行奴化宣传与伪化统治，协助日军控制安徽沦陷区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2ad0c45129b542ef862943add4663b67','b4da42a8d0a3425abf10522d58c50b00',1943,'伪皖南独立方面军总司令','原国民党军将领，1943年率部投敌，任伪皖南独立方面军总司令，在皖南地区配合日军进攻抗日根据地。；原国民党军将领，1943年在皖南投敌，任伪皖南独立方面军总司令，活动于宣城、宁国、南陵一带，配合日军进攻新四军。；原国民党军将领，1943年率部投敌，任伪皖南独立方面军总司令，活动于皖南宣城、芜湖一带，配合日军进攻抗日根据地。；原国民党军将领，1943年率部投敌，任伪皖南独立方面军总司令，活动于宣城、芜湖、南陵一带，配合日军清乡。；原国民党军将领，1943年率部投敌，任伪皖南独立方面军总司令，活动于皖南宣城、南陵、繁昌一带，配合日军进攻抗日根据地。；原国民党军将领，1943年率部投敌，任伪皖南独立方面军总司令，活动于皖南宣城、泾县一带，配合日军进攻抗日根据地、搜刮地方。；原国民党军将领，1943年率部投敌，任伪皖南独立方面军总司令，活动于宣城、绩溪等皖南地区。；原国民党军将领，1943年率部投敌，任伪皖南独立方面军总司令，活动于皖南包括宣城、郎溪一带，配合日军扫荡抗日武装。；原国民党军将领，1943年率部投敌，任伪皖南独立方面军总司令，盘踞皖南地区。；原国民党军将领，1943年率部投敌，任伪皖南独立方面军总司令，盘踞皖南地区，包括黄山、休宁一带，配合日军扫荡抗日武装。；原国民党军将领，1943年在皖南率部投敌，被编为伪皖南独立方面军，驻防皖南包括屯溪周边地区，配合日军对抗日武装进行扫荡。；原国民党军将领，1943年在皖南率部投敌，任伪皖南独立方面军总司令，配合日军进攻新四军和抗日根据地，活动于黄山、徽州周边地区。；原国民党军将领，1943年在皖南投敌，任伪皖南独立方面军总司令，盘踞皖南芜湖、宣城、徽州周边地区，配合日军进攻抗日根据地。；原国民党军将领，1943年率部投敌，任伪皖南独立方面军总司令，活动于皖南黄山、黟县一带，配合日军进攻抗日根据地。；安徽人，原国民党军将领，1943年率部投敌，任伪皖南独立方面军总司令，活动于皖南、赣东北（含上饶周边）地区，配合日军进攻抗日根据地。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0c39948cdaa548b5a9f63ee324e24122','5b3187957ade4aa1a703516923e040a3',1937,'伪宣城县维持会会长','宣城沦陷后组织伪维持会，任会长，为日军筹粮筹款，维持地方伪秩序。；宣城沦陷后组织伪维持会，协助日军维持地方秩序、征粮派款，是宣城本地直接附逆者。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0440f6c36da6452b87073c672d39ac8a','2402233d224a40b3b48c4777c32146ca',1940,'伪宣城县县长','汪伪政权委任的宣城县县长，在宣城推行保甲制度，配合日军清乡，镇压抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('832c7d6a6e554ea7b636d8f42fd89d52','38ab65dd8b634b4eb207479a5dbdb897',1941,'伪宣城县警察局局长','任伪宣城县警察局长，协助日军维持治安，搜捕抗日人士，迫害当地百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1931dffca0b5474b84f1f67556804484','33ed95f1e4294e4e81b8ff9b078c0eb4',1938,'伪宁国县维持会会长','宁国沦陷期间组织伪维持会，任会长，为日军提供物资与情报。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a6fbacf8f410492c843404def6a68db6','d385dabb054b48799cb7eb9b60fa7cd2',1940,'伪广德县县长','汪伪政权委任的广德县县长，在广德推行伪化教育，配合日军扫荡抗日武装。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('57b7b34f28274317b5b0312ec6850b32','63006a4879fb4f49ad97a1e88c8c5d69',1942,'伪和平建国军第二方面军总司令、伪苏北绥靖公署主任','原国民党军将领，1942年率部投敌，任伪第二方面军总司令，活动于苏北、皖北地区，配合日军进攻抗日根据地。；原西北军将领，投敌后任伪军要职，其伪军活动于苏北、皖东，滁州、凤阳地区邻近其防区，曾配合日军对皖东抗日根据地进行扫荡。；原国民党将领，1942年率部投敌，所部活动于苏北、皖东一带，配合日军扫荡抗日根据地，滁州地区亦受其伪军势力影响。；原国民党将领，1942年率部投汪伪，所部活动于山东、苏北、豫东交界地区，配合日军进攻抗日根据地，其势力范围覆盖菏泽、鄄城周边。；原国民党将领，后率部投敌，在苏北、河南一带配合日军进攻抗日根据地。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b3385b792949477cabe94d0db7d59524','848992e841c9488c8cdcf56cad9f079c',1943,'伪和平建国军第四方面军总司令、伪河南省省长','原国民党军将领，1943年投敌，任伪第四方面军总司令，活动于豫东、皖北地区，配合日军作战。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('59cdfd1406a94ce387cba8e30c42688f','fefd7f9ddbac40469c751144d6cbd784',1940,'伪和平建国军第一方面军总司令','汪伪政权军事将领，任伪第一方面军总司令，所部活动于南京、安徽等地，配合日军维持沦陷区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('60c98e51ae424556be75777e696bf8db','cebb4769b324411abb6e1f5a0f26ecf6',1938,'伪海军部长、伪苏浙皖绥靖军总司令','汪伪政权海军负责人，曾任伪苏浙皖绥靖军总司令，管辖江苏、浙江、安徽沦陷区伪军，配合日军清乡。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d6c17d391df94506965e0bdb65f7e7ec','f62754ef8d4a41f58e3b8f1b4bd4ab3a',1940,'伪国民政府考试院院长、伪安徽省省长','汪伪政权文教界汉奸，曾任伪考试院院长、伪安徽省省长，在安徽推行奴化教育。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9a229a98a84545dfb261ae0ee8929369','28c69a91441d4439abc95701e2c6787a',1938,'伪工商部长、伪浙江省长','汪伪政权核心成员，参与汪精卫投敌活动，曾任伪工商部长、伪浙江省长，其政策影响安徽等沦陷区经济。；汪伪核心成员，参与汪精卫投敌谈判，后任伪工商部长、伪浙江省长，与安徽沦陷区伪政有联系。；汪伪政权要员，参与伪政权决策，其经济统制政策影响安徽沦陷区，滁州地区亦受其伪工商政策波及。；浙江永嘉人，汪伪政权重要成员，参与对包括江西在内的东南沦陷区经济掠夺与奴化宣传。；汪伪政权要员，参与伪化华中包括江西九江地区的经济统制与物资掠夺。；浙江永嘉人，参与汪精卫投敌活动，后任伪浙江省长，在浙江推行伪政，镇压抗日力量。；汪伪政权核心成员，参与对重庆方面的诱降。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9a2ca0e24bd942b890dd73b1578a852e','9910c48b9b394ffa8c73439ed0a473b0',1938,'伪社会部长、伪浙江省长、伪特务委员会副主任','汪伪政权特务头目，曾任伪社会部长、伪浙江省长，掌控伪特工总部，在包括安徽在内的沦陷区进行特务活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8ffe0c7ad973403fa43d3d5623d6e803','07ff958e7f18410f864975f09234ac7e',1938,'伪警政部长、伪特务委员会主任','汪伪政权特务头目，掌控伪特工总部，在包括安徽在内的沦陷区进行特务恐怖活动，镇压抗日人士。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f8272b9c5285417dbfdc81d783e3ed9c','c12e72a145724c39b755a2a16dce9a71',1938,'伪国民政府主席、行政院长','安徽籍（祖籍婺源，生于广东三水），1938年12月发表艳电公开投日，1940年在南京成立伪国民政府，自任主席兼行政院长，统辖包括安徽在内的华中沦陷区伪政权，是抗战时期最大汉奸。；安徽籍（祖籍婺源，生于广东三水），抗战期间叛国投敌，在南京建立伪政权，其伪政权统治范围覆盖安徽及宣城地区，是抗战时期最大汉奸头目。；安徽籍（祖籍婺源，生于广东三水），抗战期间投靠日本，在南京建立伪政权，其伪政权统治范围覆盖安徽宣城一带，推行奴化教育与经济掠夺。；安徽籍（祖籍安徽婺源，今属江西），在南京建立汪伪政权，统辖包括安徽在内的沦陷区，其伪政权在宣城、旌德周边地区推行伪化统治。；安徽绩溪人（祖籍婺源，生于广东三水，籍贯安徽绩溪），抗战期间投靠日本，在南京建立伪政权，任伪国民政府主席，是抗战时期最大汉奸之一。；安徽籍（祖籍婺源，生于广东），抗战期间投靠日本，在南京建立伪政权，其伪政权统治范围覆盖安徽及宣城地区，推行奴化教育与经济掠夺政策。；原国民党副总裁，1938年12月公开投敌，1940年在南京成立伪国民政府，自任主席兼行政院长，全面配合日本侵华，推行‘和平反共建国’路线。；安徽婺源（今属江西，邻近休宁）人，祖籍浙江山阴。抗战期间叛国投敌，在南京成立伪国民政府，自任主席，推行‘和平反共建国’路线，与日本签订卖国条约，是抗战时期最大汉奸。其伪政权势力覆盖安徽及黄山、休宁地区。；安徽婺源（今属江西）人，祖籍浙江山阴，出生于广东三水；抗战期间叛国投敌，在南京建立伪政权，是最高级别的汉奸，其伪政权统治范围覆盖安徽，对黄山、屯溪地区亦有名义上的管辖。；安徽籍（祖籍婺源，今属江西，但长期与皖南徽州地域关联），1938年公开投敌，1940年在南京成立伪国民政府，任主席兼行政院长，是抗日战争时期最大汉奸政权首脑。；安徽籍（祖籍徽州婺源，邻近黄山黟县），抗战期间投靠日本，在南京建立伪政权，任伪国民政府主席，推行亲日卖国政策。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3cc5b4a9135f4c758c24b31a7bdbcf1d','62a6d6c8e7ab4bbfbc92c5b14abbde74',1938,'伪国民政府立法院长、伪行政院长','随汪精卫投敌，历任伪立法院长、伪上海市长、伪行政院长，汪死后继任伪国民政府主席，统辖包括安徽在内的沦陷区伪政。；随汪精卫投敌，任伪职，其伪政权政令下达至安徽宣城地区，协助日军征粮、清乡。；汪伪政权核心人物，参与伪政权对安徽等沦陷区的统治，战后以汉奸罪被处决。；汪精卫死后继任伪国民政府主席，安徽宣城泾县人，随汪投敌，参与伪政权核心决策。；广东乳源人，汪伪政权重要头目，汪精卫死后继任伪国民政府主席，其伪政权对安徽沦陷区包括皖南部分地区有管辖权。；广东乳源人，随汪精卫投敌，历任伪立法院长、伪行政院长，主持伪政权日常事务，其伪政权体系涉及江西沦陷区。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cb44f94895c34868ad93751a3bef4744','a2e4190c87b449e685d78c118a6801b5',1938,'伪财政部长、伪警政部长、伪上海市长','汪伪政权核心人物，掌管伪财政与警政，其伪警政系统延伸至安徽沦陷区各县伪警察局。；汪伪政权核心成员，其伪政权体系覆盖安徽沦陷区，参与对包括宣城地区在内的沦陷区控制。；安徽绩溪人，汪伪政权核心成员，掌管伪财政与特务系统，后任伪上海市长。；安徽绩溪人，随汪精卫投敌，在伪政权中历任要职，参与对安徽等沦陷区的控制与经济搜刮。；安徽绩溪人，汪伪政权核心人物之一，曾任伪财政部长、警政部长、上海市长，掌握伪政权财政与特务系统，1946年以汉奸罪被判死刑后改无期，死于狱中。；安徽籍（祖籍徽州），随汪精卫投敌，任伪政权要职，参与对日媾和与伪政权运作。；湖南沅陵人，汪伪政权核心人物，历任伪财政部长、伪警政部长等职，其伪政权经济掠夺政策覆盖河南沦陷区。；湖南沅陵人，汪伪政权核心成员，参与伪政权对包括河南在内的沦陷区进行经济掠夺和特务统治。；湖南沅陵人，抗战期间投靠汪精卫伪政权，历任伪财政部长、伪警政部长、伪上海市长等职，是汪伪政权核心人物之一，其家乡沅陵属怀化地区，与怀化有直接关联。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c6e20793810d4333adb3f01ebd4a47f5','83a92f4d9e894ddc95c8e9a351babc4f',1938,'伪安徽省长、伪安徽省政府主席','安徽阜阳人，北洋时期政客，抗战后投敌，历任伪安徽省长、伪安徽省政府主席，主持安徽沦陷区伪政，推行保甲、征粮、拉夫。；安徽阜阳人，抗战期间投敌，历任伪安徽省长、伪安徽省政府主席等职，在安徽沦陷区推行伪化政策，其统治范围涉及黄山、休宁地区。；安徽阜阳人，抗战期间投敌，历任伪安徽省长、伪安徽省政府主席，在安徽沦陷区推行伪化统治，配合日军“清乡”与掠夺。；安徽阜阳人，抗战期间任伪安徽省长，在安徽沦陷区推行伪化统治，配合日军清乡。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6c398120091247c588cbeee4615a215c','3f934b1c263b4cd78c73d9700621e7bd',1938,'伪安徽省长、伪江苏省长','曾任伪维新政府绥靖部长、伪安徽省长，主持安徽沦陷区伪政，配合日军清乡。；在汪伪政权中历任伪安徽省长等职，负责安徽沦陷区行政，宣城地区在其管辖范围内。；历任伪维新政府、汪伪政权安徽省长，在安徽沦陷区推行伪化行政，宣城地区在其伪省政管辖范围内。；伪维新政府及汪伪政权官员，曾任伪安徽省长，在安徽推行伪化统治。；在汪伪政权中历任伪安徽省长等职，直接参与对安徽沦陷区包括宣城地区的统治与镇压抗日活动。；抗战期间投敌，历任伪维新政府绥靖部长、伪安徽省长、伪江苏省长等职。；江苏崇明人，抗战期间投敌，曾任伪安徽省长，在安徽沦陷区推行伪化统治，搜刮民财，配合日军清乡。；安徽籍，汪伪政权要员，曾任伪安徽省长、伪江苏省长，协助日军在安徽等地推行伪化政策，搜刮物资。；抗战期间投敌，曾任伪安徽省长，在安徽沦陷区建立伪政权机构，协助日军维持治安、征粮征税。；抗战期间投敌，曾任伪安徽省长，在安徽沦陷区推行伪政。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b53293e637d54227bef19b76ab07ca41','d1abe59a5d664bf18b442130fc0478a1',1938,'伪宣传部长、伪安徽省长','汪伪宣传系统头目，后任伪安徽省长，在安徽推行奴化宣传。；汪伪政权宣传与行政头目，曾任伪安徽省长，在安徽推行奴化宣传与统治。；汪伪宣传干将，后任伪安徽省长，在宣城等地进行亲日宣传与思想控制。；汪伪宣传干将，后任伪安徽省长，在安徽沦陷区推行奴化宣传与伪化统治，涉及宣城地区。；汪伪政权宣传干将，后任伪安徽省长，在安徽进行奴化宣传。；广东人，汪伪政权宣传干将，后任伪安徽省长，在安徽推行奴化宣传与伪化教育，影响宣城地区。；汪伪政权宣传干将，后任伪安徽省长，抗战胜利后被处决。；安徽籍（一说广东），汪伪政权宣传部长，后任伪安徽省长，控制沦陷区舆论宣传，推行奴化教育，1945年被捕处决。；汪伪政权核心成员，曾任伪安徽省长，在安徽进行亲日宣传与伪化统治。；广东信宜人，汪伪政权宣传部长，推行奴化宣传，影响包括河南沦陷区。；广东信宜人，抗战期间投靠汪精卫伪政权，历任伪宣传部长、伪安徽省长等职，在华中地区包括湖南进行伪化宣传和统治。；汪伪政权要员，任伪宣传部长、伪安徽省长等职，推行奴化宣传，协助日军统治安徽。；汪伪政权要员，任伪宣传部长、伪安徽省长等职，推行奴化宣传。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7c59be8d45dc417ca6cb7ad1bb91b038','5b3187957ade4aa1a703516923e040a3',1941,'伪和平建国军皖南部队头目','皖南伪军头目，活动于宣城、郎溪、广德一带，配合日军扫荡。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('177ae08822474d648b767e2945e52dd9','e2c66871d6614f4789846b103dc455d9',1940,'伪宣城县长','汪伪政权委任的宣城县长，主持宣城沦陷区伪政，征粮拉夫，配合日军清乡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e40bf6d8641c42728cd0cd188cf618eb','70a05a799ab649dcb1e066740c197d1f',1940,'伪宁国县长','汪伪政权委任的宁国县长，主持宁国沦陷区伪政。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e0561833379b49c1aa81262880c8b408','124574ad0a424e7c806d5aa065dad2a1',1940,'伪广德县长','汪伪政权委任的广德县长，活动于宣城地区广德一带。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d30ae2a1b3ce4276964da7a52d8695e7','fefd7f9ddbac40469c751144d6cbd784',1943,'伪苏皖边区绥靖军总司令','伪军头目，活动于苏皖边区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('633baf3f9078412491384afb408e2707','5ec2ad124b2f429482b1a90a7f8d4a92',1943,'伪和平建国军第二十四集团军总司令','原国民党军将领，1943年投敌，所部伪军活动于豫北、皖北。；原国民党军将领，投敌后所部在华北、华中活动，对安徽宣城地区有间接影响。；原国民党军将领，投敌后任伪军要职，其伪军活动于豫北、皖北，滁州、凤阳一带曾受其伪军势力间接影响。；原国民党军将领，1943年投敌，所部伪军活动于安徽北部及河南部分地区。；投敌后所部曾活动于鲁西，配合日军对聊城周边进行清剿。；原国民党军将领，1943年被俘后投日，任伪第二十四集团军总司令，所部在山东、河南一带活动，配合日军扫荡鲁西地区。；1943年投敌，所部在山东、河南交界地区活动，包括菏泽、单县周边，协助日军维持占领区治安，镇压抗日武装。；活动于河南、山西，与广西玉林无关。；被俘后投敌，所部伪军活动于豫北、豫西一带，协助日军扫荡抗日武装。；在河南投敌，所部配合日军在豫北、豫南地区进行清乡与扫荡。；原国民党河北省主席、第二十四集团军总司令，1943年被俘后投敌，驻防豫北安阳、林县地区，率部配合日军扫荡。；被俘后投敌，所部在河南开封、尉氏等地配合日军作战。；原国民党河北省政府主席、第24集团军总司令，1943年投敌，所部在豫北、濮阳一带配合日军作战，进攻抗日武装。；投降日军后，其伪军活动于豫北、豫中，包括许昌周边地区，协助日军维持占领区。；在华北投敌，率伪军配合日军扫荡，其活动范围涉及华北包括陕西周边。；投靠日本，率部投降，在华北包括陕西周边地区配合日军作战。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a574a5fd3a7244719ad8822b2fd1705e','8f551835027d47d8a72a3185f6ccbc2f',1943,'伪和平建国军第十军军长','原国民党军将领，投敌后任伪军长，活动于皖北。；投敌后所部在安徽、江苏交界活动，宣城地区受其伪军骚扰。；在鲁南地区投靠日军，率伪军配合日军扫荡，骚扰临沂、郯城一带抗日根据地。；原国民党将领，投敌后任伪军军长，活动于鲁南、鲁中，参与对淄博周边抗日武装的作战。；原国民党军将领，投敌后任伪军军长，在鲁南、鲁中及淄博周边地区配合日军行动，后于1945年反正。；率部投敌，在鲁西地区配合日军扫荡，强征民夫、掠夺物资。；原国民党军官，投敌后率伪军在山东配合日军作战，活动于鲁西、鲁南一带，威胁聊城、临清抗日根据地。；率部投敌后驻防山西，在吕梁山区边缘地带配合日军作战，参与对晋绥边区的扫荡。；在河南、陕西邻近地区组织伪军，配合日军扫荡抗日根据地。；投靠日本，率部投降，在华北及陕西周边地区配合日军行动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('008db2a0fdb049b080d1ed81c3f3c9b4','62a6d6c8e7ab4bbfbc92c5b14abbde74',1940,'伪国民政府代主席、行政院长','汪精卫死后继任伪政权头目，继续推行附日政策，其伪政权对安徽宣城等地实施统治。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5853a3e38aaa4f3fb4523cd292a110ff','a2e4190c87b449e685d78c118a6801b5',1938,'伪财政部长、伪上海市长','汪伪政权核心人物，参与筹建伪政权，其财政与行政体系覆盖包括安徽在内的华中沦陷区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('16e8a0ffdbb9417f8b284599d99287e5','83a92f4d9e894ddc95c8e9a351babc4f',1938,'伪安徽省长','安徽阜阳人，抗战期间出任伪安徽省长，协助日军统治安徽沦陷区，包括宣城一带。；安徽阜阳人，抗战期间出任伪安徽省长，直接负责安徽沦陷区包括宣城、郎溪一带的伪政权事务，推行日军政策，搜刮民财。；皖系军阀倪嗣冲之侄，投日后任伪安徽省长，在淮北、相山一带组织伪军，配合日军‘清乡’，杀害抗日志士。；安徽阜阳人，北洋时期政客，抗战期间投敌，出任伪安徽省长，主持安徽沦陷区伪政权，配合日军统治，其辖区涵盖皖南部分区域。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('434e347a92e54f06a3d5262685a31b36','e2c66871d6614f4789846b103dc455d9',1938,'伪宣城县县长','在日军占领宣城期间出任伪县长，负责伪政权在宣城的行政事务。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('447b43e631234396a5f64afa3a90f1bf','124574ad0a424e7c806d5aa065dad2a1',1938,'伪宣城警察局长','担任伪宣城警察局长，协助日军镇压抗日活动、维持占领区治安。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9873bb694ae343fd94844cc6044d6512','ed0d68ce0e0f4e40ba88774709d7fea6',1940,'伪安徽省警务处长','汪伪政权安徽警务头目，负责安徽沦陷区警察系统，配合日军镇压抗日力量。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('063eebeceddc4591ac5f59af890ed8c6','bb34b45b44c34a018d410cde66579fb1',1939,'伪武汉绥靖公署主任、伪安徽省长','投敌后历任伪职，曾任伪安徽省长，参与对安徽沦陷区的军事与行政统治。；原国民党将领，投敌后任伪安徽省长等职，参与安徽沦陷区伪化统治。；抗战期间投敌，曾任伪安徽省长，在安徽组织伪军，配合日军扫荡。；湖北黄陂人，原国民党将领，投敌后任伪武汉绥靖公署主任，后任伪安徽省长，在安徽沦陷区推行伪化统治，涉及黄山、休宁地区。；湖北黄陂人，原国民党将领，抗战期间投敌，曾任伪安徽省长，在安徽沦陷区推行伪化统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bfd435ab534842469964252823ccc72a','3f934b1c263b4cd78c73d9700621e7bd',1938,'伪安徽省长、伪南京市长','曾任伪安徽省长，管辖包括宣城在内的安徽沦陷区，推行伪化统治、征粮征兵。；江苏崇明人，汪伪政权官员。曾任伪安徽省长，在安徽沦陷区推行伪化统治，对黄山、休宁地区有管辖权。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('09ffedf3a2c744acb3b2cbc04f3b9462','83a92f4d9e894ddc95c8e9a351babc4f',1938,'伪安徽省长、伪安徽维持会长','安徽籍汉奸，组织伪维持会，后任伪安徽省长，在宣城等地建立伪政权、协助日军统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6c22b57f404e48a28078833a3243a4d5','5b3187957ade4aa1a703516923e040a3',1938,'伪宣城县维持会长、伪宣城县长','宣城本地汉奸，组织伪维持会，后任伪宣城县长，为日军征粮、拉夫、搜集情报。；宣城本地人，日军占领宣城后出面组织维持会，后任伪宣城县长，为日军征粮拉夫，镇压抗日群众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0ce4ac64f24a404d9ac1b5063599821a','f6d9dfca5a2a480faa907d55fa3d2f65',1939,'伪宣城县警察局长','在宣城沦陷区任伪警察局长，协助日军维持治安、抓捕抗日人员。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ef33a730694744a78e7c0444098015ac','23e225d56a0a4abab719cbc1e3c8ce04',1940,'伪宣城自卫团长','组织伪自卫团，配合日军对宣城周边乡村进行扫荡与征粮。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('839fdd1599eb4ae08799263c66ce16aa','b1e2c050fe6449ff84cb46f64f24d30e',1940,'伪和平建国军暂编第X师师长','原国民党军投敌，所部在皖南宣城、郎溪一带活动，配合日军进攻抗日根据地。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e3bda71e65344a048f9296aca6b143aa','f50cf011f8f842fc8d69caa402ffbf67',1938,'伪安徽省省长、伪苏浙皖绥靖军总司令','抗战期间投靠日军，历任伪中华民国维新政府内政部长、伪安徽省省长等职，在安徽境内推行伪化统治，组建伪军配合日军清乡、扫荡，镇压抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5ec12194b35545669d26d4bb023eaeea','5b3187957ade4aa1a703516923e040a3',1938,'伪军头目、伪宣城地区维持会/伪军负责人','在宣城、广德一带组织伪维持会和伪军，为日军搜集情报、征发民夫粮秣，参与对当地抗日武装的袭扰。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0edb80dc9aef4d4ba21710e93d17b871','9730a7c1a9604c69bbe553c26f5bad49',1938,'伪广德县维持会会长','广德沦陷期间出面组织伪维持会，协助日军维持地方秩序、摊派粮款，是当地伪政权代表人物之一。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8f2f0e899d154c6988ea836f79d5c64d','83a92f4d9e894ddc95c8e9a351babc4f',1937,'伪安徽省维持会会长、伪安徽省省长','安徽合肥人，抗战初期即组织伪维持会，后长期在伪安徽省政权中任职，是安徽沦陷区重要汉奸之一。；安徽沦陷区重要汉奸，组织维持会并出任伪省长，协助日军控制安徽地方伪政权。；安徽沦陷区早期伪政权头目，组织维持会，为日军筹办粮秣、劳工，协助建立各级伪政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1a220e9bc4a6420782733ff589351b03','70a05a799ab649dcb1e066740c197d1f',1938,'伪宣城县县长','宣城沦陷期间出任伪县长，负责为日军征粮、派款、维持治安，协助日军控制宣城地区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7cea3fdf40614e46a86e6570131c6de1','903f92a867db4e77abb94dac1ad28168',1941,'伪军将领、伪第一集团军总司令','原国民党苏鲁皖边区游击副总指挥，1941年率部投敌，所部活动于苏皖边区，曾配合日军在安徽东部、宣城周边地区扫荡。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cb3a310dfa5a4f2bb8ef781f3ecbea6b','5a14726dc0a944709762daf466d4cd08',1941,'伪军将领、伪苏皖边区绥靖军总司令','投敌后组建伪军，活动于苏皖边区，配合日军对安徽境内抗日根据地实施清乡和扫荡。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('662b924abb2a45dbb111756a8fc7eced','bacadba533394b3bb79fb5b9c5b66118',1943,'伪军将领、伪苏北绥靖公署主任','原国民党军将领，投敌后任伪军要职，所部在苏皖地区配合日军行动，对安徽沦陷区周边抗日力量构成威胁。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('995497c573334a19b403cc4fd43d3439','fefd7f9ddbac40469c751144d6cbd784',1940,'伪军将领、伪苏皖豫绥靖军总司令','抗战期间投敌，统率伪军活动于苏皖豫边区，协助日军维持占领区治安，参与对抗日武装的作战。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cb10eaeff6754b4bae04eacdb98bea65','40ceda4a3fba43bb8c30faefaa993de4',1943,'伪军将领、伪第三方面军总司令','原国民党军将领，1943年投敌，所部在山东、安徽边区活动，配合日军对抗日根据地进行清乡扫荡。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c1135c9ed36a4905acead6514144859f','f62754ef8d4a41f58e3b8f1b4bd4ab3a',1940,'汪伪政府考试院副院长、伪国民政府委员','安徽旌德人，早年社会党人，抗战期间投靠汪精卫政权，任汪伪考试院副院长等职，参与伪政权统治，战后以汉奸罪被判刑。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9460a243708447bf836076e0d7517e8f','83a92f4d9e894ddc95c8e9a351babc4f',1937,'伪安徽省长、伪安徽维持会会长','安徽合肥人，抗战期间投敌，任伪安徽省长等职，协助日军在安徽包括宣城地区推行伪政。；安徽合肥人，抗战期间组织伪维持会，后任伪安徽省长，配合日军在安徽的统治。；安徽阜阳人，抗战期间投敌，任伪安徽维持会会长、伪安徽省长，协助日军控制安徽沦陷区，推行伪化统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6ca9e54ffa114d7eaff0fbc2b6b4ea7d','8f1dd12e548b4c4f866dd743c3377896',1937,'伪华北政务委员会委员长、伪安徽省长','安徽合肥人，北洋旧官僚，抗战期间投靠日伪，曾任伪安徽省长，参与安徽沦陷区伪化统治。；北洋旧官僚，抗战期间投敌，曾任伪安徽省长、伪华北政务委员会委员长等职，在安徽等地推行伪化统治、搜刮民财。；华北及安徽地区重要汉奸，参与伪政权决策，推行日军侵略政策，影响覆盖皖北宿州一带。；安徽合肥人，北洋政客。抗战期间投敌，曾任伪华北政务委员会委员长，并一度兼任伪安徽省长，对安徽沦陷区包括黄山、休宁一带实施伪化统治。；安徽合肥人，抗战期间投敌，虽主要活动于华北，但其伪政权体系影响波及湖北黄冈等地，参与日军对华中地区的控制。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2ea298b084324867a146af177da495e8','5b3187957ade4aa1a703516923e040a3',1943,'伪皖南独立方面军副总司令','随张昌德投敌，任伪皖南独立方面军副总司令，在宣城、旌德周边地区进行伪军活动。','基层头目','hanjian');
