INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bde9040a535a4da19ed1a30f63e7094f','e2c66871d6614f4789846b103dc455d9',1938,'伪宣城县维持会会长','宣城沦陷后出面组织伪维持会，任会长，协助日军维持地方秩序、征派粮款，是宣城地区有记载的附逆人物。；宣城沦陷后组织伪维持会，协助日军维持地方统治。','基层维持会/地方自治头目','hanjian');
