INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('53792857275c488b911a4e8ed3b5967a','f62754ef8d4a41f58e3b8f1b4bd4ab3a',1940,'伪国民政府委员、伪考试院长','安徽宣城旌德人，抗战期间投靠汪伪政权，任伪考试院长等职。；江西弋阳人，汪伪政权要员。曾任伪考试院长，参与伪政权对安徽沦陷区的统治，间接涉及黄山、休宁地区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('74e0302d89774e57becacfb024d57a13','28c69a91441d4439abc95701e2c6787a',1938,'伪工商部长、伪内政部长','汪伪政权骨干，参与汪精卫投敌谈判，安徽宣城人。；浙江永嘉人，汪伪政权核心人物之一。参与伪政权对安徽沦陷区的控制，间接涉及黄山、休宁地区。；浙江永嘉人，参与汪精卫投敌活动，任伪工商部长、内政部长等职，协助日军经济掠夺。；浙江永嘉人，抗战期间投靠汪精卫伪政权，历任伪工商部长、伪内政部长等职，参与汪伪政权对华中包括湖南地区的伪化统治。','省部级/大军区级要员','hanjian');
