INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ceb65411753a4de7a7e7c85a2a0c855b','62a6d6c8e7ab4bbfbc92c5b14abbde74',1938,'伪立法院长、伪国民政府代主席','汪伪政权核心人物，在汪死后继任伪主席，其政权对安徽沦陷区包括宣城一带实施统治。；安徽籍（一说福建，长期在安徽活动），随汪精卫投敌，任伪立法院长、伪上海市长等职，汪死后任伪国民政府代主席，1946年以汉奸罪被处决。；随汪精卫投敌，任伪政权核心职务，汪死后继任伪国民政府代主席。；广东乳源人，汪伪政权核心人物，历任伪立法院长、行政院长、代主席等职，抗战胜利后被处决。；汪伪政权要员，其伪组织在四川东部包括万州一带有秘密活动。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('10463776c417419d8eb42ba383691502','3e05f83d537a4d50a5354a848a00c807',1938,'伪郎溪县维持会长','郎溪本地人，日军侵占郎溪后组织伪维持会，协助日军维持治安、征发物资，迫害抗日人员。','基层维持会/地方自治头目','hanjian');
