INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('404231bdb3c247b0a105e5c8d0d91c4b','63006a4879fb4f49ad97a1e88c8c5d69',1942,'伪第二方面军总司令、伪苏北绥靖公署主任','原国民党军将领，投敌后任伪军要职，其部队曾活动于安徽北部及皖南部分地区，与宣城地区有间接关联。；原国民党军将领，1942年率部投敌，任伪第二方面军总司令，所部在苏皖北部活动，与阜阳地区抗日力量为敌。；原国民党军将领，投敌后任伪第二方面军总司令，活动于苏北、皖北一带，对安徽沦陷区有控制，间接影响黄山、休宁地区。；率部投敌，在苏北、鲁南地区配合日军进攻抗日根据地。','省部级/大军区级要员','hanjian');
