INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('38599b8e7d5d4606b613967e4e784733','21853206ad2b417598d1af0b4b3a4782',1938,'伪宿县保安团团长','率伪保安团配合日军对宿县周边抗日根据地进行扫荡。；宿州地区伪军头目，率伪保安团配合日军扫荡，袭击抗日武装，掠夺民财。','基层头目','hanjian');
