INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('adf8c46d5e684603be0711bb67f815c8','7afda6e05b9949d28074a369c144b4b0',1938,'伪泗县维持会会长','泗县沦陷后组织维持会，为日军筹集物资、招募伪军。；泗县地区伪维持会负责人，协助日军维持占领区秩序，参与经济掠夺。','基层维持会/地方自治头目','hanjian');
