INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('55668956119148e5afde20797c6d0aae','304399e6f8f94bd5912316df10e1ac2a',1939,'伪萧县保安大队大队长','在萧县地区收编土匪武装，充当日伪帮凶，袭击抗日游击队。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a724649b0e1641b7b8c5a92fe3e31c0b','a06c0041e5294f2987f746729e510de9',1942,'伪淮海省省长兼保安司令','伪淮海省辖境包括宿州部分地区，其推行保甲连坐，征发民夫，镇压抗日力量。；原西北军将领，投日后任伪淮海省（辖今安徽淮北、宿州等地）省长，在淮北地区扩充伪军，配合日军“治安强化”运动。；原国民党第四十二军军长，投敌后任伪淮海省（驻徐州，辖苏北部分地区）省长，推行奴化统治，强征壮丁。；曾任伪淮海省（驻徐州）省长，组建伪军，参与日军对邳州、睢宁等地的清剿，后于1946年反正又叛变，最终被处决。；在汪伪政权下任伪职，所部在苏鲁豫皖边区活动，配合日军对河南抗日力量进行清剿。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6abc894a67fd4320903a3c6c4981e179','fefd7f9ddbac40469c751144d6cbd784',1942,'伪苏淮特别区行政长官','伪苏淮特别区管辖宿州等地，其推行伪化政策，掠夺物资支持日军。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('af5e94635aec4b5b98986b974032124e','3f934b1c263b4cd78c73d9700621e7bd',1940,'伪安徽省省长','在安徽沦陷区推行伪政，宿州属其辖区，协助日军征粮、清乡。；汪伪安徽省政权头目之一，在安徽沦陷区推行伪化统治，配合日军清乡与物资掠夺。；汪伪政权安徽省最高行政长官，推行奴化教育、经济统制，配合日军在皖北包括宿州地区的统治。；汪伪政权安徽省最高行政长官，其政令覆盖池州、贵池等地，推行伪化统治。','省部级/大军区级要员','hanjian');
