INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b8f62172b5a14ecbab5834c6ee95806f','70a05a799ab649dcb1e066740c197d1f',1938,'伪宿县维持会会长、伪宿县县长','宿州地区伪政权头目，组织维持会迎接日军，任伪宿县县长，协助日军征粮、拉夫、清乡，镇压当地抗日活动。','基层维持会/地方自治头目','hanjian');
