INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('74fec5f958094933897bf20780961ddd','d628138847f84b86bf8a356b172e4e52',1938,'伪安徽省教育厅厅长','安徽沦陷区伪政权教育头目，推行奴化教育，篡改教材，宣传“大东亚共荣圈”。；在安徽推行奴化教育，编写亲日教材，组织学生参加亲日活动，为日军占领区培养顺民。；在安徽沦陷区推行奴化教育，篡改教材，宣传“大东亚共荣”，毒害青少年。；在安徽沦陷区推行奴化教育，篡改教材、宣传亲日思想，滁州地区学校亦受其伪教育政策影响。','市县厅局级','hanjian');
