INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('77a814adda574b5e977f0e7448bb80aa','e3ccbe1888c3422bbb0f371257a8d01e',1938,'伪萧县维持会会长','萧县本地汉奸，抗战初期组织伪维持会，为日军筹粮、带路，协助日军控制萧县城乡。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d9d27847922c4df9b39bbf3c9beb21c2','304399e6f8f94bd5912316df10e1ac2a',1939,'伪萧县县长、伪军团长','原为地方武装，后投靠日军，任伪萧县县长兼伪军团长，在萧县、宿县交界地区配合日军清乡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8594de8acadc45aeaadd94955ea7c047','51545b6e477b4c85a1bb46726d5d34b5',1938,'伪宿县警察局局长','宿州伪警察头目，协助日军维持宿县城区秩序，搜捕抗日分子，推行保甲连坐。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('45a76c65622342e8a044f56572ea2744','ccaf5560fb1e4a3a892f62f4ce46f93a',1940,'伪安徽省教育厅厅长','汪伪政权安徽教育负责人，在安徽沦陷区推行亲日奴化教育，宿州、萧县等地学校被迫使用伪教材。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('113371fdd486439fac4b59eb44b3eecd','007e06d315a948b5b3568088b824a1ed',1940,'伪安徽省财政厅厅长','汪伪安徽财政官员，在安徽沦陷区推行伪币、征粮征税，为日军提供经济支持，涉及宿州地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('66f1eaafa2c3468296c02e20c39f0a05','70a05a799ab649dcb1e066740c197d1f',1938,'伪宿县商会会长','宿州工商界附逆者，任伪商会会长，为日军筹款筹物，协助经济统制。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b19cd2ae6ce54e06bdd239d7101f33a8','9310d462946a4ccf89039649cb4972b8',1939,'伪萧县教育会会长','萧县教育界汉奸，推行奴化教育，组织亲日宣传，协助日军控制学校。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5c6637c5d1a440b2be7e7c674e4de215','2d8ecb3c0e934838aaffddc5f651ac81',1940,'伪宿县保甲长、伪自卫团团长','宿州基层汉奸，任保甲长兼伪自卫团团长，协助日军征粮、抓丁，镇压抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b168c3a0dea64f77b6461507a768192a','b4da42a8d0a3425abf10522d58c50b00',1943,'伪皖南独立方面军总司令、伪军头目','原国民党军将领，1943年在皖南率部投敌，任伪皖南独立方面军总司令，盘踞皖南池州、宣城一带，配合日军扫荡抗日根据地，残害民众。；原国民党军将领，1943年率部投敌，任伪皖南独立方面军总司令，盘踞皖南芜湖、宣城、池州一带，配合日军进攻抗日根据地，征收捐税、强征民夫，对青阳、贵池等地区民众造成严重危害。；原国民党军将领，1943年在皖南率部投敌，任伪皖南独立方面军总司令，盘踞皖南芜湖、宣城、黄山周边地区，配合日军扫荡抗日根据地，残害民众。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1c2c504d88ed40be9e9e8352f1811672','5b3187957ade4aa1a703516923e040a3',1938,'伪池州维持会会长、伪池州自治会负责人','池州本地士绅，日军侵占池州后出面组织维持会，为日军筹粮筹款、拉夫带路，协助建立伪基层政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4be44a3df3d342959f82f0e2d94ac0a8','ff163d4899c84c3bb2f4a21fd7382e5e',1938,'伪贵池县县长','汪伪政权委任的贵池县县长，在池州城区及周边推行保甲制度，征发民夫、物资供给日军，镇压抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4cd4452682864d4f9c948d66265a2c4b','33ed95f1e4294e4e81b8ff9b078c0eb4',1938,'伪东流县县长','汪伪政权委任的东流县（今属池州东至县）县长，协助日军维持占领区治安，搜刮粮食与矿产。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('eea663478f794800b6f1eba3ae2e04c6','e2c66871d6614f4789846b103dc455d9',1938,'伪青阳县维持会会长','青阳本地人物，日军占领青阳后组织维持会，为日军提供情报与后勤服务。；青阳沦陷后组织伪维持会，任会长，后改任伪青阳县知事，协助日军控制青阳及邻近东至地区，推行奴化教育，征发劳工。；青阳沦陷后出面组织伪维持会，为日军筹措粮秣、拉夫、提供情报，协助日军维持占领秩序，是青阳当地伪政权初期的主要附逆者。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e93050d853d24317a4342021ae9b3aa0','28998920f1ec48ea9ecffe8022116867',1940,'伪石埭县县长','汪伪政权委任的石埭县（今属池州石台县）县长，在山区推行伪化统治，配合日军清乡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2b5d036842894977877fb425e9e9847d','06536dc7c8c1488eb1c6a95cbe67fed0',1942,'伪皖南绥靖军团长','伪军头目，率部在池州、铜陵、芜湖一带活动，配合日军进攻新四军皖南部队，抢掠民财。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d5d06706b3394e7ebae0c6bea84b7a24','2bed75fc78e64674b48ceff345e18ac5',1940,'伪安徽省教育厅厅长','汪伪政权教育官员，在安徽沦陷区推行奴化教育，篡改教材，宣扬“大东亚共荣”。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5431450fab9c48c59783aea395685daa','a2e4190c87b449e685d78c118a6801b5',1940,'伪财政部长、伪警政部长、汪伪政权核心','湖南沅陵人，汪伪政权第三号人物，虽主要在南京活动，但其财政、警政体系覆盖安徽池州等沦陷区，间接主导伪化统治与经济掠夺。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d9f77c59f98049a79f7d4490540908b6','62a6d6c8e7ab4bbfbc92c5b14abbde74',1940,'伪立法院长、伪行政院长、汪伪政权代理主席','汪伪政权核心人物，其行政体系涵盖安徽沦陷区，池州等地伪政权均受其统辖，推行亲日卖国政策。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('33409c861e624a248bbae8f898594100','b4da42a8d0a3425abf10522d58c50b00',1943,'伪军将领、伪皖南独立方面军司令','原国民党军将领，1943年率部投敌，任伪皖南独立方面军司令，盘踞皖南池州、东至、青阳一带，配合日军扫荡抗日根据地，残害民众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d0190992fc934494b26e8f268b6647fa','5b3187957ade4aa1a703516923e040a3',1940,'伪军头目、伪东至县保安大队长','东至县本地人，抗战期间组织伪保安队投靠日军，任伪东至县保安大队长，协助日军维持东至及周边地区治安，搜捕抗日人员，征敛物资。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ad10b3f8ba5742839f1eb98d5afafb8f','ff163d4899c84c3bb2f4a21fd7382e5e',1938,'伪池州县维持会会长','池州沦陷后出面组织伪维持会，任会长，协助日军建立伪政权，征发民夫、物资，推行保甲制度，为日军统治池州地区服务。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('488f4561b6c546fdb796181daffbda12','e501c0cf6d6b4d9e9eb5b81c43f284cb',1939,'伪贵池县知事','汪伪政权委任的伪贵池县知事，在贵池（今池州）地区推行伪化行政，配合日军清乡，镇压抗日活动，征收赋税供给日军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bc7c9e71b96c4de6b50a3eccaeef5773','a3b9535287664a6fa9a03b630ca41311',1940,'伪东流县知事','东流（今属东至县）人，投靠日军后任伪东流县知事，在沿江地区协助日军封锁长江，搜刮民财，镇压抗日游击队。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4c0cbaee062a47b7990ccb1639069543','736b0ec5e95449b9a5c3f9975a1e1c0a',1941,'伪至德县保安团团长','至德（今属东至县）本地武装头目，率部投敌后被编为伪至德县保安团，任团长，配合日军对东至山区进行扫荡，杀害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b723227e1ba84f77ba9d8ea4e659c4c1','37ec755e8c4e4711b97d4d3708b135f9',1942,'伪安徽省皖南行署主任','汪伪政权皖南行署主任，驻芜湖，管辖皖南包括池州、东至在内的伪政权，推行日军殖民政策，组织伪军配合扫荡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cb346332823f4ffa9dbd7e6607cb8831','70a05a799ab649dcb1e066740c197d1f',1943,'伪池州地区清乡专员','汪伪清乡委员会派驻池州地区的专员，负责在贵池、东至、青阳等地推行清乡运动，建立伪保甲联防，搜捕抗日分子。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c3edad7eb552453aa492a6e68e23aa98','3f934b1c263b4cd78c73d9700621e7bd',1938,'伪安徽省政府主席、伪江苏省政府主席','原为北洋军人，抗战后投敌，曾任伪维新政府绥靖部长、伪安徽省长、伪安徽省政府主席，在安徽沦陷区推行伪化统治，配合日军清乡与掠夺，池州一带伪政权亦受其节制。；原为北洋及国民政府官员，抗战后投敌，曾任伪安徽省长、伪安徽省政府主席，参与汪伪政权在安徽的统治，配合日军清乡与掠夺，其伪政权体系延伸至皖南池州等地。；原为北洋及国民政府官员，抗战期间附逆，曾任伪维新政府绥靖部长、伪安徽省长、伪安徽省政府主席等，参与安徽沦陷区伪政权建设与治安强化运动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2c6479ab9a1747abaa04fd857dcb876e','b4da42a8d0a3425abf10522d58c50b00',1943,'伪皖南独立方面军总司令、伪皖南行署主任','原国民党军将领，1943年在皖南率部投敌，任伪皖南独立方面军总司令，盘踞芜湖、宣城、池州一带，配合日军进攻新四军，残害抗日军民，是皖南地区重要汉奸武装头目。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('10f4c633017a47318eecdc6b7b10b794','5b3187957ade4aa1a703516923e040a3',1943,'伪皖南独立方面军副司令、伪军师长','随张昌德投敌，任伪皖南独立方面军副司令兼师长，在池州、青阳、石台周边地区活动，协助日军扫荡抗日根据地，征收苛捐杂税，迫害民众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d77a292dabf2412faa483bef56405236','e2c66871d6614f4789846b103dc455d9',1938,'伪池州维持会会长、伪贵池县知事','池州贵池人，日军侵占池州后出面组织维持会，后任伪贵池县知事，为日军筹粮筹款、拉夫带路，协助建立伪保甲制度，控制池州城区及周边乡镇。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ca38442ba1064245afafb42598a8b84e','dc807d337e854648a44d715c4f34d4b5',1938,'伪石台县维持会会长','石台县地方士绅，日军侵扰皖南时投敌，组织石台县维持会，为日军提供情报与物资，协助伪化地方基层，后因内部争斗失势。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('70fb5cadc2b14d3aba32fccda5af98d9','ff163d4899c84c3bb2f4a21fd7382e5e',1938,'伪青阳县维持会会长、伪青阳县知事','青阳人，日军占领青阳后投敌，历任伪维持会长、伪县知事，在青阳、石台交界地区推行伪化统治，配合日军清乡，搜捕抗日人员。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5176abd822584ed4bb95c0d456e765ac','33ed95f1e4294e4e81b8ff9b078c0eb4',1938,'伪东流县维持会会长','东流县（今属池州东至）人，投敌后组织维持会，控制东流沿江地区，为日军运输物资、提供情报，其势力范围与石台、贵池相邻。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0259c0e45b7b47c28c1378f5476ee894','ae97568ef9e0432abf02b2e636a1f017',1938,'伪秋浦县（今贵池）维持会副会长','贵池地方商人，投敌后任伪秋浦县维持会副会长，协助日军管理码头与物资转运，在池州沿江一带为日军服务。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('25d0f8706a374a028c770f233f7b09cc','b387d4f177e54721b632b230fe0a649a',1940,'伪池州警察分处主任','汪伪安徽省警务处在池州设立警察分处，负责人配合日军维持治安，搜捕抗日分子，推行保甲连坐，具体姓名史料记载不全。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('743cbee46a744614846e79137c282134','70a05a799ab649dcb1e066740c197d1f',1940,'伪安徽省政府委员、伪皖南行署秘书长','汪伪安徽省政府要员，参与伪皖南行署事务，协助日军在皖南包括池州地区的伪化行政与经济掠夺。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('200ff325a2c8414c99f8062a7b96d49d','bb34b45b44c34a018d410cde66579fb1',1939,'伪武汉绥靖公署主任、伪安徽省长（未到任）','原国民党将领，投敌后任伪军要职，曾被任命为伪安徽省长，其伪军势力在皖南沿江一带活动，与池州地区伪政权有联系。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('37b1a4ecfeb04ff7a684f6619a7ae22b','f50cf011f8f842fc8d69caa402ffbf67',1938,'伪安徽省维新政府省长、伪内政部长','福建人，伪维新政府要员，曾任伪安徽省长，在安徽沦陷区建立伪政权体系，池州等地伪维持会受其节制。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('78f6527d1b4647f4bbf118a0e5d59f7f','70a05a799ab649dcb1e066740c197d1f',1938,'伪贵池县维持会会长、伪贵池县县长','日军侵占贵池后出面组织伪维持会，后任伪贵池县县长，为日军征粮、派夫、维持占领秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fdf5f9d0660f4d528feff67bc65b9479','dc807d337e854648a44d715c4f34d4b5',1939,'伪贵池县警察局局长','在贵池沦陷区组建伪警察力量，配合日军搜捕抗日人员、镇压民众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e26e5fc15a3c4809b6a456fbb83831ca','fb6dff0e5f0a4b15b4c9911b93a3aa10',1940,'伪贵池县保安大队大队长','统率伪保安大队配合日军对贵池及周边抗日根据地进行扫荡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4f6f4e2d6e724abe8e0016b11239a3c7','e2c66871d6614f4789846b103dc455d9',1938,'伪池州地区维持会联合会负责人','联络贵池、东流、至德等地伪维持会，协助日军推行治安强化运动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('faaea9fda91f42cc922b2e75203d8d7e','ec06455414524c44ab90ecb621c05970',1940,'伪安徽省贵池县教育科科长','在贵池推行奴化教育，强制使用日伪教材，组织学生参加亲日宣传活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9820e699acc54663be64e5853db00b98','33ed95f1e4294e4e81b8ff9b078c0eb4',1939,'伪贵池县商会会长','为日军筹款筹粮，控制沦陷区物资流通，协助日军经济掠夺。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3d247d41453c4beb8b86b95a3662df6f','83a92f4d9e894ddc95c8e9a351babc4f',1938,'伪安徽省维持会会长、伪安徽省政府主席','组织安徽伪维持会系统，为日军在池州等地的占领提供行政支持。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ce4e67e78f304b03afb03fe785e6c4db','5b3187957ade4aa1a703516923e040a3',1938,'伪军团长、伪青阳县保安大队长','青阳本地人，抗战期间投靠日军，组织伪保安武装，控制青阳及周边地区，为日军征粮、带路、搜捕抗日人员，参与维持会活动，是青阳地区有记载的附逆武装头目。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6b67aac47f9645a9b3e7cd2a06c31fc9','ff163d4899c84c3bb2f4a21fd7382e5e',1938,'伪贵池县维持会会长、伪贵池县县长','贵池（今池州市区）人，日军占领贵池后投敌，先后任伪维持会会长、伪县长，管理伪政权，为日军征粮征税、推行保甲，其辖区与青阳相邻，对青阳地区伪政权有影响。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5f0135d992aa44d7a1131fb692e5ad02','e501c0cf6d6b4d9e9eb5b81c43f284cb',1938,'伪东流县维持会会长','东流（今属池州市东至县）人，抗战期间组织伪维持会，协助日军控制长江南岸东流、至德一带，与青阳、贵池伪政权互通声气，参与征粮与情报活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b104f36241544e0981c627bfe0946501','ae97568ef9e0432abf02b2e636a1f017',1938,'伪安徽省财政厅厅长','安徽人，汪伪政权财政官员，负责安徽沦陷区税收与物资统制，为日军搜刮战略物资，其财政网络覆盖池州、青阳等皖南地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d759901f4d1b41d7a75241647e552142','e4b3a76b09bb4f10ac1dd4808bba9d30',1938,'伪安徽省政府委员、伪教育厅厅长','在汪伪安徽省政府中负责教育，推行亲日奴化教育，在沦陷区学校强制日语教学与亲日宣传，池州、青阳等地部分学校受其政策影响。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3b34ebbd0b2545b1b5ced5e777723e62','37ec755e8c4e4711b97d4d3708b135f9',1939,'伪青阳县警察局局长','青阳本地附逆者，任伪警察局长期间配合日军搜捕抗日分子，管理伪警察队伍，参与保甲连坐与物资管制，是青阳地区伪警特系统的代表人物。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a203cb10887246939621acceb317c952','646be5baad234cddb74b1f3d9bc7c3dd',1940,'伪青阳县保安团团长','青阳人，组织伪保安团配合日军扫荡，在青阳、南陵、泾县交界地区活动，袭击抗日游击队，强征壮丁与粮款，对当地抗日力量造成损失。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('790fd05eee614f1fa153480a91bb58c2','d1abe59a5d664bf18b442130fc0478a1',1940,'伪安徽省主席（未到任）、伪行政院宣传部长','汪伪政权核心人物，虽主要任职南京，但曾兼任伪安徽省主席，参与策划对安徽地区的伪化统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ff50d0bab6214f45a59e7c4540c65d7e','3f934b1c263b4cd78c73d9700621e7bd',1940,'伪安徽省省长（继任）','接替倪道烺任伪安徽省长，在安徽推行保甲制度，配合日军“扫荡”，强征民夫物资。；曾任伪维新政府及汪伪政权安徽省长，在蚌埠、怀远等地推行保甲制度，强化日伪统治，配合日军“扫荡”。；1941年接任伪安徽省长，驻蚌埠，推行“治安强化运动”，组织伪军配合日军扫荡淮上抗日根据地，强迫民众“自首”，实施连坐。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a1d43a03f2784085ae73dd5e4288d5ad','70a05a799ab649dcb1e066740c197d1f',1940,'伪淮海省（淮北地区）保安司令','在淮北地区组织伪军，协助日军进攻新四军，残害抗日军民，参与“清乡”行动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7c55e2d9448743849752de334d209829','807ca12d2dcb44989aababb17d52ca6d',1940,'伪淮北绥靖军司令','驻守淮北地区，多次率伪军袭击抗日根据地，制造“潘圩惨案”等屠杀事件。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('30fe350194cd4250a2d138270df5912f','5f96d671fb3246f1ae22fff91559ebfb',1938,'伪宿县县长','在宿县（今属淮北市）任伪县长，强征粮食，出卖抗日志士，协助日军建立维持会。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9669bf7bff9c4b8f99a99adea0a3ffea','ee22b2df1c8844d69f561451511538f0',1939,'伪涡阳县长（活动于淮北地区）','在涡阳、蒙城一带为日军效力，组织伪警察镇压抗日群众，掠夺民间财物。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('00415b46b9f84680941c2c75b61a8459','799e980390314724a73f5c167e384e5a',1938,'伪濉溪维持会会长','在濉溪（今淮北市濉溪县）组织维持会，为日军提供情报，协助抓捕抗日分子。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4da674614b364ef0a542059d805e71b0','3717f98d530244a5b34bcf8620a40a4c',1939,'伪蚌埠（皖北）绥靖主任','控制蚌埠及淮北交通线，为日军运输物资，参与“三光”政策，残害百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('858c97bd7b1d442da439bafa46817f58','70a05a799ab649dcb1e066740c197d1f',1938,'伪濉溪口维持会会长','日军侵占濉溪口后出面组织维持会，为日军筹粮筹款、维持地方秩序，协助伪政权控制濉溪一带。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8c5975c386bf4158904f857c83fb2ce3','5de8249bb76d40f6b63fa1aeef8137c7',1938,'伪宿县县知事、伪淮北地区行政人员','抗战期间在宿县、淮北一带依附日军，参与伪政权行政事务，为日伪统治服务。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a6f1f494ddfd4127a50e07ad27acdf19','8f1dd12e548b4c4f866dd743c3377896',1937,'伪中华民国临时政府内政部长、伪华北政务委员会委员长','安徽合肥人，北洋旧官僚，抗战期间投靠日本，在华北伪政权中任要职，推行日伪统治政策。；江西婺源人，北洋政客，抗战期间投靠日本，在华北伪政权中任要职，参与推行伪化统治。；安徽合肥人，北洋政客，抗战期间投靠日本，参与组织伪中华民国临时政府，后任伪华北政务委员会委员长，推行奴化教育、配合日军掠夺华北资源。虽非赣州籍，但其伪政权体系覆盖包括江西在内的沦陷区，与赣州地区有间接关联。；安徽合肥人，北洋政客，抗战期间投靠日本，在华北伪政权中任要职，其伪政权统治范围包括河南沦陷区，商丘、虞城等地伪政权均受其系统影响。；长期在华北伪政权任职，推行日伪政策，其影响波及陕西等华北周边省份。；北洋政客，投敌后任伪临时政府内政部长、伪华北政务委员会委员长等职，配合日军在华北推行治安强化运动，镇压抗日力量。；长期在华北伪政权中任职，配合日军推行治安强化运动，镇压抗日力量，其伪政权体系对陕西周边及华北地区有影响。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('968ea9b6dd474a40aef2cf85ec7fa2ff','4f8793c77ca74d3dbe773329337bfbb0',1938,'伪中华民国维新政府行政院长、伪监察院长','安徽人，抗战期间组织华中伪政权，依附日军，参与伪政府事务。；福建长乐人，华中伪政权头目；与湖南衡阳无直接关联。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('15b484c8e48b4e9691abfe83873c7ee6','b4da42a8d0a3425abf10522d58c50b00',1943,'伪军头目、伪皖南独立方面军司令','原国民党军将领，后率部投敌，在皖南及安徽部分地区配合日军作战、清乡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7a418ddd3cc84c0ea2e9dcb8dfaf7f41','5b3187957ade4aa1a703516923e040a3',1938,'伪军头目、伪淮北保安队头目','在淮北一带组织伪军，配合日军扫荡抗日根据地，残害抗日军民。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5f18b4d6253d44bcb6d6629db0318e3e','46bdc67b9ef84e198720785e6442c8ce',1938,'伪濉溪地区保甲长、维持会人员','在濉溪、杜集一带充当日伪基层爪牙，催粮逼款、监视民众，协助日军维持占领秩序。','基层帮凶(维持会系统)','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2f5f989d9a334703bad9362819f3a632','848992e841c9488c8cdcf56cad9f079c',1938,'伪淮北绥靖司令','原西北军将领，投日后任伪淮北绥靖司令，在濉溪、宿县一带协助日军清乡，镇压抗日武装，强征民夫修筑工事。；原西北军将领，投日后任伪淮北绥靖司令，在烈山、濉溪一带协助日军扫荡抗日武装，强征民夫开采烈山煤矿资源供日军使用。；原西北军将领，投日后任伪淮北绥靖司令，在淮北、相山一带协助日军‘扫荡’，残害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('00f84768f3514b5a94dd81924f17e0c2','5f96d671fb3246f1ae22fff91559ebfb',1939,'伪濉溪县知事','任伪濉溪县知事期间，推行保甲制度，向日军提供抗日分子情报，强征粮食，迫害抗日家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b7ec6f39574b410cbec8f9ebbadfe047','9440396056a04187bc52e7b50788149b',1940,'伪淮北保安队大队长','率伪保安队配合日军扫荡濉溪、百善、临涣等地，多次袭击抗日游击队，杀害地方干部和群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5d36c1a517e24ab1b6a34ed2bb549ba2','00cb65377c0040eb8014e5612ffc329b',1938,'伪濉溪维持会会长','日军占领濉溪后首任维持会长，组织汉奸政权，为日军筹粮派款，强迫百姓悬挂日旗，报告抗日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('95f6f4eb7a654744b2eab533561a5bb6','40024fb6888e4b039cfc06035f6a4613',1941,'伪安徽省第四区行政督察专员（驻濉溪）','在濉溪地区推行伪化统治，设立“清乡”机构，配合日军“三光”政策，逮捕抗日军民送交日军宪兵队。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('12196f68b1c94582952b0a9a6c57597b','7afda6e05b9949d28074a369c144b4b0',1940,'伪濉溪县警察局长','指挥伪警察搜捕地下党员，破坏抗日交通站，参与制造“濉溪惨案”，杀害无辜群众数十人。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('319924e7bc6144b5af2e83caa8cf5b40','229d6797c3fc4b25b28d9d4d373b07df',1942,'伪淮北剿共军支队长','率部驻防濉溪、铁佛一带，多次进攻新四军第四师游击区，烧毁村庄，抢掠财物。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1e9a010b696f4429b516f9f6b8cf34ed','9f7b3ed9c76f4eea8211fd8ebc40a461',NULL,'（不适用）',NULL,'无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('61b002bd4a644d80851554d4c32c9464','5f96d671fb3246f1ae22fff91559ebfb',1939,'伪烈山矿区维持会会长','烈山本地劣绅，日军占领烈山后出任维持会长，为日军提供矿工名单，抓捕抗日嫌疑分子，克扣矿工口粮中饱私囊。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fc432a19fbec402aa310be1a20dfc371','bf9d7a2e9ecb4c04b87c7e2ba46557a2',1940,'伪淮北保安队大队长','原地方民团头目，投敌后任伪保安大队长，在烈山、蔡里一带多次袭击抗日游击队，杀害抗日军属，并配合日军“清乡”。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f4afa75e5bde4287afeb3bd8702a68bc','ea5376b8cba24145ae613e52dcb2ad57',1941,'伪烈山煤矿稽查科科长','负责为日军管理烈山煤矿劳工，克扣工资，虐待矿工，多次向日军举报矿内抗日地下活动，导致多名矿工被捕牺牲。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7a263cfd48f6423aa532c4de722cd5a8','2cc01142014e4c1cbb29f71cb79fe93e',1942,'伪濉溪县（含烈山）警察局特务股长','专门刺探新四军四师在烈山一带的活动情报，带领日伪军突袭抗日联络点，逮捕并严刑拷打抗日群众。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6e5cef17737a4bcbb20074aab5c5b07f','9f7b3ed9c76f4eea8211fd8ebc40a461',1943,'伪新编第五军军长（曾驻防淮北）','1943年投敌后，其部队曾驻扎淮北地区，参与对抗日根据地的“扫荡”，在烈山周边征粮派款，但主要活动在豫北，烈山地区事迹有限。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7dd9f0d605a84f4aa5086fa474331cb9','5f96d671fb3246f1ae22fff91559ebfb',1938,'伪安徽省长（注：刘峙未投敌，此处更正为刘子良）','刘子良，安徽涡阳人，投日后任伪安徽省长，在淮北地区推行保甲制度，强征粮税，镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0e5d5a7f3538488e90065e4fe29bb5d4','d1abe59a5d664bf18b442130fc0478a1',1943,'伪安徽省长（后期）','汪伪政权要员，任伪安徽省长期间，在淮北地区强化奴化教育，推行‘新国民运动’，协助日军掠夺物资。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e27e08bc8c1646818b39202fce0588c0','3f934b1c263b4cd78c73d9700621e7bd',1940,'伪安徽省长（代理）','投日后任伪安徽省代理省长，在淮北、相山地区设立伪区乡政权，强抓壮丁，破坏抗日根据地。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8f858cd4c7344b0aabb86440c1715774','4cc5391bc78947fa9bf1a4b59e0f5371',1942,'伪淮海省省长（辖淮北部分地区）','原北洋政客，投日后任伪淮海省省长，管辖包括淮北相山在内的区域，推行‘治安强化运动’，屠杀抗日群众。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('29caebc1607544ebb74f54ebc69dbc3c','807ca12d2dcb44989aababb17d52ca6d',1938,'伪淮北地区维持会会长','相山本地劣绅，日军占领后出任维持会长，为日军提供情报，强征民夫修筑工事，霸占民产。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('be777c79754e46beb008a724ddcfe166','ee22b2df1c8844d69f561451511538f0',1939,'伪相山保安团团长','投日分子，任伪相山保安团长，配合日军‘扫荡’萧县、濉溪等地，杀害抗日干部数十人。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ccc08cf7d7ee44098a76cc6106f0399f','124574ad0a424e7c806d5aa065dad2a1',1940,'伪濉溪县知事','王仲华，投日后任伪濉溪县知事，在相山地区推行‘连坐法’，强征粮食，迫害抗日家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ed8404bd30304f258bccd9913c7691fe','6b186890888c4ef59afd6a82a310d3ad',1941,'伪宿县（含相山）警备队长','李本一，投日后任伪宿县警备队长，在相山一带设卡盘查，抓捕抗日交通员，多次参与‘清剿’行动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6a3746ae23ac4f2486c086f2112ecbc2','3717f98d530244a5b34bcf8620a40a4c',1938,'伪淮北矿务督办','原煤矿主，投日后任伪淮北矿务督办，在相山附近开采煤炭资源供日军军需，压榨矿工，致数百人死亡。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('02d6f93f204a4939862618c59c139673','83a92f4d9e894ddc95c8e9a351babc4f',1938,'伪安徽省省长、伪淮南矿业所所长','曾任伪安徽省省长，后兼任淮南煤矿（日占时期）负责人，为日军掠夺淮南煤炭资源服务，镇压矿工反抗。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b2a748e2d21948f0afa46943d0b4b9d6','d2076b368add49ecaaf0640987a60c82',1939,'伪淮南煤矿警察局局长','协助日军管理淮南矿区，组织伪警察镇压矿工罢工，抓捕抗日分子，向日军提供矿工劳役。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2c430afd81ed43cbac8f35fc94a593a1','edb475b2cf104992a904364937ed9a11',1938,'伪淮南维持会会长','日军占领淮南后首任维持会长，负责为日军征粮、派夫，协助建立伪政权，迫害当地抗日家属。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('843ab1132a3146d3baffcaaf0743abbb','bf9d7a2e9ecb4c04b87c7e2ba46557a2',1940,'伪淮南县知事（日占时期淮南县）','任伪县知事期间，推行保甲制度，强征壮丁，为日军提供情报，参与“清乡”行动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4547c3444985401ea7fa6d77d81cc157','fc3532a799904724859b9fae9156ae06',1941,'伪淮南矿务督办','负责与日本三井、三菱财团合作开采淮南煤矿，压低矿工工资，增加煤炭产量供日军军需。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('876d8a120f8d4687ae95bb957599a682','85e8e57334fc480cbacf3863e9d22aee',1942,'伪淮南保安大队长','率领伪保安队配合日军扫荡淮南抗日根据地，杀害新四军游击队员及群众数十人。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4576d0a09da149fd86e4617d53feebc9','0e27c43ed7d146e2b2c5203a50a1785c',1939,'伪淮南区税务局长','为日军征收苛捐杂税，强征粮食，导致当地百姓饥荒，并贪污部分税款中饱私囊。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dd9f2ab7c8a34281ac317fceadded467','bdee5434a2434f6aba5c1f80c273e3b7',1940,'伪淮南教育督办','推行奴化教育，强制学校教授日语，删改历史教材，宣扬“中日亲善”，迫害爱国教师。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('158a530d4f7a4a80a68339c41621dd36','6eb2c9d253354251aa717193cd7b6542',1939,'伪淮南矿务局局长','日本占领淮南煤矿后，出任伪矿务局长，组织汉奸矿警队，强迫矿工为日军采煤，供应侵华战争军需，虐待矿工，造成大量矿工死亡。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ed8bef85e56f488eb17b67c5de6c9c9c','8f1dd12e548b4c4f866dd743c3377896',1937,'伪华北政务委员会委员长（曾管辖安徽北部）','虽为华北伪政权头目，但曾插手安徽淮南地区伪政权事务，协助日军在八公山一带建立伪保甲制度，征收军粮，迫害抗日家属。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4fd7a695436d4148874e6f83e9451b3d','0d2d2045fc1d498dab9499e43abcb3de',1944,'伪安徽省长（后期）','汪伪政权骨干，任伪安徽省长后，加强对淮南、八公山地区的控制，推行“新国民运动”，强迫青年接受奴化训练，并协助日军搜刮粮食。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('762e0c408ea4451a97f18929ac84dc0f','848992e841c9488c8cdcf56cad9f079c',1939,'伪和平救国军第一军军长（活动于皖北）','率伪军驻扎皖北，多次配合日军扫荡淮南、八公山抗日根据地，烧杀抢掠，抓捕抗日群众，并参与护矿，保障日军煤炭运输线。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('92f699e6dfe54a4b828810eaa468e188','a06c0041e5294f2987f746729e510de9',1943,'伪淮海省保安司令（曾驻皖北）','虽以淮海省为基地，但曾派伪军进入淮南八公山地区，协助日军镇压矿工罢工，破坏中共地下组织，残害抗日志士。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d46fb254bebe4b3e99bfd4a583c4dc1a','63006a4879fb4f49ad97a1e88c8c5d69',1942,'伪第二方面军总司令（活动于皖北）','率伪军数万人在皖北一带驻防，多次进攻淮南、八公山抗日武装，烧毁村庄，强征民夫修筑碉堡和公路，为日军运输煤炭提供保护。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1f72a6a0343746cb85b3ebb82d7c4f8e','5ec2ad124b2f429482b1a90a7f8d4a92',1943,'伪第五方面军总司令（曾驻皖北）','投敌后率部在安徽北部活动，参与对淮南八公山地区的“扫荡”，杀害抗日军民，并协助日军控制矿区，掠夺资源。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1b76b8ce6b404e30958aec5c8a93b4a5','9f7b3ed9c76f4eea8211fd8ebc40a461',1943,'伪新编第五军军长（活动于皖北）','投日后率部在皖北地区活动，曾配合日军进攻淮南八公山一带的抗日游击队，并参与伪政权对矿区的经济掠夺。','市县厅局级','hanjian');
