INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d3b9bfc475d94267a1ab6a819b8fd880','07bf8b26aa0c490e84459f9a2919d2c8',1938,'伪凤台县维持会会长','日军占领凤台后，率先组织维持会，为日军提供情报，协助建立伪政权。','基层维持会/地方自治头目','hanjian');
