INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('13d37eada6a94414a021c74ef07be792','a50124f91e2647b9a6d6613897403d9b',1940,'伪淮南矿区警察局长','在淮南矿区为日军控制煤矿，镇压矿工反抗，强征劳工，为日军提供煤炭资源。','市县厅局级','hanjian');
