INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e9cdfdf0e38143edba032e094bb1fbce','0c2036d96f2b49e6b7252d4051efc23b',1939,'伪凤台县财政科长','为伪政权征收苛捐杂税，搜刮民财，供日军和伪军使用。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('54207f33119f41d1954c7e23988652db','620f96d12e224682a48220ac2a514789',1940,'伪凤台县警察局长','指挥伪警察协助日军抓捕抗日分子，破坏地下组织，欺压百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9cf037f1d6f24fbab83ffea34298e6b1','83a92f4d9e894ddc95c8e9a351babc4f',1938,'伪安徽省省长、伪淮南矿区督办','原北洋军阀倪嗣冲之侄，投日后任伪安徽省长，积极推行日军‘以华制华’政策，在淮南大通矿区设立伪政权机构，强迫矿工为日军开采煤炭资源，镇压抗日活动。；曾任伪安徽省省长，后兼任淮南煤矿（田家庵矿区）督办，组织日伪对淮南煤炭资源的掠夺，镇压矿工抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('beb979a2eee348f6bdec5faffd02424d','d2076b368add49ecaaf0640987a60c82',1939,'伪淮南大通煤矿警察局局长','充当日军矿务管理帮凶，组织矿警队抓捕抗日地下工作者，残酷迫害矿工，多次配合日军‘清乡’行动，在大通地区制造多起血案。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8ca9fdff6e944823b44d457b1e5f79d6','edb475b2cf104992a904364937ed9a11',1938,'伪大通维持会会长','日军占领淮南后率先投敌，组织维持会为日军征粮派款，强征民夫修筑工事，并告密导致多名抗日群众被捕牺牲。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cb2fee8063294d9ca52a1c27078103ce','e87739f6f4234a0b817687e42b19e5ed',1940,'伪淮南矿区保安队队长','率保安队协助日军护矿，多次围剿新四军游击队，在洛河、上窑一带烧杀抢掠，杀害抗日军民数十人。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('82aec622512046fc81f5ba512b0815e1','0c5a598c6c2e4903aea8785d6528ed62',1941,'伪大通区区长','投靠日伪政权，推行保甲制度，强征壮丁补充伪军，配合日军‘扫荡’大通周边村庄，掠夺粮食和物资。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('708f6566abbf43ee9270d3fed62c4bc8','194487e4498b48de949603e29f8960ad',1939,'伪淮南矿务局总务处长','负责为日军管理煤矿劳工，克扣矿工口粮，虐待致死矿工数百人，并参与向日本本土输送战略煤炭。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7a8a0d9835174217986233bd5eddf518','9f7b3ed9c76f4eea8211fd8ebc40a461',1943,'伪新编第五军军长（曾驻防淮南地区）','原国民党将领，1943年投敌后所部在淮南大通一带活动，配合日军进攻抗日根据地，并参与‘曲线救国’伪化宣传。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f829ae55b81542aaa9d663699945ba0a','5ec2ad124b2f429482b1a90a7f8d4a92',1943,'伪第五方面军总司令（势力涉及淮南）','投日后其部队曾驻扎淮南周边，协助日军维持治安，参与对淮南矿区抗日力量的围剿行动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('adc7d313db0c40e5bdf079f687b702f3','a06c0041e5294f2987f746729e510de9',1944,'伪淮海省省长（曾管辖淮南部分地区）','在任期间推行日伪‘治安强化’运动，对淮南大通地区抗日活动进行残酷镇压，强征矿工补充伪军。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2973b6a59cb74232a5929aa8e04976f7','8f1dd12e548b4c4f866dd743c3377896',1940,'伪华北政务委员会委员长（名义上涉及安徽）','虽主要活动于北平，但作为伪政权高层，其政策直接指导淮南大通地区伪政权运作，支持日军掠夺淮南煤炭。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('eb21a3bea5cb45f4a5305549527accce','83a92f4d9e894ddc95c8e9a351babc4f',1938,'伪安徽省省长、伪寿县维持会会长（曾任）','原北洋军阀倪嗣冲之侄，日军占领安徽后投敌，任伪安徽省省长，推行日伪统治，协助日军在寿县等地清乡、征粮、镇压抗日力量。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d0d6caee5fb046bd86a8825cf9a455bb','d2076b368add49ecaaf0640987a60c82',1939,'伪寿县县长','日军占领寿县期间出任伪县长，组织伪政权，为日军提供民夫和粮食，配合日军扫荡，逮捕抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0ae90362e2ef4450bf3b94afdc8f687f','e4dd4370399f46839a8e95d93e2be4e7',1940,'伪寿县保安大队长','率伪保安队协助日军在寿县南部地区“清剿”新四军游击队，杀害多名抗日群众，烧毁村庄。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('88ee66afb7bc400490d5821cf1d1119d','01e75c0937a04eabbd68975a5e901763',1938,'伪寿县维持会副会长','寿县沦陷初期出任维持会副会长，为日军筹办粮秣，强征民夫修筑碉堡，并劝诱乡绅投敌。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ebe7d335a09a40ca9e16f61637fc8659','f7561e29d3204274b713e8543dc4117f',1941,'伪淮南特区警察局长（管辖寿县部分地区）','原地方武装头目，投靠日军后任伪警察局长，在寿县、淮南交界处设卡盘查，抓捕抗日地下工作者，勒索百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e8b88a4c1e034b8aa3a847e78596f516','cfb17070691845b2a8bf9eee5efeae67',1940,'伪寿县税务局长','为日军征收苛捐杂税，强征田赋，导致寿县农民破产，并贪污伪政权公款，民愤极大。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('42feb7cab8104614a38246b3b9956762','d730f8e8c35643b58c26c3eb156f0dc1',1942,'伪寿县教育科长','推行奴化教育，强制学校使用日伪教材，宣传“中日亲善”，迫害爱国教师，破坏抗日宣传活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d7171628c00f460a8bb6b836584dbab8','90d615a78438465ab7dd4a61f9ebccd0',1943,'伪寿县情报组长','为日军搜集新四军及国民党游击队情报，多次导致抗日人员被捕牺牲，并亲自参与刑讯逼供。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fcd40c98e31943b787a36fecc3e236f7','6b186890888c4ef59afd6a82a310d3ad',NULL,'无','无','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('30da200cbd3244518047c1df990206ea','83a92f4d9e894ddc95c8e9a351babc4f',1938,'伪安徽省省长、汪伪国民政府委员','原北洋军阀倪嗣冲之侄，1938年投敌，任伪安徽省长，在淮南、潘集一带推行日伪统治，强征民夫，掠夺煤炭资源，镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f813670b70ad4ecd9b8ddf59ed7c51a9','76223232c38241b996a8dcb3d7f9af4f',1939,'伪淮南矿警队队长','驻守淮南煤矿（含潘集矿区），协助日军维持矿区秩序，抓捕抗日地下工作者，残害矿工，多次参与“清乡”行动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ac486b233f7c4be981b614aca0434eb2','5721c8bdd56c44f98f2c4c5821f12c41',1940,'伪潘集区维持会会长','在潘集地区组织维持会，为日军征粮派款，提供情报，协助日军扫荡新四军游击区，欺压百姓。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('18cf069b99464370912e48fb4b2d53e6','78bbe30320354e069efe1aa54d842cb9',1941,'伪淮南保安团团长','率保安团驻防淮南、潘集交界地带，配合日军“蚕食”抗日根据地，杀害多名抗日军民，抢劫民财。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f1e66178527045a5adc992ee047e9a7f','b65c0f4930254d19a26945587952284b',1942,'伪潘集区区长','投靠日伪后任区长，推行保甲制度，强抓壮丁，向日军报告新四军活动，导致多处抗日联络点被破坏。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('69840ddda9984b8dbf8ce13ca13616c8','bf9d7a2e9ecb4c04b87c7e2ba46557a2',1943,'伪淮南绥靖军第三师师长','率伪军驻扎淮南、潘集一带，参与日军“扫荡”，在潘集地区烧毁村庄，杀害抗日家属，掠夺牲畜粮食。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bdfb46ba40ef4dac9a6c32130f8f17e0','442c28514ea346ce822d971794bd311c',1940,'伪潘集区自卫团团长','组织地方自卫团为日军效力，在潘集各乡设卡盘查，逮捕抗日嫌疑人员，并参与对抗日根据地的突袭。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6c449e88915d498ba6cf476f8f0ae7c2','fadd5666781e4a638b98446b34550753',1939,'伪淮南矿务局稽查主任','负责淮南煤矿（含潘集矿区）的劳工管理，克扣矿工口粮，向日军举报抗日工人，导致多名矿工被处决。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('98f7031c58f348b39b141440c4d97afb','d2076b368add49ecaaf0640987a60c82',1939,'伪淮南煤矿局局长','在日本占领期间担任伪淮南煤矿局局长，负责管理田家庵矿区生产，为日军提供煤炭资源，迫害矿工。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('51ed41c2dcde44188833752c9d4d42ba','6174377f7b5b49cda0a8bcbe33b2f2a6',1938,'伪田家庵维持会会长','日军占领田家庵后出任维持会会长，协助日军建立伪政权，征收粮税，强迫民众为日军服务。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a27ad03cab134801aa9c85aebd7c7219','cfb17070691845b2a8bf9eee5efeae67',1940,'伪田家庵区区长','任伪田家庵区区长，推行日伪保甲制度，协助日军清乡，抓捕抗日人士，强征劳工。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7e6d90bafb804945a5d593dc758b3429','bf9d7a2e9ecb4c04b87c7e2ba46557a2',1941,'伪淮南保安大队大队长','担任伪淮南保安大队长，率伪军配合日军扫荡田家庵周边抗日武装，残害百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('352d7db324d04e06bee1997851561abf','a50124f91e2647b9a6d6613897403d9b',1938,'伪田家庵商会会长','任伪商会会长，为日军筹措物资，垄断粮食和煤炭贸易，从中牟利，压迫商户。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cac1cef87beb4e0fa7d1efd17390ceb0','0e27c43ed7d146e2b2c5203a50a1785c',1940,'伪淮南矿警队队长','任伪矿警队长，负责镇压矿工罢工，为日军看护煤矿设施，抓捕抗日地下工作者。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('61e6844998d248aeac0dc40a9f5bf303','6a807220826141f4bcaa4eed9d3d01c8',1939,'伪田家庵税务局局长','任伪税务局长，强征各种苛捐杂税，为日伪政权搜刮民财，导致当地民生凋敝。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0a704e09dd114fcb9e609768416ff6d3','0d2d2045fc1d498dab9499e43abcb3de',1940,'伪安徽省省长、汪伪司法行政部长','汪伪政权要员，曾任伪安徽省省长等职，参与安徽沦陷区伪政权管理，协助日军征粮、清乡。；汪伪政权要员，曾任伪安徽省长，参与安徽沦陷区行政与警务控制，协助日军维持占领秩序。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a48e7e0ee0cf48d7b4d5ce561a70a7d3','70a05a799ab649dcb1e066740c197d1f',1938,'伪淮南地区维持会头目','抗战时期在淮南矿区一带活动，参与组织维持会，为日军掠夺淮南煤炭资源提供协助，维持地方伪秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b3da2d54e20c40ab970ad56d1cf72c0c','21853206ad2b417598d1af0b4b3a4782',1938,'伪军头目、淮南矿区伪自卫团首领','在淮南及谢家集一带组织伪军武装，配合日军守备矿区、镇压抗日活动，协助日军控制淮南煤矿。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a94c0de40494491a9810eea4d40f4985','f50cf011f8f842fc8d69caa402ffbf67',1938,'伪安徽省省长、汪伪内政部长','汪伪政权成员，曾任伪安徽省省长、伪内政部长，参与安徽沦陷区行政与治安伪化。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e50e031ce19142599b1e29b3348b06a6','83a92f4d9e894ddc95c8e9a351babc4f',1938,'伪安徽省政府主席','作为安徽沦陷区重要伪政权头目，长期在蚌埠等地主持伪省政，影响覆盖淮南地区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8e9d5ebbaa844f649633075c8c4d4c18','70a05a799ab649dcb1e066740c197d1f',1938,'伪滁县维持会会长、伪滁县县长','滁县本地士绅，日军占领滁县后出面组织维持会，后任伪滁县县长，为日军征发民夫、粮食，维持地方伪秩序。；滁县沦陷后组织维持会，投靠日军，后任伪滁县县长，为日军筹粮、派款、征夫，协助建立伪基层政权。；滁州本地士绅，日军侵占滁县后出面组织维持会，后任伪滁县县长，为日军征粮、派夫、维持治安，协助伪政权控制滁州城区及周边乡镇。；滁州本地士绅，日军侵占滁县后出面组织维持会，后任伪滁县县长，协助日军征粮、拉夫、维持治安，是滁州地区直接附逆的地方伪政权头目。；滁州本地士绅，日军侵占滁县后出面组织维持会，后任伪滁县县长，为日军征粮、征夫，协助维持沦陷区秩序，活动范围包括滁州及明光一带。；滁县本地士绅，日军侵占滁县后出面组织维持会，后任伪滁县县长。协助日军征粮、征夫、维持治安，镇压当地抗日活动，是滁州地区伪政权的主要代表人物。；滁县本地士绅，日军侵占滁县后出面组织维持会，后任伪滁县县长，为日军筹粮、征夫、维持地方治安，直接服务于滁州及琅琊地区的日伪统治。；滁县本地士绅，日军侵占滁县后出面组织维持会，后任伪滁县县长，为日军征粮、征夫、搜集情报，协助维持滁县及周边地区伪统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d927d3f621024378b47dd542cc15e7a3','124574ad0a424e7c806d5aa065dad2a1',1939,'伪滁县警察局局长','在滁县沦陷区担任伪警察头目，配合日军搜捕抗日人员，管理户籍与保甲，镇压民众反抗。；在滁县伪警察系统任职，配合日军搜捕抗日人员，维持沦陷区治安，压迫当地民众。；在滁县沦陷区担任伪警察头目，配合日军搜捕抗日人员、控制户籍与物资，维持伪统治秩序。；在滁县沦陷区担任伪警察头目，配合日军搜捕抗日人员，镇压民众反抗，其活动范围覆盖滁州城区及周边明光等地。；在滁县伪政权中担任警察头目，带领伪警察配合日军搜查、逮捕抗日人员，镇压当地民众反抗，维护日伪在滁县的治安统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('02adcc0b587e4265bfef62c33121ce9f','3cad5c7111df4e1d83aca1226d9895ad',1939,'伪滁县保安团团长','组建伪滁县保安团，配合日军扫荡周边抗日根据地，袭击新四军及地方抗日武装。；滁县本地人，组织伪保安团配合日军扫荡抗日根据地，参与清乡与情报搜集，活动范围包括滁县及南谯一带。；组织伪保安团，配合日军对滁县周边抗日游击区进行扫荡，强征民夫、修筑据点，协助日军控制滁县交通线。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0a472f60cb6b46e088a0cf72f4788bb9','62a6d6c8e7ab4bbfbc92c5b14abbde74',1940,'伪国民政府立法院长、伪安徽省长（短暂）','汪伪政权核心人物，虽主要活动于南京，但其伪政权统辖安徽，对安徽沦陷区行政有直接影响，曾参与对安徽的伪化统治决策。；汪伪政权二号人物，曾短期兼任伪安徽省长，其伪政权体系覆盖安徽全省，滁州、凤阳等地伪组织均受其节制，参与对安徽沦陷区的统治与掠夺。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d7d7972d7ff74f7593f452d05407aa2c','a2e4190c87b449e685d78c118a6801b5',1940,'伪国民政府财政部长、伪安徽省长（未到任）','汪伪政权要员，虽未实际到安徽任职，但其财政与物资统制政策覆盖安徽沦陷区，对滁州等地经济掠夺有间接责任。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d6409b00309247d4bf00c38f6e32d19c','807ca12d2dcb44989aababb17d52ca6d',1943,'伪淮海省保安处处长','在伪淮海省任职，负责保安与警察事务，参与对安徽北部沦陷区的控制与镇压。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b95f23fb6a834cbb9375a612f8c309a2','9a58a6d0ca124e4e8470270a43ef0a46',1940,'伪安徽省警务处处长','汪伪安徽省警务负责人，统管沦陷区警察系统，在滁州等地推行保甲连坐，搜捕抗日分子。；在伪安徽省警务系统任职，负责沦陷区警察事务，配合日军维持治安、搜捕抗日分子，滁州地区伪警察受其统辖。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e3e7fa20d5d643808f243ed7a522dd3b','ff7e839d04e04c73833b017b9cee9c9d',1940,'伪安徽省建设厅厅长','在安徽沦陷区配合日军进行资源开发与交通建设，实质服务于军事侵略与经济掠夺。；在安徽沦陷区协助日军修建军事设施、公路，掠夺资源，配合经济统制。','市县厅局级','hanjian');
