INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('97853677ada34c31927a10c08db41332','a2e4190c87b449e685d78c118a6801b5',1943,'汪伪行政院副院长、伪安徽省长（未久任）','汪伪核心人物，曾短暂兼任伪安徽省长，参与安徽沦陷区统治决策，为日军提供财政与物资支持。','省部级/大军区级要员','hanjian');
