INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5244438f110a4ff09483532ae532f3c1','124574ad0a424e7c806d5aa065dad2a1',1938,'伪凤阳县维持会会长','凤阳本地人，日军占领凤阳后组织维持会，替日军筹措粮秣、招募伪警，协助日军维持凤阳城区及临淮关一带的统治秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('74994963297d4089ba38474c4c8414e5','1408b8755b0b4bd1b0a999aede8f8aed',1940,'伪凤阳县县长','汪伪政权委任的凤阳县县长，在凤阳推行保甲制、征粮征丁，配合日军对凤阳山区抗日根据地进行封锁与扫荡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b98d9e2a37bf428eac48c75657f4b9e1','fefd7f9ddbac40469c751144d6cbd784',1940,'伪和平建国军将领、伪安徽省保安司令','原东北军将领，投敌后任伪军要职，在安徽指挥伪军配合日军作战，滁州、凤阳一带伪军及伪警察多受其节制，参与扫荡抗日武装。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('777bca28f3ea41ecbcb778ec2161c987','506df7877e6b4b589f0df223e5da77c6',1940,'伪湖北省长、伪安徽省长（未到任）','汪伪政权官员，曾被任命为伪安徽省长，其伪政权活动涉及安徽沦陷区，滁州、凤阳等地伪组织受其伪省政权体系影响。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('593acaa1dbfe4de69e9a1aa310a361b0','ff7e839d04e04c73833b017b9cee9c9d',1944,'伪安徽省长、伪司法行政部长','汪伪政权官员，曾任伪安徽省长，在安徽沦陷区推行亲日政策，滁州、凤阳等地在其伪省政权管辖下，协助日军维持统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('34300b295f8a43df93b63627db5d2c4c','fefd7f9ddbac40469c751144d6cbd784',1938,'伪和平救国军总司令','原东北军将领，投敌后任伪和平救国军总司令，其伪军部队在安徽北部及滁州一带配合日军作战与清乡。；华北伪军头目，配合日军扫荡抗日根据地，其活动与陕西宝鸡抗日后方形成对抗。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a658ab1ff595478b99e092c1058cbd5c','b4da42a8d0a3425abf10522d58c50b00',1938,'伪滁县商会会长','滁县本地商人，日军占领后出面组织伪商会，为日军筹粮筹款、统制物资，协助经济掠夺。','基层头目','hanjian');
