INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bc018d8c772d4c5da3712c368ac30467','903f92a867db4e77abb94dac1ad28168',1941,'伪和平救国军第一集团军总司令','原国民党苏鲁皖边区游击副总指挥，投敌后任伪军头目，其部队活动于苏中与安徽东部，滁州地区受其伪军影响。；原国民党军将领，率部投敌，所部伪军在苏中、苏北活动，与湖南无直接关联，但属汪伪军事体系一部分。；原国民党将领，投敌后任伪第一集团军总司令，在苏中配合日军扫荡。','省部级/大军区级要员','hanjian');
