INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2619aca9a0594a10a9178fccb7a337f2','46bdc67b9ef84e198720785e6442c8ce',1938,'伪滁县警察局局长','在滁县沦陷区担任伪警察头目，配合日军搜捕抗日人员、镇压民众，其活动范围涉及滁县与来安交界地区。','市县厅局级','hanjian');
