INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('81c46a6a92104cf2b98052d30d21e088','a2e4190c87b449e685d78c118a6801b5',1940,'伪南京国民政府财政部长、伪安徽省省长（名义）','汪伪政权核心人物，其财政与行政体系延伸至安徽沦陷区，滁州、来安等地伪政权在其总体框架下运作，参与对沦陷区民众的掠夺。','省部级/大军区级要员','hanjian');
