INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8d268ad95a284166a8504e3b84aa682a','7a45ac60b4054e90af960d52f84ea60a',1938,'伪来安县维持会会长','来安县士绅，日军占领来安后组织维持会，为日军筹集粮草、招募伪军，协助维持占领区秩序，后因内部争斗被日军撤换。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('54f2f4b26dba4e3885f4993268ac9ce2','af904f9433ee44168502ad9c407433fd',1939,'伪全椒县县长','全椒县人，抗战期间投敌，任伪全椒县县长，推行保甲制度，配合日军清乡，搜捕抗日分子，强征粮食与劳工。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8682bb6617a94b62a7871ddb537418bc','5b3187957ade4aa1a703516923e040a3',1938,'伪定远县维持会会长、伪定远县县长','定远县地方势力人物，日军侵占定远后率先投敌，组织维持会并任伪县长。协助日军修筑据点、封锁抗日根据地，参与对定远周边新四军活动区域的扫荡。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ee9aaa27474a45eaa542e240afbd4273','bcb37c4353544714b74a597dd730126a',1938,'伪凤阳县维持会会长','凤阳县商人，日军占领凤阳后出面组织维持会，为日军提供物资与情报，协助管理蚌埠至凤阳沿线交通，后因民愤被抗日武装处决。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5cf0b0de2add45368165402f9ec805bb','28b89fcbdbc0426a8e2b2bb23b572ec4',1940,'伪嘉山县县长','嘉山县（今明光市）人，抗战期间任伪嘉山县县长，配合日军控制津浦铁路沿线，征发民夫修筑工事，镇压当地抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4ed6fb2e11e44dac859b8dcb8b527277','f62754ef8d4a41f58e3b8f1b4bd4ab3a',1940,'伪安徽省省长、伪考试院院长','江西人，社会党创始人之一。抗战期间投靠汪伪政权，曾任伪安徽省省长、伪考试院院长，在安徽推行奴化教育与亲日宣传。；汪伪政权成员，曾任伪安徽省省长，在安徽推行奴化教育，协助日军进行思想控制。；汪伪政权成员，曾任伪安徽省省长，在安徽推行奴化教育，配合日军统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('feb270a09614497399aa15b4a298c14b','f50cf011f8f842fc8d69caa402ffbf67',1938,'伪安徽省省长、伪内政部长','福建人，早年参加辛亥革命，后投靠汪伪政权。曾任伪安徽省省长、伪内政部长，在安徽推行伪政权的行政与警察制度，配合日军清乡。；汪伪政权成员，曾任伪安徽省省长、伪内政部长。在安徽任内配合日军实施保甲、清乡与物资统制，滁州一带在其伪省政权管辖之下。','省部级/大军区级要员','hanjian');
