INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4cc63802834643a99bdf60161b4e3ba8','4cc5391bc78947fa9bf1a4b59e0f5371',1938,'伪芜湖县知事','在芜湖鸠江地区任伪职，为日军提供粮食和劳力，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('61c5dba369af43df86cdd5e44e05c417','f50cf011f8f842fc8d69caa402ffbf67',1938,'伪内政部长','伪维新政府内政部长，在安徽芜湖鸠江地区推行保甲制度，控制民众。；负责汪伪政权内部治安，推行保甲制度，在浙江包括绍兴、诸暨建立伪警察体系，协助日军搜捕抗日分子。；汪伪政权要员，曾参与对四川地方势力的策反。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ef92c8f2c04c4c35ace9bddbd435e82e','2da345b6c2e840b18cda3eba84087f6b',1940,'伪芜湖保安司令','在芜湖鸠江地区指挥伪保安队，配合日军“扫荡”，欺压百姓。','市县厅局级','hanjian');
