INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2f9ac61c5ff3476eb6fe87f37e3ab3e7','83a92f4d9e894ddc95c8e9a351babc4f',1938,'伪安徽省省长、蚌埠地区伪政权头目','原北洋军阀倪嗣冲之侄，日军占领蚌埠后投敌，任伪安徽省省长，积极推行日伪统治，镇压抗日力量，征收苛捐杂税，为日军提供物资和情报。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('615684a35cb44726804ea40ad2cca1fe','32c759d6dac640779934ea1d2fdd7353',1938,'伪蚌埠维持会会长、伪蚌埠市市长','日军占领蚌埠后率先组织维持会，任会长，后任伪市长，协助日军建立殖民秩序，强征民夫，掠夺粮食资源。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('72685d88e9a14c69a6b9a439eb9d79c9','3f934b1c263b4cd78c73d9700621e7bd',1939,'伪安徽省主席（驻蚌埠）','汪伪政权任命为安徽省主席，驻蚌埠，推行“清乡”运动，配合日军扫荡新四军，残害抗日军民。；任伪安徽省主席期间，在蚌埠设立伪省府，推行奴化教育，配合日军清乡。；任伪安徽省主席期间，在蚌埠设立伪省府，推行奴化教育，配合日军清乡扫荡。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('93055d80788b4c32aad1fac4d2c5bd25','ef112d84ad03423b9c9112a9594814bd',1939,'伪蚌埠警察局局长','负责蚌埠地区日伪治安，抓捕抗日地下工作者，协助日军进行大逮捕和屠杀，镇压民众反抗。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d8a22800aa0e48878be6d3f58ed1b15f','01e75c0937a04eabbd68975a5e901763',1938,'伪蚌埠商会会长','充当日伪经济汉奸，控制蚌埠商会，为日军征购粮食、棉花等战略物资，从中牟利，破坏抗日经济。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a22954b3006449049383cd267bf475d6','0df82cc71f7049c68890acafba8cd79a',1939,'伪蚌埠县知事（县长）','任伪县知事期间，推行保甲制度，强征壮丁，为日军修建碉堡和公路，强征民夫，迫害抗日家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4dc7274e1825407dbe10a5bbd2e03901','0e27c43ed7d146e2b2c5203a50a1785c',1940,'伪蚌埠特务机关情报员','为日军特务机关搜集新四军和抗日游击队情报，多次导致抗日人员被捕牺牲，民愤极大。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('eaf37e6a090e4591aae07424f4eeac41','67171d39b8e945a2b87917f1ac3c8dbd',1941,'伪蚌埠保安队副队长','率伪保安队配合日军“扫荡”怀远、凤阳等地，烧杀抢掠，杀害抗日群众，参与制造多起惨案。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9adcfaaa54464890bbd53ea8c801620e','bf9d7a2e9ecb4c04b87c7e2ba46557a2',1940,'伪安徽省教育厅长（驻蚌埠）','推行奴化教育，强制学校使用日伪教材，宣扬“中日亲善”，破坏抗日教育，迫害爱国师生。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('76d98833c5424bcdbd3f1ecf244f3f2b','d8c3493186d94718ad05072d725f4939',1939,'伪蚌埠税务局局长','为日伪政权强征各种捐税，包括“治安捐”“慰劳捐”，搜刮民财，导致百姓负担沉重，部分款项直接用于日军军费。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f9d92dfff6664976b69fcef9c44e4956','70a05a799ab649dcb1e066740c197d1f',1938,'伪蚌埠维持会会长、伪蚌埠商会会长','蚌埠沦陷后出面组织伪维持会，协助日军维持地方秩序、征发物资，并参与伪商会活动，是蚌埠当地重要的附逆人物。；蚌埠沦陷后出面组织伪维持会，协助日军维持地方秩序、征发物资与劳工，并利用商会身份为日军筹措军需，是蚌埠当地重要的附逆人物。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3971cec4cdfd479985f45e203ad3e9e8','21853206ad2b417598d1af0b4b3a4782',1938,'伪蚌埠警察局局长','在蚌埠沦陷期间担任伪警察头目，配合日军搜捕抗日人员、管制民众，维持伪政权在蚌埠城区的统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('26a74f7e1bce4a7ebea04c46e3be5324','ff7e839d04e04c73833b017b9cee9c9d',1944,'伪安徽省省长','汪伪政权官员，曾任伪安徽省省长，在安徽沦陷区维持伪政权统治，其辖区覆盖蚌埠、五河等地。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3d0b57396e3240a3b151bb805987ad56','e68cb3d58f924b60bb2287031548e44e',1938,'伪五河县维持会会长','五河沦陷期间，当地士绅或地痞出面组织伪维持会，协助日军征粮、派夫、维持治安，具体姓名在地方史料中记载较少，但五河县伪维持会确实存在并活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e5d2709c58d7461fa9cea7e5aa176d7b','0f8912e598a94b9ab51f29ab45c67025',1938,'伪五河县警察所所长','五河沦陷期间，伪警察所负责地方治安，配合日军搜捕抗日人员，压迫民众，具体姓名在现存史料中多不完整。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('30c705f269f0400591a9c8cfc324cfa8','6b186890888c4ef59afd6a82a310d3ad',1938,'伪蚌埠地区维持会头目（一说为伪凤阳县长）','蚌埠及凤阳一带沦陷后投敌，参与组织伪维持会与伪政权，为日军征集粮食、情报与民夫，活动范围覆盖蚌埠、固镇周边地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4bf8866bfa7e4b478c719c07c67cce20','62a6d6c8e7ab4bbfbc92c5b14abbde74',1940,'汪伪国民政府主席、伪行政院院长','汪伪政权最高头目之一，其伪政权统辖包括安徽在内的华中沦陷区，安徽蚌埠等地伪政权均受其节制，战后以汉奸罪被处决。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aa2cb32dab0441cdb436bc679fe3b432','a2e4190c87b449e685d78c118a6801b5',1940,'汪伪财政部部长、伪警政部部长','汪伪政权核心人物，掌控伪财政与警政，其政策推行至安徽沦陷区，蚌埠等地伪警察与税收机构受其系统管辖，战后被审判。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('eb660777768f461fb7e60eda54faaa64','28c69a91441d4439abc95701e2c6787a',1940,'汪伪工商部部长、伪浙江省省长','汪伪政权要员，参与伪政权经济统制政策制定，安徽沦陷区物资征发与配给受其影响，战后以汉奸罪处决。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2eb0e4842eb54440a4671181c78ad7dd','8f1dd12e548b4c4f866dd743c3377896',1938,'伪华北政务委员会委员长、伪安徽省省长（早期）','北洋政客，抗战期间投敌，曾任伪安徽省省长及伪华北政务委员会要职，在安徽沦陷区推行亲日政策，战后被处决。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6076c1fd028d4533a0d327162986eb41','f62754ef8d4a41f58e3b8f1b4bd4ab3a',1940,'汪伪考试院院长、伪安徽省省长（未到任或短任）','社会党人，抗战期间投靠汪伪，曾任伪考试院院长等职，与安徽伪政权有联系，战后以汉奸罪被判刑。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2946d05c485b4fc995442f9e0dc1f60b','c12dbd8a10f74ecbaedbb88848f6613b',1938,'伪蚌埠警察局局长','蚌埠沦陷期间伪警察机构负责人，协助日军搜捕抗日人员、管制居民、征收捐税，具体姓名史料记载不全，但该职务为当地重要附逆岗位。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4d05c1f42f3b4f05a3f182bdd1fd0eaa','e312f1975aec4a44892226314ba5be35',1938,'伪固镇维持会会长','固镇沦陷后组织伪维持会，为日军征集粮食、劳工与情报，维持地方伪秩序，具体姓名在地方史料中记载较少。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3dca0f31c23540eeb502f136c1c01e2d','83a92f4d9e894ddc95c8e9a351babc4f',1938,'伪安徽省省长、蚌埠绥靖公署主任','原北洋军阀倪嗣冲之侄，投靠日军后任伪安徽省省长，在蚌埠设立伪政权，推行奴化教育，协助日军清乡、征粮、抓捕抗日人士。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('19beb8da4b3b4d32846682305c722f60','6eb2c9d253354251aa717193cd7b6542',1938,'伪怀远县知事（县长）','日军占领怀远后出任伪县长，组织维持会，为日军提供粮食和民夫，镇压抗日活动，迫害抗日家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c0c6f5a1d1a8425ca0c1e45e9226a552','a6316b3bc957471fbe564178f5501fff',1938,'伪蚌埠维持会会长','日军侵占蚌埠初期，率先组织维持会，为日军带路、提供情报，协助建立伪警察局。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9438b8ece15644e0aed01e23d156e96a','ef112d84ad03423b9c9112a9594814bd',1938,'伪蚌埠商会会长','长期担任日伪控制下的商会会长，为日军筹措军饷、摊派捐款，垄断粮食贸易，从中牟利。；控制蚌埠商会，强迫商户向日军缴纳“慰劳金”，垄断粮食和食盐贸易，从中牟利。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fcedbb330d174bd6a1c55adabb15dbfb','0df82cc71f7049c68890acafba8cd79a',1939,'伪怀远县保安大队长','组织伪保安队，配合日军在怀远农村“清剿”新四军游击队，杀害多名抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e1a292dc6f2748a982b9a4833c04fb23','5e3f74433e5e4e55baf6202b20c4bcbd',1940,'伪怀远县警察局长','效忠日伪，在怀远城内设立多个检查站，搜捕抗日分子，严刑逼供，致多人死亡。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4859d623210c4d43a3ac5f7fa4df9cf0','85e8e57334fc480cbacf3863e9d22aee',1941,'伪蚌埠区行政督察专员','管辖蚌埠及周边县，推行“治安强化运动”，组织汉奸情报网，破坏中共地下组织。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3e5c882950ee44ffb68d73160799680f','bf9d7a2e9ecb4c04b87c7e2ba46557a2',1939,'伪怀远县教育科长','强制推行日语教育，篡改历史教材，宣传“中日亲善”，迫害爱国教师。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('64333497a34945aca7dcea3e4f56907a','83a92f4d9e894ddc95c8e9a351babc4f',1938,'伪安徽省省长、伪蚌埠绥靖公署主任','1938年投敌，任伪安徽省省长，在蚌埠设立伪政权，推行日伪统治，镇压抗日活动，征收苛捐杂税，协助日军进行经济掠夺和“清乡”行动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('83d0b3d019f946ecb98abb29aced8aa5','76223232c38241b996a8dcb3d7f9af4f',1939,'伪蚌埠特别区行政公署署长','1939年任伪蚌埠特别区行政公署署长，主持伪区政，配合日军建立保甲制度，强征劳工，搜刮粮食资敌，破坏抗日地下组织。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fc61b1a564194c29a01cd5e902606502','0d2d2045fc1d498dab9499e43abcb3de',1943,'伪安徽省省长（后期）','1943年任伪安徽省长，在蚌埠强化日伪统治，扩充伪保安队，协助日军掠夺淮上矿产和粮食，镇压学生和民众反日运动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8fb30dad5908458da41924af2ee736c8','4cc5391bc78947fa9bf1a4b59e0f5371',1940,'伪蚌埠市市长','1940年任伪蚌埠市长，主持市政，推行奴化教育，设立日语学校，强制民众悬挂日伪旗帜，配合日军“慰安妇”征用和物资统制。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5ce229e71ab14e669069f0a366f1dca2','07ff958e7f18410f864975f09234ac7e',1939,'伪特工总部蚌埠站负责人（兼）','虽主要活动于上海，但曾派员在蚌埠建立特工站，抓捕抗日志士，破坏地下交通线，策反国民党地方武装投敌。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('266334decd2f49c98f55932767659ce3','9910c48b9b394ffa8c73439ed0a473b0',1939,'伪特工总部顾问（涉及蚌埠活动）','作为汪伪特工头目，曾指导蚌埠特工行动，参与策划暗杀抗日人士，协助日军在淮上地区进行“肃正”和情报搜集。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f11fb6ddb6dc43bd940692356d725443','a2e4190c87b449e685d78c118a6801b5',1940,'伪行政院副院长（涉及蚌埠政务）','虽为中央伪职，但多次过问蚌埠伪政权财政和军事，批准在淮上设立伪税卡，截留抗日物资，支持伪军扩编。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1e0847b5bff94ee1b7bbaef9d977e0a5','28c69a91441d4439abc95701e2c6787a',1940,'伪安徽省财政厅长（驻蚌埠）','在蚌埠主持伪财政，发行伪币，强制兑换法币，垄断粮食贸易，为日军提供军费，导致淮上地区物价飞涨、民不聊生。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c1c1e875934141d2bef7bb195015eff0','fefd7f9ddbac40469c751144d6cbd784',1940,'伪蚌埠绥靖军司令','指挥伪绥靖军驻守蚌埠及淮上要地，多次配合日军“扫荡”新四军游击队，杀害抗日群众，烧毁村庄，抢夺牲畜。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a83967e6073c4de1bdcaa09963363048','63006a4879fb4f49ad97a1e88c8c5d69',1942,'伪第二方面军总司令（驻蚌埠地区）','率部投敌后驻防皖北，在淮上地区与日军联合进攻抗日武装，强征壮丁，修筑碉堡，破坏淮河两岸交通。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8f3cde9e8e93454989a92d97c8d2a1f0','848992e841c9488c8cdcf56cad9f079c',1943,'伪第四方面军总司令（活动于淮上）','所部曾驻扎蚌埠周边，参与“清剿”淮上抗日根据地，掠夺民间枪支，强迫农民种植鸦片，为日军提供战略物资。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d2c395ff6f5145bd80eac5b741dcdeda','5ec2ad124b2f429482b1a90a7f8d4a92',1943,'伪第五方面军总司令（涉及淮上防务）','投敌后其部队在皖北活动，曾派兵协助日军在蚌埠、怀远一带设卡盘查，搜捕抗日分子，并参与“三光”政策行动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7428952bc8d04e11922703a505bc8ee3','9f7b3ed9c76f4eea8211fd8ebc40a461',1943,'伪新编第五军军长（活动于淮上）','率部在淮上地区与日军合作，袭击新四军地方武装，破坏地下党组织，掠夺民间财物，并强迫民众为其修建工事。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('60d6939c7a2e467fbde83a6a0a7223cf','a06c0041e5294f2987f746729e510de9',1944,'伪淮海省保安司令（涉及蚌埠）','虽驻徐州，但曾派伪军南下蚌埠，协助日军镇压淮上抗日运动，抓捕进步青年，并参与对淮北盐场的控制。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7567b6e13e63401da8c70158b7419de5','ef676fac9bb24126bcc992f39c87c979',1940,'伪华北政务委员会治安总署督办（涉及蚌埠）','曾巡视蚌埠伪军，推动伪警政建设，在淮上地区推行“连坐保甲”，强化对民众的监视和镇压。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f29787697f1040d4b6b20bdbf1cbc6ca','da58b77853f14ce7b32f7f6b3305b75a',1940,'伪华北政务委员会委员长（涉及蚌埠）','作为华北伪政权首脑，曾批准在蚌埠设立伪军校，训练伪军骨干，并协调日军在淮上地区的“治安”行动。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8a2a5d754f1f4ae6a88aa5031702a012','8f1dd12e548b4c4f866dd743c3377896',1940,'伪华北政务委员会内政总署督办（涉及蚌埠）','参与策划在蚌埠推行“新民会”组织，进行奴化宣传，强迫民众参加反共集会，协助日军搜集淮上情报。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e62723009d6f404e92b957ddf51fa7c3','1bea23fefee9462fab8d11fc69a557b9',1938,'伪中国联合准备银行总裁（涉及蚌埠金融）','在蚌埠设立伪银行分行，发行联银券，掠夺淮上地区物资，导致通货膨胀，破坏当地经济，间接支持日军战争。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7e1d322515a142438ebf8bd3cee4ecd7','b5ba32ac9dee4113808d7f1e4475b119',1935,'伪冀东防共自治政府首脑（曾涉蚌埠活动）','虽主要活动于华北，但曾派代表至蚌埠联络伪政权，协助日军协调南北伪组织，推动“以华制华”策略。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('704a869bb906461b9a082a7d2c45bb6d','83a92f4d9e894ddc95c8e9a351babc4f',1938,'伪安徽省省长、蚌埠伪政权头目','曾任伪安徽省省长，在蚌埠及周边推行日伪统治，协助日军征粮、镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5038c0e9042348b997d3215f017a7617','db2bf5a5ebdc496eb35c1e8eb67f6efc',1938,'伪蚌埠维持会会长','日军占领蚌埠后出任维持会会长，组织伪政权，为日军提供物资和劳役。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7e2d1fe907fa4ae3b5e6362b45e84c5e','70a05a799ab649dcb1e066740c197d1f',1940,'伪蚌埠警察局局长','负责伪蚌埠警察系统，协助日军抓捕抗日分子，镇压民众反抗。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('775c75a7430341f8a6e253f20f6af707','8f1dd12e548b4c4f866dd743c3377896',1940,'伪华北政务委员会委员长（曾管辖蚌埠地区）','虽主要活动于北平，但作为伪华北政权首脑，对包括蚌埠在内的沦陷区伪政权负有领导责任，支持日军统治。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e80f31ef3a1d4d8197aeacccaac18dbf','a2e4190c87b449e685d78c118a6801b5',1940,'伪国民政府财政部长兼伪安徽省长（名义）','虽未常驻蚌埠，但作为汪伪政权核心人物，其伪安徽省长名义下辖蚌埠地区，推动伪化政策。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('945ef5a083544e4488941c3a611c7432','07ff958e7f18410f864975f09234ac7e',1941,'伪特工总部（76号）负责人（曾活动于蚌埠）','曾派特工至蚌埠建立情报站，暗杀抗日人士，协助日军维持治安。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f84ef83275194fd7842816d361cbaad5','9910c48b9b394ffa8c73439ed0a473b0',1941,'伪社会部长（曾巡视蚌埠）','巡视蚌埠期间督导伪政权强化保甲制度，推行“治安强化运动”。','省部级/大军区级要员','hanjian');
