INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fffd38c0d43b448682a98ede4ec0f029','9f7b3ed9c76f4eea8211fd8ebc40a461',1943,'伪第六方面军总司令','原国民党军将领，1943年投敌，任伪第六方面军总司令，所部在豫皖苏边区活动，其势力范围接近阜阳地区。；投敌后驻防苏北，配合日军作战；河南人，原国民党将领，抗战期间投靠日军，任伪第六方面军总司令，在华北地区进行伪化统治。','省部级/大军区级要员','hanjian');
