INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('40e39ed27c4c41af9028b42b3a57e590','f497ba24d7d243cbba884c7b57799408',1938,'伪马鞍山维持会副会长','协助日军强征劳工修建军事设施，克扣劳工工资，参与镇压工人罢工','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('afbdbca268f84f62907b184aada8accd','85ce9837114f45cf9bc3a4d5781f5284',NULL,'无','经查现存公开历史档案及地方志，马鞍山市花山区（含原当涂县部分区域）在抗日战争时期无明确记载的、经司法审判或党史部门认定的汉奸个人名录。该地区当时主要为游击区与日占区交错地带，日伪基层政权人员多为外地调任或临时委派，且战后档案散佚，未形成系统名单。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4cb3325de05d4acabb1b791db49b62a0','70a05a799ab649dcb1e066740c197d1f',1937,'伪当涂县维持会会长、伪当涂县知事','当涂沦陷后出面组织维持会，投靠日军，后任伪当涂县知事，为日军征粮、征夫、维持地方伪秩序，活动范围覆盖今马鞍山市区及当涂、雨山一带。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('edc1a4a7bae34bc9b5259927813eb1f2','3c3df055141e42ce8a5afc86cab01fc5',1938,'伪当涂县警察局局长','在伪当涂县政权中掌管警察武装，配合日军搜捕抗日人员、镇压民众，控制当涂及周边马鞍山、雨山地区治安。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3b9c9494b6324cf8951f29230707af2b','62a6d6c8e7ab4bbfbc92c5b14abbde74',1940,'汪伪国民政府立法院院长、伪上海市市长等','汪伪政权核心人物之一，虽主要在南京、上海活动，但其伪政权体系覆盖安徽，包括马鞍山、当涂一带的伪县政权均受其伪中央节制。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b9138c9254e7450da8341f46e652cb1f','a2e4190c87b449e685d78c118a6801b5',1940,'汪伪国民政府财政部长、伪警政部长等','汪伪政权核心成员，掌管伪财政与警政，其伪政权体系延伸至安徽各地，马鞍山、当涂地区伪组织亦在其系统之内。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6e380de04b054ce2b2587e641d4a80aa','d1abe59a5d664bf18b442130fc0478a1',1940,'汪伪国民政府宣传部长、伪安徽省长','汪伪宣传系统头目，后任伪安徽省长，在安徽推行奴化宣传与伪化统治，马鞍山、当涂地区伪教育、宣传机构受其节制。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('82bf58be9644406797101145fd8bc6fc','0d2d2045fc1d498dab9499e43abcb3de',1938,'汪伪国民政府司法行政部长、伪安徽省长','汪伪政权成员，曾任伪安徽省长，在安徽沦陷区推行伪政，其辖区包括当涂、马鞍山地区。；汪伪政权成员，活动于华中伪政权，其体系与广西周边伪政权有联系。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('50ab686618254ee18fd3ba5e2ea32c3a','b4da42a8d0a3425abf10522d58c50b00',1938,'伪当涂县保安团团长','在当涂、马鞍山一带组织伪保安武装，配合日军扫荡抗日根据地，征粮抓夫，残害民众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3e59a3af5bb64513a57093de84f52dc8','bacadba533394b3bb79fb5b9c5b66118',1943,'伪苏北绥靖公署主任、伪浙江省长','汪伪伪军高级将领，其伪军系统在苏皖边区活动，对马鞍山、当涂地区抗日力量构成威胁。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('735eb45b74b64363ba9f2e9e01514bf7','9aa78194c75d41ed93af1ccc8a1ab5c6',1939,'汪伪特工总部南京区区长','汪伪特工头目，其特工网络覆盖南京周边及安徽当涂、马鞍山地区，搜捕抗日人员，镇压民众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('534d9d2ac3a247ae8802e971be337c30','ed0d68ce0e0f4e40ba88774709d7fea6',1939,'汪伪特工总部南京区副区长','汪伪特工骨干，在南京及周边包括马鞍山、当涂一带进行特务活动，迫害抗日人士。；湖南人，汪伪特工成员，参与华中地区伪特工活动，与长沙有间接关联。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('386ed25e66dc48d3b5b8b71d0476c062','8a4a65c59beb4c3f9cabed02ac3f57ba',1939,'汪伪特工总部骨干','汪伪特工系统成员，活动于南京、安徽沿江地区，马鞍山、当涂一带有其特务活动痕迹。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ed0a63100bfb4f66b89af1898ed63c01','62a6d6c8e7ab4bbfbc92c5b14abbde74',1940,'伪国民政府代主席、立法院长','汪精卫死后继任伪国民政府代主席，继续推行附日政策，抗战胜利后被处决。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('db8ae5ba732045f2ac39665c1ee8fe0f','a2e4190c87b449e685d78c118a6801b5',1940,'伪财政部长、警政部长、上海市长','汪伪政权核心人物，掌握财政与特务系统，后兼任伪上海市长，抗战末期试图向重庆输诚，仍被处决。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('59f29ec5081544b9a1d2a2cfaaabd0ad','664d3df731bb4293bee63eea6deacb2d',1940,'伪外交部长、广东省长','汪伪政权要员，曾任伪外交部长，后任伪广东省长，抗战胜利后被处决。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('28538ec843514a9cb596334cd2f8ec53','8f1dd12e548b4c4f866dd743c3377896',1937,'伪华北政务委员会委员长、伪内政部长','北洋政客，抗战期间投敌，历任伪临时政府内政部长、伪华北政务委员会委员长等职，抗战胜利后被处决。；安徽合肥人，北洋旧官僚，抗战期间投敌，任伪华北政务委员会委员长、伪内政部长等职，推行奴化教育，1948年以汉奸罪被处决。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4b7c47a385b74820b68224cc7ece5cee','bbc7d2d2f1174918a3a12cc3ce766af2',1937,'伪北平维持会会长、伪北平市长','1937年北平沦陷后组织维持会，任会长，后任伪北平市长，积极为日军筹款筹粮。；安徽旌德人，北洋旧官僚，1937年北平沦陷后组织伪维持会，任会长，后任伪北平市长，协助日军维持占领秩序，1943年病死。；安徽旌德人，北洋政客，抗战期间投敌，1937年组织伪北平维持会并任会长，后任伪北平市长，协助日军维持华北占领区统治。；北平沦陷后组织维持会，协助日军维持占领秩序，其伪政权体系与华北各地包括陕西周边有联系。；日军占领北平后组织维持会，协助日军维持治安、征发物资。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0a12a10661eb477bb9392c4679fc1bd9','10b88f41fdee46778f29f60ae3d41741',1937,'伪天津市市长、伪华北政务委员会要员','抗战期间投敌，曾任伪天津市长，参与伪华北政务，战后被处决。；在华北伪政权中任要职，参与推行日军殖民政策，其影响覆盖华北包括山东德州、禹城一带的伪政权体系。；抗战期间投敌，任伪职于华北伪政权，属华北汉奸体系高层，对包括河南在内的华北伪政权有统辖关系。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('23ed7f59c07a4fc3a864ac1b21ccb5b6','5b2f7fb20693426f81f3853beb962949',1937,'伪天津市长','抗战期间任伪天津市长，配合日军统治，战后被处决。；华北伪政权要员，参与伪化统治，其体系与江西九江沦陷区的伪维持会有间接联系。；天津人，抗战期间投靠日军，任伪天津市长，在华北地区推行伪化统治。；伪政权要员，主要活动于天津，与重庆沙坪坝无直接关联。；在天津沦陷区任伪市长，协助日军征发物资、镇压抗日。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ae7f09c5d213410f9a4e8360a5842b06','8f1dd12e548b4c4f866dd743c3377896',1938,'伪安徽省长（早期）','曾短暂任伪安徽省长，后调任伪华北政务委员会。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d39f80c5f1ed49108fd57eb188ee14a8','5b3187957ade4aa1a703516923e040a3',1938,'伪黄山地区维持会会长','黄山地区（今黄山市）沦陷期间组织维持会，任会长，为日军征粮征夫。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c21e4a3dd8384ea8ae26d7e36719c60a','6d29eb6e14634c5e833d67a5aff346b5',1938,'伪屯溪维持会会长','屯溪（今黄山市屯溪区）沦陷期间任维持会会长，协助日军维持地方秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c47eeece2110408eb9b14766234e1e2d','00eb7352a7314fa2b7cb5b2039305773',1938,'伪歙县维持会会长','歙县沦陷期间任维持会会长，为日军筹款筹粮。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b01cb382cb7845b98a7abeda5d7c4b47','8933b319968240c9a59232fc882f6524',1938,'伪黟县维持会会长','黟县沦陷期间任维持会会长，配合日军统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b06c47dc02244f11aa42483b721ef53a','10ee16e4674f4d5e8f0f26179e60e4e2',1938,'伪休宁维持会会长','休宁沦陷期间任维持会会长，协助日军征粮。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('888e536c4a7341dea71f7d96a46c55d7','088ce6241b494d869c2ca19ed6ef0ef9',1938,'伪祁门维持会会长','祁门沦陷期间任维持会会长，为日军服务。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5a716e5a654d4deba8407460d7f33444','ebdef4a1fa0248b8b45eb4cf59ec98c7',1938,'伪太平县维持会会长','太平县（今黄山区）沦陷期间任维持会会长，配合日军统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6f81acbbbdab40a3b05171851a0a818c','10acba6111734062b531f2000d16c21e',1938,'伪石埭县维持会会长','石埭县（今石台县）沦陷期间任维持会会长，为日军征粮征夫。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('647785debd2744a8b523d18c152fe051','5c9df644dcb043b9b055ac4794dbd981',1938,'伪旌德县维持会会长','旌德县沦陷期间任维持会会长，协助日军维持地方。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9f9de2a17c0840cda96c9f62dd4bf071','a4cec86c8ec3479f9ea3f3cc9b95a536',1938,'伪绩溪县维持会会长','绩溪县沦陷期间任维持会会长，为日军服务。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a2a40daa75434054bce6552ea6ff3c07','a2e4190c87b449e685d78c118a6801b5',1938,'伪国民政府财政部长、警政部长、上海市长','湖南沅陵人，汪伪政权核心人物之一。曾任伪财政部长、警政部长等职，参与对安徽沦陷区的控制与掠夺，其伪政权体系延伸至黄山、休宁一带。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5eb5fed10b2543dfb4f7aeefa8519fca','62a6d6c8e7ab4bbfbc92c5b14abbde74',1938,'伪国民政府立法院长、行政院长、代主席','广东乳源人，汪伪政权重要头目。汪精卫死后任伪国民政府代主席、行政院长，继续推行附日政策，其伪政权对安徽沦陷区包括黄山、休宁地区实施统治。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('96dc97413d3d47499c12f189eca35cb2','d1abe59a5d664bf18b442130fc0478a1',1940,'伪安徽省长、伪宣传部长','广东信宜人，汪伪政权宣传部长，后任伪安徽省长。在安徽沦陷区推行奴化宣传与伪化统治，涉及黄山、休宁地区。；广东信宜人，汪伪政权宣传系统负责人，后任伪安徽省长，在安徽进行亲日宣传和伪化教育。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ac45e30d0f76442490dc3689de2c674a','5b3187957ade4aa1a703516923e040a3',1938,'伪休宁县维持会会长','休宁本地人，抗战期间组织伪维持会，任会长，为日军征集物资、情报，协助日军维持占领区秩序，是休宁地区直接附逆者。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('839e2e8785144dd3b7685ef691dba0ca','31b24af7cf4143bbb4e166ca9042e96e',1940,'伪休宁县知事','休宁人，汪伪政权委任的伪休宁县知事，在休宁推行伪化行政，征粮征税，配合日军统治。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1aae073359b34a40838ddda310cfeac8','0513822bb41d41a9855e3b3f071a7d81',1938,'伪黄山地区维持会会长','黄山地区（今黄山市）人，抗战期间任伪维持会会长，协助日军管理黄山风景区及周边地区，为日军提供向导与物资。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5e9e19c89e5c41489e6b316cb5618567','5ad11aac98e446d8a0e0dc41bfa7b7a3',1938,'伪屯溪维持会会长','屯溪（今黄山市屯溪区）人，任伪屯溪维持会会长，在屯溪及周边休宁等地为日军服务，维持伪秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('317e0f69575d4980afa2a32269741296','848992e841c9488c8cdcf56cad9f079c',1938,'伪第四方面军总司令、伪豫东剿共军总司令','原国民党军将领，投敌后任伪第四方面军总司令，活动于豫东、皖北一带，对安徽沦陷区有影响，间接涉及黄山、休宁地区。；在豫东、皖北地区组织伪军，配合日军进攻抗日根据地，其活动范围接近陕西。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('21e2b6ccfa874949b434cc2340d4b92b','e1badd3fe14246acb4a3d2bf765b2db2',1940,'伪华北政务委员会常委、伪安徽省长','山西人，汪伪政权官员。曾任伪安徽省长，在安徽沦陷区实施伪化统治，涉及黄山、休宁地区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dc42bd49c4604c2a953b25e34e245fc2','a2e4190c87b449e685d78c118a6801b5',1938,'伪国民政府行政院副院长、伪上海市长','湖南沅陵人，汪伪政权核心人物之一，参与筹建伪政权，其伪政权体系延伸至安徽各地，对屯溪等皖南地区有间接统治影响。；安徽绩溪人，属徽州地域，随汪精卫投敌，任伪政权要职，参与伪政权财政、特务与对日交涉，是汪伪政权核心人物之一。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c478b0f4ef364e0e9f9707d0a1f9dec0','5b3187957ade4aa1a703516923e040a3',1938,'伪屯溪维持会会长','屯溪本地士绅，抗战期间出面组织伪维持会，协助日军维持屯溪地区秩序，为日军筹粮筹款，是屯溪地区主要的附逆人物。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('51854a7e33464f81bb818c5be794aecd','aa5c1bdd7fa24a13896802e01008592d',1938,'伪黄山地区维持会负责人','黄山地区地方人物，抗战期间投靠日军，组织伪维持会，协助日军管理黄山周边乡镇，征收赋税，镇压抗日活动。','基层维持会/地方自治头目','hanjian');
