INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('38e59498ddef4e5995079e7dbf59c04b','9910c48b9b394ffa8c73439ed0a473b0',1939,'汪伪特工总部主任、伪社会部部长','汪伪特务头目，其特工组织在安徽沦陷区活动，包括黄山周边地区，参与镇压抗日力量、诱降国民党军政人员，是安徽地区伪特工体系的重要人物。；湖南常德人，汪伪特工头目，其特务活动涉及湖南，在沦陷区抓捕抗日人员。；汪伪特务头目，在沦陷区进行恐怖统治，迫害抗日志士。','省部级/大军区级要员','hanjian');
