INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cfabce1a0ed14233b6fcc3875ec29751','08cf2daf57624bc0bd6648341fc817bd',1940,'伪垦利县警备队队长','率伪警备队在垦利、利津边境地区活动，协助日军封锁黄河口一带，盘查、抓捕抗日人员，勒索群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('36e9271c9b004104b0b2a585d15aae0c','7556fd1f8b1f4180927b6356b214e742',1938,'国民党顽固派、后投敌任伪山东保安第十五旅旅长','长期在寿光、广饶、利津、垦利一带活动，后与日军勾结，进攻清河区抗日根据地，残害抗日军民，是山东北部著名附逆武装头目。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7c286bc0943d4f9c82751eb78dbc607e','cac97cc283e049a9b56c0655c19af05f',1939,'伪广饶县县长','在广饶及邻近的东营、垦利地区建立伪政权，配合日军扫荡，征发民夫、粮食，镇压抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('73817a32135d4797817bdb2cf09d388d','f1509202ed604b49b953b662a140282d',1940,'伪山东保安第二十七旅旅长','在广饶、博兴、利津、垦利一带投敌，配合日军进攻八路军清河军区，烧杀抢掠，破坏抗日根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3b4d53803201422b8bd6b18be5276dac','b5686f56ef7f415f84d1947ee4719aea',1938,'伪利津县维持会会长','在利津及黄河口附近组织维持会，迎接日军，筹粮筹款，协助建立伪政权，压迫当地民众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9afaae7e269e40299e637709e7dd3132','1b07d61c8eca4d97a405f1cf0eb52987',1940,'伪利津县县长','在利津、垦利交界地区推行伪政，配合日军对垦区抗日根据地实行经济封锁和军事扫荡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('eed373c7430b4b058046b6a02d2880d7','a52d82089a804187b2198be492c8000a',1938,'投敌后任伪军头目','曾率部在山东北部活动，后公开投敌，其势力范围一度涉及鲁北东营周边，配合日军进攻抗日武装。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fddadfe819a74c69923e54a8bc3a968b','fabd450d8480433fb1634895d3c43510',1938,'伪山东保安第二师师长','在鲁北、胶东一带投敌，所部在广饶、寿光、利津、垦利周边配合日军扫荡，残害抗日军民。；在鲁东南投敌，其部活动于临沂、临沭、莒县一带，配合日军扫荡，残害百姓，后于1945年被八路军击溃。；投敌后任伪军师长，活动于山东诸城、临沂、沂水一带，配合日军扫荡，残害抗日军民。；在胶东地区投靠日军，配合日军扫荡抗日根据地，其势力范围涉及威海周边地区。；山东伪军头目之一，活动于胶东地区，与威海日伪政权有联系，参与对威海、文登、荣成一带的扫荡。；投敌后率伪军在山东胶东地区活动，配合日军扫荡，曾波及威海、文登周边，镇压抗日群众。；山东汉奸，活动于泰安、新泰一带，配合日军扫荡，残害百姓。；在山东诸城、济南周边地区为日军效力，参与清乡与扫荡。；率伪军在鲁北地区配合日军扫荡，活动范围包括商河周边。；山东著名伪军头目，活动于鲁中、鲁南及济南外围，配合日军扫荡，残害抗日军民。；在山东境内为日军效力，其活动范围包括济南周边，参与清乡。；在山东境内依附日军，参与扫荡，活动范围涉及济南周边地区。；活动于鲁中、济南周边，配合日军进攻抗日武装。；投靠日军后任伪军师长，在鲁中、鲁南及淄博邻近地区活动，参与扫荡抗日根据地，残害百姓。；投敌后任伪军师长，活动于诸城、潍县、寒亭南部一带，配合日军扫荡，残害抗日军民。；在山东胶东地区组织伪军，活动于烟台、莱州周边，配合日军清乡扫荡。；在山东诸城、菏泽等地活动，投敌后配合日军进攻抗日根据地，抢粮抓丁，残害百姓。；盘踞山东胶东地区，后投靠日军，配合日军进攻即墨、平度、莱阳等地抗日根据地。；在山东诸城、胶县一带组织伪军，协助日军维持统治。；在山东东部包括青岛、崂山一带组织伪军，袭击抗日游击队。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b8e193da1d694fdc94e26b275e649ef7','391e57c9623843dea409722f3754920e',1939,'伪广饶县公署知事、伪广饶县保安团团长','抗日战争时期投靠日军，出任伪广饶县公署知事，组建伪保安团配合日军清乡、扫荡，镇压广饶一带抗日军民，强征粮款，推行保甲连坐。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9b54664f63954da1965e612852bf1da7','7556fd1f8b1f4180927b6356b214e742',1938,'伪山东省保安第十五旅旅长、伪寿光/广饶一带地方武装头目','长期在寿光、广饶、益都一带活动，抗战中后期与日军勾结，配合日军进攻清河区抗日根据地，残害抗日群众，横征暴敛。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1a71e318bc24487297e72bb9639317c2','d6d76958ee164d75a29297b85ac0cbe2',1938,'伪山东省鲁北道道尹、伪军头目','在鲁北地区依附日军，负责伪政权与伪军事务，其势力范围涉及东营、广饶周边，配合日军对清河平原进行扫荡和治安强化运动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b6d75ca14a9740b9a8d4ddd01cdbd42a','b1e2c050fe6449ff84cb46f64f24d30e',1938,'伪山东省第十三区行政督察专员兼保安司令、伪军头目','在胶东及山东多地反复投靠日伪，配合日军进攻抗日根据地；其部曾在山东北部活动，对包括广饶周边在内的抗日力量造成危害。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6732b649ff0540088c85f83b6790de8a','f1509202ed604b49b953b662a140282d',1938,'伪广饶县维持会会长','日军侵占广饶后出面组织维持会，为日军筹粮筹款、拉夫修路，协助建立伪基层政权，压迫当地民众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('463ebc3c92774f5484dd4de4a3eb1b08','1b07d61c8eca4d97a405f1cf0eb52987',1940,'伪广饶县新民会指导部职员、教育附逆者','在广饶推行日伪奴化教育，参与新民会宣传，协助日军控制学校和社会团体，向民众灌输“大东亚共荣”思想。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('23c8ab05266344ba823c835dcacc4d41','69acc0909f544a318cf03fc20bac4c6a',1941,'伪东营地区保甲长、情报员','在东营、广饶交界一带担任伪保甲长，为日军搜集抗日武装情报，带领日伪军抓捕抗日干部和群众，催缴捐税。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6946064e3f8540068204d7461d7ccd64','7556fd1f8b1f4180927b6356b214e742',1938,'伪山东省保安第三师师长、伪山东第十四行政督察区专员','盘踞寿光、广饶、博兴一带，后公开投敌，配合日军对清河区、渤海区抗日根据地扫荡，其势力范围覆盖今东营市广饶、利津、河口周边地区。；山东寿光人，抗战期间长期在鲁北、鲁中一带活动，后投靠日军，所部被编为伪军，配合日军对清河区、渤海区抗日根据地进行扫荡，其势力范围涉及淄博北部及高青周边地区。；山东寿光人，抗战期间率部投敌，所部盘踞寿光、广饶、博兴、滨县一带，配合日军扫荡清河抗日根据地，捕杀抗日军民，横征暴敛。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0f82942152844e4bbbd60369d5ef8825','391e57c9623843dea409722f3754920e',1938,'伪山东保安第十六旅旅长、伪广饶县县长','在广饶、利津、沾化沿海一带活动，后投靠日军，任伪职，配合日伪军进攻清河区抗日根据地，活动区域邻近今东营市河口区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cb776e37e8e84910a27bbd6a3baba4a7','08cf2daf57624bc0bd6648341fc817bd',1938,'伪山东保安第九旅旅长','在利津、沾化、滨县沿海地区活动，后投敌任伪军头目，配合日军扫荡渤海区抗日根据地，其活动范围覆盖今东营市河口区及周边沿海地带。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('173afb36f06c4b21a4d2ab2ff6651d2b','f1509202ed604b49b953b662a140282d',1938,'伪山东保安第二十七旅旅长、伪临淄县县长','在临淄、广饶、博兴一带活动，后公开投敌，任伪军头目，配合日军对清河区抗日根据地进行扫荡，活动范围涉及今东营市南部地区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('69eb430a2d4d4c5baeb7b3cecc43109c','bb6e37179eee41be9dca57cf4bae06d1',1939,'伪山东保安第三师副师长、伪广饶县县长','在广饶、寿光一带依附张景月部，后任伪职，配合日军进攻清河区抗日根据地，活动区域邻近今东营市河口区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('329d80e63b3e434fa74fd98bb391a2bf','d6d76958ee164d75a29297b85ac0cbe2',1938,'伪山东省渤海道道尹、伪山东保安总队司令','在渤海沿海地区活动，曾任伪渤海道道尹，管辖范围包括利津、沾化、广饶等县，配合日军对渤海区抗日根据地进行扫荡，其辖区覆盖今东营市河口区一带。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1a71db385c57487db3a424e66da0ee82','0806580d2c7a479e84a3ccdbd55c1bd4',1938,'伪山东保安第二旅旅长、伪沾化县县长','在沾化、利津沿海一带活动，后投敌任伪职，配合日军扫荡渤海区抗日根据地，活动范围邻近今东营市河口区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b885d51dbdd548cda8b48ae5d0f7a3a8','1fdb3eb9cc184432bdddd5b7f493b0fd',1938,'伪利津县维持会会长','在利津县任伪维持会会长，协助日军维持地方治安、征粮征夫，其活动区域包括今东营市利津县及河口区周边。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bd2e931e836b4ab7bf5c79a722da8317','c692801ac2c3420b89c5234722019808',1939,'伪利津县县长','在利津县任伪县长，配合日军推行保甲制度、征粮征夫，其辖区包括今东营市利津县及河口区一带。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('396e491ee7884e34b562e7e8f3c59ad3','ff36e423126d40dd8a1a47689baf8ffe',1938,'伪广饶县维持会会长','在广饶县任伪维持会会长，协助日军维持地方统治、征粮征夫，其活动区域涉及今东营市广饶县及周边地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b402e094871f45aeb1154769291f5c52','1f8eba63c91140febd4802304d747e35',1938,'伪临沂县维持会会长、伪临沂县知事','日军侵占临沂后出面组织维持会，后任伪临沂县知事，协助日军推行保甲、征粮、抓丁，镇压抗日群众。；抗战期间投靠日军，在临沂县城组织维持会，后任伪临沂县知事，协助日军征粮、征夫、清乡，镇压抗日群众。；日军侵占临沂后投敌，组织伪维持会，后任伪临沂县知事，协助日军推行保甲连坐、征粮抓丁，镇压抗日群众。；抗战期间投靠日军，在临沂县城组织维持会，后任伪临沂县知事，协助日军征粮、派夫、清乡，镇压抗日群众。；日军侵占临沂后出面组织维持会，充任伪临沂县知事，协助日军推行保甲、征粮、抓丁，镇压抗日群众。；日军侵占临沂后出面组织维持会，后任伪临沂县知事，协助日军推行保甲连坐、征粮派夫，镇压抗日群众，其势力范围覆盖临沂城区及罗庄一带。；抗战期间投靠日军，在临沂地区组织伪维持会，后任伪临沂县知事，协助日军推行保甲、征粮、抓丁，镇压抗日群众。；临沂沦陷后投靠日军，组织伪维持会，后任伪临沂县知事，协助日军征粮、派夫、清乡，镇压抗日群众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a798702ea4bb4190860aacd3f84e7296','b1e2c050fe6449ff84cb46f64f24d30e',1938,'伪剿共军暂编第十二师师长、伪莱阳/胶东地区伪军头目','原国民党军将领，后投靠日军，在胶东及鲁南边缘地区配合日军扫荡，残害抗日军民，与临沂周边伪军有联络配合。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('894ecf7ebb2d4ca9836eb995366131b4','177c17b9b440453fa41ed47b9ebbd502',1937,'伪和平救国军第三方面军司令、土匪武装头目','长期在鲁南、临沂、费县、蒙阴一带活动，投靠日军后任伪军头目，烧杀抢掠，配合日军进攻抗日根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('959f56d241834eb0afb696e528b45169','3fcfa73a208547969c91611154e4f66e',1938,'伪临沂地区地方武装头目、后任伪职','在临沂及鲁南地区反复于抗日与附逆之间，后期部分部属投伪，配合日军维持地方伪秩序。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aea46957cb1749dcb54bb0c39c739da6','448d0f7cee64452499a7d23f73c33bbb',1938,'伪青岛特别市市长、伪鲁东地区要员','虽主要在青岛，但与鲁南、临沂伪政权系统有联系，协助日军推行伪化统治和经济掠夺。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c88d08d7dc0a4bf4b2c5104b05cad284','4ae43298968148da833d28b2f13c858d',1937,'伪山东省省长','伪山东省最高行政头目，统辖包括临沂在内的各道县伪政权，推行保甲、征粮、奴化教育，配合日军扫荡。；伪山东省最高行政长官，推行日军殖民政策，在临沂、费县等地设立伪政权，征粮征兵，镇压抗日活动。；伪山东省最高行政长官，推行日军殖民统治政策，其政令覆盖威海、乳山地区，协助日军征粮、抓丁。；任伪山东省长期间，推行日军殖民政策，协助日军在山东各地包括威海地区征粮、征丁。；继马良后任伪山东省省长，继续推行治安强化运动，在威海、文登地区建立伪政权、伪军和保甲制度，配合日军扫荡。；继任伪山东省长，继续推行日军在山东的伪化统治，其政令覆盖威海环翠一带。；继马良后任伪山东省省长，配合日军清乡、治安强化运动，镇压抗日力量。；继马良之后任伪山东省省长，继续为日军服务，推行保甲、治安强化运动，其伪政权统治范围覆盖德州、临邑等地。；继马良后任伪山东省省长，继续为日军统治山东服务，推行保甲、征粮、征工等政策，配合日伪清乡与治安强化运动。；作为山东伪政权最高头目，推行日军侵略政策，在德州、宁津等地强化伪政权，征发劳工、粮食，镇压抗日力量。；继马良后任伪山东省省长，继续为日军统治服务，推行伪政权的征粮、征丁和治安强化政策，协助日军控制山东沦陷区。；继马良之后任伪山东省省长，继续为日军统治山东服务，推行保甲、征粮、抓丁等政策，配合日军扫荡抗日根据地。；继马良之后任伪山东省省长，继续为日军统治山东服务，推行伪政权的征粮、征丁和治安强化运动。；继马良之后任伪山东省省长，继续为日军统治山东服务，在包括德州在内的山东沦陷区推行伪政令，配合日军扫荡与掠夺。；继马良后任伪省长，配合日军在山东包括德州地区实施治安强化运动。；继马良之后任伪山东省省长，继续为日军统治山东服务，配合日军在德州、禹城等地的征粮、清乡和治安强化运动。；继马良之后任伪山东省省长，依附日军，推行治安强化运动，配合日伪清乡、扫荡。；继马良之后任伪山东省省长，依附日军，协助推行治安强化运动，镇压山东抗日军民。；曾任伪山东省省长，配合日军在山东各地推行伪化统治，参与组织伪政权、伪军和治安强化运动，对山东民众进行镇压与掠夺。；原为北洋及国民政府官员，抗战爆发后附逆，任伪山东省省长，配合日军在山东实施治安强化运动，推行保甲连坐，镇压抗日根据地。；抗战时期任伪山东省省长，依附日军，推行伪政，配合日军对山东抗日根据地进行扫荡和经济掠夺。；曾任伪山东省省长，协助日军维持山东沦陷区统治，推行保甲、征粮、清乡等政策。；曾任伪山东省省长，配合日军在山东推行治安强化运动，组织伪政权和伪军，镇压抗日根据地。；继马良后任伪山东省省长，驻济南，配合日军实施治安强化运动，镇压抗日力量。；继马良后任伪山东省省长，驻济南，推行日军政令，镇压抗日活动。；继马良后任伪山东省省长，驻济南，配合日军清乡、掠夺物资、强征劳工，推行奴化教育。；继马良后任伪山东省省长，配合日军清乡、掠夺物资，推行奴化教育。；长期在济南主持伪山东省政权，推行日军政令，镇压抗日活动，为日军搜刮粮棉、矿产与劳工。；接替马良任伪山东省省长，驻济南，配合日军实施治安强化运动，镇压抗日力量。；继马良后任伪山东省省长，驻济南，协助日军征粮、征丁，推行奴化教育。；继马良后任伪山东省长，驻济南，协助日军推行治安强化运动，搜刮物资，镇压抗日根据地。；继马良后任伪山东省省长，驻济南，推行日军政令，镇压抗日活动，为伪政权核心人物。；继马良后任伪山东省省长，驻济南，推行日军政令，镇压抗日活动，为山东伪政权核心人物。；继马良后任伪山东省省长，驻济南，配合日军清乡、治安强化运动，迫害抗日军民。；继马良后任伪山东省省长，驻济南，配合日军清乡、治安强化运动。；继马良后任伪山东省长，配合日军在山东包括济宁地区的扫荡、征粮和治安强化运动。；作为山东伪政权最高头目，推行日军政策，在济宁等地设伪道、县政权，征粮征兵，镇压抗日活动。；曾任伪山东省公署省长，配合日军在山东各地推行伪化政权、保甲连坐与物资统制，为日军侵华提供行政支持。；原为北洋官员，抗战期间附逆，任伪山东省省长，配合日军在山东各地推行伪化统治，参与清乡、治安强化运动。；曾任伪山东省省长，配合日军在山东推行伪化统治，搜刮物资，镇压抗日活动。；山东伪政权最高头目之一，协助日军统治山东，包括济宁地区，推行保甲、征粮、扫荡等。；山东省伪政权最高头目，在山东包括济宁、泗水地区推行保甲、治安强化运动，为日军征粮征丁。；作为山东伪政权最高头目，推行日军殖民政策，督令各道县征粮、征兵、清乡，镇压山东抗日力量。；山东济宁人，抗战期间投敌，1938年后历任伪山东省公署省长、伪山东省政府省长，协助日军推行保甲、征粮、清乡等政策。；作为山东伪政权最高头目，推行日军政策，督令各道县征粮、清乡，配合日军扫荡鲁西南抗日根据地。；曾任伪山东省公署省长，推行日伪统治，在山东包括淄博地区实施保甲、征粮、抓丁等政策。；曾任伪山东省省长，协助日军维持山东沦陷区统治，推行治安强化运动。；原为北洋政府官员，1938年投敌，任伪山东省省长，推行日伪统治，配合日军在山东包括淄博地区的清乡、扫荡和经济掠夺。；原为北洋及国民政府官员，抗战爆发后附逆，任伪山东省省长，配合日军在山东各地推行伪化统治，包括淄博地区。；原为山东省政府官员，1938年投敌，任伪山东省公署省长，推行伪化统治，协助日军征粮、征丁，其政令覆盖淄博、张店地区。；1938年后任伪山东省公署省长，推行日伪殖民统治，组织伪政权、伪军配合日军扫荡山东抗日根据地，其伪省政权管辖范围覆盖淄博、桓台等地。；1938年任伪山东省公署省长，推行日伪统治，在山东各地包括淄博、沂源地区建立伪政权、维持会，征发劳工、掠夺资源。；作为伪山东省最高行政长官，推行日军殖民统治，在鲁北地区包括惠民、滨州一带实施保甲制、治安强化运动，征发劳工，镇压抗日。；任伪山东省省长，主持伪省政，协助日军统治山东，推行保甲、征粮、奴化教育，涉及潍坊、临朐地区。；原为山东省政府官员，投日后任伪山东省省长，推行日军殖民统治政策，在潍县、坊子等地设立伪政权机构、征发劳工与粮食。；继马良之后任伪山东省省长，协助日军维持山东沦陷区统治，推行治安强化运动，镇压抗日力量。；伪山东省政府首脑，推行日伪政令，组织伪军、伪警察和保甲制度，在山东全省包括潍坊、昌邑地区实施征粮、征丁和镇压抗日活动。；继马良任伪山东省长，推行日军政策，统治包括潍县在内的山东地区。；原北洋政府官员，抗战期间出任伪山东省省长，在山东全省推行日伪政策，为日军筹粮筹款，镇压抗日活动，其政令下达至潍坊、诸城各县。；继马良之后任伪山东省省长，协助日军征粮、征丁，推行治安强化运动，镇压山东抗日根据地。；继马良后任伪山东省省长，协助日军统治山东，推行经济掠夺和奴化教育。；抗战时期出任伪山东省省长，为日军在山东推行殖民统治，组织伪政权、伪军，配合日军扫荡抗日根据地，烟台、栖霞等地均在其伪政权管辖范围内。；任伪山东省省长期间，推行日伪政令，支持胶东地区伪政权和伪军建设，对烟台、海阳等地抗日活动进行镇压。；抗战时期任伪山东省省长，主持山东伪政权，推行日军殖民统治，其政令覆盖烟台、福山等山东各地。；原北洋政府官员，抗战期间投敌任伪山东省省长，在山东全省推行伪化统治，包括烟台、芝罘地区，协助日军征粮、征丁。；山东沦陷后历任伪山东省公署省长，推行日军殖民统治政策，在山东全省包括聊城、东昌府地区征粮抓丁、清乡扫荡。；继任伪山东省长，继续在山东各地包括聊城、东阿推行伪政，支援日军作战。；原山东旧官僚，投靠日军后历任伪山东省财政厅长、伪省长，推行日伪政策，搜刮民财，镇压抗日力量，其统治范围包括聊城、临清地区。；任伪山东省长期间，在聊城、冠县等鲁西地区推行伪化统治，征粮征兵，配合日军扫荡。；伪山东省长，直接管辖包括聊城、茌平在内的山东沦陷区，推行保甲、征粮、奴化教育，配合日军扫荡抗日根据地。；伪山东省最高行政长官，主持山东伪政权，推行保甲连坐、征粮征夫，其辖区包括聊城、莘县，直接为日军在鲁西北的统治服务。；作为山东伪政权最高头目，推行日军政策，征发劳工、粮食，配合扫荡，统辖包括聊城、阳谷在内的伪政权。；接替马良任伪山东省长，配合日军“治安强化运动”，在聊城、高唐等地推行保甲连坐、掠夺物资，镇压抗日力量。；抗日战争时期出任伪山东省省长，全面推行日军殖民统治，建立各级伪政权，征粮征丁，配合日军对山东各抗日根据地进行扫荡，是山东地区最大的汉奸头目之一。；抗战期间任伪山东省省长，统领全省伪政权，在菏泽、定陶等鲁西地区推行保甲、清乡、奴化教育，为日军提供物资与人力支持。；抗战期间任伪山东省省长，统辖全省伪政权，包括菏泽、巨野等地，推行日军侵略政策，征粮征丁。；原为北洋政府官员，抗战期间投敌，任伪山东省省长，推行奴化教育，配合日军在山东各地包括菏泽、成武一带征粮派款、清乡扫荡。；作为山东伪政权最高头目，推行日军殖民政策，统辖包括菏泽、曹县在内的伪政权，征粮征丁，镇压抗日运动。；山东人，抗战期间出任伪山东省省长，为日军在山东推行伪化统治，建立各级伪政权，征发粮食劳工，配合日军扫荡抗日根据地，其统治范围覆盖菏泽地区。；原为北洋政府官员，抗战期间投敌，任伪山东省省长，推行日军殖民统治政策，其伪政权覆盖菏泽等鲁西地区。；继马良后任伪山东省长，继续在山东包括菏泽地区推行伪政权统治，配合日军作战。；抗战期间出任伪山东省省长，统辖全省伪政权，在山东包括菏泽、郓城地区推行日军殖民政策，征粮征丁、镇压抗日力量。；任伪山东省省长期间，在全省推行保甲制度、治安强化运动，为日军征发劳工、粮食，其政令覆盖菏泽、鄄城地区。；出任伪山东省省长，推行日伪政策，协助日军在山东全省包括青岛、即墨地区进行清乡、征粮和镇压抗日力量。；长期任伪山东省长，配合日军在山东推行治安强化运动，掠夺资源。；任伪山东省长期间，配合日军在山东各地包括青岛、崂山推行治安强化运动，征发劳工，镇压抗日武装。；继马良后任伪山东省省长，配合日军扫荡抗日根据地，推行治安强化运动，掠夺山东资源。；继马良等之后任伪山东省长，配合日军在山东进行扫荡、清乡和经济掠夺，是山东伪政权核心人物之一。；抗战期间出任伪山东省省长，推行日伪政令，配合日军扫荡山东抗日根据地，包括青岛、平度地区。；历任伪山东省公署省长、伪山东省政府省长，管辖包括青岛、胶州在内的山东沦陷区，推行保甲制，配合日军扫荡。；抗战期间任伪山东省省长，主持山东伪政权，配合日军扫荡抗日根据地，推行奴化教育。；长期担任伪山东省省长，配合日军在山东的统治、征粮、清乡，是山东地区重要汉奸头目。；长期担任伪山东省省长，为日军搜刮物资、征发劳工，协助维持占领区秩序。','省部级/大军区级要员','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ab952fb9349648d18053189cf4c7f12e','9edb0275b4734a47805ca9385baed31a',1937,'伪山东省公署省长、伪济南维持会会长','山东伪政权早期头目，建立伪省署并控制临沂等道县，协助日军维持占领秩序。；山东沦陷初期组织维持会并任伪省长，为日军稳定山东占领区秩序，影响波及菏泽、曹县等地伪政权建立。','基层维持会/地方自治头目','hanjian');
