INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('16e7ef7d044048c3a7498943989b9301','177c17b9b440453fa41ed47b9ebbd502',1938,'伪和平建国军第三方面军司令','匪首出身，抗战期间投靠日军，活动于鲁南临沂、费县、蒙阴一带，配合日军进攻抗日根据地，残害百姓。；著名土匪武装头目，投靠日军后率部在山东日照、莒县、诸城一带活动，配合日军扫荡，烧杀抢掠，后于1943年被八路军击毙。；原为土匪，投日后率部在鲁东南日照、莒县、临沂一带活动，配合日军扫荡，所到之处烧杀抢掠，1943年被八路军击毙。','基层头目','hanjian');
