INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2b936c4159fd4265a13183fdaf4e8193','8428849b87d9490cb77a5fc92c1aaabc',1938,'伪临沂县保安团团长','投靠日军后组建伪保安团，在临沂、临沭交界地带进行清乡，捕杀抗日干部和群众，强征钱粮。；组织伪保安团盘踞临沂城南及罗庄附近，为日军征粮抓丁，袭击八路军地方武装，残害抗日家属。','基层头目','hanjian');
