INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bf506dd196de46eda387275790c9642f','527b33cbf97f4907b567ab193092180f',1940,'伪临沂县保安团团长','组织伪保安团，协助日军在临沂兰山及周边地区清乡、扫荡，强征民夫，修筑据点。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('42b13913a4e544409992ffaf2c3ef1df','2f5442eec70b42ee9538471002804322',1939,'伪临沂县教育科科长','在临沂推行奴化教育，编写亲日教材，组织师生参加日伪庆祝活动，毒害青少年。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aafe5dd6bb814a1da0b82ba9d8da6611','8428849b87d9490cb77a5fc92c1aaabc',1938,'伪军头目，活动于鲁南临沂一带','率伪军配合日军扫荡临沂、费县等地，抢粮抓丁，杀害抗日干部和群众。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6e06e7bc35d54cceb4c4f33fac2c2b95','f0eae9f7415b4325b738db713926bacd',1937,'即刘桂堂，伪军师长','在临沂、费县、平邑一带为害，投日后任伪职，配合日军进攻八路军，1943年被击毙。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('39578bf5dbaa492da828e70bb7bfa5fb','fabd450d8480433fb1634895d3c43510',1938,'伪“山东自治联军”副司令','在山东诸城、临沂一带投敌，组织伪军，配合日军扫荡抗日根据地，残害百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('029ccb76d8fe4afcbf773d93d46233ff','3fcfa73a208547969c91611154e4f66e',1938,'伪临沂县知事、伪沂州道尹公署官员','在临沂地区附逆，历任伪职，配合日军进行治安强化运动，参与清乡、征粮和情报搜集。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a3410145a68d4d90b66fdc2d8affb081','177c17b9b440453fa41ed47b9ebbd502',1937,'伪军头目、伪和平救国军司令','率部投靠日军，活动于鲁南临沂、费县、兰陵一带，配合日军扫荡抗日根据地，烧杀抢掠。；原为土匪，抗战爆发后投靠日军，率部在鲁南、临沂、莒南一带活动，配合日军扫荡抗日根据地，残害百姓，1943年被八路军击毙。；原为土匪，抗战后投敌，率部在鲁南、临沂、蒙阴一带配合日军扫荡，烧杀抢掠，后于1943年被八路军击毙。；原为土匪，抗战期间投靠日军，率部在山东胶东地区活动，曾窜扰文登、威海周边，配合日军扫荡抗日根据地，残害民众。；率部投敌，在山东济南、泰安、临沂一带配合日军扫荡，残害抗日军民。；惯匪出身，抗战时期投靠日军，任伪军头目，流窜山东各地，包括潍县、寒亭一带，烧杀抢掠，无恶不作。；绰号刘黑七，率部投靠日军，在山东胶东及鲁中南地区活动，配合日军扫荡抗日根据地，残害民众，1943年被八路军击毙。；惯匪出身，抗战期间投靠日军，率伪军流窜于豫北、鲁西一带，曾活动至安阳周边，参与劫掠和配合日军作战。；流窜华北、西北的伪军匪首，曾活动于陕西东部边缘，对渭南、华州一带有骚扰和伪化影响。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('628372263a424a87af6698be430d28d8','30ce61bce3b94c0db98fa9508345e79c',1939,'伪临沂县警察所所长','掌管伪警察武装，在临沂城乡搜捕抗日人员，推行保甲连坐，勒索民众。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('09148995263e41cfa0e5d9c590657099','b1e2c050fe6449ff84cb46f64f24d30e',1938,'伪军头目、伪剿共军司令','在山东胶东及鲁南地区投敌，所部配合日军进攻八路军，在临沂周边地区有活动记录。；投靠日军后率部在山东胶东及鲁南地区活动，曾与临沂、莒南一带的日伪军配合扫荡，进攻八路军根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f3b637a6e5ec4cb2b6fe34cf8e918e2f','527b33cbf97f4907b567ab193092180f',1938,'伪兰陵县维持会会长','在兰陵地区组织维持会，为日军筹粮筹款，协助建立伪政权和伪军据点。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3017fc69986d493ca94ef8768b3261aa','2f5442eec70b42ee9538471002804322',1940,'伪兰陵县知事','任伪兰陵县知事期间，推行日军政令，征发民夫、粮食，配合日伪军对周边抗日根据地的扫荡。','基层头目','hanjian');
