INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('417c4df91ef640cc85863e85c037973e','47d747b3344b4bcdbf48b13eb24ea59e',1940,'伪沂州道尹公署道尹','任伪沂州道尹，管辖临沂等地伪政权，推行治安强化运动，为日军掠夺物资、征集劳工。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5ff884dbd6064c229bf877a4a377e427','dd6b6cda46c04c109fd14e65881d73fb',1938,'伪临沂县商会会长','在临沂商界附逆，为日军筹集物资、推销日货，协助经济封锁抗日根据地。；临沂沦陷后出面组织商会，为日军筹集物资，协助推行伪经济政策，压迫商民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('64db4090be8b47c69650df7c2d251357','8dc17a3c81f84795af50c8e88858ec67',1939,'伪临沂县教育科科长','推行奴化教育，在临沂各学校强制使用日伪教材，宣传“大东亚共荣”，毒害青少年。','基层头目','hanjian');
