INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d4fc877821714a8586f9225cfd16c566','0ce82afb041f4eb4a6fb886726d0274f',1938,'伪军头目、伪鲁南剿共军司令','在鲁南临沂、兰陵一带投敌，率伪军配合日军扫荡，袭击抗日武装，残害百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('da6ee876e2b24c3d935e18e2fb9d6f5f','eb04e636fb1541429b188c582ae8a447',1940,'伪临沂县合作社理事长','控制临沂地区物资流通，为日军掠夺农产品和战略物资，配合经济封锁。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4a2f5748d3434b2089c7e7bb15e1bd8e','b1e2c050fe6449ff84cb46f64f24d30e',1938,'伪剿共军暂编第十二师师长、伪莱阳/平度一带军政头目','原国民党军将领，后投敌编入伪军，在胶东及鲁中南边缘地区配合日军扫荡，进攻八路军和抗日根据地。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d232ae5e0a0c420baf2dbf21dc98023c','fabd450d8480433fb1634895d3c43510',1938,'伪山东剿共军第二路司令、伪诸城/莒县一带头目','率部投日，盘踞诸城、莒县、日照一带，配合日军对鲁东南包括临沂周边地区进行扫荡、抢粮和清乡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8a07a02dd2fe478da70987f8b420398d','177c17b9b440453fa41ed47b9ebbd502',1937,'伪军头目，绰号“刘黑七”','长期在山东流窜为匪，抗战期间投靠日军，活动于鲁南、鲁中一带，烧杀抢掠，配合日伪进攻抗日根据地。；长期在山东鲁南、鲁中一带流窜，后投靠日军，任伪军师长等职，在枣庄、峄县、费县、滕县周边活动，烧杀抢掠，配合日军进攻抗日根据地。；长期在山东流窜为匪，后投靠日军，在胶东及鲁中地区配合日军作战，骚扰牟平、烟台周边地区。','无明确职位或一般帮凶','hanjian');
