INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9e49929030094441bdaac21b5a5b2138','e0f3219e326a4f5c9431aa9a24b2239e',1938,'伪平邑维持会会长','平邑地区沦陷后出面组织维持会，协助日军建立伪政权，摊派粮款，压迫当地民众。','基层维持会/地方自治头目','hanjian');
