INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('90025e75abc346cea5b92fc13f092532','1f8eba63c91140febd4802304d747e35',1938,'伪沂州道道尹、伪临沂县知事','抗战期间投靠日军，出任伪沂州道道尹兼伪临沂县知事，在临沂及沂南一带推行伪化统治，组织维持会、保甲制，配合日军清乡、扫荡，镇压抗日群众。','基层头目','hanjian');
