INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('59dd9f88ca5e47eabb5cd7c40302b555','3fcfa73a208547969c91611154e4f66e',1938,'伪临沂县维持会会长','临沂沦陷后出面组织伪维持会，协助日军维持城区秩序、征粮派款，诱迫商户和居民服从伪政权，为日军侵华提供后勤支持。；日军侵占临沂后出面组织维持会，为日军筹粮筹款、拉夫，协助建立伪基层政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7e611edb816145259b6486c09d2e6fa2','b1e2c050fe6449ff84cb46f64f24d30e',1938,'伪剿共军司令、伪军头目','投靠日军后任伪剿共军司令，在山东包括临沂、沂南周边地区活动，配合日军扫荡抗日根据地，残害抗日军民。；原国民党军将领，后投敌任伪剿共军司令，活动于胶东及潍县一带，配合日军进攻抗日根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f5042dd43f954e6cbbfc1b7bb78c3223','448d0f7cee64452499a7d23f73c33bbb',1939,'伪沂州道公署顾问、伪政权要员','在伪沂州道公署任职，参与临沂、沂南地区伪政权建设，推行奴化教育，协助日军征发劳工、物资。','无明确职位或一般帮凶','hanjian');
