INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('adfa2bc5322442b19a28595ca8d9b6aa','448d0f7cee64452499a7d23f73c33bbb',1938,'伪沂水维持会会长','沂水沦陷后组织维持会，协助日军维持地方秩序，搜捕抗日人员。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('35aea7a398c846acb69ba5c214efa4a0','b1e2c050fe6449ff84cb46f64f24d30e',1938,'伪剿共军司令、伪莱阳县长','在胶东及鲁中南地区投敌，配合日军扫荡，其势力范围曾覆盖临沂北部、沂水一带。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('644fc2f49fc642ae8fafe3bf5610281c','5f288d2b1f2a40b7863a25e30e61b7c4',1937,'伪鲁东和平建国军司令','原国民党游击部队，后投敌，在鲁中、鲁南地区配合日军行动，活动范围包括临沂、沂水周边。；原国民党山东省第八区专员，后投敌任伪职，在胶东地区组织伪军，配合日军进攻抗日根据地，活动范围涉及威海周边。；原国民党地方武装首领，投敌后任伪军司令，在山东配合日军作战，镇压抗日力量。；山东伪军重要头目，虽主要活动于鲁东，但其伪军体系在山东全省配合日军，对鲁南包括枣庄地区有影响。；山东伪军重要头目，长期在山东地区为日军效力，参与对抗日根据地的进攻和治安强化运动。；山东伪军重要头目，活动于胶济铁路沿线及济南周边，配合日军作战。；山东伪军头目，所部在胶济线及济南外围配合日军行动。；原国民党将领，1943年投敌，任伪军司令，活动于鲁东、鲁中地区，配合日军扫荡淄博一带。；原国民党地方武装，后投敌，盘踞潍县、昌乐一带，与淄博地区日伪有协同行动。；原国民党山东省第八区专员，1943年投敌，任伪鲁东和平建国军司令，活动于潍县、坊子、安丘一带，配合日军扫荡。；原国民党军将领，投敌后盘踞潍县、昌邑、安丘一带，活动范围接近胶东，配合日军进攻抗日根据地。；原国民党山东省第八区专员，后投降日军，在胶东地区组织伪军，配合日军扫荡，活动范围覆盖烟台、蓬莱等地。；1943年投敌，所部在山东活动，曾配合日军对菏泽、单县地区进行扫荡，镇压抗日力量。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6bfb9451591a4000b7690f5064921f6e','fabd450d8480433fb1634895d3c43510',1938,'伪山东国民自卫军第二师师长','在鲁东南一带投敌，配合日军扫荡滨海抗日根据地，活动区域邻近临沂、沂水。；在胶东及鲁东地区组织伪军，活动范围涉及威海周边，配合日军进行清乡、扫荡。；山东诸城一带伪军头目，投靠日军后配合扫荡山东抗日根据地，其活动范围覆盖胶东部分地区，与威海、荣成地区抗日斗争有间接关联。；投靠日军，在诸城、高密、安丘、潍县一带组织伪军，残害抗日军民，配合日军扫荡。；在胶东地区组织伪军，活动于烟台、招远周边，配合日军扫荡，镇压抗日力量。；在胶东地区组织伪军，配合日军对烟台、牟平周边抗日根据地进行扫荡和清乡。；原国民党军军官，投敌后盘踞诸城、胶县、高密一带，活动范围接近胶东，配合日军扫荡，残害百姓。；在山东胶东地区组织伪军，配合日军对胶东抗日根据地进行扫荡，活动于烟台、青岛之间地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cc9c6891131e47a2bd50c9b73cb44239','527b33cbf97f4907b567ab193092180f',1940,'伪沂水县保安大队大队长','率伪保安队驻守沂水据点，配合日军清乡、扫荡，抓捕抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e462e1bf8dbf40c098caafacbecfa19d','0d895504e90643baa3a4f21afe45d189',1939,'伪临沂县警察局局长','在临沂沦陷区掌管伪警察，镇压抗日活动，逮捕、刑讯抗日人员。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d29d86fbedbf47439db4c94eb1b1ee89','177c17b9b440453fa41ed47b9ebbd502',1937,'伪军头目，曾任伪和平救国军第三方面军司令','长期在鲁南、临沂一带活动，先为土匪，后投靠日军，配合日伪扫荡抗日根据地，残害百姓，1943年被八路军击毙。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b63c336a079248928ad67aee8f3bca63','3fcfa73a208547969c91611154e4f66e',1938,'国民党游击武装首领，后降日任伪职','在临沂、沂水一带活动，抗战中后期与日伪勾结，接受伪职，配合日军进攻抗日根据地。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ce028b626c18410fa8845cfa06cd8bf1','b1e2c050fe6449ff84cb46f64f24d30e',1938,'伪军头目，曾任伪剿共军司令','在山东胶东及鲁南地区活动，后投靠日军，配合日伪扫荡，其势力一度覆盖临沂周边。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3a210f9d5ab048f6aa1c9962ff0d5ac4','527b33cbf97f4907b567ab193092180f',1938,'伪临沂县河东区维持会会长','在临沂河东地区组织伪维持会，为日军征粮派款，协助建立伪保甲制度，镇压当地抗日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c4b98aff3f264e638615f787e2262d0d','bb9f3367044e403997a73a2007e0c137',1940,'伪临沂县保安团团长','率伪保安团在临沂及河东一带配合日军扫荡，抓捕抗日军民，抢掠财物。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7fad7ae80d2f41b79c533744e4c694e0','e8d5ed0d704a472680033191d6ee53a9',1938,'伪山东省公署委员、伪临沂道尹','任伪临沂道尹期间，推行日军殖民统治政策，督饬各县伪政权征粮、抓丁、修路，镇压抗日力量。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('326193e2187d464a9a17b762dd275507','c1daa171e05746d383d93806c90f6027',1939,'伪临沂县教育会会长','在临沂推行奴化教育，编写亲日教材，组织师生参加日伪宣传活动，毒害青少年。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ee253c82b5f34aa08ca7e9d9cf8d485f','f64531e1c7554edb9219473b57045b70',1938,'伪临沂县商会会长','控制临沂城区商业，为日军筹集物资，配合经济封锁，压榨商户和百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e13706b2f0484c98b7ea6ffdc94e6eed','b1e2c050fe6449ff84cb46f64f24d30e',1938,'伪剿共军暂编第十二师师长、伪莱阳县长','原国民党军将领，后投靠日军，在胶东及鲁中南地区配合日军扫荡，其伪军活动曾延伸至临沂北部及沂水、蒙阴一带，对罗庄周边抗日根据地构成威胁。；原国民党军将领，后投靠日军，在胶东地区配合日军进攻抗日根据地，活动范围覆盖威海、烟台一带。；原国民党军将领，后投靠日军，盘踞莱阳、海阳、即墨一带，控制胶东部分地区，配合日军进攻抗日根据地，1945年被八路军击毙。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ac4d86ae48c84089849ab547ad275c5e','177c17b9b440453fa41ed47b9ebbd502',1937,'伪和平救国军第三方面军总司令','绰号刘黑七，长期在鲁南、沂蒙山区流窜，投日后任伪军头目，配合日军扫荡临沂、费县、平邑等地，烧杀抢掠，罗庄周边村庄亦受其害。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1ca7c2b2f4e6493682459281b66ee3ca','3fcfa73a208547969c91611154e4f66e',1938,'伪沂州道道尹','日军在临沂设立伪沂州道后出任道尹，管辖临沂、郯城、费县等县，推行伪化教育、经济统制，为日军征集物资，其道署驻临沂城，直接影响罗庄地区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4c89e25ca705478ea6bbf95764371a72','448d0f7cee64452499a7d23f73c33bbb',1939,'伪临沂县警察局局长','任伪临沂县警察局长期间，带领伪警察配合日军搜捕抗日人员，在罗庄、付庄一带设立检查站，勒索百姓，镇压抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('91cbca0de71d419db0ab9f5752c8347f','a8b4bdacb8364253965c78e9825e4713',1938,'伪临沂县罗庄乡维持会会长','在罗庄一带组织维持会，为日军带路、征粮，协助建立伪保甲制度，监视村民抗日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7239156126d54655bf8a7af59102616c','e0f3219e326a4f5c9431aa9a24b2239e',1940,'伪临沂县付庄乡乡长','任伪付庄乡乡长，配合日军在付庄、罗庄一带清乡，强迫村民修筑据点，提供情报。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('207301db42484b1bb46f99b372daf203','f64531e1c7554edb9219473b57045b70',1939,'伪沂州道警务处督察长','在伪沂州道警务系统任职，负责临沂及周边县伪警察调度，参与对罗庄地区抗日群众的镇压。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e13a593cb9b0443c8f7509fb77245f7a','f4897f3618544e07ac7ec05e3426180e',1938,'伪临沂县新民会会长','主持伪新民会临沂分会，推行奴化教育，在罗庄等地设立日语学校，宣传“大东亚共荣”，毒化民众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6932eca7f5474a85a1888604c9f2c42b','1f8eba63c91140febd4802304d747e35',1938,'伪临沂县维持会会长、伪临沂县县长','抗战期间投靠日军，在临沂地区组织维持会，协助日军维持占领区秩序，推行伪化统治，搜捕抗日人员，为日军征发劳役和物资。；日军侵占临沂后出面组织维持会，后任伪临沂县县长，协助日军推行保甲、征粮、抓丁，镇压抗日群众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('43908055ad9446c59233c2898dc1be7b','3fcfa73a208547969c91611154e4f66e',1939,'伪临沂县警察局局长','在日军占领临沂期间担任伪警察头目，负责维持城区治安，抓捕抗日嫌疑人员，协助日军推行保甲制度。；在临沂沦陷后投敌，任伪警察局长，协助日军搜捕抗日人员，推行治安强化运动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6941099b81394a279283867233e2fbe1','448d0f7cee64452499a7d23f73c33bbb',1940,'伪莒南县维持会会长','在莒南地区组织维持会，为日军征集粮食、劳工，协助日军建立伪政权，镇压当地抗日活动。','基层维持会/地方自治头目','hanjian');
