INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f711166a290149d08c65678ed2e0f316','177c17b9b440453fa41ed47b9ebbd502',1937,'伪军头目，曾任伪“和平救国军”师长','匪首出身，抗战期间投靠日军，率部在鲁南、临沂、费县一带活动，配合日军扫荡，残害抗日军民，1943年被八路军击毙。','市县厅局级','hanjian');
