INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cb9fa219f63e48b199eb4ef3dfef8d02','b1e2c050fe6449ff84cb46f64f24d30e',1938,'伪“和平救国军”暂编第十二师师长','原国民党军将领，后投日，在山东胶东及鲁南地区活动，其势力一度覆盖临沂北部，配合日军进攻八路军。','市县厅局级','hanjian');
