INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1fcb2d0e96844a79ab0919e995d34109','787316523113404490ba5600ddd81417',1938,'伪郓城县知事、伪鲁西道尹','山东著名汉奸，在鲁西地区为日军效劳，其伪化活动虽主要在鲁西，但作为山东伪政权要员，对全省伪化有影响。','基层头目','hanjian');
