INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2c6a3d900fc44a918da82898a90dd3f8','e0f3219e326a4f5c9431aa9a24b2239e',1938,'伪临沂县商会会长','临沂商界附逆代表，为日军筹集物资，协助推行伪币，控制当地经济。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5bcc6bc2d93f400faaf37ca0e5f3ddfd','5de8249bb76d40f6b63fa1aeef8137c7',1939,'伪费县教育科科长','在费县推行奴化教育，篡改教材，宣传“大东亚共荣”，毒害青少年。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8e79593b42dd4b7a8a6de959c0ce54ed','3fcfa73a208547969c91611154e4f66e',1938,'伪临沂县保安团团长、伪军头目','在临沂一带收编土匪、散兵组织伪保安团，配合日军扫荡抗日根据地，袭击八路军和地方抗日武装。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('94419e8b293d4f16ac91e01615845d56','177c17b9b440453fa41ed47b9ebbd502',1933,'伪军师长、伪“和平救国军”头目','长期在鲁南、临沂、郯城、费县一带流窜，后投靠日军任伪军师长，配合日军进攻鲁南抗日根据地，残害百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bbe630aca4034c73947346d9fa1c10bd','30ce61bce3b94c0db98fa9508345e79c',1938,'伪郯城县维持会会长、伪郯城县县长','郯城沦陷后组织维持会，任伪县长，为日军征粮派款、搜集情报，协助日伪军控制郯城及周边地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('16ec340a635240b3a8063fbae6df7ef6','2f5442eec70b42ee9538471002804322',1939,'伪郯城县警备队队长','任伪郯城县警备队头目，率伪军配合日军下乡扫荡，抓捕抗日人员，催缴捐税。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('58d5cfa658ef42c384b91b44d06c74fb','572e493580ca4064a2dde5b7f31ae399',1940,'伪郯城县教育科科长、伪新民会郯城分会负责人','在郯城推行奴化教育，组织新民会宣传“大东亚共荣”，协助日军控制学校和文化宣传。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('74bf8791702243ecb34e345332d9572a','b1e2c050fe6449ff84cb46f64f24d30e',1938,'伪军暂编第十二师师长','在山东胶东及鲁南一带投靠日军，所部伪军配合日军扫荡，与八路军为敌，后活动范围涉及鲁南地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4ea264efcece4ad9b36de40deba62602','15a53deac38b4a38bb911a125d119e5c',1939,'伪临沂县警察局局长','任伪临沂县警察局长，协助日军维持治安，搜捕抗日人员，镇压群众抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e9bba68ff8c849fdbc6f14aca9216d8c','8428849b87d9490cb77a5fc92c1aaabc',1938,'伪军头目、伪临沂县自卫团团长','在临沂、郯城交界一带组织伪自卫团，配合日军扫荡，抢粮抓丁，残害抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7a3808d30add43c78bebce767d2029d7','dd6b6cda46c04c109fd14e65881d73fb',1940,'伪郯城县保安大队大队长','率伪保安大队驻守郯城，配合日军封锁抗日根据地，盘查行人，抓捕抗日嫌疑人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('557a2caf6a5b45d0869073c31ce93974','811fe999084946d8baee44410886b3e6',1931,'伪山东自治联军副总司令、伪军头目','日本浪人出身，本名伊达顺之助，长期在山东活动，组织伪军配合日军进攻胶东，参与威海、烟台一带的伪化统治。；原名仓谷次太郎，日本浪人出身，长期在山东胶东地区活动，收编土匪、溃兵组成伪军，配合日军进攻胶东抗日根据地，活动范围覆盖威海、烟台一带。；日本浪人出身，长期在山东活动，组织伪军配合日军进攻山东各地，1938年前后在鲁东南一带活动，与日照地区伪化过程有关联。；原名张宗昌之侄或日籍浪人化名，抗战初期在山东组织伪军，配合日军进攻鲁中地区，其部曾活动于淄博、沂源一带，参与扫荡抗日根据地。；原名张步云，山东诸城人，抗战期间投靠日军，在山东境内组织伪军，配合日军进攻抗日根据地，活动范围涉及潍坊及周边地区。；原名张宗昌旧部相关伪军头目之一，抗战时期在山东一带收编土匪、溃兵组成伪军，配合日军在胶济铁路沿线及潍坊、昌邑周边地区进行扫荡、征粮和镇压抗日力量。；原名仓谷次太郎，日本浪人出身，长期在山东胶东地区活动，组织伪军配合日军进攻招远、烟台等地，参与扫荡抗日根据地。；原名仓谷次太郎，日本浪人出身，长期在山东胶东地区活动，收编土匪、溃兵组成伪军，配合日军进攻胶东抗日根据地，在烟台、栖霞一带参与扫荡和清乡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1185597687d14ca59dc7b6a75643d600','b1e2c050fe6449ff84cb46f64f24d30e',1938,'伪剿共军胶东司令、伪莱阳县长','原国民党军将领，后投敌，盘踞胶东莱阳、海阳一带，与威海地区伪军相呼应，配合日军扫荡抗日根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bce9f6c554d74114afed0fe9612cce33','448d0f7cee64452499a7d23f73c33bbb',1938,'伪青岛特别市市长、伪胶东道尹','在青岛及胶东地区推行伪政，其辖区涵盖威海周边，协助日军征发劳工、物资。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a168a2c62a134d83849ea0fe76f21a19','6d784f5f562c45c29f0b08537c8a2594',1938,'伪威海卫维持会会长','日军侵占威海后出面组织维持会，为日军筹粮筹款、招募伪警察，维持地方伪秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2916a1c6666a41d2a0548f31d32eecfe','ddf655c3bf3343f69896744af0376eb6',1940,'伪威海卫特别区公署署长','在威海卫伪政权中任职，推行保甲制，配合日军抓捕抗日人员、征发劳工。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('429bbfb343cd4f5da3533c830087009b','bd5cba57bd1846c89237f9e3ce03fb0e',1938,'伪威海卫警察局局长','组建伪警察队伍，协助日军搜查、逮捕抗日志士，镇压威海周边抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d43a7311317b486096df3ad11c17d93c','bcce4eb13f2542e19c91f0327c0c5316',1938,'伪文登县知事','在文登（今威海辖区）推行伪政，组织伪自卫团，配合日军对昆嵛山抗日根据地的扫荡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e7c68a58bf7d4eedb7924c134280661d','fd970e353c7a4171abfbe981a54193b3',1938,'伪荣成县维持会会长','在荣成组织维持会，为日军登陆和驻防提供便利，协助征发渔船、劳工。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6f13360e270f459aa8595c5c71657c52','fe7588d226fa430ea2eda3d08a162f2f',1941,'伪乳山县知事','在乳山（今威海辖区）建立伪政权，推行保甲连坐，配合日军扫荡马石山一带。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e65f1c7603004b5c8703c7063ca2143e','b2c19be7112c493a928de325ad0ad15c',1938,'伪烟台市市长','在烟台伪政权任职，其辖区与威海相邻，协助日军控制胶东沿海，征发物资劳工。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('de78c291bd324f19ba6e8041c9c0826f','8085e0e5fd8a4ece88f3b28d89e9760f',1938,'伪胶东道道尹','统辖胶东伪政权，包括威海卫、烟台等地，推行日语教育、奴化宣传，配合日军经济掠夺。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3920743305b64db5b03107df707a2392','2170fa0658af47b6ab65f21d7d387c41',1938,'伪山东新民会胶东指导部部长','在胶东包括威海地区开展奴化教育，组织新民会，宣传“中日亲善”，协助日军控制民众思想。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('eb43a4e39c564f708e834b78f8c94d02','e52245c19301443fb3995b3718c42935',1938,'伪威海卫商会会长','作为经济界附逆者，为日军筹集军需物资，控制威海商业，配合经济封锁抗日根据地。；在威海卫商界为日军筹款筹粮，组织商户附逆，协助日军经济掠夺。；在威海卫为日军筹集物资、摊派款项，协助日军经济掠夺，属经济领域附逆者。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('435b7c2c7565417e9efb79888f5b6cf4','201ab0466f404f49ba0dee4d607fbfa2',1938,'伪威海卫教育会会长','在威海推行奴化教育，改编教材，强制教授日语，培养亲日分子。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f37974798c124cb58bec36556c2b2eab','b1e2c050fe6449ff84cb46f64f24d30e',1938,'伪暂编第十二师师长、伪胶东挺进军司令','原国民党军将领，后投靠日军，盘踞胶东莱阳、海阳、即墨一带，多次配合日军扫荡胶东抗日根据地，与威海、乳山地区抗日武装多次交战。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e539f9f699dc4f8f8f49caa2f5353220','fabd450d8480433fb1634895d3c43510',1938,'伪山东保安第二师师长、伪滨海警备军司令','盘踞诸城、胶县、日照一带，后势力扩展至胶东边缘，配合日军对胶东抗日根据地扫荡，残害抗日军民。；在鲁东南及胶济铁路沿线投敌，配合日军进攻八路军，活动范围涉及淄博以东地区。；原土匪武装，投靠日军后盘踞诸城、高密、胶县一带，活动区域邻近潍坊滨海地区，多次配合日军进攻八路军滨海根据地。；原国民党地方武装，后投靠日军，在诸城、潍县、安丘一带组织伪军，残害抗日军民。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('99b51f6052734d7db9d6bf4566d8891a','448d0f7cee64452499a7d23f73c33bbb',1938,'伪青岛特别市市长、伪青岛保安总队司令','抗战期间在青岛地区与日伪合作，维持伪政权统治，其势力范围与胶东威海、乳山地区有间接关联。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('30b536cd2a0e4443bac26afcfd6aecc9','8376c3d3521140298ec1ac6d87bd32ef',1937,'伪青岛特别市市长','青岛伪政权头目，配合日军在山东沿海地区推行殖民统治，对胶东地区抗日活动进行镇压。；长期担任伪青岛市长，协助日军控制山东沿海，推行伪化教育与经济掠夺。；青岛伪政权头目，与济南伪省府配合，推行日军殖民政策。；山东伪政权重要成员，驻青岛，与济南伪政权有联系。；在青岛任伪市长，配合日军统治，其伪政权影响覆盖山东包括淄博地区的经济统制。；接任伪青岛市长，继续为日伪政权服务至抗战结束。；继李先良后任伪青岛市长，推行保甲制，强征劳工，其辖区与潍坊地区同属胶济铁路沿线伪政权体系。；任伪青岛市长期间，配合日军统治，镇压抗日活动，搜刮民财。；继李先良后任伪青岛市长，继续为日军服务，配合经济掠夺。；投靠日军，出任伪青岛市市长，配合日军在胶东地区的统治，镇压抗日活动。；曾任伪青岛特别市市长，在山东胶东地区为日军服务，推行伪化统治。；接任伪青岛市长，继续推行伪化统治，与烟台、芝罘伪政权配合，协助日军征粮征丁。；汉奸政权官员，任伪青岛市长期间，配合日军统治，在青岛及胶东地区推行伪化政策。；继赵琪后任伪青岛市长，继续为日军服务，直至抗战胜利。；抗战后期任伪青岛市长，继续为日军服务，直至日本投降。；继赵琪后任伪青岛市长，继续推行日军政策，在崂山周边强化保甲连坐，搜捕抗日人员。；继赵琪之后任伪青岛特别市市长，配合日军征粮、征工与治安强化运动，是青岛沦陷后期主要伪政权头目之一。；抗战期间出任伪青岛特别市市长，推行日伪殖民统治，镇压抗日活动，为日军搜刮物资。；接替赵琪任伪青岛市长，继续推行日军政策，强征劳工，搜刮物资，直至抗战胜利。；继赵琪之后任伪青岛特别市市长，继续为日军服务，直至抗战胜利。','特别市市长','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('64e3f48d52404fb6a58fa458bac7ec72','8dd71bba0484426388d6dbcfae15bd52',1938,'伪青岛特别市市长、伪华北政务委员会委员','青岛伪政权要员，协助日军维持山东沿海占领区统治，与胶东威海、乳山地区伪政权有行政联系。；青岛沦陷后出任伪市长，主持伪政权事务，配合日军征粮、征工，镇压抗日活动，其管辖范围包括崂山地区。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cd5afef06e854089b1d6e52fe91e478c','6d784f5f562c45c29f0b08537c8a2594',1938,'伪威海卫专员公署专员','日占威海卫时期伪政权头目，负责威海卫及周边地区的伪行政事务，配合日军征粮、抓丁、镇压抗日活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('63a1b294e05a43f2bc1da927bda9444e','e52245c19301443fb3995b3718c42935',1938,'伪威海卫维持会会长','日军侵占威海卫后组织维持会，协助日军维持地方秩序，为日军筹集物资、情报。；日军占领威海后组织维持会，出任会长，为日军筹粮筹款、维持治安，协助建立伪政权，影响文登周边。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('da64bb11e41048aa8c076d9b4f50834d','bd5cba57bd1846c89237f9e3ce03fb0e',1938,'伪威海卫商会会长、维持会成员','威海卫商界附逆者，协助日军控制威海卫经济，为日军采购物资，参与伪政权活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6a6a7663f5804061ab93e22db825930f','bcce4eb13f2542e19c91f0327c0c5316',1938,'伪威海卫管理公署职员、伪政权参事','原威海卫管理公署人员，日军占领后留任伪职，协助日军管理威海卫地方事务。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('191bbd0b717a4e229820ab42b8ec9614','7e62cc93b19f491aafffea9ee4969692',1938,'伪牟平县县长','牟平伪政权头目，牟平与乳山相邻，其伪政权活动覆盖乳山北部地区，配合日军扫荡抗日根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('07b17a664c1d470798734b2da63e3249','8085e0e5fd8a4ece88f3b28d89e9760f',1938,'伪海阳县县长','海阳伪政权头目，海阳与乳山接壤，其伪政权配合日军对乳山、海阳交界地区抗日武装进行清剿。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d438f05a260c4792ad7e14a07914dd14','2f9f8887697d4f2a89bf9e602d9c4bec',1938,'伪文登县县长','文登伪政权头目，文登与乳山相邻，其伪政权协助日军控制文登、乳山交界地区，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6d6547e08dc44e6ba6c16c02acaa8ddd','fd970e353c7a4171abfbe981a54193b3',1938,'伪文登县保安大队大队长','文登伪军头目，率伪军配合日军扫荡文登、乳山地区抗日根据地，残害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1352b13ba7384b10a3e4545ed222ccb4','40f92d8dcd244ed4b27495497bbc1c5c',1938,'伪军头目、胶东伪军司令','盘踞胶东地区，收编土匪武装投靠日军，配合日军进攻胶东抗日根据地，活动范围涉及威海、乳山一带。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('72a4bd5e3ca04f008aacc7e59059d26d','8dc74cb6dfab4cf49fc60ef909d45839',1938,'伪军头目、胶东伪军旅长','胶东伪军头目，配合日军在威海、烟台地区扫荡，残害抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('311dc1f24d1e47b68f3e67ad681fde37','3b9fc251991e4aaa970a766d06b65bcf',1938,'伪烟台市市长','烟台伪政权头目，烟台为威海邻近地区，其伪政权配合日军控制胶东沿海，支援威海、乳山地区日军行动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b6dcf32c290241a2ba61ba18500dddd9','1f4d71be8fd04f95b60a3051426cd5cc',1938,'伪烟台商会会长','烟台商界附逆者，协助日军控制胶东经济，为日军筹集物资，与威海、乳山地区伪政权有经济往来。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('771cdffcd2464229b529921d655278e9','2bca068f7db246f9aa902335d2194712',1938,'伪山东省政府委员、伪胶东道尹','伪胶东道尹，管辖胶东各县包括威海、乳山地区，配合日军推行伪化统治，镇压抗日活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('95029bda28544c878d1ed56cb33b2c6c','9edb0275b4734a47805ca9385baed31a',1937,'伪山东省省长','伪山东省省长，配合日军在山东推行伪化统治，其行政管辖范围包括威海、乳山地区。；早期伪山东省长，协助日军建立伪政权体系，其政令覆盖威海地区。；投敌后任伪山东省省长，在山东推行伪化统治，其政令下达至威海、文登等县，协助日军征粮、抓丁、镇压抗日。；出任伪山东省长，为日军在山东包括威海地区的殖民统治服务，推行伪化政策。；曾任伪山东省省长，协助日军统治山东，推行伪政，涉及潍坊、临朐地区。；济南沦陷后任伪山东省长，其伪政权统治覆盖潍县等地。；担任伪山东省省长，协助日军统治山东，推行保甲制度，镇压抗日活动。；北洋旧官僚，日军侵占山东后出任伪山东省省长，协助日军建立伪政权，在鲁西聊城等地推行保甲制度。；作为山东伪政权头目，在包括聊城、东阿在内的全省推行伪化政策，配合日军扫荡。；早期伪山东省长，在鲁西包括聊城、冠县一带建立伪政权，为日军筹措物资。；伪山东省长，在任期间在聊城等地建立伪政权，推行治安强化运动。；伪山东省最高行政长官，在山东全省推行伪化统治，包括菏泽地区，协助日军掠夺资源、镇压抗日。；曾任伪山东省省长，配合日军维持山东沦陷区统治，在青岛、即墨等地推行保甲制度和奴化教育。；早期伪山东省长，协助日军建立伪政权，镇压抗日力量。；出任伪山东省省长，协助日军统治山东，推行伪化教育、征发劳工，镇压抗日根据地。；北洋旧官僚，抗战后投敌，出任伪山东省省长，协助日军维持山东沦陷区统治。；曾任伪山东省长，在济南等地组织伪政权，其政令涉及青岛、胶州地区。；曾任伪山东省省长，协助日军维持山东占领区统治，镇压抗日活动。；抗战初期出任伪山东省省长，协助日军在山东建立伪政权，推行殖民统治。；投靠日本，出任伪山东省省长，在山东境内推行伪化统治。','省部级/大军区级要员','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6d7767142f3640b6ab4bad80ce3f1ba7','2994abf4d5f94828a7c8432e77840e2a',1938,'伪山东省警务厅厅长','伪山东省警务头目，负责全省伪警察系统，协助日军镇压山东各地抗日活动，包括威海、乳山地区。；山东人，抗战期间任伪山东省警务厅厅长，统辖伪警察力量，参与搜捕抗日人员、破坏抗日组织。；任伪山东省警务厅厅长，统管伪警察，配合日军搜捕抗日人员，涉及潍坊、临朐地区。；掌管山东伪警察系统，配合日军清乡、扫荡，镇压抗日群众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('38d40320942d40d3b6cb9a7f2c504638','eeb3c8c33a9044808ed5db66316ce87d',1938,'伪山东省保安司令部司令','伪山东省保安部队头目，统辖山东伪军，配合日军扫荡抗日根据地，其部队在胶东威海、乳山地区有活动。；统率伪保安队驻济南及周边，配合日军进攻抗日武装。；统率山东伪保安队，配合日军对济南周边及长清等地进行扫荡。；抗战期间投敌，任伪山东保安司令，统辖伪保安队配合日军在济宁、微山湖地区清乡。；任伪山东省保安司令部司令，统管伪保安队，配合日军扫荡抗日根据地，涉及潍坊、临朐地区。；在山东组织伪保安队，配合日军扫荡抗日根据地，活动范围包括潍坊、高密。；统辖山东伪保安队，在聊城地区配合日军扫荡，征丁征粮。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6cc00192bc084ef8a431a82f1936c432','b5b65c50b47e42e49b1a39960686a979',1938,'伪军头目、伪山东保安旅旅长','胶东伪军头目，配合日军在威海、乳山地区进行扫荡，残害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('69a0abf5d9884185911fd20be278a861','bf09837695814bdc909bf536d932d291',1938,'伪军头目、伪胶东保安团团长','胶东伪军头目，活动于威海、乳山一带，配合日军清剿抗日武装。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('42a7e9a0e2484ef2b7fc467cda0e0fb1','e96fe66c2c554a15bdd4e6a2360553e9',1940,'伪乳山维持会会长','乳山地区伪维持会头目，协助日军在乳山地区征粮、抓丁、搜集情报，镇压抗日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('85790108e28b4297b6ac59cb000d47f3','948f8c20b4954578b53560b096928c22',1938,'伪军头目、胶东伪军司令','原国民党军将领，后投靠日军，盘踞胶东地区，配合日军进攻威海、乳山抗日根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0f0448a0159248feb1064e35b67eb456','c736f6028cbf48979234bd1391a47012',1938,'伪军头目、伪胶东挺进军司令','胶东伪军头目，活动于栖霞、牟平、海阳一带，与威海、乳山地区抗日武装多次交战。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bc5affd34b6246319561de793a7e9bac','03e974605726485ab675c37d99b22c99',1938,'伪军头目、伪威海卫保安司令','威海卫伪军头目，配合日军控制威海卫及周边地区，镇压抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7fca1f408f3b499bba2f9f3b65b750c7','b2c19be7112c493a928de325ad0ad15c',1938,'伪军头目、伪威海卫警察局局长','威海卫伪警察头目，协助日军维持威海卫治安，抓捕抗日人员。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d69c1bb966414fe485b2110fd2617c55','bcce4eb13f2542e19c91f0327c0c5316',1938,'伪威海卫特别行政区专员公署专员','日军侵占威海卫后出面组织伪政权，任伪威海卫特别行政区专员，协助日军维持占领秩序、征发物资。；抗日战争时期投靠日军，出任伪威海卫特别行政区专员，协助日军维持威海卫及环翠一带的殖民统治，推行伪化政策。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('734a72445abf49c1928d35264a2dca21','ddf655c3bf3343f69896744af0376eb6',1938,'伪威海卫维持会会长','1938年日军占领威海卫后，参与组织伪维持会，为日军筹粮筹款、拉夫，协助建立殖民统治秩序。；日军侵占威海卫后出面组织伪维持会，为日军筹粮筹款、维持地方秩序，协助推行伪政权统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a0cd7fa857e8427a86ea399c8c14b252','912e82b16f544df0b945acb324ec1261',1938,'伪威海卫商会会长','在日军占领威海卫期间，以商会名义为日伪筹集物资、摊派款项，协助日伪控制当地工商业。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5256ee1a70974c6492c7f549739516e5','8085e0e5fd8a4ece88f3b28d89e9760f',1938,'伪威海卫警察局局长','任伪威海卫警察局长期间，配合日军搜捕抗日人员，镇压民众抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4cc0611433324a898fa969195f1f06ed','448d0f7cee64452499a7d23f73c33bbb',1938,'伪青岛特别市市长','任伪青岛市长期间，配合日军在山东沿海地区的统治，为日军提供物资和情报支持。；抗日战争后期出任伪青岛市长，为日军在山东沿海地区的统治服务，其影响波及胶东包括威海一带。；在青岛任伪市长，其伪政权与山东各地包括淄博有行政联系，协助日军掠夺物资。；抗战期间曾任伪青岛特别市市长，为日军控制青岛提供行政支持。；在青岛及山东地区任伪职，协助日军维持殖民统治，推行伪化政策。；任伪青岛市长期间，推行日伪政策，协助日军控制胶济铁路沿线，影响潍坊地区。；抗日战争时期在山东青岛地区任职伪政权，配合日军统治，其活动范围覆盖胶东地区。；抗战期间投敌，任伪青岛市长，管辖青岛及周边地区，包括烟台部分区域，推行奴化教育，为日军搜刮物资。；抗日战争后期出任伪青岛特别市市长，推行日伪统治政策，协助日军维持青岛及周边即墨等地的治安与物资征调。；抗战期间任伪青岛特别市市长，主持伪政权，推行日军殖民统治政策，镇压青岛地区抗日活动。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a4fe800a58e94316a1204d45f1c6fcd9','e76c89aa3bac464887a41dbac4b6e4e1',1937,'伪山东省省长','任伪山东省长期间，配合日军在山东的殖民统治，推行保甲制度，镇压抗日活动。；抗战末期任伪山东省省长，维持日军在山东包括威海、文登地区的殖民统治，直至日本投降。；北洋旧官僚出身，抗战时期附逆，任伪山东省省长，为日军统治山东服务。；抗战后期任伪山东省省长，继续为日军服务，维持伪政权统治，参与对山东抗日军民的镇压与经济掠夺。；抗战末期任伪山东省省长，继续为日军维持山东沦陷区统治。；抗战末期任伪山东省省长，驻济南，维持日伪统治。；抗战末期任伪山东省省长，维持日伪在山东的统治。；在济南任伪山东省省长，配合日军建立伪政权体系，推行保甲与治安强化运动。；抗战末期任伪山东省省长，驻济南，维持日伪政权至日本投降。；继任伪山东省长，继续推行日军侵略政策，在济宁地区强化伪政权，掠夺经济资源。；北洋旧官僚出身，抗战期间附逆，任伪山东省省长，协助日军维持山东沦陷区统治。；抗战时期任伪山东省省长，为日军在山东的殖民统治服务，参与伪政权行政与治安事务。；继任伪山东省长，继续推行日军政策，配合扫荡山东抗日武装。；抗战末期任伪省长，继续为日军服务，维持山东沦陷区统治。；抗战末期任伪山东省省长，继续为日伪政权服务。；曾任伪山东省省长，协助日军统治山东，推行伪政，涉及潍坊、临朐地区。；北洋政客出身，1945年任伪山东省省长，继续维持日军在山东包括潍县、坊子地区的殖民统治，抗战胜利后被逮捕。；抗战期间任伪山东省长，为日军搜刮物资、征发劳工，在山东各地包括潍坊、诸城推行伪化统治。；抗战末期任伪山东省省长，继续维持日伪在山东的统治。；在山东伪政权中任要职，协助日军推行治安强化运动，波及烟台、海阳等胶东地区。；继马良之后任伪山东省省长，继续推行日军殖民政策，在聊城、东昌府等地强化治安、掠夺物资。；伪山东省长，继续在聊城、茌平地区推行伪化政策，镇压抗日活动。；继任伪山东省省长，继续在山东各地包括菏泽、定陶推行伪化统治，配合日军扫荡与物资掠夺。；继任伪山东省长，继续推行治安强化运动，在鲁西南包括菏泽、曹县地区强化伪政权和伪军建设。；抗战期间任伪山东省省长，为日军在山东实施殖民统治，在菏泽地区建立伪政权和伪军，征粮抓丁，配合日军扫荡。；继任伪山东省省长，继续推行日伪统治政策，支持日军对山东抗日根据地的扫荡，涉及青岛、即墨地区。；抗战末期任伪山东省长，继续为日军服务。；继唐仰杜后任伪山东省长，继续在山东包括青岛、崂山地区推行日军政策，搜刮物资。；出任伪山东省省长，参与日伪在山东的殖民统治与治安强化运动。；继马良任伪山东省长，继续推行日军政策，征发劳工、粮食。；继唐仰杜后任伪山东省省长，继续推行日军殖民政策，配合日军对胶东抗日根据地的扫荡。','省部级/大军区级要员','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('206483c25db54ab7bad810cb93f32430','dadbba2de38d401bbb1a41e5048c8ea2',1938,'伪威海卫特别行政区公署警察大队大队长','统领伪警察大队，配合日军在威海卫及周边地区进行治安肃正，抓捕抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e00d8afa72684e9091efb3533ae417fd','bd5cba57bd1846c89237f9e3ce03fb0e',1938,'伪威海卫维持会副会长','协助日军组织维持会，负责摊派粮款、招募伪职人员，为日军占领威海卫提供后勤支持。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d3a2ca59f04d455dbbce5549dc03942c','fd970e353c7a4171abfbe981a54193b3',1940,'伪文登县县长','任伪文登县长期间，配合日军对威海临港经开区一带进行扫荡，推行保甲连坐。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d0a102eed0f44e01b51dcb3a19de84f3','b2c19be7112c493a928de325ad0ad15c',1940,'伪荣成县县长','任伪荣成县长期间，协助日军控制威海东部沿海地区，征发民夫、物资。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c5e797b372344e578ad97abd02cfd64e','e52245c19301443fb3995b3718c42935',1940,'伪牟平县县长','任伪牟平县长期间，配合日军在威海临港经开区周边地区进行清乡、扫荡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1741cb1f6ac6467cbdd4a8777db32c8d','811fe999084946d8baee44410886b3e6',1931,'伪山东自治联军总司令、伪军头目','原名张宗昌之弟或日籍浪人化名，抗战期间在山东沿海包括威海一带收编土匪、组织伪军，配合日军进攻胶东抗日根据地，在威海及周边地区进行扫荡、征粮、抓丁。；原名张宗昌旧部相关伪军头目，抗战时期在山东沿海及胶东一带活动，参与组织伪军配合日军进攻胶东抗日根据地，其势力范围涉及威海、荣成周边地区。；日本特务机关扶植的伪军头目，在山东一带收编土匪、散兵组织伪军，配合日军进攻抗日根据地，活动范围涉及鲁北、德州周边。；原名张宗昌旧部相关伪军头目，抗战初期在山东一带组织伪军，配合日军进攻抗日根据地，活动范围涉及鲁西北、德州周边。；日本浪人出身，组织伪军配合日军进攻山东，活动于鲁北、德州一带，参与镇压抗日武装。；日本浪人出身，组织伪军配合日军在山东各地作战，活动范围涉及鲁西北及德州、禹城周边地区，参与镇压抗日武装。；日本浪人出身，化名张宗援，在山东组织伪军，配合日军进攻鲁北、鲁中地区，其部曾活动于淄博一带，参与镇压抗日武装。；原名张宗昌之弟或日籍浪人化名，抗战初期在山东组织伪军，配合日军进攻鲁中、鲁北地区，其部曾活动于淄博、张店一带，参与扫荡抗日根据地。；原名张宗昌旧部相关伪军头目，抗战时期在山东境内收编土匪、溃兵组成伪军，配合日军进攻鲁中、鲁北抗日根据地，活动范围涉及淄博、桓台周边地区。；原名张宗昌之弟，抗战期间在山东收编土匪、溃兵组成伪军，配合日军进攻鲁中、鲁南抗日根据地，在潍坊及周边地区进行扫荡、征粮、抓丁。；原名张宗昌旧部相关伪军头目，抗战时期在山东组织伪军，配合日军进攻鲁中、鲁南抗日根据地，活动范围涉及潍坊、临朐一带。；日本浪人出身，本名仓谷次太郎，冒充张宗昌之弟在山东组织伪军，率部配合日军进攻胶济铁路沿线，活动范围涉及潍县、坊子一带，后因与日军矛盾被处决。；原名张宗昌旧部相关伪军头目，抗战时期在山东境内组织伪军，配合日军进攻鲁中、鲁东地区，活动范围涉及潍县、寒亭一带，参与扫荡抗日根据地。；日本浪人出身，抗战初期在山东组织伪军，配合日军进攻胶济铁路沿线，活动范围包括潍坊、寿光一带，后因内部矛盾被日军处死。；原名张宗昌之弟或日籍浪人化名，抗战期间在山东组织伪军，配合日军进攻胶东、鲁中等地，活动范围覆盖潍坊及周边地区。；日本浪人出身，抗战初期在山东组织伪军，配合日军进攻胶济铁路沿线，活动范围涉及潍县一带。；原名张宗昌之弟张宗援，抗战期间在山东组织伪军，配合日军进攻胶东及鲁中地区，其伪军活动范围涉及潍坊、高密一带，参与扫荡抗日根据地。；日本浪人出身，化名张宗援，在胶东一带收编土匪、散兵组织伪军，配合日军进攻胶东抗日根据地，曾任伪山东自治联军总司令，在烟台、青岛等地活动。；原名张宗昌之弟或部属系统人物，抗战时期在山东沿海一带收编土匪、伪军，配合日军进攻胶东抗日根据地，活动范围涉及烟台、海阳周边地区。；原名仓谷次太郎，日本浪人出身，长期在山东胶东地区活动，组织伪军配合日军进攻烟台、蓬莱、黄县等地，参与建立伪政权，镇压抗日武装。；日本浪人出身，长期在山东胶东一带活动，组织伪军配合日军进攻烟台、蓬莱、黄县等地，1938年在胶东被抗日武装击伤后毙命。；原名仓谷次太郎，日本浪人出身，长期在山东活动，组织伪军配合日军进攻胶东抗日根据地，活动范围覆盖烟台、牟平一带。；原名张宗昌旧部相关伪军头目，抗战时期在山东胶东一带活动，收编土匪、伪军，配合日军进攻抗日根据地，活动范围涉及烟台、福山周边地区。；原名仓谷次太郎，日本浪人出身，长期在山东活动，组织伪军配合日军进攻胶东抗日根据地，在烟台、芝罘一带参与伪化统治与军事扫荡。；原名仓谷次太郎，日本浪人出身，抗战期间在山东组织伪军，活动于胶东及烟台、莱州一带，配合日军进攻抗日根据地，残害民众。；原名张宗昌旧部相关伪军头目，抗战时期在山东胶东一带收编土匪、伪军，配合日军进攻抗日根据地，活动范围涉及烟台、莱阳周边地区。；原名张宗昌之弟张宗援，抗战初期在山东胶东一带收编土匪、散兵组织伪军，配合日军进攻胶东抗日根据地，活动范围涉及烟台、蓬莱周边地区。；日本浪人出身，抗战初期在山东胶东一带收编土匪、散兵组织伪军，配合日军进攻烟台、龙口等地，参与建立伪政权。；日本浪人出身，冒充张宗昌之弟，在山东组织伪军，配合日军进攻鲁西、鲁北抗日根据地，活动范围涉及聊城、临清一带。；原名仓谷次太郎，日本浪人出身，长期在山东活动，组织伪军配合日军进攻胶东和青岛周边地区，参与对即墨、平度、莱阳等地的扫荡与镇压。；原名仓谷次太郎，日本浪人出身，抗战期间在山东收编土匪、散兵组织伪军，配合日军进攻胶东抗日根据地，活动范围涉及青岛、平度一带。；原名张宗昌之弟张宗援，抗战期间在山东投敌，组织伪军配合日军进攻胶东抗日根据地，活动范围涉及青岛、莱西周边地区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ad9f87229102447d99830beacb805310','b1e2c050fe6449ff84cb46f64f24d30e',1938,'伪暂编第十二师师长、国民党投降派兼伪军头目','原国民党鲁东军区部队，后公开投敌，盘踞胶东莱阳、海阳、即墨及威海周边地区，配合日军进攻八路军胶东根据地，在威海一带参与扫荡、抢粮、镇压抗日群众。；原国民党军将领，后投靠日军，盘踞胶东莱阳、海阳一带，多次配合日军扫荡胶东抗日根据地，对威海、荣成地区抗日力量构成威胁。；原国民党军将领，后率部投降日军，盘踞胶东莱阳、海阳一带，任伪暂编第十二师师长，多次配合日军扫荡胶东抗日根据地，残害抗日军民。；原国民党军将领，后投靠日军，盘踞胶东莱阳、招远一带，配合日军进攻抗日根据地，残害抗日军民。；原国民党军将领，后率部投降日军，盘踞胶东莱阳、栖霞、海阳一带，配合日军进攻八路军胶东根据地，残害抗日军民，1945年被八路军击毙。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dee61825bb224e2380f794c9cf6365ab','fabd450d8480433fb1634895d3c43510',1938,'伪山东国民自卫军第二师师长、伪军头目','在山东胶东地区组织伪军，活动范围涉及威海周边，配合日军对胶东抗日根据地实施封锁和扫荡，参与抓捕抗日人员、强征劳工。；在胶东地区组织伪军，配合日军扫荡，活动范围涉及烟台、平度、莱阳等地，参与维持会与保甲制推行。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0bf8bb8cb88c4279a5679dd05b921711','448d0f7cee64452499a7d23f73c33bbb',1938,'伪青岛特别市市长、伪政权官员','抗战期间在青岛及胶东地区附逆，担任伪职，协助日军维持占领区统治，其势力范围与威海地区有联系，参与经济掠夺和治安强化运动。；抗战时期在山东伪政权中任职，参与日伪统治，其活动范围涉及胶济铁路沿线，对潍坊、昌邑等地物资征调和伪化统治有间接影响。；抗战时期在山东伪政权中任职，参与日伪统治，其活动范围覆盖山东东部，与烟台、海阳地区伪政权有联系。；在日军占领青岛后出任伪职，协助日军维持统治，其活动范围覆盖胶东地区，与烟台伪政权有联系。；抗战时期在山东伪政权中任职，后任伪青岛特别市市长，参与日伪统治，其活动范围覆盖山东东部，与烟台地区伪政权有联系。；抗战后期在青岛附逆，任伪青岛市市长，协助日军维持山东东部占领区统治，其影响范围覆盖胶东烟台、莱阳周边区域。；抗战期间在青岛地区附逆，担任伪职，其活动范围涉及胶东地区，与烟台、蓬莱等地伪政权有联系。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bb664b0f894541ef94d52d26e6394be8','8376c3d3521140298ec1ac6d87bd32ef',1938,'伪青岛特别市市长、伪政权官员','在青岛及山东沿海地区为日军服务，推行伪化教育、经济统制，其管辖范围与威海地区有行政和军事联系，协助日军镇压抗日活动。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('88c1d8a84d984fcda0ac8da04d102ed4','8085e0e5fd8a4ece88f3b28d89e9760f',1938,'伪威海卫维持会会长、伪政权头目','日军侵占威海卫后，出面组织伪维持会，协助日军维持地方治安、征粮征款、登记户口，镇压抗日群众，是威海本地早期附逆代表人物。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('128504ab831642a4a334b3a44e93d173','e52245c19301443fb3995b3718c42935',1940,'伪威海卫特别区专员、伪政权官员','在威海卫伪政权中任职，配合日军推行保甲制度、治安强化运动，参与抓捕抗日人员、强征劳工和物资，为日军统治服务。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8595170d121749ef8be623eba98468c0','c552abc3b7b84cba89444280b9b4ad3a',1938,'伪威海卫警察局局长、伪警察头目','在威海卫伪警察系统任职，带领伪警察配合日军搜查、抓捕抗日人士，镇压群众抗日活动，维护日伪在威海卫的殖民统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e146352f9af0481e8305b375e9b1255e','fd970e353c7a4171abfbe981a54193b3',1938,'伪文登县维持会会长、伪政权头目','在文登及威海周边地区组织伪维持会，协助日军征粮、征丁、建立伪保甲，参与对胶东抗日根据地的封锁和扫荡。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e36eaad268b9490a885b4007ae3cface','40f92d8dcd244ed4b27495497bbc1c5c',1938,'伪牟平县维持会会长、伪军头目','在牟平及威海周边地区附逆，组织伪军和维持会，配合日军进攻昆嵛山抗日根据地，在威海一带参与扫荡、抢粮、抓捕抗日人员。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('22ece5fc7b0c46c5a76e16839ec50ae0','d8de220ca35b4b20b96fa8ae7fbf4674',1938,'伪荣成县维持会会长、伪政权头目','在荣成及威海沿海地区组织伪政权，协助日军控制沿海港口、征用民船、封锁抗日根据地，参与镇压当地抗日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9cc4edfa070f46b181d9b6abb941296c','fe7588d226fa430ea2eda3d08a162f2f',1938,'伪威海卫商会会长、经济附逆者','在威海卫为日军筹款筹粮，组织商户为日伪服务，协助日军实施经济统制，掠夺当地海产和物资，支持日伪统治。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3bfefd57a4d341c0aac0f2d00b7c139a','bd5cba57bd1846c89237f9e3ce03fb0e',1938,'伪威海卫教育科科长、文化附逆者','在威海卫推行奴化教育，编写和采用亲日教材，组织师生参加日伪宣传活动，为日军殖民统治培养顺民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('508d04f1f5094ce7a39e356a752a99ad','7e62cc93b19f491aafffea9ee4969692',1938,'伪威海卫新民会会长、文化附逆者','在威海卫组织伪新民会，宣传“大东亚共荣圈”，配合日军进行思想控制和奴化宣传，拉拢地方士绅附逆。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6a25fc6562974130a058357ad43de84c','bcce4eb13f2542e19c91f0327c0c5316',1938,'伪威海卫保安队队长、伪军头目','在威海卫组织伪保安队，配合日军维持治安、搜查抗日人员，参与对周边抗日根据地的扫荡和封锁。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1ba5379b9f5b4cb9929b0f1ded5b3505','15aba61e822c4e50a3d0ac9384c005f1',1938,'伪烟台市市长、伪政权官员','在烟台及胶东地区附逆，担任伪市长，协助日军统治烟台和威海周边地区，推行治安强化运动，参与经济掠夺和镇压抗日活动。','市县厅局级','hanjian');
