INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('77d78ca4b68d43bd84fd4fd3c4853b78','2170fa0658af47b6ab65f21d7d387c41',1938,'伪胶东道尹公署道尹、伪政权官员','在胶东道伪政权中任职，管辖范围包括威海地区，协助日军推行伪化政策、征粮征丁、封锁抗日根据地。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('00ca0e06990c41ceb4729a7771e736a6','17ba4ca514844dcbb95b21c193e11290',1938,'伪山东省政府委员、伪政权官员','在伪山东省政府中任职，参与制定和实施日伪在山东的统治政策，其政策覆盖威海地区，协助日军镇压抗日力量。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('30f3546945964f24b2f8ea05083dcc76','4ae43298968148da833d28b2f13c858d',1938,'伪山东省省长、伪政权头目','担任伪山东省省长，全面协助日军统治山东，推行治安强化运动、经济统制、奴化教育，其政令覆盖威海地区，对当地抗日力量进行镇压。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('08c75129d01c48ef8f288467899e78bb','bcce4eb13f2542e19c91f0327c0c5316',1938,'伪威海卫专员公署专员','抗日战争时期投靠日军，出任伪威海卫专员公署专员，协助日军维持威海卫及周边地区统治，推行伪化政策。','无明确职位或一般帮凶','hanjian');
