INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e48111a8d5e04585861e65f41ff1aca0','8085e0e5fd8a4ece88f3b28d89e9760f',1938,'伪威海卫维持会会长','日军侵占威海后组织伪维持会，任会长，协助日军征粮、征夫、维持地方治安，镇压抗日群众。；日军侵占威海卫后出面组织伪维持会，协助日军维持地方治安、征发物资，为日军统治威海地区提供支持。','基层维持会/地方自治头目','hanjian');
