INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f90c0966eeac43dfbed55ecbe238019f','811fe999084946d8baee44410886b3e6',1937,'伪山东自治联军副总司令','原名张宗昌旧部，日军侵占山东后投敌，率伪军配合日军进攻胶东，活动范围包括烟台、威海一带，参与镇压抗日武装。','基层头目','hanjian');
