INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1b4a3d02ee054f39a145d109affa4bc3','448d0f7cee64452499a7d23f73c33bbb',1938,'伪青岛市市长','抗战期间投敌，任伪青岛市市长，为日军在山东沿海地区推行伪化统治，其管辖范围与威海同属山东沿海，间接影响文登地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b34a1ca572cf46c5b26e8a6059c40599','8376c3d3521140298ec1ac6d87bd32ef',1938,'伪青岛市市长','投敌后任伪青岛市市长，协助日军在山东沿海进行经济掠夺和治安强化，与威海、文登地区同属山东沿海伪政权体系。；继赵琪后任伪青岛市长，协助日军在山东包括济宁地区的物资掠夺。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a311273ef96f4614a70b0e7ed4d43914','8085e0e5fd8a4ece88f3b28d89e9760f',1938,'伪文登县知事','日军侵占文登后出任伪县知事，建立伪政权和维持会，协助日军征粮、抓丁、镇压抗日群众，推行奴化教育。','基层头目','hanjian');
