INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3d4b5be07ae64ad1a8c3f918c535f193','1801590af35e42d9a7a11e8b64d7b871',1940,'伪文登县新民会会长','任伪文登县新民会会长，配合日军进行宣传、奴化教育，组织亲日团体，协助推行治安强化运动。','基层维持会/地方自治头目','hanjian');
