INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a41a4fd0252b4c6d8d1fff0d4f954047','8085e0e5fd8a4ece88f3b28d89e9760f',1938,'伪山东省政府委员、伪鲁东道尹','在山东伪政权中任职，参与推行日军在胶东地区的伪化统治，其辖区涉及威海一带。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('38fe5208df274c879202e8bd2def08df','b1e2c050fe6449ff84cb46f64f24d30e',1939,'伪剿共军胶东部队司令','原国民党地方武装，后投靠日伪，在胶东包括威海周边地区配合日军进攻抗日根据地，残害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('82d3d796ffb84ef9afc6f8c786b8e068','fabd450d8480433fb1634895d3c43510',1938,'伪山东剿共军第二路司令','在山东胶东地区投敌，组织伪军配合日军扫荡，活动范围涉及威海周边区域。；山东境内伪军头目，活动于鲁南、鲁中一带，配合日军进攻抗日根据地，与枣庄地区伪军有协同。；山东汉奸武装头目，其伪军活动于鲁南、济宁一带，配合日军扫荡抗日根据地。；在山东胶东地区组织伪军，配合日军进攻抗日根据地，活动范围涉及青岛、莱西周边。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e81abe6965224509b25fed59ec3ec7bf','e76c89aa3bac464887a41dbac4b6e4e1',1938,'伪山东省警务厅长','负责山东伪警察系统，协助日军镇压抗日活动，其警务体系涉及威海地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a305ee303d4e40f49526dd85b836c510','ca95eda6f9a048c9bb642e6f639b1e8f',1938,'伪威海卫海军基地伪军头目','日军占领威海卫后，在刘公岛一带组织伪海军及伪警察力量，配合日军控制威海沿海，镇压抗日活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e34581c9532e413f8cd247fe3e67de79','b2c19be7112c493a928de325ad0ad15c',1938,'伪荣成县维持会会长','日军侵占荣成后，出面组织伪维持会，协助日军征粮、征夫，维持伪政权统治，镇压当地抗日群众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cb7ae9d8556241ab915d294c9465dd57','fd970e353c7a4171abfbe981a54193b3',1938,'伪文登县维持会会长','在文登、威海一带组织伪维持会，配合日军统治，为日军提供情报和物资支持。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b0363fdc48d047ec882e31fa708e9488','da8e80b514ee4af39fb74cc139f6dd64',1938,'伪山东省公署委员、伪胶东道尹','伪山东省政权中负责胶东道事务，协助日军推行保甲制度、征发劳工，其管辖范围包括威海、荣成地区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b0e13655bfac45aca126349bcb38be4c','448d0f7cee64452499a7d23f73c33bbb',1938,'伪青岛特别市警察局局长（后投敌）','在青岛及胶东地区为日军效力，组织伪警察力量配合日军扫荡，其活动与威海、荣成地区抗日斗争有间接关联。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d2c0d6ebd8294abba78a263ff0bee34f','e8fd705bc4cd4d37a65c90810460019b',1938,'伪威海卫警察局局长','日军占领威海卫期间任伪警察局长，协助日军维持治安、抓捕抗日人员，镇压威海地区抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2991e281a897455ebe3a18902bc19f78','bcce4eb13f2542e19c91f0327c0c5316',1938,'伪荣成县知事','日军侵占荣成后出任伪县知事，推行伪政权政策，征粮征夫，协助日军控制荣成地区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9306112215aa4239abef3892622cb313','7e62cc93b19f491aafffea9ee4969692',1938,'伪荣成县教育科科长','在荣成推行奴化教育，篡改教材，宣传“大东亚共荣圈”，为日军文化侵略服务。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('031a688b66614a7b907fd375d514399a','9edb0275b4734a47805ca9385baed31a',1937,'伪山东省省长、伪济南维持会会长','济南沦陷后出面组织维持会，后任伪山东省省长，协助日军推行殖民统治、征粮征丁。；山东沦陷后投敌，任伪省长，推行日军政策，影响覆盖德州、武城等地。；山东沦陷后投敌，历任伪济南维持会会长、伪山东省省长，协助日军推行殖民统治、征粮征丁。；抗战期间投靠日军，历任伪济南维持会会长、伪山东省省长等职，协助日军推行殖民统治、征发劳役与物资，是山东伪政权核心人物之一。；抗战期间投靠日军，历任伪济南维持会会长、伪山东省省长等职，协助日军推行殖民统治、征粮征丁，镇压山东抗日力量。；抗战期间投靠日军，参与组织伪山东省政权，推行日伪统治，镇压抗日活动。；济南沦陷后出面组织伪维持会，后任伪山东省省长，协助日军推行殖民统治、征粮征丁。；济南沦陷后组织维持会，出任伪山东省省长，协助日军维持殖民统治，推行保甲连坐，镇压抗日活动。；济南沦陷后组织伪维持会，后任伪山东省省长，推行日伪统治，镇压抗日活动。；济南沦陷后出面组织伪维持会，后任伪山东省省长，协助日军推行殖民统治、征发物资与劳工。；济南沦陷后组织伪维持会，后任伪山东省长，推行奴化教育、配合日军征粮征丁，镇压抗日活动。；济南沦陷后组织伪维持会，后任伪山东省省长，协助日军推行殖民统治、征粮征丁。；济南沦陷后组织伪维持会，后任伪山东省省长，推行日伪政令，镇压抗日活动，为日军搜刮物资。；济南沦陷后组织维持会，出任伪山东省省长，协助日军推行殖民统治、征粮征丁。；抗战期间投靠日军，历任伪济南维持会会长、伪山东省省长等职，协助日军推行殖民统治、征发劳役与物资，镇压抗日活动。；山东汉奸代表人物之一，日军侵占济南后组织维持会，后任伪山东省省长，协助日军统治山东，镇压抗日力量。；山东早期伪政权头目，组织维持会，配合日军侵占山东各地，包括济宁地区。；济南沦陷后组织维持会，后任伪山东省长，推行伪化统治，其伪政权体系覆盖济宁地区，为日军征集粮食、劳工。；山东人，抗战初期在济南组织维持会，后任伪山东省省长，配合日军维持占领区秩序，镇压抗日活动。；组织济南维持会，后任伪省长，协助日军控制山东，包括济宁一带的伪政权建立。；济南沦陷后组织维持会，后任伪山东省长，协助日军维持山东沦陷区统治，影响波及淄博。；济南沦陷后组织维持会，后任伪山东省省长，协助日军维持占领区秩序，其伪政权影响覆盖淄博等地。；济南沦陷后组织维持会，后任伪山东省长，积极推行保甲制、奴化教育，其伪政权体系延伸至淄博、张店各县。；济南沦陷后组织伪维持会，后任伪山东省长，协助日军维持占领秩序，其伪政权体系延伸至淄博、桓台一带。；济南沦陷后组织维持会，后任伪山东省长，其伪政权体系覆盖淄博、沂源等地，协助日军维持占领秩序。；回族军阀出身，济南沦陷后投敌，历任伪济南维持会会长、伪山东省省长，协助日军推行保甲、征粮、清乡，其伪政权统辖范围包括潍县、坊子等地。；抗战期间投靠日军，参与组织伪山东省政权，任伪省长，推行日伪统治，镇压抗日活动。；抗战初期在山东组织维持会，后任伪山东省省长，协助日军维持占领区秩序，推行伪化政策，其伪政权影响波及烟台、栖霞地区。；抗战初期在山东组织伪维持会，后任伪山东省省长，为日军侵略山东服务，其伪政权体系延伸至烟台、福山地区。；在济南组织维持会，后任伪山东省省长，其伪政权体系延伸至烟台、芝罘等地，推行保甲制与奴化教育。；山东本地旧官僚，日军侵占山东后出面组织维持会，后任伪山东省长，协助日军统治山东，聊城、临清等鲁西地区在其伪省政权名义管辖下。；济南沦陷后组织维持会，后任伪山东省省长，协助日军稳定山东占领区秩序，其伪政权体系延伸至聊城、莘县地区。；日军侵占山东后率先组织维持会，后任伪省长，为日军筹款筹粮，劝降地方势力，影响波及鲁西聊城、阳谷等地。；济南沦陷后出面组织维持会，后任伪山东省长，推行伪化教育、征粮征丁，其伪政权政令覆盖聊城、高唐等鲁西北地区。；日军侵占济南后出面组织维持会并任伪山东省省长，为日军筹款筹粮、维持占领秩序，是山东沦陷初期主要汉奸之一。；山东人，抗战初期组织济南维持会，后任伪山东省省长，协助日军控制山东，在菏泽等地区建立伪政权，推行奴化教育，镇压抗日活动。；济南沦陷后组织维持会并任伪山东省省长，为日军在山东建立伪政权体系，其伪化政策覆盖菏泽、郓城等鲁西地区。；济南沦陷后组织维持会，后任伪山东省长，其伪政权影响波及青岛及崂山地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4497ab27dc7a46179ece408fb03079e6','e76c89aa3bac464887a41dbac4b6e4e1',1938,'伪山东省警务厅厅长、伪济南市市长','在山东伪政权中负责警务与市政，参与搜捕抗日人员、推行保甲连坐。','市县厅局级','hanjian');
