INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c4fafaa7ae5d4a3b9b2246c695ff50e4','c6df24aab02e4bbfb993cf6c0e5708c7',1937,'伪德州维持会副会长','协助成逸庵组织维持会，为日军进城提供便利，筹办粮秣。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('979eb7ef365541dcb50c5550f06d55ce','9edb0275b4734a47805ca9385baed31a',1938,'伪山东省省长、伪山东省公署省长','山东沦陷后投敌，历任伪济南维持会会长、伪山东省公署省长、伪山东省省长，协助日军推行殖民统治，在山东包括德州一带组织伪政权、征粮征丁。；抗战期间投靠日军，出任伪山东省省长，主持伪省政，推行日伪统治，镇压抗日活动，为日军掠夺山东资源服务。；抗日战争时期投靠日军，出任伪山东省省长，主持伪省政，推行治安强化运动，配合日军清乡、扫荡，镇压山东抗日力量。；抗战期间投靠日军，出任伪山东省省长，主持伪省政，推行日伪统治，镇压抗日活动，为日军掠夺山东资源、维持占领秩序服务。；抗战期间投靠日军，出任伪山东省省长，主持伪省政，推行日伪统治政策，在山东沦陷区包括德州一带协助日军维持治安、征粮征丁。；抗日战争时期投靠日军，出任伪山东省省长，主持伪省政，推行奴化教育与治安强化运动，为日军在山东包括德州、禹城一带的殖民统治服务。；抗战期间投靠日军，出任伪山东省省长，主持伪省政，推行日伪统治，镇压抗日活动。；抗战期间投靠日军，出任伪山东省省长，参与组织伪政权，推行日伪统治，镇压抗日活动。；抗战期间投靠日军，出任伪山东省省长，参与推行伪化统治、镇压抗日活动，为日军在山东的殖民统治服务。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0ecab2beccaf4d23a800f6cf561919c7','e76c89aa3bac464887a41dbac4b6e4e1',1938,'伪山东省公署民政厅厅长、伪山东省省长','曾任伪山东省公署民政厅厅长，后一度任伪山东省省长，参与山东伪政权建设，支持日军在德州地区的统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('03d68a93d3c04200a50d326e825f7304','6606ccaa567148ceac5f6381e52b66f8',1937,'伪德县县知事、伪德县县长','德州沦陷后任伪德县县知事/县长，组织维持会，协助日军维持德州城区及周边治安，征发民夫、粮食。','基层头目','hanjian');
