INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1736a601008448799504763cb97bf09d','794da95164184f74a08235220228dd72',1938,'伪临邑县维持会会长、伪临邑县县长','临邑沦陷后投敌，组织维持会并任伪县长，配合日军扫荡抗日根据地，推行保甲连坐。','基层维持会/地方自治头目','hanjian');
