INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d0c7660e8c9c41fd98b35ca9f626cf36','0994eab753184b9793af3c811589fe29',1940,'伪临邑县新民会会长','组织新民会进行亲日宣传，拉拢腐蚀抗日人员，配合日军推行治安强化运动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7964ce0e8e2a48d287b56305ab3a2e62','d6d76958ee164d75a29297b85ac0cbe2',1938,'伪山东省警务厅厅长、伪警察头目','在伪山东省政权中掌管警务，组织伪警察配合日军维持治安、搜捕抗日人员，镇压山东各地抗日力量。；在伪山东省政权中负责警务，建立和指挥伪警察力量，配合日军搜捕抗日人员、破坏中共地下组织，镇压山东沦陷区民众。；在伪山东省政权中负责警务，组织伪警察配合日军维持占领区秩序，镇压抗日群众，搜捕抗日人员。；在伪山东省政权中掌管警务，组织伪警察配合日军清乡、扫荡，镇压抗日群众，维护日伪在山东包括德州地区的统治。；在伪山东省政权中掌管警务，建立伪警察体系，配合日军在山东包括德州、禹城地区搜捕抗日人员、维持殖民治安。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b398e1de431f4109bc0c46be536220e1','eeb3c8c33a9044808ed5db66316ce87d',1938,'伪山东省政府委员、伪鲁北道尹','在伪山东省政权中任职，参与鲁北地区伪政权建设，配合日军推行治安强化运动，控制德州及周边地区。；在伪山东省政权中任职，负责鲁北地区伪政事务，德州、平原一带属其影响范围，协助日军推行保甲、征粮和治安强化。','无明确职位或一般帮凶','hanjian');
