INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('11308514911e45f0aa15e9cb8d0b0aef','59e05c0816384215a5591fdd4a3ee3ff',1937,'伪德县商会会长、伪维持会成员','德州沦陷后参与伪维持会，协助日军摊派捐款、物资，控制商会为日伪经济掠夺服务。；在德州沦陷后参与伪维持会，利用商会身份为日军筹集物资、摊派款项，协助日伪维持德州地方经济控制。','基层维持会/地方自治头目','hanjian');
