INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6e9408c8c8404a47b20d353309ef8378','23db8a4fdd2a40b181dab4df2f37ed3a',1938,'伪武城县县知事','在武城县（今属德州）任伪县知事，为日军筹集军粮，组织伪自卫团，对抗抗日武装。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5d34fc215f8d4c8e9eb6be8bf742f8aa','ab2d25921d5d4da8a66f286b4b95d71b',1939,'伪宁津县县知事','在宁津县（今属德州）任伪职，推行保甲制度，协助日军抓捕抗日人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9c395cf295e04d66b331391704611b96','1cf28c38810d40a2b8fcc073dca37926',1939,'伪庆云县县知事','在庆云县（今属德州）充任伪县知事，配合日军扫荡，掠夺物资，镇压抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('686d2f29e5e34bffaaabc16abfec57f8','0806580d2c7a479e84a3ccdbd55c1bd4',1937,'伪宁津县维持会会长、伪宁津县知事','抗日战争时期投靠日军，在宁津县组织伪维持会，后任伪县知事，协助日军征粮、派夫、清乡，镇压抗日群众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('de00946452a84afb8c80be5811629933','fd0c9d8f81764286b8c81443bd1d17d7',1938,'伪宁津县警备队队长','率伪警备队配合日军扫荡宁津及周边地区，抓捕抗日人员，催缴粮款，残害百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('263b8071ada345e3aa5b94029ec3edc3','d6e6fc2a3b6a4cf1bbfda66e265bbf1b',1937,'伪德县县知事','日军侵占德州后出任伪德县县知事，推行伪化统治，为日军筹集物资、修筑据点，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ccb8c69cc69c47b099aba7f770f55b88','d6d76958ee164d75a29297b85ac0cbe2',1938,'伪山东省鲁北道道尹、伪德县县长','在德州及鲁北地区充任伪职，协助日军推行保甲连坐，组织伪自卫团，配合日军对宁津、乐陵等抗日根据地扫荡。；在鲁北道及德州地区推行伪政，协助日军掠夺物资、镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c5b9b10a128f44248d2f2c6a5a0551ce','23db8a4fdd2a40b181dab4df2f37ed3a',1937,'伪德州维持会会长','德州沦陷后组织维持会，迎接日军入城，为日军筹办粮秣、夫役，维持伪秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('130ff383490045afb6c98fbc398a8d0d','fc93649ade4d496db9e57c903cc79baf',1938,'伪德县警备队队长','统领伪警备队在德州及邻近宁津地区进行清乡、扫荡，捕杀抗日军民，勒索民财。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b9db0f70742c4f18b6bec780655a352c','11a53228a1f04138b78497d7c99cffe7',1939,'伪宁津县保安团团长','组织伪保安团配合日军守备队进攻宁津抗日根据地，烧毁民房，抢掠牲畜，杀害抗日干部家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('26dd680e116c4b469501ffcf961593e7','c3702032be8b4960bd9759a5e3a67635',1940,'伪宁津县新民会会长','在宁津推行奴化教育，宣传“大东亚共荣”，组织伪青年团，协助日军进行思想控制和经济掠夺。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dfad39854e1a4bc7a4da9c342be4f210','c1daa171e05746d383d93806c90f6027',1938,'伪山东省警务厅厅长','统管山东伪警察，在德州、宁津等地部署伪警力，配合日军扫荡，搜捕抗日人员，实施恐怖统治。；统管山东伪警察，指挥济宁等地伪警搜捕抗日人员，推行保甲连坐。；掌管山东伪警察系统，在聊城、莘县等地建立伪警察所与保甲自卫团，配合日军清乡、搜捕抗日人员。；掌管伪山东警察系统，在聊城、高唐等地建立伪警察所、训练伪警，参与搜捕抗日人员、维持伪统治秩序。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3e7de0925db94c86bb29494b8e75cf36','4036712021a049238796d20c60e1f434',1938,'伪山东省鲁北道道尹','在鲁北道（辖德州、宁津等）推行伪化行政，组织伪自卫团，协助日军掠夺棉花、粮食等物资。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a4d9e3c4cea74aeb97c43d2a42c4fd5e','59e05c0816384215a5591fdd4a3ee3ff',1937,'伪德县商会会长','在德州为日军筹款筹粮，控制物资流通，配合经济封锁，压榨商户和百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9c50ba0fb7e14fa484ed10cad9472358','5d820a5b2b114c0e8312a21493c45d60',1939,'伪宁津县警察所所长','带领伪警察在宁津城乡搜捕抗日人员，刑讯逼供，勒索钱财，无恶不作。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4c6c228cfc2045a693829eb92aa76ae8','df4ac79bd5494ff9b25803f1ffee94c7',1940,'伪德州新民会指导部部员','在德州、宁津等地进行奴化宣传，组织伪合作社，配合日军经济统制，毒化民众思想。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3ae553cbf6c44a8982d71719fac2e7d9','c6df24aab02e4bbfb993cf6c0e5708c7',1941,'伪宁津县保甲长','担任宁津县某区保甲长，为日军催缴粮款、派送劳工，监视村民行动，告发抗日家属。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f043316b3a8044f4beb9ce3e5b33b90d','811fe999084946d8baee44410886b3e6',1937,'伪军头目、伪山东自治联军总司令','日本特务机关扶植的伪军头目，在山东一带收编土匪、散兵组织伪军，配合日军进攻抗日根据地，活动范围涉及鲁西北、德州周边。；日本特务机关扶植的伪军头目，在山东一带收编土匪、散兵组织伪军，配合日军进攻抗日武装，活动范围涉及鲁北、德州周边。；在山东地区组织伪军，配合日军进攻抗日根据地，参与扫荡和镇压抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5d8f46148a2a441b9270ec731eee9d41','926a397c6e23463bab0fd82d55673a7c',1937,'伪德县维持会会长、伪德县县长','日军侵占德州后出面组织维持会，后任伪德县县长，为日军筹粮筹款、维持地方伪秩序，协助日军控制德州城区及周边。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('60fd1eee89e34787aa7d38168a1b648d','11a53228a1f04138b78497d7c99cffe7',1937,'伪平原县维持会会长','日军侵占平原后组织伪维持会，为日军征粮、征夫、维持地方秩序，协助日伪建立基层伪政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('625658566581470bace38b4a18bc52bb','0806580d2c7a479e84a3ccdbd55c1bd4',1938,'伪平原县县长','任伪平原县县长期间，推行日伪政令，配合日军清乡、征粮、抓丁，镇压当地抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ba93cca8c5594a4a81bbc3b58025d971','77ec9a468e544a669a0b82755353ccc0',1938,'伪鲁北道道尹、伪德县县长','在鲁北道伪政权中任职，管辖包括德州、平原在内的鲁北地区，协助日军推行治安强化运动和地方伪政。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('10800153bf764602afc81834c04f10ac','fabd450d8480433fb1634895d3c43510',1938,'伪山东保安第二师师长、伪军头目','在山东东部及北部一带组织伪军，配合日军扫荡抗日根据地，残害抗日军民。；原为土匪，后投靠日军，在诸城、安丘、高密、潍县一带活动，配合日军扫荡抗日根据地，残害百姓，1945年后被国民党收编。；在诸城、安丘、高密、昌邑一带活动，先依附国民党地方势力，后投靠日军，所部伪军配合日军扫荡，抢粮抓丁，镇压抗日群众，是潍坊地区较有影响的伪军头目之一。；在诸城、高密、安丘一带组织伪军，投靠日军，配合日军扫荡抗日根据地，杀害抗日干部和群众。；在胶东及鲁东地区组织伪军，投靠日军，任伪山东保安第二师师长，在烟台、平度、莱阳等地配合日军进攻抗日武装。；在山东胶东地区组织伪军，活动于烟台、栖霞周边，配合日军扫荡抗日根据地，抢掠民财，镇压抗日群众。；在山东胶东及鲁东南地区活动，投靠日军后任伪军师长，配合日军进攻抗日根据地，1945年后被国民党收编。；在山东胶东地区组织伪军，投靠日军，配合日军对烟台、福山等胶东地区进行扫荡和清乡。；在山东胶东地区组织伪军，活动于烟台、莱州周边，配合日军清乡扫荡，镇压抗日力量。；在山东东部投敌，所部伪军配合日军扫荡胶东抗日根据地，参与对莱阳、烟台周边地区的清乡和掠夺。；在山东胶东地区组织伪军，配合日军对烟台、龙口周边抗日武装进行清剿，控制地方伪政权。；在山东诸城、胶州一带活动，先投敌后任伪军头目，配合日军扫荡并残害地方抗日力量。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1bd6d14903e3494c9c37bf4903f55f1e','7556fd1f8b1f4180927b6356b214e742',1938,'伪山东保安第三师师长','长期在山东寿光、广饶一带活动，后投靠日伪，配合日军扫荡，残害抗日人员。；盘踞寿光、广饶一带，后投敌，配合日军在胶东边缘地区扫荡，残害百姓。；在山东寿光、广饶一带组织伪军，后扩展势力至胶东地区，配合日军进攻八路军抗日根据地。；原国民党地方武装，后投敌，盘踞鲁北、鲁西，配合日军进攻抗日根据地，活动范围接近聊城、临清。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('406eacb66c0048dd91de154d86eb64b7','54d0d8a0c40f422189d5ca735fd90204',1938,'伪军头目、伪鲁北保安司令','在鲁北地区组织伪军，配合日军控制德州、平原周边交通线和乡村，参与清乡、扫荡。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b58fa7d561414791ad08f5b709764e7b','b7c1d146417145fd81df206e77765c9b',1938,'伪德平县县长','德平邻近平原、德州，任伪县长期间推行日伪政令，征粮征丁，协助日军维持地方统治。','基层头目','hanjian');
