INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0be32b88056347949583c90956891d0b','d3241d6c3d8f48c8af4fbc6b8565cbd9',1938,'伪临邑县县长','临邑属德州地区，任伪县长期间协助日军征粮征丁，推行保甲制，镇压抗日活动。','基层头目','hanjian');
