INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('64ffcde2788f4ea9b7a9cd49f5acd3dd','5d820a5b2b114c0e8312a21493c45d60',1938,'伪德县知事','任伪德县知事期间推行保甲连坐，配合日军经济封锁与治安强化运动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8033910c96514c0ea4d31f58975f72d7','e76c89aa3bac464887a41dbac4b6e4e1',1938,'伪山东省警务厅厅长','统管山东伪警察，在德州、武城等地编练伪警，参与清乡与搜捕抗日人员。；负责伪山东警务，在潍县等地建立伪警察体系，镇压抗日活动。；在山东组织伪警察，配合日军搜捕抗日人员，活动范围涉及潍坊、高密等地。；掌管山东伪警察系统，在菏泽等地建立伪警察网络，镇压抗日活动。；掌管伪山东警察系统，参与搜捕抗日人士、破坏中共地下组织，协助日军维持占领区治安。；掌管山东伪警察系统，参与搜捕抗日人员、破坏中共地下组织及协助日军维持占领区秩序。；在伪山东省警务系统任职，参与组织伪警察力量，镇压山东抗日军民。；在伪山东省政权中负责警务，参与镇压抗日力量。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('73d5545f2d3d4fa5a32672e432843f71','4036712021a049238796d20c60e1f434',1938,'伪山东省新民会会长','在山东包括德州地区推行新民会奴化教育，组织宣传亲日思想。；主持山东伪新民会，在济宁等地推行亲日宣传和奴化教育。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7e3476a95bde43c1a220b5b427b56dc0','8dd71bba0484426388d6dbcfae15bd52',1938,'伪青岛市市长、伪山东省政府委员','山东伪政权要员，参与日军在山东的统治政策，间接影响德州地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d0d22e6e3f484ab189453d5bd0d57644','811fe999084946d8baee44410886b3e6',1937,'伪山东自治联军总司令','率伪军配合日军进攻山东各地，包括鲁北德州一带，烧杀抢掠。；组织伪军配合日军进攻山东抗日根据地，在济南及周边地区活动。；在山东包括济南、长清一带收编土匪、组建伪军，配合日军作战。；日本浪人出身，组织伪军配合日军进攻山东抗日武装，活动于胶济铁路沿线及潍坊地区。；率伪军配合日军进攻鲁西抗日根据地，在聊城、阳谷一带进行扫荡，烧杀抢掠。；率伪军配合日军在山东各地进行扫荡，包括菏泽、东明一带，镇压抗日武装，残害百姓，为日军侵略效力。；组织伪军配合日军进攻山东抗日武装，在胶东、青岛周边地区进行扫荡与清乡。；组织伪军配合日军在山东各地进攻抗日武装，活动范围涉及胶东、青岛周边地区。；日本浪人出身，组织伪军配合日军进攻山东，在青岛及胶东地区活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('833fe9505f4842dca6bee02ca5ab8d2f','177c17b9b440453fa41ed47b9ebbd502',1937,'伪军司令、伪和平救国军师长','匪伪结合，活动于鲁北、鲁西包括德州武城周边，配合日军扫荡，残害百姓。；率部在鲁南、济宁、邹县一带活动，先降日后又反复，配合日军扫荡，残害百姓。','市县厅局级','hanjian');
