INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('82aa0c1cf72049948c4955315d9d4985','dd6b6cda46c04c109fd14e65881d73fb',1938,'伪军头目（后反正）','曾在华北伪军系统中任职，活动于山东北部，后率部反正；其附逆期间与德州地区有联系。；原国民党将领，曾与伪军有联系，活动于华北，与陕西渭南地区有间接关联。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ce8a016a7c9f472fb693e6320f3ee714','811fe999084946d8baee44410886b3e6',1938,'伪山东自治联军副总司令、伪日照县知事','原名张步云，山东诸城人，抗战初期投靠日军，组织伪军配合日军进攻日照、莒县等地，曾率部侵占日照县城并出任伪日照县知事，推行伪化统治，抓捕抗日人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fd834cc988cb4112b64130706529f3b5','fbe95b8f1ab448f3bb9f58546b05be91',1938,'伪日照县维持会会长','日照县城沦陷后出面组织维持会，为日军筹粮筹款、拉夫带路，协助日军建立伪政权，维持地方伪秩序。；日军侵占日照后出面组织维持会，为日军筹粮筹款、拉夫修路，协助建立伪政权。','基层维持会/地方自治头目','hanjian');
