INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a3796befaf5448519d5be1bac6217643','177c17b9b440453fa41ed47b9ebbd502',1938,'伪和平建国军第三方面军总司令','惯匪出身，抗战期间投靠日军，率部在鲁南、日照、莒县一带活动，配合日军扫荡，残害抗日群众，后于1943年被八路军击毙。','省部级/大军区级要员','hanjian');
