INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cf0e73b3a1824b91b8ec0fadd542f854','5254fb64d6f844c79e97b5a20665ca57',1937,'伪滨海警备军司令','盘踞诸城、日照、胶南一带，配合日军对滨海抗日根据地进行扫荡，残害百姓。；在胶东及滨海地区组织伪军，活动范围包括高密、胶县、诸城等地，配合日军进攻抗日根据地。','基层头目','hanjian；traitors');
