INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('279c9e829db943789b4eb141c354c8d9','fabd450d8480433fb1634895d3c43510',1938,'伪山东国民自卫军第二师师长、伪滨海警备军司令','原为土匪武装，抗战期间投靠日军，盘踞诸城、日照、莒县一带，配合日军扫荡滨海抗日根据地，残害抗日军民，在日照及周边地区活动频繁。；原为土匪武装，后投靠日军，在诸城、日照、五莲一带活动，配合日军扫荡抗日根据地，残害抗日军民。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1b702f54029d45c7aa032f2089e4a962','5254fb64d6f844c79e97b5a20665ca57',1939,'伪滨海警备军副司令、伪日照县保安大队长','投靠日军后长期在日照、诸城、胶南一带活动，率伪军配合日军对滨海根据地进行扫荡，抓捕杀害抗日人员，横征暴敛。；在日照、五莲地区组织伪军，配合日军进行清乡、扫荡，镇压抗日力量。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c70f2b146d304cc0bb9d342f1d83b76e','fbe95b8f1ab448f3bb9f58546b05be91',1938,'伪日照县知事、伪日照县维持会会长','日军侵占日照后出面组织维持会，出任伪县知事，协助日军推行保甲制度、征粮征夫，镇压抗日活动。；日军侵占日照后出面组织维持会，后任伪县知事，为日军征粮、征夫，推行奴化教育。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('196f420e23764dc09a49e885f4fbeac2','e82a1a41eb0e4a19b6f2959237e561e7',1939,'伪日照县警察所所长','在日照地区充任伪警察头目，配合日军搜捕抗日人员，勒索百姓，维持日伪统治秩序。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ec35e874e1974a6880c47cc10a68e2d7','7d3a7da67468411990dd8aac12be7529',1940,'伪日照县保安队队长','率伪保安队在日照东港及周边地区配合日军行动，参与扫荡、清乡，迫害抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('39cd452f178f44a48dc5eab1e6a536de','811fe999084946d8baee44410886b3e6',1937,'伪山东自治联军司令','日本特务机关扶植的伪军头目，在山东沿海包括日照地区活动，收编土匪武装，配合日军控制沿海地区。；日本浪人出身，长期在山东活动，组织伪军配合日军进攻日照、岚山等沿海地区，参与扫荡抗日根据地。；率伪军配合日军进攻山东，活动于济南、商河一带。；率伪军在济南及山东各地配合日军作战，进攻抗日根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('40bdf2cb60c74623a2e05914059adaca','076d4f7f3b874037ba3d21cd5b1e1283',1938,'伪日照县东港区维持会会长','在东港地区组织维持会，为日军筹集物资、提供情报，协助日军管理地方。','基层维持会/地方自治头目','hanjian');
