INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('68c35bc5d07543df8c8b41a5664f30aa','e42da0879cbd4aaf921586baab0c198c',1939,'伪五莲县维持会会长','在五莲地区组织维持会，协助日军建立伪政权，搜捕抗日人员。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aa4a2bcddac54b1ba3749a1319ffef6c','177c17b9b440453fa41ed47b9ebbd502',1937,'伪和平救国军第三方面军司令','土匪出身，投靠日军后活动于鲁东南包括日照、五莲一带，配合日军扫荡，烧杀抢掠。；土匪出身，投敌后率部在鲁南、鲁东南包括日照、莒县一带流窜，配合日军扫荡，烧杀抢掠。；著名土匪汉奸，投靠日军后活动于鲁南、济宁周边，烧杀抢掠，袭击抗日武装。；著名土匪汉奸，活动于山东各地包括潍坊南部，配合日军扫荡，1943年被八路军击毙。；土匪出身，投靠日军，活动于山东、河北交界地带，包括聊城周边，烧杀抢掠，配合日军扫荡。','基层头目','hanjian');
