INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('297f97b94a274adbb1d7caee0441a1a0','5254fb64d6f844c79e97b5a20665ca57',1939,'伪滨海警备军司令、伪日照县长','盘踞日照、诸城、胶南一带，任伪日照县长期间推行保甲连坐，配合日军清乡扫荡，镇压抗日群众。','基层头目','hanjian');
