INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('51dec3e416db475181e99b70ebbc499c','5254fb64d6f844c79e97b5a20665ca57',1940,'伪滨海警备军司令（活动于日照、莒县、诸城沿海地区）','盘踞日照、莒县东部沿海，为日军搜集情报、封锁海岸，袭击抗日武装，1945年被八路军歼灭。','基层头目','hanjian');
