INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d22f2768caa14c288a1f1995adf0f55e','15aba61e822c4e50a3d0ac9384c005f1',1941,'伪日照县新民会会长','在日照推行奴化教育，组织亲日团体，为日军搜集情报。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6cfac45a7ad24cfd93419cdf4ec75151','9693a17603c84c99901937ab07933712',1938,'伪峄县警备队队长、伪军头目','抗战期间投靠日军，在枣庄、峄县一带组织伪军，配合日军扫荡抗日根据地，残害抗日军民。；抗战期间在枣庄峄县一带组织伪军，配合日军扫荡抗日根据地，残害抗日军民，控制枣庄部分煤矿区。；抗战期间在峄县及枣庄一带组织伪军，配合日军扫荡抗日根据地，残害抗日军民，控制枣庄煤矿周边地区。；抗战期间在枣庄、峄县一带组织伪军，配合日军扫荡鲁南抗日根据地，残害抗日军民，控制枣庄矿区周边地区。；抗战期间在枣庄、峄县、薛城一带组织伪军，配合日军扫荡抗日根据地，残害抗日军民，是鲁南地区较有影响的汉奸武装头目之一。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('00e725baa62844d69cc2f60db45494b6','48823033c05149a695bdcf859710cc93',1938,'伪峄县维持会会长','日军侵占枣庄后出面组织维持会，为日军筹粮筹款、维持伪秩序，协助推行殖民统治。；日军侵占枣庄后出面组织伪维持会，为日军筹粮筹款、拉夫，协助建立伪政权。；日军侵占枣庄、峄县后出面组织维持会，为日军筹粮筹款、拉夫，协助建立伪政权，维持日伪在枣庄地区的统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7dd1990464ab44c7a2fd81c5cfdd1762','5c5cb2ed1d154c1086863b507e70114f',1939,'伪枣庄矿区警察所所长','在枣庄煤矿区充任伪警察头目，镇压矿工反抗，配合日军掠夺煤炭资源。；在枣庄煤矿区充当伪警察头目，镇压矿工反抗，抓捕抗日人员，配合日军经济掠夺。；在枣庄煤矿区为日军管理矿工，镇压工人反抗，抓捕抗日嫌疑人员，配合日军经济掠夺。','无明确职位或一般帮凶','hanjian');
