INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3c16ec15a8d1488b9dd4b60d9354e3aa','3fcfa73a208547969c91611154e4f66e',1937,'国民党地方武装头目，后投敌','原为山东地方武装首领，活动于鲁南、枣庄、临沂一带，抗战中后期与日伪勾结，所部部分投敌，配合日军对付八路军和地方抗日力量。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('010bf1d647d24039849ea3078b876c53','1f8eba63c91140febd4802304d747e35',1938,'伪军头目、国民党顽固派武装首领','在鲁南临沂、枣庄、费县一带活动，后与日伪合作，进攻抗日根据地，残害抗日群众，其武装在抗战后期具有明显附逆性质。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7ab11b962039457889327a1428469c6a','30ce61bce3b94c0db98fa9508345e79c',1938,'伪滕县县长','日军占领滕县后，出任伪滕县县长，在滕县、枣庄北部一带协助日军建立伪政权，推行保甲、征粮、抓丁等政策。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('113159c31c80428395806cc9920c1e6c','9d4020f9caa443b1b80ea357ec80aadf',1938,'伪峄县维持会会长','日军侵占峄县后，参与组织维持会，任会长，在峄县、枣庄、薛城一带为日军筹粮筹款、维持地方伪秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a48e49c6ee584a35811583356fc1a0e4','16acf465455e4354986b1a6027c263c3',1939,'伪军军官','在鲁南枣庄、峄县一带充任伪军军官，配合日军扫荡，袭击抗日武装，镇压当地民众抗日活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2cd6af90e44441769946663e5cff5e26','26aee8405e0b4bff86e7da705091275a',1938,'伪临城警察所头目','在临城（今枣庄薛城）一带担任伪警察头目，协助日军控制铁路沿线，盘查行人，抓捕抗日嫌疑人员。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1b5c62b3fd0b4c67bb5277713423873b','f64531e1c7554edb9219473b57045b70',1938,'伪保长、维持会成员','在枣庄、薛城地区担任伪保长、维持会成员，为日军征粮派款、搜集情报，协助日伪维持基层统治。','基层帮凶(维持会系统)','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('35a5883fecda4be0a89d13aca717ffb1','e76c89aa3bac464887a41dbac4b6e4e1',1938,'伪山东省省长、伪泰安道尹','曾任伪泰安道尹、伪山东省省长，在泰安地区推行伪化教育、征发劳工。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c94d1110ea2741b5bf5a26dfc7c6369e','c1daa171e05746d383d93806c90f6027',1938,'伪泰安道尹','任伪泰安道尹期间，协助日军维持泰安及周边地区治安，推行保甲连坐。；抗战时期任伪泰安道尹，驻泰安，管辖包括泰安、岱岳一带的伪政权事务，协助日军维持占领区秩序、征发物资。；抗战时期任伪泰安道尹，管辖泰安、新泰等地区，推行伪政，为日军征集物资、劳工，镇压当地抗日活动。；日伪在泰安设立伪道尹公署，朱经古等伪道尹负责泰安及周边地区的伪政权事务，配合日军扫荡、征粮和治安强化运动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('774d6be6b0b74ed19d58998241d13646','d1e97c8db7a1426e98f85bf32313d5d4',1938,'伪泰安县知事','泰安沦陷后任伪县知事，为日军征粮、征夫，镇压当地抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5e83ab00d86546948e92e1a927e1bd98','797c553510f3440f88255e16480f23b4',1937,'伪泰安县维持会会长','日军侵占泰安后组织维持会，为日军筹粮筹款、维持地方伪秩序。；抗战初期在泰安组织维持会，迎接日军进城，协助日军建立伪政权，维持地方治安，压迫百姓。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dabbb5b1d8dd475cb15f99ffd3f6b5d6','d6d76958ee164d75a29297b85ac0cbe2',1938,'伪山东剿共军司令','在泰安、济南一带组织伪军配合日军扫荡，进攻抗日根据地。；组织伪军配合日军在山东包括淄博地区进行剿共、扫荡，残害抗日军民。；在鲁中地区组织伪军，活动范围包括淄博、张店，配合日军对抗日根据地进行蚕食扫荡，残害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c04551fa4fd442e4b65426993a51dac2','fabd450d8480433fb1634895d3c43510',1938,'伪山东保安军司令','活动于鲁中、泰安周边，率伪军配合日军清乡，残害抗日军民。；原为土匪，投敌后任伪军头目，活动于鲁中、鲁南地区，配合日军进攻淄博周边抗日根据地。；在山东胶东地区投敌，组织伪军配合日军扫荡，活动范围涉及烟台周边，残害抗日军民。；原为土匪，投靠日军后任伪军头目，在山东诸城、青岛一带活动，残害百姓，攻击抗日武装。；在山东东部组织伪军，配合日军扫荡抗日根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('666d32fd0d844a6bb261fa05dc955991','b1e2c050fe6449ff84cb46f64f24d30e',1938,'伪山东第十三区专员兼保安司令','在鲁东及泰安周边地区与日军勾结，进攻八路军，后公开投敌。；盘踞胶东，但与济南伪政权有联系，配合日军反共。；在胶东及鲁中地区投敌，其部队在淄博、张店一带配合日军作战，进攻抗日武装。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5fb369a38e004cd093dd7402be04c524','5f288d2b1f2a40b7863a25e30e61b7c4',1938,'伪山东保安第一师师长','在鲁中、泰安一带活动，后投敌任伪职，配合日军扫荡抗日根据地。；山东伪军头目，活动于鲁中、济南周边，协助日军扫荡抗日根据地。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0008aa87879641fa9ab1b6bc8bf4bb61','86370f4da9bc48adad6691aeeed3543f',1938,'伪泰安道公署顾问、伪山东省政府参议','协助日军在泰安地区推行殖民政策，参与伪政权决策。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('95d9119374fa44b4bd6c34bfb86119cd','448d0f7cee64452499a7d23f73c33bbb',1938,'伪泰安县警察局局长','任伪警察局长期间，搜捕抗日人员，维持泰安城区伪治安。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9b895a4b517348638fed2f1875a58ade','ddf8985b133549c9a4590901a5905ad7',1938,'伪泰安县教育科科长','在泰安推行奴化教育，篡改教材，宣传“大东亚共荣”。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7e1b8c7ba11943dd9979bbaa08c7b05a','dcbd3f11b08444478257060e7b77424f',1938,'伪泰安县商会会长','为日军筹款筹物，协助经济统制，压榨泰安商民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5ad617b49b864dbb9c59461929712efd','0a71e37726884338bdc803653aefbb92',1938,'伪泰安道保安队队长','率伪保安队配合日军扫荡泰安周边抗日根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c365c89771724014bdb6dc7a9afbc292','8428849b87d9490cb77a5fc92c1aaabc',1938,'伪泰安道剿共队队长','在泰安、莱芜一带捕杀抗日干部和群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('43ef332892ba465da3f9c20b6a83dd2a','01fc41d607e441439f77c52dd85bd2ae',1938,'伪泰安县新民会会长','组织新民会进行亲日宣传，协助日军控制泰安民众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('44e9e95fa866435190689c6acc9da7d5','15a53deac38b4a38bb911a125d119e5c',1938,'伪山东省新民会副会长','在山东包括泰安地区推行新民会运动，进行奴化宣传。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9b2bff46442c467185c1c0dbeb690fa4','eeb3c8c33a9044808ed5db66316ce87d',1938,'伪山东省警务厅厅长','统管山东伪警察，在泰安等地实施治安强化运动，镇压抗日。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('28b5d79bef0740e4bf278199ea841db6','fe10aebe651c4e6b9d2d4cb4945326c8',1938,'伪东平县维持会会长、伪东平县知事','日军侵占东平后出面组织维持会，后任伪县知事，为日军征粮派款、维持伪政权统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8058757537684cfb8df59b45817f0cf5','d647af638d6840ceb2aa1a711532eb26',1939,'伪东平县警备队队长','协助日军清乡扫荡，统领伪警备队配合日伪军进攻抗日根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('28fca539d4954a70a5ec7a1fabda2a53','0a71e37726884338bdc803653aefbb92',1938,'伪泰安道尹公署道尹','任伪泰安道最高行政长官，推行日军殖民统治政策，统辖泰安、东平等县伪政权。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0481a0da78494fc4866d55a4025b4a7b','f045370dce7245978dc41b47ba690cd4',1938,'伪泰安县知事','在泰安县城组织维持会并任伪县长，为日军筹粮筹款、镇压抗日民众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bab6386c9b1045f2ade39a4226c92a6f','4687429622ee4bb2a686e55ca9cb8bef',1939,'伪泰安县警备大队大队长','率伪军配合日军对泰安、东平一带抗日根据地进行扫荡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('896709c311744eda8d831f95c27f2178','c1daa171e05746d383d93806c90f6027',1938,'伪山东省公署省长','任伪山东省长，推行日军‘治安强化运动’，统辖全省伪政权，包括泰安、东平地区。；作为山东伪政权最高头目，推行日军殖民政策，督令各道县征粮、征兵、清乡，镇压山东抗日军民。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9f60904e3a4946869a58ad3179a53b48','4ae43298968148da833d28b2f13c858d',1940,'伪山东省公署省长','继任伪山东省长，继续为日军搜刮物资、维持殖民统治。；继金寿良后任伪山东省省长，继续在山东包括济宁、兖州地区推行日伪统治，征粮征丁，镇压抗日力量。；继任伪省长后继续为日军搜刮物资、强征劳工，配合日军对山东抗日根据地的扫荡。；接替张宗援任伪山东省长，配合日军在山东推行保甲连坐、经济统制，搜刮民财，镇压抗日根据地。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2d0cd9e30f39447094e4c064b52e2d84','9edb0275b4734a47805ca9385baed31a',1938,'伪山东省公署省长（早期）','曾任伪山东省长，参与组织山东伪政权，影响波及泰安、东平地区。；济南沦陷后出面组织伪山东省公署，任伪省长，为日军在山东包括菏泽地区建立伪政权体系。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a63eae7abf28430491642161f55c2ef3','4036712021a049238796d20c60e1f434',1938,'伪山东新民会指导部部长','在山东包括泰安、东平地区推行奴化教育，组织新民会协助日军控制民众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e0347e14a4ca44a7934bd1cc5b4c039e','797c553510f3440f88255e16480f23b4',1940,'伪东平县新民会会长','在东平推行奴化宣传，配合日军进行思想控制和经济掠夺。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('23697a120fb94370b15623da18a0ddac','b907b671631e4f9791da7d7393bea3aa',1941,'伪东平县保安团团长','统领伪保安团在东平境内配合日军扫荡，捕杀抗日人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('08aba2ee029a4a6da92692493763ab25','8dc17a3c81f84795af50c8e88858ec67',1939,'伪泰安道新民会会长','在泰安道所属各县包括东平推行新民会运动，进行奴化教育。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cce2b040ca0c420eb9d3cc8251c0daf6','e76c89aa3bac464887a41dbac4b6e4e1',1938,'伪山东省省长、伪新民会山东总会会长','投敌后任伪山东省省长等职，利用新民会等组织进行奴化宣传，协助日军控制山东沦陷区。；抗战时期投敌，任伪山东省省长及伪新民会要职，协助日军进行宣传、奴化教育与物资掠夺。；投靠日军后任伪山东省省长等职，参与组织伪新民会，进行亲日宣传与殖民统治，影响覆盖淄博一带。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d1a02eeddd494737ba3fd7bbeed496d4','2994abf4d5f94828a7c8432e77840e2a',1938,'伪泰安道尹、伪泰安县长','日军侵占泰安后投敌，历任伪泰安道尹、伪泰安县长等职，负责泰安及周边地区的伪政权运作，为日军征粮、征夫、维持治安。；在泰安地区为日伪政权效力，参与维持会与伪县政，协助日军控制泰山周边地区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('41572d5f610e4a70879de580d9d7a50f','d1e97c8db7a1426e98f85bf32313d5d4',1938,'伪泰安县维持会会长','泰安沦陷后组织伪维持会，协助日军维持地方秩序、摊派物资，是泰安早期伪政权代表人物之一。；泰安沦陷后组织维持会，为日军筹粮、派夫、维持地方秩序，协助伪政权建立。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fe826c8d670944678552599e75401d9d','9ad49cb1edd1406b892c9eb1bbdc1fb3',1938,'伪宁阳县知事/伪宁阳县长','宁阳沦陷后投靠日军，出任伪宁阳县知事、县长等职，配合日伪在宁阳地区推行保甲、征粮、抓丁和清乡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2d021d527a064e78b3fdefa633aaf3ae','fe7588d226fa430ea2eda3d08a162f2f',1938,'伪宁阳县维持会会长','在宁阳组织伪维持会，协助日军建立基层伪政权，为日军筹粮筹款、搜集情报。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4826109f8654449faf245ddbdef857b8','d6d76958ee164d75a29297b85ac0cbe2',1938,'伪山东保安总队/伪军头目','抗战期间在山东投敌，组织伪军配合日军扫荡抗日根据地，活动范围涉及泰安、宁阳周边地区。','无明确职位或一般帮凶','hanjian');
