INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dae5328b52604311bc5bbacd935344f6','01fc41d607e441439f77c52dd85bd2ae',1938,'伪军头目','在泰安、宁阳一带组织伪军，依附日军，参与对抗日根据地和游击区的进攻与掠夺。；在山东淄博、莱芜一带活动，组织伪军配合日军扫荡。','无明确职位或一般帮凶','hanjian');
