INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1631547a46e24bb39219d2f2e1e0037c','b1e2c050fe6449ff84cb46f64f24d30e',1938,'伪军头目、国民党投降派','在山东胶东及鲁中地区活动，后与日伪勾结，配合日军进攻抗日根据地，其势力与泰安、宁阳周边伪军有联系。；原国民党军将领，后投靠日伪，在山东胶东及鲁中一带活动，所部伪军配合日军进攻抗日根据地，残害抗日军民。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('30ad497f078d484689c73c70278a5a95','fabd450d8480433fb1634895d3c43510',1937,'伪军头目','山东伪军头目之一，投靠日军后在鲁中、鲁南一带活动，配合日军扫荡，与泰安、宁阳地区日伪势力有呼应。；山东伪军头目之一，活动于鲁中、鲁南地区，配合日军扫荡，抢掠民财，镇压抗日力量。；在山东诸城、日照、淄博边缘地区活动，后投敌任伪军师长，参与扫荡。；山东人，抗战期间投靠日军，组织伪军，在华东地区进行伪化统治。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('886a9293fd61417dae3248b102fa74b2','177c17b9b440453fa41ed47b9ebbd502',1937,'伪军头目、土匪','著名土匪，抗战期间投靠日军，率部在山东泰安、宁阳、费县、蒙阴等地活动，配合日军扫荡抗日根据地，残害百姓。；著名土匪，抗战期间投靠日军，在山东鲁中、鲁南一带活动，配合日军扫荡，残害百姓和抗日人员。','无明确职位或一般帮凶','hanjian');
