INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('924820027a2e42429df6ef85b7d12217','8428849b87d9490cb77a5fc92c1aaabc',1938,'伪军头目','山东地方伪军头目，在泰安、肥城周边地区活动，协助日军征粮、抓丁、扫荡抗日根据地。；在山东中部依附日军，参与对章丘、济南周边抗日武装的镇压。；在山东鲁中地区包括淄博周边投日，组织伪军协助日军控制交通线和乡村。','无明确职位或一般帮凶','hanjian');
