INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f8c6ea69a71c46ca957465998b88f226','2994abf4d5f94828a7c8432e77840e2a',1937,'伪济南市市长','济南沦陷后任伪市长，负责市政、警察与保甲事务，协助日军控制济南城区。；济南沦陷初期任伪市长，组织伪政权，为日军服务。；济南沦陷时期长期任伪济南市市长，负责市政、警察与保甲事务，配合日军镇压抗日群众。；济南沦陷初期任伪市长，组织伪政权，协助日军维持治安。；济南伪市政首脑之一，协助日军管理城市、控制粮食配给、镇压抗日分子。；任伪济南市市长期间，配合日军实施保甲制，镇压抗日群众，征收苛捐杂税。；济南沦陷后任伪市长，维持殖民统治，配合日军经济统制与保甲连坐。；济南沦陷后任伪济南市市长，主持伪市政，配合日军统治济南地区。；济南沦陷初期任伪市长，组织维持会，为日军筹粮筹款。；任伪济南市市长，配合日军管理济南市区，推行保甲、配给与奴化教育。；济南沦陷后任伪济南市市长，协助日军管理城市，推行保甲制，镇压抗日活动。；济南伪市政首脑，协助日军维持城区秩序、搜捕抗日人员。；长期担任伪济南市市长，配合日军管理济南市区，推行保甲、配给与奴化教育。','市县厅局级','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('54562387ebac48e69686568816f9722c','625ad52c67854ba6bab154fb0e53fbd6',1937,'伪济南市商会会长','组织商界附逆，为日军筹款筹物，配合经济统制。；在济南为日军筹款筹粮，组织商界附逆，支持日伪经济统制。；协助日军统制济南工商业，强制摊派物资，为伪政权筹款。；任伪济南商会会长，为日军筹款筹粮，控制经济，协助日伪物资统制。；组织商界附逆，为日军筹措物资、摊派款项。','基层头目','hanjian');
