INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7489eec2e8cb4835b9852fcc4b21cd29','9edb0275b4734a47805ca9385baed31a',1938,'伪山东省省长、伪华北政务委员会委员','山东主要汉奸之一，历任伪济南维持会会长、伪山东省长，推行日伪政令，镇压抗日活动，济宁地区伪政权受其管辖。；山东沦陷后投敌，任伪省长，支持日军在济宁等地的统治，推行保甲连坐，搜捕抗日人员。；山东伪政权头目之一，协助日军统治山东，其政令覆盖济宁、泗水等县。；曾任伪山东省长，协助日军统治山东，参与治安强化运动，镇压抗日根据地。；曾任伪山东省长，在山东包括鲁北惠民、滨州地区推行伪化政策，协助日军掠夺资源，镇压抗日力量。；山东人，投靠日军，历任伪山东省长等职，在山东推行保甲制度、治安强化运动，配合日军扫荡，其伪政权覆盖潍坊、诸城地区。；曾任伪山东省省长，在山东包括菏泽地区推行伪政，协助日军维持占领秩序，镇压抗日活动。；山东沦陷后投敌，任伪山东省长等职，协助日军推行治安强化运动、征粮征工，镇压山东抗日根据地。','省部级/大军区级要员','hanjian');
