INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c9ee69a00c664b8ba27796a6ab4f6536','8f551835027d47d8a72a3185f6ccbc2f',1943,'伪和平救国军第十军军长','原国民党军将领，1943年投敌，任伪军长，活动于鲁南、济宁地区，配合日军扫荡。；原为国民党军将领，投敌后率伪军在山东鲁西、鲁南一带配合日军作战，残害抗日军民。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0aced21f3ba9470eb594dd5193055b3a','6c7a932fd30546f68c97803bbee70a1f',1938,'伪济宁道保安队队长','任伪济宁道保安队长，率伪军协助日军在济宁各县清乡、抓丁、征粮。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b336bb6af3e349569068c5759c7f4689','b9cf4fcd08454d86876971409cfc1a52',1939,'伪微山湖水上警察局局长','控制微山湖水上伪警察，检查过往船只，抓捕抗日交通员，封锁湖区抗日联系。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f6a7f8c417594333b75967d1da3ec0b6','a23958f2a093468d8476a9eec1ddb6a8',1937,'伪河北省省长、伪华北政务委员会要员','华北汉奸，其伪政权体系与山东相邻，参与日军对山东资源的掠夺与伪化统治协调。；北洋旧官僚，抗战期间投敌，任伪河北省省长等职，属华北伪政权高层，其伪政权体系对河南北部及豫东部分地区有影响。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4986387f2500402cb61eed4a048383a9','bbc7d2d2f1174918a3a12cc3ce766af2',1937,'伪北平维持会会长、伪华北政务委员会委员','华北汉奸，其维持会模式影响山东各地伪维持会建立，间接支持济宁等地伪政权。；华北伪政权早期人物，参与维持会与伪政权，其影响涉及华北包括河南北部。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cfca66d71ccc4be3980894e60e09a580','8f1dd12e548b4c4f866dd743c3377896',1937,'伪华北政务委员会委员长、伪内政总署督办','华北著名汉奸，参与组织伪临时政府，后任伪华北政务委员会委员长，协助日军在华北包括山东地区推行治安强化运动与经济掠夺。；安徽人，北洋政客，抗战期间投敌，任伪华北政权要职，其伪政权管辖范围包括河南北部，推行保甲、征粮、奴化教育。；安徽合肥人，北洋政客，抗战期间投敌，任伪华北政务委员会要职，推行日军殖民统治政策，其伪政权管辖范围包括河南北部，对河南沦陷区民众进行压迫与掠夺。；安徽合肥人，但在伪华北政权中负责河南等沦陷区政务，推行奴化教育、征粮征丁，其伪政权体系覆盖河南周口、淮阳等地，属华北汉奸首脑之一。；安徽合肥人，北洋旧官僚，抗战期间投敌，任伪华北政务委员会委员长等职，其伪政权统治范围覆盖河南北部及部分豫东地区，推行奴化教育与经济掠夺。；投靠日本，参与伪华北政权，推行奴化教育与经济掠夺政策，其伪政权体系对陕西等华北地区有渗透影响。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e5f168dc489543b5bb80f3df6813d465','c1daa171e05746d383d93806c90f6027',1938,'伪济宁道尹、伪济宁县知事','日伪时期在济宁地区任职，负责伪政权地方行政，协助日军维持济宁及周边地区统治。','基层头目','hanjian');
