INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fd40171334d94e62b83115cd137591ee','7556fd1f8b1f4180927b6356b214e742',1938,'伪山东保安第三师师长、伪军头目','原国民党地方武装，后投靠日军，盘踞寿光、广饶、桓台一带，配合日军扫荡清河区抗日根据地，残害抗日军民。；在寿光、潍县及胶东一带组织伪军，投靠日军，任伪山东保安第三师师长，配合日军进攻抗日根据地。；盘踞寿光、平度一带，后投靠日军，配合日军进攻胶东抗日根据地，残害百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('87691c34fcce40ca9e833acac09c5d08','cef80a2fc690455aab49a06859a36d09',1938,'伪军头目、伪博兴县长','在鲁北、淄博北部一带组织伪军，配合日军进攻清河抗日根据地，活动范围接近桓台、博兴地区。','基层头目','hanjian');
