INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e642f1c0bca84712a0d980a0336113db','fabd450d8480433fb1634895d3c43510',1937,'伪军师长、土匪头目','在鲁中、鲁东南地区活动，投靠日军任伪军师长，其部曾窜扰淄博、沂源一带，配合日军扫荡抗日根据地。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('be21f0236aed46b899e6acfb40915dac','527b33cbf97f4907b567ab193092180f',1938,'伪淄川县知事、伪淄博维持会头目','任伪淄川县知事，在淄博淄川地区建立伪政权，推行保甲，协助日军掠夺煤炭，镇压抗日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('86a0c6b581bb4f3dba5579a172f64e9e','2c9d695c38da4be8be19b5a5b59c6baf',1938,'伪益都县知事、伪淄博周边伪政权头目','益都与淄博、沂源相邻，其伪政权活动覆盖淄博东部和沂源北部，组织维持会，配合日军扫荡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('343f5cdcd15f4636ae2398deea3d19f8','54d0d8a0c40f422189d5ca735fd90204',1938,'伪山东保安第二师师长','在鲁北地区投敌，组织伪军配合日军扫荡抗日武装。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c9aee4d780344efa8b53ca080ea2bcb7','8dd71bba0484426388d6dbcfae15bd52',1938,'伪青岛特别市市长','长期担任伪青岛市长，协助日军管理青岛，推行殖民统治。；抗日战争时期任伪青岛特别市市长，在胶东地区配合日军进行殖民统治。；青岛沦陷后出任伪市长，协助日军维持殖民统治，推行奴化教育，配合经济掠夺。；青岛沦陷后出任伪市长，协助日军维持殖民统治，在青岛及即墨周边推行保甲连坐、物资统制等政策。；长期担任伪青岛市长，配合日军经济掠夺与治安强化运动，镇压抗日活动。；抗战期间投靠日军，出任伪青岛特别市市长，协助日伪维持青岛地区殖民统治，推行伪化政策。；早年曾任青岛商埠督办，抗战爆发后投敌，出任伪青岛特别市市长，协助日军维持殖民秩序。；1938年日军占领青岛后出任伪市长，主持伪政权，配合日军征粮、征工，镇压抗日活动，管辖范围包括胶州。；抗战期间投靠日军，出任伪青岛特别市市长，协助日伪维持青岛地区殖民统治，推行伪化行政。；抗日战争期间投靠日本，出任伪青岛特别市市长，协助日军维持殖民统治，推行伪化政策。','特别市市长','hanjian');
