INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5093350305dd4d6d9f0472ae1b689215','69acc0909f544a318cf03fc20bac4c6a',1941,'伪博兴县警备队小队长','博兴县伪警备队骨干，驻守博兴城关据点，多次随日军下乡扫荡，烧毁民房，杀害抗日干部家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bd768ffd97c948a2bc16834280000fb9','7556fd1f8b1f4180927b6356b214e742',1938,'伪山东省保安第五旅旅长、伪山东第十四区行政督察专员兼保安司令','原为国民党地方武装首领，后率部投敌，盘踞寿光、广饶、博兴、蒲台、利津、滨县、惠民一带，配合日军进攻清河抗日根据地，捕杀抗日军民，横征暴敛。；原为国民党地方武装首领，后率部投敌，盘踞寿光、广饶、博兴、滨县、沾化一带，配合日军进攻清河抗日根据地，捕杀抗日军民，横征暴敛。；原为国民党地方武装首领，后率部投敌，盘踞寿光、广饶、博兴、蒲台一带，配合日军扫荡清河抗日根据地，在滨州及周边地区征粮抓丁、残害抗日军民。；原为国民党地方武装首领，后率部投敌，盘踞寿光、广饶、博兴、邹平一带，配合日军扫荡抗日根据地，残害抗日军民。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f30f10713acc4647afa4accb56bf9429','391e57c9623843dea409722f3754920e',1939,'伪山东保安第六旅旅长、伪滨县县长','在滨县、惠民、阳信、沾化一带组织伪军，配合日军扫荡，镇压抗日群众，控制徒骇河沿岸地区。；在滨县、沾化、利津一带组织伪军，配合日军扫荡清河区，杀害抗日干部和群众，强征民夫修筑据点。；在滨县、蒲台、利津一带组织伪军，控制黄河下游沿岸地区，为日军搜集情报、修筑据点，参与对清河区抗日根据地的蚕食和扫荡。；在滨县、蒲台、利津一带组织伪军，控制黄河下游沿岸，配合日军对清河区进行蚕食扫荡，残害抗日军民。','基层头目','hanjian');
