INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e50c94d9704049f7b978e9237d427959','08cf2daf57624bc0bd6648341fc817bd',1941,'伪山东保安第十旅旅长','盘踞滨县、蒲台、利津地区，与日军勾结，袭击抗日武装，掠夺民财。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1228bd86b9ab4a4b86f1d5de58a989c4','23db8a4fdd2a40b181dab4df2f37ed3a',1939,'伪滨县教育科科长','在滨县推行奴化教育，编写亲日教材，组织学生参拜神社，宣传“大东亚共荣”。','基层头目','hanjian');
