INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('07e4c5d3897b44648094227dec938d6f','dcbd3f11b08444478257060e7b77424f',1939,'伪滨县警察局局长','在滨县及阳信边界地区搜捕抗日人员，实施保甲连坐，镇压民众反抗。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e5983e749aa34b1389f86a3990835062','5f288d2b1f2a40b7863a25e30e61b7c4',1938,'伪山东保安总司令、伪潍县县长','原国民党山东省第八区专员，1943年率部投敌，任伪山东保安总司令，驻潍县，配合日军扫荡胶济铁路沿线抗日武装，残害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cf6058ef86594b4288a40a3c68d6c577','fabd450d8480433fb1634895d3c43510',1938,'伪山东保安第二师师长、伪诸城县长','盘踞诸城、安丘、高密一带，先投日军后任伪军师长，在潍坊南部地区烧杀抢掠，配合日军进攻八路军滨海、鲁中根据地。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e00c18a89d314453833fc4c421e0aee0','54d0d8a0c40f422189d5ca735fd90204',1938,'伪山东保安第三师师长、伪昌邑县长','在昌邑、潍县北部活动，投敌后任伪军师长，控制沿海盐场，为日军掠夺物资，镇压抗日群众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('32da516f003f4651842ab7ac08906691','b1e2c050fe6449ff84cb46f64f24d30e',1938,'伪山东保安暂编第十二师师长、伪莱阳县长','虽主要活动于胶东莱阳，但与潍坊地区伪军有协同，曾配合日军扫荡胶济铁路东段，在潍坊东部边缘地区亦有骚扰。；原国民党军投敌，盘踞胶东莱阳一带，配合日军进攻八路军，残害抗日军民。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('00c34af40e2944118cdfd860f2ca3571','448d0f7cee64452499a7d23f73c33bbb',1938,'伪青岛特别市市长、伪山东保安副总司令','原国民党青岛市党部委员，投敌后任伪青岛市长，控制胶济铁路东端，与潍坊地区伪政权有行政、经济联系，协助日军掠夺物资。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8a4002fe10b048c68dad0377cf695168','4036712021a049238796d20c60e1f434',1938,'伪潍县维持会会长、伪潍县县长','潍县本地士绅，日军占领潍县后出面组织维持会，后任伪县长，为日军征粮、征夫，推行奴化教育。；潍县沦陷后出面组织维持会，后任伪潍县县长，协助日军管理潍县及坊子地区，推行保甲连坐、征粮征工。；在潍县组织维持会，投靠日军，协助建立伪政权，推行保甲制度，镇压抗日群众。；日军侵占潍县后组织维持会，后任伪县长，为日军征粮征夫，推行奴化教育，协助日军镇压抗日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('86b3e26e2a6c4e54bdd1e167adba3d0a','908606fc16e74846b2bc83393e20f446',1938,'伪潍县警察局局长','在潍县城区及周边村镇搜捕抗日人员，镇压群众反抗，配合日军进行治安强化运动。；潍县本地人，投靠日军后任伪警察局长，镇压抗日群众，搜捕抗日人员，直接参与潍县地区的日伪统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cdfcd0a50c4941e59576cecaaabfbd8d','5b44553f0f3d4c968ef9e277302ce9ff',1938,'伪潍县商会会长','控制潍县工商业，为日军筹集军需物资，强制商户纳捐，协助日军经济统制。；潍县商人，投靠日军后任伪商会会长，为日军征集物资，协助经济统制。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('31c97463d1de4e1a857e94ad0dc30039','73a8c2a55bd7454e8652e1e311780a5b',1938,'伪益都县维持会会长、伪益都县长','在益都（今青州）组织维持会，后任伪县长，为日军征集粮食、劳工，镇压抗日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c49b09fe4ec34a0189017c197b216462','fd7e6da58d8947c58019b131b53be340',1939,'伪寿光县县长','在寿光推行保甲连坐，配合日军扫荡清水泊抗日根据地，残害抗日家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('feb841065dce4bf8bcc77da7e6b5ac01','7556fd1f8b1f4180927b6356b214e742',1938,'伪山东保安第十五旅旅长、伪寿光县长','盘踞寿光、广饶一带，投敌后任伪军旅长，多次配合日军进攻八路军清河区根据地。；山东寿光人，抗战期间投敌，任伪职，盘踞寿光、潍县北部，配合日军进攻抗日武装，活动范围覆盖潍坊北部。；原国民党地方武装头目，后投靠日军，任伪职，活动于寿光、潍县、寒亭北部沿海地区，配合日军进攻清河抗日根据地。；原国民党寿光县长，后投靠日军，任伪职，在寿光、潍县一带活动，配合日军扫荡，1945年后被国民党收编。；盘踞寿光、广饶一带，后投靠日军，控制潍坊北部沿海地区，配合日军对清河区、滨海区进行扫荡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dce00796d8be4303889db5e115161ba3','d6d76958ee164d75a29297b85ac0cbe2',1938,'伪临朐县县长','在临朐推行治安强化运动，配合日军扫荡沂山抗日根据地，制造无人区。','基层头目','hanjian');
