INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6cb14a400e154b8489e34bf31269e260','fabd450d8480433fb1634895d3c43510',1937,'伪山东自治联军第二路司令、伪军头目','山东诸城人，抗战初期投敌，组织伪军盘踞诸城、安丘、高密一带，配合日军扫荡，残害抗日军民，活动区域邻近潍坊奎文。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3e6d0cd72d884c0389bc32ec30f4746d','5f288d2b1f2a40b7863a25e30e61b7c4',1938,'伪鲁东和平建国军司令、伪潍县县长','原国民党山东省第八区专员，1943年公开投敌，任伪鲁东和平建国军司令，盘踞潍县、昌乐、安丘等地，配合日军进攻八路军，直接活动于潍坊地区。；原国民党山东省第八区专员，1943年公开投日，任伪鲁东和平建国军司令，盘踞潍县、昌乐、安丘等地，配合日军进攻八路军，1945年被俘。；原国民党山东省第八区专员，1943年公开投敌，任伪鲁东和平建国军司令，盘踞潍县、安丘一带，配合日军扫荡抗日根据地。；原国民党游击部队将领，后投敌，任伪鲁东和平建国军司令，盘踞潍县、安丘、昌乐一带，配合日军扫荡抗日根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2d45e28c3243446487db9a51d268f4ac','08cf2daf57624bc0bd6648341fc817bd',1938,'伪潍县维持会会长','潍县本地人，日军侵占潍县后出面组织维持会，为日军筹粮筹款、维持伪秩序，直接服务于潍坊奎文一带的日伪统治。；潍县本地士绅，日军占领潍县后出面组织维持会，为日军筹粮筹款，协助建立伪政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('346c7eaa9f994731a976ecb2eb6456f0','5b44553f0f3d4c968ef9e277302ce9ff',1938,'伪潍县商会会长、伪政权经济附逆者','潍县商人，抗战期间与日伪合作，控制潍县商会，为日军征集物资、推行伪币，在经济领域附逆，活动于潍县城区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('41eb5a3c7adc4268b79e57d75c6dd6d0','06c36f3a19fe4c9a913b99dd4cf1f2df',1938,'伪益都县县长、伪政权官员','山东益都（今青州）人，投敌后任伪县长，在益都、临朐一带推行伪政，配合日军征粮抓丁，活动区域邻近潍坊。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b8c81ffa7b96446cbd9760b9d5e4fe23','177c17b9b440453fa41ed47b9ebbd502',1937,'伪山东自治联军第三路司令、伪军头目','绰号刘黑七，山东平邑人，投敌后任伪军司令，流窜山东各地包括潍坊一带，配合日军扫荡，烧杀抢掠。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bc41034eba9b40ff9244035a66d1a042','8085e0e5fd8a4ece88f3b28d89e9760f',1938,'伪昌乐县县长、伪政权官员','山东昌乐人，投敌后任伪县长，在昌乐、潍县一带推行伪政，为日军征集物资，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('98ca0def328d4f1cb106c6f2d16fdc85','91d839cb8f3a4466ad45fa333d208f70',1938,'伪昌邑县县长、伪军头目','山东昌邑人，投敌后任伪县长兼伪军头目，在昌邑、潍县北部活动，配合日军扫荡抗日根据地。；在昌邑、高密一带组织伪政权和伪军，配合日军进攻抗日根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5cc2208786f34cfd8ff753725c7b8c37','1bfef426d4f248868334c1aee43ef54f',1938,'伪安丘县维持会会长','安丘本地人，日军侵占安丘后组织维持会，为日军筹粮筹款，维持伪秩序，活动区域邻近潍坊奎文。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4581623e6f154f90b0d5a314bfe31e99','fabd450d8480433fb1634895d3c43510',1938,'伪山东剿共军第二路司令、伪和平建国军第三方面军暂编第一军军长','山东诸城、安丘、高密一带著名伪军头目，先投日军，后编入伪和平建国军，长期在潍河两岸配合日军扫荡抗日根据地，残害抗日军民。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9fc08127c7bc44109905a1d92b9cdba7','5f288d2b1f2a40b7863a25e30e61b7c4',1938,'伪鲁东和平建国军司令、伪山东省政府委员','原国民党山东省第八区专员兼保安司令，1943年率部投敌，所部盘踞潍县、安丘、昌乐一带，配合日军进攻八路军，后任伪鲁东和平建国军司令。；原国民党山东省第八区专员，后率部投日，在潍坊、安丘、诸城一带组织伪军，配合日军扫荡鲁中、滨海抗日根据地。','基层头目','hanjian');
