INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7566f22d3d1b40af9a122eaa90e6bdc4','0643fe38e7a5477e80f330958da84e34',1938,'伪山东省公署教育厅厅长','在山东沦陷区推行奴化教育，篡改教材，宣传“中日亲善”，毒害青年学生。；在伪山东省公署任职，推行奴化教育，在聊城、东昌府等地学校强制使用日伪教材，宣传“大东亚共荣”。','市县厅局级','hanjian');
