INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9850cd5a45454d32a55ce43fd1f4c506','1bfef426d4f248868334c1aee43ef54f',1938,'伪潍县警察局局长','在潍县掌管伪警察，参与搜捕抗日人员，推行保甲连坐，镇压民众反抗。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('451fea9441164d98995412418d3b1721','b1e2c050fe6449ff84cb46f64f24d30e',1938,'伪剿共军总司令、国民党投降派兼伪军头目','原国民党地方武装首领，后投靠日军，在胶东及潍坊东部一带活动，所部多次配合日伪进攻抗日根据地，残害抗日军民，对昌邑、平度、掖县周边地区造成严重破坏。；原国民党军将领，后投靠日军，在胶东地区组织伪军，活动于平度、高密、胶县一带，配合日军进攻八路军，残害抗日军民。；原国民党军将领，后投靠日军，盘踞胶东莱阳、莱州、烟台一带，组织伪军配合日军扫荡抗日根据地，鱼肉百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6950e9f25b3e43f28bf1defedcdd2c69','5f288d2b1f2a40b7863a25e30e61b7c4',1938,'伪山东保安总司令、伪潍县县长相关伪政权头目','原国民党山东省第八区专员兼保安司令，后率部投日，在潍坊及周边地区组织伪政权和伪军，配合日军扫荡鲁中、胶东抗日根据地，对昌邑、潍县、安丘一带抗日力量进行镇压。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7e089b6dc9854d0585d8a39aac878d4c','54d0d8a0c40f422189d5ca735fd90204',1938,'伪军头目、国民党投降派','在鲁东及潍坊地区活动，后投靠日伪，参与组织伪军和维持会，配合日军对昌邑、潍县、平度交界地区进行清乡和扫荡。；在胶东地区率部投敌，任伪军司令，配合日军扫荡莱阳、烟台周边抗日根据地，残害百姓。；在胶东平度、莱阳一带活动，后投敌任伪军职务，配合日军扫荡抗日根据地。；在胶东地区投敌，组织伪军配合日军扫荡，活动于莱阳、莱西、即墨一带。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4b408463872a4a1bb33d736c87d49f64','9edb0275b4734a47805ca9385baed31a',1938,'伪山东省省长、伪政权官员','曾任伪山东省省长，协助日军建立伪政权体系，推行伪化教育、保甲连坐和物资统制，对潍坊及昌邑地区伪政权建立有推动作用。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('53be7db6ad67413fba1fa95246f5b91b','2994abf4d5f94828a7c8432e77840e2a',1938,'伪山东省警务厅厅长、伪警察头目','在伪山东省政权中负责警务，建立伪警察系统，配合日军在潍坊、昌邑等地搜捕抗日人员、镇压群众，推行治安强化运动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('447da301ae604d57a40de03e54e948d4','4036712021a049238796d20c60e1f434',1938,'伪潍县维持会会长、伪政权头目','在潍县组织维持会，协助日军维持地方伪秩序，征粮派款，压迫民众，其活动直接影响昌邑、潍县周边地区。','基层维持会/地方自治头目','hanjian');
