INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c3b3c1d7c44b40dca26bb9853e867b96','0dcbb0d4404e42c08f31747aad9778bd',1938,'伪平度县县长、伪军头目','在平度及昌邑周边地区组织伪政权和伪军，配合日军扫荡，镇压抗日力量，对昌邑西部有直接影响。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('31930aea58bf48439cd1735bb8f4f361','bf09837695814bdc909bf536d932d291',1938,'伪胶济铁路警务段段长、伪警察头目','负责胶济铁路沿线伪警务，在潍坊、昌邑附近车站参与搜查、逮捕抗日人员，保障日军运输，镇压铁路沿线群众。','无明确职位或一般帮凶','hanjian');
