INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7fd0bc9bcc6a4fce9c5b25446e6abaef','8dd71bba0484426388d6dbcfae15bd52',1938,'伪青岛市市长、伪政权官员','在青岛伪政权任职，参与日伪统治，其经济统制和物资征调政策影响胶济铁路沿线包括潍坊、昌邑地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d8c3ddaea4f5491aa66ae9ad21e57377','8376c3d3521140298ec1ac6d87bd32ef',1938,'伪青岛市市长、伪政权官员','抗战时期在青岛伪政权中任职，推行日伪经济统制，协助日军征调物资，对山东包括潍坊、昌邑地区经济掠夺有间接作用。；在山东伪政权中任职，活动于青岛及周边胶东地区，为日军殖民统治服务。','市县厅局级','hanjian');
