INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6123d33842e74eeabdd71d4c070b2430','448d0f7cee64452499a7d23f73c33bbb',1938,'伪青岛特别市市长、伪山东省政府委员','抗战期间附逆，在山东伪政权中任职，参与日伪统治，推行奴化教育，协助日军征发劳工和物资，其活动范围覆盖山东多地包括烟台地区。；抗战期间投敌，任伪青岛市市长，在山东沿海地区推行伪政，与烟台、芝罘等地伪政权有联系，协助日军经济掠夺。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('980c74c4a0c24c939ba5ba5f545035bd','2994abf4d5f94828a7c8432e77840e2a',1938,'伪烟台市市长、伪烟台维持会会长','在烟台地区组织伪维持会，后任伪烟台市市长，直接配合日军统治烟台及周边栖霞等地，征发劳工、物资，镇压抗日活动。；在烟台市区组织维持会，后任伪烟台市市长，直接负责芝罘地区的伪政权运作，协助日军征收物资、镇压抗日活动。','基层维持会/地方自治头目','hanjian');
