INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b62d96dc85ed493781f177964c3a6eb9','cf3960d9803c4c2383b50eff9d1b49a1',1938,'伪烟台警察局局长','在烟台任伪警察局局长，协助日军维持治安，搜捕抗日人士，镇压烟台及栖霞周边地区的抗日活动。','市县厅局级','hanjian');
