INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2037900f6fb3400e8ab30b58d7f6cc84','b1e2c050fe6449ff84cb46f64f24d30e',1938,'伪剿共军司令、国民党投降派兼伪军头目','盘踞胶东莱阳、海阳一带，后公开投敌，任伪剿共军司令，配合日军扫荡胶东抗日根据地，对海阳、烟台地区抗日力量造成重大破坏。；原国民党军将领，后投靠日军，在胶东莱阳、烟台一带组织伪军，配合日军扫荡抗日根据地，残害抗日军民，是胶东地区著名汉奸武装头目。；原国民党军将领，后投靠日军，在胶东地区组织伪军，盘踞莱阳、莱西、即墨一带，配合日军扫荡抗日根据地，残害抗日军民。','基层头目','hanjian');
