INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('18971a77425442d6934ddf2c9176240e','e52245c19301443fb3995b3718c42935',1938,'伪胶东道尹','任伪胶东道尹期间，管辖烟台、海阳等胶东地区伪政，推行日伪政策，镇压抗日力量。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('87eb56d374ee43159acb1d99cb50d895','8085e0e5fd8a4ece88f3b28d89e9760f',1938,'伪烟台市市长','在烟台伪政权中任职，协助日军管理烟台市区，参与经济统制和治安镇压。；抗日战争时期在烟台地区任职伪政权，为日军统治服务，推行伪化政策。；日军侵占烟台后，出任伪烟台市长，组织维持会，推行保甲制度，为日军征发劳工、物资，镇压抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('543dcbd6d6424ff78b3240bec0c4c949','bd883ce767fe4b3c83566498b24a27fb',1938,'伪烟台市商会会长','在烟台地区为日军筹款筹物，协助经济掠夺，属于经济领域附逆者。','基层头目','hanjian');
