INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d61dfef74dac4891a294baccc3ff7f54','fbde0da50ebf4ff8aa9b36ce2cfdf0de',1938,'伪烟台警察局督察长','在烟台伪警察系统中任职，参与镇压抗日活动，迫害当地民众。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a8458ad5c71948ababd69cb44416d968','177c17b9b440453fa41ed47b9ebbd502',1937,'伪军头目、土匪武装','率部在山东胶东一带活动，后投靠日军，配合扫荡，活动范围接近烟台、海阳地区。；原为土匪，后投靠日军，活动于山东胶东及烟台、莱州一带，配合日军扫荡，残害抗日军民。；绰号刘黑七，率部投降日军，在山东胶东及鲁中一带流窜，配合日军扫荡抗日根据地，活动范围曾涉及烟台、蓬莱周边地区。；原为土匪，后投靠日军，在山东各地流窜，配合日军扫荡抗日根据地，活动范围涉及胶东地区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('00b9667fd6a74d67a0960b97bce1979c','c736f6028cbf48979234bd1391a47012',1938,'伪军头目、国民党投降派','在胶东地区活动，后投靠日军，率部配合日伪扫荡，对海阳、烟台地区抗日根据地造成破坏。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e3cc8de38e2a4a94a64241a332b90f99','b1e2c050fe6449ff84cb46f64f24d30e',1938,'伪胶东招抚使、伪军司令','原国民党军将领，后投靠日军，在胶东地区组织伪军，盘踞莱阳、海阳一带，配合日军进攻烟台及周边抗日根据地，1945年被八路军击溃。；原国民党军将领，后投靠日军，任伪胶东招抚使，盘踞莱阳、海阳一带，多次配合日军扫荡胶东抗日根据地，1945年被八路军击溃后逃窜。','基层头目','hanjian');
