INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('805787dc79f44ca8987f8a7ed1d7375c','e76c89aa3bac464887a41dbac4b6e4e1',1938,'伪山东省省长、伪北平市市长','北洋旧官僚，抗战期间投敌，曾任伪山东省长，参与日伪在山东的统治，聊城、临清等地在其伪政权体系内。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('050612a95ae245a7800172b13d83db48','177c17b9b440453fa41ed47b9ebbd502',1937,'伪军头目、伪和平救国军师长','惯匪出身，抗战期间投敌，率部在鲁西、鲁南一带配合日军扫荡，残害抗日军民，活动区域包括聊城、临清周边。；原为土匪，后投靠日军，率伪军在山东、胶东一带活动，配合日军扫荡抗日根据地。；土匪出身，投日后在豫北、鲁西一带活动，其伪军曾窜扰安阳、汤阴地区，配合日军扫荡。；山东惯匪，抗战期间投靠日军，率部流窜于豫东、豫南及平顶山周边，烧杀抢掠，配合日军扫荡，1943年被八路军击毙。；土匪出身，投靠日军后率伪军在豫西、豫中一带流窜，烧杀抢掠，其活动范围包括平顶山周边地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cd67e11a2ba846e1bb67c01437581d78','a529f22d619d455581bb8d99f40b8295',1937,'伪军头目、伪山东保安第五师师长','原国民党地方武装，后投敌，盘踞鲁西聊城、临清一带，配合日军进攻抗日根据地，鱼肉百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0ec7567dedcb4fddbe8fb7ab2f835839','4a9ea97cfc5644b980c7a1255bc29efa',1937,'伪临清县知事、伪临清维持会会长','临清本地士绅，日军侵占临清后出面组织维持会，任伪县知事，协助日军征粮、派夫、镇压抗日活动。','基层维持会/地方自治头目','hanjian');
