INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b544be167b174c3ca209aa015b5c77a6','a2e4190c87b449e685d78c118a6801b5',1938,'伪国民政府行政院副院长、伪上海市市长','汪伪政权核心人物，其伪政权体系覆盖山东，包括聊城、茌平地区的伪县政权受其名义管辖。；湖南沅陵人，汪伪政权核心人物之一，参与伪政权决策，推行亲日卖国政策，对湖南地区伪政权有影响。；湖南沅陵人，抗战期间投靠汪精卫，成为汪伪政权核心人物之一，历任伪财政部长、伪警政部长、伪行政院副院长、伪上海市长等职，参与伪政权决策与对日妥协活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d3e19bf4a7954a23bfa03a04c4367080','6876b4dc973441299b47d406050a627f',1937,'伪华北政务委员会实业总署督办','参与伪华北经济掠夺，在山东聊城等地征粮征棉，支持日军以战养战。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('12ee7d086849448bbd7086f4cb722653','eb97867e737c44e4944e71b5792c1f23',1937,'伪北京市市长、伪华北政务委员会委员','参与伪华北政权，其政策波及山东聊城地区，协助日军维持治安。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7194e5fca46245039c15197e65b66731','4b89b0b1aadc4aa2b3384379d6297cd7',1937,'伪山西省省长','伪山西省长，与山东聊城地区邻近，其伪政权与山东伪政权有协同，配合日军扫荡。；曾任阎锡山部将领，后投日，任伪山西省长，在临汾等地推行日伪统治，协助日军清乡、征粮，镇压抗日力量。；曾任阎锡山部高级参事，后投敌任伪山西省长，推行日伪统治，协助日军掠夺山西资源，镇压抗日力量。；山西朔县人，抗战期间投靠日军，历任伪山西省公署省长、伪华北政务委员会委员等职，主持山西伪政权，推行奴化教育、配合日军征粮征丁，其伪政权统治覆盖临汾地区。；曾任阎锡山部将领，后投敌任伪山西省长，推行日伪政权统治，协助日军在山西各地建立维持会，镇压抗日力量。；曾任阎锡山部高级将领，后投敌任伪山西省长，推行日伪统治，镇压抗日力量。；投靠日军，任伪山西省长，推行奴化政策，协助日军征粮征税，镇压抗日力量。；原阎锡山部属，投日后任伪山西省长，推行日伪政权，强征民夫粮食，镇压抗日活动。；山西朔县人，抗战期间投靠日军，历任伪山西省公署省长、伪华北政务委员会委员等职，主持山西伪政权，推行日军殖民统治政策，为日军征粮、征丁、维持治安提供支持。；曾任阎锡山部将领，后投日，出任伪山西省长，在太原及晋南地区推行日伪统治，协助日军清乡、征粮，镇压抗日力量。其管辖范围涉及临汾、洪洞等晋南地区。；曾任阎锡山部高级参事，后投敌任伪山西省省长，协助日军推行“治安强化运动”，在翼城、临汾等地强征粮税、镇压抗日民众。；原为阎锡山部属，投日后任伪山西省长，推行日伪政权统治，协助日军在山西各地建立维持会，镇压抗日力量。；原为阎锡山幕僚，投日后任伪山西省省长，在太原及晋南地区推行日伪政令，组织伪军和维持会，镇压抗日力量。；曾任阎锡山部将领，投日后任伪山西省长，推行日伪政权，协助日军统治山西，镇压抗日力量。；曾任阎锡山部将领，后投日，任伪山西省长，推行日伪统治，镇压抗日力量。；山西伪政权最高头目，在包括吕梁在内的日占区推行殖民统治，组织伪军伪警，配合日军扫荡。；任伪山西省长期间，推行日军殖民统治政策，在山西全境包括吕梁地区建立伪政权、征粮征丁，是山西伪政权最高头目。；投靠日军，任伪山西省长，为日军征粮派款，组织伪军协助扫荡。；作为伪山西省最高行政长官，推行日军殖民统治，在山西各地包括吕梁地区建立伪政权、维持会，征发劳役、掠夺资源，镇压抗日活动。；曾任阎锡山部高级官员，后投靠日军，出任伪山西省省长，协助日军推行“治安强化运动”，镇压抗日力量，征收粮饷供日军使用。；投靠日军，任伪山西省公署省长，推行日伪统治政策，协助日军掠夺山西资源，镇压抗日力量。；投靠日军，任伪山西省长，推行奴化教育，协助日军掠夺山西资源，镇压抗日力量。；投靠日军，任伪山西省公署省长，推行奴化教育，协助日军掠夺山西资源，镇压抗日力量。；投靠日军，出任伪山西省省长，推行日伪统治政策，协助日军掠夺山西资源，镇压抗日力量。；曾任阎锡山部高级官员，投日后任伪山西省省长，推行日伪政权统治，协助日军在山西进行经济掠夺和奴化教育。；曾任阎锡山部将领，投日后任伪山西省长，推行日伪政权统治，协助日军掠夺山西资源。；曾任阎锡山部高级官员，后投日，出任伪山西省省长，积极推行日伪政权政策，协助日军统治山西，镇压抗日力量。；曾任阎锡山政府要员，投日后任伪山西省省长，推行日伪政权统治，协助日军征粮、征税、镇压抗日力量。；投靠日军后出任伪山西省长，推行日伪政权各项政策，协助日军进行经济掠夺和奴化教育。；投靠日军，任伪山西省公署省长，推行日伪政权统治，协助日军在山西进行经济掠夺和奴化教育。；投靠日军，出任伪山西省省长，推行奴化教育，协助日军掠夺山西资源，镇压抗日活动。；投靠日军，任伪山西省公署省长，推行奴化政策，协助日军镇压抗日力量，征收苛捐杂税，迫害抗日军民。；曾任阎锡山部高级官员，投日后任伪山西省省长，推行日伪政权各项政策，协助日军进行经济掠夺和殖民统治。；山西沦陷区最高伪政权头目，推行日军殖民政策，为日军征粮征兵，镇压抗日力量。；任伪山西省长期间，推行日伪政令，配合日军在山西包括雁北、朔州地区的统治。；投靠日军，任伪山西省长，推行奴化政策，协助日军掠夺山西资源，镇压抗日力量。；山西朔县人，抗战期间投靠日军，历任伪山西省公署省长、伪华北政务委员会委员等职，主持山西伪政权，推行奴化教育、配合日军征粮征丁，其伪政权统治覆盖运城、稷山等晋南地区。；曾任伪山西省省长，推行日伪政权统治，协助日军在山西各地建立维持会，镇压抗日力量。；原阎锡山部属，投日后任伪山西省长，推行日伪统治，镇压抗日力量，协助日军在山西各地建立伪政权。；曾任阎锡山部将领，后投日，出任伪山西省长，推行日伪政权统治，协助日军在山西各地建立维持会，镇压抗日力量。；曾任阎锡山部将领，投日后任伪山西省长，推行日伪政权统治，协助日军在山西各地建立维持会，镇压抗日力量。；山西伪政权最高头目之一，主持全省伪政，推行日伪法令，阳泉、平定等地伪政权均受其统辖。；投敌后任伪山西省省长，协助日军经济统制，强征劳工，对陕西周边抗日根据地实施封锁。；投靠日本，在山西伪政权中任职，推行日伪政策，其活动区域与陕西邻近。；山西伪政权要员，协助日军掠夺资源，镇压抗日活动，影响波及陕西宝鸡。；在山西伪政权中任职，推行日军侵略政策，其伪政权与陕西沿边地区有政治和军事联系。；山西伪政权头目，其伪政权与陕西渭南地区邻近，有间接联系。；投靠日本，在山西建立伪政权，推行奴化教育，其势力范围与陕西渭南、富平邻近。；投敌后任伪山西省省长，协助日军统治山西沦陷区。；在山西建立伪政权，配合日军扫荡，山西与陕西隔河相望，其伪政权活动对陕西抗日根据地构成直接威胁。；任伪山西省省长，配合日军在山西及陕西周边地区的统治，是华北重要汉奸之一。；投靠日本，任伪山西省长，配合日军在山西及陕西周边地区的殖民统治和扫荡。；在山西沦陷区任伪省长，协助日军征发物资、镇压抗日。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('39505054fe37429abc2608c19ad2eca3','2d84686f304148859166863eeaf93bb5',1938,'伪山东省警务厅厅长','负责山东伪警察系统，在聊城等地建立伪警察所，搜捕抗日人员。','市县厅局级','hanjian');
