INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('22f4661f4d9443c3ad087661ad871ee9','d6d76958ee164d75a29297b85ac0cbe2',1940,'伪山东省剿共军司令','组织伪剿共军，在聊城、茌平地区配合日军进攻抗日根据地，捕杀抗日人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('52e1c617af4e4d9f998f23071cf4be47','793dba30c5cd4e9ab0835412a8dc7906',1937,'伪河南省省长','伪河南省长，其辖区与山东聊城邻近，与山东伪政权协同扫荡。；任伪河南省省长，在开封等地建立伪政权，协助日军统治河南沦陷区。；出任伪河南省省长，为日军在河南的统治服务，推行伪政。；在日军扶植下出任伪河南省长，统辖河南沦陷区伪政权，包括信阳地区，推行征粮、清乡与奴化政策。；汪伪政权河南省最高行政头目，统辖包括信阳在内的沦陷区伪政权，推行奴化教育与经济统制。；抗战期间任伪河南省长，驻开封，协助日军维持河南沦陷区统治，推行伪化政策，其政令涉及南阳周边地区。；抗战期间任伪河南省省长，在开封等地设立伪政权，配合日军统治河南沦陷区，推行保甲制度、征粮征丁，镇压抗日活动。；抗战期间任伪河南省长，主持河南沦陷区伪政，配合日军征粮、征兵、清乡，其政令下达至豫东周口、商水一带伪县政权。；抗战期间任伪河南省省长，驻开封，统辖包括豫东商丘在内的伪政权，推行日军征粮、征丁和治安强化政策。；抗战期间任伪河南省省长，主持河南沦陷区伪政权，推行日军殖民统治政策，商丘、虞城等豫东沦陷县伪政权在其管辖体系内。；伪河南省政权头目之一，在日军控制下推行伪政令，其统治范围覆盖豫北安阳、内黄等地，为日军征粮、征兵、维持治安。；伪河南省政权头目之一，在日军控制下推行伪政，协助征粮、征兵和镇压河南抗日力量。；河南沦陷区伪政权头目，推行日军殖民统治，为安阳等地伪政权提供支持。；河南安阳人，抗战期间投敌，曾任伪河南省省长，为日军在河南推行殖民统治，其家乡安阳及汤阴一带受其伪政权影响。；作为伪河南省政权头目，推行日军殖民统治政策，督令包括安阳在内的豫北各县征粮、派夫、清乡，支持日伪在河南的统治。；1943年出任伪河南省省长，在日军控制下推行伪政，协助日军征粮、征夫，其伪政权覆盖河南全省包括平顶山地区。；继任伪河南省省长，驻开封，协助日军掠夺物资、镇压抗日力量。；任伪河南省省长期间驻开封，为日军统治河南沦陷区服务，推行保甲、征粮等伪政。；任伪河南省长期间，为日军征集物资、推行奴化教育，协助维持占领区统治。；任伪河南省长期间驻开封，配合日军统治河南沦陷区，推行保甲、征粮、奴化教育。；继任伪河南省省长，在开封主持伪省政，配合日军“治安强化运动”，推行保甲连坐，镇压抗日力量。；在开封任伪省长，配合日军征粮、征兵，推行奴化教育。；继任伪河南省长，驻开封，配合日军进行治安强化运动，镇压抗日活动。；继任伪河南省省长，驻开封，协助日军征粮、征丁，镇压抗日活动。；任伪河南省长，驻开封，统辖河南伪政权，为日军筹粮筹款、推行奴化教育。；抗战期间出任伪河南省省长，在开封等地主持伪省政府，推行日军殖民统治政策，为日军征粮、征夫、维持治安，是河南伪政权最高头目之一。；抗战期间任伪河南省省长，驻开封，主持河南沦陷区伪政权，推行日军殖民统治政策，其伪省政权下辖豫中各县，漯河、召陵一带亦在其伪化行政体系覆盖范围内。；抗战期间任伪河南省省长，主持河南沦陷区伪政权，推行日军殖民统治政策，漯河、舞阳等地伪政权均受其管辖。；抗战期间任伪河南省省长，主持伪省政，推行日军殖民统治政策，其伪政权覆盖包括濮阳在内的河南沦陷区。；河南沦陷后出任伪河南省长，推行日军殖民统治政策，在包括焦作、修武在内的豫北地区建立伪政权体系。；作为伪河南省最高行政长官，为日军在河南包括豫北焦作地区的殖民统治服务，推行保甲、征粮、奴化教育。；在伪河南省长任内，配合日军在河南包括许昌一带征粮、征兵、镇压抗日活动。；抗战初期出任伪河南省省长，在开封等地建立伪政权，为日军筹措物资、推行奴化教育，是河南伪政权早期核心人物。；抗战期间出任伪河南省政府省长，驻开封，主持伪省政，推行日军占领政策，在河南沦陷区实施保甲、征粮、劳工等事务，是河南伪政权最高行政头目之一。；抗战期间出任伪河南省政府省长，驻开封，协助日军推行伪政，维持河南沦陷区统治，其伪政权体系覆盖郑州等地。；河南人，任伪河南省长期间，协助日军在河南各地建立维持会、伪政权，包括驻马店地区。；作为伪河南省最高行政长官，推行日军殖民统治政策，其政令覆盖豫北鹤壁、淇县等地。；伪河南省政府首脑，驻开封，其伪政权体系覆盖豫北包括鹤壁、淇县、浚县等地，推行日伪统治。；河南伪政权要员，其伪化活动与陕西渭南地区有间接关联。；在河南伪政权任职，参与日军对陕西的封锁与进攻。；投敌后任伪河南省省长，配合日军统治河南沦陷区。；在河南地区出任伪职，配合日军推行治安强化运动。；在河南沦陷区任伪省长，协助日军征发物资。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b50ba965063c4606b17ef2b36d1d434d','a23958f2a093468d8476a9eec1ddb6a8',1937,'伪河北省省长','伪河北省长，其辖区与山东聊城接壤，配合日军对鲁西北的扫荡。','省部级/大军区级要员','hanjian');
