INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9aad34b4144844f593be9bb55ef04772','b703389315144282b95be5459756f9fa',1938,'伪山东省教育厅厅长','推行奴化教育，在聊城、茌平学校强制日语教学，篡改历史。','市县厅局级','hanjian');
