INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5211ee0414154ae4814dc8b81856da34','903f92a867db4e77abb94dac1ad28168',1941,'伪和平救国军第一集团军司令','原国民党军，投敌后驻苏北、山东南部，其势力与山东聊城地区有联系。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('01842efcf70c4b37b1686c2cba28ca88','bacadba533394b3bb79fb5b9c5b66118',1938,'伪浙江省省长','汪伪要员，其伪政权体系与山东聊城地区有名义联系。；任伪浙江省长末期，组织伪军协助日军防守，对抗游击区。；汪伪政权要员，1943年接任伪浙江省省长，任内强化日伪统治，配合日军进行经济掠夺和军事清剿。；末任伪浙江省长，在绍兴、上虞地区继续维持伪政权，直至日本投降。；伪政权要员，与陕西渭南地区无直接关联，属华中伪政权体系。；投敌后任伪浙江省省长，协助日军。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b1e6bd62c6ad490cbf5fa126686ed984','41d2b197fedd4eefa3bd64d7cebe1523',1940,'伪国民政府军事委员会参谋总长','汪伪军事头目，其伪军系统覆盖山东，包括聊城、茌平地区的伪军受其指挥。；在南京参与伪军军事策划，协助日军进攻抗日根据地。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2f744ffb53f74280b9e0c71e2e067f1b','bb34b45b44c34a018d410cde66579fb1',1943,'伪国民政府陆军部部长','汪伪军事要员，其伪军系统在山东聊城地区有活动。','省部级/大军区级要员','hanjian');
