INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6fa5dfff483c403fa686ef2db14bae28','fefd7f9ddbac40469c751144d6cbd784',1943,'伪国民政府军事委员会驻华北委员','汪伪驻华北军事代表，与山东聊城地区伪军有联系。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0fd1218961c041f8a8067d8d68e95eab','259163e844a045a9964a8dfa9d5dd306',1943,'伪国民政府军事委员会委员','汪伪军事要员，其活动涉及山东聊城地区伪军。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('361ae8ec2ee6426380f29ceee46b5d42','1ba31d558b934fbd83a28a8c2b446022',1933,'伪满洲国热河省省长','伪满要员，其势力与华北伪政权有联系，间接影响山东聊城地区。；原东北军将领，1933年投敌，任伪热河省省长，协助日军镇压抗日武装，推行殖民统治，在丰宁、承德一带组织伪警察和保甲制度，强征民夫修筑军事工事。；原东北军将领，1933年投靠日军，任伪热河省省长，协助日军镇压围场地区抗日武装，推行奴化教育，强征劳工；1933年日军侵占热河后投敌，任伪热河省省长，协助日军镇压抗日武装，推行殖民统治，在宽城、承德一带强征劳工、掠夺资源。；原东北军将领，1933年投敌，任伪热河省省长，协助日军镇压抗日武装，推行殖民统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('65021f3015e84d578490020fd1e01ac3','1d67ff455ffc47b8addcc485beb0ca34',1933,'伪满洲国治安部大臣','伪满军事头目，其伪军与华北伪军有协同，间接影响山东聊城地区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6a61defa47b644d8b272accd4a1406ae','79b17193512846a1a5bde9f5df22c926',1935,'伪满洲国民政部大臣','伪满要员，其政策与华北伪政权有协同，间接影响山东聊城地区。','无明确职位或一般帮凶','hanjian');
