INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f2ec306d97a5498589a6209cbccf1e78','1cdcb37a962e40ad85582f9cf711eaf6',1932,'伪山东省政府顾问、伪军头目','原山东军阀，九一八事变后寓居天津，与日本特务机关往来，企图借日军势力重返山东，其旧部在鲁西北包括聊城、高唐一带活动，对地方伪化有间接影响。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ca6d030c41db42ce802fa7a43f1ecac7','ee609f4730d74ad9a717988920c1016e',1930,'国民党山东省政府主席（后与日军妥协）','抗战初期为保存实力，擅自放弃山东黄河防线，导致聊城、高唐等地迅速沦陷；虽非正式汉奸，但其不抵抗行为为日军扶植伪政权创造了条件。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8391298ed62746128e09b9c70e396a0e','926a397c6e23463bab0fd82d55673a7c',1938,'伪聊城县维持会会长、伪聊城县知事','聊城沦陷后组织维持会，后任伪县知事，为日军征粮派款、搜集情报，直接控制聊城城区及周边乡镇。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5fd592e123de43898f95dc020f882250','773c389cdc344708985c5427cd1d1689',1938,'伪高唐县维持会会长、伪高唐县知事','高唐沦陷后投靠日军，组织维持会，后任伪县知事，协助日军建立伪政权、清乡扫荡，镇压高唐抗日武装。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0a06a9912fc347a2bcc220840bd3f12e','f72731704785407fb05e76f2ea11990c',1939,'伪高唐县警备队队长','统领伪高唐警备队，配合日军对高唐及周边地区进行“扫荡”，捕杀抗日干部和群众，强征民夫修筑据点。','基层头目','hanjian');
