INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('58b034345d9f4a94af31b7754d6159ed','a529f22d619d455581bb8d99f40b8295',1939,'伪军司令（原国民党游击武装投敌）','原为国民党地方武装，后率部投靠日军，编为伪军，活动于聊城、高唐、茌平一带，配合日军进攻抗日根据地，残害百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('747712c42b5646eca2ba6022c1dce16f','4a9ea97cfc5644b980c7a1255bc29efa',1940,'伪军旅长、伪高唐县保安团团长','率伪军盘踞高唐、夏津一带，为日军征收粮食、棉花，参与“扫荡”抗日根据地，屠杀抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('947e4fe657db481396bb800708f064d5','908606fc16e74846b2bc83393e20f446',1941,'伪高唐县保安队队长','控制高唐部分乡镇，建立保甲制度，强征壮丁，配合日军清剿抗日武装，勒索百姓财物。','基层头目','hanjian');
