INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('065faa4fbdf648b7a89a67bfc8ce2a1e','8085e0e5fd8a4ece88f3b28d89e9760f',1938,'伪曹县县知事、伪鲁西南道尹','在曹县、单县交界地区组织伪政权，强征粮食棉花供应日军，诱降抗日队伍，破坏中共地下组织。','基层头目','hanjian');
