INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c07375a20a804369a340bf9400faa60f','71274a6a71304c5cbab2ff72dcb0a98b',1938,'伪兖州道尹（活动涉及鲁西）','任伪兖州道尹期间，其辖区与鲁西相邻，参与对菏泽、定陶一带的伪化协调，协助日军征发物资、镇压抗日。','无明确职位或一般帮凶','hanjian');
