INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7e372f2c8227493aa61d8e5af57023d5','ccaf5560fb1e4a3a892f62f4ce46f93a',1940,'伪鲁西道公署道尹','任伪鲁西道尹期间，统辖菏泽、巨野等县伪政权，推行治安强化运动，配合日军清乡。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('700ab87dd43544bc90328ac9ab91cb49','15a53deac38b4a38bb911a125d119e5c',1938,'伪山东省公署参议','山东伪政权要员，参与制定伪化政策，曾到菏泽、巨野等地视察督导伪政，协助日军掠夺物资。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('08d349eeee8840158e351be80d1446f6','9edb0275b4734a47805ca9385baed31a',1938,'伪山东省公署省长','早期伪山东省长，建立伪政权体系，菏泽、巨野等县伪政权在其任内设立并运作。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9848f5ca3d7f4099b3e453640aafbc01','c1daa171e05746d383d93806c90f6027',1940,'伪巨野县教育科科长','在巨野推行奴化教育，篡改教材，宣传“大东亚共荣”，毒化青少年。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dcc136bd5eb74971a1468cc35ea63156','eeb3c8c33a9044808ed5db66316ce87d',1940,'伪鲁西道保安司令','率伪保安部队在菏泽、巨野一带配合日军扫荡，进攻抗日根据地，残害百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('58bc915e02824684a44468307482c3da','b13717d0c73e4b4dab35109ce0057aba',1937,'伪皇协军第一军军长','原国民党军将领，1938年投敌，所部在鲁西包括菏泽、巨野一带活动，配合日军作战。；原国民党军将领，1938年在豫北投敌，组织伪皇协军，虽主要在豫北活动，但其伪军体系与豫东商丘一带伪军有联系。；原国民党军将领，1938年在河南北部投敌，组织伪皇协军，虽主要活动于豫北，但其伪军系统与河南沦陷区伪政权、伪军网络相连，影响波及商丘一带的伪军组建。；在安阳、林县一带组织伪皇协军，配合日军作战，后因内部冲突被日军处死。；原国民党军将领，1938年在河南投敌，组织伪皇协军，在豫北、豫西一带配合日军作战，其伪军活动范围涉及河南中部，对平顶山、汝州地区有间接影响。；在豫北、豫东一带率伪军配合日军作战，后于1938年被日军处死。；在豫北、豫东一带率部投敌，组织伪皇协军，配合日军进攻河南抗日武装。；原国民党军将领，1938年在河南安阳、新乡一带投敌，组织伪皇协军配合日军进攻，1939年被部下击毙。；原国民党军将领，1938年在河南投敌，组织伪皇协军，在豫北、豫东一带配合日军作战，其伪军活动曾波及漯河周边。；原国民党将领，1938年在河南林县投敌，任伪皇协军第一军军长，活动于豫北、冀南一带，包括濮阳地区，配合日军进攻抗日武装。；原国民党将领，1938年在河南投敌，组织伪皇协军，在豫北地区配合日军。；在豫北安阳、焦作一带率部投敌，被编为皇协军，配合日军进攻太行山区。；在豫北地区组织伪军，配合日军进攻抗日根据地，后活动范围扩展至豫中一带。；在豫北、豫中组织伪军，配合日军作战，其活动范围包括许昌周边。；原国民党军将领，1938年在豫北投敌，组织伪皇协军，活动于安阳、新乡及郑州以北地区，后被抗日武装击毙。；原国民党军将领，1938年在河南安阳一带率部投敌，组织伪皇协军，配合日军进攻豫北抗日武装，后被击毙。；原国民党军将领，1938年率部投敌，任伪皇协军第一军军长，活动于豫北、豫东一带，其伪军曾配合日军向郑州方向进攻。；在河南安阳、郑州以北地区组织皇协军，配合日军进攻，后在水冶被抗日武装击毙。；原为国民党军将领，1937年在豫北投敌，组建伪皇协军，活动于安阳、鹤壁、淇县、浚县等地，配合日军进攻抗日武装。；原国民党将领，投敌后组建伪军，在华北配合日军作战，对陕西宝鸡抗日后方构成威胁。；在河南、华北组织伪军，配合日军作战，其活动对陕西周边有影响。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4b245d4e71d84a9aa9dee62652c4dbe9','46170abf3f1f43a4ac2e37f7fe177225',1941,'伪巨野县保安团团长','组织伪保安团，协助日军守备巨野，参与清乡，搜捕抗日人员，勒索民众。','基层头目','hanjian');
