INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('894a9d82aad14ae5864f3faaca3a8225','8085e0e5fd8a4ece88f3b28d89e9760f',1938,'伪单县县知事、伪单县保安团长','单县沦陷后投敌，任伪职期间在单县、成武、金乡一带配合日军清乡，强征壮丁，镇压抗日武装。','基层头目','hanjian');
