INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('646c85d6401f4edcaa4802a7ada01cd2','bda9545ab0114fa3b5d9d7d22d03b9eb',1939,'伪郓城县知事','在郓城建立伪政权，配合日军对郓城、鄄城一带抗日根据地进行扫荡，残害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e81812d12e174fe2977568320bdf3106','b5b65c50b47e42e49b1a39960686a979',1939,'伪鲁西道尹公署道尹','在鲁西道（辖菏泽、曹县、单县等地）推行伪政，为日军征集粮食、劳工，镇压抗日活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('355ea2e8cef448208a97abbef0d65506','b13717d0c73e4b4dab35109ce0057aba',1938,'伪华北治安军第八集团军司令','原为国民党军将领，投敌后率伪治安军在鲁西、豫北一带配合日军作战，活动范围覆盖菏泽周边。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d0c5619ea2614233bd4bc26dea60397a','5ec2ad124b2f429482b1a90a7f8d4a92',1943,'伪和平救国军第二十四集团军总司令','原为国民党军将领，被俘后投敌，率伪军在华北包括鲁西地区配合日军作战。；原国民党河北省主席，1943年被俘投敌，任伪军总司令，其伪军活动于豫北、晋南，与临汾地区日军有配合。；在河南林县投敌，后率伪军在豫北、豫西配合日军扫荡。；被俘后投敌，率伪军在河南沦陷区配合日军作战，参与对豫南包括信阳附近抗日武装的扫荡。；河北人，原国民党军将领，1943年在河南林县投敌，所部被编为伪军，在豫北、豫西活动，对河南抗战局势造成破坏。；河北人，原国民党河北省主席、第二十四集团军总司令，1943年在河南林县被俘后投敌，所部伪军活动于豫北、豫西，对南阳地区构成威胁。；河北人，1943年投日后，其伪军活动范围包括河南豫东地区，与周口一带伪军勾结，协助日军维持占领区。；河北人，但在河南林县投敌后，其伪军体系影响河南沦陷区，包括豫东周口、淮阳一带的伪军整编与指挥。；原国民党河北省主席、集团军总司令，1943年在河南投日，任伪军总司令，在豫北、豫东一带配合日军。；1943年投敌，在豫北安阳、林县一带率部降日，配合日军进攻抗日根据地。；原国民党河北省主席、第二十四集团军总司令，1943年在豫北被俘后投日，率部在安阳、林县、辉县一带协助日军进攻抗日根据地。；投降日军后活动于豫东开封、通许地区，协助日军维持治安。；投敌后率伪军活动于河南北部及开封周边，配合日军作战，镇压抗日力量。；投敌后率伪军驻豫北、豫西，配合日军扫荡，其势力范围一度接近洛阳。；在河南投日，所部伪军活动于豫北、豫西，协助日军维持占领区。；原国民党河北省主席、集团军总司令，1943年投敌，所部伪军在河南北部及豫西活动，与洛阳地区日军协同。；1943年投日，在豫北地区组织伪军，配合日军扫荡，活动范围包括焦作、武陟周边。；1943年在豫北被俘后投日，组织伪军配合日军扫荡豫北抗日根据地，其活动区域覆盖焦作、沁阳等地。；被俘后投日，所部在河南北部及许昌一带协助日军维持治安、进攻抗日武装。；原国民党河北省政府主席、第二十四集团军总司令，1943年在河南林县地区被日军俘获后投降，被汪伪政权任命为伪军总司令，在豫北一带活动，协助日军控制平汉铁路沿线。；被俘后投敌，任伪军总司令，在河南北部及郑州周边地区配合日军扫荡抗日武装。；1943年在豫北投敌，率部编为伪军，活动于豫北包括鹤壁、淇县、浚县等地，进攻八路军。；河北人，被俘后投敌，伪军活动于豫北，与湖南无直接关联。；投降日军后，在华北、华中地区组织伪军，其部队曾参与对湖南的进攻和占领。；原国民党将领，投敌后任伪军头目，活动于华北，与陕西渭南地区有间接关联。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('80772d06f64d4df6b3ade3cbed7dfbcf','787316523113404490ba5600ddd81417',1938,'伪郓城县县长兼伪军团长','郓城一带著名汉奸，投靠日军后组织伪政权和伪军，配合日军扫荡鲁西南抗日根据地，残害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ef7872a5ed5443c0989b5b56e4590753','63006a4879fb4f49ad97a1e88c8c5d69',1942,'伪和平建国军第三方面军总司令','原国民党将领，1942年率部投敌，所部活动于鲁西南、菏泽一带，配合日军进攻抗日根据地。；率部投敌，在华北、华中配合日军进攻抗日根据地，其伪军活动对陕西周边有影响。；投靠日本，率部投降日军，在华北及陕西周边地区配合日军进行治安战。','省部级/大军区级要员','hanjian');
