INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('db7852319ef646b2ba99196abb448307','c692801ac2c3420b89c5234722019808',1939,'伪菏泽县警察局局长','在菏泽伪警察系统任职，负责情报搜集与抓捕抗日人员，协助日军在菏泽及郓城一带推行保甲制度和良民证管理。','市县厅局级','hanjian');
