INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d971ad84f69b46b0a3c880cf66f6353f','1a5f254b2f68424a91a5fbf85fece5e1',1937,'伪山西省省长','山西解县人，继苏体仁后任伪山西省省长，继续为日军服务，在包括临汾在内的山西各地推行伪政，搜刮物资支持日军侵略。；山西解县人，继苏体仁后任伪山西省省长，继续为日军统治服务，协助日军在山西各地推行保甲、征粮、扫荡等政策。；继苏体仁后任伪山西省长，继续在吕梁等日占区推行伪化政策，为日军掠夺资源、镇压抗日力量。；继任伪山西省长，继续推行‘治安强化运动’，在吕梁等地区强化保甲、掠夺资源，支持日军扫荡。；继苏体仁后任伪山西省长，继续推行日军殖民政策，在吕梁等地区强化伪政权和保甲制度，配合日军扫荡抗日根据地。；继苏体仁任伪省长，继续为日军服务，推行治安强化运动，配合扫荡。；继任伪山西省长，继续为日军在山西的殖民统治服务，涉及朔州等雁北地区。；山西解县人（今属运城），早年留学日本，抗战期间附逆，继苏体仁后任伪山西省省长，为日军筹措物资、镇压抗日力量，直接涉及其家乡运城一带的伪政权运作。；继苏体仁后任伪山西省长，继续为日军统治山西服务，阳泉地区伪政亦在其管辖之下。；华北汉奸，活动于山西，与河北日伪政权有协作。；投敌后任伪山西省省长，推行保甲连坐，配合日军扫荡山西、陕西边境抗日武装。；在山西伪政权中任职，配合日军统治，对陕西抗日根据地有间接威胁。；山西伪政权头目，推行日军政策，对陕西宝鸡抗日后方构成威胁。；在山西伪政权中任职，配合日军对晋陕绥边区的封锁和进攻，影响榆林、府谷一带。；山西伪政权要员，其伪化活动与陕西渭南地区有间接关联。；在山西伪政权任职，配合日军经济掠夺与治安强化，其活动区域与陕西邻近。；投敌后任伪山西省省长，配合日军。；继任伪山西省长，推行日军政策，镇压抗日民众，其活动区域紧邻陕西，对陕西地区有直接影响。；继苏体仁后任伪山西省省长，协助日军维持山西及邻近陕西地区的伪政权。；投靠日本，任伪山西省长，协助日军在山西及邻近陕西地区进行统治。；在山西沦陷区任伪省长，配合日军统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7f2d67d57a254f0f857123c906108683','0367758e6b0a4e6e9be4392582958ec0',1938,'伪山西省公署警务厅厅长','在伪山西省公署任职期间，统管全省伪警察力量，在临汾等地建立伪警察网络，镇压抗日活动，抓捕抗日人员。；在伪山西省政权中负责警务，参与组建和指挥伪警察力量，配合日军在山西包括临汾地区进行治安强化运动、搜捕抗日人员。；负责组织伪警察力量，在临汾、翼城等县建立伪警察所，配合日军清乡、搜捕抗日人员，残害百姓。；山西人，抗战期间在伪山西省公署任职，掌管伪警察系统，参与搜捕抗日人员、维持日伪统治秩序，其警务体系延伸至晋南运城、稷山等地。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9d7eba5d7d7b4a6a83237849b086b680','b968cf1fa00147bea4c95506b5097555',1938,'伪山西保安队副司令、伪军头目','山西人，原为阎锡山部属，后投敌任伪山西保安队副司令等职，率伪军在临汾、晋南一带配合日军扫荡抗日根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9e57cd3227cc47ed9c8643c1e704fb21','5f82d23ccd2e45fd9e59f76c92bcc9ad',1933,'伪蒙古军总司令、伪华北政务委员会要员','热河人，长期在日军扶植下任伪军头目，其伪蒙古军活动范围曾涉及山西北部及临汾周边地区，配合日军进攻抗日力量。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('542a5e2643de4ea19b7a31c6053c4658','9f7b3ed9c76f4eea8211fd8ebc40a461',1943,'伪新编第五军军长（后投敌）','原国民党将领，1943年在河南被俘后投敌，任伪新编第五军军长，其部队在晋南、临汾一带配合日军行动。；1943年投敌后，其部队在河南平顶山、许昌一带配合日军行动，进攻抗日根据地，残害百姓。；1943年在河南林县一带投敌，所部被编为伪军，后在豫西、洛阳周边配合日军作战，参与对抗日根据地的扫荡。；原国民党将领，1943年在河南林县投敌，所部被编为伪军，在豫北包括焦作周边配合日军行动。；1943年投敌，所部在豫北、焦作一带配合日军进攻抗日根据地。；1943年在河南林县一带投敌，所部被编为伪军，活动于豫北包括焦作周边地区。；1943年率部投敌，所部在豫北焦作、新乡一带配合日军进攻抗日根据地，搜捕抗日人员。；1943年在豫北投敌，所部被编为伪军，活动于林县、鹤壁、淇县一带，配合日军进攻抗日根据地。；在河南、华北投敌任伪军头目，配合日军作战，其活动对陕西周边有威胁。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1810dd27c01841fba76fcd87e392f531','8f551835027d47d8a72a3185f6ccbc2f',1937,'伪临汾县维持会会长','临汾本地人，日军占领临汾后出面组织维持会，为日军筹集粮草、招募劳工，协助建立伪政权基层组织。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6a4a46110f4d4b918422a18411d672df','cbce9a2c60fa41d3a6b6ec2d64314c85',1938,'伪临汾县警察所所长','在临汾任伪警察头目，带领伪警察配合日军搜捕抗日人员，镇压民众反抗，维持日伪统治秩序。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7b20d22bdc1d48e4b882754f820ed7ff','4cb994e9e01743f3a2a93b21ffac28fb',1940,'伪古县维持会会长','古县本地人，日军侵入古县后组织维持会，为日军征粮派款、带路扫荡，协助建立伪保甲制度。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('89ba2ecfde44463fbd673b749b3ec7c5','d99b198bab9048c1838f0f3a07f9265a',1941,'伪古县保安队队长','古县人，任伪保安队队长，率队配合日军在古县及周边地区清乡、扫荡，抓捕抗日干部和群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('72f004f72a9246369ba02aa335201f9a','1c56285454d64a1a800e7e45279a0f99',1938,'伪临汾道尹','任伪临汾道道尹，管辖临汾及周边各县伪政，推行日军政策，征发民夫、粮食，支持日军侵略。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b7faca5c5bfa48cb95894130cf45d378','75df6f6433e54cce9f3eafc3830ffc1d',1938,'伪临汾县知事','临汾沦陷后出任伪县知事，主持伪县政，为日军征粮征税，推行奴化教育。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('51ab38ed330a475bbadbc8e6b0dbf22c','8991a876b1c947cba18e6da7602edea5',1942,'伪临汾县知事','继赵子青后任伪临汾县知事，继续为日军服务，在临汾推行治安强化运动，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5204b4f7258247129ac41220be826a8e','cdee7dd1322048df968b8ed75275b910',1938,'伪山西公署宣传处处长','在伪山西省公署负责宣传，推行奴化教育，在临汾等地散发亲日宣传品，麻痹民众抗日意识。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f93092e15cbf4e4db2cc14c08e34e289','697fa99e2d124c559fbb3e28e360394f',1938,'伪山西省公署顾问（日本人）','日本特务，任伪山西省公署顾问，实际控制伪政权，在临汾等地督导日军政策实施，参与镇压抗日。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8e147531247c4639aa172fef7a2f552c','0367758e6b0a4e6e9be4392582958ec0',1938,'伪山西省公署顾问','在临汾地区协助日军进行“治安强化运动”，组织伪警察和保甲制度，搜捕抗日军民。；为日军出谋划策，参与组建伪政权，迫害抗日军民。；参与日伪对临汾、襄汾地区的“治安强化”运动，协助日军收集情报，破坏抗日组织。；在临汾地区为日军搜集情报，参与建立伪政权，协助日军清乡。；协助日军在山西建立伪政权，参与经济掠夺和特务活动。；原为阎锡山政府官员，投敌后任伪省署顾问，参与策划对晋西北抗日根据地的“扫荡”，并协助日军建立伪政权。；曾任阎锡山部属，后投敌，为日军提供山西军政情报，参与组建伪政权。；原山西省政府官员，投日后任伪省公署顾问，参与制定日伪政策，协助日军镇压抗日力量。；原为山西地方士绅，投日后任伪省公署顾问，参与策划日伪行政措施，为日军征粮派款，协助维持殖民统治。；协助日伪维持会工作，参与组织伪警察和保甲制度，迫害抗日军民。；充当日军顾问，参与策划“治安强化运动”，协助日伪军扫荡抗日根据地。；为日军出谋划策，参与建立伪政权，协助日军在运城地区清乡扫荡。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9ec2914d2f22444c8634ba5be2a2848d','8ed7d31ce27e4d969c30b8665b6cd829',1940,'伪吉县知事','任伪吉县知事期间，强征民夫修筑日军碉堡，强迫百姓领取“良民证”，并配合日军扫荡抗日根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cf1c84c622254821ad639ee48faa0067','8ca7803875d447f288905bfe3594a49b',1941,'伪临汾县保安队队长','率伪保安队多次袭击抗日游击队，杀害抗日干部，并参与日军在临汾的“清乡”行动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5f4a15ec6b234e7dbd300d1b7e646e2c','12a8b4767b1e4a989997caabbb41d83a',1942,'伪晋绥军第7集团军总司令（投敌后）','原阎锡山部将领，后与日军勾结，在吉县、乡宁一带配合日军进攻八路军，提供情报并协助维持日占区秩序。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ff1fe7cf848a44dba2a7dc07da12d58e','e31e07da4b3b4cc1a9d4d0614b4d1699',1939,'伪临汾地区维持会会长','组织维持会为日军筹集粮饷，强征劳役，并告密导致多名地下党员被捕牺牲。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('85770993cb294584966456a3706c9960','91abac68340742b9bfd228794f1fd3a4',1942,'伪山西剿共军第1师师长','率伪军驻防吉县一带，参与日军“铁滚扫荡”，烧毁村庄，掠夺物资，杀害抗日群众。；率伪军在霍州、洪洞一带与日军协同作战，袭击八路军游击队。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3f7fd40036e5401b8e663d141c92de86','209c004e337548c6abe34dce6de09f9d',1942,'伪临汾警备司令','在临汾城内设立特务机构，抓捕抗日志士，并配合日军实施经济封锁。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('54e57a53da30480e8610d9da336ea587','9a1674f4648c48ec889a96587a5840d8',1941,'伪晋西地区保安副司令','在吉县、蒲县等地组织伪保安团，协助日军镇压民众反抗，参与“三光”政策下的破坏行动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5e36af3704bc44828b39dcd9d6d11e83','c3c999e491f1414780ed21e7d1590d40',1940,'伪山西省政府顾问','原阎锡山部高级将领，投日后为日军出谋划策，在临汾、吉县推行“以华制华”策略，建立伪政权。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c820c9e7adcf4dc9b3d145fe619097f7','7f6066ad727a41bca724f0139c620b63',1938,'伪大宁县维持会会长','日军占领大宁后出任维持会长，为日军征粮派款，协助建立伪政权，镇压抗日群众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0c00ade0c4ac43ccbfa40e13f5e2d9be','bb14653d2ee94ed1a79327e17af143f5',1940,'伪大宁县保安队队长','率伪军配合日军扫荡抗日根据地，抓捕抗日干部，抢劫百姓财物。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('771bf803194e41ea99210e9a516fb1f9','af8a54e4d8ad4f43b4e20eba2fbd4567',1941,'伪大宁县知事（县长）','任伪知事期间推行保甲制度，强征壮丁，为日军提供情报，迫害抗日家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2467abbbf1ab47de923c0ac1d64fbcc1','d21dcf5c5d9d4b398b2267eef46e97c4',1942,'伪大宁县警察所所长','指挥伪警察搜捕抗日地下党员，破坏抗日组织，参与屠杀无辜百姓。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6021f334b61a4f67bf0f73837e6f7417','c64988685ee04ae2bd85219b54c81287',1943,'伪大宁县合作社主任','为日军统制物资，强征粮食棉花，导致百姓饥荒，从中贪污中饱私囊。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('82afdb42da864a84ae316985d1e93e30','94f524d6bf8346eb8c0636fb77a9ac9c',1940,'伪大宁县新民会会长','宣扬“中日亲善”，强迫群众参加新民会，收集抗日军事情报供日军使用。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7433f01e5018435b8e2bcd2a0ed5530d','5f82d23ccd2e45fd9e59f76c92bcc9ad',1938,'伪安泽县知事','在日军占领安泽期间，出任伪县知事，协助日军推行“治安强化运动”，强征民夫修筑炮楼和公路，并组织伪警察队搜捕抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('19b91d999b404353a0ffaef771ea791b','760ea963567b4048a0664ea4c37179a7',1939,'伪安泽县保安队队长','率领伪保安队配合日军多次扫荡安泽抗日根据地，杀害抗日干部和群众数十人，并参与抢劫粮食和物资。','基层头目','hanjian');
