INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('082f7642969345d89e1adc47cc3a531d','2ced595bfc314a60adc5c52f33a8bec9',1938,'伪临汾县知事','在日军占领临汾期间出任伪县知事，负责临汾县伪政权的日常运作，推行日军政令，征粮征夫，配合日伪军对周边抗日根据地的封锁与扫荡。；在临汾县城推行保甲制度，强征民夫修筑碉堡公路，为日军提供粮食和劳役，镇压当地抗日群众。；任伪临汾县知事期间，强征民夫，为日军修筑碉堡公路，迫害抗日家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('832aeec9f9164085b20c55affc9c332c','cbce9a2c60fa41d3a6b6ec2d64314c85',1938,'伪汾西县维持会会长/伪县知事','汾西县地方人物，日军侵占汾西后出面组织维持会并出任伪职，协助日军在汾西地区征粮、派款、维持治安，配合日伪军对汾西抗日根据地的清剿。','基层维持会/地方自治头目','hanjian');
