INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b7dc20cb307a4bbe8ca7b36cc46e9c3d','1c56285454d64a1a800e7e45279a0f99',1941,'伪山西急进建设团团长','山西人，组织伪“急进建设团”配合日军在山西各地进行经济掠夺和治安强化，活动范围包括晋南临汾一带，为日军搜集物资、情报。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5c9e9e3e6e40416abee5fb0ad338160e','bc8f3a231a194ecfa0fc1d788a2b40b8',1938,'伪山西省公署宣传处处长','在伪山西省政权中负责宣传和奴化教育，推行亲日思想，为日军殖民统治制造舆论，影响范围覆盖山西全省包括临汾地区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('60db3e69848644c08f4062e503d0f23a','54e6651a36ec42db8829a0dee5205557',1938,'伪山西省公署财政厅厅长','在伪山西省政权中负责财政，为日军筹措军费、征收赋税，对山西包括临汾地区民众进行经济压榨。；抗战期间任伪山西省公署财政厅厅长，为日伪政权筹措经费，推行伪币，掠夺山西物资，其财政政策直接波及运城、稷山地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('48a086be7ddb42c5b8e7e9fd926e5ab9','e0db70eb69f94335becc6bb751af0c79',1938,'伪山西省公署教育厅厅长','在伪山西省政权中负责教育，推行奴化教育，篡改教材，向山西包括临汾地区青少年灌输亲日思想。','市县厅局级','hanjian');
