INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d8a5c17f0e834c3b9a198de20b28dcf2','cee56391be664a2d872d18517ce9872d',1940,'伪汾阳警察局局长','效忠日军，指挥伪警察搜捕抗日分子，严刑逼供，破坏抗日救亡活动，协助日军建立保甲制度。','市县厅局级','hanjian');
