INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9bcffbc5a3e3428fa1a679a2be5ad746','da96ee84179748f186f01444af36982e',1942,'伪吕梁地区‘自卫团’总团长','组织伪自卫团，配合日军封锁山区，袭击抗日武装，杀害多名八路军伤员和村干部。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dd2ca875696f419aa553205eab1b7310','2ce1da13b03e4efb96672249707e40a9',1938,'伪汾阳商会会长','为日军控制商业，强制推行‘军用票’，垄断粮食布匹，为日军提供物资，从中牟利。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('65afd8a276884b159e34b4c0b07b8179','9f7b3ed9c76f4eea8211fd8ebc40a461',1943,'伪冀察战区挺进军司令（活动涉及汾阳）','原国民党将领，后投敌，其部队在汾阳周边地区与日军合作，围剿抗日游击队，抢掠百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('534a391596be4fc2bb04685f40c07c56','b3e16696e9de4dbfafa9e0a4f87d0644',1937,'山西省政府主席、第二战区司令长官（后期与日军秘密接触并达成妥协）','抗战中后期推行“存在哲学”，与日军秘密谈判并达成局部妥协，允许日军在山西部分占领区保留伪政权，其部下多支力量与日伪合作进攻八路军和抗日根据地，对吕梁、石楼一带的抗日力量造成严重损失。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ff1caed644b2421d968107ee1e12eb16','12a8b4767b1e4a989997caabbb41d83a',1937,'晋绥军骑兵军军长、第七集团军总司令（后任伪职并与日军合作）','长期在晋西北吕梁一带活动，抗战后期与日军勾结，参与对晋绥抗日根据地的进攻，其部队在吕梁地区配合日伪行动，损害抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('727c4732c9894c2babf1175266e90407','9a1674f4648c48ec889a96587a5840d8',1937,'晋绥军第十九军军长、第十三集团军总司令（后期与日军妥协合作）','在晋西吕梁地区驻防期间，执行阎锡山与日军妥协路线，参与对八路军和抗日根据地的军事行动，其部在石楼、中阳、离石一带与日伪配合。','省部级/大军区级要员','hanjian');
