INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d39d6ac7ee6f46468f5102cb3c733d0a','d255dc1ec48b48db88f1279a2498b74c',1937,'伪大同宣抚班班长','任伪大同宣抚班班长，随日军进行“宣抚”活动，诱骗民众归顺，收集抗日情报，破坏群众抗日团体。','无明确职位或一般帮凶','hanjian');
