INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9b89536317d647968ea1c1403949820d','5bab58bfaec448a0ac38a91327036320',1940,'伪广灵县新民会会长','负责在广灵推行奴化教育，组织“新民会”宣传“中日亲善”，强迫学校使用伪满教材，并动员青年参加伪军，协助日军进行经济掠夺。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bbaeb5b54ea2470d9a18d78f43b0d823','be101ae50c01499eb4d1ad9af8d79b62',1938,'伪广灵县财政科科长','为日军征收各种苛捐杂税，包括“亩捐”“门牌捐”等，并负责为日军筹办粮秣，曾强行征收民间粮食和牲畜，导致当地百姓生活极度困苦。','基层头目','hanjian');
