INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8d8fd9e6ae554fb3b79b34787486ec48','27058a945c504a2f853b049422d35340',1937,'伪广灵县翻译官','为日军驻广灵部队担任翻译，多次参与审讯抗日志士，并利用翻译身份敲诈勒索百姓，曾向日军告密导致多名地下党员被捕牺牲。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3e1ee691026d4064b253e94df7fd46cf','b6f296245f9d4f6aaf1731687d0e64c8',1937,'伪广灵县维持会会长（初期）','日军占领广灵后率先组织维持会，为日军筹集粮款、提供向导，并协助日军建立伪政权，后调任伪大同县公署任职。','基层维持会/地方自治头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aee22d90104c4621b12cf0534faefce9','0a6701c6e99848af943f955f3f60f2e6',1942,'伪广灵县特务队队长','专门负责刺探八路军情报，带领特务队破坏抗日交通线，曾抓捕并杀害抗日村长数人，其特务队以手段残忍著称。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('736040cf50984d06b8f85371eeb65a60','7840583523b447a6999d9c07357583ec',1938,'伪广灵县商会会长','为日军控制广灵商业，强迫商户向日军“献金”，并垄断食盐、布匹等物资供应，从中牟利，同时为日军收购军需物资。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('afe120aa8c1143b3a3d5cc7cc37aff08','f27fdea68c0f4c87901d2593feda5141',1937,'伪晋北自治政府主席','原为大同商会会长，日军侵占大同后出任伪晋北自治政府主席，积极为日军筹粮筹款，组织伪警察协助日军清乡，迫害抗日军民。','无明确职位或一般帮凶','hanjian');
