INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0de1e62e2f93404a8640f1eb3acdc92a','529eba01fd3844d2a4780badaf25cb50',1939,'绛县伪保安队队长','组织伪保安队配合日军‘扫荡’抗日根据地，多次袭击抗日游击队驻地，杀害抗日军属，并参与日军在绛县南樊镇、横水镇等地的烧杀抢掠行动。','基层头目','hanjian');
