INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('21ad8acd1e85459e8071dd25e187aabf','2712c952e951473090d361f47ea5a135',1940,'伪粤西治安维持会联合会委员','在粤西包括云浮地区参与伪维持会联合活动，协调各伪组织为日军服务，推行保甲连坐。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c87e7cff232743fb98985c73a6e31cf0','62a6d6c8e7ab4bbfbc92c5b14abbde74',1940,'伪南京国民政府立法院院长、伪广东省政府主席','作为汪伪政权核心人物，其伪广东省政府管辖包括云浮在内的广东沦陷区，推行傀儡统治。；汪伪政权核心人物，后任伪广东省政府主席，统治广东沦陷区，推行日伪政策，影响包括佛山、三水在内的广东各地。；广东乳源人，抗战期间投靠汪精卫伪政权，任伪立法院院长、伪广东省政府主席等职，推行伪化统治，协助日军控制广东，其统治范围包括佛山、高明等地。；作为汪伪政权核心人物，主持伪广东省政，推行奴化教育、经济掠夺，其政令覆盖肇庆、德庆地区。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b26921bc499845a5a0f1489b25fbf168','c12e72a145724c39b755a2a16dce9a71',1940,'伪南京国民政府主席兼行政院院长','建立汪伪政权，其统治范围涵盖广东沦陷区，云浮地区伪政权名义上受其管辖。；建立汪伪政权，其伪广东省政府下辖肇庆、德庆等县，推行全面附日政策，为最大汉奸头目。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e1e8f35b9aa8430fa0198e1a92076ded','603ce2df5bcb46a0af7bee2df8ea7d65',1938,'伪云浮县维持会会长','日军侵占云浮期间出面组织伪维持会，协助日军征粮、拉夫、维持地方治安，镇压抗日群众。','基层维持会/地方自治头目','hanjian');
