INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('567fde5efc74446b8437fc37ba809c1f','92849dafffdd42fcb302ac17dfc6db0f',1940,'伪云浮县教育局局长','推行奴化教育，强制学校使用日伪教材，宣传“大东亚共荣圈”，压制师生抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e83853acf5714e56b1e7ee7c49c8d3b4','d3a62c82af76421eb6e33a1eca244b38',1939,'伪云浮县商会会长','为日军筹集物资、代购粮食，协助日伪对云浮地区实施经济封锁和统制。','基层头目','hanjian');
