INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('56a3dce0ffa84c61adccfb6130d99034','ce7546d10af04356983709b44dfe8ed1',1940,'伪广东绥靖公署主任','统辖广东伪军，部署对西江抗日武装的围剿，其势力范围覆盖云浮、云安一带。','基层头目','hanjian');
