INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6a9f18feff3c4e44baa825c517a7ef95','62a6d6c8e7ab4bbfbc92c5b14abbde74',1940,'伪广东省政府主席','作为广东伪政权最高头目，推行日军政策，其政令下达至云浮、云安等县，支持当地伪政权镇压抗日力量。；作为伪广东省政府主席，推行日伪统治，其政策覆盖汕尾地区，支持伪县政权建设，征粮征兵。；汪伪政权核心人物，任伪广东省政府主席期间推行奴化教育、经济掠夺，配合日军统治广东包括肇庆地区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6153a0d296804fb4aec8bbcdb003f956','e2d410ff7764440c9f0b7c403926beef',1941,'伪云浮县建设科科长','主持修建日伪据点、公路，为日军掠夺云浮矿产资源提供便利。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3fc78d82638f465181df5fa1568a68c6','932664fc2e934849b11e72ca17fe4e1a',1939,'伪新兴县维持会会长','日军侵占新兴期间出面组织伪维持会，为日军征派粮秣、拉夫，协助维持占领区秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cea3e2d648e14708ab58d1e4ad027212','7e230a0168c24006b82842e589b6e022',1940,'伪新兴县警察所所长','在伪新兴县政权中掌管警察事务，配合日军搜捕抗日人员，推行保甲连坐。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8b1ccba7d34541bc911313fd3b940181','d23546c7a14b4472a1efb38e1dab4de3',1939,'伪云浮县维持会副会长','在云浮县城组织伪维持会，协助日军征粮、派款，并诱迫乡绅附逆。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d8ed2828cc7b4cf2a8b455c0f5e8e590','85353b3a7c0a425bb1f876ca4d0a1f05',1941,'伪广东绥靖军云浮地区指挥官','统率伪军配合日军对云浮、新兴一带抗日游击队进行扫荡，强征民夫修筑据点。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d1bacc4e984f4234910b79a1a1c610cc','42f7808e176c457a8c0898c88cc51d63',1942,'伪新兴县保甲长、情报员','担任伪保甲长期间为日军搜集抗日游击队情报，带领日伪军搜村，导致多名抗日群众被捕。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7cedfa54e9a74f85b8cd9cf495bb785f','116c74012db343aa954fbec4fa2197cf',1940,'伪广东教育厅督学（附逆文化教育者）','在广东沦陷区推行奴化教育，曾到云浮、新兴等地督导伪校，宣扬“大东亚共荣”。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8d71f5f86d10479088a4ab7da086b533','62a6d6c8e7ab4bbfbc92c5b14abbde74',1940,'伪南京国民政府立法院长、伪广东省长','作为汪伪政权核心人物，其伪广东省政府管辖范围覆盖云浮、新兴，推行伪化统治、征粮征兵。；汪伪政权核心人物之一，曾兼任伪广东省长，其政策与人事安排覆盖广东全省，包括佛山、南海地区。；曾任伪广东省长，对汕头等广东沦陷区推行伪化统治，协助日军征发物资和兵员。；汪伪政权核心人物，曾兼任伪广东省长，对广东及深圳地区的伪政权运作负有总责。；汪伪政权核心人物，曾兼任伪广东省长，全面推行日军殖民政策，其伪省政覆盖茂名、电白等县。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f39517d7014c4c82bad75ec77482fec6','c12e72a145724c39b755a2a16dce9a71',1938,'伪南京国民政府主席','建立汪伪政权，其伪广东省政府下辖云浮、新兴等地，对广东沦陷区实行傀儡统治。；广东籍汉奸，建立汪伪政权，其伪政权体系延伸至广东各地，阳江地区伪政权亦受其名义统辖。；汪伪政权头号人物，活动于南京，与广西玉林无直接关联。；其伪政权在贵州设有秘密联络点，拉拢地方军政人员，息烽集中营曾关押与其相关的附逆嫌疑人员。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f453f51c2bc94a30aa140cf631c3debb','d1abe59a5d664bf18b442130fc0478a1',1944,'伪广东省长、伪宣传部长','任伪广东省长期间，其政令覆盖云浮、新兴，推行“清乡”与奴化宣传。；任伪广东省长期间，在广东各地包括河源地区推行伪化宣传与保甲制度。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b5b64f3156d54a178c9fdd10591941ae','ce7546d10af04356983709b44dfe8ed1',1938,'伪广东绥靖军总司令','统辖广东伪军，其部队在云浮、新兴一带配合日军扫荡抗日武装，强征粮秣。；广东新会人，抗战期间投敌，任伪广东绥靖军总司令，统辖广东伪军，配合日军在广东各地扫荡抗日力量，活动范围覆盖佛山、南海、高明等地。；在广东沦陷区组织伪军，其势力范围覆盖南路，配合日军对雷州半岛及徐闻地区的抗日力量进行清剿。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3060306eaebb4114a29ddd6fe8d3926a','a476142f6a644b75bc0334134eb503fa',1938,'伪广东维持会委员、伪广东省政府委员','抗战期间投靠日军，参与组织伪广东维持会，后任伪广东省政府委员，协助日军推行殖民统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('baf60edb56dc489d8a215ee7214e7523','2fd8cc09575c41a9b821f93ad2283af3',1938,'伪广州市市长、伪广东维持会会长','广州沦陷后出面组织伪广东维持会并任会长，后任伪广州市市长，为日军筹粮筹款、维持治安。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5022da1babfa4044949d5d9b550ae2b0','ce7546d10af04356983709b44dfe8ed1',1938,'伪广东维持会副会长、伪广东省政府委员','参与组织伪广东维持会，任副会长，后任伪广东省政府委员，协助日军控制广东沦陷区。；参与组织伪广东维持会，配合日军推行伪化统治。；与彭东原共同组织伪广东维持会，后任伪省政府委员，参与推行日军政策，协助维持治安与征调物资，影响范围包括广州及周边包括深圳地区。','基层维持会/地方自治头目','hanjian');
