INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a8f96ede64b44b45bf52c3eec66bf372','603ce2df5bcb46a0af7bee2df8ea7d65',1938,'伪南海县维持会会长、伪南海县县长','佛山沦陷后出面组织伪南海县维持会，后任伪县长，协助日军征粮、拉夫、维持治安，镇压抗日活动。；佛山沦陷后出面组织伪南海县维持会，后任伪南海县县长，协助日军征粮、拉夫、维持治安，镇压抗日群众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('698af1ed02e14118ad9b78f7b8d861aa','063a5e44a9d14e9a89147fc763a66e9a',1938,'伪佛山镇维持会会长','日军占领佛山后，纠集地方劣绅成立伪维持会，为日军筹款、派夫、搜集情报，迫害抗日家属。；日军占领佛山后，纠集地方劣绅成立伪佛山镇维持会，为日军筹粮筹款、登记户口、诱降抗日人员。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('49bca255590c4d5fac72a558de3cd35f','a98600d0d5454e2083ea60d3016209e4',1938,'伪广东治安维持会委员、伪广东省政府参议','广东著名赌商，广州沦陷后投靠日军，参与伪政权，利用帮会势力为日军控制广州及佛山周边地区服务。；广东沦陷后附逆，参与伪政权筹组，利用帮会势力为日军维持广州、佛山一带治安，包庇烟赌。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8405a42a4ff14fd6ab817316c4bedd67','6b66e91ca33943a6a5867bb9076f13a6',1938,'伪广东治安维持会会长','广州商团叛乱首领，广州沦陷后出任伪维持会会长，协助日军维持广州及珠三角地区统治，后任伪广东省政府委员。；广州沦陷后出任伪维持会会长，后任伪广东省政府委员，协助日军控制广东包括佛山在内的沦陷区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('11da973e9b7a4963a85961283044c42c','2fd8cc09575c41a9b821f93ad2283af3',1940,'伪广东省政府主席、伪广州市市长','汪伪政权在广东的主要头目之一，历任伪广州市长、伪广东省主席，推行日军殖民政策，镇压广东抗日力量。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('01b8f148e21d4d13bfd2626c227ecaec','62a6d6c8e7ab4bbfbc92c5b14abbde74',1940,'伪广东省政府主席、伪国民政府代主席','汪伪政权核心人物，曾任伪广东省主席，直接管辖佛山地区，推行“清乡”与奴化教育，协助日军掠夺物资。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c2108cf767ab4bf89c9b8b5f0abdf1e8','d1abe59a5d664bf18b442130fc0478a1',1940,'伪广东省政府委员、伪宣传部长','汪伪宣传系统头目，在广东推行亲日宣传，控制佛山等地报刊与教育，毒化民众思想。；在广东推行奴化宣传，控制舆论，为日军侵略辩护，毒化沦陷区民众思想。；汪伪政权宣传与地方伪政要员，参与伪广东省政，推行亲日宣传和伪化教育，对广东各地包括粤西地区产生附逆影响。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('79570897346d4ca28882788500a3560a','c12e72a145724c39b755a2a16dce9a71',1938,'伪国民政府主席、伪行政院长','广东番禺人，投降日本后建立汪伪政权，其伪政权直接统治广东及佛山地区，是抗战时期最大汉奸。；建立南京伪政权，其伪广东省政府下属机构延伸至河源地区，推行奴化教育与经济掠夺。；公开投敌，建立汪伪政权，其伪政权体系覆盖广东湛江等地，推行“和平反共建国”卖国路线，协助日军统治沦陷区。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ade1ccc202da4c41bd7f86d0066acb6b','084a8b66c5e446d3a73b6e2d5205b4d8',1940,'伪广东省政府委员、汪伪中央监察委员','汪精卫之妻，积极参与汪伪政权，在广东扩展伪势力，干预佛山等地伪政权人事与物资征调。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ccca33b6ab07430cba58094749f2929b','86e982eb4f0043c4b6f7b586ec525f98',1940,'伪广东绥靖公署主任、伪广州警备司令','汪伪军事头目，统率伪军配合日军在佛山、南海、顺德等地“扫荡”，进攻抗日游击队。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7f537a1ca38a44b59af3b4017fd817bb','8f72b61f266b479d87bc4f107b9ec330',1940,'伪南海县县长','接替陈耀任伪南海县长，推行保甲制，强征粮食，配合日军清乡，镇压西樵、九江一带抗日武装。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('20ecc24c76a042b6b5d8a1b2c3707183','99644ca9279d49e0861fc8f9797d6486',1940,'伪顺德县县长','汪伪政权委任的顺德伪县长，在顺德及佛山周边地区为日军征粮、征税，破坏抗日根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5f90d790103c4875bde5cf3d38a7a2fb','35df55c6f6a04b3e941c07cd3aa19fd6',1940,'伪三水县县长','伪三水县长，控制佛山三水一带，协助日军封锁西江，搜捕抗日人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('25e5ab2ceb34436c823a0f6bc4fc8081','5d8631ff8d0a40489f8b334a9d83502d',1940,'伪佛山镇镇长','汪伪时期佛山镇伪镇长，执行保甲连坐，为日军征发劳工、物资，监视居民言行。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('54031064742049f7b8b4f4979394a4b8','08d0fd9c71ba4cadb6e75ecacd3730e3',1941,'伪南海县警察局长','控制南海县伪警察，配合日军搜捕抗日分子，在佛山城区实行宵禁与户口清查。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5380a42a78ac4fdabfc42905f46e33f2','42f7808e176c457a8c0898c88cc51d63',1939,'伪佛山商会会长','佛山商界附逆代表，为日军筹款、摊派物资，协助日伪控制佛山粮食与日用品贸易。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7d77e46c22994f93af08034e8d4a85d3','7f94567029794bb4a5d21ed0aef46388',1940,'伪广东教育厅长','在广东推行奴化教育，佛山各校被迫使用汪伪教材，灌输“大东亚共荣”思想。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3eb054b13be2471797d7b05158d843e5','845de899b20e4631bbf68676aa47dec8',1940,'伪广东省政府秘书长、伪建设厅长','汪伪广东省要员，参与制定掠夺佛山及珠三角物资的政策，支持日军“以战养战”。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f0777660a0ab4cd1960319c44c0a454a','2378268bb6eb4de58319a82ddd658b97',1940,'伪广东财政厅长','负责汪伪广东财政，在佛山等地强征苛捐杂税，为日军及伪政权搜刮民财。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7ba00a85b8cb47ce8c18f1acb7b1d41b','11095691d2d9465c8659ea39b5fd429f',1941,'伪广东绥靖军师长','率伪军驻防佛山、南海，多次配合日军进攻西海抗日根据地，杀害抗日军民。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f2e0d249da3f49cfb62f4f27cb3e39d3','50da58de49ed4a528c1754acb949ad36',1938,'伪三水县维持会会长、伪三水县政府县长','抗战期间投靠日军，在三水组织伪维持会，后任伪三水县政府县长，协助日军征粮、拉夫、清乡，镇压抗日民众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3690e6c27c28447d99ee5fe1b24636ea','603ce2df5bcb46a0af7bee2df8ea7d65',1939,'伪三水县警察局局长','任伪三水县警察局局长期间，配合日军搜捕抗日人员，推行保甲连坐，勒索当地百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8bcfebc12e4a493bbf242bdc8bfde500','9ddc37b48e534b7eb3ff655f97f058fa',1938,'伪南海县维持会会长、伪南海县政府县长','佛山南海沦陷后投敌，组织伪维持会，后任伪南海县县长，为日军筹粮筹款，维持伪秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0d052afa724748be9af1a9f04a57c80a','08d0fd9c71ba4cadb6e75ecacd3730e3',1938,'伪佛山维持会会长','佛山沦陷后出面组织伪佛山维持会，协助日军安民、征粮、招募伪警，压迫佛山镇商民。；佛山沦陷后组织伪维持会，协助日军管理佛山镇，推行保甲、征发物资，是佛山本地早期附逆代表人物。；佛山沦陷初期组织维持会，协助日军接管市政，维持秩序并征集物资。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('84e2bc45430c4904a8052c406fe69f66','99644ca9279d49e0861fc8f9797d6486',1938,'伪广东治安维持会委员、伪佛山镇镇长','在佛山地区依附日伪，参与伪政权基层统治，协助日军推行保甲、征丁、征粮。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e52bef86cae7402aa3e179bc7d3d88e2','e0084ea11e804593a3e43a7c28d2fc67',1938,'伪广东绥靖军第四路司令、伪珠江三角洲剿共军司令','广东著名汉奸武装头目，活动于珠江三角洲包括佛山、三水一带，配合日军扫荡抗日游击队，残害百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d14dd08c47644bf8a2d8aade5e02b092','baefea53d8cf403da4493c81a5fa3e4b',1938,'伪广东绥靖军头目、伪三水一带伪军首领','在珠江三角洲及三水、佛山周边组织伪军，为日军效力，参与清乡、扫荡，勒索地方。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1acd73f148214fc9a745758f0f97611b','084a8b66c5e446d3a73b6e2d5205b4d8',1938,'汪伪政权中央监察委员、伪广东政治指导员','汪精卫之妻，参与汪伪政权，在广东活动，督导伪广东省政，支持日伪统治。；汪精卫之妻，积极参与汪伪政权建立，曾赴广东活动，干预伪广东省政，支持其弟陈耀祖等亲属把持广东伪政权，是汪伪集团在广东的重要幕后人物。；汪精卫之妻，常驻广东干预伪政权事务，为日军统治广东出谋划策。；在广东沦陷区积极从事汪伪活动，干预珠海及中山一带伪政权人事与治安，协助日军镇压抗日力量。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1edc673738e44bfa92b4eaae2646108f','d1abe59a5d664bf18b442130fc0478a1',1938,'伪南京国民政府宣传部长、伪广东省政府委员','汪伪政权宣传要员，后在广东参与伪政权活动，推行奴化宣传。；负责汪伪宣传，在广东推行奴化教育，佛山地区学校亦被迫使用伪教材。；在广东推行奴化宣传，佛山、顺德等地伪教育、文化附逆活动受其指导。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5dbd170c2e944d6ead96c7ccb019b53c','d85cd285c30b4eb0af400dc4a45494eb',1940,'伪广东省政府委员、伪广东民政厅厅长','在伪广东省政府任职，协助日军推行民政、保甲、征粮等政策，波及佛山、三水地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('eac84212aed94c53ba9cea75e0a63525','442efeeab3ce406d9c88cf819802f905',1940,'伪广东省政府委员、伪广东财政厅厅长','负责伪广东财政，为日伪筹措经费，压榨沦陷区民众，包括佛山、三水一带。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a33d5364aa7c4ab793e6bac0c6e3fa3b','2378268bb6eb4de58319a82ddd658b97',1940,'伪广东教育厅厅长','在广东推行奴化教育，篡改教材，宣传“大东亚共荣”，影响佛山、三水等地学校。；汪伪广东教育厅厅长，推行奴化教育，篡改教材，宣传所谓大东亚共荣。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('450733aae37d4f09acb559f6bfb02309','075b5b4817584064baada36d1055f1e2',1940,'伪广东警务处处长','统管伪广东警察，配合日军镇压抗日活动，在佛山、三水等地搜捕抗日人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('012ffd7748c14c688fa5aa401a29aae4','ce7546d10af04356983709b44dfe8ed1',1940,'伪广东绥靖军司令','率伪军配合日军在广东各地包括佛山、三水进行扫荡，残害抗日军民。；统率伪广东绥靖军，配合日军在广东包括肇庆、广宁一带进行扫荡，进攻抗日游击队。；在广东南路包括茂名、电白、化州等地收编土匪与散兵，组织伪军配合日军扫荡抗日游击队。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d60c31fcc8b443ba80234460ef4138d1','9e1d574f9d114fa8829216019baa04fe',1940,'伪三水县保甲长','在三水基层推行保甲制度，协助日军征粮、征夫、监视民众，压迫乡里。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c83af98490584d389c57f112726516e2','04b0dd9ad1db4a48ac0d045be3462620',1941,'伪三水县自卫队队长','组织伪自卫队，配合日军在三水清乡，搜捕抗日游击队员及其家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e3b58e1785e84135ab4e77a3f58610a9','d18502442f354d8fb6b52487097632f5',1939,'伪佛山商会会长','在佛山沦陷区为日伪筹款筹物，控制商会，协助日军经济掠夺。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('baf0a2a887a448fabcff8dbbd56ca1ae','d2631876d39045218d683a391deb9539',1939,'伪南海县警察局局长','在南海、佛山一带配合日军维持治安，逮捕抗日嫌疑人员，勒索商户。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9b7ce80aa6884f6f80a1e1fd9aeb6e38','c444c2eb70bb4afda2c8b43299fc692c',1938,'伪广东绥靖军第一路司令','广东汉奸武装头目之一，活动于广东西江、北江一带，包括三水周边，配合日军作战。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ebea7ac61545436e86ba2b9755835544','4ffa32e45d104ce88220a4d3f3942ffb',1940,'伪广东省政府主席、伪广州绥靖公署主任','汪伪政权在广东的最高头目之一，1940年后主持伪广东省政府，推行日伪统治，镇压抗日活动，其势力覆盖佛山、南海一带。；汪伪政权在广东的最高行政长官之一，主持伪广东省政务，推行日军殖民统治政策，镇压抗日活动。；汪伪政权在广东的最高行政长官，主持伪广东省政务，推行日军殖民统治政策，镇压抗日活动，1944年被刺身亡。；广东新会人，但在广东全省包括梅州地区推行伪政，任伪广东省政府主席期间，配合日军扫荡、征粮，其伪政权延伸至梅州周边沦陷区。；汪伪政权在广东的最高行政长官，推行日军殖民统治，镇压抗日活动，1944年被刺身亡。；汪伪政权在广东的最高头目之一，主持伪广东省政务，推行日伪统治，镇压抗日力量，其势力覆盖广东包括韶关周边地区。；陈璧君之弟，汪伪广东省政府主席，控制华南伪政权，其势力范围与广西东部相邻。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('94464c44239c49d7b04eda075e5d6273','845de899b20e4631bbf68676aa47dec8',1940,'伪广东省政府秘书长、伪广州市长','汪伪政权广东省要员，参与伪政权运作，协助日军维持广东沦陷区统治，影响包括佛山、南海地区。；汪伪政权在广东的重要成员，曾任伪广东省政府秘书长、伪广州市长等职，参与广东沦陷区的伪政权运作。；汪伪广东省政府要员，协助陈耀祖处理伪政，参与对广东沦陷区民众的统治与镇压，与粤北伪政权体系有关联。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('70ed21bb60604bd69d2b88584632d554','86e982eb4f0043c4b6f7b586ec525f98',1938,'伪广东江防舰队司令、伪广州要港司令','原国民党海军人员，广州沦陷后投敌，任伪广东江防舰队司令，配合日军在珠江三角洲及佛山、南海水道进行封锁与扫荡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('60e75d0cc0234b168561a6f5969b9683','075b5b4817584064baada36d1055f1e2',1938,'伪南海县维持会会长、伪南海县长','南海沦陷后出面组织维持会，后任伪南海县长，为日军征粮、拉夫、维持治安，直接服务于佛山南海地区的日伪统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6fcfde2d4a6f4e04be8d7b566bae00cd','99644ca9279d49e0861fc8f9797d6486',1939,'伪南海县警察局长','在南海县伪警察系统任职，配合日军搜捕抗日人员，控制佛山、南海一带治安，镇压民众抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a3c8d4706dcc41a2a0e0f79389bf4137','a98600d0d5454e2083ea60d3016209e4',1938,'伪广东财政厅顾问、烟赌捐商','广东著名烟赌商人，广州沦陷后与日伪合作，承包烟赌税捐，为伪政权筹措经费，其势力及于佛山、南海一带。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d538ec36bc9b49f3aa0a2332b12e7650','50da58de49ed4a528c1754acb949ad36',1938,'伪广东绥靖军头目、地方武装首领','广州及珠江三角洲沦陷区投敌武装头目之一，率部配合日军扫荡抗日游击队，活动范围包括南海、佛山周边。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1ed8d3b8a7414a88a35a5136a6440a06','ef976cd5ef0f475686687168cc845c74',1940,'伪南海县自卫大队长','组织伪自卫武装，协助日军清乡，在南海、佛山地区搜捕抗日分子，强征粮食劳工。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e6e32171ddfe4c54932726cacb6b0473','b5bd49b1a3cf42a7912c0910aa8e9ea0',1939,'伪佛山镇商会会长','佛山商界附逆代表，协助日军统制物资、摊派捐款，维持伪政权在佛山镇的经济控制。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f4328eb617444a02b7fa17323bd734dd','a2e4190c87b449e685d78c118a6801b5',1940,'伪南京国民政府财政部长、伪广东省长','汪伪政权核心成员，曾兼任伪广东省长，主导广东沦陷区财政与行政，影响佛山、南海等地。；汪伪政权要员，曾兼任伪广东省长，控制广东及深圳地区的经济掠夺。；汪伪政权要员，曾兼任伪广东省长，参与对广东沦陷区的经济掠夺与伪政权建设，影响覆盖湛江地区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8a5b04f143324c6fafc79c00b7cb3c33','d1abe59a5d664bf18b442130fc0478a1',1940,'伪南京国民政府宣传部长、伪广东省长','汪伪政权宣传与地方行政要员，曾任伪广东省长，推行奴化宣传，其统治范围包括佛山、南海。；汪伪宣传系统头目，兼任伪广东省长期间推行奴化教育，影响深圳等地。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('922f9ce011124d4a88f68b680cb150ad','664d3df731bb4293bee63eea6deacb2d',1938,'伪南京国民政府外交部长、伪广东省长','汪伪政权要员，曾任伪广东省长，参与广东沦陷区统治，影响佛山、南海地区。；汪伪政权要员，参与伪政权统治，其活动与华中包括河南沦陷区伪政权体系有关联。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6b0f933810c9421dabd47cb02f5b637f','c12e72a145724c39b755a2a16dce9a71',1940,'伪南京国民政府主席、伪广东省长','汪伪政权最高首领，其政权统治广东沦陷区，佛山、南海地区亦在其伪政权控制之下。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0f038a953d554a1da07ec540cd1898e9','99644ca9279d49e0861fc8f9797d6486',1939,'伪南海县警察局局长','在佛山及南海一带组建伪警察队伍，配合日军搜捕抗日志士，勒索商户，残害百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('29ab790244a142cd92cc1e3bcd8e3c8f','2fd8cc09575c41a9b821f93ad2283af3',1938,'伪广东省政府主席、伪广东治安维持会副会长','广东沦陷后投敌，历任伪维持会副会长、伪省长、伪省政府主席，推行日军殖民统治，影响覆盖佛山地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8619789ab9cf43a49d6dce91a6affe3d','ce7546d10af04356983709b44dfe8ed1',1938,'伪广东省政府委员、伪广州市市长','附逆后参与伪广东政权，协助日军征发物资、镇压抗日活动，其政令亦下达佛山一带。；在广东伪政权中任要职，协助日军推行殖民统治，镇压抗日活动。；广东沦陷后投敌，历任伪广东省政府委员、伪广州市市长等职，协助日军推行殖民统治，在广东地区影响较大，其活动范围覆盖广东多地。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('79bb6d4671e04e74b5da1235276bf352','c12e72a145724c39b755a2a16dce9a71',1938,'伪南京国民政府主席、伪行政院院长','公开投敌，建立全国性伪政权，广东及佛山地区伪组织均受其名义统辖，推行“和平反共建国”卖国路线。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5dbdb911c0424b148474e88ebdfcf012','62a6d6c8e7ab4bbfbc92c5b14abbde74',1938,'伪南京国民政府代主席、伪行政院院长','汪精卫死后继任伪政权头目，继续维持日伪统治，广东佛山等地伪政权在其体系内运作。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d44a1211debf443fa2bede6f2838038e','a2e4190c87b449e685d78c118a6801b5',1938,'伪南京国民政府财政部长、伪上海市市长','汪伪政权核心人物，参与对广东沦陷区的经济掠夺与物资统制，佛山地区亦受其政策影响。；投靠日本，参与汪伪政权，配合日军在华东及华北包括陕西周边地区进行殖民统治和经济掠夺。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d609851e24f545e9bd2b3bbd130177fe','845de899b20e4631bbf68676aa47dec8',1938,'伪广东省政府秘书长、伪广州市市长','参与伪广东政权运作，协助日军控制佛山等地的行政、经济与文教。；在广东日伪政权中负责行政与宣传，协助日军推行殖民统治。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('351bb7f7102945128b5e265777b9ae2c','86e982eb4f0043c4b6f7b586ec525f98',1939,'伪广东绥靖军总司令','统率伪军配合日军在广东包括佛山地区进行“扫荡”，进攻抗日游击队，残害民众。；汪伪政权在广东的军事头目，统率伪军配合日军扫荡抗日游击队，活动范围覆盖潮汕地区，包括揭阳、揭西一带。；汪伪政权在广东的军事头目，统率伪军配合日军在广东各地进行清乡、扫荡，活动范围涉及潮汕地区。；统辖广东伪军，包括宝安、深圳地区的伪军部队，配合日军作战，进攻东江抗日游击队。；统率伪广东绥靖军，配合日军对广东抗日武装进行扫荡，活动范围包括粤中、粤北部分地区。；统率伪广东绥靖军配合日军作战，参与对广东各地抗日武装的扫荡，其势力范围包括雷州半岛与广州湾周边。；统率伪军配合日军在广东各地包括南路湛江地区进行清乡扫荡，镇压抗日武装。；统率伪军配合日军在广东各地包括雷州半岛、遂溪进行扫荡和镇压抗日力量。；统率伪广东绥靖军，配合日军对广东抗日根据地和游击区进行扫荡，抓捕抗日人员。；统率伪广东绥靖军，配合日军对广东抗日根据地和游击区进行军事进攻，残害百姓。；统率伪军配合日军进攻抗日根据地，进行清乡与扫荡。；汪伪政权在广东的伪军高级将领，指挥伪军配合日军在广东包括韶关地区进行军事行动。；汪伪政权任命为伪广东绥靖军总司令，统率伪军配合日军在广东各地扫荡，包括粤北韶关一带。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6a65c4bca4094a5587a73e0b2404adde','f2a6bebd8b1b4d6cab6d363eed10c955',1940,'伪南海县保安大队大队长','在佛山、南海一带率领伪保安队随日军下乡清乡，烧杀抢掠，破坏抗日根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('779de0caec9747e29f2c6cd2b63b88a0','7f94567029794bb4a5d21ed0aef46388',1940,'伪南海县教育科科长','在佛山地区推行奴化教育，强制学校教授日语和亲日课程，毒化青少年。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f2adca629bd048248e74a4a1a91a220d','b985f4636ad24596ab365d517497793c',1939,'伪佛山商会会长','控制佛山商业，为日军筹款筹物，配合经济统制，压榨商户与市民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('48afdc0db64044b2a80cc6fb30761f21','20d929c2ab834e3f97929f056a6cd595',1939,'伪南海县保甲长、维持会骨干','在佛山镇内协助日军登记户口、征发劳役、监视居民，举报抗日人员。','基层帮凶(维持会系统)','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7b36e63cee4043f08d83ec4791e5b2ab','50da58de49ed4a528c1754acb949ad36',1938,'伪顺德县维持会会长、伪顺德县县长','顺德沦陷后出面组织维持会，后任伪顺德县县长，协助日军征粮、拉夫、维持治安，镇压抗日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c5f1b7304a83462b959a9e5bd064d0dc','35df55c6f6a04b3e941c07cd3aa19fd6',1939,'伪顺德县警察局局长','在顺德地区组建伪警察队伍，配合日军搜捕抗日人员，推行保甲连坐，控制沦陷区基层。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1ce49e65c23345369e811d737693b1ff','88cd612e1d90419789b11f585a0c7bac',1938,'伪陈村维持会会长','在顺德陈村一带组织维持会，为日军筹集物资、情报，协助管理码头与交通线。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('32a4bf2572d54de29e661ba5c5dbd8ea','9ddc37b48e534b7eb3ff655f97f058fa',1939,'伪南海县县长','佛山南海沦陷后任伪县长，配合日军推行伪化统治，征粮征税，镇压抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('40c17b1e411b46efb54bf06d200fe23c','7f94567029794bb4a5d21ed0aef46388',1938,'伪广东治安维持会委员','在广州及佛山周边参与伪维持会活动，协助日军推行伪化政策。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3084c40a412d468a8307746b5edb02e4','2fd8cc09575c41a9b821f93ad2283af3',1938,'伪广东治安维持会会长、伪广东省省长','广东沦陷后出任伪维持会会长，后任伪广东省省长，统管包括佛山、顺德在内的沦陷区伪政，协助日军征粮、拉夫、镇压抗日。；广东伪政权首要人物，历任伪维持会会长、伪省长，统辖包括汕头在内的广东沦陷区伪政，推行日军殖民政策。；广东沦陷后出面组织伪治安维持会，后任伪广东省省长，全面协助日军统治广东，包括湛江、广州湾周边地区的伪化工作。；广东沦陷后投敌，组织伪广东省政权，协助日军统治广东各地包括南路湛江、遂溪一带。；广东沦陷后出任伪广东治安维持会会长，后任伪广东省省长，协助日军统治广东，包括潮汕沦陷区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('408ff5d98d3a441086259270067acb6e','ce7546d10af04356983709b44dfe8ed1',1938,'伪广东治安维持会副会长、伪广东省政府委员','参与伪广东省政权，协助日军在广东各地包括佛山、顺德推行伪化统治。；广东沦陷后投敌，参与组织伪广东治安维持会，后任伪广东省政府委员，协助日军维持广东沦陷区统治。；广东沦陷后投敌，参与组织伪广东治安维持会，后任伪广东省政府委员，协助日军推行殖民统治。；与彭东原共同组织伪广东政权，参与日军在广东的殖民统治，协助征发物资与劳工，影响范围覆盖南路及广州湾地区。；在广东伪政权中任职，协助日军推行殖民政策，影响覆盖湛江、遂溪等沦陷区。；投敌后任伪广东治安维持会副会长，参与伪广东省政府，协助日军推行殖民统治，影响波及潮汕。；广东沦陷后参与伪政权，任伪广东治安维持会副会长，后任伪广东省政府委员，协助日军维持占领区秩序，参与征粮、征夫及反共宣传。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fb3ef0ec7f4849fdb7632e811a108dd0','c12e72a145724c39b755a2a16dce9a71',1940,'伪南京国民政府主席、伪广东省政府主席（名义）','建立伪南京政权，广东伪政权在其体系下运作，佛山、顺德等地伪组织均受其名义统辖。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4770a52d12574c60a32c4978aba93918','62a6d6c8e7ab4bbfbc92c5b14abbde74',1940,'伪南京国民政府代主席、伪广东省政府主席','曾任伪广东省政府主席，统辖广东沦陷区包括佛山、顺德的伪政，推行日军政策。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('de226ffca51747438c19d8d6cfc86af5','e0084ea11e804593a3e43a7c28d2fc67',1940,'伪广东绥靖军司令','统率伪军在广东包括佛山、顺德一带配合日军扫荡抗日游击队，维持伪统治。；汪伪广东绥靖军头目，率伪军配合日军在广东各地清乡、扫荡。；统领伪军配合日军在广东各地扫荡抗日游击队，实行“三光”政策。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bf2e41af286a4b5fadf387ce48fb3bc6','075b5b4817584064baada36d1055f1e2',1940,'伪顺德县保安大队大队长','在顺德组织伪保安队，配合日军清乡，搜捕抗日人员，控制乡村。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bcfe367bd1a74780a5bf9174d21be5d7','4f53dfa89929459f912b974078022d9c',1940,'伪佛山镇镇长','在佛山镇推行保甲制度，协助日军征粮、征丁，维持伪政权基层统治。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a9149b9830f34043a07edd4018a91750','a2e4190c87b449e685d78c118a6801b5',1940,'伪南京国民政府财政部长、伪广东省政府委员','参与伪政权财政与广东伪政，间接影响佛山、顺德沦陷区经济掠夺。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('714e24cfd8b34991a0a3b4422bf267f8','4ffa32e45d104ce88220a4d3f3942ffb',1939,'伪广东省政府委员、伪广州市市长','在广东伪政权中任职，协助日军控制包括佛山、顺德在内的珠三角地区。；在伪广东省政府中任职，后任伪广州市市长，协助日军管理城市、征调物资、压制抗日活动，其伪政权体系延伸至深圳、盐田等珠江三角洲地区。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dd3969330c1645bfb811d4b26d460624','d85cd285c30b4eb0af400dc4a45494eb',1941,'伪顺德县教育科科长','在顺德推行奴化教育，改编教材，宣传“大东亚共荣”，毒化青少年。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('57780b41c7c94da883c39dd2288501b0','ad0f5245dc5843a1bdc28dccac66adb4',1940,'伪南海县警察局局长','在南海、佛山一带组建伪警察，配合日军搜捕抗日分子，推行保甲连坐。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('586f9f316f6643849616ef7ac71a96df','c07058daa77046b08b3fdb1f962aca45',1940,'伪三水县县长','在三水及佛山周边地区任伪县长，协助日军征粮、拉夫，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('999d4e903a62466bbc7815a5a4436272','86e982eb4f0043c4b6f7b586ec525f98',1940,'伪广东绥靖军副司令','协助指挥伪军在佛山、顺德一带配合日军扫荡，维持伪统治。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('81423134b03e4f66bcbf4548eddd5061','e0084ea11e804593a3e43a7c28d2fc67',1938,'伪广东绥靖军暂编第二十师师长、伪珠江三角洲联防司令','广东番禺人，抗战期间投靠日军，组织伪军盘踞珠江三角洲，在番禺、顺德、中山、南海、佛山一带征收军粮、勒收保护费、配合日军扫荡抗日游击队，残害民众，被称为“市桥皇帝”。其势力范围覆盖佛山及高明周边地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('62b613d03c8e47ff810e826956df7318','075b5b4817584064baada36d1055f1e2',1938,'伪广东绥靖军暂编第二十师副师长','李辅群部伪军主要头目之一，协助李辅群在珠江三角洲地区组织伪军、配合日军作战，活动范围包括佛山、南海、顺德等地。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('849234f91abb453a8461803b01d797c4','603ce2df5bcb46a0af7bee2df8ea7d65',1938,'伪佛山维持会会长、伪南海县县长','佛山沦陷后出面组织伪维持会，后任伪南海县县长，为日军征集物资、维持治安、推行保甲制度，协助日军统治佛山及南海地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a4a19f427a9a4799a1460dcb7a212eab','063a5e44a9d14e9a89147fc763a66e9a',1938,'伪南海县维持会副会长','佛山沦陷初期参与组织伪维持会，协助日军维持地方秩序、征发民夫物资。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('55ff8305570849229ffe2556d5ff95b6','15e24ae5624c45b69222a7463115e50f',1938,'伪三水县县长','三水沦陷后投敌，任伪三水县县长，配合日军统治三水及邻近高明地区，征收赋税、推行伪化教育。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5f34f486ac61438bbf4d97ca4ff4adab','99644ca9279d49e0861fc8f9797d6486',1939,'伪高明县维持会会长','高明沦陷后出面组织伪维持会，为日军征集粮食、民夫，协助日军维持高明地区统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4b0c36f6523a4a4fa1713970125f599f','2712c952e951473090d361f47ea5a135',1938,'伪广东和平救国军总司令','广东人，抗战期间投靠日军，组织伪和平救国军，在广东各地配合日军作战，其势力曾活动于珠江三角洲及佛山周边地区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a2e2d70bb55847adafebaa6b4b202e3a','d85cd285c30b4eb0af400dc4a45494eb',1938,'伪广东省政府委员、伪广州市市长','广东人，抗战期间投敌，历任伪广东省政府委员、伪广州市市长等职，协助日军推行伪化统治，其政策影响覆盖佛山等周边地区。；在汪伪广东省、广州市政权中任职，参与推行伪政，配合日军经济统制和治安强化。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1254c8b2cf18452a8c675e6fce092cfb','5e606d59f6b44906b34555ad8d2022c8',1938,'伪广东绥靖军第一师师长','广东人，抗战期间投敌，任伪广东绥靖军第一师师长，在佛山、南海、顺德一带配合日军扫荡抗日游击队。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b9cb935d10234f5982342a1b569d8037','0a21ead19059440a8c5b0c87e227273d',1938,'伪广东绥靖军第二师师长','广东人，抗战期间投敌，任伪广东绥靖军第二师师长，活动于珠江三角洲地区，配合日军作战。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6cff1509a4454f4fa2e4a11dc187c124','86e982eb4f0043c4b6f7b586ec525f98',1938,'伪广东绥靖军第三师师长','广东人，抗战期间投敌，任伪广东绥靖军第三师师长，在佛山周边地区配合日军扫荡抗日力量。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1bff3e37d0674772b79a7e1f3c47e8b2','8f72b61f266b479d87bc4f107b9ec330',1938,'伪南海县警察局局长','佛山沦陷后投敌，任伪南海县警察局局长，协助日军维持治安、搜捕抗日人士，推行保甲制度。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('66841f78dc154c60ad80e28261486438','fd19f88c94f04a78941b420e6b3a7734',1938,'伪佛山商会会长','佛山沦陷后投敌，任伪佛山商会会长，为日军征集物资、摊派款项，协助日军经济掠夺。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e089a84b1f55480ab35ac2e6d82a5355','62a6d6c8e7ab4bbfbc92c5b14abbde74',1938,'伪南京国民政府立法院长、伪上海市长、伪国民政府代主席','原国民党改组派要员，1938年随汪精卫投敌，参与建立汪伪政权，历任伪立法院长、伪上海市长、伪国民政府代主席等职，为汪伪政权核心人物之一，广东乳源人，与广州地区有籍贯关联。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0c5848c12dd847819950a603120b85b4','4ffa32e45d104ce88220a4d3f3942ffb',1940,'伪广东省政府主席、伪广州市长','陈璧君之弟，汪伪政权在广东的主要代理人，历任伪广东省政府委员、伪广州市长、伪广东省政府主席等职，推行伪化统治，镇压抗日活动。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3ee156dd05d84fad839e3bc26fa99ad4','86e982eb4f0043c4b6f7b586ec525f98',1940,'伪广东省政府主席、伪广东绥靖公署主任','原国民党军官，投敌后任汪伪政权伪广东省政府主席、伪广东绥靖公署主任等职，协助日军维持广东占领区秩序，统率伪军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e7d5463d445d4cfca98cc2e6755b34b8','442efeeab3ce406d9c88cf819802f905',1940,'伪广东省政府委员、伪广州市长','汪伪政权在广东的重要官员，曾任伪广州市长、伪广东省政府委员等职，参与伪政权地方行政。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5d83ecdc5fde4de8833dfa1e1627200e','2378268bb6eb4de58319a82ddd658b97',1941,'伪广州市长、伪广东民政厅长','汪伪政权官员，曾任伪广州市长、伪广东省民政厅长等职，负责地方民政与伪化教育。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('24510a63d3d24377a5473a643f98b687','67fb5f1b2e0e49279cb00f55697f08f3',1940,'伪广东省政府委员、伪广东教育厅长','汪伪政权在广东教育领域的附逆者，推行奴化教育，曾任伪广东教育厅长。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e6aebd6dd2654037ab5c97b70570e04f','ce7546d10af04356983709b44dfe8ed1',1940,'伪广东绥靖公署副主任、伪军师长','原国民党军官，投敌后任伪广东绥靖公署副主任兼伪军师长，率伪军配合日军扫荡广东抗日游击区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dc5452a146e14fcb9a609c891fd33f79','0a21ead19059440a8c5b0c87e227273d',1941,'伪广东绥靖公署参谋长、伪军师长','汪伪政权在广东的伪军头目之一，曾任伪广东绥靖公署参谋长、伪军师长，参与对广东抗日力量的军事镇压。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cad90468b66a41a8b7b10832d8d100ce','075b5b4817584064baada36d1055f1e2',1940,'伪广州市警察局长','汪伪政权在广州的警察头目，曾任伪广州市警察局长，协助日军维持广州治安，镇压抗日分子。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2418bdc83e7b479f8ca8ee7fdd7f03be','11095691d2d9465c8659ea39b5fd429f',1938,'伪广州维持会会长','广州沦陷初期出面组织伪广州维持会，任会长，协助日军维持占领秩序，为早期广州伪政权代表人物。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b66df0d9a18f4902b8cf07880f9ea31e','da8834ec6b1447d89fedffed2b5371b5',1938,'伪广东治安维持会委员、伪广州市商会会长','广州商界附逆者，参与伪维持会活动，后任伪广州市商会会长，为日军经济掠夺服务。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a08f34dca9ad4532a46714f42c1a8a1b','7888344884ef4573a9ab5ee7a27c67a8',1940,'伪广东省政府委员、伪广东财政厅长','汪伪政权在广东的财政官员，曾任伪广东财政厅长，为伪政权筹措经费，配合日军经济统制。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fcb21ac5c5264582b3cacb11595b7076','e70bee90991e4908a7a90faa071096de',1940,'伪广东宣传处长、伪广州广播电台长','汪伪政权在广东的文化宣传附逆者，负责伪宣传与广播，进行亲日媚日宣传。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('60600c9f34ef41938f23968b342b8a43','9b5be9a467934c8a8eebc2f077a09a7f',1941,'伪广州市教育局长','汪伪政权在广州教育领域的附逆者，推行奴化教育，曾任伪广州市教育局长。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('de2d58ce95c849b2b82fee592c6030ff','f2a6bebd8b1b4d6cab6d363eed10c955',1942,'伪广东绥靖军团长','伪广东绥靖军头目之一，率部配合日军在广东各地进行扫荡和清乡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a5d8a449f7ec471495bf468bec340a32','3a5a046c040749728e54e7c9013775bf',1943,'伪广州市长、伪广东建设厅长','汪伪政权后期广东官员，曾任伪广州市长、伪广东建设厅长，参与伪政权地方建设与资源掠夺。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8235ed9f56a24dde97b9d7ad8772707c','e0084ea11e804593a3e43a7c28d2fc67',1940,'伪广东番禺县长、伪军头目','番禺地区伪政权与伪军头目，曾任伪番禺县长，组织伪军配合日军控制广州周边地区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('42cb5db3118a46ceb74df08fe3bf2911','ef976cd5ef0f475686687168cc845c74',1940,'伪广东东莞县长、伪军头目','东莞地区伪政权头目，曾任伪东莞县长，协助日军维持东莞占领区统治。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('55a6211ecd57471ca449b1a8d312d7cf','e6fef6aaecc045348b54f54deec27563',1938,'伪广东佛山维持会会长、伪军头目','佛山地区附逆者，组织伪维持会，后任伪军头目，控制佛山一带，配合日军行动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e7fe62ddc9d2487d827b9ac66ba00336','4ffa32e45d104ce88220a4d3f3942ffb',1940,'伪广东省政府主席','汪伪政权广东省政府主席，主持广东沦陷区伪政，推行日军殖民统治政策，1944年遇刺身亡。；汪伪政权在广东的最高行政头目之一，主持伪广东省政，推行日军占领政策，其伪政权下辖包括惠州、惠阳在内的沦陷区。；汪伪政权广东省政府主席，推行伪政令，协助日军控制广东。；广东新会人，汪伪政权广东省政府主席，推行日伪统治，镇压抗日活动，其管辖范围包括揭阳、揭西地区。；汪伪政权时期任伪广东省政府主席，推行亲日政策，协助日军维持广东沦陷区统治，其活动范围覆盖广东全省，包括揭阳周边地区。；汪伪政权广东省政府主席，统辖包括汕头在内的广东沦陷区伪政权。；汪伪政权广东省政府主席，主持广东沦陷区行政，配合日军清乡、征粮，镇压抗日力量。；汪伪政权在广东的最高行政长官，推行日军政策，镇压抗日活动，其管辖范围包括河源、紫金在内的广东全省，对当地抗日力量造成严重威胁。；汪伪政权在广东的最高头目之一，推行日军殖民统治，清远地区伪政权亦受其管辖。；汪伪政权广东省政府主席，主持广东伪政权，推行日军殖民统治政策，其辖区涵盖清远、英德周边沦陷区。；汪伪政权广东省政府主席，在广东推行伪化统治，配合日军清乡、掠夺物资。；汪伪政权广东省政府主席，推行日军殖民政策，统辖广东伪政权，对包括清远、连州在内的粤北地区进行政治渗透与招降活动。；汪伪政权在广东的最高行政头目，推行日伪法令，配合日军清乡与物资统制，影响波及南路包括广州湾周边。；汪伪政权广东省政府主席，推行日军奴化政策，统辖包括湛江在内的广东沦陷区伪政权，为日军掠夺资源、镇压抗日力量服务。；汪伪政权广东省最高头目，推行日军殖民政策，其伪政权管辖范围包括湛江、廉江等地。；汪伪广东省政府首脑，推行日军殖民政策，其政令覆盖包括广州湾在内的广东沦陷区。；在广东推行伪政，支持潮汕伪政权，为日军征粮征兵，镇压抗日活动。；汪伪政权任命为伪广东省政府主席，协助日军统治广东，包括潮汕地区，推行伪化政策。；接替彭东原任伪广东省政府主席，配合日军在广东各地推行治安强化运动，镇压抗日力量。；汪伪政权广东省政府主席，推行日军殖民政策，在广东各地包括阳江一带组织伪政权、伪军，配合日军扫荡抗日力量。；汪伪政权广东省政府主席，在广东沦陷区推行汪伪政令，配合日军进行殖民统治和经济掠夺。；汪伪政权广东省最高头目，推行日军殖民统治，配合“清乡”与物资统制。；汪伪政权任命为伪广东省政府主席，在广东推行伪化政策，配合日军经济掠夺。；汪伪政权在广东的最高行政长官，推行日军侵略政策，在广东全省包括韶关地区实施伪化统治，组织伪军配合日军作战。；汪伪政权广东省政府主席，主持广东沦陷区伪政，推行日军殖民统治政策，其伪省府势力覆盖韶关周边沦陷区及粤北部分区域。；汪伪政权在广东的最高行政头目之一，推行日军殖民统治政策，镇压广东抗日力量。；汪伪政权广东省最高行政长官，推行日军殖民统治，在广东各地包括韶关周边地区建立伪政权，征粮征税，配合日军清乡。；汪伪政权广东省政府主席，主持广东伪政权，推行日军占领政策，配合日军清乡与治安强化运动。；汪伪政权在广东的最高行政头目之一，推行伪化统治，配合日军清乡与物资统制。；汪伪政权任命为伪广东省政府主席，在广东推行伪化统治，配合日军征粮、征丁，镇压抗日活动。；广东伪政权头目，活动于广州，与广西玉林无直接关联。；广东伪政权头目，与广西贵港、平南无直接关联。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('da22a4044dbc4408b583ff8d0a16ef47','845de899b20e4631bbf68676aa47dec8',1940,'伪广东省政府主席、伪广州市市长','汪伪政权要员，曾任伪广东省政府主席、伪广州市市长，协助日军维持广州及广东沦陷区统治。；接替陈耀祖任伪广东省政府主席，并曾任伪广州市市长，协助日军维持广州地区统治。；接替陈耀祖任伪广东省政府主席，并曾任伪广州市市长，协助日军维持广东沦陷区统治。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('30889b1c82bf4a0fa9ef36b3df2e30c2','86e982eb4f0043c4b6f7b586ec525f98',1938,'伪广州市市长','广州沦陷后出任伪广州市市长，组织伪维持会，配合日军管理广州城区。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9dadf5d1b08347098a93438716a5b37b','2fd8cc09575c41a9b821f93ad2283af3',1938,'伪广州市市长、伪广东治安维持会会长','广州沦陷后参与组织伪广东治安维持会，后任伪广州市市长，为日军维持广州治安与物资征调。；广州沦陷初期组织伪治安维持会，后任伪广州市长，为日军筹粮筹款、推行奴化教育。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c5679876073c427baf9ade60d4ae9b53','ce7546d10af04356983709b44dfe8ed1',1938,'伪广东治安维持会副会长、伪军头目','广州沦陷后任伪广东治安维持会副会长，协助日军招抚土匪、组织伪军。；广州沦陷后参与伪维持会，后收编地方土匪武装为伪军，配合日军在珠江三角洲地区活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('33686d04131f43d98464acdd83201f1a','86e50968a7294fddba35a472628b948b',1938,'伪从化县维持会会长','从化沦陷期间出任伪维持会会长，为日军征粮、派夫、维持地方伪秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f9cc80daf71646f3beda614b4cde1db6','11095691d2d9465c8659ea39b5fd429f',1939,'伪从化县县长','汪伪政权委任的从化县县长，在从化地区推行伪政，配合日军扫荡与清乡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('60759963715f475e8939eedaea6d48fc','c12e72a145724c39b755a2a16dce9a71',1938,'伪国民政府主席、伪行政院院长','广东三水人，投降日本后建立汪伪政权，其伪政令覆盖广东及广州沦陷区，是华南汉奸政权最高头目。；建立汪伪政权，其伪广东省政府下辖潮汕沦陷区，对包括潮州在内的广东伪政权负有最高责任。；建立全国性伪政权，广东及潮汕伪组织均受其统辖，推行“和平反共建国”卖国路线。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ffd0ae5b7dce4352bbfe58044190fbf6','62a6d6c8e7ab4bbfbc92c5b14abbde74',1940,'伪国民政府代主席、伪行政院院长','广东乳源人，汪伪政权核心人物，继汪精卫后主持伪政，其统治范围包括广东沦陷区。；汪精卫死后继任伪政权首脑，继续维持包括潮汕在内的沦陷区伪统治。；继汪精卫后领导伪政权，继续维持广东潮汕等地伪统治，配合日军作战。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('df248392cba6470387d2232a931dffc6','d1abe59a5d664bf18b442130fc0478a1',1940,'伪宣传部长、伪广东省长','广东信宜人，汪伪宣传部长，后任伪广东省长，在广东推行奴化宣传与伪政。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d1638b94265d4edba86b7540784c2e72','d85cd285c30b4eb0af400dc4a45494eb',1940,'伪广东警务处处长','汪伪广东警务头目，组织伪警察配合日军镇压抗日活动。；掌管广东伪警察系统，在肇庆、广宁等地建立伪警察网络，配合日军维持治安、搜捕抗日人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('58441e6b61164c1da22c882987c79f4d','075b5b4817584064baada36d1055f1e2',1939,'伪广州警察局局长','广州沦陷期间任伪警察局长，协助日军维持广州治安、搜捕抗日人员。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cca8039235a34887a4ad164fb702cbff','aace34d602c24dffb9041a976489b9b3',1939,'伪广州市商会会长','广州沦陷后出任伪商会会长，为日军筹款、征调物资，属经济附逆者。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cbef60f577ea4a3ead80d1e7e1ec01b1','6b66e91ca33943a6a5867bb9076f13a6',1938,'伪广东商业联合会主席','广州商人，沦陷后与日伪合作，组织伪商业团体，为日军经济掠夺服务。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d663d511d23f431b997e1d499dd08eaf','dbabfd0e04f743518e92d715eaa30998',1938,'伪广东绥靖军总司令','广东番禺人，原国民党将领，广州沦陷后投敌，组织伪军配合日军。；广东地方实力派投敌，所部伪军在珠江三角洲包括江门、新会地区配合日军维持治安。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0fd2649161034ddc856b48ab5b4440dd','63400e54ff1e4f30b857cd94ce29440e',1939,'伪广东绥靖军师长','伪广东绥靖军头目，率伪军在广州及从化周边配合日军扫荡。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8dd30262fc304e5e9326ccf9ae18481a','f2a6bebd8b1b4d6cab6d363eed10c955',1940,'伪从化县保安大队长','从化伪保安大队头目，协助日军清乡、搜捕抗日游击队员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('01182265f43a4fe59dbdacf29ec35813','e6fef6aaecc045348b54f54deec27563',1939,'伪从化县维持会副会长','从化地方劣绅，沦陷后组织伪维持会，为日军征粮派款。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c471cc9953ce4226a9793b7d4cf179cf','084a8b66c5e446d3a73b6e2d5205b4d8',1938,'汪伪政权中央监察委员会常务委员、伪广东省政务长','汪精卫之妻，随汪投敌后参与汪伪政权核心决策，后任伪广东省政务长，在广州主持伪广东省政，推行日伪统治。；汪精卫之妻，随汪投敌后参与汪伪政权核心决策，后任伪广东省政务长，主导广东沦陷区亲日统治。；汪精卫之妻，随汪投敌后参与汪伪政权核心事务，后任伪广东省政务长，在广州等地推行日伪统治。；汪精卫之妻，随汪投敌后参与汪伪政权核心决策，曾任伪广东省政务长，推动广东沦陷区伪化统治，为日军侵华张目。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('80380b0158e344938bb61b552ed20098','4ffa32e45d104ce88220a4d3f3942ffb',1940,'伪广东省政府主席、伪广州市市长','汪伪政权广东省政府主席兼广州市市长，在广州推行伪政，配合日军维持占领区秩序，1944年被刺身亡。；汪伪政权广东省主要头目之一，曾任伪广州市市长、伪广东省政府主席，协助日军维持广东沦陷区统治。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('010b64a02ab74bc1bf6c34e3ae69661f','86e982eb4f0043c4b6f7b586ec525f98',1944,'伪广东省政府主席、伪广州绥靖公署主任','接替陈耀祖任伪广东省政府主席，兼伪广州绥靖公署主任，统辖广东伪军，协助日军镇压抗日力量。；接替陈耀祖任伪广东省政府主席，并任伪广州绥靖公署主任，统辖广东伪军警力量。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('887a8dbe8c3046c688db24a065f2fbf5','664d3df731bb4293bee63eea6deacb2d',1938,'汪伪政权外交部长、伪广东省长','汪伪核心人物之一，曾任伪广东省长，在广州参与日伪统治，战后被处决。；汪伪政权要员，曾任伪广东省长，参与广东沦陷区政务与对日合作。；汪伪政权要员，曾任伪广东省长，活动于华南，与广西邻近地区伪政权有联系。；原国民党中央候补委员，随汪精卫投敌，任汪伪外交部长、伪广东省长等职，参与签订卖国条约，协助日军维持占领区统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cacaf9c1b5114b2fa339b0a2d1a95da7','d1abe59a5d664bf18b442130fc0478a1',1940,'汪伪宣传部部长、伪广东省长','汪伪宣传系统负责人，后任伪广东省长，在广州推行亲日宣传与伪政，战后被处决。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5cfbe9f973074f6fac54c42f7d55640c','ce7546d10af04356983709b44dfe8ed1',1938,'伪广州市维持会会长、伪广州市市长','广州沦陷后组织伪维持会，任伪广州市市长，协助日军维持广州占领秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e26bccb0feb64193bdda723e41bcaeaa','2fd8cc09575c41a9b821f93ad2283af3',1938,'伪广州市市长、伪广东治安维持会副会长','广州沦陷后参与伪维持会，后任伪广州市市长，长期在广州为日伪服务。；广州沦陷后任伪广州市市长，参与伪广东治安维持会，配合日军在珠江三角洲及深圳、罗湖一带进行治安强化与物资统制。；广东伪政权头目之一，协助日军控制广州及华南地区，其活动影响覆盖广西周边。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0782d687a5974a90b0ee42b0f8429ed2','3a5a046c040749728e54e7c9013775bf',1939,'伪广州市警察局局长','任伪广州市警察局长，指挥伪警察配合日军搜捕抗日人员、维持殖民统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('eb4566e452634823b6a0512eee9eacca','075b5b4817584064baada36d1055f1e2',1940,'伪广东绥靖军总司令','统率广东伪绥靖军，配合日军在广东各地扫荡抗日武装。；统率伪广东绥靖军，配合日军对广州及周边地区进行扫荡，进攻抗日游击队。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('08f2a67a875d413492cdd3bf700999bd','f2a6bebd8b1b4d6cab6d363eed10c955',1940,'伪广东保安司令部司令','任伪广东保安司令，指挥伪保安队协助日军控制广东占领区。；统率汪伪广东保安部队，配合日军在广东各地“清乡”、扫荡抗日游击队。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7f3308d7b6c942959e30870281f066fc','e0084ea11e804593a3e43a7c28d2fc67',1938,'伪广东番禺、南沙一带维持会头目、伪军头目','在广州番禺、南沙及珠江口一带组织伪维持会与伪军，配合日军控制水路与乡村，征收捐税、镇压抗日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f5ac6fdac2cc4faabe28191d06a48ac4','baefea53d8cf403da4493c81a5fa3e4b',1938,'伪珠江三角洲护沙队头目、伪军头目','在珠江三角洲包括南沙周边水域活动，组织伪护沙队，为日军控制沙田与水道，勒索民众。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e77b27d9f5074243bafbd183e2e3f197','3bdebfa9aaef42389872c83fe0f00eb1',1938,'伪广东教育厅厅长','任伪广东教育厅长，在广州推行奴化教育，篡改教材，灌输亲日思想。；任伪广东教育厅厅长期间，在广东包括深圳、罗湖地区推行奴化教育，篡改教材，宣传“大东亚共荣圈”。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6cf46a6cbdad4f14b8ccbd3056f37b64','9b5be9a467934c8a8eebc2f077a09a7f',1940,'伪广东宣传处处长','负责伪广东宣传，在广州主办亲日报刊与广播，为日军占领制造舆论。；负责汪伪广东宣传机构，为日军侵略辩护，进行反共亲日宣传，影响范围包括韶关周边沦陷区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aeb176f48fe1498ca192e7e84a88486a','d85cd285c30b4eb0af400dc4a45494eb',1940,'伪广东财政厅厅长','任伪广东财政厅长，为日伪筹措经费，搜刮民财，支持占领统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c47b757a0a8d48faa790d5bd08de8bcd','2378268bb6eb4de58319a82ddd658b97',1939,'伪广州市商会会长','广州商界附逆代表，组织伪商会，配合日军经济统制，为日伪采购物资。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('73f65d3906284f69a06e324addde9f0e','f36cf0b0e2064e039d1614b2fbe9f4cc',1939,'伪南沙维持会会长','在南沙地区组织伪维持会，协助日军管理地方，征发劳工与物资。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5011de50947644c4bdbd2811a16a5696','084a8b66c5e446d3a73b6e2d5205b4d8',1938,'汪伪政权中央监察委员会常务委员、汪伪广东省政府指导长官','汪精卫之妻，随汪投敌后参与汪伪政权核心决策，曾赴广东活动，为汪伪在广东的统治站台撑腰。；汪精卫之妻，随汪投敌后参与汪伪政权核心决策，曾赴广东活动，为汪伪在华南建立伪政权、拉拢地方势力提供支持。；汪精卫之妻，随汪投敌后参与汪伪政权核心决策，曾赴广东活动，支持伪广东省政权，为华南地区伪政权重要后台人物。；汪精卫之妻，随汪投敌后参与汪伪政权核心决策，曾赴广东活动，支持伪广东省政权建设，为日军在华南的统治张目。；汪精卫之妻，随汪投敌后参与汪伪政权核心决策，曾赴广东活动，对包括江门、开平在内的广东沦陷区伪政权建立与维持负有重要责任。；汪精卫之妻，随汪投敌后参与汪伪政权核心决策，曾赴广东活动，对包括江门、恩平在内的广东沦陷区伪政权建立与维持负有责任。；随汪精卫投敌，参与汪伪政权建立，后常驻广东，操纵伪广东省政，为日军在华南推行殖民统治效力。；汪精卫之妻，随汪投敌后参与汪伪政权核心决策，曾到广东等地活动，广西方面亦有汪伪势力渗透背景，属广西籍汉奸要员。；汪精卫之妻，随汪投敌后参与汪伪政权核心决策，曾到广东等地活动，广西籍背景与华南伪政权网络有关联，但主要在南京、广东活动。；汪精卫之妻，随汪投敌后参与汪伪政权核心决策，曾赴广东等地活动，广西为其夫广东政治势力邻近影响区域，属汪伪政权高层附逆者。；汪精卫之妻，随汪投敌，参与汪伪政权建立，曾任汪伪国民党中央监察委员会常务委员等职，为汪伪政权核心人物之一，其活动虽主要在南京、广东，但与广西籍汪伪人员及华南伪政权网络有联系。；随汪精卫投敌，参与汪伪政权建立，虽非广西籍，但汪伪政权对广西沦陷区及周边地区伪组织有统辖影响，其附逆行为在广西有宣传与组织渗透。；汪精卫之妻，随汪投敌后参与汪伪政权核心决策，曾到广东等地活动，广西为其夫广东相邻省份，桂林、荔浦一带亦处其影响辐射范围。；汪精卫之妻，随汪投敌后参与汪伪政权核心决策，曾到广东等地活动，广西籍背景及汪伪政权在华南的渗透与桂林、广西有间接关联。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ca90396d51be46d8b5f202a26ca9c2d7','4ffa32e45d104ce88220a4d3f3942ffb',1940,'汪伪广东省政府主席','汪伪政权在广东的最高行政头目之一，推行伪化统治，配合日军掠夺广东资源、镇压抗日力量。；陈璧君之弟，任汪伪广东省政府主席期间，推行日伪统治，配合日军对广东沦陷区进行政治控制与经济掠夺，江门、开平一带在其辖境内。；陈璧君之弟，任汪伪广东省政府主席，主持广东伪政，推行日军殖民统治政策，其辖区涵盖江门、恩平等地。；汪伪政权在广东的最高行政头目之一，推行伪化统治，配合日军对广东沦陷区进行控制与掠夺。；汪伪广东省政权头目，活动于广州及华南，未见在广西柳州活动的可靠记载。；陈璧君之弟，汪伪广东省政府主席，在华南推行伪化统治，其活动与广西、桂林地区有间接关联。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('815f89efef4e439b8d7b58a23fdb8c92','86e982eb4f0043c4b6f7b586ec525f98',1944,'汪伪广东省政府主席、汪伪广州绥靖公署主任','接替陈耀祖主政汪伪广东，统辖伪军警力量，继续为日军维持占领区秩序。；接替陈耀祖主持伪广东省政，统辖伪军警，继续配合日军维持华南占领区统治。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8865954b22564986a888eb33e234da4f','442efeeab3ce406d9c88cf819802f905',1940,'汪伪广东省政府委员、广州市市长','曾任汪伪广州市长，负责广州城区伪政权的行政运作，协助日军实施物资统制与治安强化。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4c1e9d94abe34331a5e2fad2626685f7','6115e572c6e14d7c85a58e4fc07cfa8b',1941,'汪伪广州市市长','汪伪政权广州市行政负责人之一，推行伪政府政令，配合日军对广州民众的管控。','核心城市市长/省部级','hanjian');
