INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5ebcf112f2414ba1ac9939fc8cc86041','62a6d6c8e7ab4bbfbc92c5b14abbde74',1938,'汪伪政权立法院长、伪广东省长兼伪广州绥靖主任','汪伪政权核心人物之一，曾任伪广东省长兼伪广州绥靖主任，控制广州及广东部分地区伪政权与伪军。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a3556375a81d427caec8683cf7b25093','d1abe59a5d664bf18b442130fc0478a1',1938,'汪伪政权宣传部长、伪广东省长','汪伪宣传系统要员，后任伪广东省长，在广东推行亲日宣传与殖民统治。；汪伪政权核心人物之一，曾任伪广东省长，推动广东沦陷区包括湛江、雷州在内的亲日宣传与殖民统治。','省部级/大军区级要员','hanjian');
