INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0a94fba05b6a48969201d190afe461fe','50da58de49ed4a528c1754acb949ad36',1938,'伪广州维持会干事、伪保甲长','广州基层伪政权人员，协助日军推行保甲制度与人口控制。','基层帮凶(维持会系统)','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d2433e7e2ebd4bc4aa0c2f34a63ee32e','62a6d6c8e7ab4bbfbc92c5b14abbde74',1938,'汪伪国民政府立法院长、行政院长、代理主席','原国民党要员，随汪精卫叛国投敌，成为汪伪政权核心头目之一，对包括广东在内的沦陷区伪政权建立与维持负有重要责任。；虽非广西籍，但作为汪伪政权核心头目，其伪政权体系覆盖广西沦陷区及周边，对广西地区伪政权建立有间接影响。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('21c49a310397413a9d551dbc859e7f83','a2e4190c87b449e685d78c118a6801b5',1938,'汪伪国民政府财政部长、警政部长、上海市长','汪伪政权核心人物之一，参与伪政权财政、警政与特务系统，间接影响华南沦陷区伪组织运作。；汪伪政权核心成员，掌控伪财政与特务系统，其势力范围涉及华南伪政权网络。；汪伪政权核心人物，其财政与警政体系延伸至广西部分沦陷区，对广西伪政权维持会、伪警察系统有统辖关系。；汪伪政权核心成员，虽主要在南京、上海活动，但其伪政权体系覆盖广西沦陷影响区域，属全国性汉奸头目。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('08ed4fa0c690490d81cf29784de08557','664d3df731bb4293bee63eea6deacb2d',1938,'汪伪国民政府外交部长、广东省长','汪伪政权要员，曾任伪广东省长，直接参与广东沦陷区伪政权统治，推行日伪政策。','省部级/大军区级要员','hanjian');
