INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('361b8acc9f7141139fc501b7686a1a27','4ffa32e45d104ce88220a4d3f3942ffb',1938,'汪伪广东省政府主席、伪广州市市长','陈璧君之弟，历任汪伪广东省政府委员、伪广州市市长、伪广东省政府主席，是汪伪在广东、广州地区的重要代理人。；陈璧君之弟，历任汪伪广东省政府委员、主席等职，主持广东伪政，推行日军殖民统治政策，镇压抗日力量。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('989e06501b8549caaf2aa84b7f2eade8','86e982eb4f0043c4b6f7b586ec525f98',1938,'汪伪广东省政府委员、伪广州市市长','曾任汪伪广州市市长，参与广州沦陷区的伪政权行政与治安维持。；汪伪广东省政权成员，参与伪广州市政管理，配合日军经济统制与治安强化运动。；广东籍汉奸，在华南地区为日军搜集情报、推行伪化统治，其活动范围与广西、桂林邻近，对桂林抗战后方有间接威胁。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7187182466f14c88beb29cfe22d9f207','6115e572c6e14d7c85a58e4fc07cfa8b',1938,'汪伪广东省政府委员、伪广州市市长','曾任汪伪广州市市长，协助日军维持广州占领区秩序，推行伪化行政。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d00c320182b844278c86773000545065','442efeeab3ce406d9c88cf819802f905',1938,'汪伪广东省政府委员、伪广州市市长','曾任汪伪广州市市长，参与广州伪政权运作。；在汪伪广东省、广州市政权中任职，参与伪政权行政事务，协助日军控制广州及周边地区。；在汪伪广东省、广州市政权中任职，参与伪化地方行政。；广东伪政权成员，参与伪广东省政务，活动区域与广西邻近。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('796d394dfc1746e2a55f4cf3e7c8d483','3a5a046c040749728e54e7c9013775bf',1938,'伪番禺县维持会会长、伪番禺县县长','广州沦陷后参与组织番禺伪维持会，后任伪番禺县县长，为日军征粮、拉夫、维持治安。','基层维持会/地方自治头目','hanjian');
