INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8bc2c6d60a5c4b58a71542ec3f288476','e0084ea11e804593a3e43a7c28d2fc67',1938,'伪广东番禺县县长、伪军头目','在番禺、广州南郊一带组织伪军，配合日军清乡，残害抗日群众，人称“市桥皇帝”。；广东番禺人，投敌后任伪番禺县县长，组织伪军，配合日军在番禺、广州一带清乡、征粮、镇压抗日力量。；广东著名汉奸，投靠日军后组织伪军，在珠江三角洲一带配合日军扫荡，镇压抗日力量，其势力范围覆盖广东多地，与河源、紫金地区抗日活动有间接对抗关系。；广东著名汉奸，投靠日军后组织伪军，在珠江三角洲一带配合日军扫荡，镇压抗日力量。；投靠日军，在广东番禺一带组织伪政权和伪军，配合日军清乡、征粮，镇压抗日民众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ef4a0ef637bb478a9019eb86d1e6f596','ef976cd5ef0f475686687168cc845c74',1940,'伪广东增城县县长','在增城地区建立伪政权，协助日军控制广州东部，镇压当地抗日力量。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6021217e9efd4cb08f2e986a343cf4a2','3a5a046c040749728e54e7c9013775bf',1939,'伪广东南海县县长','在南海县推行伪政，配合日军对广州西南地区进行统治和经济掠夺。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1eecc5dec5714adf8bd690c916ded411','62a6d6c8e7ab4bbfbc92c5b14abbde74',1940,'汪伪政权立法院院长、伪广东省政府主席（兼）','汪伪政权核心人物之一，曾兼任伪广东省政府主席，对广东沦陷区推行傀儡统治负有责任。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e0e46d2b75954e46a15a61fcfd55c5a8','a2e4190c87b449e685d78c118a6801b5',1940,'汪伪政权财政部长、伪广东省政府委员','参与汪伪政权对广东的经济掠夺政策，通过伪政权控制广东金融和物资。；汪伪政权核心人物，参与制定日伪经济统制政策，其财政体系覆盖广东包括广州湾周边。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8420a65983724be7aec0a7c83e34cde6','07ff958e7f18410f864975f09234ac7e',1939,'汪伪特工总部主任、伪广东特工负责人','在广东建立伪特工网络，暗杀抗日人士，破坏抗日组织，配合日军镇压广州地下抵抗运动。','特工总部主任','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('197db107543144d2a948697cdf4f386f','4ff53dd874e141ef96803ca1d78fd200',1938,'伪广州市商会会长、伪广东经济协会会长','控制广州商业，为日军筹集军需物资，协助推行伪币，剥削沦陷区民众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6c92532cec564c5c9cf821b05ac58363','f50cf011f8f842fc8d69caa402ffbf67',1940,'伪广东省政府委员、伪广东教育厅长','在广东推行奴化教育，篡改教材，强迫学生学习日语，培养亲日思想。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e6e0f37ff0834a748e56e9ec2fdab9e4','7f7d8835940640f89ed6bf7a264ff93f',1938,'伪广州白云区维持会会长','在广州白云地区组织伪维持会，为日军带路、征发民夫，协助日军控制白云山周边乡村。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('195e16e185034ef084c8c7bfc1481b69','9ddc37b48e534b7eb3ff655f97f058fa',1939,'伪广州白云区保甲长','在白云区推行保甲制度，监视居民，向日军举报抗日分子，协助征粮征税。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4d69843c882144b09766e08a1b976b34','e0084ea11e804593a3e43a7c28d2fc67',1939,'伪广东绥靖军司令、伪番禺县县长','广东著名汉奸武装头目，组织伪军配合日军扫荡珠江三角洲抗日游击队，在番禺、花都一带活动，残害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9949287943e84c96afb5168b8d753ce9','075b5b4817584064baada36d1055f1e2',1938,'伪广州市维持会会长、伪广州市市长','广州沦陷后组织伪维持会，任伪广州市市长，协助日军维持广州治安与物资征调。；广州沦陷后出面组织伪维持会，后任伪广州市市长，协助日军维持广州治安、征发物资。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('66ee00f76b5c49b08fb17bd8c0e6cb46','2fd8cc09575c41a9b821f93ad2283af3',1938,'伪广州市维持会副会长、伪广州市市长','广州沦陷初期与郭卫民共同组织伪维持会，后任伪广州市市长，推行日军指令。；广州沦陷后参与伪维持会，后任伪广州市市长，协助日军控制广州，推行伪化统治。；广州沦陷后参与伪维持会，后任伪广州市市长，长期在广州市政中为日军服务。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aec55f01a64f49adab65c64af597f1fb','ce7546d10af04356983709b44dfe8ed1',1939,'伪广东绥靖军副司令、伪军头目','广东伪军主要头目之一，配合日军在广州及周边地区进行清乡、扫荡，镇压抗日力量。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('97d21bcda26545a1b54cf81df00edb5c','3a5a046c040749728e54e7c9013775bf',1938,'伪花县维持会会长','花县沦陷后组织伪维持会，为日军征调粮食、劳工，协助维持地方伪秩序。','基层维持会/地方自治头目','hanjian');
