INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7d12a5b280da4082a1247f6ed2579fd7','ce7546d10af04356983709b44dfe8ed1',1941,'伪广东绥靖军第三师师长','投敌后任伪军师长，率部在惠州、河源、龙门地区配合日军扫荡东江抗日根据地，烧杀抢掠。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('342d8ef7f01b4f6283dfef8c44e802da','f2a6bebd8b1b4d6cab6d363eed10c955',1940,'伪博罗县县长','在日军占领博罗期间任伪县长，与龙门、惠州伪政权配合，推行保甲连坐，协助日军清乡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c5e3a734ad644f149472305537d48d59','8ab4e9687c814ebf88894bde1b3f3529',1938,'伪广东维持会会长（未就任）','日军侵占广州后曾试图拉拢其出任伪维持会会长，陈炯明未接受，但日方仍将其列入拟用名单，此事在揭阳及粤东地区有传闻。；日军侵占广州后曾试图拉拢其出任伪职，陈炯明未接受，但因其旧部多附逆，常被列入相关人物讨论。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ec24bb738ccc4374a867dbe66a65f4eb','f415d17d03cf4be0b1b03573cdbe07f8',1939,'伪揭阳县维持会会长','日军侵占揭阳期间，出面组织伪揭阳县维持会，协助日军征粮、派夫、维持地方秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4e211207a5ed45709dda9303303cf843','6ab12cc3c54343e8bf4b717a73a5fb81',1940,'伪揭阳县警察局局长','在伪揭阳县政权中担任警察头目，配合日军搜捕抗日人员，镇压地方抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4e3291466496454aa8a76796f098d9d5','0d510de08c744c4f9def511254134668',1941,'伪揭阳县保安团团长','率伪保安团配合日军扫荡揭阳周边抗日游击队，强征壮丁、勒索民众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a4a9d0c7b2d041519e6a0120c83c2da3','660cce47cbfa4556854e5c4226386ce8',1939,'伪潮汕维持会副会长','在潮汕地区协助日军推行伪化统治，参与组织揭阳、潮阳等地维持会，为日军筹款筹粮。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('09f7aa983b4340e49b5a0a6652f416a6','a9708e8b7e6a4a6aacef69da8f32bb5e',1939,'伪汕头市市长','在汕头及潮汕地区推行伪政权统治，与揭阳伪政权有行政往来，协助日军控制潮汕物资。；日军侵占汕头后出任伪汕头市市长，协助日军维持殖民统治，推行伪化行政。；日军侵占汕头后出任伪汕头市市长，协助日军维持殖民统治，推行伪化政策，为潮汕地区伪政权核心人物之一。；日军侵占汕头后出任伪汕头市市长，协助日军推行殖民统治，组织伪政权维持地方秩序，镇压抗日活动。；日军侵占汕头后出任伪汕头市市长，协助日军维持殖民统治，推行伪化政策，参与镇压抗日活动。；日军侵占汕头后出任伪汕头市市长，主持伪市政，推行日伪统治措施，协助日军维持占领秩序。；日军侵占汕头后出任伪汕头市市长，主持伪市政，推行日军殖民统治，协助征发物资与劳工。；日军侵占汕头后，出任伪汕头市市长，协助日军维持殖民统治，推行伪化教育，搜刮民财，镇压抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('15d0ef43313249ca944811a11ff4fc86','d85cd285c30b4eb0af400dc4a45494eb',1939,'伪潮安县维持会会长','在潮安组织伪维持会，配合日军对揭阳、潮安交界地区的扫荡与物资掠夺。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9467505479754778a789a197b4cd59e7','69e3e3014c0a4ccea98723cdf49b44c7',1940,'伪广东和平建国军总司令','在广东收编伪军，其势力范围涉及潮汕地区，与揭阳伪军有联系，配合日军进攻抗日根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9813c10fbbf84cc691c9770344809f28','a161896f59e844289bd4cbab55d387de',1940,'伪揭阳县教育科科长','在揭阳推行奴化教育，篡改教材，强迫学校使用日语教学，宣传“大东亚共荣圈”。；在揭阳推行奴化教育，篡改教材，宣传“大东亚共荣圈”。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('625944a4ad734e5c97263e8d537c0924','4c167016f2d14fc58996ff5156d10b7b',1939,'伪揭阳县商会会长','控制揭阳商业，为日军征购物资，协助日军对揭阳经济进行掠夺，压榨商户。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('185c458803b847b6aa8056d917e508c3','0d5357c7fcb948968a0a7305a6670060',1940,'伪普宁县维持会会长','在普宁组织伪维持会，配合日军对揭阳、普宁交界地区的控制，征粮派款。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ece08ec068f244df8fbf3508438a3c55','9896dc171be947339f4faf58c55072ef',1941,'伪惠来县维持会会长','在惠来组织伪政权，与揭阳伪政权协同，协助日军封锁沿海，阻断抗日物资运输。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8e29475eb9824e98b58c40a734cb158c','8ab4e9687c814ebf88894bde1b3f3529',1931,'伪广东省政府主席（未就任）','九一八事变后，日本方面曾拉拢陈炯明，试图让其出面组织伪政权。陈炯明虽未公开就任伪职，但曾与日方接触，其旧部在广东沿海地区活动，与揭阳、惠来一带地方势力有联系。；九一八事变后，日本方面曾试图拉拢陈炯明合作，陈炯明一度与日方接触，但最终未公开就任伪职。其活动范围主要在广东及香港，与揭阳地区有间接关联。；抗日战争初期，日本侵略者曾试图拉拢陈炯明出任伪广东省政府主席，陈炯明未正式就任即于1938年病逝，但其与日方接触的传闻在广东地区流传。；九一八事变后，日本方面曾试图拉拢陈炯明出任伪广东省政府主席，陈炯明未公开就任，但其旧部与日方有接触。陈炯明为海丰人，海丰与陆河相邻，其活动范围覆盖汕尾地区。；九一八事变后，日本方面曾拉拢其出面组织华南伪政权，陈炯明虽未正式就任伪职，但与其旧部保持联系，被时人视为潜在附逆对象；其活动范围涉及广东及香港，与深圳、盐田一带的旧部有联络。；九一八事变后，日本方面曾试图拉拢其出面组织伪政权，陈炯明虽未公开就任伪职，但与其旧部在广东沿海及深圳、罗湖一带的势力被日军利用，间接为日方渗透提供便利。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1f6c0b01734649a2bf8bc071aea7bff8','f415d17d03cf4be0b1b03573cdbe07f8',1938,'伪广东治安维持会委员','广州沦陷后，林知渊参与伪广东治安维持会，协助日军维持占领区秩序，其活动范围涉及广东东部沿海，包括揭阳、惠来周边地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('826a12f9d94e4930a1a96e01cc69ab3a','4ffa32e45d104ce88220a4d3f3942ffb',1939,'伪广东省政府委员兼伪广州市长','陈耀祖在日军占领广州后出任伪职，参与伪广东省政府事务，其政令曾下达至潮汕地区，包括揭阳、惠来一带，协助日军推行治安强化运动。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('67b51ab1404549dcadfc3048c18ab267','d85cd285c30b4eb0af400dc4a45494eb',1939,'伪潮汕维持会会长','潮汕沦陷后，王英儒出面组织伪潮汕维持会，协助日军管理潮汕地区，包括揭阳、惠来等县，负责征粮、拉夫及情报收集。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('db7bb29b4241469c9091528092522ee2','0b597f0c195f4893b99164689e3a9590',1940,'伪惠来县维持会会长','李国梁在惠来县沦陷期间出任伪维持会会长，协助日军征缴粮食、物资，并参与组织伪自卫队，镇压当地抗日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('976ed7ace7964354a2694e31a1f6a590','59e83473f9ba42b88fdee13364b42911',1940,'伪揭阳县维持会副会长','张瑞贵在揭阳地区协助日军建立伪政权，负责保甲连坐制度的推行，配合日军扫荡抗日游击队，其活动范围覆盖揭阳及惠来交界地带。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('241f31a91d5a45fb8e8980a4b1e1732b','d545141de1f54c32a3405154b2524766',1941,'伪潮汕警备司令部侦缉队长','陈子岐在潮汕地区为日军搜集情报，抓捕抗日人士，其侦缉活动涉及揭阳、惠来等县，导致多名抗日志士被捕遇害。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('730a6e8a0cac47d19225541932b8a458','42f7808e176c457a8c0898c88cc51d63',1942,'伪惠来县保安大队长','黄启良统率伪保安大队在惠来及周边地区配合日军作战，参与围剿抗日武装，强征民夫修筑工事，残害当地百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0ef2d8b8206043b5b6a257f34c78ff47','69e3e3014c0a4ccea98723cdf49b44c7',1938,'伪广东和平建国军司令','刘志陆在广东东部地区组织伪军，配合日军对潮汕抗日根据地实行封锁和扫荡，其部队活动范围包括揭阳、惠来一带。；在广东东部包括揭阳一带活动，收编土匪、伪军，配合日军作战。；广东梅县籍，抗战初期投靠日军，在广东沦陷区收编土匪、组织伪军，配合日军进攻抗日游击区。；在广东收编土匪、散兵组成伪军，活动于潮梅、惠阳一带，配合日军扫荡抗日根据地，残害百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0cbb3ca42c6641ee9d604d69b7be09a9','4c167016f2d14fc58996ff5156d10b7b',1941,'伪揭阳县教育科长','吴文献在揭阳推行奴化教育，强制学校使用日伪教材，宣传“大东亚共荣圈”，并协助日军筛查抗日师生，其影响波及惠来等邻县。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9ff10865ccd147a788a97bfba4399e39','2fd8cc09575c41a9b821f93ad2283af3',1938,'伪广东维持会会长、伪广州市市长','广东沦陷后出面组织伪广东维持会，后任伪广州市市长，协助日军维持殖民统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3fb0fb3dc96e48a29c13ae03542309f9','664d3df731bb4293bee63eea6deacb2d',1944,'伪广东省政府主席、伪外交部长','汪伪政权要员，后任伪广东省政府主席，抗战胜利后被处决。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('399fcae2d9f34341b93b84ac03a4dc95','d85cd285c30b4eb0af400dc4a45494eb',1939,'伪揭阳县维持会会长','揭阳沦陷期间出面组织伪维持会，为日军征粮、派夫、维持地方伪秩序。','基层维持会/地方自治头目','hanjian');
