INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4a541e7fe4494e02a4f210bda85c3800','d545141de1f54c32a3405154b2524766',1940,'伪揭阳县政府县长','汪伪揭阳县县长，推行伪政令，配合日军在揭阳及周边地区的统治。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('20e3fb2b318c4737a625190101ed26f5','f2a6bebd8b1b4d6cab6d363eed10c955',1939,'伪潮汕维持会委员','在潮汕地区参与伪维持会活动，协助日军控制揭阳、潮阳一带。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b9edab68a5e644fcbe072cd5b65dc977','d366f1f59a7c4ea4afd8b7f98480197f',1941,'伪揭阳县保安团团长','率伪保安团在揭阳地区配合日军行动，参与清乡与征粮。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a9c980e87a8f411abaf72b6ed4558a8e','4c167016f2d14fc58996ff5156d10b7b',1939,'伪潮汕自治会会长','在潮汕地区组织伪自治会，为日军提供情报与物资。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c557ae0ae0f349e38d52d87af97490d2','fcae177a81b84f58b97f232afb03dca3',1941,'伪潮汕警备司令','负责潮汕地区伪警备，协助日军维持治安、镇压抗日力量。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d8b4a7f29faf4651bf893ee19c185af0','d1abe59a5d664bf18b442130fc0478a1',1938,'汪伪政权宣传部部长、伪广东省政府主席','广东信宜人，汪精卫伪政权核心成员，曾任伪宣传部长、伪广东省长等职，积极推行日伪奴化宣传，其活动范围覆盖广东全省，包括揭阳地区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b399766a053e4dc1901918a8087105b7','d366f1f59a7c4ea4afd8b7f98480197f',1939,'伪揭阳县维持会会长','揭阳本地人，日军侵占潮汕期间出面组织伪揭阳县维持会，协助日军征粮、拉夫，维持日伪统治秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b0ce72d94e684d849575ce9a4eb40571','5b92e9687d644b99a566303ef0e2c5cf',1940,'伪揭阳县政府县长','汪伪政权委任的揭阳县伪县长，在揭阳地区推行日伪政令，配合日军清乡，镇压抗日民众。；在揭阳部分沦陷区出任伪县长，配合日军维持占领区统治。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9297eb7a6ab44043a08911e2faa95d4f','ab21dff7d3a14043a30541bc70f12806',1939,'伪潮汕维持会联合会头目','在潮汕地区组织伪维持会，协调各县伪政权，活动范围包括揭阳、揭西，协助日军控制潮汕平原。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0875dfb1fabf4a79a76ca94e38b8002d','4c167016f2d14fc58996ff5156d10b7b',1940,'伪揭西地区保甲长、情报员','揭西本地人，充当日伪情报员和保甲长，为日军提供抗日游击队活动情报，协助日军搜捕抗日人员。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('abd664c55def4951815c1005a72f2dde','a161896f59e844289bd4cbab55d387de',1939,'伪潮汕自治会会长','在日军支持下组织潮汕自治会，鼓吹“中日亲善”，为日军侵占潮汕地区制造舆论，活动涉及揭阳一带。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e5008f77acad49b7b4c8dc419b76c797','69e3e3014c0a4ccea98723cdf49b44c7',1940,'伪和平建国军广东方面军司令','广东梅县人，汪伪政权在广东的军事头目之一，统率伪军配合日军在潮汕地区扫荡，活动范围覆盖揭阳、揭西。','基层头目','hanjian');
