INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('483aca35bf884f279ebccafca90aefb8','fea5ba2d5e614ac086086bd338dbef85',1939,'伪闽粤边区总司令','抗战初期投靠日军，组织伪军活动于闽粤边区，包括潮汕一带，后因内部矛盾被日军处决。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a6ca9df9aea14023a1e1711f32813976','236cf121d01347ec8d01a345d59fe850',1939,'伪潮汕维持会头目（传闻）','有记载称其在潮汕沦陷初期曾与日方接触，参与维持会活动，但具体事迹记载较少，需进一步考证。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('840b16956f0b43649eacd865b0612856','3bcf52bfa5f34d6c9ebe0cbb8be22b74',1939,'伪揭阳维持会会长','揭阳沦陷期间，出任伪揭阳维持会会长，协助日军维持地方秩序，征粮派款，压迫当地民众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6f32caf894184ff5a9deb3825722273c','1d43b24658e74d7998aeb977db93442f',1940,'伪揭阳县政府县长','汪伪政权委任的伪揭阳县县长，在揭阳地区推行伪政，配合日军统治，活动范围包括榕城一带。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b3626d2d865e41afa22c804dac9bd8cd','1282d84b1bf948e7b87d5f6447a19660',1939,'伪榕城维持会会长','榕城沦陷后，出面组织伪维持会，为日军筹粮、拉夫，维持地方治安，直接服务于日军占领当局。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d0b828c477f8469787d172f43c495e54','d545141de1f54c32a3405154b2524766',1940,'伪潮安县政府县长','汪伪政权在潮安地区的伪县长，潮安与揭阳相邻，其活动对揭阳地区有一定影响。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0c2e03f501b84328aa8b8afa209b3aee','529eba01fd3844d2a4780badaf25cb50',1939,'伪汕头市市长','汕头沦陷后出任伪汕头市市长，汕头为潮汕地区中心城市，其伪政权活动辐射揭阳等地。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e39f335919a0406c90fc495dce30e73f','a9708e8b7e6a4a6aacef69da8f32bb5e',1940,'伪广东省政府委员','汪伪政权广东省政府委员，参与广东沦陷区政务，其政策影响包括揭阳在内的潮汕地区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7e3ada92d5aa44d0b51da08a786cb27e','2378268bb6eb4de58319a82ddd658b97',1941,'伪潮汕警备司令','伪军头目，负责潮汕地区警备，配合日军对揭阳、榕城等地的控制与扫荡。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e3726f2258b647b29026a7e943a0c033','e0084ea11e804593a3e43a7c28d2fc67',1940,'伪广东绥靖军师长','伪军师长，活动于广东各地，包括潮汕地区，参与对抗日武装的围剿。；率伪军在广东各地配合日军作战，曾进入梅县周边地区进行清乡、抢粮，镇压抗日民众。；在广东多地包括东江地区活动，率伪军配合日军进攻抗日根据地，涉及河源周边。；汪伪广东绥靖军师长，率部在清远、英德、从化一带配合日军作战，镇压抗日力量。；率伪军在珠江三角洲及西江流域配合日军作战，参与对四会、肇庆一带的扫荡和清乡。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ebb4053470eb43c7bc0975e5eea496ce','d0f98aab616d49c1909c1593eeb5f848',1941,'伪揭阳保安大队长','伪揭阳县保安大队长，率领伪军配合日军在揭阳地区进行治安强化运动，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b237d57a9b7645fabe9fbfe282a91bb2','c84a84dadc764af1a1772c3dc19fecd6',1939,'伪丰顺县维持会会长','日军侵占潮汕期间，在丰顺县出面组织伪维持会，协助日军征粮、派夫，维持沦陷区秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0268facd5a6d451e9e7c255e3f7d2852','0ca8e30648f943e999536018d0e22853',1939,'伪梅县维持会副会长','在梅县沦陷前后参与组织伪维持会，为日军搜集情报、筹办物资，并协助推行伪化教育。；在梅县地区勾结日军特务，组织维持会，为日军搜集情报、筹粮筹款，协助伪政权推行奴化教育。','基层维持会/地方自治头目','hanjian');
