INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7a4bd6eded8b4c13bc942e5476045d4f','69e3e3014c0a4ccea98723cdf49b44c7',1938,'伪广东治安维持会委员','在广州参与伪广东治安维持会，后其影响扩展至潮梅地区，协助日军推行伪化统治，与丰顺等地伪组织有联系。；在广东伪政权中任职，参与推动潮汕地区伪化。','基层维持会/地方自治头目','hanjian');
