INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('53b922e716104d699d4083fe71e8aae0','d85cd285c30b4eb0af400dc4a45494eb',1938,'伪宝安县维持会会长','宝安县（含今深圳、光明地区）沦陷后组织维持会，协助日军维持治安、征粮。；深圳地区沦陷后，出面组织伪宝安县维持会，协助日军维持地方治安、征粮征工，为日军提供情报，直接涉及深圳、盐田地区。；深圳地区沦陷后，出面组织伪宝安县维持会，协助日军在深圳、罗湖一带维持治安、征发物资与劳工。','基层维持会/地方自治头目','hanjian');
