INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b9f4c28c306749dc907778fc58349e15','e0084ea11e804593a3e43a7c28d2fc67',1938,'伪广东绥靖军第二十师师长、伪东莞县县长','广东著名汉奸，投靠日军后组织伪军，在珠江三角洲及粤北一带配合日军扫荡，其势力范围曾扩展至清远、佛冈周边地区，参与征粮、抓丁和镇压抗日民众。；广东著名汉奸，投靠日军后组织伪军，在珠江三角洲一带配合日军扫荡，镇压抗日武装，其势力范围曾扩展至清远、花县、三水等地，对清远地区抗日活动构成威胁。；广东著名汉奸，投靠日军后组织伪军，在珠江三角洲及粤北部分地区配合日军扫荡，镇压抗日武装，搜刮民财。其势力范围曾扩展至韶关周边地区。；广东著名汉奸，投靠日军后组织伪军，在珠江三角洲及粤北一带配合日军扫荡，曾任伪广东绥靖军第二十师师长，后兼伪东莞县县长，对广东抗日力量造成较大破坏。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1ff252b677f44ebabb43671f8484c264','075b5b4817584064baada36d1055f1e2',1939,'伪清远县维持会会长','日军侵占清远期间出面组织伪维持会，为日军筹粮、派夫、搜集情报，协助日军控制清远县城及附近乡村，对佛冈等邻近地区亦有影响。；日军侵占清远期间，出面组织伪维持会，为日军征粮、拉夫、搜集情报，协助日军维持清城及周边地区的殖民统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('458ca33953c44983ba616bf30c24bfb4','9f546b31db5245ecb96951f038848923',1939,'伪清远县警察局局长','在清远沦陷区充任伪警察头目，带领伪警察配合日军搜捕抗日人员，勒索民众，维持伪政权治安，活动范围覆盖清远南部及佛冈边缘地带。；在清城地区担任伪警察头目，配合日军搜捕抗日人士，镇压民众反抗，推行保甲连坐制度，为日伪政权维持地方治安。；在清远沦陷区充任伪警察头目，协助日军搜捕抗日人士，镇压民众反抗，维护伪政权治安。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('56ec29a00a324d82811ac4b8faa45ad4','e6fef6aaecc045348b54f54deec27563',1939,'伪广东绥靖军团长、伪清远地区联防队长','率伪军盘踞清远、佛冈交界山区，替日军守备交通线，多次参与对北江抗日游击队的围剿，并强征当地粮食、劳工。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('058e0d9809a94e96a3421492ae22f2ee','42f7808e176c457a8c0898c88cc51d63',1940,'伪佛冈县维持会副会长','在佛冈县协助日军建立伪政权，负责摊派捐税、登记户口、诱降抗日人员，为日军提供佛冈至清远一带的情报。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c7093e41f8b4481294ab437d7bba10cf','2d8f00ea97ab4404aac62e147fe7fec2',1941,'伪广东省政府参议、北江伪政权联络员','作为伪省府与北江各县伪政权之间的联络人，往来于清远、佛冈、英德等地，协调伪军行动，推动奴化教育，为日军掠夺物资。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6c3f3753b532487b86c2e666659e226c','9ddc37b48e534b7eb3ff655f97f058fa',1940,'伪清远县教育科科长','在清远沦陷区推行日语教育和奴化宣传，编写亲日教材，组织学生参加日军庆祝活动，影响范围包括佛冈部分学校。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d0bfa24c62e7448ab340c13ba7d49e33','3f6e5671740e45c986c99f46a1dda33a',1939,'伪清远县商会会长','控制清远沦陷区商业，为日军采购军需物资，强制商户缴纳“合作费”，并协助日军对佛冈等地的经济封锁。','基层头目','hanjian');
