INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ebb935b7cf594b32aadd818ba58cbf7d','50da58de49ed4a528c1754acb949ad36',1938,'伪广东绥靖军第四师师长','广东著名汉奸，率伪军在广州、佛山、清远等地配合日军作战，参与扫荡抗日游击队，对清远地区抗日力量造成较大破坏。','市县厅局级','hanjian');
