INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('87268da59a10462fa0228b98270badc0','ce7546d10af04356983709b44dfe8ed1',1942,'伪广东和平救国军清远地区司令','收编地方土匪武装，配合日军在清远、清新、英德交界地区进行扫荡，破坏抗日根据地。','基层头目','hanjian');
