INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ac62c6c4ba20446d846c846d746116db','28ca272aab024a6b9ee4ad65d0c2a95d',1941,'伪清新县保甲长','在清新县基层推行保甲制度，监视民众言行，向日军举报抗日嫌疑人员，协助征发劳役。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1e479009c0194f66aeccbbf423e0f0e2','86e982eb4f0043c4b6f7b586ec525f98',1938,'伪广东治安维持会会长、伪广东省政府委员','广东沦陷后出任伪广东治安维持会会长，后任伪广东省政府委员，为日军在广东的统治效力。；广东伪维持会与伪省府要员，参与组织珠海及中山地区伪政权，为日军维持占领秩序。；广州沦陷后投敌，参与组织伪广东治安维持会，后任伪广东省政府要职，协助日军推行殖民统治，其伪政权体系延伸至珠江三角洲包括珠海地区。；广东伪政权头目之一，活动于华南沦陷区，与广西邻近，参与日军在华南的统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('239eaf64e0a44476ae85772ffc7b1b29','2fd8cc09575c41a9b821f93ad2283af3',1938,'伪广州市市长','广州沦陷后任伪广州市市长，协助日军管理广州及周边地区，其伪政权影响波及清远、英德一带。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e57c532607954428af7a12cfbbbe1add','3a5a046c040749728e54e7c9013775bf',1938,'伪广东江防舰队司令','投靠日军，任伪广东江防舰队司令，配合日军在珠江及北江流域的军事行动，活动范围涉及清远、英德水域。；率伪海军配合日军封锁广东沿海与内河，拦截抗日物资。','基层头目','hanjian');
