INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7fed8c0431db464bb5c74f6087f604d2','728bd01fbcbc45bebed4e156015ade4c',1938,'伪广东治安维持会委员','在广州参与伪广东治安维持会，为日军稳定广东沦陷区秩序、推行伪化教育及宣传服务。；在广州参与伪广东治安维持会，后其势力与广州湾伪政权有联系，协助日军在粤西扩张。','基层维持会/地方自治头目','hanjian');
