INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('39246878307b404c80abd868266513d1','2a3bdea850e641fd9cafe5efad153829',1943,'伪广州湾维持会会长、伪广州湾特别区公署署长','广州湾（今湛江）沦陷后投靠日军，组织伪维持会，协助日军维持殖民统治，推行伪化教育，为日军征发物资与劳工。；广州湾（今湛江）沦陷后投靠日军，组织伪维持会，协助日军推行殖民统治，征发物资、劳工，镇压抗日活动。','基层维持会/地方自治头目','hanjian');
