INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d49a8399f2e94e2599d2d86c52e12c1e','ce7546d10af04356983709b44dfe8ed1',1938,'伪广东治安维持会会长、伪广东省政府要员','广东伪政权头面人物之一，参与组织伪维持会与伪政府，其伪政权体系覆盖包括湛江、雷州在内的广东沦陷区。','基层维持会/地方自治头目','hanjian');
