INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cd9d67e200f241d08f510ab0ebbe14f9','d85cd285c30b4eb0af400dc4a45494eb',1940,'伪广东绥靖军将领、伪军头目','在广东沦陷区统率伪军，配合日军在粤西及雷州半岛进行治安战和物资掠夺。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('15ac6c1eceb54f2ea1c019beb5b8b958','62a6d6c8e7ab4bbfbc92c5b14abbde74',1940,'汪伪政权立法院长、伪广东省长','汪伪政权主要头目之一，曾兼任伪广东省长，其伪政权体系覆盖广东沦陷区，包括湛江、雷州地区。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('97ff63df9be34031882b9ccf5723bbd2','a2e4190c87b449e685d78c118a6801b5',1938,'汪伪政权财政部长、伪警政部长','汪伪政权核心人物，其财政与警政体系延伸至广东沦陷区，支持湛江、雷州等地伪政权和伪警察运作。；汪伪政权核心成员，其财政与警政体系对广西沦陷区伪组织有渗透，通过经济与特务手段影响广西附逆分子。','省部级/大军区级要员','hanjian');
