INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c44734f0742a40e09dad56a1b2ba1050','86e982eb4f0043c4b6f7b586ec525f98',1940,'伪广东警务处处长','掌管广东伪警察系统，其警务网络延伸至广州湾及雷州半岛，镇压抗日民众。；统管广东伪警察系统，在肇庆、德庆等地设立警察机构，镇压抗日活动，搜捕抗日人员。；统管广东沦陷区伪警察系统，在茂名等南路地区设立伪警察所，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c4c2788714b445c4998aef7ad57720c3','62a6d6c8e7ab4bbfbc92c5b14abbde74',1940,'伪国民政府代主席、伪广东省政府主席','接任汪伪政权首脑，继续推行附日政策，广东伪政权包括广州湾地区在其管辖范围内。；继汪精卫后领导伪政权，其伪广东省政府控制湛江等地，继续推行卖国政策，协助日军维持占领区统治。；曾任伪广东省政府主席，督导包括肇庆、广宁在内的广东沦陷区伪政权的运作。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('19348cbad12046689e3d8a5c9356755e','664d3df731bb4293bee63eea6deacb2d',1945,'伪广东省政府主席','1945年任伪广东省长，维持广东沦陷区包括广州湾的伪统治至日本投降。；任伪广东省政府主席期间，管辖包括湛江在内的广东沦陷区，为日军征发物资，镇压抗日力量。','无明确职位或一般帮凶','hanjian');
