INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('01d2779043ff4ffdbad2a55e77aa929f','664d3df731bb4293bee63eea6deacb2d',1938,'伪国民政府外交部长、伪广东省长','曾任伪广东省长，对广东包括潮汕沦陷区的伪政权运作负有责任。；汪精卫连襟，参与汪伪政权，在南京任伪外交部长等职，后任伪广东省长。；浙江湖州人，抗战期间投敌，任伪外交部长、伪广东省长，其伪政权外交与地方治理涉及华南、华东包括江西部分地区。；浙江吴兴人，汪伪政权要员，参与伪政权外交与地方统治，其伪化政策对河南沦陷区有间接影响。；浙江吴兴（今湖州）人，汪伪政权要员，曾任伪外交部长，后任伪广东省长，1946年被处决。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f2ff05b1f5e441978a40fb1e2d983b07','d1abe59a5d664bf18b442130fc0478a1',1938,'伪国民政府宣传部长、伪安徽省长','汪伪宣传系统负责人，在潮汕沦陷区推行亲日宣传与奴化教育。；汪伪政权宣传头目，在南京控制伪宣传机构，进行亲日宣传，后任伪安徽省长。；福建籍汪伪高官，虽主要在南京活动，但与福建伪政权有联系，推动闽南地区奴化宣传。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fe6e26c681804a8ab9fe73d4dde823d4','ae517ac3c0964918804ac4e186a9323d',1940,'伪潮安县政府警察局长','在潮安沦陷区充任伪警察头目，配合日军搜捕抗日人员，推行保甲连坐，压制民众抗日活动。','市县厅局级','hanjian');
