INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0e5602024cac4b7a8f65b7aa952565d0','7b7cedf8b4344f31952ce2de2b0d8949',1940,'伪肇庆县县长','任伪肇庆县县长期间，推行奴化教育，协助日军征发劳工，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b62ba5fb911048d5b0d318cf2822e580','c12e72a145724c39b755a2a16dce9a71',1938,'伪国民政府主席兼行政院长','建立南京伪政权，其伪广东省政府管辖包括肇庆、广宁在内的地区，推行日伪统治。；广东三水人，投降日本后建立汪伪政权，其伪政权体系覆盖广东全省，包括韶关地区，对广东人民进行殖民统治。；原国民党副总裁，1938年叛国投敌，1940年在南京成立伪国民政府，成为头号汉奸。；在南京建立汪伪政权，与日本签订卖国条约，组织伪军配合日军作战，在江苏、南京、江宁推行“和平运动”欺骗民众。；在南京建立汪伪政权，与日本签订卖国条约，组织伪军配合日军作战。；在南京建立汪伪政权，与日本合作，其核心活动区域包括鼓楼附近的颐和路公馆区。；公开投日，建立汪伪政权，其伪省政府体系覆盖江西沦陷区，九江地区伪政权受其管辖，推行‘清乡’与物资统制。；广东三水人，国民党副总裁，1938年叛国投敌，在南京成立伪国民政府，其伪政权名义上统辖包括江西在内的沦陷区，对赣州地区伪政权组织有间接影响。；原籍浙江绍兴（山阴），生于广东三水，1940年在南京成立汪伪政权，与日本合作，对浙江杭州地区进行殖民统治，1944年死于日本。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('abfa77ee5b6a484eb82605368b334022','d1abe59a5d664bf18b442130fc0478a1',1944,'伪广东省政府主席、伪宣传部长','出任伪广东省政府主席，在广东沦陷区推行日伪政策，包括肇庆、广宁地区的伪化统治。','省部级/大军区级要员','hanjian');
