INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d2dd65d088ef412f9b95605f1017cc7c','1699dbbabdd14faaa7f5ea6924376bea',1940,'伪雷州半岛维持会头目','在雷州半岛及邻近粤西地区附敌，组织伪维持会，为日军征集粮食、劳工，配合日军对茂名、化州方向的扫荡与封锁。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f9e446606e954f8298641d092074616c','2a3bdea850e641fd9cafe5efad153829',1940,'伪广州湾/雷州方面维持会人员','在广州湾及雷州一带与日军合作，参与伪维持会活动，影响粤西沿海与茂名、化州周边地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dc8016afa0fc45b48807f2743194f194','f2a6bebd8b1b4d6cab6d363eed10c955',1940,'伪军粤西部队头目','抗战期间在粤西地区率部投敌，编入伪军，配合日军进攻抗日游击区，活动范围接近茂名、化州。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cf12b6d1e3254c4fb7920aee6092c428','0bb95d8e35d849a1ac831917705e7f6a',1940,'伪茂名、化州地方经济附逆者','茂名、化州部分商绅在日军控制或威胁下，为伪政权筹款、供应物资，参与经济附逆活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f7e1c239385645e5905d42069453ecf1','4ffa32e45d104ce88220a4d3f3942ffb',1940,'伪广东省政府主席、伪广州绥靖主任','汪伪政权在广东的最高头目之一，主持伪广东省政，推行日军殖民统治，镇压抗日力量，其伪政权统治范围覆盖广东全省，包括茂名、电白一带的伪行政体系。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ca668a1b38ea4c17b733bebc919fc492','86e982eb4f0043c4b6f7b586ec525f98',1939,'伪广东省政府委员、伪广州市长','汪伪广东省政权核心成员，参与伪政权对广东各地的控制与征敛，配合日军清乡与治安强化运动，影响波及粤西茂名、电白地区。；广东伪政权头目之一，活动范围未直接覆盖贵港、平南。','核心城市市长/省部级','hanjian');
