INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a352917854cd490fb94bdd843f9e9c4e','67fb5f1b2e0e49279cb00f55697f08f3',1940,'伪广东省政府委员、伪建设厅长','汪伪广东省府成员，负责为日军掠夺物资、修筑工事，配合经济统制，对粤西包括茂名、电白实施物资管制与征发。','市县厅局级','hanjian');
