INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a40d1ead555d46eeba4fb4248318ecdd','8e033c0efe004d1f9fd444872d2b685c',1931,'未在北海伪政权任职，但抗战时期主政广东期间对日妥协倾向明显','主政广东时与日本保持暧昧关系，采购日械，压制抗日救亡运动；虽非直接投敌，但其对日妥协政策为后来广东沿海沦陷区伪政权滋生提供了条件。','无明确职位或一般帮凶','hanjian');
