INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0bdc404950294e02be6cb0fa6f62b122','fd012acd6eaf4a24aed8d1f0adae170e',1939,'伪南宁维持会会长','日军第一次侵占南宁后，出面组织伪南宁维持会，协助日军维持占领秩序、征发民夫与物资。；日军第二次侵占南宁期间，出面组织伪维持会，协助日军维持地方秩序、征发物资。；1944年日军第二次入侵广西占领南宁期间，出面组织伪南宁维持会，协助日军维持占领区秩序、征调物资。；日军第一次侵占南宁期间，出面组织伪南宁维持会，协助日军征粮、拉夫、维持治安，为日军侵桂提供后勤支持。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('53269952f8ba4b7fba15291dfff201c1','596196c92f02492ba879028942c83b43',1939,'伪南宁维持会副会长','参与伪南宁维持会事务，协助日军推行保甲、征粮和宣传‘中日亲善’。；日军侵占南宁期间，与田次廉等组织伪南宁维持会，任副会长，协助日军推行保甲、征发民夫物资，镇压抗日活动。；与田次廉共同组织伪南宁维持会，为日军侵占南宁提供地方协助。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ab82486f58c34fe991c0989ad3c72a90','5f8553e003de4f37aa0ff3cb6ca6515f',1939,'伪南宁警察局局长','在日军占领南宁期间出任伪警察头目，配合日军搜捕抗日人员、维持城区治安。；在日军占领南宁期间出任伪警察局长，协助日军维持治安、搜捕抗日人员。；在日军占领南宁期间出任伪警察局局长，统率伪警察配合日军搜捕抗日人员、维持占领区治安，迫害民众。；日军占领南宁期间出任伪警察局长，配合日军搜捕抗日人士、镇压民众反抗。；在日军占领南宁期间，李耀林出任伪警察局长，配合日军搜捕抗日人士、镇压民众。','市县厅局级','hanjian');
