INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cb2cd74d986e487ebc897ea38f1bee43','0a4ccb2198e14ef096089ca8086d93fe',1937,'伪广西省政府主席（未就任，但曾与日方接触）','抗战后期桂系与日方有秘密接触，黄旭初作为桂系核心人物之一，曾参与相关谈判，但最终未公开附逆。；抗战后期日军入侵广西时，黄旭初作为桂系要员曾一度与日方有接触，但最终未公开投敌，其行为在战后受到调查。；抗战后期，日军入侵广西，黄旭初作为桂系要员曾一度与日方有接触，但最终未公开投敌，其行为在战后受到调查。；桂系要员，抗战后期曾与日军暗中接触，谋求保存实力，但未公开投敌，故严格意义上不属汉奸，仅列作相关人物。','无明确职位或一般帮凶','hanjian');
