INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3cbcc77d177c4940bcfea36241b73b62','0a4ccb2198e14ef096089ca8086d93fe',1944,'伪广西省政府主席（汪伪政权委任，未实际到任）','汪伪政权曾试图拉拢其出任伪广西省主席，黄旭初未就任，但日伪在广西沦陷区曾以其名义进行宣传。；抗战后期汪伪政权为渗透广西，曾委任其为伪广西省政府主席，试图在桂西、百色一带建立伪政权，因日军未能长期控制广西全境而未实际履职，但其名义上的附逆行为被记录。','无明确职位或一般帮凶','hanjian');
