INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aaabaf5f87f047f6b3fff6e7da0696d9','0b10d72a65d347808b7450dba1d9e025',1944,'伪广西省宣传处主任','在日军扶植下，陈日葵负责伪宣传机构，鼓吹“大东亚共荣圈”，为日军侵略张目。','基层头目','hanjian');
