INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('060a329e204942229787235a6a4a8070','02a4e84319ba438189869a1792dbacca',1939,'伪南宁警察局局长','在日军占领南宁期间出任伪警察局局长，统辖伪警察协助日军搜捕抗日人士、维持占领区治安。','市县厅局级','hanjian');
