INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9c7302b7a28e4ef389461a2ea0180228','24047aa5c662402983ed5ea194cf5fb4',1939,'伪南宁商会会长','日军占领南宁期间，以商会会长身份出面为日军摊派款项、物资，协助维持占领区经济秩序。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a2b5b94ce6944772b148f587b97fab48','689017ee02b048c89e853446a8b9de6a',1939,'伪广西教育厅顾问（附逆文化教育人士）','据部分地方史料记载，其在日军侵占南宁期间与伪政权合作，参与推行奴化教育宣传；此说存在争议，需谨慎对待。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e80590def8134c329aa62ea8be2546ba','0a4ccb2198e14ef096089ca8086d93fe',1944,'伪广西省政府主席（附逆说法）','有史料称其在日军第二次侵桂期间一度与日方接触、参与维持地方秩序，但此说争议较大，主流记载其仍属桂系抗日阵营，需谨慎对待。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bbf2ebe1449b4f96a5ab42302e9073f1','628de3e1f6444491a6c5adb8d85cba19',1944,'伪桂林维持会会长（附逆说法）','部分地方史料提及其在桂林沦陷期间参与维持会活动，但此说缺乏确证，需谨慎对待。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0773acd44935481bb68a70db24a206a0','8e033c0efe004d1f9fd444872d2b685c',1939,'伪广东维持会相关（与广西邻近活动）','有说法称其在日军侵占两广期间与伪政权有联系，但主流记载其坚持抗日立场，此说不可靠。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6f8b2a5027de407ca5f59db8108985e0','86e982eb4f0043c4b6f7b586ec525f98',1938,'伪广东治安维持会会长（活动范围邻近广西）','在广州组织伪维持会，其伪政权活动范围与广西东南部邻近，对南宁一带伪政权组织有间接影响。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4aebbc7cddec489cb36f0bec35233f1b','0a4ccb2198e14ef096089ca8086d93fe',1937,'广西省伪政府主席（未就任，但曾与日方接触）','抗战后期桂林沦陷后，日军曾试图拉拢其出面组织伪政权，黄旭初虽未公开投敌，但曾与日方进行过接触和谈判，在广西伪政权筹建过程中态度暧昧。；抗战期间长期主政广西，与日方有秘密接触，但未公开投敌，战后被列为附逆嫌疑人物。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('09579528764a4fe78e382d1594472c30','a55f246e140d4624a240c74fb8ee7284',1944,'南宁维持会会长','1944年11月南宁沦陷后，出面组织南宁维持会，协助日军维持地方秩序、征调民夫和物资，为日军占领南宁提供后勤支持。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d60da4069f6e462db9c7f73d3fdbc615','689017ee02b048c89e853446a8b9de6a',1944,'伪广西省政府委员（未就任，但被日方列入拟任名单）','日军占领广西期间，曾将其列入伪政权拟任名单，雷沛鸿虽未实际就任，但在日方拉拢过程中未明确拒绝，态度动摇。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cc27e7ab1117488e94cbc80cb9c7a571','6b186890888c4ef59afd6a82a310d3ad',1938,'伪安徽省政府主席（与广西有渊源，桂系出身）','桂系将领，抗战期间在安徽任职，与日伪方面有秘密接触和物资交换，其部下在皖东地区与伪军合作，对广西籍官兵有影响。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ceafdef0ef8a4e3193c125a1106e50d5','fd012acd6eaf4a24aed8d1f0adae170e',1944,'南宁伪警察局局长','南宁沦陷后出任伪警察局长，协助日军搜捕抗日分子、镇压民众反抗，维持日占区治安。','市县厅局级','hanjian');
