INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('52404c6835be4fba81554bbc6668bcd4','53a5a44d99f34de2bff716153de3a373',1944,'武鸣伪维持会副会长','武鸣沦陷后任伪维持会副会长，协助日军管理武鸣及周边地区，包括马山部分区域，为日军提供情报和物资。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('695cc12a570d4569b6b3cc308c6a72ee','c43a8e30f85f4c9888779f448405e97b',1944,'南宁伪保安队队长','南宁沦陷后组建伪保安队，配合日军清乡，在马山、武鸣一带参与对抗日游击队的围剿。','基层头目','hanjian');
