INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d8516983cddd442d8aed9d87e7beb216','6b186890888c4ef59afd6a82a310d3ad',1939,'伪广西省维持会会长（未就任，仅日方拟任）','日军侵占南宁、崇左一带时，日方曾试图拉拢其出面组织伪政权，李品仙未公开附逆，但日伪档案中列为其拟任伪维持会会长人选。','基层维持会/地方自治头目','hanjian');
