INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c8976bee06d94a92b556ccf885fc4355','493541638bdf4f329429543172635e3c',1944,'伪南宁维持会会长（第二次占领时期）','日军第二次侵占南宁期间，再次组织伪维持会，协助日军征粮、拉夫、搜捕抗日人士。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('251cdf3ed96f405fb7f7c8871f2757da','689017ee02b048c89e853446a8b9de6a',1944,'伪广西省教育厅厅长（未就任，日方拟任）','日军第二次侵桂时，日方曾试图拉拢其出任伪教育厅长，雷沛鸿未附逆，但日伪档案中列为其拟任人选。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('20f4aae1158540f3a7bb14a0911cd817','0a4ccb2198e14ef096089ca8086d93fe',1944,'伪广西省主席（未就任，日方拟任）','日军侵占广西期间，日方曾试图拉拢其出面组织伪省政府，黄旭初未附逆，但日伪档案中列为其拟任伪省主席人选。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('69ae7c99be114623bde6f7449dc97995','ff402eb79edc4b7896287b9eeb6090f4',1940,'伪广东南路维持会会长（活动涉及桂南）','在日军侵占桂南、粤西期间，组织伪维持会，活动范围涉及崇左、南宁一带，协助日军征粮、拉夫。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a6bd3399b8ba4f5a81365687e457c529','86e982eb4f0043c4b6f7b586ec525f98',1939,'伪广东治安维持会会长（活动涉及桂南）','日军侵占桂南期间，其伪政权势力延伸至崇左、南宁一带，协助日军推行伪化统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('582d115640cc4d0684fbae657a3e49d3','6b186890888c4ef59afd6a82a310d3ad',1939,'伪广西省政府主席、伪军将领','原为桂系将领，抗战期间投靠汪伪政权，任伪广西省政府主席，协助日军在广西各地推行伪化统治，其势力范围覆盖崇左、龙州一带，组织伪军配合日军扫荡抗日武装。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3ff58b5a3441459dae53cf8fca7026a4','dfd3214d3b5a4dbd8a9dc139442d1acd',1940,'伪广西省警务处处长','投靠日伪后负责广西伪警察系统，在崇左、龙州等地建立伪警察所和保甲联防，镇压抗日群众，搜捕抗日志士。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d716a60d9a1f41748a814259e125358e','4c9c6707d36a45a296c2ffcdcc855ebb',1940,'伪龙州维持会会长','龙州本地士绅，日军侵占龙州后出面组织维持会，为日军征粮征夫，协助建立伪基层政权，压迫当地民众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('227e5665b8ef48bfb8f26fe464eeaac2','81ef0cb8e9c74b2ebb85ccacee4196f0',1940,'伪崇左县县长','汪伪政权委任的崇左县伪县长，在崇左及龙州周边推行伪化教育，组织伪保安队配合日军清乡，搜刮民财。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('86b24939fc6c4adebcdea1649a3b79cd','628de3e1f6444491a6c5adb8d85cba19',1941,'伪广西绥靖公署督办','投日后任伪广西绥靖公署督办，统辖广西伪军，在崇左、龙州地区部署伪军据点，配合日军对抗日根据地进行扫荡。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('214d398b32884e6b81ad7d7f26bc6db0','0a8a11d72d3e41f1b4563f18779c391e',1941,'伪龙州警察局局长','在龙州担任伪警察局长期间，建立特务网络，逮捕抗日人员，强征劳工为日军修筑工事，民愤极大。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1bd25b9f8d734015b276c6b9e2b37f65','a9e4a62ea0554f338f71fcabb04ba414',1940,'伪龙州保甲长、维持会骨干','龙州本地人，任伪保甲长期间为日军收集情报，带领日伪军搜捕抗日游击队员，强征粮食和壮丁。','基层帮凶(维持会系统)','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b1efd1dfb13a4a05bfc6ee2f518de0b3','9f2163cb671846ee895596bc5e026260',1940,'伪广西省宣传处处长','负责汪伪在广西的宣传工作，在崇左、龙州等地发行伪报刊，宣扬“大东亚共荣”，进行奴化教育。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e34e13011ae149ffbc5a8e494a65a1a6','084a8b66c5e446d3a73b6e2d5205b4d8',1938,'汪伪政权中央监察委员会常务委员、汪伪广东省政务长','汪精卫之妻，随汪投敌，参与汪伪政权建立，曾任汪伪国民党中央监察委员会常务委员、广东省政务长等职，为汪伪政权核心人物之一。；汪精卫之妻，随汪投敌，参与汪伪政权核心决策，曾到广东等地活动，广西为其夫汪精卫早年活动区域，桂林亦有其汪伪势力渗透背景。；汪精卫之妻，随汪投敌，参与汪伪政权核心决策，曾到广西活动，为汪伪在华南及广西一带的渗透提供支持。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0627392009604e3d9335ed63c8ba9b90','d1abe59a5d664bf18b442130fc0478a1',1938,'汪伪国民党中央宣传部部长、伪安徽省长','广东人，汪伪政权宣传系统负责人，主办《南华日报》等，为汪伪政权重要骨干，后任伪安徽省长。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('96717ee9d8a34d39ab5abda7dc6b28bd','62a6d6c8e7ab4bbfbc92c5b14abbde74',1938,'汪伪国民政府立法院长、伪上海市长、汪伪政权代主席','原国民党要员，随汪精卫投敌，历任汪伪政权要职，汪精卫死后任伪国民政府代主席，为汪伪政权头号人物之一。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f178099d4a214de3b4995bd05afa28aa','a2e4190c87b449e685d78c118a6801b5',1938,'汪伪国民政府财政部长、伪警政部长、伪上海市长','原国民党要员，汪伪政权核心人物，把持财政、警政大权，后任伪上海市长，抗战末期与重庆方面暗中联系。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f3b4be70fc464bc2aaf7d83b80b902ef','07ff958e7f18410f864975f09234ac7e',1938,'汪伪特工总部主任、伪江苏省长','汪伪特务头子，组建汪伪特工总部（极司菲尔路76号），残酷镇压抗日力量，后任伪江苏省长，1943年被毒杀。；浙江遂昌人，汪伪特务头子，其特工网络覆盖华中包括江西部分地区，迫害抗日人士。；浙江遂昌人，汪伪特务头子，其特工网络覆盖华中沦陷区包括湖南部分区域，与湖南伪政权特务机构有联系。；浙江遂昌人，汪伪特务头目，虽非湖南籍，但其特务活动范围涉及华中地区，与湘潭无直接关联。；浙江人，汪伪特务头子，其特工网络延伸至湖南沦陷区，1943年被日军毒杀。；汪伪特务头子，虽非湖南籍，但其特工网络延伸至湖南沦陷区，迫害抗日人士。；虽为浙江籍，但作为汪伪特务头目，其特工网络延伸至湖南沦陷区，参与镇压抗日力量、收编伪军和维持会。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('739ad659e8e64e4b8309e4ac4d5d3377','4f8793c77ca74d3dbe773329337bfbb0',1938,'伪中华民国维新政府行政院长、汪伪国民政府监察院长','组织伪维新政府，任行政院长，后并入汪伪政权任监察院长，为华中地区重要汉奸。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cac33f6fac06457bbec56341b528ee45','8f1dd12e548b4c4f866dd743c3377896',1937,'伪临时政府内政部长、伪华北政务委员会委员长','华北重要汉奸，历任伪临时政府、伪华北政务委员会要职，推行奴化教育。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c6b2930c7ae146b3ab4d9beefa22d598','664d3df731bb4293bee63eea6deacb2d',1938,'汪伪国民政府外交部长、伪广东省长','汪精卫连襟，汪伪政权重要成员，曾任伪外交部长、伪广东省长等职。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d1d18354f38b411baea50a4cba4af1e6','28c69a91441d4439abc95701e2c6787a',1938,'汪伪国民政府工商部长、伪浙江省长','参与汪精卫投敌谈判，汪伪政权重要成员，历任伪工商部长、伪浙江省长等职。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('16ac877cb75b4723a4fb206a4f5bd6fe','993e4eff978c4539b275a1e53335a341',1937,'青帮头目、伪浙江省长','上海青帮头目，投敌后任伪浙江省长，组织伪军，1940年被刺身亡。；浙江慈溪人，上海青帮头目，抗战期间投靠日军，组织伪军，后任伪浙江省长，协助日军镇压抗日活动。；上海青帮头目，投靠日伪，其势力未直接进入万州。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f0d3fd22faa14148ae3c247f3e63b252','a2ce64836511484ebdf165f12d7a04d8',1938,'青帮头目、汪伪特工总部顾问','上海青帮头目，投靠日伪，为汪伪特工总部顾问，1939年被刺身亡。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c7737cd708ca438cb81bd0a70625b883','22185172400545108441e7de275e4c4a',1937,'伪黄道会会长、伪中国安清同盟会会长','上海青帮头目，组织伪黄道会等汉奸组织，进行暗杀、破坏活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7e3da656142340d5b2a5936f1bca8a3e','d3256e7274c448058c67c4d51c3fa885',1938,'汪伪政权宣传部次长、伪《中华日报》主笔','汪伪政权文宣骨干，曾任伪宣传部次长，为汪伪政权进行舆论宣传。；虽非九江本地人，但在汪伪政权中负责文化宣传，其亲日言论影响江西沦陷区，属全国性文化汉奸。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('19af77f979f14b9481044e8931dba210','8b933aba4bdb445db49232a8d741f1f7',1938,'汪伪政权中央宣传部副部长、伪《平报》社长','汪伪政权新闻宣传骨干，主办伪报，进行亲日宣传。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f973966e7a164f339cd81fd2549f6496','f50cf011f8f842fc8d69caa402ffbf67',1938,'汪伪国民政府内政部长、伪江苏省长','汪伪政权重要成员，历任伪内政部长、伪江苏省长等职。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c6da9282101c4668b6fb6638caa4e47a','cebb4769b324411abb6e1f5a0f26ecf6',1938,'伪绥靖军总司令、伪江苏省长','组织伪绥靖军，任总司令，后任伪江苏省长，为华中伪军重要头目。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e31924a53b304f5d81e40e676a0d1f1e','848992e841c9488c8cdcf56cad9f079c',1938,'伪和平救国军总司令、伪河南省长','原西北军将领，投敌后组织伪军，任伪和平救国军总司令、伪河南省长等职。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8c60e55d817b4288bc48203f5cf0f901','63006a4879fb4f49ad97a1e88c8c5d69',1942,'伪和平救国军总司令、伪河北省长','原西北军将领，投敌后任伪和平救国军总司令、伪河北省长等职。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5d7664482b934ac3ac60fa8364326c0f','5ec2ad124b2f429482b1a90a7f8d4a92',1943,'伪和平救国军总司令、伪河北省长','原国民党将领，被俘后投敌，任伪和平救国军总司令、伪河北省长等职。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f6e859c56e5e48b1b831b1adb723e8dd','a06c0041e5294f2987f746729e510de9',1941,'伪淮海省省长、伪和平救国军总司令','原国民党将领，投敌后任伪淮海省省长、伪和平救国军总司令等职。；原为国民党将领，1943年投敌，任伪淮海省省长，驻徐州，统治新沂地区，推行日伪“清乡”政策，残害抗日军民，1945年抗战胜利后一度被收编，后再次叛变，终被处决。；原为国民党将领，1941年投敌，任伪淮海省（驻淮安）省长，组建伪军，配合日军清乡扫荡，残害抗日军民。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a83c9498a6ab4b0587152f12e750a047','e409ef959281461b91e8ce1eef37d186',1938,'伪华北政务委员会河北省长','原东北军将领，投敌后任伪河北省长等职。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('447474bf113543a686312ea3f3432e26','a23958f2a093468d8476a9eec1ddb6a8',1937,'伪临时政府河北省长、伪华北政务委员会委员','原北洋政府官员，投敌后任伪河北省长等职。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5945d06b3ab54994807f3f35d9f6727a','83b067447f4744f7b527179c4d9524d4',1937,'伪临时政府河北省长','投敌后任伪河北省长，为华北早期汉奸之一。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fe7c702fbe8941ceb4f14299da92cec2','3acc7f5b9d1c45359d912b1fc0e2c626',1937,'伪新民会副会长、伪立法院副院长','原国民党官员，投敌后任伪新民会副会长等职，进行奴化宣传。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('620201f03d4b4a6b8ffe67b5798929ac','e1badd3fe14246acb4a3d2bf765b2db2',1937,'伪华北政务委员会实业总署督办、伪华北政务委员会委员长','华北重要汉奸，历任伪华北政务委员会要职，后任委员长。；投靠日本，在华北伪政权中任职，参与日伪统治，对陕西有间接影响。；投敌后任伪华北政务委员会实业总署督办，后任委员长，配合日军经济掠夺。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e134a1896c7446e6b353ddf37eed2cdf','51eaa4b1ac7641869b3baeeed576ac4c',1937,'伪华北政务委员会教育总署督办','著名作家，投敌后任伪华北政务委员会教育总署督办，推行奴化教育。；著名文人附逆，任伪华北教育总署督办，推行日伪奴化教育，影响包括河北在内的华北地区。；投靠日本，在华北伪政权中任职，推行奴化教育，对陕西有间接影响。；投靠日本，参与伪华北政权，推行亲日教育，配合日军在华北包括陕西周边地区进行文化殖民。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bf0e410e3122457f840413fea7c85155','b6ae69ffcd5e454a99182f7d989b8ad0',1938,'伪东亚文化协议会成员、亲日文人','作家，投敌后参与伪东亚文化协议会等组织，为日伪进行文化宣传。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('56a1d01cd61f40b5a6777e2ce6b3ea28','3fd05215d22d411cbf20ce669eabb4db',1938,'伪《申报》社长、伪东亚文化协议会成员','报人，投敌后任伪《申报》社长，为日伪进行舆论宣传。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7a18159da1ef47f583f5d59de5331f07','8645a36c774448e798d07ece262909ad',NULL,'无','无','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('108d7947046f4b7b81c24f48c5bd34bc','d1abe59a5d664bf18b442130fc0478a1',1938,'汪伪国民党中央宣传部部长、汪伪安徽省省长','广西陆川人，汪伪政权宣传系统核心人物，主办《南华日报》等鼓吹投降，属广西籍著名汉奸。；广东籍汪伪要员，长期主持汪伪宣传，属于华南籍附逆者，但与广西柳州无直接任职记载。；汪伪政权宣传系统核心人物，早年曾在广西活动，后随汪精卫投敌，负责伪政权舆论宣传，属与广西有历史关联的汪伪高层汉奸。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b7d2cca1f0ce485cb1d6c2549e286e70','62a6d6c8e7ab4bbfbc92c5b14abbde74',1938,'汪伪国民政府立法院院长、行政院院长、代理主席','汪伪政权二号人物，虽非广西籍，但其伪政权势力曾向华南包括广西渗透，抗战末期在南京等地主持伪政。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d4160c7dcbc847d3bdc6a0cb15361615','d85cd285c30b4eb0af400dc4a45494eb',1940,'汪伪广东省政府委员、伪民政厅长','在汪伪广东省政权中任职，参与华南沦陷区伪化统治，活动范围与广西东南部邻近。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dad3b8148a534e60a3f01018566a29ae','ce7546d10af04356983709b44dfe8ed1',1944,'伪广西维持会成员、伪柳州维持会头目（地方伪组织）','抗战末期日军侵入广西柳州期间，参与组织地方维持会，协助日军征粮、拉夫、维持治安，属柳州地方附逆者。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('378d334b45da4137bd6f9fc0884781d3','d0d924a87fa44b79a54bb80bd5690bd8',1944,'伪柳州维持会保甲长','日军占领柳州期间，充任伪保甲长，为日军派捐、指认抗日人员，属柳州基层汉奸。','基层帮凶(维持会系统)','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2103ecc19cf24a5dbf8ec38acf9ea501','eadd8843e09b48859807563c80046a25',1944,'伪三江维持会头目','日军侵扰桂北三江地区时，出面组织维持会，为日军带路、筹粮，属三江地方附逆者。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4a7a2bc0d8104ce08f83b25fcab2a912','27daf68623ea46ac92f5386b27003038',1944,'伪柳州警察局便衣队长','柳州沦陷期间充任伪警察便衣，协助日军搜捕抗日分子和地下工作者。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a917c1026338461ea22daf0c376d071d','8ab4e9687c814ebf88894bde1b3f3529',1938,'伪广东维持会头目（早期）','虽主要活动于广东，但其伪维持会网络曾向桂东、桂南渗透，与广西邻近地区伪化有关。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0fc8462f53334ab68ef78a9fca553614','6c881b59820e439c842c0724302987a9',1944,'伪广西绥靖公署参议（日伪策反人员）','抗战末期被日军利用，在广西进行策反和伪化宣传，活动于柳州、桂林一带。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('65e7d64442124f439482d442db2c8631','084a8b66c5e446d3a73b6e2d5205b4d8',1938,'汪伪政权中央监察委员会常务委员、汪伪国民政府委员','汪精卫之妻，随汪投敌后参与汪伪政权核心决策，曾到广西活动并为汪伪政权张目，属于广西籍或与广西有直接关联的著名附逆人物。；汪精卫之妻，随汪投敌后参与汪伪政权核心决策，曾到广西活动并为汪伪政权张目，是汪伪集团重要成员。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c06fcf1b7227402fafcac5e762b8041d','d1abe59a5d664bf18b442130fc0478a1',1938,'汪伪国民党中央宣传部部长、汪伪国民政府宣传部长','广西陆川人，汪伪政权宣传系统核心人物，主办《南华日报》等，为汪伪投降路线制造舆论，是广西籍汉奸中职务较高者。；广东人，汪伪宣传系统头目，早年曾在广西活动，后追随汪精卫叛国投敌，负责汪伪舆论宣传。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('af889d3412664444ba3e12477bad04d5','86e982eb4f0043c4b6f7b586ec525f98',1939,'汪伪政权广东省政府委员、伪军将领','广东籍伪军头目，活动于粤桂边区，其伪军势力曾渗入广西东南部，与柳州方向伪政权有联系。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4ea00f7a7c3640cb81b6349e7484802b','529eba01fd3844d2a4780badaf25cb50',1937,'伪蒙疆联合自治政府副主席、伪军头目','绥远地区著名汉奸，虽主要活动于华北，但其伪军系统与广西无直接关联，仅作为扩展检索中的排除项。；绥远籍汉奸，虽主要活动于华北，但其伪蒙疆政权与广西、桂林无直接关联，仅作为全国汉奸名录参考。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1d62c06cbca64b8f87cfdcb9a1087f69','5e606d59f6b44906b34555ad8d2022c8',1938,'伪广东维持会会长、伪广东省政府委员','广东伪政权头目之一，其维持会体系与广西梧州、柳州等地伪维持会有横向联系，间接影响柳州地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('237237fa1a6a42e1b9f0feb5af098b67','4ffa32e45d104ce88220a4d3f3942ffb',1940,'伪广东省政府主席、汪伪政权广东省长','陈璧君之弟，汪伪广东省政府主席，其伪政权与广西伪政权有行政往来，对柳州地区伪政权有间接管辖关系。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2d66efc442c046b09cd58f08668d9836','dfd3214d3b5a4dbd8a9dc139442d1acd',1944,'伪广西维持会成员、柳州伪维持会头目（待考）','据部分地方文史资料提及，1944年日军入侵柳州期间，有地方士绅组织伪维持会，张君嵩可能为其中之一，但可靠记载有限。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bf346c6e1122478ab1ce7e68a4229bf8','0a4ccb2198e14ef096089ca8086d93fe',1931,'桂系将领，抗战期间未附逆','桂系核心人物，抗战期间坚持抗日，未任伪职，此处仅作排除说明，非汉奸。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d4c9bcc760f240ff9fc99756139ff192','8ab4e9687c814ebf88894bde1b3f3529',1938,'伪广西省维持会会长（未就任）','日军侵占广州后，曾试图拉拢其出面组织伪政权，但陈炯明于1933年已去世，此说系误传，实际未参与。；日军侵占广州后，曾试图拉拢其出面组织伪政权，但陈炯明于1938年病逝，未实际附逆。；抗战初期日军曾试图拉拢其出面组织广西伪政权，但其未实际就任，相关记载存疑，仅作为广西伪政权筹组背景提及。；抗战初期日军曾试图拉拢其出面组织广西伪政权，但其未实际就任，相关记载存疑。；日军侵占广州后，曾试图拉拢陈炯明出任伪广西省维持会会长，但陈炯明未就任，此事与广西伪政权筹建有关。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7e3c607d042f4aeca85a395fd6fb59a7','fd012acd6eaf4a24aed8d1f0adae170e',1944,'伪柳州维持会会长','1944年11月日军侵占柳州后，出面组织伪柳州维持会，协助日军征发民夫、物资，维持占领区秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4f663f24c5884ff0b6fb90084070e163','3d48afc215a643f6b184aea0b61e193d',1944,'伪柳州维持会副会长','与张君度共同组织伪柳州维持会，负责联络地方士绅，为日军筹粮筹款。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6b3ee13f93b44e66861cdb0cb81dc606','fd542683ffd649c3a7a085edd10ccf0d',1944,'伪柳江县知事','日军占领柳州期间，出任伪柳江县知事，推行日军政令，协助清乡与物资统制。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('eafa5ddb95874644bd8855aee085fa24','7c8c802a3b6a4edfb2863c8cfd8df0db',1944,'伪柳北维持会会长','在柳北地区组织伪维持会，为日军征集粮食、牲畜，并协助建立伪保甲制度。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('65e0b9aa8a4f4e54a9d29a76acc76a52','af4d9150d6314cab9319562273a5c04f',1944,'伪广西省绥靖军司令（未就任）','日军曾试图拉拢其出任伪广西绥靖军司令，但其未就任，后逃往香港。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0758c7b3a442403587ced2f736c5a600','6b186890888c4ef59afd6a82a310d3ad',1944,'伪广西省主席（未就任）','日军曾策动其出任伪广西省主席，但其未接受，后率部撤退。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2e24d568a8d44147b7efe16dbd481cb6','8e033c0efe004d1f9fd444872d2b685c',1941,'伪华南政务委员会主席（未就任）','日军曾试图拉拢其组织伪华南政权，但其拒绝合作，未就任。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4d63a2d561e44be8a7bbc73ebb22a79f','d1abe59a5d664bf18b442130fc0478a1',1940,'伪南京国民政府宣传部长、伪安徽省长','广西籍（梧州），汪伪政权核心成员，负责宣传与地方伪政权，1945年被捕处决。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('53c64d51a99f49aebcd68e872d746621','845de899b20e4631bbf68676aa47dec8',1940,'伪南京国民政府行政院秘书长、伪广东省长','广西籍（防城），汪伪政权要员，参与伪政权决策与地方治理，1945年被捕。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2a617fe574524144804f3f75f534e79e','d0f14e9a4ad147849deae2340b83f8ff',1944,'伪广西省保安司令部司令（未就任）','日军曾策动其出任伪广西保安司令，但其未就任，后撤往后方。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5ee90f7a081a4f7cb3b65af858711fa8','0a4ccb2198e14ef096089ca8086d93fe',1944,'伪广西省主席（未就任）','日军曾试图拉拢其合作，但其拒绝，坚持抗日立场。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('db5bb01f64c64e6485c4238ab2d323e7','2fd4e198bb7f4afd84bb539635327fba',1944,'伪广西省教育厅长（未就任）','日军曾试图拉拢其出任伪教育厅长，但其未就任，后撤往重庆。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('681aed69511a4c31ad55d21001676b44','27e6537284c34943908eefa10510ad18',1944,'伪柳州警察局局长','日军占领柳州后，出任伪警察局长，协助日军维持治安，抓捕抗日分子。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('faa00da228ef4f9fb985f78c086946fb','86384f97be52418ab96d14317a77990b',1944,'伪柳北保甲长','在柳北地区担任伪保甲长，为日军征发民夫、粮食，协助清乡。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b4708480ccdf498cb3b463efffcc625b','bb6ea08a85454c91a3b091e200374b83',1944,'伪柳北维持会文书','在柳北维持会中担任文书，负责登记物资与民夫，协助日军统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e6346a1eb1bc4a91b1b1df41e6080e30','0a8a11d72d3e41f1b4563f18779c391e',1944,'伪柳州商会会长','日军占领柳州后，出面组织伪商会，为日军筹款筹粮，协助物资统制。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7f957b8b983d450ea41fd7d37cb489ab','8c1c98f7b39a4b608f2b627d46b586f7',1944,'伪广西省绥靖军副司令（未就任）','日军曾试图拉拢其合作，但其拒绝，坚持抗日。','基层头目','hanjian');
