INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6a279d9ca09143aea8dd83547878a5d4','af4d9150d6314cab9319562273a5c04f',1944,'伪柳州维持会文化科科长','日军侵占柳州期间，任伪柳州维持会文化科科长，协助日军进行文化渗透与奴化宣传。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('acf56cca3d0a4f8f8d6a4b557a76fbb9','f85264e6ee3445eb8307bb2decc934b9',1944,'伪鹿寨维持会经济科科长','日军侵占鹿寨期间，任伪鹿寨维持会经济科科长，协助日军掠夺物资、控制经济。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('612847bca6c046e8b2a05f31601be3dd','3d48afc215a643f6b184aea0b61e193d',1944,'伪鹿寨维持会财政科科长','日军侵占鹿寨期间，任伪鹿寨维持会财政科科长，协助日军控制财政、掠夺资源。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b21eed6f0aa44c95b98eaae104c662d6','f3ebed4507744ee4b58556a88de14e24',1944,'伪鹿寨维持会文化科科长','日军侵占鹿寨期间，任伪鹿寨维持会文化科科长，协助日军进行文化渗透与奴化宣传。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a34967f7866e41e989773d5a88c549f2','fd012acd6eaf4a24aed8d1f0adae170e',1944,'桂林维持会会长','日军侵占桂林后，出面组织桂林维持会，协助日军推行殖民统治，征发民夫、物资，维持地方秩序以服务日军。；日军侵占桂林后，出面组织桂林维持会，协助日军推行殖民统治，征发民夫、物资，维持地方秩序以供日军驱使。；1944年日军侵占桂林后，出面组织桂林维持会，协助日军维持治安、征发物资、诱降地方士绅，为日军在桂林的统治服务。；日军侵占桂林期间，出面组织桂林维持会，任会长，协助日军征粮、派夫、维持治安，镇压抗日活动，为桂林地区主要附逆者之一。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d03507c553c14d14a4ce45a551e9242d','5fd923e02f3445ba9c79ace5f39db06b',1944,'伪桂林市市长','桂林沦陷后出任伪桂林市市长，主持伪市政，配合日军实施保甲连坐、物资统制与宣传奴化政策。；桂林沦陷期间出任伪桂林市市长，主持伪市政，配合日军统治，推行保甲连坐，为日军筹粮筹款。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a29a42552e1b4a8a92639ef7e9fd4b8b','3d48afc215a643f6b184aea0b61e193d',1944,'伪广西省警务处处长','在日军占领广西期间，参与伪广西省政权，负责警务与治安，协助日军搜捕抗日人士、镇压民众反抗。；在日军占领广西期间依附日伪，担任伪警务头目，参与搜捕抗日人士、镇压民众反抗。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ed422f16b95147a285efeb5b52c515ec','a55f246e140d4624a240c74fb8ee7284',1944,'伪广西省财政厅厅长','在伪广西省政府中主管财政，为日军筹款、征粮，推行伪币与物资统制，支持日伪统治。；协助日军在广西占领区征收赋税，为伪政权筹措经费，涉及百色地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6cda957452d44bb0a4f57a578bcf8052','6b186890888c4ef59afd6a82a310d3ad',1944,'伪广西省主席（未就任/争议）','有资料称日军曾试图拉拢其组织伪政权，但其最终未公开附逆；此条仅作争议性关联记录，需谨慎使用。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e028559404f84ef7bdab711fa25d1461','62a6d6c8e7ab4bbfbc92c5b14abbde74',1940,'伪南京国民政府立法院院长、伪上海市市长','虽非桂林本地，但作为广西籍（或与广西有政治关联）的汪伪政权核心人物，其附逆行为对广西沦陷区伪政权有示范与统辖影响。；投靠日本，参与汪伪政权，配合日军在华东及华北包括陕西周边地区进行殖民统治。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ec364f07be0441b6a7e9ba93e77c123d','d0f14e9a4ad147849deae2340b83f8ff',1944,'伪广西省保安司令部司令','桂林沦陷后参与伪广西省军事组织，统率伪保安部队配合日军扫荡抗日游击队、维护占领区治安。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ea007ffa073b476b9561b676da860ee6','0a4ccb2198e14ef096089ca8086d93fe',1944,'伪广西省副主席（未证实）','有传闻称日军曾诱其出任伪职，但黄旭初实际未附逆；此条为争议性记录，需进一步考证。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9c9c057df42647cf966f7c5cbf8c8f78','628de3e1f6444491a6c5adb8d85cba19',1944,'桂林维持会副会长','协助张君度组织维持会，负责联络日军与地方士绅，征调民力物资，推行奴化宣传。；桂林沦陷期间任维持会副会长，协助会长张君度处理伪务，为日军征集粮食和民夫。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9e1d89a7431a448db41d517a591cdb13','7edfaa80910f4f0d97fe4f3a41ed6e62',1944,'伪桂林警察局局长','在桂林沦陷期间担任伪警察局长，指挥伪警察配合日军搜查、逮捕抗日分子，实施保甲连坐。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1e2492838f404dd782a821e398817f34','ff402eb79edc4b7896287b9eeb6090f4',1944,'伪广西省教育厅厅长','在伪广西省政府中主管教育，推行日语教学与奴化教育，篡改历史教材，为日军殖民统治服务。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('53a1744851f9468db65443dc407e00d3','a9fa228d25514fd0941677631406db00',1944,'伪桂林市商会会长','组织商会为日军筹款、摊派物资，协助日军实施经济统制，压迫商户与民众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('98927dcd995a477e993992a6f875cca3','b006f97780844173b82d19f230d70c42',1944,'伪广西省宣传处处长','负责伪政权宣传，散布“大东亚共荣”言论，诋毁抗日力量，配合日军进行思想控制。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e3247b01cd1c46c18903e8a21ff39a07','8c1c98f7b39a4b608f2b627d46b586f7',1944,'伪广西省绥靖公署主任（未证实）','有资料提及日军曾试图拉拢其组织伪绥靖机构，但张发奎实际坚持抗日；此条为争议性记录，需谨慎对待。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3f00391284a74e33a6e572be66061b62','432de53877d8476eb14402bbbf971a83',1944,'伪广西省建设厅厅长（未证实）','传闻日军曾诱其出任伪建设厅职务，但黄绍竑未公开附逆；此条为争议性记录，需进一步考证。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('779b2270bb4e4fba843d1ff6f251bf3f','084a8b66c5e446d3a73b6e2d5205b4d8',1938,'汪伪政权中央监察委员会常务委员、汪伪政府要员','汪精卫之妻，随汪投敌后参与汪伪政权核心决策，曾到广西活动并为汪伪政权张目，是汪伪集团重要成员。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0054860d41774cc3899b8808e9ec07fa','d0f14e9a4ad147849deae2340b83f8ff',1939,'伪广西维持会/伪政权相关头目','抗战时期在广西沦陷区附近参与伪政权维持活动，协助日军推行殖民统治，具体任职于桂南一带伪组织。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2355e2aecdc14970956231fdf4d7bdb0','86e982eb4f0043c4b6f7b586ec525f98',1938,'伪广东省/伪广西方面军职、伪军头目','抗战期间投敌，曾任伪军职务，活动于华南包括广西周边地区，配合日军对抗日力量进行镇压。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c91ffa19c5c34d51842d14d6e2b3959d','529eba01fd3844d2a4780badaf25cb50',1937,'伪军头目、伪绥西联军司令','长期在华北、西北投敌，虽主要活动不在广西，但其伪军系统与华南伪政权有联系，属于抗战时期有明确记载的汉奸。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e7ceb55e8e0044308cf548133268e3ce','62a6d6c8e7ab4bbfbc92c5b14abbde74',1938,'汪伪政权立法院长、伪上海市长、汪伪政府代主席','汪伪政权核心人物，参与对日投降与伪政权建设，其伪政权体系覆盖包括广西在内的华南沦陷区。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9a0bef593db84303bcbaff42ff56cf3a','a2e4190c87b449e685d78c118a6801b5',1938,'汪伪政权财政部长、伪警政部长、伪上海市长','汪伪政权核心成员，负责伪财政与警政，其伪政权体系对广西等沦陷区有影响。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dcb3476de5e84a3c9fde1eabd822809d','d1abe59a5d664bf18b442130fc0478a1',1938,'汪伪政权宣传部长、伪安徽省长','汪伪政权宣传系统负责人，推行亲日卖国宣传，其宣传体系覆盖华南包括广西。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('37a240b180964a4aa78f720d43ef7fd2','28c69a91441d4439abc95701e2c6787a',1938,'汪伪政权工商部长、伪浙江省长','汪伪政权重要成员，参与对日投降谈判与伪政权建设，属于有明确记载的汉奸。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('89a05b90d7f94c5dab468143cef03570','07ff958e7f18410f864975f09234ac7e',1938,'汪伪特工总部副主任、伪江苏省长','汪伪特工组织头目之一，参与镇压抗日活动，属于有明确记载的汉奸。；汪伪特务头子，其特务活动对广西有渗透，但直接关联较少。；汪伪特务头目，其特工网络覆盖华中、华南，属全国性汉奸。；浙江遂昌人，汪伪特工头目；与湖南衡阳无直接关联。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ac21873265604b7b9ff1fb954111e66d','28311a8f5be44c79bdc09dd3295b8511',1931,'伪满洲国执政、皇帝','被日本扶植为伪满洲国元首，充当日本殖民统治工具，属于抗战时期有明确记载的汉奸。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('80725c490b8c4ed2bc79399fbe1cdad6','c12e72a145724c39b755a2a16dce9a71',1938,'汪伪政权主席、行政院长','公开投敌，建立汪伪政权，是抗战时期最大汉奸头目，其伪政权体系覆盖包括广西在内的华南地区。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ec49121bdbc04410a558ca99377b6f0c','d0f14e9a4ad147849deae2340b83f8ff',1940,'汪伪政权广西方面联络人、伪军招抚人员','广西籍人，抗战期间投靠汪伪政权，参与在华南及广西边境的伪军招抚与联络活动，协助日军对广西进行政治诱降。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('eb6d32d4b93743ee9fc0151b963353e7','0a4ccb2198e14ef096089ca8086d93fe',1944,'桂系地方政权人物（抗战后期一度与日伪接触）','广西省政府主席，抗战后期在日军入侵广西、桂林沦陷前后，曾出现与日方接触、谋求地方自保的传闻与记载，但未公开投敌，历史评价复杂，常被列入广西沦陷时期附逆嫌疑人物讨论。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c3e4d1fe75b345cfa4b7e2f0646ed7c1','a55f246e140d4624a240c74fb8ee7284',1944,'桂林维持会会长','1944年日军占领桂林后，出面组织桂林维持会，协助日军维持地方秩序、征发物资、推行伪化统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6fe85f7e4f824d24a48f790f61da0431','5fd923e02f3445ba9c79ace5f39db06b',1944,'桂林伪警察局负责人','桂林沦陷期间，参与组建伪警察机构，协助日军搜捕抗日人员、管控户籍与物资。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d0ad1eee93fa4c85ba5cafc1166f3f9b','6b186890888c4ef59afd6a82a310d3ad',1944,'桂系将领（抗战后期与日伪有接触嫌疑）','桂系重要将领，抗战后期在广西沦陷区边缘与日伪方面有接触传闻，但未正式投敌，历史记载存在争议。；抗战后期在广西沦陷区与日伪方面有接触、妥协传闻，部分地方史料将其列入附逆嫌疑人物。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('47746e5e6dbe4c40a6c225a0ff449c28','fd012acd6eaf4a24aed8d1f0adae170e',1944,'临桂县维持会会长','临桂沦陷期间，出面组织地方维持会，为日军征粮、派夫、维持伪秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c4b48e00f890436188fda632e53b34c7','eeccfce67d1c4e8481918ceade5208a3',1944,'桂林伪政府教育科附逆人员','桂林沦陷后，参与伪政权教育机构，推行奴化教育，协助日军控制学校与文化宣传。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('df288188f258425caf0cc4bb54e39d97','fb6b6a8dbe504339b1855a6f12142213',1944,'桂林伪商会负责人','桂林沦陷期间，协助日军控制商会、摊派款项、征调物资，为伪政权经济掠夺服务。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f98a210865be44f9af8326cf926a395e','ff402eb79edc4b7896287b9eeb6090f4',1944,'广西伪军头目','抗战后期在广西境内组织伪军，配合日军扫荡抗日游击区，活动范围涉及桂林周边。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e4f6b86294204589adccdc4bce0d53c0','7edfaa80910f4f0d97fe4f3a41ed6e62',1944,'广西伪保安队头目','广西沦陷期间，率伪保安队协助日军维持占领区，参与清乡与搜捕抗日人员。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6e8d091ae90049b7afbbb245a2c0eaed','1d857b1673bc4e558246126a8e648905',1940,'汪伪政权广西籍附逆文人','广西籍文人，投靠汪伪政权，在南京、广州等地从事亲日宣传，与广西沦陷区伪化宣传有联系。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('38783279c33d4f7c87f4bfa54c1546d2','fd012acd6eaf4a24aed8d1f0adae170e',1944,'伪桂林维持会会长','日军侵占桂林后出面组织伪维持会，协助日军维持占领秩序、征派民夫与物资。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('615ca5a59cd34823ac4106730ebce7dc','5fd923e02f3445ba9c79ace5f39db06b',1944,'伪广西省政府委员、伪桂林市市长','抗战后期附逆，参与伪广西政权，在桂林沦陷期间为日军占领当局效力。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('573e288c348d4e2998f291110965a95d','fb6b6a8dbe504339b1855a6f12142213',1944,'伪广西省政府主席','日军发动桂柳会战后，在广西沦陷区参与伪政权活动，担任伪省府要职。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('749dd2aa232246faa5aabb9f326d3211','316d187ae9644ca782cc874a635e3554',1944,'地方伪军、伪警察头目','桂柳沦陷期间，广西部分地方武装和警察在日军诱降下改编为伪军伪警，协助日军控制交通线和乡镇。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ca7edf304c2e4599a3469b413c0b493f','c9a8e156621e438eac6035f65b5c2fd9',1944,'伪全州维持会会长','1944年日军侵入全州后，当地士绅中有人出面组织维持会，为日军筹粮、派夫、维持地方秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('29496ae86a0b415a839f3d6b2dae4944','5f83ea26d4f746a28264d005892a9b6f',1944,'伪桂林警察局负责人','桂林沦陷期间，伪警察机构协助日军搜捕抗日人员、管制居民、征收捐税。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b780f8bbe2ed43c8ac59ceae5a3f3e8f','5e5d54676f9b4531861501ace894b384',1944,'伪军大队长/支队长','在桂柳会战后的沦陷区，部分投敌武装被编为伪军，配合日军扫荡抗日游击区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('84b05d8c834d4ff2a7b39def7b107afa','35ec901bb2e147ca91e27a882001f8c5',1944,'伪学校校长、伪宣传机构人员','在日军占领桂林、柳州等地期间，少数教育文化界人士参与伪政权举办的宣传、奴化教育活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('15bd0d112eeb4b4d9a2104d0b649f3f6','62a6d6c8e7ab4bbfbc92c5b14abbde74',1938,'伪南京国民政府立法院长、伪上海市长等职','作为汪精卫伪政权核心人物之一，参与对日投降与伪政权建设，其伪政权体系影响覆盖包括广西在内的沦陷区及国统区渗透活动。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('19bd68d939a7428da29d4b580a288942','a2e4190c87b449e685d78c118a6801b5',1938,'伪南京国民政府财政部长、伪行政院副院长等职','汪伪政权核心成员，负责伪财政与特务系统，参与对日合作及对后方包括广西地区的政治渗透与情报活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c761240dab1d49229137e04c67afdc0a','07ff958e7f18410f864975f09234ac7e',1939,'伪特工总部主任、伪江苏省长等职','汪伪特务头目，其特务网络在华南、西南包括广西方向进行渗透、策反与情报搜集活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('31ddf3b54fb64d6182e367cd0e31ac11','084a8b66c5e446d3a73b6e2d5205b4d8',1938,'汪伪政权中央监察委员会常务委员等','汪精卫之妻，积极参与汪伪政权对日投降活动，在伪政权中担任要职，影响涉及华南包括广西的伪组织发展。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('16e325d00de741b1b9036aac6cd932ef','664d3df731bb4293bee63eea6deacb2d',1938,'伪南京国民政府外交部长、伪广东省长等职','汪伪政权要员，曾任伪广东省长，其活动范围邻近广西，参与对日合作与伪政权建设。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d1deab889063452db962ae6ee61de264','d1abe59a5d664bf18b442130fc0478a1',1938,'伪南京国民政府宣传部长等职','汪伪政权宣传负责人，主导亲日卖国宣传，其宣传网络覆盖包括广西在内的南方地区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6655ac0439c5461d8a4b4a63fd0ad3c5','28c69a91441d4439abc95701e2c6787a',1938,'伪南京国民政府工商部长、伪浙江省长等职','汪伪政权核心成员，参与对日投降谈判与伪政权运作，其活动对南方包括广西有政治影响。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('caeb147772c6451f97880698559b96cc','9910c48b9b394ffa8c73439ed0a473b0',1939,'伪特工总部主任、伪社会部长等职','汪伪特务头目之一，参与对后方包括广西地区的特务渗透与策反活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('09f4eea0da064d77acd352b800526987','ed0d68ce0e0f4e40ba88774709d7fea6',1939,'伪广西维持会成员（地方维持会头目）','在广西地方协助日军维持占领区秩序，参与组织维持会，为日军提供物资与情报支持。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9d49c2c557864d00baf49807b8e6ad13','0a4ccb2198e14ef096089ca8086d93fe',1944,'桂系人物，抗战后期与日方有接触传闻','作为桂系要员，在抗战后期广西沦陷前后有与日方接触的传闻，但历史记载存在争议，未被广泛认定为汉奸。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c67f34934df94e0ab6bb39ad56e485e5','8c1c98f7b39a4b608f2b627d46b586f7',1937,'国民党将领，无汉奸明确记载','在广西等地指挥抗战，无可靠历史记载表明其附逆，此处仅作排除性说明。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1f8b2d8551ce4ccaa8aa6a10d20b0dd8','14b45fa244664bae8e79ac7542e41e05',1944,'伪桂林妇女会负责人','桂林沦陷后投靠日军，组织伪妇女团体，宣传“大东亚共荣”，动员妇女为日军服务。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a0c6e258a70546baa3c7499dcee72a27','6b186890888c4ef59afd6a82a310d3ad',1944,'伪广西省绥靖公署顾问（附逆嫌疑）','抗战后期与日伪方面有秘密接触，其部属在桂林沦陷前后有投敌行为，本人被指对日伪妥协，历史评价存在附逆争议。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('90e8a00691d645398322e590598fe67e','a55f246e140d4624a240c74fb8ee7284',1944,'伪桂林县县长','桂林沦陷后出任伪桂林县县长，协助日军建立基层伪政权，推行保甲制度，征发劳役。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('35e428505c094b648d85d3f6cb1ca16d','6d6faf0313364a3486e47fd5e264fee3',1944,'伪广西省宣传处处长','在日伪占领广西期间负责伪宣传机构，为日军侵略辩护，进行奴化宣传。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('99691672193740a8a090c3e9a58b7549','0a4ccb2198e14ef096089ca8086d93fe',1944,'伪广西省合作事业管理处处长（附逆嫌疑）','桂林沦陷后留在广西，与日伪有经济合作往来，被指为日伪筹措物资，战后受到调查。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5d44e910c96d4faa910af4a608568c65','ff402eb79edc4b7896287b9eeb6090f4',1944,'伪桂林市商会会长','日军占领桂林后，出面组织伪商会，强制商户向日军缴纳物资，配合日军经济掠夺。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b16a59507059457e808921e12f35e175','fd012acd6eaf4a24aed8d1f0adae170e',1944,'伪平乐县维持会会长','日军侵占平乐期间，出面组织伪平乐县维持会，充任会长，为日军征派粮秣、民夫，协助维持占领秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('27fd7ba76b944610a8499636f5870aec','5fd923e02f3445ba9c79ace5f39db06b',1944,'伪桂林市维持会会长','桂林沦陷后，参与组织伪桂林市维持会并任会长，协助日军推行殖民统治，征调物资与人力。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0fc56be8291a499497573079fde8032c','3d48afc215a643f6b184aea0b61e193d',1944,'伪广西省维持会会长','日军第二次入侵广西期间，出面组织伪广西省维持会，任会长，为日军筹粮筹款、招募伪职人员。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('222c893118ca4dfe85a66218c6d70825','6b186890888c4ef59afd6a82a310d3ad',1944,'伪广西省政府顾问（附逆嫌疑）','抗战后期在广西与日伪方面有接触，被指对日妥协、保存实力，其部属在沦陷区有附逆行为，历史评价存在争议。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f4557be2f4664e03aa33bae389a8296e','28b2a90196a541a4a14854e999ea536e',1944,'伪桂林市警察局局长','桂林沦陷期间出任伪警察局长，协助日军维持治安，搜捕抗日人员，镇压民众反抗。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2611353ba41041dfa5d5e7f78f464878','c6e1aee62f104133b4370604e1b8c142',1944,'伪广西省教育会附逆人员（争议）','抗战时期在广西从事教育活动，被指在沦陷区与日伪合作推行奴化教育，但史料记载不一，存在争议。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('40cd574834df48b7a71785781cc28782','1d857b1673bc4e558246126a8e648905',1944,'伪平乐县保安队队长','平乐沦陷后率地方武装投靠日军，编为伪保安队，配合日军扫荡抗日游击队，征缴民间枪支。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3633099bc33e4b25904f273684724402','b56c75d9a5f24306ace42d07ab4b1fc5',1944,'伪桂林市商会会长','桂林沦陷期间出面组织伪商会，为日军筹款筹物，强制商户“献纳”，协助日军经济掠夺。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('17bbccea6e6645c98021840036772200','a55f246e140d4624a240c74fb8ee7284',1944,'伪广西省宣传处附逆人员','在日军占领广西期间，参与伪宣传机构，为日军“大东亚共荣”宣传造势，撰写附逆文章。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('871a86383f84413faeb50c1017b28bb6','0a4ccb2198e14ef096089ca8086d93fe',1944,'伪广西省维持会副会长（附逆嫌疑）','广西沦陷时期与日伪有联系，被指参与维持会活动，协助日军维持地方秩序，但史料记载有限。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b7c8a96f48584a1d9f3eb4f55a417427','d0f14e9a4ad147849deae2340b83f8ff',1940,'汪伪广西省政府主席（未实际到任）、伪军将领','广西籍旧军人，抗战期间投靠汪伪政权，被任命为汪伪广西省政府主席，虽因广西大部分地区未沦陷而未实际主政，但参与伪政权对广西的策反与渗透活动。；广西籍旧军人，抗战期间投靠汪伪，被任命为汪伪广西省政府主席，虽因广西大部未沦陷而未实际主政，但其附逆行为与广西、桂林地区有直接政治关联。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b193d8a39a0c42ed9fb33c5cb24fcbf5','dfd3214d3b5a4dbd8a9dc139442d1acd',1944,'伪桂林维持会会长','1944年日军发动豫湘桂战役占领桂林后，出面组织伪桂林维持会，协助日军维持占领秩序、征发民夫与物资。；1944年日军侵占桂林期间，出面组织伪维持会，协助日军维持地方秩序、征发物资。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3be28676fcec440d9daf038ad3bae1e4','5fd923e02f3445ba9c79ace5f39db06b',1944,'伪桂林市商会会长、维持会成员','桂林沦陷期间，依附日军，参与伪维持会与商会活动，为日军筹款筹粮，协助控制桂林商业与物资流通。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6827cd90a2144f61ad285f634209b280','6b186890888c4ef59afd6a82a310d3ad',1944,'桂系将领，后与日伪暗中联络','抗战后期在广西主政期间，曾与日军及伪政权进行秘密接触和妥协，保存实力，对日伪在广西的渗透负有责任，但其主要身份仍为国民党桂系将领，附逆程度存争议。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('43ee96f69d494ad0b6f4e7871747f6b8','0a4ccb2198e14ef096089ca8086d93fe',1931,'广西省政府主席（抗战后期与日伪有接触）','长期主政广西，抗战后期在日军入侵广西时，省政府撤退，部分地方政权瓦解，其下属有投敌行为，黄本人对日伪渗透应对不力，但未直接投敌。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e9443a12859f479badb4123a2b978693','a55f246e140d4624a240c74fb8ee7284',1940,'伪广西省警务处处长（汪伪任命）','被汪伪政权任命为伪广西省警务负责人，负责在广西沦陷区及周边建立伪警察力量，配合日军维持治安、搜捕抗日人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('003815eeafaf4ee0b124ec8bcf9b95f3','62a6d6c8e7ab4bbfbc92c5b14abbde74',1938,'汪伪政权立法院院长、伪上海市长','汪伪政权核心人物，其伪政权对广西有名义统辖权，并通过伪组织对广西进行策反与宣传，间接影响广西附逆势力。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fd53a94be3dd4ac3934d1644922f8240','d1abe59a5d664bf18b442130fc0478a1',1938,'汪伪政权宣传部长','负责汪伪宣传，对广西进行亲日卖国宣传，拉拢广西籍人士附逆，影响广西部分文化教育界人士。；负责汪伪宣传，在华南包括广西沦陷区推行奴化教育，桂林、灌阳等地学校曾被迫使用伪教材。；汪伪宣传头目，进行亲日宣传，战后被处决。；负责伪政权宣传工作，推行亲日奴化教育，战后以汉奸罪被处决。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3b625eddbe7f474aade02d49cd8301a4','845de899b20e4631bbf68676aa47dec8',1938,'汪伪政权广东省长、伪侨务委员长','汪伪政权要员，参与对华南包括广西的伪化活动，协助日军在广西周边建立伪政权。','机构委员长(非国家首脑)','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6341d7a77f4140ac8a870007f33e0fee','664d3df731bb4293bee63eea6deacb2d',1938,'汪伪政权外交部长','汪伪核心成员，参与对日外交与伪政权扩张，对广西有间接影响。；参与汪伪对日外交，其伪政权体系涉及广西，桂林沦陷期间伪组织受其外交方针影响。；汪伪政权核心成员，参与对湖南等地的伪化宣传，间接影响常德、临澧地区的附逆分子。；汪伪高官，参与对重庆方面的诱降活动，战后被处决。；代表汪伪政权与日本交涉，签署卖国条约，战后以汉奸罪被处决。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('534ea65546344edc871f86d8bbc33619','28c69a91441d4439abc95701e2c6787a',1938,'汪伪政权工商部长、内政部长','汪伪政权要员，参与伪政权对广西的经济统制与渗透。；参与汪伪政权组建，推行亲日经济政策，战后以汉奸罪被处决。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6fa2113851f2445fb5aba6a57858b22e','0d2d2045fc1d498dab9499e43abcb3de',1938,'汪伪政权司法行政部长、伪安徽省长','汪伪要员，参与伪政权对广西的司法与行政渗透。；湖南湘乡人，汪伪政权重要成员，历任伪司法行政部长、伪安徽省长等职，参与伪化统治，其活动与湖南伪政权有联系。；在安徽推行伪政，镇压抗日力量，战后以汉奸罪被处决。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e5ae59e8596841e0b09cd669a335d56b','d823baec96e04682bca33413f02ae20d',1938,'汪伪政权浙江省长','汪伪政权要员，对广西无直接活动，但作为汉奸整体名录可列。','省部级/大军区级要员','hanjian');
