INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fb8bbd0877c04f99bc950ab9723a2889','62a6d6c8e7ab4bbfbc92c5b14abbde74',1938,'汪伪国民政府立法院长、行政院长、代主席','汪伪政权核心人物之一，早年曾参与广西方面政治活动，后随汪精卫投敌，任汪伪要职。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('88e4b0f27f1d45649a0f9bac694072e2','529eba01fd3844d2a4780badaf25cb50',1937,'伪军头目、伪“和平建国军”将领','绥远、华北一带伪军头目，后其伪军系统被日军调遣至华中、华南，与广西周边伪军有联系。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('103ec79f9008462f91e1893cb2e62295','848992e841c9488c8cdcf56cad9f079c',1938,'伪“和平救国军”总司令、伪河南省长','华北伪军大头目，其伪军系统曾配合日军在华中、华南作战，间接影响广西战局。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7bd1ee8217a34e18a7c9954fe2838b4e','9f7b3ed9c76f4eea8211fd8ebc40a461',1943,'伪“和平救国军”第四方面军总司令','原国民党将领，1943年投敌，所部伪军活动于河南、安徽等地，与广西外围战事有关。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b07b8cffbcf9460aaa53280ba1e635d1','5ec2ad124b2f429482b1a90a7f8d4a92',1943,'伪“和平救国军”第二十四集团军总司令','原国民党河北省主席，1943年投敌，其伪军活动于华北，后其系统被日军南调，与广西战事有间接关联。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f9eca839b0bd4fe99a7bfc8a42401638','664d3df731bb4293bee63eea6deacb2d',1938,'汪伪国民政府外交部长、驻日大使','汪伪核心成员，参与汪伪政权对日外交，其活动虽主要在南京，但属汪伪体系覆盖广西。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('12b3648cf21342559f8d72a67ef7bedf','28c69a91441d4439abc95701e2c6787a',1938,'汪伪国民政府工商部长、内政部长','汪伪政权重要成员，参与汪伪与日本谈判，属全国性汉奸。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('86575a7fcb604abb933e18ed85688087','9910c48b9b394ffa8c73439ed0a473b0',1938,'汪伪特工总部主任、伪浙江省长','汪伪特务头目，其特工系统渗透华南，与广西周边伪政权有联系。；湖南常德人，汪伪特务头子，参与伪政权特务活动，其势力范围涉及江西部分沦陷区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5a927effd611489aa8f7b4f8c5d13e19','f50cf011f8f842fc8d69caa402ffbf67',1938,'伪中华民国维新政府内政部长、伪江苏省长','华中伪政权头目，后并入汪伪，属全国性汉奸。；作为伪江苏省长，直接管辖镇江、丹徒地区，推行清乡运动，镇压抗日力量，征收苛捐杂税。；在镇江及江苏地区组织伪政权，推行奴化教育，协助日军清乡，残害抗日军民。；浙江绍兴人，曾任伪维新政府内政部长，后任伪江苏省长，协助日军清乡，残害抗日军民，抗战胜利后自杀。；浙江杭州人，早年追随汪精卫，后投靠日本，任伪维新政府内政部长，参与组建伪政权，协助日军在江浙地区推行“清乡”政策。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('61a9d1059b654737a12e5d6c9fb5465f','f62754ef8d4a41f58e3b8f1b4bd4ab3a',1940,'汪伪国民政府考试院长','汪伪政权成员，属全国性汉奸。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dc306f108ee74670bdfe8c18eac31664','3acc7f5b9d1c45359d912b1fc0e2c626',1938,'伪中华民国维新政府立法院长','华中伪政权头目，后与汪伪合作。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cc195b56311c4d51b27a2cde769173b2','1d67ff455ffc47b8addcc485beb0ca34',1932,'伪满洲国军政部大臣','东北伪军头目，属全国性汉奸。；原东北军旅长，投日后任伪军政部大臣，负责伪军整编，其部队曾驻防热河，参与对承德、滦平抗日力量的围剿。；参与伪满军事行动，涉及冀东边境地区；原东边道镇守使，投日后任伪军政部长，协助日军整编伪军，围剿抗联。；辽宁台安人，原东北军将领，九一八后投敌，任伪军政部大臣，协助日本整编伪军，镇压辽宁及大连地区抗日活动。；辽宁台安人，曾任伪奉天省警备司令、军政部大臣，协助日军清剿抗日力量。；原奉军旅长，投日后任伪满军政要职，指挥伪军配合日军在沈阳、浑南等地扫荡抗日游击队。；原东边道镇守使，投日后在黑龙江、牡丹江等地部署伪军配合日军“讨伐”。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('35ac835cbe38488badfe5743be0ac3e6','1ba31d558b934fbd83a28a8c2b446022',1932,'伪满洲国热河省长','东北伪军头目，属全国性汉奸。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cd7277f504b1413caeb373f89ebf7421','d0f14e9a4ad147849deae2340b83f8ff',1940,'汪伪政权广西方面联络人、伪军头目','在广西南部及桂东南一带为日军搜集情报、策动地方势力投敌，配合日军对桂林、柳州等地的进攻。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('60691df393c6431f8657afa166f9ab66','0a4ccb2198e14ef096089ca8086d93fe',1937,'桂系要员，后附逆传闻人物','广西省政府主席，抗战期间与日方有秘密接触传闻，但未公开投敌，历史评价存在争议，非典型汉奸。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c35423e0453f414cb9033159613e6d43','e02fd2faed6245d7aadb7fc51e70e6d2',1940,'汪伪政权考试院院长','参与汪伪政权，在华南地区进行所谓和平运动宣传，与广西部分附逆知识分子有联系。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('40a6bdf5e7d44477b6ea3dee055b6024','86e982eb4f0043c4b6f7b586ec525f98',1940,'汪伪政权广东省警务处长、伪军将领','在华南配合日军清乡，其势力范围曾延伸至桂东、桂南，与桂林地区伪维持会有联络。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ffdf38e8c4004ecdb30606dcd6237bea','529eba01fd3844d2a4780badaf25cb50',1937,'伪蒙疆联合自治政府要员，后活动于华南','早期在华北投敌，后受汪伪指派到广西、广东一带策反地方武装，与桂林伪政权有间接关联。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('926d6008b76a4587ba198be7abca126f','62a6d6c8e7ab4bbfbc92c5b14abbde74',1938,'汪伪政权立法院院长、行政院院长','汪伪政权核心人物，其伪政权体系覆盖广西，桂林、柳州等地伪组织受其领导。；汪伪政权核心人物，其伪政权体系覆盖湖南，对常德、澧县等地伪组织有统辖关系。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8f91c1398496405483796dc4c431c361','845de899b20e4631bbf68676aa47dec8',1940,'汪伪政权广东省长、伪军要员','在广东、广西边界地区组织伪军，配合日军扫荡，与桂林地区伪维持会有联系。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5ab9f88cccb4481f8fe2bf85a27859b5','e0084ea11e804593a3e43a7c28d2fc67',1938,'伪广东番禺、顺德等地维持会长','在珠三角地区组织伪维持会，其模式被推广至广西部分沦陷区，桂林附近亦有类似组织。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('71b73183421e4fe0b2574732a87a7745','075b5b4817584064baada36d1055f1e2',1944,'伪桂林维持会会长','1944年日军侵占桂林后，出面组织伪维持会，协助日军维持治安、征发民夫、搜刮物资。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4741e0b0d53543bcbd18a9e47e7aca62','5fd923e02f3445ba9c79ace5f39db06b',1944,'伪桂林警察局局长','桂林沦陷期间任伪警察局长，配合日军镇压抗日活动，抓捕抗日志士。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b5e8096ef45246149ee4773a4b8a9664','b3c2657f84d74659a2c94bd2933d78da',1944,'伪灌阳县维持会会长','灌阳沦陷期间组织伪维持会，为日军征粮、派夫，协助日军控制地方。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1ad91845550342ecb465f5637c9b36eb','057de9adc28f4cb1b72d979205e303ce',1944,'伪灌阳县保安队长','投靠日军，率伪保安队配合日军扫荡灌阳周边抗日游击队。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('370b45a906764d1aa4271472ee821980','05bffb13c43f4bfdbe42a13b08cc2ebc',1944,'伪全州、灌阳一带维持会联络员','在桂北全州、灌阳地区为日军搜集情报，策动地方士绅附逆。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('563d6c9a7ea046209e203f9dae4fee2f','c91f6de89cd543ed9f399f290bbf4156',1944,'伪桂林商会会长','桂林沦陷后出面组织伪商会，为日军筹款筹粮，协助经济掠夺。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('053b8a0c651a4271bddf7ea5e61e1746','7c01041998954328a6dd59c666b12be1',1940,'伪广西教育会会长','在汪伪政权支持下，于广西沦陷区推行奴化教育，桂林、灌阳等地学校被迫改用伪教材。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f38a491331ab438f892d7e9b29df1ff4','27e6537284c34943908eefa10510ad18',1944,'伪广西日报社长','桂林沦陷期间主办伪报，为日军宣传“大东亚共荣圈”，进行文化附逆。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2b6cb5a0bb734c1e942585f755d546f5','084a8b66c5e446d3a73b6e2d5205b4d8',1938,'汪伪政权中央监察委员会常务委员、汪伪政府广东省长等职（与广西有历史关联，其夫汪精卫为广西籍相关政治人物）','随汪精卫投敌，参与建立汪伪政权，任伪中央监察委员会常务委员等职，为汪伪政权核心人物之一；其活动虽主要在南京、广东等地，但与广西籍汪精卫集团关系密切，对广西籍人员附逆有影响。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c6c08057f01e4ec9854a8ec8282d3bc7','c12e72a145724c39b755a2a16dce9a71',1938,'伪中华民国国民政府主席、行政院长兼海军部长等','原籍浙江山阴，生于广东三水，但其政治势力与广西有深厚关联；1938年12月发表艳电公开投敌，1940年在南京成立汪伪国民政府，自任主席，成为抗战时期最大汉奸头目。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fe7329632b6c4f3fbd90e428f5714a5b','86e982eb4f0043c4b6f7b586ec525f98',1938,'伪广州市长、伪广东省政府委员等','广东人，抗战期间投敌，历任伪广州市长、伪广东省政府委员等职，协助日军维持广东沦陷区统治；其活动范围与广西邻近，属华南伪政权系统。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2956cb903bff4562ba268decfa42690a','4ffa32e45d104ce88220a4d3f3942ffb',1940,'伪广东省政府主席、伪广州市长等','陈璧君之弟，汪伪政权要员，历任伪广东省政府主席、伪广州市长等职，在广东沦陷区推行伪化统治，与广西邻近地区有联系。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0fa97c7347fe49dba677147e1f46599d','d1abe59a5d664bf18b442130fc0478a1',1938,'伪中央宣传部长、伪安徽省长等','汪伪政权宣传系统负责人，广东人，长期追随汪精卫，负责伪政权宣传与思想控制，其活动虽不在广西，但属汪伪集团核心，对华南包括广西附逆势力有影响。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9b047377929c4d038bafe9f5d3a16dd9','664d3df731bb4293bee63eea6deacb2d',1938,'伪外交部长、伪广东省长等','汪伪政权要员，历任伪外交部长、伪广东省长等职，参与汪伪政权对日交涉与地方伪化统治，属华南伪政权系统。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2967ad1f0ae54b1db5b90f0ad2ae0c96','62a6d6c8e7ab4bbfbc92c5b14abbde74',1938,'伪立法院长、伪上海市长、伪国民政府代主席等','汪伪政权核心人物之一，历任伪立法院长、伪上海市长、伪国民政府代主席等职，汪精卫死后继任伪政权头目，属全国性大汉奸。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f2554a26b9cd4003858b14418481b1ea','a2e4190c87b449e685d78c118a6801b5',1938,'伪财政部长、伪警政部长、伪上海市长等','汪伪政权核心人物之一，历任伪财政部长、伪警政部长、伪上海市长等职，掌握伪政权财政与警察系统，属全国性大汉奸。','省部级/大军区级要员','hanjian');
