INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a7f2a66f5649461c9665d8bed48dc80b','d0f14e9a4ad147849deae2340b83f8ff',1940,'汪伪政权广西省省长、伪军将领','广西籍人，投靠汪伪政权，任伪广西省省长，协助日军在广西推行伪化统治，在桂林等地进行诱降与维持会组织活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a81f15d0ec2746f5938bb3dc8a0c77f1','0a4ccb2198e14ef096089ca8086d93fe',1944,'桂系要员，抗战后期一度与日伪接触','桂系核心人物之一，抗战后期在广西沦陷期间曾与日军有妥协接触，其部下在桂林、柳州等地组织维持会，虽未正式投敌，但相关附逆行为有记载。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9cc927fc899245429666e6e32c02d749','5fd923e02f3445ba9c79ace5f39db06b',1944,'桂林伪警察局局长','桂林沦陷后投敌，任伪警察局局长，协助日军搜捕抗日人士、镇压民众反抗，维持日伪在桂林城区的秩序。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8de844350b8a4f93ae630150578e8abe','6b186890888c4ef59afd6a82a310d3ad',1944,'桂系将领，抗战后期与日伪有秘密接触','桂系重要将领，抗战后期在安徽、广西等地与日伪有秘密接触，其部下在桂林沦陷期间有部分人员投敌组织伪军。；抗战后期在广西地区与日伪方面有秘密接触和妥协活动，但未公开投敌，属于复杂历史人物，地方史料中对其附逆嫌疑有争议。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('316d5e6c1ce34349abdd740e00334584','a55f246e140d4624a240c74fb8ee7284',1944,'桂林伪维持会副会长','桂林沦陷后与张君度共同组织维持会，负责联络地方保甲长，为日军征粮征夫，协助推行伪化教育。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b91cef46ae16481f9afb68c4c723cf74','ff402eb79edc4b7896287b9eeb6090f4',1940,'汪伪广西省警务处处长','在汪伪广西省政权中任职，负责警务与情报，协助日军在桂林、南宁等地建立伪警察网络，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f5b101cffe3741919329dc12624d0026','27e6537284c34943908eefa10510ad18',1944,'桂林伪商会会长','桂林沦陷后出面组织伪商会，为日军筹款筹粮，协助日伪控制桂林经济，压迫商户。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('833ceab0040f40319c0919cec5d87b9c','113aecc016814053ac08a977b5c4819c',1944,'桂林伪教育会会长','在桂林沦陷期间附逆，主持伪教育会，推行奴化教育，篡改教材，为日军文化侵略服务。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c70c95b4369b45f5a87377f1eff4ea05','d0f14e9a4ad147849deae2340b83f8ff',1944,'伪广西省维持会会长、伪广西省政府委员','桂系出身，抗战后期在日军侵占广西期间出面组织伪维持会，协助日军维持桂林、柳州等地治安，为日军征发民夫物资。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('34be7684b64b45e2a38a8371681606d3','27e6537284c34943908eefa10510ad18',1944,'伪桂林市维持会会长','1944年日军攻陷桂林后，出面组织伪桂林市维持会，协助日军搜捕抗日人士、征发粮食民夫，维持日占区秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('43a87ec541da448c810e347858333b6b','a55f246e140d4624a240c74fb8ee7284',1944,'伪桂林市警察局局长','桂林沦陷后投敌，出任伪警察局长，率伪警察配合日军清查户口、抓捕抗日分子，镇压市民反抗。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0dccb5e0783745daacdd868963db696f','5fd923e02f3445ba9c79ace5f39db06b',1944,'伪广西省保安司令部司令','原桂系军官，桂林沦陷后率部投敌，被日军委为伪广西省保安司令，收编散兵游勇组成伪军，配合日军扫荡桂北抗日武装。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('85bd798762a540d68dd6e1cd161eb595','af4d9150d6314cab9319562273a5c04f',1944,'伪广西省绥靖军总司令','原国民党军将领，抗战后期在广西投敌，组织伪绥靖军，活动于桂林、柳州、荔浦一带，协助日军维持占领区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7005c490c3e747eeaee0193abfa9878c','fd012acd6eaf4a24aed8d1f0adae170e',1944,'伪荔浦县维持会会长','1944年日军侵入荔浦后，出面组织伪荔浦县维持会，为日军征粮征夫，协助日军控制荔浦及周边乡村。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('40e0e3027fe145b08edc07da704b81cd','1d857b1673bc4e558246126a8e648905',1944,'伪荔浦县警察所所长','荔浦沦陷期间投敌，任伪警察所所长，率伪警配合日军搜捕抗日人员，勒索当地民众。','无明确职位或一般帮凶','hanjian');
