INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a67d6fdab77d48a3bf6825122c41768b','a2e4190c87b449e685d78c118a6801b5',1938,'汪伪财政部部长、警政部部长','汪伪政权核心成员，其财政、警政体系对华南包括广西有间接影响，桂林抗战后方曾对其伪化经济政策进行抵制。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('19f037eeb7774e0ab769cac4c03d564c','664d3df731bb4293bee63eea6deacb2d',1938,'汪伪外交部部长、广东省省长','汪伪政权要员，曾任伪广东省省长，其活动范围与广西、桂林邻近，对华南抗战后方有威胁。','省部级/大军区级要员','hanjian');
