INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4a48ef7aca634ef595c639092be6b1ec','628de3e1f6444491a6c5adb8d85cba19',1944,'桂林城防司令，后投敌','桂林保卫战期间任城防司令，城陷后未坚持抵抗，被日军俘获后变节投敌，参与伪政权组织的活动，为桂林地区重要附逆人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4a35b1026bf94d03b52b41212e53806f','4c9c6707d36a45a296c2ffcdcc855ebb',1944,'桂林维持会副会长','桂林沦陷后与张君度共同组织维持会，任副会长，协助日军管理桂林市区，征调民夫物资，迫害抗日群众。','基层维持会/地方自治头目','hanjian');
