INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('64c66e4814334419a3ea31f5d06e4df2','86e982eb4f0043c4b6f7b586ec525f98',1938,'伪广东治安维持会会长、伪广州市长','广东沦陷区汉奸，活动于广州及周边，与广西玉林地区无直接关联。；广东人，抗战期间投敌，组织伪维持会，协助日军维持广州治安；与湖南郴州、安仁无直接关联。','基层维持会/地方自治头目','hanjian');
