INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('19083e89a6324426af0f2c7401d17951','a2e4190c87b449e685d78c118a6801b5',1938,'伪南京国民政府财政部长、伪上海市长','汪伪政权核心人物，活动于南京、上海，与广西玉林无直接关联。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6a98b29a984742f8bd4e574ff943fc8c','31abdc5e4e0a4ebdbe5f0b715a509863',1937,'伪中华民国临时政府行政委员长','活动于北平，与广西玉林无直接关联。；伪临时政府头目，其伪政权势力曾渗透至四川，战后被逮捕。；在北平组建伪政权，后并入汪伪政权，战后以汉奸罪被逮捕，狱中自杀。','机构委员长(非国家首脑)','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8e49fb4b785141e7bc1e354ac6c15d24','664d3df731bb4293bee63eea6deacb2d',1940,'伪南京国民政府外交部长','汪伪政权人物，活动于南京，与广西玉林无直接关联。；汪精卫伪政权核心人物，参与伪政权外交与内政，其政策影响包括河南沦陷区，协助日军推行殖民统治。；参与策划对贵州的外交与宣传攻势，拉拢贵阳知识界人士附逆。；投靠日本，在汪伪政权中任职，推行亲日外交，对陕西有间接影响。；汪伪政权要员，与陕西渭南地区无直接关联。；汪伪政权外交要员，参与对日卖国外交，其活动服务于日军侵华整体战略，对包括陕西在内的中国抗战有危害。；投靠日本，参与汪伪政权，配合日军在华东及华北包括陕西周边地区进行殖民统治。；汪伪政权外交负责人，参与对日妥协投降活动。；在汪伪政权中任外交要职，参与对日妥协。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ba5582f7b0874be99975fffd061e70f4','28c69a91441d4439abc95701e2c6787a',1940,'伪南京国民政府工商部长','汪伪政权人物，活动于南京，与广西玉林无直接关联。；其部门在贵州秘密采购战略物资，通过贵阳商界汉奸网络输往沦陷区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e7333bff4d5f4b47831e7273e9c5358b','d1abe59a5d664bf18b442130fc0478a1',1940,'伪南京国民政府宣传部长','汪伪政权人物，活动于南京，与广西玉林无直接关联。；在贵州散发伪宣传品，收买贵阳报界人员，为日军侵黔制造舆论。；投靠日本，参与汪伪政权，进行亲日宣传，配合日军在华东及华北包括陕西周边地区进行殖民统治。；在汪伪政权中负责宣传，为日军侵略辩护。','省部级/大军区级要员','hanjian');
