INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a2b44d387d9040d6b516be2ed6a46ec1','96b96eb8f5414a1f874f70f38feb0054',1937,'伪上海大道市政府市长','上海伪政权头目，与广西玉林无直接关联。；早期伪政权头目，后失势。；在上海沦陷区组织伪政权，配合日军统治。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3e86aeca94e942209d68a4e556b789f6','4c9c6707d36a45a296c2ffcdcc855ebb',1939,'伪广西省维持会会长（未就任）','据部分地方文史资料提及，日军入侵广西期间曾拟拉拢其出面组织伪维持会，但其未实际就任，相关记载存疑，需谨慎使用。','基层维持会/地方自治头目','hanjian');
