INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d886a0e748324cc0a5a7e7e2e2b182e5','74a64b2a6efb4c73982cbdd156849ea8',1940,'伪钦县教育局局长','在钦县推行奴化教育，篡改教材，强制学校讲授日语和亲日内容，毒化青少年思想。','市县厅局级','hanjian');
