INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f1b92f20eb60441eb0772e0238b0cdcf','c12e72a145724c39b755a2a16dce9a71',1940,'伪国民政府主席、伪国民党总裁','叛国投敌，在南京成立汪伪政权，与日本签订卖国条约，组织伪军配合日军作战','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('60b264ca802947aaa6f723e80b5237e2','a2e4190c87b449e685d78c118a6801b5',1938,'伪行政院副院长、伪财政部长、伪上海市长','参与筹组汪伪政权，主管财政金融，为日军搜刮资财，战后被判死刑后改无期；湖南沅陵人，叛国投敌，参与汪伪政权核心，虽主要在南京、上海活动，但作为湘籍汉奸头目对湖南沦陷区伪政权有影响。；湖南沅陵人，汪伪政权核心人物之一，虽主要在南京、上海活动，但作为湖南籍汉奸头目，对湖南沦陷区伪政权建立有直接影响。','省部级/大军区级要员','hanjian');
