INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('60625a72df2e45cf8ac8ae605bd92919','cebb4769b324411abb6e1f5a0f26ecf6',1938,'伪第一方面军总司令、伪江苏省长','率部投敌，任伪江苏省长期间镇压抗日力量，战后逃港；其伪军部队在无锡、宜兴一带驻防，协助日军“扫荡”，并参与清乡。；率伪军驻防江苏，参与清乡和扫荡，在常熟、苏州一带配合日军作战。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('829ab74a3cf946f3a63f15e654438bae','3f934b1c263b4cd78c73d9700621e7bd',1938,'伪江苏省长、伪安徽省长','历任汪伪江苏省长、安徽省长，推行奴化统治，战后被捕；伪维新政府及汪伪政权要员，其伪省政体系与江西九江沦陷区有行政与经济联系。；汪伪政权地方头目，与重庆地区无直接关联。','省部级/大军区级要员','hanjian');
