INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('838737fcd9174161bb8396b4397b64c4','a06c0041e5294f2987f746729e510de9',1937,'伪淮海省省长、伪第八方面军总司令','在徐州地区建立伪淮海省，残酷镇压抗日军民；抗战后期投敌，任伪淮海省省长，其伪军活动于苏鲁豫皖边区，曾配合日军在河南东部行动，与漯河地区有间接关联。；投敌后任伪职，所部伪军在豫东、皖北一带活动，配合日军进攻抗日根据地，对漯河、舞阳周边地区造成威胁。；河南阌乡人，1943年投敌，在苏北、淮海地区活动；与湖南衡阳无直接关联。；投靠日本，在苏北、淮海地区组建伪军，配合日军作战，其伪军活动对陕西抗日根据地有间接影响。；原国民党将领，投敌后任伪淮海省省长，组建伪军配合日军。','省部级/大军区级要员','hanjian');
