INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d4cc58211b1a4c938b3fac0c3081d127','cebb4769b324411abb6e1f5a0f26ecf6',1940,'伪南京绥靖公署主任','原国民党军官，投敌后任伪南京绥靖公署主任，统辖苏南、苏中伪军，协助日军维持占领区秩序。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('30b6a2235eba446a8fb7bafe5f3570ef','3acc7f5b9d1c45359d912b1fc0e2c626',1940,'伪国民政府考试院副院长','江苏无锡人，早年加入国民党，投日后在南京伪政权任职，参与“和平运动”宣传，为日军服务。；参与伪政权教育考试制度，推行奴化教育。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('acd15bc809df4acb908771cd32deff6e','f50cf011f8f842fc8d69caa402ffbf67',1938,'伪江苏省省长','原国民党官员，投敌后任伪江苏省长（驻苏州），在江苏推行伪化统治，配合日军清乡。；任伪江苏省长期间，推行日伪统治政策，协助日军清乡，对南通、如东地区抗日力量进行镇压。；任伪江苏省长期间，管辖南通、海安等地，组织伪军和警察，协助日军扫荡，征收苛捐杂税，迫害抗日民众。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b9378395e5ae4453906db90cf47a386a','07ff958e7f18410f864975f09234ac7e',1941,'伪江苏省省长兼特工总部主任','原中统特务，投日后组建76号特工总部，后任伪江苏省长，在苏州、南京等地残害抗日志士。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3519354f96f14298afb1d383fe078a6f','a2e4190c87b449e685d78c118a6801b5',1940,'伪行政院副院长兼财政部长','原国民党中央宣传部部长，随汪精卫投敌，在南京伪政权中掌握实权，协助日军经济掠夺。；其伪政权控制舟山海关和税收，为日军筹集军费。','省部级/大军区级要员','hanjian');
