INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cbddd64acec144b28693caa8739ff040','f50cf011f8f842fc8d69caa402ffbf67',1938,'伪中华民国维新政府内政部长','协助梁鸿志组建伪政权，主管内政，参与清乡和特务活动。；主管伪政府内政，协助日本维持南京及江苏地区统治，参与清乡和特务活动。；协助梁鸿志组建伪政权，负责警察与特务系统，迫害抗日人士。；协助梁鸿志管理伪政权，参与清乡和特务活动。；任伪维新政府内政部长，参与镇压抗日活动，在南京及鼓楼地区设立特务机构。；浙江绍兴人，抗战期间附逆，任伪维新政府内政部长、伪江苏省长等职，推行伪化政策。；华中伪政权要员，与陕西渭南地区无直接关联。；投靠日本，参与伪维新政府及汪伪政权，配合日军在华东及华北包括陕西周边地区进行殖民统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7d288195496345d89cb17af2b402b66a','80cae6effc3d4019b67eeeb81d5e9e63',1938,'伪中华民国维新政府立法院长','担任伪立法院长，为日本占领政策提供法律依据。；参与伪政权立法，为日本殖民统治提供法律依据。；任伪立法院长，为日本侵略政策提供法律粉饰。；参与组建伪维新政府，为日军在南京的殖民统治提供法律与行政支持。；投靠日本，参与伪维新政府及汪伪政权，配合日军在华东及华北包括陕西周边地区进行殖民统治。','伪政权最高层/元首级','hanjian');
