INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('498b8f74367346a29ad4f4313379b4a6','cebb4769b324411abb6e1f5a0f26ecf6',1938,'汪伪政府江苏省省长、伪军第一方面军总司令','原国民党将领，投敌后任汪伪江苏省省长，在南京、溧水等地推行清乡，镇压抗日力量，协助日军征粮征税。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('27e606ff32ab4467a430cf9d98cc9582','07ff958e7f18410f864975f09234ac7e',1939,'汪伪特工总部（76号）负责人、伪江苏省政府主席','在南京、上海等地组建特务组织，残害抗日志士，后任伪江苏省主席，在溧水等县强化伪政权统治。；在江苏、上海地区组织特务活动，镇压抗日力量，推行清乡政策，后因日方内部矛盾被毒杀','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('422fc6e2000f49b7a57b915bfcbf0815','f50cf011f8f842fc8d69caa402ffbf67',1940,'汪伪政府内政部长、伪江苏省长（后期）','在江苏地区推行伪化政策，参与清乡运动，对溧水等地抗日根据地实施经济封锁和军事围剿。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c8537ebca0f1416c91071c7794b075dc','3f934b1c263b4cd78c73d9700621e7bd',1940,'汪伪南京特别市市长、伪江苏省长','任伪南京市长期间，协助日军维持治安，后调任伪江苏省长，在溧水等地推行保甲制度，搜捕抗日人员。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('185227c352b24526bf12c6a19f862bde','260af50e16cb47f19341bcffade264ee',1941,'汪伪江苏省政府委员、伪溧水县长（任职时间较短）','在溧水任伪县长期间，组织伪警察和自卫团，配合日军扫荡，强征民夫修筑据点。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8459094b72a14e3780122dcfecba6ab3','4c0724ba86184ad9aea99954ed4e044b',1941,'汪伪江苏省保安司令部参谋长、伪溧水地区清乡指挥官','在溧水、句容一带指挥伪军清剿新四军游击队，杀害多名抗日群众，烧毁村庄。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b0d15174aedf40f69441fa60ef62d7ab','0d2b86dbbedf44a286ab059fed3e73fa',1940,'伪溧水县知事（汪伪时期）','在溧水推行伪政权，征收苛捐杂税，向日军提供粮食和情报，破坏地下抗日组织。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c3385a99e4d844dd8cb6ce23eb4fc92a','a2e4190c87b449e685d78c118a6801b5',1940,'汪伪政府行政院副院长、伪财政部长兼伪江苏省长（兼任）','虽主要活动于南京，但作为伪江苏省最高行政长官，对溧水等地的伪政权运作负有直接责任，支持清乡。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d9afc672a0bd46938da2c135b31e1e4a','9910c48b9b394ffa8c73439ed0a473b0',1940,'汪伪社会部长、伪浙江省长（曾短暂兼管江苏部分地区）','在南京、江苏活动期间，参与策划对溧水抗日根据地的特务破坏行动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('27dfdea36ad64ae481664fa4e8894f5b','3acc7f5b9d1c45359d912b1fc0e2c626',1943,'汪伪立法院副院长、伪江苏省长（后期）','在江苏推行“新国民运动”，在溧水等地强化奴化教育，协助日军进行经济掠夺。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0cb188cb01b448b2ae7a3db7c526fa4b','62a6d6c8e7ab4bbfbc92c5b14abbde74',1944,'汪伪政府代理主席、伪江苏省长（名义）','作为汪伪最高领导人之一，对江苏包括溧水地区的伪政权统治负有总责，未直接到溧水但政策覆盖该地。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('475f68f1c63844009b90e4a72f2ca84b','d1abe59a5d664bf18b442130fc0478a1',1940,'汪伪宣传部长、伪安徽省长（曾兼管江苏边境）','在南京、江苏地区进行汉奸宣传，影响溧水一带的舆论，为日军侵略张目。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('631da974d1004779a1f056f497c64b04','28c69a91441d4439abc95701e2c6787a',1940,'汪伪内政部长、伪浙江省长（曾参与江苏事务）','在南京参与汪伪政权决策，其推行的保甲制度在溧水等地实施，强化了日伪控制。','省部级/大军区级要员','hanjian');
