INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('63e9200849c848bfa39e951e9787a35f','1bea23fefee9462fab8d11fc69a557b9',1937,'伪华北政务委员会财务总署督办','在南京鼓楼区参与伪政权金融会议，协助日本控制经济。；在廊坊各县强征苛捐杂税，为伪军和日军提供经费，加重百姓负担。；负责伪华北财政，为日军在河北等地征敛物资和税款。；安徽人，抗战期间投靠日军，任伪华北政务委员会财务总署督办，在华北地区推行伪化经济统治。；掌管伪华北政务委员会财政，为日军在华北包括陕西的侵略提供经济支持。；投靠日本，参与伪华北政权，配合日军在华北包括陕西周边地区进行经济掠夺。；在华北伪政权中负责财务，配合日军经济掠夺。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9b84189b10484919a288ce313278d962','06c4f35ee78346faad09f9021d8bd970',1937,'伪中华民国临时政府司法委员会委员长','在南京鼓楼区参与伪司法系统建设，为日军服务。','机构委员长(非国家首脑)','hanjian');
