INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1b63b2acb6d94c07aff393d5d053a9f2','07ff958e7f18410f864975f09234ac7e',1938,'汪伪特工总部（76号）主任、江苏省省长','投靠日本，组建76号特工组织，残害抗日志士，后任汪伪江苏省省长，统治江苏期间横征暴敛。；无锡人，组建76号特工，暗杀抗日人士，破坏地下组织，后任伪江苏省长期间实施清乡，残害民众，1943年被毒杀。；在盐城地区协助日军清乡扫荡，残害抗日军民，组织特务暗杀活动，后任伪江苏省长期间强化对苏北的殖民统治。；组建76号特工组织，在江苏、上海等地大肆捕杀抗日人士，后任伪江苏省省长，推行清乡运动，残害百姓。','省部级/大军区级要员','hanjian');
