INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4cb8814e0f0b4eec9d84ba8d737892cb','07ff958e7f18410f864975f09234ac7e',1938,'汪伪特工总部（76号）主任、汪伪江苏省政府主席','投靠日本，组建76号特工组织，在江苏、上海等地大肆捕杀抗日志士，后任汪伪江苏省长，推行清乡政策，祸害如皋等苏中地区。；在江苏南通、通州等地部署特工网络，镇压抗日活动，推行清乡运动，残害抗日军民。；在江苏、上海等地组织特务活动，镇压抗日力量，后任汪伪江苏省主席，管辖包括盐城、东台地区，推行清乡政策，残害民众。；在江苏盐城、阜宁一带组织清乡扫荡，捕杀抗日军民，推行汪伪政权统治，后因内部矛盾被毒杀。','特工总部主任','hanjian');
