INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f4e446097ae54f4fa9cf8406e62e2862','82175420bb7b41c885e5486399f83bbc',1942,'常州天宁区伪保长','在天宁地区告密抗日活动，带领日军搜查民宅，勒索百姓，导致多名地下党员被捕。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3c36b34856014330a60433a31ffd3be9','a2e4190c87b449e685d78c118a6801b5',1939,'汪伪行政院副院长、财政部长（曾兼江苏省长）','虽为中央级汉奸，但其在江苏（含常州）的伪税警团和特工系统直接控制天宁一带的物资配给和情报网。；虽主要在上海/南京，但其控制的伪财政系统在常州钟楼征收各种苛捐杂税，支持伪军和特务活动，间接参与对当地抗日力量的镇压。；虽非无锡籍，但长期控制江苏政务，在无锡推行伪币政策，垄断物资，支持清乡，间接参与对无锡的殖民统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e1bfe67d5a214c508c98ded999fe4efb','4c0724ba86184ad9aea99954ed4e044b',1937,'汪伪常州维持会会长、伪常州县长','日军占领常州后出任维持会会长，后任伪县长，协助日军征粮、征税，镇压抗日活动，强迫民众欢迎日军，推行奴化教育。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('63078125b2b64f65b8468fc2941d0f44','80c19677480749eda7b9e26e0920def2',1938,'伪常州保安大队长','组织伪保安队，配合日军清乡扫荡，搜捕抗日志士，杀害新四军交通员及群众，抢劫民财。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a9aa762e2fe64d52868f28ecea6439f7','2a9429d0933e46dd990edb237e4abb4c',1939,'伪武进县知事（常州地区）','在伪政权中推行保甲制度，强征壮丁，为日军提供劳役，参与经济统制，掠夺粮食棉花。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5fb8f6408f914b9bbba29f5fed245339','2f41922cae144be9be7b2c61455a2a43',1938,'伪常州商会会长（附逆）','为日军筹措军饷，组织商会为伪政权捐款，强迫商户使用军票，协助日军控制常州商业命脉。','基层头目','hanjian');
