INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('874883a9264244589e07786e4cd2b999','3b28a0ae9ced49f4bd465270bab0c94a',1937,'伪常州维持会会长（初期）','日军占领常州初期，组织维持会，协助日军建立伪政权，在钟楼地区张贴告示，强迫居民领取‘良民证’，为日军征粮派夫。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4619f422b8bb4bf7944ed04f5006d006','a5f5a19f73dd449ebbaf35024bbe05b7',1938,'伪武进县（含钟楼）知事/县长','主持伪县政，在钟楼地区实施保甲制度，清查抗日嫌疑分子，配合日军‘扫荡’，并参与汪伪‘清乡’行动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('793d71683c274334b1d5750b917238b5','d385dabb054b48799cb7eb9b60fa7cd2',1940,'伪武进县警察局长','指挥伪警察在钟楼地区巡逻、搜捕抗日地下工作者，查禁抗日书刊，逮捕并引渡爱国人士给日军宪兵队。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c56fd37c0ab242f99021686b07c115a8','4b466e2b0900404a8f165e0d34923cc9',1938,'伪常州商会会长（汉奸商人）','为日军在钟楼地区筹款、采购军需物资，强迫商户缴纳‘慰劳金’，并协助日伪经济统制，垄断粮食和棉布。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('564fd854623a4109a6011b7458639406','a06c0041e5294f2987f746729e510de9',1942,'伪淮海省省长、伪徐州绥靖公署主任','原为国民党将领，1942年投敌，任伪淮海省省长兼保安司令，在徐州地区推行日伪统治，镇压抗日力量，征收苛捐杂税，协助日军进行“清乡”和“扫荡”。；原为国民党将领，1942年投敌，任伪淮海省省长，统治徐州及周边地区，推行日伪政权，镇压抗日活动，1945年日本投降后一度被收编，后再次反叛被处决。；原为国民党将领，1942年投敌，任伪淮海省省长，统治徐州及周边地区，推行日伪政权，镇压抗日力量，1945年抗战胜利后一度被收编，后再次反叛被处决。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b8133b2ee99c4f2dbec3a62761bd4eaa','29efac731db049eaae30482803d23e05',1943,'伪淮海省保安副司令、伪徐州绥靖公署参谋长','追随郝鹏举投敌，参与组织伪军和警察，在徐州及周边地区协助日军抓捕抗日志士，破坏地下抗日组织。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d49e850c247646ba87553f83dc15468f','848992e841c9488c8cdcf56cad9f079c',1943,'伪淮海省保安司令（后任伪第四方面军总司令）','原西北军将领，投日后在徐州地区负责伪军整编与训练，多次率伪军配合日军进攻抗日根据地，参与“治安强化运动”。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a0904cf3b48e4f459340ad38ecb5cdfd','ef676fac9bb24126bcc992f39c87c979',1940,'伪华北政务委员会驻徐州办事处处长','在徐州主持伪华北政务委员会事务，推行奴化教育，强制民众献铜献铁，为日军战争机器搜集物资。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6c2b85234f4e4e6db9a50d526883c31d','10b88f41fdee46778f29f60ae3d41741',1938,'伪天津市市长（曾短暂兼任徐州地区伪职）','虽主要活动在天津，但曾以伪华北政权高官身份巡视徐州，推动“中日亲善”宣传，协助日军在徐州建立伪政权体系。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('723113287fc444b7bb9c85ac9654ab66','8f1dd12e548b4c4f866dd743c3377896',1940,'伪华北政务委员会委员长（管辖徐州地区）','作为华北伪政权最高负责人，直接管辖徐州地区，推行“新民会”运动，组织汉奸团体，配合日军进行经济掠夺和思想控制。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e88accd90883410aa7915f9517287376','da58b77853f14ce7b32f7f6b3305b75a',1940,'伪华北治安军总司令（在徐州设有分支机构）','其指挥的伪治安军在徐州地区驻有部队，参与“扫荡”八路军和新四军，杀害抗日军民，强征壮丁。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('30bd1ca8681a4f8d867d09b7e3450faf','d2b840cc6fa142c8b5c30c100a11b64d',1938,'伪徐州地区维持会会长（早期）','日军占领徐州初期，组织维持会，为日军提供粮食、劳力和情报，协助建立日伪基层政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('39581876fa674a539035d06b94bb73a6','8dd71bba0484426388d6dbcfae15bd52',1938,'伪山东省省长（曾管辖徐州北部地区）','其伪政权势力延伸至徐州北部（如丰县、沛县一带），推行保甲制度，强征粮食，镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('44f4749ec15040b3826e5ccaf0288435','9edb0275b4734a47805ca9385baed31a',1938,'伪济南维持会会长（曾参与徐州地区伪组织协调）','作为山东伪政权头目，曾协调徐州与济南间的伪军行动，协助日军运输物资，破坏陇海铁路沿线抗日游击战。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ce76f3b6099246e1a4c025a2a81075b5','9ca0328bf94a47b0b9efceee14b76a01',1939,'伪徐州警察局局长','指挥伪警察在徐州城内搜捕抗日地下工作者，查禁抗日书刊，配合日军宪兵队实施“特别清乡”。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('24f095807e70485fbbdceeb9555c5a56','797c553510f3440f88255e16480f23b4',1938,'伪铜山县知事（县长）','在铜山地区（今徐州铜山区）推行日伪法令，强征土地税，组织“自卫团”协助日军，迫害抗日家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('32144780bce143e5a3ac96f4f3e94e0e','646ddf68eb4d4278bbebfd2c78cf329d',1939,'伪睢宁县知事','在睢宁地区建立伪政权，强征壮丁补充伪军，多次向日军报告新四军活动情报，导致抗日武装遭受损失。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cc760cc6078045be8a51f0f55a1bcf56','48ebe058067b43e790583011139dbe95',1940,'伪丰县知事','在丰县推行“保甲连坐”，杀害抗日干部，组织地主武装“还乡团”，配合日军进行“蚕食”进攻。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2b705605f0834d33aea620ebbba561cf','ff36e423126d40dd8a1a47689baf8ffe',1941,'伪沛县知事','在沛县强征军粮，破坏中共地下组织，协助日军建立碉堡封锁线，镇压湖西抗日根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7f8478f9bc2440828404f34f56c1e92b','32d46280d809464e98e1a6cf0ed30ece',1942,'伪邳县知事','在邳县（今邳州）推行奴化教育，强迫民众参加“新民会”，搜捕抗日游击队员，向日军提供运河沿线情报。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c4267b7f428644b4b2c5b890aff42944','2044d833c6ab4b308f4359ff9991d320',1943,'伪新沂县知事','在新沂地区组织伪保安队，配合日军“扫荡”宿北抗日根据地，强征民夫修筑公路和炮楼。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c75a2b51c0fb4591aca6d637f30db110','5a14726dc0a944709762daf466d4cd08',1943,'伪徐州绥靖公署高级顾问','原国民党军官，投敌后为日军提供徐州地区军事部署建议，参与策划“铁壁合围”战术，对抗抗日武装。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('140de7ee5c924537b5a24e2098ee45af','63006a4879fb4f49ad97a1e88c8c5d69',1942,'伪第二方面军总司令（曾驻防徐州周边）','率伪军数万人在徐州以西地区驻防，多次进攻冀鲁豫抗日根据地，烧杀抢掠，制造无人区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('338c76115b784e0ea013d5e231e3a3ff','5ec2ad124b2f429482b1a90a7f8d4a92',1943,'伪第五方面军总司令（曾活动于徐州附近）','投敌后其部队在徐州以北地区活动，配合日军“扫荡”太行山和冀南抗日根据地，残害抗日军民。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f3f57b94f2384e28a440e317233cb201','a06c0041e5294f2987f746729e510de9',1941,'伪淮海省保安司令、伪和平救国军第一军军长','原为国民党将领，1941年投敌，在徐州地区组建伪军，协助日军扫荡抗日根据地，残害抗日军民。；原为国民党将领，后投靠汪伪政权，在徐州及周边地区协助日军清剿抗日武装，镇压民众，后于1946年反正，但此前在泉山地区有活动记录。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('23658e3af92747be944bc625afc53b64','848992e841c9488c8cdcf56cad9f079c',1939,'伪和平救国军第二军军长、伪苏北绥靖公署主任','在徐州及丰县一带活动，率伪军配合日军“清乡”“扫荡”，镇压抗日力量，强征民夫粮饷。；在徐州地区为日军效力，参与“扫荡”抗日根据地，在泉山一带设立据点，强征民夫，掠夺物资。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1d2acd4f02674a3fbb8a6a148622d8ae','807ca12d2dcb44989aababb17d52ca6d',1940,'伪徐州绥靖公署参谋长、伪淮海省保安副司令','协助日军管理徐州地区伪政权，参与策划对丰县、沛县等地的军事围剿，迫害抗日家属。','基层头目','hanjian');
