INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c5fda927dd144e7995ed8384b5c17309','ff36e423126d40dd8a1a47689baf8ffe',1940,'伪丰县警察局长','协助日军建立特务情报网，搜捕共产党员和进步人士，刑讯逼供，制造多起惨案。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e41599d869ad42f19b824f076e29e962','ff1091c1c06f4fe584fadafb613b1248',1938,'伪丰县维持会会长','日军初占丰县时组织维持会，为日军筹粮派款，引导日军清乡，迫害抗日群众。','基层维持会/地方自治头目','hanjian');
