INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4a0d9d3a14e4421a9db46a7aa4259895','40ceda4a3fba43bb8c30faefaa993de4',1943,'伪和平救国军第三方面军总司令（曾驻徐州地区）','率部在徐州、丰县一带活动，配合日军进攻抗日根据地，屠杀抗日军民，后于1945年反正。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7187bd77bc3a426896b7771287914b56','848992e841c9488c8cdcf56cad9f079c',1943,'伪淮海省保安司令、伪徐州绥靖公署副主任','原西北军将领，投日后在徐州地区组织伪军，协助日军清乡扫荡，残害抗日军民。；原西北军将领，投日后在徐州地区组织伪保安部队，协助日军清乡扫荡，残害抗日军民。','市县厅局级','hanjian');
