INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9fe8c5801c6145c3b8094ce6c5b632a7','e87739f6f4234a0b817687e42b19e5ed',1941,'伪鼓楼区区长','任伪鼓楼区区长期间，负责该区治安和物资配给，强征民夫修筑工事，并协助日军清查抗日嫌疑人员。','基层头目','hanjian');
