INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4d1550ee288a43038ec4d783e7103180','903f92a867db4e77abb94dac1ad28168',1939,'伪苏北地区绥靖军总司令、伪第一集团军总司令','原国民党鲁苏战区游击纵队副总指挥，1939年投敌，在扬州、泰州一带收编伪军，配合日军扫荡抗日根据地，残害抗日军民。；原国民党鲁苏战区游击纵队副总指挥，1941年投敌，在扬州、泰州一带配合日军进攻新四军，残害抗日军民，后任伪第一集团军总司令，驻防苏北（含邗江地区）。','省部级/大军区级要员','hanjian');
