INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7629f6fc089f42abb5035e8eb32f2c34','a2e4190c87b449e685d78c118a6801b5',1940,'伪行政院副院长兼财政部长（汪伪中央，影响扬州宝应）','虽驻南京，但通过伪江苏省政府控制扬州宝应税收和物资，资助伪军清剿抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('82be61d43d09485d9f3afaf23e53d171','903f92a867db4e77abb94dac1ad28168',1939,'伪苏北绥靖军总司令、伪第一集团军总司令','原国民党鲁苏战区游击副总指挥，1941年投敌，在扬州、泰州一带收编伪军，配合日军‘清乡’扫荡，残害抗日军民。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bf44d8da3a024c07b950bf2c165ce0f6','dc2c7930d2b4490aafb9ba6c509ff1e3',1940,'伪江都县知事（县长）','在扬州广陵地区推行伪政权，协助日军征粮、征税，抓捕抗日志士，参与‘清乡’运动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dabd5bbb8bd6408d94688e89ac183974','807ca12d2dcb44989aababb17d52ca6d',1941,'伪江都县保安大队长','率伪保安队驻防扬州城，多次配合日军突袭新四军游击队，杀害地下党员，强征民夫修筑工事。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e8ca753a922f4694a026b18ca2f1d293','c3dada437a4b47afb8549cbac2f856b3',1937,'伪扬州维持会会长（初期）','扬州沦陷后率先组织维持会，为日军提供物资、情报，协助建立伪政权，后任伪商会会长。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6300f0eada5145cdb06696ae08e65c0a','94e92476c693405cb4077ebab12f08d8',1940,'伪江都县警察局长','在广陵城区设立特务机构，搜捕抗日分子，严刑逼供，破坏地下交通站，罪行累累。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('90e3b164e006483aae1c54b9c11d5bc9','a2e4190c87b449e685d78c118a6801b5',1941,'伪国民政府财政部部长兼伪中央税警总团总团长','虽主要活动于南京，但曾多次到扬州、广陵视察伪政权，推动‘清乡’和物资统制，间接支持当地汉奸势力。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('61125ecd470748a39b20f51d2addd491','bacadba533394b3bb79fb5b9c5b66118',1943,'伪苏北行营主任（驻扬州）','统管苏北伪军和行政，在扬州广陵地区强化殖民统治，组织‘自首’运动，迫害抗日家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('05d1ec605a744ba7a7217f1ef9d9a679','63006a4879fb4f49ad97a1e88c8c5d69',1942,'伪第二方面军总司令','率部驻防扬州及周边，配合日军‘扫荡’高邮、宝应等地，在广陵设有指挥部，参与镇压抗日武装。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c97daac7e21849ddac11a08e4c73e9c7','dc2c7930d2b4490aafb9ba6c509ff1e3',1937,'伪扬州维持会会长、伪江都县知事','扬州沦陷后出任伪维持会会长，后任伪江都县知事，为日军征粮派款，镇压抗日民众，协助建立伪政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('89bb557011e3444d841bb2ac19dbbb87','45531b9eaba24b64b538ece7b006de71',1940,'伪江都县县长','汪伪政权时期任江都县（含扬州城区）县长，推行保甲制度，强征壮丁，配合日军清乡，迫害抗日家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1686dee904184b988cc7d0da80a57d11','94e92476c693405cb4077ebab12f08d8',1940,'伪扬州保安队大队长','原土匪头目，投日后任伪扬州保安队大队长，率部在扬州郊区（今经开区一带）搜捕抗日游击队员，抢劫民财，民愤极大。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c4146340b7814601aa52c84adbcf47e8','739a1ecacf814b4dba52c2be8866ff38',1940,'伪江都县警察局长','任伪江都县警察局长期间，在扬州城区及近郊（含今经开区部分区域）设立特务据点，逮捕抗日地下工作者，刑讯逼供。；管理伪警察机构，在扬州城内设立特务据点，侦捕地下党员和进步学生，破坏抗日组织。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c1f29e1f1788444d90757eea05fc89d4','a2e4190c87b449e685d78c118a6801b5',1940,'汪伪行政院副院长兼财政部长（曾兼伪江苏省长）','虽非扬州本地人，但作为汪伪核心人物，曾管辖江苏（含扬州地区），支持伪军清乡，其势力渗透扬州，间接参与对扬州抗日力量的镇压。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9a6b5d1c647d4531aff4ab42fe230101','3acc7f5b9d1c45359d912b1fc0e2c626',1940,'汪伪考试院副院长、伪江苏省长（1940-1941）','任伪江苏省长期间，管辖扬州地区，推行伪化政策，组织“新民会”在扬州及周边进行奴化宣传，协助日军“扫荡”。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c55e0e9333494767929cd85eb0e5d8f4','3f934b1c263b4cd78c73d9700621e7bd',1943,'伪江苏省长（1943-1944）','任伪江苏省长期间，扬州属其管辖，强化清乡运动，在扬州经开区等乡村地区增设伪据点，迫害抗日群众。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5e5fa0f8a2004101b2f170ede060beb1','bacadba533394b3bb79fb5b9c5b66118',1943,'伪江苏省保安司令、伪第一方面军司令','驻防江苏（含扬州），指挥伪军配合日军对扬州周边地区进行“扫荡”，在扬州经开区一带烧杀抢掠。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0b52b7814e4c4814b05a169bb6d28042','63006a4879fb4f49ad97a1e88c8c5d69',1942,'伪第二方面军总司令（驻苏北）','率部驻防苏北，多次进犯扬州地区，在扬州郊区（含今经开区）与抗日武装作战，强征粮食，破坏抗日根据地。；在盐城西部及周边地区配合日军扫荡，破坏抗日民主政权，抓捕抗日干部。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8eba7b5459364955831b5f9799c31974','903f92a867db4e77abb94dac1ad28168',1939,'伪军第一集团军总司令、伪苏北绥靖公署主任','原国民党鲁苏战区游击纵队副总指挥，1941年2月率部投敌，在泰州、扬州一带配合日军进攻新四军，后任伪第一集团军总司令，驻防苏中地区，残害抗日军民。；原国民党鲁苏皖边区游击副总指挥，1941年投敌，在泰州组建伪军，配合日军扫荡兴化、高邮等地，残害抗日军民。；原国民党鲁苏皖边区游击副总指挥，1941年投敌，在泰州组建伪军，配合日军扫荡泰兴、黄桥等地，残害抗日军民。；原国民党鲁苏皖边区游击副总指挥，1941年投敌，在泰州地区组织伪军，配合日军扫荡抗日根据地，残害抗日军民。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bacfc4f8e3dc4ff193a11dbd76fb820f','94e92476c693405cb4077ebab12f08d8',1941,'伪军第一集团军第二军军长','李长江部属，投敌后驻防扬州、江都一带，多次参与日军“扫荡”，搜捕抗日志士，强征民夫粮饷。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('09a08a082da7492ba198b17a75aae595','f08bb6dce31f4e57be00a1766c61d396',1941,'伪军第一集团军第四军军长','原国民党地方武装头目，投敌后盘踞江都、高邮交界地区，配合日军清乡，杀害新四军交通员和群众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('236669d7febd4bb5b798f8484ed0b210','73ea8c4de57d4c8d916a762e59780c78',1941,'伪军第一集团军第五军军长','原李明扬部游击司令，投敌后驻防扬州西郊及江都部分地区，为日军提供情报，参与“治安强化”运动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4575dd6b8e3a44fbb267e2c19f415c37','a7e4d8e611f649d7b721b758c8393fd5',1939,'伪江都县知事（县长）','日军占领扬州后任伪江都县知事，推行保甲制度，强征捐税，协助日军建立伪政权，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9db568a44f2245c6a741ca4eb2b0e37c','0a4924f6632d45fa995bce0378e07a94',1941,'伪江都县知事（县长）','继任伪江都县知事，组织伪警察和自卫团，配合日军“扫荡”邵伯、樊川等地，抓捕抗日干部。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a79762fda90a4c8fb8a40982356ab4c4','45531b9eaba24b64b538ece7b006de71',1943,'伪江都县知事（县长）','末任伪江都县知事，推行“新国民运动”，强征壮丁补充伪军，协助日军掠夺粮食资源。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('08b82b9fd14746e9a9f5c13f99b0ba43','c79b91ceb24844df830039705470fa08',1940,'伪江都县保安大队长','统领伪县保安队，驻防仙女庙（今江都城区）一带，多次袭击新四军地方武装，杀害抗日家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('16a9437a31104f8094728e13c1d36291','f875bb51985b4c2d8e6e79a1a66d3173',1941,'伪苏北行营扬州办事处主任','负责协调扬州地区伪军、伪警与日军联络，参与策划“清乡”计划，向日军提供抗日武装活动情报。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('95903b2dc193444db412d7818127d6b4','b968cf1fa00147bea4c95506b5097555',1943,'伪军第二十四集团军暂编第十五师师长（驻防江都）','率部驻防江都沿江地区，配合日军封锁长江交通，袭击新四军渡江部队，强征船只。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3bf653bbcb464554840592ce1fa05948','5a14726dc0a944709762daf466d4cd08',1942,'伪苏皖边区绥靖军第二师师长（活动于扬州、江都）','原国民党军官，投敌后在扬州、江都一带收编散兵游勇，充当日军“扫荡”先锋，烧毁村庄。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('277efd6daf9942009f00f125d7015f8d','c67015f7e522482daec7c08125ae5060',1940,'伪江都县第三区（仙女庙）区长','在仙女庙地区强征“和平捐”，为日军提供粮食和劳役，告密导致多名抗日群众被捕。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f4e6f3e0534c4bd8a967a8e15a9d8929','0bee9f52da6245058c95276abdb79603',1941,'伪江都县教育科长','推行奴化教育，强制学校使用日伪教材，组织学生参加“庆祝日军胜利”活动，压制师生抗日言论。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ecaac35d09a64466962b2fdacfa9cd57','b2f7efcb3ed940c5b43449f3e45a0ad3',1942,'伪江都县水上警察队长','控制邵伯湖及运河航道，盘查商旅，为日军运输队护航，截获新四军物资，勒索船民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7a5ddb4a8fd84f629399ec5431db1547','dc2c7930d2b4490aafb9ba6c509ff1e3',1937,'伪江都县（含邗江）维持会会长、伪县知事','扬州沦陷后率先投敌，组织维持会，为日军征粮派夫，协助建立伪政权，镇压抗日活动，后任伪江都县知事，管辖邗江一带。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c90ed21b76254f3493f7269cfd3c8e76','807ca12d2dcb44989aababb17d52ca6d',1938,'伪江都县保安大队长、伪扬州城区警备司令','原地方土匪头目，投日后任伪保安大队长，在邗江、扬州近郊设卡勒索，捕杀抗日游击队家属，多次配合日军“清乡”。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('919fc20744224266bd3ef4bdc16b41fc','94e92476c693405cb4077ebab12f08d8',1939,'伪扬州水上警察局局长','控制邵伯湖至扬州运河段（含邗江水网），为日军运输物资护航，搜捕水上抗日交通员，敲诈船民，罪行累累。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('df41ceef8ed64b2d9fcd3a2e11fbf4ef','40ceda4a3fba43bb8c30faefaa993de4',1943,'伪苏北绥靖公署高级顾问（曾驻扬州）','原国民党将领，1943年投敌后一度在扬州参与伪军整编，协助日军对邗江地区进行“扫荡”，后调任山东。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ec5cd32d14184787b424ba9e1d1f80a4','63006a4879fb4f49ad97a1e88c8c5d69',1942,'伪第二方面军总司令（驻苏北，活动范围含扬州）','原国民党第三十九集团军副总司令，1942年投敌，所部驻防苏北，在邗江、仪征等地配合日军进攻新四军，强征壮丁。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ba48d1fd15244d1685d50baed24bb8fc','f875bb51985b4c2d8e6e79a1a66d3173',1940,'伪江都县警察局长','在邗江各乡镇设立伪警察分驻所，专门侦缉抗日地下组织，逮捕进步青年，刑讯逼供，致多人死亡。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f926dd23133d441e90ce6fc75150abae','a2e4190c87b449e685d78c118a6801b5',1940,'伪国民政府财政部部长兼伪苏北行营主任（名义管辖扬州）','虽常驻南京，但作为汪伪政权核心，其推行的“清乡”政策在邗江地区造成大量民众被屠杀，并直接指挥伪军参与对扬州周边抗日根据地的封锁。','省部级/大军区级要员','hanjian');
