INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('06290b82a3a2478f9595ef8f876a6bb1','cebb4769b324411abb6e1f5a0f26ecf6',1940,'伪第一方面军总司令、伪江苏省保安司令','率伪军在苏州、无锡等地配合日军“扫荡”，围剿新四军和游击队，强征民夫，掠夺地方资源。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d4b15fa659da4b05869de4179a987e64','4c0724ba86184ad9aea99954ed4e044b',1941,'伪苏州地区清乡督察专员','直接负责苏州地区的“清乡”行动，建立伪保甲组织，搜捕抗日分子，推行“连坐”制度，造成大量平民伤亡。；负责苏州地区“清乡”工作，设立封锁线，搜捕抗日分子，残害百姓。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('01f829ae293b4697bc185cab60bbd6e8','1c17d96bb774472c9abc1aec7dc87e4f',1938,'伪吴县（苏州）知事','在苏州城区任伪知事期间，为日军征粮、征税，强征劳工，协助日军维持治安，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b08b793ac4a9409b9f96d99eab8b7a70','bf21679c8d844a97a972ecd6cc737733',1938,'伪苏州商会会长','充当日伪经济工具，组织商会为日军筹措军费，控制苏州粮食与棉纱贸易，从中牟利，间接支持侵略战争。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7522788f9132456f9c55d50adb4857fb','3d2200381fdd4186aa372c02646d3fec',1940,'伪苏州警察局局长','指挥伪警察协助日军搜捕抗日人士，破坏地下组织，参与“清乡”行动，镇压民众反抗。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5c85302494f549e8af73bd703c192607','f50cf011f8f842fc8d69caa402ffbf67',1938,'伪江苏省政府主席、伪内政部部长','曾任伪维新政府内政部长，后任伪江苏省政府主席，在苏州、吴中地区推行日伪统治，镇压抗日活动。；曾任伪维新政府内政部长，后任伪江苏省主席，在苏州地区推行日伪统治，镇压抗日活动。；浙江温州人，汪伪政权重要成员，曾任伪江苏省政府主席、伪内政部部长，参与日伪统治。','省部级/大军区级要员','hanjian');
