INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7f77df18a59f43b08fe6d04797b144fa','3f934b1c263b4cd78c73d9700621e7bd',1940,'伪江苏省政府主席（代理）','曾任伪江苏省政府代理主席，在苏州地区协助日军推行“清乡”运动，搜捕抗日力量。；代理伪江苏省主席，在任期间配合日军“清乡”运动，在苏州、常熟等地推行保甲制度。；曾任伪江苏省代理主席，在苏州等地推行伪化政策，配合日军“清乡”运动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1887f110cb0a49af8a8c29737bfa61e6','cebb4769b324411abb6e1f5a0f26ecf6',1940,'伪江苏省政府主席、伪第一方面军总司令','伪江苏省政府主席兼伪军将领，在苏州、吴中地区驻有伪军，配合日军扫荡抗日根据地。；投靠汪伪政权，任伪江苏省政府主席兼保安司令，在苏州、无锡等地协助日军清乡，搜捕抗日志士。；曾任伪江苏省主席兼保安司令，在苏州地区协助日军清乡，镇压抗日力量。','省部级/大军区级要员','hanjian');
