INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5d23aa69bf8e4e788e87af5cc3ad7ca4','e595823962b846eb97e7f27f2151869d',1941,'伪江苏省教育厅长','在镇江推行奴化教育，解散爱国学校，迫害进步教师，强制学生参加日伪庆典。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8296f9adf3af41219f943cd846ea740a','8f1dd12e548b4c4f866dd743c3377896',1937,'伪华北政务委员会委员长、汪伪政府考试院院长','安徽合肥人，北洋政客，抗战期间投敌，任伪华北政务委员会委员长等职，推行奴化教育、配合日军掠夺华北资源，虽非上饶籍，但其伪政权体系曾延伸影响江西部分沦陷区。；安徽合肥人，北洋政客，抗战期间投靠日本，任伪华北政务委员会委员长等职，参与伪政权统治，虽非江西籍，但其伪政权体系覆盖包括江西在内的沦陷区相关事务。；江西籍汉奸代表人物之一，原籍安徽但长期在江西活动，抗战期间投靠日军，历任伪华北政务委员会委员长等职，推行奴化教育，协助日军掠夺资源。；江西九江人，北洋政客，抗战期间投靠日本，任伪华北政务委员会委员长等职，推行奴化教育、配合日军掠夺华北资源，虽主要活动于华北，但作为江西籍汉奸代表人物被记录。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5489acb868614993a589feed2f51b4ad','62a6d6c8e7ab4bbfbc92c5b14abbde74',1938,'伪国民政府立法院长、伪上海市长','广东乳源人，汪伪政权核心人物之一，曾任伪立法院长、伪上海市长等职，参与汪伪政权对江西等沦陷区的统治与掠夺。；汪伪政权核心人物，参与伪化江西等沦陷区统治，配合日军在九江地区的经济掠夺与治安强化。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4c100ec032684b2e846e7d2360c2bee0','96b96eb8f5414a1f874f70f38feb0054',1938,'伪上海特别市市长、伪江西省长','广东人，曾任伪上海特别市市长，后调任伪江西省长，直接参与江西沦陷区的伪政权统治与资源掠夺。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('db8dbcf447364767b6266031849d399d','3f934b1c263b4cd78c73d9700621e7bd',1938,'伪江西省长、伪安徽省长','江苏人，汪伪政权地方大员，曾任伪江西省长，在江西沦陷区推行奴化教育、征粮征丁，配合日军“清乡”。；江苏崇明人，投敌后曾任伪江西省长，直接负责江西沦陷区伪政权事务，推行日军殖民统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('65a916f8d5df42a28ffff2118a4b418d','ae03221e7bea40148f2df1d4d6e487b2',1939,'伪江西省政府委员、伪南昌市长','江西人，汪伪政权在江西的地方官员，曾任伪南昌市长，协助日军维持南昌及周边占领区秩序。；在江西日占区参与伪政权，推行日军殖民统治政策。；江西人，投敌后任伪江西省及南昌市要职，协助日军统治江西沦陷区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c46b4f184f564666aa23260b4f7fdf38','13b409fcff2449c3bd42692da36e6178',1940,'伪税警总团副总团长、伪军师长','浙江人，原军统人员后投敌，任汪伪税警总团要职，其伪军部队曾活动于江西及周边地区，配合日军作战。；浙江昌化人，原国民党军官，后投敌任伪军要职，在华中地区包括江西周边进行伪军活动。；汪伪伪军头目，其部队在湖北地区配合日军作战，参与清乡扫荡。；湖北人，抗战期间投敌，在湖北、江苏等地率伪军配合日军作战，参与对湖北抗日根据地的扫荡。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6ebfe05f7c824b49b77aa7079634e4fd','86e982eb4f0043c4b6f7b586ec525f98',1940,'伪军师长、伪江西保安司令','广东人，汪伪政权军事将领，曾任伪江西保安司令，率伪军配合日军在江西沦陷区“扫荡”抗日武装。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('40ef9e778b3f4995b5890398c26e8367','455643dcc8d948048c745963ebd68c1c',1941,'伪军师长、伪江西省保安副司令','江西人，汪伪政权军事人员，曾任伪江西省保安副司令，协助日军在江西沦陷区维持治安、镇压抗日活动。','市县厅局级','hanjian');
