INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a974c4a3634448eda081bee03ed59f06','3a26c48b18974cbeb1d7b7e29e8f29c2',1941,'伪江西省警务处长','江西人，汪伪政权在江西的警务头目，掌管伪警察力量，参与搜捕抗日人员、推行保甲连坐。','基层头目','hanjian');
