INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f52bc3e4e530488e9bac43b60280b31e','ebdd9ee39e19463c8d27a1cd5cabd4a2',1942,'伪上饶县维持会长','江西上饶人，日军侵占上饶期间组织伪维持会，任会长，为日军征粮征夫、维持占领区秩序，协助日军统治上饶地区。','基层维持会/地方自治头目','hanjian');
