INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4fa32cad37ae44f784c81ad8753e1323','bacadba533394b3bb79fb5b9c5b66118',1943,'伪浙江省长、伪军长','浙江杭州人，汪伪政权浙江省长兼伪军长，参与镇压抗日武装。；浙江杭州人，投敌后任伪浙江省长等职，其伪政权与江西邻近，对江西沦陷区伪政权有影响。；浙江杭州人，抗战期间任伪浙江省长及伪军长，配合日军清乡，1946年以汉奸罪被处决。','省部级/大军区级要员','hanjian');
