INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ff3dc2cc65a74463854159b9ce075c09','27e5483f777b4a8f891133642d830442',1939,'伪九江妇女会负责人','在九江参与伪民众团体活动，协助日军宣传“大东亚共荣”，组织慰劳日军及附逆社会活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('43d7cc3f7d644a7a9f38c88d049b5f8e','ba4d26d2594549b2be6f8a4cc0d09758',1931,'未任伪职，但相关附逆传闻需辨伪','熊式辉为江西籍国民党官员，非汉奸；此处仅说明江西范围内有明确记载的汉奸较少，需避免误列。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('66eba666efd7406f9cd8f18e54c4765a','a1442e252a78480888f49fee68c84d90',1939,'伪江西省政府委员、伪南昌市长','在江西沦陷区参与伪政权，任伪南昌市长等职，协助日军维持南昌及周边地区统治，影响波及九江一带。；江西人，抗战期间投敌，在伪江西省政府任职，参与伪南昌市政权，协助日军维持江西沦陷区统治，与赣州地区同属江西省。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3fb7a5d0ea074e45a964f927cefe351f','915bcf11429e46bc80172aede7ac2e64',1943,'伪江西省保安司令','在江西伪政权中任军事头目，统率伪保安队配合日军进攻抗日根据地，镇压民众抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('54d74b31c6124d7aa03851dfa4e46a15','455643dcc8d948048c745963ebd68c1c',1938,'伪九江地区保安队头目','在九江及周边地区组织伪保安队，配合日军扫荡、清乡，搜捕抗日军民，勒索地方。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('97201f0db270440b87292afe8b631e49','b6ae69ffcd5e454a99182f7d989b8ad0',1937,'伪文化汉奸、日伪刊物编辑','江西籍文人，抗战期间附逆，参与日伪文化宣传，发表亲日文字，为日军侵略辩护。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('119966bab6594addb15dd9e9f2b59a25','07ff958e7f18410f864975f09234ac7e',1939,'汪伪特工总部头目','汪伪76号特工头目，其特务网络延伸至江西沦陷区，在九江等地搜捕抗日人员，镇压地下抵抗。；其特工网络延伸至浙江衢州等地，收买地方人员、破坏抗日组织。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a938d4cea1a042958222179dd3ef0713','9910c48b9b394ffa8c73439ed0a473b0',1937,'汪伪特工总部主任','汪伪特务头目，参与在江西沦陷区建立特务组织，迫害抗日志士，协助日军维持恐怖统治。；主持汪伪特工总部，在浙江包括衢州地区发展汉奸组织，破坏抗日力量。；汪伪特务头子，在重庆周边有情报网络，战后被处决。','特工总部主任','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cc29160d668a4f0c9366388f8702442d','62a6d6c8e7ab4bbfbc92c5b14abbde74',1939,'汪伪立法院长、伪国民政府代主席','汪伪政权主要头目之一，参与制定沦陷区统治政策，江西伪政权亦受其节制。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ca5dce578cf54e27a8e49a7f8c0f28fd','f62754ef8d4a41f58e3b8f1b4bd4ab3a',1940,'汪伪考试院长、伪社会运动指导委员会主任','文化汉奸，参与汪伪政权，鼓吹“和平建国”，在江西等沦陷区进行亲日宣传。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('120ba5db7e5245fe9b97f40d198177c3','3acc7f5b9d1c45359d912b1fc0e2c626',1937,'伪新民会副会长、汪伪立法院副院长','参与日伪民众团体与伪政权，在华中包括江西沦陷区推行新民会活动，协助日军控制基层。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6b84369b544b4c829acac4f648bd13e0','f16a0c2922c341969e2e7100e4837824',1938,'伪九江县政府筹备处主任、伪九江县长','日军侵占九江后出面组织伪政权，任伪九江县政府筹备处主任，后任伪九江县长，协助日军维持占领区统治、征发物资与劳工。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1bc9a289c72d4e709aa291dde4149236','f1614e7f18ba4936a10109b14e9942c0',1938,'伪九江维持会会长','九江沦陷后参与组织伪维持会，任会长，为日军筹粮筹款、安抚民众并协助建立伪基层保甲体系。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c008dc7eb35847ce96636b03e52acdc9','0ce82afb041f4eb4a6fb886726d0274f',1938,'伪湖口县维持会会长、伪湖口县长','湖口沦陷后投敌，组织伪维持会并任会长，后任伪湖口县长，配合日军清乡、征粮和修筑据点。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dc83d154ef394bcdb9ace3ba7048219b','a7ed5fc763a54756bd71f2537f405769',1939,'伪湖口县保安大队大队长','任伪湖口县保安大队长，率伪军配合日军对湖口、彭泽一带抗日武装进行扫荡，抓捕抗日人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a00ab857454e45f6af5e33117d28317a','5056571b1b364bc0853dbe0b44b57fae',1939,'伪九江警察局督察长','在伪九江警察系统任职，参与搜捕抗日志士、管制居民出行并协助日军实施物资统制。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d77d9bdc376c42f0ac4a3228f7252e81','baa3bd812ff64a56ae7c19ade04febdc',1940,'伪江西省警务处秘书、伪九江警察局长','在伪江西省警务系统任职，后任伪九江警察局长，负责城区治安与情报搜集，配合日军镇压抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('924e68bb5c7d41bc96ff70854c2c5271','a1442e252a78480888f49fee68c84d90',1940,'伪江西省政府委员、伪建设厅长','在伪江西省政府任职，参与推行日军经济掠夺政策，为九江及湖口一带的物资征发、交通管制提供行政支持。；江西人，投敌后任伪江西省建设厅长，协助日军进行经济掠夺。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a01c702765ff40ff8db8f423acb42f94','3a26c48b18974cbeb1d7b7e29e8f29c2',1941,'伪江西省政府警务处长','任伪江西省警务处长，统管包括九江、湖口在内的伪警察力量，参与清乡与抗日人员搜捕。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7dd767c0907c4b8eb473b957fccc4577','a156783f10f84cb59e101d85866263e4',1938,'伪九江商会会长','九江沦陷后出面组织伪商会，为日军摊派款项、物资，协助控制粮食与日用品流通。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('13077705909549148d1bea4a2be94658','19d93b46325f4980a7abef6dca24ce2f',1940,'伪湖口县教育科长','在伪湖口县教育系统任职，推行奴化教育，篡改教材并组织师生参加亲日宣传活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0a437e7026ab485ca7795bac8b404f64','415feb04354a42af831c2e3ce76c70c5',1939,'伪九江县政府财政科长','负责伪九江县政府财政，为日军征收田赋、摊派捐税，并管理掠夺物资的账目。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('529a4c6510f042d89c09e26f846bf8c3','46e21dc8b20f43baa3ec542c1c8ebbd2',1941,'伪湖口县保安队中队长','率伪保安队在湖口沿江地区配合日军巡逻、封锁，参与抓捕抗日交通员和破坏抗日联络点。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d3f45dbdb4b444d7a7e38df9f15037ad','4a8d0bc8bfcb4f9ebff633f16f626fc3',1938,'未就任的伪全国性政权首领人选（日方诱降对象）','抗日战争时期，日本侵略者曾试图拉拢吴佩孚出面组织伪政权，吴佩孚虽未公开附逆，但日方在九江、武汉等地对其反复诱降，其态度暧昧，客观上被日伪利用来影响江西、九江一带的所谓‘和平’舆论。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ea3b6e020657413d91d96c341b56e329','993e4eff978c4539b275a1e53335a341',1937,'伪浙江省政府主席（未就任前即与日伪勾结）','上海青帮头目，抗战期间投靠日本，组织伪‘新亚和平促进会’，为日军在华中、江西等地采购物资、诱降国民党军政人员，其势力范围涉及九江一带的长江航运与情报活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0055a4145b8a4db59453dac32349e285','3acc7f5b9d1c45359d912b1fc0e2c626',1940,'伪立法院副院长、伪考试院长','汪伪政权要员，参与伪化江西等地的行政与教育体系，推行亲日奴化政策。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('19294e646266487babc27ac69447865b','845de899b20e4631bbf68676aa47dec8',1940,'伪广东省长、伪建设部长','汪伪政权要员，其伪建设系统涉及江西九江沦陷区的资源掠夺与交通控制。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0aa3d7384c654ca9919d0ab40511ce33','bb34b45b44c34a018d410cde66579fb1',1939,'伪武汉绥靖公署主任、伪湖北省长','汪伪军事头目，其伪绥靖体系覆盖江西九江邻近地区，配合日军对赣北抗日根据地的扫荡。；伪湖北省军政头目，指挥伪军配合日军在荆州等地区扫荡，镇压抗日力量。；统率伪军配合日军在鄂北随县一带“清乡”，收编土匪武装，镇压抗日力量。；湖北黄陂人，投敌后任伪湖北省长，控制武汉及鄂南，与湖南岳阳、汨罗邻近，其伪政权势力延伸至湘北。；湖北黄陂人，活动于湘鄂赣交界地区，配合日军对湖南北部进行扫荡与伪化统治。；原国民党将领，抗战期间投敌，任伪武汉绥靖公署主任、伪湖北省长等职，率伪军配合日军进攻抗日根据地。；在华中伪政权中任职，组织伪军配合日军，其活动对全国抗日包括陕西后方有影响。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d97c88d47ae24ae497fcdd03ee6d1e4c','915bcf11429e46bc80172aede7ac2e64',1940,'伪军事参议院院长、伪陆军部长','汪伪军事要员，参与指挥伪军在江西九江一带的治安作战与物资征发。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('05996ed2dab94cf391e9c9caef13d213','fefd7f9ddbac40469c751144d6cbd784',1940,'伪军委会委员、伪驻华北军司令','汪伪军事头目，其伪军活动涉及华中包括江西九江地区的‘清乡’与封锁。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e8afefcb3bc248e384ab705d367ee07b','bacadba533394b3bb79fb5b9c5b66118',1940,'伪浙江省长、伪军委会委员','汪伪军政要员，参与伪化江西邻近的浙赣沿线，配合日军在九江地区的军事行动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('97a490d81e99460087bb20d2d599cab4','506df7877e6b4b589f0df223e5da77c6',1940,'伪湖北省长、伪军委会委员','汪伪湖北省长，其伪政权与江西九江沦陷区有行政与军事联系，参与‘清乡’与物资统制。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('14a4048460c74414bfaa933c9675a32b','ad65aa69fa0c4f84aa598321e8c96ad1',1937,'伪华北政务委员会委员长','华北伪政权要员，参与伪化统治，其体系与江西九江沦陷区的伪维持会有间接联系。；华北伪政权头目，负责华北沦陷区包括河南商丘、民权一带的伪政事务，协助日军征发物资、镇压抗日。；华北伪政权后期首脑，其伪化政策覆盖华北，与陕西渭南地区有间接关联。；北洋旧官僚，投敌后任伪华北政务委员会委员长，继续推行日军政策。；继王揖唐后任伪华北政务委员会委员长，继续推行华北沦陷区包括陕西的伪化统治。；在华北伪政权中任要职，配合日军推行殖民统治，其伪政权体系对陕西周边有影响。；投靠日本，参与伪华北政权，配合日军在华北包括陕西周边地区进行殖民统治。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3203b1da641f4e8e8c08601804fa6327','e1badd3fe14246acb4a3d2bf765b2db2',1937,'伪华北政务委员会常委','华北伪政权要员，参与经济掠夺，其伪化政策影响华中包括江西九江的物资统制。；山西人，抗战期间投靠日军，任伪华北政务委员会常委，在华北地区推行伪化统治。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8d5f2be4e6fe42f99b890f82e935751a','bbc7d2d2f1174918a3a12cc3ce766af2',1937,'伪北平市长、伪华北政务委员会委员','华北伪政权要员，其伪化活动与江西九江沦陷区的伪政权有间接联系。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('714172a2a3914b08a14030959d86d208','10b88f41fdee46778f29f60ae3d41741',1937,'伪天津市长','华北伪政权要员，参与伪化统治，其体系与江西九江沦陷区的伪政权有间接联系。；河北盐山人，抗战期间投靠日军，任伪天津市长，在华北地区推行伪化统治。；在华北伪政权中任职，参与日军统治下的天津及华北事务，对华北抗日力量进行镇压。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cd363e56b8d649449720fa2a8e328bd1','4cc5391bc78947fa9bf1a4b59e0f5371',1938,'伪武汉市长、伪天津市长','伪维新政府及汪伪政权要员，曾任伪武汉市长，其伪政权与江西九江沦陷区有行政联系。；张之洞之子，投敌后任伪武汉市长，其伪政权与湘北沦陷区有行政联系。；在武汉、天津任伪职，协助日军管理城市，战后以汉奸罪被处决。','核心城市市长/省部级','hanjian');
