INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1672c3c08018442e91aa8827020340b3','ba4d26d2594549b2be6f8a4cc0d09758',1944,'伪江西省政府顾问（传闻任职）','有资料称其在江西沦陷后与日伪有接触，但主要历史记载仍以其战前主赣及后方任职为主，附逆情节存疑，仅列备考。','无明确职位或一般帮凶','hanjian');
