INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0fa6379a21f342dfa55a9bd62469da1d','41f22c2e74ff49b29b8d3a4cc094162c',1941,'伪安福县警察所所长','任伪安福县警察所所长，带领伪警察配合日军搜查抗日分子，勒索民众，维持伪政权在安福的基层统治。','无明确职位或一般帮凶','hanjian');
