INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1347ec31eb6d411f95c74994ac1f9cd2','01e75c0937a04eabbd68975a5e901763',1940,'伪江西省宣传处职员','在伪江西省宣传机构任职，参与日伪奴化宣传，活动涉及吉安地区教育文化领域。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('589224f7c28647f5882ac23cbb9d4478','3adf197024f14b7396923920852eda38',1941,'伪吉安地区合作社理事长','控制吉安地区物资配给，为日军掠夺粮食和战略物资，协助经济统制。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('31f4119b25b1452eaa8720f57e965c64','759cfb5f46624562bc0d114d5292cbca',1940,'伪峡江县保安队队长','率领伪保安队在峡江及周边配合日军扫荡，袭击抗日游击队。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d5ccd265953b49eeab943ecb5dedfc3d','62a6d6c8e7ab4bbfbc92c5b14abbde74',1938,'汪伪政府立法院长、行政院长、代理主席','广东乳源人，随汪精卫投敌，任汪伪政府要职，其伪政权统治区域包括江西沦陷区，对江西伪政权有统辖关系。；虽为广东人，但作为汪伪政权核心，其伪政权统治体系覆盖湖南沦陷区，间接影响株洲芦淞一带的伪政权运作。；虽为广东人，但作为汪伪政权主要头目，其伪政权统治覆盖包括湖南在内的华中沦陷区，对湖南伪政权有统辖关系。；湖南籍？实为广东乳源人，但长期在汪伪政权任要职，其伪政权体系对湖南沦陷区有管辖影响。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3527e08c08224d95af1595d56540ce20','a2e4190c87b449e685d78c118a6801b5',1938,'汪伪政府财政部长、警政部长、上海市长','湖南沅陵人，汪伪政权核心人物，掌管财政与警政，其伪政权体系延伸至江西沦陷区，对当地伪军伪警有控制关系。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b8aef78e21a5445aa3118bd44eb91f80','a06c0041e5294f2987f746729e510de9',1943,'伪淮海省省长、伪保安司令','河南阌乡人，原国民党军将领，投敌后任伪淮海省要职，其伪政权与江西沦陷区伪政权同属汪伪体系。；河南阌乡人，抗战期间投敌，在苏北、豫东一带组建伪军，配合日军进攻抗日根据地，对河南包括南阳地区造成威胁。；原国民党将领，1943年投敌，任伪淮海省省长，管辖苏北、皖北、豫东部分地区，配合日军扫荡抗日根据地，其势力范围与南阳地区有间接关联。；河南阌乡人，原国民党军将领，1943年投敌，任伪淮海省要职，在苏北、豫东一带配合日军维持伪统治，镇压抗日力量。；抗战末期投敌，任伪淮海省省长兼保安司令，其伪政权与河南东部相邻，曾配合日军在豫东地区行动，间接影响郑州周边。；抗战后期投敌，任伪淮海省省长，其伪政权与河南伪政权有联系，所部伪军活动范围一度接近豫南驻马店地区。；原国民党将领，1943年投敌，任伪淮海省省长，其伪政权与河南东部相邻，对豫南驻马店地区有间接影响。；河南人，投敌后任伪淮海省要职，活动于苏北、皖北，与湖南无直接关联。；在江苏、安徽、河南、湖南交界地区组织伪军，配合日军进攻湖南，参与伪政权统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8f359e507e044982a85a2229233e12fd','d823baec96e04682bca33413f02ae20d',1940,'伪浙江省长、伪建设部长','浙江乐清人，投敌后任伪浙江省长等职，其伪政权与江西接壤，对江西沦陷区有辐射影响。；浙江乐清人，曾任伪浙江省长，在杭州期间协助日军掠夺资源，强征劳工，破坏抗日组织。','省部级/大军区级要员','hanjian');
