INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('69dc7a8d0119485cb946a58828de8b81','0e60373d82794847b0a91604e34f29c2',1939,'伪江西省政府警务处处长','在伪江西省政府中负责警务，协助日军维持沦陷区治安，镇压抗日活动。；在伪江西省政权中负责警务，协助日军在赣中、赣南地区搜捕抗日人士，镇压民众反抗，推行保甲连坐制度。','基层头目','hanjian');
