INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dfc2587af7334eb990ed48690a548577','4bf16c613ce64001bbcf1d60e3cc9f97',1939,'伪南昌县维持会会长','在南昌地区组织伪维持会，协助日军控制赣中交通，迫害抗日人员。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8c7100c215e24d9ea2f7784573714d2e','13b409fcff2449c3bd42692da36e6178',1943,'伪江西省保安司令部副司令','投靠日军后任伪江西省保安部队头目，在赣中、赣西包括宜春地区配合日军行动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('faa2ae29016941b38a789a02a0227c88','915bcf11429e46bc80172aede7ac2e64',1943,'伪江西省省长','汪伪政权江西省最高头目，在江西沦陷区推行伪化统治，宜春地区亦受其管辖。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4981f76de4fb493288cae18fe6437ae8','3f934b1c263b4cd78c73d9700621e7bd',1940,'伪江西省省长（前任）','汪伪江西省省长，在江西占领区建立伪政权体系，宜春周边伪组织多受其节制。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dea4c6a8d8234403bc26a83270305dfb','86e982eb4f0043c4b6f7b586ec525f98',1940,'伪江西省保安司令部司令','统率伪江西保安部队，配合日军在赣西地区清乡，宜春、萍乡一带伪军受其指挥。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('886cb2725b2b47f4927c7a3ff1839f41','ba4d26d2594549b2be6f8a4cc0d09758',1931,'江西省政府主席（后附逆投靠汪伪政权）','抗战期间在江西主政，后期与汪伪政权有联系，其部下在宜春、万载一带推行妥协政策，被指为附逆行为。；原国民党江西省主席，抗战后期与日伪方面有联系，其部分旧部在江西沦陷区参与维持会活动，对宜春、上高一带的伪政权建立有间接影响。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7af67cde7edd437f9308ebb46bc98e50','8f1dd12e548b4c4f866dd743c3377896',1937,'汪伪政府内政部部长、伪安徽省省长','在江西周边地区协助日军推行伪化统治，其伪政权势力曾渗透至宜春、万载一带，组织维持会与伪军。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5a07551f1ea8427aba7233bd1b040016','07ff958e7f18410f864975f09234ac7e',1939,'汪伪特工总部主任、伪江苏省省长','其特工网络在江西宜春、万载等地活动，收买地方保甲长，建立伪情报网，镇压抗日力量。；浙江遂昌人，抗战期间投靠汪精卫，组建伪特工总部（76号），任主任，后任伪江苏省省长，大肆捕杀抗日志士，在江苏、上海等地活动，其特务网络延伸至华中包括湖南部分地区。与湖南有间接关联。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a6a7ff9c0fe54263aea2b4d5b6f29aeb','62a6d6c8e7ab4bbfbc92c5b14abbde74',1940,'汪伪政府立法院院长、伪上海市市长','其伪政权体系在江西设有分支机构，宜春、万载地区部分维持会受其指挥，推行奴化教育。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('78b6984cd76746fb9c64da7b4111c399','a2e4190c87b449e685d78c118a6801b5',1938,'汪伪政府财政部长、伪警政部长','通过伪政权在江西宜春、万载等地征收赋税，支持日军物资供应，并组织伪警察维持地方治安。；汪伪政权要员，其财政与警政体系延伸至江西，赣州地区伪警察系统受其节制，协助日军维持占领区秩序。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('73cc6ccbe12144fabb39c076a08fdd7c','b6ae69ffcd5e454a99182f7d989b8ad0',1938,'伪江西省维持会会长（文化附逆者）','在江西宜春、万载一带宣传“中日亲善”，为日军提供文化渗透服务，组织伪教育机构。','基层维持会/地方自治头目','hanjian');
