INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('90a389e48ec04bec8dbef221156f996e','ae03221e7bea40148f2df1d4d6e487b2',1939,'伪江西省政府委员、伪南昌市市长','在南昌沦陷区担任伪职，参与伪江西省政权的运作，为日军在江西的统治提供行政支持，推行日伪政策。；汪伪政权在江西的主要代理人之一，参与组织伪南昌市政府，协助日军维持占领区秩序、征发劳役与物资。','市县厅局级','hanjian');
