INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('611421baae614aa7bafef3028ef1927f','07ff958e7f18410f864975f09234ac7e',1938,'伪国民政府特工总部主任、伪江苏省长','浙江遂昌人，抗战期间投敌，组建伪特工总部（76号），残酷镇压抗日力量，其特务网络覆盖包括江西在内的华中地区。','省部级/大军区级要员','hanjian');
