INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0e2d0fcd0926483d874dcb7ec70e3f21','4a5e7e3e858a4e8997921f6911db7566',1944,'伪赣州维持会长','江西赣州人，1944年日军侵占赣州期间，出面组织伪赣州维持会，任会长，协助日军征粮、拉夫、维持治安，是赣州本地直接附逆者。','基层维持会/地方自治头目','hanjian');
