INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dfd618c0d3d440ddb8f93b799dcd2bb4','936938a09530470594869ddd2dc52df0',1930,'遂川县靖卫团团长、国民党遂川县党部书记长、赣西南反共顽固派头目','长期在赣西南遂川、井冈山、于都周边地区组织地主武装，镇压红军和革命群众；抗日战争时期破坏抗日民族统一战线，迫害抗日进步人士，袭击中共地方组织，是赣西南地区著名的反共顽固势力代表。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a4d2c6ac59134cd6b7b9ba495a2cb5dc','0517ad3a6eb14019b790e91550fd27b2',1930,'国民党江西省党部执行委员、赣南地区反共骨干','在赣南地区参与组织反共武装和地方政权，压制抗日民主运动，迫害进步青年和中共地下党员，与地方豪绅勾结控制赣州一带基层政权。','无明确职位或一般帮凶','hanjian');
