INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4b3b6f8b584747b8ab842f827d208233','936938a09530470594869ddd2dc52df0',1930,'遂川县靖卫团总、遂川县政府县长、赣西绥靖公署指挥官','长期在赣西南遂川、上犹、崇义一带组织靖卫团和保安团队，配合国民党军清剿红军游击队；抗日战争时期继续把持地方武装，横征暴敛、迫害抗日进步人士和群众，是赣南地区有明确记载的反动地方武装头目。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6fc2edc3d9704f6faa603a783432d5b2','b8f1bd6290db47b8a6a8cb2cdb305bd8',1930,'宁都县保安团团长、江西省保安旅旅长、赣南绥靖区指挥官','在赣南宁都、瑞金、石城一带长期掌握地方保安武装，抗日战争时期借抗日名义扩充势力，镇压群众抗日活动，迫害中共地下组织和游击队员，是赣南地区有明确记载的保安团队头目。','基层头目','hanjian');
