INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f88919f0d0e04d34ac32acee546fa000','c69ebaf9aa5b46f18ba82fa492c71343',1939,'赣县伪维持会会长','抗日战争时期在赣县组织伪维持会，为日军征派粮食、民夫，协助日伪维持地方秩序，压迫当地民众。','基层维持会/地方自治头目','hanjian');
