INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4bc6b370dcc8481e9d4cce74fbc58939','936938a09530470594869ddd2dc52df0',1931,'遂川县靖卫团总、赣西绥靖公署反共自卫军第一路司令、遂川县县长','长期在赣西南遂川、井冈山一带组织靖卫团和反共武装，配合国民党军及日军清剿抗日根据地，屠杀民众与游击队员；抗战时期在赣州周边地区维持日伪统治秩序，1949年后继续组织土匪武装抵抗解放军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ab725b6f8d674318b80056cf0a3a3039','b8f1bd6290db47b8a6a8cb2cdb305bd8',1934,'国民党江西省第五区行政督察专员兼保安司令、赣南反共自卫军司令','在赣州地区长期把持地方军政，抗战期间消极抗日、积极反共，与日伪势力暗中勾结，镇压赣南抗日救亡运动，迫害进步人士。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2f34d5ecd08b4d03844452c53ece7217','c69ebaf9aa5b46f18ba82fa492c71343',1939,'伪赣县维持会会长','日军侵占赣州期间出面组织伪赣县维持会，为日军征粮派款、搜集情报、维持占领区秩序，协助日军镇压抗日群众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1f170fda16c74c47aeb60eb929726c5f','7a21c00308b049e4af8afb0a3699a6c2',1944,'伪赣州地区维持会副会长','日军侵入赣州期间，协助伪赣县维持会组织伪政权，为日军筹集物资、招募劳工，参与对赣州城区居民的管控。','基层维持会/地方自治头目','hanjian');
