INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4387880ad4a34677a745284ca2888816','aea3838771d8458ba6073d341943bb27',1939,'伪华北治安军第1集团军司令','率伪军驻扎保定，多次参与日军对冀中根据地的扫荡，残害抗日军民。；原为国民党军军官，投敌后任伪华北治安军第1集团军司令，驻防保定一带，多次率部“扫荡”冀中抗日根据地，杀害抗日干部和群众。；原国民党冀察战区将领，投日后任伪华北治安军高级军官，在冀中地区（含廊坊、大城一带）参与“扫荡”，屠杀抗日军民。；率伪军驻防冀中，多次参与对肃宁、献县、饶阳等地的“清剿”，屠杀抗日干部和群众，烧毁村庄。','基层头目','hanjian');
