INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bd0a99b9d9c44e8cb5556ba29ba3209c','d2b840cc6fa142c8b5c30c100a11b64d',1938,'伪河北省保安司令','在保定一带组织伪保安队，协助日军抓捕抗日志士，破坏地下组织。；指挥伪保安队在廊坊、大厂地区围剿抗日游击队，烧毁村庄。','市县厅局级','hanjian');
