INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d53e9aa7342d415988ab872171d339c6','8ab29f89ba2147a1b5c2d7258899eab0',1941,'伪河北省警备处副处长兼保定地区清乡督察','在保定及白沟新城推行“保甲连坐”制度，组织汉奸特务队，多次突袭抗日村庄，逮捕并杀害抗日干部及家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('248c8af64a16471dac9f34f42366b58b','b1303da80b994629ba3bf2748d8842c1',1942,'伪华北政务委员会保定办事处主任','原国民党河北省民政厅长，投日后负责保定地区伪政权行政事务，协助日军强征粮食、劳工，在白沟新城一带破坏抗日地道。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4a2f0a0ee7af4b308af9504f622793f3','4d73b990808044b7a3bbaed656b086ea',1938,'伪白沟河维持会会长','白沟新城本地恶霸，投日后任维持会长，为日军提供抗日情报，勒索商户，多次带日军搜查白沟河两岸村庄，致使数十名群众遇害。','基层维持会/地方自治头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c0fd8f42da064482a36786574fa9eb7b','6fee2b329ee54681a24b19e7abf091b7',1940,'伪保定宪兵队特高课翻译兼密探队长','原为保定商人，投日后充当日军翻译，组建密探网，在白沟新城、容城、雄县等地诱捕抗日志士，直接参与刑讯逼供。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6de4ef7946c44144ac24f58cfc7aca51','9f7b3ed9c76f4eea8211fd8ebc40a461',1943,'伪新编第五军军长','原国民党军阀，1943年投日，其部队曾驻防保定西部，虽主要活动于太行山区，但曾派兵至白沟新城一带“清剿”八路军游击队。','市县厅局级','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b7d8a68389fa4d7987f5a9f973ee6534','faf1e7317adc4737b491d3a86435b024',1937,'伪保定保安队队长','原为土匪，后投靠日军，任保定伪保安队队长，协助日军扫荡抗日根据地，残害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1b681d1584264f5497011e6ead5d4f65','b0ef39cdbaf940c7b1651f04bfe57b09',1938,'伪高阳县长、伪保定道尹','曾任伪高阳县长，后升任伪保定道尹，推行日伪统治，强征粮税，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ad462f3a946448a5952fa9fa2a045abb','b1303da80b994629ba3bf2748d8842c1',1938,'伪河北省保安司令（后投敌）','原国民党将领，后与日军勾结，任伪河北省保安司令，在保定地区组织伪军袭扰抗日武装。；原国民党河北民军总指挥，后与日军勾结，在冀中地区（含望都）破坏抗日组织，袭击八路军后方机关，制造摩擦事件。；原国民党河北民军总指挥，在阜平、曲阳一带与八路军摩擦，后公开投敌，协助日军建立伪政权，破坏抗日组织。；原国民党将领，后与日伪勾结，在冀中地区破坏抗日组织，协助日军扫荡。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9ca6ec4647bb4eba8c187c14ddfd633a','247dfbbaa63247e6972f3f1e381eadf4',1940,'伪保定警备队大队长','率伪警备队多次配合日军“扫荡”高阳、清苑等地，抓捕抗日干部，烧毁村庄。','基层头目','hanjian');
