INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c1cb388d1d9c439d9706784e827fe176','54bc56fb24964f85a6c77ecfaa3803bd',1942,'伪保定宪兵队翻译官','为日军宪兵队充当翻译，参与审讯和酷刑迫害被捕抗日志士。','基层头目','hanjian');
