INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7d7e1ed82c004a7fa7b65c738097e73f','8cdba6442ec2496c99f3cd93fd4a2106',1937,'华北自治联军司令','原抗日武装首领，后叛变投日，在保定、唐县一带组建伪军，协助日军清剿抗日根据地。','基层头目','hanjian');
