INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('11db1c857d334e159348b0bff613d472','9f7b3ed9c76f4eea8211fd8ebc40a461',1943,'伪新五军军长（后投日）','虽非安新籍，但其部队在冀中包括安新地区活动，配合日军清剿，其部属在安新犯有烧杀罪行。；原国民党将领，1943年投敌后，其部队曾驻扎廊坊南部地区，协助日军“清乡”。；原国民党将领，1943年投敌后，其部队在冀鲁边（含沧州、海兴）参与“扫荡”，配合日军进攻八路军。；1943年率部投敌，所部在豫北鹤壁、林县一带配合日军行动，进攻八路军根据地，后任伪军要职。','市县厅局级','hanjian');
