INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('302b25218c284db1bb3e7e323ac05c3f','8ab29f89ba2147a1b5c2d7258899eab0',1939,'伪保定道尹公署顾问','原国民党地方官员，投敌后任伪保定道顾问，协助日军推行“治安强化运动”，在涿州一带强征民夫、掠夺粮食。','无明确职位或一般帮凶','hanjian');
