INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('764d4c082c3d4c0994255fa8a250e7bd','14a64bdf83f946a69313263707ddf495',1941,'伪涿县新民会会长','主持新民会涿县分会，推行奴化教育，组织“反共救国会”，搜集抗日情报，协助日军抓捕进步青年。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7435ad7a13474b6d982aae70d1b553cc','6fee2b329ee54681a24b19e7abf091b7',1942,'伪涿县警察局局长','指挥伪警察特务，破坏涿州地下党组织，逮捕并刑讯逼供抗日志士，导致多名党员牺牲。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('38a57a5ccaac4e90949f898faf8eda78','bde7fd610ba844e2a3bd382d0f88b962',1943,'伪保定绥靖公署参议（涉涿州）','原国民党军官，投敌后参与策划对涿州、新城等地的“铁壁合围”，为日军提供当地抗日武装情报。','无明确职位或一般帮凶','hanjian');
