INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('83421357fbcd402fa84f8574e874f517','be101ae50c01499eb4d1ad9af8d79b62',1939,'伪满城县知事','任伪满城县知事期间，推行保甲制度，强征粮税，协助日军建立情报网，抓捕抗日地下人员。','基层头目','hanjian');
