INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('706fce79c54148f9b0577e7c9c5906f7','9f7b3ed9c76f4eea8211fd8ebc40a461',1943,'伪冀察战区挺进军暂编第2军军长（活动于满城周边）','虽为军阀出身，但1943年后公开投敌，其部队在满城、易县一带配合日军“清剿”，劫掠百姓。','市县厅局级','hanjian');
