INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a562d299e361465a936ac988346fc2d7','16282abdc6384cc0b4580ac64c3f14b2',1938,'伪保定市市长','任伪保定市市长期间，积极推行日伪政权各项政策，强征民夫，搜刮粮食，协助日军建立保甲制度，镇压抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('93b713482429469295aa12f142c9e907','8f1dd12e548b4c4f866dd743c3377896',1937,'伪华北政务委员会内政总署督办（曾驻保定）','虽为华北级汉奸，但多次到保定视察督导，推动伪政权在保定地区的建立，支持日军清乡和“三光”政策。','省部级/大军区级要员','hanjian');
