INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('13df4fb6f0ac433cb85e9b620c089fad','8ab29f89ba2147a1b5c2d7258899eab0',1940,'伪保定保安队大队长','率伪保安队配合日军在竞秀区及周边村庄进行“清剿”，烧毁民房，抢掠财物，杀害抗日家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('14497c5a415f430dbbfbb0f2801c0a44','1ec7c49f402b4acbb11ec0197fc7341a',1939,'伪保定警察局局长','主持伪警察局，设立特务机构，破坏中共地下组织，逮捕并刑讯抗日人士，直接参与多起屠杀事件。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aca8d01ad8ae408a8ead5734d01b62b6','8f1dd12e548b4c4f866dd743c3377896',1937,'华北政务委员会内政总署督办、伪河北省省长','原北洋政客，投日后任伪华北政务委员会要职，在保定、莲池一带推行日伪统治，镇压抗日力量，协助日军进行经济掠夺和奴化教育。','省部级/大军区级要员','hanjian');
