INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d714fbcb06504b23920ab037e02524b3','bf398d44782c4c1594ef5ef1eecbf521',1937,'伪保定市维持会会长、伪保定道尹','保定本地士绅投敌，组织维持会迎接日军，后任伪保定道尹，为日军提供情报，强征民夫，破坏莲池书院等文化场所。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('45236bef330f4dc58ff8e16d42c714ba','8ab29f89ba2147a1b5c2d7258899eab0',1938,'伪保定保安队队长','原土匪头目，投日后任保定伪保安队长，多次参与对莲池周边村庄的烧杀抢掠，抓捕抗日军民，双手沾满鲜血。','基层头目','hanjian');
