INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8012af9d517445e9a0913075ebaf75cf','fe3714834b1947b889499c395158f675',1935,'伪冀东防共自治政府民政厅长','主管伪政权民政，在唐山地区推行保甲制度，协助日军清乡。；负责冀东地区（含唐山、丰南）的民政和保甲制度，强征壮丁，配合日军清乡，迫害抗日家属。；主管伪政权民政事务，在唐山各县推行日伪户籍管理，强征劳役，协助日军建立伪乡村政权。；负责伪冀东政府民政事务，在滦南、乐亭等地推行保甲制度，协助日军清乡，迫害抗日家属。；主管伪政权民政事务，在滦州、唐山地区组织保甲制度，镇压抗日活动。；负责伪政府民政事务，在遵化、唐山等地推行日伪户籍登记，协助日军清乡，迫害抗日家属。；负责伪政府民政事务，推行日伪统治政策，在秦皇岛、北戴河等地实施保甲制度，镇压抗日活动。；在伪冀东政权中任要职，配合日军统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4078e95949df4b6d819b25fde9afa821','4cc5391bc78947fa9bf1a4b59e0f5371',1935,'伪冀东防共自治政府财政厅长','为伪政权筹措经费，在唐山地区强征捐税，搜刮民财。；主持伪政府财政，搜刮唐山、丰南等地税收和粮食，为日军提供军费物资。；为伪政权筹措经费，征收苛捐杂税，将唐山地区盐税、矿税等收入用于日军军需。；负责伪政权财政，为日军侵华筹措资金，协助掠夺唐山地区资源。；在唐山地区发行伪币，搜刮民间金银，造成通货膨胀，民不聊生。；掌管伪冀东财政，为日军筹措军费，强征苛捐杂税，导致唐山、滦南地区民生凋敝。；为伪政权筹措经费，在唐山、滦州强征捐税，搜刮民财供日军使用。；主管伪政府财政，为日军筹措军费，在唐山、遵化强征各种捐税，掠夺当地资源。；为伪政府筹措经费，征收苛捐杂税，搜刮秦皇岛、北戴河地区民财，支持日军经济掠夺。；负责冀东伪政权财政，在秦皇岛、山海关征收苛捐杂税，搜刮民财；在秦皇岛港征收苛捐杂税，为日军提供军费，控制海港贸易。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0e9abd7cb270413c82e00481a87a3207','9dc3aaa23c914c94acade8c943435489',1935,'伪冀东防共自治政府建设厅长','负责伪政权建设事务，在唐山地区强征劳工修建军事设施。；负责伪政府管辖区域（含唐山、丰南）的交通和工矿资源开发，为日军掠夺开滦煤矿等资源服务。；负责伪冀东交通和资源开发，配合日军掠夺开滦煤矿资源，强征劳工修筑军事设施。；负责伪政权在冀东的交通、工矿建设，配合日军掠夺唐山煤炭资源。；负责伪政府建设事务，组织劳工为日军修建公路、碉堡，在遵化山区协助日军封锁抗日根据地。','市县厅局级','hanjian');
