INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('152071eab88848dd948280e262c9dd4f','9f7b3ed9c76f4eea8211fd8ebc40a461',1939,'伪冀东剿匪军副司令（后投敌）','率部在唐山地区配合日军进攻八路军，后公开投敌。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('21d8430213414111bb692bbeb41f8fd9','5ec2ad124b2f429482b1a90a7f8d4a92',1943,'伪华北治安军第二集团军司令（活动于冀东）','投敌后率伪军在唐山地区“扫荡”，制造无人区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5a114b54c71e462ab6056e413af9834b','63006a4879fb4f49ad97a1e88c8c5d69',1944,'伪冀东绥靖军司令（后期）','率伪军在唐山沿海地区布防，对抗登陆盟军和游击队。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8e2268bd25874925933a1f787b5ae12a','848992e841c9488c8cdcf56cad9f079c',1944,'伪冀东保安司令（后期）','在唐山地区扩充伪军，镇压抗日力量，直至日本投降。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('431677141981474da99c0fb6d3953c5e','83b067447f4744f7b527179c4d9524d4',1935,'伪冀东防共自治政府秘书长、代理政务长官','殷汝耕的主要助手，参与伪政府行政运作，管理冀东地区（含唐山、丰南）的伪政权事务，推行奴化教育和经济掠夺。；殷汝耕主要助手，参与伪政府行政运作，在唐山地区推行保甲制度，协助日军镇压抗日力量。；协助殷汝耕管理伪政权，1938年殷汝耕下台后短暂代理政务长官，继续为日军服务。；协助殷汝耕管理伪政府，在唐山地区推行奴化教育，强征民夫修建军事设施，配合日军清乡。；殷汝耕的主要助手，参与伪冀东政府运作，在唐山地区推行奴化教育和经济掠夺，后接替殷汝耕主持伪政府。；殷汝耕的主要助手，参与伪政府行政运作，协助日军在冀东地区推行保甲制度，强征民夫修筑工事。；殷汝耕的得力助手，参与伪政府日常行政，协助日军在唐山、遵化等地推行保甲制度，强征民夫，搜刮物资。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8e783ae9638846b19835eaa3b952849c','c962700c3422426b946336b59832e9d0',1935,'伪冀东保安队第一总队队长','率部驻防唐山地区，充当日军鹰犬，参与镇压冀东抗日暴动，捕杀抗日军民。；率部驻防唐山、开平一带，多次配合日军扫荡抗日游击队，抓捕并杀害抗日军民，制造多起惨案。；驻防唐山地区，参与镇压1938年冀东抗日大暴动，屠杀暴动群众，后随伪政府并入华北伪政权。；原为冀东保安队军官，投日后率部驻防唐山一带，配合日军清剿抗日武装，参与制造多起屠杀事件。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1f80432a6e2547448cf9fbe717be47d7','ce9e90f94a5d49b1bfa7d545908262bf',1935,'伪冀东保安队第二总队队长','在丰南、滦县一带活动，协助日军扫荡，破坏抗日组织，强征民夫修筑工事。；在唐山地区协助日军维持治安，参与镇压1938年冀东抗日大暴动，屠杀暴动群众。；驻防迁西、遵化交界地区，多次袭击八路军游击队，抓捕抗日群众并移交日军宪兵队。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2646484d78544aab8df06d00c1cf8fce','b5b65c50b47e42e49b1a39960686a979',1935,'伪冀东保安队第三总队队长','驻防唐山周边，参与围剿抗日游击队，残害百姓，掠夺财物。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b722a3eed1ef45198fe1829a776443d1','614aeb3d282f4fcaa4ae33adfba60644',1935,'伪冀东防共自治政府唐山办事处处长','在唐山市区推行伪政权法令，管理治安和税收，协助日军建立情报网，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('395841544ae3463c8b35e9d6e79144df','6fab1ab12345452bb255f075c3437dc4',1937,'伪丰润县知事（含丰南地区）','在丰润、丰南一带任伪县长，推行保甲连坐，强征粮食，配合日军“治安强化运动”，多次带队清乡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1c640a585d3548c0aa9b61bcb42ee036','7338777bfbc14a209d01af8c4dc145fd',1938,'伪滦县知事（含丰南部分区域）','在滦县及丰南边界地区实施伪政权统治，组织汉奸武装，协助日军屠杀抗日群众。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2c3dc0b7910f4b7b9155bcade46998c7','472bf2c37be248e48ba228f6716b5e12',1938,'伪唐山特别市公署市长','1938年唐山设市后任伪市长，全面推行日伪统治，控制工商业，强征劳工，为日军提供煤炭等战略物资。','市县厅局级','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('743ba12412064c1ba1ddd85a1b0648fd','e538c80c33b940f0b5d7c5daa6a74d22',1941,'伪唐山特别市公署市长（继任）','继任伪唐山市长，继续执行日伪政策，强化治安，镇压工人罢工和抗日地下活动。','市县厅局级','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('07b32f03bbfd4457b9a89a9fb77ed88e','5d14d3296bb6460cb4888b6a2dcce5ae',1938,'伪唐山特别市公署警察局局长','指挥伪警察在唐山、丰南地区搜捕抗日分子，破坏地下党组织，刑讯逼供，民愤极大。','市县厅局级','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5a2b63e3ce6545b49d93d343a46e6533','8fdb75c63ff4478aa86d74431b472cde',1938,'伪冀东保安队司令（后改编为伪治安军）','原军阀余部，投日后任伪冀东保安司令，驻防唐山、丰南，多次参与“扫荡”，屠杀抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c39312fdd93145519c433c8e2a450564','4a71ce857bc64724acfaa74f2868edfd',1940,'伪冀东剿共军司令','在冀东地区（含唐山、丰南）组织伪军，专门对抗八路军，制造多起惨案，如丰南潘家峪惨案中参与围剿。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3db53391e2ba4c4a94898a1a16159ec2','b623d18433e34b859e385f6a8c02c27e',1937,'伪丰南胥各庄维持会会长','在丰南胥各庄一带组织维持会，为日军征粮派款，提供情报，协助抓捕抗日志士。','基层维持会/地方自治头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('facec728f98246dc897fa5653582b448','89c8afa72b15420fb3bf3cb433f0f091',1938,'伪丰南稻地镇自卫团团长','在丰南稻地镇组织汉奸自卫团，配合日军巡逻，袭击抗日游击队，残害百姓。','基层头目','hanjian');
