INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('49b577d5361d4b30ba4554715d23fd0d','bde77533c68f469aa5eeb667ea3940ed',1938,'伪冀东银行行长（唐山分行）','在唐山设立伪银行，发行伪币，搜刮民财，为日军侵华战争提供金融支持。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3134c5d9efb3433d9536cc6d85aa1656','83b067447f4744f7b527179c4d9524d4',1935,'伪冀东防共自治政府秘书长/代理政务长官','协助殷汝耕管理伪政府，后代理政务长官，在唐山、丰润地区推行奴化教育和经济掠夺。；殷汝耕的主要助手，参与伪冀东政府行政运作，在唐山地区推行奴化教育和经济掠夺。；协助殷汝耕建立伪政权，后代理政务长官，在唐山、滦州推行奴化教育和经济掠夺。；殷汝耕的主要助手，参与伪政府运作，后代理政务长官，协助日军控制冀东地区，包括秦皇岛、北戴河一带。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ac7f26e43e9b47628a2da86ab16e6fed','7a23cbce0a324a57b42b15b4cf9670f6',1935,'伪冀东防共自治政府唐山办事处主任','负责唐山地区伪政权日常事务，配合日军清乡，强征民夫修筑工事。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ec832236653a4a90a7c503bfa1be8999','c962700c3422426b946336b59832e9d0',1935,'伪冀东保安队第三总队队长','驻防唐山、丰润一带，多次率部袭击抗日游击队，杀害抗日军民，后随殷汝耕投敌。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e8624eb413434d479aa8edc3ee64940a','8fdb75c63ff4478aa86d74431b472cde',1935,'伪冀东保安队第一总队队长','在丰润、滦县等地配合日军扫荡，抓捕抗日分子，烧毁村庄。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('936a236e2509423fa4b2f2f887deb078','7ecf38311c27407bbb44fdd793ae7b5b',1935,'伪冀东保安队第二总队队长（后反正）','初期在唐山地区为日军效力，但1937年通州事变中反正，击毙日军，后脱离伪职。注：因其前期活动在丰润地区，故列入。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b0a157147d564c72aa08294ddf84aeda','614aeb3d282f4fcaa4ae33adfba60644',1935,'伪冀东自治政府保安处长/伪冀东保安队司令','在唐山、丰润地区组织伪保安武装，协助日军镇压抗日救国会，残害进步群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f614e9850a5c4da0906c9ff5607291b1','ee8d55af56294c0cbfa4ebf21208495a',1937,'伪丰润县知事（县长）','在丰润县推行保甲制度，强征粮食，配合日军“治安强化”运动，多次报告抗日武装行踪。','基层头目','hanjian');
