INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0765d83339b94eed8737e1133ec21b3a','4cc5391bc78947fa9bf1a4b59e0f5371',1938,'伪唐山市长','管理唐山市区，为日军提供煤炭等战略物资，镇压工人罢工，设立“劳工协会”强征劳工。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('de2faf0e6d4c4e41b70099a0f67efd51','6fab1ab12345452bb255f075c3437dc4',1937,'伪唐山警察局局长','在唐山、丰润交界处设立检查站，搜捕抗日人员，严刑逼供，杀害多名地下党员。；指挥伪警察协助日军特务机关，破坏地下抗日组织，逮捕并刑讯抗日人员，在汉沽地区设检查站。；在唐山市区及芦台地区建立伪警察网络，搜捕抗日志士，破坏地下组织，执行日军“治安强化”政策。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e7137c2186fe48f3be44b00459b01ed2','894e36564eb143b4a455105f9e6253c4',1938,'伪冀东道尹公署顾问/汉奸特务','在丰润地区发展情报网，向日军提供八路军活动情报，参与制造“潘家峪惨案”的向导工作。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('df4c33a3582240f9b6fd8dea1a5a3714','da90806a908143cd8269c5f4be2a69e6',1941,'伪丰润县保安队副队长（日籍顾问代理）','实际指挥伪军扫荡丰润北部山区，烧毁村庄十余个，屠杀百姓百余人。注：此人为日籍但归化汉奸，有争议，但史料列为汉奸。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f542596540094711a17a1e19a0386760','575ddccb955b4eadaa25fd9980fc3368',1939,'伪丰润县新民会会长','宣传“中日亲善”，组织奴化教育，强迫青年参加伪军，协助日军收集民间枪支。','基层维持会/地方自治头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0ce1e6ea47a34ab3b965f26872718466','0d8caf4d9bc44947a89d5d6feaeefbae',1937,'伪唐山商会会长','为日军筹款，垄断粮食和棉布，高价卖给百姓，资助伪军，并告发抗日商人。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a96c56eee4514c61a0b1909aba399a43','ea4f2836cca74ade939f536f1ff8b3e5',1940,'伪冀东剿共军第一路司令','率伪军驻防丰润、玉田，多次围剿八路军冀东军区部队，杀害抗日战士和群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9cb02ab2588741408145d9d14b34c4ca','5254fb64d6f844c79e97b5a20665ca57',1942,'伪丰润县特务队长','专门抓捕抗日家属，刑讯逼供，破坏地下交通站，罪行累累。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('847346fce139464d945c9aac03d563a8','8f4c6a82abd7490ab754fe15d2224dd0',1938,'伪唐山宪兵队翻译兼密探','为日军宪兵队翻译，参与审讯抗日志士，多次带路突袭丰润村庄，造成重大伤亡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e207f17dd45147bd9b3b357246156e78','83b067447f4744f7b527179c4d9524d4',1935,'冀东防共自治政府秘书长/代理政务长官','殷汝耕的主要助手，参与冀东伪政权运作，管理唐山地区行政事务，协助日军征粮派款。；殷汝耕的主要助手，参与冀东政府运作，后接替殷汝耕主持伪政府，协助日军在冀东地区征粮、抓夫、建立保甲制度。','市县厅局级','hanjian');
