INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d30a03b9c4f14ca7a04f5cd3b11711a2','8fdb75c63ff4478aa86d74431b472cde',1935,'伪冀东自治政府顾问/伪华北治安军高参','唐山丰润人，早年投靠日军，参与组建伪冀东政权，后任伪治安军高参，在唐山地区招募伪军，配合日军扫荡。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1724010689ea44578c741dc467889520','7ecf38311c27407bbb44fdd793ae7b5b',1935,'伪冀东保安队第一总队队长（后反正）','原冀东保安队军官，投日初期在唐山地区维持伪秩序，1937年通州事变中反正，但此前在唐山、芦台一带执行伪职。；初期在冀东包括大厂地区为日军效力，后于1937年通州起义反正，但此前有助日行为。','基层头目','hanjian');
