INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a6b6b96934ff495ba85b5477c6808327','894e36564eb143b4a455105f9e6253c4',1937,'伪唐山商会会长','投靠日伪，组织商会为日军筹措军费，强征物资，协助日伪经济统制，在唐山芦台一带盘剥商户。；投靠日军，控制唐山商会，为日军筹集物资、摊派捐款，强迫商户悬挂伪旗，迫害爱国商人。；为日军强制收购钢铁、棉花，压低价格盘剥商户，资助伪军经费。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8973ecac3c7142a0b676802fef325211','aea3838771d8458ba6073d341943bb27',1939,'伪冀东剿共军司令','率伪军驻防唐山、芦台一带，多次参与对冀东抗日根据地的围剿，屠杀平民，烧毁村庄。；在唐山、丰南、滦南等地进行“清剿”，制造多起惨案，烧毁渔船，封锁沿海交通。','基层头目','hanjian');
