INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('291b56728ca04f9aa1be71bf39fb4492','c1dbe26db6d84f79b1e21b01f55a543b',1938,'伪唐山矿务局督办','管理唐山煤矿，强迫矿工为日军生产煤炭，克扣工资，镇压矿工罢工，致多起矿难。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('43c4e2fce03b44b48149fdf1557c8fcb','132f5d3d790f45d8a0fd662613f98328',1939,'伪唐山教育督办','推行奴化教育，强制学校教授日语，删改历史教材，迫害爱国教师，组织学生参拜神社。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('229be11632504498bdb8ce7d189710c0','a397621afab5417ca3f54a3a30162bb8',1941,'伪唐山高地区联防队长','在唐山高地区（今开平区一带）组织伪联防队，配合日军“清乡”，杀害抗日积极分子，抢夺民财。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8bebe202ad674c0990fb6a809e567ee6','7ecf38311c27407bbb44fdd793ae7b5b',1935,'伪冀东保安队第三总队队长（后反正）','初期在唐山、开平执行伪政府命令，但1937年通州起义反正，此处仅列其前期汉奸行为。；初期为伪冀东保安队军官，驻滦县，后于1938年通州起义反正，但此前曾参与镇压抗日活动。；初期在玉田地区执行伪政权命令，后于1937年通州起义反正，但此前有助敌行为。；初期投日，在唐山地区维持伪秩序，1937年通州起义反正，但此前曾参与镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('30e4b9b49d8344b7910196bd682df3a4','8fd3b0b16b584737a57d1cde87478765',1935,'伪冀东保安队第四总队队长','驻防唐山地区，协助日军收缴民间武器，强征壮丁，破坏抗日组织。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e6094cbe5bc64fe79b6144251b18beb6','e522b6ab522f49069eec5b5c41bfd50f',1938,'伪唐山特别市公署市长','1938年伪冀东政府改为伪河北省后，任伪唐山市长，推行日伪经济统制，强征粮食煤炭，为日军提供战争物资。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8732802c181445a09be668271c2f9572','6fab1ab12345452bb255f075c3437dc4',1938,'伪唐山特别市公署警察局长','指挥伪警察在唐山、开平地区搜捕抗日地下党员，破坏交通线，多次参与“治安强化运动”。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a62e5504f76d4d61a074ff82d759538d','614aeb3d282f4fcaa4ae33adfba60644',1938,'伪冀东剿共军司令','在唐山、开平、滦县一带组建伪军，配合日军进行“铁壁合围”扫荡，杀害抗日干部数百人。；率伪军驻扎唐山、迁西一带，多次进攻冀东八路军，制造“潘家峪惨案”等血案（潘家峪属丰润，但活动范围覆盖迁西）。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5919db0c905b4ecf9b3e903ee9b9514d','aea3838771d8458ba6073d341943bb27',1936,'伪冀东保安队第五总队队长','长期盘踞开平镇，设立据点，勒索百姓，多次袭击八路军游击队，烧毁村庄。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e6b3d023b0cc4553a57b89ed55502bcc','76f302c6ed8e41a2baa25169b3e4c5cb',1937,'伪开平区维持会会长','日军占领开平后组织维持会，为日军征粮派款，提供情报，协助建立伪区公所。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4b710f5acecc4d509f40012c6dd83fa7','0fcbbced9bbc4b5bbfed598fc6098f93',1940,'伪开平区区长','在开平推行“保甲连坐”，强抓壮丁送日军当苦力，克扣抗日家属救济粮。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e9b0f76e2a7c4ecda4d99d40e11ff017','c3702032be8b4960bd9759a5e3a67635',1935,'伪冀东防共自治政府教育督办','在唐山、开平各学校推行日语教育，篡改历史教材，强迫学生参拜日本神社。','省部级/大军区级要员','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2a6cb153417f4c6588cfc0f3e5dd0c56','bde77533c68f469aa5eeb667ea3940ed',1935,'伪冀东防共自治政府顾问（未实际到任但参与策划）','虽主要活动于东北，但曾为殷汝耕出谋划策，涉及唐山地区伪政权设计。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4f3606ee7fd14a7b9a02182852e0f8f4','da58b77853f14ce7b32f7f6b3305b75a',1940,'伪华北政务委员会治安总署督办（管辖唐山驻军）','虽总部在北京，但其伪军部队多次在唐山、开平地区扫荡，指挥“治安军”屠杀抗日群众。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('afef981526db44159641de095369b6ea','d2b840cc6fa142c8b5c30c100a11b64d',1941,'伪华北治安军第二集团军司令（驻防唐山）','率治安军驻扎唐山，配合日军进行“剔抉”扫荡，在开平制造无人区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1e17cc1480214763824df7711a6b971c','b5ba32ac9dee4113808d7f1e4475b119',1935,'冀东防共自治政府主席','1935年11月在通州成立冀东防共自治政府，宣布冀东22县脱离国民政府，管辖范围包括唐山、曹妃甸所在地区，为日本侵略者服务，征收苛捐杂税，镇压抗日活动。；1935年11月在日本扶植下成立冀东防共自治政府，辖冀东22县（含唐山、路南地区），公开投敌，为日军提供粮秣、劳役，镇压抗日活动。','地方伪政权首脑','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('31cde1acaff4467c893a75da1e635263','83b067447f4744f7b527179c4d9524d4',1935,'冀东防共自治政府秘书长/代理主席','协助殷汝耕管理冀东伪政权，参与组织伪军和警察，配合日军清乡，在唐山地区推行奴化教育。；协助殷汝耕管理冀东伪政权，参与推行奴化教育、征收苛捐杂税，配合日军清乡。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f78a689aa2134e198f2b82c575e7833a','7a23cbce0a324a57b42b15b4cf9670f6',1935,'冀东防共自治政府民政厅长','在冀东伪政权中负责民政事务，协助日军控制唐山、滦县等地基层政权，强征民夫修筑军事工事。；主管伪政权民政事务，组织保甲制度，协助日军建立治安维持会，迫害抗日军民。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e4805c84c2124192b22d82cbd4b4a0d6','c962700c3422426b946336b59832e9d0',1935,'冀东保安队司令','统率冀东伪保安队，驻防唐山一带，多次配合日军扫荡抗日游击队，杀害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ab8665e404ab4492a96a691e829996d0','ce9e90f94a5d49b1bfa7d545908262bf',1936,'冀东伪军第一师师长','率伪军在唐山、丰润、滦县等地进攻八路军，烧毁村庄，掠夺物资。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a7be53bac1fa4f34a9a036567e1152a1','7ecf38311c27407bbb44fdd793ae7b5b',1935,'冀东保安队第一总队队长','初期为殷汝耕效力，后于1937年通州事变中反正，但此前曾在唐山地区参与镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2db9da2778054b4da43dd4f57df9c415','8fd3b0b16b584737a57d1cde87478765',1936,'冀东伪军第二师师长','驻防唐山地区，协助日军“治安肃正”，抓捕抗日地下工作者。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3a055b90d3aa4492b67808f76ddfd8e9','b5b65c50b47e42e49b1a39960686a979',1938,'伪冀东道公署道尹','伪冀东道（辖唐山、昌黎、滦县等地）最高行政长官，推行保甲制度，强征粮食支援日军。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8ad52a7f059b4e6298186431a208e03a','4a71ce857bc64724acfaa74f2868edfd',1939,'伪冀东道公署顾问','日本顾问的帮凶，参与策划对冀东抗日根据地的“铁壁合围”，在曹妃甸沿海地区组织伪自卫团。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e77199664635479f81e19b0bb65f9ab4','614aeb3d282f4fcaa4ae33adfba60644',1940,'伪唐山治安军司令','统率伪治安军驻唐山，多次袭击冀东八路军，在曹妃甸一带设卡盘查，杀害抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ec067a4ae89f4ff3a40175f6e56aaffc','132f5d3d790f45d8a0fd662613f98328',1938,'伪丰润县知事','管辖包括曹妃甸周边区域，为日军提供情报，强征劳工，迫害抗日家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('763932edbfd4465abeffbfef5a94bf5e','4cc5391bc78947fa9bf1a4b59e0f5371',1939,'伪滦县知事','在滦县及沿海地区推行“连坐法”，协助日军掠夺盐业资源，镇压渔民抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('89c2b64a60884112b595fa72061c00df','8fdb75c63ff4478aa86d74431b472cde',1936,'伪冀东保安队第三总队长','驻防唐山古冶一带，参与屠杀抗日游击队员，抢劫商旅。；驻防廊坊北部地区，多次率部参与对冀中十分区（含霸州、文安等地）的扫荡，烧杀抢掠。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5ac13e13e82d45b398ac05100dc38a89','0ce8cfc7facb4f7987ad17446ef46f24',1939,'伪唐山警察局局长','指挥伪警察搜捕抗日分子，破坏地下组织，在曹妃甸港口设立检查站。','市县厅局级','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ab02ba5ec7f34c1f83306a641b053c0d','5f1c45e69c7a45979dc23fe85669619c',1940,'伪冀东盐务局局长','控制曹妃甸沿海盐场，将盐产大量供应日军，禁止民间私盐，导致渔民困苦。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7ee358edfe7d4b278d91effdc1122549','9f7b3ed9c76f4eea8211fd8ebc40a461',1943,'伪冀东挺进军总司令（后投敌）','原国民党将领，1943年投敌后任伪职，在唐山北部山区配合日军进攻八路军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b1b3a0e35e9d41a8b2c553420e1638fd','5ec2ad124b2f429482b1a90a7f8d4a92',1943,'伪冀察战区总司令（投敌后）','投敌后名义上管辖冀东部分地区，虽未直接驻唐山，但影响伪军行动，间接参与对曹妃甸沿海的封锁。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('510b6bf73ff4450f8357b6644c73b350','6403f5d422ce4931b72d743567bd3190',1935,'伪冀东保安队总队长','指挥伪冀东保安队，在唐山、滦县一带协助日军扫荡，围剿抗日游击队，制造多起惨案。；原为地方武装头目，投靠殷汝耕后任伪保安队总队长，在唐山、遵化一带配合日军扫荡，围剿抗日游击队。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0657760765d44336baa7f2e2b300f517','614aeb3d282f4fcaa4ae33adfba60644',1935,'伪冀东保安队第二总队队长','在滦县、滦南一带驻防，多次袭击抗日武装，抓捕并杀害抗日志士，民愤极大。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('54e7d416fe854ea2b659ed985419cd6e','8fdb75c63ff4478aa86d74431b472cde',1935,'伪冀东自治政府顾问、伪华北治安军高参','原军阀，投日后参与冀东伪政权组建，后任伪治安军高参，协助日军在唐山地区“治安肃正”。；原为军阀余部，投日后任伪职，参与策划冀东伪政权，后任伪华北治安军高参，在唐山地区协助日军训练伪军。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b4f9f994af594b9eb90e9b4a46e44e5e','31abdc5e4e0a4ebdbe5f0b715a509863',1937,'伪中华民国临时政府行政委员会委员长（辖河北）','1937年北平伪临时政府首脑，管辖包括唐山、滦南在内的河北地区，推行伪化统治，支持日军经济掠夺。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4f8af0b5a7954e2497f7428b91d498c2','d2b840cc6fa142c8b5c30c100a11b64d',1938,'伪华北治安军副总司令兼第一集团军司令','率伪治安军驻扎冀东，在滦南、丰南一带多次进攻抗日游击队，烧杀抢掠。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a8c9003bb28249f098fecb5db9d00cfe','ce9e90f94a5d49b1bfa7d545908262bf',1938,'伪冀东剿共军司令','原土匪头目，投日后任伪冀东剿共军司令，在滦南、乐亭沿海地区残害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b066bb4ae6d34bd581f46d4afedaccef','b5b65c50b47e42e49b1a39960686a979',1938,'伪冀东剿共军副司令','协助李海天在滦南地区活动，参与“无人区”制造，强迫村民集家并村。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d5823f6acdd844499e4d24c568a1c645','14a8c9f458644409a01ba33a632897c7',1935,'伪冀东保安队第四总队队长（后反正）','同张庆余，初期在冀东地区执行日伪命令，后参加通州起义，但前期行为仍属汉奸行径。；投日期间在唐山、丰润一带活动，协助日军收缴民间枪支，后随通州起义反正。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4357f9c09c1a4d0fbb75b6ef34b52ffd','bde77533c68f469aa5eeb667ea3940ed',1937,'伪华北政务委员会顾问','作为法律顾问参与伪华北政权立法，为日伪统治河北（含唐山、滦南）提供法律依据。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4439c060167848639d409c9842b8abb8','eb97867e737c44e4944e71b5792c1f23',1937,'伪北平市长（兼辖冀东部分地区）','虽驻北平，但参与对冀东地区伪政权的协调管理，支持对唐山、滦南的殖民统治。','核心城市市长/省部级','hanjian');
