INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8f68442352d54db9ab09418fd9e57762','5254fb64d6f844c79e97b5a20665ca57',1939,'伪迁安县警察局长','在迁安县城及乡镇建立伪警察网络，严查抗日地下交通线，多次带队搜捕八路军游击队和地下党员。','市县厅局级','hanjian');
