INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cb198bc791234c2ba1b20ea29f4b8fca','6fab1ab12345452bb255f075c3437dc4',1937,'伪冀东政府滦县（含迁安西部）维持会长','在滦县、迁安交界地区组织维持会，为日军筹集粮饷，诱降抗日人员，破坏地方抗日武装。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('47a56aa923ee4e318ab384da8ee7c574','1ba31d558b934fbd83a28a8c2b446022',1935,'伪冀东防共自治政府军事顾问（原东北军将领）','虽主要在伪满任职，但多次到冀东唐山、迁安地区指导伪军作战，协助日军策划“扫荡”方案。','无明确职位或一般帮凶','hanjian');
