INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8faa3d71cc224215bcb670da4aff684c','8f1dd12e548b4c4f866dd743c3377896',1940,'伪华北政务委员会委员长（管辖冀东）','作为华北伪政权最高头目，其统治范围覆盖唐山、迁安，支持当地伪军警镇压抗日活动，推行奴化政策。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8a08bf350ae14a58aea2559a03e8ed05','d2b840cc6fa142c8b5c30c100a11b64d',1938,'伪冀东保安队指挥官（驻唐山）','长期驻守唐山，指挥伪军参与对迁安、遵化等地的“清剿”，杀害抗日干部和群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a74b7022b99c4e058a2c0472c8230236','9b2643d9a3f6451bbd8628ccace55b39',1940,'伪迁安县新民会会长','在迁安推行新民会奴化宣传，组织青少年接受日伪教育，收集抗日情报，协助日军“宣抚”工作。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7c280b34905f4d57a14c6449dce8638f','9f7b3ed9c76f4eea8211fd8ebc40a461',1943,'伪冀东剿共军司令（后反正）','虽为军阀投机，但曾在冀东地区（含迁安）与日军合作，参与对抗日根据地的进攻，后于1945年投降八路军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('45335d89634d427582bcbe654c772210','b5b65c50b47e42e49b1a39960686a979',1938,'伪冀东道尹公署道尹','伪冀东道（辖唐山、迁西等县）最高行政长官，推行日伪“治安强化运动”，组织汉奸武装“反共自卫团”。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6f33a80789d542e4a05f289333f2c755','6fab1ab12345452bb255f075c3437dc4',1938,'伪迁西县知事（县长）','在迁西县（时属迁安县）推行日伪统治，强征粮食，建立伪村公所，配合日军“扫荡”抗日根据地。','基层头目','hanjian');
