INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5f3e0c2fcc7646cba90b7a8938d86852','894e36564eb143b4a455105f9e6253c4',1938,'伪唐山特别市公署市长','在唐山市区推行日伪经济统制，强征劳工，镇压工人罢工，迫害抗日分子。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('50f01602d91940b794a2f3ccd5facefb','bde77533c68f469aa5eeb667ea3940ed',1937,'伪华北政务委员会顾问（曾涉唐山地区）','虽主要活动于北平，但多次赴唐山、迁西指导“治安肃正”，为日军出谋划策。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('88ce423a58324a9fbb5f5e8cc93a2bb3','4cc5391bc78947fa9bf1a4b59e0f5371',1943,'伪冀东道尹（继任）','接替王铁相，继续推行日伪统治，在迁西等地强抓壮丁补充伪军。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a52a5184c8a745b889d8124ae4422ae5','9b2643d9a3f6451bbd8628ccace55b39',1941,'伪迁西县保安队队长','率伪保安队常驻迁西金厂峪一带，为日军护矿，镇压矿工反抗，杀害抗日游击队员。','基层头目','hanjian');
