INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('287a15872e3e4a7ca03bfa6a0657efd9','c1dbe26db6d84f79b1e21b01f55a543b',1940,'伪迁西警察署署长','在迁西县城及主要集镇设立警察分所，抓捕抗日地下党员，刑讯逼供，致死多人。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4e445ea77b9f41ff9ebc7f6911d13a38','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满洲国立法院院长、冀东防共自治政府顾问','原为奉系政客，后投靠日本，参与策划冀东事变，协助建立伪冀东防共自治政府，并任顾问，为日军在冀东地区统治出谋划策。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5ec1dba6075d4d6cab2b7625d33a7d63','614aeb3d282f4fcaa4ae33adfba60644',1935,'伪冀东保安队第三总队队长','驻防唐山地区，多次率伪军袭击遵化、迁西等地的抗日武装，杀害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('06ea0946b01747ba887b3f6435046322','da58b77853f14ce7b32f7f6b3305b75a',1937,'伪华北政务委员会治安总署督办、伪华北治安军总司令','虽为华北级汉奸，但其指挥的伪治安军多次在唐山、遵化地区进行大规模“扫荡”，直接参与屠杀抗日军民。；北洋军阀旧部，投敌后任伪华北治安军总司令，组建伪军配合日军扫荡华北抗日根据地。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a7bfc18b36584223928e7edc9a5801fc','d2b840cc6fa142c8b5c30c100a11b64d',1939,'伪华北治安军第一集团军司令','率伪治安军驻扎冀东，在遵化、唐山等地建立据点，配合日军推行“治安强化运动”，围剿八路军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('53bf40b2818d46ec9f46239ee08f6b89','27891b63e29643ee9b1d914ef55b74b3',1938,'伪唐山特别市市长','1938年伪唐山市政府成立后任市长，为日军在唐山矿区掠夺资源服务，镇压工人罢工，迫害抗日分子。','特别市市长','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5baa4887384b4730a4a5b18f23b0a553','6fab1ab12345452bb255f075c3437dc4',1938,'伪唐山特别市警察局局长','负责唐山地区日伪治安，多次组织特务抓捕抗日地下党员，破坏抗日组织。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8bb102a9fa0d4c3b80b6e7ad0013ce92','894e36564eb143b4a455105f9e6253c4',1938,'伪遵化县知事（县长）','在遵化县推行日伪统治，强征粮食，组织伪自卫团，协助日军在遵化山区修建封锁沟，围困抗日根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aa63e576c7f643b68b3f94425fa0f2e1','21da621c7b044526aea0cbf39e08cc05',1938,'伪遵化县保安队队长','率伪保安队多次袭击遵化境内的抗日游击队，杀害抗日群众，烧毁村庄。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6c1d2faed33046bdb4e64a0506201723','6c4ef5046f24435eb1eebae7663c6e7a',1939,'伪遵化县警察所所长','在遵化县城及各乡镇建立伪警察网络，搜捕抗日干部，为日军提供情报。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4c1f63de2b0a4fcb8da36e61e811bd7f','64768bdd2cbe47aa85ba69f423d23aad',1940,'伪遵化县新民会会长','负责遵化地区日伪奴化宣传，组织“新民会”活动，强迫民众参加反共集会，收集抗日情报。','基层维持会/地方自治头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('32ef3e4add814daaacc8fda28d542b40','247dfbbaa63247e6972f3f1e381eadf4',1938,'伪冀东道尹公署道尹（驻唐山）','管辖唐山、遵化等县，推行日伪“治安肃正”计划，组织伪军配合日军扫荡。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d41c4076786746ad9e74d7cafeee2a09','d4758e42e7f24310a9f4549105631eab',1938,'伪冀东道公署顾问','作为日本顾问的帮凶，参与策划冀东地区“清乡”行动，在遵化等地建立“爱护村”制度。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0c75949b022248bc8dd17126c1c4ad6a','b1303da80b994629ba3bf2748d8842c1',1937,'冀中保安司令、河北省保安司令','原国民党将领，后投靠日军，在冀中地区组织伪保安队，协助日军扫荡抗日根据地，捕杀抗日军民。；在安次、永清一带组织反共武装，与日军暗中勾结，破坏抗日根据地，袭击八路军后方机关。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bdc60b60296a42e9b5d0714ca72dafda','aea3838771d8458ba6073d341943bb27',1933,'伪冀东保安队司令','原冀东保安队头目，1935年随殷汝耕投日，在冀东（含廊坊北部部分地区）镇压抗日活动，配合日军“治安肃正”。；长期在冀东（含香河、廊坊一带）为日军效力，镇压抗日民众，参与“治安强化”运动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0a587c960b4147fe842ce4adb854ca60','83b067447f4744f7b527179c4d9524d4',1937,'伪冀东防共自治政府政务长官（后任）','继殷汝耕后主持冀东伪政权，在廊坊地区强化保甲制度，强征民夫修筑炮楼和封锁沟。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c9447becfbda4cf29a9c44425cecc4f7','d2b840cc6fa142c8b5c30c100a11b64d',1937,'伪河北省省长','在任期间推行日伪“新民会”政策，在廊坊各县建立伪县署，强征壮丁，破坏地下抗日组织。；在任期间强化对廊坊等地的殖民统治，推行保甲制度，协助日军掠夺资源。；原北洋将领，投日后任伪河北省省长，在石家庄等地推行日伪政权，强征粮税，协助日军建立保甲制度，迫害抗日军民。；投日后任伪河北省长，推行日伪政权，在石家庄、平山等地区强征粮税，协助日军建立保甲制度。；投敌后任伪河北省省长，配合日军统治河北沦陷区。；在河北沦陷区任伪省长，协助日军维持统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f2ce628e70c1466ba0c6699a60db79da','bf398d44782c4c1594ef5ef1eecbf521',1943,'伪河北省省长（后任）','继续执行日军命令，在廊坊地区强化“治安强化运动”，搜捕抗日家属，实施经济封锁。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a6f30583aad74483a37d3a58defe2e3f','e409ef959281461b91e8ce1eef37d186',1937,'伪华北政务委员会治安总署督办','负责华北伪军整编，在廊坊一带部署伪军据点，配合日军对大清河、永定河流域的扫荡。；在华北伪政权中负责治安，督导包括河南信阳在内的沦陷区伪警察与保安力量配合日军清乡。；在华北伪政权中负责治安，配合日军统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2ae874850de84804a8b32c48997d1cc2','9b2643d9a3f6451bbd8628ccace55b39',1938,'伪安次县知事','在安次（今廊坊安次区）任伪县长期间，积极为日军征粮派款，组织汉奸特务队，抓捕抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e1605f61ce984fd5bf7d645e39e6d062','98806a70e2a5421093e5f8e97c85b408',1939,'伪永清县知事','在永清县推行“保甲连坐”，多次引导日军突袭抗日村庄，造成多起屠杀事件。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8f066f6e5b2b45109a7b96526800c4d2','bb9f3367044e403997a73a2007e0c137',1940,'伪固安县知事','在固安建立伪警察所和情报网，破坏中共固安县委地下活动，协助日军抓捕抗日干部。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6594782d93f546a383cc156890b7aed5','9e6a68f3f008489ea0a4172d21edf894',1937,'伪香河县知事','香河县伪政权头目，强征民夫修建日军机场和碉堡，镇压当地抗日武装。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7629c3e12da2447f873c273c61a2e348','8085e0e5fd8a4ece88f3b28d89e9760f',1938,'伪三河县知事','在三河县推行“粮食统制”，搜刮民财，并组织汉奸武装“反共自卫团”袭击游击队。','基层头目','hanjian');
