INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('18875bae834942029166e999fc78f0c5','8085e0e5fd8a4ece88f3b28d89e9760f',1939,'伪冀东道尹（驻廊坊）','管辖廊坊及周边县份，推行保甲制度，组织“反共自卫团”，协助日军封锁抗日根据地。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3664f2f4e3dc42feba849f58c21bf2af','6fee2b329ee54681a24b19e7abf091b7',1940,'伪香河县警察局长','指挥伪警察侦捕地下党员，破坏抗日联络点，多次参与“清乡”行动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('822700b699464a328bd6a80e7448c89f','5f82d23ccd2e45fd9e59f76c92bcc9ad',1933,'伪蒙古军总司令、察哈尔盟公署顾问','原为热河地方军阀，1933年投日，任伪蒙古军总司令，配合日军侵占察哈尔、张家口地区，参与镇压抗日武装，推行伪蒙政权统治。；原为热河地方军阀，1933年投日，任伪蒙古军总司令，在张家口、桥东一带协助日军镇压抗日力量，参与建立伪蒙疆政权，推行奴化政策。；原为热河土匪，后投靠日军，任伪蒙古军总司令，在张家口及察哈尔地区协助日军镇压抗日力量，参与建立伪蒙疆政权，推行奴化政策。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7be62ee759204e6781e38e63ba871daf','b86083bd13c04af7ae64c9ee8b5ee802',1937,'伪蒙疆联合自治政府总务委员长','曾任伪蒙疆政府高级官员，协助日本管理张家口地区行政事务，参与经济掠夺和奴化教育。；作为德王主要幕僚，参与伪蒙疆政权行政事务，协助日军控制张家口及下花园地区，征收苛捐杂税，强征劳工。；曾任伪蒙疆政府高级官员，协助德王管理张家口、张北地区行政事务，配合日军征粮、抓夫，镇压抗日活动。；原为察哈尔省地方官僚，投日后任伪蒙疆政府要职，协助日军在张家口及察北地区推行保甲制度、征粮派款，镇压抗日活动。','机构委员长(非国家首脑)','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('93280788c69949bb90ed4c708473a427','7fe60a0e08e747819e43053afc3d9d27',1937,'伪张家口市市长','原张家口商会会长，日军占领后出任伪市长，为日军征粮派款，镇压抗日活动，协助维持殖民秩序。；原为张家口商人，日军占领后出任伪市长，为日军征收粮饷，强征劳工，协助维持殖民统治。；原为张家口商会会长，日军占领后出任伪市长，为日军征粮派款，组织维持会，协助日军镇压抗日分子。；原为张家口商会会长，投日后任伪市长，管理桥东等区，为日军提供物资情报，协助建立保甲制度，镇压抗日活动。；原为张家口商会会长，日军占领后出任伪市长，为日军征粮派款，组织伪警察协助日军维持统治，迫害抗日民众。；投靠日军后任伪市长，推行保甲制度，强征劳工，为日军修建军事设施。；投靠日军后任伪张家口市长，为日军提供情报，镇压抗日活动，搜刮民财。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('991f524f49004d15b6029b66ac5912c9','87e5121f4b3b403b908a4c2705738cd3',1937,'伪察哈尔省警务厅厅长','负责伪察哈尔省（含张家口）警察系统，搜捕抗日人士，配合日军进行“治安肃正”行动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('39b6623d24d0472585ac343536ae554e','5bb6456b293d479e87f26e53e7afaa80',1938,'伪察哈尔省保安队司令','指挥伪保安队协助日军扫荡抗日根据地，在张家口周边地区制造多起屠杀事件。','基层头目','hanjian');
