INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a4be0454aa54440ca4e19af8d107dc39','3a9e402192aa460fb51a927d874bb93e',1937,'伪张家口市商会会长','为日军征购物资，强迫商户捐款，充当日本经济侵略的帮凶。','基层头目','hanjian');
