INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a1de3ac3a0bc439d9e81c4a3be9b338f','d255dc1ec48b48db88f1279a2498b74c',1937,'伪察哈尔省司法处处长','为日伪法庭审判抗日志士，判处多人死刑或长期监禁。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1290125492fb41baa44f7661cd30cbd0','b86083bd13c04af7ae64c9ee8b5ee802',1936,'伪蒙古军政府参谋长','参与伪蒙疆政权军事策划，在张家口、万全一带协助日军清剿抗日力量，管理伪军训练与防务。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6fc5e9c23d3d43ecb450f5d15d1b837c','47cac7a73af140d39ff53133e8cfe760',1938,'伪察哈尔省保安队队长','原为地方民团头目，投靠日军后任万全地区伪保安队长，帮助日军维持治安，抓捕抗日志士。；在怀来、涿鹿一带为日军维持治安，搜捕抗日地下工作者，破坏抗日组织。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('620bb61df3bb4b51bf85d5034c36ecb7','8f4c6a82abd7490ab754fe15d2224dd0',1939,'伪万全县知事','任伪万全县县长期间，推行日伪征粮、征税政策，强征劳工，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2ca3aac659b244b29bf40cb89d38a27e','d1a8778b8ca043688fd9fe9e33865efc',1939,'伪张家口市市长','在张家口市推行日伪市政管理，协助日军实行经济统制，迫害市民。；在张家口推行日伪统治，协助日军经济掠夺，对康保等县实施物资统制。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1ce49a41f3634e3b8363a0c5b041dc0b','b8a63ee7224043ba8d5b34e6c030cce4',1940,'伪察哈尔省警务厅厅长','主管伪警察系统，在张家口、万全等地大肆搜捕抗日地下人员，破坏地下组织。','市县厅局级','hanjian');
