INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9def00809a5a427691480870391bacf8','5f82d23ccd2e45fd9e59f76c92bcc9ad',1937,'伪万全维持会会长','日军占领万全初期，组织维持会，为日军筹集粮饷，协助建立伪政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9ad6a0254b634b2fb5739661e7320968','5f82d23ccd2e45fd9e59f76c92bcc9ad',1933,'伪蒙古军总司令、伪张家口特别市市长','投靠日军，组建伪蒙古军，参与侵占察哈尔，曾任伪张家口特别市市长，协助日军统治下花园及周边地区，镇压抗日力量。；投靠日军，任伪蒙古军总司令，参与侵占察哈尔，后任伪张家口特别市市长，协助日军统治宣化地区，镇压抗日力量。；投靠日军，任伪蒙古军总司令，参与侵占察哈尔，后任伪张家口特别市市长，协助日军统治张家口地区，镇压抗日力量。；原东北军将领，1933年投日，组建伪蒙古军，任总司令，后任伪张家口特别市市长，协助日军统治张北地区，镇压抗日力量。；原为热河地方军阀，1933年投靠日军，任伪蒙古军总司令，后任伪张家口特别市市长，协助日军在张家口地区推行殖民统治，镇压抗日力量。；原为东北军将领，后投靠日军，在张家口地区组建伪蒙古军，协助日军控制察哈尔地区，曾任伪张家口特别市市长，镇压抗日力量。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('07b9e434f19b42e9a886728b62e64625','7fe60a0e08e747819e43053afc3d9d27',1937,'伪张家口特别市公署参事、伪察南政厅厅长','投靠日军，历任伪职，在张家口、下花园一带推行保甲制度，协助日军清乡，迫害抗日军民。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d5fd4de29a254df39445828eca7b9d2f','d566dc108e3e455eb9267bb5683e9461',1937,'伪察南自治政府副主席','参与组建伪察南自治政府，管辖下花园等地，为日军提供粮食和物资，协助维持殖民秩序。','无明确职位或一般帮凶','hanjian');
