INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f1af4710962743d2aee47cb5e10535df','5f82d23ccd2e45fd9e59f76c92bcc9ad',1933,'伪蒙古军总司令、察哈尔盟公署长官','原为东北军军官，1933年投靠日军，组建伪蒙古军，在察北地区协助日军镇压抗日力量，推行殖民统治，后任伪蒙古联合自治政府副主席。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f52bff9d43614f7faf6f17e0ed5f428b','dd8c71d66e0841399bb26d229b5ac4ef',1937,'伪察哈尔盟盟长','察哈尔右翼旗总管，投日后任伪察哈尔盟盟长，在察北地区组织伪警察和保安队，配合日军“扫荡”，强征民夫和牲畜。；蒙古族贵族，任伪察哈尔盟盟长，管辖包括沽源在内的察北地区，协助日军征粮派夫，镇压抗日活动。','无明确职位或一般帮凶','hanjian');
