INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('041214a49bbb442fb4c93a4ede3101d7','1ba31d558b934fbd83a28a8c2b446022',1933,'伪热河省省长','1933年日军侵占热河后投敌，任伪热河省省长，协助日军推行殖民统治，镇压抗日力量，强征劳工，掠夺资源。；投靠日军后任伪热河省省长，在承德一带强征民夫、搜刮物资，配合日军“讨伐”抗日武装。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('493115e86b3348bb957b802841365406','e913aea565d54f398ad14deb4526d3a9',1933,'伪热河省警务厅长','任伪热河省警务厅长期间，组织伪警察配合日军“讨伐”抗日武装，抓捕抗日志士，实施“治安肃正”。；承德本地人，指挥伪警察协助日军在双滦、滦平一带搜捕抗日人员，参与制造多起惨案。','市县厅局级','hanjian');
