INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b0b96e1ac86d492c8cd53c044030e7e4','589ab27feed347c6944e6c001125dc02',1933,'伪承德县县长','任伪承德县县长期间，强征民夫修建军事工程，配合日军“清乡”，迫害抗日家属。；在承德县（含双滦部分区域）推行保甲制度，强征粮食，为日军提供情报，镇压抗日群众。；在承德县内强制推行奴化教育，强征劳工，为日军提供物资和情报。','基层头目','hanjian');
