INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c6c1dba46b2c42479fb61b4c0b58fb83','357879a940db49acb9f4e73858a6d10c',1934,'伪满洲国热河省警务厅厅长','在承德、丰宁地区建立特务情报网，多次指挥围剿抗日游击队，逮捕并杀害抗日军民，参与“集家并村”行动，制造无人区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a56cdc708ab14d3d855f2998ddad812a','5f82d23ccd2e45fd9e59f76c92bcc9ad',1933,'伪蒙古军总司令、伪满洲国热河地区军事顾问','原热河地方军阀，投日后在丰宁、围场一带配合日军扫荡，参与镇压抗日义勇军，后任伪蒙古军总司令，长期在热河北部活动。；原热河地方军阀，投日后率伪蒙古军配合日军进攻平泉、承德，镇压抗日游击队。','基层头目','hanjian');
