INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3c245eedda95482aabdc00ef1e0f59c0','af96068e274a4fdfb011573dd045f17a',1935,'伪满洲国军热河省警备军团长','率伪军驻防承德、丰宁，多次参与对抗日根据地的“讨伐”，烧毁村庄，掠夺牲畜，在丰宁黑山嘴一带制造多起惨案。','基层头目','hanjian');
