INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('429d6e5eaad84e789847fb820b4a5e33','903927f67ccb4497af93b39c850dc3c8',1942,'伪热河省丰宁县协和会青年训练所所长','训练汉奸青年，灌输奴化思想，组织青年团协助日军巡逻，曾带领特务抓捕丰宁地区的地下党员，并参与破坏抗日交通线。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ab82b4bf09e640f283048c7a5fbb0058','908a861abb6f4307b72d53f1dd6a8f41',1933,'伪兴隆县县长','任伪兴隆县县长期间，积极推行日伪殖民统治，强征劳工，镇压抗日群众，协助日军实施‘集家并村’政策，制造‘无人区’。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('32b5df11a52c4a4eb90e10327dccc6c7','5f82d23ccd2e45fd9e59f76c92bcc9ad',1933,'伪蒙古军总司令（涉及热河）','投日后在热河地区（含承德、兴隆）协助日军作战，参与镇压抗日游击队，掠夺资源，为日军提供情报和兵力支持。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('122377d1a897489d91c8360972ea662d','ec26ab26d6bb4c4b8f8348f1bb125cd7',1935,'伪兴隆县警务科长','在兴隆地区组织伪警察队，抓捕抗日地下工作者，破坏抗日组织，参与‘清乡’行动，杀害多名抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1e4640889d044585854d798eabe29d08','3a9e402192aa460fb51a927d874bb93e',1938,'伪兴隆县保安团长','率伪保安团配合日军对兴隆山区进行反复‘扫荡’，烧毁村庄，强迫村民迁入‘集团部落’，致使大量平民死亡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('243d2c2b06524b2783d02e1086d1d20f','15aba61e822c4e50a3d0ac9384c005f1',1937,'伪承德县（含兴隆部分）维持会会长','投靠日军，组织维持会为日军征粮派款，提供劳役，并告密抗日分子，导致多名抗日人员被捕牺牲。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9f2524a8e03743a6a834234195a9b7a0','3f37dc5f28fd4441bdca3df489255cc2',1939,'伪热河省协和会兴隆分会主任','积极宣传‘日满亲善’，推行奴化教育，搜集抗日情报，协助日军实施‘三光政策’，在兴隆地区犯下罪行。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0137ca7e5a7140809a139cfaf1926951','6174377f7b5b49cda0a8bcbe33b2f2a6',1940,'伪兴隆县警察署署长','指挥伪警察多次突袭抗日村庄，逮捕并严刑拷打抗日群众，参与制造多起惨案，如‘狗背岭惨案’。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('93f5255455f74daf84b7564c261b1ac4','6a89fad0f513410089f90e82d3e7934f',1941,'伪兴隆县自卫团总团长','组织自卫团协助日军封锁山区，切断抗日武装补给线，并亲自带队搜捕抗日游击队员，杀害多名伤员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1a5a9d2bf02d4c1cbea3cb1b869d39f1','c40979e7b74a48469d46ce829371916b',1942,'伪兴隆县特务队长','充当日军特务，打入抗日组织内部，策反叛徒，导致兴隆地区多个地下联络站被破坏，数十名抗日人员牺牲。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ab692cf89a6545a29a5acd7a14e140db','4f4b8ce61e4545939068c55bb6b36057',1933,'热河省主席、伪满参议府参议','九一八事变后放弃热河抵抗，日军进攻承德时率部不战而逃，导致承德迅速沦陷；后投靠伪满洲国，任伪职，其旧部多被编入伪军，对承德及周边地区沦陷负有直接责任。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('93ecc77bd07940bc9c57f8c668f30008','83b067447f4744f7b527179c4d9524d4',1935,'伪冀东防共自治政府秘书长、代理主席','殷汝耕主要助手，参与伪冀东政权运作，在河北地区推行奴化教育与经济掠夺，后伪政权并入伪华北政务委员会，继续附逆。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2d17f841b8c541f79b45f2bf4fdfca9c','d2b840cc6fa142c8b5c30c100a11b64d',1938,'伪华北政务委员会绥靖总署督办、伪河北省长','曾任伪河北省长，在河北境内推行伪政，配合日军对承德及冀东、冀北地区进行治安肃正，掠夺资源，镇压民众抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('620ecdfaf7ad4b50b3c338ddc7a52f21','a23958f2a093468d8476a9eec1ddb6a8',1937,'伪河北省长、伪华北政务委员会委员','天津人，曾任伪河北省长，在河北地区推行亲日政策，协助日军维持占领区秩序，其辖区包括承德周边部分区域。；天津人，北洋政客，抗战期间投敌，任伪河北省长，其伪政权对河南北部地区有影响，推行日军殖民政策。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fa0d8e0fdc9e4d9db097c3783cd86cd2','bf398d44782c4c1594ef5ef1eecbf521',1938,'伪河北省长、伪华北政务委员会委员','在河北任伪职期间，推行保甲制度、经济统制与奴化教育，配合日军对冀东、冀北抗日根据地的扫荡，承德地区亦受其伪政影响。；抗战期间投敌，任伪河北省长等职，协助日军在河北推行殖民统治。；在河北伪政权中任职，配合日军扫荡抗日根据地，其伪政权与陕西周边抗日形势相关。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ded9d924dbf043248d7bad3343fcda45','e409ef959281461b91e8ce1eef37d186',1943,'伪河北省长、伪华北政务委员会要员','河北籍汉奸，任伪河北省长期间继续推行日军殖民政策，在河北各地包括承德周边强化治安，掠夺物资，镇压抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c7a2fa73b6c243189039d5182e8fa366','d6d76958ee164d75a29297b85ac0cbe2',1935,'伪冀东防共自治政府保安队长、伪军头目','长期在冀东及承德周边活动，率伪军配合日军扫荡，残害抗日群众，参与制造多起惨案。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6bfca9ca7a4c45d59a8c12b90c2fe073','dc8e7098d5c649d6a4fd9105da5d97f7',1933,'伪热河省警务厅厅长、伪满承德警察头目','在承德地区担任伪满警察要职，负责侦捕抗日人员，推行保甲连坐，镇压承德及双桥一带的抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9b27d1dcc3a14392a2893057e0e83975','ac60ab9d3fbd4dc298e96a4ed6ba2090',1933,'伪热河省民生厅厅长、伪满承德地方要员','在伪满热河省任职，参与承德地区的殖民行政与经济掠夺，推行奴化教育，协助日军维持统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8fa32a60ab104823999fb1afbc53fc81','9dc3aaa23c914c94acade8c943435489',1933,'伪热河省省长、伪满要员','首任伪满热河省长，在承德地区建立伪政机构，推行保甲制度，协助日军镇压抗日武装，掠夺地方资源。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('54d7c657072a4261a81b5f0f79ceacb7','5e3c03e59a9d4a4f81ce0c0f481fb548',1937,'伪热河省省长','继任伪热河省长，在承德及周边地区继续推行殖民政策，强化治安，配合日军扫荡冀热边抗日根据地。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1d77d70a8d614128ac4e36bc828a05e3','1eb3ba4bfbdd4b01a2c999042542f201',1940,'伪热河省省长','在承德任伪热河省长期间，推行经济统制与奴化教育，协助日军围剿抗日武装，镇压民众反抗。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d281417e358848be91d90275251fe1fe','39ce648a4b6a4e1b963e2aea5da2ab38',1943,'伪热河省省长','伪满末期热河省长，在承德地区继续执行日军殖民政策，强征劳工，掠夺物资，配合日军对冀热辽抗日根据地的扫荡。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('864e2bca303b496eb2cd1ffcdbf12744','fe7588d226fa430ea2eda3d08a162f2f',1933,'伪承德县县长','在伪满承德县任职，直接负责双桥及周边地区的伪政事务，推行保甲连坐，征发劳工，协助日军镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e170abcae7dd4cdf81fa921d1fd996ae','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满奉天市长、伪华北政务委员会顾问','原籍河北，后投靠日本，参与伪满政权建立，协助日本在华北推行殖民统治，镇压抗日力量。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1f99963a6a054b2487cea0290d066749','1ba31d558b934fbd83a28a8c2b446022',1933,'伪热河省省长、伪满军政部大臣','原东北军将领，投日后任伪热河省长，在承德地区推行奴化教育，强征劳工，配合日军清剿抗日武装。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('471a2d880ff143649385f2c8a7dc4ffa','236b09af126745e997e5603fc3f56d0e',1933,'伪满热河省次长（实际掌权者）','日本关东军指派，在承德地区实施“治安肃正”，组织汉奸特务网，逮捕抗日志士。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('157d55d25c9d41c4982de2b4108beff3','5e3c03e59a9d4a4f81ce0c0f481fb548',1933,'伪滦平县县长（双滦地区属滦平管辖时期）','在双滦一带组织“自卫团”，配合日军扫荡，杀害抗日干部和群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3e1ea88635dc4f31839ada0434cf5af8','9f7b3ed9c76f4eea8211fd8ebc40a461',1943,'伪华北剿共军司令（后期投敌）','虽为军阀出身，但在热河地区活动时曾与日军合作，其部队在承德周边参与“剿共”行动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e8ce7fef76614eb7b6e9ccabce328a87','c962700c3422426b946336b59832e9d0',1935,'伪热河省协和会会长','在承德地区组织协和会，宣传“日满亲善”，搜集抗日情报，破坏地下党组织。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('78eb974e6c814d25be019e59723b3ed7','77a789268c6f47b4a617cdb9e41180bd',1935,'伪满国务总理大臣（曾管辖热河）','虽为东北人，但作为伪满最高行政长官，对承德地区汉奸政权负有总责，支持日军在双滦的殖民统治。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9e7203243f9844a287ab9c7e9a0b868b','1d67ff455ffc47b8addcc485beb0ca34',1933,'伪满热河省警备军司令','在承德、双滦地区驻军，参与“讨伐”抗日义勇军和八路军，烧毁村庄，屠杀平民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7f3c694a63d941a1b8f78d8ba0b3e424','31abdc5e4e0a4ebdbe5f0b715a509863',1937,'伪华北政务委员会委员长（管辖热河西部）','虽非本地人，但其伪政权在承德部分地区推行“治安强化运动”，支持汉奸武装。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4a07477dec944d6790f82c94642efcd1','3e453d36fb8146cba1524ca1133da725',1933,'伪围场县县长','日军侵占围场后首任伪县长，协助日军建立保甲制度，组织清乡队搜捕抗日人员，强征粮食支援日军','基层头目','hanjian');
