INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('931272f43f9343d69b242e25ba2d6362','3e453d36fb8146cba1524ca1133da725',1933,'伪满洲国青龙县（含今宽城部分区域）县长','在宽城、青龙一带为日军效命，组织伪警察和保甲制度，参与“治安肃正”，围剿抗日游击队，强征民夫修建警备道路和碉堡。','基层头目','hanjian');
