INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a3b55762a4334427bb574ffab2e726b0','d3dbbce0f773495c95cf1c9896ca6b02',1935,'伪宽城协和会会长','在宽城地区宣传“日满亲善”，组织协和会分会，刺探抗日情报，强迫民众参加“勤劳奉仕”，为日军提供物资和人力。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('13fcc45816c64b40bf337f1c8d154059','bb8ae4dfd5a04cf1b42ef7cf977c3c3b',1937,'伪满洲国承德县警务科科长','在承德、宽城交界地区指挥伪警察队，多次袭击抗日根据地，杀害抗日干部和群众，并参与制造“无人区”行动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('78cf9f1ce8a74d88a69434a0e4e13494','1e22bb92ec6e4f95bc78f12dfec105f9',1939,'伪满洲国热河省特务机关宽城分室主任','为日本关东军特务机关效力，在宽城发展特务网络，破坏地下抗日组织，逮捕并杀害多名抗日志士。','基层头目','hanjian；traitors');
