INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('37ef6b75fcd94b719979d8434af67315','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满洲国立法院院长（曾任奉天市市长）','河北籍汉奸，积极投靠日本关东军，参与伪满洲国建立，协助日本殖民统治东北及热河地区。；原奉系人物，九一八后投靠日本，在铁岭地区活动，参与建立伪满政权，推行奴化教育，镇压反满抗日人士。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('56e6abd928ef4857ba4868cca20f68f6','1ba31d558b934fbd83a28a8c2b446022',1933,'伪满洲国热河省省长兼伪军司令','原东北军将领，1933年投敌，率部配合日军侵占热河（含承德），镇压抗日武装，为日本在承德地区推行殖民统治效力。','省部级/大军区级要员','hanjian');
