INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f5c700d7d3e4418d9eb21cd9ef37e440','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满洲国立法院院长、伪华北政务委员会顾问','原奉系官员，后投靠日本，参与伪满洲国建立，曾任伪立法院院长，后任伪华北政务委员会顾问，协助日本在华北推行殖民统治，涉及滦平地区日伪政权建设。；原为奉系军阀官员，后投靠日本，在伪满洲国及华北伪政权中任职，协助日本殖民统治，参与对河北、承德地区的资源掠夺和奴化政策。；原为奉系人物，后投靠日本，参与伪满洲国建立，并协助日本在华北推行殖民统治，曾到山海关一带活动','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ce21adf508e84350bbee7c26b758fb9c','87b0aba74b9b4c5f8a515bd9270d23b4',1931,'伪满洲国参议府议长、伪奉天省省长','东北沦陷后投敌，任伪满洲国要职，曾参与对热河省（含承德、滦平）的日伪行政规划与殖民统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f261cd878af34b5f851404547595868b','a984ebfabbf64a5b8e1dfef2d68daa53',1933,'伪满洲国热河省警务厅长','原东北军军官，投日后任伪热河省警务厅长，在承德、滦平一带组织伪警察，协助日军清乡、搜捕抗日人员。；原东北军军官，投敌后任伪警务厅长，负责清剿抗日力量，抓捕抗日志士。；原热河省警察头目，投日后负责伪警体系，参与抓捕抗日志士和镇压民众反抗。；原东北军军官，投敌后任伪警务厅长，参与围剿抗日游击队，抓捕抗日志士。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('24e8ce446224473a8af6c7436550044a','5f82d23ccd2e45fd9e59f76c92bcc9ad',1933,'伪蒙古军总司令、伪热河省保安司令','原热河地方武装头目，投日后任伪蒙古军总司令，参与日军对承德、滦平地区的军事占领，镇压抗日游击队。；原热河地方军阀，投靠日军后任伪蒙军首领，参与侵占承德、隆化，协助日军建立伪政权，镇压当地抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('58b3748b6baa4457ac36100c7a5ee001','3a9e402192aa460fb51a927d874bb93e',1933,'伪热河省滦平县县长','投靠日伪，任滦平县伪县长，推行日伪法令，征收苛捐杂税，协助日军建立“无人区”，迫害当地百姓。','基层头目','hanjian');
