INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7bd4b7e9b00940fb8926b251a4714e50','b9cce48e70ac415fb78d48afeaf84b30',1941,'伪沧县新民会顾问','为日军进行奴化宣传，在孟村等地建立伪新民分会，搜集抗日情报，协助日军推行“保甲制度”和“连坐法”。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f34b0bd00c804675ad9516670038e9a8','d6d76958ee164d75a29297b85ac0cbe2',1937,'伪沧州知事','日占时期任伪沧县知事，协助日军推行保甲制度，强征民夫，搜刮粮食，镇压抗日活动。；日军占领沧州后出任伪知事，协助日伪推行保甲制度，强征民夫修筑工事，镇压抗日民众。；投靠日军，任伪沧州知事，协助日军推行‘治安强化运动’，强征民夫、粮食，镇压抗日群众。；投靠日军，任伪沧州知事，协助日军推行治安强化运动，镇压抗日民众，征收苛捐杂税，为日军提供粮食物资。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b32c78da3fbf475d8cdbf7ca3c1267fe','b1303da80b994629ba3bf2748d8842c1',1938,'伪冀中剿共总司令（后投敌）','原国民党将领，后投靠日军，在沧州、新华一带组织伪军，配合日军扫荡抗日根据地，杀害抗日军民。；原国民党将领，后投靠日军，在沧县及周边组织伪军，配合日军扫荡抗日根据地，杀害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3592b3c64e874986b8debef2567772ca','6a89fad0f513410089f90e82d3e7934f',1938,'伪沧县保安队队长','率伪保安队多次袭击新华地区抗日武装，抓捕并杀害抗日干部，为日军提供情报。；组织伪保安队，为日军提供情报，抓捕抗日地下工作者，参与制造多起惨案。；任伪沧县保安队队长，协助日军维持治安，抓捕抗日地下工作者，参与多次清乡行动。','基层头目','hanjian');
