INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3d51777bcc494994a9fb111a3913fe5e','b13717d0c73e4b4dab35109ce0057aba',1937,'伪冀南道尹公署顾问','在邯郸地区协助日军推行治安强化运动，组织伪政权，镇压抗日力量。；在邯郸、广平一带协助日军推行‘治安强化运动’，组织伪警察和保甲制度，镇压抗日群众，征收苛捐杂税供给日军；原为国民党军将领，投日后任伪冀南道顾问，协助日军在邯郸地区推行治安强化运动，镇压抗日力量。；原为土匪武装头目，投日后任伪冀南道顾问，协助日军在邯郸地区推行“治安强化运动”，参与镇压抗日军民，征收粮秣供日军使用。','无明确职位或一般帮凶','hanjian');
