INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('893087588d984b7b922c13ae6d0b5831','7840583523b447a6999d9c07357583ec',1943,'伪魏县保安团中队长','多次率部袭击魏县抗日区公所，杀害区干部和民兵，抢夺抗日物资。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5e30d058f5b343278e3ac3022fe12f59','a2a33c8255fc4a2f89bc0416be0e6e0a',1938,'鸡泽县伪县长','投靠日军，任鸡泽县伪县长，协助日军推行“治安强化运动”，强征粮税，镇压抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6219f34f7801478cacc15aff898be615','102db9e5c6744a65ae8e91478952c456',1940,'鸡泽县伪保安联队队长','组建伪保安队，配合日军扫荡抗日根据地，抓捕抗日军民，烧杀抢掠。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4804a43aa75d46e3b117a76e0e89a3ce','14373ea89db7402e8d7f44750e55add3',1941,'鸡泽县伪警察所所长','效忠日军，负责伪警察事务，搜捕抗日地下人员，破坏抗日组织。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9847cbc65e3841b1b8aec61b871c93a4','4d321af5127c44468420029ab1db0e2d',1942,'鸡泽县伪自卫团团长','组织伪自卫团，为日军提供情报，参与“清乡”行动，残害抗日家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c77aa9ed7d234c2391ed539216091a77','98806a70e2a5421093e5f8e97c85b408',1938,'鸡泽县伪维持会会长','日军占领初期出任维持会长，为日军征粮派款，强迫民众“欢迎皇军”，协助建立伪政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0249fdc4287b4bca8d5d03cf68a6ec82','82c8dc8c68f3449d85ce6770c252b411',1939,'邯郸县伪县长（兼辖鸡泽部分地区）','在邯郸伪政权任职期间，参与对鸡泽等县的“扫荡”协调，强征民夫修筑炮楼公路。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e854a2b23b0d4f9b979baf01a22fc28c','ea44bfcd495e4842a2a25b453a384985',1940,'冀南伪军暂编第三旅旅长（活动于邯郸、鸡泽一带）','率伪军多次进攻鸡泽抗日根据地，杀害抗日干部，抢劫物资，是当地著名汉奸武装头目。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c7602ca91b954a3e9abf5ea93ed92aab','dd050a597c56463d815aa78b9b3bce7c',1941,'邯郸地区伪军独立团团长（活动范围含鸡泽）','依附日军，在鸡泽、永年等地烧杀抢掠，抓捕壮丁，配合日军“铁壁合围”。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('285173c746124322a01bb04e8a33f4c7','a36adf024ce44c63a7d6f7c343eb3712',1944,'伪陕县维持会会长','日军占领陕县后出面组织伪维持会，协助日军征粮、派夫，维持占领区秩序。；日军侵占陕县后，出面组织伪维持会，协助日军征粮、派夫、维持地方秩序，为日军统治服务。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ca8f34de97f142a6b942ba79c20b319b','a83acb9158ad44ebb26430cc363bbc42',1944,'伪陕县公署知事','任伪陕县公署知事期间，推行日军政令，配合清乡、征发劳工和物资。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a3bf1d0fae764638a83faeac22f43ad1','7dd0dfd982f44fe78f68670843ac79ae',1944,'伪陕县警察局局长','组建伪警察队伍，协助日军搜捕抗日人员，镇压地方反抗。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('22c4b2cd22114922b043160206f4751a','be101ae50c01499eb4d1ad9af8d79b62',1938,'伪灵宝县维持会会长','在灵宝地区组织维持会，为日军筹粮筹款，诱降地方武装。；在灵宝地区组织伪维持会，为日军筹粮筹款，诱降地方武装。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1229967105794b74889296b3f41e3bc4','0c9d9be7baba497bac5b4c4c48d4839b',1944,'伪渑池县公署知事','任伪渑池县知事，协助日军建立基层伪政权，推行保甲连坐。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('452b27c253bf4e9fbaf4c7d443095759','4c82265eb03f426ba59d5587412f13e3',1944,'伪卢氏县维持会副会长','参与组织伪维持会，为日军提供情报和物资，破坏抗日根据地。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('eb5c2815a697417896fcbb0b2b09639a','9f7b3ed9c76f4eea8211fd8ebc40a461',1943,'伪新编第五军军长（降日）','率部投降日军，所部被编为伪军，在豫西、豫北配合日军进攻抗日武装。；1943年在河南林县率部投降日军，被编为伪军，配合日军进攻抗日根据地，活动范围涉及豫北及豫西。；1943年率部投降日军，所部驻防豫西、豫北一带，配合日军进攻抗日根据地，活动范围覆盖三门峡周边。；1943年在河南林县率部投降日军，所部被编为伪军，活动于豫北、豫西一带，配合日军进攻抗日根据地。；原国民党军将领，1943年在河南林县率部降日，所部被编为伪军，活动于豫北、豫西一带，配合日军进攻抗日根据地。；1943年率部投降日军，所部驻防豫西，配合日军进攻抗日根据地，后任伪军要职。；1943年率部投降日军，驻防豫北新乡、辉县一带，配合日军进攻抗日根据地。；1943年在河南林县被日军包围后投降，所部被编为伪军，活动于豫北新乡、辉县一带，配合日军进攻抗日根据地。；原国民党军将领，1943年在河南林县被俘后降日，任伪军军长，配合日军进攻抗日根据地。；1943年率部投降日军，所部被编为伪军，在河南洛阳、汝阳及豫西地区配合日军作战，进攻抗日根据地。；原国民党将领，1943年降日，所部被编为伪军，在河南林县、郑州以北地区配合日军作战。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4823ecf469554f0fab4051b9acc1d7d5','5ec2ad124b2f429482b1a90a7f8d4a92',1943,'伪第二十四集团军总司令（降日）','被俘后投降日军，任伪职，在河南北部及豫西地区协助日军维持治安、进攻八路军。；1943年在河南林县投降日军，任伪军总司令，协助日军扫荡豫北抗日根据地。；1943年降日，被汪伪政权任命为伪军头目，所部在豫北、豫西活动，与日军协同作战。；1943年在河南投降日军，任伪军总司令，率部配合日军在豫北、豫西地区扫荡抗日武装。；原国民党军将领，1943年在河南降日，任伪职，率伪军配合日军在豫北、豫西地区作战。；1943年投降日军，任伪职，其势力范围涉及豫北及豫西，协助日军维持占领区。；1943年在太行山被俘后投降日军，任伪军总司令，驻防豫北，其部队在新乡、辉县地区协助日军维持治安、清剿抗日武装。；原国民党军将领，1943年在河南林县降日，任伪军总司令，协助日军扫荡豫北。；1943年投降日军后，任伪职，在河南北部及豫西一带指挥伪军配合日军扫荡，其势力范围涉及洛阳周边。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6049a024f95644e1944fb0a317ca75ee','2bd76bd4f7874f8f8becd896967ac4f3',1940,'伪河南剿共军司令','在豫西地区组织伪军，配合日军扫荡，残害抗日军民。；在河南沦陷区组织伪军，配合日军扫荡抗日武装，活动于豫中、豫西一带，包括平顶山附近地区。；在豫北地区组织伪军，配合日军进攻抗日根据地，活动范围包括焦作周边。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dc39b34d7aea4d8bb9d244c730c96717','b77a9c0384c94aa5bcd13e6c90ce35f9',1943,'伪河南省政府委员','在伪河南省政府中任职，参与制定和推行日伪在河南的统治政策。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('31d61f815eb14e7aafddfdac04fada57','793dba30c5cd4e9ab0835412a8dc7906',1938,'伪河南省政府省长','任伪河南省省长，全面推行日军政策，征粮征兵，镇压抗日活动。；在日军扶植下出任伪河南省长，推行殖民统治政策，其政令下达至信阳等沦陷区，配合日军经济掠夺与清乡。；抗战初期投敌，1938年任伪河南省政府省长，在日军占领的豫北、豫东地区建立伪政权，协助日军维持治安、征粮征税，其伪省政权名义上管辖河南全境，对南阳、新野地区有行政上的关联。；日军占领河南后出任伪河南省长，在开封、安阳等地推行伪政，为日军征发物资、劳工，协助维持沦陷区统治。；继萧瑞臣后任伪河南省长，依附日军维持伪政权，配合日军对豫北包括新乡地区的控制与掠夺。；曾任伪河南省长，协助日军推行保甲、征粮、清乡等政策。；继萧瑞臣后任伪河南省长，配合日军“治安强化运动”，在河南沦陷区推行保甲连坐，搜刮物资，镇压抗日群众。；继萧瑞臣后任伪河南省省长，配合日军在河南的殖民统治，推行治安强化运动。；继萧瑞臣后任伪河南省长，配合日军“治安强化运动”，镇压抗日力量。；继萧瑞臣后任伪河南省长，配合日军征粮、征丁，推行治安强化运动。；继萧瑞臣后任伪河南省省长，推行伪化教育、征粮征丁，配合日军扫荡。；抗战期间任伪河南省政府省长，驻开封，其伪政权名义上管辖河南全境，包括洛阳地区，推行日伪统治政策。；继萧瑞臣后任伪河南省长，配合日军维持占领区秩序，推行保甲、征粮、奴化教育等。；抗战初期出任伪河南省政府省长，在豫北、豫东一带为日军维持伪政权，其伪政令曾下达至漯河周边地区。；抗战期间任伪河南省省长，主持伪省政，推行日军殖民统治政策，其伪政权覆盖濮阳地区。；曾任伪河南省省长，推行日军政策，协助征粮征丁，镇压抗日力量。；抗战期间任伪河南省省长，主持伪省政，推行日军殖民统治政策，其伪政权体系覆盖许昌、襄城等县。；抗战期间任伪河南省政府省长，驻开封，统管伪政权事务，其政令覆盖郑州等地，协助日军维持占领区统治。；抗战期间任伪河南省政府省长，驻开封，为日军在河南的殖民统治服务，推行伪化政策，协助征粮征丁。；继萧瑞臣后任伪河南省省长，配合日军进行治安强化运动，镇压抗日力量。；继萧瑞臣后任伪河南省长，协助日军推行治安强化运动，镇压抗日力量，搜刮民财。；抗战初期在日伪河南省政权中任省长，驻开封，统辖包括郑州在内的豫中、豫东沦陷区伪行政事务，推行日军殖民统治政策。；日军侵占河南后出任伪河南省政府省长，参与组织伪政权，协助日军征粮、征夫，镇压抗日活动。；抗战期间任伪河南省政府省长，驻开封，协助日军推行伪政，征发粮款、维持治安，其伪政权体系延伸至驻马店、上蔡等县。；抗战期间任伪河南省长，主持伪省政，推行日军殖民统治政策，征粮征丁，其政令下达至驻马店、遂平一带。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4ca81e6bcd7944c5a47e99e7af51dbfd','fcb3e5ff966f4327a818cbc1e3244da5',1938,'伪河南省警务厅厅长','统管伪警察系统，在河南各地搜捕抗日人员，实施恐怖统治。；掌管伪河南警务，镇压抗日活动，抓捕抗日人员。；掌管河南伪警察系统，督导信阳等地伪警察协助日军搜捕抗日人员、维持占领秩序。；掌管河南沦陷区伪警察系统，督导信阳等地伪警务，镇压抗日活动。；在伪河南省政府任职，掌管伪警察系统，在河南沦陷区搜捕抗日人士，镇压民众反抗，配合日军维持殖民统治。；抗战期间投敌，任伪河南省警务厅厅长，统管伪警察系统，配合日军在河南各地包括南阳、方城进行治安强化运动。；在伪河南省政府中主管警务，督导包括商丘在内的各地伪警察局镇压抗日活动、搜捕抗日人员。；掌管河南沦陷区伪警察系统，在安阳等地搜捕抗日人士，镇压民众。；在伪河南省政府任职期间，统管全省伪警察，镇压抗日活动，其警务系统覆盖平顶山、宝丰地区。；掌管河南伪警察系统，在洛阳等地设立伪警察机构，镇压抗日活动。；掌管伪河南警务，在漯河、许昌等地设立伪警察机构，配合日军清乡、扫荡，镇压抗日群众。；负责伪河南省警务，在豫北焦作、修武等地设立伪警察机构，镇压抗日群众。；统管伪河南警务，指挥许昌等地伪警察搜捕抗日人员、破坏地下组织。；在河南推行伪警察统治，参与抓捕抗日人员，其活动范围与陕西邻近。；在河南地区协助日军建立伪警察系统，镇压抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3bb9b0f6aca5471cabcdf77f63300efa','d409a62a1fcf424a82d99abd16ad9bea',1938,'伪开封市维持会会长','在开封组织维持会，为日军筹办物资、招募劳工，协助建立伪政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f007b47bb2174b5f939fa3b735645597','342fa3388ae7472fb6629b24e1da04d5',1938,'伪豫北道尹','任伪豫北道尹，管辖豫北地区，推行日伪法令，配合日军扫荡。','无明确职位或一般帮凶','hanjian');
