INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e7a5e3a9f3104b168b716441c46719ef','bcff0d550ff5447c897225054e9f13b3',1939,'伪信阳县知事/伪信阳县政府县长','在日军扶植下出任伪信阳县政权头目，推行保甲连坐，配合日军清乡、征粮、抓丁，镇压抗日群众，活动范围覆盖信阳城区及浉河一带。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8a59991eab25493c8ae7e15c0b8b503e','0c9d9be7baba497bac5b4c4c48d4839b',1939,'伪信阳县警察局局长','掌管伪警察系统，在信阳城区及浉河沿岸设立检查哨，盘查行人、抓捕抗日嫌疑人员，协助日军维持殖民统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('710f9b8acc1e43139709f9f6ce91dbe5','1739f5bd20744c40ae42338925b39576',1938,'伪信阳县商务会会长','作为商界附逆代表，为日军筹款筹物，强制商户摊派物资，协助日军对信阳城区经济进行掠夺与控制。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('193094f95d564ea193fc6c217135fc19','7afda6e05b9949d28074a369c144b4b0',1940,'伪信阳县教育科科长','在信阳推行奴化教育，改编教材宣扬“大东亚共荣”，组织教师参加亲日培训，毒化沦陷区青少年。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7f04a6fd7d8942adbae2db779b548914','759cfb5f46624562bc0d114d5292cbca',1938,'伪信阳县城关镇维持会会长','在信阳城关及浉河沿岸组织维持会，为日军带路、指认抗日人员家属，征派民夫修筑工事。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1e47e22070eb4e89a499a47edd2a9a09','113aa564979f44a3a077b798eaeab07f',1939,'伪豫南道尹公署道尹','统辖豫南伪政权，包括信阳一带，推行日军政令，组织伪军配合扫荡，掠夺粮食棉花等战略物资。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a61c0334e39f456494b18cc08307936e','848992e841c9488c8cdcf56cad9f079c',1938,'伪和平救国军第一军军长、伪豫东剿共军总司令','率伪军在豫东、豫南包括信阳周边配合日军作战，参与扫荡抗日根据地，收编土匪扩充伪军。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0cff788e32d248aea7de6624b07152fa','63006a4879fb4f49ad97a1e88c8c5d69',1942,'伪和平救国军第二方面军总司令、伪开封绥靖公署主任','率部投敌后驻防河南，其伪军活动范围涉及豫南信阳一带，配合日军清乡、扫荡，镇压抗日武装。；天津人，1942年投敌，率部在豫东、豫南一带配合日军作战，其伪军曾活动于南阳周边地区。；原西北军将领，1942年率部投敌，任伪第二方面军总司令，驻防河南开封、商丘一带，配合日军扫荡豫东、豫南抗日武装，其势力范围涉及南阳周边地区。；原西北军将领，1942年投敌，率部驻防豫东、鲁西，在周口、鹿邑一带配合日军扫荡，后任伪开封绥靖公署主任。；原国民党将领，1942年率部投敌，所部活动于豫东、豫北一带，配合日军进攻抗日根据地，是河南伪军主要头目之一。；率部投敌后驻防豫东、豫北，其伪军活动范围包括商丘、民权一带，配合日军进攻抗日根据地，残害民众。；原国民党将领，1942年率部投敌，所部驻防河南开封、商丘等地，配合日军扫荡，后任伪开封绥靖公署主任，控制豫东地区。；原国民党将领，1942年率部投敌，任伪军要职，其部队活动于河南开封、洛阳周边地区，配合日军进攻和维持占领区秩序。；原国民党将领，1942年率部投敌，所部驻防河南开封、漯河、郾城周边地区，配合日军“扫荡”和维持伪政权统治。；原国民党将领，1942年率部投敌，任伪第二方面军总司令，驻防河南开封、濮阳一带，配合日军扫荡冀鲁豫抗日根据地。；原国民党将领，1942年率部投敌，任伪第二方面军总司令，驻防开封、濮阳、东明一带，配合日军扫荡冀鲁豫抗日根据地，其伪军活动范围覆盖濮阳及南乐周边地区。；原国民党将领，1942年率部投敌，任伪第二方面军总司令，驻防河南开封、濮阳一带，配合日军扫荡冀鲁豫抗日根据地，1945年任伪开封绥靖公署主任。；原国民党将领，1942年率部投敌，所部驻防河南开封、濮阳一带，配合日军扫荡冀鲁豫抗日根据地。；原国民党将领，1942年率部投敌，任伪职，驻防河南开封、濮阳一带，配合日军扫荡冀鲁豫抗日根据地。；原国民党将领，1942年率部投敌，任伪职，驻防河南开封、许昌一带，配合日军扫荡豫中抗日力量。；原国民党将领，1942年率部投敌，所部驻防河南开封、许昌一带，配合日军维持伪政权统治，参与对抗日武装的作战。；率部投敌后驻防河南，配合日军对豫中地区进行扫荡，控制包括许昌在内的多个县份。；原西北军将领，1942年在鲁西投敌，所部伪军活动于豫东、豫北及开封、郑州一带，协助日军维持占领区治安并进攻抗日武装。；原西北军将领，1942年率部投敌，任伪军第二方面军总司令，驻防河南开封、郑州一带，配合日军扫荡抗日武装。；原西北军将领，1942年率部投敌，任伪军要职，活动于河南开封、郑州及豫东地区，配合日军扫荡抗日武装。；原国民党将领，1942年率部投敌，驻防开封、郑州一带，配合日军扫荡豫中抗日力量，1944年豫中会战后协助日军控制郑州地区。；原国民党将领，1942年率部投日，所部伪军活动于河南开封、商丘、周口及驻马店周边地区，配合日军扫荡、征粮、清乡。；原国民党将领，1942年率部投敌，所部伪军驻防豫东、豫南及驻马店一带，配合日军扫荡，后任伪开封绥靖公署主任，统辖河南伪军。；原国民党将领，1942年率部投敌，所部伪军驻防河南开封、商丘及豫南部分地区，配合日军对河南抗日力量进行扫荡，其势力范围涉及驻马店周边。；原西北军将领，1942年率部投敌，任伪第二方面军总司令，驻防开封、商丘及豫东、豫南地区，配合日军扫荡，其伪军活动范围涉及驻马店、正阳一带。；原国民党将领，1942年率部投敌，所部活动于河南开封、商丘、周口及豫南部分地区，配合日军“扫荡”和维持伪政权统治。；原国民党将领，1942年率部投汪伪，任伪第二方面军总司令，驻防河南开封、驻马店、信阳一带，配合日军扫荡豫南抗日武装，强征民夫、粮食。；原西北军将领，1942年率部投敌，所部驻防河南开封、商丘及豫南一带，配合日军“扫荡”抗日武装，控制沦陷区。；原国民党将领，1942年率部投敌，所部伪军在河南境内配合日军作战，活动范围覆盖豫中、豫南，对驻马店、西平一带抗日力量构成威胁。；原国民党将领，1942年率部投敌，所部伪军活动于河南开封、商丘、周口及豫南一带，对驻马店周边地区有军事控制与征敛。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f94f0567a8a94c35aebe9541fa7888a6','5ec2ad124b2f429482b1a90a7f8d4a92',1943,'伪和平救国军第二十四集团军总司令、伪河南省政府主席','投降日军后任伪河南省政府主席，统辖河南伪政权，其政令覆盖信阳地区，协助日军征粮征丁、扫荡抗日力量。；原国民党河北省政府主席、第二十四集团军总司令，1943年在河南林县被俘后投敌，任伪和平救国军第二十四集团军总司令，后兼任伪河南省政府主席，协助日军维持河南沦陷区统治，其伪政权名义上管辖河南全境，对南阳、新野地区有行政关联。；原国民党河北省主席、第二十四集团军总司令，1943年被俘后投敌，任伪职，其伪军活动范围涉及豫北、豫东，对河南沦陷区伪政权的维持负有责任。；原国民党河北省主席、第二十四集团军总司令，1943年被俘后投敌，任伪河南省政府主席，统辖河南伪政权，其政令覆盖豫东商丘等地。；原国民党军将领，1943年在河南投敌，任伪军总司令及伪河南省主席，其伪政权和伪军系统覆盖河南沦陷区，包括商丘、虞城一带。；河北新河人，1943年在豫北投敌，任伪河南省政府主席，统辖伪军配合日军控制河南沦陷区，包括平顶山一带的伪政权运作。；1943年在河南投敌，任伪河南省政府主席兼伪军总司令，在河南境内协助日军推行伪化统治，其伪政权名义上管辖包括平顶山、汝州在内的豫中、豫西地区。；投日后在河南境内协助日军，参与伪政权与伪军活动，影响开封周边地区。；原国民党河北省政府主席、第24集团军总司令，1943年在河南林县被俘后投敌，任伪河南省政府主席兼伪军总司令，其伪政权名义上管辖河南全境，包括洛阳地区。；原国民党河北省政府主席、第二十四集团军总司令，1943年在河南林县被俘后投敌，任伪第二十四集团军总司令、伪河南省政府主席，其伪政权与伪军活动涉及豫北、冀南交界地区，与濮阳、南乐一带的日伪统治有联系。；原国民党河北省政府主席，1943年被俘后投敌，任伪河南省政府主席，其伪政权管辖范围包括豫北濮阳等地。；原国民党河北省政府主席，1943年投敌，任伪河南省政府主席等职，在豫北、濮阳地区协助日军维持统治。；原国民党河北省政府主席，1943年被俘后投敌，任伪河南省政府主席等职，在河南境内协助日军维持伪政权，影响涉及许昌地区。；在河南率部投敌，出任伪河南省政府主席，推行日军政令，其伪政权覆盖许昌、长葛等地。；原国民党河北省政府主席，1943年在太行山被俘后投敌，任伪河南省政府主席等职，在开封、郑州等地参与伪政权统治。；原国民党河北省政府主席，1943年被俘后投敌，任伪军第二十四集团军总司令，后兼伪河南省政府主席，在豫北、豫西地区为日军效力。；原国民党河北省政府主席、第24集团军总司令，1943年在河南林县被俘后投敌，任伪河南省政府主席兼伪军总司令，在河南境内协助日军维持统治。；原国民党河北省政府主席、第二十四集团军总司令，1943年在河南林县被俘后投降日军，任伪河南省政府主席等职，在河南沦陷区推行伪政。；原国民党河北省政府主席，1943年被俘后投敌，任伪河南省政府主席，驻开封，其伪政权势力覆盖郑州、荥阳等豫中地区。；原国民党河北省政府主席，1943年被俘后投日，任伪职，其伪政权与伪军势力覆盖河南部分地区，包括豫南、豫东一带。；原国民党河北省政府主席、第二十四集团军总司令，1943年在河南林县被俘后投敌，任伪河南省政府主席等职，其伪政权名义上管辖河南全境，包括驻马店地区。；原国民党河北省政府主席、第二十四集团军总司令，1943年在河南林县被俘后投敌，后任伪河南省政府主席等职，其伪政权体系对河南各地包括豫南地区产生控制影响。；原国民党河北省主席、第二十四集团军总司令，1943年在河南林县被俘后投敌，任伪河南省政府主席、伪集团军总司令，其伪政权名义上管辖河南全省，包括驻马店、泌阳地区，协助日军维持占领区秩序。；原国民党河北省政府主席，1943年被俘后投敌，任伪河南省政府主席，其伪政权统辖河南沦陷区，驻马店、西平地区在其名义管辖范围内。；原国民党河北省政府主席，1943年被俘后投敌，任伪职，其伪政权与伪军势力覆盖河南部分地区，包括豫南。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f93b9fd820c1478fb81f66aebd5ba82d','fcb3e5ff966f4327a818cbc1e3244da5',1938,'伪河南省政府警务厅厅长','掌管河南伪警察系统，在信阳等地设立警察机构，训练伪警察，配合日军搜捕抗日人员、镇压民众反抗。；河南人，抗战后投敌，在伪河南省政府任警务厅厅长，负责全省伪警察系统，在周口、扶沟等地设立伪警察所，推行保甲连坐。；掌管伪警察系统，在开封及周边县镇搜捕抗日人员，镇压民众反抗。；伪河南省警务头目，负责组建伪警察队伍，在驻马店、平舆等地设立伪警察所，镇压抗日群众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c395941dcffd4b38b6d5726f35e12aa8','a2a33c8255fc4a2f89bc0416be0e6e0a',1938,'伪信阳县柳林镇维持会会长','在信阳南部柳林一带组织维持会，为日军提供情报、带路扫荡，征派粮草民夫，迫害抗日家属。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('72e4d50cfe6e41b48931b31bffcff3ba','e49f8a9dadbe44b5bce22cf81a128c5f',1938,'伪信阳县东双河维持会会长','在东双河及浉河沿岸地区为日军征粮征夫，组织伪自卫团配合日军巡逻，搜捕抗日游击队员。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e6a98c64eefa4f5c99344f95633a1f9c','bcff0d550ff5447c897225054e9f13b3',1938,'伪信阳县知事、伪信阳县政府县长','在日军扶植下出任伪信阳县政权头目，推行保甲连坐，配合日军清乡、扫荡，强征粮食和壮丁，镇压抗日活动。；在日军扶植下出任伪信阳县政权头目，推行保甲连坐，配合日军清乡、征发民夫粮秣，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aa05c20620b840a6a4889456850c9fb9','2159de38efb94153bd3d92638438b38a',1939,'伪信阳县政府警察局局长','掌控伪警察力量，搜捕抗日人员及嫌疑民众，协助日军维持占领区治安，参与破坏中共地下组织和抗日群众团体。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0b7fd93be8a84f258da5189bcfd5ffc6','69073b7113c34f488a2a46688d7f9a56',1940,'伪信阳县保安团团长','统率伪保安团配合日军对信阳周边抗日根据地和游击区进行扫荡，抢掠民财，捕杀抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('38d2c46e3a78434b9aff460b049085f2','0c9d9be7baba497bac5b4c4c48d4839b',1938,'伪淮滨地区维持会会长（伪乌龙集维持会）','在淮滨（时属息县、固始交界之乌龙集一带）组织维持会，为日军筹集物资、情报，协助建立伪基层政权，压迫当地民众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('43ee0b2d8c484ff69c774608188fe1f9','7afda6e05b9949d28074a369c144b4b0',1938,'伪息县县政府县长（日占时期）','日军侵占息县期间附逆出任伪县长，管辖范围涉及今淮滨部分地区，推行伪化教育、征粮征夫，配合日军统治。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('033da8db8ca840f1a56ca95b035794d2','721765fe1d8b4abd90897b852d09de4a',1938,'伪固始县维持会副会长、伪固始县政府要职','在固始及邻近淮滨地区协助日军建立伪政权，组织伪自卫团，参与对抗日武装的封锁和清剿。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e64135940bdb420f8be29f5c1de87e9f','8528c2945ee544578dfd38e96bf95218',1938,'伪潢川县维持会会长','在潢川沦陷期间组织维持会，为日军提供情报和物资，协助日军控制豫东南交通线，镇压民众反抗。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('abb61d158aac471ca515097e92c2723d','03d23edca05d48e78bf195e9468f7ec7',1938,'伪河南省政府委员、伪豫南道尹','在伪河南省政权中任职，负责豫南地区伪化行政，督导信阳、潢川、固始等县伪政权建设，配合日军统治豫南。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b57a5d21e3b041daa28a05036b9764b3','fcb3e5ff966f4327a818cbc1e3244da5',1938,'伪河南全省警务处处长、伪河南省政府警务厅厅长','统管伪河南警务，在信阳等沦陷区建立伪警察网络，搜捕抗日人士，协助日军维持占领秩序。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8fb7805f3cef4e8e916e8e095b1b6708','8f723085f177405d820bf765fb08fd13',1941,'伪豫南剿共军司令','率伪军配合日军在信阳、罗山、息县、淮滨一带清乡扫荡，进攻抗日根据地，残害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2fa2222b20664b83a655d5d984f6f14f','66634d7e373a4c188b41364f4bd19166',1938,'伪信阳县教育科科长','在信阳沦陷区推行奴化教育，篡改教材，宣传“中日亲善”“大东亚共荣”，毒化青少年思想。；在信阳推行奴化教育，改编教材宣扬“中日亲善”“大东亚共荣”，组织师生参加日伪宣传活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4a3bec8faf27475885fef2a46d17fdcf','e49f8a9dadbe44b5bce22cf81a128c5f',1938,'伪信阳县商会会长','控制信阳沦陷区商业，为日军采购军需物资，协助经济掠夺，压榨商户和民众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e904cc1c149a4c78a90e774c08b4c02c','4dd386edc4914c76aea752c6b364c341',1940,'伪淮滨乌龙集保甲长、情报员','在淮滨地区担任伪保甲长，为日军搜集抗日武装情报，带领日伪军搜捕抗日人员，催缴粮款。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b537ae7ee30746c6b81e1ba2821b40ec','442e352824804acaab2b5d5fd7dda75e',1938,'伪潢川县维持会会长、伪潢川县知事','日军侵占潢川后出面组织伪维持会，后任伪县知事，为日军征粮派款、维持伪秩序，协助日伪统治潢川地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b5b9c5235e5044088f0fff81634fae52','ce41d9e7f6e44b88990076d4306704a4',1939,'伪潢川县保安团团长','在潢川一带收编土匪、游杂武装，组成伪保安团，配合日军扫荡抗日根据地，镇压抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('50433dc201d545fbbade47f1f653737a','cd6bd8e57e4147f5b633a46a11754965',1938,'潢川伪军头目','率部投靠日军，在潢川、光山交界地区活动，为日军带路、侦察，袭击抗日游击队。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('91c13298fb234196a5f594548a88e71f','83ce1a1a0f6a4a88a73055925785f9fa',1938,'伪信阳县维持会会长','信阳沦陷后组织伪维持会，后任伪信阳县知事，推行日军殖民统治，强征民夫、粮食供给日军。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6cc5fb566f1047c48ce5bb8bc5b503ca','e49f8a9dadbe44b5bce22cf81a128c5f',1939,'伪信阳县保安大队大队长','在信阳地区组建伪保安大队，配合日军对信阳南部山区进行清乡扫荡，捕杀抗日人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c31b827444b24128a60ac8d8f532fa83','be101ae50c01499eb4d1ad9af8d79b62',1940,'伪信阳县政府警察局局长','掌管伪警察局，在信阳城区及近郊搜捕抗日志士，勒索商民，为日军提供情报。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('29c7124ffaba40c5bdf1da7284b1efd5','b6e48bbf374c47cdadfa90d188c355fc',1939,'伪豫南道尹公署道尹','任伪豫南道尹，管辖信阳、潢川等县伪政权，推行日军“治安强化运动”，统筹征粮、征兵、清乡。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('81b51a8148bc44408545f4c712391ef3','d492b175c0d2433d82d0b823bf81a6ef',1940,'伪河南省政府委员兼豫南办事处主任','代表伪河南省府在豫南地区协调各县伪政权，督促向日军供应物资，参与对抗日根据地的经济封锁。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e6f9a58e74fe4ac597cf2183edab543a','9f7b3ed9c76f4eea8211fd8ebc40a461',1943,'伪新编第五军军长（后投日）','1943年率部投靠日军，所部在豫北、豫南一带配合日军行动，其势力范围曾覆盖信阳以北地区。；1943年在河南林县投日，所部被编为伪军，在豫北、豫东一带配合日军行动，其势力曾影响周口周边。；河南永城人，抗战后期投靠日军，所部在豫东周口、商丘一带活动，配合日军进攻抗日武装，危害地方。；原为国民党军将领，1943年在河南投靠日军，所部被编为伪军，在豫东、豫北一带配合日军行动。；原国民党军将领，1943年在河南林县投敌，所部被编为伪军，活动于豫北、豫东一带，配合日军作战。；原国民党军将领，1943年在河南林县投日，所部被编为伪军，活动于豫北、豫东一带，配合日军进攻抗日根据地。；原国民党军将领，1943年投敌，所部驻防豫北林县、安阳一带，配合日军进攻太行抗日根据地。；1943年投敌，所部在豫北安阳、林县一带配合日军行动，后任伪军职。；原为国民党军将领，1943年在豫北被俘后投敌，所部被编为伪军，在安阳、林县一带配合日军行动。；原国民党将领，1943年投敌，所部被编为伪军，活动于豫北新乡一带，配合日军进攻抗日根据地。；原国民党军将领，1943年在河南林县投敌，所部被编为伪军，配合日军进攻太行抗日根据地，活动范围包括豫北新乡一带。；原国民党将领，1943年在河南林县投敌，所部被编为伪军，活动于豫北包括新乡一带，配合日军进攻抗日根据地。；1943年率部投日，所部活动于豫北太行山南麓，配合日军进攻抗日根据地，其势力范围覆盖焦作、博爱一带。；1943年投靠日军，所部在豫北焦作、新乡一带配合日军行动，后任伪军要职。；1943年在豫北率部投靠日军，所部被编为伪军，配合日军进攻太行抗日根据地，活动范围包括焦作、沁阳一带。；1943年投靠日军，所部在河南驻马店、新乡一带配合日军作战，进攻抗日根据地。；1943年率部投敌，被编为伪军，在豫北、太行山南麓配合日军进攻抗日根据地，其活动范围包括鹤壁周边。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('072df23ca0b74e46bcdd636ebf8720ee','5ec2ad124b2f429482b1a90a7f8d4a92',1943,'伪暂编第二十四集团军总司令','1943年投日，所部在河南境内配合日军作战，其伪军活动范围包括豫南信阳周边地区。；1943年在河南投日，任伪军总司令，在豫北、豫东地区配合日军扫荡，其伪军活动范围涉及周口周边。；原国民党河北省主席、第二十四集团军总司令，1943年在河南投日，任伪军总司令，活动于豫北、豫东地区。；原国民党河北省政府主席、第二十四集团军总司令，1943年在河南林县投敌，率部伪化，活动于豫北地区。；1943年投敌，在豫北、焦作地区协助日军维持伪化统治，进攻抗日武装。；1943年投敌后，在豫北包括焦作地区协同日军作战，进攻八路军，残害抗日群众。；1943年投降日军，在河南境内包括驻马店周边地区率伪军配合日军扫荡，镇压抗日力量。；1943年投敌，率部在豫北、太行山区配合日军扫荡，其伪军活动涉及鹤壁、安阳、新乡一带。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('22bfb7e6e9994d689667409a14b971a5','2bd76bd4f7874f8f8becd896967ac4f3',1939,'伪潢川县教育科科长','在潢川推行奴化教育，强制学校使用日伪教材，组织师生参加亲日宣传活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4dd836e7b24c4f0cbf040e54935d48fe','906dcc78f8af418eac9b54e7cf19fa8f',1938,'伪潢川县商会会长','控制潢川商会，为日军筹款筹粮，强制商户交纳“治安费”，协助日军经济掠夺。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b1bb62713b9a46aba7e69a112a9193c4','8d8fd50571324b678226b9a4e8030574',1938,'伪信阳县保甲长、维持会骨干','在信阳城郊担任保甲长，为日军征派民夫、粮食，举报抗日人员，协助维持伪基层统治。','基层帮凶(维持会系统)','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('56e122a285914d75a5b98329423f405d','caa9cf41d9da43ac9cff305ac6b82371',1938,'伪光山县维持会会长','光山沦陷后组织伪维持会，后任伪光山县知事，配合日军对光山、潢川交界地区进行扫荡。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5f940ef1598249679ac591dc7020b9cf','02a4e84319ba438189869a1792dbacca',1938,'伪罗山县维持会会长','在罗山组织伪政权，为日军征粮派款，协助日军封锁信阳、潢川之间的交通线。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2a54fea1d76a458d93666c9d83ccd554','0c9d9be7baba497bac5b4c4c48d4839b',1938,'伪罗山县维持会会长','罗山沦陷后组织维持会，为日军提供情报、粮草和宿营便利，协助日军控制罗山县城及周边乡镇。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b187335d414945e181310021bd576a4d','69073b7113c34f488a2a46688d7f9a56',1938,'伪罗山县保安团团长','率伪保安团配合日军对罗山南部山区进行扫荡，袭击抗日武装，强征壮丁和物资。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ca8ed9fe1346462e968bcf672e7bbc72','d492b175c0d2433d82d0b823bf81a6ef',1938,'伪信阳道尹公署道尹','任伪信阳道最高行政长官，统辖信阳、罗山等县伪政权，推行日军殖民统治政策，征发劳工、粮食支持日军作战。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('45749ef9df0248eaa93d74f828b2e3e5','639d7084a75442ad8fb401c7c9db7d65',1938,'伪河南省政府豫南办事处主任','在豫南地区代表伪河南省政权协调各县伪化工作，督促信阳、罗山等地征粮征丁，配合日军经济掠夺。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6a31e7fc430047279c4f4d0a4df03016','fefd7f9ddbac40469c751144d6cbd784',1938,'伪和平救国军豫南地区指挥官','率伪军盘踞信阳、罗山一带，配合日军进攻抗日根据地，抢掠民财，收编土匪武装扩充伪军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8dd41d121b0840118fdcc18c83c9c499','848992e841c9488c8cdcf56cad9f079c',1938,'伪和平救国军第一军军长（活动于豫东、豫南）','所部伪军曾活动于河南东部及南部，与信阳、罗山地区日伪势力有联络配合，参与对抗日武装的作战和扫荡。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e1a061c9aa6848f58541f57a2a350c5e','2eacd3f5fcff4cc8951b38d131e9b5d7',1938,'伪罗山县商务会会长','协助日军控制罗山物资流通，为日军采购军需，强制商户缴纳“献金”，配合经济封锁。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5a015e4ece9d44dfa5b9ef5c060ad095','906dcc78f8af418eac9b54e7cf19fa8f',1938,'伪信阳维持会保甲长','在信阳城郊担任伪保甲长，负责清查户口、报告抗日人员行踪，为日军征发民夫和粮草。','基层帮凶(维持会系统)','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('353dd0efa6d64e39a16496ca14685d24','848992e841c9488c8cdcf56cad9f079c',1938,'伪豫东剿共军总司令、伪和平救国军第一军军长','河南柘城人，抗战期间投靠日军，在豫东、豫南一带组织伪军，配合日军进攻抗日根据地，后任伪军长，长期盘踞商丘、南阳周边地区。；河南柘城人，抗战期间投靠日军，在豫东、豫中一带组织伪军，配合日军进攻抗日根据地，其势力范围曾扩展至平顶山周边地区。；河南柘城人，抗战期间投靠日军，在豫东、豫中一带组织伪军，配合日军进攻抗日根据地，1944年后活动范围扩展至郑州、开封周边地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a93a3efac4a041a5b83b455e1891de1e','9f7b3ed9c76f4eea8211fd8ebc40a461',1943,'伪新编第五军军长、伪豫北保安司令','河南永城人，1943年投敌，所部被编为伪军，在豫北、豫西一带配合日军作战，其势力范围一度影响南阳周边。；河南永城人，原国民党军将领，1943年在河南林县被日军俘虏后投敌，所部被编为伪军，在豫北、豫西一带配合日军作战，其势力一度延伸至南阳以北地区。；河南永城人，抗战后期投敌，所部在豫东、豫北活动，与周口、淮阳地区伪军有联系，配合日军进攻抗日根据地。；河南永城人，原国民党军将领，1943年投敌，任伪新编第五军军长等职，活动于豫北、豫东一带，配合日军进攻抗日根据地。；原国民党军将领，1943年投敌，任伪新编第五军军长，活动于豫北、豫东一带，其部曾配合日军在商丘、永城周边地区进行扫荡。；河南永城人，1943年投敌，所部被编为伪军，在豫北、豫西一带活动，曾配合日军扫荡，其部众流窜至平顶山附近地区。；1943年在河南林县被日军俘虏后投敌，所部被编为伪军，在豫北、豫西一带配合日军行动，其伪军活动区域与平顶山、汝州同属河南战区，对豫西抗日力量构成威胁。；原国民党军将领，1943年在河南林县被日军俘虏后投敌，所部被编为伪军，在豫北、豫西一带配合日军行动，对河南抗战局势造成严重破坏。；原国民党将领，1943年在河南林县被俘后投敌，任伪职，在豫北地区为日军效力，配合日军维持占领区秩序。；原国民党军将领，1943年在河南林县一带被日军俘虏后投敌，所部被编为伪军，驻防豫北、豫西地区，配合日军维持占领区秩序，对河南抗战局势造成危害。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('78fd7578bfce4ded9acfa99844a45d32','5f82d23ccd2e45fd9e59f76c92bcc9ad',1933,'伪蒙古军总司令、伪豫北绥靖军司令','内蒙古人，长期充当伪军头目，抗战后期所部曾活动于河南北部，配合日军扫荡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7a111b77b3d845cf99cf90d6f0b63470','fcb3e5ff966f4327a818cbc1e3244da5',1938,'伪河南省警务厅长、伪开封市警察局长','在伪河南省会开封负责警务，镇压抗日活动，配合日军搜捕抗日人员，其警务系统延伸至河南各地。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4652bb8d6d844771a415e2b5a7b9a1f2','d409a62a1fcf424a82d99abd16ad9bea',1939,'伪南阳维持会会长','南阳本地士绅，日军占领南阳期间出面组织维持会，为日军筹粮、派夫、维持治安，协助伪政权控制南阳城区。；1945年日军侵占南阳期间，出面组织伪南阳维持会，为日军筹粮筹款、维持地方秩序，协助日军统治南阳地区。；南阳本地人，日军侵占南阳期间组织维持会，为日军筹粮、派夫、搜集情报，协助日军控制南阳城区。；1945年日军侵占南阳期间，出面组织伪南阳维持会，为日军筹粮筹款、维持秩序，协助日军控制南阳城区。；南阳本地人，日军侵占南阳后组织维持会，为日军筹粮筹款，协助建立伪基层政权，镇压抗日群众。；河南南阳人，抗战期间组织伪南阳维持会，任会长，协助日军维持南阳地区治安，推行伪化统治。；南阳本地人，日军侵占南阳后出面组织维持会，为日军筹粮、派夫、搜集情报，协助建立伪政权。；1945年日军侵占南阳期间，出面组织维持会，为日军筹粮筹款，维持地方秩序，协助日军统治南阳城区。；南阳地区维持会头目，1945年日军侵占南阳时出面组织维持会，为日军筹粮、派夫，协助维持地方治安。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4755eb7fd2254d679738addb4c6733e9','a7f97d8353ae4b63b92615956608aded',1941,'伪南阳县政府县长','抗战期间任伪南阳县长，执行日军指令，推行保甲连坐，征发民夫，配合日军对南阳周边抗日武装进行清剿。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b48411f484994131b74f00178f1392be','d6dfd188b7474385b7f0cfbde3069fe0',1942,'伪豫南绥靖军司令','在豫南信阳、南阳一带组织伪军，配合日军扫荡抗日根据地，残害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('97d4089fc4ec42a3994bcff1f6d66388','442e352824804acaab2b5d5fd7dda75e',1941,'伪南阳警察局局长','任伪南阳警察局长期间，带领伪警察配合日军搜查、逮捕抗日人员，镇压民众反抗。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d6a2ce4ddd94433eb3d257de31019ef2','ec89d405bae645879d97c60c7813b1bd',1943,'伪豫鄂边区绥靖军副司令','原国民党军将领，投敌后任伪职，在豫鄂边区包括南阳一带活动，协助日军维持占领区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('59d8b2940c964716983d3ea328af579a','e58a1196151242e997361b25a1cafb1b',1941,'伪南阳保安团团长','组织伪保安团，配合日军守备南阳，参与对抗日游击队的围剿。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('20519676fa03413ab4683e70dda8b5ff','53bdb8682e984f6e8c77b531f0d4ae7a',1939,'伪唐河县维持会会长','南阳唐河人，日军侵占唐河后组织维持会，为日军征粮派款，协助伪政权统治。；唐河县劣绅，组织维持会为日军服务，其活动范围与社旗南部接壤，协助日军控制南阳东部。；1945年日军侵入唐河期间，组织维持会，为日军筹办粮草，协助日军维持地方统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('059495658ee1497aa017ec73f0daaf9b','42fb54d5549a49d88797d3208cb21142',1941,'伪新野县县长','任伪新野县长，推行伪化教育，征发民夫修筑工事，配合日军对南阳南部地区的控制。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('38a1ef10d3f740508f6482e6e6401716','48978bca01144ac987c2b560564f5c8f',1940,'伪方城县维持会会长','南阳方城人，组织维持会，为日军筹集物资，协助日军维持地方秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d5ba46b9790c482081d1dbf64271e5cc','3cc7f92b40d8464abdfe1dba899d9fea',1941,'伪南召县县长','任伪南召县长，配合日军扫荡南召山区抗日武装，推行保甲制度。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('186b0cb4dcc44058bf35669494714962','d49c34074e9448bc9a73b99ceca35092',1938,'伪河南省教育厅长','在伪河南省政府任职，推行奴化教育，篡改教材，宣传“中日亲善”，其教育政策覆盖河南沦陷区包括南阳。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8b089bb9c803411bbca97bf009912f8a','4e7f43cc92e4469b84f28625fa4a1328',1938,'伪豫南道尹','任伪豫南道尹，管辖信阳、南阳等地区，协助日军征粮、派夫，维持伪政权统治。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7df64cde1a0f4b4298c2f8f8eec08f1e','a2e4190c87b449e685d78c118a6801b5',1940,'伪财政部部长、伪中央储备银行总裁','虽主要在南京伪政权任职，但其经济政策影响河南沦陷区，通过伪币发行、物资统制掠夺河南包括南阳地区资源。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('670715613d944b4b978e3eb74b0fb5f7','848992e841c9488c8cdcf56cad9f079c',1938,'伪豫东剿共军总司令、伪第二集团军总司令','河南柘城人，抗战期间投靠日军，在豫东、豫南一带组织伪军，配合日军进攻抗日根据地，后任伪第二集团军总司令，所部活动范围覆盖河南多地，包括南阳周边地区。；河南柘城人，抗战期间投靠日军，在豫东、豫南一带组织伪军，配合日军进攻抗日根据地，其势力范围曾覆盖南阳周边地区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fc3c63f60af44b498840c90c9ea39202','9f7b3ed9c76f4eea8211fd8ebc40a461',1943,'伪新编第五军军长、伪第二十四集团军副总司令','河南永城人，原为国民党军将领，1943年在河南林县投敌，所部被编为伪军，在豫北、豫西一带配合日军作战，其活动范围涉及河南大片地区。；河南永城人，1943年在河南林县被日军俘虏后投敌，所部被编为伪军，在豫北、豫西一带配合日军行动，对河南抗日力量造成危害。；河南永城人，1943年在河南林县被日军俘虏后投敌，任伪职，所部在豫北、豫西一带活动，与南阳地区有军事关联。；河南永城人，早年以盗掘清东陵闻名，1943年在河南林县率部投敌，所部被编为伪军，在豫北、豫西一带配合日军行动，对河南抗战局势造成严重破坏。；河南永城人，1943年在河南林县投敌，所部被编为伪军，在豫北、豫西一带配合日军作战，其势力一度延伸至南阳北部。；原国民党军将领，1943年在河南林县被日军俘虏后投敌，任伪职，所部在河南北部及豫西一带活动，配合日军作战。；原国民党军将领，1943年在河南林县一带被日军俘虏后投敌，所部被编为伪军，驻防豫北、豫西地区，配合日军作战。；原国民党军将领，1943年在河南林县一带被日军俘虏后投敌，所部被编为伪军，驻防豫北、豫西地区，配合日军扫荡。；河南永城人，原国民党军将领，1943年在豫北投敌，所部被编为伪军，驻防豫北、安阳一带，配合日军作战。；1943年在河南林县被俘后投敌，所部被编为伪军，活动于豫北、豫西一带，配合日军进攻太行山区和豫西抗日力量。；1943年在河南林县被俘后投敌，所部被编为伪军，活动于豫北、豫西一带，配合日军扫荡，其势力范围曾覆盖平顶山周边地区。；1943年在河南林县被俘后投敌，所部被编为伪军，驻防豫北、豫西一带，配合日军扫荡，其活动范围涉及河南中部包括平顶山周边。；1943年在河南林县投敌，所部被编为伪军，在豫北、豫西一带配合日军行动，其势力范围一度接近平顶山地区。；河南永城人，原国民党军将领，1943年在河南林县投敌，所部被编为伪军，在豫北、豫西一带配合日军作战，其活动范围涉及平顶山周边区域。；原国民党军将领，1943年在河南林县一带被日军俘虏后投敌，所部被编为伪军，驻防豫北、豫西地区，配合日军维持占领区治安。；原国民党军将领，1943年在河南林县一带被日军俘虏后投敌，所部被编为伪军，驻防豫北、新乡一带，配合日军维持占领区秩序。；河南永城人，1943年在河南林县被俘后投敌，所部被编为伪军，在豫北、豫西一带配合日军行动，后曾活动于漯河及平汉铁路沿线地区。；1943年在河南林县投敌，所部被编为伪军，在豫北、豫中一带配合日军行动，其伪军势力一度影响河南多地，包括漯河周边地区的伪化秩序。；原国民党军将领，1943年在河南林县被俘后投敌，所部被编为伪军，在豫北、豫中一带配合日军行动，其投敌行为对河南抗战局势造成恶劣影响。；1943年在河南林县被日军俘虏后投敌，所部被编为伪军，在豫北、豫中一带配合日军行动，其伪军活动曾涉及漯河周边地区。；1943年在河南林县投敌，所部被编为伪军，在豫北、豫中一带配合日军行动，其势力一度延伸至漯河、舞阳附近地区。；原国民党军将领，1943年在河南林县投敌，所部被编为伪军，活动于豫北太行山区，与焦作、修武一带日军协同作战。；1943年在河南林县投敌，所部被编为伪军，在豫北、豫西一带配合日军行动，其势力范围一度接近许昌、禹州地区。；原国民党军将领，1943年在河南林县一带被日军俘虏后投敌，所部被编为伪军，活动于豫北、豫西及平汉铁路沿线，配合日军维持占领区治安。；原国民党军将领，1943年在河南林县一带被日军俘虏后投敌，所部被编为伪军，驻防豫北、豫西地区，配合日军维持占领区秩序并参与对抗日武装的作战。；原国民党军将领，1943年在河南林县一带被日军俘虏后投敌，所部被编为伪军，驻防豫北、豫西地区，配合日军维持占领区秩序并进攻八路军，活动范围涉及郑州以北及河南多地。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('613a447e960541b3b40a29ebfc30d1e8','d31196ebd5bb4af4a5f843ae6817e5ea',1945,'伪内乡县维持会会长','1945年日军进犯内乡时，出面组织伪维持会，为日军提供物资、情报，协助日军控制内乡地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('662e1b42123449d49e4a8bbeddb71678','ec89d405bae645879d97c60c7813b1bd',1943,'伪军师长（后反正）','原国民党军将领，1943年在河南投敌，任伪军师长，在南阳、内乡一带配合日军行动，后于1945年率部反正。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9c14bb55da68418ca7cd4d258f1d36dd','a976a94be0bf4b76b621948c0802222f',1933,'伪平津第二集团军总司令','北洋军阀余孽，1933年投靠日军，在华北组织伪军，其活动范围涉及河南北部，后于1935年被刺杀。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9f34bb7f2cf64caab994fb85bf698146','a52d82089a804187b2198be492c8000a',1938,'伪冀察战区副总司令、伪军军长','原国民党军将领，抗战期间多次投敌，在河南北部、河北南部一带组织伪军，配合日军进攻抗日根据地，后于1940年被部下处决。；原国民党将领，后投敌，在河北、河南一带配合日军作战。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bca6338700244210983d8184e91e4c5a','b19edc2e16ec4c7d9462b01fbba0f27f',1940,'伪军师长（后反正）','原国民党军将领，1943年在湖北被俘后投敌，任伪军师长，其活动范围涉及河南南部，后于1945年反正。；湖北人，原国民党将领，曾一度投敌任伪军师长，在湖北黄冈、红安地区活动，后反正继续抗日。；原国民党军将领，在湖北被俘后一度任伪职，活动于鄂中，与湘北接近，但不久即脱离伪方。；原为国民党军将领，被俘后一度附逆，在湘北、鄂南一带活动，后重新抗日。；原国民党军将领，被俘后一度附逆，在湖北、湖南边界活动，其部队活动范围接近永州地区，后重新抗日。；原国民党军将领，1943年被俘后一度附逆，在湘北、鄂南一带活动，后重新抗日。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cb649a8b587f47e4922db8b0860dde14','62a6d6c8e7ab4bbfbc92c5b14abbde74',1940,'伪南京国民政府立法院院长、伪行政院院长','汪精卫伪政权核心人物，其伪政权统治范围包括河南沦陷区，推行奴化政策、经济掠夺，对河南民众造成深重灾难。；广东乳源人，汪伪政权核心人物，其伪政权名义上管辖河南，推行反共、奴化政策，南阳地区亦在其伪化影响范围内。；投靠日本，在汪伪政权中任职，推行日伪统治，其伪政权对包括陕西在内的全国抗日力量有威胁。；汪伪政权核心人物，其伪政权体系与陕西渭南地区无直接关联。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d7133de891c642888c8b93701cb0d783','9f7b3ed9c76f4eea8211fd8ebc40a461',1943,'伪新编第五军军长、伪第四方面军副总司令','河南永城人，1943年在河南林县被俘后投敌，所部被编为伪军，在豫北、豫西一带配合日军行动，对南阳地区抗日力量构成威胁。；原国民党军将领，1943年在河南林县一带被日军俘虏后投敌，所部被编为伪军，驻防豫北、豫西一带，配合日军维持占领区。；河南永城人，1943年在河南林县投敌，所部被编为伪军，在豫北、豫西一带配合日军行动，其伪军活动曾波及南阳、西峡周边地区。；河南永城人，原国民党军将领，1943年在豫北投敌，所部被编为伪军，活动于豫东、豫北一带，配合日军对周口、商丘地区进行扫荡。；河南永城人，原国民党将领，1943年投敌，所部在豫东、豫北配合日军作战，其势力范围涉及商丘周边地区。；1943年在河南林县投敌，所部被编为伪军，在豫北、豫西一带配合日军行动，活动范围涉及平顶山周边。；河南永城人，1943年投敌，所部被编为伪军，驻防豫北、豫东地区，配合日军扫荡。；河南永城人，1943年投敌，在河南、河北一带活动；与湖南衡阳无直接关联。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('afd58090c71a4c959132f7634c2a17ac','5ec2ad124b2f429482b1a90a7f8d4a92',1943,'伪暂编第二十四集团军总司令、伪第五方面军总司令','河北新河人，1943年在河南林县投敌，率部编入伪军，在豫北、豫西及南阳周边地区配合日军扫荡抗日武装。；河北人，1943年在河南林县投敌，所部伪军活动于豫北、豫西，对南阳地区抗日力量构成威胁。；河北人，原国民党军将领，1943年在河南林县投敌，率部编为伪军，在豫北、豫西地区配合日军作战，其势力范围曾接近南阳、西峡一带。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('88a7f4aac0864bfa957e86e4febc7f74','4f8793c77ca74d3dbe773329337bfbb0',1938,'伪中华民国维新政府行政院院长、伪监察院院长','福建长乐人，主持伪维新政府，其势力范围曾涉及河南部分地区，配合日军进行经济掠夺和伪化宣传。；福建长乐人，抗战期间投靠日军，组织伪中华民国维新政府，其伪政权影响范围涉及华中、华东，包括河南东部部分地区。；福建长乐人，抗战期间组织伪维新政府，后并入汪伪政权，其伪政权势力曾涉及河南部分地区，协助日军进行经济掠夺与治安维持。；福建长乐人，抗战期间组织伪维新政府，后并入汪伪政权，任伪监察院院长，其伪政权影响包括河南部分地区。；福建长乐人，组织伪维新政府，其势力范围涉及华中、华东，与河南南部地区有间接关联，后并入汪伪政权。；投靠日本，在华中组建伪政权，其伪政权与华北伪政权有联系，对陕西有间接影响。；华中伪政权头目，其伪政权与华北伪政权有联系，对华北各地包括陕西黄河沿岸日占区的伪组织有影响。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('27b7d771f94845e8a45f0f4e443d6e0e','41d2b197fedd4eefa3bd64d7cebe1523',1940,'伪南京国民政府军政部长、伪河南省政府主席','辽宁辽城人，曾任伪河南省政府主席，直接负责河南伪政权，推行日军政策，南阳地区在其管辖之下。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d3abd511426d4e329c6cfbeedb257edd','793dba30c5cd4e9ab0835412a8dc7906',1938,'伪河南省政府省长、伪河南省警务厅长','河南人，抗战期间在伪河南省政府任职，协助日军维持治安、征粮、抓捕抗日人员，其政令覆盖南阳及南召一带。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9fa01f0227b04bbead19310c183c62b0','2f7bbac25fb94f79a0527f838ea60d46',1940,'伪南阳县知事','在南阳沦陷期间任伪南阳县知事，推行保甲制度，配合日军扫荡南阳周边抗日武装，镇压民众抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5feecf1a13024100b2994e78b050a23a','d00abe2d305841a9923c2b6f58f34737',1941,'伪南召县维持会会长','南召本地人，日军侵入南召后出面组织维持会，为日军带路、征粮、招募伪军，协助日军控制南召山区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0a899ae114804a9f87a30f730038ac56','fe7588d226fa430ea2eda3d08a162f2f',1940,'伪南阳警察局局长','在南阳沦陷期间任伪警察局长，带领伪警察配合日军搜捕抗日人员，镇压南阳民众抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('28f151668fc84f8db900f9e9bf4fdff6','ec89d405bae645879d97c60c7813b1bd',1941,'伪军团长（南阳地区）','原为国民党军下级军官，投敌后在南阳地区组建伪军，配合日军扫荡南阳、南召一带抗日根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('37ce3609932348179f402ce469bd709d','f86731da17ce4a1b95263b9bcf38b69c',1942,'伪军旅长（豫南地区）','在豫南、南阳一带活动，率伪军配合日军进攻抗日武装，掠夺民众财物，残害抗日家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7f005aeba2654590be691a32cd41d2be','53bdb8682e984f6e8c77b531f0d4ae7a',1940,'伪南阳县教育局长','在南阳沦陷期间任伪教育局长，推行奴化教育，篡改教材，向学生灌输亲日思想，为日军培养顺民。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ff6d6f9ed2b54d0591751dceaaae0592','42fb54d5549a49d88797d3208cb21142',1940,'伪南阳商会会长','在南阳沦陷期间任伪商会会长，为日军筹集物资、摊派款项，协助日军对南阳经济进行掠夺。；河南南阳人，抗战期间任伪南阳商会会长，为日军筹集物资。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('514471aae4ac4f3487b0637cf6ce664f','fabd450d8480433fb1634895d3c43510',1941,'伪军师长（豫南地区）','在豫南、南阳一带活动，率伪军配合日军扫荡，烧杀抢掠，残害抗日民众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('20167a0163e5456ba2e8db4aa81ac9ba','2bd76bd4f7874f8f8becd896967ac4f3',1941,'伪南召县警察所长','在南召沦陷期间任伪警察所长，带领伪警察配合日军搜捕抗日人员，镇压南召山区抗日活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('edc543d9cf634612a53aa5ef152230a2','bb9f3367044e403997a73a2007e0c137',1940,'伪南阳保甲长','南阳本地人，任伪保甲长，为日军征粮、派夫、搜集情报，协助日军控制南阳基层社会。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e91e36d5fa9247db93b6d659b3c9b8e5','848992e841c9488c8cdcf56cad9f079c',1938,'伪豫东剿共军总司令、伪和平救国军第一军军长、伪第四方面军总司令','河南柘城人，抗战期间投靠日军，在豫东、豫南一带组织伪军，配合日军进攻抗日根据地，长期控制商丘、开封及豫东地区，其势力范围一度延伸至南阳周边。；河南柘城人，抗战期间投靠日军，在豫东、豫南一带组建伪军，配合日军进攻抗日根据地，其势力范围一度覆盖南阳周边地区，是河南境内影响较大的汉奸武装头目之一。；河南柘城人，抗战期间投敌，在豫东、豫南一带组织伪军，配合日军进攻抗日根据地，其伪军活动范围覆盖河南大部，对南阳、西峡等地抗日力量构成威胁。；河南柘城人，抗战期间投靠日军，在豫东、豫北一带收编土匪、组建伪军，配合日军进攻抗日根据地，其伪军活动范围覆盖安阳、汤阴周边地区。；河南柘城人，抗战期间投靠日军，在豫东、豫中一带组织伪军，配合日军进攻抗日根据地，其势力范围覆盖漯河、临颍周边地区，是河南境内影响较大的汉奸武装头目之一。；河南柘城人，抗战期间投靠日军，在豫东、豫北一带组织伪军，配合日军进攻抗日根据地，其势力范围覆盖濮阳周边地区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2ee9e95a6930408e9ad11b4a1adb4713','5ec2ad124b2f429482b1a90a7f8d4a92',1943,'伪第二十四集团军总司令、伪开封绥靖公署主任','1943年在河南林县被俘后投敌，任伪职，在河南境内协助日军维持占领区秩序，参与对抗日根据地的扫荡。；河北人，1943年在河南林县被俘后投敌，任伪第二十四集团军总司令，后任伪开封绥靖公署主任，统辖河南伪军，其势力范围涉及南阳。；原国民党河北省政府主席、第二十四集团军总司令，1943年在河南林县被俘后投敌，任伪职，在河南及华北地区协助日军维持伪政权，影响波及豫西、豫南。；河北新河人，1943年在河南投敌，任伪职，统辖豫北伪军，配合日军扫荡，对河南抗日力量造成较大破坏。；原国民党河北省政府主席、第二十四集团军总司令，1943年在河南林县被俘后投敌，任伪第二十四集团军总司令、伪开封绥靖公署主任，在河南境内协助日军维持伪政权。；原国民党河北省政府主席、第二十四集团军总司令，1943年在河南林县被俘后投降日军，任伪职，在河南及华北地区协助日军维持统治。；原国民党河北省政府主席、第二十四集团军总司令，1943年在河南林县被俘后投降日军，任伪职，在豫北、豫东地区协助日军维持统治。；河北新河人，原国民党军将领，1943年在豫北被俘后投敌，任伪职，统辖豫北伪军，活动涉及安阳、汤阴地区。；原国民党河北省政府主席、第二十四集团军总司令，1943年在河南林县被俘后投敌，任伪第二十四集团军总司令，驻河南开封，统辖豫北、豫东伪军。；1943年在河南投敌，任伪职，统辖伪军活动于豫北、豫东及平顶山周边，协助日军维持占领区秩序。；1943年在河南投敌，任伪第二十四集团军总司令，后任伪开封绥靖公署主任，统辖河南伪军，配合日军维持占领区治安，活动范围覆盖豫中包括平顶山地区。；1943年在河南投敌，任伪职，统辖豫北伪军，配合日军维持河南沦陷区统治，其伪政权体系覆盖河南大部，包括平顶山周边。；原国民党河北省政府主席、第二十四集团军总司令，1943年在河南林县被俘后投敌，任伪职，在河南境内协助日军维持占领区秩序，其伪政权影响覆盖豫中地区。；原国民党军将领，1943年在河南林县一带被俘后投敌，任伪第二十四集团军总司令，驻河南开封等地，协助日军控制豫中、豫东地区。；原国民党河北省政府主席、第二十四集团军总司令，1943年在河南林县被俘后投敌，任伪职，活动于豫北及开封一带，协助日军统治河南沦陷区。；河北人，原国民党河北省主席，1943年在河南林县被俘后投敌，任伪职，统辖河南北部及平汉线伪军，其势力范围涉及漯河周边地区。；原国民党河北省政府主席、第二十四集团军总司令，1943年在河南投敌，任伪职，驻开封，统辖河南部分伪军，对豫中、豫东包括漯河一带的伪政权和伪军有节制关系。；原国民党河北省政府主席、第二十四集团军总司令，1943年在河南林县被俘后投降日军，任伪职，在河南境内协助日军维持占领区秩序。；1943年在河南投敌，任伪第二十四集团军总司令等职，统辖伪军在豫北、豫东及漯河周边地区配合日军作战。；1943年在河南投敌，任伪职，统辖豫北、豫东伪军，配合日军维持河南沦陷区统治，其伪政权体系覆盖漯河、舞阳一带。；原国民党河北省主席，1943年在河南林县被俘后投敌，统率伪军盘踞豫北，控制焦作、修武等地的部分伪政权与伪军。；1943年在河南投敌，任伪职，统辖豫北、豫东伪军，配合日军维持河南沦陷区统治，对许昌、禹州地区有间接控制影响。；原国民党军将领，1943年在河南投敌，任伪职后驻开封，统辖伪军活动于豫东、豫北及郑州周边地区，协助日军控制平汉、陇海铁路沿线。；原国民党河北省政府主席、第二十四集团军总司令，1943年在河南林县地区被俘后投降日军，出任伪职，统辖豫北一带伪军，协助日军控制平汉铁路沿线及豫北地区。；原国民党河北省政府主席、第二十四集团军总司令，1943年在河南林县被俘后投降日军，任伪职，驻开封等地，统辖伪军配合日军在河南的统治与扫荡。；在河南投敌，组织伪军配合日军扫荡，河南与陕西相邻，其活动对陕西东南部有影响。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9f47d53a0aff49a0882eecf7d390e6d9','793dba30c5cd4e9ab0835412a8dc7906',1938,'伪河南省省长、伪河南省公署省长','抗战期间任伪河南省省长，在开封等地设立伪政权，推行日军政策，征发劳役、搜刮物资，配合日军对河南各地的控制，其伪政权影响覆盖南阳周边地区。；河南人，抗战期间任伪河南省长，在开封等地建立伪政权，推行日军政策，征粮征丁，镇压抗日活动，影响波及南阳、桐柏。；抗战期间任伪河南省公署省长，驻开封，统辖河南沦陷区伪政权，推行日军政令，征粮征丁，镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('50d31c062b044aeb8082dffeea2bac83','fcb3e5ff966f4327a818cbc1e3244da5',1940,'伪河南省公署警务厅厅长、伪河南省省长','在伪河南省政权中历任警务厅长、省长等职，协助日军维持河南沦陷区治安，镇压抗日活动，其警务系统延伸至南阳地区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('30381338dd514fbeade8ebe97b06480a','d31196ebd5bb4af4a5f843ae6817e5ea',1945,'伪南阳县维持会会长','1945年日军占领南阳时，组织伪南阳县维持会，配合日军征发民夫、物资，维持日占区统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3c24485b08574a179fb67db28ede37f4','d591a5834126475491c95ca5f7cc2648',1945,'伪南阳警察局局长','1945年日军侵占南阳后，出任伪南阳警察局局长，协助日军维持城区治安，搜捕抗日人员。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('035a401deb53476f94c013c777e8fdc1','62953086cc564a46b7f64c7b7980aa60',1945,'伪南阳保安团团长','1945年南阳沦陷期间，组织伪保安团，配合日军对南阳周边地区进行扫荡，镇压抗日武装。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f8df22b028da4839b94f3d439d9da2bd','ec89d405bae645879d97c60c7813b1bd',1945,'伪南阳地区维持会联合会会长','1945年日军侵占南阳后，联络南阳各县维持会，成立伪联合会，为日军筹办粮秣、夫役，协助日军统治南阳地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('83a3d87e1ea54464b0f1f032f0a4fc84','c41163edd0b74776acd6570b3d8fceb2',1945,'伪南阳县教育科科长','1945年南阳沦陷期间，在伪政权中负责教育事务，推行奴化教育，宣传“大东亚共荣圈”，毒害青年学生。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8f2bb78e30b6480caf7161782df116a6','1b173aa0e4744eab8c1b146e0be9d072',1945,'伪南阳商会会长','1945年日军占领南阳后，出任伪商会会长，为日军筹款筹物，协助日军对南阳工商业进行掠夺。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3a1a7aec1a584705a3ca9381eca8fe62','42fb54d5549a49d88797d3208cb21142',1945,'伪南阳地区保甲长','1945年南阳沦陷期间，担任伪保甲长，协助日军清查户口、征发劳役、搜捕抗日人员。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6e1c5bddcb454fbb879e4d3159adaafd','81aa72a7f9e340cdae9f69095f69cff8',1945,'伪南阳地区保甲长','1945年南阳沦陷期间，担任伪保甲长，为日军征粮征夫，监视居民行动，向日军报告抗日活动。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3ca241fb39ab42efa4dae371f1276fb9','86fe1fead892460db58a6370752bc1cc',1945,'伪南阳地区维持会文书','1945年南阳沦陷期间，在伪维持会中担任文书，协助日军登记物资、人口，为日军统治提供情报。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7185760a079b469397839177dc67ad47','0e792a422e304f25928a9cdf3c3fe99b',1945,'伪南阳地区翻译官','1945年日军侵占南阳期间，担任日军翻译，协助日军与当地伪政权沟通，参与审讯抗日人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ddd31fc6286040f4bbe084c5c579fd52','177c17b9b440453fa41ed47b9ebbd502',1937,'伪军旅长、伪和平救国军师长','山东人，长期在河南、山东交界地区为日军效力，组织伪军配合日军扫荡，其活动范围涉及豫西、豫南，对南阳周边地区造成威胁。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6968f106d92042de9c867f1c933bb504','fabd450d8480433fb1634895d3c43510',1938,'伪和平救国军第二军军长','在河南东部、南部组织伪军，配合日军进攻抗日根据地，其伪军活动曾延伸至南阳地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a9805eadddbd47d9b202aa246bfae43f','848992e841c9488c8cdcf56cad9f079c',1938,'伪豫东剿共军总司令、伪第四方面军总司令','河南柘城人，抗战期间投靠日军，在豫东、豫南一带组织伪军，配合日军进攻抗日根据地，后任伪第四方面军总司令，所部活动范围覆盖南阳周边地区。；河南柘城人，抗战期间投靠日军，在豫东、豫南一带组织伪军，配合日军进攻抗日根据地，后任伪第四方面军总司令，所部活动范围覆盖河南多地，包括南阳周边地区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('755e27fdb39f472b805e0a755bd53459','5f82d23ccd2e45fd9e59f76c92bcc9ad',1933,'伪蒙古军总司令、伪豫北剿共军司令','内蒙古人，长期任伪蒙古军总司令，后率部进入河南，任伪豫北剿共军司令，配合日军在河南境内作战，活动范围包括豫西南。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c19b56b4e85244429026d20e54ece10a','8f1dd12e548b4c4f866dd743c3377896',1937,'伪华北政务委员会委员长、伪河南省省长','安徽人，抗战期间任伪华北政务委员会委员长，后兼任伪河南省省长，推行奴化教育、经济掠夺，其伪政权覆盖河南全省包括南阳。；安徽合肥人，北洋政客，抗战期间投靠日本，任伪华北政务委员会委员长等职，其伪政权管辖范围包括河南，推行奴化教育、经济掠夺。；安徽人，投靠日军，在华北及河南推行伪化政策，影响驻马店地区伪政权运作。；安徽合肥人，北洋政客，抗战期间投敌，任伪华北政务委员会委员长，曾兼任伪河南省省长，推行奴化教育、经济掠夺，其伪政权体系覆盖河南全省包括驻马店、正阳。；安徽合肥人，北洋政客，抗战期间投靠日本，任伪华北政务委员会委员长等职，其伪政权管辖范围包括河南沦陷区，推行奴化教育、经济掠夺。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1b76411758254d3c854a24bf55ca1538','793dba30c5cd4e9ab0835412a8dc7906',1938,'伪河南省省长、伪河南省政府主席','河南人，抗战期间任伪河南省省长，协助日军维持占领区统治，推行保甲制度，其伪政权机构涉及南阳地区。；河南人，抗战期间出任伪河南省长，协助日军维持沦陷区统治，推行保甲、征粮、奴化教育，南阳地区在其伪政权名义管辖之下。；河南沦陷后投敌，历任伪河南省长等职，在河南全省推行日伪政策，其政令覆盖周口、太康等豫东地区，为日军征发物资、镇压抗日活动。；抗战期间出任伪河南省长，主持伪省政，推行日军殖民统治政策，在河南各地包括豫东周口一带建立伪政权、征粮征丁，配合日军清乡。；河南伪政权最高头目之一，在开封、安阳等地推行日军殖民统治，协助征粮、征兵。；抗战期间任伪河南省省长，驻开封，协助日军维持河南沦陷区统治，推行保甲制度、征粮征丁。；抗战期间投靠日军，历任伪河南省政府要职，参与组织伪政权、推行奴化教育、征发物资劳工，支持日军在河南的殖民统治。；抗战期间任伪河南省省长，在开封等地建立伪政权，配合日军征粮、征丁，镇压抗日活动。；河南本地人，日军占领开封后出面组织伪河南省政府，任伪省长，协助日军推行保甲、征粮、奴化教育等政策，影响及于郑州地区。；抗战期间投敌，历任伪河南省政府委员、伪河南省省长，驻开封，为日军在河南推行殖民统治、征粮征丁，是河南沦陷区伪政权核心人物之一。；抗战期间投敌，历任伪河南省政府要职，协助日军在河南推行殖民统治，参与征粮、征丁等伪政活动。；抗战期间任伪河南省省长，在开封等地设立伪政权，协助日军维持沦陷区统治，推行保甲制度、征发劳工。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('22218698826849c588a651e5f6280a50','fcb3e5ff966f4327a818cbc1e3244da5',1939,'伪南阳维持会会长、伪南阳县县长','河南南阳人，抗战期间组织伪南阳维持会，后任伪南阳县县长，协助日军征粮、征夫，镇压抗日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('13ff9d7d930742aebb46da525cf0c325','da5574c93d254557802d943bec632fa7',1940,'伪南阳警察局局长','河南南阳人，抗战期间任伪南阳警察局局长，配合日军搜捕抗日人员，维持伪政权治安。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3b177d3c0d43465b82aebc61e0c6cd87','d1d26f259bec4fd890f98576625c8886',1941,'伪南阳保安团团长','河南南阳人，抗战期间任伪南阳保安团团长，率部配合日军扫荡南阳周边抗日武装。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0e148f82eb6a4138bb6c57b05fd3f6a8','cb5c123407db4327a62478fa50c09023',1940,'伪南阳县教育科科长','河南南阳人，抗战期间任伪南阳县教育科科长，推行奴化教育，篡改教材，宣传“大东亚共荣”。；南阳教育界人士，1945年日军占领南阳后出任伪教育科科长，推行奴化教育，篡改教材，向学生灌输亲日思想。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0470e9b2ff734ea5866a3b370872aaac','ec89d405bae645879d97c60c7813b1bd',1939,'伪南阳商会会长','河南南阳人，抗战期间任伪南阳商会会长，为日军筹集物资、资金，协助经济掠夺。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0deb167bed5c45ecab873d70d4ed8ec9','2bd76bd4f7874f8f8becd896967ac4f3',1939,'伪南阳维持会副会长','河南南阳人，抗战期间任伪南阳维持会副会长，协助日军管理地方事务，征发民夫。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1f6f7f56adb444309256264ea2f11e27','848992e841c9488c8cdcf56cad9f079c',1938,'伪和平救国军第一军军长、伪第四方面军总司令、伪河南省省长','河南柘城人，抗战期间投靠日军，在豫东、豫南一带组织伪军，配合日军进攻抗日根据地；后任伪河南省省长，推行伪化统治，为日军征粮、征丁、维持治安。其伪军活动范围覆盖河南大部，对南阳地区亦有影响。；河南柘城人，抗战期间投靠日军，在豫东、豫南一带组建伪军，配合日军进攻抗日根据地，后任伪河南省省长，是河南地区影响较大的汉奸之一。；河南柘城人，抗战期间投靠日军，在豫东、豫南一带组织伪军，配合日军进攻抗日根据地，后任伪河南省省长，是河南地区影响较大的汉奸之一。；河南柘城人，早年在西北军任职，抗战爆发后投敌，在豫东商丘、周口一带组建伪军，配合日军扫荡抗日根据地，后任伪河南省省长，是河南沦陷区最具实力的汉奸武装头目之一。；河南柘城人，抗战期间投靠日军，在豫东商丘、周口、柘城、鹿邑、淮阳一带组建伪军，配合日军进攻抗日根据地，搜捕抗日人员，横征暴敛，是豫东地区最具实力的汉奸武装头目之一。；河南柘城人，早年在冯玉祥部任职，抗战爆发后投敌，在豫东商丘、周口、柘城、鹿邑、淮阳一带组建伪军，配合日军扫荡抗日根据地，1943年后任伪第四方面军总司令，1945年任伪河南省省长，是豫东地区最具实力的汉奸武装头目。；河南柘城人，抗战期间在豫东周口、商丘一带组织伪军，先投日军任伪和平救国军第一军军长，后任伪第四方面军总司令，1945年又任伪河南省省长，长期配合日军在豫东地区进行统治和扫荡。；河南柘城人，早年留学日本，抗战爆发后投敌，在豫东商丘、周口、鹿邑一带组建伪军，配合日军扫荡抗日根据地，后任伪河南省省长，是河南沦陷区最大的汉奸军事头目之一。；商丘柘城人，抗战爆发后投靠日军，在豫东商丘一带组建伪军，配合日军进攻抗日根据地，后任伪河南省省长，是河南沦陷区最具实力的汉奸武装头目之一。；商丘柘城人，抗战期间投靠日军，在豫东商丘一带组建伪军，长期盘踞商丘及周边地区，配合日军扫荡抗日根据地，后任伪河南省省长，是河南沦陷区最重要的汉奸头目之一。；河南柘城人，抗战期间在豫东商丘、夏邑一带组织伪军，初任伪和平救国军第一军军长，后任伪第四方面军总司令，配合日军进攻抗日根据地，1945年任伪河南省省长，是豫东地区最具实力的汉奸武装头目之一。；商丘柘城人，抗战期间在豫东商丘一带组织伪军，先后投靠日军、汪伪政权，任伪军要职，配合日军进攻抗日根据地，搜刮民财，残害抗日军民。；柘城人，抗战期间在商丘一带组织伪军，初投日军任伪和平救国军第一军军长，后任伪第四方面军总司令，长期盘踞商丘、柘城、鹿邑、亳县等地，配合日军扫荡抗日根据地，1945年又任伪河南省省长。；河南柘城人，抗战期间投靠日军，在豫东、豫北一带组织伪军，配合日军进攻抗日根据地，后任伪河南省省长，是河南地区影响较大的汉奸之一。；河南柘城人，抗战期间投靠日军，在豫东、豫中一带组织伪军，配合日军进攻抗日根据地，后任伪河南省省长，是河南沦陷区重要汉奸头目之一。；河南柘城人，抗战期间投靠日军，在豫东、豫北一带组建伪军，配合日军进攻抗日根据地，1943年后任伪第四方面军总司令，1945年任伪河南省省长，长期在河南境内为日军维持统治。；河南柘城人，抗战期间投靠日军，在豫东、豫中一带组建伪军，配合日军进攻抗日根据地，后任伪河南省省长，是河南地区影响较大的汉奸之一。；河南柘城人，抗战期间投靠日军，在豫东、豫中一带组织伪军，配合日军进攻抗日根据地，后任伪河南省省长，是河南地区影响较大的汉奸之一。；河南柘城人，抗战期间投靠日军，在豫东、豫北及郑州周边地区组建伪军，配合日军进攻抗日根据地，后任伪河南省省长，是河南地区影响较大的汉奸之一。；河南柘城人，抗战期间投靠日军，在豫东、豫南一带组建伪军，配合日军进攻抗日根据地，其伪军活动范围覆盖驻马店、平舆周边地区，后任伪河南省省长，是河南最大的汉奸武装头目之一。；河南柘城人，抗战期间投靠日军，在豫东、豫南一带组建伪军，配合日军进攻抗日根据地，曾任伪河南省省长，其势力范围覆盖驻马店、正阳周边地区。；河南柘城人，抗战期间投靠日军，在豫东、豫南一带收编土匪、组建伪军，配合日军进攻抗日根据地，后任伪河南省省长，是河南地区影响较大的汉奸之一。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2a5217484721491e8c3bd19f0ffbd6f3','5ec2ad124b2f429482b1a90a7f8d4a92',1943,'伪和平救国军第二十四集团军总司令、伪河南省政府委员','原国民党河北省政府主席、第24集团军总司令，1943年在河南林县被俘后投敌，任伪第二十四集团军总司令，驻防豫北、豫东，配合日军进攻河南抗日根据地，对南阳地区亦有间接影响。；河北人，原国民党军将领，1943年投敌，任伪和平救国军第二十四集团军总司令，活动范围包括河南北部及豫东部分地区，协助日军维持伪政权。；投降日军后任伪职，其伪军活动于豫北、豫东地区，与商丘、民权一带日伪势力配合，参与对抗日根据地的扫荡。；原国民党河北省政府主席、第二十四集团军总司令，1943年在河南林县被俘后投敌，所部被编为伪军，活动于豫北、豫西一带。；原国民党将领，1943年投敌，任伪军要职，活动于河南北部、豫北地区，配合日军进攻抗日根据地。；原国民党河北省政府主席、第二十四集团军总司令，1943年在河南林县被俘后投敌，所部被改编为伪军，活动于豫北及河南部分地区。；原国民党河北省政府主席、第二十四集团军总司令，1943年在河南林县被俘后投敌，任伪第二十四集团军总司令，活动于豫北、冀南一带，配合日军进攻太行和冀鲁豫根据地。；原国民党河北省政府主席、第二十四集团军总司令，1943年在河南林县被俘后投敌，所部被编为伪军，活动于豫北、豫东地区。；原国民党河北省主席、第二十四集团军总司令，1943年在河南林县被俘后投敌，所部伪军活动于豫北、豫东，与驻马店地区伪政权有联系。；原国民党河北省政府主席、第二十四集团军总司令，1943年投敌，任伪第二十四集团军总司令，驻防豫北、豫东，其伪军势力曾扩展至豫南驻马店地区。；原国民党河北省政府主席、第24集团军总司令，1943年在河南林县被俘后投敌，所部被改编为伪军，活动于豫北、豫东地区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('79d5eb9420164522ae98d00622a44cb9','5f82d23ccd2e45fd9e59f76c92bcc9ad',1933,'伪蒙古军总司令、伪河南省保安司令','内蒙古人，早年在热河投敌，后任伪蒙古军总司令；1944年后被派往河南任伪保安司令，协助日军维持河南占领区治安，其活动涉及豫南、豫西南地区。；蒙古族，早年在东北投敌，后随日军进入河南，曾任伪河南省保安司令等职，参与镇压河南抗日力量。；1944年率伪军进入河南，配合日军控制豫中地区，其部队曾驻扎许昌一带。；蒙古族，早年在热河投敌，后任伪蒙古军总司令，抗战后期被派往河南任伪保安司令，参与维持豫南伪政权，活动涉及驻马店、正阳一带。；投敌后任伪职，其伪军一度调驻河南，参与对豫南抗日根据地的扫荡。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4b127eff54f74a4faf36537ab084552c','8f1dd12e548b4c4f866dd743c3377896',1937,'伪华北政务委员会委员长、伪河南省政府省长','安徽合肥人，北洋政客，抗战期间投敌，任伪华北政务委员会委员长，后兼任伪河南省省长，推行奴化教育、经济掠夺，其伪政权统治覆盖河南全境，包括南阳地区。；华北伪政权首要汉奸之一，统辖包括河南在内的华北沦陷区，其政策影响商丘、民权等地伪政权运作，推行奴化教育与经济掠夺。；安徽合肥人，北洋余孽，抗战期间投敌，任伪华北政务委员会委员长，统辖包括河南在内的华北伪政权，推行奴化教育、经济掠夺。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b4db75ac587b4e47ac0fd582a62042e1','793dba30c5cd4e9ab0835412a8dc7906',1938,'伪河南省政府省长、伪豫北道尹','河南安阳人，抗战初期即投敌，历任伪豫北道尹、伪河南省省长，在河南推行伪化行政，为日军征集物资、劳工，其伪政权体系延伸至南阳各县。；河南人，抗战期间投敌，在豫北地区任伪道尹、伪省长，协助日军征粮、抓丁，镇压抗日民众。；河南安阳人，抗战期间历任伪河南省政府要职，协助日军推行保甲、征粮、抓丁，其伪政权体系覆盖河南多地，包括平顶山地区。；长期在豫北日伪政权任职，配合日军清乡、征粮、抓劳工，残害抗日群众。；河南安阳人，抗战期间投敌，历任伪河南省政府省长、伪豫北道尹等职，协助日军在河南推行伪化统治，其伪政权体系延伸至驻马店、泌阳等县，征粮征兵。；河南安阳人，抗战期间投敌，历任伪河南省政府要职，协助日军推行保甲、征粮、清乡等政策，其伪政权体系延伸至豫南各县。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('452e0aa8b72c4c38b849385748c60bd8','b675598d6a7f4448baceea6f8fb0fc37',1945,'伪南阳维持会会长、伪南阳县县长','南阳本地士绅，1945年日军侵占南阳时出面组织维持会，任伪南阳县县长，协助日军维持城区秩序、征粮征夫，是南阳地区直接附逆的代表人物。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b83b61bbbb3a4b3184a2df7649f66e98','72792c04c74542839218a7738df11d8f',1945,'伪南阳警察局局长','1945年日军占领南阳期间，出任伪南阳警察局局长，协助日军搜捕抗日人员、维持治安，镇压民众反抗。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8a64b1f4da8543aa9690d8763daa62ba','1ec7c49f402b4acbb11ec0197fc7341a',1945,'伪南阳保安团团长','南阳地方武装头目，1945年投靠日军，任伪南阳保安团团长，配合日军扫荡南阳周边抗日武装，为日军提供情报和向导。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1781e253b2d742c0bcd990be23ccc201','d6758c561d214b1aa05b70b38bea49fb',1945,'伪南阳商会会长','南阳商界人物，1945年日军占领南阳后出任伪商会会长，为日军筹款筹粮，协助日军控制南阳经济命脉。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d9bcc267932c48f5afd5ca511c2f56ba','ec89d405bae645879d97c60c7813b1bd',1938,'伪豫南道尹、伪信阳维持会会长','河南信阳人，抗战期间投敌，任伪豫南道尹，管辖信阳、南阳部分区域，组织维持会，为日军征粮征丁，配合日军扫荡豫南抗日根据地。；在豫南信阳一带组织伪政权，活动范围接近平顶山南部，配合日军扫荡豫南抗日武装。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1a062666e21c4c6392bb51ed4db9adbd','e409ef959281461b91e8ce1eef37d186',1938,'伪河南省政府委员、伪豫东道尹','原东北军将领，抗战期间投敌，任伪豫东道尹、伪河南省政府委员，在豫东推行伪化统治，为日军征集物资，其伪政权体系与南阳地区有行政关联。；伪豫东道尹，管辖包括驻马店东部在内的豫东地区，协助日军建立伪政权，征发物资。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('158f167b20ea46279cdef95d6a82f4b2','5ec2ad124b2f429482b1a90a7f8d4a92',1943,'伪第四方面军总司令、伪开封绥靖公署主任','原国民党军将领，1943年在河南林县一带被俘后投敌，任伪第四方面军总司令，驻开封等地，协助日军控制河南沦陷区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6c5615b57ba645ce989d155dd34c1876','62a6d6c8e7ab4bbfbc92c5b14abbde74',1940,'伪南京国民政府立法院院长、伪行政院院长、伪国民政府代主席','广东乳源人，抗战期间随汪精卫投敌，在伪南京国民政府中担任要职，推行日伪统治政策，其伪政权名义上管辖包括河南在内的华中沦陷区。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5b81f078d1e04f109e8ec982ee15cee9','a2e4190c87b449e685d78c118a6801b5',1940,'伪南京国民政府财政部长、伪警政部长、伪上海市长','湖南沅陵人，抗战期间随汪精卫投敌，在伪南京国民政府中担任要职，参与伪政权财政与警政，其政策影响涉及华中沦陷区包括河南南部。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('635509f19d064375b315b60112d8261a','41d2b197fedd4eefa3bd64d7cebe1523',1940,'伪南京国民政府军政部长、伪河南省省长','辽宁辽城人，抗战期间投靠汪伪政权，曾任伪河南省省长，在河南沦陷区推行日伪政策，协助日军维持统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('44a465ed4cef4e46bbb982affa840867','f50cf011f8f842fc8d69caa402ffbf67',1940,'伪南京国民政府内政部长、伪江苏省省长','福建闽侯人，抗战期间投靠汪伪政权，在伪政权中担任内政部长等职，其政策影响涉及华中沦陷区包括河南部分地区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fc612947843d4f93b28ccf3d01732e91','0b332f77f5834d0d8064a3cbcc8c1f1a',1940,'伪南京国民政府司法行政部长、伪河南省省长','贵州黎平人，抗战期间投靠汪伪政权，曾任伪河南省省长，在河南沦陷区推行日伪法令，协助日军控制地方。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3236ddd33f104d67bd070e04c009cf12','5bb6456b293d479e87f26e53e7afaa80',1938,'伪河南省警务处处长、伪开封市警察局局长','抗战期间在河南沦陷区伪政权中任职，负责警务与治安，协助日军镇压抗日活动，维护日伪统治秩序。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a202f89dadda4503a6df9c70d8e5ecf0','2bd76bd4f7874f8f8becd896967ac4f3',1939,'伪唐河县维持会会长','河南唐河人，抗战期间在唐河县组织维持会，协助日军维持地方治安，征发物资，压迫当地民众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dc05edc6d58d4cc6aa6c31be72c294a0','f72e552995ad4e0bb5393c8c688d6b60',1939,'伪南阳县维持会会长','河南南阳人，抗战期间在南阳县组织维持会，配合日军征粮征夫，维持日伪统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('78e5fce9ef74454bb76fcd392d66fea3','ec89d405bae645879d97c60c7813b1bd',1940,'伪南阳地区保安团团长','河南南阳人，抗战期间投靠日军，组织伪保安团，配合日军扫荡南阳周边抗日武装。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('da586a1c344c4794896bd76c90895f8c','caa9cf41d9da43ac9cff305ac6b82371',1940,'伪唐河县警察所所长','河南唐河人，抗战期间在唐河县伪警察所任职，协助日军搜捕抗日人员，镇压民众反抗。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('50aca97ca9904453b0f49fdff7156ab9','d1d26f259bec4fd890f98576625c8886',1938,'伪南阳道尹公署道尹','抗战期间在河南南阳地区伪政权中任职，负责推行日伪政策，管理地方行政，协助日军维持占领区秩序。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1617e270bd3e4488ae6575a23dc826bc','42fb54d5549a49d88797d3208cb21142',1941,'伪唐河县保安队队长','河南唐河人，抗战期间组织伪保安队，配合日军清乡，镇压当地抗日力量。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('651c17913ee1411dafbadf083ee83497','1212fb183f9f47588077aa0f9e20e346',1939,'伪南阳县警察局局长','河南南阳人，抗战期间在南阳县伪警察局任职，协助日军维持治安，搜捕抗日分子。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f1338ccaf1d1444b9b7d52fe6d79cbaf','5f82d23ccd2e45fd9e59f76c92bcc9ad',1933,'伪蒙古军总司令、伪察南自治政府要职','内蒙古人，长期在伪蒙疆政权中任伪军头目，其伪军曾配合日军在华北、豫北一带作战，对河南北部地区构成威胁。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1f0e61a1f6fa4d8c940aef861e7bb63b','62a6d6c8e7ab4bbfbc92c5b14abbde74',1940,'伪国民政府立法院院长、伪行政院院长、伪国民政府代主席','广东乳源人，汪伪政权核心人物之一，抗战期间协助汪精卫推行伪化统治，其伪政权对河南沦陷区有名义上的管辖权，配合日军镇压抗日力量。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d7403b2a2c3f4f68921b12a8cca8fa92','41d2b197fedd4eefa3bd64d7cebe1523',1940,'伪国民政府军政部长、伪参谋总长','辽宁辽县人，原东北军将领，投敌后任汪伪政权军事要职，参与整编伪军，其伪军系统在河南一带有活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('05896832c47e451ca9763929a7dd2d0b','bb34b45b44c34a018d410cde66579fb1',1939,'伪国民政府陆军部长、伪武汉绥靖公署主任','湖北黄陂人，抗战期间投敌，任伪军要职，在武汉及周边地区包括河南南部一带配合日军作战，镇压抗日武装。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('95e377ae5d41415089440684e5f11f5c','a976a94be0bf4b76b621948c0802222f',1937,'伪华北政务委员会要职、伪军头目','安徽霍邱人，北洋军阀余孽，抗战初期投敌，在华北组织伪军，其活动范围涉及河南北部，后因内讧被杀。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f64d2a3cd5cd4f45ba8644a619d201f4','a52d82089a804187b2198be492c8000a',1938,'伪冀察战区副总司令、伪军头目','吉林长春人，反复无常的军阀，抗战期间投靠日军，在冀南、豫北一带组织伪军，配合日军进攻抗日根据地，后因再次谋叛被部下活埋。；原西北军将领，投敌后任伪军头目，活动于华北，与陕西渭南地区有间接关联。；反复投敌，在华北组织伪军，配合日军进攻抗日根据地，对陕西周边有威胁。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('497342a0d7504110a998de23aab2fd99','63006a4879fb4f49ad97a1e88c8c5d69',1942,'伪第二方面军总司令、伪开封绥靖公署主任','天津人，原国民党军将领，1942年在山东投敌，后任伪第二方面军总司令，所部在河南东部、北部一带配合日军作战，对河南抗战造成危害。；1942年在河南投敌，任伪第二方面军总司令，所部伪军驻防豫东、豫中，配合日军进攻抗日武装，其防区覆盖漯河周边。；原西北军将领，1942年率部投敌，任伪第二方面军总司令，驻防开封、郑州一带，配合日军扫荡豫中、豫东抗日力量，1945年后被国民党收编。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dfa5fa1a5f3d4b4da66b339da1fc9648','e409ef959281461b91e8ce1eef37d186',1937,'伪华北政务委员会要职、伪河北省长','河北枣强人，原东北军将领，投敌后任伪河北省长等职，其伪政权与河南北部沦陷区有行政关联，协助日军征粮征丁。；在华北伪政权中任职，协助日军维持河北及华北占领区秩序，对陕西抗日后方有间接威胁。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6eb600e02a4d41a184012d0b6e606ee3','83b067447f4744f7b527179c4d9524d4',1938,'伪河南省长、伪河南省政府主席','河南人，抗战期间投敌，任伪河南省长，在开封等地设立伪政权，协助日军统治河南沦陷区，包括南阳周边地区，推行征粮、征丁、清乡等政策。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6798efe102b54890a72b21e0d4fa684e','793dba30c5cd4e9ab0835412a8dc7906',1938,'伪河南省政府委员、伪豫北道尹','河南人，抗战期间投敌，任伪河南省政府要职及豫北道尹，在豫北地区协助日军维持伪统治，镇压抗日活动。；在伪河南省政府任职，协助日军推行保甲制度、征发劳工，其伪政权体系延伸至南阳、西峡一带。；河南本地汉奸，抗战期间在豫北道任职，管辖包括新乡、封丘在内的豫北各县伪政权，协助日军推行治安强化运动，掠夺物资、镇压抗日力量。；在河南日占区协助日军推行伪化统治，参与对濮阳等地的经济掠夺与思想控制。；抗战期间投敌，任伪河南省政府委员、豫北道尹，管辖豫北包括濮阳地区，推行伪化教育、经济掠夺，配合日军扫荡。；在豫北道任职期间，管辖包括濮阳在内的豫北各县，推行伪化教育、经济掠夺，协助日军维持占领区秩序。；抗战期间在河南伪政权中任职，负责豫北道事务，管辖包括焦作、新乡在内的豫北地区，推行日军殖民统治政策，协助征发物资、镇压抗日力量。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8aacd7ee9bb74dc4af88b881d1b19972','13a3e370290e481cafdf46e018427148',1938,'伪豫东道尹、伪河南省政府委员','河南人，抗战期间投敌，任伪豫东道尹，在豫东地区协助日军统治，其伪政权与南阳地区有行政联系。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9b0362a74caf4ef3ba7b1b953c2e3caf','25917df51aa04d7793ee1451b8167067',1938,'伪河南省政府委员、伪豫南道尹','河南人，抗战期间投敌，任伪豫南道尹，在豫南地区包括南阳一带协助日军维持伪政权，推行殖民统治。','无明确职位或一般帮凶','hanjian');
