INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2fb574c0d0e5407fb0cb73326b3744eb','faa065ec4e25450b8635a1cc1dc27693',1940,'伪南阳保安团排长','河南南阳人，抗战期间投敌，任伪保安团排长，配合日军扫荡抗日武装。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('90458030a13b44fabaefe16c57310766','51b866d209994272b9e9307c543dcfcc',1940,'伪南阳警察局警员','河南南阳人，抗战期间投敌，任伪警察局警员，协助日军维持治安，迫害百姓。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('763e313718a5414b93eae47780570cbf','102db9e5c6744a65ae8e91478952c456',1940,'伪南阳教育科科员','河南南阳人，抗战期间投敌，任伪教育科科员，推行奴化教育，审查教材。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8c20e2bd9a0947c8ba61eb69d2454cb4','cde1e0e6fbcb44e2b323bf44e7b770ed',1940,'伪南阳新民会会员','河南南阳人，抗战期间投敌，任伪新民会会员，宣传亲日思想，组织亲日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4dbfc9926ae14b81afc27deb777d504a','63388300e1ce45099aba5c1ee1a60f29',1940,'伪南阳商会会员','河南南阳人，抗战期间投敌，任伪商会会员，协助日军征购物资，控制市场。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('104328bbfe0c4f79a4c4ea38d1fd3faf','36150d27cf8f4d44bbd4ca962a5c982e',1940,'伪南阳维持会文书','河南南阳人，抗战期间投敌，任伪维持会文书，协助日军登记户口、征发劳役。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3afd6c2b566a48d69629d88e0a7146ef','be101ae50c01499eb4d1ad9af8d79b62',1940,'伪南阳保安团士兵','河南南阳人，抗战期间投敌，任伪保安团士兵，配合日军扫荡抗日武装。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('68fb1870718e4b95abeafb2675557227','e951a5e0ed3649059896daa566d43498',1940,'伪南阳警察局警员','河南南阳人，抗战期间投敌，任伪警察局警员，协助日军维持治安，迫害百姓。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cb87c0dd250448df972985dc57ce85cd','44edbe63d35e4dcfbf376c18c6865b39',1940,'伪南阳税务所职员','河南南阳人，抗战期间投敌，任伪税务所职员，协助日军征收苛捐杂税。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('92397883c777400b991a80dad20657bd','cfc3d2dd38bc4af29d7fd90e40eee454',1940,'伪南阳电报局职员','河南南阳人，抗战期间投敌，任伪电报局职员，为日军提供通讯服务。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3c0e720ed8914f619d9fe99a05834bcd','9f7b3ed9c76f4eea8211fd8ebc40a461',1943,'伪豫北剿共军总司令、伪新编第五军军长','原国民党军将领，1943年在河南林县一带率部投敌，被汪伪政权任命为伪豫北剿共军总司令等职，配合日军在豫北、豫西地区进行扫荡和反共活动，其部队活动范围涉及河南多地，对南阳、新野周边地区亦有影响。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a6fb27bfde4e4f1caac9c1b0a08e6c66','fcb3e5ff966f4327a818cbc1e3244da5',1940,'伪河南省政府省长','继陈静斋之后任伪河南省政府省长，在河南沦陷区推行日军政策，组织伪军配合扫荡，其伪政权对南阳、新野地区有名义上的管辖权。；任伪河南省长期间，协助日军推行治安强化运动，镇压抗日力量，影响豫北新乡等地。；河南伪政权头目之一，配合日军统治河南沦陷区。；任伪河南省长期间，协助日军维持沦陷区秩序，推行奴化教育，强征劳工和粮食支援日军。；抗战后期任伪河南省省长，继续为日军服务，直至日本投降。；接替萧瑞臣任伪河南省省长，继续为日军维持河南沦陷区统治。；任伪河南省长期间，协助日军搜刮物资、推行保甲连坐，镇压河南抗日活动。；任伪河南省长期间，协助日军维持占领区秩序，推行奴化教育。；接替萧瑞臣任伪河南省长，继续为日军征集粮食、劳工，镇压抗日活动，其伪政权覆盖豫北新乡、辉县等地。；任伪河南省省长期间，协助日军掠夺物资、镇压抗日力量。；继陈静斋后任伪河南省省长，驻开封，配合日军在河南的占领统治，其辖区名义上包括洛阳。；伪河南省长，任内协助日军镇压抗日力量，维持伪政权运作。；继任伪河南省省长，继续为日军服务，维持沦陷区统治。；接替萧瑞臣任伪河南省省长，继续为日军服务，推行伪政权的保甲、征粮、劳工征集等政策，其辖区包括郑州、惠济一带。；任伪河南省省长期间，协助日军征粮、征夫，推行保甲制度，加强对河南民众的控制。；任伪河南省长期间配合日军第五次治安强化运动，在郑州、开封等地强化保甲、清查户口，镇压抗日活动。；继陈静斋之后任伪河南省省长，在开封及郑州周边地区推行日伪政令，配合日军扫荡抗日力量，强化保甲制度。；继任伪河南省省长，配合日军推行治安强化运动，在河南沦陷区实施保甲连坐，镇压抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3effdfb7a316432f98cf8b52aa6e75e0','41d2b197fedd4eefa3bd64d7cebe1523',1942,'伪河南省政府省长、伪军事委员会委员','原东北军将领，投敌后任伪河南省政府省长，后调任伪军事委员会委员，在河南沦陷区协助日军维持统治，其伪政权与南阳、新野地区有行政关联。；抗战后期任伪河南省省长，在日军占领的河南地区维持伪政权，配合日军作战与后勤，直至抗战胜利。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b1b1cf8df15544a8849618b451709242','a1da16c8e56e480dac4f7b8ce876b429',1942,'伪河南省政府省长','任伪河南省政府省长期间，在河南沦陷区推行日军经济掠夺和奴化教育政策，其伪政权名义上管辖河南全境，对南阳、新野地区有行政影响。；伪河南省长，继续为日军服务，维持沦陷区秩序，新乡地区在其伪省政管辖范围内。；抗战末期任伪河南省长，继续为日军服务，直至日本投降。；抗战后期任伪河南省省长，直至日本投降，属河南伪政权头目之一。；抗战末期任伪河南省长，继续为日军服务直至日本投降。；抗战后期任伪河南省长，直至日本投降，参与日军在河南的统治。；抗战末期任伪河南省省长，继续为日军服务直至日本投降。；任伪河南省省长期间，协助日军维持河南占领区秩序，其伪政权覆盖洛阳地区。；伪河南省长，继续为日军提供行政支持，参与征发劳工与物资。；抗战末期任伪河南省省长，随日军控制河南沦陷区，直至日本投降，其伪政权活动覆盖郑州地区。；在任伪河南省省长期间，配合日军实施经济掠夺和奴化教育。；伪河南省长，协助日军掠夺河南物资、强征劳工，维持沦陷区殖民统治。；任伪河南省省长期间，继续在河南沦陷区推行日伪统治，协助日军征粮、征兵，镇压民众抗日活动，其政令覆盖郑州及豫中地区。；任伪河南省省长期间，协助日军掠夺河南物资，推行奴化教育，强化伪政权对基层的控制。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3bc7ef728d5e442bbea048c10f8b1417','c663863c960f4bf8839380e202936b81',1944,'伪河南省政府省长（未就任）','1944年日军发动豫湘桂战役后，河南大部沦陷，刘茂恩被汪伪政权任命为伪河南省政府省长，但未实际就任，其任命反映了当时河南伪政权对南阳、新野等地的名义管辖意图。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('14cec9926b0c4ecbb836ef56557d9d2a','a976a94be0bf4b76b621948c0802222f',1937,'伪华北政务委员会要员、伪河南省政府顾问','北洋军阀余孽，抗战爆发后投敌，在伪华北政务委员会任职，并曾担任伪河南省政府顾问，协助日军在河南建立伪政权，对南阳、新野地区的伪化有间接影响。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('541c9774eabb48a39db94704ddda7273','0b332f77f5834d0d8064a3cbcc8c1f1a',1938,'伪河南省政府委员、伪豫南道尹','在伪河南省政府任职，并担任伪豫南道尹，管辖豫南地区包括南阳一带，协助日军推行保甲制度、征粮征税、组织维持会，对南阳、新野地区的伪化统治有直接影响。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b034fef9d5cf4d57a9b75812004a5dde','66634d7e373a4c188b41364f4bd19166',1945,'伪南阳维持会会长','1945年日军侵占南阳期间，出面组织伪南阳维持会并任会长，协助日军维持地方秩序、征派粮款，是南阳地区直接附逆的地方头目。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fefd5e60708d429dbb6381b52f19acd4','81aa72a7f9e340cdae9f69095f69cff8',1945,'伪新野县维持会会长','1945年日军窜扰新野期间，出面组织伪新野县维持会并任会长，为日军征粮派款、维持地方，是新野当地直接附逆的汉奸头目。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7bfa67b59ccd46088454d15b03c4b95f','1ec7c49f402b4acbb11ec0197fc7341a',1938,'伪南阳道尹公署道尹','在伪河南省政府下任伪南阳道尹，管辖南阳及周边各县，协助日军推行伪化政策、组织伪军和维持会，对南阳、新野地区的沦陷区统治有直接责任。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('79fb4b26393e4cb29ef4351419f2d855','e6b90d99b49245c088a89d84f1dabeb6',1938,'伪豫南道尹公署道尹','任伪豫南道尹，管辖豫南包括南阳部分地区，协助日军建立保甲、征粮征税、组织伪军，对南阳、新野地区的伪化统治有直接影响。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2b0f67a0115b43ee91167e8db738eee9','cb5c123407db4327a62478fa50c09023',1945,'伪新野县公署县知事','1945年日军占领新野后，被任命为伪新野县公署县知事，协助日军维持地方统治、征派粮款，是新野地区直接附逆的伪政权头目。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d86b8bd2f9b94c8f9a09a945fb5156f4','ec89d405bae645879d97c60c7813b1bd',1944,'伪南阳地区伪军头目','抗战后期在豫南地区投敌，组织伪军配合日军在南阳、新野一带进行清乡、扫荡，是当地伪军头目之一。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b2c8de7c9b3143d981e2d3d59644d160','a06c0041e5294f2987f746729e510de9',1943,'伪淮海省省长、伪和平救国军第八方面军总司令','原国民党军将领，1943年投敌，任伪淮海省省长兼伪和平救国军第八方面军总司令，其伪政权管辖苏北、豫东部分地区，与河南沦陷区伪政权有联系，对南阳、新野地区有间接影响。；原国民党将领，1943年投敌，任伪淮海省省长，活动范围包括河南东部与濮阳邻近地区，配合日军维持伪统治。；原国民党将领，投敌后任伪淮海省省长，所部活动于苏北、皖北、豫东地区，对河南东部及驻马店周边有一定影响。；原国民党将领，投敌后任伪淮海省省长，其伪军活动范围涉及河南东部，与驻马店地区伪军有协同，协助日军维持占领区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c9c65d8fb63b48f98396d9434970a24d','e409ef959281461b91e8ce1eef37d186',1937,'伪华北政务委员会委员、伪河南省政府委员','原东北军将领，投敌后在伪华北政务委员会和伪河南省政府任职，协助日军在河南推行伪化政策，对南阳、新野地区有间接影响。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aff58c976de74530b7ced272616d2cd5','fefd7f9ddbac40469c751144d6cbd784',1938,'伪河南省政府委员、伪豫东道尹','在伪河南省政府任职，并担任伪豫东道尹，协助日军在河南沦陷区推行保甲、征粮、奴化教育，其伪政权与南阳、新野地区有行政关联。；在伪河南省政权中任职，负责豫东道各县伪政事务，督导周口、商水、淮阳、鹿邑等地维持会与伪县政，为日军统治服务。；在河南日伪政权中任职，参与豫东道伪政权的建立与运作，协助日军推行治安强化运动，影响范围包括周口一带。；抗战期间在河南伪政权中任职，参与伪河南省政，协助日军在豫东、豫中地区推行伪化统治，其辖区涉及漯河周边。；抗战期间在河南日伪政权中任职，协助日军推行伪化统治，参与征粮、征兵等事务。；在河南豫东地区担任伪职，协助日军维持占领区统治，参与伪政权行政与治安事务。；在豫东地区协助日军推行伪化统治，为驻马店周边伪政权提供支持。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7ae81d2d53d147bca494c3dc08065d0b','6af8c3df19e545d4a3f1c03cb0186b18',1938,'伪河南省政府财政厅厅长','在伪河南省政府任财政厅厅长，负责在河南沦陷区征粮征税、掠夺经济资源，其财政政策覆盖南阳、新野等县，对当地经济造成破坏。；在伪河南省政府掌管财政，为日军筹措军费，掠夺河南物资。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('52238038e7d8405ab682bd64fa4abaec','25917df51aa04d7793ee1451b8167067',1938,'伪河南省政府教育厅厅长','在伪河南省政府任教育厅厅长，在河南沦陷区推行奴化教育，篡改教材、宣传亲日思想，其教育政策覆盖南阳、新野等县，对当地教育领域造成附逆影响。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2e7025a47c7846c889064229077d20e0','f50cf011f8f842fc8d69caa402ffbf67',1938,'伪河南省政府警务厅厅长','在伪河南省政府任警务厅厅长，负责组建伪警察队伍，协助日军在河南沦陷区维持治安、镇压抗日活动，其警务系统覆盖南阳、新野等县。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0e2844591ff046c6b4d0ff6ecd5af64f','b13717d0c73e4b4dab35109ce0057aba',1938,'伪豫北剿共军司令','原国民党军将领，1938年在豫北投敌，任伪豫北剿共军司令，配合日军在豫北、豫西进行扫荡，其伪军活动与河南沦陷区伪政权有联系，对南阳、新野地区有间接影响。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('af4d3720dcd44dff94a1fb362d0eba8f','baf1d4d55c8f4c4ea1463288a4667364',1938,'伪豫南剿共军司令','在豫南地区投敌，组织伪军任伪豫南剿共军司令，配合日军在南阳、新野一带进行清乡、扫荡，是当地伪军头目之一。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e249e7236d024e89979e5a5df84098e3','94fef89c7dbf4d168ff8fcdb315cf40c',1945,'伪南阳警察局局长','1945年日军占领南阳期间，任伪南阳警察局局长，协助日军维持地方治安、镇压抗日活动，是南阳地区直接附逆的伪警察头目。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1c78e741593a4c638f7e3d13dcb9a16e','42fb54d5549a49d88797d3208cb21142',1945,'伪新野县警察局局长','1945年日军占领新野期间，任伪新野县警察局局长，协助日军维持地方治安、镇压抗日活动，是新野地区直接附逆的伪警察头目。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('079ed419bd0f434f8883146b9b15b118','5f82d23ccd2e45fd9e59f76c92bcc9ad',1933,'伪蒙古军总司令、伪豫东剿共军司令','内蒙古人，长期在伪蒙疆政权任职，后率伪军进入河南，在豫东、豫南配合日军扫荡，其部队曾活动于南阳以东地区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bbbee93c0c1c4089834ffa2353dceabe','b19edc2e16ec4c7d9462b01fbba0f27f',1943,'伪和平救国军第一师师长','原国民党军第一二八师师长，1943年在湖北沔阳被俘后投敌，所部伪军在豫南、鄂北活动，与南阳地区相邻。；原国民党军将领，被俘后投降日军，在湖北、湖南交界地区组织伪军，配合日军对湖南的侵略。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4bddb8023296425fabbc92dfe2052b2d','ec89d405bae645879d97c60c7813b1bd',1943,'伪豫南剿共军司令','原国民党军将领，1944年投敌，在豫南组织伪军，配合日军进攻南阳、方城一带的抗日武装。；在豫南地区组织伪军，配合日军进攻抗日根据地，活动范围包括南阳东部及驻马店一带。；抗战后期在豫南投敌，组织伪军配合日军扫荡确山、泌阳、新蔡一带抗日武装，残害抗日军民。；抗战后期在豫南投敌，组建伪军配合日军清乡，活动于驻马店、确山、西平一带，袭击抗日武装。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('69808df237b448e582a6b56da5dfc999','40fa834a858647699b6f23e9c7383015',1945,'伪南阳维持会会长','1945年日军侵占南阳期间，出面组织伪南阳维持会，为日军筹粮、派夫、维持治安，协助日军统治南阳城区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0753cd2a3b5f4df6b4d7358ff7f72de1','42fb54d5549a49d88797d3208cb21142',1945,'伪方城县维持会会长','1945年日军侵占方城期间，组织伪方城维持会，充当日伪政权在方城的代理人，为日军征粮、派款、拉夫。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f1576dfb71ef42a3b516aad4e5a43e02','a14f29cadc5340259c41fbf40ee2cf42',1945,'伪方城县保安团团长','方城本地人，1945年日军占领方城后投敌，组建伪保安团，配合日军清乡、扫荡，镇压抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d4ef0d88c6334ee68571cd0ee5cb88e7','81aa72a7f9e340cdae9f69095f69cff8',1945,'伪南阳警察局局长','1945年日军侵占南阳后，出任伪南阳警察局局长，协助日军维持城区秩序，抓捕抗日人员。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('308466122b6b48748ffabce2ac176d52','d6dfd188b7474385b7f0cfbde3069fe0',1945,'伪南阳县政府县长','1945年日军占领南阳期间，出任伪南阳县政府县长，为日军征粮、派款、推行奴化教育。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5ebd2e54445a4d35830a6661ecebb874','3528daef89c7440fa850f8592d84f11f',1945,'伪方城县警察所所长','1945年日军侵占方城后投敌，任伪方城县警察所所长，带领伪警察配合日军搜查、抓捕抗日人员。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1888b759dedf4e8d9b1f3053b1d94023','f86731da17ce4a1b95263b9bcf38b69c',1944,'伪豫南特别区行政公署专员','1944年投敌，任伪豫南特别区行政公署专员，管辖包括南阳在内的豫南地区，为日军筹粮、派夫、推行伪化教育。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('281cd086da5445ec8202079f0762f82f','a36adf024ce44c63a7d6f7c343eb3712',1940,'伪河南省政府委员','河南人，抗战期间投敌，任伪河南省政府委员，参与伪政权决策，协助日军在河南推行殖民统治，其影响波及南阳地区。；在伪河南省政府任职，参与制定伪政策，协助日军在河南包括漯河地区推行奴化教育、经济掠夺。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4ce4c47907784ad28b35c108d7cd820c','d409a62a1fcf424a82d99abd16ad9bea',1940,'伪河南省教育厅厅长','抗战期间投敌，任伪河南省教育厅厅长，推行奴化教育，在南阳、方城等地设立伪学校，灌输亲日思想。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5f61e12bb695483dbe45aa64e157e2f8','b77a9c0384c94aa5bcd13e6c90ce35f9',1940,'伪河南省宣传处处长','抗战期间投敌，任伪河南省宣传处处长，为日军进行舆论宣传，在南阳、方城等地散发亲日传单、组织亲日集会。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d2d975e4cff4420598cf7342cf9a953f','98348583b1c343d2a65aeb302a367bcf',1945,'伪南阳新民会会长','1945年日军侵占南阳后，组织伪南阳新民会，进行亲日宣传，协助日军推行奴化教育。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('51fb93aeec864aeba812fde5c7e77247','46385304fea34954ac978fb8f4443448',1945,'伪方城县新民会会长','1945年日军侵占方城后，组织伪方城县新民会，为日军进行亲日宣传，拉拢当地士绅附逆。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d77976bd7a234f2db8b7d5dfa7ab2248','522f8e16c7854ca5accb55f51b413dd1',1945,'伪南阳商会会长','1945年日军侵占南阳后，出任伪南阳商会会长，为日军筹款、筹粮，协助日军控制南阳经济。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9b8510dffb334fe1bb2c04e51ef79fb2','fcb3e5ff966f4327a818cbc1e3244da5',1938,'伪河南省警务厅厅长、伪开封市市长','在河南伪政权中负责警务，组建伪警察队伍，配合日军搜捕抗日人员，其警务系统延伸至南阳地区。；在伪河南省政府中负责警务，参与镇压抗日分子，管理伪警察队伍，配合日军维持开封及周边地区治安。；河南伪政权高级汉奸，参与全省伪警察与伪行政系统建设，其政令覆盖豫东周口等地，协助日军镇压抗日人员。；在伪河南省政府中担任警务要职，后任伪开封市市长，协助日军建立伪警察体系，镇压抗日活动，维护日伪在河南的统治秩序。；在伪河南省政府中负责警务，参与镇压抗日活动，搜捕抗日人员，维持日军在河南沦陷区的治安统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3889894d6ffc4fd0bdd44b04346e15ee','2f7bbac25fb94f79a0527f838ea60d46',1940,'伪桐柏县维持会会长','桐柏县人，日军侵入桐柏后出面组织维持会，充当日军耳目，协助征发民夫、粮食，破坏当地抗日组织。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7b430b87a88f49a085a7e4e6bbfaaa0e','d6dfd188b7474385b7f0cfbde3069fe0',1940,'伪南阳县政府筹备处处长','在南阳沦陷区参与伪政权筹建，协助日军推行保甲制度，登记户口，压制抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('58375d387615428ab03ff787d6743e26','fe7588d226fa430ea2eda3d08a162f2f',1941,'伪桐柏县保安团团长','桐柏人，率伪保安团配合日军扫荡桐柏山区抗日根据地，捕杀抗日军民，抢掠财物。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4e37fe695e6240ca93761c28e51f2067','ec89d405bae645879d97c60c7813b1bd',1942,'伪南阳地区清乡队队长','在南阳地区组织伪清乡队，配合日军进行清乡，搜捕抗日人员，焚烧村庄，勒索民众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aeed0580b8d64f878e5a49c820fdd9a0','42fb54d5549a49d88797d3208cb21142',1939,'伪河南省宣传处科长','在伪河南省宣传部门任职，编写亲日宣传材料，推行奴化教育，在南阳等地散发反共传单。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8f0b1bff78874d0c9655e872bc26a8fc','53bdb8682e984f6e8c77b531f0d4ae7a',1940,'伪南阳新民会会长','南阳人，任伪新民会会长，组织亲日团体，宣传“大东亚共荣”，协助日军进行思想控制。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('736a166ec6b5444fa8b84cce9cf75e3c','8853ebc9482649aca1ee056bfe54c04c',1941,'伪桐柏县警察局局长','桐柏人，任伪警察局长，带领伪警察配合日军搜查抗日分子，刑讯逼供，残害百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0311f952f1dc451ab53efb8389aab15e','62a6d6c8e7ab4bbfbc92c5b14abbde74',1938,'伪立法院院长、伪行政院院长、伪国民政府代主席','广东乳源人，汪伪政权核心人物，历任伪立法院院长、伪行政院院长、伪国民政府代主席，其伪政权统治范围包括河南沦陷区。；广东乳源人，汪伪政权核心人物，其伪政权统治范围包括河南部分地区，推行亲日政策，镇压抗日力量。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('37c5f6c122294f6aa13f24bd8f8d2051','41d2b197fedd4eefa3bd64d7cebe1523',1940,'伪军政部长、伪河南省长','辽宁辽阳人，汪伪政权军政部长，后任伪河南省长，直接负责河南沦陷区伪政权事务，包括南阳周边地区的伪化统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bcd05ec237134f56b9b9dc6fa2433bb6','f50cf011f8f842fc8d69caa402ffbf67',1938,'伪内政部长、伪江苏省长','福建闽侯人，汪伪政权内政部长，参与伪政权对河南等地的统治政策制定。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f6afa83dac454d6592730548fe6f0e7f','28c69a91441d4439abc95701e2c6787a',1938,'伪工商部长、伪实业部长','浙江永嘉人，汪伪政权工商部长，参与对河南沦陷区的经济掠夺。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3bebe430866342a2aebe55d125e0124b','07ff958e7f18410f864975f09234ac7e',1938,'伪特工总部主任、伪警政部长','浙江遂昌人，汪伪特工总部主任，其特务组织活动范围包括河南沦陷区，镇压抗日力量。','省部级/大军区级要员','hanjian');
