INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1ca7b383a48b409e93fc86a625cf530b','d3256e7274c448058c67c4d51c3fa885',1940,'伪宣传部次长、伪法制局长','浙江嵊县人，汪伪政权宣传部次长，参与奴化宣传，影响包括河南沦陷区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('12ecbe937ade4ba598f0f231a8c7efd3','ef676fac9bb24126bcc992f39c87c979',1940,'伪开封绥靖公署主任、伪河南省长','河北清苑人，原西北军将领，投敌后任伪开封绥靖公署主任、伪河南省长，直接统治河南沦陷区，包括南阳周边地区。；原西北军将领，抗战期间投敌，任伪开封绥靖公署主任、伪河南省长等职，协助日军统治河南。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('462695deb5b049cd9cefef711907f677','fcb3e5ff966f4327a818cbc1e3244da5',1938,'伪河南省警务厅长、伪开封市长','河南人，抗战期间在伪河南省政府任职，任伪警务厅长等职，参与河南沦陷区的伪化统治。；在伪河南省政府任职，负责警务与地方治安，协助日军镇压抗日民众，其警务系统覆盖河南各县包括平顶山地区。；抗战期间投敌，任伪河南省警务厅长、伪开封市长等职，协助日军维持河南占领区治安。','市县厅局级','hanjian');
