INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('068f849d5e0f4dfeb84a1aa7e5595d4d','fcb3e5ff966f4327a818cbc1e3244da5',1938,'伪河南省警务厅长、伪开封市市长','在伪河南省政府任职期间，负责警务与特务活动，镇压抗日分子，其警务系统延伸至南阳各县。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('79bf68b9c42f48a4a5b0e7eb3f980f78','d31196ebd5bb4af4a5f843ae6817e5ea',1940,'伪南阳县县长','在日军控制下出任伪南阳县县长，推行保甲制度，征发民夫、粮食，配合日军扫荡抗日武装。','基层头目','hanjian');
