INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5d27839d41be49b3945c29e3e0aa587b','cb5c123407db4327a62478fa50c09023',1940,'伪方城县县长','在日军支持下出任伪方城县县长，活动于南阳东北部，与社旗地区相邻，配合日军征粮、清乡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f81ee4cf75184a5b8f32cfa36425b19f','ec89d405bae645879d97c60c7813b1bd',1943,'伪军团长（后投敌）','原国民党军军官，1943年在河南投敌，所部伪军在南阳、方城、社旗一带活动，配合日军进攻抗日根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('15a502dec3a54d01a2ff30c6681ea098','e58a1196151242e997361b25a1cafb1b',1940,'伪南阳警察局局长','在伪南阳县政权下掌管警察，搜捕抗日人员，镇压民众反抗，为日军维持治安。；1945年日军占领南阳后，出任伪警察局局长，负责城区治安，抓捕抗日嫌疑人员。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0078791af1c54c889a9c1027ec60d680','42fb54d5549a49d88797d3208cb21142',1940,'伪泌阳县县长','在日军占领下出任伪泌阳县县长，活动于南阳东部边缘，与社旗地区有联系，推行伪化统治。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0a9cdca8a18141bea5220a612f27d427','2bd76bd4f7874f8f8becd896967ac4f3',1945,'伪南阳维持会会长','1945年日军侵占南阳期间，出面组织伪南阳维持会，协助日军维持占领秩序、征发物资，为日军侵略服务。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('231cc7270f874276a3fa96468b36fff6','42fb54d5549a49d88797d3208cb21142',1945,'伪南阳县政府筹备处主任','1945年日军占领南阳后，参与筹建伪南阳县政府，协助日军推行伪化统治，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cf360aa3aee94633a21212a094d7c935','81aa72a7f9e340cdae9f69095f69cff8',1945,'伪西峡口维持会会长','1945年日军侵占西峡口期间，组织伪维持会，为日军筹集粮草、提供情报，协助日军控制当地。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('46b11465b17e446ab4f9485fa91e6f8e','ec89d405bae645879d97c60c7813b1bd',1944,'伪豫西剿共军司令','抗战后期在豫西投敌，组织伪军配合日军扫荡抗日根据地，其活动范围包括南阳西部及西峡周边地区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('469dcc3d657d400091454136aac97594','a976a94be0bf4b76b621948c0802222f',1938,'伪河南自治政府筹备委员','北洋旧军阀，抗战初期在河南参与伪政权筹备活动，为日军在河南建立伪统治机构效力。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8827d592373549f5a55ff8c1435b0ce2','24b27e92935346b5b0c750031defdd1f',1938,'伪河南省政府省长','抗战期间任伪河南省政府省长，协助日军推行伪化统治，其伪政权覆盖河南大部，包括南阳、西峡地区。；日军侵占河南后出任伪河南省长，主持伪省政，推行日伪统治，其辖区涵盖豫北新乡一带。；抗战时期河南伪政权头目之一，参与日军在河南的殖民统治与治安强化运动。；日军侵占河南后，出任伪河南省政府省长，协助日军推行殖民统治，组织伪政权、征粮征丁，镇压抗日力量。；日军侵占河南后，出任伪河南省政府省长，协助日军维持占领区统治，推行伪化政策。；日军侵占河南后，出面组织伪河南省政府并任省长，协助日军推行殖民统治、征粮征丁。；日军侵占河南后，出任伪河南省政府省长，协助日军推行殖民统治，镇压抗日活动。；1938年日军占领河南北部后，出任伪河南省政府省长，驻开封，管辖豫北道（含新乡、辉县），推行奴化教育、征发劳工、配合日军扫荡。；日军侵占河南后，出任伪河南省政府省长，协助日军维持占领区统治。；日军侵占河南后出任伪河南省长，主持伪省政，推行日伪统治，为河南地区主要附逆人物之一。；日军侵占河南后出任伪河南省长，主持伪省政，推行奴化教育、征粮征丁，配合日军维持占领区统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5d553297959249809f7588178b8a8fdb','fcb3e5ff966f4327a818cbc1e3244da5',1940,'伪南阳道尹','任伪南阳道尹期间，协助日军在南阳地区推行伪化教育、经济掠夺，镇压抗日民众。','无明确职位或一般帮凶','hanjian');
