INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('405a5984c5c3473f8e233a539a63905c','793dba30c5cd4e9ab0835412a8dc7906',1937,'伪河南省省长、伪河南省维持会会长','河南本地人，日军侵占河南后出面组织维持会，后任伪河南省省长，协助日军征粮、征夫，镇压抗日活动。；河南本地士绅，抗战初期即组织维持会迎接日军，后任伪河南省省长，协助日军征粮、征夫，镇压抗日活动。','基层维持会/地方自治头目','hanjian');
