INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0c5839a68fe44873b906fdd2436b8a7e','d49c34074e9448bc9a73b99ceca35092',1945,'伪邓县新民会会长','1945年日军侵入邓县期间，组织新民会，进行亲日宣传，协助日军维持地方统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cae1f19f16d7486d864a915ef8cc6638','41d2b197fedd4eefa3bd64d7cebe1523',1940,'伪河南省政府主席、伪开封绥靖公署主任','辽宁辽城人，原东北军将领，投敌后任伪河南省政府主席，在开封等地主持伪政，配合日军维持河南沦陷区统治。；汪伪政权在河南的重要头目，负责河南沦陷区伪军政事务，其势力范围覆盖商丘、民权等豫东地区，配合日军扫荡抗日力量。；1945年任伪河南省政府主席兼伪开封绥靖公署主任，抗战胜利后被国民政府逮捕审判。','基层头目','hanjian');
