INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0301de4aee40445b865f11bc71a6e7cd','e6b9d1970cba464083a2a63c31b8a9a4',1940,'伪鹿邑县保安大队大队长','鹿邑伪军头目，率部配合日军对鹿邑、郸城、亳县交界地区进行清乡，镇压抗日武装，强征粮食和壮丁。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('764394a651c749f384e58d0b2228ef90','85e64c3cc5dd44a783d2ba097702bcd5',1939,'伪周口新民会会长','周口伪新民会头目，负责宣传亲日思想、组织伪民众团体，协助日军推行保甲制度和物资统制，进行奴化宣传。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('23d4539ddf2549a79c96166b630d063a','848992e841c9488c8cdcf56cad9f079c',1938,'伪和平救国军第一军军长、伪第四方面军总司令、伪河南省政府豫东道尹','河南柘城人，抗战期间投靠日军，在豫东商丘、周口、柘城、鹿邑一带组建伪军，配合日军扫荡抗日根据地，搜捕抗日人员，横征暴敛。；河南柘城人，抗战期间投靠日军，在豫东商丘、周口、太康一带组建伪军，配合日军扫荡抗日根据地，搜捕抗日人员，横征暴敛，是豫东地区最具实力的汉奸武装头目之一。；河南柘城人，抗战期间在豫东周口、商丘一带组织伪军，投靠日军，配合日军进攻抗日根据地，搜刮民财，残害抗日军民。；河南柘城人，抗战期间在豫东周口、商丘一带组织伪军，投靠日军，配合日军进攻抗日根据地，统治豫东伪政权，是周口及周边地区最具代表性的汉奸头目之一。；河南柘城人，抗战期间在豫东周口、淮阳、鹿邑、柘城一带组织伪军，投靠日军，配合日军扫荡抗日根据地，统治豫东沦陷区，是周口及淮阳周边地区最具实力的汉奸武装头目之一。；河南柘城人，抗战期间在豫东周口、商丘一带组织伪军，投靠日军，配合日军进攻抗日根据地，统治豫东伪政权，其势力范围覆盖周口及郸城周边地区。；河南柘城人，抗战期间在豫东商丘、宁陵、柘城一带组织伪军，投靠日军，任伪和平救国军第一军军长、伪第四方面军总司令等职，配合日军进攻抗日根据地，控制商丘及周边地区，是豫东地区最具实力的汉奸武装头目之一。；柘城人，抗战期间投靠日军，在商丘、柘城、鹿邑、亳州一带组建伪军，配合日军扫荡豫东抗日根据地，搜捕抗日人员，强征粮款，是豫东地区最具实力的汉奸武装头目。；河南柘城人，抗战期间在豫东商丘、民权、睢县、柘城一带组织伪军，投靠日军，配合日军扫荡抗日根据地，统治豫东伪政权，是商丘及民权周边地区最重要的汉奸武装头目之一。；河南柘城人，抗战期间在豫东商丘、永城一带组织伪军，初投日军任伪和平救国军第一军军长，后任伪第四方面军总司令，配合日军扫荡豫皖苏抗日根据地，1943年任伪河南省政府豫东道尹，在商丘、永城等地推行伪化统治、征粮抓丁。；河南柘城人，抗战期间投靠日军，在商丘、睢县、柘城、太康一带组建伪军，配合日军扫荡抗日根据地，推行伪化统治，是豫东地区最具实力的汉奸武装头目之一。；河南柘城人，抗战期间在豫东商丘、虞城、柘城一带组织伪军，投靠日军，配合日军扫荡抗日根据地，统治豫东沦陷区，是商丘及周边地区最具代表性的汉奸武装头目之一。；商丘柘城人，抗战期间在豫东商丘一带组织伪军，先后投靠日军、汪伪政权，任伪和平救国军第一军军长、伪第四方面军总司令等职，长期盘踞商丘、柘城、鹿邑、亳县一带，配合日军进攻抗日根据地，征粮抓丁，残害民众。；河南柘城人，抗战期间投靠日军，在豫东、豫中一带组织伪军，配合日军进攻抗日根据地，镇压民众，控制平顶山周边部分区域。；河南柘城人，抗战期间投靠日军，在豫东、豫中一带组织伪军，配合日军进攻抗日根据地，其伪军势力曾活动于平顶山周边地区，1945年抗战胜利后被国民党收编。；河南柘城人，抗战期间投靠日军，在豫东、豫中一带组建伪军，配合日军进攻抗日根据地，其伪军活动范围覆盖漯河、周口、许昌等豫中地区，对包括召陵在内的河南沦陷区实行伪化统治。；河南柘城人，抗战期间投靠日军，在豫东、豫中一带组织伪军，配合日军进攻抗日根据地，曾任伪河南省政府豫东道尹，其伪军活动范围覆盖漯河及周边地区。；河南柘城人，抗战期间投靠日军，在豫东、豫中一带组织伪军，配合日军进攻抗日根据地，1944年后任伪第四方面军总司令，所部活动范围覆盖漯河、舞阳周边地区。；河南柘城人，抗战期间投靠日军，在豫东、豫北一带组织伪军，配合日军进攻抗日根据地，控制包括濮阳周边在内的豫北部分地区，后任伪第四方面军总司令，是河南境内影响较大的汉奸武装头目之一。；河南柘城人，抗战期间投靠日军，在豫东、豫南一带组织伪军，配合日军进攻抗日根据地，曾任汪伪政权军事要职，长期盘踞河南东部及郑州周边地区。；河南柘城人，抗战期间投靠日军，在豫东、豫南一带收编土匪、组建伪军，配合日军进攻抗日根据地，驻马店、上蔡周边地区曾受其伪军势力影响。；河南柘城人，抗战期间投敌，在豫东、豫南一带组织伪军，配合日军进攻抗日根据地，其伪军活动范围覆盖驻马店及周边地区，是河南境内影响较大的汉奸武装头目之一。；河南柘城人，抗战期间投敌，在豫东、豫南一带收编土匪、伪军，配合日军进攻抗日根据地，长期控制商丘、周口、驻马店周边部分地区，是河南境内影响较大的伪军头目之一。；河南柘城人，抗战期间投靠日军，在豫东、豫南一带收编土匪、组建伪军，配合日军进攻抗日根据地，其伪军活动范围覆盖驻马店、周口、商丘等地，对河南民众横征暴敛。；河南柘城人，抗战期间投靠日军，在豫东、豫南一带收编土匪、组建伪军，配合日军进攻抗日根据地，驻马店、西平周边地区亦受其伪军活动影响。；河南柘城人，抗战期间投靠日军，在豫东、豫南一带收编土匪、组建伪军，配合日军进攻抗日根据地，驻马店地区亦受其伪军势力影响。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('204339a3672d4f408486d515b82ed236','cd6bd8e57e4147f5b633a46a11754965',1938,'伪周口警察所所长','在周口地区充任伪警察头目，协助日军清查户口、抓捕抗日嫌疑人员，勒索商户百姓。；在周口地区充当伪警察头目，带领伪警配合日军抓捕抗日人员，勒索商户，欺压百姓。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f1003e49592546dbbd2040acc2a73f4b','304399e6f8f94bd5912316df10e1ac2a',1938,'伪淮阳县政府县长','淮阳沦陷后投敌，任伪县长，在淮阳、周口一带推行保甲连坐，为日军征粮征丁，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0f9e087ebb97422bbfd1c7b1ef049ec7','772426e687914a769c5c7e4fedacadc5',1939,'伪豫东剿共军司令','在商丘、周口、鹿邑一带收编土匪武装，组织伪军配合日军进攻睢杞太抗日根据地，残害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4b069a8417a2469abaf328f407a51d1f','bbd63c1ca8684efa918c037030708eac',1938,'伪河南省政府委员、伪豫东道尹','在开封、商丘、周口等地任职伪政权，推行日军殖民统治政策，协助掠夺豫东物资。；在河南沦陷区伪政权中任职，参与豫东地区伪政权的行政与治安管理，为日军统治提供支持。；在河南伪政权中任职，参与推行日军殖民统治政策，协助征粮征兵，镇压河南抗日力量。；在伪河南省政府任职并一度主持豫东道伪政，商丘一带为其管辖区域，协助日军推行治安强化运动。；在河南沦陷区任伪职，协助日军推行保甲制度、征发劳工，其管辖范围涉及豫中包括许昌在内的部分地区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('98e061ff173646d7bbdec696cdab0b6b','5f82d23ccd2e45fd9e59f76c92bcc9ad',1944,'伪蒙古军总司令（后任伪河南省保安司令）','抗战后期在河南任职伪军，协助日军维持豫东治安，其部队曾驻扎周口附近地区。；抗战后期在河南任职伪职，参与日军在豫东的统治，其部下在周口周边地区征粮抓丁，镇压民众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('840aab1d76e34b778c05e872548126fe','fefd7f9ddbac40469c751144d6cbd784',1940,'伪河南省保安司令部参谋长','在伪河南省政府任职，参与组织伪保安队，在豫东包括周口地区进行反共清乡活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c05a36fbbed64c008c0b0789d5248a75','fcb3e5ff966f4327a818cbc1e3244da5',1938,'伪周口商会会长','周口沦陷期间任伪商会会长，为日军筹集物资，协助日军对周口经济进行掠夺。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1cb56ff68f69437faad14b397bb9a7bb','aea3838771d8458ba6073d341943bb27',1939,'伪豫东道公署警务科长','在商丘、周口一带负责伪警务，指挥伪警察配合日军搜捕抗日人员，镇压民众反抗。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2372008ccc9c4cc4977704d4189b6cc6','c41163edd0b74776acd6570b3d8fceb2',1938,'伪淮阳维持会副会长','在淮阳、周口地区协助日军建立伪政权，推行奴化教育，为日军提供情报。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('599a3a73668d43fb8e7bc5da3133ff0b','9f7b3ed9c76f4eea8211fd8ebc40a461',1943,'国民党军新编第五军军长、伪豫北剿共军总司令（投日后）','1943年在河南林县一带被日军俘虏后投敌，任伪职，配合日军在河南境内进行反共与治安作战，其部队活动范围涉及豫东、豫北，对河南抗战局势造成严重破坏。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('760be3d9cd734d5da7d6e947c6ccb5f7','5ec2ad124b2f429482b1a90a7f8d4a92',1943,'国民党军第二十四集团军总司令、伪晋冀鲁豫剿共军总司令（投日后）','1943年在河南北部被日军俘获后投降，任伪军总司令，协助日军在河南及华北地区清乡、扫荡，是抗战后期河南境内影响较大的投敌将领之一。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2263ff1efbdd47e58b6238044d4a0d0b','2bd76bd4f7874f8f8becd896967ac4f3',1938,'伪商水县维持会会长（一说伪商水县知事）','商水沦陷后出面组织维持会，为日军筹粮、派夫、维持地方伪秩序，协助日伪政权控制商水城乡，压迫当地民众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('04aa83f3005f4b1baefb50c9e63bec74','cd6bd8e57e4147f5b633a46a11754965',1938,'伪商水县保安队头目','商水本地人，抗战期间投靠日军，纠集地方武装编入伪保安队，配合日军下乡扫荡、抓捕抗日人员，勒索百姓，为害一方。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6f33eb2074fb4911ba1c3462e8642f84','067b8e028f5740dfa47b25db64ed7534',1938,'伪周口维持会会长','周口沦陷后组织维持会，替日军征集物资、拉夫派款，协助建立伪基层政权，是周口地区较早附逆的地方头面人物之一。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e0fba632519a43b29d3ddb77bdde4d3a','4b034429b0834c0ebe93d3a9b2e7c572',1938,'伪淮阳县知事','在淮阳一带为日军推行伪政，组织伪保安团，配合日军对周口、商水、淮阳交界地区进行治安强化，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4afe7cff80db407fad41f9d6a2076937','21853206ad2b417598d1af0b4b3a4782',1938,'伪鹿邑县维持会会长、伪鹿邑县知事','鹿邑沦陷后投敌，主持伪县政，为日军征粮征兵，协助日军控制鹿邑、郸城、商水一带交通线，迫害抗日群众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1731c8c5a3344f35bec07f444aae6fc7','bbd63c1ca8684efa918c037030708eac',1938,'伪太康县知事','在太康任伪职期间，配合日军扫荡豫东抗日根据地，组织伪自卫团，强征民夫修筑据点，对周口北部地区造成较大危害。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e6b6cd8823074ca0959fa918b9be6363','c692801ac2c3420b89c5234722019808',1938,'伪西华县维持会会长','西华沦陷后出面维持伪秩序，为日军筹款筹粮，协助伪军清乡，活动范围靠近周口、商水，是豫东附逆地方势力之一。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ab051e612e1e480cbfb4e0e01fd0974b','e092244794474f1885a5f861c38d21c9',1938,'伪项城县知事','项城沦陷后投靠日军，任伪县知事，推行保甲连坐，协助日军控制项城、商水、周口交界地区，镇压抗日人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('86227f970529480a977d4be6bdebf7c1','4c75963c29ea48b79ac340fa9d8bbd32',1938,'伪周口警察所所长','周口本地地痞出身，投日后任伪警察头目，带领伪警察配合日军搜查、逮捕抗日嫌疑人员，敲诈商民，民愤极大。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d141db0a6c2948e5b3f7b0a324990fe6','c41163edd0b74776acd6570b3d8fceb2',1938,'伪商水县教育科科长','在商水推行奴化教育，强制学校使用日伪教材，宣传“大东亚共荣”，组织师生参加日伪集会，是文化教育领域附逆者。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e588036a4c0145dc900911a40c4ecb68','6ee404958cec40e7adb51cb4dd7ece1f',1938,'伪商水县某区保甲长、情报员','担任伪保甲长期间，为日军搜集抗日武装情报，带领日伪军抓捕抗日家属，强征粮食和壮丁，直接危害商水乡村。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e67d3b952fc34b2b8e6c39c22c2f9d94','2bd76bd4f7874f8f8becd896967ac4f3',1938,'伪太康县维持会会长、伪太康县县长','太康沦陷后出面组织维持会，后任伪县长，为日军征粮派款、拉夫修路，协助日伪维持太康及周边地区统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d982747b8b9040d2804bea858ddbfefd','d1fa608f414c45a1a0bf38f7543bc966',1939,'伪太康县保安团团长、伪军头目','在太康及周口周边地区收编土匪、地痞组成伪保安团，配合日军进攻抗日武装，残害地方百姓，控制太康部分乡村。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1a2fd2e44082433891d94068065741a5','48978bca01144ac987c2b560564f5c8f',1938,'伪河南省政府委员、伪豫东道尹公署官员','在开封、商丘、周口一带参与伪政权事务，协助日军推行治安强化运动，督导豫东各县伪政权建立与征粮。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5d2cbc22b3674a1baaf6f2b0f7611e6f','fcb3e5ff966f4327a818cbc1e3244da5',1938,'伪河南省政府警务厅厅长、伪开封市市长','在河南伪政权中负责警务与地方治安，协助日军在豫东包括周口、太康一带清乡、抓捕抗日人员。；在伪河南省政府中负责警务，协助日军镇压河南抗日活动，其警务系统覆盖郑州、新密等豫中地区。；在伪河南省政权中负责警务与地方治安，协助日军镇压抗日活动，其警务系统延伸至河南各县，包括豫南驻马店地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c7009a2ae7ae4533aa6bc56740d7011c','d409a62a1fcf424a82d99abd16ad9bea',1938,'伪周口维持会会长','周口沦陷后组织维持会，为日军筹粮筹款、维持地方秩序，协助日伪控制周口及沙河沿线。','基层维持会/地方自治头目','hanjian');
