INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d90003b08f284db3af0670be17084017','772426e687914a769c5c7e4fedacadc5',1939,'伪军豫东剿共军司令','在豫东周口、太康、鹿邑一带活动，率伪军配合日军进攻抗日游击区，抢掠民财，杀害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ab41868005bb4b06ad7a7613bbfde03f','614d7c7e23ff423f92117c0c884eee87',1940,'伪和平救国军师长','在豫东地区驻防，与张岚峰部协同，在太康、柘城、周口一带参与日伪扫荡和治安作战。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('080b8965a20449ec934d22a638058f2a','304399e6f8f94bd5912316df10e1ac2a',1938,'伪豫东道公署道尹','在豫东包括周口一带任职伪政权，推行日军殖民统治，征发民夫、物资，协助日军扫荡。；在商丘设立伪豫东道公署，统辖商丘、民权、睢县、柘城等县伪政权，推行日军殖民统治政策，征发物资，配合日军军事行动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ba620a7f48204c7f8553320a0b1f8520','bbd63c1ca8684efa918c037030708eac',1938,'伪淮阳县政府县长','淮阳邻近周口，其任伪县长期间为日军征粮派款，组织伪自卫团，配合日军对周口周边地区进行清乡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('916cbd6098204babb7f8af0fd2003cda','c692801ac2c3420b89c5234722019808',1938,'伪商丘维持会会长','商丘为豫东重镇，与周口同属豫东地区，其组织维持会为日军服务，协助建立伪政权，镇压抗日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fe8aa34d405142d5b7b84f98629603db','7c4f055fe1bf4b1ea64573ebbd87eeb8',1938,'伪周口商会会长','周口沦陷期间担任伪商会会长，为日军筹集物资，强制商户捐款，协助日军经济掠夺。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('eb09a6c677e1454e907c6d3a7787141c','fefd7f9ddbac40469c751144d6cbd784',1938,'伪和平救国军第一军副军长、伪军事参议院副院长','辽宁人，早年东北军将领，抗战后投敌，曾与张岚峰在豫东地区共同组织伪军，参与对周口、商丘一带的治安作战和扫荡。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4d5296a7624543359bc8b4be894cf902','66634d7e373a4c188b41364f4bd19166',1938,'伪扶沟县维持会会长、伪扶沟县县长','扶沟县地方士绅，1938年日军侵占扶沟后出面组织维持会，后任伪扶沟县县长，为日军征粮派款、维持伪秩序，是扶沟本地直接附逆的代表人物。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('486c627b72804dcc88cd173bddc64e9f','b1303da80b994629ba3bf2748d8842c1',1938,'伪豫东道尹公署道尹','抗战初期在豫东地区投敌，任伪豫东道尹，管辖商丘、周口、淮阳、扶沟等县伪政，协助日军推行保甲连坐和物资统制。','无明确职位或一般帮凶','hanjian');
