INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('04e1849c3a5f4fa3a7f2fc5493c8ba05','fefd7f9ddbac40469c751144d6cbd784',1938,'伪和平救国军总司令、伪军事委员会北平分会委员','河南项城人，早年北洋军阀出身，抗战期间投敌，参与伪军组织与指挥，其势力与豫东周口、淮阳地区有联系，属河南籍重要汉奸军事人物。；辽宁人，抗战期间投靠日军，曾任伪和平救国军总司令，活动范围涉及河南东部及周口一带，协助日军收编地方武装、维持伪政权统治。','基层头目','hanjian');
