INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('62c977ad534e4253bd297e8f677fe692','42fb54d5549a49d88797d3208cb21142',1939,'伪淮阳县教育科科长','在淮阳沦陷区推行奴化教育，改编教材，强制学生学习日语和亲日内容，为日军培养顺民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5ac8c8b6f684406aa0f871ab7097a594','5f82d23ccd2e45fd9e59f76c92bcc9ad',1937,'伪蒙古军总司令、伪华北政务委员会军事委员','内蒙古人，其伪军活动主要在华北，但与河南伪政权有军事协作，间接影响周口、淮阳地区伪军组织。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3590c25f4427485da15275ab1fecf6c2','5bb6456b293d479e87f26e53e7afaa80',1938,'伪淮阳县警察局局长','在淮阳任伪警察局长，负责城区治安，抓捕抗日人员，协助日军清查户口、发放良民证。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('afe3c102727e4e5eb2aa889be46e8306','0ce82afb041f4eb4a6fb886726d0274f',1939,'伪周口镇保甲长','在周口镇任保甲长，为日军摊派粮款、征集劳工，监视居民言行，举报抗日嫌疑人员。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e8a1f063a62949a989876fbc6295177d','3528daef89c7440fa850f8592d84f11f',1938,'伪淮阳商会会长','控制淮阳沦陷区商业，为日军采购军需物资，协助经济封锁，压榨商户和民众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f5b8446c8c754587b33c1792c3b7cd45','c663863c960f4bf8839380e202936b81',1940,'伪豫东道保安司令部参谋','在豫东道伪保安系统任职，参与制定扫荡计划，协调周口、淮阳等地伪军行动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('199129b6eba4439c8b48142627f66a98','d485c70cf19e49daa34f4a4e02302297',1938,'伪太康县长、伪淮阳专区联络员','在太康、淮阳一带任伪职，负责日军与伪政权间的联络，征调粮食、劳工，配合治安强化运动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bee3be4344fe419d81fca28fcead1bfe','6c1d8a87bb794f058ebc060e7bf1dcef',1939,'伪淮阳自卫团团长','组织淮阳地方伪自卫团，配合日军守备据点，清乡扫荡，迫害抗日家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('84c4a89ffe354d2cab23da70bb4ffd63','793dba30c5cd4e9ab0835412a8dc7906',1938,'伪河南省省长、伪豫东道尹','抗战期间投靠日军，曾任伪河南省省长及伪豫东道尹，管辖包括周口部分地区在内的豫东沦陷区，协助日军征粮、征丁、维持治安。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ab93df06d0564f6f8c3b06171ea0d64c','d409a62a1fcf424a82d99abd16ad9bea',1938,'伪西华县维持会会长','西华县地方士绅，日军侵占西华后出面组织伪维持会，任会长，协助日军维持地方秩序、征派粮款，后伪维持会改组为伪县公署。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('603280a0b75540bda795834e0c6c3f58','bd75a24948f34fdb834336b0c220847c',1938,'伪周口维持会会长','周口镇商人，日军占领周口期间出面组织伪维持会并任会长，为日军筹粮筹款、招募伪警察，维持沦陷区统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('303fcd095bd54350a3ab9c5a6c6be1a5','4b034429b0834c0ebe93d3a9b2e7c572',1939,'伪淮阳县公署知事','淮阳人，抗战期间投敌，任伪淮阳县公署知事，管辖区域邻近西华、周口，配合日军推行保甲制、征粮征丁，镇压抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9371124417ee4866bb4ae51323b84c24','304399e6f8f94bd5912316df10e1ac2a',1940,'伪豫东剿共军司令','原国民党地方武装头目，后投靠日军，任伪豫东剿共军司令，在周口、西华、淮阳一带配合日军进攻抗日根据地，捕杀抗日人员。','基层头目','hanjian');
