INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('abf66569c1b44fc08c2b31c35adcb804','5f82d23ccd2e45fd9e59f76c92bcc9ad',1938,'伪蒙古军总司令、伪豫东剿共军副司令','内蒙古人，抗战期间投靠日军，曾任伪蒙古军总司令，后参与豫东地区伪军指挥，配合日军在周口、商丘一带进行扫荡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('96c5cfe382114895889be1d2084a81bd','7c4f055fe1bf4b1ea64573ebbd87eeb8',1940,'伪西华县教育科科长','西华县人，抗战期间任伪西华县教育科科长，推行奴化教育，强制学校使用日伪教材，宣传“大东亚共荣圈”。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('27b8aaad6ae9428681c78ce1c26944df','3528daef89c7440fa850f8592d84f11f',1939,'伪周口商会会长','周口商人，抗战期间任伪周口商会会长，为日军筹集物资、摊派款项，协助日军控制周口经济。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3b5afb9aecef4d0380e13bc82d7ca077','2bd76bd4f7874f8f8becd896967ac4f3',1938,'伪郸城县维持会会长','郸城沦陷后出面组织维持会，为日军征粮派款、维持地方伪秩序，协助日军控制郸城及周边乡镇。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b8fd3e23a07f4f0cb1123ddc103fc2e0','cd6bd8e57e4147f5b633a46a11754965',1939,'伪郸城县保安团团长','在郸城一带收编土匪武装，投靠日军，编为伪保安团，配合日军扫荡抗日武装，残害地方抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('412f7cfc186c4ae892075994b87c33af','304399e6f8f94bd5912316df10e1ac2a',1938,'伪豫东道公署道尹、伪河南省政府委员','在豫东周口、商丘地区依附日军，主持伪道公署，推行保甲连坐，为日军征集物资、劳工，镇压抗日活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c895586331624969835d9b29f998a0dd','fefd7f9ddbac40469c751144d6cbd784',1938,'伪和平救国军第一军副军长、伪苏豫边区绥靖军总司令','在豫东、皖北一带活动，与张岚峰部配合，在周口、郸城周边地区进行伪化统治和军事扫荡。；在豫东、皖北、苏北交界地区组织伪军，活动范围包括郑州以东的商丘、开封周边，配合日军扫荡抗日根据地。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('da1e0ee01a9841309e1fc8b06a892398','75f09c865de64a35a5afb45724999676',1938,'伪商丘县知事、伪豫东道尹公署参事','在豫东地区为日军推行伪政，协助征粮征兵，其活动范围涉及周口北部及郸城邻近地区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3d3deed4a6d8440fb07ab68672d9ce08','2d1ab2337d7040f78bf16f79ac344a41',1938,'伪淮阳县维持会会长、伪淮阳县知事','淮阳沦陷后组织维持会，后任伪县知事，为日军统治周口一带效力，征发民夫、物资，镇压抗日群众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0d3b44ffbb644533bbceb2d7c6eeeeb0','772426e687914a769c5c7e4fedacadc5',1939,'伪鹿邑县保安大队大队长','在鹿邑、郸城交界地区活动，率伪军配合日军扫荡，袭击抗日游击队，残害百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dad670c85f8444b2a37434c8fd9cf189','3e607ad5fd9e486dad46b3bc19c5bffc',1938,'伪沈丘县维持会会长','在沈丘一带组织伪维持会，为日军筹粮筹款，协助日军控制沙河沿岸地区，影响波及郸城南部。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e1dec05251d04767a8773202897ab22d','aea3838771d8458ba6073d341943bb27',1939,'伪豫东剿共军司令','在豫东周口、开封之间活动，收编土匪伪军，配合日军进攻抗日根据地，其势力一度延伸至郸城周边。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d566e2b6ccfb4b51ae4dd1c13fe7c961','848992e841c9488c8cdcf56cad9f079c',1938,'伪和平救国军第一军军长、伪第四方面军总司令、伪河南省政府委员','河南柘城人，早年留学日本，抗战爆发后投敌，在豫东商丘、周口、柘城、鹿邑、项城一带收编土匪、组建伪军，配合日军扫荡抗日根据地，推行伪化统治，是豫东地区最具实力的汉奸武装头目之一。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a99206477278467781a577067a4e18d0','fefd7f9ddbac40469c751144d6cbd784',1938,'伪和平救国军总司令、伪河南省省长','原东北军将领，投敌后任伪职，曾参与伪河南省政，协助日军在河南推行治安强化运动，其伪政权体系覆盖豫东包括周口、项城周边地区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5907e51875034710bf7e9eea2778c4e8','fcb3e5ff966f4327a818cbc1e3244da5',1938,'伪河南省政府委员、伪豫东道尹','在豫东地区任职伪道尹，管辖商丘、周口等县，推行保甲连坐、维持会制度，为日军征集物资、劳工，镇压抗日活动。；在伪河南省政府任职，参与河南沦陷区伪政权管理，协助日军推行保甲、征粮、抓丁等政策，其管辖区域涉及豫东、豫中部分县份。；在河南沦陷区任伪职，协助日军推行保甲、征粮、抓丁等政策，其管辖范围涉及漯河、舞阳周边。；在河南日伪政权中任职，参与伪化地方行政，协助日军征敛物资。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c1aaa971c7be4ecc981c14095ae5b57a','a3af6fcc375c4ca9be53e0d99afc265e',1938,'伪豫东道公署职员、伪项城县维持会会长（地方维持会头目）','项城沦陷后出面组织维持会，协助日军维持地方秩序、征发粮秣，是项城当地有记载的附逆头目之一。','基层维持会/地方自治头目','hanjian');
