INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('09661e1f6560407b9b036f47742757bb','304399e6f8f94bd5912316df10e1ac2a',1938,'伪豫东道尹公署道尹','日伪在豫东设立道级伪政权，刘子仁任道尹期间驻商丘，统辖商丘、柘城、鹿邑等县伪政，推行日军殖民统治政策。；汪伪政权在豫东设立道级伪政权，刘子仁任伪道尹，管辖商丘、开封以东地区，推行伪化教育、经济掠夺。；汪伪政权在豫东设立道尹公署，刘子仁曾任伪道尹，驻商丘，统辖豫东各县伪政权，推行日军殖民统治政策。','无明确职位或一般帮凶','hanjian');
