INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b7c9b2f7e6134cc68f297beb1553e81e','38d5ea25829949a28b7f32f06c1059e8',1938,'伪商丘县商会会长','控制商丘物资流通，为日军采购军粮和战略物资，协助经济掠夺，是商丘地区经济附逆的代表人物。；协助日军控制商丘物资流通，为日军采购军需，压榨商户，配合经济掠夺。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6b05da921ae447da9a72d8394ce9b507','42fb54d5549a49d88797d3208cb21142',1938,'伪豫东道尹公署道尹','任伪豫东道尹期间，统辖商丘、夏邑等县伪政权，推行日军政令，征发民夫、粮食，支持日军扫荡。；在商丘主持伪豫东道政务，推行日军殖民统治政策，统辖商丘、睢县、柘城等县伪政权，征发民力物资支持日军。；伪豫东道管辖商丘、睢阳、夏邑、永城、虞城等地，赵子立作为道尹，是豫东地区伪政权的重要行政头目，推行日军殖民统治政策。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0f6dff82354c49d3ac07e4f567f4c269','d17960b2360f4c60b5d72ab73d2bf090',1939,'伪商丘县保安团团长','率伪保安团在商丘、夏邑交界地区活动，配合日军清乡，抓捕抗日干部和群众，破坏抗日基层组织。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c733e260fef34245aefbbb91d2ac80f6','a7f97d8353ae4b63b92615956608aded',1938,'伪商丘县维持会会长、伪商丘县县长','商丘沦陷后出面组织维持会，后任伪商丘县县长，协助日军维持地方统治、征粮派款、镇压抗日活动，是商丘地区伪政权的重要人物。；商丘沦陷后出面组织维持会，协助日军建立伪政权，推行保甲连坐，征发民夫物资，镇压抗日活动。；商丘沦陷后出面组织维持会，后任伪商丘县县长，为日军征粮、征夫、维持地方伪秩序，是商丘城区及睢阳一带伪政权的主要头目之一。；商丘沦陷后出面组织维持会，后任伪商丘县县长，为日军筹粮筹款、维持伪秩序，协助日军统治商丘城区及周边地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('57fe4382b468459e81bda6131d14f868','86fe1fead892460db58a6370752bc1cc',1938,'伪宁陵县维持会会长、伪宁陵县县长','宁陵沦陷后投靠日军，组织伪维持会并出任伪宁陵县县长，为日军征集物资、拉夫派款，协助维持日伪在宁陵的统治。','基层维持会/地方自治头目','hanjian');
