INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c17558f94a6542ca8a6134269ade6bbf','a3af6fcc375c4ca9be53e0d99afc265e',1938,'伪商丘县维持会会长、伪商丘县知事','商丘沦陷后出面组织维持会，投靠日军，协助建立伪政权，为日军征粮、征夫、维持地方治安，活动范围覆盖商丘城区及周边民权等地。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('494426fd7b7443fd986f2351e2b0fe49','42fb54d5549a49d88797d3208cb21142',1938,'伪民权县维持会会长','民权沦陷后组织维持会，投靠日军，协助建立伪县政权，为日军征集粮食、劳工，维持地方伪秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6ac216c64d4a4fcb86a7f6a7db3e1f9b','bbd63c1ca8684efa918c037030708eac',1939,'伪民权县知事','出任民权县伪知事，执行日军政令，推行保甲制度，配合日军对民权及周边地区的控制与扫荡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b7bc5f6625b94e0ca97621360bbf2d45','4b034429b0834c0ebe93d3a9b2e7c572',1938,'伪河南省政府委员、伪豫东道尹公署顾问','河南沦陷区伪政权要员，参与伪河南省政，协助日军在豫东包括商丘、民权一带推行殖民统治。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e7ebe9f07b204dd99170467e077f5021','fcb3e5ff966f4327a818cbc1e3244da5',1937,'伪河南省省长','伪河南省最高行政长官，统辖包括商丘、民权在内的沦陷区伪政权，推行日军政策，征发物资劳工，镇压抗日活动。；曾任伪河南省省长，为日军统治河南服务，推行保甲、征粮、奴化教育等附逆政策。；在开封任伪河南省省长，推行日军“治安强化运动”，配合扫荡抗日根据地。；继任伪河南省省长，驻开封，协助日军维持河南沦陷区统治，镇压抗日力量。；继任伪省长，继续为日军征粮征丁，推行伪政权政策。；在开封任伪河南省省长，协助日军掠夺物资、推行奴化教育，维持伪政权统治。；继任伪省长，继续为日军搜刮物资，维持伪政权。；在开封主持伪省政，推行日军‘治安强化’与物资统制政策。；任伪河南省省长，驻开封，推行日军“治安强化运动”，配合扫荡抗日根据地。；继陈静斋之后任伪河南省省长，驻开封，协助日军推行保甲制度、征发劳工，维持沦陷区统治秩序。；任伪河南省长期间，推行保甲、征粮征丁，支持驻马店周边伪政权。；投敌后任伪河南省省长，配合日军经济掠夺，强征劳工，其伪政权与陕西周边地区有联系。；投靠日本，在河南推行伪政，协助日军掠夺资源，影响陕西邻近地区。；投靠日本，在河南伪政权中任职，协助日军扫荡抗日力量，其活动区域与陕西接壤。；河南伪政权后期头目，其伪化活动与陕西渭南地区有间接关联。；投敌后任伪河南省省长，协助日军搜刮物资。；在河南沦陷区任伪职，配合日军统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5959a31b01af4e19a8b7d42853a005a8','5f82d23ccd2e45fd9e59f76c92bcc9ad',1933,'伪蒙古军总司令、伪河南省政府委员','蒙古族汉奸，投靠日军，其伪军曾活动于河南北部及豫东部分地区，与商丘、民权日伪政权有联系，配合日军作战。；原东北军出身，长期在伪蒙疆政权任职，1944年后其伪军部分力量活动于河南地区，与洛阳沦陷后的伪政权有联系。；长期在伪蒙疆政权任职，后与河南伪政权有联系，其伪军活动范围一度涉及豫北地区。；蒙古族汉奸，长期在伪蒙疆政权任职，后与河南伪政权有联系，其伪军曾配合日军在河南境内活动。；热河土匪出身，早年在东北投敌，后任伪蒙古军总司令，抗战后期其势力曾延伸至河南北部，配合日军作战。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8a0ff4366e8c45fb8238d0172f7822bb','d2b840cc6fa142c8b5c30c100a11b64d',1938,'伪河南省政府委员、伪豫东道尹','在豫东伪政权中任职，负责商丘、民权等县伪政事务，执行日军命令，征粮征夫，镇压抗日民众。','无明确职位或一般帮凶','hanjian');
