INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4f0f9f10e8a146b8959ba78f7b5a47f4','ffa65e01448c489d8de64b4eba88b3d5',1938,'伪开封市维持会会长','开封沦陷后组织维持会，后任伪开封市市长，为日军在河南省会推行殖民统治，影响波及豫东商丘等地。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8ef05a557d574ff6a45cdda9a8de63ee','da468ceacd8e4ec1a1dec91ade2429a7',1938,'伪河南省政府委员、伪豫东道尹','汪伪河南省政府官员，曾任伪豫东道尹，驻商丘，统辖豫东伪政权，推行日军政策。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e19f1a708a70406793e6d6c1a843d46a','135b16ef41e74ecc8b954f7fe8666eda',1938,'伪河南省教育厅厅长','汪伪河南省政府官员，推行奴化教育，在包括商丘在内的河南沦陷区学校强制日语教学和亲日宣传。；推行奴化教育，篡改教材，向学生灌输亲日思想。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('439c754fda624577a599b277a335f630','793dba30c5cd4e9ab0835412a8dc7906',1940,'伪河南省政府财政厅厅长','汪伪河南省政府官员，为日军筹款筹粮，在河南沦陷区包括豫东商丘一带推行伪币和掠夺性财政政策。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6df38fec24eb468a9a3026c0425bc01d','d485c70cf19e49daa34f4a4e02302297',1938,'伪商丘县商会会长','商丘沦陷后任伪商会会长，为日军筹集物资，协助日军控制商丘经济，压迫商民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8db23eb9529a4b0bac9bf8670d1aa4f8','24b27e92935346b5b0c750031defdd1f',1937,'伪河南省政府委员、伪豫北道尹','抗战期间投靠日军，在豫北道（辖安阳等县）推行伪政，协助日军征粮、征夫，镇压抗日活动。；抗战期间投靠日军，在豫北地区参与伪政权建设，协助日军维持安阳及周边地区统治，推行保甲、征粮、抓丁等政策。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9a0e54b0e4864b7da296093af84d77fd','793dba30c5cd4e9ab0835412a8dc7906',1937,'伪河南省省长、伪豫北道尹','北洋旧官僚，日军侵占河南后出任伪职，先后任伪豫北道尹、伪河南省省长，为日军筹粮筹款，推行奴化教育。；北洋旧官僚出身，抗战时期附逆，曾任伪河南省长及伪豫北道尹，参与日伪在豫北包括安阳地区的行政统治。；北洋旧官僚，抗战后投敌，历任伪豫北道尹、伪河南省省长，在豫北包括鹤壁周边地区建立伪政权，配合日军维持治安、掠夺物资。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('645452d2d13641908bfef058a97773d3','fcb3e5ff966f4327a818cbc1e3244da5',1938,'伪河南省政府委员、伪豫北道尹','在豫北道任内配合日军“治安强化运动”，组织伪自卫团，清乡扫荡，残害抗日群众。；在豫北道任职期间，管辖安阳、内黄等县伪政，配合日军推行保甲、征粮和治安强化运动。；抗战时期在豫北道任职，配合日军在安阳、新乡等地推行伪化统治，参与征发物资、镇压抗日活动。；在豫北道任职期间，督导安阳、滑县等地伪政权，推行保甲、征粮、抓丁，配合日军扫荡抗日根据地。；在豫北道任职期间，协助日军控制安阳等县，推行保甲连坐、物资统制等政策，镇压抗日活动。；在豫北地区任伪道尹，负责地方伪政权事务，配合日军清乡、扫荡。；在豫北地区依附日军，参与伪政权行政，配合日军对豫北各县包括新乡、延津地区的控制与掠夺。；在伪河南省政府任职，参与伪政权事务，协助日军在河南各地推行伪化，其活动范围涉及豫中包括漯河一带。；河南沦陷区伪政权官员，参与伪河南省政，协助日军维持豫北、豫中地区治安与物资征调。；在河南沦陷区担任伪道尹等职，负责豫北地区伪行政事务，配合日军维持占领区统治，推行伪化教育与经济掠夺政策。；在河南沦陷区任伪职，参与伪河南省政，负责豫北地区伪政权事务，配合日军征粮、征丁及维持治安。；曾任伪豫北道尹，管辖豫北地区包括鹤壁、淇县、浚县等，协助日军推行保甲、征粮、清乡。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('db4ac7d3deb34a07b6d8101b18031301','a2a33c8255fc4a2f89bc0416be0e6e0a',1937,'伪安阳县维持会会长、伪安阳县县长','安阳沦陷后率先组织维持会，后任伪县长，为日军征集物资、修筑工事，并协助建立伪保甲制度。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('93e39640cee14246935cfb3723f1985d','6a00b85438bf440da23993044f22735d',1938,'伪和平建国军第一军军长、伪豫东剿共军司令','原国民党军将领，投敌后率部驻防豫北、豫东，配合日军进攻抗日根据地，在安阳周边地区多次参与扫荡。；原国民党军将领，投降日军后任伪军头目，活动于豫东、豫北一带，配合日军进攻抗日根据地，其势力范围涉及安阳周边。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bef7e4b45b984644bb194b933e78a0e7','53719b7eb602459ebd656b246a4d1a92',1940,'伪和平建国军第二十四集团军总司令、伪河南省保安司令','率部投敌，所部驻防豫北安阳、新乡一带，协助日军守备铁路、据点，进攻八路军。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('449e570571d640c1a9c592761fcacc04','38b34fb7f6c3411580ffe576ac292e0f',1938,'伪安阳县保安团团长、伪豫北剿共军支队长','安阳本地土匪武装头目，投日后编为伪军，在安阳西部山区配合日军扫荡，杀害抗日干部和群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ba6ace7cc4d8485ca68c41f39f433e20','ea44bfcd495e4842a2a25b453a384985',1938,'伪安阳县警察局局长、伪安阳县保安大队大队长','长期把持安阳伪警察系统，搜捕抗日人员，推行保甲连坐，勒索百姓。','市县厅局级','hanjian');
