INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a662c103413c4fe4b4ffd9b825d5a2fe','35ee95eae0874ad4980e2e4bbce1d54a',1939,'伪豫北道公署警务科长','在豫北道统管伪警察，参与抓捕抗日嫌疑人员，破坏中共地下组织。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('032fdfc56e334f92a68ec56568db2ff8','2bd76bd4f7874f8f8becd896967ac4f3',1938,'伪安阳县新民会会长','在安阳组织新民会，进行亲日宣传，训练伪青年团，协助日军推行“治安强化运动”。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('667367380b9644b69f8fbf8cc40bd069','99aa41aac21b4a7ebaa5c793013c2156',1938,'伪汤阴县县长','汤阴沦陷后任伪县长，为日军征粮征丁，修筑封锁沟墙，配合扫荡安阳、汤阴一带抗日武装。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2a38a38efe2c4c929183e856c022f02b','a2a33c8255fc4a2f89bc0416be0e6e0a',1938,'伪内黄县维持会会长、伪内黄县知事','内黄沦陷后出面组织维持会，充任伪内黄县知事，为日军征粮派款、维持伪秩序，是内黄当地主要附逆头目之一。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('00414af4ccd546a69508bb9b53ac7442','6a00b85438bf440da23993044f22735d',1938,'伪豫北剿共军总司令、伪河南省保安队副总司令','在豫北安阳、内黄、汤阴一带收编土匪、伪军，配合日军扫荡抗日根据地，长期控制安阳周边地区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0ab89b479dc34934bd261aafe576db65','53719b7eb602459ebd656b246a4d1a92',1938,'伪豫北剿共军副总司令、伪安阳县县长','投靠日军后盘踞安阳，参与组织伪军，配合日军进攻冀鲁豫和太行抗日根据地，在安阳、内黄一带活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8e750706ed1b445dbd2b82f7b3873ab5','38b34fb7f6c3411580ffe576ac292e0f',1938,'伪安阳县保安团团长、伪军头目','安阳本地伪军头目，率部配合日军在安阳、内黄、汤阴地区清乡、扫荡，残害抗日群众。；盘踞安阳东部，组织伪保安团，为日军搜集情报、征粮抓丁，多次配合日军进攻抗日武装。；安阳本地伪军头目，组织保安团配合日军维持安阳及文峰一带治安，参与清乡、抓丁、征粮，镇压抗日群众。；盘踞安阳东部及殷都区一带，充当日伪爪牙，强征粮款、捕杀抗日人员。；盘踞安阳一带，先投日军任伪保安团团长，后扩编为伪军，配合日军扫荡豫北抗日根据地，残害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('13b5e8a6c3984c8e92e69c3f75a0313a','3b57a17d2c3d4092b9af781e5aef0f69',1938,'伪军头目、伪安阳地区保安队首领','在安阳东部和内黄一带组织伪武装，为日军搜集情报、征发民夫粮秣，配合日伪统治。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0ccb1b59770a488c96dcc7b08cf5f853','ea44bfcd495e4842a2a25b453a384985',1938,'伪军头目、伪安阳地区剿共队首领','活动于安阳、内黄、临漳交界地区，投靠日军后多次参与扫荡冀鲁豫边区，烧杀抢掠。','无明确职位或一般帮凶','hanjian');
