INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6b2f6251b07c48f9b5c1d901f3f298e3','9f7b3ed9c76f4eea8211fd8ebc40a461',1943,'国民党军将领，后投敌任伪新编第五军军长','1943年在豫北被日军俘获后投敌，所部被编为伪军，活动于安阳、新乡一带，配合日军进攻抗日根据地。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fb9f3a862184467da3bf189c83843308','5ec2ad124b2f429482b1a90a7f8d4a92',1943,'国民党军将领，后投敌任伪第二十四集团军总司令','1943年在豫北投敌，所部伪化后活动于安阳、林县、内黄周边地区，配合日军扫荡。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('53ac6c6fe75c43ca85ad34e522910932','2bd76bd4f7874f8f8becd896967ac4f3',1938,'伪内黄县警察所所长','在内黄伪警察机构任职，协助日军搜捕抗日人员、维持伪治安，压迫当地民众。','无明确职位或一般帮凶','hanjian');
