INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9ec332df0c6249bea303edd4b009659a','229d6797c3fc4b25b28d9d4d373b07df',1938,'伪内黄县教育科科长','在伪内黄县政权中负责教育，推行奴化教育，宣传“中日亲善”，毒害当地青少年。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a39bff6571d2468aa6d049dcff72568d','760d3e1a7c054145942b8b3885c32745',1938,'伪安阳县知事、伪豫北道公署职员','在安阳伪政权中任职，执行日军征粮、派夫、保甲连坐等政策，波及内黄等周边县。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('908993f4c74642c0a90e6a07d1394489','a2a33c8255fc4a2f89bc0416be0e6e0a',1937,'伪安阳县维持会会长、伪安阳县知事','安阳沦陷后出面组织伪维持会，后任伪安阳县知事，协助日军征粮、派夫、维持治安，镇压抗日活动。；安阳沦陷后出面组织维持会，后任伪安阳县知事，为日军筹粮筹款、维持地方伪秩序，是安阳本地重要附逆人物。；安阳沦陷后出面组织伪维持会，后任伪安阳县知事，协助日军征粮、派夫、维持治安，镇压抗日群众。；日军侵占安阳后出面组织维持会，协助日军维持城区秩序、征粮派款，并出任伪安阳县知事，为日伪政权在安阳地区的统治服务。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7530e7dc9f664060816e43bd83446c5e','ea44bfcd495e4842a2a25b453a384985',1938,'伪安阳县保安团团长、伪军头目','在安阳一带收编土匪、组建伪保安团，配合日军扫荡抗日根据地，残害抗日军民。；在安阳一带收编土匪、组建伪保安团，配合日军对安阳周边抗日根据地进行扫荡，镇压抗日群众，是豫北地区较有影响的伪军头目之一。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('47b5a28b1e7a443db64ba5785bb89d49','38b34fb7f6c3411580ffe576ac292e0f',1938,'伪安阳县保安队头目、伪军军官','盘踞安阳东部及周边，率伪军配合日军进攻抗日武装，控制地方，勒索民众。；盘踞安阳东部及周边地区，率伪军配合日军行动，参与对抗日武装的围剿，并向当地百姓摊派粮款。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('182f62879c97435aaab247b5a2fb669a','3b57a17d2c3d4092b9af781e5aef0f69',1938,'伪豫北剿共军司令','在豫北安阳、汤阴、淇县一带组织伪军，配合日军扫荡，进攻八路军和地方抗日政权。；在豫北安阳、汤阴、浚县一带活动，组织伪军配合日军扫荡抗日根据地，残害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c7370bea67f845c3b6d61079114d85e0','9c6d4ab9d91f4afaaae956846605be40',1938,'伪豫北剿共军师长、伪军头目','在安阳、汤阴、浚县、淇县一带活动，率部投日，配合日军扫荡豫北抗日根据地。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6d45aa6683244671a9e72f890921c7fa','41d2b197fedd4eefa3bd64d7cebe1523',1942,'伪河南省省长、伪开封绥靖公署主任','在河南日占区任伪职，协助日军维持统治，整编伪军，镇压抗日活动。；在开封主持伪河南省政及伪绥靖公署，统辖伪军配合日军作战，维持沦陷区统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cf510f44a1104568be7a247b8f9d766b','5ec2ad124b2f429482b1a90a7f8d4a92',1943,'伪和平建国军第二十四集团军总司令、伪豫北绥靖公署主任','在豫北投降日军，任伪职，率伪军配合日军扫荡太行、豫北抗日根据地。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('28909c3aacfb4e64a0a858f2e3d3aa90','9f7b3ed9c76f4eea8211fd8ebc40a461',1943,'伪和平建国军新编第五军军长、伪豫北绥靖公署副主任','在豫北投日，所部配合日军进攻八路军，控制安阳、林县、汤阴一带。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0210c36a3c534ee7b3e9fed442575374','2bd76bd4f7874f8f8becd896967ac4f3',1938,'伪安阳县警察局局长','在安阳城区及北关一带维持伪警察系统，搜捕抗日人员，协助日军控制城市治安。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f7ad810b938a4f6f8b2b4b2dfb03f640','7914b096c2ea4a20bc48600bc6b34adf',1938,'伪安阳县教育会会长、伪中学校长','在安阳推行奴化教育，组织亲日宣传，协助日军控制学校和文化机构。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('28a5f6cdbb4c40a69a768d79e8216936','b6223ced161a43abba0329d6cf515e1b',1937,'伪安阳县商会会长','在安阳为日军筹款、征粮、摊派物资，协助日伪经济统制。；协助日军控制安阳工商业，为日军筹集物资、资金，压榨商户。；控制安阳城区商业，为日军征购物资、摊派捐款，协助日伪实行经济统制。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7328ad36061343cbbda8b0117fc1b840','8cc8ff216c7341e184899257fe25633b',1937,'伪安阳县维持会副会长、伪保长','在安阳北关一带组织维持会，协助日军登记户口、征发民夫、催缴粮款。','基层帮凶(维持会系统)','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c00faaed6a4741a3a05c86eef724d9a5','6a00b85438bf440da23993044f22735d',1938,'伪豫北剿共军总司令、伪河南省政府委员','在豫北安阳一带收编土匪、组建伪军，配合日军扫荡抗日根据地，控制安阳周边地区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('357c37f42f044c6593aca4f53ed33981','ea44bfcd495e4842a2a25b453a384985',1938,'伪安阳县警备队队长、伪军头目','在安阳及周边地区充当伪警备队头目，协助日军维持占领区秩序，参与清乡、扫荡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dbec0281c14d42448c85bedbc56f1fe4','3b57a17d2c3d4092b9af781e5aef0f69',1937,'伪彰德县（安阳）维持会副会长','安阳沦陷初期参与组织维持会，为日军筹款、筹粮，协助建立伪政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5d9d8580afae49c099d51c0618f2b930','53719b7eb602459ebd656b246a4d1a92',1938,'伪豫北道尹、伪河南省政府委员','在豫北地区（含安阳）任伪道尹，推行日军政策，征发物资，镇压抗日民众。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('80154808e653458ebb8c05f7e558d874','63006a4879fb4f49ad97a1e88c8c5d69',1942,'伪和平建国军第二方面军总司令、伪开封绥靖公署主任','率部投敌后驻防豫北、豫东，配合日军进攻抗日根据地，其势力范围覆盖安阳周边。；原西北军将领，1942年率部投敌，所部驻防河南开封、濮阳一带，配合日军对冀鲁豫抗日根据地进行蚕食和扫荡。；原西北军将领，1942年率部投敌，所部驻防河南开封、郑州周边地区，配合日军维持伪政权统治，参与扫荡抗日武装。；原国民党将领，1942年率部投敌，任伪和平建国军第二方面军总司令，后任伪开封绥靖公署主任，其伪军活动范围覆盖河南大部，包括郑州、惠济一带，协助日军扫荡抗日根据地。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1f4487f9777a4889aba117cafef7e28a','5ec2ad124b2f429482b1a90a7f8d4a92',1943,'伪和平建国军第二十四集团军总司令、伪河南省政府主席','在豫北被俘后投敌，组织伪军驻防安阳、新乡一带，配合日军扫荡。；原国民党军将领，1943年投降日军，任伪军集团军总司令及伪河南省主席，在豫北安阳等地参与日伪统治和军事行动。；原国民党河北省政府主席，1943年投敌，任伪河南省政府主席，其伪政权管辖范围包括豫北濮阳、清丰等地，推行保甲连坐，协助日军征粮征丁。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d8aa328c53924e359505f12664430dc3','2bd76bd4f7874f8f8becd896967ac4f3',1938,'伪安阳县教育会会长','在安阳推行奴化教育，编写亲日教材，组织学生参加日军宣传活动。；在安阳推行奴化教育，协助日伪修改教材、宣传“中日亲善”和“大东亚共荣圈”，毒化当地青少年。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('eb381a1d258c4dc4bd9c62c9605049cd','53719b7eb602459ebd656b246a4d1a92',1943,'伪和平建国军第二十四集团军副总司令、伪河南省保安司令','原国民党军将领，投日后任伪军高级头目，在豫北安阳、新乡等地配合日军扫荡，参与伪政权军事活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dbc11a1cbebc439fb6a15b9803f40240','9f7b3ed9c76f4eea8211fd8ebc40a461',1943,'伪新编第五军军长、伪和平建国军第二十四集团军副总司令','原国民党军将领，1943年投敌，所部被编为伪军，活动于豫北、太行山南麓一带，配合日军对安阳周边抗日根据地作战。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4a2fe75d4c0d49a480d186cb7b861451','ea44bfcd495e4842a2a25b453a384985',1938,'伪安阳县警察局局长、伪保安队头目','安阳沦陷后任伪警察头目，协助日军控制安阳城区及文峰一带，参与搜捕抗日人员、推行保甲连坐。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c32dc182c4fd48cdba8edfd569ee0f81','50789647a08643c2af5f199ff8c39b26',1938,'伪安阳县教育会会长、伪新民会安阳分会负责人','在安阳教育文化领域附逆，通过新民会推行奴化教育，宣传“中日亲善”，协助日军控制安阳学校和文化机构。','基层维持会/地方自治头目','hanjian');
