INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('43bc0cda3ed244b393f28fa1f951b999','793dba30c5cd4e9ab0835412a8dc7906',1938,'伪河南省公署省长','河南沦陷区伪政权头目之一，依附日军，推行治安强化运动，为日军搜刮民财、征发劳工。；继任伪河南省省长，驻开封，协助日军维持河南沦陷区统治，推行治安强化运动。','省部级/大军区级要员','hanjian');
