INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('86f22f07bda94374940b04213981f78a','8cc8ff216c7341e184899257fe25633b',1938,'伪豫北剿共军司令','率伪军在安阳、林县、汤阴一带配合日军扫荡，袭击八路军和地方抗日武装。；率伪军在安阳、汤阴、淇县、浚县一带配合日军扫荡，进攻抗日根据地，残害抗日军民。；收编土匪武装组成伪军，在鹤壁、安阳、汤阴一带配合日军进攻抗日根据地，残害抗日军民。；率伪军在豫北包括鹤壁、淇县、浚县一带配合日军扫荡，进攻抗日根据地，残害抗日军民。','基层头目','hanjian');
