INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e26cf70966ad4234a256e9277d813324','9f7b3ed9c76f4eea8211fd8ebc40a461',1943,'伪新编第五军军长（投敌后）','原国民党军将领，1943年在豫北投敌，所部被编为伪军，活动于安阳、新乡一带，配合日军进攻抗日根据地。；1943年在豫北投敌，所部被编为伪军，驻防豫北地区，配合日军进攻抗日根据地，活动范围覆盖新乡、延津一带。；率部投敌后驻防豫西，与日军配合进攻太行、豫西抗日根据地，活动范围涉及洛阳以北地区。；原国民党军将领，1943年在河南林县被俘后投敌，所部被编为伪军，活动于河南北部及豫西地区，配合日军作战。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b641ece2415746f9a820d4ab895f3878','5ec2ad124b2f429482b1a90a7f8d4a92',1943,'伪第二十四集团军总司令（投敌后）','原国民党河北省主席、军长，1943年在豫北被俘投敌，任伪第二十四集团军总司令，驻安阳一带，协同日军扫荡豫北。','省部级/大军区级要员','hanjian');
