INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fda5e92f101f4dc08605af6d83789da0','f056bbda69f94541a6e18accfa3ee857',1938,'伪河南省宣传处处长','负责伪河南省的新闻宣传，创办伪报纸，为日军侵略辩护，鼓吹“大东亚共荣圈”。；在开封主持伪宣传机构，为日军侵略辩护，进行奴化宣传。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8a738bd8ddcb4b11abe909dc69336c25','38d5ea25829949a28b7f32f06c1059e8',1944,'伪平顶山煤矿株式会社理事长','日军占领平顶山煤矿后，出任伪煤矿株式会社理事长，强迫矿工劳动，掠夺煤炭资源，配合日军经济侵略。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9436462fb58f493db711d584de7bfe6c','a2a33c8255fc4a2f89bc0416be0e6e0a',1938,'伪河南省商会会长','在开封任伪河南省商会会长，为日军筹集军需物资，协助日军对沦陷区进行经济掠夺。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('86872ad4307a48af9a197eadaa0bfe32','b77a9c0384c94aa5bcd13e6c90ce35f9',1938,'伪河南省公署参事、伪豫东道尹','在伪河南省政权中历任参事、豫东道尹等职，协助日军推行保甲制度，征发劳工，镇压抗日活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('14904d60196042999bb31336daef8f94','5ec2ad124b2f429482b1a90a7f8d4a92',1943,'伪第二十四集团军总司令、伪第五方面军总司令','1943年在河南投敌，率部降日，在豫北、豫西地区配合日军作战，其伪军活动范围覆盖河南中部包括平顶山一带。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('64b03d36471c42da994f4dac5f8420ed','2bd76bd4f7874f8f8becd896967ac4f3',1944,'伪叶县维持会会长','1944年日军侵占叶县后，出面组织伪维持会，协助日军征粮、派夫、维持地方治安，为日军统治服务。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('37eba68593da46e888a4d5363b3f01cb','666e4553a940419fafda1ba2aa5a4710',1944,'伪叶县保安团团长','叶县沦陷后投靠日军，组织伪保安团，配合日军清乡、扫荡，镇压抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ce81ca20def64c22a5c8c109689d69fb','d492b175c0d2433d82d0b823bf81a6ef',1944,'伪平顶山地区维持会会长','在平顶山地区组织伪维持会，为日军搜集情报、征发物资，协助日军控制当地煤矿和交通线。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('89998c9e42254329a2d39ea7fe832bfa','a36adf024ce44c63a7d6f7c343eb3712',1944,'伪河南省政府委员、伪豫西道尹','日军占领豫西后出任伪职，协助日军推行保甲制度、征粮征丁，其管辖范围涉及平顶山地区。；河南沦陷区伪政权要员，负责豫西道政务，其辖区包括平顶山、宝丰等地，推行奴化教育、征发物资。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('42e6923d7f0146c2b935bfec86cb1cc7','fcb3e5ff966f4327a818cbc1e3244da5',1940,'伪河南省政府秘书长、伪豫东道尹','在伪河南省政府任职期间，协助日军推行殖民统治，参与征粮、征丁等事务，其活动涉及河南中部包括平顶山一带。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('35566f75529f4ec18ff6c22b25d14a7e','2bd76bd4f7874f8f8becd896967ac4f3',1944,'伪宝丰县维持会会长','1944年日军侵占宝丰后，出面组织维持会，为日军征粮派款、搜集情报，协助建立伪政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c5151d1a0c104b21ac7d0ee1a50ab9df','d492b175c0d2433d82d0b823bf81a6ef',1944,'伪宝丰县保安团团长','宝丰沦陷后投敌，率部配合日军清乡，镇压抗日群众，控制宝丰及周边乡镇。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d5f7db19a4c047bdb403f0067d73faba','666e4553a940419fafda1ba2aa5a4710',1944,'伪平顶山矿区维持会会长','在平顶山矿区组织维持会，为日军掠夺煤炭资源提供劳力与情报，迫害矿工中的抗日分子。；平顶山地区煤矿区伪维持会头目，协助日军控制煤矿，强迫矿工劳动，为日军提供煤炭资源。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('911b85cf508e4b44aa99b90ec0220488','6e9ca6b425994c5b88f8c66b5a917691',1944,'伪临汝县维持会会长','临汝沦陷后投敌，组织维持会，协助日军控制临汝及邻近的宝丰、郏县一带。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a522702b2274455080cc1ef99c1124b5','8853ebc9482649aca1ee056bfe54c04c',1944,'伪郏县保安队队长','郏县沦陷后率部投敌，配合日军扫荡郏县、宝丰交界地区，残害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9702889b8b984f18a50d7c4a3ca61423','2bd76bd4f7874f8f8becd896967ac4f3',1940,'伪河南剿共军第一路司令','河南地方伪军头目，在豫中一带组织伪军，配合日军扫荡抗日武装，活动于平顶山、许昌、漯河周边地区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5d2712cf69be451cafe2d15110faa28f','38b34fb7f6c3411580ffe576ac292e0f',1938,'伪安阳县长、伪豫北剿共军司令','河南安阳人，投靠日军后任伪安阳县长，组织伪军配合日军扫荡豫北、豫中抗日根据地，其势力范围一度延伸至平顶山周边。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5e22dfaf383a40238cbfef5c07f14941','793dba30c5cd4e9ab0835412a8dc7906',1938,'伪河南省长','抗战期间任伪河南省长，主持伪省政，推行日军殖民统治，征粮征丁，镇压抗日活动，其伪政权覆盖河南全省包括平顶山地区。；在河南伪政权中任职，协助日军维持占领区，对陕西抗日后方有威胁。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0965e7583e214995ba894921dfc29c9f','d409a62a1fcf424a82d99abd16ad9bea',1944,'伪平顶山地区维持会会长','1944年日军占领平顶山地区后，出面组织维持会，为日军征粮征夫，维持伪秩序，协助日军控制当地煤矿与交通线。；1944年日军侵占平顶山地区后，出面组织维持会，为日军筹集粮草、拉夫派款，协助日军维持地方治安，压迫当地民众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('67e0e7418a7947718fd368df82075321','a36adf024ce44c63a7d6f7c343eb3712',1944,'伪许昌县长、伪豫中维持会会长','1944年日军占领许昌后出任伪县长，组织维持会，为日军征集物资，协助日军控制豫中包括平顶山地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('46f494c195df48e391c520d45f3acbff','b0ef39cdbaf940c7b1651f04bfe57b09',1944,'伪临汝县维持会会长、伪县长','临汝（今属平顶山汝州市）沦陷后组织维持会，任伪县长，为日军征粮派款、搜集情报，镇压抗日群众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b9af7d8cfd194c4e939eabbeec5a520b','42fb54d5549a49d88797d3208cb21142',1944,'伪鲁山县维持会会长','鲁山（今属平顶山）沦陷后出面组织维持会，协助日军维持地方秩序，征发民夫物资。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5aefc309999d4d34b3c013628331155b','c663863c960f4bf8839380e202936b81',1944,'伪豫西自治军司令','豫西沦陷后投敌，组织伪自治军，在平顶山、宝丰、鲁山一带配合日军行动，骚扰抗日根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fee737ddcb7c4fefa16694c43686d5e8','3528daef89c7440fa850f8592d84f11f',1944,'伪宝丰县维持会会长','宝丰（今属平顶山）沦陷后任维持会会长，为日军筹粮筹款，协助建立伪基层政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f050bb2f59614f35ae82e828df7dbe32','a36adf024ce44c63a7d6f7c343eb3712',1944,'伪叶县维持会会长','叶县（今属平顶山）沦陷后组织维持会，任会长，协助日军统治地方，征发劳役。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b6a471530e6d4ce0aae057467e7cb78e','4eff0ffeb5824b35b6ef219203b87277',1944,'伪郏县维持会会长','郏县（今属平顶山）沦陷后任维持会会长，为日军服务，镇压抗日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('33dabb6230cd4a9ca311637277e35bc7','e2514afaf3df4fda87c43f712d34fac9',1944,'伪舞阳县维持会会长','舞阳（今属平顶山）沦陷后组织维持会，任会长，协助日军征粮征丁。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5c2b735427f24ca9bc4ea3601ccaeb1a','260e03fb0baa4197bc2f82f5d4273c92',1944,'伪襄城县维持会会长','襄城（今属平顶山）沦陷后任维持会会长，为日军筹办物资，维持伪秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8771c363d10e404f92a4f60230ab514f','cb4fd60a84ac4782bad97fbf983f8c94',1944,'伪平顶山维持会会长','平顶山地区沦陷后，出面组织维持会，为日军征集物资、情报，协助日军管理煤矿及地方治安。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a7c47c9f6c2e4d35b9ce2ecfb87cfa1a','2bd76bd4f7874f8f8becd896967ac4f3',1944,'伪宝丰县维持会会长、伪宝丰县县长','宝丰县邻近平顶山新华区，李振亚在日军占领宝丰后出任伪职，组织维持会，征派民夫、粮食供给日军，配合日军扫荡周边抗日武装。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f8198c76885c46aaa4fbd7bd30fbc489','c692801ac2c3420b89c5234722019808',1944,'伪叶县维持会会长','叶县与平顶山新华区接壤，赵子明在日军侵占叶县后组织维持会，为日军提供情报、粮秣，并协助建立伪保甲制度。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('10859bcf7eb94bef91994b3ac881ce32','6e9ca6b425994c5b88f8c66b5a917691',1944,'伪鲁山县维持会副会长','鲁山县靠近平顶山新华区，刘子久在日军占领期间出任伪维持会副会长，协助日军征粮、派款，维持地方伪秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1440d8945ba7405bbb20a4e7797b302e','a36adf024ce44c63a7d6f7c343eb3712',1944,'伪襄城县维持会会长','襄城县与平顶山地区相邻，张伯英在日军侵占襄城后组织维持会，为日军征集物资、修筑工事，并参与伪政权基层管理。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ab16e2b143b14b1c923a4ea84e1ece93','4fb7b58e00cf47eba0110680d7e06ced',1944,'伪郏县维持会会长','郏县紧邻平顶山新华区，王明远在日军占领郏县后出任伪维持会会长，协助日军推行保甲、征粮抓丁，镇压抗日群众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c3027a657c6342c191aa8b91dce37d2a','793dba30c5cd4e9ab0835412a8dc7906',1937,'伪河南省政府省长、伪河南省维持会会长','抗战期间在河南沦陷区出任伪职，先后任伪河南省维持会会长、伪省长，协助日军在河南各地建立伪政权，其伪省府机构对平顶山、汝州等地的伪县政权有统辖关系。；河南人，抗战期间投敌，曾任伪河南省省长，主持全省伪政权，推行日军殖民政策，其伪政权体系覆盖濮阳、南乐等豫北地区，为日军搜刮物资、镇压抗日力量服务。；河南安阳人，抗战初期即组织伪维持会，后任伪河南省政府省长，为日军在河南推行殖民统治，其伪政权机构设于开封，对郑州、新密等地伪政权有统辖关系。；河南本地士绅，日军占领开封后出面组织伪维持会，后任伪河南省长，协助日军在河南各地建立伪政权，包括郑州、荥阳地区的伪县政权。；河南本地汉奸，抗战初期组织维持会，后任伪河南省省长，协助日军在河南各地建立伪政权，驻马店、平舆等县伪政权均受其统辖。；河南安阳人，抗战初期即组织维持会迎降日军，后任伪河南省省长，协助日军在河南推行殖民统治、征粮征丁，其伪政权体系覆盖驻马店各县。；抗战初期即在河南参与组织伪维持会，后任伪河南省政府省长，协助日军推行殖民统治、征粮征丁，其伪省政权覆盖河南包括驻马店一带。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1d99f26214ae4ec9987b291ea7170559','25917df51aa04d7793ee1451b8167067',1938,'伪河南省政府委员、伪豫西道尹','在河南沦陷区任伪豫西道尹等职，负责豫西地区伪化行政，其辖区包括临汝（今汝州）、郏县、宝丰等平顶山地区，协助日军征粮、拉夫、维持治安。；在伪河南省政府中任职，负责豫西道事务，管辖洛阳及嵩县等地，协助日军推行伪化政策。；1944年日军占领豫西后，出任伪豫西道尹，管辖包括洛阳在内的豫西地区，协助日军维持统治。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('14e8fd03f23f479aa8f528a7f58f2e4c','d409a62a1fcf424a82d99abd16ad9bea',1944,'伪临汝县维持会会长、伪临汝县县长','1944年日军侵占临汝（今汝州）后，出面组织维持会并任伪县长，协助日军建立伪政权、征发物资、镇压抗日活动，是汝州本地直接附逆的代表人物。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5eb3d145152847d7a093dcd43d7f6f2d','d00abe2d305841a9923c2b6f58f34737',1944,'伪临汝县保安团团长','临汝沦陷后投靠日军，任伪保安团团长，率部配合日军扫荡汝州周边抗日武装，维护伪政权统治。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ffc6ce62c6e347da89ed9f9ead30b485','6e9ca6b425994c5b88f8c66b5a917691',1944,'伪宝丰县维持会会长','1944年日军侵占宝丰后，组织维持会并任会长，协助日军在宝丰、汝州交界地区推行伪化统治，征粮派款。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f652a3f6faf7465d89ed9668463c32cb','a36adf024ce44c63a7d6f7c343eb3712',1944,'伪郏县维持会会长、伪郏县县长','郏县沦陷后出任伪维持会会长、伪县长，配合日军在郏县、汝州一带建立伪政权，镇压抗日群众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bfddece0043847e7ab8a7651003bf828','9136812e246d44968bc6a122297298ad',1944,'伪鲁山县维持会会长','鲁山沦陷后组织维持会，任会长，协助日军在鲁山、汝州交界地区征发物资、维持伪秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e2f36c05bb7544d5b2eebcfb1460bc2e','1b173aa0e4744eab8c1b146e0be9d072',1944,'伪叶县维持会会长','叶县沦陷后任伪维持会会长，协助日军在叶县、平顶山一带推行伪化统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b10bb9f0777448e78f3b2cdc30ddea8c','c692801ac2c3420b89c5234722019808',1944,'伪襄城县维持会会长','襄城沦陷后出任伪维持会会长，配合日军在襄城、平顶山周边地区征粮拉夫，维持伪政权。；1944年日军侵占襄城后，组织维持会，为日军征粮征丁、提供情报，协助日军镇压当地抗日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f2c107f2a77c4638bdb9aea95b875caa','2bd76bd4f7874f8f8becd896967ac4f3',1944,'伪许昌县维持会会长、伪许昌县县长','许昌沦陷后任伪维持会会长、伪县长，协助日军在许昌、平顶山地区建立伪政权，其伪县府与汝州伪政权有联系。；1944年日军占领许昌后，组织维持会并出任伪县长，为日军征集物资、维持治安，其活动范围与漯河、临颍同属豫中地区。；1944年日军占领许昌后，出面组织伪维持会，后任伪许昌县县长，协助日军维持占领秩序、征粮派款。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4446c65423e9411bbe447d64a8db0213','1796a08d440c4f18b5af8b7fe542deac',1938,'伪河南省教育厅厅长','在河南沦陷区任伪教育厅厅长，推行奴化教育，在包括平顶山、汝州在内的沦陷区学校强制使用伪教材，进行亲日宣传。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9a799fd8cb014c6ca9923be45194da8a','fefd7f9ddbac40469c751144d6cbd784',1938,'伪河南省警务厅厅长','任伪河南省警务厅厅长，统辖沦陷区伪警察力量，在平顶山、汝州等地建立伪警察机构，配合日军镇压抗日活动。；掌管伪河南省警务，建立伪警察体系，配合日军镇压河南沦陷区包括新乡的抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('932011d1b08a48718eb06f85a05ec24f','38d5ea25829949a28b7f32f06c1059e8',1944,'伪临汝县警察局局长','临汝沦陷后任伪警察局局长，率伪警察配合日军搜捕抗日人员，维护汝州地区伪统治秩序。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e46c048a0a974008b622bb43e02bbf27','cd6bd8e57e4147f5b633a46a11754965',1944,'伪临汝县保安队队长','临汝本地人，投靠日军后任伪保安队队长，带领伪军配合日军扫荡汝州周边村庄，抓捕抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a48e848dc7104b0696f3a3be6fc41fdf','177c17b9b440453fa41ed47b9ebbd502',1938,'伪和平救国军第三路军司令','著名土匪汉奸，抗战期间投靠日军，率伪军在河南、山东交界地区活动，其部曾流窜至豫中平顶山、汝州一带，配合日军骚扰抗日根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b61af3cac9b64684a613aee51def9cb0','42fb54d5549a49d88797d3208cb21142',1938,'伪平顶山维持会会长','抗日战争期间在平顶山地区组织伪维持会，协助日军维持地方治安、征粮派款，镇压抗日群众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3f8ba0e6c78f47e7921abce941ff865e','2bd76bd4f7874f8f8becd896967ac4f3',1940,'伪叶县保安团团长','在叶县及周边地区（含今平顶山湛河一带）组建伪保安团，配合日军扫荡抗日根据地，抓捕抗日人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ac428e21b9b14899b996231af5b814b6','da730529440844ce928caadb51d83352',1941,'伪宝丰县维持会会长','在宝丰县及邻近平顶山地区组织维持会，为日军筹集物资、情报，协助日军控制地方。','基层维持会/地方自治头目','hanjian');
