INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a6d763b5ddc54a5fa86b8eba1afbc8d9','c700efc4b7484f43814808e97db5b6f2',1941,'伪郏县保安大队大队长','在郏县及平顶山地区率领伪保安大队配合日军行动，袭击抗日游击队，强征民夫。','基层头目','hanjian');
