INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('078b25c7f1f84453a8b589b6ba64d80e','e202339a17dd4f1980873eab80c88173',1939,'伪平顶山矿区把头兼情报员','在平顶山煤矿区充当日军把头，监视矿工，向日军提供抗日人员活动情报，参与镇压矿工反抗。','无明确职位或一般帮凶','hanjian');
