INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3e17285724124738b22028f5421dff0c','a2a33c8255fc4a2f89bc0416be0e6e0a',1938,'伪河南全省警务处处长','在伪河南省政府中负责警务，统辖沦陷区伪警察，配合日军镇压抗日活动，其警务系统覆盖平顶山、鲁山等地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4150eb87fea84a8ba967a99df1c6f1c6','342fa3388ae7472fb6629b24e1da04d5',1938,'伪开封市维持会会长、伪开封市市长','日军占领开封后出面组织维持会，后任伪开封市市长，协助日军推行殖民统治、征粮征丁。；日军占领开封后出面组织伪维持会，后任伪开封市市长，协助日军推行殖民统治、征发物资与劳工。；日军侵占开封后出面组织伪维持会，后任伪开封市市长，协助日军推行殖民统治、征发物资与劳工。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ecea23b9cf7448aa8ac80574c8ed3dc7','da468ceacd8e4ec1a1dec91ade2429a7',1938,'伪河南省省长','任伪河南省省长期间，配合日军在开封及河南占领区推行伪政权建设、治安强化运动。；伪河南省公署成立后任省长，驻开封，秉承日军意旨推行伪政，镇压抗日活动，为河南沦陷区重要附逆人物。；任伪河南省省长期间驻开封，配合日军建立伪政权体系，推行保甲连坐与物资统制。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fb52961fa6664eef8aa2bcad4f83f978','a1da16c8e56e480dac4f7b8ce876b429',1937,'伪河南省省长','任伪河南省省长，驻开封，继续为日军征集粮食、劳工，维持伪统治。；任伪河南省省长期间驻开封，配合日军征粮、征夫，推行伪化教育。；任伪河南省省长期间驻开封，继续配合日军统治，参与征粮征丁和镇压抗日活动。；任伪河南省长期间驻开封，协助日军搜刮粮棉、维持伪政权统治。；任伪河南省省长，驻开封，继续为日军搜刮物资、维持伪统治秩序。；继续推行伪化政策，为日军在河南包括驻马店地区的统治服务。；在河南伪政权中任职，配合日军统治，对陕西抗日根据地有间接影响。；投敌后任伪河南省省长，配合日军统治。；在河南沦陷区任伪职，配合日军统治，其活动区域与陕西邻近。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d95432cd8929486584345726b3acdeca','41d2b197fedd4eefa3bd64d7cebe1523',1943,'伪河南省省长','抗战末期任伪河南省省长，驻开封，直至日本投降。；后期伪省长，配合日军强化治安，镇压抗日力量。；在开封任伪河南省省长，为日军搜刮物资、维持伪政权，直至抗战胜利。；抗战末期出任伪河南省长，驻开封，继续为日伪维持地方统治。；任伪河南省省长，驻开封，抗战末期仍协助日军维持占领区统治。；任伪河南省长期间，配合日军扫荡，维持驻马店地区伪秩序。','省部级/大军区级要员','hanjian');
