INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fbf0277fec5a4b8693eef6097aed45e1','3c48bf950e3a432195b9d60741552bf0',1938,'伪开封市维持会会长','日军占领开封后组织维持会，为日军筹粮筹款、招募伪职人员，维持沦陷区秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5f76aaf011194f10844f27f8d363ba72','da468ceacd8e4ec1a1dec91ade2429a7',1938,'伪河南省警务厅厅长','在开封主持伪河南警务，配合日军清乡、扫荡，镇压抗日群众。；掌管伪河南警务，督导包括新乡在内的各地伪警察机构镇压抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('52b0921b74ff4f8780a75d12b2a7e057','fefd7f9ddbac40469c751144d6cbd784',1940,'伪开封绥靖公署主任','在开封地区统率伪军，配合日军扫荡抗日根据地，镇压民众抗日活动。；统辖伪军配合日军扫荡，控制开封及周边地区。；在开封设立绥靖公署，指挥伪军进攻抗日武装。；在开封设立伪绥靖机构，指挥伪军配合日军作战。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0eee4321a8bc4795acde8d77e9b6d6d5','5ec2ad124b2f429482b1a90a7f8d4a92',1943,'伪和平救国军第二十四集团军总司令、伪河南省保安司令','投敌后率伪军在河南境内配合日军扫荡，活动范围涉及开封、兰考周边地区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('23b95b84551c44bea3ef26d7ec9897e9','9f7b3ed9c76f4eea8211fd8ebc40a461',1943,'伪和平救国军新编第五军军长','投敌后率伪军在河南北部及豫东地区配合日军作战，对开封、兰考周边抗日力量进行镇压。；投敌后率部在河南活动，配合日军扫荡，参与伪政权军事行动。；原国民党军将领，1943年在河南被俘后投敌，任伪军军长，活动于河南北部及豫西地区，配合日军作战。；投日后在河南境内配合日军行动，其势力范围涉及许昌周边。；在河南投敌后率伪军配合日军作战，活动于豫中、豫北地区，与许昌、长葛有军事关联。；投敌后任伪军军长，在河南北部及郑州附近活动，配合日军进攻抗日根据地。；原国民党将领，1943年在河南被俘后投敌，所部伪军活动于豫北、豫东，与驻马店地区伪军有联络。；原国民党新编第五军军长，1943年被俘后投敌，任伪新编第五军军长，驻防豫北、豫东，其伪军曾活动于豫南驻马店周边。；原国民党将领，1943年被俘后投敌，所部伪军活动于河南北部及豫南部分地区，对驻马店周边有间接影响。；原国民党将领，投敌后任伪军头目，活动于华北、华中，与陕西渭南地区有间接联系。','市县厅局级','hanjian');
