INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5872f3cafa2f4dcd8fccca40555834f6','a976a94be0bf4b76b621948c0802222f',1933,'伪河南省政府主席（未就任前被刺）','北洋旧军阀，1933年受日本策动拟出任伪河南省政府主席，在北平被刺杀，与河南及新乡地区日伪政权筹划有关联。；北洋旧军阀，1933年受日军拉拢，企图出任伪河南省政府主席，在北平被刺杀，与河南伪政权筹建有关。；北洋旧军阀，1933年受日军拉拢，拟出任伪河南省政府主席，在北平被刺杀，其活动与河南伪政权筹建有关。；北洋旧军阀，1933年受日军拉拢，企图出任伪河南省政府主席，在北平被刺杀，其活动涉及河南伪政权筹组。；北洋旧军阀，九一八事变后与日本特务勾结，被日方内定为伪河南省政府主席，1933年在北平被刺杀，其附逆活动涉及河南及华北地区。；北洋旧军阀，1933年受日军拉拢，拟出任伪河南省政府主席，在北平被刺杀，与河南伪政权筹建有关。；北洋旧军阀，九一八事变后与日本特务勾结，被日方委任为伪河南省政府主席，企图在河南建立伪政权，1933年在北平被刺杀。；北洋旧军阀，九一八事变后投靠日本，被日方委任为伪河南省政府主席，1933年在北平被刺杀，其伪政权活动涉及河南全省，郑州、惠济一带亦在其名义管辖范围内。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b247f6e21f0d47a99e96d8d39bbb4023','41d2b197fedd4eefa3bd64d7cebe1523',1944,'伪河南省政府省长','抗战末期任伪河南省长，直至日本投降，参与日伪在河南包括新乡地区的最后统治。；1944年任伪河南省省长，时值洛阳沦陷，其伪政权直接参与洛阳及豫西地区的日伪统治。；伪河南省长，抗战末期仍附逆，直至日本投降。；抗战末期任伪河南省省长，继续为日军服务，直至日本投降。；抗战末期任伪河南省长，继续为日军服务，直至日本投降。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ef1d571d06a64600995870af80fe2188','d485c70cf19e49daa34f4a4e02302297',1938,'伪新乡县维持会会长','日军侵占新乡后出面组织维持会，为日军筹粮筹款、维持地方秩序，是当地早期汉奸头目之一。；日军侵占新乡后，组织维持会，为日军筹粮筹款，维持地方伪秩序。','基层维持会/地方自治头目','hanjian');
