INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('99548101e61e454ea937c0d8519bf187','a976a94be0bf4b76b621948c0802222f',1933,'伪河南省政府主席（未就任即被刺）','北洋旧军阀，1933年投靠日本，被委任为伪河南省政府主席，未及赴任即在北平被刺杀，其伪政权计划覆盖河南包括新乡一带。；北洋旧军阀，1933年投靠日本，被委任为伪河南省政府主席，未及就任即在北平被刺杀。；北洋旧军阀，1933年投靠日本，被委任为伪河南省政府主席，尚未就任即在北平被刺杀，与洛阳地区有政治关联。；北洋旧军阀，1933年投靠日本，被委任为伪河南省政府主席，尚未就任即在北平被刺杀，其活动涉及河南地区。','无明确职位或一般帮凶','hanjian');
