INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b57146834ec64ee7a82f8abc75a75683','635f627893344f38be7aafbcec1e279b',1938,'伪豫北道尹/伪新乡地区要职','在豫北伪政权中任职，协助日军控制新乡一带，推行治安强化运动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fad9a1ed3c984d3b9311088b80dfe41f','9f7b3ed9c76f4eea8211fd8ebc40a461',1943,'伪新编第五军军长（降日后）','原国民党军将领，1943年降日，所部被编为伪军，活动于豫北、新乡一带，配合日军进攻抗日根据地。；原国民党军将领，1943年在河南林县一带投降日军，所部编为伪军，活动于豫北、新乡周边地区。；1943年在河南林县被俘后降日，任伪军军长，活动于豫北新乡一带，配合日军进攻抗日根据地。；1943年率部投降日军，所部被编为伪军，活动于豫北太行山区及鹤壁、浚县周边，配合日军进攻抗日根据地。；1943年率部投降日军，所部驻防豫北，配合日军进攻抗日武装，活动范围包括鹤壁、淇县周边。；1943年在豫北林县、辉县一带率部投降日军，被编为伪军，配合日军进攻抗日根据地。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('52b13c3d5f9249158f2db059cb77378d','5ec2ad124b2f429482b1a90a7f8d4a92',1943,'伪第二十四集团军总司令（降日后）','原国民党军将领，1943年降日，任伪军总司令，所部活动于豫北包括新乡地区，协助日军维持占领。；原国民党军将领，1943年在河南投降日军，任伪军总司令，所部活动于豫北、新乡一带。；1943年在河南降日，任伪军总司令，所部活动于豫北新乡、获嘉周边，协助日军维持占领区。；1943年投降日军，所部伪军活动于豫北地区，包括鹤壁、浚县一带，协助日军维持占领。；1943年投降日军，在豫北地区收编伪军，协助日军维持占领，其势力波及鹤壁、淇县一带。；1943年在豫北林县地区被俘后投降日军，出任伪职，率伪军配合日军扫荡太行山区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3c3d01daae324beb99edf37edc493ab7','53719b7eb602459ebd656b246a4d1a92',1938,'伪豫北保安司令/伪军头目','豫北地区伪军头目之一，率部配合日军扫荡新乡、原阳等地抗日力量。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c3cb8971dbf44371b73b004c57e5dc4c','38b34fb7f6c3411580ffe576ac292e0f',1938,'伪安阳保安司令/伪军头目','豫北伪军头目，势力涉及新乡以北地区，配合日军维持豫北伪统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1188c7ecd1474b30b95cb9def8a26441','3b57a17d2c3d4092b9af781e5aef0f69',1940,'伪豫北剿共军头目','在豫北组织伪武装，配合日军清乡、扫荡，活动范围接近新乡、原阳一带。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7815ff9f901d4108af1c1adb9cb1b9f0','a67d024285724be0acbad8ecf6f712c4',1938,'伪新乡县警察局长','任伪新乡县警察局长，协助日军搜捕抗日人员、维持伪治安。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cd681585993f4a9cba2124de11f434b8','fd019576460a43799c9eb4e8aa1e9685',1938,'伪河南教育界附逆者','在河南沦陷区参与伪教育机构，推行奴化教育，其活动涉及豫北新乡等地。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('11a2ab5d91034fdf93b3edc6135d4e83','a1c48c4603f844dfb19de1ae060c5d44',1938,'伪河南文化界附逆者','在河南沦陷区参与伪文化宣传，为日军殖民统治张目，活动范围包括豫北。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ecfa7bd38292465db51a8d6868947f4a','848992e841c9488c8cdcf56cad9f079c',1938,'伪和平建国军第一军军长、伪第四方面军总司令、伪河南省省长','河南柘城人，抗战期间投靠日军，在豫东、豫北一带组建伪军，长期配合日军对河南抗日根据地和国统区进行扫荡、蚕食，1943年后任伪河南省省长，是河南地区影响最大的汉奸武装头目之一。；河南柘城人，抗战期间投靠日军，在豫东、豫中一带组织伪军，配合日军进攻抗日根据地，后任伪河南省省长，其伪军势力活动范围覆盖漯河及周边地区。；河南柘城人，抗战期间投靠日军，在豫东、豫北一带组织伪军，配合日军进攻抗日根据地，后任伪河南省省长，是河南地区最具代表性的汉奸之一。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6f9955dd49ad41f6b4eda6418309f947','9f7b3ed9c76f4eea8211fd8ebc40a461',1943,'国民党军新编第五军军长，后投敌任伪军头目','1943年在河南林县一带被日军包围后投降，所部被编为伪军，活动于豫北、太行山南麓一带，配合日军进攻抗日根据地，对包括新乡在内的豫北地区造成危害。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('56796c6b37d64d068740e0cc4cef5891','5ec2ad124b2f429482b1a90a7f8d4a92',1943,'国民党军第二十四集团军总司令，后投敌任伪军总司令','1943年在豫北林县、辉县一带被日军俘获后投降，被日军委任为伪军总司令，所部活动于豫北地区，配合日军维持伪统治，对新乡及周边地区有直接影响。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e1dac891cba84870ab57a7ffe80ebe8b','2bd76bd4f7874f8f8becd896967ac4f3',1938,'伪新乡县维持会会长、伪新乡县县长','抗战期间在新乡县城沦陷后出面组织维持会，后任伪新乡县县长，协助日军征粮、征夫、维持治安，镇压抗日活动，是新乡本地伪政权的重要人物。；抗战期间在新乡沦陷后出面组织维持会，后任伪新乡县县长，协助日军征粮、派夫、维持地方伪政权，直接服务于新乡及周边地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0242a9255cf44ec6ae4baab51ca9ff70','c692801ac2c3420b89c5234722019808',1938,'伪封丘县维持会会长','封丘沦陷后组织维持会，为日军筹粮筹款、拉夫修路，协助日军建立伪基层政权，是封丘当地附逆代表人物。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f809e1a22f6b4ab4b79e21f524119e6e','067b8e028f5740dfa47b25db64ed7534',1939,'伪封丘县县长','任伪封丘县县长期间，推行保甲制度，配合日军清乡、扫荡，镇压当地抗日武装和群众，维护日伪在封丘的统治。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6ecfbd8778ba4397a3a6908c2b805325','24b27e92935346b5b0c750031defdd1f',1938,'伪豫北道尹、伪河南省政府委员','在豫北道任职期间，负责新乡、封丘等县伪政权的督导，配合日军实施经济统制、征发劳工，是豫北地区伪政权的重要汉奸官员。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9b8dd1b2e36449bd9ac1af45f611b861','fefd7f9ddbac40469c751144d6cbd784',1938,'伪和平建国军豫北地区头目','抗战期间在豫北一带收编土匪、散兵组成伪军，配合日军驻守新乡及周边据点，参与对封丘、延津等地的扫荡和清乡。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('98646dae311e43de8cd5c2406c0ba617','53719b7eb602459ebd656b246a4d1a92',1940,'伪军师长，活动于豫北','率伪军在豫北新乡、封丘、延津一带配合日军作战，进攻抗日根据地，抢粮抓丁，残害抗日群众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('746d896f97cb49e1a32ed020ef2db501','3b57a17d2c3d4092b9af781e5aef0f69',1938,'伪新乡地区保甲长、伪自卫团头目','在新乡周边乡村担任伪保甲长并组织伪自卫团，为日军征粮、派夫、搜集情报，协助日军控制基层，迫害抗日家属。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('47f1d82acbf74d4393665e8195438e17','4b034429b0834c0ebe93d3a9b2e7c572',1939,'伪封丘县教育科科长','在封丘推行奴化教育，编写亲日教材，组织师生参加日伪宣传活动，为日军殖民统治服务。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('76bc184f5f284d2eac0933c5a2fa14da','fcb3e5ff966f4327a818cbc1e3244da5',1938,'伪河南省商会联合会头目','在河南沦陷区协助日军实施经济掠夺，控制新乡、封丘等地物资流通，为日军筹集军需，是经济领域附逆代表。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6d284f23130b434cb390ba490ffa7a4f','24b27e92935346b5b0c750031defdd1f',1937,'伪河南省政府主席、伪豫北道尹','抗战期间投敌，历任伪豫北道尹、伪河南省政府主席等职，协助日军在豫北推行伪化统治，新乡、延津一带在其伪政权管辖范围内。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4d6a521c00dd40808299fcba34613ff7','793dba30c5cd4e9ab0835412a8dc7906',1938,'伪河南省政府主席、伪豫东道尹','投靠日军，曾任伪河南省政府主席、伪豫东道尹等职，参与河南伪政权维持与征粮、征丁等附逆活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('01c74faf686a414697d19212b8c22e31','a2a33c8255fc4a2f89bc0416be0e6e0a',1938,'伪新乡县维持会会长、伪新乡县县长','新乡沦陷后出面组织维持会，后任伪新乡县县长，为日军筹粮筹款、维持地方伪秩序，直接涉及新乡及延津周边地区。；新乡沦陷后出面组织维持会，后任伪县长，为日军征粮征丁，强占民田，协助日军在辉县、新乡交界地区建立据点。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('98ab4dd9c2724124990612f7c509ed31','c692801ac2c3420b89c5234722019808',1938,'伪延津县维持会会长','延津沦陷后组织维持会，投靠日军，为日军征粮派款、维持伪地方秩序，是延津当地附逆代表人物之一。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fd19512bebf743508f26723b6287f973','1808b7d9d025494598d265e55ca66fc9',1938,'伪延津县县长','任伪延津县县长期间，配合日军推行保甲、征粮征丁，镇压当地抗日力量，直接服务于日军在延津的统治。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f7d284da07a94520b7c639ef1d91b9cf','b1303da80b994629ba3bf2748d8842c1',1939,'伪豫北剿共军司令（后投敌）','原国民党河北民军首领，后与日军勾结，在豫北一带进行反共附逆活动，其势力范围涉及新乡、延津周边。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cb4ddcbd1019452790ad93b5e147ef8f','2bd76bd4f7874f8f8becd896967ac4f3',1938,'伪豫北道公署警务科长','在伪豫北道公署任职，参与警务与情报活动，协助日军在豫北各县包括新乡、延津进行治安控制和抗日人员搜捕。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('043f2531ff674e0f9687b75a6d1b29fe','4fb7b58e00cf47eba0110680d7e06ced',1938,'伪新乡县教育科科长','在伪新乡县政权中负责教育，推行奴化教育，篡改教材，向学生灌输亲日思想，属文化教育领域附逆者。；在新乡推行奴化教育，修改教材，灌输亲日思想，培训伪师资。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1250a414b4cb4f83b9cd64d9d52318b9','8853ebc9482649aca1ee056bfe54c04c',1938,'伪延津县保安团团长','组织伪保安团，配合日军扫荡延津及周边抗日根据地，参与抓捕抗日军民、抢粮拉夫等附逆活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('016b578e08ef46e4978505867db72fe8','cb4fd60a84ac4782bad97fbf983f8c94',1938,'伪新乡县维持会会长、伪新乡县县长','日军侵占新乡后，出面组织伪维持会，后任伪新乡县县长，为日军征粮、派夫、维持地方伪秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('21869a12f3ae4fe6b8dd30775b0ca0cc','a2a33c8255fc4a2f89bc0416be0e6e0a',1938,'伪新乡县公署要职、地方维持会头目','新乡地方士绅，附逆日军，参与伪新乡县政权与维持会活动，协助日军控制新乡城乡。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6187e9c1ee6548d095390bd090db58e2','f77ba5f6586a42188eb81b08f690986b',1938,'伪新乡县警察所所长','任伪新乡县警察头目，带领伪警察配合日军搜捕抗日人员、催征粮款。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('71af7624d1534581b79729d359b41614','067b8e028f5740dfa47b25db64ed7534',1938,'伪豫北道尹','伪豫北道管辖新乡等地，刘明德任道尹期间，推行日军政令，控制豫北伪政权。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d3204c87357b45038bfe350eb6adf612','2bd76bd4f7874f8f8becd896967ac4f3',1938,'伪豫北道保安司令','统率伪豫北道保安部队，配合日军在豫北包括新乡一带进行清乡、扫荡。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fc6b8c51cd7740f1b847fa2e8e6b661a','53719b7eb602459ebd656b246a4d1a92',1940,'伪豫北剿共军司令','率伪军配合日军在豫北新乡、汲县、辉县等地进攻抗日根据地。；在豫北新乡、安阳一带组织伪军，配合日军进攻抗日根据地，残害抗日军民。；在豫北地区组织伪军，配合日军进攻抗日根据地，残害抗日军民。；在济源、孟县、温县等地组织伪军，配合日军扫荡，残害抗日军民。；在豫北濮阳、滑县、内黄一带组织伪军，配合日军扫荡冀鲁豫抗日根据地，捕杀抗日干部和群众。；在豫北组织伪军，活动于安阳、鹤壁、浚县等地，配合日军扫荡，残害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('03eff8290b73498eac01c57d4286bc02','38b34fb7f6c3411580ffe576ac292e0f',1938,'伪安阳、新乡一带地方武装头目','豫北地方武装头目，后投靠日军，配合日军在平汉铁路沿线新乡、安阳段进行护路与扫荡。','无明确职位或一般帮凶','hanjian');
