INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8c6be822430e4bae8ebdbdc7e1f133d8','ba51bf00958b47d78ca43788f68d0e27',1939,'伪新乡县警察局局长','任伪新乡县警察局长，搜捕抗日人员，镇压民众反抗。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('065af73389a04ea68f8662be1c4a97d8','fd019576460a43799c9eb4e8aa1e9685',1940,'伪获嘉县警察所所长','在获嘉县任伪警察所所长，配合日军维持治安，迫害抗日家属。','无明确职位或一般帮凶','hanjian');
