INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2c8bd9d934174becacc1b6dbfd4c95c5','bb9f3367044e403997a73a2007e0c137',1942,'伪获嘉县合作社理事长','控制获嘉县物资配给，为日军掠夺粮食、棉花等战略物资。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3fe5301988f4419d8917d1a6d7ec7c13','a976a94be0bf4b76b621948c0802222f',1933,'伪华北政务委员会顾问、伪河南省政府主席（未就任）','北洋军阀余孽，1933年投靠日本，参与策划华北自治，1935年被任命为伪河南省政府主席，未及就任即在北平被刺杀。其活动范围涉及河南北部，与新乡、辉县地区有间接关联。；北洋旧军阀，抗战初期投靠日本，被任命为伪河南省政府主席，尚未赴任即在北平被军统刺杀。其活动与河南伪政权筹建有关。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a752769a8cba42049aae0a8eab4a114f','d485c70cf19e49daa34f4a4e02302297',1938,'伪豫北道尹','伪豫北道公署驻新乡，王锡龄任道尹期间，在新乡、辉县等地推行保甲连坐，组建伪自卫团，配合日军清乡，搜捕抗日人员。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('09e7add2a1a9492ca9103bbfcafb8779','338628f1c81b466eaa07f94c29339381',1938,'伪辉县维持会会长','辉县沦陷后组织维持会，为日军带路扫荡山区抗日根据地，强征民夫修筑公路和炮楼，迫害抗日家属。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1c0c68b4ade6442eb3d0eb4b7fba9bbe','c692801ac2c3420b89c5234722019808',1940,'伪辉县县长','任伪辉县县长期间，配合日军对太行山抗日根据地进行经济封锁，推行配给制，强征粮食和铜铁，抓捕抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('97a128a648a445b88e0be91adf1c5427','067b8e028f5740dfa47b25db64ed7534',1939,'伪新乡县警察局局长','掌控伪警察队伍，在新乡、辉县等地搜捕抗日地下工作者，刑讯逼供，参与制造多起惨案。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5d1c26a789b6468abfef22d1be375140','793dba30c5cd4e9ab0835412a8dc7906',1940,'伪豫北道保安司令','统率伪保安团配合日军驻新乡部队，对辉县、获嘉、修武等豫北地区进行反复扫荡，烧毁民房，抢掠粮食。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('332760345af4494393117e1936c5ecd3','2bd76bd4f7874f8f8becd896967ac4f3',1941,'伪新乡县合作社联合会理事长','控制新乡、辉县等地物资配给，低价强购农产品，高价配售日货，为日军经济掠夺服务，盘剥当地民众。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a30b1bbda30c4d0781eab5fcebf3ea84','cd6bd8e57e4147f5b633a46a11754965',1942,'伪辉县保安团团长','率伪保安团在辉县山区配合日军搜山，抓捕抗日游击队员，烧毁村庄，勒索百姓钱财。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('61f5a35656874b42a0d3c977663f4f22','760d3e1a7c054145942b8b3885c32745',1939,'伪新乡县教育科科长','推行奴化教育，在新乡、辉县各学校强制开设日语课，篡改历史教材，组织学生参拜神社，毒化青少年思想。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('05a6c00e0aed410bbe348c2876ada391','6e9ca6b425994c5b88f8c66b5a917691',1940,'伪豫北道宣传处处长','主办伪《豫北日报》，宣扬“大东亚共荣”，为日军侵略辩护，诋毁抗日力量，在新乡、辉县等地散发反动宣传品。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('94b238c1f32b4b629a2aaaf88910404f','d485c70cf19e49daa34f4a4e02302297',1938,'伪长垣县维持会会长、伪长垣县县长','长垣沦陷后投靠日军，组织伪维持会并出任伪县长，在长垣及周边地区为日军筹粮、拉夫、镇压抗日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('150dd7856172404da0eab3b8cc71f4e3','42fb54d5549a49d88797d3208cb21142',1938,'伪豫北道尹公署道尹','伪豫北道管辖新乡、长垣等县，赵子立作为伪道尹，负责推行日军在豫北的行政、经济掠夺政策，是新乡、长垣一带伪政权的重要头目。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d0bc32b317f84526bf3e262e08dc038b','793dba30c5cd4e9ab0835412a8dc7906',1938,'伪河南省政府委员、伪豫北道道尹','抗战期间在河南沦陷区任伪职，曾负责豫北道行政，配合日军在豫北包括新乡、长垣等地实施统治和资源掠夺。；伪豫北道管辖包括濮阳、清丰在内的豫北各县，陈静斋任道尹期间推行奴化教育，强征民夫，为日军掠夺物资。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('78f11fdffef94b5aad8ab37cf9cc6d7e','614d7c7e23ff423f92117c0c884eee87',1938,'伪豫北保安司令','在豫北地区组织伪保安部队，驻防新乡一带，协助日军清乡、扫荡，镇压抗日武装。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('df9e3eff7b5445dc8040a0b40e1e296f','a1d8acfa6324461c8558e68d813ea429',1938,'伪新乡县警察局局长','在新乡沦陷期间任伪警察局长，负责城区治安与情报，配合日军搜捕抗日人员，维持伪政权统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('966afee0432a4982a75f223578e9d5df','a2a33c8255fc4a2f89bc0416be0e6e0a',1938,'伪长垣县保安团团长','长垣本地人，投靠日军后组织伪保安团，配合日军在长垣及黄河沿岸地区进行扫荡和征粮。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('13d4641fd71d4055849e8e69dde2169f','d485c70cf19e49daa34f4a4e02302297',1944,'伪洛阳县维持会会长','1944年日军攻占洛阳后，出面组织维持会，为日军筹粮、拉夫、维持治安。；洛阳沦陷后出任伪洛阳县维持会会长，为日军筹粮、派夫、维持治安，配合日伪政权在洛阳及嵩县一带进行统治。','基层维持会/地方自治头目','hanjian');
