INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c76242ce8eb74532bf640ce96b5b23c5','2bd76bd4f7874f8f8becd896967ac4f3',1944,'伪洛阳县警察局局长','任伪洛阳县警察局长，配合日军搜捕抗日人员，镇压民众反抗。；在日军占领洛阳期间担任伪警察局长，协助日军搜捕抗日人员、镇压民众，活动范围覆盖洛阳城区及嵩县部分乡镇。；充任伪洛阳县警察局长，率伪警察配合日军搜捕抗日人员、镇压民众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9462efb7c6494e8ea8d5c2c0a756bc59','7afda6e05b9949d28074a369c144b4b0',1944,'伪豫西自治军司令','在洛阳周边收编土匪、溃兵，组织伪军配合日军扫荡豫西抗日根据地。','基层头目','hanjian');
