INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d8c10e7292fd404a9ccfd9f109d2c8b0','92b57485f7b148b88921a92ec018662b',1944,'伪偃师县知事','洛阳周边偃师县沦陷后出任伪知事，协助日军征粮征丁。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b7d9329a3b344409add53b821a51423e','38b34fb7f6c3411580ffe576ac292e0f',1938,'伪安阳县维持会会长','豫北安阳沦陷后组织维持会，为日军筹粮、拉夫、维持伪政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0692224f3bca49ec9bd6e6298eb00253','bbd63c1ca8684efa918c037030708eac',1938,'伪开封市市长','开封沦陷后出任伪市长，协助日军统治河南省会。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d13d399ef31e4d809124f4f50e03198e','da468ceacd8e4ec1a1dec91ade2429a7',1938,'伪开封市警察局局长','任伪开封市警察局长，配合日军搜捕抗日人员。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('417a1c848b174261b60f3c8f9bf9b97a','fefd7f9ddbac40469c751144d6cbd784',1938,'伪河南省政府委员','参与伪河南省政，协助日军推行各项伪化政策。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7a11b65455e842a787b44e3aed1a4bd4','d15c35a070b14591b367c3b719c29380',1944,'伪河南省政府委员、伪豫西行政督察专员','1944年豫西沦陷后投靠日军，参与组织伪河南省政权，在洛阳、伊川一带协助日军推行保甲、征粮和维持会体系。；抗战后期洛阳沦陷后，参与日伪在豫西的行政维持活动，协助日军推行保甲与征粮，活动范围覆盖洛阳及豫西各县。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bd76d4a776e24eefa135126e70dca2ea','42fb54d5549a49d88797d3208cb21142',1944,'伪洛阳县维持会会长','洛阳沦陷后出面组织维持会，为日军筹粮、派夫、维持城区秩序，并协助伪政权向伊川等周边地区扩展控制。；日军占领洛阳后出面组织维持会，为日军筹粮、派夫，并协助建立伪基层保甲体系。；日军占领洛阳后出面组织维持会，为日军征粮、派夫、维持城区秩序，直接服务于洛阳及附近新安地区的占领统治。；1944年日军攻占洛阳后，出面组织洛阳县维持会，为日军筹粮、拉夫、维持城区秩序，并协助建立伪基层政权。；日军占领洛阳后出面组织维持会，协助日军征粮、拉夫、维持城区秩序。；1944年日军攻占洛阳后，出面组织洛阳县维持会，协助日军维持地方秩序、征发物资，为洛阳地区伪政权头目之一。；1944年日军攻占洛阳后，出面组织伪洛阳县维持会，协助日军维持地方秩序、征粮征夫。；洛阳沦陷后受日军指使组建洛阳县维持会，为日军筹粮筹款、征派民夫，协助维持城区及老城一带的殖民秩序。；1944年日军攻占洛阳后，出面组织洛阳县维持会，协助日军维持地方秩序、征派物资，直接活动于洛阳城区及西工一带。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c0d4cbd9333249cd91aae9eb72cfbdc1','2ba1fd11caa34837ac501ad4d431ac96',1944,'伪洛阳县知事','日军占领洛阳后出任伪县知事，主持伪县政，配合日军清乡、征粮，并在伊川、偃师交界地区推行伪化统治。；任伪洛阳县知事，主持伪县政，为日军征发民夫、粮食，推行伪化统治。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1c3f01d696634ad4a19e1c5236f6ed52','033d2413b6044b03b4088c6b99a76a34',1944,'伪豫西剿共军司令','收编地方武装组成伪军，在洛阳、伊川、宜阳一带配合日军扫荡抗日根据地，袭击八路军和地方抗日武装。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1421c23e822c465db1e5b7b10c089811','2bd76bd4f7874f8f8becd896967ac4f3',1944,'伪伊川县维持会会长','伊川沦陷后组织维持会，为日军征集粮食、民夫，协助建立伪区乡政权，并参与镇压当地抗日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('509c5b7436224b478500bfbe8eebdd2c','cb5c123407db4327a62478fa50c09023',1944,'伪伊川县保安团团长','率地方武装投敌，编为伪保安团，在伊川及洛阳南部配合日军进行清乡、搜捕抗日人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ce3e2cb0706f4262915426fe7a2fd826','c663863c960f4bf8839380e202936b81',1944,'伪豫西自治军总指挥','豫西沦陷后投靠日军，拼凑伪自治军，活动于洛阳、伊川、嵩县一带，协助日军维持占领区秩序并对抗抗日武装。；在洛阳、宜阳、洛宁交界地区组织伪自治军，协助日军维持占领区治安。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8ef05f6b8d494d858bc440b4029005fa','0c9d9be7baba497bac5b4c4c48d4839b',1944,'伪洛阳县警察局局长','出任伪警察局长，利用伪警力量侦捕抗日人员，配合日军在洛阳及伊川周边实施治安强化。；任伪警察局长期间，搜捕抗日人员，镇压民众反抗，推行奴化教育。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8ab8bc6a958842ca97301d4e68dad91f','f883b2d3e3e1446cbc28c60f9f2c9d54',1944,'伪河南省宣传处职员、伪洛阳教育会负责人','在洛阳教育文化界附逆，主持伪教育会，推行奴化教育，为日军占领宣传服务。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6f420cbc272a4df795b64628f3c484fc','1b173aa0e4744eab8c1b146e0be9d072',1944,'伪洛阳商会会长','控制洛阳商会，为日军筹措物资、摊派款项，协助日伪经济统制，并影响伊川等地商贩。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('65916d89ce6f4ebcaef1cc49e96552e1','d15c35a070b14591b367c3b719c29380',1944,'伪河南省政府委员、伪豫西行政公署主任','抗战后期在豫西沦陷区参与伪政权，协助日军维持洛阳及豫西一带的治安与征发。；抗战后期在豫西沦陷区参与伪政权，协助日军维持豫西占领区秩序，活动范围涉及洛阳及新安周边。；抗战后期在豫西沦陷区附逆，参与伪政权维持会与地方治安活动，活动范围覆盖洛阳及豫西各县。；抗战后期洛阳沦陷后，参与伪河南省政权，在豫西地区协助日军推行伪化统治，活动范围覆盖洛阳及周边。；日军发动豫湘桂战役占领洛阳后，出面组织伪豫西行政公署，协助日军维持豫西占领区治安，推行伪化统治。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b839ec9c167e4d6aa4e88f43f66d2eb0','fd019576460a43799c9eb4e8aa1e9685',1944,'伪豫西道尹公署道尹','在洛阳及豫西地区推行伪政令，配合日军清乡、征粮，镇压抗日活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dbef95f79d7744e19d9eb53cc36220a5','d485c70cf19e49daa34f4a4e02302297',1944,'伪洛阳县警察局局长','组建伪警察队伍，协助日军搜捕抗日人员，维持洛阳城区及近郊治安。；在日军占领洛阳期间担任伪警察头目，参与搜捕抗日人员、镇压民众反抗，并协助日军维持殖民统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('648e0448936b452aab6bbf69e06c26cf','2bd76bd4f7874f8f8becd896967ac4f3',1944,'伪宜阳县维持会会长','在宜阳沦陷期间组织维持会，为日军征粮派款，并诱降地方武装。','基层维持会/地方自治头目','hanjian');
