INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4487209397384f70859280872e89ba0b','a36adf024ce44c63a7d6f7c343eb3712',1944,'伪河南省教育厅督学、伪洛阳中学校长','在沦陷区推行奴化教育，改编教材，组织学生参加亲日宣传活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c00c774aada54df4a3e3d5dd806d8606','1956371a4c354bada35bbbcc05d9d35b',1944,'伪洛阳县商会会长','控制洛阳商业物资，为日军采购军需，并协助推行伪币与物资统制。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b2ca4bb417d24c4f95fe22b01a28c194','ec99e7a101984e4abcdbcacf5f6e6bae',1944,'伪豫西保安总队总队长','在洛阳、宜阳、嵩县交界地区活动，配合日军清剿抗日武装，残害地方民众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7c93771d4ef54509acd19382e5cb814a','d15c35a070b14591b367c3b719c29380',1938,'伪河南省政府委员、伪豫西道尹公署道尹（未就任）','抗战初期被日军拉拢，曾列入伪河南省政府名单，但未实际就任；后在洛阳、嵩县一带从事地方活动，与日伪有接触，历史评价复杂。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f68bc51b9e324d79b5ffdf013a312f28','42fb54d5549a49d88797d3208cb21142',1944,'伪豫西维持会会长','1944年日军攻占洛阳后，在洛阳及豫西地区组织维持会，协助日军维持地方秩序、征粮派款，活动范围涉及洛阳、嵩县周边。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9ca07ac45d6346eb853b4cd07619120c','fd019576460a43799c9eb4e8aa1e9685',1944,'伪豫西道尹公署秘书、伪嵩县维持会顾问','洛阳沦陷后投靠日伪，参与组织嵩县维持会，为日军提供情报、协助征粮，是嵩县当地较有影响的附逆者。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4f9999dff483462182ec115c82a894bc','c663863c960f4bf8839380e202936b81',1944,'伪豫西保安团团长（后反正）','原为地方武装首领，1944年日军侵占豫西后一度投敌，被编为伪保安团，活动于洛阳、嵩县交界地区，后率部反正。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7d7d9bd4614d4e7885c60e74b06b3cd9','0c9d9be7baba497bac5b4c4c48d4839b',1944,'伪嵩县维持会会长','1944年日军侵入嵩县后，出面组织维持会，为日军筹集物资、维持地方，是嵩县当地直接附逆的代表人物。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1e86155af4254976a87cd69f9aeecc04','a36adf024ce44c63a7d6f7c343eb3712',1938,'伪河南省政府参议、伪豫西道尹公署参议','抗战期间在河南日伪政权中任职，参与伪河南省政府事务，与洛阳、嵩县地方伪政权有联系，协助日军推行治安强化运动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bf28a86afe6341ceaebf535e188bc09f','fcb3e5ff966f4327a818cbc1e3244da5',1938,'伪河南全省警务处处长','在伪河南省政府中主管警务，统辖包括洛阳、嵩县在内的伪警察系统，镇压抗日活动，为日军维持占领区秩序。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('db428750c18b41bdb7dd83d3a1500b5d','fd019576460a43799c9eb4e8aa1e9685',1944,'伪洛阳县知事','在洛阳沦陷期间出任伪县知事，配合日军推行保甲、征发劳役，活动范围覆盖洛阳城区及新安一带。；洛阳沦陷后出任伪洛阳县知事，配合日军在洛阳城乡推行保甲、征粮、拉夫等政策。；在日军占领洛阳期间出任伪县知事，管理洛阳城区及老城民政，配合日军推行保甲连坐与物资统制。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0080172bb82b448484690acbb9a706dc','d485c70cf19e49daa34f4a4e02302297',1944,'伪新安县维持会会长','新安沦陷后组织维持会，为日军筹集粮秣、情报和民夫，直接在新安地区为日军占领服务。','基层维持会/地方自治头目','hanjian');
