INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8545706a5c9d40cab55f612bce78a805','0c9d9be7baba497bac5b4c4c48d4839b',1944,'伪豫西剿共军司令','在豫西收编土匪、散兵组成伪军，配合日军对洛阳、新安一带抗日根据地和游击区进行扫荡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('584bfe336106499bb50569cd3c87db7e','c663863c960f4bf8839380e202936b81',1944,'伪河南剿共军副总司令（后投日）','原国民党将领，抗战后期在河南率部投敌，所部被编为伪军，活动范围包括洛阳、新安周边地区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6b69a626e1774950a823b3e6c4b11a08','5ec2ad124b2f429482b1a90a7f8d4a92',1943,'伪第二十四集团军总司令（投日后）','1943年在河南投敌，所部伪军活动于豫北、豫西，与洛阳、新安地区日伪政权有协同关系。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4dc5acc797dc45aab44c3ec500e9fdd9','8f1dd12e548b4c4f866dd743c3377896',1940,'伪河南省政府省长','汪伪政权在河南的最高行政头目之一，推行伪化教育、征粮征丁，其政令覆盖包括洛阳、新安在内的河南沦陷区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('293569ec894a407cac89659385cf4e20','793dba30c5cd4e9ab0835412a8dc7906',1938,'伪河南省政府委员兼伪豫西道尹','负责豫西道伪政权，督导洛阳、新安等县维持会与伪县公署，为日军征发物资、维持治安。；在豫西地区协助日军建立伪道、县政权，推行保甲连坐，为日军搜集情报、征发物资，活动范围覆盖洛阳及周边。；在豫西道任内，协助日军建立伪政权，推行保甲连坐，镇压抗日活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0fdeaa3d21aa4813834dd61a25f8be4d','d409a62a1fcf424a82d99abd16ad9bea',1944,'伪洛阳县警察局局长','在洛阳沦陷期间掌管伪警察，配合日军搜捕抗日人员、管制居民，活动涉及洛阳及新安交界地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('957649a4e53f48389d96f7c21cc97575','19bdb5eaf0e54b8fa34aa2290466712a',1944,'伪新安县警察所所长','在新安组织伪警察力量，为日军提供情报、抓捕抗日群众，直接服务于新安地区的日伪统治。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e7e2e939989f4d41ba2b73a35f2deb30','6b437c7423ad48679ac13f71e92cafac',1944,'伪洛阳县教育会会长','在洛阳推行奴化教育，改编教材、组织亲日宣传，影响洛阳及新安周边学校。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d9d6dc2e0b294d0fa98710e76acc1eb1','6f8f1faf86ae4a1e9e8fbd0a243d2b96',1944,'伪新安县商务会会长','在新安为日军筹款、摊派物资，协助控制沦陷区经济，属于经济领域附逆者。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f2a7d55d5f304bc99bec27b44e049c12','fd019576460a43799c9eb4e8aa1e9685',1944,'伪豫西自治军司令','洛阳沦陷后投靠日军，收编地方武装组成伪军，配合日军在洛阳、偃师、孟津一带清乡、扫荡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ee1890489753454180ff603107d36cfe','2bd76bd4f7874f8f8becd896967ac4f3',1944,'伪栾川县维持会会长','1944年豫西沦陷后，在栾川地区组织维持会，为日军征粮派款、带路搜山，协助日军控制伏牛山北麓交通线。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('661ee5908bdb4cd8baf83bbffd465203','c663863c960f4bf8839380e202936b81',1944,'伪豫西保安团团长','洛阳及豫西沦陷后率部投敌，所部被编为伪保安团，在洛阳、宜阳、嵩县、栾川交界地区配合日军行动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ba0f736fc24b46ad9b18efbd4ab6d72f','0c9d9be7baba497bac5b4c4c48d4839b',1944,'伪河南省宣传处职员、伪洛阳《新民报》编辑','在洛阳沦陷后参与日伪宣传机构，编辑亲日报刊，鼓吹“大东亚共荣”，为日军殖民统治进行文化宣传。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('63cde6b01541474790e41909f346950e','a976a94be0bf4b76b621948c0802222f',1938,'伪河南自治军总司令','抗战初期在河南北部及豫西一带收编土匪武装，投靠日军，组织伪军配合日军进攻抗日根据地，后活动范围扩展至豫西。；在豫北包括焦作一带组织伪军，配合日军作战。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('18c3832f3f02449287a4d71ea0ac8d31','8f1dd12e548b4c4f866dd743c3377896',1938,'伪河南省省长、伪华北政务委员会委员','作为伪河南省最高行政头目，推行日军殖民政策，在河南全省包括洛阳地区建立伪政权、征粮拉夫、镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e5561e70690143fa8e4096fb50063d85','fcb3e5ff966f4327a818cbc1e3244da5',1944,'伪洛阳县公署知事','日军占领洛阳后出任伪县知事，主持伪县政，协助日军征粮、派夫、登记户口，维持洛阳城区及近郊殖民统治。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2af7472697434b689c44fb27c4a71f23','d409a62a1fcf424a82d99abd16ad9bea',1944,'伪洛阳商会会长','在洛阳沦陷期间出面组织伪商会，为日军筹款、摊派物资，协助日军控制洛阳商业与经济命脉。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1678474d3e134e4890a60c988c0d9948','d15c35a070b14591b367c3b719c29380',1944,'伪洛阳县维持会会长','日军占领洛阳后，出面组织伪洛阳县维持会，协助日军维持地方秩序、征派粮款、拉夫修路，为日军侵略服务。；日军占领洛阳后，出面组织伪洛阳县维持会，协助日军维持地方秩序、征派粮款。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f18594a516d943bd99089bb479ca8d6c','4e22079107b14c1193280b07f4da5441',1944,'伪洛阳县知事','任伪洛阳县知事期间，配合日军推行保甲制度，征发民夫、粮食，镇压抗日活动，维护日伪统治。；洛阳沦陷后任伪洛阳县知事，在日军控制下管理洛阳县政务，包括涧西地区，推行保甲制度、征粮征丁。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('80d70c48048a47b5a82908264b90dc11','2bd76bd4f7874f8f8becd896967ac4f3',1944,'伪豫西剿共军司令','在洛阳及豫西地区收编土匪、散兵，组织伪军配合日军扫荡抗日根据地，袭击八路军和地方抗日武装。；在洛阳、洛宁一带收编土匪与溃兵，组织伪军配合日军扫荡抗日根据地。；收编地方土匪武装组成伪军，配合日军在洛阳、偃师、孟津一带扫荡抗日根据地，残害抗日军民。；收编地方武装投靠日军，组成伪军配合日军在洛阳、偃师、巩县一带扫荡，镇压抗日力量。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ee90335d535d4095b128d2434785e61e','520cc059ddff46fa89cb46f1b3804b54',1944,'伪洛阳县警察局局长','控制伪警察力量，搜捕抗日人员，勒索百姓，为日军提供情报，协助维持洛阳城区治安。','市县厅局级','hanjian');
