INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('74d7db2e962c40d5a0ee7c217cc34c11','5ec2ad124b2f429482b1a90a7f8d4a92',1943,'伪暂编第二十四集团军总司令、伪开封绥靖公署主任','原国民党河北省政府主席、第二十四集团军总司令，1943年在河南林县被俘后投降日军，出任伪职，在河南开封等地协助日军维持伪政权统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('206082ac304d4d65b4e7db3a05dbed1c','e471cbcbc80d46a8ac1c06a70f6a9820',1944,'伪临颍县维持会会长、伪临颍县县长','1944年日军侵占临颍后，出面组织维持会，后出任伪临颍县县长，为日军筹粮筹款、征派民夫，协助日军维持地方治安，是临颍当地直接附逆的代表人物。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bd33f62fb2804bb68d69112b7160673f','da8bc6a0c8ad438ab8ceae18d53d2efa',1944,'伪郾城县维持会会长、伪郾城县县长','1944年日军占领郾城后，组织维持会并出任伪县长，为日军征集物资、维持地方秩序，其活动范围覆盖漯河及周边地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('88ae75f2168644b89e926a37d3a2788b','d492b175c0d2433d82d0b823bf81a6ef',1944,'伪漯河镇维持会会长','1944年日军侵占漯河后，出面组织漯河镇维持会，协助日军管理地方事务、征发物资，是漯河当地直接为日军服务的汉奸头目。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e6bff7a8138845e5b8608d7b23e1f8a2','f056bbda69f94541a6e18accfa3ee857',1944,'伪舞阳县维持会会长、伪舞阳县县长','1944年日军占领舞阳后，组织维持会并出任伪县长，为日军征粮征夫，协助维持伪政权统治，活动范围与漯河、临颍相邻。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bdf2cd7ffee24ffd9f3ae7f9f7e4cd73','b1303da80b994629ba3bf2748d8842c1',1939,'伪豫北剿共军司令','原国民党军将领，抗战期间在河南北部与日军勾结，组织伪军配合日军进攻抗日根据地，其活动虽主要在豫北，但对河南全省伪军体系有影响。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('76312b1cf40e4866b31c33b59bbef0b3','2159de38efb94153bd3d92638438b38a',1938,'伪河南省宣传处处长','在伪河南省政府中负责宣传事务，为日军殖民统治进行文化宣传和奴化教育，鼓吹“中日亲善”“大东亚共荣”，是河南文化教育领域附逆的代表人物。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('525cc25d51e1452d99223333bd7c3afd','cb4fd60a84ac4782bad97fbf983f8c94',1944,'伪漯河维持会会长','1944年日军占领漯河后，出面组织伪维持会，协助日军维持占领秩序、征派物资、登记户口，是漯河当地直接附逆的伪政权头目。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('26907c2fef984ad58eafe6aabe166186','a2a33c8255fc4a2f89bc0416be0e6e0a',1944,'伪郾城县维持会会长','郾城沦陷后任伪维持会会长，为日军征粮、派夫、维持地方伪秩序，郾城为漯河附郭县，召陵即在其辖境，属当地直接附逆者。；郾城地方士绅，日军侵占郾城后率先投敌，组织维持会，为日军带路、指认抗日人员及家属。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5376916321ee4e4e9c2b7d7148b786be','d492b175c0d2433d82d0b823bf81a6ef',1944,'伪郾城县警察局局长','在郾城沦陷期间任伪警察局长，配合日军搜捕抗日人员、镇压民众，维持伪治安体系，活动范围覆盖漯河、召陵一带。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d64515c9fc3a473da3ac9e8cf61da8ab','f056bbda69f94541a6e18accfa3ee857',1944,'伪临颍县维持会会长','临颍沦陷后组织伪维持会，协助日军征粮、派款、维持占领区秩序，临颍与漯河、郾城相邻，属漯河周边地区附逆者。；临颍沦陷后组织伪维持会，协助日军维持临颍及邻近舞阳地区的统治秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('10a09f1be518466d922024734033e175','49dec89263424c2a9206607bb993ce48',1944,'伪许昌县维持会会长','许昌沦陷后任伪维持会会长，为日军筹粮、派夫、维持伪政权，许昌为漯河邻近地级区域，其伪化活动与漯河一带伪政权联系密切。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bc74ad5b50504925982eabc3cda2c08f','1796a08d440c4f18b5af8b7fe542deac',1944,'伪舞阳县维持会会长','舞阳沦陷后任伪维持会会长，协助日军控制舞阳及周边地区，舞阳与漯河、郾城接壤，属漯河周边附逆伪职者。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a4cce55aa13f4382af3d02cd862fcb8b','8853ebc9482649aca1ee056bfe54c04c',1944,'伪漯河商会会长','漯河沦陷期间任伪商会会长，为日军筹款、摊派物资，协助维持经济掠夺体系，属经济领域附逆者。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1017c5f5e0a349c7b86d19d55403b0c2','10374107eb744b6a8e506e7eb0f6342a',1944,'伪郾城县教育科科长','在郾城沦陷期间任伪教育科科长，推行日军奴化教育，篡改教材，宣传“大东亚共荣”，属教育文化领域附逆者，活动范围覆盖漯河、召陵。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b439cb723f2d44de96ecaa84d8b68394','cd6bd8e57e4147f5b633a46a11754965',1944,'伪郾城县召陵区保甲长','召陵当地保甲长，日军占领期间协助伪政权征粮、派夫、清查户口，直接为日军和伪维持会服务，属基层附逆者。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a9e64d4bcf974846aa8e8f0ad8a7efb8','fcb3e5ff966f4327a818cbc1e3244da5',1938,'伪河南省警务厅厅长、伪开封市警察局局长','在伪河南省警务系统任职，负责伪警察力量，配合日军搜捕抗日人员，其警务网络覆盖漯河等豫中城镇。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('51b135e4a90c4c42bc2b6c9d44a671a5','d409a62a1fcf424a82d99abd16ad9bea',1944,'伪漯河维持会会长','漯河本地商人，1944年日军占领漯河后出面组织维持会，为日军筹集物资、招募劳工，协助维持占领区秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d741206f97a847988930e4142ef71555','f056bbda69f94541a6e18accfa3ee857',1944,'伪郾城县知事','郾城县（今漯河市源汇区、郾城区一带）伪政权头目，日军占领期间任伪知事，推行保甲制度，征粮派款，配合日军清乡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('79893bfcf00344779ba49b72dd846871','38d5ea25829949a28b7f32f06c1059e8',1944,'伪漯河警察所所长','在漯河镇（今源汇区）任伪警察所所长，带领伪警察配合日军巡查、抓捕抗日嫌疑人员，勒索商户。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('79fed870836f4b1bbe7cfcdea0444a44','cd6bd8e57e4147f5b633a46a11754965',1944,'伪漯河保甲长','漯河本地地痞，日军占领后充当保甲长，负责摊派捐税、监视居民，多次向日军密报抗日人员行踪。','一般帮凶/基层人员','hanjian');
