INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8c111e1291994cc4bcc096ff40daff31','d492b175c0d2433d82d0b823bf81a6ef',1944,'伪郾城县公署知事','日军侵占郾城后出任伪县知事，在漯河、郾城一带推行伪政，征发物资、登记户口，配合日军统治。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bfc0813b79764e888d32500f5fe911f4','cd6bd8e57e4147f5b633a46a11754965',1944,'伪漯河镇维持会会长','漯河镇人，日军占领漯河后组织维持会，为日军搜集情报、征派民夫，协助日军控制漯河镇及周边区域。','基层维持会/地方自治头目','hanjian');
