INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b35e33adb45840fb91ac829a8b233ad3','aa3d77b342e94b6a836d4677c7bdc819',1944,'伪漯河维持会会长','日军占领漯河后，组织伪维持会，协助日军管理漯河镇及周边地区，为日军征集物资、情报。','基层维持会/地方自治头目','hanjian');
