INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cd5443a5ac1b47059813bd57335e4bd0','a2a33c8255fc4a2f89bc0416be0e6e0a',1937,'伪濮阳县维持会会长、伪濮阳县知事','日军侵占濮阳后出面组织维持会，协助日军建立伪政权，推行保甲连坐，为日军征粮派款、搜集情报。；抗日战争时期投靠日军，在濮阳组织维持会，后任伪濮阳县知事，协助日军征粮、派款、抓捕抗日人员，镇压当地抗日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6d32bfb2b93d479fb612f7864021f07e','1a4bd9c96a304940986068b2e0a00561',1938,'伪濮阳县保安团团长','率部配合日军扫荡濮阳周边抗日根据地，捕杀抗日军民，强征民夫修筑据点与封锁沟。；濮阳人，抗战期间投靠日军，任伪濮阳县保安团团长，率部配合日军扫荡濮阳、台前一带抗日武装，捕杀抗日干部和群众。；率部投降日军，编为伪濮阳县保安团，配合日军扫荡濮阳周边抗日根据地，袭击抗日武装，残害群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('45a5ee076ef24904a979b6d18e1637b9','321ccab00f8a4fe4b1ae1aeae34f3570',1939,'伪濮阳县警察局局长','在濮阳城内搜捕抗日人员，镇压群众抗日活动，协助日军维持占领区治安。','市县厅局级','hanjian');
