INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d05a634a3af6478aa3fd5ada82f6ee9e','53719b7eb602459ebd656b246a4d1a92',1938,'伪和平救国军暂编第六军军长、伪豫北绥靖公署主任','河南濮阳人，抗战初期即投靠日军，在濮阳、清丰、南乐一带组织伪军，任伪暂编第六军军长，后任伪豫北绥靖公署主任，长期控制濮阳地区，配合日军扫荡冀鲁豫边区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ef038ab9d5594ad2a4f3ae893da44fc4','2efa3b1637824e71a5227941dfc3e4af',1938,'伪濮阳县维持会会长、伪濮阳县县长','濮阳本地士绅，1938年日军占领濮阳后出面组织维持会，任会长，后任伪濮阳县县长，协助日军征粮、派夫、建立保甲制度，镇压抗日群众。','基层维持会/地方自治头目','hanjian');
