INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('db9eda0af1cb4ea6b3bf75f9804608cb','135b16ef41e74ecc8b954f7fe8666eda',1938,'伪河南省政府教育厅长','在伪河南省政府中负责教育，推行亲日奴化教育，其教育政策覆盖郑州等地学校。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2e48f80d7fee44d9bd11f46f2e80b2e7','342fa3388ae7472fb6629b24e1da04d5',1938,'伪郑州维持会会长、伪郑县县长','郑州沦陷后组织伪维持会，后任伪郑县县长，为日军在郑州地区的统治提供地方行政支持，协助征发民夫、物资。；郑州沦陷后出面组织伪郑州维持会，后任伪郑县县长，为日军征集物资、维持地方秩序，是郑州地区伪政权代表人物。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('af544b2454a24bd79a591ec63f0104ec','a2a33c8255fc4a2f89bc0416be0e6e0a',1938,'伪郑州商会会长、伪维持会要员','郑州商界人物，抗战期间附逆，任伪商会会长及维持会要员，为日军筹款筹粮，协助控制郑州经济。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2804abb37efd4e44809260ccf32297cb','a976a94be0bf4b76b621948c0802222f',1938,'伪河南省政府豫东道尹','任伪豫东道尹，驻商丘，管辖豫东地区，为日军征粮征丁，配合日军对豫东抗日武装的扫荡。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6b61ab15016b475cb8c89d893ff2fae1','fefd7f9ddbac40469c751144d6cbd784',1940,'伪和平救国军将领、伪河南省政府委员','投敌后任伪军将领及伪河南省政府委员，在河南境内协助日军作战，参与对抗日根据地的进攻。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2161eb8e4da04712b6bba993f5a9fc2e','119eac9eaebd4e12a3fb99eee1912d9f',1938,'伪郑州警察局局长','任伪郑州警察局局长，负责郑州沦陷区治安，搜捕抗日人士，协助日军维持殖民统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0b2b3cb1911d411091447fe2389f6260','d485c70cf19e49daa34f4a4e02302297',1938,'伪郑县维持会副会长','郑州沦陷后参与组织伪维持会，任副会长，协助日军征发物资、民夫，维持地方伪政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5b77f032b17e459f88f02eb9f6143f17','8853ebc9482649aca1ee056bfe54c04c',1938,'伪郑州保甲长','郑州地区伪保甲长，协助日军推行保甲制度，监视居民，征发劳役，迫害抗日家属。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fc79ff21cbef437fb895bf2c2cb27a81','5ec2ad124b2f429482b1a90a7f8d4a92',1943,'伪和平建国军第二十四集团军总司令、伪河南省政府委员','原国民党河北省政府主席、第24集团军总司令，1943年在河南林县被俘后投敌，所部被编为伪军，活动于豫北、豫东一带。；原国民党河北省政府主席、第二十四集团军总司令，1943年被俘后投敌，任伪和平建国军第二十四集团军总司令，活动于豫北、豫西一带，其伪军曾进入郑州周边地区配合日军行动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4a376e6bdf204fb2b609aa77930f3b5a','41d2b197fedd4eefa3bd64d7cebe1523',1940,'伪河南省省长、伪军事委员会参谋总长','原东北军将领，投敌后曾任伪河南省省长，后调任伪南京政府军事要职，在河南期间配合日军进行治安强化运动。；河南伪政权及伪军要员，其活动范围与陕西渭南地区邻近。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9e9901baa1a047e5a9c8b2740fc68e83','a2a33c8255fc4a2f89bc0416be0e6e0a',1938,'伪郑县县知事','日军占领郑州后出任伪郑县县知事，推行保甲制度，配合日军征发民夫、物资，维持沦陷区基层统治。；日军占领郑州后出任伪郑县县知事，管理郑县及周边地区伪政，配合日军征粮、拉夫、清乡，活动范围包括今郑州金水一带。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('de3004ed7e584143a261866d30e76600','c692801ac2c3420b89c5234722019808',1938,'伪中牟县维持会会长','中牟沦陷后组织维持会，为日军提供情报、粮秣，协助日军控制中牟及周边地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('92c5d43476344d9887bc0060de602a5a','782e349015c34117b68d41c83f4a0267',1941,'伪中牟县县知事','出任伪中牟县县知事，推行奴化教育，征发劳工，配合日军对中牟地区抗日武装进行清剿。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('51d029fa00ce4fa5a852b8bd5d5f4f58','38d5ea25829949a28b7f32f06c1059e8',1938,'伪郑州警察局局长','掌管郑州伪警察系统，搜捕抗日分子，镇压民众反抗，协助日军维持治安。；控制郑州伪警察系统，配合日军搜捕抗日人员，镇压市民反抗，管理良民证与通行证。；在郑州沦陷期间担任伪警察头目，协助日军搜捕抗日人员，维持城区治安，参与镇压民众抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('52701ca0161c4fecb2e513493ce83db5','cd6bd8e57e4147f5b633a46a11754965',1938,'伪郑州保甲长','郑州本地保甲长，协助日军清查户口、征发劳工、催缴粮款，为日军基层统治服务。','一般帮凶/基层人员','hanjian');
