INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8e3b2de460b14f6690358453fc549550','2bd76bd4f7874f8f8becd896967ac4f3',1939,'伪郑州新民会会长','任伪郑州新民会会长，协助日军进行宣传、奴化教育、物资征集，组织亲日团体，是郑州文化教育领域的主要附逆者。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('915632c55bd14532a0c93e68a6a524a6','2a353d8987f94e768884b67142b3a9e2',1940,'伪河南省宣传处科长、伪郑州新民会干事','在伪河南省宣传系统及郑州新民会任职，参与亲日宣传、奴化教育，协助日军控制舆论。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dd42c5301ccc49d88ae77c6a4cff0d5a','848992e841c9488c8cdcf56cad9f079c',1938,'伪和平救国军第一军军长、伪第四方面军总司令、伪河南省政府豫东道尹、伪苏豫皖边区绥靖军总司令','河南柘城人，抗战期间投靠日军，在豫东、豫南及郑州周边地区组织伪军，配合日军进攻抗日根据地，曾任伪河南省政府豫东道尹，其伪军活动范围覆盖郑州、开封及豫中地区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fd19905a9814411e8c8607a601a83ad6','63006a4879fb4f49ad97a1e88c8c5d69',1942,'伪和平救国军第二方面军总司令、伪开封绥靖公署主任、伪河南省政府主席','原西北军将领，1942年率部投敌，任伪第二方面军总司令，驻防开封、郑州一带，配合日军扫荡豫中抗日武装，后任伪河南省政府主席。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('110cdd1d79e54500a5e9174e31a088b9','5ec2ad124b2f429482b1a90a7f8d4a92',1943,'伪和平救国军第二十四集团军总司令、伪河南省政府主席、伪开封绥靖公署主任','原国民党河北省政府主席、第二十四集团军总司令，1943年在河南林县被俘后投敌，任伪第二十四集团军总司令，后任伪河南省政府主席，驻开封、郑州，协助日军维持豫中占领区。','省部级/大军区级要员','hanjian');
