INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a54518e24229400e8a6015175137f0ad','fcb3e5ff966f4327a818cbc1e3244da5',1938,'伪河南省警务厅厅长、伪开封警察局局长','在河南伪政权中负责警务，参与镇压抗日活动，搜捕抗日人员，维持日军在开封及周边地区的殖民统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dd327d82cb394803a857436367c03737','d409a62a1fcf424a82d99abd16ad9bea',1938,'伪郑州维持会会长','郑州沦陷后组织伪维持会，协助日军维持郑州城区治安，征派粮款、劳工，为日军提供情报，是郑州本地直接附逆的代表人物之一。；日军侵占郑州后，出面组织伪维持会，协助日军维持地方秩序、征发物资。；郑州沦陷后出面组织伪维持会，协助日军维持郑州城区秩序，为日军筹粮、派夫、征收物资，是郑州本地直接附逆的伪政权头目之一。；郑州沦陷后出面组织伪维持会，协助日军维持郑州城区秩序、征发物资、登记户口，是郑州本地直接附逆的伪政权头目之一。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('90a4b8bad7884f5b978139740ff17301','a2a33c8255fc4a2f89bc0416be0e6e0a',1941,'伪新郑县维持会会长、伪新郑县县长','新郑沦陷后投靠日军，组织伪维持会并任伪县长，协助日军控制新郑地区，征粮抓丁，镇压抗日群众，直接关联新郑地区。','基层维持会/地方自治头目','hanjian');
