INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f82c7089bc7c40a6b11fd16850b5260e','3528daef89c7440fa850f8592d84f11f',1938,'伪正阳县维持会会长','在正阳县城组织伪维持会，为日军提供粮秣、情报，协助日军维持豫南占领区秩序。；正阳县人，日军侵占正阳后组织维持会，为日军征发民夫、粮食，协助日军在正阳、确山一带建立据点。','基层维持会/地方自治头目','hanjian');
