INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f4ea6c84928647fa84182c84097ec76c','9dce2f4b795b41cd885bd547e190dc39',1938,'伪泌阳县维持会会长','在泌阳县城组织伪维持会，协助日军控制豫南山区边缘地带，为日军提供情报和物资。；泌阳属驻马店地区，任维持会会长，协助日军征粮、清乡，迫害抗日群众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6d6c63cdb6f740ca8c21d0716dac8f48','bf398d44782c4c1594ef5ef1eecbf521',1938,'伪河南省政府委员、伪豫南道尹','在伪河南省政府中负责豫南道事务，管辖包括驻马店、汝南在内的豫南各县，协助日军推行伪化统治。','无明确职位或一般帮凶','hanjian');
