INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8d1ea3f7f9134c488a8ffe28fa93d3db','d823baec96e04682bca33413f02ae20d',1938,'伪浙江省省长','继任伪浙江省长，配合日军“清乡”行动，强征物资，迫害抗日军民。；继任伪浙江省长，强化对绍兴、上虞等地的控制，配合日军“扫荡”和物资掠夺。；原国民党政客，投敌后任汪伪浙江省省长，在金华等地推行日伪统治，协助日军清乡、征粮，镇压抗日力量。；曾任汪伪政权浙江省省长，推行日伪统治政策，协助日军在浙江进行经济掠夺和清乡运动。；曾任汪伪政权浙江省省长，在杭州推行日伪统治政策，协助日军征粮、镇压抗日力量，其管辖范围涉及金华、永康等浙中地区。；投敌后任伪浙江省省长，配合日军统治浙江沦陷区。','省部级/大军区级要员','hanjian');
