INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('43dc2693a6594710873a26614cbf83ea','5a4f56944b43494e91fd2c1483fb2b13',1943,'伪玉环县田粮处主任','负责为日军征收军粮，虚报产量，强抢农民稻谷，导致多地饥荒，民怨极大。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9c401b0cafee4ee8bb295a93b8ca519a','42fcec40ebf248fa9ad0d37a9a2bbfad',1938,'伪黄岩县维持会会长、伪黄岩县县长','抗战期间投靠日军，在黄岩组织伪维持会，后任伪黄岩县县长，协助日军征粮、派款、维持占领区秩序，镇压抗日活动。黄岩与路桥地域相邻，其伪政权活动覆盖今台州路桥一带。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('28b305b3930d46ea95b448a0802dc129','b926d5d15d8c4344895b5ce6db20ba9f',1941,'伪温岭县维持会会长、伪温岭县县长','日军侵占温岭后出面组织伪维持会，任伪县长，为日军筹粮筹款、拉夫，配合日伪清乡，镇压当地抗日力量。温岭属台州，与路桥同处台州湾南岸。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7f947a5d545b4d5aa8833f75c8508fc1','413f6ec8f1fc4634adf12ed24a742eac',1941,'伪临海县维持会会长','临海沦陷期间投敌，组织伪维持会，替日军维持地方秩序、征发物资，并诱迫地方士绅附逆。临海为台州旧府治，对路桥一带具有行政影响。','基层维持会/地方自治头目','hanjian');
