INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('72722eba37d8447b9fc9ac33ec1403d3','5b2b99e0e44e48ada769a6dbe0498193',1941,'伪海门维持会会长','海门（今台州椒江）沦陷后组织伪维持会，任会长，协助日军控制台州湾口岸，检查来往船只、征收捐税，并迫害抗日人员。海门与路桥同属台州沿海要地。','基层维持会/地方自治头目','hanjian');
