INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0b79e42bc0d74f7b90d06a21eb889c6e','47c5e19d9dba45a6b6fa65464cb6dfec',1943,'海盐县伪情报组长','建立汉奸情报网，向日军报告新四军和国民党游击队活动地点，导致多次袭击和村民伤亡。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c4f352cc12294053b1b09e67dacda53f','a61f06db71c84aecae27ee1f97f3ea1d',1940,'嘉兴伪自卫团团长','率伪自卫团协助日军“清乡”，焚烧村庄，杀害抗日家属，并强征壮丁补充伪军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6c78ae0cae6e48858c2a1540699c1059','d6901b3dc12147e0a1a11544530b8eaf',1941,'海盐县伪教育科长','推行奴化教育，强迫学校使用日伪教材，宣扬“大东亚共荣”，并告发拒绝合作的教师。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d5e7fe0325ed48fe9c16a617f845a050','13544d0b57464b00b5f37170f3f33915',1942,'嘉兴伪水上保安队长','控制嘉兴至海盐水路，拦截商船，勒索船户，为日军运输军火，并搜捕水上抗日交通员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1e4f6ea814bf4901b4e619d0aed67d61','dc7934b01f5540738c363af568c3fbe8',1943,'海盐县伪粮食统制主任','垄断海盐粮食收购，压低粮价，导致饥荒，将大批粮食运往日军据点，饿死百姓无数。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('322f30fabe934b08b0054cd1f3c4957c','fb06ee412fb94226b9f22800c807cf4e',1940,'嘉兴伪法院推事','审判抗日人士时，按日军授意判处重刑或死刑，伪造罪名，破坏司法，助纣为虐。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d3ba62b3853141aeb86ee5ef9db26e25','30f7c4dfb1b64bb4a1f4b592a29ee32e',1938,'伪嘉兴县知事','任伪嘉兴县知事期间，协助日军推行‘清乡’政策，强征民夫，搜刮粮食，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('79fbad3d8ede43c9a5f73c48ee1ff8bb','0288f81f1e7347bd8cc1da8900aacae4',1939,'伪嘉兴县保安大队长','率伪保安队配合日军扫荡秀洲区抗日游击区，杀害多名抗日军民，并参与诱捕地下党员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('67e6233cf76242bf8c1c6f427f84d631','4d50f61a18e842c1bf1f31c1c1e0fbc9',1938,'伪秀洲区维持会会长','组织维持会为日军提供粮秣情报，强迫商户悬挂伪旗，并举报抗日积极分子，致多人被捕。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bbaa7964d2754ce2bcc2b939fdddbf53','07ff958e7f18410f864975f09234ac7e',1940,'伪特工总部（76号）浙江区负责人（曾涉嘉兴活动）','虽主要活动于上海，但曾派特务至嘉兴秀洲地区破坏抗日组织，逮捕并杀害数名地下工作者。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('206e591fdf2b443ab5ba6a748bfae898','40a321f3b2fb4082a88908f431076243',1941,'伪嘉兴县警察局特高课课长','专门侦缉抗日分子，在秀洲区设立密探网，多次带队抓捕进步学生和游击队员，酷刑逼供。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f0730339c4bd401d83b7af62bd8bff35','6f91a320d4b24c87ba22765a6743d08f',1942,'伪秀洲区自卫团团长','率自卫团协助日军修筑碉堡，封锁交通，并参与‘清乡’行动，抢劫民财，强奸妇女，民愤极大。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f9a794d48da344658b0adc7da15b1d7d','d0671f67380a4a1fa3dfd6f82d6102a2',1939,'伪嘉兴县商会会长（秀洲籍）','为日军统制物资，强征桐油、棉布等战略物资，从中牟利，并资助伪政权活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0a4f3d49dd084d1ab1b3d14490f92813','fdf06ef287034f1583bfc57fe738384f',1940,'伪秀洲区情报组组长','专门刺探新四军浙东游击队活动情报，多次引导日军突袭，导致秀洲区多个联络点被破坏。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0fdebb61ba4b43ff8e3e7e85df0bd30f','4ff53dd874e141ef96803ca1d78fd200',1938,'伪上海特别市市长（原籍宁波镇海）','原中国通商银行董事长，投敌后出任伪上海市长，为日军搜刮物资、镇压抗日力量，1940年被军统刺杀。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f2b46443735d48f29095580423ca4475','f56a62c8958f4432a34dad66f56e632c',1941,'伪宁波维持会会长、伪鄞县县长','宁波沦陷后出任伪维持会会长，协助日军推行“治安强化”运动，强征粮食和劳工，迫害抗日家属。；宁波沦陷后出任伪维持会会长，后任伪鄞县县长，为日军征粮派款，协助推行保甲制度。；宁波沦陷后出任伪维持会会长，后任伪鄞县县长，为日军征收粮饷、推行保甲制度，镇压抗日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c174a80ef79a4fb18314d2a81bdd8d9b','c8410b8912ad475793f129da4b9db987',1941,'伪宁波商会会长','充当日军经济掠夺代理人，控制宁波商会，为日军统制棉布、煤油等物资，从中牟利。；原为宁波商界头目，投日后控制商会，为日军筹措军饷，强迫商户缴纳“献金”。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bbb61fa597e0477d9081f60702ad83b9','5398dcc12d7543efac54f76b9f72ec51',1942,'伪宁波保安司令','组建伪保安队，配合日军“清乡”扫荡，捕杀抗日游击队员，参与制造多起惨案。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('24156923dc4b44609992bb973ef34fb0','3f35c5d8216c4f6f81fb965612319313',1941,'伪鄞县警察局长','效忠日军，指挥伪警察搜捕抗日地下人员，破坏中共宁波地下组织，罪行累累。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fc77646e6b3b459b9ee5ac66ad69d063','d58995eb1b6749468c3a0214a17e36b4',1941,'伪宁波税务局长','为日军征收苛捐杂税，强征田赋，导致宁波百姓负担沉重，部分款项用于伪军军费。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5fbb46f6c2df46ad93c8310d7a00779a','c0a20f989d7b4d999ade96d059456d2e',1940,'伪浙江省长（原籍宁波）','早年留学日本，投敌后任伪浙江省长，推行奴化教育，配合日军“清乡”，后调任伪粮食部长。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b37569c28c314dec9e45531b74e26309','962bb14101a04756a7f54b5b3522c181',1940,'伪浙江省主席（名义，实际由徐箴代理）','作为汪伪核心人物，虽未常驻浙江，但通过伪省府控制浙江包括宁波的行政与财政。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('abc8b94d6c884fab9a6c2ca7a355589e','9910c48b9b394ffa8c73439ed0a473b0',1941,'伪浙江省长（1941-1943）','原军统特务，投敌后任伪浙江省长，在宁波地区推行“保甲制度”，强化特务统治，镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8b493e1d33914edf8381a112ee75d8a6','becb9d36ae77476e9c0a04ea1d1c456b',1941,'伪浙江省民政厅长（兼宁波地区事务）','协助丁默邨在宁波等地推行伪政权基层建设，组织“和平救国”宣传，瓦解抗日意志。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5aafc5850afd4dd8adb7745becdcfa04','e1badd3fe14246acb4a3d2bf765b2db2',1937,'伪华北政务委员会常委（原籍宁波）','虽主要活动于华北，但作为宁波籍汉奸，曾参与伪政权对浙江的联络与物资调配。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2f72774801bd44f3bd7c8eb99b4f6e97','07ff958e7f18410f864975f09234ac7e',1939,'伪江苏省长、特工总部主任（原籍宁波）','76号特工头目，虽主要活动于上海江苏，但曾派特工渗透宁波，暗杀抗日人士，并控制宁波帮商界。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0f2171a02366477592446b2ab5a9636b','95e4356f12fb4832b18ecbad49cf091a',1939,'伪76号特工总部警卫队长（原籍宁波）','李士群手下打手，参与绑架、勒索宁波籍富商，为日军筹集资金，后因内讧被毒杀。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7bdbb64f5d844d938eea1bf593f0ed49','e2ecc3b276954dfdb951e5b9260465bf',1942,'伪宁波水上警察大队长','控制甬江航道，为日军运输军需物资，并协助日军封锁海上交通，截击抗日武装的物资补给。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('283727d56f344032be4742e1ae3e7e7c','22ea8e4e4df7441b9aaab1befe5bf4bf',1941,'伪宁波教育局长','推行奴化教育，强制学校教授日语，删改历史教材，宣扬“中日亲善”，迫害爱国教师。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ad73ac39d5734129962eeb48db264629','8e02526396f143aba9afcbc04f9247e7',1942,'伪宁波宪兵队翻译官','为日军宪兵队充当翻译，参与审讯酷刑，指认抗日分子，导致多名地下党员牺牲。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1756a6d150494860b71744d13e188dc0','9dc5879596294e0cb9867853f74f7633',1940,'伪镇海县维持会会长','在镇海（今属宁波）组织维持会，为日军征粮拉夫，破坏镇海抗日游击队活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('15871bf36e524af7ac36930633be16b1','1a9b49639f7d4f6aa0ced79d4bcfa373',1941,'伪宁波银行公会理事长','协助日军控制宁波金融，发行军用票，套取法币，扰乱经济，并资助伪军。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6772b9ad08e24f7f87c1027014c35344','0f89767d550645e4868b2f7ed99539f1',1943,'伪宁波绥靖公署参议','参与策划“清乡”行动，提供宁波地形和抗日武装情报，导致游击队多次受挫。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2d03ca09d8b343e593d75209e4b8fd5d','993e4eff978c4539b275a1e53335a341',1939,'伪浙江省政府顾问（未就任，被刺杀）','青帮头目，投靠日本，拟出任伪浙江省长，但未及上任即被军统刺杀于上海。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('28cb06ec0d244ec1a7a29ee4c01a674c','4ff53dd874e141ef96803ca1d78fd200',1938,'伪上海市长、伪浙江省长','原为宁波商人，后投靠日伪，任伪上海市长，协助日军经济掠夺，镇压抗日活动。；原为宁波商人，后投靠日伪，任伪上海市长，协助日军推行经济掠夺和殖民统治，1940年被军统刺杀。；原为宁波富商，后投靠日军，任伪上海市长，1940年被军统刺杀。曾参与对浙江沿海的掠夺和奴化统治。；原镇海籍商人，投日后任伪上海市长，后调任伪浙江省长，协助日军在浙东推行殖民统治，1940年被军统刺杀。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e84b6e2f21794309a289650ca2a5f3ef','9910c48b9b394ffa8c73439ed0a473b0',1941,'伪浙江省长、伪特工总部主任','在浙江宁波等地组织特工活动，镇压抗日力量，参与“清乡”行动，残害民众。；在浙江期间，组织特务活动，破坏地下抗日组织，对宁波地区进行残酷镇压。；浙江人，曾任伪浙江省长，在宁波、奉化等地推行保甲制度，镇压抗日力量，残害百姓。；虽原籍湖南，但任伪浙江省长期间，管辖宁波、宁海，推行“治安强化运动”，在宁海设立伪警察机构，镇压抗日力量。；原为中统特务，后投靠日本，任伪浙江省长期间，在宁波、鄞州等地推行日伪统治，镇压抗日力量，残害百姓。；在浙东地区组织特务活动，破坏抗日组织，曾到宁波、镇海视察清乡。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0e24e53d4f5e4a54a309dab18ee7c4e7','07ff958e7f18410f864975f09234ac7e',1939,'伪江苏省长、伪特工总部副主任','曾在宁波地区活动，指挥特工破坏抗日组织，协助日军进行经济掠夺和人口清查。；虽主要活动于江苏，但曾参与对浙江宁波地区的特工渗透和清剿行动。；虽为江苏人，但曾在浙江宁波等地建立特务网络，协助日军清乡，捕杀抗日志士。；原为军统特务，后投靠汪伪，负责特工活动，曾在浙江宁波地区组织暗杀和破坏抗日活动。；虽主要活动于江苏，但曾参与指挥对浙东宁波、镇海地区的特工渗透和破坏行动。；浙江遂昌人，汪伪特工“76号”实际负责人，虽主要活动于上海、江苏，但多次在浙江杭州、临安等地指挥特务行动，破坏地下抗日网络。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('beab6810379d40c6bf85e9a75eb843fb','0d2d2045fc1d498dab9499e43abcb3de',1941,'伪浙江省警务处长、伪杭州市长','在浙江宁波等地推行伪化统治，建立警察特务网络，抓捕抗日志士。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c81933f61e5841af85e79620f81da011','f50cf011f8f842fc8d69caa402ffbf67',1938,'伪内政部长、伪浙江省主席','曾管辖余姚地区，推行奴化教育，协助日军征粮征税，镇压反抗。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('292b4aa098bb4cbd8797bda014d3dd1e','28c69a91441d4439abc95701e2c6787a',1940,'伪浙江省长','在任期间对宁波、余姚实施伪化统治，组织保甲制度，配合日军扫荡。；在任期间推行奴化教育，在宁波、镇海设立伪学校，强迫民众学习日语。；直接统治浙江，在绍兴、诸暨推行伪化统治，强征粮食和壮丁，镇压抗日游击队。','省部级/大军区级要员','hanjian');
