INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('29cf241939304d739e271ef4af5373e7','2da345b6c2e840b18cda3eba84087f6b',1938,'伪宁波维持会委员','宁波商人，参与维持会，为日军提供物资。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3a3e4ad99bc4441cb33b81fc5cb50913','b3f0439840a8474faf5828a6a6637bee',1940,'伪交通部长（未实际到任）','广东人，但曾与浙江日伪合作，参与策划宁波港的日军控制。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('95c97629b2ec4106ba74dd2599020b1c','4ff53dd874e141ef96803ca1d78fd200',1938,'伪中华民国维新政府行政院院长、伪上海市长','宁波镇海人，早年投靠日本，1938年出任伪维新政府行政院院长，后任伪上海市长，推行奴化政策，镇压抗日活动，1940年被军统刺杀身亡。；浙江镇海人，曾任伪维新政府首脑，后任伪上海市长，积极推行日伪统治，镇压抗日活动，1940年被军统刺杀于上海寓所。；原为上海商人，投靠日本后任伪维新政府首脑，协助日军控制江浙沪地区，推行奴化政策，镇压抗日活动。其祖籍浙江镇海，但主要活动于上海，与杭州上城无直接关联，但因其浙江籍贯常被列入相关名单。；浙江镇海人，曾任伪维新政府首脑，后任伪上海市长，积极推行日伪统治，镇压抗日活动。虽主要活动于上海，但原籍浙江，与杭州地区有联系。；原浙江镇海人，投靠日本后任伪维新政府首脑，协助日军控制上海及江浙地区，征收苛税，镇压抗日活动。；浙江镇海人，曾任北洋政府高官，抗战期间投敌，任伪维新政府首脑，后任伪上海市长，积极推行日伪统治，1940年被军统刺杀。其活动虽以上海为主，但原籍浙江，且其势力曾渗透杭州、滨江地区。；浙江镇海人，曾任伪维新政府首脑，后任伪上海市长，积极推行日伪统治，镇压抗日活动。虽主要活动于上海，但原籍浙江，与浙江有密切联系。；原浙江镇海人，投靠日本后任伪维新政府首脑，协助日军控制江浙沪地区，推行奴化政策，镇压抗日力量。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('388cf21a220d4257b38927f66e01f465','19f49a3951974e60a6bfae5fc7ad0b7f',1941,'伪宁波地区维持会会长','宁波鄞县人，日军占领宁波后投敌，任伪维持会会长，协助日军征粮、拉夫，迫害抗日军民，搜集情报。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('35f624d6687d480e86de414943572a8f','d58995eb1b6749468c3a0214a17e36b4',1942,'伪宁海县知事','宁海本地人，日军扶植下出任伪宁海县知事，推行保甲制度，强征壮丁，为日军提供物资，镇压抗日武装。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('29eb577678c4407eab2ba53feebcc38a','dbbbf913a5ff467f844b31287abce72c',1942,'伪宁波保安司令','宁波人，投靠日军后任伪保安司令，率伪军配合日军扫荡四明山抗日根据地，杀害多名游击队员。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a6c037226b7c4252a4d3e6a4e80475d9','cd8e5ab701f04770ad28171753ae1ceb',1943,'伪浙东行政公署参议','宁海籍，任伪浙东行政公署参议，参与策划“清乡”行动，协助日军在宁海、象山一带搜捕抗日分子。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4301b9655def4d66b31d6ac381e82778','0d2d2045fc1d498dab9499e43abcb3de',1941,'伪浙江省政府秘书长','在伪浙江省政府任职期间，直接参与对宁波、宁海地区的伪政权管理，协助日军掠夺粮食和战略物资。；原国民党官员，投日后任伪浙江省政府秘书长，协助省长处理政务，在桐庐地区推行伪化统治，强征壮丁。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d0447a886d84455983ae31d5f50f88d6','c78d172e245644f5997374b3b4cf617d',1942,'伪宁波警察局局长','宁波人，投敌后任伪警察局长，组织汉奸警察队，抓捕抗日群众，破坏地下交通站，罪行累累。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3159976264bf458bb9fc119312736119','e2ecc3b276954dfdb951e5b9260465bf',1943,'伪宁海县保安大队长','宁海人，任伪保安大队长，率部配合日军“扫荡”宁海山区，烧毁村庄，杀害抗日家属。','基层头目','hanjian');
