INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8ab3d4b8f3734bb2bd58b2d1f2a6ebe6','f483eba8537042e1b947afb1e11fc5c7',1942,'伪慈溪县知事（县长）','任伪慈溪县知事期间，配合日军清乡，强征民夫，搜刮物资，镇压抗日力量。','基层头目','hanjian');
