INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('418fe4e02a85452782b5cd684a13c438','60e656f2f4464afabeada661940f4fe3',1941,'伪浙江省政府委员（原籍慈溪）','投靠汪伪政权，任伪浙江省政府委员，参与伪省府对浙东地区的统治和物资统制。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('239787adc6b648aab10497cb7f05b291','0c20c30658c249d6b3f00f4fb4dc0fbf',1943,'伪宁波地区清乡督察专员','主持宁波地区清乡工作，设立封锁线，搜捕抗日分子，强征粮食。','无明确职位或一般帮凶','hanjian');
