INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c9692de3e4094ae696a79fdce478937b','3f35c5d8216c4f6f81fb965612319313',1942,'伪宁波保安大队长','率领伪保安队参与“扫荡”，在宁波郊区和海曙周边村庄烧杀抢掠，强征壮丁。','基层头目','hanjian');
