INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4d95cafdcb2e49f08c407d7c5de08b87','845de899b20e4631bbf68676aa47dec8',1940,'伪国民政府行政院秘书长','浙江鄞县人，汪伪政权行政院秘书长，协助处理浙江事务，抗战胜利后被捕，1950年病死狱中。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4d8f71ece9a742c089c6d5d2347edab4','d35b800ae83a4c5385af2369ff517d54',1938,'伪杭州市长','浙江杭州人，1938年任伪杭州市长，推行日伪统治，强征物资，镇压抗日活动，后调任伪浙江省政府委员。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8b33a9dbaee94c13a99ce9bf2d034edf','e595823962b846eb97e7f27f2151869d',1941,'伪杭州市长','江苏武进人，曾任伪杭州市长，协助日军管理杭州，实施经济统制，1946年被处决。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1a052ce2ae394792b5f46309cf4098fd','ff0ea03fa0ac4de5898398164be0055a',1941,'伪杭州市长','浙江杭州人，曾任伪杭州市长，在任期间配合日军“清乡”，迫害抗日群众，抗战胜利后逃亡，后被逮捕处决。；继任伪杭州市长，推行日伪经济统制，强征市民财产，协助日军在杭州设立特务机构。；浙江杭州人，日伪时期最后任伪杭州市长，在滨江地区推行“治安强化运动”，镇压抗日活动，强拆民房建碉堡。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f87cc13438524a71856efe42c197bd53','ed85d7932ac840b88664eaa8f8b4ffa4',1940,'伪浙江省警务处长','浙江绍兴人，任伪浙江省警务处长，指挥伪警察协助日军搜捕抗日分子，残害百姓，战后被镇压。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('618512b038fe469ea76fbe96c02d15ef','0a4924f6632d45fa995bce0378e07a94',1941,'伪浙江省保安司令','浙江杭州人，任伪浙江省保安司令，率伪军参与“清乡”和扫荡，杀害抗日军民，战后被处决。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('311b902d2db7439487c8a1a246397b94','2da345b6c2e840b18cda3eba84087f6b',1940,'伪浙江省财政厅长','浙江吴兴人，任伪浙江省财政厅长，为日伪搜刮民财，征收苛捐杂税，战后被逮捕。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e1849e98e3a84b9e9670d8258343ad04','993e4eff978c4539b275a1e53335a341',1937,'伪浙江省政府参议、日伪杭州维持会顾问（非正式）','上海青帮头目，与杜月笙、黄金荣齐名。抗战初期投靠日本，曾参与策划在浙江杭州等地建立伪政权，为日军提供情报和镇压抗日力量。1940年被暗杀。其活动范围主要在沪杭一带。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('93240529e1d64e169fd2644483bccdf3','f50cf011f8f842fc8d69caa402ffbf67',1938,'伪中华民国维新政府内政部长、伪浙江省长（未实际到任）','原国民党政客，投日后任伪维新政府内政部长，后任伪浙江省长（但实际控制力弱）。在杭州地区推行日伪统治，协助日军清乡，迫害抗日志士。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d6760b3b00f746fda663e30a7a5fa03e','9910c48b9b394ffa8c73439ed0a473b0',1939,'伪浙江省保安司令部顾问、日伪特工总部（76号）头目','原军统特务，投日后成为汪伪特工总部主任，在杭州、上城等地设立情报站，捕杀抗日地下人员，制造多起血案。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8c1339d40ea34b39ba449fe62d71a624','07ff958e7f18410f864975f09234ac7e',1939,'伪浙江省警务处处长、日伪特工总部副主任','与丁默邨共同主持76号，在杭州及上城地区建立特务网络，残害抗日军民，后因内讧被日军毒杀。','特工总部主任','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8bce01600e3b4e5caa3accac02014b00','a2e4190c87b449e685d78c118a6801b5',1940,'伪行政院副院长、伪浙江省主席（名义）','汪伪政权核心人物，虽名义上兼任浙江省主席，但实际未常驻杭州，其政策影响浙江，包括上城地区，推行“和平救国”卖国路线。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ef8b697ec66145748005ac2c1bcb1c32','28c69a91441d4439abc95701e2c6787a',1940,'伪浙江省长（实际任职）','汪伪政权骨干，任伪浙江省长期间，在杭州上城等地强化日伪统治，推行保甲制度，强征粮食，镇压抗日运动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('062317ca42a542339d31ceb9aaf169cd','d823baec96e04682bca33413f02ae20d',1941,'伪浙江省长（继任）','继梅思平后任伪浙江省长，在杭州上城地区实施“清乡”政策，配合日军扫荡，迫害民众，搜刮物资。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e5b0ca080bb94e49afbfbb497ed3851a','bacadba533394b3bb79fb5b9c5b66118',1944,'伪浙江省长（末任）','汪伪末期浙江省长，在杭州上城维持日伪统治，直至日本投降。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('34627adfea824ffca6d3869474f42b69','2da345b6c2e840b18cda3eba84087f6b',1938,'伪杭州市长','投日任伪杭州市长，管辖上城等区域，推行奴化教育，协助日军维持治安，镇压抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f9273a3552fe4e73b85f489e3e9c5272','b2a7dfc99dee48b595a6e1f6839e9ab1',1941,'伪杭州市长（继任）','继任伪杭州市长，在上城地区实施日伪法令，强征劳工，迫害抗日家属。；原国民党杭州地方官员，投日后任伪杭州市长，在桐庐地区组织伪警察，镇压抗日活动。；浙江萧山人，继徐苏中后任伪杭州市长，配合日军“治安强化运动”，实施保甲制度。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b1a058e99efe4f6f9777fc9a09779a35','60fc9c47fb954919a88149139047b9e6',1943,'伪杭州市长（末任）','末任伪杭州市长，在杭州上城继续为日军服务，直至投降。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('75e3d0e1e8fa4406ad47889b7f8fe3df','3d23e3b1fb354d7eaa27ae8dd5893745',1937,'伪杭州上城区维持会会长','杭州沦陷初期，在上城地区组织维持会，为日军提供粮食、劳力和情报，协助建立伪政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('60f852be4b4a447a9b58b46965a29e59','e5c35ee788854082b8040537b53e0667',1938,'伪上城区区长','任伪上城区区长，管理户籍，推行“良民证”，配合日军清乡，抓捕抗日分子。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8b45894509c246e1b3e0b53e0f7194b5','becb9d36ae77476e9c0a04ea1d1c456b',1941,'伪上城区区长（继任）','继任伪上城区区长，强征捐税，为日军提供物资，镇压反日言论。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ab0a5c84935643608bf1417c80147779','0a4924f6632d45fa995bce0378e07a94',1938,'伪上城区警察署署长','负责上城区治安，协助日军和宪兵队搜捕抗日地下工作者，参与多起逮捕和刑讯。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d30cf12aac6b473ea90664908b6b429f','0e9bfd23f2284278b92c9b0a21a07315',1940,'伪杭州绥靖公署上城办事处主任','负责上城地区绥靖事务，组织汉奸武装，破坏抗日组织，向日军报告抗日动态。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('95cde728f5eb457ba106b6eb213fb33d','2549f4c8c6384f5ab1ee29e99eebaa0b',1938,'伪上城区商会会长','担任伪商会会长，强迫商户向日军缴纳“慰劳金”，为日伪筹集军费，打压爱国商人。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ee95063c921c465db2c3f7dddd3b9220','0d63f897c7e04f93909f33a86150e193',1938,'伪浙江省教育厅长（影响上城学校）','推行奴化教育，在上城各中小学强制教授日语，篡改历史教材，灌输“中日亲善”思想。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('73ed8d34696042e19955ef1da7653a06','dc74a97606f54135832092c2699ef618',1940,'伪浙江省宣传处长（上城活动）','负责日伪宣传，在上城地区张贴标语、发行汉奸报纸，美化侵略，污蔑抗日力量。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('af42e93ad1a8416485016eeb850cc8d3','993e4eff978c4539b275a1e53335a341',1937,'伪浙江省政府顾问、日伪特务','浙江慈溪人，青帮头目，抗战初期投敌，在杭州、上海等地为日军搜集情报，协助日伪镇压抗日力量，1940年被暗杀。；浙江慈溪人，上海青帮头目，抗战爆发后投靠日本，在杭州、滨江一带协助日军建立伪政权，贩卖鸦片、强征物资，1940年被军统刺杀。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d8655ea02bb048988bef66b99ff18fe1','f50cf011f8f842fc8d69caa402ffbf67',1938,'伪中华民国维新政府内政部长、伪浙江省长','福建长汀人，曾任伪维新政府内政部长，后任伪浙江省长，在杭州推行奴化教育，强征物资，配合日军清乡。；福建长汀人，但长期在浙江活动，任伪浙江省长期间推行奴化教育，强征民夫，协助日军清乡。；福建长汀人，但长期在浙江任职，投日后任伪维新政府内政部长，后调任伪浙江省长，在杭州推行奴化教育，镇压抗日力量，强征粮食。；原国民党官员，投日后任伪浙江省长，在杭州推行保甲制度，强征壮丁，协助日军清乡，迫害抗日军民。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b24797a5aed54c7d844dcb464c8af318','67395e03d811442fa215f96687efac6a',1938,'伪浙江省长、伪杭州市长','安徽盱眙人，曾任伪浙江省长兼伪杭州市长，在杭州实施保甲制度，强征粮食，镇压抗日民众。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5aec057052aa43528457a373bb3336ec','28c69a91441d4439abc95701e2c6787a',1940,'伪浙江省长、伪内政部长','浙江永嘉人，汪伪政权核心成员，曾任伪浙江省长，在杭州推行“清乡”运动，残害抗日军民。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b6976fa02a4c4e0fa0c730f14d7a42ac','bacadba533394b3bb79fb5b9c5b66118',1943,'伪浙江省保安司令、伪杭州市长','浙江杭州人，曾任伪浙江省保安司令，后任伪杭州市长，在临安等地组织伪军清剿抗日游击队。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('11aa8a345b0d43e382ddb9abc740bfa3','9910c48b9b394ffa8c73439ed0a473b0',1940,'伪浙江省党部主任委员、伪特工总部主任','湖南常德人，汪伪特工头目，曾任伪浙江省党部主任委员，在杭州、临安地区设立特务机构，逮捕杀害抗日志士。；湖南常德人，但曾在杭州、滨江地区主持日伪特工活动，建立“76号”分支机构，捕杀抗日志士，破坏地下组织。；原军统特务，投日后在杭州建立伪特工组织，大肆搜捕抗日志士，制造多起血腥惨案。','特工总部主任','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e411677d8dbd43999951e726ae445a4f','0d2d2045fc1d498dab9499e43abcb3de',1940,'伪浙江省警务处长、伪杭州市警察局长','湖南湘乡人，曾任伪浙江省警务处长，在杭州、临安等地建立伪警察体系，协助日军搜捕抗日分子，实施“连坐”政策。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f71786c0b9f842b6a2f557b91954df50','ed0d68ce0e0f4e40ba88774709d7fea6',1942,'伪浙江省保安司令部参谋长','浙江杭州人，曾任伪浙江省保安司令部参谋长，在临安、余杭等地指挥伪军“扫荡”，烧毁村庄，屠杀抗日群众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cb821ec50acb4637990ead97753b6141','c6a682cb9d834e4a910285cc9abb8db2',1937,'伪杭州市维持会会长、伪杭州绥靖公署主任','浙江杭州人，杭州沦陷后率先投敌，任伪杭州市维持会会长，为日军提供粮食和情报，协助建立伪政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e9892f32589f4b87a529d72cc08cc311','b2a7dfc99dee48b595a6e1f6839e9ab1',1938,'伪临安县长','浙江临安人，曾任伪临安县长，在临安地区推行日伪统治，强征壮丁，搜刮民财，镇压抗日武装。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5a0ff10f54c5447f8d669d5fe1f72314','f106f5d644104d9cb98dad2b651b4426',1941,'伪临安县长','浙江绍兴人，继任伪临安县长，在临安实施“清乡”，配合日军烧毁山区抗日据点，杀害多名抗日游击队员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('36a361ee2bc94b46bb8f8865c749ca72','0a4924f6632d45fa995bce0378e07a94',1940,'伪临安县保安大队长','浙江临安人，任伪临安县保安大队长，多次率伪军袭击天目山一带的抗日游击队，抓捕并杀害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3119b20aaf38453bb227fe42ba77446d','6a446dd9dfdf422d822f0bb8e74c480f',1938,'伪杭州市商会会长、日伪经济汉奸','浙江杭州人，任伪杭州市商会会长，为日军统购物资，垄断粮食、丝绸贸易，从中牟利，资助伪政权。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('29600f130cbd4de6b2a774e2a8d88c95','2da345b6c2e840b18cda3eba84087f6b',1940,'伪浙江省教育厅长','浙江杭州人，任伪浙江省教育厅长，在杭州、临安等地推行奴化教育，强迫学校使用日伪教材，宣扬“中日亲善”。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ab3ffd48f5a749c4b9c4f80ab7a8080c','62a6d6c8e7ab4bbfbc92c5b14abbde74',1940,'伪国民政府代主席、伪上海市长','广东南海人，汪伪政权二号人物，多次到杭州、临安“视察”，推动日伪“治安强化”运动，间接指挥浙江汉奸活动。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5862ce2b9d164438974cbd1a8578357f','4ff53dd874e141ef96803ca1d78fd200',1938,'伪浙江省省长、伪杭州市市长','曾任北洋政府官员，抗战爆发后投敌，1938年出任伪浙江省省长兼伪杭州市市长，积极推行日伪统治，镇压抗日活动，1940年被军统刺杀身亡。；原为上海总商会会长，投敌后任伪浙江省长兼杭州市长，推行日伪统治，镇压抗日活动，1940年被军统刺杀于上海寓所。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6082f623f79d4c15b9b22746e1966749','28c69a91441d4439abc95701e2c6787a',1940,'伪浙江省省长（未到任）','汪伪政权核心成员，参与日伪谈判，1940年被任命为伪浙江省省长但未实际到任，后任伪实业部长等职，抗战胜利后被处决。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e362449c16c24607ae553af446c5f7df','67395e03d811442fa215f96687efac6a',1941,'伪浙江省省长','原国民党官员，投敌后任伪浙江省省长，期间协助日军推行“清乡”运动，搜刮民财，镇压抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f6e5e6bc6b044bf392b0acfd2028d9ed','9910c48b9b394ffa8c73439ed0a473b0',1945,'伪浙江省省长（兼任）','汪伪特工头目，曾任伪浙江省省长（短暂兼任），此前主导“76号”特工总部，杀害大量抗日志士，战后被处决。','省部级/大军区级要员','hanjian');
