INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3721f649d8874a60a09eb1a495754702','cd8e5ab701f04770ad28171753ae1ceb',1944,'伪余杭县知事（县长）','末任伪余杭县知事，在抗战末期仍坚持效忠日伪，协助日军进行最后挣扎，战后被捕。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3ffa90caed854a6399706ad91e144610','07ff958e7f18410f864975f09234ac7e',1940,'伪浙江省警务处处长（兼）','汪伪特工“76号”实际负责人，曾任伪浙江省警务处长，在浙江各地建立特务网络，残害抗日人士，后因内讧被毒杀。','基层头目','hanjian');
