INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5deace3ab1d94e458a0bb95b1ee636e5','28c69a91441d4439abc95701e2c6787a',1940,'伪浙江省长、伪行政院委员','浙江永嘉人，早年参加汪伪政权，曾任伪浙江省长，在杭州、滨江地区推行保甲制度，协助日军清乡，迫害抗日军民。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8e035ca3c3154fa2b3f41677fb142b9a','67395e03d811442fa215f96687efac6a',1943,'伪浙江省长','安徽盱眙人，但长期在浙江任职，投日后任伪浙江省长，在杭州地区实施物资统制，强征壮丁，为日军提供后勤支持。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('de0fa67042834bab8ad3ad8343021c1e','07ff958e7f18410f864975f09234ac7e',1940,'伪浙江省保安司令部顾问、日伪特工','江苏苏州人，但受汪伪指派在浙江活动，于杭州、滨江一带组建伪警察和特务网络，参与“清乡”行动，残害百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b74f8cb0022441b18b82f4f8f154c5ce','a2e4190c87b449e685d78c118a6801b5',1940,'伪行政院副院长、伪财政部长（曾兼管浙江）','湖南沅陵人，汪伪核心人物，虽未直接任浙江职务，但通过其亲信控制浙江伪政权，在杭州、滨江地区推行伪币、掠夺资源。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7a8709818246442586b5ff9c493796f5','664d3df731bb4293bee63eea6deacb2d',1944,'伪浙江省长（未到任）','浙江吴兴人，汪伪政要，曾被任命为伪浙江省长，虽未实际到任，但其在浙江的家族势力与日伪合作，在杭州、滨江地区有影响。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7951cd8d13ed4dc3872bfc9aac193eb5','62a6d6c8e7ab4bbfbc92c5b14abbde74',1944,'伪国民政府主席（曾兼浙江省主席）','广东南海人，汪伪政权第二号人物，曾短暂兼理浙江省政，其政策直接影响杭州、滨江地区，支持日军“扫荡”。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('868051d1e14e4075961aa7fdb91215d4','d1abe59a5d664bf18b442130fc0478a1',1941,'伪浙江省宣传处长','广东信宜人，汪伪宣传骨干，在杭州、滨江地区控制报纸、电台，鼓吹“大东亚共荣”，压制抗日舆论。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9b8f107d5cef46fc92b6ff93384aabb1','bb34b45b44c34a018d410cde66579fb1',1941,'伪浙江省保安司令','湖北黄陂人，投日后任伪浙江省保安司令，在杭州、滨江地区训练伪军，配合日军清剿游击队，杀害无辜群众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('969bee74976849b1ac570b7721f5ab1b','ed0d68ce0e0f4e40ba88774709d7fea6',1940,'伪浙江省警察厅长','山东人，但长期在浙江任职，投日后任伪浙江省警察厅长，在杭州、滨江地区设立关卡，搜捕抗日分子，勒索商民。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f31e201b775444468bfc11b3bff59499','3b28a0ae9ced49f4bd465270bab0c94a',1938,'伪杭州市长','浙江杭州人，原为地方士绅，日军占领杭州后出任伪市长，在滨江地区推行“良民证”，强征劳工，为日军修建军事设施。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d34c8e48095f4470ab9e593bfa4735a7','b2a7dfc99dee48b595a6e1f6839e9ab1',1941,'伪杭州市长','浙江诸暨人，投日后任伪杭州市长，在杭州、滨江地区实施粮食配给，克扣民食，协助日军掠夺丝绸、茶叶等物资。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('54a358e0480b4af982fb40e32b03b5dc','a419a0064900406f9dfcdbd36022eb7d',1937,'伪杭州维持会会长','浙江杭州人，日军占领杭州初期任维持会长，在滨江地区组织伪政权，为日军征粮派款，迫害抗日家属。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('62ab1336a62b4e4aa36fd714fcb936d0','3d23e3b1fb354d7eaa27ae8dd5893745',1938,'伪滨江地区维持会会长','浙江萧山人（今属杭州滨江），地方恶霸，投日后任滨江维持会长，霸占土地，强迫农民种植鸦片，勾结日军欺压百姓。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('965ac1ed4ac447a781231aac09bdd792','1bbeaf70b9444d13acc444d2532243a0',1940,'伪滨江区区长','浙江萧山人，投日后任伪滨江区区长，在钱塘江南岸（今滨江）推行日伪法令，强征壮丁，为日军提供情报。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('16bdc7f4566a4a7c99b95245550b8926','abc0968451c04dddb858d01f7ee396ce',1941,'伪滨江区保安团长','浙江萧山人，投日后组织伪保安团，在滨江地区协助日军“扫荡”，杀害抗日游击队员，抢劫民财。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1e5f49e6035940719008e3e89dda0d24','34c2c3a89d464117a9142c8a08110896',1940,'伪浙江省建设厅厅长（兼管杭州水利）','浙江杭州人，投日后任伪建设厅长，在滨江地区强征民夫修筑军用公路和机场，克扣工钱，导致大量劳工死亡。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4a5ebc06cfab48149bae641ef468517e','28c69a91441d4439abc95701e2c6787a',1939,'伪中华民国国民政府（汪伪）中央执行委员、实业部长','浙江永嘉人（今温州），汪伪政权核心成员，参与“日汪密约”谈判，任伪实业部长，为日本经济掠夺服务。','省部级/大军区级要员','hanjian');
