INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5c2de4d5337d4fcaa9eb2592a35f063d','3d23e3b1fb354d7eaa27ae8dd5893745',1937,'伪萧山维持会会长','浙江萧山人，日军初占萧山时组织维持会，为日军提供情报和物资。','基层维持会/地方自治头目','hanjian');
