INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2274d61fd69841258879c64a6984a356','07ff958e7f18410f864975f09234ac7e',1940,'伪江苏省长、伪特工总部副主任（活动于浙北）','汪伪76号特工头目，多次在杭州、嘉兴等地进行暗杀、绑架，破坏地下抗日组织。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('22a7abb02b6b49ac82dfc80844891c39','28c69a91441d4439abc95701e2c6787a',1940,'伪浙江省长（后任伪内政部长）','汪伪政权骨干，任伪浙江省长期间，在杭州推行“清乡”运动，屠杀抗日群众，强征粮食。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('32a707aad5744694a0b555d026d28cf9','d1abe59a5d664bf18b442130fc0478a1',1940,'伪浙江省宣传厅长（后任伪宣传部长）','负责汪伪在浙江的舆论控制，在杭州创办汉奸报刊，鼓吹“和平反共”，毒化民众思想。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2abc5da75ab844d48f0c0ed4de6489cd','664d3df731bb4293bee63eea6deacb2d',1941,'伪浙江省长（后任伪外交部长）','汪精卫妻弟，任伪浙江省长期间，在杭州推行奴化教育，协助日军掠夺西湖周边文物资源。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('55ae1fcd499b4bb48c4db5d2ade3b5fc','62a6d6c8e7ab4bbfbc92c5b14abbde74',1944,'伪国民政府代理主席（兼涉浙江）','汪伪政权后期首脑，继续维持对浙江的伪化统治，直至日本投降。','伪政权最高层/元首级','hanjian');
