INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aa610d37d13b45d3be54155fb01def89','993e4eff978c4539b275a1e53335a341',1937,'伪浙江省政府主席（未就任）','上海青帮头目，抗战初期投敌，与日伪勾结，策划组建伪浙江省政府，后遭暗杀。；上海青帮头目，抗战初期投敌，与日本特务勾结，策划成立伪浙江省政府，因未及就任即被暗杀。其势力曾渗透湖州地区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5fef8725c11c4215834e5a0129f41f34','28c69a91441d4439abc95701e2c6787a',1940,'伪浙江省政府主席','原国民党中央宣传部专员，后投靠汪伪政权，任伪浙江省主席，推行清乡政策，镇压抗日力量。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9db7a61b9c5242efa44159853b3d90a1','d823baec96e04682bca33413f02ae20d',1940,'伪浙江省政府主席','汪伪政权核心成员，任伪浙江省主席期间，强化日伪统治，配合日军扫荡，征收苛捐杂税。；浙江乐清人，抗战期间投靠汪精卫，任伪浙江省政府主席，在浙江推行伪化教育、经济统制，配合日军清乡。；汪伪浙江省政府最高头目，推行伪化统治，配合日军在浙江包括衢州地区的清乡与物资掠夺。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6ec42e2f4fb649ebbda520d081163cb3','bacadba533394b3bb79fb5b9c5b66118',1944,'伪浙江省政府主席','汪伪军事将领，任伪浙江省主席，组织伪军协助日军作战，镇压浙东抗日根据地。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2b22a4dbbe4144b3baa2759cce059468','9910c48b9b394ffa8c73439ed0a473b0',1945,'伪浙江省政府主席（未实际到任）','汪伪特工总部主任，1945年短暂被任命为伪浙江省主席，未及到任日本即投降。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('418152d228f04907961489e0f328f13e','2dba56ad791e4cca995598ee378f3aa5',1941,'伪温州区行政督察专员','投靠日伪，任伪温州区专员，协助日军维持占领区秩序，强征民夫，搜刮物资。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('44e3f56a70fe4c769cebc12177b12208','99cdac66a3934874835c28acf3b210a7',1942,'伪瑞安县知事','任伪瑞安县知事，推行日伪政令，组织维持会，协助日军清剿抗日游击队。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('654df422e1ae4a369c2669dde634d05e','50380aeea4d040e7b7134a1f53cc71e3',1941,'伪瑞安县维持会会长','日军占领瑞安初期，出任维持会长，为日军提供粮食、情报，迫害抗日群众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e55eb65c99294e0c8035e6a48020280b','0d6ac9ed03094decb2b6e405bd9c2502',1942,'伪温州绥靖军司令','组织伪绥靖军，配合日军在温州、瑞安一带扫荡，残害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('de6d7b0b1c8844f0bf012a00a5415ee5','727432a3e6e840a3834bf2f83d9141b9',1943,'伪瑞安保安大队长','任伪保安大队长，抓捕抗日志士，破坏地下党组织，罪行累累。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('33fff24a0a3b4a73919497175f0e732f','28c69a91441d4439abc95701e2c6787a',1938,'伪浙江省政府主席、汪伪政权工商部部长','浙江温州人，汪伪政权核心成员之一，参与筹建汪伪政权，曾任伪浙江省政府主席，推行日伪统治政策。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bce91d52e7c4443f8e3d32acd7500a94','993e4eff978c4539b275a1e53335a341',1937,'伪浙江省政府委员、汉奸帮会头目','浙江杭州人，上海青帮头目，抗战期间投靠日军，组织伪军，协助日军镇压抗日力量，后在浙江一带活动。；浙江慈溪人，上海青帮头目，抗战期间投靠日本，组织伪军，1940年被军统刺杀。；其帮会势力曾向贵州延伸，在贵阳、息烽一带发展成员，协助日军搜集西南情报。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5e72359a95e84c05b815e73b6153f244','07ff958e7f18410f864975f09234ac7e',1939,'伪特工总部主任、伪江苏省政府主席','浙江丽水人，汪伪政权特务头目，组建伪特工总部，镇压抗日力量，活动范围覆盖浙江部分地区。；汪伪特务头子，其特工网络延伸至湖北等地，参与搜捕抗日人员、破坏抗日组织，为日伪在华中地区统治服务。；汪伪特工头目，其特务组织在湖北武汉等地设有分支机构，镇压抗日人士，协助日军维持占领区恐怖统治。；汪伪特工头目，其特务网络延伸至湖北，在武汉设立特务机构，镇压抗日人员。；汪伪特工头目，其特务网络延伸至湖北，在黄冈等地发展情报人员，镇压抗日志士。；浙江遂昌人，汪伪特工头目，其特务组织在湖北沦陷区设有分支机构，参与镇压抗日力量。；浙江遂昌人，抗战期间投靠汪精卫伪政权，历任伪特工总部主任、伪江苏省政府主席等职，在华中地区包括湖南北部进行特务活动和伪化统治。','特工总部主任','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2ce3f22a37fe4837bccaab192d9e8117','9910c48b9b394ffa8c73439ed0a473b0',1939,'伪特工总部主任、伪社会部部长','浙江温州人，汪伪政权特务头目，参与组建伪特工总部，镇压抗日人士，活动涉及浙江。；汪伪特工头目，其特务网络覆盖湖北，参与镇压武汉地区抗日活动。；汪伪特工头目，在武汉等地建立特务组织，迫害抗日志士。；汪伪特工头目，其特务组织在湖北沦陷区活动，黄冈、团风等地有其情报网，协助日军捕杀抗日人员。；湖南常德人，汪伪特工头目，其特务网络延伸至湖北沦陷区，协助日军镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('60be1c5929374970b12ac89e93369bf5','ed0d68ce0e0f4e40ba88774709d7fea6',1940,'伪浙江省警务处处长','浙江温州人，汪伪政权警务官员，曾任伪浙江省警务处处长，协助日军维持治安，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d3c639975bb84024bdc2c8116b1e73bf','42fcec40ebf248fa9ad0d37a9a2bbfad',1941,'伪温州维持会会长','浙江温州人，抗战期间组织伪维持会，协助日军管理温州地区，推行日伪政策。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ba538753d6984040807d921d6b7f80c4','132f5d3d790f45d8a0fd662613f98328',1941,'伪瓯海县维持会会长','浙江温州瓯海人，抗战期间出任伪瓯海县维持会会长，协助日军控制当地，征集物资，镇压抗日活动。','基层维持会/地方自治头目','hanjian');
