INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b66d45222773478f8608ddcade9bfa18','c7d19dcfd9a84265b5bc492f9222e392',1940,'伪浙江省政府委员','浙江温州人，汪伪政权官员，曾任伪浙江省政府委员，参与日伪统治浙江地区。','无明确职位或一般帮凶','hanjian');
