INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dc9a0524163a4c28ae07e70ddd0bcf32','29d971c1e53e43f594e027bf1a93efd2',1941,'伪温州维持会委员（早期）','温州首次沦陷期间参加维持会，协助日军维持市区秩序，后因与日方利益冲突被撤换。','基层维持会/地方自治头目','hanjian');
