INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2c9922ef6faf4f36b71f830315d6f673','4f8793c77ca74d3dbe773329337bfbb0',1938,'伪中华民国维新政府行政院长、伪汪精卫政权监察院长','福建长乐人，北洋政客，抗战期间投敌，1938年在南京组织伪中华民国维新政府并任行政院长，后并入汪伪政权任监察院长、立法院长等职，抗战胜利后被处决。；福建长乐人，生于浙江，抗战期间组织伪维新政府，后任汪伪政权要职，1946年以汉奸罪被处决。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cbeaa9f948d7498a85e4f40a89f0b5f1','62a6d6c8e7ab4bbfbc92c5b14abbde74',1938,'伪汪精卫政权立法院长、伪上海市长、伪国民政府代主席','广东乳源人，原国民党要员，随汪精卫投敌，历任汪伪政权立法院长、上海市长、行政院长、代主席等职，是汪伪政权核心人物之一，抗战胜利后被处决。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4659300d25c6414cb2fcd7f5a0b6bd32','a2e4190c87b449e685d78c118a6801b5',1938,'伪汪精卫政权财政部长、伪上海市长','湖南沅陵人，原国民党要员，随汪精卫投敌，历任汪伪政权财政部长、警政部长、上海市长等职，掌控伪政权财政与特务系统，抗战后期与重庆方面暗中联系，胜利后被判无期徒刑。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('344f5204445e4fd1bd05a642bca2e1f8','664d3df731bb4293bee63eea6deacb2d',1938,'伪汪精卫政权外交部长、伪广东省长','浙江吴兴人，原国民党元老，随汪精卫投敌，历任汪伪政权外交部长、驻日大使、广东省长等职，抗战胜利后被处决。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4875e44e97a24fb49bccfdb93ecaa055','28c69a91441d4439abc95701e2c6787a',1938,'伪汪精卫政权工商部长、伪浙江省长','浙江永嘉人，原国民党中央委员，参与汪精卫投敌活动，历任汪伪政权工商部长、内政部长、伪浙江省长等职，在浙江协助日军推行伪化统治，抗战胜利后被处决。；浙江永嘉人，抗战期间参与汪精卫投敌活动，后任伪浙江省长，1946年以汉奸罪被处决。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('134d335ae9e34f7c8194486d60e0277e','d823baec96e04682bca33413f02ae20d',1940,'伪汪精卫政权浙江省长','浙江乐清人，学者出身，抗战期间投敌，1940年出任伪浙江省长，协助日军在浙江推行伪化统治、征粮征丁，抗战胜利后被处决。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3e635165ce394f9d9fc020dae594c8ad','bacadba533394b3bb79fb5b9c5b66118',1943,'伪汪精卫政权浙江省长、伪军将领','浙江杭州人，原国民党军官，投敌后历任汪伪政权军事要职，1943年出任伪浙江省长兼伪军第一方面军总司令，在浙江协助日军清乡、镇压抗日力量，抗战胜利后被处决。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('62aa3d50a068488c833687d3fff618ff','9910c48b9b394ffa8c73439ed0a473b0',1939,'伪汪精卫政权社会部长、伪浙江省长','湖南常德人，原国民党特务，投敌后成为汪伪特工总部负责人之一，历任汪伪政权社会部长、伪浙江省长等职，在浙江推行特务统治，抗战胜利后被处决。；湖南常德人，抗战期间任汪伪特工总部主任，后任伪浙江省长，1947年以汉奸罪被处决。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('eec599a0009042819ab2f687869cbc9b','0d2d2045fc1d498dab9499e43abcb3de',1939,'伪汪精卫政权司法行政部长、伪浙江省长','湖南湘乡人，原国民党要员，随汪精卫投敌，历任汪伪政权司法行政部长、伪浙江省长等职，在浙江协助日军维持统治，抗战胜利后被判无期徒刑。；湖南湘乡人，抗战期间任汪伪政权要职，后任伪浙江省长，1945年被捕，1947年判无期徒刑。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b6f8c07e2d4b4b89a0ae3c1316ea76af','8f1dd12e548b4c4f866dd743c3377896',1937,'伪中华民国临时政府内政部长、伪汪精卫政权考试院长','安徽合肥人，北洋政客，抗战期间投敌，参与组织伪中华民国临时政府，后任汪伪政权考试院长、华北政务委员会委员长等职，抗战胜利后被处决。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('22b7f618cbce4e5ca4b29da9cabba33e','3f934b1c263b4cd78c73d9700621e7bd',1938,'伪汪精卫政权江苏省长、伪安徽省长','浙江绍兴人，原国民党军官，投敌后历任伪维新政府、汪伪政权江苏省长、安徽省长等职，在华东地区协助日军推行伪化统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('699fb616df304eaa95e403064d446abd','15dd8e7e3cd44f409d8f76177747bcf9',1940,'伪汪精卫政权浙江省政府委员、伪杭州市长','浙江绍兴人，抗战期间投敌，历任汪伪政权浙江省政府委员、伪杭州市长等职，在杭州及绍兴周边协助日军维持统治、推行伪化教育。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('edcf7a5c7e3f491dbbb520536491d23a','f0f5ad4cc2fb44e49ebff86917e2fa3a',1941,'伪绍兴县维持会会长、伪绍兴县长','浙江绍兴人，抗战期间投敌，日军占领绍兴后组织伪维持会并任会长，后任伪绍兴县长，协助日军征粮征丁、维持地方伪化统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('39eb00406e3f475fbb4eee5eea21cb86','becb9d36ae77476e9c0a04ea1d1c456b',1941,'伪汪精卫政权浙江省政府委员、伪绍兴县长','浙江绍兴人，抗战期间投敌，历任汪伪政权浙江省政府委员、伪绍兴县长等职，在绍兴地区协助日军推行保甲制度、镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8dfa6d58315647698abcf6fd827352dc','8b933aba4bdb445db49232a8d741f1f7',1940,'伪汪精卫政权中央宣传部次长、伪绍兴县长','浙江绍兴人，原报人，抗战期间投敌，历任汪伪政权中央宣传部次长、伪绍兴县长等职，在绍兴地区协助日军进行文化宣传与伪化统治。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9555514b290844feb5d603e99e5726dc','ac19ad67acd4492fb89544f33b23eea6',1942,'伪嵊县维持会会长、伪嵊县长','浙江嵊县人，抗战期间投敌，日军占领嵊县后组织伪维持会并任会长，后任伪嵊县长，协助日军征粮征丁、维持地方伪化统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('abf5598435454a3e8ba69a1debdfdef5','b071942dcf434244829f9eba3dd277bd',1942,'伪嵊县警察局长','浙江嵊县人，抗战期间投敌，出任伪嵊县警察局长，协助日军维持地方治安、搜捕抗日人员。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a37c734dbea04463b006b59ab9f8c5a4','ac82fca70fbe437790bf53d40b53be2a',1942,'伪嵊县教育科长','浙江嵊县人，抗战期间投敌，出任伪嵊县教育科长，在嵊县推行奴化教育、协助日军进行文化侵略。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('592f99c37c8b47be91223c6e4f6a711e','07ff958e7f18410f864975f09234ac7e',1939,'伪汪精卫政权特工总部主任、伪江苏省长','浙江遂昌人，原共产党叛徒，投敌后成为汪伪特工总部负责人，历任汪伪政权特工总部主任、警政部长、伪江苏省长等职，在华东地区大肆镇压抗日力量，1943年被日军毒杀。；浙江遂昌人，抗战期间组建汪伪特工总部，活动范围覆盖浙江，1943年被日军毒杀。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('935cc2a6caa144938f51d9c778a17800','95e4356f12fb4832b18ecbad49cf091a',1939,'伪汪精卫政权特工总部警卫队长','江苏南通人，上海青帮头目，投敌后任汪伪特工总部警卫队长，在上海及周边地区参与暗杀、绑架等恐怖活动，协助日军镇压抗日力量。；江苏南通人，活动于上海及浙江，抗战期间任汪伪特工总部警卫队长，参与暗杀和镇压抗日人士，1942年暴毙。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('74314eb6b5e64f8db168d7723dab254d','993e4eff978c4539b275a1e53335a341',1937,'伪浙江省政府委员、上海青帮头目','浙江慈溪人，上海青帮头目，抗战期间投敌，出任伪浙江省政府委员，协助日军在上海及浙江地区维持统治、镇压抗日活动，1940年被军统刺杀。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3e8a7c3efcdf4a36a2ad7aa06908aeac','22185172400545108441e7de275e4c4a',1937,'伪上海特别市警察局长、伪军将领','江苏南京人，青帮头目，抗战期间投敌，历任伪上海特别市警察局长、伪军将领等职，在上海及周边地区协助日军维持治安、镇压抗日力量。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e2bc575c615f413da30b1b65e875b5d9','96b96eb8f5414a1f874f70f38feb0054',1938,'伪上海特别市秘书长、伪浙江省政府委员','浙江绍兴人，抗战期间投敌，历任伪上海特别市秘书长、伪浙江省政府委员等职，在浙江及上海地区协助日军推行伪化统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('10adfdb47a8049259d6ed11cdc4a10f4','f50cf011f8f842fc8d69caa402ffbf67',1938,'伪中华民国维新政府内政部长、伪汪精卫政权江苏省长','福建闽侯人，北洋政客，抗战期间投敌，历任伪维新政府内政部长、汪伪政权江苏省长等职，在华东地区协助日军维持统治，抗战胜利后被处决。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('802370bf871e448583111ae10e18d15a','cebb4769b324411abb6e1f5a0f26ecf6',1938,'伪汪精卫政权海军部长、伪军第一方面军总司令','江苏宜兴人，原国民党军官，投敌后历任伪维新政府绥靖部长、汪伪政权海军部长、伪军第一方面军总司令等职，在华东地区协助日军清乡、镇压抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('645a9c955b0f4fc5af3def6253833108','4c0724ba86184ad9aea99954ed4e044b',1940,'伪汪精卫政权江苏省政府委员、伪军将领','浙江绍兴人，抗战期间投敌，历任汪伪政权江苏省政府委员、伪军将领等职，在江苏及浙江北部地区协助日军维持统治、镇压抗日活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a79b1312d8524ba291ec42a4ef113ee6','1fbe09aa711a43c999e915eb28dd7a40',1939,'伪汪精卫政权江苏省政府委员、伪军将领','湖北蕲春人，原共产党叛徒，投敌后历任汪伪政权江苏省政府委员、伪军将领等职，在华东地区协助日军维持统治，同时与多方势力有复杂联系。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c6e3c0635f60485ca351090b6a9dc832','dac090c4256e4d689328f6eb861554bb',1937,'伪新昌县知事','投靠日军，出任伪新昌县知事，协助日军维持占领区秩序，推行保甲制度，强征粮税，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('88124d74c4394bc5bbbe42fab1c50a14','238d19c9eebf4d07b39cad5e8169d00f',1937,'伪新昌县维持会会长','日军占领新昌后率先组织维持会，为日军提供粮食、劳役和情报，协助建立伪政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('341a3f495c9641a188455695f76fc5c1','4b8fc3893e8f4641bbeb664a7a37ec7d',1938,'伪新昌县保安大队长','组织伪保安队，配合日军扫荡抗日武装，抓捕抗日军民，残害无辜百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('add8acdc19d546b39dbb2f75033eaa29','0d18483f1d9c43f383b79b8825cf4301',1940,'伪绍兴县知事（兼辖新昌事务）','在绍兴伪政府任职期间，多次派员到新昌催收捐税，协助日军清乡，破坏地下抗日组织。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('645b5a6fbac3488491b182e219a6138b','61827b4dc08a4663a40db3ba8c9784e5',1941,'伪新昌县警察局长','指挥伪警察侦缉抗日分子，实施“连坐”政策，多次参与围捕中共地下党员和游击队员。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('03a806a1f4e74971a99733a18d4937b7','b071942dcf434244829f9eba3dd277bd',1939,'伪新昌县商会会长','为日军筹措军需物资，垄断粮食和食盐贸易，从中牟利，并强迫商户向日军献金。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('eb63befd24144d9b94f824d647723845','573de74de34b47a19369601f907eadae',1940,'伪新昌县宣抚班长','负责日伪宣传，散布“中日亲善”言论，诱骗青年参加伪军，破坏抗日民心。','无明确职位或一般帮凶','hanjian');
