INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d02d91c5935e49aea2d5e61ad9ef0d46','59c027df20ca4f1c8803b79c8c1918cb',1940,'伪定海县警察局局长','担任伪警察局长期间，配合日军搜捕抗日分子，参与“清乡”行动，残害百姓，强征壮丁。；在定海（今舟山）执行日伪治安法令，逮捕抗日嫌疑分子，参与“清乡”行动。','市县厅局级','hanjian');
