INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d8d97a7554db4418a4bf5022312f045d','c396168cfc3b4082b4572d36b6489966',1942,'伪定海县侦缉队队长','专门为日军搜集抗日情报，带领侦缉队抓捕地下党员和抗日群众，多次参与酷刑审讯，致死多人。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9b4bace617ec41da9b553c38f5779760','67dc7178ca9a463f9e62edd774e91427',1943,'伪舟山群岛自治会副会长','在舟山群岛推行“自治”运动，实际为日军服务，组织渔民为日军提供海上运输，协助封锁抗日物资流通。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('10ecef3837074ba9b633853ffd13fbe4','b4c3d97d79804b85884cc0cada821568',1941,'伪定海县田赋征收主任','为日军强征田赋和粮食，超额摊派，导致农民破产，并将搜刮的粮食直接供应日军军需。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f1dba752126047baa21d9283b4ef1571','901d90126a2a4f918174219586945444',1942,'伪定海县水上保安队队长','控制定海港及附近水域，为日军船只护航，搜查过往商船，劫掠抗日物资，并协助日军镇压海岛渔民反抗。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c3b6492a41b04635b651f231c267073c','8e02526396f143aba9afcbc04f9247e7',1940,'汪伪政权浙江省警务处处长','投靠汪精卫政权，在浙江地区协助日伪镇压抗日活动，破坏地下组织。；投靠汪精卫政权，在浙江协助日伪镇压抗日力量，破坏地下抗日组织。；在浙江任职期间，协助日伪镇压抗日力量，破坏地下抗日组织，推行“清乡”政策。；在金华、兰溪等地协助日军清乡，镇压抗日力量，搜捕军统地下人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d09bacc39b114a4ba0cff7b276096205','d823baec96e04682bca33413f02ae20d',1940,'汪伪浙江省省长','任伪浙江省长期间，推行日伪政策，征收苛捐杂税，协助日军进行经济掠夺和“清乡”行动。；任伪浙江省长期间，推行日伪“清乡”政策，强征民力，协助日军掠夺浙江资源。；作为汪伪政权在浙江的最高行政长官，积极推行日伪统治，征收苛捐杂税，配合日军“扫荡”抗日根据地。；管辖包括金华、兰溪在内的浙江沦陷区，推行日伪政策，强征粮食和劳工。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6851420ff6b147aa8d5ff4689942d1c0','becb9d36ae77476e9c0a04ea1d1c456b',1941,'汪伪浙江省政府秘书长','协助傅式说管理伪省政，参与“清乡”计划，迫害抗日军民。；协助傅式说处理伪省府日常事务，参与策划对浙江抗日民众的镇压行动。','市县厅局级','hanjian');
