INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d12569080e4c4df48ae7a5880a4253b1','bb66d8a9a0114db3b1830e2a9bfdb253',1939,'伪琼崖临时政府委员、伪琼崖自卫军司令','海南沦陷后投敌，参与组织伪琼崖临时政府，统率伪军配合日军对琼崖抗日根据地和游击区进行扫荡、清乡，镇压抗日民众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d728971d700543929c870cf57ff3b5e4','2d4c2ede23464422bf00d0dbed2f74d6',1939,'伪琼崖临时政府主席','日军侵占海南后出任伪政权首脑，协助日军推行殖民统治，组织伪政权、伪军和维持会，参与征粮、征工及镇压抗日活动。；海南伪政权最高头目之一，依附日军，统辖伪琼崖临时政府，配合日军对海南抗日根据地和民众进行镇压、掠夺。；日军侵占海南后出任伪政权首脑，配合日军统治，推行伪化教育、征发劳工与物资。','无明确职位或一般帮凶','hanjian');
