INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0b0855c29fbc45cbb857a42a28678460','833de8b2f9f145bbbd3359473b9d72e3',1939,'伪琼崖临时政府委员、伪文昌县县长','在海南文昌等琼北地区任伪县长，组织伪维持会和伪保安队，配合日军扫荡抗日乡村，镇压民众抗日活动。；在海南充任伪职，协助日军征粮、拉夫、清乡，其伪政权体系延伸至海南南部包括崖县地区。；文昌沦陷后附逆，任伪文昌县县长，建立伪区乡政权和伪自卫队，协助日军控制文昌沿海及清澜港一带，参与封锁抗日根据地和掠夺渔盐资源。；在文昌一带组织伪政权和伪维持会，配合日军扫荡抗日游击区，征发民夫与物资。','基层头目','hanjian');
