INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a56dbd2ed51b431da463ef0f1ad4bf43','c0e70f67b3bd45e9a5f127f2ac54564c',1939,'伪琼崖临时政府宣传科科长','为日军进行宣传鼓动，散布投降言论，瓦解抗日意志，协助推行伪化政策。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6d338d36a9b1463db968a45e81906b6f','bb66d8a9a0114db3b1830e2a9bfdb253',1939,'伪琼崖临时政府委员长、伪琼崖民众自卫军司令','海南岛沦陷后投靠日军，出任伪琼崖临时政府委员长，组建伪军配合日军对琼崖抗日根据地和抗日军民进行扫荡、清剿，推行保甲连坐，协助日军征粮、征夫、掠夺资源。；海南沦陷后投敌，出任伪琼崖临时政府委员长，组建伪军配合日军对琼崖抗日根据地和海南民众进行镇压、清乡与掠夺。；海南沦陷后投敌，组织伪琼崖临时政府，配合日军清乡、征粮、拉夫，统辖伪军协助日军进攻抗日根据地。；海南岛沦陷后投敌，出任伪琼崖临时政府最高头目，组建伪军配合日军清乡、扫荡，镇压琼崖抗日力量。','机构委员长(非国家首脑)','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cf8bb09873a04c58bef8b873734d0e58','35cba66a0e9b494db37b2ebfe3e0c154',1939,'伪琼崖临时政府副委员长、伪海口市市长','海南沦陷后附逆，参与组织伪琼崖临时政府，任副委员长并兼任伪海口市市长，协助日军维持海口及琼北地区殖民统治，推行伪化教育、经济统制和物资征集。','机构委员长(非国家首脑)','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('65c1222e16a24302ae15760e5eb48bb8','914bc4f98efa4d75826a243e4ad529d4',1939,'伪琼崖临时政府委员、伪琼山县县长','在琼山地区投敌，任伪琼山县县长，组织伪维持会和伪保安队，配合日军对琼山、海口一带抗日游击区进行清乡、扫荡，强征粮食和劳工。；在琼山地区组织维持会，协助日军扫荡抗日游击队。','基层头目','hanjian');
