INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('46217adf70774c03b7580491463a5f97','ef9b7088a50046f289d4824a046ff59a',1943,'伪和平救国军第一师师长（活动于沔阳、监利一带）','率部投日，编为伪军，在沔阳、监利、潜江交界地区配合日军扫荡抗日根据地。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fe340d7f346f4a7a8c0fd0a50ab4b9e8','6224618be5604abd9e88ebd6996818f1',1940,'伪沔阳县保安大队大队长','统领伪保安大队，随日军下乡清乡，烧毁民房，捕杀抗日干部和群众。；在沔阳、洪湖交界地区组织伪保安队，配合日军清乡，捕杀抗日干部和群众，控制湖区交通线。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1e582681181c4ac8912d1cbe908eab79','8f1dd12e548b4c4f866dd743c3377896',1938,'伪湖北省政府主席、伪华北政务委员会委员长','安徽合肥人，北洋政客，抗战期间投敌，曾任伪湖北省政府主席，后任伪华北政务委员会委员长，推行日伪统治，镇压抗日活动。；作为湖北伪政权最高头目之一，推行日军殖民政策，在湖北包括孝感地区征粮征税、训练伪军，支持日军扫荡。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ff58b38b66554932bd3d3153378f4ccb','26a40096acd9428f88ebde3e69fecb20',1938,'伪湖北省政府主席、伪湖北省省长','湖北建始人，抗战期间投敌，任伪湖北省政府主席、省长，协助日军维持占领区统治，搜刮物资，镇压抗日力量。；湖北黄陂人，抗战期间投靠日军，历任伪武汉特别市参议府议长、伪湖北省政府主席、伪湖北省省长等职，协助日军推行殖民统治、掠夺物资。；抗战期间投敌，1938年后历任伪湖北省政府主席、伪湖北省省长，为日军在湖北地区推行殖民统治，参与伪政权建设与治安维持。；抗战期间附逆，历任伪湖北省政府主席、伪湖北省省长，协助日军维持湖北沦陷区统治，推行伪化政策。；北洋时期官僚，抗战期间投敌，任伪湖北省政府主席、伪湖北省省长，在武汉及湖北地区协助日军推行伪化统治。；日军占领武汉后投敌，历任伪武汉治安维持会会长、伪湖北省政府主席、伪湖北省省长，协助日军推行殖民统治。；日军占领武汉后出任伪湖北省政府主席，推行伪化统治，为日军征粮、征夫、维持治安。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e99373d174844935b564f535e3ef2090','506df7877e6b4b589f0df223e5da77c6',1942,'伪湖北省政府主席、伪湖北省省长','湖北武昌人，抗战期间投敌，继何佩瑢后任伪湖北省政府主席、省长，配合日军推行治安强化运动，镇压抗日活动。；湖北黄陂人，继何佩瑢后任伪湖北省政府主席、省长，配合日军在湖北沦陷区推行治安强化运动，镇压抗日力量。；何佩瑢死后继任伪湖北省政府主席、伪湖北省省长，继续为日军服务，在湖北地区推行伪化统治，协助日军征粮、征工、维持治安。；接替何佩瑢出任伪湖北省政府主席、伪湖北省省长，继续为日军在湖北的占领统治服务。；抗战期间投敌，继何佩瑢后任伪湖北省政府主席、伪湖北省省长，在武汉及湖北地区为日军维持伪政权。；接替何佩瑢任伪湖北省政府主席、伪湖北省省长，继续为日军在湖北的占领统治效力。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('44951cdee1cc4827b66e8882491403fd','bb34b45b44c34a018d410cde66579fb1',1939,'伪武汉绥靖公署主任、伪湖北省政府主席','湖北黄陂人，原国民党将领，投敌后任伪武汉绥靖公署主任、伪湖北省政府主席，组织伪军配合日军作战，镇压抗日武装。；原国民党将领，抗战期间投敌，先后任伪武汉绥靖公署主任、伪湖北省政府主席等职，统率伪军配合日军在湖北各地清乡、扫荡。；抗战后期任伪湖北省政府主席兼伪武汉绥靖公署主任，统辖伪军配合日军在湖北各地清乡扫荡，对鄂西北抗日活动进行镇压。；湖北黄陂人，抗战期间投靠汪伪政权，曾任伪武汉绥靖公署主任、伪湖北省政府主席，统率伪军配合日军进攻抗日根据地。；原国民党将领，投敌后任伪武汉绥靖公署主任、伪湖北省政府主席，统率伪军配合日军进攻抗日根据地，残害民众。；原国民党军官，后投敌任伪职，曾任伪武汉绥靖公署主任、伪湖北省政府主席，在湖北地区组织伪军配合日军作战。；原国民党军官，抗战期间投敌，任伪武汉绥靖公署主任、伪湖北省政府主席等职，统率伪军配合日军在湖北地区活动。；原国民党将领，后投汪伪，任伪武汉绥靖公署主任、伪湖北省政府主席，在湖北地区收编伪军、配合日军作战。；在湖北沦陷区统率伪军，参与日军对鄂南、咸宁一带的清乡与扫荡。；原国民党将领，投靠汪伪后任伪武汉绥靖公署主任、伪湖北省政府主席，在湖北地区收编伪军、配合日军进攻抗日根据地。；原国民党将领，投敌后任伪武汉绥靖公署主任、伪湖北省政府主席，统率伪军配合日军在湖北各地包括孝感、云梦地区进行治安强化运动。；原国民党将领，投敌后任伪武汉绥靖公署主任、伪湖北省政府主席，统率伪军配合日军进攻抗日根据地，抗战胜利后被处决。；原国民党军官，投敌后任伪武汉绥靖公署主任，后任伪湖北省政府主席，在湖北地区收编伪军、配合日军作战。；原国民党将领，投敌后任伪武汉绥靖公署主任，后兼伪湖北省政府主席，统辖伪军配合日军清乡扫荡，应城、孝感均在其伪军活动范围内。；原国民党军官，投敌后任伪武汉绥靖公署主任、伪湖北省政府主席，统率伪军配合日军进攻抗日根据地，抗战胜利后被处决。；原国民党军官，投敌后任伪武汉绥靖公署主任、伪湖北省政府主席，统率伪军配合日军扫荡抗日根据地，残害民众。；原国民党军官，投敌后任伪武汉绥靖公署主任、伪湖北省政府主席，统率伪军配合日军清乡、扫荡，镇压抗日力量。；湖北伪军主要头目，统辖伪军配合日军作战，在宜昌周边参与“清乡”和扫荡。；原国民党将领，投敌后任伪武汉绥靖公署主任、伪湖北省政府主席等职，在湖北地区组织伪军，配合日军清乡、扫荡。；统率伪湖北军政，指挥伪军配合日军在宜昌周边地区“清乡”，镇压抗日武装，搜刮民间物资。；原国民党将领，抗战期间投敌，历任伪武汉绥靖公署主任、伪湖北省政府主席，在湖北地区组织伪军配合日军作战。；原国民党军官，投靠汪伪后任伪武汉绥靖公署主任、伪湖北省政府主席，统率伪军配合日军在湖北各地扫荡。；原国民党将领，投敌后任伪武汉绥靖公署主任、伪湖北省政府主席，在湖北地区组织伪军配合日军作战。；原国民党将领，投敌后任伪武汉绥靖公署主任、伪湖北省政府主席等职，在湖北地区组织伪军配合日军作战，抗战胜利后被处决。；率伪军配合日军在湖北各地清乡，其势力范围涉及宜昌地区，镇压抗日武装。；原国民党军官，投敌后任伪武汉绥靖公署主任、伪湖北省政府主席，统率伪军配合日军进攻抗日根据地，在鄂中鄂西地区进行清乡。；原国民党将领，投敌后任伪武汉绥靖公署主任、伪湖北省政府主席，统率伪军配合日军进攻抗日根据地。；湖北黄陂人，原国民党将领，投敌后任伪武汉绥靖公署主任、伪湖北省政府主席等职，统率伪军配合日军进攻抗日根据地。；原国民党将领，投敌后任伪武汉绥靖公署主任、伪湖北省政府主席，组建伪军配合日军进攻抗日根据地，搜刮民财。；原国民党军官，投敌后任伪武汉绥靖公署主任、伪湖北省政府主席，率伪军配合日军进攻抗日根据地，在武汉湖北地区罪行显著。；抗战期间投敌，曾任伪武汉绥靖公署主任、伪湖北省政府主席等职，在武汉及湖北地区统率伪军，配合日军进攻抗日根据地，镇压抗日力量。；原国民党将领，抗战期间投敌，任伪武汉绥靖公署主任、伪湖北省政府主席等职，在武汉地区组织伪军，配合日军进攻抗日根据地。；原国民党将领，投敌后任伪武汉绥靖公署主任、伪湖北省政府主席，统率伪军配合日军进攻抗日根据地，残害百姓。；原国民党将领，抗战期间投敌，任伪武汉绥靖公署主任、伪湖北省政府主席等职，在武汉及湖北地区组织伪军，配合日军扫荡抗日武装。；原国民党将领，投敌后任伪武汉绥靖公署主任、伪湖北省政府主席，统率伪军配合日军进攻抗日根据地，在湖北武汉地区推行伪政。；原国民党军官，投敌后任伪武汉绥靖公署主任，后任伪湖北省政府主席，统率伪军配合日军进攻抗日根据地，镇压民众。；原国民党将领，投敌后任伪武汉绥靖公署主任、伪湖北省政府主席等职，在武汉及湖北地区组织伪军，配合日军清乡扫荡，抗战胜利后被处决。；原国民党将领，投敌后任伪武汉绥靖公署主任、伪湖北省政府主席，在武汉及湖北地区组织伪军，配合日军清乡、扫荡，镇压抗日力量。；原国民党军官，投敌后任伪武汉绥靖公署主任、伪湖北省政府主席等职，在武汉及湖北地区组织伪军配合日军作战，1946年被处决。；抗战期间投敌，曾任伪武汉绥靖公署主任、伪湖北省政府主席等职，组织伪军配合日军行动。；原国民党军官，抗战期间投敌，任伪武汉绥靖公署主任、伪湖北省政府主席，在武汉地区组织伪军，配合日军进攻抗日根据地。；原国民党将领，投敌后任伪武汉绥靖公署主任，后任伪湖北省政府主席，在湖北地区组织伪军，配合日军进攻抗日根据地，罪行累累。；原国民党将领，1939年投敌，历任伪武汉绥靖公署主任、伪湖北省政府主席等职，在湖北收编伪军、配合日军作战，1946年被处决。；汪伪军事与政权要员，曾任伪武汉绥靖公署主任，其伪军活动范围包括鄂中荆州、沙市一带，配合日军扫荡。；抗战后期任伪湖北省政府主席兼伪武汉绥靖公署主任，指挥伪军配合日军在湖北各地清乡，荆州、石首一带伪军多受其节制。；原国民党将领，抗战期间投降日军，历任伪武汉绥靖公署主任、伪湖北省政府主席，在湖北组织伪军配合日军作战。；统辖湖北伪军，配合日军对荆门等地区进行清乡扫荡。；统辖湖北伪军，配合日军对荆门、沙洋等地区进行扫荡，镇压抗日武装。；原国民党将领，投敌后任伪武汉绥靖公署主任、伪湖北省政府主席等职，在湖北地区组织伪军，配合日军清乡扫荡。；原国民党将领，投敌后任伪武汉绥靖公署主任、伪湖北省政府主席等职，在湖北组织伪军配合日军作战，1946年被处决。；原国民党将领，抗战期间投敌，任伪武汉绥靖公署主任、伪湖北省政府主席，统率伪军配合日军进攻抗日根据地，镇压民众抗日活动。；原国民党将领，抗战期间投敌，历任伪武汉绥靖公署主任、伪湖北省政府主席等职，在湖北地区组织伪军配合日军作战，抗战胜利后被处决。；湖北伪军与伪政权头目，统辖伪军配合日军在湖北包括襄阳一带进行扫荡与治安作战。；在湖北任伪职期间，统率伪军配合日军作战，对襄阳、老河口等地的抗日力量进行镇压与扫荡。；原国民党将领，投敌后任伪武汉绥靖公署主任、伪湖北省政府主席，率伪军配合日军进攻抗日根据地，抗战胜利后被处决。；统率伪军配合日军在鄂东包括鄂城地区进行扫荡，镇压抗日武装。；在湖北充任伪军政要职，统率伪军配合日军作战，其势力范围覆盖鄂北随县、应山一带。；在湖北组织伪军配合日军作战，控制鄂北部分县区，随州地区伪军和伪警察系统与其有隶属或协作关系。；抗战期间投靠汪伪政权，曾任伪武汉绥靖公署主任、伪湖北省政府主席等职，统率伪军配合日军在湖北地区活动。；湖北黄陂人，抗战期间投敌，曾任伪武汉绥靖公署主任、伪湖北省政府主席，统率伪军配合日军在湖北包括黄石一带进行清乡扫荡。；投靠汪伪政权，在湖北地区任伪军要职，统率伪军配合日军进攻抗日根据地，镇压抗日力量。；湖北黄陂人，抗战期间投靠汪伪政权，曾任伪武汉绥靖公署主任、伪湖北省政府主席，在湖北地区组织伪军，协助日军镇压抗日力量，1946年被处决。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7da5e224fb4d495c9f2346ef50d2c1c5','d39512eb28bb4bcf9149d4f6f339fd91',1938,'伪武汉特别市市长、伪湖北省政府委员','湖北阳新人，抗战期间投敌，任伪武汉特别市市长，协助日军管理武汉，推行伪化教育，搜刮民财。；抗战期间投靠日军，参与伪武汉特别市和伪湖北省政权，任伪市长、伪省政府委员等职。；在武汉附逆，任伪市长，协助日军管理武汉及周边地区，推行奴化教育。；湖北阳新人，抗战期间投敌，任伪武汉特别市市长等职，协助日军维持武汉地区殖民秩序。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1392062f92b3437cbf07fac7a9ca7074','4cc5391bc78947fa9bf1a4b59e0f5371',1937,'伪武汉特别市市长、伪天津特别市市长','河北南皮人，张之洞之子，抗战期间投敌，曾任伪武汉特别市市长，后任伪天津特别市市长，协助日军统治。；张之洞之子，抗战期间投靠日军，曾任伪武汉特别市市长，后调任伪天津特别市市长，参与汪伪政权活动。；张之洞之子，投敌后曾任伪武汉特别市市长，在武汉及湖北地区推行伪政，后调任伪天津特别市市长。；张之洞之子，抗战期间附逆，曾任伪武汉特别市市长，后调任伪天津特别市市长，参与日伪政权。；张之洞之子，投敌后任伪武汉特别市市长，在武汉地区推行伪化统治，后调任伪天津特别市市长。；张之洞之子，投敌后曾任伪武汉特别市市长，在武汉地区推行伪化教育、经济统制，后调任伪天津特别市市长。；张之洞之子，抗战期间投敌，曾任伪武汉特别市市长，后调任伪天津特别市市长，在湖北期间配合日军统治。；河北南皮人，曾任伪武汉特别市市长，在湖北黄冈周边地区协助日军实施经济统制，搜刮民财。；河北南皮人，曾任伪武汉特别市市长，在湖北武汉地区协助日军统治，后调任伪天津特别市市长。；河北南皮人，张之洞之子，抗战期间投靠汪伪，曾任伪武汉特别市市长，在武汉地区推行伪政，为日军侵略服务。；河北南皮人，张之洞之子，抗战期间投敌，曾任伪武汉特别市市长，在武汉地区配合日军统治，后调任伪天津特别市市长。；张之洞之子，抗战期间投靠汪伪，曾任伪武汉特别市市长，在武汉地区推行伪政，后调任伪天津特别市市长。；河北南皮人，张之洞之子，抗战期间投靠汪伪，任伪武汉特别市市长，在武汉地区推行伪化统治，后调任伪天津特别市市长。；河北南皮人，张之洞之子，1939年投敌，任伪武汉特别市市长，在武汉地区协助日军统治，后调任伪天津特别市市长。；河北南皮人，张之洞之子，抗战期间任伪武汉特别市市长，后调任伪天津特别市市长，在武汉期间协助日军统治。；曾任伪武汉特别市市长，参与湖北沦陷区伪政权建设，后调任伪天津市市长。；华北、华中伪政权要员，其伪政权体系与陕西渭南地区伪组织有行政关联。；投靠日本，在华中、华北伪政权任职，参与经济掠夺与治安强化运动，其伪政权网络涉及陕西周边。；在日占区担任伪职，推行奴化教育，镇压抗日活动。；张之洞之子，投敌后历任伪武汉特别市市长、伪天津特别市市长等职，在华北华中沦陷区推行伪化统治。；投靠日本，在伪政权中任职，配合日军在华北及华中地区的殖民统治。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7b06680f7bcf47bbbfb3b4aa5cf99b6b','10f9a2b89a8040c8b078f51b23827f6e',1938,'伪湖北省政府委员、伪汉口市市长','湖北人，抗战期间投敌，任伪湖北省政府委员、伪汉口市市长，协助日军维持汉口治安，推行伪化政策。；抗战时期投敌，在伪湖北省和伪汉口市政权中任职，协助日军控制武汉及周边地区。；抗战期间投敌，在湖北伪政权中任职，参与伪汉口市政务，协助日军管理占领区。；在湖北伪政权中任职，参与推行日军占领政策，协助经济统制与物资征调。；湖北人，抗战期间投敌，在伪湖北省及汉口市政权中任职，协助日军推行保甲、征粮等殖民政策。','市县厅局级','hanjian');
