INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1d16d7d675e04006984177036aadd719','cede6d7d979e449aa55c747a4050662a',1940,'伪郧县维持会会长','在郧县一带依附日军，组织伪维持会，为日军筹粮、派款、拉夫，并协助推行伪化统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9bbd6236bc4142d98000531958dce003','c715df1b344749bfbff3823fdb93718a',1940,'伪均县保安团头目','在均县地区纠集武装投靠日伪，配合日军“扫荡”地方抗日力量，欺压百姓。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7bda6fb8e5c54c07ad640db7110ac6e6','0ce82afb041f4eb4a6fb886726d0274f',1940,'伪竹山维持会副会长','在竹山地区参与伪维持会活动，协助日军征发物资、维持地方伪秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d9d322dc342148a49e007cb2a0fd8f5f','0c9d9be7baba497bac5b4c4c48d4839b',1940,'伪十堰地区保甲长','在十堰周边地区担任伪保甲长，为日伪政权摊派捐税、监视乡民，协助控制基层。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2ef700a323dd4a3e991b979713457350','9e6a68f3f008489ea0a4172d21edf894',1938,'伪襄阳维持会头目','在襄阳地区组织伪维持会，配合日军统治，参与征粮、拉夫和镇压抗日群众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('004fd944eca945be84be41da824abb90','e49f8a9dadbe44b5bce22cf81a128c5f',1940,'伪宜昌维持会会长','在宜昌地区投靠日军，组织伪政权，协助日军控制鄂西交通与物资。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9d612aa6ee764914b8b82b9e1dd08854','26e0d8a534384aeba8d4071069cc3f16',1939,'伪湖北保安军头目','在湖北地区收编地方武装投靠日伪，配合日军进攻抗日根据地，残害抗日军民。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b66495873d494c1e9dc8edd6b26b5d62','c9d4722bba1c4a56a5ca260b027c26db',1938,'伪应城维持会会长','在应城地区组织伪维持会，为日军掠夺石膏等资源，协助维持占领区统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8784ec2a4f4342a7b8e118ad8c8137e1','506df7877e6b4b589f0df223e5da77c6',1940,'伪湖北省政府主席','作为伪湖北省政府最高头目，在武汉及湖北沦陷区推行伪化统治，协助日军征粮、征兵、镇压抗日活动。；继任伪湖北省政府主席，继续推行亲日卖国政策，配合日军在湖北的军事行动和经济掠夺。；湖北人，抗战期间投靠汪精卫伪政权，任伪湖北省政府主席，在华中地区推行伪化统治，其活动范围涉及湖南北部。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e761e3d5cf7d45979a19fc80c95f90d9','bb34b45b44c34a018d410cde66579fb1',1939,'伪武汉绥靖公署主任','在武汉地区统率伪军，配合日军“清乡”“扫荡”，镇压湖北抗日力量。；在湖北地区组建伪军，配合日军作战，镇压抗日武装，是湖北地区重要汉奸军事头目。；在华中伪政权中任职，组织伪军配合日军，其活动对全国抗日包括陕西后方有影响。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('502f23a317144a55b133bcb37e053c09','d39512eb28bb4bcf9149d4f6f339fd91',1938,'伪汉口特别市市长','在汉口地区主持伪市政，协助日军控制城市经济、物资和人口，推行奴化教育。；抗战期间投敌，出任伪汉口特别市市长，协助日军管理武汉地区，推行伪化政策。；旧官僚，日军占领武汉后任伪汉口特别市市长，协助日军管理城市、征发劳役与物资。；日军占领武汉后出任伪汉口特别市市长，协助日军管理城市、征发劳役与物资。；抗战初期投敌，出任伪汉口特别市市长，协助日军维持武汉地区治安与物资征调。；抗战期间投敌，任伪汉口特别市市长，协助日军管理武汉地区，推行伪化教育与经济掠夺。；任伪汉口特别市市长，协助日军管理武汉地区，推行奴化教育，为日军侵略张目。；抗战期间投敌，出任伪汉口特别市市长，协助日军管理武汉地区，推行伪化教育与经济掠夺。；湖北人，伪汉口市长，活动于武汉，与湖南无直接关联。；在武汉地区组织伪政权，其活动影响湖南沦陷区，参与伪政权行政活动。；汉口伪市长，与万州有水路联系。；投靠日本，在汉口伪政权中任职，配合日军统治，对陕西有间接影响。；在汉口伪政权中任职，配合日军统治，其活动区域与陕西无直接关联。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('20353b05c23443128b4e74ef6234c27a','4cc5391bc78947fa9bf1a4b59e0f5371',1939,'伪武汉特别市市长','在武汉地区担任伪市长，配合日军统治，参与经济掠夺和伪化宣传。；在武汉地区组织伪政权，其活动影响湖南沦陷区，参与伪政权行政活动。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f27e2995b3d245bbbf74c1e1d8e22a1e','26a40096acd9428f88ebde3e69fecb20',1938,'伪湖北省政府省长','在湖北沦陷区出任伪省长，组织伪政权，协助日军维持占领秩序、掠夺资源。；湖北伪政权最高头目，在包括咸宁在内的湖北沦陷区推行伪化统治，为日军征粮、征兵。；北洋时期曾任湖北省长，抗战后投敌，1938年出任伪湖北省政府省长，协助日军维持湖北沦陷区统治，1942年被日军毒杀。；北洋旧官僚，日军占领武汉后出面组织伪政权，任伪湖北省政府省长，协助日军维持占领区秩序、征发物资。；湖北伪政权头目，推行日军殖民统治，其伪省府政令覆盖宜昌沦陷区。；抗战期间投敌，任伪湖北省政府省长，协助日军维持湖北沦陷区统治，推行伪化政策，后因与日军矛盾被毒杀。；湖北早期伪政权头目，1938年后组织伪湖北省政府，其政令影响荆州、沙市地区。；北洋时期政客，抗战期间投敌，出任伪湖北省政府省长，协助日军维持湖北沦陷区统治，后因与日军矛盾被毒杀。；作为伪湖北省最高行政长官，推行日军殖民政策，督令襄阳、谷城等沦陷区伪政权征粮征兵，镇压抗日活动。；湖北伪政权最高头目，推行日军政策，统辖包括鄂城在内的各县伪政权，征粮征丁。；湖北沦陷后出任伪湖北省长，建立全省伪政权体系，鄂城、华容等地伪组织均受其统辖，是湖北地区头号汉奸之一。；湖北伪政权最高头目，在武汉及鄂东地区推行日军殖民政策，鄂城伪政权受其统辖。；湖北黄冈人，抗战期间出任伪湖北省政府省长，参与组织伪政权，为日军在湖北的统治服务。；湖北建始人，抗战期间出任伪湖北省政府省长，为日军在湖北的占领统治服务，参与伪政权组织与治安维持。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fc5bbb2f80834bd7b2b74102b2d1ab80','442e352824804acaab2b5d5fd7dda75e',1940,'伪竹山县维持会会长','抗日战争时期在竹山地区出面组织伪维持会，协助日军与伪政权维持地方统治，搜刮民财、摊派物资，为日伪势力在鄂西北山区的渗透提供地方支持。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('65b898862a7a4f5db79f52875dfa1dd7','eeddc8748a154d9ba6c373674b6b80ef',1940,'伪郧阳县政府筹备处负责人、伪郧县县长','抗战时期在鄂西北郧阳一带依附日伪，参与筹组伪政权，任伪郧县县长，推行伪化统治，为日军征集粮秣、夫役，并配合伪军维持治安。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6cff7b55e0b74dd88aca04a60c3ffac4','e0578fe0059e4143be8dcc8797eaa3e2',1940,'伪均县维持会会长','在均县（今丹江口市一带）组织伪维持会，替日军办理地方事务，强征粮食、物资和民夫，协助日伪控制汉水沿线交通。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c808a925e32147ffae513fc80e321d28','d6dfd188b7474385b7f0cfbde3069fe0',1940,'伪房县维持会骨干、伪保长','在房县地区充当日伪基层爪牙，担任伪保长并参与维持会活动，负责摊派捐税、监视抗日群众、传递日伪政令。','基层帮凶(维持会系统)','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2b2956d6ac384f728b0eaf73e91d6998','b536c5c75b5c4be6b170520ac0052398',1940,'伪郧西县维持会会长','在郧西地区组织伪维持会，配合日伪军警活动，协助征发民夫、粮食，维持日伪在鄂陕边界一带的基层统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('909cde716a8943fbae359e6b904470e0','6b635b027b974274ba6ff34ff48b378c',1940,'伪襄郧地区保安队头目','抗战时期在襄阳、郧阳交界地区率部投靠日伪，编入伪保安队，配合日军扫荡抗日根据地，袭击地方抗日武装。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4b1d545182324c3781207041f7d33a7d','26a40096acd9428f88ebde3e69fecb20',1938,'伪湖北省政府主席','抗战期间投靠日军，出任伪湖北省政府主席，推行伪化统治，为日军在湖北占领区征粮、征夫、维持治安，是湖北地区级别最高的汉奸之一。；抗战期间投靠日军，出任伪湖北省政府主席，推行伪化统治，为日军征粮征丁，镇压湖北各地抗日力量，其伪政权体系覆盖鄂西北包括十堰、竹溪一带。；湖北沦陷后投敌，任伪湖北省长，为日军推行伪化统治，征粮征兵，镇压抗日力量。；抗战期间投敌，1938年出任伪湖北省政府主席，协助日军维持湖北沦陷区统治，其伪政权管辖范围包括孝感、云梦等县。；主持湖北伪政，协助日军维持占领区秩序，在孝感等县建立伪政权机构，镇压抗日活动。；北洋时期旧官僚，抗战爆发后投敌，1938年出任伪湖北省政府主席，在武汉及湖北各地建立伪政权，协助日军维持占领区秩序。；北洋旧官僚，日军占领武汉后出任伪湖北省政府主席，协助日军推行殖民统治、征粮征丁，其伪政权管辖范围包括孝感、应城等地。；北洋旧官僚，抗战期间出任伪湖北省政府主席，协助日军维持湖北沦陷区统治，1942年病死。；北洋时期曾任湖北省长，抗战爆发后投敌，1938年出任伪湖北省政府主席，后兼任伪湖北省保安司令，协助日军维持湖北沦陷区统治，1942年病死。；抗战初期投敌，任伪湖北省政府主席，在湖北全省推行伪化统治，其政令覆盖荆州、石首地区，为日军侵华服务。；湖北沦陷后投敌，任伪湖北省长，建立伪政权体系，为日军在湖北包括襄阳、老河口一带的统治提供行政支持。；北洋旧官僚，抗战期间投敌，1938年后出任伪湖北省政府主席，协助日军维持湖北沦陷区统治，推行伪化政策，1942年病死。；湖北伪政权早期头目，在日军支持下建立伪省政，鄂城、梁子湖地区伪组织受其节制，推行殖民统治。；湖北人，抗战期间投靠日军，任伪湖北省政府主席，在华中地区推行伪化统治。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4f07163d0e8247d58f2d9e17c84a7ed3','d39512eb28bb4bcf9149d4f6f339fd91',1938,'伪汉口特别市市长、伪湖北省政府委员','抗战时期滞留武汉并投靠日伪，参与伪政权活动，任伪汉口特别市市长等职，协助日军维持武汉及周边地区统治。；湖北阳新人，抗战期间附逆，曾任伪汉口特别市市长等职，协助日军维持武汉地区殖民秩序。；抗战期间投敌，曾任伪汉口特别市市长等职，参与湖北沦陷区伪政权事务。；湖北沦陷后附逆，曾任伪汉口特别市市长，参与伪政权统治，协助日军维持治安、征发物资。；湖北沦陷后出任伪职，参与伪汉口特别市和伪湖北省政权，协助日军维持占领区秩序、征发劳役。；抗战期间投敌，曾任伪汉口特别市市长，参与日伪在湖北的行政统治，其影响波及孝感、云梦等周边地区。；原北洋将领，抗战期间投敌，任伪汉口特别市市长等职，协助日军管理武汉及周边地区。；辛亥革命旧人，抗战期间附逆，任伪汉口特别市市长等职，参与日伪在武汉及鄂东、鄂中地区的统治。；原北洋将领，抗战期间投敌，任伪汉口特别市市长等职，协助日军管理汉口地区。；抗战期间投敌，任伪汉口特别市市长等职，协助日军管理武汉地区。；湖北伪政权要员，参与制定沦陷区经济统制政策，影响荆州等地物资征调。；抗战期间投敌，曾任伪汉口特别市市长、伪湖北省政府委员，在武汉地区协助日军维持治安、推行伪化教育。；抗战期间投敌，曾任伪汉口特别市市长、伪湖北省政府委员等职，在武汉及湖北地区为日伪政权效力。；湖北伪政权成员，参与日军占领下的行政与经济统制，其影响波及襄阳等湖北沦陷区。；辛亥革命旧人，抗战期间投敌，任伪汉口特别市市长等职，协助日军管理武汉及周边地区，参与经济掠夺。；参与湖北伪政权决策，支持日军对鄂城等地的经济掠夺与治安强化。；湖北阳新人，抗战期间投敌，任伪汉口特别市市长等职，在武汉及周边地区协助日军维持治安、征收赋税、推行奴化教育。；湖北阳新人，抗战期间投敌，任伪汉口特别市市长等职，在武汉地区为日军服务，参与伪政权统治。；湖北阳新人，抗战期间投敌，任伪汉口特别市市长等职，在武汉地区协助日军管理市政、经济，镇压抗日活动。；湖北阳新人，原国民党将领，1938年投敌，任伪汉口特别市市长，后任伪湖北省政府委员，在武汉及湖北地区协助日军推行伪化政策。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d5cf196131784357b771d8aee4443a3c','10f9a2b89a8040c8b078f51b23827f6e',1938,'伪湖北省政府委员、伪警务处处长','在伪湖北省政府中担任要职，负责伪警察系统，配合日军镇压抗日活动，搜捕抗日人员，维持日伪占领区秩序。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4cced1439bc0432e9e7439b767d61a3a','506df7877e6b4b589f0df223e5da77c6',1939,'伪湖北省政府委员、伪保安司令部司令','投靠日伪后参与湖北伪政权和伪保安部队，协助日军整编伪军、维持地方治安，配合对鄂西北等地的军事行动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('513bc2a28d1a421d93f69a70469a95b7','a79d6448e8a14a4f868ac0d2c464a559',1939,'伪和平救国军师长','抗战时期在湖北地区率部投敌，编为伪和平救国军，配合日军在鄂中、鄂西北一带进行扫荡和清乡。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7567af8000734cc785a3552e5e9f7310','e1e11268f33147caa4c7f51dbbd58046',1940,'伪鄂西保安队头目','在鄂西地区依附日伪，组织伪保安武装，协助日军控制地方，征粮派款，袭击抗日游击队。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a8ab5a1756874f1cbb438f04c836a947','a2e4190c87b449e685d78c118a6801b5',1940,'伪国民政府行政院副院长、伪财政部部长','汪伪政权核心人物之一，虽主要在南京活动，但其伪政权体系覆盖湖北，参与推行伪化政策、经济掠夺和配合日军统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('af577649ad2a4f9eb28f6661bd12cb1e','442e352824804acaab2b5d5fd7dda75e',1940,'伪竹溪县维持会会长','抗日战争时期在竹溪地区出面组织伪维持会，协助日军与伪政权维持地方统治，摊派粮款、拉夫，压迫当地民众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f1f99f8934604d95b84e4120f732598a','ea7c915b92db46bb8359f291386c25cd',NULL,'伪郧县维持会头目','在郧县一带依附日伪势力，参与组织维持会与伪基层政权，为日军搜集情报、征发民夫粮秣，压制抗日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('93b1759c78264876a4f838363daeaead','eeddc8748a154d9ba6c373674b6b80ef',1940,'伪均县维持会会长','在均县（今丹江口一带）组织伪维持会，配合日伪军维持治安，向商户和农户摊派款项，协助伪政权控制汉江水路。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2300b573ada2457e865f8f21c6ea7061','0c9d9be7baba497bac5b4c4c48d4839b',1940,'伪房县保安团头目','在房县地区率部投靠日伪，编入伪保安团，配合日军扫荡抗日根据地，捕杀抗日军民，勒索地方。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4cce02be79a849efb36a6e5c1e4cd48a','6b635b027b974274ba6ff34ff48b378c',1940,'伪十堰地区保甲长、情报员','在十堰周边乡村担任伪保甲长，为日伪军派粮派夫、传递情报，监视并举报抗日人员及家属。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9433ad6b66ed4d538e1b7c6aeae3ca33','506df7877e6b4b589f0df223e5da77c6',1940,'伪湖北省政府主席、伪武汉行营主任','继何佩瑢后任伪湖北省政府主席等职，依附汪伪与日军，在湖北推行保甲、征粮、清乡，其政令下达至鄂西北各县，包括十堰、竹溪地区。；汪伪政权在湖北的重要头目，曾任伪湖北省政府主席、伪武汉行营主任等职，配合日军清乡、扫荡，推行伪化统治。；抗战时期湖北重要汉奸，曾任伪湖北省政府主席、伪武汉行营主任等职，配合日军在湖北地区的统治与清乡活动。；汪伪政权在湖北的重要头目，继何佩瑢后任伪湖北省政府主席，并兼伪武汉行营主任，统辖伪军警，配合日军清乡、扫荡。；汪伪政权在湖北的重要头目，继何佩瑢后任伪湖北省政府主席，并任伪武汉行营主任，统辖伪军配合日军清乡、扫荡，推行保甲连坐。；汪伪政权在湖北的最高头目之一，坐镇武汉，统辖湖北伪政权，推行日军侵略政策，影响包括孝感在内的湖北各地。；继何佩瑢后任伪湖北省政府主席，并兼伪武汉行营主任，统辖湖北伪军伪警，配合日军清乡扫荡，孝感、云梦一带在其伪政权控制之下。；继续推行湖北伪化统治，在孝感地区强化保甲连坐，配合日军经济统制与军事扫荡。；继何佩瑢后任伪湖北省政府主席，兼任伪武汉行营主任，统辖湖北伪军，配合日军清乡扫荡，镇压抗日力量。；继何佩瑢后任伪湖北省政府主席，兼伪武汉行营主任，积极配合日军在湖北的统治与掠夺。；接替何佩瑢任伪湖北省政府主席，后兼伪武汉行营主任，为日军在湖北征集物资、镇压抗日力量。；原国民党军官，投敌后任伪湖北省政府主席、伪武汉行营主任，统率伪军配合日军扫荡，残害抗日军民。；伪湖北省政府主席兼伪武汉行营主任，统辖伪军配合日军清乡、扫荡，镇压湖北武汉地区抗日力量。；日本陆军士官学校毕业，投敌后任伪湖北省政府主席、伪武汉行营主任等职，配合日军清乡扫荡，镇压抗日力量。；投敌后任伪湖北省政府主席、伪武汉行营主任，配合日军清乡，镇压湖北抗日力量。；抗战期间投敌，继何佩瑢后任伪湖北省政府主席，并兼任伪武汉行营主任，在湖北武汉地区协助日军统治，抗战胜利后被处决。；继何佩瑢后任伪湖北省政府主席，并兼伪武汉行营主任，统辖湖北伪军伪警，协助日军清乡、扫荡，镇压抗日力量。；继何佩瑢后任伪湖北省长，统辖包括荆州在内的沦陷区伪政，协助日军征粮、清乡。；何佩瑢死后继任伪湖北省政府主席，兼任伪武汉行营主任，统辖湖北伪军，配合日军清乡扫荡，搜刮民财，残害抗日军民。；何佩瑢死后继任伪湖北省政府主席，后任伪武汉行营主任，统辖湖北伪军，配合日军清乡、扫荡，1945年抗战胜利后被处决。；继雷寿荣后任伪湖北省政府主席，统辖湖北伪政权，荆州、沙市在其辖区，继续推行附日政策。；继何佩瑢后任伪湖北省政府主席，统辖湖北伪政权，包括荆州、石首等地的伪县政权，积极推行日军殖民政策。；继何佩瑢后任伪湖北省政府主席，并任伪武汉行营主任，配合日军在湖北的殖民统治，1945年抗战胜利后被处决。；投敌后历任伪湖北省政府主席、伪武汉行营主任等职，配合日军在湖北的军事与政治控制，参与伪政权运作。；何佩瑢死后继任伪湖北省政府主席，并任伪武汉行营主任，继续在湖北推行日伪统治，抗战胜利后被逮捕处决。；继何佩瑢后任伪湖北省长，继续推行伪化政策，统辖包括襄阳在内的伪政权，协助日军征粮、清乡。；继何佩瑢后任伪湖北省政府主席，兼伪武汉行营主任，统辖湖北伪军，配合日军清乡、扫荡，镇压抗日力量。；湖北黄冈人，汪伪政权要员，任伪湖北省主席期间配合日军清乡，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ae5ff3ed076a4fca8842b07abd6c0c8f','10f9a2b89a8040c8b078f51b23827f6e',1938,'伪湖北省政府委员、伪民政厅长','在伪湖北省政府中负责民政与地方伪政权建设，推动各县维持会、保甲制度，协助日军控制包括十堰、竹溪在内的鄂西北基层社会。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1e6407d27606445ebccb42f2a4e74948','be1c8ea2bc994b6b97fbd3d9b2605781',1940,'伪鄂西北清乡督办系统头目','参与伪湖北省清乡事务，在鄂西北地区组织伪军警与保甲，配合日军对竹溪、竹山、房县一带进行治安强化和搜捕抗日人员。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('01780b93318c46c098810309c11439f2','26a40096acd9428f88ebde3e69fecb20',1938,'伪湖北省政府省长、伪武汉特别市市长','湖北咸宁人，抗战期间投靠日军，历任伪武汉特别市市长、伪湖北省政府省长等职，协助日军推行殖民统治、掠夺物资。；北洋时期政客，投敌后任伪湖北省省长、伪武汉特别市市长，主持伪政权日常事务，为日军征粮征税，压迫民众。；北洋时期旧官僚，武汉沦陷后率先投敌，组织伪维持会，后任伪湖北省省长、伪武汉特别市市长，为日军筹措物资、维持伪秩序。；北洋旧官僚，武汉沦陷后出面组织伪政权，任伪武汉特别市市长、伪湖北省省长，协助日军维持占领秩序，1942年病死。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('45f672b3821442ef9392b2f75681c91d','506df7877e6b4b589f0df223e5da77c6',1940,'伪湖北省政府主席、伪参谋总长','湖北人，汪伪政权高级官员，曾任伪湖北省政府主席、伪参谋总长，参与伪军整编与日军协同作战。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ca372209fe1e44af8894219df9199f1a','10f9a2b89a8040c8b078f51b23827f6e',1938,'伪湖北省政府委员、伪汉口特别市市长','湖北人，抗战期间在武汉地区附逆，历任伪湖北省政府委员、伪汉口特别市市长等职。；投敌后历任伪湖北省政府委员、伪汉口特别市市长，在湖北地区推行伪政，为日军筹粮筹款。；抗战时期在湖北沦陷区任伪职，参与伪政权维持与日军合作事务。；湖北伪政权要员，曾任伪汉口特别市市长、伪湖北省政府委员，参与日军控制下的地方行政与物资统制。；湖北伪政权要员，参与制定并推行沦陷区统制经济政策，影响咸宁等地的物资征调。；湖北伪政权要员，历任伪湖北省政府委员、伪汉口特别市市长等职，协助日军控制武汉及周边地区。；抗战期间投敌，在伪湖北省及汉口特别市任职，参与日伪政权对湖北沦陷区的控制。；湖北人，汪伪政权在湖北的重要成员，历任伪湖北省政府委员、伪汉口特别市市长，协助日军统治武汉及周边地区。；湖北人，抗战期间在湖北沦陷区任职伪政权，曾任伪汉口特别市市长，协助日军维持武汉地区治安与物资统制。；湖北人，抗战期间在湖北沦陷区任伪职，参与伪政权事务，为日军统治服务。；在湖北伪政权中任职，参与伪汉口市政管理，协助日军推行殖民统治。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('345bf404a1864e3a90a89994aa2e5bc9','00698e27bdf04b01b3df0628db6a9101',1938,'伪咸宁县维持会会长','咸宁本地人，日军侵占咸宁后出面组织维持会，为日军征粮、拉夫、维持地方殖民统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('441bba8f6d994c99a70be6ecc1829088','3f7c83ce675540628f4a1a78ee713ae5',1940,'伪咸宁县公署知事','咸宁本地人，汪伪政权时期任伪咸宁县公署知事，协助日军推行保甲制度、征收赋税。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('660c19407ecf4687b87608c3f8fa9e24','5227b796962d451987d454a35c332df8',1938,'伪蒲圻县维持会会长','蒲圻（今赤壁）人，咸宁周边地区汉奸，组织维持会为日军服务，镇压抗日群众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('af3054312ecd463ba1ac8f88538b1f52','ff163d4899c84c3bb2f4a21fd7382e5e',1938,'伪嘉鱼县维持会会长','嘉鱼人，咸宁周边地区汉奸，日军侵占嘉鱼后组织维持会，协助日军控制长江沿岸。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d1fbd510d1f54189b17906576367e1f7','8c1ab1fe92b349b09c444cbd037860bf',1938,'伪崇阳县维持会会长','崇阳人，咸宁周边地区汉奸，组织维持会为日军征粮、搜集情报。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c7f3d0a31563461e8f59c019d278079a','79b918ffe2054392899f0602ca830127',1938,'伪通山县维持会会长','通山人，咸宁周边地区汉奸，日军侵占通山后出面组织维持会，协助日军维持地方秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c1babeb50a724cf7b0d7c946cbfbabd4','7eceffac0c5a49c6b751d6cb54020b94',1938,'伪湖北省政府委员、伪武汉参议府参议','湖北人，抗战期间投靠汪伪政权，任伪湖北省政府委员等职，参与湖北沦陷区殖民统治。；湖北人，抗战期间投靠汪伪政权，任伪湖北省政府委员等职，在湖北各地包括黄石地区协助日军推行伪化政策。；投靠日伪，在湖北伪政权中担任要职，为日军统治湖北出谋划策。；湖北人，抗战期间投靠汪伪政权，任伪湖北省政府委员等职，为日伪在湖北的统治出谋划策，协助日军推行保甲制度。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('52c1ec368cdd4ab2a946418d4c46f7f4','aa0859c329b0490f884fddfd4d3bbe42',1938,'伪湖北省政府委员、伪武汉特别市参议','湖北黄冈人，抗战期间附逆，任伪湖北省政府委员等职，协助日军推行经济掠夺政策。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8ca45b4d4b4c4934a6652cfa78f410f3','26a40096acd9428f88ebde3e69fecb20',1938,'伪湖北省政府省长、伪湖北省政府主席','湖北沦陷后投敌，历任伪武汉治安维持会会长、伪湖北省政府省长、伪湖北省政府主席，协助日军推行殖民统治，搜刮物资，镇压抗日活动。；湖北汉奸政权首要人物之一，抗战期间投靠日军，历任伪武汉特别市参议府议长、伪湖北省政府省长等职，协助日军推行殖民统治，1942年病死。；抗战期间投靠日军，参与组织伪湖北省政权，任伪湖北省政府省长、主席等职，为日军在湖北的统治服务。；北洋时期政客，抗战后投敌，出任伪湖北省政府省长、主席，协助日军维持湖北沦陷区统治，1942年病死。；北洋旧官僚，抗战期间投靠日军，出任伪湖北省政府省长、主席，协助日军维持湖北沦陷区统治，1942年病死。；北洋旧官僚，日军占领武汉后出面组织伪政权，任伪湖北省政府省长、主席，协助日军维持占领秩序，推行保甲连坐，镇压抗日力量。；北洋旧官僚，抗战期间投敌，1938年后历任伪湖北省政府省长、伪湖北省政府主席，协助日军维持湖北沦陷区统治，1942年病死。；北洋时期曾任湖北省长，抗战后投敌，1938年出任伪湖北省政府省长，后任伪湖北省政府主席，协助日军统治湖北沦陷区，1942年病死。；抗战期间投敌，1938年后任伪湖北省政府省长、主席，在武汉及湖北地区为日军筹粮筹款、推行伪化统治。；北洋时期政客，抗战期间投敌，1938年后任伪湖北省政府省长、主席，在武汉及湖北地区为日军维持殖民统治，后因与日军矛盾被毒杀。；北洋旧官僚，武汉沦陷后投敌，1938年任伪湖北省政府省长，后任伪湖北省政府主席，协助日军维持占领区秩序，推行伪政。；北洋时期旧官僚，武汉沦陷后投敌，出任伪湖北省政府省长、主席，配合日军维持湖北沦陷区统治，1942年病死。；北洋时期曾任湖北省长，抗战爆发后投敌，1938年出任伪湖北省政府省长，后任伪湖北省政府主席，协助日军维持湖北沦陷区统治。；湖北建始人，抗战期间投敌，1938年后任伪湖北省政府省长、主席，在武汉及鄂东地区建立伪政权，协助日军维持占领秩序，推行奴化教育。；湖北建始人，抗战期间投靠日军，组织伪湖北省政府并任省长、主席，协助日军维持湖北沦陷区统治，推行保甲、征粮、拉夫等政策。；湖北黄冈人，抗战期间投敌，1938年出任伪湖北省政府省长，后任伪湖北省政府主席，在湖北沦陷区建立伪政权，配合日军维持占领秩序，推行奴化教育。；湖北建始人，抗战期间出任伪湖北省政府省长、主席，在武汉及湖北沦陷区建立伪政权，为日军筹措物资、推行奴化教育。；湖北建始人，抗战期间投敌，任伪湖北省政府省长、主席，在武汉及湖北各地建立伪政权，协助日军维持占领区秩序。；湖北建始人，清末举人，曾任北洋政府官员。1938年武汉沦陷后投敌，出任伪湖北省政府省长，后任伪湖北省政府主席，协助日军维持湖北沦陷区统治，1942年病死。黄冈、麻城在其伪省政权名义管辖下。；湖北黄冈人，日军侵占武汉后出面组织伪政权，任伪湖北省政府省长、主席，推行奴化教育，配合日军征粮征兵，1942年病死。；湖北建始人，抗战期间投敌，出任伪湖北省政府省长，主持伪省政，推行日军殖民统治政策，其伪政权管辖范围包括黄石地区。；湖北建始人，抗战期间投敌，历任伪湖北省政府省长、主席，配合日军在湖北各地推行伪化统治，其伪政权管辖范围覆盖黄石地区。；湖北建始人，抗战期间投敌，任伪湖北省政府省长、主席，配合日军在湖北推行伪化统治，其伪政权管辖范围包括黄石、铁山地区。；湖北建始人，抗战期间投敌，1938年后出任伪湖北省政府省长、主席，协助日军推行殖民统治，1942年病死。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('61dffe3cc3c5457eb31c1e5ef6577d66','d39512eb28bb4bcf9149d4f6f339fd91',1938,'伪武汉治安维持会会长、伪湖北省政府委员','湖北沦陷初期参与组织伪武汉治安维持会，后任伪湖北省政府委员，协助日军维持占领区秩序，推行奴化教育。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c19f9b5504064e76998f748b0a1a098f','00698e27bdf04b01b3df0628db6a9101',1938,'伪湖北省政府委员、伪武昌市政处处长','在湖北沦陷区任职伪湖北省政府委员、伪武昌市政处处长，协助日军管理武昌地区，推行保甲制度。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3a9c2d244acd4f23ac46328f3db1629c','25e09ebc59ca4a5e878d8f50c44ed822',1938,'伪咸宁县维持会会长','咸宁沦陷后出面组织伪咸宁县维持会，为日军征发民夫、粮食，维持占领区秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('122fc0f2e1714f9ca3f00861084f1c76','76f32e67558041529d15b7d23d56c415',1940,'伪咸宁县县长','任伪咸宁县县长期间，配合日军在咸宁地区推行保甲连坐，搜捕抗日人员，征敛物资。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ddda2d61a72e44fa84a50482b0584a81','925998c26ea24a6abd0194502bfbe41c',1939,'伪咸宁县警察局局长','任伪咸宁县警察局局长，率伪警察配合日军扫荡咸宁周边抗日游击区，镇压民众反抗。；抗战期间任伪咸宁县警察局局长，配合日军镇压抗日活动，维持沦陷区秩序。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e70c3ccdf6b04c0bbc7c9582942eb1db','8933b319968240c9a59232fc882f6524',1939,'伪咸安区（原咸宁县）某区维持会会长','在咸安地区组织伪维持会，为日军据点供应物资，协助日军清乡。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5aa2af5098504f5191763ee3e62a09e9','ab38f904cfb74adfb4801954ac5fcdae',1940,'伪蒲圻县县长','咸宁邻县蒲圻（今赤壁）伪县长，配合日军在鄂南地区推行伪化，与咸宁伪政权协同行动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7e836d1c3b6447cb85cedc77da45ceaf','ef9b7088a50046f289d4824a046ff59a',1940,'伪鄂南绥靖军司令','统率伪军在鄂南咸宁、蒲圻、崇阳一带配合日军扫荡，进攻抗日武装，残害百姓。；抗战期间投敌，任伪鄂南绥靖军司令，率伪军在咸宁、崇阳、蒲圻一带配合日军作战。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3f7d9fface9a4dfd9b39d86586625221','884de4b09945444ea96ef275723b973a',1940,'伪鄂南保安司令','原国民党地方武装头目，投敌后任伪鄂南保安司令，在咸宁、阳新、大冶一带为日军效力，镇压抗日力量。；抗战期间在鄂南地区投敌，任伪保安司令，活动于咸宁、崇阳、通山等地。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('16f0ec68969c49cfb626490f655c5608','f9ba16ca18af439e8c33488b0eb8844f',1941,'伪湖北省政府鄂南办事处主任','负责伪湖北省政府在鄂南地区的政务，协调咸宁、蒲圻等县伪政权，推行日军殖民政策。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bf920d54a35c44799e023cd2f26a927e','85d51bf30fdf4a55aba74c3349918f34',1938,'伪咸宁县保安大队大队长','率伪保安大队在咸宁地区配合日军守备队行动，参与清乡、扫荡，抓捕抗日人员。；在咸宁地区组织伪保安武装，配合日军清乡、扫荡抗日力量。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1184e9a0d5154c47b634a2e42dc847d5','ba51bf00958b47d78ca43788f68d0e27',1941,'伪咸宁县教育科科长','在咸宁推行奴化教育，强制学校使用伪教材，宣传“大东亚共荣圈”，毒化青少年。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5244af87746c4c1b99264be77c6e8df5','76876df87d714d80bed70eb7a1c88872',1939,'伪咸宁县商会会长','控制咸宁商会，为日军强制征购粮食、物资，协助日军经济掠夺。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2bb7cbc8ddfa40e68f0402fd0f5d521b','4cc5391bc78947fa9bf1a4b59e0f5371',1938,'伪汉口特别市市长、伪天津特别市市长','张之洞之子，抗战期间投敌，曾任伪汉口特别市市长，后调任伪天津特别市市长，属湖北沦陷区汉奸政权人物。；投靠日本，在汉口、天津伪政权中任职，参与日伪统治，对陕西有间接影响。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7be753b544d5449b980c210be7cb297e','25e09ebc59ca4a5e878d8f50c44ed822',1938,'伪湖北省政府委员、伪汉口特别市市长','抗战期间投敌，在湖北沦陷区担任伪政权职务，协助日军统治。；汪伪政权官员，曾任伪湖北省政府委员，后任伪汉口特别市市长，在武汉地区推行伪政，配合日军经济掠夺。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d787900d1c40483aacace98c007c8d5c','169c6ae4a04b45f6a124faffe90f9d82',1938,'伪湖北省政府委员、伪汉口特别市市长','抗战时期在湖北伪政权中任职，参与沦陷区行政事务。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4ae0ee3f172944ae8550be7958010298','ce28e22900da4ef0897cb5ff911eb983',1938,'伪咸宁县政府县长','抗战期间在咸宁地区任伪县长，配合日军维持地方伪政权，推行保甲与征粮等事务。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('398d2447809d4b878fd1b62437c4de52','132451acd5f4496389561a5e63d6fa25',1938,'伪嘉鱼县维持会会长','嘉鱼沦陷后组织维持会，协助日军维持地方秩序、征派物资与人员。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a782f2e3491740d1a09e21035e0d2872','ba51bf00958b47d78ca43788f68d0e27',1938,'伪嘉鱼县政府县长','抗战期间在嘉鱼任伪县长，执行日军指令，管理沦陷区基层事务。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('33213e6576824f75a6782e34694e8850','ab38f904cfb74adfb4801954ac5fcdae',1938,'伪蒲圻县维持会会长','咸宁邻近地区蒲圻沦陷后任维持会会长，协助日军征粮、派夫与维持治安。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c47621c440d54de8b5938ef757db121b','7910049c32e74b1d83dea1d8b9b8c286',1938,'伪崇阳县维持会会长','崇阳沦陷后组织维持会，为日军筹粮筹款，协助控制地方。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b6a620c537f7418aa76080fdb385188e','e669fe30128c474bbcee00597c40f204',1938,'伪咸宁地区情报员','在咸宁及嘉鱼一带为日军搜集抗日武装情报，协助破坏抗日组织。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('41c6824fc87c4f01a50c14be817b58fb','506df7877e6b4b589f0df223e5da77c6',1939,'伪湖北省政府主席、伪武汉特别市市长','抗战时期附逆，历任伪武汉特别市市长、伪湖北省政府主席等职，协助日军维持湖北沦陷区统治。；继何佩瑢后主政湖北伪政权，统辖鄂城等县伪政府，配合日军清乡与物资统制。；长期在湖北伪政权中任职，先后任伪武汉特别市市长、伪湖北省政府主席，协助日军统治湖北沦陷区。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fcfffff3bdb24f1f964ef343eea002d5','169c6ae4a04b45f6a124faffe90f9d82',1939,'伪湖北省政府委员、伪汉口市市长','抗战期间附逆，任伪汉口市市长等职，参与日伪在湖北的行政统治。；抗战后期任伪汉口市市长，配合日军维持武汉地区统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e8036c3dedd54b168262db128b1afd38','00698e27bdf04b01b3df0628db6a9101',1938,'伪湖北省政府委员、伪汉口市市长','抗战时期投靠日军，在伪汉口市和伪湖北省政权中任职。；汪伪政权在湖北的官员，曾任伪汉口市市长，协助日军推行经济掠夺和治安强化。','市县厅局级','hanjian');
