INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ad4ca5a6c98d446daa88dba06e185212','85d51bf30fdf4a55aba74c3349918f34',1939,'伪孝感县保安大队大队长','率部投敌，编为伪保安大队，配合日军扫荡孝感周边抗日根据地，捕杀抗日人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b0f2759704904edc90e2ce63723f7e11','f9ba16ca18af439e8c33488b0eb8844f',1939,'伪汉阳县县长','在汉阳地区附逆，任伪县长，协助日军控制汉阳及周边地区，推行奴化教育，搜刮民财。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0ba41eb4438943849979e3ea74d1e2c1','76aa02100fe042b1aa83824f9b07038a',1938,'伪黄陂县维持会会长','黄陂沦陷后组织维持会，为日军带路、征夫、筹粮，协助日军建立伪政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('49c39f9791984c3bb9fec36a9b94a78d','13b409fcff2449c3bd42692da36e6178',1940,'伪黄卫军总司令、伪军将领','原国民党军官，被俘后投敌，在湖北地区组建伪黄卫军，配合日军进攻抗日根据地，后任伪军要职。；湖北黄冈人，原国民党军官，被俘后投敌，组建伪黄卫军，在湖北黄冈、红安一带配合日军扫荡抗日根据地，残害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('194fcb9b63674732a9aa5f9fb162498e','5539c9c4c2584c629bff64df432ca767',1940,'伪黄卫军副司令、伪军师长','与熊剑东一同投敌，在湖北孝感、黄陂一带活动，率伪军配合日军扫荡，残害抗日军民。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6a77888f410c4c2882b31451b6bb824a','ef9b7088a50046f289d4824a046ff59a',1941,'伪军师长、伪和平救国军将领','在湖北地区投敌，收编游杂武装组成伪军，盘踞孝感、应城、安陆一带，为日军效力。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('99a9252da6ba4fed8baf481e31888070','a79d6448e8a14a4f868ac0d2c464a559',1939,'伪和平救国军军长','在湖北沔阳、汉阳、孝感一带活动，率伪军配合日军作战，控制湖区，鱼肉百姓。；在湖北沔阳、汉川、孝感一带活动，率伪军配合日军清乡，其势力范围接近云梦地区。；在湖北沔阳、汉川、孝感一带收编土匪武装，组成伪军配合日军作战。；在鄂中汉阳、汉川、沔阳一带组建伪军，与应城、孝感日伪势力互通声气，配合日军清乡。；在湖北武汉地区组织伪军，任伪和平救国军军长，配合日军进攻抗日根据地。；在湖北武汉地区组织伪和平救国军，任军长，配合日军扫荡抗日根据地，后反正。；在湖北沔阳、汉阳一带组织伪军，配合日军进攻抗日根据地，活动范围接近武汉及蔡甸地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('130b00e428814a618325216238046cfe','6224618be5604abd9e88ebd6996818f1',1939,'伪安陆县县长','任伪安陆县县长期间，为日军征粮征税，组织伪保安队，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7ef1e0418c084a2db285ba8a9accac57','ae8da03748604bd79c91e296c24b8341',1938,'伪云梦县维持会会长','云梦沦陷后出面维持，为日军筹办物资，协助建立伪区乡政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2033ea9e5cfb4ae0b50778896b33a67c','bb34b45b44c34a018d410cde66579fb1',1942,'伪湖北省政府主席、伪武汉绥靖公署主任','投靠汪伪，任伪湖北省长，协助日军统治湖北，指挥伪军配合日军扫荡，包括孝感地区。','基层头目','hanjian');
