INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('76ae752b64e94f9780c288043e772bfb','00698e27bdf04b01b3df0628db6a9101',1940,'伪孝感县警察局局长','任伪警察局长，配合日军搜捕抗日人员，维持占领区治安，欺压百姓。','市县厅局级','hanjian');
