INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f5bbd6da246f45b287aa64fd3da2fee6','f31ce236ed2e4cddb4e86dce99fd1f7c',1940,'伪孝感县教育科科长','在伪政权中负责教育，推行奴化教育，篡改教材，向学生灌输亲日思想。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0e3e6ab1632d498581c2f10ed2fa3f22','4cc5391bc78947fa9bf1a4b59e0f5371',1938,'伪武汉特别市市长、伪湖北省政府委员','张之洞之子，抗战期间投靠日军，历任伪武汉特别市市长、伪湖北省政府委员等职，参与日伪在湖北的殖民统治，其活动范围覆盖武汉及周边孝感、云梦等地。；张之洞幼子，抗战期间投靠日军，历任伪武汉特别市市长、伪湖北省政府委员等职，在湖北地区推行伪化统治，为日军搜刮物资、镇压抗日活动。；张之洞之子，抗战期间投靠日军，历任伪武汉特别市市长、伪湖北省政府委员等职，参与日伪在湖北的殖民统治，其活动范围覆盖武汉及周边孝感、应城地区。；张之洞之子，抗战期间投靠日军，历任伪武汉特别市市长、伪湖北省政府委员等职，参与日伪在湖北的殖民统治，为日军搜刮物资、推行奴化教育。；张之洞之子，抗战期间投靠日军，历任伪武汉特别市市长、伪湖北省政府委员等职，参与日伪在湖北的殖民统治。；抗日战争期间投靠日军，出任伪武汉特别市市长等职，参与伪政权统治，为日军在武汉地区的殖民统治服务。；河北南皮人，投靠日军，在武汉及湖北地区任伪职，参与经济掠夺与伪化宣传。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a18fb14ab89f4a16ab055780e6af730f','10f9a2b89a8040c8b078f51b23827f6e',1938,'伪孝感县维持会会长、伪孝感县县长','孝感沦陷后出面组织维持会，后任伪孝感县县长，为日军征粮派款、维持地方伪秩序，直接管辖孝感及邻近云梦地区。','基层维持会/地方自治头目','hanjian');
