INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1b53da93d7d64218b2b029d3bed75be3','5227b796962d451987d454a35c332df8',1940,'伪云梦县县长','任伪云梦县县长期间，配合日军清乡，组织伪保安队，镇压抗日活动，是云梦地区伪政权的主要头目之一。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2b9aa88c3b0a4336869e493a53d7bdb3','f1e6b8c5b8d2445f8d61ae40c1458f29',1939,'伪黄陂县县长、伪孝感专区伪职','在孝感周边地区任伪职，协助日军控制鄂东、鄂中一带，其活动范围与孝感、云梦相邻。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f11f044514b74ef5b8b70506605b9bcb','76aa02100fe042b1aa83824f9b07038a',1940,'伪应城县县长','应城与云梦相邻，陈守方任伪应城县县长，配合日军在鄂中地区征粮、清乡，与云梦伪政权有协同行动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('473d80b5a09a41988fff2467941ca617','42f00b4d06c9435c940a58eb4aeb0935',1938,'伪安陆县维持会会长、伪安陆县县长','安陆与云梦接壤，张伯常在安陆组织伪维持会并任伪县长，协助日军控制鄂中北地区，与孝感、云梦伪政权联系密切。','基层维持会/地方自治头目','hanjian');
