INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ba179166d9bb4103b56d9e5524deaa07','f9b3ac3c196843cc9b270d8b03b59b5c',1943,'伪湖北绥靖军将领','原国民党将领，后投敌任伪湖北绥靖军要职，率部在鄂中包括孝感、云梦地区配合日军作战。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3b93ada4a57847d4ac3947cefba9a41e','0487c7d40cba4ad5912d162b537971db',1941,'伪和平救国军师长','在鄂中地区率伪军活动，与孝感、云梦一带的日伪政权协同，参与对抗日根据地的扫荡。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fb66c5d1baa44527a5b18e8521fa1b95','b19edc2e16ec4c7d9462b01fbba0f27f',1943,'伪军头目（后投日）','原国民党将领，1943年被俘后投日，在湖北沔阳、汉川、孝感一带组织伪军，其活动区域与云梦相邻。；原国民党军将领，1943年被俘后投靠日军，在湖北、湖南交界地区组织伪军，其活动范围接近常德，配合日军维持占领区秩序。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3616aa20f8434bdc8ca2627ae1781a81','ac3cec78309747798319be6a2911b2f2',1938,'伪湖北省政府委员、伪民政厅厅长','在伪湖北省政府中任职，参与制定沦陷区民政政策，其管辖范围包括孝感、云梦等县。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('10acc3c6e1004d4c806e39b73979d634','1e612d1fafdd45dea5d096dd65a1520d',1938,'伪湖北省政府委员、伪财政厅厅长','任伪湖北省财政厅厅长，为日伪在湖北包括孝感、云梦地区征敛粮款，支持日军侵略。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0f7f5660522649db9f3b7789e821f460','c3c938ec40c34bbd9910f0f11075257e',1940,'伪孝感县教育科科长','在孝感推行奴化教育，编写亲日教材，培训伪教职员，其教育附逆活动影响云梦等周边县。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f6bc940690e24b759b0653d2bb980920','4cc5391bc78947fa9bf1a4b59e0f5371',1938,'伪武汉特别市市长、伪湖北省政府主席','张之洞之子，抗战期间投敌，历任伪武汉特别市市长、伪湖北省政府主席等职，在湖北推行日伪统治，为日军搜刮物资、镇压抗日活动。；张之洞幼子，抗战期间投敌，历任伪武汉特别市市长、伪湖北省政府主席等职，在湖北推行伪化统治，为日军搜刮物资、征发劳工。；张之洞之子，抗战期间投靠日军，历任伪武汉特别市市长、伪湖北省政府主席等职，在湖北推行伪化统治，为日军搜刮物资、镇压抗日活动。；张之洞之子，抗战期间投敌，历任伪武汉特别市市长、伪湖北省政府主席等职，在湖北推行日伪统治，为日军搜刮物资、镇压抗日力量。；张之洞幼子，抗战期间投敌，历任伪武汉特别市市长、伪湖北省政府主席等职，在湖北推行伪化统治，为日军搜刮物资、镇压抗日力量。；张之洞之子，抗战期间投靠日军，历任伪武汉特别市市长、伪湖北省政府主席等职，在湖北推行日伪统治，为日军搜刮物资、镇压抗日活动。；张之洞之子，抗战期间投靠日伪，历任伪武汉特别市市长、伪湖北省政府主席等职，在湖北地区推行日伪统治，为日军搜刮物资、镇压抗日活动。；张之洞之子，抗战期间投敌，历任伪武汉特别市市长、伪湖北省政府主席等职，在湖北沦陷区推行日伪统治，为日军搜刮物资、维持治安。；张之洞之子，抗战期间投靠日军，历任伪武汉特别市市长、伪湖北省政府主席等职，在湖北推行伪化统治，为日军搜刮物资、镇压抗日力量。；张之洞之子，抗战期间投敌，历任伪武汉特别市市长、伪湖北省政府主席等职，协助日军推行殖民统治，掠夺物资，镇压抗日活动。；张之洞之子，抗战期间投敌，历任伪武汉特别市市长、伪湖北省政府主席等职，在武汉及湖北地区推行日伪统治，协助日军征粮、征工、推行奴化教育。；张之洞之子，抗战期间投敌，历任伪武汉特别市市长、伪湖北省政府主席等职，在武汉及湖北地区推行伪政，协助日军维持殖民统治。；张之洞幼子，抗战期间投敌，1939年任伪武汉特别市市长，后任伪湖北省政府主席，推行伪化统治，为日军搜刮物资、镇压抗日活动。；张之洞之子，抗战期间投靠日军，历任伪武汉特别市市长、伪湖北省政府主席等职，协助日军推行殖民统治，掠夺物资，镇压抗日活动。；张之洞之子，抗战期间投敌，历任伪武汉特别市市长、伪湖北省政府主席等职，在武汉及湖北地区推行日伪统治，协助日军征粮、征丁、镇压抗日活动。；张之洞之子，抗战期间投靠日军，1938年武汉沦陷后出任伪武汉特别市市长，后任伪湖北省政府主席，推行伪化统治，为日军搜刮物资、镇压抗日活动。；张之洞之子，抗战期间投敌，1939年任伪武汉特别市市长，后任伪湖北省政府主席，推行伪化统治，为日军搜刮物资、镇压抗日活动。；张之洞之子，抗战期间投敌，历任伪武汉特别市市长、伪湖北省政府主席等职，在武汉及湖北地区推行日伪统治，协助日军掠夺物资、镇压抗日活动。；张之洞之子，抗战期间投靠日军，历任伪武汉特别市市长、伪湖北省政府主席等职，在武汉及湖北地区推行日伪统治，协助日军征粮、征丁、镇压抗日活动。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a62bd39b165d4fe99622705ec2dee244','506df7877e6b4b589f0df223e5da77c6',1940,'伪湖北省政府主席、伪国民政府参军长','接替何佩瑢任伪湖北省政府主席，后任伪国民政府参军长，参与汪伪政权在湖北的统治，抗战胜利后被处决。；继何佩瑢后任伪湖北省政府主席，后调任伪南京政府参军长，参与汪伪政权在湖北的军政伪化活动。；接替何佩瑢任伪湖北省政府主席，后调任伪南京政府参军长，在湖北期间配合日军征粮征丁，推行奴化教育。；接替何佩瑢任伪湖北省政府主席，后调任伪南京政府参军长，长期参与汪伪政权在湖北的统治。；原国民党将领，投敌后任伪湖北省政府主席，后任伪国民政府参军长，在湖北配合日军进行殖民统治。；原国民党将领，投敌后任伪湖北省政府主席等职，参与汪伪政权在湖北的统治，配合日军清乡与物资统制。；何佩瑢死后继任伪湖北省政府主席，后调任伪国民政府参军长，在湖北沦陷区推行伪化统治，抗战胜利后被处决。；伪湖北省政府主席，后调任伪南京政府参军长，参与汪伪政权在湖北的统治，配合日军清乡与物资统制。；投靠汪伪政权，历任伪湖北省政府主席、伪国民政府参军长等职，在湖北地区配合日军进行殖民统治。；投靠汪伪政权，曾任伪湖北省政府主席，在湖北武汉地区协助日军推行伪政，后任伪国民政府参军长。；抗战期间投敌，曾任伪湖北省政府主席，在湖北地区推行日伪政策，后任伪国民政府参军长，抗战胜利后被处决。；原国民党将领，投敌后任伪湖北省政府主席，后调任伪国民政府参军长，参与汪伪政权军政事务，在湖北地区推行伪化统治。；抗战期间投靠汪伪政权，历任伪湖北省政府主席、伪国民政府参军长等职，在湖北地区配合日军进行殖民统治。；接替何佩瑢任伪湖北省政府主席，后调任伪南京政府参军长，长期在湖北从事伪政权活动，为日军统治服务。；湖北武昌人，汪伪政权重要成员，曾任伪湖北省政府主席，配合日军在湖北的统治，后任伪参军长。；湖北鹤峰人，抗战期间投靠汪伪政权，曾任伪湖北省政府主席，在湖北境内协助日军维持占领区秩序，推行奴化教育。','市县厅局级','hanjian');
