INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4ec9c8f12a984759931abfb4f2d1477b','d00abe2d305841a9923c2b6f58f34737',1939,'伪应城县县长（活动涉及孝感南部）','在应城、孝感交界地区推行伪政，为日军掠夺石膏、食盐等物资，配合日军对孝感南部进行经济封锁。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('939134fdbb5b45e5b596e5efec7c9d26','bb34b45b44c34a018d410cde66579fb1',1940,'伪武汉行营主任、伪湖北省政府主席','在湖北包括孝感地区组织伪军，配合日军进攻抗日根据地，实施清乡与物资掠夺。；湖北黄陂人，抗战期间投敌，曾任伪武汉行营主任、伪湖北省政府主席，在湖北沦陷区推行日伪政策，其势力范围涉及黄石地区。；虽主要活动于湖北，但其伪政权势力延伸至湖南北部，与益阳、岳阳一带日伪组织有联系，参与对洞庭湖区的控制。','基层头目','hanjian');
