INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('61e647281f2a433eaa9e20b7332990ce','76aa02100fe042b1aa83824f9b07038a',1940,'伪孝感县合作社联合会理事长','控制孝感地区物资配给，为日军收购军粮、棉花等战略物资，盘剥民众。','无明确职位或一般帮凶','hanjian');
