INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a2f1064d3d59473597814ab238636a63','f31ce236ed2e4cddb4e86dce99fd1f7c',1940,'伪孝感县县长','任伪孝感县县长期间推行保甲连坐，配合日军清乡，镇压抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1236943193714a7aac133df52f336c5a','e577648a17a449d3bb660e9de7838856',1941,'伪孝感县保安团团长','率伪保安团配合日军在孝感、安陆交界地区扫荡，袭击抗日武装。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6e7bb13476bc49b0af3c14e2fc424611','26a40096acd9428f88ebde3e69fecb20',1938,'伪湖北省省长','湖北沦陷后投敌，任伪湖北省长，推行伪化统治，为日军掠夺湖北资源效力。；湖北沦陷区最高伪政权头目之一，依附日军，推行伪化统治，其势力范围覆盖宜昌等地。；湖北沦陷区最高伪政权头目，推行日军殖民政策，统辖包括宜昌在内的伪县政权，征粮征丁支持侵华战争。；湖北沦陷后投敌，任伪湖北省长，协助日军在湖北各地包括宜昌推行伪政权建设与物资征调。；湖北沦陷区最高伪政权头目，推行日军殖民政策，为荆州等地伪政权提供支持。；湖北沦陷区最高伪政权头目，推行日军殖民统治政策，其政令覆盖荆门地区。；作为伪湖北省最高行政长官，推行日军殖民政策，其政令覆盖荆门、沙洋地区，征丁征粮支持侵华战争。；湖北沦陷区伪政权首要人物，主持伪湖北省政府，推行日军殖民统治政策，为日军征粮征丁。；湖北伪政权最高头目之一，在日军扶植下成立伪省政府，推行治安强化运动，其政令覆盖襄阳、樊城等沦陷区。；湖北沦陷区最高伪政权头目，推行日军殖民政策，其势力范围覆盖襄阳地区。；湖北沦陷区最高伪政权头目，推行日军殖民政策，为日军征粮征丁，随州地区伪政权受其管辖。；湖北沦陷后出任伪湖北省长，建立伪省政权，统辖包括随县、应山在内的鄂北伪组织，为日军提供物资与情报支持。；湖北沦陷后出任伪湖北省长，建立伪省政权，配合日军统治湖北各地，包括随州地区伪政权的设立与运作。；湖北伪政权首脑，主持全省伪政，配合日军在随县等地征粮、征兵，推行保甲连坐。；在湖北、湖南地区组织伪政权，配合日军对湖南的侵略，参与伪政权行政活动。；在湖北伪政权中任职，配合日军经济掠夺，其活动与陕西南部有间接关联。；投靠日本，任伪湖北省长，配合日军在华中及华北包括陕西周边地区进行殖民统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8746746df77f431689ba166f8adfb91a','506df7877e6b4b589f0df223e5da77c6',1939,'伪湖北省省长、伪武汉特别市市长','继何佩瑢后任伪湖北省长，继续推行伪化政策，配合日军在湖北各地的占领统治。；继何佩瑢后任伪湖北省长，继续在湖北沦陷区推行奴化统治，配合日军对宜昌等地的控制与掠夺。；长期在湖北伪政权任职，配合日军统治，对宜昌等地的伪政权有统辖关系。；继何佩瑢后任伪湖北省长，积极推行“治安强化”，配合日军对鄂北、鄂中抗日根据地封锁扫荡。；湖北伪政权要员，配合日军在湖北各地包括襄阳地区推行殖民统治、经济掠夺与清乡。；继任伪湖北省长，继续推行日军殖民统治，统辖湖北各县伪政权，随州、曾都一带伪组织受其节制。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('97071129391a447886abf41381bcb343','bb34b45b44c34a018d410cde66579fb1',1939,'伪武汉特别市市长、伪湖北省政府主席','投靠汪伪政权，在湖北武汉地区任职，协助日军维持占领区秩序、搜刮物资。；在湖北沦陷区担任伪职，协助日军控制包括襄阳在内的鄂北地区，推行奴化教育，组织伪军配合日军作战。；湖北伪政权要员，参与日军统治，影响鄂城等周边地区，协助征兵征粮。；湖北地区重要伪政权头目，曾任伪武汉市长及伪湖北省主席，统辖包括鄂城在内的湖北伪政权，为日军搜刮物资、镇压抗日力量。；湖北伪政权最高头目之一，在武汉及鄂东地区推行日军政策，其伪政权体系覆盖鄂城、梁子湖一带，征粮征丁，镇压抗日。；湖北黄陂人，抗战期间投靠汪伪政权，历任伪武汉特别市市长、伪湖北省政府主席等职，协助日军推行殖民统治，在湖北地区影响较大。；湖北黄陂人，抗战期间投靠汪伪政权，历任伪武汉特别市市长、伪湖北省政府主席等职，协助日军推行殖民统治、搜刮物资、镇压抗日力量。；湖北黄陂人，抗战期间投敌，曾任伪武汉特别市市长、伪湖北省政府主席，协助日军控制武汉及鄂东地区，黄石、铁山一带受其伪政权影响。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9889981df0064912ac433ab0d082fa2d','d39512eb28bb4bcf9149d4f6f339fd91',1938,'伪武汉特别市市长','武汉沦陷后出任伪市长，为日军维持武汉及周边地区治安、征发物资。；投靠日本，任伪武汉市长，配合日军在华中及华北包括陕西周边地区进行殖民统治。','特别市市长','hanjian');
