INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('295574fab9894dd3ae2f4521625487fc','506df7877e6b4b589f0df223e5da77c6',1942,'伪湖北省政府主席、伪国民政府委员','接替何佩瑢任伪湖北省政府主席，继续为日军搜刮物资、镇压抗日力量，伪省府政令下达至孝感、应城各县。；湖北武昌人，接替何佩瑢出任伪湖北省政府主席，继续推行日伪统治，配合日军在湖北包括黄石一带的治安强化运动。；湖北鹤峰人，抗战期间投敌，继何佩瑢后任伪湖北省政府主席，继续协助日军统治湖北沦陷区，黄石、铁山在其伪政权管辖范围内。；湖北鹤峰人，接替何佩瑢任伪湖北省政府主席，积极配合日军在湖北的统治，1945年抗战胜利后被处决。','无明确职位或一般帮凶','hanjian');
