INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4933473bcb8a41d2954284984d53a493','506df7877e6b4b589f0df223e5da77c6',1939,'伪湖北省省长、伪武汉行营主任','继任伪湖北省长，继续为日军搜刮湖北资源、征发劳工，支持日军在宜昌等地的军事行动。；继任伪湖北省长，继续为日军统治湖北服务，荆门等沦陷县均受其管辖。；继任伪湖北省长，继续为日军搜刮湖北资源，荆门、沙洋一带的伪政权均受其节制。；继何佩瑢后任伪湖北省长，继续为日军搜刮物资、镇压抗日力量，影响及襄阳。；继何佩瑢后任伪湖北省长，统辖包括随县在内的湖北沦陷区伪政权，配合日军扫荡。；继任伪湖北省长，继续推行日伪统治，统辖鄂北伪政权，配合日军对随县、应山等地的控制与扫荡。；继何佩瑢后任伪湖北省长，统辖随县等鄂北伪政权，协助日军清乡、扫荡。；在湖北、湖南地区组织伪政权，配合日军对湖南的侵略，参与伪政权行政和军事活动。；在湖北建立伪政权，配合日军统治，湖北与陕西相邻，其伪政权活动对陕西南部有间接影响。','省部级/大军区级要员','hanjian');
