INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f277fd10608a4aa0bda87d40ebf2b830','506df7877e6b4b589f0df223e5da77c6',1940,'伪湖北省政府主席、伪国民政府参谋总长','抗战期间投靠汪伪政权，曾任伪湖北省政府主席、伪国民政府参谋总长等职，参与湖北伪政权建设与伪军整编。；湖北沔阳人，汪伪政权重要军事头目，曾任伪湖北省政府主席，在湖北地区整编伪军，配合日军对鄂东、黄冈等地进行扫荡和清乡。；湖北鹤峰人，汪伪政权要员，曾任伪湖北省政府主席，在湖北沦陷区推行伪政，配合日军清乡、扫荡，镇压抗日活动。；湖北黄冈人，汪精卫伪政权重要成员，曾任伪湖北省政府主席，在湖北地区协助日军实施殖民统治，参与伪军整编与治安强化运动。；湖北鹤峰人，接替何佩瑢任伪湖北省政府主席，继续在湖北沦陷区推行伪政，协助日军维持治安、征发劳役。；湖北鹤峰人，投靠汪精卫伪政权，任伪湖北省政府主席，在湖北推行伪化政策，配合日军清乡扫荡。；湖北鹤峰人，接替何佩瑢任伪湖北省政府主席，后任伪国民政府参谋总长，在湖北推行伪化政策，配合日军军事行动。；湖北鹤峰人，原国民党军官，1942年接替何佩瑢任伪湖北省政府主席，后调任伪国民政府参谋总长，参与汪伪军事指挥，协助日军在湖北的统治与清乡。黄冈、麻城属其伪省管辖。；湖北黄冈人，曾任伪湖北省政府主席，后调任伪南京政府参谋总长，参与伪军整编与对抗日根据地的扫荡。；湖北鹤峰人，原国民党将领，后投汪伪。接替何佩瑢任伪湖北省主席，继续在黄冈、黄梅等地强化伪政权，配合日军对鄂东抗日根据地进行扫荡和经济封锁。','无明确职位或一般帮凶','hanjian');
