INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5a037039150e40368e773a40deea1c86','6b635b027b974274ba6ff34ff48b378c',1942,'伪湖北省政府鄂西办事处主任','在鄂西地区代表伪湖北省政府协调各县伪政权，督导征粮、征丁，配合日军对恩施、鹤峰等地的控制。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('25b0d48a928844dead1108060096ca6d','785ebb6312f34cf6b0b8d1626f0a5b09',1941,'伪鹤峰县警察所所长','在鹤峰地区组建伪警察队伍，搜捕抗日人士，勒索商民，为日军提供情报。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ffed046eab104f4da9d71b7cd656c57e','2b9d6a009aa74b2787970a222f7b21bc',1940,'伪恩施县维持会副会长','协助伪维持会会长管理恩施城区，登记户口，发放良民证，配合日军清查抗日分子。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('81410d74046f4654b8735c6cefa25a5a','b2dfd81ed7d64390b978b5b16d6723b5',1942,'伪鹤峰县保安团团长','率伪保安团在鹤峰及周边地区清乡，烧毁抗日群众房屋，捕杀抗日干部及家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('53e3e672cc33486291f7538903e35950','5f9a622d49eb44d1b886b236ee64d59a',1941,'伪恩施县教育科科长','在恩施推行奴化教育，篡改教材，强迫学生学日语，宣传“大东亚共荣”。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('22c0b7b46ac443f8b9be8b18f9547ffc','66d368228d0d4d65b2c68d4ca496f31a',1942,'伪鹤峰县财政科科长','为伪政权搜刮税款，强征粮食，导致鹤峰地区民不聊生，饿殍遍野。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dd0fd803328d4955b319278d9b359bab','9f633fd7f93b41fea6e1702cdb729286',1940,'伪恩施县商会会长','组织商户为日军及伪政权筹集物资，垄断市场，配合经济封锁，牟取暴利。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9dfa8bb17ee84a288d0030b3e02fd510','10f9a2b89a8040c8b078f51b23827f6e',1939,'伪武汉特别市警察局局长','任伪武汉特别市警察局局长，指挥伪警察搜捕抗日人士，镇压市民反抗，维护日伪统治秩序。；任伪武汉特别市警察局局长，指挥伪警察配合日军搜捕抗日人员、镇压市民反抗，推行保甲连坐。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ff27baf5f34440c593a93442c4101a08','25e09ebc59ca4a5e878d8f50c44ed822',1938,'伪汉口市维持会会长','日军占领武汉后组织伪汉口市维持会并任会长，为日军筹粮筹款，诱降地方士绅，协助建立伪政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cfb8dfbbc4194bc3b834dc2fd8d25609','729921a05c6848389c345d2b66774b8f',1938,'伪武昌维持会会长','任伪武昌维持会会长，协助日军维持武昌地区治安，征发民夫物资，为伪政权建立做准备。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('083d49cc7c6d44d6891353665e81efdc','f24b8faec1bf46b4a03fc831ec162c84',1938,'伪汉阳县维持会会长、伪汉阳县政府县长','任伪汉阳县维持会会长及伪县长，控制汉阳地区基层政权，为日军征集粮食、劳工，镇压抗日活动。；武汉沦陷后在汉阳地区参与伪维持会并任伪汉阳县政府县长，协助日军在汉阳及周边地区推行伪化统治，征粮征工。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9d100cceec3f444ea6cfa7b00ba44823','1d49f36066704253a7e73addd64c47a4',1939,'伪武昌市政处处长','任伪武昌市政处处长，负责武昌地区市政与治安，配合日军实施保甲连坐，压制抗日宣传。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a5ac39ae89374fe6a2de5dffe529b33d','b4ce71a321bf461485e051acd7bc3651',1939,'伪汉口特别市商会会长','任伪汉口特别市商会会长，为日军统制经济服务，强制商户纳捐，协助掠夺战略物资。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5772f6070d9d4f24946aa12a24833ab2','fbf22e9b44e04c39a9b4483c290a14a4',1940,'伪湖北省政府教育厅厅长','任伪湖北省教育厅厅长，推行奴化教育，篡改教材，强制学校教授日语和亲日内容，毒害青少年。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5291277e12874435afe3bed664e40eb9','5fe428d888934144876dcaf8cef69e61',1939,'伪武汉特别市社会局局长','任伪武汉特别市社会局局长，控制社会团体，监视民众动向，协助日军征用劳工。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('deec595f0e5c444787dff68ea3cac0a0','3f3486cb92e443ef83019661f8b86e4b',1939,'伪汉口市警察局特高科科长','任伪汉口市警察局特高科科长，专门负责侦破抗日地下组织，逮捕和刑讯抗日人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a5045f247f3d4644aafde9dc5238a23c','df28afd27c224ff4a72dccb3f51bcd57',1940,'伪湖北省政府宣传处处长','任伪湖北省政府宣传处处长，主办亲日报刊和广播，散布“大东亚共荣”谬论，诋毁抗日力量。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4065524f8ced42129c6b6e1c1889582a','c3c938ec40c34bbd9910f0f11075257e',1940,'伪武汉绥靖公署参谋长','任伪武汉绥靖公署参谋长，参与制定伪军作战计划，配合日军对鄂中、鄂东抗日根据地进行扫荡。；协助叶蓬统率伪军，配合日军对湖北抗日根据地扫荡。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('eabc534f30064478a8ca14ceb8a57758','85d51bf30fdf4a55aba74c3349918f34',1938,'伪黄陂县维持会会长','任伪黄陂县维持会会长，为日军征粮派款，组织伪自卫团，协助日军清乡。；在黄陂地区参与伪维持会活动，协助日军维持地方治安、筹措物资，为日伪在武汉北部地区的统治服务。；抗战期间在黄陂地区组织维持会，协助日军维持地方秩序，为日军征粮征夫，压迫当地民众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('44ac72d58eff45d990e172572f45642b','5f9a622d49eb44d1b886b236ee64d59a',1938,'伪孝感县维持会会长','任伪孝感县维持会会长，控制孝感地区基层，为日军提供情报，抓捕抗日人员。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9593bacda3694bd0946057dd7f9ff53f','642c7074a39a480094c90581a73df0f6',1938,'伪应城县维持会会长','任伪应城县维持会会长，协助日军掠夺应城石膏、盐矿资源，压榨矿工。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e3fd0eeb08984c758540027d1d97f653','af3362fed1644e71a5919526f28e6247',1938,'伪汉川县维持会会长','任伪汉川县维持会会长，为日军征集粮食和棉花，配合日军封锁抗日根据地。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4f8e5894c9e34b6c815783c624e84787','d39512eb28bb4bcf9149d4f6f339fd91',1938,'伪武汉特别市市长、伪湖北省政府省长','辛亥旧军人，武汉沦陷后附逆，历任伪武汉特别市市长、伪湖北省省长，参与伪政权统治，协助日军镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8047d42fbb0646889f14c3d9d96ef15c','10f9a2b89a8040c8b078f51b23827f6e',1938,'伪汉口特别市市长','武汉沦陷后任伪汉口特别市市长，主持伪市政，协助日军维持占领秩序、征发物资。；抗战期间投敌，任伪汉口特别市市长，在汉口、硚口地区推行日伪政策，协助日军征收物资、管理户口。；抗战期间投敌，任伪汉口特别市市长，在武汉地区协助日军维持伪政权和殖民统治。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6da22b96f547409fbb0a409b3a45960d','169c6ae4a04b45f6a124faffe90f9d82',1939,'伪汉口特别市市长','继任伪汉口特别市市长，推行日伪政策，在汉口地区协助日军进行经济统制与治安强化。；抗战期间投敌，曾任伪汉口特别市市长，在武汉地区协助日军维持殖民统治。；投敌后任伪汉口特别市市长，在汉口地区协助日军维持统治，直至抗战胜利。；抗战期间附逆，任伪汉口特别市市长，在武汉地区为日伪政权服务。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2bb6e9f4482c4784a3a7d35b75c4eb14','ac3cec78309747798319be6a2911b2f2',1939,'伪武汉警备司令','伪武汉警备司令，指挥伪警察与伪军警备武汉市区，搜捕抗日人员，配合日军维持殖民统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c28641e2f39c4c789133009c9d0ad09d','00698e27bdf04b01b3df0628db6a9101',1938,'伪汉口商会会长、伪维持会头目','汉口商界附逆代表人物，组织伪维持会，为日军筹款筹粮，协助经济掠夺。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('15664e78531d4b07ab4626143367ec55','25e09ebc59ca4a5e878d8f50c44ed822',1938,'伪武昌维持会会长','武昌沦陷后组织伪维持会，任会长，协助日军安民、征工征粮，维持武昌地区伪秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c3646558098b41a483a29eba5a751a41','f24b8faec1bf46b4a03fc831ec162c84',1939,'伪汉阳县县长、伪保安团头目','在汉阳及武汉近郊任伪县长、伪保安团头目，配合日军清乡，镇压当地抗日活动，东西湖一带亦在其伪统治影响范围内。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2d11e8c922ee488f84c764212552814d','fdf21b4786fd4759a4fc0158fc2af447',1939,'伪黄陂县县长、伪保安大队长','在黄陂及武汉北部地区任伪职，率伪保安队配合日军扫荡，残害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7aeaa0fdbcb645dc8d6cd1be126d0da1','ef9b7088a50046f289d4824a046ff59a',1940,'伪武汉行营参谋长、伪军师长','投敌后任伪武汉行营参谋长、伪军师长，参与指挥伪军配合日军在湖北武汉地区作战。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('22623624ca6d4706beb323ae06d91fde','5539c9c4c2584c629bff64df432ca767',1940,'伪黄卫军军长、伪武汉警备副司令','伪黄卫军头目，后任伪武汉警备副司令，率部在武汉及周边地区配合日军清乡、扫荡。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c13f4a6a3e6449cdb40e725fc3629ef8','13b409fcff2449c3bd42692da36e6178',1940,'伪黄卫军军长','原军统人员，被捕后投敌，组建伪黄卫军，在武汉及湖北地区配合日军进攻抗日武装。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('04b402e30637427bacc74974ce8d4d76','ee5c41cf755c4b6b860f8ba54a0a1a81',1939,'伪武汉地区情报头目','在武汉地区为日军搜集情报，协助破获抗日组织，参与镇压地下抗日活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('777a27f444064ef9bd5058f35ed3a084','f2c99eb1b0d343818114b39936365e43',1940,'伪湖北省政府委员、伪宣传处长','在伪湖北省政府任职，主持伪宣传，推行奴化教育，为日军侵略张目。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c9044bd49cd04f00904ef80f9a7fd2e5','d3256e7274c448058c67c4d51c3fa885',1944,'伪《大楚报》社长、伪宣传部官员','在武汉主办伪《大楚报》，进行亲日宣传，为日伪统治制造舆论。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7f64ba277a594704b79ca859fe6cae96','a2e4190c87b449e685d78c118a6801b5',1940,'伪财政部部长、伪湖北省政府主席（兼）','汪伪政权核心人物，曾兼任伪湖北省政府主席，其伪政权体系覆盖湖北武汉，推行经济统制与奴化政策。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('91299718c1674de79be20e9783abdfd2','07ff958e7f18410f864975f09234ac7e',1939,'伪特工总部头目、伪湖北省特务负责人','汪伪特工头目，其特务组织在武汉设分支机构，搜捕抗日人员，镇压地下抵抗运动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b235a73d4a11493eb891d89ba7254d52','4cc5391bc78947fa9bf1a4b59e0f5371',1938,'伪武汉特别市市长、伪湖北省政府委员兼伪汉口市市长','张之洞之子，抗战期间投敌，历任伪武汉特别市市长、伪湖北省政府委员兼伪汉口市市长等职，在武汉地区推行日伪统治，协助日军维持占领秩序。；张之洞之子，抗战期间投敌，历任伪武汉特别市市长、伪汉口市市长等职，在武汉地区推行日伪统治，协助日军维持占领秩序。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8003b567bd854e7f953eaf3a5117481f','d39512eb28bb4bcf9149d4f6f339fd91',1938,'伪汉口特别市市长、伪武汉特别市参议府议长','抗战期间投敌，在武汉地区历任伪汉口特别市市长、伪武汉特别市参议府议长等职，参与伪政权统治，协助日军维持武汉占领区秩序。；抗战期间投敌，曾任伪汉口特别市市长、伪武汉特别市参议府议长，在武汉地区协助日军维持伪政权。；抗战期间投敌，曾任伪汉口特别市市长、伪武汉特别市参议府议长，在武汉地区协助日军维持治安、推行奴化教育。；原北洋将领，武汉沦陷后投敌，任伪汉口特别市市长，后任伪武汉特别市参议府议长，协助日军管理汉口市政，推行伪化教育。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d456083013f94034bfa8b01b284aba11','3ac5b30fa15d4b5aa4ad3fbdbf8029b7',1939,'伪武汉特别市警察局局长','在伪武汉特别市政权中担任警察局局长，负责武汉地区伪警察事务，协助日军镇压抗日活动、搜捕抗日人员、维持殖民统治秩序。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4854bb2208514a9faf77b813b15d9f47','00698e27bdf04b01b3df0628db6a9101',1938,'伪汉口市商会会长、伪汉口特别市维持会委员','武汉沦陷后参与伪维持会及伪商会活动，协助日军筹措物资、摊派款项，在经济领域附逆，为日伪统治服务。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8d6a788ac62f46aea1df477471bb1631','59b7b80204834717877601d8363522b9',1938,'伪武昌维持会会长','武汉沦陷初期参与组织伪武昌维持会，任会长，协助日军维持武昌地区秩序，为日军占领武汉提供地方配合。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9277a3fd53e74a9e8fa4fc94f6ebda22','76aa02100fe042b1aa83824f9b07038a',1938,'伪孝感县县长','抗战期间在孝感地区任伪县长，协助日军推行伪化统治，征粮征工，维持地方治安，配合日军对周边抗日力量进行压制。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5a938082124a4c028fb5e8d510387604','f31ce236ed2e4cddb4e86dce99fd1f7c',1938,'伪黄冈县维持会会长','在黄冈地区参与伪维持会活动，协助日军维持地方秩序、摊派物资，为日伪在武汉东部地区的统治提供地方支持。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c3a37db2e1314a94af23e3c008d9cfbc','f1e6b8c5b8d2445f8d61ae40c1458f29',1938,'伪湖北省政府委员、伪汉口市市长','抗战期间投敌，在伪湖北省及伪汉口市政权中任职，参与伪政权管理，协助日军在武汉地区推行殖民统治。；投敌后任伪湖北省政府委员、伪汉口市市长，在湖北沦陷区推行日伪政策，影响覆盖荆州等地。；湖北人，抗战期间投敌，任伪湖北省政府委员、伪汉口市市长，在武汉地区协助日军维持统治，推行伪化政策。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('060b019a5c114fd7b5114a2383997e07','a2e4190c87b449e685d78c118a6801b5',1940,'伪国民政府行政院副院长、伪财政部部长，曾管辖武汉地区伪政权事务','作为汪伪政权核心人物，其财政、行政权力覆盖包括武汉在内的华中占领区，参与伪政权决策，协助日军对武汉及湖北地区进行经济掠夺与统治。','省部级/大军区级要员','hanjian');
