INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9b0f3d3fa4444dc5ba85abd39ccf761b','4cc5391bc78947fa9bf1a4b59e0f5371',1938,'伪湖北省政府委员、伪汉口特别市市长','张之洞之子，抗战期间投敌，历任伪武汉特别市市长、伪湖北省政府委员等职，在湖北地区推行日伪统治，为日军搜刮物资、维持治安。；张之洞之子，抗战期间投靠日伪，历任伪武汉特别市参议府参议、伪汉口特别市市长、伪湖北省政府委员等职，在湖北地区推行日伪统治，为日军搜刮物资、维持治安。；张之洞之子，抗战期间投靠日伪，历任伪武汉特别市市长、伪湖北省政府委员等职，参与日伪在湖北的殖民统治，为日军搜刮物资、推行奴化教育。','特别市市长','hanjian');
