INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0a4ac8c4fe32481aae9b975dd72d13bd','10f9a2b89a8040c8b078f51b23827f6e',1940,'伪襄阳县政府县长','抗战期间在襄阳沦陷区出任伪县长，协助日军维持地方伪政权，征发民夫、物资，配合日伪军对襄枣宜地区的控制。；抗战期间任伪襄阳县政府县长，依附日军维持襄阳沦陷区统治，为日军征粮、派夫，协助伪化教育。','基层头目','hanjian');
