INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('57d475199500455192def26e08065179','d6dfd188b7474385b7f0cfbde3069fe0',1941,'伪鄂北清乡督办署督办','在鄂北包括随州地区推行清乡，组织伪军和伪警察封锁抗日根据地，编查保甲，镇压民众抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4b697c6b0a884e49a4f4e57706934428','8f1dd12e548b4c4f866dd743c3377896',1937,'伪华北政务委员会委员长、伪内政部部长','虽主要在华北活动，但其伪政权体系与湖北伪政权有联系，随州地区部分伪行政人员受其伪内政系统影响。；安徽合肥人，北洋旧官僚，抗战期间投敌，虽主要在华北活动，但其伪政权体系延伸至湖北部分沦陷区，对黄冈等地伪政权有间接影响。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('14e0ae2a482042509ead31470c1487e0','98b6615bf2324e2bba63a1dbfd1ac6a8',1939,'伪随县保安大队大队长','率伪保安队配合日军扫荡随县南部山区，搜捕抗日游击队员，强征民夫修筑据点。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e3ae34b12b1347929ce6bfe9354aacfc','f9ba16ca18af439e8c33488b0eb8844f',1940,'伪随县警察局局长','在随县城区及淅河、安居等地建立伪警察网络，登记户口、发放良民证，协助日军抓捕抗日人员。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('df72a42e6f2344dea3503d6f5c70151f','0806580d2c7a479e84a3ccdbd55c1bd4',1941,'伪随县教育科科长','推行奴化教育，在随县各小学强制开设日语课，篡改教材，宣传“大东亚共荣”。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d2ad577026b0411eb34a3144a674ced4','e1e11268f33147caa4c7f51dbbd58046',1941,'伪和平救国军第一师师长','率伪军驻防鄂北随县、安陆一带，配合日军进攻抗日根据地，抢掠民财。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('841dcc03241b40fe9c02b37c2fb7bdca','f163a12be90d4d0e995a0071deb7ede8',1939,'伪随县淅河区维持会会长','在淅河镇组织维持会，为日军提供情报、粮秣，强拉民女供日军淫乐。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3c4db77a80854a168b008130e5627380','76aa02100fe042b1aa83824f9b07038a',1940,'伪随县安居镇保甲长','充任伪保甲长，按日军指令摊派捐税、抓捕壮丁，迫害抗日家属。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f3a182f3f9a047d298762f96b88b2f90','bb34b45b44c34a018d410cde66579fb1',1938,'伪武汉特别市市长、伪湖北省政府主席、伪国民政府参军长','湖北黄陂人，早年投靠日军，历任伪武汉特别市市长、伪湖北省政府主席等职，协助日军推行治安强化运动，搜刮物资，镇压抗日力量。；湖北黄陂人，早年在鄂东活动。抗战期间投靠汪伪政权，历任伪武汉特别市市长、伪湖北省政府主席等职，在湖北推行伪化统治，配合日军清乡、征粮、拉夫，是湖北地区级别最高的汉奸之一。；湖北黄陂人，抗战期间投靠汪伪政权，历任伪武汉特别市市长、伪湖北省政府主席等职，在湖北地区推行伪化统治，为日军搜刮物资、镇压抗日力量。；湖北黄陂人，早年即为国民党将领，抗战期间投靠汪精卫伪政权，历任伪武汉特别市市长、伪湖北省政府主席等职，在湖北地区推行伪化统治，协助日军征粮、征兵、镇压抗日力量。；湖北黄陂人，抗战期间投靠汪伪政权，历任伪武汉特别市市长、伪湖北省政府主席等职，在湖北地区推行伪化统治，搜刮民财，配合日军清乡。；湖北黄陂人，抗战期间投靠日军，历任伪武汉特别市市长、伪湖北省政府主席等职，在湖北地区推行伪化统治，为日军搜刮物资、镇压抗日力量。；湖北黄陂人，原国民党将领，1939年投敌，任伪武汉特别市市长，后任伪湖北省政府主席兼保安司令，在湖北推行伪化统治，搜刮民财，配合日军清乡。黄冈、麻城属其伪湖北省管辖范围。；湖北黄陂人，早年投靠日军，1938年武汉沦陷后出任伪武汉特别市市长，后任伪湖北省政府主席，协助日军推行治安强化运动，搜刮物资、镇压抗日力量。；湖北黄陂人，原国民党将领，后投靠汪伪政权。任伪湖北省政府主席期间，在黄冈、黄梅等鄂东地区推行保甲连坐、征粮征丁，配合日军清乡扫荡，是湖北地区级别最高的汉奸之一。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fe7b3649e4424709a0fd8ba21d3f4c4c','26a40096acd9428f88ebde3e69fecb20',1938,'伪湖北省政府省长、伪湖北省保安司令','湖北黄冈人，日军占领武汉后出面组织伪政权，任伪湖北省省长，配合日军征粮征丁，推行奴化教育。；湖北建始人，早年留学日本，抗战爆发后投敌。1938年武汉沦陷后出任伪湖北省省长，在黄冈、黄梅等鄂东各县建立维持会、伪警察局，推行奴化教育，为日军征集物资劳工。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6a051ac374334a92a5d847bb7736afcb','d39512eb28bb4bcf9149d4f6f339fd91',1938,'伪湖北省政府省长、伪汉口特别市市长','湖北黄冈人，曾任伪湖北省省长、伪汉口市长，协助日军维持占领区秩序，参与经济掠夺。；湖北阳新人，抗战期间投敌，曾任伪湖北省政府省长、伪汉口特别市市长，协助日军维持占领区秩序。；湖北阳新人，抗战期间投靠日军，历任伪湖北省政府省长、伪汉口特别市市长，在武汉及湖北地区推行伪政，协助日军掠夺物资、镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('750101eb88a24b61acbcd556679a34e0','00698e27bdf04b01b3df0628db6a9101',1938,'伪黄冈县维持会会长、伪黄冈县县长','黄冈本地人，日军占领黄冈后组织维持会，任伪县长，为日军征粮拉夫，出卖抗日人员。；黄冈地区伪政权头目，组织维持会迎接日军，任伪黄冈县县长期间，为日军征粮、拉夫、搜集情报，镇压当地抗日群众。；黄冈本地人，抗战期间组织维持会，任伪黄冈县县长，协助日军征粮、拉夫，镇压当地抗日力量。；黄冈本地人，1938年黄冈沦陷后出面组织维持会，后任伪黄冈县县长，协助日军征粮、拉夫、维持治安，镇压抗日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4d6eb459caa0495798d71e43f42875a0','0487c7d40cba4ad5912d162b537971db',1939,'伪黄冈县保安大队大队长','黄冈本地人，率伪保安队配合日军扫荡，袭击抗日游击队，残害百姓。；黄冈人，任伪黄冈县保安大队大队长，率伪军配合日军对黄冈抗日根据地进行扫荡，捕杀抗日人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5ffabe6564f94fc8aa9e1399ef008d6c','76aa02100fe042b1aa83824f9b07038a',1939,'伪黄冈县警察局局长','黄冈本地人，任伪警察局长期间，协助日军抓捕抗日志士，推行保甲连坐。；黄冈地区伪警察头目，在黄冈及浠水周边地区搜捕抗日志士，推行保甲连坐，协助日军维持殖民统治。；抗战期间任伪黄冈县警察局局长，协助日军维持治安，镇压抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1fcbc22118e24dfe90aa53cb11efa43e','c02b988b0aec4155902b2273ca1f3e09',1941,'伪黄冈县教育科科长','黄冈本地人，推行奴化教育，强制学校使用日伪教材，宣传“大东亚共荣”。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('70acd8f20d7544fa8e7bf31029b3d966','69388f3b2cbe490b9efdc1d7c67b897c',1938,'伪黄冈县商会会长','黄冈本地商人，任伪商会会长，为日军筹集物资，垄断当地贸易，牟取暴利。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e75cbd4e8e654c3094a0bc8f30120f45','13b409fcff2449c3bd42692da36e6178',1942,'伪黄冈县自卫团团长','黄冈本地人，组织伪自卫团，配合日军清乡，多次进攻新四军根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('782d6f37d4124e01b944e15f726aa1b4','85d51bf30fdf4a55aba74c3349918f34',1939,'伪黄冈县保甲长','黄冈本地人，任保甲长期间，为日军提供情报，勒索百姓，迫害抗日家属。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('16f324ff63c346e88a61027d4de1ec2b','140629d88b8d40e9868abf9b16cef6b8',1938,'伪黄冈县维持会副会长','黄冈本地人，协助日军建立维持会，征发民夫，修筑据点。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d7200a66fbce446480e454389abf19a4','49d6ef3f99394c16a2f42e903c51880b',1940,'伪黄冈县保安队中队长','黄冈本地人，带领伪军配合日军扫荡，烧毁民房，杀害抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1de5510f36e94b009a8bb3cff066728f','10f9a2b89a8040c8b078f51b23827f6e',1938,'伪湖北省政府委员、伪黄冈县县长','抗战期间任伪黄冈县县长，在黄冈地区建立伪政权，组织维持会、保甲，配合日军征粮、拉夫、清乡，直接压迫团风一带民众。；在黄冈地区任伪县长，组织维持会，协助日军征粮拉夫，镇压当地抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c58e41dd188949f8bad2ca8c840a968b','76aa02100fe042b1aa83824f9b07038a',1938,'伪黄冈县维持会会长','黄冈本地士绅，日军占领黄冈后出面组织维持会，任会长，协助日军维持地方秩序、征集物资，是黄冈沦陷初期重要附逆者。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('08d0e7e1b4f740b183d04d5cc49e0db4','f1e6b8c5b8d2445f8d61ae40c1458f29',1940,'伪黄冈县保安团团长','抗战期间在黄冈地区组织伪保安团，配合日军对团风、淋山河等地进行扫荡，镇压抗日力量，残害百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('71a829541a1a4803b76574d2a7e8c074','0487c7d40cba4ad5912d162b537971db',1940,'伪黄冈县警察局局长','任伪黄冈县警察局局长，在团风及周边地区搜捕抗日人员，推行保甲连坐，协助日军维持殖民统治。；黄冈人，抗战期间任伪黄冈县警察局局长，在黄冈地区搜捕抗日人员，镇压民众抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b964cd5c84c440de995ef2cff5ec18f4','40fa834a858647699b6f23e9c7383015',1938,'伪团风镇维持会会长','团风镇本地商人，日军占领团风后组织维持会并任会长，为日军筹集粮草、提供情报，协助管理码头和过往人员。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('df927cd11aa74ab09ee3ac3f2e733981','4a5a9f90b0a34a59b7989699475d8dee',1940,'伪黄冈县教育科科长','在黄冈沦陷区推行奴化教育，编写伪教材，强制学校教授日语和亲日内容，毒害青少年。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('203acb499dad492db97f7b641828c472','c02b988b0aec4155902b2273ca1f3e09',1939,'伪黄冈县商会会长','控制黄冈沦陷区商业，为日军采购物资，配合经济封锁，压榨商户和民众，是经济领域附逆者。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('92431417ee4a40a99ef27c67a257029b','13b409fcff2449c3bd42692da36e6178',1940,'伪黄冈县自卫团团长、伪军头目','在黄冈、团风一带收编土匪武装，组成伪自卫团，配合日军清乡，袭击抗日游击队，残害地方。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('70ae93ecb9c642e79caae8d78c665def','a2e4190c87b449e685d78c118a6801b5',1938,'伪财政部部长、伪警政部部长','湖南沅陵人，汪伪政权核心人物，其伪财政、警政体系覆盖湖北沦陷区，对黄冈等地伪政权和伪警察有管辖和影响。；湖南沅陵人，汪伪政权核心人物，其伪财政、警政体系覆盖湖北沦陷区，包括黄冈地区伪警察与伪军组织。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('453e6d62d31c4eaba2959bf3b85f0818','d3256e7274c448058c67c4d51c3fa885',1940,'伪宣传部次长、伪《中华日报》总主笔','在汪伪政权中负责宣传，其亲日文章和宣传品在湖北沦陷区散发，对黄冈等地民众进行奴化宣传。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3d4955aa244c472a946a28791bbcc41b','62a6d6c8e7ab4bbfbc92c5b14abbde74',1940,'伪立法院院长、伪国民政府主席','汪伪政权核心人物，其伪政权体系覆盖湖北，对黄冈等地伪政权有领导责任，推行亲日卖国政策。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9c8b72359666496289236c2d62be57dc','506df7877e6b4b589f0df223e5da77c6',1940,'伪湖北省政府主席、伪军事参议院院长','湖北随县人，汪伪政权要员，曾任伪湖北省政府主席，参与伪军组织与殖民统治。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aaf5a06463264d138a9165158c8a13d4','00698e27bdf04b01b3df0628db6a9101',1938,'伪黄冈县维持会会长','湖北黄冈人，抗战期间组织伪维持会，为日军征粮、派夫，协助维持占领区秩序。；湖北黄冈人，抗战期间在黄冈地区组织伪维持会，协助日军征粮、征夫，维持地方伪秩序，镇压抗日群众。；黄冈地区人，抗战期间组织伪维持会，为日军征粮、派夫，协助日军控制黄冈一带。；黄冈地区伪维持会头目，协助日军在黄冈县及周边地区建立伪政权、征发劳役、搜刮物资。','基层维持会/地方自治头目','hanjian');
