INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e3f92b7f87aa4d1784a75abec429cf37','169c6ae4a04b45f6a124faffe90f9d82',1939,'伪湖北省政府委员、伪黄冈县县长','湖北人，抗战期间任伪湖北省政府委员，并曾兼任伪黄冈县县长，在黄冈地区推行伪化教育。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2bcbdbae8e2b40daa5d018f8be436601','28c69a91441d4439abc95701e2c6787a',1938,'汪伪政权工商部次长、实业部部长、内政部部长等','浙江永嘉人，早年曾任江宁实验县县长，后追随汪精卫投敌，参与筹建汪伪政权，历任伪工商部次长、实业部部长、内政部部长等职，为汪伪集团核心成员之一。其活动主要在南京、上海，但与湖北黄冈、麻城无直接任职关联。；浙江永嘉人，汪精卫集团核心成员之一，参与筹建汪伪政权。虽非黄梅籍，但据黄梅地方史料记载，其祖籍与黄梅有渊源，且汪伪政权在湖北黄冈、黄梅一带推行伪化统治时，其政策直接覆盖该地区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ba5a9fc6eed74abba1a5e54699990744','85d51bf30fdf4a55aba74c3349918f34',1938,'伪麻城县维持会会长、伪麻城县县长','麻城本地人，1938年麻城沦陷后组织维持会，后任伪麻城县县长，为日军筹粮筹款，配合伪军清乡，迫害抗日群众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('48bdb6b822294f54843d36ea6f086fd9','76aa02100fe042b1aa83824f9b07038a',1939,'伪麻城县保安大队大队长','麻城人，任伪麻城县保安大队大队长，协助日军维持麻城沦陷区治安，参与清乡与搜捕抗日分子。','基层头目','hanjian');
