INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('48f12e690c954ee6aa68e40b8dd86f14','13b409fcff2449c3bd42692da36e6178',1940,'伪黄卫军总司令、伪武汉行营参谋长','湖北黄陂人，原国民党军官，1940年投敌，组建伪黄卫军，活动于武汉及黄冈、麻城一带，配合日军清乡，后任伪武汉行营参谋长。','基层头目','hanjian');
