INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d4299a51ce564175a7903b00cae25dee','cfe14f020f314baba4b2dd46ee716bf4',1942,'伪湖北保安司令部副司令','湖北人，任伪湖北保安司令部副司令，协助伪湖北省政府主席叶蓬、杨揆一统辖湖北伪军，参与鄂东黄冈、麻城地区清乡。','市县厅局级','hanjian');
