INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4a52cb2e6f0c4bf094ccdccad84516f6','10f9a2b89a8040c8b078f51b23827f6e',1938,'伪黄冈县维持会会长、伪黄冈县县长','黄冈本地士绅，日军侵占黄州后组织维持会，后任伪黄冈县县长，为日军征发民夫、粮食，镇压当地抗日活动。','基层维持会/地方自治头目','hanjian');
