INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2856c9f44e8d4402b5cadf4f2fd3a04e','76aa02100fe042b1aa83824f9b07038a',1940,'伪黄冈县教育科科长','黄冈人，在伪政权中负责教育，推行日语教学和奴化教育，篡改历史教材，为日军侵略辩护。','基层头目','hanjian');
