INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('941757721d8f47e793d0b7f4ad926816','10f9a2b89a8040c8b078f51b23827f6e',1938,'伪湖北省政府委员、伪武昌市政处处长','湖北黄冈人，早年留学日本，抗战后投敌。作为黄冈籍汉奸，在伪湖北省政府中负责联络鄂东各县伪政权，直接参与黄冈、黄梅等地维持会的组建与督导。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0ee30bf2d3da4d7f849c99a074019e05','f2c99eb1b0d343818114b39936365e43',1939,'伪湖北省政府委员、伪黄冈县县长','湖北黄冈人，抗战期间出任伪黄冈县县长，在黄冈及邻近黄梅地区推行保甲制度，为日军征粮征丁，镇压抗日群众，是黄冈本地伪政权头目。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('db5409551bc74c1a87c79f8236da60d3','f1e6b8c5b8d2445f8d61ae40c1458f29',1938,'伪黄梅县维持会会长、伪黄梅县县长','湖北黄梅人，黄梅沦陷后出面组织维持会，后任伪黄梅县县长。在黄梅地区为日军征集粮食、劳工，配合日军对黄梅抗日游击区进行清乡，是黄梅本地主要汉奸。','基层维持会/地方自治头目','hanjian');
