INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6bc6210e584442c2808411c33945a2e6','d39512eb28bb4bcf9149d4f6f339fd91',1938,'伪和平救国军第一军军长、伪湘鄂赣边区绥靖公署主任','湖北阳新人，抗战期间投敌，在鄂东南一带收编土匪游杂武装，组织伪军配合日军进攻抗日根据地，活动范围覆盖黄石、大冶、阳新等地。','市县厅局级','hanjian');
