INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('914b0dc8e9c841b3b9a133636ca630c4','10f9a2b89a8040c8b078f51b23827f6e',1938,'伪黄石港维持会会长','黄石港沦陷后出面组织维持会，为日军征集物资、拉夫、维持地方秩序，协助日军控制黄石港及周边地区。；日军占领黄石后出面组织伪维持会，协助日军维持地方秩序、征发物资，为黄石地区伪政权初期头目之一。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a1ac43ee6cb04c409cb6b76a928f4056','f1e6b8c5b8d2445f8d61ae40c1458f29',1938,'伪大冶县维持会会长','大冶沦陷后组织维持会，配合日军管理矿区，为日军开采大冶铁矿提供劳力与物资支持。；在大冶、阳新一带组织伪维持会，为日军提供情报、粮食和劳工，配合日军清乡。','基层维持会/地方自治头目','hanjian');
