INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d5596c7530964538ac718739d5d1735c','76f32e67558041529d15b7d23d56c415',1938,'伪黄石港警察局局长','担任伪黄石港警察局局长，协助日军维持治安，搜捕抗日人员，控制黄石港码头与交通。；在黄石港地区担任伪警察头目，配合日军镇压抗日活动、搜捕抗日人员。；黄石港人，投靠日军后出任伪警察局局长，负责黄石港及西塞山周边治安，抓捕抗日人士，协助日军推行保甲连坐。','市县厅局级','hanjian');
