INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f53affb5423f474794791648956a5e67','85d51bf30fdf4a55aba74c3349918f34',1938,'伪石灰窑维持会会长','石灰窑（今黄石市区）商人，日军占领后出面组织维持会，为日军提供石灰窑地区物资情报，协助日军控制黄石沿江码头。；石灰窑（今黄石市石灰窑区）维持会头目，日军占领后组织维持会，为日军提供情报、物资和劳工，协助控制石灰窑及铁山矿区。','基层维持会/地方自治头目','hanjian');
