INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a2ebb37cf6794cbeb0044b1662ae6545','d39512eb28bb4bcf9149d4f6f339fd91',1938,'伪中华民国维新政府军政部长、伪湖北省政府主席','湖北阳新人，早年曾任北洋政府官员，抗战期间投敌，参与组织伪政权，任伪维新政府军政部长、伪湖北省政府主席，协助日军维持湖北沦陷区统治，其活动范围覆盖鄂东南包括黄石、铁山一带。','省部级/大军区级要员','hanjian');
