INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e8eba89f29f4433b897419c4a9f6b4ee','9f633fd7f93b41fea6e1702cdb729286',1939,'伪大冶县教育科科长','大冶县伪教育科头目，推行奴化教育，篡改教材，向学生灌输亲日思想，为日军在黄石、铁山地区的文化侵略服务。','基层头目','hanjian');
