INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('33e3b9e94993416bbe210c2bb56b1fdd','d39512eb28bb4bcf9149d4f6f339fd91',1938,'伪和平救国军第一军军长、伪湖北省政府委员','抗战期间投敌，在湖北地区组织伪军，配合日军维持占领区治安，参与伪政权活动。；湖北阳新人，抗日战争期间投靠日军，参与组织伪军，在鄂东南一带配合日军维持治安与清乡，后任伪湖北省政府委员，为日伪政权效力。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5f6c3451924649eaaf80b8c118bca5cf','169c6ae4a04b45f6a124faffe90f9d82',1938,'伪黄石港维持会会长','日军占领黄石后组织维持会，为日军筹集物资、征派民夫，协助维持黄石港地区治安。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1e75c0bc57204c2ab962ed3088e747e6','f2c99eb1b0d343818114b39936365e43',1938,'伪阳新县维持会会长、伪阳新县县长','日军侵占阳新后投敌，组织伪维持会并出任伪县长，协助日军征粮、征夫、维持占领区秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('98a46b8547b749c9bb1f204a1a0b0be2','ff163d4899c84c3bb2f4a21fd7382e5e',1939,'伪黄石港警察局局长','在黄石港伪警察局任职，配合日军搜捕抗日人员，镇压当地民众反抗。','市县厅局级','hanjian');
