INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0c3da6e2e869437cac9da68f44b559d7','0487c7d40cba4ad5912d162b537971db',1938,'伪黄石港维持会会长','黄石港本地士绅，日军占领黄石后出面组织伪维持会，为日军筹粮、拉夫、维持地方秩序，协助日军控制黄石港码头与矿区。','基层维持会/地方自治头目','hanjian');
