INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6c593b5ce84e4ff989a02b33b73075b0','0bdfae5a1cd34bb59104613572739f86',1938,'伪大冶县维持会会长','大冶县（今黄石市区）人，日军占领大冶后组织伪维持会，任会长，协助日军管理矿区、征发民夫，为日军开采铁矿提供劳力。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9c971d02eb8d4b0b82f2ac1e41ba0a29','76f32e67558041529d15b7d23d56c415',1939,'伪大冶县警察局局长','抗战期间任伪大冶县警察局局长，配合日军搜捕抗日人员，镇压地方抗日活动，维护日伪在大冶地区的统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('af2c07912fb2443697cc3011bf765241','ff163d4899c84c3bb2f4a21fd7382e5e',1938,'伪黄石港区保甲长','黄石港本地人，抗战期间担任伪保甲长，为日军征收粮食、税款，登记户口，协助日军控制黄石港居民，举报抗日嫌疑人员。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6e39882635bf46b1a1b9f142fb911348','49d6ef3f99394c16a2f42e903c51880b',1939,'伪黄石港码头工会会长','黄石港码头工人出身，投靠日军后组织伪工会，控制码头工人，为日军装卸掠夺物资，协助日军镇压工人反抗。','基层头目','hanjian');
