INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('31d333cb87354a548757f759f8fd7baa','10f9a2b89a8040c8b078f51b23827f6e',1938,'伪湖北省政府委员、伪武汉市市长','湖北人，抗战期间投敌，曾任伪武汉市市长、伪湖北省政府委员，协助日军管理武汉及周边地区，包括黄石一带的物资调配。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3db67b9eb2db4484b25a1c2f8ba436ed','169c6ae4a04b45f6a124faffe90f9d82',1940,'伪黄石港税务局局长','抗战期间任伪黄石港税务局局长，为日伪征收税款，盘剥当地商民，协助日军对黄石港经济进行控制。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('678869cdceff482fb89f41c40dc2b9d7','d6c62d6f41694b5b8736bb8b43e972f4',1939,'伪黄石港小学校长','黄石港教育界人士，抗战期间附逆，任伪黄石港小学校长，推行奴化教育，使用日伪教材，向学生灌输亲日思想。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('eacffb3def4c4f908794b8c119b80326','ca678bc1a4ba4f1b9b03d6c6da5088a4',1944,'双峰县维持会会长','日军侵占双峰期间，出面组织维持会，为日军征派粮秣、夫役，协助维持占领区秩序。','基层维持会/地方自治头目','hanjian');
