INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e8bf2fc0490b4ba2a90e5dbae0cb26d8','b8c3462e5f5d49389caec12839d26158',1944,'娄底维持会会长','日军窜扰娄底时组织维持会，为日军筹粮、带路，并诱迫乡民归顺。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('07e15369dd4f49a3aaeb24535a404494','cbaf785da5ae45159f8f160436ea6d7f',1944,'湘乡县伪县长','抗战后期在湘乡沦陷区出任伪县长，秉承日军意旨推行伪化统治，征粮拉夫。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b0bb5e94dca4429ba33ac234204e9d9c','f5dc03bde8d94f119c62820c4bfd945b',1944,'宝庆（邵阳）维持会副会长','在邵阳及邻近娄底地区参与维持会活动，为日军搜集情报、征发物资。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ba1e2d3cf6da4c5a8c64fb862b6e79a2','a2e4190c87b449e685d78c118a6801b5',1940,'汪伪政权行政院副院长、伪上海市长','湖南沅陵人，汪伪政权核心人物之一，虽主要活动于南京、上海，但作为湖南籍汉奸头目对湖南沦陷区伪政权有影响。；湖南沅陵人，汪伪政权核心人物之一，参与对湖南等地的伪化宣传与策反活动，间接影响常德、临澧一带的伪政权建立。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1043614c299949648da59a9f684680d1','4f19196006a34c1b88aeb20e5ccaacdb',1940,'汪伪政权军事委员会委员、伪江苏省保安司令','湖南东安人，受重庆方面派遣打入汪伪，但公开附逆任职，在湖南籍汉奸中有一定代表性。；湖南东安人，受重庆方面派遣打入汪伪内部，但在汪伪政权中担任要职，与湖南籍伪政权人员有联系，其活动范围涉及湖南。；湖南东安人，受重庆方面派遣打入汪伪内部，但公开身份为汪伪高级将领，在伪政权中任职，与湖南籍军政人物网络有关联。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('27df79a8f76647969aaef4b83b8ee7a2','e7ec243906d4478082206f56be9b96f0',1944,'湘潭县维持会会长','日军侵占湘潭期间组织维持会，为日军征粮、派夫，维持沦陷区秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ce0481d3e5744fb8bdbf91e85a7b2b1d','8af75c63d4ac48f8a4a24a2ebdedf700',1944,'湘乡县伪保安团团长','在湘乡、双峰一带收编游杂武装，投靠日军，配合日军扫荡抗日游击队。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('082ff2bba8144e3cbc58f82f1e24b01e','6c8dcdeb7a3b488da111d68136c5ceeb',1944,'长沙县伪维持会委员','在长沙沦陷区参与维持会，协助日军征发物资，其活动范围涉及湘中地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cdb838b413fd40e8b39e4cfcecb8790f','4f19196006a34c1b88aeb20e5ccaacdb',1940,'汪伪政府军事委员会委员、伪清乡委员会驻苏州办事处主任','湖南东安人，受重庆方面派遣打入汪伪政权，曾任伪军委会委员等职，在沦陷区活动，与湖南籍军政人员有联系，但其身份为军统潜伏人员，并非完全附逆。；湖南东安人，奉蒋介石、戴笠之命打入汪伪政权，表面附逆，实为军统潜伏人员，在汪伪政权中任军事委员会委员等职，从事策反与情报工作。；湖南东安人，奉蒋介石、戴笠之命打入汪伪政权，表面任伪职，实际从事策反与情报工作，属潜伏性质，与株洲、攸县无直接活动关联。；湖南东安人，原国民党将领，后受蒋介石、戴笠派遣打入汪伪政权，任伪军事委员会委员、伪清乡委员会驻苏州办事处主任等职，表面附逆，实为重庆方面提供情报并掩护军统活动。其活动范围主要在江苏、上海，但与湖南永州东安有籍贯关联。；湖南东安人，原国民党将领，后受蒋介石、戴笠派遣打入汪伪政权，表面任伪职，实际从事策反与情报工作。其活动与湖南永州东安有关联，但主要附逆任职在南京、苏州等地。；湖南东安人，奉蒋介石、戴笠之命潜入汪伪政权进行策反工作，但公开身份为汪伪高官，在沦陷区参与伪政权军事与清乡事务，与湖南籍军政人员联系密切。；湖南东安人，奉蒋介石、戴笠之命潜入汪伪政权，表面附逆，曾任伪军事委员会委员等职，在江苏、上海一带活动，与湘潭无直接地域关联，但属湖南籍有明确记载的汪伪政权任职者。；湖南东安人，原国民党将领，后受蒋介石、戴笠派遣打入汪伪政权，任伪军事委员会委员、伪清乡委员会驻苏州办事处主任等职，在沦陷区活动，与湘潭地区有间接关联。；湖南东安人，原国民党将领，后受蒋介石、戴笠派遣打入汪伪政权，任伪军事委员会委员、伪清乡委员会驻苏州办事处主任等职，表面附逆，实为重庆方面提供情报并掩护军统活动。；湖南东安人，原国民党将领，后受蒋介石、戴笠派遣打入汪伪政权，任汪伪军事委员会委员、伪清乡委员会驻苏州办事处主任等职，表面附逆，实为重庆方面提供情报并掩护营救部分抗日人员。；湖南东安人，原国民党将领，后受蒋介石、戴笠派遣打入汪伪政权，但在此期间公开附逆，任汪伪军事委员会委员、伪清乡委员会驻苏州办事处主任等职，参与伪政权军事与清乡活动，与湖南衡阳、南岳地区有籍贯及人脉关联。；湖南东安人，受重庆方面派遣打入汪伪政权，曾任伪军事委员会委员等职，在沦陷区活动，与湖南衡阳地区无直接任职关联，但属湖南籍附逆人员中较知名者。；湖南东安人，奉蒋介石、戴笠之命潜入汪伪政权，表面附逆，曾任伪军事委员会委员等职，负责联络策反伪军，抗战胜利后恢复国军身份。；湖南东安人，奉蒋介石、戴笠之命打入汪伪政权，表面任伪职，实际从事策反与情报工作，抗战胜利后恢复国军身份。；湖南东安人，奉蒋介石、戴笠之命打入汪伪内部，表面附逆，实为军统潜伏人员，并非真汉奸。；湖南东安人，受重庆方面派遣打入汪伪政权，曾任伪军事委员会委员等职，在湖南及周边地区有活动关联，但身份具有双重性，历史评价复杂。；湖南东安人，奉蒋介石、戴笠之命打入汪伪政权，表面附逆，曾任伪军事委员会委员等职，从事策反与情报工作；其活动主要在上海、南京、苏州一带，与湖南郴州、安仁无直接地方任职关联。；湖南东安人，受重庆方面派遣打入汪伪政权，在江苏、上海一带活动，其活动范围未直接覆盖郴州宜章，但作为湖南籍伪政权高层被部分史料提及。；湖南东安人，奉蒋介石、戴笠之命潜入汪伪政权，表面任伪职，实际从事策反与情报工作，属特殊历史人物，常被列入湖南籍附逆人员讨论范围。；湖南东安人，奉蒋介石之命打入汪伪政权，表面任伪职，实际从事策反与情报工作；其活动范围主要在江苏、上海，但与湖南籍军政网络有联系，常被视为抗战时期湖南籍伪职人物中需辨析者。；湖南东安人，原国民党将领，后受蒋介石、戴笠派遣打入汪伪政权，但在汪伪政府中公开任职，参与伪军事与清乡事务，与长沙、湖南地区有籍贯及人脉关联。；湖南东安人，原国民党将领，后受蒋介石、戴笠派遣打入汪伪政权，任伪军事委员会委员、伪清乡委员会驻苏州办事处主任等职，在沦陷区活动，与长沙、湖南有籍贯关联，但其主要活动区域在江浙，属于有明确历史记载的湖南籍附逆人物。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c13b3a9a51924576891bee390c3262ce','a2e4190c87b449e685d78c118a6801b5',1938,'汪伪政府行政院副院长、财政部长、伪警政部长','湖南沅陵人，汪伪政权核心人物之一，参与筹建汪伪政权，推行伪化统治，其活动范围涉及华中、华东，与湖南籍人士有较多联络。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7d3e5fca01054e248caed87a0d6ddcf1','62a6d6c8e7ab4bbfbc92c5b14abbde74',1938,'汪伪政府立法院长、伪行政院长','虽为广东籍，但作为汪伪政权主要头目，其伪政权统治体系覆盖包括湖南在内的华中地区，对湖南沦陷区伪组织有统辖关系。；湖南籍（祖籍湖南），汪伪政权主要头目之一，其伪政权统治体系覆盖包括湖南在内的沦陷区。；广东乳源人，汪伪政权二号人物，虽非湖南籍，但其伪政权体系覆盖湖南沦陷区，对湖南伪政权有统辖关系。；广东乳源人，汪伪政权主要头目之一，追随汪精卫叛国投敌，其伪政权统治覆盖华中、华南，包括湖南部分地区，但与郴州、汝城无直接活动记载。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dc0431242d21468694a030ee08c11d59','bb34b45b44c34a018d410cde66579fb1',1939,'汪伪政府陆军部长、伪武汉行营主任','湖北人，汪伪军事头目，曾负责伪军扩编与清乡，其伪军活动范围包括湘北、鄂南，对湖南北部沦陷区有影响。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ef23c666488c4b3e954cc61dc63334e3','ef676fac9bb24126bcc992f39c87c979',1940,'汪伪政府开封绥靖主任、伪军委会委员','河北人，西北军旧部，投汪后负责河南伪军，其伪政权与湖南无直接统辖，但属汪伪体系。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4638dbbd6324433db7d94a7b5def1659','bacadba533394b3bb79fb5b9c5b66118',1943,'汪伪政府浙江省长、伪军委会委员','浙江人，汪伪地方要员，活动于浙江，与湖南无直接关联。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a4e4f26faddb445982e14af86381433c','d823baec96e04682bca33413f02ae20d',1940,'汪伪政府浙江省长、伪建设部长','浙江人，汪伪政权文职要员，活动于华东，与湖南无直接关联。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('79ff5b171f74411a95287dbb080419d2','3f934b1c263b4cd78c73d9700621e7bd',1940,'汪伪政府安徽省长、伪江西省长','江苏人，汪伪地方要员，活动于皖、赣，与湖南接近但无直接统辖。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('37b16f52b5cd483cb16b0e7d08189b42','506df7877e6b4b589f0df223e5da77c6',1940,'汪伪政府湖北省长、伪军委会委员','湖北人，汪伪湖北省要员，其伪政权与湘北沦陷区有接壤，对湖南北部伪化有一定影响。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5e5147b8bbc94667bc674802fa24b071','26a40096acd9428f88ebde3e69fecb20',1938,'伪湖北省长、伪保安司令','湖北人，伪湖北省政权头目，活动于武汉及鄂中，与湘北接近。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('579b3d31d1894a91a665d2e4b45153fa','10f9a2b89a8040c8b078f51b23827f6e',1944,'伪湖南省政府筹备处负责人（未正式成立）','在日军侵占湖南部分地区后，曾参与伪湖南省政权筹备活动，但伪省政府未正式成立，具体活动记载有限。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0963396840cb4e6f96ce5a084dab6e86','8588ca8a02624b44a8d08163d89016ba',NULL,'无','经查，新化、娄底地区在抗战时期有明确记载的汉奸名录极少，地方志中多记载抗日志士而非附逆者。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f37942d1faf04e3496efa02116c02429','51cc603628064bf99c4cc926d3628036',1938,'伪岳阳维持会会长','日军侵占岳阳后出面组织伪维持会，协助日军征粮、拉夫、维持城区秩序，镇压抗日群众。；日军占领岳阳后出面组织伪维持会，协助日军征粮、拉夫、维持城区秩序，为日军侵岳提供地方支持。；岳阳沦陷后出面组织维持会，为日军筹粮、派夫、维持地方秩序，协助日军控制岳阳城区及周边乡镇。；日军侵占岳阳后出面组织伪维持会，为日军筹粮筹款、维持地方秩序，协助推行伪化统治。；日军侵占岳阳后出面组织伪维持会，协助日军维持占领秩序、征派民夫与物资。；日军侵占岳阳后出面组织伪维持会，协助日军征粮、拉夫、维持城区秩序，为日军侵略服务。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('df9e4bc36aac4dccaa4c5707007e76ce','64b4e1b9cdd44c32b01f56f5b963644c',1939,'伪岳阳县知事','在伪岳阳县公署任职期间，配合日军推行保甲连坐，搜捕抗日人员，强征物资。；在日军扶植下出任伪岳阳县知事，推行伪政令，配合日军清乡、征粮和奴化宣传。；在日军扶植下出任伪岳阳县知事，推行保甲制度，配合日军清乡、征粮、拉夫。；在日军扶植下出任伪岳阳县政权头目，推行伪化统治，配合日军清乡与征粮。；在日军扶植下出任伪岳阳县知事，推行伪政令，配合日军清乡、征粮、编查保甲。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c3e3da066afc4205b6d8d08b7cf889c5','c6df24aab02e4bbfb993cf6c0e5708c7',1939,'伪岳阳警察局局长','统领伪警察为日军搜集情报，参与抓捕、审讯抗日嫌疑人员，勒索市民。；掌控伪警察力量，搜捕抗日人员，镇压民众反抗，为日军提供情报。；掌控伪警察力量，协助日军搜捕抗日人员，镇压民众反抗，维护日伪在岳阳的统治秩序。；掌控伪警察力量，协助日军搜捕抗日人员、镇压民众反抗。；充任伪警察头目，协助日军搜捕抗日人员，镇压民众，维护日伪统治秩序。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d6cfd38d89574bc9820f63d8e17c5345','82c8dc8c68f3449d85ce6770c252b411',1941,'伪岳阳保安大队大队长','率伪军配合日军扫荡岳阳周边乡村，袭击抗日游击队，抢掠民财。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6bd6930808844d26a898f113c30d4644','f229600d6b374711b33d2aa5a728b586',1938,'伪临湘县维持会会长','在临湘地区组织伪维持会，为日军提供情报、粮秣，协助建立伪政权。；在岳阳邻近的临湘县组织伪维持会，为日军筹粮筹款，协助建立伪政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0dd7bb111e204543990263b79146af75','860eb570bbc54a35b97fd7d750cc53b3',1940,'伪华容县知事','任伪华容县知事期间，推行奴化教育，强征壮丁，配合日军清乡。；任伪华容县知事期间，配合日军在洞庭湖区征粮、清乡，压迫民众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2a88b9e61d3a49518f9cbdec1519573c','78ccd066dd4d409f8a5f4d63b1fc6482',1939,'伪湘阴县维持会副会长','协助日军在湘阴建立伪组织，征发民夫修筑工事，迫害抗日家属。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a0f036ec126f4a2ab72b54dcc2ffdbfa','b9cce48e70ac415fb78d48afeaf84b30',1939,'伪平江县维持会会长','在平江组织伪维持会，为日军筹粮筹款，诱降抗日人员。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('60973098cfd3445a8929ac22093a56e6','03e03d27f71e4e3d9d2a07309fedc8b2',1944,'伪长沙县知事','长沙沦陷后出任伪长沙县知事，协助日军维持占领区秩序，征调物资。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c5c7d6d36e24472eb691b031c3f191e8','b0029840ecbd4ef8b36226ecba81c9bc',1944,'伪湖南省政府委员兼伪长沙市市长','在长沙沦陷区参与伪湖南省政权，为日军粉饰统治，推行配给制度，压制民众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fb252c3a27a24377af5ccc62c6cc993b','4f19196006a34c1b88aeb20e5ccaacdb',1943,'伪湖南省保安司令部副司令（后证实为军统潜伏人员）','受军统派遣打入汪伪政权，表面任伪职，实际从事潜伏与策反工作；此处仅列其伪职身份，历史评价以潜伏为主。；受军统派遣打入汪伪政权，任伪职期间与湖南伪政权有联系，但属潜伏性质，历史评价复杂。；名义上在日伪湖南政权中任职，活动范围涉及长沙、益阳等地；但战后证实其为重庆方面派遣的潜伏人员，故不应列为汉奸。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1aa12dad7c32422ea7500a59b5e8b09a','49fe903b7e6f4d9a9ca4f4691be2d305',1944,'伪湖南日报社社长','在长沙主办伪报纸，宣扬“大东亚共荣”，为日军占领政策进行文化宣传。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('17226c699d064810b04766fd1193a048','a027a230235f4b4290c87bed8364d422',1940,'伪岳阳县教育科科长','在岳阳推行奴化教育，篡改教材，强迫学生学习日语和亲日内容。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('54ac6355bec44a0aa07c0fe85a4af469','68528c7dbb224fd2a2003f3588d39e96',1939,'伪岳阳商会会长','控制岳阳商会为日军筹集物资，协助实行经济统制，从中牟利并压制商户。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e6957cddf7974afdbb9219c2741462ba','adf7fbb10f444960a2987e099fa97e5d',1940,'伪粤汉铁路岳阳段护路队队长','率伪护路队保护日军铁路运输，参与清剿铁路沿线抗日武装，抓捕破坏交通人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1f0cceac1c244b6a86d0510d3c936b4a','51cc603628064bf99c4cc926d3628036',1938,'伪临湘县维持会会长、伪临湘县县长','日军侵占临湘后出面组织维持会，后任伪临湘县县长，为日军征粮派款、维持地方伪秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b84cfd03319142a0addaf19a8a995d8d','5396624e0aab407fb0a31f272a7754ed',1939,'伪临湘县保安团团长','在临湘一带收编土匪武装，投靠日军，配合日军扫荡抗日根据地，残害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('833d02916bcb49c4996032fb6f56e1b8','90652850b32b4581af274e6bff0e3a79',1938,'伪岳阳维持会会长','岳阳沦陷后组织维持会，为日军筹粮筹款、拉夫，协助日军建立伪政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d5450c6f940f4d84929283ddba4fffaa','64b4e1b9cdd44c32b01f56f5b963644c',1940,'伪岳阳县县长','任伪岳阳县县长期间，推行日军殖民统治政策，征发民夫、物资，配合日军清乡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1eef20b8d25948469f1d55ec035bcbf0','9edffbe996544548b557d5046210f571',1940,'伪军保安队队长（岳阳地区）','率伪保安队在岳阳、临湘交界地区活动，配合日军扫荡，抢掠民财。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c5247bf4f2344a4690b89af5964e3560','8588ca8a02624b44a8d08163d89016ba',1939,'伪湖南维持会联合会成员（岳阳籍）','在湖南伪维持会系统中任职，协助日军在岳阳等地推行保甲连坐，镇压抗日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('90ad9fa279744af293b85b4830786e30','4f19196006a34c1b88aeb20e5ccaacdb',1943,'伪湖南省政府委员（后反正）','受重庆方面派遣打入汪伪政权，任伪湖南省政府委员等职，在湖南日占区活动，后率部反正。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1cf7031b8d3048d1ad6bcda4cce41aa5','2d636ffc39184e92b391439163f73f16',1940,'伪湘阴县县长（邻近岳阳）','在湘阴、岳阳交界地区任伪县长，为日军征粮、征夫，配合日军对洞庭湖区的扫荡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c28d8e9ebfe24258959f4295eb31b5ab','63e8ad6773624d45b1a7e6dc11c6b2bf',1943,'伪湖南清乡督办（后反正）','在汪伪政权中任湖南清乡督办，参与日军对湖南抗日根据地的清乡，后向国民政府投诚。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('11935a64345644f6ac1f0eca655f5569','82c8dc8c68f3449d85ce6770c252b411',1939,'伪湘阴县维持会会长','在湘阴一带组织伪维持会，为日军筹粮筹款，协助建立伪基层政权，活动范围邻近岳阳地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('960a9d86efb445659a6f028c4229f13d','3c48e58b753e4582a2ebca10fd31aac6',1938,'伪临湘县知事','临湘沦陷后投靠日军，任伪县知事，配合日军修筑粤汉铁路沿线据点，镇压抗日游击活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('196d0aac12994d519c80f30ce0367679','f159181879454138b256d41584535500',1941,'伪湖北保安司令部岳阳地区伪军头目','率伪军配合日军在岳阳、云溪一带清乡扫荡，袭击抗日武装，强征民夫修筑工事。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f643d7ec01b94c2eb1b95c876cc0dbe9','8588ca8a02624b44a8d08163d89016ba',1939,'伪岳阳商会会长','以商会名义为日军筹措物资，协助日伪经济统制，压迫商户，属经济领域附逆者。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c4b3160861b64555bdd80c74f5c4996e','98ed2b5ac6e84c4888b2ae7bf3106ddc',1940,'伪湖南省政府顾问','虽主要活动于长沙，但与岳阳日伪政权有联系，为日军在湖南的统治提供所谓地方名流支持。；原湖南军阀，晚年投靠日伪，任伪湖南省政府顾问，为日军统治湖南提供咨询。；湖南沦陷后与日伪合作，参与伪省政咨询，为日军统治湖南出谋划策。；湖南沦陷后出任伪省政府顾问，为日军出谋划策，协助推行伪化教育。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4313db16676d41aeb4185606c6caec4b','0d2d2045fc1d498dab9499e43abcb3de',1944,'伪湖南省政府主席','抗战后期任伪湖南省政府主席，推行日伪政令，其伪政权影响覆盖岳阳地区，协助日军维持占领区统治。；汪伪政权任命其为伪湖南省政府主席，在湖南沦陷区推行伪政令，协助日军征粮、征丁，镇压抗日活动。；汪伪政权任命为伪湖南省政府主席，在日军占领区推行伪政令，协助日军统治湖南。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c94b20bb4fd34f1586fc4759fad1911c','4f19196006a34c1b88aeb20e5ccaacdb',1943,'伪湖南省保安司令部副司令','在湖南伪政权中任职，与日伪合作维持治安，其活动范围涉及岳阳等沦陷区，后因军统潜伏身份存争议。；受日军扶植出任伪职，协助整编伪军，配合日军在湖南的军事行动。；抗战后期在湖南伪政权中任职，协助日军整编伪军，其活动范围涉及湘西部分地区。；受重庆方面派遣潜伏，但公开身份为伪职，在湖南伪军中任职，与邵阳地区伪军有联络。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ec133a1e7a9c49a5b2d061adcfcdcc28','a2e4190c87b449e685d78c118a6801b5',1938,'汪伪国民政府行政院副院长、财政部长、警政部长、上海市长','湖南沅陵人，汪伪政权核心人物之一，参与对日妥协与伪政权建设，虽主要活动于南京、上海，但作为湘籍汉奸代表人物，其伪政权体系对湖南沦陷区有间接影响。；湖南沅陵人，汪伪政权核心人物之一，参与对日投降与伪政权建设，推行伪化统治，为日军侵华提供财政与行政支持。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('41de5b1af78a46d98e42bc54f785ccac','4f19196006a34c1b88aeb20e5ccaacdb',1940,'汪伪军事委员会委员、伪清乡委员会副秘书长等','湖南东安人，受重庆方面派遣打入汪伪内部，但公开身份为汪伪高官，参与伪军与清乡事务，与湖南籍军政网络关系密切，常被视为灰色人物。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3677accadaa34892a1b8e50d32c53cff','bb34b45b44c34a018d410cde66579fb1',1939,'汪伪武汉绥靖公署主任、伪湖北省长、伪陆军部长','湖北黄陂人，长期在武汉及鄂湘边界活动，其伪政权与伪军势力覆盖湘北、岳阳一带，配合日军对湖南沦陷区进行控制与清乡。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a408045c226c4e3fa4fc938a53cea055','b19edc2e16ec4c7d9462b01fbba0f27f',1943,'伪军头目（原国民党军将领，后投敌）','在鄂湘边界及岳阳、华容周边活动，曾率部投靠日军，编入伪军，配合日军在洞庭湖区域进行扫荡与治安作战。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('87a5781f2f374dc4b7d067be60de6299','5b3187957ade4aa1a703516923e040a3',1943,'伪华容县维持会会长','华容沦陷期间组织维持会，为日军征粮、征夫，协助建立伪基层政权，控制华容及洞庭湖西岸部分地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3a11f0dad9a346e69b1e18e2104fe935','fcde9c684d3041fa8a4bf2275da74a5a',1940,'伪岳阳县政府县长','在日军扶植下出任伪岳阳县长，推行保甲制度，配合日军清乡，镇压抗日活动，控制岳阳及临湘、华容交界地区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d35b84ea504b4084bc6b26e2611c0408','76f32e67558041529d15b7d23d56c415',1941,'伪军岳阳保安大队大队长','统率伪保安队配合日军在岳阳、华容、南县一带进行扫荡，搜捕抗日人员，强征民夫与物资。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6524b2ffc2bb48d1988ee5c9948be8a2','1ebf74820a8f47f5a69c6222f26c9167',1941,'伪湖南清乡事务局委员（伪职）','在汪伪湖南省政权中任职，参与清乡计划，其活动范围涉及湘北岳阳、华容等沦陷区，协助日军推行治安强化。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1fdd4f337a0b46d086ac1009b371533a','8588ca8a02624b44a8d08163d89016ba',1942,'无（注：此名与中共将领同名，但此处指岳阳地区伪保长）','岳阳华容交界地区伪保长，为日军征粮派款，监视村民，协助日军维持基层统治。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dd8c328ec3d947359597a03a2d93c686','1ca3503a85404bf78e71fe36ed7cd49c',1940,'伪岳阳县政府秘书/伪科长','在伪岳阳县政权中任职，参与伪政令宣传、物资统制与情报搜集，协助日军控制岳阳城区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('872fe435d14f4fae9f679aeb7d85e18a','e9587227b0b94a66bd0400664cc4baa6',1941,'伪岳阳警察局局长','统率伪警察配合日军搜捕抗日人员，镇压民众反抗，维护日伪在岳阳的治安统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8e882fc227f442ec9a934173ee8eba41','3c48e58b753e4582a2ebca10fd31aac6',1938,'伪岳阳商会会长','以商会名义为日军摊派物资、筹措军需，协助日伪对岳阳工商业进行经济统制。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5bfb5d18633049a0a80cf01d8af2deab','860eb570bbc54a35b97fd7d750cc53b3',1939,'伪君山维持会会长','在君山地区组织伪维持会，为日军提供船只、粮草和情报，协助日军控制洞庭湖沿岸。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('491c171d3e1e47bdbd653a231c34597c','bed70a52a5f14e529560fd0c03a85df9',1939,'伪临湘县知事','在岳阳邻近的临湘县出任伪知事，配合日军修筑据点、征发民夫，参与对岳阳周边抗日根据地的封锁。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('919063d97b95497799dccede41a732b1','8588ca8a02624b44a8d08163d89016ba',1939,'伪湘阴县维持会副会长','在湘阴地区协助日军推行伪化，组织伪自卫团，配合日军对洞庭湖抗日游击区进行扫荡。；在湘阴县协助日军建立伪维持会，参与征发民夫、物资，支持日军军事行动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aaceee16d63c4814a902117dbea0e40a','3eb9c6309b2649c8b968f873d3f22131',1940,'伪湖南省政府委员','在伪湖南省政权中任职，参与制定伪政策，协助日军对湖南沦陷区进行政治控制与经济掠夺。；在伪湖南省政府中任职，参与推行日伪政策，为日军在湖南的统治提供行政支持。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2e834efbb4ad43f98deae69e92e72597','4f19196006a34c1b88aeb20e5ccaacdb',1943,'伪湖南省保安司令部司令','受日军扶植出任伪湖南省保安司令，统率伪军配合日军在湖南各地清乡、扫荡，镇压抗日武装。；受重庆方面派遣打入汪伪政权，但在湖南日占区与伪政权有公开任职，后被认定为潜伏人员，其公开附逆行为在地方史料中有记载。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1f02fb8f7caa4d248cf4612581360f64','a2e4190c87b449e685d78c118a6801b5',1939,'汪伪政权要员（湖南籍）','湖南沅陵人，汪伪政权核心人物之一，参与伪政权决策，其活动对湖南沦陷区伪化统治有直接影响。','无明确职位或一般帮凶','hanjian');
