INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('007981f5a56b42468785a7c944a614d0','8588ca8a02624b44a8d08163d89016ba',NULL,'无','无可靠汉奸记录，此条为误置占位，不应视为汉奸；无；湖南湘潭人，八路军副总司令，抗日将领，非汉奸。；经检索，彭德怀为抗日将领，非汉奸，此处仅作排除说明，不列入汉奸名录。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ce93cc77660045b5afe844e17f356e80','555a5637277447408f5f697f052d0c9d',1943,'伪临澧县维持会会长','抗日战争后期在临澧县组织伪维持会，为日军征派粮秣、夫役，协助日军维持占领区秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1ce85631f08344778593a093a340f106','6162af4edadf4e5497cc6425df4ff288',1943,'伪常德县维持会会长','常德会战期间及之后，出面组织伪维持会，替日军筹集物资、安抚民众，协助日军控制常德城区。；常德会战后，受日军指使筹组伪常德县维持会，充任会长，为日军征粮、征夫，并参与伪政权宣传。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('950a05ef24d14f5abc0e4700fb4ff49e','d12e35a8ce32472f94b974ab6213e8e6',1943,'伪常德县警察局局长','在日军占领常德期间出任伪警察局长，带领伪警察配合日军搜捕抗日人员、维持治安。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4e057182d265439e8c168e9197730791','bb34b45b44c34a018d410cde66579fb1',1940,'汪伪政权陆军部长、伪湖北省长','湖北人，但活动范围覆盖湘北，与常德、临澧一带的伪军有联络，曾参与策动湖南伪军。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2be097bdf8144f76b36cf55679ac1dea','b19edc2e16ec4c7d9462b01fbba0f27f',1943,'伪和平建国军师长','在湘北一带活动，曾配合日军对常德、临澧地区进行扫荡和伪化统治。；投靠日本，在华北及陕西周边地区配合日军进行殖民统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8540489e222e4ed5b69c8ddbc9255075','62a6d6c8e7ab4bbfbc92c5b14abbde74',1940,'汪伪政权立法院长、伪上海市长','汪伪政权要员，参与对湖南等地的伪化政策制定，其影响波及常德、临澧的伪政权运作。；汪伪政权二号人物，其伪政权体系延伸至重庆周边，有间接关联。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3aff0f4924b64f08aa95322cbfb07068','555a5637277447408f5f697f052d0c9d',1943,'伪安乡县维持会会长','抗日战争时期在安乡县组织伪维持会，为日军征集物资、拉夫，协助日军维持占领区秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c087678da2af4b07b6a739a812da1440','a2e4190c87b449e685d78c118a6801b5',1940,'汪伪政权行政院副院长、财政部长','湖南沅陵人，汪伪政权核心人物之一，参与对湖南沦陷区的伪化统治与经济掠夺。；湖南沅陵人，汪精卫伪政权核心人物，参与对湖南地区的伪化宣传与渗透。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('abf531ff1bbe4f79ba142ae868721abe','4f19196006a34c1b88aeb20e5ccaacdb',1940,'汪伪政权军事委员会委员、伪清乡委员会要职','湖南东安人，受重庆方面派遣打入汪伪内部，但公开身份为汪伪高官，在湖南及沦陷区有一定影响。；湖南东安人，受重庆方面派遣打入汪伪内部，表面附逆，实际为军统提供情报，战后被认定为潜伏人员。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4e0ed543542944e4ad4c5035104f404e','e7ec243906d4478082206f56be9b96f0',1943,'伪常德县维持会会长','常德沦陷期间组织伪维持会，为日军提供情报、粮食和民夫，协助日军控制常德城区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('70d8562524244d4fa4302e1b39eeed7f','51cc603628064bf99c4cc926d3628036',1943,'伪常德县警察局局长','在常德沦陷区担任伪警察头目，配合日军搜捕抗日人员，镇压民众反抗。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('78e115b1d36e4a09ab3df7430359724c','5b3187957ade4aa1a703516923e040a3',1943,'伪安乡县保安团团长','率部投靠日军，编为伪保安团，在安乡、南县一带配合日军扫荡抗日武装。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('daf4f64d40764df495388503784d1897','f159181879454138b256d41584535500',1944,'伪湖南省政府委员','汪伪政权在湖南设立伪省政府时任职，参与推行伪化教育、征粮和治安强化运动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dce3f4d321b44e35b5b88170655390aa','1793bd7ead3940c19f20f231c5c3695d',1938,'伪岳阳维持会会长','岳阳沦陷后组织维持会，控制洞庭湖区域物资运输，为日军提供船只和情报，影响波及常德、安乡水路。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dedb6b3e1df14b3192ffffa02caef80e','b19edc2e16ec4c7d9462b01fbba0f27f',1943,'伪沔阳保安司令（后投日）','原国民党军将领，1943年被俘后投靠日军，在湖北、湖南交界地区组织伪军，活动范围接近常德、安乡。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('870d2594bdbd4576b8087a6f2a3f79e2','444e6f45cd45427a9f77f72e757e63f2',1944,'伪湖南省教育厅厅长','在汪伪湖南省政府中负责教育，推行奴化教育，篡改教材，宣传“大东亚共荣”。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d7ea54f2a63e4381ae8b76ad49373207','a2e4190c87b449e685d78c118a6801b5',1938,'汪伪政权行政院副院长、财政部长、伪上海市长','湖南沅陵人，汪精卫伪政权核心人物之一，参与筹建汪伪政权，历任伪行政院副院长、财政部长、伪上海市长等职，推行伪化统治，为日军侵华服务。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c32d083bc05d4372867de2b74031505e','4f19196006a34c1b88aeb20e5ccaacdb',1940,'汪伪政权军事委员会委员、伪清乡委员会副秘书长','湖南东安人，受重庆方面派遣打入汪伪内部，但公开身份为汪伪军事委员会委员等职，在沦陷区活动，与常德地区日伪势力有联系。；湖南东安人，受重庆方面派遣打入汪伪政权，但在汪伪中担任军事委员会委员、伪清乡委员会副秘书长等职，参与伪政权军事与清乡事务，身份具有双重性，常被列为附逆人员。；湖南东安人，受重庆方面派遣打入汪伪，但在汪伪政权中担任要职，参与伪军策反与情报活动，战后一度被指为汉奸。；湖南东安人，受重庆方面派遣打入汪伪内部，但曾公开附逆任职，参与伪军与清乡事务，与湖南籍军政网络有联系，其活动涉及华中沦陷区包括湖南周边伪政权运作。；湖南东安人，受重庆方面派遣打入汪伪内部，但公开附逆任职，参与伪军策反与情报活动，战后被认定为潜伏人员。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1ae8df73d49348609fe3ac97ee6c713e','bb34b45b44c34a018d410cde66579fb1',1939,'汪伪政权武汉行营主任、伪湖北省长','湖北黄陂人，汪伪政权在华中地区的重要军事头目，其势力范围覆盖湖南北部，与常德地区日伪政权有协同，参与清乡与镇压抗日力量。；湖北人，其伪政权活动范围毗邻湖南北部，与湘北伪军、维持会有协作，参与对湖南沦陷区的伪化控制。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('38541726290d440ca927c87837389a6a','8bbed0a8fb2f49f29556f523a1e02e46',1943,'常德维持会会长','常德沦陷期间组织维持会，协助日军征粮、拉夫、维持治安，为日军占领常德提供地方支持。；常德沦陷期间出面组织维持会，为日军征集物资、维持占领区秩序，协助日军统治常德城区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e816e21fd1a744eeb5879c801a805fb8','0ce82afb041f4eb4a6fb886726d0274f',1943,'常德伪警察局局长','在常德沦陷区担任伪警察局长，配合日军搜捕抗日人员，镇压民众反抗，维持伪政权统治。；常德沦陷期间任伪警察局局长，协助日军维持治安，搜捕抗日人员，推行保甲连坐。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3e8c57c0ce8a4539b8c5dea0ddd95f2d','0806580d2c7a479e84a3ccdbd55c1bd4',1943,'常德县伪保安团团长','组织伪保安团，配合日军对常德周边地区进行扫荡，协助日军控制西洞庭湖区域。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4e33a89bd3b746b8bb9f4ce897e56270','5b3187957ade4aa1a703516923e040a3',1943,'西洞庭湖地区伪维持会会长','在西洞庭湖管理区域组织伪维持会，为日军征集船只、粮食，协助日军控制湖区交通。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e1d4a0674186460888bdd2678b33cdf0','27e6537284c34943908eefa10510ad18',1940,'伪湖南省政府委员','湖南人，在汪伪湖南省政府中任职，参与推行伪化教育、经济掠夺政策，其影响覆盖常德地区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8ce51f4c960246b49fe4cf71d8f2bbbd','49fe903b7e6f4d9a9ca4f4691be2d305',1941,'伪湖南清乡督办署督办','在湖南沦陷区负责清乡工作，配合日军对常德、益阳等地区进行清乡扫荡，镇压抗日武装。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9363dc37c49e4b03bbe074c13e752369','555a5637277447408f5f697f052d0c9d',1930,'土匪头目、伪军头目','湘西土匪，抗战期间投靠日军，在常德、桃源一带活动，配合日军袭扰抗日武装，残害百姓。；湘西土匪，抗战期间投靠日军，被委任为伪军头目，在常德、澧县一带活动，配合日军骚扰地方。；湘西土匪，抗战时期曾与日军勾结，在湘西及湘西北一带活动，其势力范围涉及张家界、桑植周边地区，配合日军骚扰抗日后方。；湘西龙山一带著名土匪，抗战时期曾与日伪势力勾结，接受伪军番号，在湘西地区从事劫掠和破坏抗日后方活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('744b37aa8e304cb395c5067b9d5fc8d2','a2e4190c87b449e685d78c118a6801b5',1938,'汪伪政权财政部长、伪行政院副院长','湖南沅陵人，汪精卫伪政权核心人物，参与对湖南地区的伪化宣传与渗透，间接影响常德、桃源一带的伪政权建设。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f43febe32c1b4fb2b95cf8fc927fb51e','4f19196006a34c1b88aeb20e5ccaacdb',1940,'汪伪政权军事委员会委员、伪清乡委员会负责人','湖南东安人，受蒋介石派遣打入汪伪内部，但公开身份为汉奸，在湖南及常德地区有活动记录，参与伪军策反与情报工作。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('12cd9f0dd0cd4d71bd3ea9e5ca84f646','27e6537284c34943908eefa10510ad18',1943,'常德维持会会长','常德会战期间，日军占领常德后组织维持会，协助日军维持治安、征发民夫、搜刮物资。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('129015b27eef49f88a326e0475d54fcf','51cc603628064bf99c4cc926d3628036',1943,'桃源县伪维持会会长','桃源沦陷期间，出面组织伪维持会，为日军征粮、派款、提供情报，协助日军控制桃源地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1e867572e6a34b688f0f2f8cbe173486','5b3187957ade4aa1a703516923e040a3',1943,'常德伪警察局局长','常德沦陷后投靠日军，担任伪警察局长，协助日军搜捕抗日人员，镇压民众反抗。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1aeec91283e74e29ab27b66298a3d012','16ced1fccdb945ecb3b2de2cd1815452',1943,'常德伪商会会长','常德沦陷期间，以商会会长身份与日军合作，强制商户缴纳“治安费”，为日军筹集物资。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fcafcd80076844168f8167e17ae785d4','82c8dc8c68f3449d85ce6770c252b411',1944,'桃源县伪保安团团长','组织伪保安团，配合日军扫荡桃源山区抗日游击队，抓捕抗日家属，罪行累累。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cefc962a330b4fc08c64bacfef9ae258','f229600d6b374711b33d2aa5a728b586',1943,'常德伪教育科科长','在常德推行奴化教育，强制学校使用日伪教材，宣传“大东亚共荣圈”，毒害青少年。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d76159bc29fb47758d927acc5b70113e','7afda6e05b9949d28074a369c144b4b0',1943,'常德伪保甲长','担任常德城区保甲长，为日军清查户口、举报抗日分子，协助日军征发劳工。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2105bb08b3db4090bf3e74235f531179','a2e4190c87b449e685d78c118a6801b5',1938,'汪伪政权行政院副院长、财政部长、警政部长、上海市长','湖南沅陵人，汪精卫伪政权核心人物之一，参与筹建汪伪政权，历任伪行政院副院长、财政部长、警政部长、上海市长等职，推行伪化统治，为日军侵华服务。；湖南沅陵人，汪精卫伪政权核心人物之一，参与对日投降与伪政权建设，推行伪财政与警政体系，镇压抗日力量。；湖南沅陵人，汪伪政权核心人物之一，参与对日投降与伪政权建设，虽主要活动于南京、上海，但作为湖南籍汉奸代表人物，其附逆行为对湖南沦陷区伪政权体系有示范与影响。','省部级/大军区级要员','hanjian');
