INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d26a1f123b8d4b88acb3a79b29c68bfa','bb34b45b44c34a018d410cde66579fb1',1939,'汪伪政权湖北省政府主席、伪武汉绥靖公署主任','湖北黄陂人，汪伪政权军事要员，曾任伪湖北省政府主席、伪武汉绥靖公署主任，其势力范围覆盖湘北、鄂南，与常德地区邻近，参与伪军扩编与清乡。','基层头目','hanjian');
