INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3f6ee39c5cf444e28f11fdece527b08a','b19edc2e16ec4c7d9462b01fbba0f27f',1944,'伪常德地区清乡专员','负责常德地区清乡工作，配合日军搜剿抗日武装，强迫民众登记良民证。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c543c5c6c02c43869bcaa1010fcfdcd8','b7f293e99cf84075a366c793be2d5dfa',1930,'土匪头目、伪军头目','湘西古丈、沅陵一带土匪，抗战时期与日军及伪政权有联系，在湘西北地区活动，其势力范围接近张家界、桑植地区，曾协助日军维持地方秩序并镇压抗日力量。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b1a0074ff2b04c1da18f6a0f930e40ca','c1c090acac0c4d3187a38fa05c27c910',1930,'土匪头目、伪军头目','湘西龙山、桑植一带土匪，抗战时期曾与日军勾结，在湘西北地区活动，其势力范围覆盖桑植周边，配合日军进行地方控制。；湘西龙山、永顺一带土匪首领，抗战时期曾与日伪方面有联系，接受伪军委任，在湘西地区扩张势力，对抗地方政府和抗日力量。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bc63e44b5a9344af90d45cbec0fd7c4c','638386aeca9244d89f7a35e47447920a',1930,'土匪头目、伪维持会头目','湘西永顺、桑植一带地方武装头目，抗战时期曾与日军合作，在桑植及周边地区参与维持会活动，协助日军征粮、拉夫。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ecd60c0522fe4b398f9c9b9b8dab55d6','521a9d06c75a41c7866bf8369dd53403',1930,'湘西地方军阀、伪政权合作者','湘西地方实力派，抗战时期曾与日军及伪政权有暧昧关系，其势力范围覆盖湘西包括张家界、桑植地区，在日军进攻湘西时未积极抵抗，部分部下投敌。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b6668033389d4b8c9e81ce0841b4e930','8c18f1191b834836b9580eb50464b3e8',1940,'伪军头目','原国民党军将领，抗战时期投降日军，在湖南地区组织伪军，其活动范围涉及湘西北，曾配合日军进攻湘西抗日根据地。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('12b9ec96e0cc4cd2bf19d1c615d0d2f1','a6971ee6071a440abebc19ede1080bd6',1940,'伪维持会会长','湖南地方士绅，抗战时期在湘西北地区组织维持会，协助日军管理地方，其活动范围涉及张家界、桑植周边地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c5848bbfee6d4932a461d4da804bc2be','6b298e69d53a43ca8ab997d236f7bc11',1940,'伪警察头目','湖南伪警察系统头目，抗战时期在湘西北地区协助日军维持治安，镇压抗日活动，其管辖范围涉及张家界、桑植一带。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7279826b484f4046acbad0ad9dfd4a0f','a5aec7ca1d314620b8797ac40b90f7cb',NULL,'未发现其担任伪职的可靠记载','经检索，张治中为抗日爱国将领，非汉奸，不应列入。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9facab5840f14c9794494e632175f0d7','0d2d2045fc1d498dab9499e43abcb3de',1940,'伪湖南省政府主席、伪上海市政府秘书长','湖南湘乡人，早年加入中国共产党后叛变，抗战期间投靠汪精卫伪政权，历任伪中央政治会议副秘书长、伪司法行政部部长、伪上海市政府秘书长、伪湖南省政府主席等职，参与推行伪化统治，为日军侵华服务。；湖南湘乡人，早年加入中国共产党后叛变，抗战期间投靠汪精卫伪政权，历任伪中央政治委员会委员、伪司法行政部部长、伪上海市政府秘书长、伪湖南省政府主席等职，参与推行伪化统治，为汪伪政权重要成员。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('50c57038c25a43659ad3313cd21b1834','4f19196006a34c1b88aeb20e5ccaacdb',1940,'伪湖南省政府委员、伪军委会委员','湖南东安人，抗战期间受蒋介石派遣打入汪伪政权内部，任伪湖南省政府委员、伪军委会委员等职，从事策反和情报工作，但其公开身份为汪伪政权要员，与湖南地区伪政权有直接关联。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2faad121fc564b19bc28dd79f42f0df7','bb34b45b44c34a018d410cde66579fb1',1939,'伪湖北省政府主席、伪武汉行营主任','湖北黄陂人，抗战期间投靠汪精卫伪政权，历任伪武汉行营主任、伪湖北省政府主席等职，在湖北、湖南北部地区配合日军进行伪化统治和清乡活动。','基层头目','hanjian');
