INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5ad8f5f1aa1349b9b866d73450f783f7','b7f293e99cf84075a366c793be2d5dfa',1945,'伪古丈县维持会会长','在古丈组织伪维持会，为日军筹粮、派夫，协助日军控制古丈地区，活动范围接近怀化、溆浦。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('efa6a5d714f94a23b612738fedf967fb','c11a15b507e9460f92ec1c924485d6f4',1945,'伪泸溪县维持会会长','在泸溪组织伪维持会，为日军提供物资和情报，协助日军维持占领区秩序，活动范围接近怀化、溆浦。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('263215a76a9c45fc80e7f15b90066174','bb2d064f8cb848f8a88812b079c416dd',1945,'伪辰溪县维持会副会长','协助舒伯韩组织伪辰溪县维持会，为日军征集物资、拉夫，并参与伪政权事务，活动范围接近怀化、溆浦。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bdfbd22eb75b474985e6edc28e37f9a1','97c6d09fa6f8464a8629257dbb67ebf4',1945,'伪沅陵县维持会副会长','协助张仲屏组织伪沅陵县维持会，为日军筹款、筹粮、派夫，并协助日军进行宣传，活动范围接近怀化、溆浦。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b3ced99a3e73454a8994b4deea0c9e79','ed066056d3fe4354a696cc0c8098841e',1945,'伪怀化县维持会副会长','协助李树森组织伪怀化县维持会，为日军提供粮秣、民夫和情报，协助日军控制地方，活动范围包括溆浦。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('25dfa669f4574ad0b6bb8d7b1925f8f5','8588ca8a02624b44a8d08163d89016ba',NULL,'无（非汉奸，历史误传需澄清）','无。彭德怀为八路军副总司令，抗日将领，与汉奸无关。此条仅为避免混淆而设，实际不应列入汉奸名录。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('67aa48f64bec42ceabf1570aa140c63b','a2e4190c87b449e685d78c118a6801b5',1938,'汪伪政权行政院副院长、财政部长、警政部长','湖南沅陵人，汪精卫伪政权核心人物之一，参与对日投降活动，推行伪化统治，搜刮沦陷区资源。其活动范围主要在南京、上海，但与湖南有籍贯关联。；湖南沅陵人，汪精卫伪政权核心人物之一，参与筹建汪伪政权，历任伪行政院副院长、财政部长、警政部长等职，推行伪化统治，为日军侵华服务。；湖南沅陵人，汪精卫伪政权核心人物之一，参与对日妥协与伪政权财政、警政事务，其活动主要在南京伪政权层面，与湖南有籍贯关联。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5db9b6b5ace6494c833f9d9b5672a4aa','4f19196006a34c1b88aeb20e5ccaacdb',1940,'汪伪政权军事委员会委员、伪清乡委员会负责人之一（后为军统潜伏人员）','湖南东安人，受蒋介石、戴笠派遣打入汪伪内部，表面任伪职，实际为重庆方面提供情报并策反伪军。其身份复杂，通常不被列为纯粹汉奸，但曾公开附逆任职。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('977408a9cbc54e41a2cd2f017b43d38d','bb34b45b44c34a018d410cde66579fb1',1939,'汪伪政权武汉行营主任、伪湖北省政府主席、伪陆军部长','湖北黄陂人，早年在湘鄂地区活动，抗战期间投靠汪精卫，任伪湖北省长等职，配合日军清乡、掠夺物资，其势力范围覆盖湘北、鄂南，与湖南邻近。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8e114a5fb45d4283acbca4bab3fcb0ff','072a989933af4ab191441098a6d8461b',NULL,'无（1931年前已死，非抗战汉奸）','无。张辉瓒为国民党军将领，1931年已死，与抗日战争汉奸无关。此条仅为避免误列。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b783aa2a660c45319e9ef2ff2aa508b3','0d2d2045fc1d498dab9499e43abcb3de',1939,'汪伪政权司法行政部长、伪安徽省长、伪上海市政府秘书长','湖南湘乡人，汪伪政权重要成员，参与伪政权行政与宣传，推行奴化教育，其活动虽主要在宁沪皖，但与湖南有籍贯关联。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c1cd723dcbb1482b93bb7b1ce7f37ff4','62a6d6c8e7ab4bbfbc92c5b14abbde74',1938,'汪伪政权立法院长、伪国民政府主席（继汪精卫后）','广东乳源人，汪伪政权二号人物，抗战期间全面附日，签署卖国条约，其伪政权统治范围包括华中、华南，对湖南沦陷区有名义管辖权。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f7f5f0c5b047477ea89ab23e15336464','07ff958e7f18410f864975f09234ac7e',1939,'汪伪政权特工总部主任、伪江苏省长','浙江遂昌人，汪伪76号特工头目，镇压抗日力量，其特务网络延伸至华中各地，包括湖南部分沦陷区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('de6fe28988284e9aac426ac075317d03','9910c48b9b394ffa8c73439ed0a473b0',1939,'汪伪政权特工总部主任、伪社会部长、伪浙江省长','湖南常德人，汪伪76号特工头目之一，参与镇压抗日志士，其籍贯与湖南直接相关，活动范围涉及华中沦陷区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('af718eac0d9641358eb5ca7835841b62','752a41642562417191e81157ce62fdec',NULL,'无（国民党湖南省主席，非汉奸）','无。何键为国民党湖南省政府主席，抗战初期主湘，后调离，未投敌。此条仅为避免误列。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('80052e27071a463d83244eb8d23e3e80','98ed2b5ac6e84c4888b2ae7bf3106ddc',NULL,'无（北洋时期湖南军阀，非抗战汉奸）','无。赵恒惕为北洋时期湖南军阀，抗战期间未任伪职。此条仅为避免误列。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1207b9798fc04440bf35cfc977c6f716','d1cfe7bd2c794cd6a4b01c9f3be744b3',NULL,'无（早期政客，非抗战汉奸）','无。彭允彝为湖南人，北洋时期政客，抗战前已退出政坛。此条仅为避免误列。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5cf7ce9525db44d4b4caec3ef5228198','3bf62702ed7f4f8891fc19d0ba99ce6f',1945,'伪靖县维持会会长（待考）','据靖州地方文史资料零星记载，1945年日军入侵湘西时，靖县（今靖州）曾出现维持会组织，有地方士绅被迫或主动出任维持会长，但具体姓名与事迹缺乏可靠档案，此名为待考示例，不应作为确证。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('78796027382e487c91e29c95ba0a7b66','50581fbac1324b869ea7a985cc40a582',1944,'伪怀化县维持会会长（待考）','怀化地区在1944-1945年日军进攻湘西时，部分县曾出现维持会，但地方志记载简略，具体负责人姓名多不可考。此条为示意，无确证。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c51fedeabb094daca0fe9dd125f71031','a2e4190c87b449e685d78c118a6801b5',1938,'汪伪政府行政院副院长、财政部长、伪上海市长','湖南沅陵人，汪伪政权核心人物之一，参与筹建汪伪政权，历任伪行政院副院长、财政部长、伪上海市长等要职，后与重庆方面暗中联络。；湖南沅陵人，汪伪政权核心人物之一，参与对日妥协与伪政权建设，活动重心在南京、上海，与株洲、攸县无直接关联。；湖南沅陵人，中共一大代表后叛变，抗战期间投靠汪精卫，成为汪伪政权核心人物之一。虽为湖南籍，但主要活动于南京、上海，与株洲石峰无直接地方关联。；湖南沅陵人，汪伪政权核心人物之一，参与对日妥协与伪政权建设；虽非株洲醴陵籍，但作为湖南籍汉奸代表人物，其伪政权人事网络覆盖湖南部分地区。；湖南沅陵人，汪伪政权核心人物之一，参与筹建汪伪政权，推行伪化统治，虽主要在南京、上海活动，但为湖南籍汉奸中职位最高者之一。；湖南沅陵人，中共一大代表后脱党，抗战期间投靠汪精卫，成为汪伪政权核心人物之一，历任伪行政院副院长、财政部长、伪上海市长等职，参与伪政权对沦陷区包括湖南部分地区的政治与经济控制。；湖南沅陵人，汪伪政权核心人物之一，参与筹建汪伪政权，掌握财政与特务系统，后与重庆方面暗中联系。；湖南沅陵人，汪伪政权核心人物之一，参与建立汪伪政权，历任伪行政院副院长、财政部长、伪上海市长等职，推行伪化经济与统治，其湖南籍贯及在湘人脉对湖南衡阳、南岳地区有一定影响。；湖南沅陵人，汪伪政权核心人物之一，虽主要活动于南京、上海，但作为湖南籍汉奸头目，其势力与影响覆盖湖南，与衡阳地区有间接关联。；湖南沅陵人，汪伪政权核心人物之一，参与对日妥协与伪政权建设；虽为湖南籍，但主要活动于南京、上海，与衡阳蒸湘无直接地方关联。；湖南沅陵人，汪伪政权核心人物之一，参与对日妥协与伪政权建设，虽非衡阳本地任职，但作为湖南籍汉奸代表人物，其伪政权体系对湖南沦陷区有间接影响。；湖南沅陵人，汪伪政权核心人物之一，参与对日妥协与伪政权财政、特务活动，后期与重庆方面暗中联络。；湖南沅陵人，汪伪政权核心人物之一，参与建立汪伪政权，推行伪化统治；其活动中心在南京、上海，与郴州、安仁无直接地方关联。；湖南沅陵人，汪伪政权核心人物之一，参与建立汪伪政权，推行伪化统治，虽主要在南京、上海活动，但作为湖南籍汉奸代表人物，对湖南沦陷区伪政权有间接影响。；湖南沅陵人，汪伪政权核心人物之一，参与对湖南等地的伪化宣传与渗透，后与重庆方面暗中联系。；湖南沅陵人，汪伪政权核心人物之一，参与对日妥协与伪政权建设，虽非直接在长沙、宁乡活动，但作为湖南籍汪伪要员，其伪政权体系对湖南沦陷区有影响。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0fb48027c7fc44389c1f59a54631839e','62a6d6c8e7ab4bbfbc92c5b14abbde74',1938,'汪伪政府立法院长、伪行政院长、伪国民政府代主席','湖南籍（祖籍湖南），汪伪政权第二号人物，随汪精卫投敌，历任伪立法院长、伪行政院长，汪精卫死后任伪国民政府代主席。；广东乳源人，汪伪政权二号人物。主要活动于南京、上海，与湖南株洲石峰无直接关联。；广东乳源人，原国民党左派，抗战期间随汪精卫投敌，历任伪立法院长、伪行政院长、伪国民政府代主席等职，为汪伪政权第二号人物，全面推行亲日卖国政策。虽非湖南籍，但其伪政权统治范围涵盖湖南沦陷区，与湖南有间接关联。；湖南籍（祖籍福建，生于广东，与湖南关联较弱），汪伪政权主要头目，抗战胜利后被处决。；湖南籍（祖籍湖南汝城，生于广东），汪伪政权主要头目之一，历任伪立法院长、伪行政院长、伪国民政府代主席，追随汪精卫叛国投敌。；广东乳源人，原国民党要员，抗战期间随汪精卫投敌，成为汪伪政权第二号人物，历任伪立法院长、伪行政院长、伪国民政府代主席等职，其伪政权统治范围涵盖华中沦陷区。；虽为广东籍，但作为汪伪政权最高层之一，其伪政权统治范围涵盖湖南沦陷区，对湖南地区伪政权运作有直接影响。；虽为广东籍，但作为汪伪政权核心头目，其伪政权统治体系覆盖湖南，衡阳、南岳地区伪组织亦受其统辖，属全国性汉奸头目，与湖南沦陷区伪政权有关联。；广东乳源人，汪伪政权核心人物，虽非湖南籍，但其伪政权统治体系覆盖包括湖南在内的沦陷区，间接影响衡阳地区。；广东乳源人，汪伪政权主要头目之一；与湖南衡阳无直接地方关联。；湖南籍祖籍，汪伪政权主要头目之一，继汪精卫后任伪国民政府代主席，推行亲日卖国政策，抗战胜利后被处决。；湖南籍祖籍背景，汪伪政权主要头目之一，追随汪精卫投敌，抗战胜利后被处决。；虽非湖南籍，但作为汪伪政权最高层之一，其伪政权任命体系覆盖湖南沦陷区，包括衡阳周边伪维持会与伪警察机构。；虽为广东人，但作为汪伪政权最高层之一，其伪政权统治范围覆盖湖南，战后以汉奸罪被处决。；湖南籍相关人物常被提及，原为国民党左派，后随汪精卫投敌，成为汪伪政权主要头目之一。；广东乳源人，汪伪政权主要头目之一，追随汪精卫叛国投敌，活动于南京、上海，与湖南郴州、桂阳无直接地方关联。；广东乳源人，汪伪政权主要头目之一；其伪政权体系覆盖华中、华南，湖南部分地区伪组织亦受其名义统辖，与郴州、永兴一带伪维持会、伪警察系统存在行政隶属关系。；广东乳源人，汪伪政权主要头目之一，其伪政权体系覆盖包括湖南在内的华中沦陷区，推行伪化政策，抗战胜利后被处决。；广东乳源人，汪伪政权第二号人物，虽非湘籍，但其伪政权统治覆盖湖南沦陷区，签署多项伪化湖南政令。；湖南籍？实际为广东乳源人，但长期在汪伪政权任要职，与湖南无直接关联，故不列入。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2f17ff276f6d498d899a8a8729723685','bb34b45b44c34a018d410cde66579fb1',1939,'汪伪政府陆军部长、伪湖北省长、伪武汉行营主任','湖北黄陂人，原国民党将领，投靠汪伪政权后任伪陆军部长、伪湖北省长等职，在华中地区配合日军清乡。；湖北黄陂人，非湖南籍，但在湖南邻近地区活动，曾参与伪军组织，与湘潭无直接关联。；湖北籍伪军头目，活动于武汉及周边，与湖南北部沦陷区伪军系统有联系，参与伪军扩编与治安强化。；湖北籍，汪伪政权军事头目，曾任伪陆军部长、伪湖北省长等职，其伪军活动范围涉及湘北、湘中，与湖南衡阳、南岳地区军事伪化有间接关联。；湖北黄陂人，汪伪政权军事要员，曾率伪军配合日军进攻湖南，其部队在湘北、衡阳外围有过活动。；湖北黄陂人，汪伪政权军事头目之一，在湖北、武汉地区活动；与湖南衡阳无直接关联。；湖北籍汉奸，其伪军体系曾向湖南北部渗透，与衡阳地区无直接任职，但属长江中游伪政权网络的一部分。；湖北人，汪伪政权军事要员，其伪军活动范围包括湖南北部，战后以汉奸罪被处决。；湖北黄陂人，汪伪政权军事头目，曾率伪军配合日军进攻湖南，其活动范围覆盖湘北、长沙一带，属于与长沙地区有直接军事关联的汉奸。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4c3464d6375d4107b5628cd617aead41','072a989933af4ab191441098a6d8461b',1944,'伪维持会头目（株洲地区）','株洲沦陷期间，出面组织伪维持会，为日军征集物资、拉夫，协助日军维持占领区秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2884e689608442bbb02134dca0ff1983','b915bf764cfc4afcb773979450337438',1944,'伪湖南省政府筹备人员（未就任）','湖南籍，抗战后期与日伪方面有接触，曾被日军考虑用于筹组伪湖南省政权，但因各方抵制未成。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a031cf6bcc1140898bcb5e7c4d35e6dd','a984f59d907348ba9abd26a16b473797',1944,'伪株洲维持会副会长','株洲本地士绅，日军占领株洲后出面组织维持会，任副会长，负责为日军筹粮、派夫。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1c8613b1f3e94f69bdfe668b5a08a904','51cc603628064bf99c4cc926d3628036',1944,'伪湘潭县维持会会长','湘潭地区士绅，日军侵占湘潭后组织伪维持会，任会长，协助日军统治地方。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('57312c10baa04cccbf0c7bf2ccddf47a','ea8df813a660484d99c916c7bbdab326',1944,'伪长沙维持会成员','长沙沦陷期间参与伪维持会活动，为日军筹办物资、维持治安。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('921db32cb7234414b0061c96b38a2343','3bf62702ed7f4f8891fc19d0ba99ce6f',1944,'伪衡阳维持会会长','衡阳沦陷后出面组织伪维持会，任会长，配合日军管理占领区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bb30ed709d094690be79b6e08605fff7','62a6d6c8e7ab4bbfbc92c5b14abbde74',1938,'汪伪政府立法院长、伪国民政府代主席','广东乳源人，汪伪政权主要头目之一，活动于南京、上海，与湖南株洲、攸县无直接关联。；湖南籍贯无直接关联，但作为汪伪政权头目之一，其伪政权体系在湖南设有省级伪组织，间接影响包括株洲、醴陵在内的湖南沦陷区。；虽为广东籍，但作为汪伪政权最高层之一，其伪政权体系覆盖湖南沦陷区，影响包括衡阳在内的华中地区。；广东乳源人，汪伪政权主要头目之一，追随汪精卫叛国投敌；活动范围主要在南京、上海，与湖南郴州、安仁无直接关联。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5ad0d21d9ce547258a22e1c94fc13824','86e982eb4f0043c4b6f7b586ec525f98',1940,'伪湖南省政府主席、伪武汉行营参议','湖南长沙人，曾任伪湖南省政府主席，参与日伪在湖南的统治，活动范围覆盖长沙及周边，与株洲、攸县地区有间接关联。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0aad450afbbe4740bdd6524073630b3a','e7ec243906d4478082206f56be9b96f0',1940,'伪湖南省政府委员、伪长沙市市长','湖南长沙人，在日伪占领长沙期间任伪职，协助日军维持地方秩序，活动范围以长沙为中心，与株洲、攸县有地域邻近关联。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('80970c3c89474513ac1e5440ef46162e','5b3187957ade4aa1a703516923e040a3',1944,'伪攸县维持会会长','攸县本地人，1944年日军侵占攸县期间出面组织维持会，为日军筹粮、派夫、维持地方秩序，属当地直接附逆者。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8f2939afc3284d208c8a676b12a6e68f','9fe3aaab3f60429a814c322a3813de79',1944,'伪攸县保安队队长','攸县本地人，日军占领期间任伪保安队头目，协助日军搜捕抗日人员、征发民夫，具体姓名在地方史料中记载不全。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8b7e6d7d563542259052d8f44bb71dc8','a6f0e540ef124f969ab954d43bf9a6dd',1944,'伪株洲维持会副会长','株洲本地人，1944年日军侵占株洲期间任伪维持会副会长，协助日军管理地方事务，与攸县有地域关联。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('62a7de8c8e0f4745b8a76dbbecd38a13','56c4c32706894486b51dcd99fc67aaaa',1944,'伪湘潭县维持会会长','湘潭人，日军占领湘潭期间任伪维持会会长，活动范围与株洲、攸县邻近，属湖南地区附逆者。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b682df7da2384bec850a589dfff7325b','4f19196006a34c1b88aeb20e5ccaacdb',1940,'汪伪政府军事委员会委员、伪清乡委员会驻苏州办事处主任（后为军统潜伏人员）','受重庆方面派遣打入汪伪政权，在湖南及周边地区活动，曾参与伪政权军事事务，但其身份具有双重性，常被列为特殊案例。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bc07d15f95b94bc3a161fce5854a7ed4','bb34b45b44c34a018d410cde66579fb1',1939,'汪伪政府武汉行营主任、伪湖北省政府主席','在湖北、湖南北部一带活动，组织伪军配合日军进攻湖南，对湘北地区造成破坏。；湖北黄陂人，早年曾在湖南任职，抗战期间投靠汪精卫，任伪武汉行营主任、伪湖北省政府主席等职，在湖北、湖南北部地区配合日军进行清乡、征粮、镇压抗日力量。其活动范围覆盖湘北，与湖南有直接关联。；湖北黄陂人，原国民党将领，投靠汪伪后任伪武汉行营主任、伪湖北省政府主席等职，在湖北湖南交界地区进行伪化活动，对湘潭地区有间接影响。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6c7b82bdde9b44bb886ad623fcb19fc1','63e8ad6773624d45b1a7e6dc11c6b2bf',1944,'伪湖南省政府参议（未就任，仅被日方列入名单）','日军进攻湖南时，曾被日方胁迫或列入伪政权名单，但实际未履职，历史记载存疑。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b1a3717aa210468c99a5d805a7bed0d1','a976a94be0bf4b76b621948c0802222f',1937,'伪湖南省政府主席（未实际到任）','北洋旧军阀，抗战初期与日方接触，被日方考虑为伪湖南省长人选，后在北平被刺杀。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('49ed60deed724149973aad07a44a959d','4315c7ab1a664e6b902019849fdb5b46',1944,'伪维持会会长（株洲地区）','日军占领株洲期间，出面组织维持会，为日军征粮、拉夫，协助维持占领秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cadbd609734242759442ab951846686e','a717543fb24f409895a297a2c48d24ee',1944,'伪株洲维持会副会长','协助彭佐熙管理株洲地区伪维持会事务，为日军提供情报和物资。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f08f7739750e406d95c619db5d41e200','a6f0e540ef124f969ab954d43bf9a6dd',1944,'伪渌口保甲长（日占时期）','日军占领渌口期间，担任保甲长，为日军摊派粮款、登记户口，协助控制当地居民。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('690a69cc2fb5497891b8b540df63dcf6','f9df36b7b43241b097e1d47e9f808e6e',1944,'伪湘潭县维持会会长（管辖渌口一带）','在湘潭、渌口地区组织伪维持会，为日军征集物资，协助日军扫荡。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e6c1d4e0a05d401b946af60cf7ff0ee2','a2e4190c87b449e685d78c118a6801b5',1940,'汪伪政府财政部长、伪行政院副院长','湖南沅陵人，汪伪政权核心人物，参与伪政权决策，其活动范围涉及湖南，对湖南沦陷区有间接影响。；湖南沅陵人，汪伪政权核心人物之一，虽主要活动于南京、上海，但作为湖南籍汉奸代表人物，其伪政权体系对湖南沦陷区有影响。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('04f45a50248641c9bbc830df2d873a00','07ff958e7f18410f864975f09234ac7e',1939,'汪伪特工总部主任、伪江苏省政府主席','浙江人，但在湖南有特务活动网络，其伪特工组织在湖南沦陷区发展线人，迫害抗日人士。','特工总部主任','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('feec81c5aa5c434cbd27b7aaf1b13f6d','0d2d2045fc1d498dab9499e43abcb3de',1938,'汪伪政府司法行政部长、伪安徽省长','湖南湘乡人，汪伪政权要员，参与伪政权统治，对湖南沦陷区有政治影响。；湖南湘乡人，汪伪政权要员，虽主要活动于南京、安徽，但作为湖南籍汉奸，其伪政权活动对湖南沦陷区有间接影响。；湖南湘乡人，汪伪政权重要成员，曾任伪边疆委员会委员长等职，在南京、安徽等地推行伪化政策。；湖南湘乡人，早年加入中共后脱党，抗战期间投靠汪伪，历任汪伪政府司法行政部长、伪安徽省长等职，参与汪伪政权对华中沦陷区的行政控制。；湖南湘乡人，汪伪政权成员；虽为湖南籍，但主要活动于南京、安徽，与衡阳蒸湘无直接地方关联。；湖南湘乡人，汪伪政权重要成员，虽主要在安徽、上海活动，但作为湖南籍汉奸，其伪政权网络对湖南沦陷区有间接影响。；湖南湘乡人，汪伪政权重要成员，参与伪政权统治，战后以汉奸罪被判刑。；湖南湘乡人，汪伪政权重要成员，参与伪政权统治；其活动主要在南京、安徽等地，与郴州、安仁无直接关联。；湖南湘乡人，汪伪政权重要成员，历任伪职，参与伪政权行政与宣传。；湖南湘乡人，汪伪政权成员，参与伪政权对湖南等地的司法与行政伪化，与长沙有籍贯关联。；湖南湘乡人，汪伪政权要员，参与伪政权司法与地方行政，后随周佛海与重庆联络。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ab7622c3d15d4823aaa2e18dd4ad51a3','9a6ddf69575e488480603c12171ac907',1944,'伪湖南省政府委员（未实际到任）','被日方列入伪湖南省政府名单，但未实际赴任，历史记载有限。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9fee0885dc6248028bb09594263d0321','d251a9f00be546a2b753af31b3a9f1c7',1944,'伪湖南省政府主席（未就任）','唐生智之弟，被日方考虑为伪湖南省长人选，但未实际就任，后逃往香港。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6598086794d84d60a7f3192adb413418','4f19196006a34c1b88aeb20e5ccaacdb',1940,'汪伪政府军事委员会委员、伪江苏省保安司令（后为军统潜伏人员）','湖南东安人，唐生智之弟。抗战期间受蒋介石、戴笠派遣打入汪伪政权，表面任伪职，实际从事策反和情报工作。其活动范围主要在南京、上海及江苏，与湖南株洲石峰无直接关联，但在湖南籍伪职人员中影响较大。；湖南东安人，奉蒋介石、戴笠之命打入汪伪政权，表面任伪职，实为军统潜伏，并非真正附逆，但曾在汪伪系统中活动，与湖南籍人员有联系。；湖南东安人，奉蒋介石、戴笠之命打入汪伪政权，表面任伪职，实际从事策反与情报工作；其活动范围涉及湖南籍军政关系网，但与醴陵无直接任职关联。；湖南东安人，奉蒋介石、戴笠之命打入汪伪政权，表面任伪职，实际从事策反与情报工作；其活动与湖南籍人员网络有关，但主要活动不在衡阳蒸湘。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ef3075f848384607b2c59e0b70f7c07f','07ff958e7f18410f864975f09234ac7e',1939,'汪伪特工总部（76号）主任、伪江苏省主席','浙江遂昌人，生于湖南？无直接株洲关联。汪伪特务头目，活动于上海、南京、江苏，与湖南株洲石峰无直接关联。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('26c15e6ef0bd40ae981da1d53848e533','8588ca8a02624b44a8d08163d89016ba',NULL,'',NULL,'无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('620991c6660046c38e91471dd3b92810','9ae6eccb18f742c48121a5642338f5d2',1944,'株洲维持会会长/保甲长','1944年日军发动豫湘桂战役，占领株洲（当时为湘潭县株洲镇，今株洲市石峰区一带属之）。当地曾出现维持会组织，协助日军征粮、拉夫、维持治安。具体姓名因地方档案散失，难以确证。','基层帮凶(维持会系统)','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e16a191a78a1459490ab2d971f085deb','74aa3714ecff454aaefc46fe3cec22a9',1944,'伪湘潭县知事/维持会长','株洲石峰地区当时属湘潭县管辖。日军占领湘潭后，曾扶植伪湘潭县政权，部分士绅附逆。具体姓名缺乏可靠记载。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('13e3475f79f149c4bcd6206fb025800c','9fd9fdcdceab41cfa174d0e84dff8d12',1944,'伪长沙维持会/伪长沙市政府人员','长沙沦陷期间（1944-1945），日伪曾组织维持会及伪政权。株洲石峰距长沙较近，部分人员可能跨区域活动。具体姓名缺乏可靠记载。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7eb9f2e836c245bbbcb7d7cd4cfb6035','4f19196006a34c1b88aeb20e5ccaacdb',1940,'汪伪政府军事委员会委员、伪江苏省保安副司令（后为潜伏策反人员）','湖南东安人，奉蒋介石、戴笠之命打入汪伪政权，表面附逆，任伪职，实为军统潜伏人员，抗战后期策反汪伪军政人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c08a069d5f3f4dc8b2699fbecc12fa60','a2e4190c87b449e685d78c118a6801b5',1938,'汪伪政府行政院副院长、财政部长、警政部长','湖南沅陵人，汪伪政权核心人物之一，参与建立汪伪政权，推行伪化统治，后与重庆方面暗中联系。；湖南沅陵人，汪伪政权核心人物之一，参与筹建汪伪政权，推行伪化统治。虽非永州零陵籍，但为湖南籍汉奸代表人物，其伪政权活动覆盖湖南沦陷区。；湖南沅陵人，汪伪政权核心人物之一，参与筹建汪伪国民政府，掌管财政、警政与特务系统，对包括湖南在内的沦陷区实施伪化统治。；湖南沅陵人，汪伪政权核心人物之一，参与筹建伪政权，掌管财政、警政与特务系统，对包括湖南在内的沦陷区伪组织有影响。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b7ef3b182f2644a5b468e8fc68829664','bb34b45b44c34a018d410cde66579fb1',1939,'汪伪政府湖北省主席、伪武汉行营主任','湖北人，汪伪高级军政人员，其伪军活动范围曾扩展至湘北、湘中，对湖南沦陷区伪政权有影响。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d949c7b6c9ab47999bbc8ac31e299f1a','0d2d2045fc1d498dab9499e43abcb3de',1939,'汪伪政府安徽省长、伪上海市政府秘书长','湖南湘乡人，汪伪政权重要成员，参与伪政权行政与警政，其活动与湖南籍伪政权人员网络有关联。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0b71a5462c5a4ce693ca9dd39e0a3e3c','86e982eb4f0043c4b6f7b586ec525f98',1938,'伪广州市长、伪广东警务处长','湖南人，汪伪政权在广东的重要人物，其伪警政体系与湖南籍附逆人员有联系。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7e7e8ed2b21d4f4dbb1f024d3b15fd8d','a1442e252a78480888f49fee68c84d90',1944,'伪湖南省政府委员、伪长沙市长（日占时期）','在日军占领长沙期间，参与伪政权维持会与伪市政府事务，协助日军征粮、征夫，镇压抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9caca5d1795643c1a282e6fb73db5c78','d8a506cb85374775a0320c3a2d257ec0',1944,'伪湘潭县维持会会长','日军占领湘潭后，出面组织维持会，为日军筹集物资、拉夫，协助伪化统治，影响波及株洲一带。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('76695e2e729f498ebc268a97bc80aabf','829c426c69154239b05da79e9a0c6194',1944,'伪株洲维持会会长（姓氏可考，名字记载不全）','日军侵占株洲后，出面组织地方维持会，协助日军维持治安、征发民夫与粮食，具体名字在地方档案中记载不全。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('caaa4ed44a3a4c1db8daf923e797d579','0f2681a2038a450393ad8f205602e6f4',1944,'伪芦淞地区保甲长（日占时期）','在株洲芦淞一带担任伪保甲长，为日军征粮、派夫，监视居民，协助伪政权控制基层。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('059ab7bc2eff45cf86e508a2c66a0311','e239249c0d8a4419a20d5c4b67707e0e',1944,'伪长沙县维持会副会长','在长沙沦陷期间，协助日军组织伪政权，参与征粮、征夫，镇压抗日群众，其活动范围包括株洲北部。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('776ce17f20f5452b8f80157f54813128','e6341b2d323245069ae9e88b332806bc',1944,'伪湘潭县警察局长（日占时期）','在日军占领湘潭期间，担任伪警察局长，协助日军搜捕抗日人员，维持伪治安，影响株洲地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('823c525bc28f4fcdabcdd206c7e98345','bb34b45b44c34a018d410cde66579fb1',1939,'汪伪政府武汉绥靖公署主任、伪湖北省长','湖北人，汪伪政权在华中地区的重要军事头目，其伪军活动范围包括湘北、鄂南，与湖南北部沦陷区有军事联系。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('30f9a0fc19c4489ebe361a04c7eb8ede','a976a94be0bf4b76b621948c0802222f',1933,'伪华北政务委员会顾问、日伪拉拢对象','湖南人，北洋旧军阀，九一八后与日本特务勾结，企图在华北组织伪政权，1933年被军统刺杀。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6377fad595eb479cb21ff3d9f974ae0c','4315c7ab1a664e6b902019849fdb5b46',1944,'伪湖南省政府委员、伪长沙市长','在日军占领长沙期间，出任伪职，协助日军维持长沙地区治安与伪化统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('26ead1b57af5465da57b02ec181b0d7b','b0029840ecbd4ef8b36226ecba81c9bc',1944,'伪湖南省政府主席兼伪保安司令','日军发动豫湘桂战役占领湖南大部后，被日军扶植为伪湖南省政府主席，在长沙等地推行伪化统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f4c30426275745aa9a83963c639f0067','d251a9f00be546a2b753af31b3a9f1c7',1944,'伪湖南省政府委员、伪长沙县长','湖南本地人，日军占领长沙后出任伪职，协助日军征粮、拉夫，维持伪政权基层统治。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9000d670d9e04a368908ced3aceac822','c3cdcc713fc04667a4ac1f2f7c0fc40e',1944,'伪湘潭县维持会会长','日军占领湘潭后，组织维持会，为日军筹粮、派夫，协助日军控制湘潭地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a15c70b39aff408b9ddc1043241fff44','cbaf785da5ae45159f8f160436ea6d7f',1944,'伪株洲维持会会长','日军占领株洲后，出面组织维持会，为日军提供物资、情报，协助维持株洲地区伪秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1e706665032b4c27aacb04ca8f0683cb','7abf5ed8188e4848af95f18a9049d4a9',1944,'伪茶陵县维持会会长','日军侵入茶陵期间，组织维持会，为日军筹粮、带路，协助日军在茶陵地区的统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8ca6cfd4eb03423c969fd501d5f3cc88','d4ba98c1b9b040a092573e45f7e7ef8f',1944,'伪茶陵县保安大队长','茶陵本地人，日军占领期间出任伪保安大队长，率伪军配合日军扫荡，镇压抗日力量。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a4dfc625429f4ffa9f5dee77f7d1e0c8','51cc603628064bf99c4cc926d3628036',1944,'伪醴陵县维持会副会长','日军占领醴陵后，参与组织维持会，为日军征粮派款，协助伪化统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6e9ad8a85c72400d9d76022a38c4c44f','ea8df813a660484d99c916c7bbdab326',1944,'伪长沙县保安团团长','在日军占领长沙期间，率部投敌，编为伪保安团，配合日军维持治安、清乡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('04ce476544224649b57d6b5e77430517','8af75c63d4ac48f8a4a24a2ebdedf700',1944,'伪湖南省政府参议、伪长沙商会会长','长沙商界人物，日军占领后出面组织商会，为日军筹款筹物，协助经济掠夺。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bc2e9204ee3740ef80f6ac4cfdbc136f','001965440f974d71bbc48c2f5215d1ac',1944,'伪湖南日报社长','在长沙沦陷期间，主办伪报纸，为日军进行宣传，鼓吹“大东亚共荣圈”。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dec3ea62c0474404aaa63ec916eeec4b','a2e4190c87b449e685d78c118a6801b5',1940,'汪伪政府财政部长、伪中央储备银行总裁','湖南沅陵人，汪伪政权核心，其财政金融政策覆盖湖南沦陷区，发行伪币，掠夺物资。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3b7dcce3ddd4431db53c1ed42ab20401','4f19196006a34c1b88aeb20e5ccaacdb',1943,'伪湖南省政府主席兼伪保安司令','抗战后期受重庆方面派遣潜入汪伪政权，任伪湖南省政府主席等职，表面附逆，实际从事策反与情报工作，其活动范围覆盖湖南全省，包括株洲地区。；原为国民党将领，后投靠汪伪政权，任伪湖南省政府主席，在湖南地区协助日军维持统治，镇压抗日活动。；湖南东安人，受重庆方面指派潜入汪伪，但公开出任伪湖南省主席，在湖南沦陷区建立伪政权，益阳、安化一带伪组织受其节制。；原国民党将领，后投靠汪伪政权，任伪湖南省政府主席，在湖南地区协助日军维持占领秩序，推行伪化统治。；原国民党将领，1943年投靠汪伪政权，任伪湖南省政府主席、伪保安司令等职，在湖南地区协助日军维持占领秩序，1945年后被蒋介石重新收编。；抗战后期受重庆方面派遣潜入汪伪政权，任伪湖南省政府主席等职，表面附逆，实际从事策反与情报工作；其活动范围覆盖湖南衡阳、耒阳一带，是湖南沦陷区伪政权最高头目之一。；抗战后期受重庆方面派遣潜入汪伪政权，任伪湖南省政府主席、伪保安司令等职，在湖南地区活动，与郴州、资兴一带的伪政权运作有间接关联。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a559bb83bfae48f5a945d5d72cf6ac6a','e7ec243906d4478082206f56be9b96f0',1944,'伪株洲维持会会长','日军侵占株洲后出面组织伪维持会，协助日军征粮、派夫、维持治安，为当地主要附逆人物之一。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('801df8d0960b40799541e69ff2ebd4ed','00fb5a90028d4fa9876c1d2a55217c0a',1944,'伪湘潭县维持会副会长（株洲时属湘潭）','在湘潭及株洲一带协助日军建立伪政权，参与征发民夫、物资，镇压抗日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9cedac88f38c430fb714c7108db3a558','51cc603628064bf99c4cc926d3628036',1940,'伪湖南省政府委员兼伪警务处长','在汪伪湖南省政府中任职，负责伪警察系统，配合日军在湖南各地包括株洲地区进行治安强化与搜捕抗日人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('647efeb256f448508a4c3c7da8d82ab9','d8a506cb85374775a0320c3a2d257ec0',1944,'伪长沙县维持会会长','日军第四次长沙会战期间组织伪维持会，其势力范围波及株洲北部地区，协助日军维持占领秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d043b2fac69c4bf8a9aeece655c238aa','ea8df813a660484d99c916c7bbdab326',1944,'伪湖南和平救国军司令','在湖南沦陷区收编散兵游勇组成伪军，配合日军在株洲、湘潭一带进行扫荡与清乡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4621f58a5356401cb1b2434b5bd58314','a717543fb24f409895a297a2c48d24ee',1944,'伪株洲警察所所长','日军占领株洲后出任伪警察头目，带领伪警察搜捕抗日分子、勒索民众，直接服务于日军驻株洲部队。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('99f7c19c7bee474d9d6510673586afc9','a6f0e540ef124f969ab954d43bf9a6dd',1944,'伪荷塘乡保长','在株洲荷塘地区担任伪保长，为日军征粮派款、提供情报，是当地基层附逆者的典型代表。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9927e4e661d74d4495d5673f9cd778ff','86e982eb4f0043c4b6f7b586ec525f98',1944,'伪湖南省政府主席（汪伪政权任命）','汪伪政权在湖南沦陷区设立伪省政府，李讴一被任命为伪湖南省长，负责配合日军维持占领区秩序，其伪政权覆盖长沙、株洲、醴陵等湘东地区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f713f72c2bee41dda95b40e7ed9c5283','a1442e252a78480888f49fee68c84d90',1944,'伪湖南省政府委员、伪长沙市维持会会长','长沙沦陷后出面组织维持会，协助日军征粮、拉夫、维持治安，其活动范围包括长沙周边及湘东株洲、醴陵一带的伪政权运作。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f9d731c6e95a43b4bddb6a08836bd3b7','bb34b45b44c34a018d410cde66579fb1',1939,'伪湖北省政府主席、伪军事委员会武汉行营主任','湖北籍汉奸，但其伪军活动曾延伸至湘北、湘东，与湖南沦陷区伪政权有联络，间接影响株洲、醴陵地区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8cf61cbaa2b4458e81a002c533fb9bf2','a976a94be0bf4b76b621948c0802222f',1932,'北洋旧军阀，后投靠日伪（未及正式任职即被刺）','湖南籍旧军阀，1933年与日伪勾结企图在华北组织伪政权，被军统刺杀；其湖南关系网涉及株洲、醴陵地方势力。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('79d2156bf1a6464fb0fab52f5dc4d9d9','4315c7ab1a664e6b902019849fdb5b46',1944,'伪醴陵县维持会会长（地方维持会头目）','1944年醴陵沦陷后，出面组织地方维持会，为日军征派粮食、民夫，协助维持占领区秩序，是醴陵本地附逆代表人物。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('30a961279f1c4134828e249d69b89ddc','b915bf764cfc4afcb773979450337438',1944,'国民党将领，后一度与日伪接触（未正式投敌）','湖南醴陵人，抗战后期在湘东地区与日伪有暧昧接触，但未正式出任伪职；其部属中有个别投敌者，影响醴陵一带。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f2233259694b4300b6a8567605502744','ea8df813a660484d99c916c7bbdab326',1944,'伪株洲维持会副会长','株洲沦陷期间，协助日军在株洲镇及周边地区建立伪维持会，负责摊派捐税、征集物资，是株洲本地附逆者之一。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bdf573b46b32432886ec3151bd7a22a9','8af75c63d4ac48f8a4a24a2ebdedf700',1944,'伪湖南省政府参议、伪湘东维持会联络员','在湘东地区为伪湖南省政府与日军之间联络，活动范围包括株洲、醴陵、浏阳一带，协助伪政权推行保甲连坐。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1f6b6212375f447395897fa4249f0a1a','a6f0e540ef124f969ab954d43bf9a6dd',1931,'无汉奸记录（仅列名以说明醴陵籍将领未附逆）','醴陵籍抗日将领，坚持抗战，无附逆行为；此处仅作对照，不属汉奸名录。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6de3fe532ea84ff8b059cb8a5346404e','e7ec243906d4478082206f56be9b96f0',1944,'伪永州维持会会长','日军侵占永州后，出面组织伪维持会，为日军征粮拉夫，协助建立伪基层政权。；日军侵占永州期间，出面组织伪维持会，协助日军征粮、派夫、维持地方秩序，为日军侵略服务。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('79d93370f96d439b9d30fd771c297a17','71f81d6984764b0489599d7e1bf7d950',1944,'伪零陵县县长','在日军占领零陵期间出任伪县长，推行伪化教育，配合日军清乡，搜捕抗日人士。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('589da3ba467d4a4a91c2308c65ef060a','a2e4190c87b449e685d78c118a6801b5',1940,'伪行政院副院长兼伪财政部长、伪湖南省长','汪伪政权核心人物，曾兼任伪湖南省长，其势力影响湖南沦陷区，推行伪化经济与治安政策。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('47badae3f9f5423dbb8a5980aa933a14','51cc603628064bf99c4cc926d3628036',1944,'伪永州警察局局长','在永州沦陷期间担任伪警察头目，协助日军维持治安，逮捕抗日分子，勒索民众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('094c3d3bb68043acb167cd333efeece7','b19edc2e16ec4c7d9462b01fbba0f27f',1944,'伪湘南保安团团长','原为地方武装头目，后投靠日军，任伪保安团长，在永州、衡阳一带配合日军扫荡抗日游击队。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4eb1ab224c21494fbac591fc71e155e8','a717543fb24f409895a297a2c48d24ee',1944,'伪零陵县维持会副会长','协助黄子琪组织伪维持会，负责摊派粮款，为日军提供情报，迫害抗日家属。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('81532e3f17d24baba8de4b94c565ebda','a6f0e540ef124f969ab954d43bf9a6dd',1944,'伪永州商会会长','在日军占领永州后，出面组织伪商会，为日军筹款筹物，协助经济掠夺。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('328399abfb124e0b819bbd33f7f73158','a5aec7ca1d314620b8797ac40b90f7cb',1940,'伪湖南省教育厅督学','在汪伪政权下负责湖南沦陷区教育，推行奴化教育，篡改教材，宣传“大东亚共荣”。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0e376d0d7ecf4f29a24c5436f75e655e','752a41642562417191e81157ce62fdec',1944,'伪湘南道尹','日军在湘南设立伪道尹公署，何键出任道尹，管辖永州、郴州等地伪政权，配合日军征丁征粮。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9d53f9e3b8614f3e95870b1a2f415571','4f19196006a34c1b88aeb20e5ccaacdb',1940,'汪伪政府军事委员会委员、伪清乡委员会副秘书长','湖南东安人，原国民党将领，后受蒋介石、戴笠派遣打入汪伪政权，任汪伪军事委员会委员、伪清乡委员会副秘书长等职，在沦陷区活动，与永州东安有籍贯关联。；湖南东安人，奉蒋介石之命打入汪伪政权，表面附逆，曾任伪军事委员会委员等职，在湖南及衡阳一带有活动关联，但实为重庆方面潜伏人员。；湖南东安人，奉蒋介石、戴笠之命打入汪伪政权，表面附逆，任伪军事委员会委员、伪清乡委员会副秘书长等职，在沦陷区活动，与湖南郴州、桂阳地区无直接地方任职记载，但属湖南籍汪伪要员。；湖南东安人，奉蒋介石、戴笠之命打入汪伪政权，表面附逆，任汪伪军事委员会委员、伪清乡委员会副秘书长等职，在沦陷区活动，与湖南郴州、汝城无直接活动记录，但属湖南籍附逆人员中影响较大者。；湖南东安人，奉蒋介石、戴笠之命打入汪伪政权，表面附逆，历任伪军事委员会委员、伪清乡委员会副秘书长等职，在长沙、湖南一带与日伪周旋，实为军统潜伏人员。；湖南东安人，受重庆方面派遣打入汪伪政权，在南京、上海等地活动，曾参与伪清乡事务，与湖南方面有联系，但其身份具有双重性，战后被认定为潜伏人员。；湖南东安人，受重庆方面派遣打入汪伪政权，在南京、上海等地活动，曾参与伪政权军事与清乡事务，与湖南籍军政人物联系密切。；湖南东安人，奉蒋介石、戴笠之命打入汪伪政权，表面附逆，历任伪军事委员会委员、伪清乡委员会副秘书长等职，在长沙、湖南一带为军统搜集情报并掩护抗日人员，抗战胜利后恢复国军身份。；湖南东安人，奉蒋介石、戴笠之命打入汪伪政权，表面附逆，任伪职，负责联络伪军将领，后回归重庆方面。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('58b4e1855a224eb0a390eb08927969b0','f9df36b7b43241b097e1d47e9f808e6e',1944,'伪永州维持会会长','日军侵占永州期间，出面组织伪维持会，协助日军征粮、派夫、维持地方秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bf75773425df4be1b951f7355eac3311','6afc4fc140684314b362906c653ff04b',1944,'伪零陵县维持会会长','零陵沦陷后，组织伪维持会，为日军筹粮、拉夫，协助日军统治地方。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fdb2ec152bbe4afd9abf8c4b54a79a37','a717543fb24f409895a297a2c48d24ee',1944,'伪衡阳维持会会长','衡阳沦陷后，组织伪维持会，协助日军管理地方，征调民夫、粮食。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3fa5c1e615f246f4bc1795c523f9f942','b19edc2e16ec4c7d9462b01fbba0f27f',1944,'伪湘南保安司令','日军侵占湘南后，投靠日军，组织伪军，配合日军扫荡抗日武装。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7b98a1d4f9144a52aa05a4578f2b45b6','a5aec7ca1d314620b8797ac40b90f7cb',1944,'伪长沙维持会副会长','长沙沦陷期间，参与伪维持会，为日军筹款筹粮，协助维持殖民统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('06e539f1d86d4ee99dc465bb00e42754','4f19196006a34c1b88aeb20e5ccaacdb',1940,'伪湖南省政府委员、伪长沙市长（后为军统潜伏人员）','受军统派遣打入汪伪政权，曾任伪湖南省政府委员、伪长沙市长等职，表面附逆，实际从事潜伏情报工作。其活动范围覆盖湖南多地，与永州地区有间接关联。；受军统派遣打入汪伪政权，曾任伪湖南省政府委员、伪长沙市长等职，表面附逆，实为重庆方面提供情报并策反伪军。因具有潜伏性质，历史评价复杂。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c81872a270564c5f99b4d136cbaa1021','6afc4fc140684314b362906c653ff04b',1944,'伪零陵县维持会副会长','零陵沦陷后，参与组织伪维持会，协助日军推行保甲制度、征收物资，镇压抗日活动。零陵与双牌地域相邻，其活动范围覆盖双牌周边。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('efed8054ee4840de92864a198fd541f9','62a6d6c8e7ab4bbfbc92c5b14abbde74',1938,'伪立法院长、伪行政院长、伪国民政府代主席','汪伪政权主要头目之一，其伪政权体系覆盖湖南沦陷区，永州地区伪政权亦受其名义管辖。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ea5bacc137004b67bebee4103facebf5','df03712788eb443e8650b5d1c61df460',1944,'伪双牌维持会保甲长','双牌本地人，日军侵占期间出任伪保甲长，协助日军征粮、派夫、搜集情报，压迫当地民众。','基层帮凶(维持会系统)','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8373ef14c2fa49e7a0d4f7893493fcd4','b915bf764cfc4afcb773979450337438',1944,'伪永州地区伪军头目','永州沦陷后，收编地方武装投靠日军，任伪军大队长，配合日军扫荡抗日游击队，活动于永州、双牌一带。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('edfc1428108642bcaff1e147852f1a43','0d2d2045fc1d498dab9499e43abcb3de',1940,'汪伪政府安徽省省长、伪上海市政府秘书长','湖南湘乡人，早年加入中国共产党后叛变，抗战期间投靠汪精卫，历任伪中央政治会议副秘书长、伪安徽省省长、伪上海市政府秘书长等职，参与伪政权决策与地方治理，在安徽、上海等地为日军服务。籍贯湖南，与湖南有直接关联。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('efcb1f6a5ee54fcb9db4ef8631658397','a2e4190c87b449e685d78c118a6801b5',1938,'汪伪政府财政部长、伪行政院副院长、伪上海市长','湖南沅陵人，原国民党要员，抗战期间投靠汪精卫，成为汪伪政权核心人物之一，历任伪财政部长、伪行政院副院长、伪上海市长等职，负责伪政权财政与经济掠夺，并后期与重庆方面暗中联系。籍贯湖南，与湖南有直接关联。；湖南沅陵人，汪伪政权核心人物之一，参与筹建汪伪政权，推行伪化统治，虽主要在南京、上海活动，但作为湖南籍汉奸代表人物被广泛记载。；湖南沅陵人，汪伪政权核心人物之一，后与重庆方面暗中联系，抗战胜利后被国民政府逮捕审判。；湖南沅陵人，汪伪政权核心人物之一，参与筹建汪伪政权，掌握财政与特务系统，后与重庆方面暗中联系。；湖南沅陵人，汪伪政权核心人物之一，参与建立汪伪政权，推行伪化统治，其活动主要在上海、南京，对湖南沦陷区有政治影响，但与郴州、桂阳无直接地方关联。；湖南沅陵人，汪伪政权核心人物之一，参与对日妥协与伪政权建设；虽非郴州、永兴本地活动，但作为湖南籍最大汉奸之一，与湖南地区伪政权人事网络有间接关联。；湖南沅陵人，汪伪政权核心人物之一，参与筹建汪伪政权，掌管财政，后与重庆方面暗中联络。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d8f17831c5484d5286df98457c894aad','072a989933af4ab191441098a6d8461b',1930,'国民党军第十八师师长（后投敌未遂）','湖南长沙人，国民党将领，1930年率部参加对中央苏区的第一次“围剿”，在江西龙冈被红军俘虏，1931年被处决。其活动主要在江西，与湖南有籍贯关联，但并非严格意义上的汉奸。；湖南长沙人，1931年在江西被红军俘虏处决，非汉奸，但常被误列，此处不属汉奸名录。；湖南长沙人，1930年率部进攻中央苏区被俘，1931年被处决，与衡阳地区关联较弱。；湖南长沙人，早年参与围剿红军，1931年被俘，并非严格意义汉奸，但因其在湖南地区活动且与日军有接触传闻，部分史料将其列入附逆嫌疑。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('247392a157f94a93b990eb5c19d92a15','752a41642562417191e81157ce62fdec',1929,'国民党湖南省政府主席（后附逆倾向）','湖南醴陵人，长期主政湖南，抗战初期仍任湖南省政府主席，后因与蒋介石矛盾被调离。其在湖南期间镇压共产党和抗日运动，但未直接投敌。与湖南有直接关联，但非典型汉奸。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5a3275e27b8d41d4809acd14ce74bd74','8588ca8a02624b44a8d08163d89016ba',1937,'无（八路军副总司令）','湖南湘潭人，八路军副总司令，抗战期间在华北领导抗日斗争，与湖南有籍贯关联，但为抗日将领，非汉奸。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8a907786d37f47ca8d2dfaa2595e7843','4f19196006a34c1b88aeb20e5ccaacdb',1940,'汪伪政权军事委员会委员、伪清乡委员会驻苏州办事处主任','湖南东安人，与永州地区有直接籍贯关联。受重庆方面派遣打入汪伪政权，但在汪伪中担任伪职，参与伪清乡活动，属于有明确历史记载的附逆人物。；湖南东安人，受重庆方面派遣打入汪伪内部，但在此期间公开附逆任职，参与伪清乡活动，与湘籍伪政权人物多有联络。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ccf06754bb8449e3b44a9d327582cadd','a2e4190c87b449e685d78c118a6801b5',1938,'汪伪政权财政部长、伪行政院副院长、伪上海市长','湖南沅陵人，湖南籍汪伪核心人物之一。虽主要在南京、上海活动，但其伪政权体系覆盖湖南沦陷区，对湖南地区伪政权建立有间接影响。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('df843b2eb8424e9b844ead27cf188062','a1442e252a78480888f49fee68c84d90',1944,'伪湖南省政府委员、伪长沙市长','湖南长沙人，日军占领长沙后出任伪职，协助日军维持占领区秩序，是湖南地区有明确记载的汉奸之一。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('92b9d9dee8434f3ab4591678e41a5b3c','d251a9f00be546a2b753af31b3a9f1c7',1944,'伪湖南省政府主席','湖南浏阳人，1944年日军占领湖南大部后，被推为伪湖南省政府主席，主持伪政权，为日军征粮、征夫，是湖南沦陷区最高伪职人物。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f8969430f4454521a012a83281b06771','4e96b390a7dc4399859add03fad2d06b',1944,'伪湖南省政府委员','湖南籍，在日军占领湖南期间参与伪湖南省政府，协助日军推行伪化政策。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ace4ae9f07584488ad6b9183d19464e8','a5aec7ca1d314620b8797ac40b90f7cb',NULL,'未任伪职（此处仅作排除说明，不列入）','无','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ea6ae5fcea4e440687737344c43f8b35','4f19196006a34c1b88aeb20e5ccaacdb',1940,'伪湖南省政府委员、伪长沙绥靖公署副主任（后为军统潜伏人员）','受军统派遣打入汪伪政权，在湖南及周边地区活动，表面附逆，实际为重庆方面提供情报并策反伪军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('92d8a49287ba4a7895877c0d446921bb','e7ec243906d4478082206f56be9b96f0',1944,'伪道县维持会会长','日军侵占道县期间，出面组织维持会，为日军征派粮秣、夫役，协助维持占领秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d6cbd52a692e44eb83b66399dfef6369','752a41642562417191e81157ce62fdec',1937,'伪湖南省政府主席（后投靠汪伪）','原国民党湖南省主席，抗战后期与汪伪政权有联系，其旧部在湖南部分地区附逆。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c012628e6dc94db1b83e035052004289','a2e4190c87b449e685d78c118a6801b5',1940,'伪行政院副院长、伪财政部长、伪湖南省长（名义）','汪伪政权核心人物，曾兼任伪湖南省长，对湖南沦陷区伪政权有名义管辖权。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5f03ac67447a4708aa5f76d5f6342379','51cc603628064bf99c4cc926d3628036',1944,'伪永州维持会副会长','日军侵占永州期间，协助组织维持会，为日军筹集物资、招募伪军。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('de9e2418fba2449fa5ca5b2edf5cd87c','a5aec7ca1d314620b8797ac40b90f7cb',1944,'伪零陵县维持会会长','在零陵（今永州零陵区）组织维持会，配合日军统治，征发民夫。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('79e8d89e6c714187a6eaa27e38d752bb','b915bf764cfc4afcb773979450337438',1944,'伪湘南绥靖军司令','在湘南地区收编土匪、散兵，组织伪军配合日军扫荡，活动范围包括永州、道县一带。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('30b1f63cea804911b4bbfd3fba4945dd','80c19677480749eda7b9e26e0920def2',1944,'伪湘南保安司令','在湘南沦陷区组织伪保安部队，协助日军维持治安，镇压抗日力量。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('88c0911c518d40c0a9be3a094116f50c','0d2d2045fc1d498dab9499e43abcb3de',1940,'伪安徽省长、伪上海市政府秘书长（湖南籍附逆者）','湖南人，汪伪政权高官，虽主要在华东活动，但对湖南沦陷区伪政权有影响。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6f89439748e0482e927d834b1c22b0cf','bb34b45b44c34a018d410cde66579fb1',1939,'汪伪政府陆军部长、伪湖北省主席','湖北黄陂人，汪伪军事头目，其伪军活动涉及湘北、湘中一带，与湖南沦陷区有军事关联。；湖北黄陂人，但在湖南长沙有军事活动背景，后投靠汪伪，其伪军活动范围覆盖湘鄂地区，与长沙有间接关联。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('254fd975ff8b460392e4f9130054bfdb','072a989933af4ab191441098a6d8461b',1931,'国民党军第十八师师长（后参与伪政权？）','湖南长沙人，1931年在对中央苏区“围剿”中被俘处决，非汉奸。此处不适用。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('097629dc72a843779c31adfe314701fe','0d2d2045fc1d498dab9499e43abcb3de',1940,'汪伪政府司法行政部长、伪安徽省主席','湖南湘乡人，汪伪政权要员，参与伪化统治，其伪政权活动对湖南沦陷区有影响。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0622591ee85c4a3e9d94b8601b95456e','9a6ddf69575e488480603c12171ac907',1939,'汪伪特工总部南京区区长、伪杭州市长','湖南人，汪伪特务骨干，在沦陷区进行特务活动，涉及湖南部分区域情报网络。','核心城市市长/省部级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b6de3a2e2c4942c8b23d9b6189f8d519','a2ac8c21a06a42938393180e489cefbe',1940,'汪伪政府边疆委员会委员、伪湖南省政府委员','湖南籍，汪伪政权中参与伪湖南省政府筹备与运作，协助日军推行伪化政策。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e0b57769499d43f8b8d393fa6e9a02f8','a1442e252a78480888f49fee68c84d90',1940,'汪伪政府江西省长、伪军事委员会委员','湖南籍？实为福建人，但伪政权活动与湖南邻近省份有关，间接影响湖南。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a992921bda2f4eacb79ec2c2166fb735','d251a9f00be546a2b753af31b3a9f1c7',1940,'汪伪政府参军处参军长、伪湖南省政府主席','湖南浏阳人，汪伪政权中任伪湖南省政府主席，直接参与湖南沦陷区伪化统治，与永州零陵地区有行政管辖关联。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2e60bfcf97ad4e7cbc8a9b7f80f2387b','9657c4e97bb84ca6be108d4609f48868',1944,'伪零陵县维持会会长','在日军侵占零陵期间，出面组织伪维持会，协助日军征粮、派夫、维持治安，镇压抗日民众。','基层维持会/地方自治头目','hanjian');
