INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('768ca327b66d47debf5874382cd58eaf','62a6d6c8e7ab4bbfbc92c5b14abbde74',1938,'汪伪政府立法院长、行政院长、代理国民政府主席','虽为广东籍，但作为汪伪政权最高层之一，其伪政权政令覆盖湖南沦陷区，与湖南伪政权机构有上下级关系。','伪政权最高层/元首级','hanjian');
