INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2dce283760df42c7a644272a6358b5fe','0d2d2045fc1d498dab9499e43abcb3de',1939,'汪伪政府司法行政部长、伪安徽省长、伪上海市政府秘书长','湖南湘乡人，汪伪政权重要成员，参与伪政权司法与地方行政，其家乡湘乡与湘潭相邻，对湘潭地区伪化统治有间接影响。；湖南湘乡人，汪伪政权重要成员，参与伪政权司法、行政与地方治理，其伪政权体系对湖南沦陷区有间接影响。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6497a9bcfaef4a3680e572f88b5e572d','9910c48b9b394ffa8c73439ed0a473b0',1939,'汪伪特工总部主任、伪社会部长、伪浙江省长','湖南常德人，汪伪特务与行政高官，参与伪政权特务活动，其湖南籍背景使其在湖南沦陷区有一定人脉与影响。；湖南常德人，汪伪特工头目，在沦陷区进行特务活动；虽为湖南籍，但主要活动于上海、南京、浙江，与衡阳蒸湘无直接地方关联。','省部级/大军区级要员','hanjian');
