INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f98b162d400942ddbef68c6b3dddeaf6','ad590c6874164183a158be674a249e06',1944,'湘潭县维持会会长','1944年日军攻陷湘潭后，当地成立维持会，会长由地方士绅或地痞出任，协助日军征粮、派夫、维持治安，具体姓名在地方志中记载不全。；1944年日军攻陷湘潭后，当地成立维持会，会长姓名在地方志中记载不全，主要负责为日军征派粮食、民夫，维持占领区秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('79bb989d4dca46ca9e9179470fdc2ed7','734ced821bd343448ea8f88fb5a06aeb',1944,'伪保长','日军侵占湘潭期间，岳塘一带设立伪保甲组织，保长负责摊派捐税、抓丁拉夫、传递日军命令，具体姓名多已失载。','一般帮凶/基层人员','hanjian');
