INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0bd22d89f33643ff961db4fcd4f1c836','ffb6cf1e915740a1a3a8c147dc9eef27',1944,'伪湘潭县县长','抗战后期湘潭沦陷期间，出任伪湘潭县县长，主持伪县政，配合日军推行保甲、征发物资。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('83e7877e1e964588b841ee4a33c31e5b','b8c3462e5f5d49389caec12839d26158',1944,'伪湘乡县维持会会长','湘乡沦陷后组织维持会，替日军筹粮筹款、拉夫，并协助建立伪基层政权。','基层维持会/地方自治头目','hanjian');
