INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b8bf8128403447c3b331578471a9e0bc','0d2d2045fc1d498dab9499e43abcb3de',1944,'伪湖南省政府主席兼伪长沙市长','汪伪政权高级官员，1944年后任伪湖南省政府主席，主持湖南沦陷区伪政，推行日军占领政策，搜刮物资、镇压抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ac7665f5c9f04faa81274d1e80931907','a2e4190c87b449e685d78c118a6801b5',1938,'伪行政院副院长、伪上海市长等（湖南沅陵人，汪伪核心）','汪伪政权核心人物之一，湖南籍，虽主要活动于南京、上海，但其伪政权体系覆盖湖南沦陷区，对湖南伪政权的建立与运作有直接影响。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ced8b7ffe2404ebdbe7d93a054b90f3b','bb34b45b44c34a018d410cde66579fb1',1939,'伪湖北省政府主席、伪武汉行营主任（湖南籍相关）','汪伪政权军事与地方伪政要员，活动于华中地区，其伪军体系与湖南北部沦陷区有联系，配合日军对湖南的军事行动。','基层头目','hanjian');
