INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('80495220855249fca78e6706c1af90e9','98ed2b5ac6e84c4888b2ae7bf3106ddc',1938,'伪湖南自治会会长（未就任，但曾与日方接触）','北洋时期湖南军阀，抗战期间滞留湖南，曾与日方接触，被日方企图拉拢组织伪政权，但最终未公开附逆。历史记载其态度暧昧。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('39b91893fc8a45ee9ac536f945f57b5c','b19edc2e16ec4c7d9462b01fbba0f27f',1938,'国民党军第一二八师师长（后脱离国民党，未投日）','陕西渭南人，在湖北沔阳一带坚持抗日，后被日军俘虏，未任伪职，不属汉奸。','市县厅局级','hanjian');
