INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('370ba9e556c9425ea8ce9679ad9633c0','8fae8e48ba17425cac032b96a046da75',1944,'湘潭县九华地区伪保甲长','日军侵占湘潭后，九华一带部分保甲长被迫或主动附逆，为日军征粮、派丁、传递情报，具体姓名散见于地方档案，但系统记载极少。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('83a96e74390a4f6c8403f8a92ba1f77b','57e1607fae8648d69afe3963e22c171f',1944,'长沙县维持会会长','1944年长沙沦陷后，伪维持会为日军服务，会长姓名在部分文史资料中有提及，但与湘潭无直接关联。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cfb1e96fcc124580a48dcc7047f62bd1','d6a94931416e4811a22a7254773f9214',1944,'汪伪政权湖南伪省政府筹备委员','日军侵占湖南部分地区后，曾试图建立伪省政府，部分附逆人员参与筹备，但未能正式成立，姓名记载零散。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('66637969eda041f8b1cafc6afa7133f8','a2e4190c87b449e685d78c118a6801b5',1938,'汪伪政府行政院副院长、财政部长、伪中央储备银行总裁','湖南沅陵人，汪伪政权核心人物之一，参与筹建汪伪政权，任伪行政院副院长、财政部长等要职，推行伪币、搜刮物资，后与重庆方面暗中联系。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('449976d294894b36bc487edd0fe6219a','bb34b45b44c34a018d410cde66579fb1',1939,'汪伪政府陆军部长、伪武汉行营主任、伪湖北省长','湖北黄陂人，长期在湖南、湖北活动，投靠汪伪后任伪陆军部长、伪武汉行营主任、伪湖北省长，在湘鄂地区组织伪军、配合日军清乡。；湖北籍伪军头目，活动于武汉及周边，与湖南北部沦陷区伪军有联络，曾参与收编湘北伪军和维持会武装。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d20e9b39063e4773b6866987d583c12b','072a989933af4ab191441098a6d8461b',1930,'国民党军第十八师师长（后与日伪有联系）','湖南长沙人，早年参与围剿红军，1931年被俘处决，其部属部分在湘中地区活动，与日伪有间接关联，但本人主要活动于抗战前。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9e74fea7e3b94ed291047182352e3746','a984f59d907348ba9abd26a16b473797',1940,'汪伪政权相关地方维持会成员（待考）','湖南湘潭地区部分维持会、保甲长在日军占领期间协助征粮、派夫，但具体姓名多不可考，彭孟缉为台湾高雄人，与湘潭无直接关联，此处仅作示例说明地方维持会现象。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6bc502ad04cf4fbeba55917a6ccd1fda','18e636f960e64de0b1c2c930628ef870',1944,'湘潭县雨湖地区维持会成员','日军占领湘潭期间，雨湖地区设有维持会分会，成员多为当地士绅或地痞，协助日军管理户籍、征收物资，具体姓名在现存史料中极少记载。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c8ec54c8507144b2ad624f5846090d62','0d2d2045fc1d498dab9499e43abcb3de',1939,'汪伪政权安徽省省长、汪伪国民党中央执行委员','湖南湘乡人，早年加入中国共产党后叛变，抗战期间投靠汪精卫，历任汪伪政权要职，参与伪政权统治，为汪伪集团核心成员之一。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a28c048fd16346fdbfd6cda6599a8b94','a2e4190c87b449e685d78c118a6801b5',1938,'汪伪政权财政部长、警政部长、上海市长','湖南沅陵人，中共一大代表后叛党，抗战期间投靠汪精卫，成为汪伪政权核心人物，掌管财政与特务警察系统，配合日军统治沦陷区。；原为国民党要员，抗战期间投靠汪精卫，参与建立汪伪政权，历任伪财政部长、警政部长、伪上海市长等职，为汪伪政权核心人物之一，在重庆时期即与汪精卫暗中联络，后公开叛国。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1bff6c3cb54740bd88697f6014a68dc6','bb34b45b44c34a018d410cde66579fb1',1939,'汪伪政权湖北省省长、伪武汉绥靖公署主任','湖北人，但与湖南军政界有联系，投靠汪伪后负责华中地区伪军与伪政权事务，配合日军清乡。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ecbde477c8084925aae5c77ccd0da025','072a989933af4ab191441098a6d8461b',1930,'国民党军第十八师师长（后与红军作战被俘处决）','湖南长沙人，早期参与围剿红军，虽非严格意义汉奸，但在抗战前的地方军事活动中与湘西地区有交集。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e90c53cfdb934305a7287e816f16ed54','521a9d06c75a41c7866bf8369dd53403',1931,'湘西地方武装首领、国民党新编第三十四师师长','湘西凤凰人，长期统治湘西地区，抗战期间虽名义上抗日，但与日伪方面有暧昧接触，保持地方割据，未积极抗日。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5c0f992489c84919b470e3b2a74cfd2e','b1505f4262704578b72602198d47fde9',1931,'湘西地方武装头目、国民党军团长','湘西凤凰人，苗族地方武装首领，抗战期间在湘西地区活动，与日伪有间接联系，维持地方势力。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dda2eb1e78fa4667979e9a04577366a8','555a5637277447408f5f697f052d0c9d',1930,'湘西地方土匪武装头目','湘西地区土匪首领，抗战期间在湘西一带活动，曾与日伪势力有勾结，扰乱地方抗日秩序。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ace98a92e2c544acae878f6685cbad09','c1c090acac0c4d3187a38fa05c27c910',1930,'湘西土匪武装首领','湘西龙山人，长期在湘西地区为匪，抗战期间与日伪及地方势力有复杂关系，未积极抗日。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('618a842b842b4fbbbc05bf4bfce78121','985c610c032f4da8be9e0f00db4db6de',1930,'湘西地方武装头目、国民党军营长','湘西龙山人，地方武装首领，抗战期间在湘西活动，与日伪有接触，维持地方割据。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d347b8e363d34d9395bece5b98777b71','8c18f1191b834836b9580eb50464b3e8',1930,'湘西地方武装头目','湘西地区地方武装首领，抗战期间在湘西一带活动，与日伪势力有联系。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('242ea11b95584dca9f328db00d7540f2','26b5c5893aff4183a58ce09795aaaa98',1943,'古丈县维持会会长','日军侵占古丈期间，出面组织古丈县维持会，为日军征集粮食、民夫，协助维持占领区秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d224b9a22e674fff81ddd98e8317df68','b7f293e99cf84075a366c793be2d5dfa',1930,'湘西土匪、伪军头目','湘西古丈、沅陵一带地方武装首领，抗战后期与日军及伪政权有勾结，接受伪职，配合日军清乡，残害抗日军民。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('394faee0707d46c8924287a913bbc912','521a9d06c75a41c7866bf8369dd53403',1930,'湘西地方军阀（后期附逆嫌疑）','湘西地方实力派，抗战期间曾与日伪方面有秘密接触，其部属在湘西部分地区与伪军合作，但本人是否正式投敌存在争议。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ace50f88633e410e873bac2d8b850967','555a5637277447408f5f697f052d0c9d',1940,'湘西伪军头目','湘西一带土匪武装，抗战后期投靠日军，被编为伪军，在古丈、保靖、永顺等地为日军搜集情报、抓捕抗日人员。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1704f1c1fc714e1e940e066e8ac3a559','8c18f1191b834836b9580eb50464b3e8',1944,'伪湘西自治军司令','抗战末期在湘西地区组织伪军，配合日军进攻湘西抗日根据地，在古丈、沅陵交界地带活动。；湘西地区人，1944年组织伪湘西自治军，配合日军在湘西进行军事活动，维持伪政权地方秩序。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0314e93af56a45dfb2ba24066e4409c1','b1505f4262704578b72602198d47fde9',1943,'湘西苗区伪维持会头目','在湘西苗区为日军组织维持会，征派粮款，协助日军统治，活动范围包括古丈、花垣一带。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f151453cd2c747638ef8fe3392abae27','6b298e69d53a43ca8ab997d236f7bc11',1944,'古丈县伪警察所长','日军占领古丈期间出任伪警察所长，带领伪警察搜捕抗日分子，镇压当地民众反抗。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6cc4cfec9b0647a78b95237a8ab96bd7','93066e24569c41c2b3537630ef6a6fa5',1943,'湘西伪保甲长','在古丈县担任伪保甲长，为日军派夫派粮，监视村民，举报抗日活动。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c35979d0583b497d93a8936c3a06e8dd','289ae8c3458f4609a800c782181fba46',1944,'伪湘西维持会教育科员','在湘西伪政权中负责教育，推行奴化教育，编写亲日教材，在古丈等地学校强制使用。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bf3093622bb94d2493b56502bc62705f','cd6bd8e57e4147f5b633a46a11754965',1944,'古丈县伪商会会长','组织古丈县伪商会，为日军筹款筹物，协助日军经济掠夺，压迫当地商户。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('29e9489e6c604b9f803c1200b5b9f953','a2e4190c87b449e685d78c118a6801b5',1938,'汪伪政权行政院副院长、财政部长、伪上海特别市市长','湖南沅陵人，汪精卫伪政权核心人物之一，参与对日投降与伪政权建设，虽主要活动于南京、上海，但作为湖南籍汉奸代表人物，与湖南地区有籍贯关联。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f232d426ae1343dcaf1eefa6e53383dd','bb34b45b44c34a018d410cde66579fb1',1939,'汪伪政权武汉行营主任、伪湖北省政府主席','湖北黄陂人，但在湘西及湖南地区有活动，曾率伪军配合日军进攻湖南，与湘西地区军事行动有直接关联。；湖北黄陂人，长期在湘鄂赣地区活动，组织伪军配合日军清乡，镇压抗日力量，其势力范围一度覆盖湘北。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8279a4e89b654fefa02738fbf7e76363','a976a94be0bf4b76b621948c0802222f',1933,'伪华北政务委员会顾问、旧军阀附逆','湖南人，旧军阀，1933年投靠日本，在华北从事伪政权活动，虽主要在华北，但作为湖南籍附逆人物被记载。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9e319bfb567a47b1870b1575f22ff12e','8588ca8a02624b44a8d08163d89016ba',NULL,'',NULL,'无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9fd92612ba0c44a68858150fc13ac8bf','b1505f4262704578b72602198d47fde9',1943,'湘西地方武装头目、后附逆伪军','湘西凤凰人，苗族地方武装首领，抗战后期与日军及伪政权有接触，被指在湘西地区配合日伪行动，维持地方伪秩序。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('667b2fb6890d49ed963e5e540f965adb','521a9d06c75a41c7866bf8369dd53403',1939,'湘西地方军阀、后与日伪有联系','湘西凤凰人，长期统治湘西，抗战期间与日伪方面有暗中联系，其部属在湘西地区有附逆行为，本人被指态度暧昧。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5d98643a5ea646d1b09e12f1af9e18dc','c74e5cdd9e4940029b8fe9587c5315c6',1944,'伪湘西维持会会长','湘西吉首地区人，1944年日军侵入湘西时组织伪维持会，协助日军征粮、拉夫，维持地方伪秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b8e40413c2a14fab9b41ea9d68afefd2','3648da79b6334a99bbf2bd7b88046b4e',1944,'伪保靖县维持会会长','湘西保靖人，日军犯湘西时出面组织维持会，为日军提供物资与情报，协助伪政权控制保靖一带。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('89808e3f4e114db6bf93a1980a16a2fb','b7f293e99cf84075a366c793be2d5dfa',1943,'湘西土匪头目、后投靠日伪','湘西古丈人，土匪武装首领，抗战后期与日军及伪政权勾结，在湘西地区劫掠并配合日伪行动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('43ce44ce86604d92aa7e0897225a9a6a','c1c090acac0c4d3187a38fa05c27c910',1943,'湘西土匪头目、附逆伪军','湘西龙山人来凤一带活动，土匪武装，抗战后期与日伪有联系，在湘西边境配合日军行动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f5bb89728be5491b8326ab666047a99c','555a5637277447408f5f697f052d0c9d',1944,'湘西土匪头目、附逆','湘西永顺人，土匪首领，日军侵入湘西时投靠日伪，率部配合日军骚扰抗日后方。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('475f12978fcb4e19a7dfda9886ad532a','26b5c5893aff4183a58ce09795aaaa98',1944,'伪沅陵县维持会会长','湖南沅陵人，日军犯湘西时组织维持会，为日军筹粮、派夫，协助伪政权控制沅陵地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('715abaac4a4840398e13c596825d9c9f','6162af4edadf4e5497cc6425df4ff288',1944,'伪辰溪县维持会会长','湖南辰溪人，日军侵入湘西时出面组织维持会，协助日军维持地方秩序，征调物资。','基层维持会/地方自治头目','hanjian');
