INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('90168bb403044af4ad10848c378ed715','62a6d6c8e7ab4bbfbc92c5b14abbde74',1938,'汪伪政权立法院长、行政院长、代主席','湖南籍背景的汪伪高层（出生于广东，祖籍湖南），随汪精卫投敌，任伪政权要职，签署卖国协定，协助日军统治沦陷区。；汪伪政权核心人物，虽非湖南籍，但其伪政权体系覆盖湖南沦陷区，对湖南伪政权组织与人事有直接任命与指挥关系。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('51cceebca1c042b5b59877c3387217e3','4f19196006a34c1b88aeb20e5ccaacdb',1940,'汪伪政权军事委员会委员、伪军将领（后为军统潜伏人员）','湖南东安人，受重庆方面派遣打入汪伪内部，曾任伪军职，在沦陷区活动，与湖南及益阳地区日伪势力有联系。；湖南东安人，受重庆方面派遣打入汪伪政权，曾任伪军事委员会委员等职，在沦陷区活动，与湖南籍军政网络有关联；其身份具有潜伏性质。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aa0fbc8ab8d448a489c152604caa31cc','bb34b45b44c34a018d410cde66579fb1',1939,'汪伪政权湖北省长、伪军委会委员、伪武汉行营主任','湖北籍伪政权要员，活动于华中地区，与湖南日伪势力有联络，参与伪军组织与清乡，镇压抗日军民。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7594762ee0a14c40b0c3468c7b2633cb','903f92a867db4e77abb94dac1ad28168',1941,'伪第一集团军总司令、汪伪军委会委员','原国民党军将领，率部投敌，任伪军高级头目，在华中包括湖南周边地区配合日军进行扫荡与清乡。','省部级/大军区级要员','hanjian');
