INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('45103e22eb4243dbb0208f9d4e8cb2b8','d2a92253f324409085004a7ae6f3ec6a',1944,'衡阳维持会会长','衡阳沦陷后组织维持会，为日军征集物资、拉夫，协助日军管理衡阳城区，镇压抗日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('701dfa1cd15e4049a274733b2a2ded2f','a2e4190c87b449e685d78c118a6801b5',1940,'汪伪政权财政部长、伪湖南省长（名义）','汪伪核心人物，其势力影响湖南，通过伪政权在湖南征收赋税、掠夺资源，支持日军侵略。；汪伪政权核心人物，虽主要在南京活动，但其伪政权体系覆盖湖南，对湖南伪政权人事与政策有直接影响。；汪伪政权核心人物，虽主要在南京活动，但其伪政权体系覆盖湖南，对湖南伪政权人事与政策有直接影响，间接关联衡阳、衡山地区伪化统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7bf4f27cc5274c60a085f2c3fb83a917','51cc603628064bf99c4cc926d3628036',1944,'伪衡阳县知事','日军占领衡阳后出任伪县长，协助日军推行保甲制度，征发民夫，镇压抗日群众。；衡阳沦陷后任伪衡阳县知事，配合日军推行保甲制度、征粮征夫，镇压抗日活动。；衡阳沦陷后出任伪县知事，配合日军推行保甲制度、征发劳役、搜刮物资。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ad1402ee77f345ebb9f192fc11487684','82d2e3b7dc8e4486b083ed9d7382d52e',1944,'伪常宁县维持会会长','常宁沦陷期间组织维持会，为日军筹粮筹款，诱降当地士绅，协助日军控制常宁地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d23dd008b8f24ae0b3bd3f89b21cde4c','2298d83cf2cc473998a68e9432dac58f',1944,'伪衡阳警察局局长','在衡阳沦陷区组建伪警察队伍，配合日军搜捕抗日分子，维持伪治安。','市县厅局级','hanjian');
