INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('24b8127a90874e668d781845ab403f0f','bb34b45b44c34a018d410cde66579fb1',1939,'汪伪政府陆军部长、伪武汉绥靖公署主任','湖北黄陂人，汪伪政权军事头目之一，其伪军活动范围涉及湘北、鄂南，与湖南衡阳地区有间接军事关联。','省部级/大军区级要员','hanjian');
