INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0aa7b3325d49467b92f675619c6f3085','4d1e4f23fd9e4fca8886a3fb0549425f',1944,'伪衡阳县维持会会长','衡阳沦陷期间，出面组织伪维持会，协助日军维持地方秩序、征派物资，具体事迹散见于衡阳地方文史资料。','基层维持会/地方自治头目','hanjian');
