INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6ed4ce5aca584cf79a68428ad0ab9bf8','98ed2b5ac6e84c4888b2ae7bf3106ddc',1938,'伪湖南省政府顾问（未就任，但曾与日方接触）','湖南衡山人，北洋时期湖南省长，抗战期间居上海，曾与日伪方面有接触，但未正式出任伪职，历史评价复杂。；北洋时期湖南军阀，抗战期间曾与日方有接触，但未实际出任伪职；其旧部在衡阳、耒阳一带有附逆行为。','无明确职位或一般帮凶','hanjian');
