INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2342cce6eec547eba2c85e2abba0c789','a976a94be0bf4b76b621948c0802222f',1933,'伪华北政务委员会顾问、伪平津地区汉奸头目','湖南衡阳人，北洋旧军阀，后投靠日本，在华北从事汉奸活动，虽主要活动于平津，但作为衡阳籍汉奸被历史记载。；湖南长沙人，北洋军阀余孽，1933年投靠日本，任伪华北政务委员会顾问，在平津地区从事汉奸活动，1935年被刺杀，与长沙有籍贯关联。','无明确职位或一般帮凶','hanjian');
