INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7e48829e0707455b8cf0f1bd3838ee56','a6971ee6071a440abebc19ede1080bd6',1944,'伪衡阳自治会负责人','衡阳保卫战后期，日军占领衡阳后，罗树甲参与组织伪自治会，协助日军管理城市、征调民夫。','基层维持会/地方自治头目','hanjian');
