INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('14c6f525797e48ec88999d4b03bd5429','80c19677480749eda7b9e26e0920def2',1944,'伪祁东地区保甲长、伪维持会骨干','祁东地区沦陷期间，陈光中担任伪保甲长，积极为日军催征粮草、搜集情报，并带领日军搜捕抗日人员。','基层帮凶(维持会系统)','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('81d249576fb8451e9e5fa418da3867e5','51cc603628064bf99c4cc926d3628036',1944,'伪衡阳警察局督察长','衡阳沦陷后，李树森投靠日军，出任伪警察局督察长，协助日军维持治安、抓捕抗日分子。','无明确职位或一般帮凶','hanjian');
