INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('81842395bb4147ae830db5ca435fb23a','02a4e84319ba438189869a1792dbacca',1944,'伪衡阳商会会长','衡阳沦陷期间，黄子安以商会会长身份出面组织伪商团，为日军筹集物资、摊派款项，协助日军控制衡阳经济。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8b2a91ec7106415c89e4d9146269216c','65cae6981b0d4ef68f23b0a495d722d1',1940,'伪湖南教育会会长、伪衡阳中学校长','湖南教育界附逆者，在日伪控制下推行奴化教育，曾在衡阳地区学校中强制使用伪教材，宣传“大东亚共荣”。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d94cfc63003443958b108f49bd02a1f1','a1442e252a78480888f49fee68c84d90',1944,'伪衡阳县维持会会长','衡阳沦陷后出面组织伪维持会，协助日军征粮、拉夫、维持治安，为日军在衡阳地区的统治提供地方支持。；衡阳沦陷后出面组织伪衡阳县维持会，协助日军征粮、派夫、维持城区秩序，并参与伪政权的基层保甲组建。','基层维持会/地方自治头目','hanjian');
