INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('76b8a453d6294d02a4581ec4bac86b25','cbaf785da5ae45159f8f160436ea6d7f',1944,'伪耒阳县维持会会长','耒阳沦陷期间组织伪维持会，为日军征集粮食、民夫，并参与伪保甲组织，协助日军控制耒阳城乡。','基层维持会/地方自治头目','hanjian');
