INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('359137cfe226452e87de78f294ca511a','a2e4190c87b449e685d78c118a6801b5',1940,'汪伪政权行政院副院长、伪湖南省长（名义）','汪伪政权核心人物，其伪政权名义上管辖湖南，对湖南沦陷区伪组织有统辖关系，间接影响衡阳、耒阳等地伪政权运作。；汪伪核心人物，曾兼伪湖南省政府主席名义，推行伪化统治，后与重庆方面有联系。；汪伪政权核心人物，其伪湖南省长名义与湖南沦陷区伪政权体系相关，推行附日政策。','省部级/大军区级要员','hanjian');
