INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('300c82b11d1f4ed2933dea06c245983e','a1442e252a78480888f49fee68c84d90',1943,'汪伪政府江西省长','湖南长沙人，汪伪政权地方头目；与衡阳蒸湘无直接地方关联。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2b98b80711054a61bf46520aaddbe825','d251a9f00be546a2b753af31b3a9f1c7',1940,'汪伪政府参军长、伪军事委员会委员','湖南浏阳人，汪伪政权军事成员；与衡阳蒸湘无直接地方关联。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d966a89300af4548971750b77dfc0c76','aba0f59094114a57abf702213f3a4eae',1944,'伪衡阳县维持会会长（待考）','衡阳沦陷期间，地方维持会组织者之一；具体姓名与事迹在地方史料中记载零散，需进一步查证。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('edd7650e68bd4e2ca99654673a19e49a','fd4166cafaba47edb4515b661b1bae4c',1944,'伪衡阳县维持会保甲长','1944年衡阳保卫战沦陷后，部分地方保甲长被迫或主动为日军维持秩序、征派民夫粮秣；因基层记载缺失，难以列出完整姓名。','基层帮凶(维持会系统)','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('71ff5c2917c44e09bf6003207cb8c97c','a2e4190c87b449e685d78c118a6801b5',1938,'汪伪政府行政院副院长、伪财政部长、伪警政部长','湖南沅陵人，汪伪政权核心人物之一，参与建立汪伪政权，推行伪化统治，后期与重庆方面联络，抗战胜利后被国民政府逮捕审判。；湖南沅陵人，汪伪政权核心人物之一，参与筹建汪伪政权，后与重庆方面暗中联系，抗战胜利后被国民政府逮捕审判。；湖南沅陵人，汪伪政权核心人物之一，参与对湖南等沦陷区的伪化统治与经济掠夺，后与重庆方面暗中联络，抗战胜利后被国民政府逮捕审判。；湖南沅陵人，汪伪政权核心人物之一，参与建立汪伪政权，任伪行政院副院长、财政部长、警政部长等职，虽主要活动于南京、上海，但为湖南籍，且其附逆行为对湖南沦陷区伪政权建立有影响。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bd016222ab3e44a5be63d31d0cc472e5','63e8ad6773624d45b1a7e6dc11c6b2bf',1944,'伪湖南和平救国军总司令（后反正）','湖南长沙人，抗战后期在湖南地区活动，曾与日伪方面有接触，后率部反正，其部活动范围涉及湘中、湘南一带。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9660ec8cd7ae4b20a8eebcc0c0632b02','e7ec243906d4478082206f56be9b96f0',1944,'伪衡阳县维持会会长','衡阳沦陷期间出面组织伪维持会，为日军征集物资、拉夫、维持地方伪秩序，协助日军统治衡阳城区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('896e877297344b22b517ff5777cfe8c8','cbaf785da5ae45159f8f160436ea6d7f',1944,'伪衡阳县县长','日军占领衡阳后，出任伪衡阳县县长，协助日军推行保甲制度、征粮征夫，镇压抗日活动。；日军占领衡阳后出任伪衡阳县县长，主持伪县政，配合日军清乡、征发民夫与物资，推行奴化教育。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e1da9f21141049ad91c7546070abc0d3','562091e5d153498c9edb1f6e2d6c9543',1944,'伪衡阳商会会长、维持会成员','衡阳商界人物，沦陷后参加伪维持会，为日军筹款筹粮，协助控制衡阳商业与物资。；衡阳沦陷期间以商会名义为日军筹款筹粮，参与维持会活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('64b08a240388474b9c1d67a04e81219e','26b5c5893aff4183a58ce09795aaaa98',1944,'伪衡东县维持会会长','衡东地区沦陷后组织伪维持会，为日军带路、征粮、拉夫，协助日军控制衡东乡村。','基层维持会/地方自治头目','hanjian');
