INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('994af57db39548528d8a519c4fdf74c6','4f19196006a34c1b88aeb20e5ccaacdb',1940,'伪湖南省政府主席兼保安司令','原国民党将领，1943年投靠汪伪政权，任伪湖南省政府主席、伪保安司令等职，在湖南地区协助日军维持占领区秩序，进行伪化宣传与治安强化活动。；抗战后期受重庆方面指派潜入汪伪政权，任伪湖南省政府主席等职，表面附逆，实际从事策反与情报工作，其活动范围覆盖湖南衡阳一带。；原国民党将领，1940年投靠汪伪政权，任伪湖南省政府主席、伪保安司令等职，在湖南地区协助日军维持占领秩序，推行伪化统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2bf8680573de4678bb8eb85b3719d0bf','51cc603628064bf99c4cc926d3628036',1944,'伪衡山县维持会副会长','衡山沦陷期间参与组织伪维持会，协助日军在衡山地区征粮、拉夫，并诱迫地方士绅附逆。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('69de90e7cf76497e871b51bab4798b25','82d2e3b7dc8e4486b083ed9d7382d52e',1944,'伪湘南自治军司令','在湘南地区组织伪军，配合日军对衡阳、衡山一带进行扫荡与治安作战，收编土匪武装为伪军。','基层头目','hanjian');
