INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3bf7b66b0a624130aebcfbb3a4b5ad81','98ed2b5ac6e84c4888b2ae7bf3106ddc',1944,'伪湖南自治会会长','晚年投靠日军，在湖南组织伪自治会，为日军统治湖南制造舆论，活动涉及衡阳地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aeeb3c7b730042889ad90def171ac0a6','4f19196006a34c1b88aeb20e5ccaacdb',1940,'汪伪政府军事委员会委员、伪江苏省保安副司令（后为军统潜伏人员）','湖南东安人，奉蒋介石、戴笠之命打入汪伪政权，表面任伪职，实为军统潜伏，负责联络策反伪军将领，其活动范围涉及湖南籍人员网络，但与衡阳松木经开区无直接地方任职关联。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('74f39cc82ef1456ca6a1687541d1c79b','a976a94be0bf4b76b621948c0802222f',1933,'伪华北政务委员会顾问、旧军阀','湖南人，北洋旧军阀，1933年投靠日本，在华北从事伪政权活动，1935年被军统刺杀，与衡阳无直接地方关联。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('994b845f87554830a2aa933ff889e317','4315c7ab1a664e6b902019849fdb5b46',1944,'伪衡阳县维持会会长（待考）','据衡阳地方文史资料零星记载，1944年衡阳沦陷期间，当地有维持会组织协助日军维持秩序、征派民夫，但具体负责人姓名多已散佚，彭佐熙之名见于部分口述史料，可靠性有限。','基层维持会/地方自治头目','hanjian');
