INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ebad1cb575cc495299fe61d40160e344','b7125571678c46e09347d888da113b00',1944,'郴县维持会会长','日军侵占郴县期间出面组织维持会，为日军征派民夫、物资，协助维持占领区秩序。；日军侵占郴县期间，出面组织郴县维持会，为日军征派粮秣、夫役，协助维持占领区秩序。','基层维持会/地方自治头目','hanjian');
