INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d3530198264342b9b10af4903ac66af9','5247e6a0279e49418e859eefae916d84',1944,'伪郴县维持会副会长','郴县沦陷期间参与伪维持会，协助日军推行保甲、征发物资，活动范围覆盖郴州城区及周边，与宜章邻近。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0b9202799c9f4c4fa35a83e9825c556c','0985764cd13f42d285716b3f0f32d4e2',1944,'伪郴县警察局局长','日军占领郴县后出任伪警察头目，负责搜捕抗日人员、维持伪治安，其活动区域包括郴县至宜章一线。','市县厅局级','hanjian');
