INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8538f75117b248a4872d064fa778cabd','2298d83cf2cc473998a68e9432dac58f',1944,'伪宜章县保安团团长','宜章本地人，日军侵占宜章后率部投敌，编为伪保安团，协助日军镇压抗日游击队。','基层头目','hanjian');
