INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2984b663fa92479c9190e6ad08aa21d3','b915bf764cfc4afcb773979450337438',1937,'国民党军第四路军总指挥（后与日方有接触）','湖南醴陵人，抗战初期在湖南任职，后与日方有秘密接触传闻，未公开投敌，但部分史料将其列入附逆嫌疑。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('17f3eb259795461e8fbb53b01eb7f7b4','d251a9f00be546a2b753af31b3a9f1c7',1940,'汪伪政府军事委员会委员','湖南浏阳人，汪伪军事委员会成员，参与伪军建设，其活动范围涉及华中，与湖南长沙、宁乡地区有间接联系。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('417c30a154a0481790183405237019fd','e7ec243906d4478082206f56be9b96f0',1944,'伪宁乡县警察局长','宁乡人，投日后任伪警察局长，带领伪警察配合日军搜捕抗日人员，镇压宁乡地区抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9a772601ae114d249a0c38c28d6b9c03','82d2e3b7dc8e4486b083ed9d7382d52e',1944,'伪长沙县教育科长','在伪长沙县政府中负责教育，推行亲日奴化教育，在长沙、宁乡等地学校进行亲日宣传。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('89b8c6f7832c4b718302739b42b0b1b5','62a6d6c8e7ab4bbfbc92c5b14abbde74',1938,'汪伪政府立法院长、行政院长、伪国民政府代主席','虽为广东籍，但作为汪伪政权主要头目，其伪政权体系覆盖湖南沦陷区，对长沙等地伪维持会、伪军警有统辖关系。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9d92c644651940a684f8f77c57ba48a8','a976a94be0bf4b76b621948c0802222f',1933,'伪平津第二集团军总司令、日伪华北政权相关头目','湖南长沙人，北洋旧军阀，九一八后投靠日本，在华北组织伪军，1935年被刺杀于北平，是湖南籍早期附逆人物。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('efc150a671fd4abe8fd77a7999813389','4315c7ab1a664e6b902019849fdb5b46',1944,'伪长沙维持会会长、伪长沙市长','长沙沦陷后出面组织伪维持会，协助日军维持长沙城区秩序、征派物资与劳工，为日军占领长沙提供地方伪政权支持。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('31c7d10a95314b8bbf5968078c981391','b0029840ecbd4ef8b36226ecba81c9bc',1944,'伪长沙县维持会会长','长沙县沦陷期间任伪维持会会长，协助日军在长沙县及岳麓山周边地区征粮、派夫、建立保甲伪组织。；长沙县人，日军占领长沙后出任伪维持会会长，负责为日军筹粮、派夫、维持地方伪秩序，活动范围包括开福区一带。；长沙沦陷后出面组织伪长沙县维持会，替日军征粮、派夫、维持治安，是长沙地区有记载的伪政权头目之一。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a48bfe1302d54f2895ed86ca523db8ba','ea8df813a660484d99c916c7bbdab326',1944,'伪湖南保安司令部相关头目、伪军将领','湖南籍军人，抗战后期在湘中、湘南一带与日伪合作，参与伪军组织与地方治安维持，活动范围接近长沙地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3a45fd06ead24719a0457dbf5c875872','9a6ddf69575e488480603c12171ac907',1944,'伪长沙警察局局长','长沙沦陷后任伪警察局长，协助日军维持城区治安、搜捕抗日人员、管理户籍与物资配给。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bdef14588c694f5ba8fe0c15608fba57','a717543fb24f409895a297a2c48d24ee',1944,'伪岳麓山维持会负责人','岳麓山地区沦陷后组织伪维持会，为日军提供向导、情报与物资，协助控制岳麓山周边乡村。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('313f54d8f5e0443e8516e9b78831fe91','47f2fc3b70ec4bb285bb5da8c195af50',1944,'伪湖南省政府委员、伪长沙市长','在日军占领长沙期间参与伪湖南省政府筹备，任伪长沙市长，推行伪政令、征粮派款。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3f9f539bebe742ca86ac53497fbe0373','d251a9f00be546a2b753af31b3a9f1c7',1944,'伪湖南和平救国军总司令','湖南籍旧军人，抗战后期投靠日军，在湘中地区组织伪军，配合日军对长沙周边抗日武装进行扫荡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('190c17cc68744b43a3d09436ca80da6d','072a989933af4ab191441098a6d8461b',1931,'国民党军第十八师师长（后投敌未遂，但被指与日伪有接触）','湖南长沙人，1931年在江西被红军俘虏处决，此前有资料指其与日方有秘密接触，但主要历史定位为国民党将领，非典型汉奸。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b9bd7bd3098542a58ab19275b5c1f262','b19edc2e16ec4c7d9462b01fbba0f27f',1943,'国民党军第一二八师师长（后投日任伪军师长）','陕西渭南人，但在湖南长沙地区有作战与活动经历，1943年被俘后投日，任伪军师长，在湘北鄂南一带活动，与长沙邻近。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('39356e6f918c40f8903fd2d729704497','62a6d6c8e7ab4bbfbc92c5b14abbde74',1938,'汪伪政府立法院长、行政院长、代主席','广东乳源人，汪伪政权二号人物，其伪政权统治覆盖湖南沦陷区，对长沙等地有伪化政策影响。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('18409e43570e458f81d2a0abe5e3af82','664d3df731bb4293bee63eea6deacb2d',1939,'汪伪政府外交部长、广东省长','浙江吴兴人，汪伪核心人物，参与伪政权对湖南等地的政策制定与宣传，与长沙有间接关联。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3defe53b18834a88b0defc8ba23d148c','28c69a91441d4439abc95701e2c6787a',1938,'汪伪政府工商部长、内政部长','浙江永嘉人，汪伪政权重要成员，参与对湖南沦陷区的经济掠夺与伪化统治，与长沙有间接关联。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('61ea0bb8a3004709b542d96f4004ee45','9910c48b9b394ffa8c73439ed0a473b0',1939,'汪伪特工总部主任、伪浙江省主席','湖南常德人，汪伪特工头目之一，其特工活动涉及湖南长沙等地的情报与镇压，与长沙有直接籍贯关联。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b397851323ae4163bd14e16a092566d0','9a6ddf69575e488480603c12171ac907',1939,'汪伪特工总部南京区区长','湖南人，汪伪特工骨干，在南京及华中地区从事特务活动，其活动范围覆盖湖南部分沦陷区，与长沙有间接关联。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d7d582d4070f4c459f02ca21629c0edf','a2ac8c21a06a42938393180e489cefbe',1944,'伪长沙维持会会长','长沙本地人，1944年长沙沦陷后组织伪维持会，协助日军维持治安、征粮征夫，直接服务于开福区及长沙城区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('20eb2cffa4774abb88eb202997c8250e','5a8397e87c874b62b0b385feca56af7f',1944,'伪长沙警察局局长','长沙人，长沙沦陷后投靠日军，出任伪警察局长，协助日军镇压抗日分子、管理户籍与治安，直接涉及开福区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dc89fa2ecc3d44638c93d8e6f647b636','cae7b9bbe0ff4982b35c606aba81fa11',1944,'伪湖南保安司令部司令','湖南人，日军占领湖南期间出任伪保安司令，统率伪军配合日军扫荡，活动范围覆盖长沙及开福地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('92a5e986e8784ce88196a4251558fcc5','a717543fb24f409895a297a2c48d24ee',1944,'伪湖南教育厅厅长','湖南人，在长沙沦陷区推行奴化教育，篡改教材、宣传“大东亚共荣”，直接涉及开福区学校。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('20faef1227124c17ac6ac05917c68022','59e12450b8a1438db10fcfaa2be786c2',1944,'伪长沙市商会会长','长沙商人，沦陷后出面组织伪商会，为日军筹款筹物，协助经济掠夺，活动于开福区商业地带。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('39c412ab79fe4f768d3c70bb211f72e2','51cc603628064bf99c4cc926d3628036',1944,'伪长沙县知事','长沙人，日军占领期间出任伪县知事，负责征粮、征夫、维持伪政权，直接管辖开福区部分区域。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ce6a8a6d85f1469fb6f2f6a5d3e421b9','c3cdcc713fc04667a4ac1f2f7c0fc40e',1944,'伪湖南宣传处处长','湖南人，在长沙沦陷区主持伪宣传，散布亲日言论、诋毁抗日力量，活动涉及开福区文化教育界。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('713b5e8277cd45269bc844fa5a0f1773','e71a078ce77e49b2ac59c2eea382aa67',1944,'伪长沙维持会副会长','长沙人，协助伪维持会会长彭年，负责开福区一带的伪化事务，包括派捐、拉夫、情报收集。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ca74d3555cd741f2822ee156131b9e9d','752a41642562417191e81157ce62fdec',1931,'国民党湖南省主席（后与日伪有秘密接触）','湖南醴陵人，主政湖南期间对日态度暧昧，有资料指其与日方有秘密接触，但未公开投敌，与长沙开福有行政关联。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b6bdc6563ff4474c9da07192f7e70289','bb34b45b44c34a018d410cde66579fb1',1939,'汪伪政府湖北省长、伪武汉行营主任、伪军委会委员','湖北黄陂人，汪伪政权在华中地区的重要军事头目，其伪军活动范围涉及湘北、鄂南，与湖南长沙、岳阳一带的伪化统治和清乡有联系，抗战胜利后被处决。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a3429c034b5343428fc5fe2d66d7d3af','a976a94be0bf4b76b621948c0802222f',1933,'伪华北政务委员会顾问、旧军阀附逆者','湖南长沙人，旧湘系军阀，九一八事变后与日本方面勾结，参与伪华北自治活动，1935年在北平被刺杀。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('19a6d90dd7b2438d8e5f871ccf665e06','8a6fd56b100f4e99b238924e753dd95b',1944,'伪长沙维持会成员、伪商会负责人','长沙沦陷期间参与伪维持会活动，协助日军维持地方秩序、征派物资，为日军在长沙的统治提供经济与后勤支持。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('92e47e5877944067acede07f2f0950a9','0575242231424eebaeddece79e7aa4c8',1944,'伪望城县维持会成员','望城沦陷期间参与伪维持会，协助日军在望城一带征派粮食、民夫，维持伪化统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9075f71bbd164d58b782f7bfa93a8a8e','51cc603628064bf99c4cc926d3628036',1943,'伪湖南清乡督办署成员','汪伪政权在湖南推行清乡运动时的伪职官员，参与对长沙周边抗日根据地的封锁与清剿，协助日军镇压抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c161e261ec344b25856ee00234f84249','0482773577634ad19589fcc237ba6aec',1944,'伪湖南省政府筹备人员','汪伪政权曾筹划在湖南沦陷区建立伪省政府，部分人员随日军进入长沙、湘潭一带活动，协助伪化地方行政，具体姓名多散佚。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('db10467b55a54c03878f04cc16957aee','e7ec243906d4478082206f56be9b96f0',1944,'伪长沙维持会会长','长沙沦陷后组织伪维持会，协助日军维持占领区秩序，征发民夫物资。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9a0d4be130934d16a7be8da0ce229aef','31cd2af261044c939a1e441b4aafc180',1944,'伪长沙县县长','日军占领长沙后出任伪长沙县县长，推行伪化统治，为日军征粮派款。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('172b84ee35b7466aa34166e46a503f74','b19edc2e16ec4c7d9462b01fbba0f27f',1944,'伪浏阳县维持会会长','浏阳沦陷期间出面组织维持会，替日军维持地方秩序、征发物资。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f89b061f338346e09009529682350522','eab3c429c5f24a1499cf6d1720c2e57c',1944,'伪浏阳县保安团团长','投靠日军，率部配合日军扫荡浏阳周边抗日武装。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1be1bf785c9548c09b65638699fdcddd','bb34b45b44c34a018d410cde66579fb1',1939,'汪伪政府陆军部长、伪湖北省长','湖北黄陂人，汪伪军事要员，其伪军系统曾扩展至湖南北部，配合日军在湘北作战。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('845254534e844408987135ad3c5f7fd8','072a989933af4ab191441098a6d8461b',1944,'伪湘阴县维持会会长','湘阴沦陷后组织维持会，为日军征集粮食、劳工。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('032eb90538e8438aa3aeb4462e0845b4','a717543fb24f409895a297a2c48d24ee',1944,'伪岳阳县县长','岳阳沦陷后出任伪县长，协助日军控制粤汉铁路沿线。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('46950c9182a44f088b701c621af6166b','752a41642562417191e81157ce62fdec',1931,'原国民党湖南省主席，后未直接附逆但部下多人投伪','其主政湖南期间镇压抗日运动，部分旧部在抗战后期投靠汪伪，如何键系部分军官加入伪军。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0cc496f808124449b7215570af2fe79b','4e96b390a7dc4399859add03fad2d06b',1944,'伪湖南省政府筹备委员','参与日军策划的伪湖南省政府筹备，协助推行伪化行政。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('214a7b5785f743c89d0c940d3ada4655','d251a9f00be546a2b753af31b3a9f1c7',1940,'汪伪政府参军处参军长','湖南浏阳人，唐生智之弟，投靠汪伪，任伪参军长，参与伪军事务。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3c9cdfc62bba4e5381782c445eb11426','4f19196006a34c1b88aeb20e5ccaacdb',1938,'伪长沙县维持会会长（后任汪伪政府军事委员会委员）','抗战初期在长沙地区组织维持会，协助日军维持地方秩序，后投靠汪伪政权，任伪军事委员会委员等职，参与伪军策反与情报活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('453261bef2474196ab19c759b66fc8ce','b0029840ecbd4ef8b36226ecba81c9bc',1938,'伪长沙县维持会副会长','在长沙沦陷期间协助日军建立基层维持会，负责征粮、派夫、维持治安，配合日军清乡行动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('22f600ec32754281994c264bfa11bac3','ea8df813a660484d99c916c7bbdab326',1944,'伪湖南省政府参事、伪长沙市政筹备处处长','长沙沦陷后投靠日伪，参与伪湖南省政府筹备，负责长沙市区伪政权建设与市政管理，协助日军推行保甲制度。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('64caefd0e5804d2796f68f279ba92c45','51cc603628064bf99c4cc926d3628036',1944,'伪长沙县警察局局长','任伪警察局长期间，配合日军搜捕抗日分子，镇压民众反抗，强征劳工，维护日伪统治秩序。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2b4959df26f24f549269e68e19b0c40b','e71a078ce77e49b2ac59c2eea382aa67',1944,'伪湖南省政府委员兼伪长沙市市长','长沙沦陷后出任伪市长，推行日军指令，征收苛捐杂税，协助日军掠夺物资，镇压抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('50c73a38dd474037afec876d157ebd5c','a2e4190c87b449e685d78c118a6801b5',1940,'汪伪政府财政部长、伪湖南省政府主席（未到任但遥控湖南伪政权）','作为汪伪核心人物，参与策划湖南伪政权建立，指派亲信控制长沙等地伪组织，为日军筹款筹粮。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e6b5ba41a7d14c77b48cf1b42dd70169','62a6d6c8e7ab4bbfbc92c5b14abbde74',1940,'汪伪政府立法院长、伪湖南省政府主席（名义）','在汪伪政权中负责湖南等省伪政府人事安排，支持长沙地区伪政权运作，配合日军经济统制。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('971c4af69d36452aae95632909082ff7','bb34b45b44c34a018d410cde66579fb1',1940,'伪武汉行营主任、伪湖南省保安司令','率伪军配合日军进攻湖南，参与长沙会战后的伪化统治，在长沙周边地区清乡、抢粮。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bce0130496c64706acf1918f401e7401','c62729fdd70c49fd989c5d7074930994',1944,'伪长沙县保安大队大队长','组织伪保安大队，配合日军扫荡长沙周边抗日武装，强征民夫修筑工事，残害百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e7f5e692cbf54eab9242cc73b6ab32af','a984f59d907348ba9abd26a16b473797',1944,'伪长沙县教育局局长','在日伪统治下推行奴化教育，修改教材，强制学校教授日语和亲日内容，组织学生参加日伪集会。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('41c43fbfe3d1408c842bb88543f62562','a2d76cf334f74322b7f182e1398ceb87',1944,'伪湖南省宣传处处长','负责日伪在湖南的舆论宣传，创办伪报，散布“大东亚共荣”言论，为日军侵略辩护。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('81bc386bf78642509dbbb0e70da4d221','752a41642562417191e81157ce62fdec',1944,'伪湖南省政府顾问（后期附逆）','原国民党湖南省主席，抗战后期与日伪暗中联系，提供情报，协助日军维持长沙地区秩序。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2e3a4413348c480aba47f8cdc3b6a3f0','d1cfe7bd2c794cd6a4b01c9f3be744b3',1944,'伪湖南省政府委员、伪长沙维持会会长','湖南长沙人，1944年长沙沦陷后出面组织伪长沙维持会，任会长，协助日军维持占领秩序，搜刮物资，是长沙本地有明确记载的汉奸头目。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('84e787372ea5400aab421a34877ab12b','b0029840ecbd4ef8b36226ecba81c9bc',1944,'伪长沙维持会副会长、伪长沙市商会会长','长沙本地商人，1944年日军占领长沙后，与彭允彝等组织伪长沙维持会，任副会长，并控制伪商会，为日军筹款筹粮，属于经济领域附逆者。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f6e7f89c3182426fab2192093d03b876','51cc603628064bf99c4cc926d3628036',1944,'伪湖南省政府警务处长、伪长沙警察局长','湖南长沙人，长沙沦陷后投靠日军，任伪长沙警察局长，后升伪湖南省警务处长，指挥伪警察配合日军镇压抗日活动，搜捕抗日人员。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('32132219e840423f80d4f592acdf632d','ea8df813a660484d99c916c7bbdab326',1944,'伪长沙县县长、伪长沙维持会委员','湖南长沙人，1944年长沙沦陷后出任伪长沙县县长，兼伪维持会委员，负责征粮征夫，协助日军统治长沙县境，包括雨花地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f4c71a59401c4083b3fb4dbd14939a33','a2d76cf334f74322b7f182e1398ceb87',1944,'伪湖南省政府参议、伪长沙自治会会长','湖南长沙人，沦陷后任伪长沙自治会会长，后任伪湖南省政府参议，在长沙及周边地区进行亲日宣传，组织伪自治机构。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1134232a88694124915561ec9d0aa7e4','b915bf764cfc4afcb773979450337438',1944,'伪湖南省政府主席（未就任）、伪军头目','湖南醴陵人，原国民党将领，1944年曾与日军接触，拟任伪湖南省政府主席，后未正式就任，但其活动与湖南沦陷区伪政权筹建有关，与长沙有间接关联。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('958b6a9872f64f7ab1b8ce9f58f70249','d251a9f00be546a2b753af31b3a9f1c7',1944,'伪湖南省政府委员、伪长沙维持会顾问','湖南浏阳人，原国民党元老唐才常之子，1944年长沙沦陷后投敌，任伪长沙维持会顾问，后任伪湖南省政府委员，在长沙从事汉奸活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a623b0a978b34cb2b9f731732dc7692a','65cae6981b0d4ef68f23b0a495d722d1',1944,'伪长沙维持会委员、伪湖南省政府参事','湖南长沙人，长沙沦陷后加入伪维持会，任委员，后任伪湖南省政府参事，协助日军推行保甲制度，在长沙雨花一带活动。','基层维持会/地方自治头目','hanjian');
