INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('df30d3001d5047c6a8dda7c8d05864cf','072a989933af4ab191441098a6d8461b',1944,'伪长沙维持会保甲长、伪长沙县自卫团团长','湖南长沙人，沦陷后任伪长沙县某保保长，后任伪长沙县自卫团团长，配合日军清乡，搜捕抗日分子，活动于长沙雨花地区。','基层帮凶(维持会系统)','hanjian');
