INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2ca9cdb0427d488ba989f683535e5993','3e4b6341bbba4a8bb061001a07219acc',1944,'伪湖南省政府委员、伪长沙市长','湖南长沙人，1944年长沙沦陷后任伪长沙市长，主持伪市政，配合日军征粮征夫，是长沙本地重要汉奸之一。','市县厅局级','hanjian');
