INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f75608e502374b0198acb968c4baf4cb','15ea40782cab4aeeaf9bc5cfb1c06443',1938,'伪甘肃省维持会会长','在兰州地区组织维持会，协助日军维持地方秩序，镇压抗日活动。','基层维持会/地方自治头目','hanjian');
