INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bf02aedfb3b74e98addf3dff20141635','800ab960315a40189c813ce7a4c4de8f',1938,'伪永登县维持会会长','在永登地区组织维持会，为日军征集物资、情报，协助日军控制地方。','基层维持会/地方自治头目','hanjian');
