INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c109fa191aea4a2eb5d8190a37657020','9edb0275b4734a47805ca9385baed31a',1937,'伪甘肃省维持会会长、伪甘肃省省长','抗日战争期间投靠日军，在甘肃地区组织伪政权，曾任伪甘肃省维持会会长、伪甘肃省省长，协助日军维持占领区秩序、推行奴化教育、征发物资。；甘肃临夏人，抗战期间投靠日伪，参与组织伪甘肃省维持会并任会长，后任伪甘肃省省长，为日军在甘肃及西北地区的侵略活动提供协助。；抗日战争时期投靠日军，参与组织伪甘肃省政权，在甘肃地区推行日伪统治，协助日军维持占领区秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('42a7fc04cac6430a8a61d4cd0325a9c3','d82720a670e049b8aac767ce40d97f63',1931,'国民党青海省主席、西北军政长官公署副长官（后期与日伪有接触）','虽为国民党地方军阀，但抗战期间在甘肃、青海地区与日伪方面有秘密接触和妥协行为，其部属在兰州、皋兰一带曾与伪军有往来，被指对日伪态度暧昧。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a27344b43dd3461fa3e0af97b363e9c7','ac23e44f28e64fc7a1d7cd57544b1dc3',1931,'国民党骑兵第五军军长、甘凉肃边防司令（后期附逆嫌疑）','在甘肃河西及兰州地区活动期间，与日伪势力有联系，其部属在皋兰、兰州一带曾出现与伪政权合作的行为，被指对日伪妥协。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('978471ac582e4030a80fac6697628eee','15ea40782cab4aeeaf9bc5cfb1c06443',1938,'伪甘肃省警务处副处长','在兰州、皋兰地区担任伪警务职务，协助日军和伪政权维持治安，参与抓捕抗日人士和镇压民众抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('11fdfbaa1fa84ab4a9d714adb22a3bdc','ad3cb069e32b4d54a63fbdd11c7f1e30',1939,'伪甘肃省教育厅督学、伪兰州维持会教育股长','在兰州、皋兰地区推行奴化教育，编写亲日教材，组织学生参加日伪宣传活动，为伪政权培养亲日人员。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6b1e03794cb24fce972b6711c876259c','800ab960315a40189c813ce7a4c4de8f',1938,'伪皋兰县维持会会长','在皋兰县组织维持会，为日军征发粮食、劳工，协助伪政权维持地方秩序，镇压当地抗日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('13d84a32118a4224bb5280213603960d','cf7f98f286694375a6ebb3fe548d7d6c',1937,'伪甘肃省商会会长','在兰州地区为日伪政权筹集资金、物资，协助日军经济掠夺，控制商会为伪政权服务。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c5b35eb2a72143869eaf7f6b820ec74a','5c736f6219ff4f6aae697448c2eb22fe',1938,'伪兰州警察局局长','在兰州地区担任伪警察局长，参与抓捕抗日分子，镇压民众抗日活动，为日伪政权维持治安。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d26ac8ca7c2d4b9e9753156de21bc9ad','06cd3f06a3354bada4c8c9266ffb346d',1940,'国民党第八十二军军长（后期与日伪有接触）','在甘肃兰州、皋兰地区活动期间，其部属与日伪方面有秘密往来，被指对日伪态度不坚决，有妥协行为。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d72963e8de6343848448ffc27e5b13ef','1e395f37b28f47d9bfbea8f1b08b4816',1931,'国民党新编第十四师师长（后期附逆嫌疑）','在甘肃南部及兰州地区活动期间，与日伪势力有联系，其部属在皋兰一带曾出现与伪政权合作的行为。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dbe69bf79a3649e8859ce19f33fad4d6','d82720a670e049b8aac767ce40d97f63',1931,'青海省主席、国民党军将领（后期与日伪有秘密接触）','虽未公开投敌，但抗战期间与日伪有秘密接触和交易，其势力范围覆盖甘肃、青海，对天水地区有影响，历史记载中其部分行为被视为附逆倾向。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f4724f6956fe43079de03b2fd425f97e','dae5cb8a53584c088365fd37339abce0',1937,'伪甘肃省维持会副会长','甘肃临夏人，与马良共同组织伪甘肃省维持会，任副会长，协助日军在甘肃的渗透和情报收集。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cca58e5a68e94eaf9ee5ddc408b90315','8e6a3022c13643e2afb331aca67024d8',1938,'伪天水县维持会会长','天水本地人，抗战期间组织伪天水县维持会并任会长，为日军提供物资、情报，协助维持日占区秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4a4476d08dc74a09b970c5c7e1c67b1f','ad3cb069e32b4d54a63fbdd11c7f1e30',1939,'伪秦州维持会副会长','秦州（今天水秦州区）人，任伪秦州维持会副会长，协助日军征粮、征夫，参与伪政权基层管理。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a56c1a99208d4125a0d3d6dbe24ceb2c','800ab960315a40189c813ce7a4c4de8f',1940,'伪天水县警察局局长','天水人，任伪天水县警察局局长，配合日军镇压抗日活动，抓捕抗日志士，维护日伪统治。','市县厅局级','hanjian');
