INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('811961fcc6d74973bb07439d922a5d70','06cd3f06a3354bada4c8c9266ffb346d',1940,'国民党军将领（后期与日伪有联系）','马步芳之子，其部队在甘肃天水一带活动，抗战期间与日伪有秘密联系，历史记载中其部分行为被视为附逆。','无明确职位或一般帮凶','hanjian');
