INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5585112df39c451687c10d79e4726433','2e76231301494145a9d8177ef49c8fa6',1930,'伪军头目','在甘肃平凉、静宁一带活动，组织伪军，投靠日伪，参与镇压抗日武装，维持伪政权统治。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6266b22bde94479dafb0942a59a1ca48','6611292d5ae54fae913d2b0650ab3e83',1930,'伪军头目','在甘肃地区活动，曾与日伪势力勾结，其部属在平凉一带参与伪军活动，协助日伪维持地方。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6dd14acbc28d42cb84188639bc2d9b59','f28330eb828a4a6bab2717ec3e6a91e4',1938,'伪平凉县维持会会长','在平凉县组织维持会，协助日军维持地方秩序，征粮征夫，镇压抗日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cf683ca66cd34a589fb1e54667daeb7b','d99c5d314d6e49c5bbfdb73e54c9f561',1939,'伪静宁县维持会会长','在静宁县组织维持会，投靠日伪，协助日军征粮征夫，维持伪政权统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ef7be4c8755d458996c41856fd7ee075','912d4e9b8d884278a822733fc25af12e',1938,'伪甘肃省教育厅长','在甘肃地区推行亲日教育，协助日伪进行文化渗透，在平凉、静宁等地设立亲日学校。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6e64c38d7fa4435e86a67b6e91cc62de','ac23e44f28e64fc7a1d7cd57544b1dc3',1937,'地方军阀、伪政权合作者','在甘肃地区与日伪有联系，其部属在平凉一带参与伪军活动，协助日伪维持地方秩序。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a50b34a71ad94062bc757a8a385f95f9','f50cf011f8f842fc8d69caa402ffbf67',1938,'伪福建省政府主席、伪福建省保安司令','抗战期间投靠日军，出任伪福建省政府主席，在福建沦陷区推行伪化统治，组织伪保安武装配合日军维持占领秩序。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('15d5243ce2ac48a08414b1199b9b0777','6e5e5467e9da41e1a8da46c8a2f13202',1938,'伪福建省政府委员、伪厦门特别市市长','厦门沦陷后附逆，历任伪厦门特别市市长等职，协助日军管理厦门及闽南部分地区，推行伪政权的行政、经济与宣传措施。；福建人，抗战期间投靠日军，历任伪厦门特别市市长、伪福建省政府委员，在厦门及闽南地区为日军搜集物资、推行伪化教育、协助维持治安。；福建汉奸，在日军占领厦门后出任伪职，协助日军维持厦门地区治安，推行奴化教育，搜刮物资支持日军。；福建汉奸，在日军占领厦门后出任伪职，协助日军维持厦门及闽南地区治安，推行奴化教育。；福建人，抗战期间投靠日军，历任伪厦门特别市市长、伪福建省政府委员，在厦门及闽南地区推行伪化统治，为日军搜集物资、镇压抗日民众。；福建籍汉奸，日军占领厦门后出任伪厦门特别市市长，后任伪福建省政府委员，协助日军在福建沿海推行殖民统治，其伪政权体系延伸至福建内陆，对南平、建瓯地区产生政治影响。；福建厦门人，厦门沦陷后投靠日军，历任伪厦门特别市市长、伪福建省政府委员，推行日语教育、配给制度，协助日军镇压抗日活动。；福建人，抗战期间投靠日军，在厦门沦陷区任伪厦门特别市市长、伪福建省政府委员，协助日军维持厦门及闽南部分地区治安，推行奴化教育。；福建人，抗战期间投靠日军，历任伪厦门特别市市长、伪福建省政府委员，在厦门及闽南地区为日军搜集物资、推行奴化教育。；福建人，抗战期间投靠日军，在厦门沦陷区任伪厦门特别市市长等职，配合日军维持厦门及闽南沿海伪政权。；在日军占领厦门后出任伪职，协助日军维持厦门及闽南地区治安，推行奴化教育，配合日军经济掠夺。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('60edfd5b7c4549349909a494f3c9c292','4fa04cb35f9e4c95ad05f733a74b3cd4',1938,'伪厦门特别市市长、伪厦门维持会会长','厦门沦陷后组织维持会并出任伪市长，为日军筹粮筹款、维持地方伪秩序，是闽南地区有明确记载的附逆人物。；厦门人，厦门沦陷后组织伪维持会并任会长，后任伪厦门特别市市长，为日军筹款筹粮、推行奴化教育。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('225944d310684cd69bbdb53287690204','fea5ba2d5e614ac086086bd338dbef85',1938,'伪军头目、伪福建和平救国军总司令','抗战初期在福建沿海投敌，收编土匪与散兵组织伪军，配合日军在闽海地区进行骚扰与伪化活动。；在福建沿海及内陆地区收编土匪、散兵组成伪军，配合日军进攻抗日根据地，活动范围涉及闽中、闽西一带，包括三明周边地区。；在福建沿海及闽东一带收编土匪、组织伪军，配合日军扫荡抗日武装，活动范围涉及宁德、福安等闽东地区。；在福建沿海及闽西南一带收编土匪、散兵组成伪军，配合日军扫荡抗日根据地，活动范围涉及龙岩、漳州、厦门周边，对闽西地区构成威胁。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4f4846e7c7c84bcca78c48d7327b2568','39d7e12cd51d4fbb84f2698489557225',1938,'伪福建和平救国军副总司令、伪军头目','在福建沿海及闽中地区活动，率伪军配合日军作战与征粮，参与对沿海抗日力量的镇压。；与黄大伟等在福建沿海岛屿及闽东地区组织伪军，劫掠民船、袭击抗日游击队，控制部分海上通道。；与黄大伟等在福建沿海岛屿及闽南、闽西边缘地区活动，组织伪军配合日军进攻抗日游击队，参与经济封锁与情报搜集。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('48709ea4820d4dfdaefb9995182759b0','8862ed3d4daf4699917b288cbf92137a',1938,'伪三明地区维持会头目（地方伪维持会）','在三明及周边地区组织伪维持会，协助日军与伪政权征派粮款、登记户口、维持地方伪秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f2d089a3a5d64fcba3ae217b0c80cbac','92cecf241ba1466f9b6dc0b05b392546',1938,'伪尤溪县维持会会长（地方伪维持会）','尤溪地区附逆人物，组织伪维持会，为日军及伪政权筹粮、派夫、维持地方伪统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b1cbde61b7fd45488cbf65d21060e2d5','5b3dd4770b784a469f04d2889688c79c',1938,'伪厦门维持会委员、教育文化界附逆者','在厦门沦陷区参与伪维持会与伪教育文化机构，协助日军推行奴化宣传与伪化教育。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e05d951c08404c2c86f40af401876524','1b8a6643bb394487acd9c3f4464ea524',1938,'伪厦门商会头目、经济界附逆者','厦门沦陷后与日军合作，控制商会与物资配给，为伪政权筹款筹物，属经济领域附逆者。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0aa4acf5b8d2497cb7cf4b1186b6ba51','b3850c3edab946ddb11a3ea25791bd08',1938,'伪闽南保甲长、地方伪基层头目','在闽南及闽中部分地区担任伪保甲长，协助日军与伪政权征粮、派夫、监视抗日人员。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('da96b5ea5e594e7a88d86c9c58165b8c','f50cf011f8f842fc8d69caa402ffbf67',1938,'伪福建省政府主席、伪南京国民政府内政部部长','福建长汀人，早年投靠日本，参与组织伪政权。1938年后任伪中华民国维新政府内政部部长，后任伪南京国民政府内政部部长、伪福建省政府主席，协助日军在福建推行殖民统治与清乡。；福建籍汉奸，早年投靠日本，参与组织伪政权，曾任伪福建省政府主席，协助日军在福建推行殖民统治，镇压抗日活动。；福建籍汉奸，早年投靠日本，参与组织伪维新政府，后任伪福建省政府主席，协助日军在福建推行殖民统治，镇压抗日活动。；福建长汀人，早年投靠日伪，1938年后任伪中华民国维新政府内政部部长，后任伪福建省政府主席，协助日军在福建推行殖民统治，镇压抗日活动。；福建籍汉奸，早年投靠日本，参与组织伪政权。1938年后历任伪中华民国维新政府内政部部长、伪南京国民政府内政部部长等职，为日军在福建及东南沿海的统治提供支持，其活动范围覆盖福建全省，对南平、建瓯等地有间接影响。；福建长汀人，早年投靠日伪，1938年后任伪中华民国维新政府内政部部长，后任伪南京国民政府内政部部长、伪福建省政府主席，参与日伪在福建的统治与诱降活动。；福建长汀人，早年即投靠日伪，1938年后参与伪维新政府、汪伪政权，历任伪内政部部长、伪福建省政府主席等职，在福建推行伪化统治，为日军搜刮物资、镇压抗日力量。；福建长汀人，早年投靠日伪，1938年后参与伪维新政府，后任汪伪政权内政部部长、伪福建省政府主席等职，协助日军在福建推行伪化统治。；福建长汀人，早年投靠日伪，1938年后参与伪维新政府，后任伪南京国民政府内政部部长、伪福建省政府主席等职，协助日军在福建推行伪化统治。；福建福州人，早年投靠日伪，1938年后参与伪维新政府，后任伪南京国民政府内政部部长、伪福建省政府主席等职，协助日军在福建推行伪化统治。；福建福州人，早年投靠日伪，1938年后历任伪中华民国维新政府内政部部长、伪南京国民政府内政部部长等职，参与日伪政权对福建及东南沿海的统治与渗透。；福建籍汉奸，早年投靠日伪，曾任伪中华民国维新政府内政部部长，后任伪福建省政府主席，协助日军在福建推行殖民统治，镇压抗日力量。；福建长乐人，早年投靠日伪，1938年后参与伪维新政府，后任伪南京国民政府内政部部长、伪福建省政府主席，协助日军在福建推行伪化统治。；福建籍汉奸，早年投靠日伪，历任伪中华民国维新政府内政部部长、伪南京国民政府内政部部长、伪福建省政府主席等职，协助日军在福建推行殖民统治。；福建长汀人，早年投靠日伪，1938年后参与伪维新政府，后任伪南京国民政府内政部部长、伪福建省政府主席，协助日军在福建推行伪化统治。；福建籍汉奸，早年投靠日本，参与组织伪政权。1938年后任伪中华民国维新政府内政部部长，后任伪南京国民政府内政部部长、伪福建省政府主席等职，协助日军在福建推行殖民统治，镇压抗日活动。；福建籍汉奸，早年投靠日本，参与组织伪政权。1938年后历任伪中华民国维新政府内政部部长、伪南京国民政府内政部部长、伪福建省政府主席等职，协助日军在福建推行殖民统治，镇压抗日力量。；福建籍汉奸，早年投靠日本，参与组织伪政权。1938年后历任伪中华民国维新政府内政部部长、伪南京国民政府内政部部长、伪福建省政府主席等职，协助日军在福建推行殖民统治，镇压抗日活动。；福建籍汉奸，早年投靠日本，参与组织伪政权。1938年后在福建日占区及南京伪政府中任职，曾任伪内政部部长、伪福建省政府主席等职，协助日军推行殖民统治、征发物资与劳工。；福建籍汉奸，早年投靠日本，参与组织伪政权。1938年后在伪中华民国维新政府、汪伪国民政府中任要职，曾任伪内政部部长、伪江苏省省长等，虽主要活动于南京、江苏，但作为福建籍伪政权高层，对福建沦陷区伪政权建立有影响。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8ad8fd562e294be6bc0fd2ff4f1681eb','4fa04cb35f9e4c95ad05f733a74b3cd4',1938,'伪厦门维持会会长、伪厦门特别市市长','厦门沦陷后组织伪厦门维持会，后任伪厦门特别市市长，协助日军管理厦门，镇压抗日活动，为日军筹粮筹款。；厦门沦陷后组织伪维持会，后任伪市长，为日军筹集粮秣、劳工，配合日军清乡，迫害抗日群众。；厦门沦陷后组织维持会，后任伪市长，为日军筹粮筹款，镇压抗日分子。；厦门沦陷后组织伪维持会，后任伪厦门特别市市长，协助日军维持治安、征收物资，迫害抗日志士。；厦门沦陷后组织伪维持会，后任伪厦门特别市市长，积极配合日军在福建的军事行动与经济掠夺，其伪政权网络与福建内陆的伪组织有联系。；厦门沦陷后组织伪厦门维持会并任会长，后任伪厦门特别市市长，为日军筹粮筹款、征发劳工，镇压厦门抗日活动。；厦门沦陷后组织伪维持会，后任伪厦门特别市市长，协助日军维持治安、征调劳工，镇压厦门及周边抗日力量。；厦门沦陷后出面组织伪维持会，后任伪厦门特别市市长，协助日军控制厦门港口与地方秩序。；厦门沦陷后组织维持会，后任伪市长，为日军筹粮筹款，协助建立伪警察队伍，镇压抗日分子。；厦门沦陷后组织伪维持会，后任伪厦门特别市市长，为日军征集物资、推行奴化教育，是闽南地区重要汉奸。；厦门沦陷后出面组织维持会，后任伪市长，为日军筹款、征粮、招募劳工，配合日军经济掠夺和治安强化。；厦门沦陷后组织维持会，后任伪市长，配合日军在闽南地区进行经济掠夺和奴化教育。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6612dcf011bb40cca6a20f38ff4dc353','fea5ba2d5e614ac086086bd338dbef85',1938,'伪闽粤边区绥靖军总司令','广东人，抗战期间投靠日军，组织伪军活动于闽粤边区，包括福建南部及三明周边地区，配合日军扫荡抗日武装。；广东人，抗战期间投靠日军，任伪闽粤边区绥靖军总司令，率伪军在闽南、粤东地区配合日军扫荡抗日武装，残害百姓。；广东籍汉奸，受日军指使在闽粤边区组建伪军，活动范围包括福建南部及沿海地区，曾试图向福建内陆渗透，对南平、建瓯一带的抗日力量构成威胁。；广东人，抗战期间投靠日军，组织伪军活动于闽粤边区，曾率部配合日军进攻福建南部及闽西地区，骚扰抗日根据地。；广东人，抗战期间投靠日军，任伪闽粤边区绥靖军总司令，率伪军活动于闽粤边区，配合日军进攻抗日根据地，在福建南部及闽西一带进行清乡、掠夺。；福建人，原国民党将领，1939年投敌，任伪闽粤边区绥靖军总司令，在闽南、粤东一带配合日军扫荡抗日游击队。；在闽南、粤东一带组织伪军，配合日军行动，势力范围涉及泉州外围地区。；原为国民党军将领，抗战初期投敌，在福建南部及粤东一带收编土匪、组织伪军，配合日军在漳州、潮汕沿海地区进行骚扰和渗透活动。；原为国民党军将领，抗战初期投敌，在福建、广东交界地区组织伪军，配合日军进攻闽南，活动范围覆盖漳州、云霄一带。；抗战初期在福建沿海及闽南一带活动，组织伪军配合日军进攻，曾率部进犯漳州、诏安、东山等地，后因内部矛盾被日军处决。；抗战初期在福建沿海及闽南一带活动，收编土匪、散兵组织伪军，配合日军在闽粤边区进行骚扰和渗透，后因内部矛盾被日军处死。；抗战初期在福建沿海及闽南一带活动，组织伪军配合日军进攻，后因内部矛盾被日军处决。；原为国民党军将领，抗战初期投敌，在福建漳州、潮汕一带收编土匪与散兵游勇，组织伪军配合日军进攻闽南，曾率部进犯漳浦、云霄等地，后因内部矛盾被日军处死。；原为国民党军将领，抗战初期投敌，在闽南、粤东一带收编土匪与散兵游勇，组织伪军配合日军进攻漳州、诏安等闽粤边区，进行清乡与掠夺。；福建人，抗战期间投靠日军，组织伪闽粤边区绥靖军并任总司令，在福建、广东交界地区配合日军扫荡抗日根据地。；福建人，抗战期间投靠日军，组织伪军活动于闽粤边区，配合日军进攻抗日根据地。；广东籍汉奸，抗战期间在闽粤边区组织伪军，配合日军进攻闽西南抗日根据地，活动范围涉及福建龙岩、漳州及广东潮汕一带，对长汀等闽西地区构成威胁。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('88656ca74fef4b48997552b93ca40712','39d7e12cd51d4fbb84f2698489557225',1938,'伪福建和平救国军总司令','福建沿海人，组织伪福建和平救国军，活动于福建沿海及闽中地区，包括三明东部邻近区域，为日军搜集情报、封锁沿海、袭击抗日游击队。；福建沿海汉奸武装头目，率部配合日军在闽海地区进行扫荡，袭击抗日游击队。；福建沿海人，组织伪福建和平救国军，配合日军在福建沿海及南平周边地区进行清乡、扫荡，掠夺物资，镇压抗日力量。；福建沿海汉奸武装头目，组织伪“和平救国军”配合日军在福建沿海及内陆的扫荡，其势力范围一度扩展至闽北地区，对南平、建瓯等地进行骚扰和破坏。；福建沿海人，抗战期间组织伪福建和平救国军，活动于闽江口及南平、建阳周边地区，配合日军扫荡、封锁抗日游击区。；福建沿海人，抗战期间组织伪福建和平救国军并任总司令，盘踞闽海岛屿，配合日军封锁福建沿海，劫掠商船、残害抗日军民。；福建沿海海盗出身，抗战期间投靠日军，任伪福建和平救国军总司令，在闽江口及南平、武夷山周边地区劫掠、配合日军封锁抗日根据地。；在福建沿海及厦门周边海域活动，率伪军配合日军封锁海岸、劫掠商船、镇压抗日力量。；福建沿海伪军头目，活动于闽东沿海包括福鼎、霞浦一带，率部配合日军进攻抗日武装，劫掠沿海村庄。；率部投敌，所部活动于闽东沿海包括宁德、霞浦一带，配合日军封锁海岸、劫掠抗日根据地。；组织伪军盘踞闽南沿海，配合日军扫荡，在泉州、惠安一带活动。；福建沿海伪军头目，在厦门、金门、泉州、晋江一带海域活动，劫掠商船、袭击抗日游击队，为日军提供沿海情报与运输支持。；率部投敌，编为伪福建和平救国军，在福建沿海包括泉州、晋江一带配合日军进行扫荡与封锁。；福建沿海人，抗战期间组织伪福建和平救国军并任总司令，配合日军在福建沿海及福州周边进行扫荡、封锁，袭击抗日武装。；福建沿海伪军头目，组织伪福建和平救国军，配合日军在福建沿海及福州地区进行扫荡、封锁和伪化活动。；福建沿海伪军头目，率部配合日军在福州、平潭及闽江口一带进行清乡、扫荡。；福建沿海伪军头目，率部配合日军在福州、福清、平潭一带进行扫荡、封锁与掠夺。；福建沿海海盗出身，投靠日军后组织伪福建和平救国军，在闽海一带配合日军扫荡抗日游击队，抢劫民船，残害百姓。；福建沿海汉奸武装头目，组织伪军配合日军在福建沿海进行扫荡，抢劫民船，封锁抗日根据地，残害沿海渔民。；福建沿海伪军头目，率部配合日军在福州、长乐一带登陆作战，袭击抗日游击队，抢掠沿海村庄。；福建沿海伪军头目，率部配合日军在福建沿海及福州附近进行清乡、扫荡，残害抗日军民。；福建沿海伪军头目，组织伪军配合日军在福建沿海进行扫荡、封锁，袭击抗日游击队。；福建沿海伪军头目，组织伪福建和平救国军，配合日军在莆田、仙游、福清等沿海地区进行扫荡和统治。；福建沿海著名汉奸武装头目，率伪军配合日军在莆田、湄洲湾一带登陆与扫荡，劫掠沿海村庄，协助日军控制海上交通线。；福建沿海伪军头目，组织伪和平救国军，活动于莆田、涵江、福清等沿海地区，配合日军扫荡抗日游击队，抢劫民财，残害百姓。；福建沿海伪军头目，组织伪福建和平救国军，配合日军在莆田、湄洲湾一带进行海上封锁、登陆扫荡，残害抗日军民。；福建沿海汉奸武装头目，组织伪军配合日军在福建沿海及内陆进行扫荡，曾活动于闽中、闽西边缘地带，参与对龙岩、长汀等抗日根据地的封锁与进攻。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7d772767f22a41e2877357dc5764e169','c6a682cb9d834e4a910285cc9abb8db2',1938,'伪福建自治军司令','福建人，抗战初期投靠日军，在福建内地组织伪自治军，活动范围涉及闽中、闽西北，包括三明一带，协助日军维持占领区秩序。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3d73d4f8230c427ca63e65d7b098b70d','d05e74cda37843e1bc5ddff20e42caa4',1940,'伪永安维持会会长','永安当地士绅，抗战期间投靠日军，组织伪永安维持会，协助日军在永安及周边地区征粮、派款、维持治安，镇压抗日群众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8cbc705ed88540efb284734565279a8f','8fc8273603404d9ab0b2bbefe2cb7b76',1940,'伪三明维持会会长','三明本地人，抗战期间投靠日军，组织伪三明维持会，为日军搜集情报、征调民夫、协助伪化统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9a8a477585fb48a882616ec303c76b6a','0ef290e1d1564bbcafa9ae81ebcc32f9',1940,'伪福建省政府警务处处长','福建人，在伪福建省政府任职，负责伪警察系统，协助日军在福建各地包括三明地区实施保甲连坐、搜捕抗日人士。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('63e3b34637134145b17dad0a9b02bf0d','50380aeea4d040e7b7134a1f53cc71e3',1940,'伪福建省政府委员、伪福州市市长','福建人，抗战期间投靠日军，历任伪福州市市长、伪福建省政府委员，在福州及闽中地区推行伪化教育、经济统制，影响波及三明。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c32a59f8bfd845cb88b4887c385c84c6','39d7e12cd51d4fbb84f2698489557225',1938,'伪福建和平救国军副总司令','与黄大伟共同组织伪军，在福建沿海及闽江流域活动，协助日军扫荡抗日武装，其势力曾延伸至三明、清流附近区域。；与王英共同在福建沿海活动，率伪军配合日军进攻闽东抗日根据地，掠夺沿海资源。；福建伪军头目之一，活动于闽中沿海包括莆田、秀屿一带，协助日军控制海上交通线，参与对抗日游击队的围剿。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('874fc81de4f047bd901dbcb902446e03','9fc88af18cad40a589714d4003e388b7',1940,'伪三明维持会会长','三明地区沦陷期间组织伪维持会，为日军提供情报、粮食和劳工，协助日军控制三明一带，镇压当地抗日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fc5d727e265240e39acbaad0104aeebe','887df721e0d24be29f77b02d48dbc15f',1940,'伪清流县维持会会长','清流县汉奸，日军侵入时组织伪维持会，协助日军征粮、派夫，迫害抗日家属，维持日占区秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('621e56be3a454bbc8a622fe9bf797927','0ef290e1d1564bbcafa9ae81ebcc32f9',1940,'伪清流县保安队队长','清流县伪保安队头目，带领伪军配合日军清乡，搜捕抗日游击队员，残害当地百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b49c546e5c3747cf9379506f7df7a1fd','8fc8273603404d9ab0b2bbefe2cb7b76',1940,'伪三明县警察局局长','在三明地区担任伪警察局长，协助日军维持治安，镇压抗日分子，推行保甲连坐制度。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8c870b68a3524c2f9688ccd216fcce82','684a6c44d1b64fe089227ceb21abb484',1938,'伪福建省教育厅厅长','福建汉奸，在伪政府中负责教育，推行奴化教育，篡改历史教材，为日军侵略辩护，影响范围覆盖福建全省包括三明地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('75083cc979944824a13f48d9a8b8d640','8080e794604c46f3b9f75b994f250c1e',1940,'伪三明县保甲长','三明地区保甲长，协助日军登记户口、征收赋税、监视居民，举报抗日人员，是基层汉奸典型。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('52f55bcaaefe45f1ad9841a6590fd723','f850c0a1049b4e7bbae00e216590fc94',1940,'伪清流县经济维持会干事','清流县经济汉奸，为日军收购粮食、木材等物资，垄断当地贸易，配合日军经济掠夺。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3419000b36de4712b8a8a3252b799c17','777d6386fff54ff4a32b34f8c190b669',1939,'伪厦门特别市警察局局长','在厦门协助日军建立伪警察系统，搜捕抗日人士，迫害无辜民众。；在厦门任伪警察头目，配合日军搜捕抗日人士，推行保甲连坐，控制厦门市区治安。；在厦门及闽南沿海地区组织伪警察力量，配合日军搜捕抗日人士，镇压民众抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1f1975e0aa194535a68eea156bb8e9e1','71cde56ac97742afb07175181b79f77c',1941,'伪福州维持会会长','福州两次沦陷期间组织维持会，为日军服务，协助征发劳役和物资。；福州两次沦陷期间，参与组织伪福州维持会并任会长，协助日军征粮、拉夫、维持占领秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a2842d72c44e41478e5158d7a1772f93','89a84dc33c8543618a76ac5b4bdf9a71',1941,'伪福州市政筹备处主任','福州沦陷时出任伪职，协助日军管理福州事务，推行保甲制度。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c87798b98a6f4cafb5232c82e45c272a','672a06dace82471ea7a4612b03f5f249',1941,'伪闽侯县维持会会长','闽侯沦陷期间组织维持会，为日军征粮征夫，压制抗日活动。；在闽侯组织维持会，配合日军在福州周边地区征粮征夫，协助建立伪保甲制度。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8881c6da076f437c8d1f168582ea613f','fea5ba2d5e614ac086086bd338dbef85',1938,'伪福建和平救国军副总司令','与张逸舟共同组织伪军，在福建沿海岛屿活动，为日军提供情报和后勤支持。；协助张逸舟统率伪军，在闽南沿海配合日军作战，参与对抗日根据地的扫荡。；与张逸舟共同在闽东沿海组织伪军，协助日军控制沿海岛屿和港口，参与对抗日根据地的封锁。；广东人，后活动于闽南，与高义、陈少平合流，在泉州沿海组织伪军，配合日军对泉港、惠安等地的登陆作战与清乡。；协助张逸舟组织伪福建和平救国军，在福建沿海及福州附近配合日军作战，参与伪化统治。；与张逸舟共同组织伪军，在福建沿海岛屿及福州周边协助日军作战。；福建籍汉奸，协助张逸舟组织伪军，在福州、连江、长乐沿海地区配合日军作战，镇压抗日游击队。；与张逸舟合作，在莆田沿海及岛屿活动，收编海盗与散兵组成伪军，为日军提供沿海情报与后勤支持。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('50a1934502e74ccd9a9d4f71891d2539','dc1400859be6498492e00f07bb3a75fe',1944,'伪南平维持会会长（未遂）','据地方史料记载，南平地区曾有汉奸试图组织维持会迎接日军，翁尚功为其中主要策划者之一，后因日军未深入南平而未能得逞。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aa1f78785e3b40619d9df5164f768f3f','50380aeea4d040e7b7134a1f53cc71e3',1944,'伪光泽县维持会筹备人员','光泽县地方档案提及，抗战后期有少数地方士绅与日伪暗通款曲，陈则民被指为其中代表，试图在光泽组织伪政权，但未及成立即抗战胜利。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0850c7aa591245d0bc3b03762efb4206','9fc88af18cad40a589714d4003e388b7',1940,'伪南平县维持会会长','南平本地人，日军侵扰南平期间组织伪维持会，为日军筹粮、带路，协助维持伪秩序，压迫当地民众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5283f1221b6a485a8834530148e64b14','92cecf241ba1466f9b6dc0b05b392546',1940,'伪延平县维持会副会长','延平本地士绅，抗战期间附逆，任伪延平县维持会副会长，协助日军征发民夫、物资，宣传“中日亲善”。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ed49b69a655e4683a59920da98030a29','e458a60e4de7461fb94fe46dafb82c89',1941,'伪南平县警察局局长','南平人，任伪南平县警察局局长，带领伪警察配合日军搜捕抗日分子，勒索百姓，维持伪政权治安。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dae95d0c4f204987abbf57e81a815493','684a6c44d1b64fe089227ceb21abb484',1938,'伪福建省政府委员、伪教育厅厅长','福建人，投靠日伪，任伪福建省政府委员兼教育厅厅长，推行奴化教育，篡改教材，毒害青年。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ca275f5511fe47eeb596dc54425a7fd3','0ef290e1d1564bbcafa9ae81ebcc32f9',1940,'伪南平县保甲长','南平乡村保甲长，附逆日军，负责摊派捐税、监视村民，举报抗日人员，协助日军维持基层统治。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e2e36670d42045baa2899f7ce69d6ba4','c6a682cb9d834e4a910285cc9abb8db2',1941,'伪闽北维持会会长','在南平、建瓯一带组织伪维持会，协助日军维持占领区秩序，推行保甲制度，为日军征粮征税，镇压抗日活动，是闽北地区直接为日军服务的汉奸头目。；福建南平人，抗战期间在南平、建阳一带组织伪维持会，协助日军征粮、拉夫，维持沦陷区秩序，参与诱降地方抗日武装。；南平地区人，1941年日军侵入闽北时组织伪维持会，任会长，为日军征粮、带路，协助镇压当地抗日武装。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6c5f7d9d7f894f189121f8d7430dfdc9','da81f2be49ba477e9dfca29887ad5a09',1941,'伪建瓯县维持会会长','建瓯本地汉奸，日军侵占建瓯期间出面组织伪维持会，担任会长，负责为日军筹集物资、招募劳工、传递情报，并协助日军镇压当地抗日民众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('22a1db4c554f4f199f3a7b53a242528d','c6df24aab02e4bbfb993cf6c0e5708c7',1941,'伪南平县维持会副会长','南平本地劣绅，日军进犯南平时投敌，出任伪维持会副会长，协助日军推行殖民统治，参与征粮、征丁，迫害抗日家属。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f0bc3e6501f54404aab29d67937abf3b','8fc8273603404d9ab0b2bbefe2cb7b76',1940,'伪福建省政府警务处处长','福建籍汉奸，在伪福建省政府中主管警务，建立伪警察体系，配合日军在福建各地搜捕抗日人士，其警务网络覆盖南平、建瓯等闽北地区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5cf3796324484a26af2088dc591905ae','df916836002c470b8a29148a15536a90',1942,'伪闽北保安团团长','组织伪保安团在闽北地区活动，配合日军对南平、建瓯一带的抗日根据地进行扫荡，烧杀抢掠，残害百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('21b8016a9e834419843bdcff630d4c15','25a9cdc616bb48faaa13ce8720cdd5b5',1938,'伪福建省政府委员、伪福州市政筹备处处长','福建福州人，抗战期间附逆，任伪福建省政府委员等职，协助日军维持福州及周边地区伪政权，参与征粮、拉夫与宣传亲日活动。；福建福州人，抗战期间附逆，在伪福建省政权中任职，参与日军控制下的福州地方伪政权筹备与维持活动。；福州人，抗战期间附逆，在伪福建省政府任职，参与福州地区伪政权筹备与维持活动。；福州人，投靠日军后历任伪福建省政府要职，参与组织伪政权，推行奴化教育，协助日军征粮征税，压迫福州民众。；福州人，抗战期间附逆，在伪福建省政府任职，参与伪政权在福州地区的行政筹备与殖民统治事务。；福州人，抗战期间附逆，在伪福建省政府任职，参与福州地区伪政权筹备与维持事务。；福州人，抗战期间附逆，在伪福建省政权中任职，参与日伪对福州地区的统治与物资征调。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('da42fb6e6e704da2b2597313f43e79da','4fa04cb35f9e4c95ad05f733a74b3cd4',1938,'伪厦门特别市市长','福建厦门人，厦门沦陷后任伪厦门维持会会长、伪厦门特别市市长，为日军筹款筹粮，推行奴化教育，搜捕抗日人士。；继陈群之后任伪厦门特别市市长，配合日军实施经济统制、物资配给和治安强化运动，镇压抗日活动。；厦门沦陷后出任伪厦门特别市市长，配合日军维持厦门占领区秩序，推行伪化行政。；作为福建沦陷区最高伪政权头目之一，其政令覆盖泉州沿海一带，推行奴化教育、经济统制，协助日军掠夺福建资源。；厦门沦陷后出任伪市长，推行日军殖民统治政策，在闽南地区配合日军进行经济掠夺和奴化教育。；抗战期间出任日伪厦门特别市市长，协助日军维持沦陷区统治，是福建地区有明确记载的伪政权头目之一。；厦门沦陷后出任伪市长，推行日军殖民统治，配合经济掠夺与奴化教育。；厦门沦陷后投敌，历任伪厦门维持会会长、伪厦门特别市市长，配合日军在闽南包括泉州沿海地区的统治与清乡。；继陈裔之后任伪厦门市长，推行伪化教育、经济统制。；在厦门伪政权中历任要职，配合日军实施经济统制与奴化教育。；福建厦门人，日军侵占厦门后出任伪厦门维持会会长、伪厦门特别市市长，协助日军统治厦门及闽南沿海地区。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('50c0524cef40417baa1bbdbb140bc414','da81f2be49ba477e9dfca29887ad5a09',1941,'伪建阳县维持会会长','福建建阳人，建阳沦陷期间任伪维持会会长，为日军筹办粮秣、夫役，协助推行保甲连坐，镇压当地抗日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('77b7ff4249904f2698f66ff7c7f07d4e','672a06dace82471ea7a4612b03f5f249',1941,'伪南平县维持会副会长','福建南平人，南平沦陷期间任伪维持会副会长，协助日军管理地方，征发民夫物资，参与奴化宣传。','基层维持会/地方自治头目','hanjian');
