INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2b7959c558c44692bf37428347d09b8f','3b34868627504ce894fc790af9d9ec95',1939,'伪厦门特别市参议会参议员','厦门知名商人，附逆后参与伪政权咨询机构，为日军统治粉饰门面。；以地方士绅身份参加伪参议会，为日伪统治粉饰门面。；厦门富商，抗战期间附逆，任伪参议员，为日军经济统治效力，与泉州商界有往来。；厦门富商，抗战期间附逆，出任伪参议员，协助日军在闽南推行伪政，其商业网络涉及泉州、惠安。；作为厦门商界人物，在沦陷后参加伪参议会，为日军统治粉饰太平，协助摊派捐税。','无明确职位或一般帮凶','hanjian');
