INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b04b48f407864260b80290746f1ad172','50380aeea4d040e7b7134a1f53cc71e3',1941,'伪福州维持会会长、伪福州市政筹备处主任','福州沦陷后出任伪职，协助日军维持福州及闽东地区秩序，推行奴化教育，为日军筹集物资。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d29e5fd766fd4e45ab8d647cd7d08b4c','df916836002c470b8a29148a15536a90',1942,'伪福建省政府教育厅督学','在福建伪政权中负责教育事务，推行日语教学和奴化教育，篡改历史教材，为日军殖民统治服务。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ff78a4eabebe427eb0ca4b91bc0c7ba4','c30f46efa0da478d81ccf1c8c6da043a',1942,'伪福建省政府财政厅厅长','在伪福建省政府中负责财政，为日军筹集军费，推行伪币，掠夺福建物资，配合日军经济封锁。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b4004322dc564d2eb0e92a08e179f4c5','38e2fe813a6c48ae8fb03087f2c0554a',1941,'伪宁德县保安队队长','在宁德组织伪保安队，配合日军对闽东抗日根据地进行扫荡，抓捕抗日人员，强征粮食。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3a069d0980b647e68ef47e873d7f95d3','6e5e5467e9da41e1a8da46c8a2f13202',1938,'伪厦门特别市政府市长','福建籍汉奸，厦门沦陷后投靠日军，出任伪厦门特别市政府市长，协助日军维持厦门及闽南沿海占领区统治，推行伪化政策。；厦门沦陷后出任伪厦门特别市市长，依附日军维持伪政权，推行保甲连坐、物资统制，配合日军镇压抗日活动。厦门为福建东南沿海要地，其伪政权与闽西南地区有行政与情报联系。；福建厦门沦陷后出任伪厦门特别市市长，协助日军维持厦门及闽南地区殖民统治，推行伪化教育、经济统制，镇压抗日活动。厦门为福建重要口岸，其伪政权与龙岩、长汀等闽西地区同属福建省，对全省伪化有辐射影响。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('924fcceda1e945fa822450a37b984218','4fa04cb35f9e4c95ad05f733a74b3cd4',1938,'伪厦门特别市政府市长、伪厦门维持会会长','厦门沦陷后组织伪维持会，后任伪厦门特别市政府市长，为日军在闽南的殖民统治服务，参与征粮、征工和镇压抗日活动。；厦门沦陷后组织伪维持会，后任伪厦门特别市市长，配合日军搜刮物资、征发劳工，推行日语教育，迫害抗日人士。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b4d67b44a80e4b90bb8a445cc4e0561e','777d6386fff54ff4a32b34f8c190b669',1938,'伪厦门特别市政府官员','在伪厦门政权中任职，协助日军推行伪化教育与社会控制，属于福建沿海占领区附逆人员。；在伪厦门政权中任职，参与协助日军管理闽南占领区事务，为日伪统治服务。；在日伪厦门政权中任职，参与伪政权的行政与宣传事务，属于福建沦陷区附逆人员。','无明确职位或一般帮凶','hanjian');
