INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d95c168ce25944cdb00e56406e8264c4','f415d17d03cf4be0b1b03573cdbe07f8',1938,'伪福建省政府委员、伪厦门特别市市长','福建人，抗战期间附逆，在伪福建省政府及厦门伪政权中任职，配合日军维持厦门及闽南部分地区治安与物资统制。；福建福州人，抗战期间附逆，在伪福建省及厦门市政权中任职，参与日军对福建沿海包括泉州地区的殖民统治与经济掠夺。；福建伪政权核心人物之一，参与组织伪厦门特别市政府，协助日军在闽南推行殖民统治，对漳州、厦门一带的抗日力量进行镇压。；福建沦陷区伪政权核心人物之一，参与组织伪福建省及厦门伪政权，推行日军殖民统治，其活动范围覆盖闽南地区。；福建沦陷区伪政权核心人物之一，参与组织伪厦门特别市政府，推行日军殖民统治，协助征粮、征工，镇压抗日活动。；福建人，抗战期间投靠汪伪政权，在厦门、漳州一带协助日军推行伪化统治。；抗战期间投靠日伪，在福建沿海日占区任职，协助日军推行伪化统治。','特别市市长','hanjian');
