INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2f109bbe923b4b7ca136614e329de05b','14ef3da5c15b4a5a9aeaad8a82c0f8cf',1939,'伪晋江县教育会会长','在泉州推行日语教育，篡改教科书，宣传“大东亚共荣圈”，毒化青年思想。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c039ac4ca21c422695e4c0b1da24a461','1c671602a80646d1a9d29e0c3b65ebca',1940,'伪福建和平救国军第一集团军司令','率伪军在泉州沿海地区配合日军登陆作战，袭击抗日武装，残害百姓。；率部在泉州、南安、惠安沿海配合日军作战，袭击抗日游击队，劫掠沿海村庄。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9a03b5811db941dea6bfffb5a9fde189','39d7e12cd51d4fbb84f2698489557225',1940,'伪福建和平救国军第二集团军司令','盘踞闽南沿海岛屿，与泉州伪政权勾结，进行海上劫掠和日军物资运输。；活动于闽南沿海包括泉州海域，为日军护航、封锁抗日根据地，在南安、晋江一带强征壮丁。；盘踞闽南沿海岛屿，与日军勾结，在泉州、漳州沿海进行走私、劫掠和伪化宣传。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aeb5b4f605004d369c1435d5a2159e8b','dc1400859be6498492e00f07bb3a75fe',1938,'伪厦门警察局局长','在厦门及闽南地区搜捕抗日分子，其警务系统延伸至泉州周边，协助日军维持殖民统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('70eb737a3c044a209c91e519a8fa260f','c8219901499042a4a73ce945a7453f8b',1939,'伪泉州保甲长','在泉州城内推行保甲连坐，监视居民言行，向日军密报抗日人员及物资。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('09216340fa6e4eb193669ee4c90092fc','99383940b68d493cb9d213dcde8ad9b6',1931,'伪福建自治军总司令、伪兴泉永警备司令','盘踞泉州、永春、德化一带，割据闽南，后接受国民党收编，但其势力长期控制泉州地区，横征暴敛，与日伪势力有勾连。；盘踞泉州、南安一带，接受国民党收编后仍割据地方，后与日军及伪政权暗中勾连，其部属在泉州、南安地区横征暴敛、残害民众。；盘踞泉州、永春、安溪一带，割据闽南，后接受国民党收编，但其部属在地方横征暴敛，与日伪势力有暗中勾连，1932年被十九路军处决。；早年盘踞泉州、永春、德化一带，1931年后接受国民党收编前后与日方有勾连，在泉州及洛江周边扩张武装势力，横征暴敛，后被十九路军处决。；盘踞泉州、南安、永春、德化、安溪、惠安、莆田、仙游等地，割据闽南，横征暴敛，与日本势力暗中勾连，后被十九路军以汉奸罪名处决。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('544c0c818e404f0aae29b887d9074c10','674237f419494fad8814f250378ffe4f',1931,'伪闽南建国军总司令','在泉州、惠安、仙游一带活动，组织伪军，配合日军侵扰闽南沿海，后被国民党军击毙。；在泉州、永春、德化一带聚匪割据，后投靠日伪，组织伪军，骚扰闽南抗日后方，1933年被十九路军捕杀。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('15c69089304246c68ccd2428c2617f9a','fe74690e75a2403e8521c0fbb7c5a646',1938,'伪厦门特别市政府市长','福建厦门人，抗战期间投靠日军，出任伪厦门市长，协助日军在闽南地区推行殖民统治，其活动范围覆盖泉州沿海。；福建沦陷区重要伪政权头目，主持厦门伪政，与泉州、漳州一带日伪机构联系密切。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0594848602914ffc96e2023cd4133a17','1b8a6643bb394487acd9c3f4464ea524',1938,'伪厦门特别市商会会长、伪厦门市副市长','厦门沦陷后投敌，任伪职，协助日军经济掠夺，与泉州商界有联系。','市县厅局级','hanjian');
