INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('26c19df6b2e64eb9ba4f6c6c00ce74d2','7b5527d0905b477fa05a8888253e44de',1938,'伪福建和平救国军副总司令','与张逸舟共同组织伪军，在泉州沿海地区为日军效力。；与张逸舟共同统领福建沿海伪军，协助日军控制闽江口及福清、长乐沿海地区。；福建人，与张逸舟共同组织伪军，在闽江口及沿海岛屿活动，协助日军封锁海岸，捕杀抗日人员。','基层头目','hanjian');
