INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('07dcfdd1a58d4029a84ae3ff35eb02e6','ad420b4f95e243ad8bdbe826e7df64a7',1938,'伪泉州维持会会长','日军侵占厦门后，在泉州一带组织维持会，为日军搜集情报、征派物资，协助推行伪化统治。','基层维持会/地方自治头目','hanjian');
