INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f160bee333d24030bc979eb411143fc6','b931e895d5044cc7a1a782c9dc828055',1938,'伪晋江维持会会长','在晋江（今泉州辖区）组织维持会，为日军登陆泉州沿海提供向导与补给，迫害抗日群众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6211be30a33c441abb6be467ccaa24e4','5cdda70bab5f4b54a7843f4752cb596d',1939,'伪南安维持会筹备处主任','在南安一带活动，串联地方劣绅筹建伪维持会，为日军搜集南安、安溪山区抗日武装情报。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3ca3a7bb6e4d47cf873ad0389f7e8df8','3b34868627504ce894fc790af9d9ec95',1940,'伪泉州地区保甲长、伪情报员','在泉州城郊充当伪保甲长，协助日军清查户口、抓捕抗日人员，向伪警察局密报南安籍抗日家属。','一般帮凶/基层人员','hanjian');
