INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('30a3ef8f949d457a91bb24a3fdb00986','dc1400859be6498492e00f07bb3a75fe',1939,'伪厦门特别市政府秘书、伪泉州联络员','多次往返厦门与泉州，传递日军指令，协助伪政权在泉州、南安发展下线，诱降地方实力派。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d49f16904c404bdd850a648dcca88cfc','99383940b68d493cb9d213dcde8ad9b6',1931,'闽南伪军头目、土匪武装首领','长期盘踞泉州、南安、安溪一带，为非作歹，后虽被国民党收编，但其部属在抗战初期有投敌附逆行为，对闽南地方造成严重危害。；长期盘踞闽南、闽西一带，曾与国民党地方势力及日伪方面有勾连，在龙岩、漳平、华安等地活动，对地方民众横征暴敛，后被国民党方面处决。；长期盘踞闽南、闽西一带，曾控制漳平、龙岩部分区域，勾结地方豪绅与日伪势力，扰害地方，后被国民党当局处决。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('16dbc29beb284724a212da6b3cd63f8e','ad420b4f95e243ad8bdbe826e7df64a7',1938,'伪厦门特别市政府警察局长、伪军头目','厦门沦陷后投敌，历任伪厦门治安维持会委员、伪警察局长等职，协助日军维持闽南沿海占领区秩序，镇压抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('32a03f72fb49402f97e3305a35476291','b9a1957a535f455ebc9d1e89f61d926e',1938,'伪厦门治安维持会委员、伪市政府参事','厦门沦陷后参与组织伪维持会，后任伪市政府参事，协助日军在闽南地区推行殖民统治。','基层维持会/地方自治头目','hanjian');
