INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('335e4c3800ad40d987b4d75dcdc39ce5','5cdda70bab5f4b54a7843f4752cb596d',1938,'伪惠安维持会会长','在惠安地区组织伪维持会，配合日军登陆后的地方控制，为日伪政权服务。','基层维持会/地方自治头目','hanjian');
