INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ede3d1b8dbbe428899db55fd5344721c','39d7e12cd51d4fbb84f2698489557225',1940,'伪军福建和平救国军头目','组织伪军配合日军在福建沿海活动，包括泉州、厦门一带，进行反共与镇压抗日力量。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2222b20989b14671b61bfa8441f01d20','fea5ba2d5e614ac086086bd338dbef85',1939,'伪军头目、伪闽粤边区绥靖军司令','率伪军在闽粤边区活动，配合日军进攻抗日根据地，其势力范围涉及福建南部包括泉州周边地区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('108108ee5a094145ad78b4765b6608eb','dc1400859be6498492e00f07bb3a75fe',1939,'伪厦门特别市政府教育科长','在伪厦门政权中负责教育事务，推行日语教育和奴化宣传，属文化教育领域附逆者。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('df5cceb43601407e9c19ae03a9e1f0b3','37166c097fc4463ca008d46c12a7f928',1939,'伪厦门《华南新日报》社长','主办伪报纸，为日军进行舆论宣传，鼓吹“大东亚共荣圈”，属文化宣传领域附逆者。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('39f25da831624ceebddb129ce1120862','99383940b68d493cb9d213dcde8ad9b6',1931,'闽南伪军头目、地方武装首领','长期盘踞泉州、德化、永春一带，割据地方，与日伪势力有勾连，后被国民党当局处决；其部属在闽南地区活动，对地方社会造成严重破坏。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8a1cba575f394398821a5af8d8d177db','674237f419494fad8814f250378ffe4f',1930,'闽南土匪武装头目、伪军相关势力','在泉州、德化、永春等闽南山区活动，曾与日伪及地方反动势力勾结，扰害地方，后被剿灭。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4bbe78696e4d49b6a226389b7b81daf9','4eac0b0597ba4f859ac53dfdb4091b80',1938,'伪厦门特别市政府相关官员','福建沦陷区伪政权成员，参与日伪在闽南的统治活动，其影响范围涉及泉州、厦门一带。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3072d0bf6f544366804e64a975b7b491','8d58039c924a4d26b0c0eb078242fa74',1938,'伪晋江地区维持会成员','在泉州晋江一带参与日伪维持会活动，协助日军征粮、派款、维持地方秩序，属于基层附逆人员。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('039b4b2b299f4c3594957263dc4228bf','3b34868627504ce894fc790af9d9ec95',1938,'伪泉州维持会相关人物','泉州沦陷前后，部分地方士绅被日伪拉拢参与维持会事务；黄奕住之名在部分地方史料中与泉州伪维持会有关联，但记载有限。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1b0264b5dc694772bcb7054e06348be0','1c671602a80646d1a9d29e0c3b65ebca',1940,'伪德化县维持会成员','德化地方史料中提及的维持会人员，协助日伪在德化山区进行统治与征敛，具体事迹记载较少。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4ea0730572c54ab78802d6a4d96d5561','14ef3da5c15b4a5a9aeaad8a82c0f8cf',1938,'伪泉州地方维持会成员','泉州地方志及抗战史料中提及的附逆人员，参与伪维持会活动，协助日军控制泉州城区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('94c6180128cf4e4e8a7a3adc8bfa1eb0','5b71e87d09df4952bbdd90def253abd9',1938,'伪福建省政府相关官员','在日伪福建省级政权中任职，参与协助日军统治福建沦陷区，其活动范围覆盖闽南泉州一带。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5cc82a2f50124f55a78a712da52e07d8','99383940b68d493cb9d213dcde8ad9b6',1931,'伪福建自治军总司令、伪泉州治安维持会头目','原为闽南土匪武装首领，1931年前后接受日本特务机关拉拢，在泉州、惠安一带组织伪军，配合日军侵扰闽南沿海，后被十九路军击败处决。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('67b8e3ebfa5b41c7a46ee43a37c70ec6','1b8a6643bb394487acd9c3f4464ea524',1938,'伪厦门特别市商会会长、伪维持会头目','厦门沦陷后组织伪维持会，后任伪厦门特别市商会会长，为日军筹款筹粮，配合经济掠夺，与泉州、惠安商界有联系。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d16a9db0eadc435dbcb6e75ca04342c6','b3850c3edab946ddb11a3ea25791bd08',1938,'伪泉州维持会会长','泉州沦陷前后组织伪维持会，为日军提供情报与物资，协助建立伪保甲制度，压迫当地民众。；泉州沦陷前后组织维持会，为日军筹粮、拉夫、搜集情报，协助建立伪基层政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b6f3388a1f1d4d8fa0b9883333717b8b','5cdda70bab5f4b54a7843f4752cb596d',1939,'伪惠安县维持会会长','惠安本地士绅，日军侵扰惠安时出面组织伪维持会，协助日军征粮征夫，后因民众反抗而瓦解。；惠安人，在日军登陆惠安、泉港一带时出面组织维持会，为日军带路、征发民夫，协助建立伪保甲制度。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8198d7c48b264691b909ae246eaef62a','43acc1b58a8e459b90ea829b2605e5b7',1940,'伪福建省政府顾问','原厦门名流，抗战期间滞留沦陷区，接受伪职，为日军在福建的统治提供咨询，与泉州、惠安地方势力有往来。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d4aa48f4363f46fdb7864f6fe6bff332','da5d1be35acf418ba2439eded5f7af44',1938,'伪福建省政府主席','北洋旧官僚，抗战初期投靠日军，出任伪福建省主席，在福州、厦门等地推行伪化，其政令影响泉州、惠安。；原北洋旧官僚，抗战期间投靠日军，出任伪福建省主席，统辖包括漳州在内的福建沦陷区伪政权。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ab31a214397d47a0bd8d610acb462183','f50cf011f8f842fc8d69caa402ffbf67',1938,'伪福建省政府委员兼伪厦门市长','福建汉奸，历任伪厦门市长、伪省政府委员，协助日军控制闽南沿海，包括泉州、惠安一带的伪政权运作。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9ddb9364afa246e0a9eb5cb12002a02a','9fc88af18cad40a589714d4003e388b7',1939,'伪泉州妇女会会长','泉州本地妇女界附逆者，组织伪妇女会，为日军宣传“大东亚共荣”，动员妇女参与伪后勤，活动涉及惠安。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a8c044ecd83b43b58cae3db54df03169','99383940b68d493cb9d213dcde8ad9b6',1937,'伪福建自治军总司令、伪兴亚院厦门联络部顾问','福建南安人，早年盘踞泉州、晋江一带。抗战爆发后投靠日军，在厦门、泉州沿海收编土匪武装，组织伪军配合日军登陆与扫荡，并诱降地方武装，为日军搜集晋江、泉州一带情报。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('60b795beea9447dbb2a28c1d9b7a6c23','fe74690e75a2403e8521c0fbb7c5a646',1938,'伪厦门特别市政府市长、伪厦门维持会会长','福建厦门人，日军占领厦门后出面组织维持会，后任伪厦门特别市市长，推行伪化统治，配合日军向泉州、晋江沿海渗透，征粮拉夫，镇压抗日分子。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b9d7c4a465d84bd3be372cd917d00937','fea5ba2d5e614ac086086bd338dbef85',1939,'伪和平建国军第一集团军总司令','广东人，受日军指使在闽粤沿海收编土匪、伪军，活动范围包括厦门、泉州、晋江沿海，配合日军封锁与扫荡，残害抗日军民。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aed053f2b5f74e92a3adcb8c9edb38ee','dc1400859be6498492e00f07bb3a75fe',1938,'伪晋江维持会会长','在日军侵占厦门后，于晋江沿海地区组织维持会，为日军征粮、拉夫、搜集情报，协助建立伪基层政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0e402c5d39114fffbc7fab658346c319','1c671602a80646d1a9d29e0c3b65ebca',1938,'伪泉州维持会委员','泉州地方士绅，日军侵入闽南沿海后附逆，参与组织伪维持会，协助日军推行保甲连坐，压制抗日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('34f17b0947f242a0beb9b2ddfd5faca6','0c68cd06e2b44687b321f4540d761d47',1939,'伪厦门特别市政府教育局局长','在厦门及闽南地区推行奴化教育，编写亲日教材，强迫学校使用日语，向泉州、晋江等地渗透文化汉奸政策。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('611a3f1a8f2c4850b640584032324b8b','b3850c3edab946ddb11a3ea25791bd08',1938,'伪厦门商会会长、伪厦门特别市政府参事','厦门富商，日军占领后出面组织伪商会，为日军筹款、征物资，并协助向泉州、晋江一带掠夺粮食与战略物资。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0fbf10b5b9654b9baa1de8ed0195c0a1','43acc1b58a8e459b90ea829b2605e5b7',1938,'伪厦门维持会副会长（未就任但一度被日方拉拢）','厦门名绅，日军曾企图拉拢其出任伪职，其一度犹豫后避走，但日方仍以其名义进行宣传，在闽南一带造成附逆影响。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('db147de51f5f4ce3aa5511ea2d3e5997','3b34868627504ce894fc790af9d9ec95',1938,'伪厦门特别市政府经济顾问（被迫挂名）','厦门华侨富商，日军占领厦门后强迫其挂名伪经济顾问，利用其声望向泉州、晋江侨乡诱骗资金与物资。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('10f99d77e8104a99982ce92adc15af4e','7cf9dda5771842af89114536bc3774b8',1940,'伪晋江保甲长、伪情报员','晋江本地人，充任伪保甲长，为日军搜集泉州、晋江一带抗日游击队情报，带领日伪军搜捕抗日家属，勒索乡民。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('92f863d082544efdb2d8aa765f1f5d20','5cdda70bab5f4b54a7843f4752cb596d',1941,'伪泉州警察局侦缉队队长','在泉州城区及晋江一带为日军侦缉抗日人员，破坏地下交通站，逮捕并刑讯爱国人士。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ad7afe6d63d9414384099ee1417072e3','4fa04cb35f9e4c95ad05f733a74b3cd4',1939,'伪厦门特别市政府社会局局长','负责厦门及闽南地区的社会控制，组织伪民众团体，配合日军向泉州、晋江进行宣传渗透与物资统制。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('67971a549b9045e088b390b5e8c66bd9','37166c097fc4463ca008d46c12a7f928',1937,'伪金门维持会会长','金门沦陷后组织维持会，配合日军封锁厦门、泉州、晋江沿海，为日军提供登陆与扫荡支持。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8682154ab3f0464594cb02d0fbae2e17','4eac0b0597ba4f859ac53dfdb4091b80',1940,'伪永春县维持会会长','日军侵占永春期间出面组织维持会，为日军征粮拉夫，协助推行伪化统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a40017b636ef4b5b9efd650dc1ba57c0','4590cc54f6fd456789d22665e78157aa',1940,'伪永春县保安队队长','率部投敌，配合日军扫荡永春、德化抗日根据地，捕杀抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('47b291ff1dc14cd2ba6d21c6c7ae3159','2a8aea0093294f648392cda14dfa6d65',1938,'伪泉州维持会副会长','在泉州沦陷期间出面组织伪政权，为日军筹款筹粮，协助推行日语教育。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a7c023745c6b491997f385320d04def1','0901e41960bb499aa0090bdc52f9f28b',1938,'伪晋江县维持会会长','泉州沦陷后组织伪晋江县维持会，协助日军维持治安，迫害抗日人士。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('51eb211c902444caa8faf5fdad1e22c4','3b00c293e2a64551a073677c9b33ddcd',1938,'伪厦门特别市市长','厦门沦陷后出任伪市长，其伪政权管辖范围涉及泉州沿海，配合日军经济掠夺。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('000e3bad9fbb46308288ec5749ec51ac','52494238654e461ab905286b0d05b136',1940,'伪福建和平救国军第一集团军司令','在福建沿海包括泉州、莆田一带组织伪军，配合日军登陆作战，劫掠沿海村庄。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9e5f3bee7fd54d58a02dfddbc6f2ebd6','dc1400859be6498492e00f07bb3a75fe',1940,'伪福建省政府委员','在福州伪政权中任职，参与制定对闽南地区的伪化政策，协助日军征调物资。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d9e294091ae24087ac0a653481231ae6','f50cf011f8f842fc8d69caa402ffbf67',1938,'伪福建省政府主席','汪伪政权福建省主席，推行伪化教育，配合日军清乡，其政令覆盖泉州、永春等地。；汪伪政权在福建的最高行政头目，推行奴化教育、经济统制，泉州地区伪组织受其节制。；抗战初期投敌，出任伪福建省政府主席，在日军支持下建立伪政权，影响范围覆盖泉州等福建沿海地区。；汪伪政权在福建的最高行政头目，推行日军殖民政策，统辖包括闽南在内的福建沦陷区伪政权。；汪伪政权任命为伪福建省主席，在福州、厦门等地推行伪化统治，影响闽南地区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e85a04ec35fd461280e03e04c6e2bb21','25a9cdc616bb48faaa13ce8720cdd5b5',1940,'伪福建省政府委员兼财政厅厅长','在伪福建省府负责财政，为日军搜刮闽南物资，发行伪币，扰乱泉州金融。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0d8d502583384bd7a282227c2047fd96','89a84dc33c8543618a76ac5b4bdf9a71',1941,'伪永春县警察局局长','在永春推行保甲连坐，协助日军抓捕抗日志士，镇压当地抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0894f7e1e3e84c289c2e765bbc252456','5e5dd06ff7064d07b2ff7321ce724e0f',1940,'伪德化县维持会会长','在德化组织维持会，为日军带路扫荡永春、德化山区抗日游击队。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('378aa00833f74b7b84ca7d7c86b22f1f','99383940b68d493cb9d213dcde8ad9b6',1931,'伪福建自治军总司令、伪兴化军军长','福建南安人，长期盘踞泉州、莆田一带，1930年代初期接受国民党收编后仍割据地方，后与日军及伪政权暗中联络，其部属在泉州沿海地区配合日军行动，1937年被捕处决。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('78ad1cefc9ad4323aa577009e8a389ba','ad420b4f95e243ad8bdbe826e7df64a7',1938,'伪福建和平救国军第一集团军总司令','福建泉州人，抗战期间投靠日军，在闽南沿海组织伪军，配合日军在泉州、惠安、泉港一带登陆与扫荡，残害抗日军民。；福建沿海伪军头目之一，活动于闽南沿海及泉州附近海域，配合日军封锁与登陆行动，收编海盗与散兵游勇。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('79141a79b61b42e391895378a9efefa3','1a19e1d5020f42aba38040ab9c3074b4',1938,'伪福建和平救国军第二集团军总司令','福建泉州人，与高义同为闽南伪军头目，在泉州、晋江、惠安沿海地区为日军搜集情报、征粮拉夫，镇压抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e1928adfac0b4beba2febda52cc689e6','4fa04cb35f9e4c95ad05f733a74b3cd4',1939,'伪厦门特别市市长、伪福建省政府委员','福建厦门人，投靠日军，在伪厦门政权中担任要职，协助日军控制闽南沿海贸易与物资，其势力范围涉及泉州、泉港一带的走私与情报网络。；长期在厦门伪政权任职，协助日军维持闽南沿海占领区秩序，参与经济掠夺与物资统制。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4d4569ecc81f4a3fbd9d671cadaa0953','529eba01fd3844d2a4780badaf25cb50',1938,'伪泉州维持会会长','泉州本地士绅，日军侵占厦门后，在泉州地区组织维持会，为日军筹粮筹款、拉拢地方势力，协助建立伪基层政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('762369ee8b9e443c9f616ef12eaa48f7','cb01e279c1de4e52b9a7a377b59aa427',1940,'伪泉港区（肖厝）维持会会长','泉港本地人，日军在肖厝、峰尾一带活动时组织维持会，为日军提供渔船、情报与物资，协助控制沿海港口。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4c76102774d54412885ccd3954359fde','0b45078da29b4465a640054f5efbdede',1939,'伪福建和平救国军第三路司令','福建晋江人，在泉州、石狮、泉港沿海为日军收编海盗与地方武装，组织伪军配合日军扫荡抗日根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5d9a6feb64524f1ba6b46bc2bab6de72','39d7e12cd51d4fbb84f2698489557225',1938,'伪福建和平救国军第一路司令','福建惠安人，投靠日军后率部在惠安、泉港、莆田沿海活动，为日军护航、走私，并镇压当地抗日游击队。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2efe687349b1406b882ce9ae7808d16d','9f8164403b534a5198d96b77e6dc9db2',1940,'伪晋江县县长','晋江人，在伪晋江县政府任职期间，为日军征粮征税，配合日军对泉州沿海的封锁与清乡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('88956710faf24498b80b1f49fe2b8b8e','3b34868627504ce894fc790af9d9ec95',1939,'伪厦门商会会长、伪福建经济协会理事','福建南安人，抗战期间在厦门附逆，协助日军控制闽南物资流通，其商业网络覆盖泉州、泉港，为日军采购战略物资。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('43e72722103f4e8f83683e826e09dca0','b3850c3edab946ddb11a3ea25791bd08',1940,'伪泉州教育会会长','泉州人，在伪政权下推行日语教育与奴化宣传，协助日军在泉州、泉港等地学校实施殖民教育。','基层头目','hanjian');
