INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6b94aa31020b40aab8c93a4484ce75ee','08da70affb9e4a75b621002cc09780a3',1937,'伪金门维持会会长','金门沦陷后出面组织维持会，为日军征调民夫、粮食，协助建立伪基层保甲，压制金门民众抗日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4905a203181044d39728eb0c1f79003c','87f2b93342294bd5beacce00ec6a5336',1939,'伪金门县知事','日军占领金门期间出任伪县知事，推行日语教育、物资配给和良民证制度，配合日军清乡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5c652cecc2ab4d599ef008faf7c58dd1','52494238654e461ab905286b0d05b136',1938,'伪泉州维持会副会长','泉州地方士绅附逆，协助日军在泉州城区及晋江沿海设立伪维持会，为日军筹集军需、招募伪警察。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d3f2cfa1d80041139f81484697519431','3b34868627504ce894fc790af9d9ec95',1939,'伪福建商会联合会理事','在日军控制下出面组织伪商会，强制泉州、厦门等地商户向日军缴纳“献金”和物资，协助经济掠夺。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ce182926789049248db031c8ae5d5a40','b3850c3edab946ddb11a3ea25791bd08',1940,'伪晋江县长','晋江沦陷区伪县长，配合日军在泉州平原推行“治安强化运动”，捕杀抗日游击队员及其家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e0fa539969504af6b18c136794f1e658','c30f46efa0da478d81ccf1c8c6da043a',1938,'伪惠安维持会会长','惠安沿海附逆头目，组织伪自卫团协助日军封锁海岸，阻止抗日物资进入泉州内陆。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('936a53e68a314df596f259f871ee88e5','6122b97b98ad4e0f8b921061cc44366a',1939,'伪厦门警察局督察长','在厦门及泉州沿海地区统领伪警察，参与搜捕抗日分子，为日军提供情报，镇压民众反抗。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b9421d9e30a74b249c3068138e384dfa','4fa04cb35f9e4c95ad05f733a74b3cd4',1940,'伪福建省政府教育厅督学','在泉州、厦门等地推行奴化教育，强制学校使用日语教材，篡改历史，为日军侵略辩护。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c9009cf09b924ea096017c516441cd64','3b34868627504ce894fc790af9d9ec95',1938,'伪厦门特别市商会会长（与泉州籍商人网络关联）','厦门沦陷后附逆，出任伪厦门特别市商会会长，协助日军控制闽南经济与物资调配，其商业网络覆盖泉州、晋江一带。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('19440c6f40c844ab97acdc029a94d268','b9a1957a535f455ebc9d1e89f61d926e',1938,'伪福建省政府委员、伪厦门市市长','福建沦陷区重要附逆者，在伪福建省政权中任职，参与日军对福建沿海包括泉州地区的行政控制与物资掠夺。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0769591be2dd440d83739178a626b9d1','c6a682cb9d834e4a910285cc9abb8db2',1938,'伪泉州地区维持会骨干','在泉州及晋江一带组织伪维持会，协助日军征发民夫、粮食，并参与保甲连坐制度的推行。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('00c7f1e82f854c948272a185e50f8d5c','c30f46efa0da478d81ccf1c8c6da043a',1938,'伪晋江县维持会会长','晋江沦陷区附逆，出任伪维持会会长，为日军搜集情报、征粮派款，压迫当地民众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5230bef503d54886beada5f312d4fdad','260af50e16cb47f19341bcffade264ee',1939,'伪厦门市政府教育科科长（泉州籍）','泉州籍附逆知识分子，在伪厦门政权中负责教育，推行奴化教育，影响闽南包括泉州地区的文教界。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a5af19c0d0d84a87ab93ee3c5a649a70','b3850c3edab946ddb11a3ea25791bd08',1938,'伪泉州警察局局长','在日军控制下的泉州地区出任伪警察局长，参与抓捕抗日人士、维持伪治安，协助日军镇压民众反抗。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ca3c0eb99c9d44d5ba1a4e6585b2e67c','fea5ba2d5e614ac086086bd338dbef85',1938,'伪闽南自治军总司令','抗战初期在闽南沿海收编土匪、散兵，组织伪军配合日军登陆作战，曾率部进犯漳州沿海地区，后因内部矛盾被日军处决。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b602b4c7060642cbbb715fbeb00ed5a4','4fa04cb35f9e4c95ad05f733a74b3cd4',1938,'伪厦门维持会会长、伪厦门特别市商会会长','厦门沦陷后出面组织维持会，为日军筹粮筹款，拉拢闽南商界附逆，其活动范围涵盖漳州商界。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('38025b2e01dd4c2d8b885206462612c1','b3850c3edab946ddb11a3ea25791bd08',1938,'伪漳州维持会会长','日军侵占厦门后，在漳州地区组织维持会，为日军提供情报、粮秣，协助维持沦陷区秩序。；漳州地区沦陷期间组织伪维持会，协助日军征粮、拉夫，维持地方伪秩序，活动直接覆盖漳州及云霄周边。；日军侵占厦门后，在漳州地区组织维持会，为日军筹粮筹款、拉夫，协助建立伪基层政权。；漳州本地士绅，日军侵占厦门后一度试图在漳州组织维持会，为日军提供粮秣、向导，后因漳州未长期沦陷而活动受限，但仍与漳浦沿海伪组织有联系。；漳州本地士绅，日军空袭与登陆威胁期间出面组织维持会，为日军提供物资与情报，后因民众抵制而销声匿迹。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('eabc74c7cfbf466f96b1ecdde36068b2','529eba01fd3844d2a4780badaf25cb50',1940,'伪闽南警备司令','收编闽南土匪组成伪军，驻防漳州、泉州沿海，配合日军扫荡抗日游击队，残害百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c44916cf94034c228c0c8b78795ca76e','99383940b68d493cb9d213dcde8ad9b6',1931,'伪闽南护法军司令（后投日）','原为闽南地方军阀，九一八事变后与日本特务机关接触，企图借助日军势力割据闽南，后在漳州一带被十九路军击溃。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dd76822acb4c4ff1994d32090bf60e1f','19d9bde812ad45e390409695b1b15dfe',1939,'伪漳州警察局局长','在漳州沦陷区担任伪警察头目，搜捕抗日人士，推行保甲连坐，配合日军维持治安。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7139213f1f66403584d35479daea6b32','c12c6938e1a442ef83b3e9ab80925a98',1940,'伪福建省政府教育厅厅长','在伪福建政权中推行奴化教育，在漳州等地强制使用日语教材，篡改历史，毒害青少年。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('49e85cd04f8240a0b90e261e88a8bb4d','3b34868627504ce894fc790af9d9ec95',1938,'伪厦门特别市经济顾问（附逆商人）','闽南知名商人，厦门沦陷后与日军合作，为日军采购战略物资，其商业网络覆盖漳州地区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a74fa071ea0d41af92f62e76b88c490c','dc1400859be6498492e00f07bb3a75fe',1938,'伪厦门特别市市长','厦门沦陷后出任伪市长，协助日军维持闽南沿海占领区秩序，其伪政权势力范围涉及漳州沿海及东山附近海域的物资统制和情报搜集。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c8ce52a614bc4afebdbf2052e542e346','4fa04cb35f9e4c95ad05f733a74b3cd4',1938,'伪厦门特别市维持会会长、伪市长','厦门沦陷后组织伪维持会，后任伪市长，配合日军对闽南沿海包括漳州、东山一带实施经济封锁和物资掠夺。；厦门沦陷后组织维持会，后任伪市长，配合日军在闽南地区推行殖民统治，与漳州、云霄伪政权有联系。；厦门沦陷后组织伪维持会，后任伪市长，配合日军在闽南地区实施经济封锁与物资掠夺，对漳州、诏安等地的抗日活动进行镇压。；厦门沦陷初期组织伪维持会，后任伪厦门特别市市长，为日军筹粮筹款、招募伪警，协助日军控制厦门及周边沿海地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b1f6c6e3b27f4ec299f53f458cfd5783','b3850c3edab946ddb11a3ea25791bd08',1938,'伪厦门商会会长、伪维持会委员','在厦门沦陷期间为日军筹款筹粮，协助日伪对闽南沿海地区进行经济控制和物资征调，其活动影响波及漳州沿海。；厦门商界人物，抗战期间附逆，协助日军控制闽南物资流通。；厦门沦陷后投敌，协助日军统制闽南物资，为伪政权筹款筹粮，其商业网络覆盖漳州、诏安等地，间接支持日军对闽南的侵略。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b2dead0d798b4fe88f91814eaea3c7dd','b931e895d5044cc7a1a782c9dc828055',1938,'伪福建省政府委员、伪厦门市长','抗战期间投敌，在福建日占区任职，参与伪政权对闽南沿海地区的统治和资源掠夺。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7cbc7da98faf46ea91b10ae832a56f28','da5d1be35acf418ba2439eded5f7af44',1939,'伪广东汕头市市长（活动涉及闽粤沿海）','汕头沦陷后任伪市长，其伪政权与闽南伪政权勾结，在闽粤沿海包括漳州、东山附近海域进行走私和情报活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f86b4a5efac7404fa10417e46915d904','a9708e8b7e6a4a6aacef69da8f32bb5e',1939,'伪汕头维持会会长','在汕头沦陷区组织伪维持会，配合日军对闽粤沿海实施封锁，其活动范围与漳州、东山沿海地区有交叉。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7110d4c8f7ea4b4cb31edcf2b5cc86bc','a1442e252a78480888f49fee68c84d90',1938,'伪闽南自治军司令','在闽南沿海一带收编土匪武装，组织伪军配合日军进攻漳州、东山等沿海地区，进行烧杀抢掠。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cfdf1b9f1f304203a3b5254315cd2fe3','c30f46efa0da478d81ccf1c8c6da043a',1939,'伪东山维持会会长（待考）','据地方史料零星记载，东山沦陷期间曾有维持会组织，吴友三可能为负责人之一，协助日军征调民夫、物资，但具体事迹记载较少。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cb265aa9ac7b44178a0333a1a6aadfff','dc1400859be6498492e00f07bb3a75fe',1938,'伪厦门特别市政府市长','厦门沦陷后出任伪市长，协助日军维持闽南沿海占领区统治，其伪政权影响波及漳州、云霄等地的伪组织建立。；福建厦门人，日军占领厦门后出任伪市长，推行奴化教育、经济统制，配合日军对闽南沿海包括漳州、漳浦一带进行物资掠夺与情报搜集。；厦门沦陷后出任伪市长，隶属伪南京政府，协助日军在闽南沿海推行伪化统治，其伪政权势力范围涉及漳州沿海及诏安一带的走私与物资统制。','市县厅局级','hanjian');
