INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6c9466171e3a487eb582822a3cc6edcd','a2e4190c87b449e685d78c118a6801b5',1940,'伪南京国民政府财政部长、警政部长','通过伪政权渠道向贵州渗透，策划经济封锁与情报搜集，与贵阳部分商界附逆者保持联系。','省部级/大军区级要员','hanjian');
