INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('72ba4e200c484709a836e7e31721b283','845de899b20e4631bbf68676aa47dec8',1940,'伪南京国民政府侨务委员会委员长','利用贵州籍华侨关系，在贵阳设立伪侨务联络点，策动侨眷附逆。','机构委员长(非国家首脑)','hanjian');
