INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3e7fefd6f2394579b008bb08f3cac02e','3c00b8b8a0a24ed1b304394220d0f56e',1940,'伪遵义县维持会会长','在遵义沦陷期间组织维持会，协助日军征粮、派款、维持地方秩序，为日军侵略服务。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('64e454f99dba4baf853b5e02f0bb9e68','e6f034eddae747bba7a6871e09370907',1940,'伪遵义县警察局局长','担任伪警察局长期间，配合日军搜捕抗日人士，镇压民众反抗，维护日伪统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('13cf127d16d4443caa6b2d8bfb5694c1','bea014924c804c948286eb8392497a9d',1940,'伪习水县保甲长','在习水地区担任伪保甲长，为日军征派粮草、劳工，协助日伪维持基层统治。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2aa1887e86be45649281c55fb0eb3cdc','9ee0a5c3575d4c06bc1741160efe7831',1939,'伪贵州省政府委员','在伪贵州省政府任职期间，推行日伪政策，协助日军在贵州地区的经济掠夺和思想控制。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2d0ae8a71cb446a2b126b5c26bcb00d3','38e2fe813a6c48ae8fb03087f2c0554a',1940,'伪遵义县教育科科长','在遵义地区推行奴化教育，篡改教材，宣传“大东亚共荣圈”，毒害青少年思想。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c95cf0ada80d4ceab13e906b76b6ca63','ba65155a21854531858e8753caca9d19',1940,'伪遵义县商会会长','组织商会为日军筹集物资，协助日军对遵义地区进行经济掠夺，压榨当地商户和百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f0fb16703ca5480fb3826a3e24f86b13','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满第一军管区司令、伪满治安部大臣','原东北军旅长，1932年投敌，任伪满第一军管区司令，在辽宁东部（含丹东地区）围剿抗日义勇军，后升任伪满治安部大臣。；原东北军将领，1932年投敌，任伪满第一军管区司令，管辖辽宁东部地区，多次派兵“讨伐”本溪、南芬一带的抗日义勇军和抗联部队。；原东北军将领，投敌后任伪满第一军管区司令，管辖辽宁中南部，多次在盘山、台安一带清剿抗日义勇军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('56a4faa1be7346ffa0de528f2e5bc5e3','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满安东省省长','原安东地区地方势力，投日后任伪满安东省省长，管辖今丹东一带，协助日军推行殖民统治，镇压抗日活动。；曾任伪满安东省（今丹东地区）省长，积极推行日伪政策，强征劳工，协助日军清剿抗日游击队。；伪满安东省（今丹东地区）最高行政长官，推行日伪“治安肃正”，在宽甸等地设立警察机构，迫害抗日军民。；原奉系军官，投日后任伪满安东省（辖今丹东、振安地区）省长，推行日伪殖民政策，强征劳工，镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('435aaec4db2f4f4b973f4831ad0425b5','21853206ad2b417598d1af0b4b3a4782',1932,'伪满安东省警务厅长','在丹东地区任伪警务厅长，组织警察特务搜捕抗日志士，破坏地下抗日组织，参与“讨伐”抗日联军。；负责安东省（含宽甸）警察特务系统，指挥抓捕抗日地下人员，参与制造多起屠杀事件。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('10eb78016c4245f7b8f9281e38068564','0639407f8320412e86eada632a47d380',1937,'伪满安东市市长','任伪安东市（今丹东）市长，推行日伪经济统制，强征劳工，协助日军建立治安维持会，镇压市民反抗。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bd7537a101d248c682643c218f835025','a979dd19db7944cd9480e25931212232',1932,'伪满安东地区警备司令','原东北军军官，投日后任安东地区警备司令，率伪军多次“扫荡”宽甸、凤城等抗日游击区，杀害抗日军民。；原东北军营长，投敌后负责安东（丹东）及宽甸、凤城等地“讨伐”抗联，制造多起惨案。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9ead228a79de4b7a826143b9b30bd444','3951963964a94498a774c966bfe9bc97',1935,'伪满安东省协和会会长','任伪安东省协和会会长，宣传“日满亲善”，组织汉奸团体，配合日军进行思想奴化，收集抗日情报。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('55e40500e7ab4928909d38bf01fa9040','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满安东省高等法院院长','在丹东地区任伪高等法院院长，以法律名义迫害抗日人士，判处大量爱国者死刑或重刑，为日伪统治服务。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3bcc0cadc96a4e96aa9ea53f3e591ff1','589ab27feed347c6944e6c001125dc02',1933,'伪满安东省实业厅长','在丹东地区任伪实业厅长，协助日本掠夺安奉铁路沿线资源，强占农民土地，为日军提供物资支持。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c3c55dd16f5c431480aae25eb4436ea3','77a789268c6f47b4a617cdb9e41180bd',1935,'伪满国务总理大臣（曾涉安东地区）','虽为伪满中央高官，但多次到安东（丹东）视察，推动“治安肃正”，支持当地伪军警镇压抗日武装。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a3958189e8494db6ad8130ef48f171a8','21853206ad2b417598d1af0b4b3a4782',1932,'伪满安东省警务厅厅长','在安东（丹东）地区任伪警务厅长，抓捕抗日志士，破坏地下抗日组织，参与制造多起屠杀事件。；在丹东（安东）地区组织伪警察，协助日军清乡，抓捕抗日志士，实施“治安肃正”。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d593f5ead6904a89988861a27df1811a','0639407f8320412e86eada632a47d380',1932,'伪满东边道保安司令','活动于东港、凤城一带，率伪军配合日军围剿抗日义勇军，烧毁村庄，残害百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('57d12d32b4a94add8d2b4bbcfc17e5d4','a979dd19db7944cd9480e25931212232',1933,'伪满安东地区警备军司令','驻守安东（丹东）及东港地区，多次率伪军进攻抗日根据地，杀害抗联战士及群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('238570f353dc4b2989cd8656a2c7a8ed','811fe999084946d8baee44410886b3e6',1935,'伪满安东省协和会会长','在安东地区推行奴化教育，组织协和会宣传“日满亲善”，协助日军搜集情报。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2480cccb725f4bb5b2cec373ad6e9685','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满立法院院长（曾任职于辽宁）','原奉系人物，投日后在沈阳及安东等地活动，参与伪满立法，为殖民统治提供法律依据。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bdb7b9129e104ccc84914d2bead90e1c','1a8847af165d4d648f62d949fad6cb5a',1937,'伪满安东省实业厅厅长','在东港地区强占土地，掠夺矿产和农产品，为日军提供战争物资。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('62aa5f09c8c74bd4a3a22f47201b4e41','589ab27feed347c6944e6c001125dc02',1938,'伪满安东市市长','在丹东市区推行保甲制度，强制居民领取“良民证”，协助日军镇压抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cffe8361c1cf4fd5b5e7c1ca54575068','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满热河省省长兼第五军管区司令','原东北军将领，九一八后投敌，曾任伪满热河省省长，镇压抗日武装，参与对辽宁地区的殖民统治。；原东北军将领，九一八后投敌，任伪满要职，镇压抗日武装，协助日军统治热河及辽西地区。；原东北军将领，九一八后投敌，曾任伪满本溪湖地区治安头目，镇压抗日武装，协助日军掠夺本溪煤铁资源。；原东北军将领，九一八后投敌，曾任伪满热河省省长，参与镇压抗日武装，本溪平山地区为其势力渗透范围。；原东北军将领，1933年投敌，任伪热河省省长，参与镇压抗日武装，在南票、朝阳一带推行日伪统治，协助日军掠夺煤炭资源。；原东北军将领，九一八后投敌，任伪满要职，参与镇压辽西抗日义勇军，在连山一带协助日军清剿抗日武装。；原东北军将领，九一八后投敌，在铁岭一带协助日军镇压抗日武装，后任伪满热河省省长，参与围剿抗联部队。；原东北军将领，九一八后投敌，在锦州、凌海一带协助日军镇压抗日武装，推行殖民统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dc864c9d62954a8a879c023e62a39f9d','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满第一军管区司令（驻辽宁）','原东北军旅长，投日后任伪满第一军管区司令，负责辽宁地区“讨伐”抗日义勇军和抗联。','基层头目','hanjian');
