INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('17576d13830848448a5969b2ba3fcedd','21853206ad2b417598d1af0b4b3a4782',1935,'伪满安东省协和会事务长','在丹东地区从事汉奸宣传和组织工作，为日军收集情报，破坏抗日地下组织。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c16aeda0efdb425fa0610a79b7b5dd1b','0639407f8320412e86eada632a47d380',1937,'伪满安东县（今丹东市东港一带）县长','任伪县长期间，强征劳工，推行“粮谷出荷”，协助日军清乡，迫害抗日家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d23f455615524101b70730cf8da4cad8','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满立法院院长（原籍辽宁）','原奉系法律人士，投日后任伪满要职，参与制定殖民法律，为伪满统治提供法理支持。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6dfacca7b251400da48598d50511dd82','1a8847af165d4d648f62d949fad6cb5a',1938,'伪满安东省民生厅长','在丹东地区推行“勤劳奉仕”和奴化教育，协助日军掠夺粮食资源。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e877963d099c468f8325440b459068c6','77a789268c6f47b4a617cdb9e41180bd',1931,'伪满国务总理大臣（原籍辽宁台安）','原奉系军阀，九一八后投敌，任伪满最高行政长官，全面配合日本殖民统治，对辽宁地区抗日活动进行镇压。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9a6402d9d4b24800bfa53355984e0ef5','79b17193512846a1a5bde9f5df22c926',1931,'伪满奉天省省长（原籍辽宁）','原奉天省主席，投日后任伪奉天省长，在沈阳及辽宁各地推行“治安肃正”，残害抗日军民。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('434d4d05794242029dc97d102a7babfe','5cce8fcbbcc043c2820499553d6999c1',1939,'伪满安东省警务厅特务科长','在丹东元宝区一带指挥特务活动，破坏抗日地下联络站，逮捕并刑讯抗日人士。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3c6074e059a8480b983d22d07c9aa05c','6eced3195da9422aacea35137312dcb9',1940,'伪满安东市（今丹东市）市长','任伪安东市长期间，推行日伪“市街建设”，强拆民房，为日军提供军事物资，镇压工人罢工。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e1de3700110e4a0b86919bb7d4f7b41f','589ab27feed347c6944e6c001125dc02',1936,'伪满安东省教育厅长','在丹东地区推行奴化教育，强制学校教授日语，删除中国历史内容，迫害爱国教师。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('79c7a64d8fa54e9eb443b4e5a3a3f181','79b17193512846a1a5bde9f5df22c926',1931,'伪满奉天省省长、伪满民政部大臣','原东北军将领，曾任辽宁省政府主席，九一八事变后被日军俘虏，随即投敌，任伪满奉天省省长，后任伪满民政部大臣，协助日军统治辽宁。；九一八后叛国投敌，任伪奉天省省长，后升任伪满民政部大臣，为日本殖民统治效力。；长期担任伪奉天省省长，配合日本殖民统治，强征劳工，镇压抚顺地区抗日力量。；长期担任伪奉天省省长，配合日本殖民政策，镇压东北抗日义勇军。；长期担任伪奉天省省长，配合日本殖民政策，强征劳工，镇压抚顺地区抗日力量。；长期担任伪奉天省省长，配合日军“治安肃正”，残酷镇压东北抗日联军。；原东北军将领，被俘后投降，任伪奉天省省长，推行日伪政策，镇压抗日活动。；九一八事变后投降，任伪奉天省省长，协助日军维持治安，镇压反满抗日活动。；原辽宁省主席，被日军扣押后变节，出任伪奉天省省长，后任伪民政部大臣，推行奴化政策。；原辽宁省政府主席，投敌后任伪满奉天省省长，在鞍山铁西地区推行日伪经济统制政策。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6e835a96ae744d8fb5f8fcac01b2ad0a','875c22d678e24c21834a32caae69933c',1931,'伪满财政部大臣、伪满宫内府大臣','原吉林省政府委员，九一八后投日，参与建立伪满洲国，虽主要活动于吉林，但曾参与辽宁地区日伪政权建设，任伪满财政部大臣。；参与策划伪满建国，曾任吉林地区伪职，后调任中央，积极效忠日本。','无明确职位或一般帮凶','hanjian');
