INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4f6e3f9537ad40f5aa35894b440f6c66','caae33d173854bf0a1b2b4f0db4f585a',1932,'伪满洲国黑龙江省省长','原黑龙江省政府委员，投日后任伪黑龙江省长，协助日军清剿抗日武装。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0fde889547d44f2bbd177e9b12ca4d86','5cce8fcbbcc043c2820499553d6999c1',1933,'伪满洲国热河省省长','原热河地方官员，日军侵占热河后投敌，任伪省长，推行奴化统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4d94d8003ee943d2a7ebe756b7551e31','589ab27feed347c6944e6c001125dc02',1931,'伪满洲国奉天省省长（未就任）','原奉天省长，虽未正式就任伪职，但参与劝降和维持会活动，被视为变节者。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8f186b808d10483b930fdf5a1f6108d9','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洲国侍从武官长、热河省警备司令','原洮辽镇守使，公开投日，率部配合日军进攻热河，镇压义勇军。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fe01f23a1c494135b6f39e70b7898a22','c0860f9060d74dfba1674157f4596712',1931,'伪满洲国吉林警备司令','原吉林陆军军官，投日后任伪吉林警备司令，多次率伪军进攻抗日游击队。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cfe31e67f2864c65a223b870e0d6296f','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满洲国奉天警备司令','原奉军旅长，投日后任伪奉天警备司令，参与镇压沈阳周边抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ff4bb6765f8b4e258162bfff2793dd16','21853206ad2b417598d1af0b4b3a4782',1931,'伪满洲国大连地区警察署长','大连本地汉奸，任伪警察署长，协助日本关东州当局抓捕抗日志士，迫害劳工。；在大连地区为日军特务机关效力，破坏抗日组织，迫害码头工人和进步人士。；在大连地区为日军效力，搜捕抗日分子，协助日本殖民统治。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9710217970a54e848e5f3f151817c0ab','a2e63f8d6660475b9a55fa85c52afeeb',1931,'伪满洲国大连民政署长','大连地区汉奸，任伪民政署长，推行保甲制度，强征劳工，为日军提供物资。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e9164078cc544dae8f23164f33a0e984','673bb1093a734acebd0f7ae34d7651fb',1931,'伪大连商会会长','大连巨商，投靠日本，任伪商会会长，为日军筹集军费，垄断港口贸易。；在大连地区为日军提供物资和资金，协助日本控制港口和航运，迫害抗日人士。；辽宁大连人，曾任伪大连商会会长，为日军提供物资和情报，协助日本控制大连经济。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ab40446cdd3b4f3f8925f8cbb61e0561','6656ff7e892d429fa8dbfea97e6be0b2',1933,'伪满洲国大连宪兵队翻译官','大连汉奸，任宪兵队翻译，参与审讯和迫害抗日地下工作者，罪行累累。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('01091dd8086948cab30764b1daa276b6','9d25e1d3d8e543ee84de82f230352248',1932,'伪大连市公署参事','大连地方士绅，投日后任伪市公署参事，协助日伪推行“治安强化”运动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('17c1d95ff3004ca998a4baaadef79df7','12df332ea8ab40bfb7302fcc24b60d11',1934,'伪满洲国大连港务局副局长','大连港务汉奸，管理港口运输，为日军输送兵员和掠夺物资，参与奴役码头工人。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('60af1ef4e7ba4f17a7eb27b69981f0a5','79b17193512846a1a5bde9f5df22c926',1931,'伪满洲国奉天省省长','曾任伪奉天省省长，在辽宁地区协助日军镇压抗日力量，推行奴化教育。；九一八事变后被日军俘获，变节投敌，任伪奉天省省长，镇压抗日活动，为日军征粮派夫。；九一八事变后投降日军，任伪奉天省长，镇压抗日活动，为日军提供粮饷。；辽宁沈阳人，九一八事变后被日军俘获并投降，出任伪奉天省省长，协助日军维持殖民统治，推行“治安肃正”等政策。；辽宁沈阳人，九一八事变后投降日本，任伪奉天省省长，管辖包括康平在内的辽宁地区，镇压抗日活动，为日军征粮派夫。；原辽宁省政府主席，沈阳沦陷后变节投日，出任伪奉天省长，推行日伪奴化政策。；原辽宁省主席，被日军俘获后变节，出任伪奉天省省长，推行日伪政策，强征物资与劳工。；原辽宁省政府主席，投日后任伪奉天省长，协助日本控制辽宁地区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e5fed29ed0de4d6a9c7fb40022166258','87b0aba74b9b4c5f8a515bd9270d23b4',1931,'伪满洲国参议府议长','曾任伪参议府议长，在辽宁地区协助日本殖民统治，参与镇压抗日活动。；曾任奉天省咨议局副议长，投日后任伪参议府议长，参与伪满建国及对日合作。；曾任奉天省议长，后任伪满参议，鼓吹“日满亲善”，为日本侵略张目。；辽宁辽阳人（沈阳地区活动），曾任伪满参议府议长，积极鼓吹“日满亲善”，协助日本控制东北。；清末民初政客，投靠日本后任伪满参议府议长，为伪政权出谋划策。；原奉天省议会议长，积极投靠日本，参与伪满政权建设，在沈阳地区活动。；作为伪满高级顾问，曾多次到盘锦、双台子地区视察，指导地方伪政权强化殖民统治，镇压抗日运动；清末举人，投日后任伪满参议府议长，虽居高位，但曾参与策划对辽宁各地（包括盘锦、大洼）的“治安肃正”行动，支持日军清乡。；原奉天省议员，九一八后参与组织伪政权，在辽南地区有影响力，协助日军建立地方伪政权。；原奉天省议会议长，投日后任伪满参议府议长，参与伪满政治决策。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d731e39ab3dd4321876197e8e1c6c114','589ab27feed347c6944e6c001125dc02',1932,'伪满洲国奉天省财政厅长','在辽宁地区为伪满洲国征收苛捐杂税，搜刮民财，支持日军战争资源。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('724da89dc38740059d65a0190997103c','5cce8fcbbcc043c2820499553d6999c1',1939,'伪大连市市长','曾任伪大连市市长，在大连地区推行日本殖民政策，镇压抗日民众。；辽宁大连人，曾任伪大连市市长，配合日本殖民当局实施奴化教育，镇压大连地区抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fbd2c6de75444057ae26fcba51d14dce','a2e63f8d6660475b9a55fa85c52afeeb',1932,'伪大连警察署署长','在大连地区指挥伪警察抓捕抗日志士，协助日军进行特务活动。；效忠日本关东军，指挥伪警察搜捕抗日地下组织，多次参与屠杀和镇压大连沙河口地区工人罢工与抗日群众。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4dab0083e24745dd856946e14241f805','6656ff7e892d429fa8dbfea97e6be0b2',1940,'伪中山区区长','在大连中山区推行保甲制度，协助日军清查抗日分子，强征劳工。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7aebca265fa441a3bdadd99115c5e4fe','0d0bffb8fd9f440595851f71ab48a4fe',1938,'伪中山区警察署署长','在中山区指挥伪警镇压学生运动和工人罢工，多次参与逮捕抗日地下党员。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('babcc013038c4109a0a2d1892ad1f25d','1d67ff455ffc47b8addcc485beb0ca34',1932,'伪满洲国第一军管区司令','在辽宁地区指挥伪军配合日军围剿抗日联军，屠杀抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('80514e0592f84cb2961d9e3fb73b9c89','c9dffc071fec4ce58fe1d611f26c28da',1931,'伪满洲国奉天省警务厅长','在辽宁地区组织伪警察特务，破坏抗日地下组织，实施白色恐怖。；辽宁海城人，投日后主管伪奉天省警务，残酷镇压沈阳、大连等地抗日运动。；原奉天警察头目，投日后负责沈阳地区治安，残酷镇压反满抗日活动，抓捕爱国志士。；原东北军军官，投敌后负责辽宁地区伪警察体系，在兴城、绥中等地建立伪警察所，协助日军抓捕抗日志士，强征劳工。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f395447a2f3e4b379f4a1873adbd20bd','21853206ad2b417598d1af0b4b3a4782',1937,'伪大连港务局局长','在大连港为日军管理运输，协助运送军需物资，并参与抓捕码头抗日工人。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('18cb547799b4423ba895d66688a38b8d','797c553510f3440f88255e16480f23b4',1941,'伪中山区公署参事','在中山区协助日军推行粮食统制，强征居民粮食，导致民众饥荒。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cf4d32bb7eab4903845eec9798afc397','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满洲国奉天省省长、伪治安部大臣','原东北军将领，九一八事变后投敌，任伪奉天省省长，积极推行日伪殖民统治，镇压抗日力量。；原东北军旅长，叛国投敌后任伪奉天省省长，在辽宁地区推行殖民统治，协助日军清乡、抓捕抗日人员。；原东北军将领，九一八事变后投敌，任伪奉天省省长，协助日军镇压抗日武装，推行殖民统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bf83a0254c5b494cb02bb4850d8a53e5','87b0aba74b9b4c5f8a515bd9270d23b4',1931,'伪满洲国尚书府大臣、奉天地方维持会会长','清末举人，九一八事变后积极参与组织伪奉天地方维持会，为日军占领辽宁提供行政支持。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bd015c1f10f04802aad55fbe0ad2e2b5','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满洲国立法院院长、奉天市市长','原律师，投日后任伪奉天市长，协助日本建立殖民秩序，后升任伪满立法院院长。；辽宁沈阳人，曾任张学良法律顾问，后投靠日本，任伪奉天市市长、伪立法院院长，协助日本在辽宁及大连推行殖民法律。；曾任张学良法律顾问，后投敌，任伪奉天市市长、伪满立法院院长，参与制定伪满法律。；曾任伪奉天市市长，后升任伪立法院院长，在辽宁地区推行奴化教育和经济掠夺政策，其活动范围覆盖盘锦地区。；原东北政客，投日后任伪奉天市长，在营口、大石桥一带推行奴化教育，协助日军经济掠夺。；原奉系法律顾问，投日后任伪奉天市长，在沈阳及周边地区协助日军建立伪政权，参与经济掠夺。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('67cd54de07be4073895a9cf95c509a5a','589ab27feed347c6944e6c001125dc02',1931,'伪满洲国奉天省财政厅长（注：实际为早期投日者）','原奉系财政官员，投日后负责为伪政权搜刮民财，征收苛捐杂税。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1db058e611e749bd9ee8437f14371325','84779a454ec74ec19985a1b53e006685',1931,'伪满洲国监察院院长、奉天省实业厅长','原奉天省官员，投日后管理伪满实业，为日本掠夺辽宁矿产资源服务。；原奉系外交官，投日后在辽宁地区协助日军管理铁路、矿山，参与经济掠夺，并参与“清乡”活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('049eb820b7534a77b9572ba77d0bbe67','caae33d173854bf0a1b2b4f0db4f585a',1931,'伪满洲国奉天省警务厅长','负责伪奉天省警察系统，残酷镇压抗日地下活动，抓捕爱国人士。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8ae7b69585bc4c56bb42ad23c970ddee','c9dffc071fec4ce58fe1d611f26c28da',1931,'伪满洲国奉天省保安局长','指挥伪保安队配合日军扫荡抗日游击队，在辽宁各地制造白色恐怖。；在沈阳等地实施白色恐怖，破坏地下抗日组织。；辽宁沈阳人，任伪奉天省保安局长，在康平地区推行保甲制度，强化殖民统治，逮捕抗日志士。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('66b28b9a3a9c46828fe4cd521f5366d5','3cd55e29febc489d9f9a7f2f88db31bb',1931,'伪大连市公署市长','在日本殖民统治下任大连伪市长，推行奴化教育，协助日本管理大连港和工商经济。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d37d9415d9b04388825b60f0640160f6','673bb1093a734acebd0f7ae34d7651fb',1931,'伪大连商会会长、日本殖民当局顾问','大连巨商，长期为日本殖民当局服务，资助日军侵略，参与经济掠夺。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f2fdbc05f746421e9941c0b53bc1847a','39ba82fc190c440587eeb4c286bb126e',1932,'伪庄河县县长','在庄河地区任伪县长，协助日军清乡，镇压庄河抗日义勇军和民众反抗。','基层头目','hanjian');
