INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6524ba4a2c8a4929a54be483f9d515ee','589ab27feed347c6944e6c001125dc02',1931,'伪满洲国奉天省省长（曾管辖大连周边）','虽非沙河口本地，但作为伪满高级官员，积极推行日本殖民政策，协助日军控制辽宁地区经济与治安，间接影响大连沙河口。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('001f968f632c4e2d9d71a9cee800a04d','84779a454ec74ec19985a1b53e006685',1932,'伪满洲国监察院院长、汉奸政客','参与伪满政权建设，为日本侵略者出谋划策，在辽宁地区（含大连）推行奴化教育，镇压抗日力量。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0f0d17f864c4430a9112eb8d89686b25','16acda0beca145d6a02d3576760b6319',1938,'伪大连市市长','在任期间全面配合日本殖民统治，强制推行保甲制度，协助日军强征劳工，迫害沙河口地区中国居民。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('63bd22f5e9684faca3e847208e0b5c8a','de99900e1d9e47e4931e9fc71c5298ee',1939,'伪大连沙河口区区长','直接管辖沙河口地区，为日军提供情报，抓捕抗日分子，强征民夫修建军事设施，欺压当地百姓。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6a9ffffccfae4874887c793714423329','247dfbbaa63247e6972f3f1e381eadf4',1940,'伪沙河口警察分署署长','指挥伪警破坏中共大连地下组织，逮捕多名抗日志士，参与“沙河口大逮捕”事件，致多人牺牲。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('51d0150224834b25b72be3bb7f2e2fbf','12df332ea8ab40bfb7302fcc24b60d11',1941,'伪沙河口区协和会会长','组织协和会宣传“日满亲善”，诱骗青年参加伪军，协助日军进行经济掠夺，监视居民言行。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a61d3eba3e8345c09a3fce2e5a3c7477','9ca97c751dcb476ebe68ce659087d0e2',1935,'伪大连港务局沙河口码头把头','作为日本人的“包工头”，克扣工人工资，强迫劳工超时劳动，多次向日军告密工人中的抗日活动。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f27f7b29bf404fbbb43de15993f5c170','a33e6385cb6c40c3a4c2153469b04453',1942,'伪沙河口区保安队队长','率保安队配合日军扫荡，围捕抗日武装，参与杀害沙河口地区抗日群众，罪行累累。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('72245073e29d49c99bd3012a4d1161ae','84779a454ec74ec19985a1b53e006685',1931,'伪满奉天省省长、伪满监察院院长','九一八事变后投靠日本，任伪奉天省省长，协助日军建立伪满政权，镇压抗日活动。；九一八事变后投靠日本，任伪奉天省省长，协助日军维持殖民统治，镇压抗日活动。；九一八事变后投靠日本，出任伪奉天省省长，协助日军维持沈阳秩序，镇压抗日活动，后任伪满监察院院长。；九一八事变后投靠日本，任伪奉天省省长，协助日军维持辽阳等地殖民统治，镇压抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1dd6ca8889514e3aa8fe3767ac58bb9b','87b0aba74b9b4c5f8a515bd9270d23b4',1931,'伪满奉天省省长、伪满参议府议长','积极投靠日本，参与伪满建国，任伪奉天省省长期间推行奴化政策，协助日军统治辽宁。；积极投靠日本，主持伪奉天省政务，推行奴化教育，协助日军“讨伐”抗日武装。；曾任伪奉天省省长，推行奴化教育，协助日本掠夺辽宁资源。；积极投靠日本，组织伪奉天省政权，推行奴化教育，协助日军清剿抗日武装。；积极投靠日本，任伪奉天省省长期间推行奴化教育，强制收缴民间武器。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b827ba83a8a94de0bc5661283b3b9702','caae33d173854bf0a1b2b4f0db4f585a',1932,'伪满奉天省省长','投靠日本后任伪奉天省省长，协助日军清剿抗日义勇军，推行保甲制度。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c51869717cde41398a872bdb5fee9cff','5cce8fcbbcc043c2820499553d6999c1',1932,'伪满奉天市市长','任伪奉天市市长期间，配合日军对沈阳进行殖民管理，镇压抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f099035ccd994cfea4da2735dcaae309','d2b7a71572c34ce0943d2a891b842d96',1931,'伪满大连警察署署长','在大连地区为日本殖民当局效力，参与抓捕抗日志士，镇压大连地区抗日活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('63b79284a43445a488a5685f1c23ef61','673bb1093a734acebd0f7ae34d7651fb',1931,'伪满大连商会会长、汉奸商人','大连著名汉奸商人，为日军提供物资和资金支持，协助日本控制大连经济，迫害抗日人士。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('123e230f58904ec095c18d81dfe441b6','a2e63f8d6660475b9a55fa85c52afeeb',1931,'伪满大连地区维持会会长','九一八后在大连组织维持会，协助日军稳定殖民秩序，出卖抗日情报。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3aa276b3c00044648b3ed2871cae335b','589ab27feed347c6944e6c001125dc02',1932,'伪满大连民政署署长','在大连民政署任职期间，推行日本殖民政策，压制中国居民反抗。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3e53c9f4161c4022af55aca81e9b078a','f650372b6d184175a14b7cfc40a91bb6',1932,'伪满复县（今瓦房店）县长','任伪复县县长期间，配合日军清剿瓦房店地区抗日武装，强征劳工。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9663f827cb4f497ab63f8795e66639a3','797c553510f3440f88255e16480f23b4',1933,'伪满复县（今瓦房店）警察局长','在瓦房店地区为日军效力，抓捕抗日地下党员，破坏抗日组织。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ec292c9d0d4344cdac0170697a0ea1e9','6c5f2811c77d4f39b1ddb522f78f5e25',1931,'伪满瓦房店维持会会长','九一八后组织瓦房店维持会，协助日军建立地方伪政权，镇压当地抗日民众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c969ba4bc63d4b52beec7f4a95a22469','5fc0c32d90444fa8a850a6a2cc0ed8a5',1931,'伪满大连日本宪兵队翻译','在大连日本宪兵队担任翻译，参与审讯和迫害抗日志士，罪行累累。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d9a6a576ac4747769e7b084364447302','4ee925c7baed4d59912b9f25df26fa29',1932,'伪满大连水上警察署署长','负责大连港口殖民治安，协助日军封锁海上抗日运输线，抓捕抗日人员。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b0289633ece840cc864ddc9a06b37ab5','589ab27feed347c6944e6c001125dc02',NULL,'（无实际汉奸记录，此条不列入）',NULL,'无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('db69f3e74f7a43ba8943dd3e0957ecdb','1ba31d558b934fbd83a28a8c2b446022',1932,'伪满洲国侍从武官长、热河省省长','辽宁盖平（今盖州）人，原奉系军阀，后投日，任伪热河省省长，曾率伪军配合日军进攻抗日武装，其势力范围涉及辽宁及大连周边。；原洮辽镇守使，主动投靠日军，参与组建伪军，协助日军进攻热河及镇压抗日武装。；原黑龙江陆军将领，1932年公开投日，参与伪满政权，协助日军在黑龙江地区清剿抗日武装。；原奉系军阀，九一八后投日，任伪满高官，参与镇压抗日义勇军。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3b26099172aa4cbf932be758ee39d041','5cce8fcbbcc043c2820499553d6999c1',1938,'伪大连市市长（1938-1942）','辽宁大连人，日本殖民统治下任伪大连市长，推行奴化教育，协助日本管理大连港及工业，镇压当地反日运动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fbc2b0420a44468b835c39399a27a2fc','3cd55e29febc489d9f9a7f2f88db31bb',1930,'伪大连市警察局局长','辽宁大连人，任伪大连警察局长，积极搜捕抗日地下组织，协助日本宪兵队残害大连地区爱国志士。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('63fa312260e847fd9797130eb494f282','673bb1093a734acebd0f7ae34d7651fb',1931,'大连商会会长、日本殖民当局御用商人','辽宁大连人，经营航运及贸易，为日本侵华提供物资和资金，组织汉奸商会，协助日本经济掠夺大连地区资源。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6b5948e09bd24350ba6d8e779b2428ed','39ba82fc190c440587eeb4c286bb126e',1930,'伪甘井子区区长（具体任期不详）','辽宁大连甘井子人，在日本殖民统治下任甘井子区长，协助日本推行保甲制度，强征劳工，镇压当地反抗。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7b54c0bc7a244d029b9139a58aa60b79','0d0bffb8fd9f440595851f71ab48a4fe',1930,'伪甘井子警察署署长','辽宁大连甘井子人，任伪警察署长，配合日军抓捕抗日分子，参与“治安肃正”行动，迫害当地居民。','无明确职位或一般帮凶','hanjian');
