INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('958d22af30a34d4694a76324dc6b20a7','caae33d173854bf0a1b2b4f0db4f585a',1932,'伪满洲国司法部大臣','辽宁沈阳人，原奉天高等法院院长，投敌后任伪司法大臣，制定殖民法律，迫害辽宁及大连地区抗日民众。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6bc71d50f47c41e8b9c36d2c8f676cf6','41502657c6b84465aa2ff94e620ed234',1932,'伪满洲国实业部大臣','辽宁辽阳人，原东北矿务局督办，投日后任伪实业大臣，协助日本掠夺辽宁及大连地区矿产和工业资源。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('db9f280dd8e645c58c7d576a8886f0ed','142849ebf8614017a075f60e0d2e7e40',1942,'伪大连市副市长（1942-1945）','辽宁大连人，任伪副市长，协助日本市长管理市政，推行粮食配给制，导致大连民众饥荒。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('eb53d1afdda144c7be9f10f586bbf042','589ab27feed347c6944e6c001125dc02',1931,'伪满洲国财政部总长（未就任，但曾为奉系要员）','辽宁大连金州人，虽未正式就任伪职，但曾与日本合作，其子王维宙等亲属在伪满任职，家族有汉奸行为记录。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('26866438a90d4b8f8855246b965db900','c9dffc071fec4ce58fe1d611f26c28da',1937,'伪满洲国奉天省省长','辽宁沈阳人，曾任伪奉天省省长，推行日本经济统制政策，强征劳工。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5b45a9eb446741d3aa5ef184328d024e','3cd55e29febc489d9f9a7f2f88db31bb',1932,'伪大连警察局局长','辽宁大连人，曾任伪大连警察局局长，参与抓捕抗日志士，迫害大连西岗地区进步群众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c6052124b5a94c69802fbd122a7a2db7','39ba82fc190c440587eeb4c286bb126e',1937,'伪满洲国大连地区宪兵队队长','辽宁大连人，曾任伪大连宪兵队队长，残酷镇压西岗区及周边抗日地下组织。','基层头目','hanjian');
