INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e00fbaf9d51045a7be0b342c7eefd45f','57c54552ab03419d9aadc8ae4720540b',1938,'伪大连西岗区警察署署长','辽宁大连人，曾任伪西岗区警察署署长，多次参与围捕抗日地下党员，迫害西岗区居民。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8c0261214bfe4c899b4838dcfc3fb6c4','247dfbbaa63247e6972f3f1e381eadf4',1935,'伪满洲国大连地区协和会头目','辽宁大连人，曾任伪协和会大连分会负责人，宣传“日满亲善”，瓦解民众抗日意志。','无明确职位或一般帮凶','hanjian');
