INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d0ff059bb06a40ac9e6a132311a65139','84779a454ec74ec19985a1b53e006685',1931,'伪满洲国监察院院长、奉天省省长','曾任东三省保安司令部顾问，后投靠日本，参与策划伪满建国，任伪奉天省省长。；原奉系官僚，投敌后长期在奉天省（含营口地区）任职，为日军提供情报，参与“清乡”行动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b8dabf9c22254b90962d326cc0c9f725','87b0aba74b9b4c5f8a515bd9270d23b4',1931,'伪满洲国尚书府大臣、奉天省省长','清末举人，九一八后出任伪奉天省省长，后任伪满尚书府大臣，为日本殖民政策服务。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('66af924cdeb1478eae8909f6a6dc051d','589ab27feed347c6944e6c001125dc02',1931,'伪满洲国交通部大臣（注：其早逝，但曾为奉系要员，需核实）','原奉系财政要员，九一八后一度被日军拉拢，但未实际任职，此处存疑，不列入。','无明确职位或一般帮凶','hanjian');
