INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bcc187bc05504d37a32d6400baed3f18','f1c6013bde504b5a97029739c664d873',1934,'伪满洲国锦州省省长','在辽西地区强征民夫修建军事设施，协助日军“讨伐”抗日武装。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9d6b47a642e54391a7c290eedf761102','922b606d45c647e8a82755373b3d3e91',1933,'伪满洲国热河省（今辽宁西部）省长','在朝阳、阜新等地推行“集家并村”，制造无人区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d03d917b765c47ae8fce66cfc6856bba','70cbcc058e6648678fa022e3a64b9cea',1932,'伪抚顺县县长','在抚顺县推行伪满法令，协助日军清乡，迫害抗日家属，参与制造“平顶山惨案”后的善后掩盖工作。；在抚顺县推行伪满法令，协助日军建立保甲制度，迫害抗日家属，参与镇压平顶山惨案后的反抗活动。；任伪抚顺县长期间，协助日军推行保甲制度，强征劳工，参与镇压抚顺地区抗日武装。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1ebd640146374d728c3f8b563e24dc9c','4b379e116bbf4841b9e829577042d380',1937,'伪抚顺市市长（伪满时期）','主持伪抚顺市政，为日军提供煤炭资源，强制推行“勤劳奉仕”，镇压矿工反抗。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9765b96599cc461e918a2993680662f4','2caaa8fc4c1d4c9cac6c3cc0c4b0508d',NULL,'无（已故，不列入）','杨宇霆于1929年被张学良处决，不在抗战时期活动，故不列入。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('856e75d1259b4d588835abcd24e28555','77a789268c6f47b4a617cdb9e41180bd',1935,'伪满国务总理大臣（曾管辖辽宁地区）','作为伪满最高行政长官，对包括抚顺在内的辽宁地区负有殖民统治责任，支持日军侵略政策。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e180ca4168e04d6199059909f63baa1f','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满立法院院长（曾任奉天市市长）','九一八后任伪奉天市市长，后升任伪满立法院院长，积极为日本侵略辩护，参与“满洲国”法统建设。；九一八后任伪奉天市市长，后升任伪满立法院院长，积极推行日本殖民统治。；虽主要活动于沈阳，但多次到辽阳、太子河地区为伪满政权宣传，参与制定殖民法规，协助日军掠夺当地资源。；虽主要活动于沈阳，但作为辽宁地区伪政权核心人物，参与制定奴化教育及经济掠夺政策，影响覆盖鞍山、台安。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d4720ff526a545c1a3ac53720a94f27e','360451ccb61f491bafdc1b28af3c6799',1937,'伪满奉天省次长（实际掌权者）','作为日本关东军控制的“次长”制度代表，实际操纵伪奉天省政务，推行经济统制，镇压抗日活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('553dab7a491241289b1e9c46f673671b','5d5b588b85754731b7b48a6f383d6ce5',1933,'伪抚顺警察局局长','指挥伪警察配合日军搜捕抗日分子，参与“集团部落”建设，迫害平民。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('63771585702e45ba9ad798d063323707','21853206ad2b417598d1af0b4b3a4782',1932,'伪抚顺矿务局总办（汉奸矿主）','为日军开采抚顺煤矿，残酷压榨矿工，提供战争资源，并协助日军镇压矿工罢工。','无明确职位或一般帮凶','hanjian');
