INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9dda50193c4740a1960721e56bd182dd','bde77533c68f469aa5eeb667ea3940ed',1931,'伪奉天市市长、伪满洲国立法委员','九一八事变后积极附逆，参与伪满建国活动，曾任伪奉天市市长，为日军在辽宁的殖民统治效力。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f9d80d8fc76d4c709663667ee7f1aaee','21853206ad2b417598d1af0b4b3a4782',1931,'伪安东省警备司令、伪军头目','原东北军军官，投敌后组织伪军，在辽宁东部包括抚顺周边地区配合日军围剿抗日武装。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1f66395ef5f34692995f33859c628f9e','c9dffc071fec4ce58fe1d611f26c28da',1931,'伪奉天省警务厅厅长、伪警察头目','在伪奉天省警务系统任职，参与镇压辽宁地区抗日活动，抚顺地区伪警察系统受其节制或影响。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5729ae498e3b4bbeaf698ed2b1e7e64e','5cce8fcbbcc043c2820499553d6999c1',1930,'伪抚顺县县长','伪满时期出任抚顺县县长，协助日军管理抚顺煤矿及地方事务，推行保甲连坐，镇压抗日民众。','基层头目','hanjian');
