INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8efcf3a7ad32478ba99cb4256ee5f328','80825e93c5dd408297e82f20484a17c4',1930,'伪抚顺县警务局局长','在抚顺地区担任伪警务头目，指挥伪警察配合日军搜捕抗日人员，推行保甲制度。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5ab491a22eb848298dcb98f9be90ca1e','3b74f508628f475a8777ffb7e38a48a0',1931,'伪满洲国经济部大臣、伪奉天省省长','辽宁籍附逆者，历任伪满经济部大臣、伪奉天省省长，参与掠夺辽宁资源，抚顺煤矿为其经济统制范围。；在辽宁推行经济统制，掠夺煤炭、粮食等资源，阜新煤矿劳工征调与其政策直接相关。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a4ad7d362801471c938f6a5c27595281','360451ccb61f491bafdc1b28af3c6799',1931,'伪满洲国文教部大臣、伪奉天省省长','投敌后历任伪满文教部大臣、伪奉天省省长，推行奴化教育，其管辖范围包括抚顺地区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f748af0912fd42b5a219640f8d0d6173','9371eb94ef6548c6887387e706c61a27',1930,'伪满洲国协和会中央本部委员、伪奉天省次长','在伪满协和会及伪奉天省任职，参与思想统制与地方控制，影响覆盖抚顺。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('17a29da0b056462f8185690b20fbff34','d2b7a71572c34ce0943d2a891b842d96',1930,'伪抚顺县协和会会长','在抚顺地区负责伪协和会工作，配合日军进行宣传、劳役征集和民众控制。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ec490c4be1d4426ea45c491f14c1ca07','51c86e593b934a1d8b87784ac6841a7f',1930,'伪抚顺炭矿警备队队长','统领抚顺煤矿伪警备队，镇压矿工反抗，协助日军维护矿区殖民统治。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('72497ad5d7764437bd01610430d99116','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满第一军管区司令官（驻奉天）','原东北军军官，投敌后任伪满军职，在辽宁地区多次参与“讨伐”抗日义勇军和抗联，制造多起屠杀事件。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('15bed480f1b448a393f00a754fc2b42e','21853206ad2b417598d1af0b4b3a4782',1932,'伪满鸭绿江地区“讨伐”司令','原土匪头目，投日后组建伪军，在宽甸、桓仁、新宾等辽东山区残酷围剿抗日武装，杀害大量民众，有“李剥皮”之称。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('df75b14d2c2c4f958215bf1735464bcc','d9bb7f270e97437ba2d41b2afdb1e972',1933,'伪满东边道“讨伐”司令','原东北军军官，投敌后长期在抚顺、新宾、通化一带追击杨靖宇抗联部队，多次设伏偷袭，是抗联在辽东最凶恶的敌人之一。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bcaec58b1ae14a91a5bfda44e2080f14','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满立法院院长、奉天市市长','原奉系法律界人物，投日后任伪奉天市长，协助日本关东军建立殖民秩序，参与策划伪满建国，并协助日本掠夺辽宁资源。；曾任伪奉天市市长，积极协助日军建立殖民秩序，参与制定镇压抗日民众的法令，在沈阳及辽中地区推行保甲制度。；原奉系法律人士，九一八后投敌，曾任伪奉天市市长（管辖辽阳部分区域），协助日本建立伪政权，后任伪满立法院院长，参与制定殖民法律。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1203d28695fc471192ec2330976a2ce3','360451ccb61f491bafdc1b28af3c6799',1937,'伪满奉天省省长（继于芷山后）','原奉天省官员，投日后历任伪满要职，任伪奉天省长期间强化“保甲制度”，配合日军推行“集家并屯”，切断民众与抗联联系。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b7b2bac5355b4c21b9f85c455ac03110','5d5b588b85754731b7b48a6f383d6ce5',1932,'伪满抚顺县县长','在抚顺地区推行日伪统治，协助日军镇压煤矿工人反抗，参与制造“平顶山惨案”后的善后掩盖工作。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fe6e661423e945debd4a0873960afbfd','4b379e116bbf4841b9e829577042d380',1932,'伪满新宾县县长','在新宾县（当时称兴京县）组织伪县署，配合日军“清乡”，多次率伪警察队袭击抗联游击队，杀害抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('239d8caea2474456b41dbf03922b694d','e0b61049ee4c4a1c86102a98d0c71ce4',1933,'伪满新宾县警务科科长','在新宾地区建立特务情报网，多次破坏抗联地下联络站，亲自审讯并杀害多名抗联战士及支持者。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3979c14e1b2e46dbb555db24a221b10a','08e5273ef5cd4e63bb8877270c73bba6',1932,'伪满抚顺地区“自卫团”团长','组织地方汉奸武装，配合日军巡逻抚顺矿区及周边乡村，多次参与搜捕抗联和抗日群众，掠夺民财。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e9d407ed1d704ec88f5d994892a2fb10','af96068e274a4fdfb011573dd045f17a',1934,'伪满东边道“讨伐”队队长','原土匪，投日后专门在新宾、桓仁一带山区追踪抗联，熟悉地形，多次引导日军突袭抗联密营，造成重大损失。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('433088ff1f6a4b44a2f92dea5f232260','ab3dded23c7447adb919b9a8705e1bf9',1931,'伪满抚顺县警务局副局长','长期在抚顺地区执行“治安肃正”，抓捕抗日分子，并参与对煤矿工人的奴役管理，克扣口粮。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('34db306abb3546f69d92d51074095adb','844c439b40b74422a9f7d5bed8019784',1935,'伪满新宾县“协和会”会长','利用“协和会”宣传奴化思想，搜集抗日情报，组织汉奸团体为日军募捐，并参与强迫青年当伪军。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fc8477346ecc4a95929259b7beb61fec','f73d32c480c14ee0b750a8b239212569',1932,'伪满抚顺炭矿劳务系主任','协助日本资本家管理中国矿工，残酷压榨劳工，迫害反抗者，并配合日军抓捕逃逸矿工。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('abb0e5679d8c40e488cca9ae19bce898','5cce8fcbbcc043c2820499553d6999c1',1932,'伪满抚顺县县长','任伪抚顺县县长期间，强征劳工，为日本开采抚顺煤矿提供人力，镇压矿工反抗。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2d6e9baa8d7c47e0976089d6c1538e70','848e143eb7124239bf45e34a0853fd88',1933,'伪满抚顺县警务科长','指挥伪警察抓捕抗日分子，协助日军实施“归屯并户”，制造无人区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f010faf9a9884ded972386c8bac1d2bf','15b0ffb0c3064aa4a57d4d84ac82b7fa',1932,'伪满抚顺地区保安队队长','率伪保安队配合日军扫荡新抚地区抗日游击队，杀害多名抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('60de0fef53dd4a8089055795a02e05b5','1c88a5dc4ffb4fa38fb4f7268277ceca',1931,'伪满新抚区维持会会长','组织地方维持会，为日军提供粮草情报，协助建立伪政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5a3c5b5e9d2841e595c0529b247a4d0d','21853206ad2b417598d1af0b4b3a4782',1933,'伪满抚顺宪兵队翻译官','为日本宪兵队充当翻译，参与审讯和迫害抗日志士，罪行累累。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1248d6ad83af42ff974bfae2da1ab039','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满立法院院长（曾任奉天地区职务）','虽主要活动于伪满中央，但早年参与辽宁地区伪政权筹建，推动“满洲独立”。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6d37cf616217417986215efc23e74eb6','360451ccb61f491bafdc1b28af3c6799',1932,'伪满奉天省教育厅厅长','推行日本奴化教育，在抚顺新抚地区学校强制灌输“日满亲善”，篡改历史教材。；推行奴化教育，强制学校教授日语，篡改历史。；推行奴化教育，在沈阳地区强制推行日语教学和殖民思想宣传。；在伪奉天省（含辽阳、文圣）推行奴化教育，强制学校教授日语，篡改历史教材，压制民族意识。；原辽宁教育界人士，投敌后任伪奉天省教育厅长，在鞍山、海城等地推行奴化教育，强制学校使用日语教材，灌输“日满亲善”思想。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('871836bcdba44d88b4b03c8a7e21604d','28ee45c17bf74301baeddd7809e70082',1933,'伪抚顺县警务局长','指挥伪警察配合日军搜捕抗日分子，在望花地区设立检查站，多次参与“讨伐”行动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7049e2db8a694a4c840d923eb9b56fc6','1ba31d558b934fbd83a28a8c2b446022',1933,'伪满热河省省长（曾驻抚顺活动）','原奉系军阀，后投敌，在抚顺及周边地区协助日军围剿抗日义勇军，残害百姓。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('709f84605a004aaea92bb5ebb0d01b85','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满立法院院长（曾参与抚顺地区殖民统治）','作为伪满高层，推动在抚顺地区实施“治安肃正”，支持日军对望花煤矿区的军事管制。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('85eded9e41a84bfd9b7f04ef25ea14f6','360451ccb61f491bafdc1b28af3c6799',1937,'伪满奉天省次长（实际掌权）','日本关东军扶植的汉奸，在抚顺地区推行经济统制，强占煤矿资源，压迫矿工。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8c81fc5511ba425daa023621c93a7b6a','5cce8fcbbcc043c2820499553d6999c1',1940,'伪抚顺市公署市长（1940年后）','在望花区推行“勤劳奉仕”运动，强征中国劳工为日军服务，协助日本特务机关监控居民。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ed2e1649997b43a582e6c1d1303b2c67','21853206ad2b417598d1af0b4b3a4782',1932,'伪抚顺地区保安队队长','组织汉奸武装，在望花一带抓捕抗日志士，多次配合日军进行“扫荡”，杀害无辜群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2a738584c87049e7bf8d02bc9fbd1c11','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满热河省省长、伪满军政部顾问','原东北军将领，1931年投降日军，在辽宁地区协助日军围剿抗日武装，后任伪热河省省长，参与“讨伐”抗日联军。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('283c79c9e1af4d66ba86c28bdde9b02c','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满奉天省警务厅厅长','在抚顺、清原地区组织伪警察和特务，多次参与“讨伐”杨靖宇领导的抗日联军，制造多起屠杀平民事件。；原奉天省警察头目，投日后任伪警务厅长，在本溪平山地区建立特务网络，抓捕抗日志士。；原奉系警察头目，投日后任伪奉天省警务厅厅长，直接指挥本溪、溪湖地区的伪警察和特务，搜捕抗日地下组织，破坏抗联交通线。；在铁岭地区组织伪警察，配合日军进行“治安肃正”，逮捕抗日地下工作者，实施“归屯并户”政策。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('774baae520e1406e98b1f3e0e6f8354f','21853206ad2b417598d1af0b4b3a4782',1932,'伪满清原县县长','任清原县伪县长期间，强征劳工，推行“保甲连坐”制度，配合日军清剿抗日游击队，迫害抗日家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e772a05a8baf478180a8c3994ab7ef89','f9b7e2a3165647cbb76c650c3dd11d27',1933,'伪满抚顺县县长','在抚顺地区协助日军实施“集家并屯”，破坏抗日根据地，参与镇压抚顺煤矿工人反抗运动。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0972c738df574d18a563e72dbee353d8','103ce81b67a940d4ab9979aae8824f91',1932,'伪满奉天省警察厅特务科科长','在抚顺、清原等地建立特务网络，搜捕抗日地下工作者，曾参与破坏中共南满地下组织。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('04cbe8fb2f8b447b83cb77bf1c3c06b6','5cce8fcbbcc043c2820499553d6999c1',1934,'伪满清原县警务科科长','指挥伪警察多次突袭清原山区抗日营地，杀害抗联伤员，并强迫村民报告抗联行踪。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6a1a7eb20410454c9995d1480c2bf679','08e5273ef5cd4e63bb8877270c73bba6',1932,'伪满抚顺地区自卫团团长','组织地方汉奸武装，配合日军“扫荡”抚顺东部山区，参与制造“平顶山惨案”的辅助行动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c27405026798491d85120bdf88c32c56','6b635b027b974274ba6ff34ff48b378c',1935,'伪满清原县协和会会长','宣传“日满亲善”，诱骗青年参加伪军，协助日军收集抗联情报，破坏群众抗日组织。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('643ba4f68db748c3bbcc66d8f26b513f','3a9e402192aa460fb51a927d874bb93e',1933,'伪满抚顺县保安队队长','率保安队多次袭击清原、新宾交界处的抗联密营，杀害抗联战士和群众，抢夺粮食物资。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6ef8eb9ed3f4442a995d6b32e34f2558','4b379e116bbf4841b9e829577042d380',1933,'伪抚顺县警务科科长','指挥伪警察配合日军“讨伐”，多次围剿抚顺、顺城一带的抗日游击队，抓捕并杀害抗日志士。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e03764f013404b33b7f298d9a02f3c02','36fd3fee0de044f08251aeaa95b6da71',1937,'伪抚顺市公署市长（伪满时期）','在抚顺推行日伪殖民政策，组织“勤劳奉仕”强征劳工，为日军提供煤炭资源。','市县厅局级','hanjian');
