INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b8e93a136bc34f3993cf1e6a3160083b','a984ebfabbf64a5b8e1dfef2d68daa53',1933,'伪满热河省警务厅长','原东北军军官，投日后任伪警务厅长，参与围剿抗日游击队，抓捕抗日志士。；原东北军军官，投敌后任伪警务厅长，参与围剿抗日义勇军，抓捕抗日志士。','市县厅局级','hanjian');
