INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('692eed5f11824e56809a6f75a9c373e7','9f7b3ed9c76f4eea8211fd8ebc40a461',1937,'伪“冀东防共自治政府”顾问（涉及朝阳边境）','原军阀，1937年一度与日军合作，其部队在朝阳西部活动，后反正。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0d04d4353efd4cc5b1502b30d10f68e0','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洲国热河省省长兼第五军管区司令','原东北军将领，1933年投敌，任伪热河省省长，镇压抗日武装，协助日军统治朝阳地区，推行殖民政策。；原东北军将领，九一八后投敌，在辽宁西部及兴城、绥中一带协助日军镇压抗日武装，参与“讨伐”义勇军，后任伪热河省省长，推行殖民统治。；原东北军将领，1933年投敌，任伪热河省省长，参与镇压抗日武装，协助日军统治建昌、凌源等地区，推行殖民政策。；原东北军将领，九一八事变后投敌，在辽宁西部及热河地区协助日军镇压抗日武装，参与围剿义勇军，后任伪满要职。；原东北军将领，九一八后投敌，在锦州、古塔一带协助日军镇压抗日武装，推行殖民统治，参与“讨伐”义勇军和抗联部队。；原东北军将领，1932年投敌，曾任伪满热河省长，但早年曾在黑龙江穆棱一带活动，后成为日军在东北的重要傀儡，参与镇压抗日武装。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3eeb27b63efc44e9b3f2c7bf61cfad24','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满洲国立法院院长（曾任热河省相关职务）','积极参与伪满政权建立，在热河省（含朝阳、龙城）推行日伪法令，协助日军清剿抗日力量。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('59a85ac5ba3d4dfdbc792f533a8dd602','3a9e402192aa460fb51a927d874bb93e',1933,'伪热河省警务厅厅长','在朝阳、龙城地区组织伪警察，抓捕抗日志士，配合日军“讨伐”活动，残害百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('92193cbccde545d5872169a070210204','8fdb75c63ff4478aa86d74431b472cde',1933,'伪热河省朝阳县县长','投日后任朝阳县伪县长，强征粮税，强迫民众修路筑堡，为日军提供情报，镇压当地抗日游击队。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6419dc6bfaeb42588fe62ce4a6355baf','15aba61e822c4e50a3d0ac9384c005f1',1933,'伪热河省龙城县（今属朝阳）维持会会长','组织维持会，协助日军建立伪政权，搜刮民财，出卖抗日人员，导致多名地下党员被捕牺牲。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('34497ca108a54c57aa751cf7a167dc2b','9f7b3ed9c76f4eea8211fd8ebc40a461',1933,'伪“冀东防共自治政府”暂编第二军军长（在热河期间）','1933年一度接受伪职，在热河朝阳地区与日军合作，后反正，但期间曾协助日军镇压义勇军。','市县厅局级','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('56e3cc0afaa8421988a3e6ac44a36d3c','d5a662852dd34787a69b09067f21b23c',1933,'伪热河省警备军第三旅旅长','原土匪头目，投日后在朝阳、龙城一带驻防，多次率伪军袭击抗日武装，烧毁村庄，屠杀平民。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a96664c0076e49018b21bf0ed2715bc4','2bdebe80571b4f8f8392a87cf474cc7d',1935,'伪热河省朝阳县警务科科长','负责朝阳地区特务工作，建立情报网，抓捕抗日分子，参与“三光”政策实施。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5631c338b83249b78b2b506f4cd099d4','867d28ff6d954de38b8bc2de0c1db7e7',1937,'伪龙城地区保安队队长','率领伪保安队配合日军扫荡，在龙城周边多次屠杀抗日群众，抢掠财物，民愤极大。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5646445b61134881a524ec7c7fa7c7f0','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满第一军管区司令（驻奉天/本溪一带）','原东北军旅长，叛国投敌，率伪军在本溪、抚顺等地围剿抗联和抗日义勇军，制造多起屠杀事件。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b62a1af84af24488877c1b579a294644','c9dffc071fec4ce58fe1d611f26c28da',1931,'伪满奉天省警务厅长','负责本溪地区伪警宪特系统，抓捕抗日志士，协助日本宪兵队镇压本溪湖煤矿工人罢工和抗日活动。；负责伪奉天省警察系统，在沈阳及辽中地区大肆搜捕抗日分子，破坏地下组织，执行日军“治安肃正”计划。；原奉天警察头目，投日后任伪奉天省警务厅长，指挥警察特务大肆搜捕抗日分子，制造多起惨案。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9c395b00b21345ef9679a86de333cd96','21853206ad2b417598d1af0b4b3a4782',1937,'伪满本溪湖市市长','任伪市长期间，强征劳工，推行保甲制度，配合日军“讨伐”本溪山区抗联部队，掠夺当地资源。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c7bc084b233c418ab35ca163d93b24d4','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满立法院院长（曾涉本溪地区）','原奉系法律人士，投日后参与伪满政权建设，支持本溪地区殖民统治和“治安肃正”政策。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('88f1eb3b738f4164a4e4b6c565a4bbea','1a8847af165d4d648f62d949fad6cb5a',1933,'伪满本溪湖警察署署长','直接指挥本溪地区伪警察，搜捕地下党员和抗联交通员，参与“集团部落”建设，迫害百姓。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('735abe9c23bc47ee8d3a2b6d41e0b7ee','af96068e274a4fdfb011573dd045f17a',1935,'伪满本溪县县长','推行日伪“粮谷出荷”政策，强征本溪农民粮食，协助日军烧毁抗联密营，杀害抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6b272bfd4cd34613a90f08feed842fa7','77a789268c6f47b4a617cdb9e41180bd',1935,'伪满国务总理大臣（曾管辖本溪地区）','作为伪满最高行政头目，签署多项针对本溪等地的“讨伐”和“移民”法令，支持日军镇压抗联。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ce4d46e8dc9d456386e46ab181a520c7','79b17193512846a1a5bde9f5df22c926',1932,'伪满奉天省省长（本溪属其辖区）','原辽宁省政府主席，投敌后长期主政奉天省，配合日军在本溪推行“治安强化运动”，围剿抗日武装。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f8ef72b8c49243e9924bd281ed31861d','84779a454ec74ec19985a1b53e006685',1932,'伪满监察院院长（曾涉本溪矿务）','早年参与本溪湖铁矿管理，投日后协助日本满铁控制本溪煤铁，为日军军工提供资源。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('85246e7e406f46849ae4b3aec7fef934','5cce8fcbbcc043c2820499553d6999c1',1935,'伪满本溪湖宪兵队翻译官','充当日军宪兵队翻译，参与刑讯逼供抗日志士，指认抗联人员，导致多人牺牲。；为日本宪兵队充当翻译，参与刑讯逼供，直接迫害平山地区抗日地下工作者。；本溪湖本地人，为日军宪兵队担任翻译，参与审讯和刑讯抗日志士，多次带领日军搜查溪湖地区的地下抗日组织。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fc308c17c2fd4660959c71a939a4345e','b8f5150658fd47f0a48c92aacb628181',1934,'伪满本溪地区协和会头目','组织协和会宣传奴化思想，监视民众，向日军报告抗联活动，协助“清乡”行动。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('572217b46088442d9f624f2f75c7c06b','0ea2cb25dcff4f368f9a6bbe89b01634',1936,'伪满本溪县协和会会长','积极推行“日满亲善”宣传，组织汉奸团体，为日军提供本溪山区抗联情报，破坏地下组织。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('28737298f55b469aa6ccc041db88a97b','589ab27feed347c6944e6c001125dc02',NULL,'',NULL,'无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1f9f9db3f15b4a1581d0c475609485e5','7ca60279616445fcaa58c2399291ebcb',NULL,'',NULL,'无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c40d2b09faf2473cb8424cbbb2228814','2caaa8fc4c1d4c9cac6c3cc0c4b0508d',NULL,'',NULL,'无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('714bb3ea1a2748e285b1a5ea7fa17515','41502657c6b84465aa2ff94e620ed234',1937,'伪满民生部大臣（曾涉本溪劳工）','主管伪满劳工政策，从本溪强征数万劳工下井采煤，致大量劳工死亡，被称“血煤”。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f2d053484daa4bea98a4bfb7bab46b8e','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满经济部大臣（本溪煤铁公司董事）','作为伪满经济要员，直接参与本溪湖煤铁公司经营，为日军生产军需钢铁，压榨中国矿工。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e304887046214ea08c64ff090cd4d2af','360451ccb61f491bafdc1b28af3c6799',1935,'伪满交通部大臣（本溪铁路监管）','负责本溪地区铁路运输，保障日军军事物资和掠夺资源运输，协助“讨伐”行动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e7c7cc8b8758440797d747e4c02f42f7','3eb966fdcf364389b5302ef8a669f7ac',1932,'伪满司法部大臣（本溪法院系统）','建立伪满司法体系，在本溪地区审判抗日人士，以“反满抗日”罪名判处多人死刑或劳役。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('202e7375b02a49f48e81afa8900068d8','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满热河省省长、伪满第七军管区司令','九一八事变后投敌，曾任伪满热河省省长，参与镇压抗日武装，其部队曾在本溪、南芬一带活动，协助日军围剿抗联部队。；原东北军将领，1931年九一八事变后投敌，在辽宁西部及铁岭、开原一带协助日军镇压抗日武装，后任伪满热河省省长，积极推行日伪殖民政策。；原东北军将领，九一八后投敌，在辽宁西部及热河地区协助日军镇压抗日武装，后任伪满要职，参与“治安肃正”行动。；原东北军将领，九一八后投敌，曾任伪满要职，参与镇压抗日武装，其势力范围曾涉及黑龙江东部地区，包括七台河一带的讨伐行动。；原东北军将领，1931年九一八事变后投敌，曾任伪满热河省省长，后调任伪满第七军管区司令，在黑龙江地区协助日军镇压抗日武装。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('19d1b4aac8bc414885e654314cfaef3d','c9dffc071fec4ce58fe1d611f26c28da',1931,'伪满奉天省警察厅厅长','原奉天省警察头目，投日后任伪满奉天省警察厅厅长，直接指挥本溪、南芬地区的伪警察和特务，搜捕抗日分子，破坏地下组织。；原奉系警察头目，投日后任伪奉天省警察厅厅长，在沈阳及铁岭、昌图地区大肆搜捕抗日分子，镇压民众反抗。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('71deb63e7bf14885925949bfb241a37d','21853206ad2b417598d1af0b4b3a4782',1932,'伪满本溪湖市市长（本溪湖为今本溪市前身）','伪满时期长期担任本溪湖市市长，推行日伪殖民政策，强征劳工，为日军提供铁矿资源，协助镇压南芬矿区工人反抗。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5c3f42b4873b483887d83cfb5b4c6876','54a2238c4cd748b78806a15c959a5b49',1933,'伪满本溪湖警察署署长','在本溪、南芬地区任伪警察署长，多次率伪警配合日军“讨伐”抗联，抓捕并杀害抗日群众，制造多起惨案。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('259f2c1d2a24422eaee1229376aff176','79b17193512846a1a5bde9f5df22c926',1931,'伪满奉天省省长','原辽宁省政府主席，投敌后任伪满奉天省省长，管辖本溪、南芬地区，积极推行日伪“治安强化运动”，镇压抗日力量。；原辽宁省主席，投敌后任伪奉天省省长，管辖本溪地区，积极推行日伪殖民统治，支持日军在本溪湖设立宪兵队和特务机关。；原奉天省主席，投日后任伪奉天省长，曾多次到葫芦岛、南票视察，督促加强“治安”和资源开发。；原辽宁省政府主席，投日后任伪奉天省省长，管辖包括鞍山、岫岩在内的地区，推行日伪殖民政策。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('93db59c82b524063a47fd6d7d1c285f1','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满立法院院长（曾任奉天市长）','曾任伪奉天市长，参与制定针对辽宁东部山区的“讨伐”计划，其政策直接影响本溪、南芬地区的抗日活动。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fc260da77eb745b9876c27e19c040fcf','360451ccb61f491bafdc1b28af3c6799',1932,'伪满奉天省警务厅长','负责伪满奉天省警察系统，多次组织对本溪、南芬山区抗联密营的突袭，抓捕抗联交通员。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7e482c29fcef4f509f7a64e18eebf3c0','5d5b588b85754731b7b48a6f383d6ce5',1933,'伪满本溪湖矿业所所长（兼日本铁矿合作代表）','作为日伪在本地矿业代理人，残酷压榨南芬铁矿工人，向日军提供战略物资，并协助日军镇压矿工罢工。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('20d83fcd6d6043f2a0c12e2464cb4c8e','af96068e274a4fdfb011573dd045f17a',1934,'伪满本溪县县长（本溪县含南芬地区）','任伪本溪县县长期间，推行“归屯并户”，制造无人区，切断抗联与群众联系，多次率县伪军配合日军扫荡南芬山区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('864ec0c8caf94639813ffcd0379ca2e7','46f570699efd413fa741462847e46f14',1935,'伪满南芬警察分驻所所长','直接驻守南芬地区，负责监视矿区工人和周边村民，多次告密导致抗联地下联络点被破坏，参与杀害多名抗日志士。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6b022a7a065e49be9cff6f7d8f8b75eb','08e5273ef5cd4e63bb8877270c73bba6',1932,'伪满本溪湖保安队队长','率保安队在本溪、南芬一带巡逻，协助日军“清乡”，抓捕抗联伤员和群众，烧毁村庄。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('afc9ee77d91c4d0d981af972fa8fe32d','6875a03c8d354c2996dd34a8f2f2fc05',1936,'伪满奉天省协和会本溪支部长','利用协和会组织，在南芬矿区进行奴化宣传，诱骗青年加入伪军，收集抗日情报。','省部级/大军区级要员','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('39e6a2cbc9854d1895024f92d3b35036','a2c03b81e5f2412bb86f5d5599c1687b',1937,'伪满本溪湖宪兵队翻译官','为日军宪兵队担任翻译，参与审讯和刑讯抗日志士，直接导致多名抗联战士牺牲于本溪监狱。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a9f79ac28b91493bbf879b61effa9988','ba135ba1ef794aeba0fdad0065a31974',1933,'伪满本溪地区“讨伐队”队长','原为抗日武装成员，后叛变投敌，熟悉抗联活动规律，带领日伪军多次突袭南芬山区抗联营地。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fdc2ef6532904054860be6395857ba32','1d67ff455ffc47b8addcc485beb0ca34',1932,'伪满第一军管区司令官（驻奉天）','原东北军旅长，叛国投敌，任伪满第一军管区司令，管辖包括本溪在内的辽宁中东部地区，多次组织“讨伐”抗日联军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('477ef37b1c2842b4a78161b59b9c69df','21853206ad2b417598d1af0b4b3a4782',1932,'伪满本溪湖警察署署长','本溪本地汉奸，充当日军走狗，在平山地区残酷镇压矿工和抗日群众，制造多起血案。；本溪湖（今溪湖）本地人，投靠日军后任伪本溪湖警察署署长，积极抓捕抗联战士和爱国群众，多次带队袭击溪湖周边的抗联据点。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f6ab5cdf1a974d31809f47c64bf89444','6f65b42b31a1440e972583350bac6450',1933,'伪满本溪县县长','投靠日伪，任本溪县县长，推行保甲制度，强征劳工，协助日军掠夺本溪煤炭资源。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3b6da8aa42e94dabaae6d58319666d55','db46f683d7524311bc88d91f051f20d7',1931,'伪满本溪湖煤铁公司总务部长','汉奸买办，为日军管理本溪煤铁公司，残酷压榨中国矿工，导致大量劳工死亡。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('56051650fdad416f9918fe00eea630e2','c4a0ca855e8444afb1f8ccdad93f5e2b',1932,'伪满奉天省地方保安局局长','原东北军军官，投敌后负责奉天省（含本溪地区）保安事务，协助日军清乡，杀害抗日人员。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f9e96e5a92234f52b8cd3496beaa4f7c','15b0ffb0c3064aa4a57d4d84ac82b7fa',1932,'伪本溪湖煤铁公司理事长、伪满洲国参议','九一八事变后投靠日本，参与掠夺本溪湖煤铁资源，为日军侵华提供物资支持。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('313c16e22796449f84f0d0c7c082189f','21853206ad2b417598d1af0b4b3a4782',1931,'伪本溪湖维持会会长','九一八事变后组织伪维持会，协助日军接管本溪湖地区，维持殖民统治秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6a761372b3a54de581704ed4643f1013','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪本溪县县长','任伪县长期间推行保甲制度，配合日军清剿抗日武装，强征劳工。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f91865edf1eb461aaa737adb9ffcf557','3b830ddc2b084232aa2b66e70229bb3e',1933,'伪本溪县警务局局长','指挥伪警察配合日军讨伐抗日联军，镇压本溪地区抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9c4cd3d1ab05446d815405ec33f9f033','d0d70c2168a04d26a2557cd16c35b229',1936,'伪明山地区协和会会长','通过协和会进行奴化宣传，协助日军征集物资和劳工，监控民众思想。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('34ab8d70ed0c49b0ace914f340c2e2d5','701063bbacd742c2a1b3fcfcd7f898d6',1934,'伪本溪湖街街长','管理本溪湖街行政事务，配合日军实施经济管制和物资统制。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d64db6ac7559408a9fb528ec7960d011','f6520a01cada4b1da45cf1afd8553e4e',1932,'伪本溪县保安团团长','率领伪保安团参与日军对本溪周边抗日游击区的扫荡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5350b754a828499b8318c92f896c3771','7e6322f26aa745109615d95e728e953c',1935,'伪明山炭矿把头','充当日军监工，残酷压迫矿工，导致大量劳工死亡。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('83cc102f8f224fa184737d575ad18a27','a33e6385cb6c40c3a4c2153469b04453',1937,'伪本溪县协和会事务长','负责协和会日常事务，组织亲日宣传活动，协助日军征召劳工。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ef32e7e2f6434769893c143c21fa91bb','382d6cd4374f4825b23e811f101eb963',1935,'伪本溪湖警察署署长','参与抓捕抗日人员，破坏本溪地区中共地下组织。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6069e42ed7df4d9f8545d9a36f73091a','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满奉天省警察厅长','原奉系警察头目，投日后任伪满奉天省警察厅长，在辽宁各地包括本溪、桓仁建立特务网络，搜捕抗日分子，破坏地下组织。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a3e43b97b32d41af8c59d65ce4ef848c','21853206ad2b417598d1af0b4b3a4782',1932,'伪满桓仁县县长','桓仁本地人，投日后任伪桓仁县县长，推行保甲制度，强征劳工，配合日军对桓仁山区抗联根据地进行经济封锁和军事清剿。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('df30834807554432a239997ed92f19e4','09cfef10fb3c428b824bbf62c73eec97',1935,'伪满本溪湖市市长（本溪湖市为今本溪市前身）','任伪本溪湖市市长期间，积极为日军提供铁矿资源，强征中国劳工，镇压本溪湖煤矿工人罢工，并协助日军围剿本溪周边抗联部队。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a68ba7796e594b90b5eae07e3760613a','54a2238c4cd748b78806a15c959a5b49',1933,'伪满本溪县警务科科长','本溪县汉奸，负责指挥伪警察和特务，多次带队袭击抗联小分队，抓捕并杀害抗日群众，在桓仁与本溪交界地区活动频繁。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f8dfe8388f5b452b8f4f4101e0990d3c','7586e178e7504332969c36318cdc1806',1934,'伪满桓仁县警务科科长','桓仁县伪警察头目，参与制造多起屠杀事件，如“老秃顶子”惨案，协助日军放火烧山，围剿杨靖宇领导的抗联第一军。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aa28b9c62bf44849982959456283a069','d3eca6f12ad24ec8b7c8b8a44001e0a7',1936,'伪满本溪湖炭矿株式会社矿警队长','本溪湖煤矿汉奸，管理矿警队，残酷镇压矿工反抗，向日军提供抗联活动情报，并参与抓捕逃往桓仁山区的抗日矿工。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('efbe11370f184bcea35f63b56318af3b','0bb742c3fa5947b6826ad06890c95853',1937,'伪满桓仁县协和会会长','原地方士绅，投日后任桓仁县协和会会长，宣传“日满亲善”，组织汉奸团体，协助日军推行“归屯并户”，切断抗联与百姓联系。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d73990c4d5914b95bee8df0c637f1700','d7404e20b4894fc5b66a2d88c815fd9a',1932,'伪满本溪县保安队队长','本溪县地方武装头目，投日后任保安队长，多次配合日军扫荡本溪、桓仁交界山区，杀害抗联伤员和百姓，抢夺粮食。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9188e3570a1946b78f2b54b7f17fa222','e7d504c7480142aca4bdaf05bbeda27a',1938,'伪满桓仁县宣抚班班长','朝鲜族汉奸，为日军充当翻译和宣抚员，在桓仁农村诱骗群众“归顺”，出卖抗联秘密联络点，导致多名地下党员被捕。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('da29e5f19f744d069eb8a2a24ac41a88','fd17151c6e8846dd8bbd6482052e4fb2',1937,'伪满本溪湖市宪兵队翻译','本溪湖宪兵队汉奸翻译，参与刑讯逼供抗日志士，直接导致抗联侦察员牺牲，并协助日军在桓仁地区进行“大讨伐”。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('45891d22aae34273bf55503a654c6bcb','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满热河省省长、伪满第七军管区司令官','原东北军将领，九一八事变后投敌，曾任伪满热河省省长，参与镇压抗日武装，其部队曾在本溪、溪湖一带协助日军清剿抗联部队。；原东北军将领，九一八事变后投敌，在辽宁西部及热河地区协助日军镇压抗日武装，后任伪满高官，曾参与围剿辽西义勇军。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('56891c8f87744c40babc5fd8acc7cf87','09cfef10fb3c428b824bbf62c73eec97',1933,'伪满本溪县县长','任伪本溪县县长期间，推行日伪“保甲连坐”制度，强征劳工用于本溪湖铁矿和煤矿，配合日军“讨伐”溪湖山区抗联部队。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cbbd49fd481e4bf5a44e1e07cf4fb688','c4a0ca855e8444afb1f8ccdad93f5e2b',1931,'伪满本溪湖煤铁公司总务部长','负责本溪湖煤铁公司（溪湖地区）的劳工管理，残酷压榨中国矿工，大量劳工因虐待致死，并协助日军将矿工充当劳役修筑军事工事。','省部级/大军区级要员','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('42ff554cc848444f9d5ed0f1868576be','1c88a5dc4ffb4fa38fb4f7268277ceca',1933,'伪满本溪县保安队队长','率伪保安队配合日军在本溪、溪湖山区“扫荡”，杀害抗联伤员和百姓，烧毁村庄，是当地民愤极大的汉奸武装头目。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('df41d1fc9f9048548fed1acbe19a58c4','79b17193512846a1a5bde9f5df22c926',1931,'伪奉天省省长','九一八事变后投敌，任伪奉天省长，镇压抗日活动，为日军提供物资和情报。；原辽宁省政府主席，被日军俘获后变节，出任伪奉天省省长，推行奴化政策，为日军征粮派夫。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('96e6a9e6ceed41399cab55bd9b61a58f','84779a454ec74ec19985a1b53e006685',1932,'伪满奉天省省长（早期）','曾任伪奉天省长，协助日本建立殖民统治，参与经济掠夺。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5420b9544303448aaa334438251e2bd0','87b0aba74b9b4c5f8a515bd9270d23b4',1931,'伪满参议府议长、奉天地方维持会会长','九一八后组织地方维持会，协助日军控制沈阳，后任伪满高官。；九一八后组织沈阳地方维持会，为日军提供行政支持，后任伪满参议，鼓吹“日满亲善”。；九一八事变后组织奉天地方维持会，积极投靠日本，参与建立伪满政权，为日军在沈阳的殖民统治出谋划策。；清末举人，九一八后组织奉天地方维持会，积极投靠日本关东军，参与策划伪满洲国成立，任伪参议府议长。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1c3afe3ed3d840afa24dd0524ee21017','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满立法院院长、奉天市长','曾任伪奉天市长，参与制定伪满法律，镇压反满抗日人士。；原奉系官僚，九一八后投日，曾任伪奉天市长，参与建立伪满政权，其势力范围涉及锦州、葫芦岛地区，协助日军推行殖民统治。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5b58cf083c724dd0aec896127f046a0a','589ab27feed347c6944e6c001125dc02',NULL,'无','无','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f7baf0f80ad746ebace148750eee5ccc','875c22d678e24c21834a32caae69933c',1932,'伪满财政部总长、吉林省长（曾涉沈阳）','虽主政吉林，但长期在沈阳活动，参与伪满政权核心决策，协助日本殖民统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('acf8bc229b2545c9a0c320a75a98d164','1ba31d558b934fbd83a28a8c2b446022',1933,'伪满热河省长、军事顾问','原奉系将领，投日后在沈阳一带协助日军清剿抗日武装。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6caac52e026c47cc9f861dfcb1cbced9','1d67ff455ffc47b8addcc485beb0ca34',1932,'伪满第一军管区司令（驻沈阳）','率伪军驻守沈阳，参与镇压抗日义勇军和地下党。；原东北军旅长，叛变后任伪军司令，在沈阳及周边地区围剿抗日武装，屠杀抗日志士。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b8f01e7617b7428092d70ee0527276d1','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满沈阳警察厅厅长','负责沈阳治安，大肆逮捕抗日分子，配合日本宪兵队。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('442545d004804e0b93c74ca363521b54','21853206ad2b417598d1af0b4b3a4782',1933,'伪满奉天省警务厅厅长','在沈阳地区推行保甲制度，残害抗日群众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e4a6937e7aec45f5ae63e753cc05487c','0639407f8320412e86eada632a47d380',1932,'伪满沈阳县县长','强征粮税，为日军提供劳役，镇压当地抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8df3f5e8358540df801ad287d0452657','103ce81b67a940d4ab9979aae8824f91',1937,'伪满奉天市副市长','协助日伪推行经济统制，迫害民族工商业者。','市县厅局级','hanjian');
