INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1517e019f31541ebaa2b40974ca1ea9f','875c22d678e24c21834a32caae69933c',1931,'伪满洲国财政部总长','辽宁沈阳人（满族），参与策划伪满洲国成立，任伪财政总长，管理伪满财政，为日本掠夺东北资源服务。；清皇室后裔，原吉林军参谋长，九一八后率先投敌，参与建立伪满，在辽宁地区协助日军清剿抗日武装。；原吉林省政府委员，九一八后投日，积极策划吉林独立，任伪满财政要职。','无明确职位或一般帮凶','hanjian');
