INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('043a59d1bf5a4deebbfb639bf40d41ce','77a789268c6f47b4a617cdb9e41180bd',1931,'伪满国务总理大臣（曾任奉天省长）','原奉系将领，九一八事变后投敌，历任伪满军政要职，在沈阳地区协助日军清剿抗日武装，推行奴化教育。；虽为省级以上汉奸，但曾在辽阳、太子河地区部署伪军，配合日军扫荡抗日游击队，并推行奴化教育。；原奉系军阀，九一八后投敌，曾任伪奉天省省长，后任伪满国务总理，对包括鞍山、海城在内的辽宁地区负有全面殖民统治责任。','伪政权最高层/元首级','hanjian');
