INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4f084e2dd3eb47b59118bf24445cd4f9','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满洲国奉天省高等法院院长','虽主要活动于奉天（沈阳），但曾多次到盘锦、双台子地区审理“反满抗日”案件，判处多名抗日分子死刑','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('994ada87dbb244e08384c5a63d7ee6e2','84779a454ec74ec19985a1b53e006685',1931,'伪满洲国参议府参议、鞍山昭和制钢所顾问','曾参与策划辽南地区“自治”运动，在盘锦、双台子一带煽动地方势力归顺日本，为日军侵略提供情报','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('24dabd66ef55464eaed1dff846841d6e','589ab27feed347c6944e6c001125dc02',1934,'伪满洲国锦州省省长','管辖盘锦、双台子地区，积极推行“治安肃正”计划，组织伪警察和自卫团，多次袭击抗日游击队','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('128eb0db5c0f463aa984ef623b3cbacd','15b0ffb0c3064aa4a57d4d84ac82b7fa',1932,'伪满洲国司法部大臣','曾参与制定伪满法律，在盘锦、双台子地区设立“矫正院”，关押迫害抗日群众，实施奴化教育；原东北军法务官员，投日后任伪满司法大臣，制定镇压抗联的法律。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('da9cf8d572854f4d878b3fced1da68b7','5cce8fcbbcc043c2820499553d6999c1',1938,'伪满洲国盘山县警务科科长','直接负责盘锦、双台子地区治安，抓捕抗日地下党员，严刑逼供，曾一次逮捕并杀害多名抗日群众','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ae19dddb4f954946a548a9cae5ccdca8','3cd55e29febc489d9f9a7f2f88db31bb',1940,'伪满洲国双台子警察署署长','在双台子地区设立多个检查站，盘查过往行人，搜捕抗日分子，并协助日军强征劳工','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e9ce229d2ba642d783554ef1b8b8c4c4','41502657c6b84465aa2ff94e620ed234',1937,'伪满洲国民生部大臣','曾到盘锦、双台子地区推行“国民储蓄”和“勤劳奉仕”制度，强迫百姓无偿劳动，为日军服务','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2179c03d22cb44f7adb97d8f3b3bf729','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洲国热河省省长、伪满军上将','原为东北军将领，九一八事变后投敌，曾任伪满热河省省长，协助日军镇压抗日武装，在辽宁西部及盘锦、大洼一带活动，参与围剿义勇军和抗联部队。；原东北军洮辽镇守使，九一八事变后投敌，率伪军配合日军进攻黑龙江，参与江桥战役对抗马占山抗日部队，后任伪满洲国热河省省长等职。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('adc6259312dc45008ae7eae1525de590','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满洲国奉天省省长、伪满军上将','原东北军旅长，叛变投日后任伪奉天省省长，管辖范围包括今盘锦、大洼地区，积极推行日伪殖民政策，强征劳工，镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('71ce60c777e74a088cd891e330f434cb','589ab27feed347c6944e6c001125dc02',1932,'伪满洲国锦州省省长（后改任）','原为地方士绅，投靠日军后任伪锦州省省长，其辖区涵盖盘锦、大洼一带，协助日军建立保甲制度，搜刮民财，迫害抗日家属。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('439aa841a8094905bcddc9b719261d52','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满洲国立法院院长、伪奉天市市长','早年留学日本，九一八后积极参与伪满建国，曾任伪奉天市市长，对盘锦、大洼地区日伪统治有间接管辖，推动奴化教育和经济掠夺。；辽宁沈阳人，九一八事变后投敌，历任伪奉天市市长、伪立法院院长等职，参与伪满政权立法与地方统治。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('55383cb16db1409d95d41035b62b73cf','79b17193512846a1a5bde9f5df22c926',1931,'伪满洲国奉天省省长（前期）','原东北军参谋长，投敌后任伪奉天省省长，在盘锦、大洼地区设立日伪警察机构，抓捕抗日志士，强征土地。；原奉天省主席，投日后任伪省长，在营口地区推行“归屯并户”，制造无人区，导致大量平民死亡。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a785c90dc4b843d9b0c90fb8ba163ab3','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满洲国锦州省警务厅厅长','原为土匪头目，投日后任伪锦州省警务厅厅长，直接管辖盘锦、大洼地区警察，率伪警配合日军扫荡，杀害无辜百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('926097d631354a4abe611c50b4050126','21853206ad2b417598d1af0b4b3a4782',1932,'伪满洲国盘山县县长（今盘锦市大洼区一带）','投靠日军后任伪盘山县县长，在任期间强制推行“归屯并户”，焚烧民房，制造无人区，并强征农民充当苦力。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('eb6bc6a0226541e7b333aabe01e70012','7ca60279616445fcaa58c2399291ebcb',NULL,'无','不列入，因未投敌。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a85d9b805cd047d39bb34df429c21eeb','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满奉天省警务厅厅长、伪满警察头目','盘山县人，曾任伪满奉天省警务厅厅长，在盘锦地区推行保甲制度，抓捕抗日地下人员，参与“讨伐”抗日联军。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('601c746257304074931c04c6e60eb26a','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满立法院院长、伪满法制局总裁','盘山籍（一说辽宁），九一八后积极投靠日本，参与伪满政权筹建，制定伪满法律，为日本殖民统治提供法理依据。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3ea63a7bff3e44a2a5eeed23c2286d8a','caae33d173854bf0a1b2b4f0db4f585a',1934,'伪满锦州省省长','伪满锦州省辖区包括盘山部分地区，任内配合日军“治安肃正”，在盘山一带强征劳工、建立伪警察机构。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7d066c2ad94a4afdbebc0a6e40c247fc','589ab27feed347c6944e6c001125dc02',1932,'伪满盘山县县长（首任）','盘山县人，九一八后投敌，任伪满盘山县县长，组织伪县公署，协助日军收缴民间武器，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('61ed94127dd64a3c9de4d5ce25faf791','f5e2125398034b06aaf31788308b6073',1937,'伪满盘山县县长','继任伪满盘山县县长，推行“保甲连坐”制度，强征粮食和劳工，为日军提供物资支持。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2f8f767be31a458c9ef5ead834dcfaea','3cd55e29febc489d9f9a7f2f88db31bb',1933,'伪满盘山县警务科科长','盘山本地人，任伪满盘山县警务科科长，亲自带队抓捕抗日义勇军家属，刑讯逼供，杀害多名抗日志士。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0d2a057864c04a72a959d85433317fbf','7ca60279616445fcaa58c2399291ebcb',1938,'伪满盘山县协和会会长','盘山士绅，投靠日伪后任协和会会长，宣传“日满亲善”，组织青少年奴化训练，破坏抗日地下组织。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f0f7864cf7b5458c9e03948088de6f4a','6c5f2811c77d4f39b1ddb522f78f5e25',1932,'伪满盘山县保安队队长','盘山土匪出身，被日伪收编后任保安队队长，在盘山、大洼一带袭击抗日游击队，烧毁村庄。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('031673a2c090404099edff271047617e','a2c03b81e5f2412bb86f5d5599c1687b',1935,'伪满盘山县田赋局局长','盘山籍，任伪满田赋局局长，残酷征收“出荷粮”，导致当地农民饿死无数，并将粮食供给日军。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d71c873ddd9744758c43453316d260b3','cd8e5ab701f04770ad28171753ae1ceb',1936,'伪满盘山县教育长','推行奴化教育，强制学生学日语，删除中国历史教材，检举有抗日思想的教师。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8e37014792f14d28906085945f0cdad1','6a89fad0f513410089f90e82d3e7934f',1937,'伪满盘山县司法科审判官','盘山本地汉奸，在伪法庭上以“反满抗日”罪名判处多名爱国人士死刑或重刑。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e5d7590ce26e49c48442b80db13b708f','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满营口市市长','任伪满营口市长期间，推行日伪殖民政策，协助日军镇压抗日活动，强征劳工，控制港口经济为日军服务。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a75e3c5cacf14aacb99b8126e28beab0','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满热河省省长（曾驻营口活动）','原东北军将领，九一八后投敌，在营口及辽南地区协助日军清剿义勇军，后任伪满省长，参与“讨伐”抗日武装。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('79ea78be775d41cfb1dcd742eb28933f','1d67ff455ffc47b8addcc485beb0ca34',1932,'伪满第一军管区司令（辖营口）','原奉军旅长，叛国投日，在营口、海城等地指挥伪军围剿抗日义勇军，残害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6d8aeab0263544188ea4549e30667081','21853206ad2b417598d1af0b4b3a4782',1933,'伪满营口警察局局长','效忠日寇，在营口市区及周边大肆搜捕抗日地下人员，破坏抗日组织，参与“治安肃正”行动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('182715ee2630434f97b47b6a54d7394d','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满奉天省高等法院院长（涉及营口案件）','汉奸法律人物，曾参与审判营口地区抗日志士，为日伪司法镇压提供合法化工具。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7fcdf5e8549e460daa414707b45d6c46','1a8847af165d4d648f62d949fad6cb5a',1931,'伪满营口商会会长','充当日本经济侵略代理人，强制商户为日军提供物资，协助日伪掠夺营口港资源，迫害爱国商人。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a60b13d2a5914fd5a9ec639cda58b59c','589ab27feed347c6944e6c001125dc02',1931,'伪满营口地方维持会成员','九一八后参与组织营口地方维持会，迎接日军占领，协助建立伪政权，为日军征粮派款。','基层维持会/地方自治头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('147c1f6813e147e089e03e6dc51ce377','3cd55e29febc489d9f9a7f2f88db31bb',1934,'伪满营口县县长','在营口县推行日伪“保甲制度”，强征民夫修筑军事工事，配合日军“清乡”屠杀抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('85175083be92428d8df2ffedd25de172','77a789268c6f47b4a617cdb9e41180bd',1935,'伪满国务总理大臣（曾巡视营口）','作为伪满最高汉奸之一，多次到营口等地督导“治安强化运动”，推动奴化教育，支持日军经济掠夺。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dca0a5f7f46c441b960a418e3a2ed51e','79b17193512846a1a5bde9f5df22c926',1931,'伪满奉天省省长（辖营口）','原辽宁省主席，投敌后任伪奉天省长，对营口地区抗日武装进行残酷镇压，签订卖国协定。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7f1086d5ec7f4ff390467a5b862623f2','1d67ff455ffc47b8addcc485beb0ca34',1932,'伪满洲国奉天省省长、治安部大臣','原东北军将领，九一八事变后投敌，任伪奉天省省长，积极推行日伪殖民统治，镇压抗日力量，后升任伪满洲国治安部大臣。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c69b7ea1f627481a8ba6525be52b4dfd','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满洲国奉天省警务厅厅长','在营口、大石桥地区任伪警务要职，组织伪警察配合日军“讨伐”抗日武装，抓捕抗日志士，残害百姓。；原辽宁地区警察头目，投日后任伪警务厅长，在辽阳、弓长岭地区组织伪警察和特务，搜捕抗日分子，破坏地下抗日组织。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5a22d6149f444c5b862651d7213e788f','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洲国热河省省长、伪满军事部大臣','原奉系军阀，九一八后公开投敌，虽主要活动于热河，但其势力曾涉及辽南地区，协助日军镇压抗日义勇军。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('37c59777ba354699a07990c229fc1c8c','875c22d678e24c21834a32caae69933c',1931,'伪满洲国财政部大臣、宫内府大臣','原吉林副司令长官，投敌后参与伪满政权，其经济政策影响辽南地区，掠夺资源。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dd4ab3e710fc42678d43d35fe9c314d5','379c345f5d8b4814a34c8ea2d01b70a8',1931,'伪满洲国“安国军”司令','日本间谍，曾活动于辽南地区，参与策划伪满成立，协助日军镇压抗日力量。；日本间谍，曾以“安国军”名义在辽宁、热河一带活动，参与对兴城、绥中抗日义勇军的诱降和镇压，协助日军搜集情报。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8d037fc90f90412f8ec2d52e615b05dc','8fdb75c63ff4478aa86d74431b472cde',1932,'伪满洲国奉天省警务厅督察长','在营口、大石桥地区任伪警职务，直接参与抓捕抗日人员，制造多起惨案。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3dc1ecb64b52421d8967846d2166b8d0','589ab27feed347c6944e6c001125dc02',1932,'伪满洲国奉天省实业厅厅长','投日后负责奉天省（含营口）经济掠夺，强征劳工，控制盐业和矿产。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9eaa428790084193abf62c2b1a3f41cd','caae33d173854bf0a1b2b4f0db4f585a',1932,'伪满洲国奉天省民政厅厅长','在营口地区推行“归屯并户”，制造无人区，协助日军清剿抗日武装。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('954e32731a0e41449bc3c46b02591f9f','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满盖平县县长','任伪满盖平县县长期间，积极推行日伪殖民政策，强征劳工，镇压抗日活动，协助日军清乡并收缴民间武器。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('376e496646ab40448b8988182af9ab2f','21853206ad2b417598d1af0b4b3a4782',1933,'伪满盖平县警务科科长','指挥伪警察配合日军围剿抗日武装，多次参与抓捕和杀害抗日志士，并强迫百姓修建警备道路和碉堡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4b1ae90b5e4949b8865a68bfbd6c0fc0','1ba31d558b934fbd83a28a8c2b446022',1934,'伪满盖平县协和会会长','组织协和会宣传奴化思想，推行“王道乐土”谎言，强迫民众参加“勤劳奉仕”，为日军提供情报和物资。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1b1198f6212e4795a550392a127739ea','a2c03b81e5f2412bb86f5d5599c1687b',1935,'伪满盖平县保安队队长','率保安队多次袭击抗日游击队，烧毁村庄，杀害无辜百姓，并参与“集家并屯”制造无人区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('14eb2dd829c04044a54ae5e0df9c1da8','3cd55e29febc489d9f9a7f2f88db31bb',1937,'伪满营口市市长','在营口市推行日伪经济统制，强征粮食和金属，组织“献纳飞机”运动，并镇压工人罢工和学生反日运动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3d4fb632b57440c3b0acc51ab0da493d','54d9b3db82044e458654314b311361c6',1938,'伪满营口市警察局局长','指挥警察特务搜捕抗日地下组织，破坏中共营口支部，严刑拷打并杀害多名爱国人士。','市县厅局级','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('01ec02c2b7754779927437f57c69e5bd','13627111d7bb4e9089e2e7f315d63275',1939,'伪满营口市协和会事务长','负责协和会日常活动，组织青少年进行军事训练，宣传“日满亲善”，并监视居民言行。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('48509a1e335b4a8a9271d56ae1136260','759cfb5f46624562bc0d114d5292cbca',1936,'伪满盖平县教育局长','强制推行日语教育，删改历史教材，灌输奴化思想，并检举有抗日倾向的教师和学生。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a5b51d149bed400485709a8576f84835','6fee2b329ee54681a24b19e7abf091b7',1940,'伪满营口港务局局长','配合日军控制营口港，为侵华日军运输军需物资，并强迫中国劳工从事繁重装卸劳动，造成多人死亡。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('034057b55fcd4eb193add6c391d58566','b8f5150658fd47f0a48c92aacb628181',1941,'伪满盖平县自卫团团长','组织自卫团协助日军巡逻，抓捕抗日嫌疑分子，并参与对抗日家属的迫害和勒索。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7be5cf2c796943e1b6f3af9d71925eb8','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满洲国奉天省警备司令、伪满军政部大臣','九一八事变后投敌，组织伪军配合日军侵占辽宁各地，长期在伪满军政系统任职，参与镇压东北抗日武装。；九一八事变后投敌，组织伪军配合日军进攻辽宁各地，长期在奉天、营口一带镇压抗日武装，后任伪满军政部大臣，是辽宁地区代表性汉奸之一。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2b45af30fbf941e6995e7bfdce3277c1','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洲国洮辽镇守使、伪满热河省警备司令','九一八事变后率先投敌，率伪军配合日军进攻辽宁、热河等地，参与镇压抗日义勇军。；原东北军将领，九一八后投敌，率伪军配合日军侵占辽宁、热河等地，在辽南、营口周边参与镇压抗日义勇军。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c6595e341a5d4a09a8442c4c61c54911','84779a454ec74ec19985a1b53e006685',1931,'伪满洲国监察院院长、伪满参议府参议','辽宁籍亲日政客，九一八事变后积极协助日军建立伪满政权，在辽宁地区为日军侵略张目。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('31d7058bad58432aac89ad79d5e36042','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满洲国立法院院长、伪满奉天市市长','辽宁籍汉奸，参与伪满建国活动，在奉天（今沈阳）及辽宁地区推行殖民统治。；辽宁籍汉奸，九一八后投靠日本，参与伪满建国活动，曾任伪奉天市市长，在辽宁地区推行殖民统治。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b907a6e8358d4a5aa1bea2043abdbad3','87b0aba74b9b4c5f8a515bd9270d23b4',1931,'伪满洲国参议府参议、伪满奉天省省长','辽宁辽阳人，九一八事变后组织维持会，协助日军维持辽宁地方秩序，后任伪满高官。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fdff737dc87f4535be882971c8d78279','8fdb75c63ff4478aa86d74431b472cde',1931,'伪满洲国奉天省警备司令、伪军头目','辽宁籍汉奸，九一八事变后投敌，在营口、海城一带组织伪军，配合日军镇压抗日力量。；原东北军军官，九一八后投敌，在辽宁地区组织伪军，配合日军进攻抗日武装，活动范围涉及营口周边。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('62e24d1cb89d4572963830034cd4f479','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满洲国营口警察厅厅长、伪满奉天省警务厅厅长','在营口地区长期担任伪警察头目，镇压抗日群众，推行保甲连坐，为日军搜集情报。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('21f2acc2ad1547148d11f768fa2bc614','5e3c03e59a9d4a4f81ce0c0f481fb548',1932,'伪满洲国营口县县长、伪满营口市市长','在营口地区任职期间，推行伪满法令，协助日军征粮征丁，压迫当地民众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c937eba79d0f4689b9c62541773bfc93','a6b18e7d4833441c9d15b3ffbbbc345a',1931,'伪满洲国营口维持会会长','九一八事变后在营口组织维持会，迎接日军进城，协助建立伪政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0b19f5aae2eb41a8bed07cbff4cd7b0c','eb688993f9ee49a7bbacda2253de406a',1932,'伪满洲国奉天省警务厅厅长、伪满营口警察局局长','在辽宁及营口地区担任伪警察要职，参与镇压抗日地下组织，抓捕爱国人士。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dc57bdef0c564b25b6f24abd7505addd','2a935b424b574114afe806c8132b82bc',1932,'伪满洲国营口商工会会长','营口商界附逆者，为日军筹集物资，协助经济统制，压迫民族工商业。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a03f2f3b36d44c4182ffcb2e2292817b','84779a454ec74ec19985a1b53e006685',1931,'伪满洲国监察院院长、伪满协和会中央本部委员','辽宁籍亲日派，九一八后积极协助日军建立伪满政权，参与策划东北各省伪政权组建，对辽宁地区附逆势力有重要影响。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4c24442d242c4d71bc7ab93c6873f39c','79b17193512846a1a5bde9f5df22c926',1931,'伪满洲国民政部大臣、伪满奉天省省长','原辽宁省政府主席，九一八后被俘投敌，历任伪奉天省省长、伪满民政部大臣，在辽宁地区协助日军维持殖民秩序。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d019fd79acf8441b8d72ff3189b57130','87b0aba74b9b4c5f8a515bd9270d23b4',1931,'伪满洲国参议府参议、伪满奉天省维持会会长','辽宁辽阳人，九一八后组织奉天维持会，协助日军维持地方秩序，后任伪满参议府参议，是辽宁地区较早附逆的地方士绅。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('273759d445dc4710b3fc3169dde5337c','c9dffc071fec4ce58fe1d611f26c28da',1931,'伪满洲国营口地区伪警察头目、伪保甲长','在营口地区担任伪警察及保甲职务，协助日军征粮、抓丁、镇压抗日群众，是营口本地附逆势力的代表。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b858b49695614734b3e62c0679089335','177c17b9b440453fa41ed47b9ebbd502',1931,'伪满洲国营口地区维持会成员','在营口地区参与维持会活动，协助日军维持地方治安、搜集情报、迫害抗日人员。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('533b9c1d848f41ffb2facdc2b552c6a3','5762ca5794044116b48fdb68f6cd67b5',1931,'伪满洲国营口县伪县长','在营口县任伪县长期间，推行日军殖民政策，征粮征工，镇压抗日活动，对老边一带亦有管辖影响。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5e1dda964c764863a8b594f3966dc3ed','2a935b424b574114afe806c8132b82bc',1931,'伪满洲国营口地区伪教育会会长','在营口教育界推行奴化教育，协助日军宣传“日满亲善”，毒害当地青少年，是文化教育领域附逆者。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5fb76db8b403474099c174636fb9b916','80825e93c5dd408297e82f20484a17c4',1931,'伪满洲国营口地区伪商会会长','在营口商界为日军筹款筹粮，协助经济掠夺，压迫当地商户，是经济领域附逆者。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9b44d5f2f303408f81d9454b32fe7e97','c9dffc071fec4ce58fe1d611f26c28da',1931,'伪满营口市警察局局长','在营口地区积极执行日伪当局命令，镇压抗日活动，协助日军搜捕抗日志士，强征劳工，为日军提供情报。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('863bbbb452764a3798ad2f24bcfba7fb','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满热河省省长（曾活动于营口西市一带）','原东北军将领，后投敌叛国，在营口及周边地区协助日军清乡，参与“讨伐”抗日武装，推行奴化教育。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ab980ba22c8b4f9fb1d0f27a9bc4bb65','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满奉天省警备司令（曾管辖营口地区）','原东北军旅长，投日后在营口、西市一带组织伪军，配合日军“扫荡”，残害抗日军民，强征粮食。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0c3f8cf803284acf809ec10ed4e02087','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满立法院院长（祖籍营口，曾回营口活动）','积极鼓吹“满洲独立”，在营口西市等地发表亲日演讲，协助日本关东军建立伪政权，参与制定奴化政策。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('43c923069d4d44f297e8080c70a8b5bd','1a8847af165d4d648f62d949fad6cb5a',1931,'伪满营口市商会会长','在营口西市地区为日军筹集军饷，强迫商户捐献物资，向日伪当局举报抗日商人，协助经济统制。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7782a17bb81c4f319a0fb21072f468d7','21853206ad2b417598d1af0b4b3a4782',1931,'伪满营口县保安队队长','带领保安队在西市一带抓捕抗日地下工作者，参与屠杀无辜百姓，为日军提供劳力和情报。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('231e568fcb6b4d7ca6209580b72c38d2','1d67ff455ffc47b8addcc485beb0ca34',1932,'伪满洲国奉天省省长','曾任东北军将领，后投靠日本，任伪奉天省省长，积极推行日伪殖民政策，镇压抗日力量，其管辖范围包括营口地区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1ef43cd27b324cd0a9800d29250ef9c2','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满洲国营口市市长','原营口地方士绅，日军占领营口后出任伪市长，协助日军维持统治，强征劳工，为日军提供物资支持。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('eb5a3f2b7ee843f5bce228ac3b9ef307','1ba31d558b934fbd83a28a8c2b446022',1933,'伪满洲国热河省省长（曾驻营口）','原东北军将领，九一八后投敌，曾任伪热河省长，期间在营口、鲅鱼圈一带协助日军清剿抗日武装，残害百姓。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3b074ec4924c4bedbe03b90a93e72df2','21853206ad2b417598d1af0b4b3a4782',1932,'伪满洲国营口地区保安队队长','原营口警察，后任伪保安队长，多次配合日军围剿抗日游击队，在鲅鱼圈沿海地区抓捕抗日志士，强征民夫。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e84254563403470f900669be055100ab','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满洲国奉天省高等法院院长（涉及营口案件）','原中国律师，投日后任伪法院院长，在营口地区审判抗日人士，以“反满抗日”罪名判处多人死刑或重刑。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dc2d3787cb31423d9b74475345dee52d','84779a454ec74ec19985a1b53e006685',1932,'伪满洲国参议府参议（曾活动于营口）','原奉系官僚，投日后任伪参议，多次到营口、鲅鱼圈视察，推动日伪“治安肃正”计划，协助日军建立保甲制度。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('678e4aec8bb54fe8b4f690290acc098c','77a789268c6f47b4a617cdb9e41180bd',1935,'伪满洲国国务总理大臣（名义管辖营口）','原东北军将领，后为伪满最高行政长官，其政策直接作用于营口地区，支持日军经济掠夺，强征粮食和劳工。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5586c67f985946939055fb535e339076','5cce8fcbbcc043c2820499553d6999c1',1932,'伪满洲国营口市警察局局长','原营口警察，投日后任伪警察局长，协助日军特务机关，在鲅鱼圈港口监控往来船只，逮捕抗日地下工作者。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9c7312dd3f1245dbaa1138059ea62dc0','589ab27feed347c6944e6c001125dc02',1933,'伪满洲国营口港务局局长','原营口港职员，投日后管理鲅鱼圈港区，为日军运输军需物资，强迫中国工人无偿劳动，克扣口粮。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8bbb791e310b45c1b86242a4d610a61c','589ab27feed347c6944e6c001125dc02',1934,'伪满锦州省省长','原奉系官员，伪满时期任锦州省省长（辖区含今葫芦岛地区），协助日伪推行“治安肃正”和奴化教育。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0d267088e6934465a17f4ec58800f384','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满立法院院长、伪满奉天市长','原奉系法律人士，投日后任伪奉天市长，参与建立伪满政权，协助日军在辽宁地区进行殖民统治。；积极参与伪满政权建立，在辽宁多地活动，为日军侵华提供法律和行政支持，涉及锦州地区伪政权建设。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('282c5ae1fbd6437999658df5410e1dcd','b8f5150658fd47f0a48c92aacb628181',1932,'伪满黑龙江省省长（短暂投敌后反正）','曾一度投降日军任伪职，但不久反正抗日，其投敌期间未在葫芦岛地区有具体活动，但作为东北汉奸名单常被提及。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0ab45ed5c2db4a9593ef212fd51bafb5','3b74f508628f475a8777ffb7e38a48a0',1931,'伪满奉天省实业厅长、伪满经济部大臣','原奉系商人，投日后任伪奉天省实业厅长，协助日本掠夺辽宁资源，包括葫芦岛地区的矿产和农产品。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e2eb2b82bee64a2ca22bb4fa93962e5f','360451ccb61f491bafdc1b28af3c6799',1935,'伪满锦州省次长（实际掌权者）','日本关东军指派日籍官员，但作为伪满官员，在锦州省（含葫芦岛）推行“集家并村”和“治安肃正”，残害百姓。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1a52197ee67a417c84c6609b71f056bc','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满锦州省警务厅长','原奉系警察头目，投日后任伪锦州省警务厅长，指挥伪警察在葫芦岛地区抓捕抗日志士，镇压民众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ce63026a5cf440aaa56d4c1f8c0ee202','21853206ad2b417598d1af0b4b3a4782',1932,'伪满锦西县（今葫芦岛市连山区）县长','投日后任伪锦西县长，协助日军建立伪政权，强征劳工，参与“讨伐”抗日义勇军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bff0d6a6f85f457d9f589f6b3a2221c1','5e3c03e59a9d4a4f81ce0c0f481fb548',1933,'伪满绥中县（今属葫芦岛市）县长','投日后任伪绥中县长，推行日伪奴化教育，强征粮食，镇压当地抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e2d9bb19c9804495b4e4bdd38026d997','7ca60279616445fcaa58c2399291ebcb',1931,'伪满兴城（今属葫芦岛市）维持会长','九一八后短暂组织地方维持会投靠日军，后因内部矛盾被撤换，但初期协助日军稳定占领秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7e876df884be4d569a299b6ef5930b65','3e5d5d23a2cb44e8a4cca512d1eba576',1935,'伪满锦州省兴城县协和会会长','利用家族影响，在兴城（今葫芦岛）组织协和会，宣传“日满亲善”，协助日军进行思想控制。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('773ac920372b4f1cbd105fd32b195b0f','922b606d45c647e8a82755373b3d3e91',1934,'伪满葫芦岛港务局局长','投日后任伪葫芦岛港务局长，协助日军扩建港口，用于军事运输和掠夺资源。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b189b6a8c56b46a8b3387fc16bcaf0a0','89a5274e857d484894f7c702bf2f7f72',1933,'伪满锦西县保安队长','组织伪保安队，配合日军在葫芦岛地区进行“扫荡”，杀害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1c64cd6958cc437b83ceb224759afe50','6c5f2811c77d4f39b1ddb522f78f5e25',1932,'伪满绥中县警察署长','指挥伪警察在绥中（今葫芦岛）抓捕抗日地下党员，破坏抗日组织。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1efd0971c7f142abba683dbe059b12fa','7958ce7509144211b5557ad8ed2dda70',1936,'伪满兴城县教育局长','推行日本奴化教育，强制学校教授日语，删除中国历史内容，在葫芦岛地区毒害青少年。','市县厅局级','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7302d989bc444e5ca9b3ed352856cb93','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满洲国奉天省警备司令官、第一军管区司令','原东北军旅长，1932年投降日军，在辽宁地区（包括兴城、葫芦岛一带）指挥伪军围剿抗日义勇军，制造多起屠杀事件。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('102f5b9a00504598a7bcd70c2be34117','21853206ad2b417598d1af0b4b3a4782',1934,'伪满洲国锦州省省长','原锦州地区士绅，投靠日军后任伪锦州省省长，管辖范围包括葫芦岛、兴城，推行“治安肃正”，组织伪自卫团镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e86639d15a6e47d994ebb9fcf0a622ac','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满洲国立法院院长（曾任奉天市长）','原奉系法律人士，九一八后积极参与伪满洲国建立，在辽宁地区协助日军建立殖民政权，参与制定镇压抗日法令，影响波及兴城等地。；积极参与伪满政权建立，在辽宁地区（含锦州辖区）为日本关东军提供法律与行政支持，协助建立伪警察和保甲制度。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('969e71d5db96440ba51a53339d3e008f','1a8847af165d4d648f62d949fad6cb5a',1932,'伪满洲国锦州省警务厅长','原锦州警察头目，投日后任伪锦州省警务厅长，在葫芦岛、兴城一带指挥伪警“清乡”，杀害抗日军民，掠夺物资。；在锦州省（含绥中）主持伪警察机构，抓捕抗日志士，协助日军“讨伐”辽西抗日武装。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4819ae9368594a98b0449974469c7ba4','875c22d678e24c21834a32caae69933c',1931,'伪满洲国财政部总长兼吉林省长','原吉林军参谋长，投敌后虽主政吉林，但曾参与策划对辽宁西部（包括兴城、葫芦岛）的军事“讨伐”，提供伪军支援。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aa0f8f2d328d48c7b1c1ca846a4a2431','811fe999084946d8baee44410886b3e6',1931,'伪满洲国“奉天地区”日籍顾问兼伪军头目','日本浪人，加入伪满军队，在辽宁锦州、兴城一带指挥伪军“讨伐”抗日武装，手段残忍，制造多起血案。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a265db8c57e4443ebcdf829c44ae24a6','f7fe928e685d43deba27b9df0ce3f4a2',1932,'伪满洲国锦州省兴城县县长','原兴城地方士绅，投日后任伪兴城县县长，强征粮税，组织伪县公署配合日军“扫荡”，迫害抗日家属。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2486eb82b31645f3a47fa889fc45214c','3cd55e29febc489d9f9a7f2f88db31bb',1933,'伪满洲国锦州省绥中县县长（曾辖兴城周边）','投靠日军后任绥中县长，在兴城、绥中交界地带协助日军建立“无人区”，强制村民迁移，烧毁房屋。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('793b1e6b6f8d411b8a812f7e551256f8','3a9e402192aa460fb51a927d874bb93e',1932,'伪满洲国锦州省警察讨伐队队长','原土匪头目，投日后任伪警察讨伐队长，在兴城、葫芦岛山区多次袭击抗日义勇军，杀害俘虏。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e6e4ee08511341e0bac2f10b39b338d0','c8f75b7e07bb4502b11b2decde145228',1933,'伪满洲国兴城地区自卫团团长','兴城本地地主，组织伪自卫团，为日军提供情报，参与抓捕抗日地下人员，强征壮丁。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a94ef7fa2d1e4c1f800e310b22c3c77e','8fdb75c63ff4478aa86d74431b472cde',1935,'伪满洲国“冀东防共自治政府”顾问（曾活动于辽西）','原军阀，投日后在辽西（包括兴城、葫芦岛）协助日军策反地方武装，组织伪军，破坏抗日统一战线。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3bbdbe842e1546fb88d6351625c8829c','c962700c3422426b946336b59832e9d0',1932,'伪满洲国锦州省保安队司令','原东北军连长，投敌后任伪保安队司令，在兴城、葫芦岛沿海地区巡逻，截击抗日物资运输，参与“清乡”。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ab1716ffd27a40d5863ecea6979f4a0f','f724b4f7519147ba93e302a475b2a225',1931,'伪满洲国奉天市市长（曾影响辽西）','原奉系官员，投日后任伪奉天市长，其伪政权政策覆盖辽宁全省，包括兴城地区，推行奴化教育和经济掠夺。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0693c44978df4dd08df1c9917be6a528','e409ef959281461b91e8ce1eef37d186',1931,'伪满洲国军政部总长（曾任东北边防军参谋长）','原东北军高级将领，九一八后投敌，参与策划对辽宁西部抗日义勇军的围剿，其伪军部队曾在兴城、绥中作战。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3c047f8401944c64928ae202d57d0e72','5cce8fcbbcc043c2820499553d6999c1',1932,'伪满洲国锦州省兴城县警务科长','投日后任兴城伪警务科长，直接指挥伪警察抓捕抗日群众，刑讯逼供，协助日军建立“爱护村”监控体系。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6f9fce904cc243f392f14f4ee74f688a','a984ebfabbf64a5b8e1dfef2d68daa53',1934,'伪满锦州省省长','原东北军旅长，后投靠日本，任伪锦州省省长，管辖包括葫芦岛、南票地区，积极推行日伪殖民政策，镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('04be063d38744cfebe30a1a6414760a5','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满奉天省高等法院院长','原奉系司法官员，投日后参与伪满司法体系，曾参与处理涉及葫芦岛、南票地区的抗日案件，迫害爱国人士。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dbbbf29b11224c81bdb772d494cf4544','589ab27feed347c6944e6c001125dc02',1933,'伪满锦州省警务厅长','原锦州地区警察头目，投日后任伪警务厅长，在葫芦岛、南票等地建立特务网络，抓捕抗日志士。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aaff995ecb3443c7bf0a09559d1a8aaa','21853206ad2b417598d1af0b4b3a4782',1935,'伪满南票煤矿矿长','原南票煤矿中方管理人员，投日后任伪矿长，强迫矿工为日军采煤，虐待劳工，造成大量矿工死亡。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f04bf588ec744ee584781dcf1e7a9059','875c22d678e24c21834a32caae69933c',1932,'伪满财政部总长','原吉林省政府委员，投日后任伪满财政总长，参与制定对辽西地区经济掠夺政策，包括南票煤矿的垄断经营。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('871b656e6cb9425bbc9eb8619878567c','b8f5150658fd47f0a48c92aacb628181',1932,'伪满黑龙江省长（短暂投敌）','一度投日任伪黑龙江省长，但未实际管辖辽宁地区，后反正抗日，与南票无直接关联，但列入以备参考。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('011c8e51f5ca4c2da9ee79e1cc4c7a09','3b74f508628f475a8777ffb7e38a48a0',1933,'伪满热河省警务厅长','原热河省警察头目，投日后在朝阳、南票一带组织伪警察，协助日军“清乡”，残害百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('04004e22203046599f665e6d411b732a','c9dffc071fec4ce58fe1d611f26c28da',1933,'伪满锦州地区保安司令','原地方民团头目，投日后任伪保安司令，在葫芦岛、南票一带围剿抗日游击队，烧杀抢掠。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ea5cc816e0254de495012bd7a9082996','177c17b9b440453fa41ed47b9ebbd502',1933,'伪满热河省游击司令','土匪出身，投日后任伪游击司令，活动于辽西山地，多次袭击南票抗日武装，为日军充当鹰犬。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c4054f73a4c941669fc664cfdfb37811','3f37dc5f28fd4441bdca3df489255cc2',1936,'伪满南票矿区警察署长','原矿区保安，投日后任伪警察署长，镇压矿工罢工，抓捕抗日地下工作者，罪行累累。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b8046f3fe3fc4f00ba08fcb502f845fe','a984ebfabbf64a5b8e1dfef2d68daa53',1934,'伪满洲国热河省警务厅厅长','原东北军军官，投日后负责热河省（含建昌）警务，多次组织清乡，抓捕抗日志士，配合日军“讨伐”活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a9c3c7e871d14951ad2de492ea919d59','3a9e402192aa460fb51a927d874bb93e',1933,'伪建昌县县长','伪满初期任建昌县县长，推行保甲制度，强征劳工，为日军提供粮食和情报，镇压当地抗日民众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a3804e5ff48342cfa149bb746dd346e7','bf1d7395d1cf4668ba4615df7bd042c7',1935,'伪建昌县警察署署长','长期担任建昌伪警察头目，直接参与抓捕抗日地下工作者，破坏抗日组织，多次带队“扫荡”农村抗日据点。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fab325c2d1844110be67420b3697fb6f','89a5274e857d484894f7c702bf2f7f72',1938,'伪建昌县协和会会长','负责建昌地区协和会宣传，推行奴化教育，组织“勤劳奉仕”，强迫民众为日军修筑工事，搜集抗日情报。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d9889c8b7e714a01b783745809d3399f','1b0d93051c8343ec93855ecd4624a43f',1936,'伪热河省建昌县保安队队长','率领伪保安队配合日军多次进攻建昌周边的抗日游击队，杀害抗日军民，烧毁村庄，罪行累累。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0ed347f63303483ead5d9133d74c09eb','9f7b3ed9c76f4eea8211fd8ebc40a461',1933,'伪满洲国热河省顾问（名义）','虽为军阀投机者，但在热河期间与日军合作，默许部下参与镇压建昌地区抗日活动，提供情报和物资支持。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d0c683f47aa54872893a88c0c29c70c7','94eb77f25c484ebf83af77ce54df34f8',1937,'伪建昌县司法科科长','主持伪司法审判，以“反满抗日”罪名判处多名爱国人士死刑或长期监禁，协助日伪维持殖民秩序。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2b8f776ee2ac472998746c73277b258c','b8f5150658fd47f0a48c92aacb628181',1939,'伪建昌县税务局局长','负责为日伪征收高额税赋，强征农民粮食，导致建昌地区民生凋敝，间接支持日军战争经济。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a955f47defd6491e860718ca5beb6b87','35ca92ca798d4a56a8ba0b695334c857',1934,'伪热河省建昌县教育督学','推行日本奴化教育，强制学校教授日语，删除中国历史内容，灌输“日满亲善”思想，毒害青少年。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('eeb7e5d2ac5d4fe2a7ec18dcb1c35421','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满洲国奉天省省长、伪第一军管区司令','原东北军旅长，叛国投日，任伪奉天省省长，管辖包括绥中在内的辽西地区，推行日伪殖民政策，镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7795f603970d408e91765e1a85c2d032','c9dffc071fec4ce58fe1d611f26c28da',1937,'伪满洲国锦州省省长','原东北军军官，投敌后任伪锦州省省长，绥中县属其管辖，积极推行“治安肃正”，配合日军围剿八路军冀热辽根据地。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8eb83c0f661542c69ca3a1b18f2d4214','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满洲国立法院院长、伪奉天市长','汉奸政客，曾任伪奉天市长，参与策划辽宁地区日伪政权建设，对绥中等地实施奴化统治。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3ddeb15ae8c5461385c25508554b9eda','21853206ad2b417598d1af0b4b3a4782',1932,'伪满洲国绥中县县长','绥中本地汉奸，投日后任伪县长，强征民夫修建日军工事，镇压当地抗日民众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ad55cd65944c41d1bda3ec70d16879e1','03693e927b0c45d1a4bc4b44a4623dfc',1933,'伪满洲国绥中县警务科长','在绥中地区组织伪警察队，多次参与围剿抗日义勇军和八路军游击队，残害百姓。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ddf7a7ff333b471e93c7380e2927f0cf','79b17193512846a1a5bde9f5df22c926',1931,'伪满洲国参议府议长、伪奉天省长','原辽宁省政府主席，九一八后投降，任伪奉天省长，对辽西绥中地区推行日伪法令。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('049ae714f23a48debcac93fc8860c3c8','875c22d678e24c21834a32caae69933c',1931,'伪满洲国财政部总长、伪宫内府大臣','满清皇族，投日卖国，参与伪满政权建设，间接影响辽宁各地包括绥中的殖民统治。；原东北军吉林副司令长官，1931年投敌，参与建立伪满，其政策影响遍及辽宁，包括阜新地区的经济掠夺与鸦片专卖。；清末宗室，九一八事变后率先在吉林投敌，组织伪吉林省政权，后任伪满财政部总长、宫内府大臣等职，积极协助日本控制东北财政与宫廷事务。；清朝宗室后裔，九一八事变后主动迎接日军进入吉林，组织伪吉林省政权，后任伪满洲国财政部总长、宫内府大臣，为伪满建立初期重要附逆者。；清末吉林驻军将领，九一八事变后率先投敌，引日军进入吉林，后任伪满财政部总长、宫内府大臣等职，参与伪满政权对东北包括黑龙江地区的统治。；原东北军吉林副司令长官，九一八后率先投敌，引日军占领吉林，推动伪满建立。；清末宗室，九一八事变后率先在吉林投敌，组织伪吉林省政权，后任伪满洲国财政部总长、宫内府大臣，积极参与伪满政权建设，其影响波及黑龙江地区。；清末宗室，九一八事变后率先在吉林投敌，组织伪吉林省政权，后任伪满洲国财政部总长、宫内府大臣，积极参与伪满政权建设，其附逆活动影响遍及东北包括黑龙江地区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d01d3a38c21a4af7810ec77144273ab4','5cce8fcbbcc043c2820499553d6999c1',1938,'伪满洲国锦州省协和会会长','在锦州省（含绥中）组织协和会，进行奴化宣传，搜集抗日情报，协助日军“清乡”。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('628e2ffdc08e4b00bd4461f6a448ab6b','589ab27feed347c6944e6c001125dc02',1939,'伪满洲国绥中县协和会分会长','绥中本地汉奸，负责协和会分会，煽动民众拥护伪满，告密抗日分子。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('388f8d4e5d9841929da19d3a46d2cec1','732f697adc0d4236a0ad7fb01ee5a149',1935,'伪满洲国绥中县保安队队长','率保安队配合日军扫荡绥中西部山区，杀害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f3881830f20d4575a917eefb5b39440d','6c5f2811c77d4f39b1ddb522f78f5e25',1937,'伪满洲国锦州省教育厅长','在锦州省（含绥中）推行奴化教育，篡改历史，强迫学生学日语。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7a459585a91b4eb1a58b4d125963a5f2','7ca60279616445fcaa58c2399291ebcb',1933,'伪满洲国顾问（名义）','虽未任实职，但公开支持伪满，其旧部在辽宁绥中地区协助日军维持秩序。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('417d6974fc8d48d3b6f2b70c16a2998d','b8f5150658fd47f0a48c92aacb628181',1932,'伪满洲国军政部总长（短暂投敌后反正）','一度投日任伪职，影响绥中地区部分旧部附逆，后反正抗日，但前期行为已构成汉奸事实。；江桥抗战英雄，1932年一度诈降出任伪职，旋即在黑省（含齐齐哈尔）反正抗日，其投敌行为虽短暂但曾造成恶劣影响。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ba37348397e946faad5d961367165660','caae33d173854bf0a1b2b4f0db4f585a',1938,'伪满洲国锦州省高等法院院长','在锦州省（含绥中）审判抗日人士，判处大量爱国者死刑或监禁。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('722f607704cc420687c79a23052b61f4','142849ebf8614017a075f60e0d2e7e40',1940,'伪满洲国绥中县副县长','协助日籍副县长管理绥中，强征劳工，实施粮食配给制，导致民众饥荒。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('062223f992bd436aa4a76c6aed278713','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满治安部大臣、奉天警备司令','原东北军旅长，叛变投敌，在辽西地区（含连山）组织伪军，多次围剿抗日义勇军，屠杀抗日志士。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0797f0492d1f492f88d720c153d35d79','c9dffc071fec4ce58fe1d611f26c28da',1934,'伪满锦州省省长','原地方豪强，投日后任伪锦州省省长，管辖范围包括葫芦岛、连山地区，推行日伪“治安肃正”，强征劳工，镇压抗日活动。；在锦州地区任伪省长期间，推行日伪奴化政策，强征劳工，协助日军建立保甲制度，镇压当地抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aba49d75d8ce4fd18f9a4b9ad914f9c3','21853206ad2b417598d1af0b4b3a4782',1932,'伪满锦州省警务厅长','原警察头目，投日后负责锦州及连山地区警务，协助日军建立保甲制度，抓捕抗日地下人员，制造多起血案。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5873a9ece90b425d821524c4373c3739','79b17193512846a1a5bde9f5df22c926',1931,'伪满参议府议长、奉天省省长','原奉天省主席，被俘后变节，任伪奉天省长期间，管辖辽西部分地区，配合日军在连山一带推行“归屯并户”，切断义勇军补给。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b2b2bf11b560424e8fce719da241e492','5cce8fcbbcc043c2820499553d6999c1',1931,'伪满锦州地区维持会会长','地方士绅，日军占领锦州后出任维持会长，在连山地区组织伪政权，为日军提供粮草和情报，协助镇压抗日义勇军。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('64e87ad3d1a3415a82700c05addbffa6','177c17b9b440453fa41ed47b9ebbd502',1933,'伪满热河省警备军司令','土匪出身，投日后任伪军头目，活动于辽西及热河交界，多次率部进攻连山一带的抗日游击队，烧杀抢掠。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('56fa803cd62a409cbd29390ea8ad185f','6c5f2811c77d4f39b1ddb522f78f5e25',1932,'伪满连山警察署署长','原地方警察，投日后任连山地区伪警察署长，直接执行日伪“治安肃正”，逮捕、刑讯抗日嫌疑人员，参与“大检举”行动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('92335f64493643a0b3a1f236305bca52','589ab27feed347c6944e6c001125dc02',1932,'伪锦州省省长（注：其子王瑞华曾任伪职）','（注：王永江为民国初期奉系要员，但已病逝于1927年，此处应为误传。实际在锦州地区活动的汉奸为伪锦州省省长王瑞华，但史料记载有限。）','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aa74e97739124a8c92b4e986d2f99819','922b606d45c647e8a82755373b3d3e91',1934,'伪满洲国锦州省省长','在锦州（含今葫芦岛地区）推行日伪统治，强征劳工，配合日军“治安肃正”，镇压抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fae11ba9fbf14f7788715f1adce7a816','87b0aba74b9b4c5f8a515bd9270d23b4',1931,'伪满洲国参议府议长、奉天省省长','原奉系官僚，积极策划“东北自治”，投日后任伪满参议府议长，在辽宁地区为日伪统治出谋划策。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('97a22efdd80a4b7ea0533b9f5bf1880a','caae33d173854bf0a1b2b4f0db4f585a',1932,'伪满洲国奉天省高等法院院长','在辽宁地区司法系统内为日伪效力，审判抗日志士，镇压反满抗日活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('05ab2080e1e4413c87009be23c87c55a','5cce8fcbbcc043c2820499553d6999c1',1933,'伪锦州省警务厅厅长','在锦州（含龙港地区）指挥伪警察，协助日军搜捕抗日地下组织，强征劳工，迫害百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('eb988dcbb4864c0da27e67120e56cbf9','21853206ad2b417598d1af0b4b3a4782',1934,'伪满洲国锦州省协和会本部部长','在锦州及葫芦岛地区推行奴化宣传，组织“协和会”刺探抗日情报，配合日军“治安强化运动”。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4a765a785a0c4f5fbaed26cf06e46b48','15b0ffb0c3064aa4a57d4d84ac82b7fa',1933,'伪满洲国锦州省民生厅厅长','在辽宁西部推行日伪“民生”政策，实际为掠夺粮食、强征劳工，协助日军控制葫芦岛港口。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4e92724c51be46a090b8824c9d61aa06','b8f5150658fd47f0a48c92aacb628181',NULL,'无','无','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7de5efaa8c3a4632af44e69da41e9a6f','87b0aba74b9b4c5f8a515bd9270d23b4',1931,'伪满参议府议长、伪满奉天省省长','积极协助日本建立伪满政权，曾任奉天省省长，参与奴化教育与经济掠夺。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2d05fd3e3b724363aa72a2dbd6116e83','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满立法院院长、伪满奉天市市长','曾任伪奉天市长，协助日本控制辽阳地区，参与制定殖民法规。；原奉系政客，九一八后投靠日本，曾任伪奉天市市长，在辽宁各地（含铁岭、开原）推行奴化教育，协助日军建立伪政权。；原奉系官员，九一八后投日，曾任伪满奉天市市长，后任伪满立法院院长，为日本殖民统治提供法律与行政支持，涉及铁岭地区伪政权建设。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('70d3f8d12cd54475b6280d685648761a','589ab27feed347c6944e6c001125dc02',1931,'伪满辽阳地区维持会会长','九一八事变后组织辽阳地方维持会，为日军提供粮饷与情报，协助建立伪政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d5d8c98dfd184aff9c9277676e6f04a8','21853206ad2b417598d1af0b4b3a4782',1932,'伪满辽阳县长','任伪辽阳县长期间，强征劳工，推行保甲制度，镇压抗日武装。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('963092f4fc674adbbbb5f87d2409598d','5cce8fcbbcc043c2820499553d6999c1',1932,'伪满辽阳警务处处长','指挥伪警察抓捕抗日志士，参与制造多起屠杀事件。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('57658f0eecf949aa8cc0abbf5ec22a9d','c9dffc071fec4ce58fe1d611f26c28da',1933,'伪满辽阳保安队队长','率伪保安队配合日军扫荡，杀害抗日军民，掠夺民间物资。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f04121cc15004bc2a669543513b151d5','84779a454ec74ec19985a1b53e006685',1931,'伪满鞍山昭和制钢所顾问','在辽阳地区协助日本掠夺铁矿资源，压榨中国工人。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4165eb738f624b5aaa1262a8b778ea87','caae33d173854bf0a1b2b4f0db4f585a',1932,'伪满奉天省警务厅长','在辽阳地区推行“治安肃正”，组织伪警察围剿抗日游击队。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2ece6d3941df41e99375b3e4d1f77953','70cbcc058e6648678fa022e3a64b9cea',1934,'伪满辽阳协和会会长','宣传“日满亲善”，强迫民众参加协和会，收集抗日情报。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('af2095514de54816ad07028b9f583790','3cd55e29febc489d9f9a7f2f88db31bb',1931,'伪满辽阳商会会长','为日军筹措军费，强征商业税，协助日伪经济统制。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e1627a42af7340fa970039eb3065159c','f1c6013bde504b5a97029739c664d873',1932,'伪满辽阳教育局长','推行奴化教育，删改历史教材，强迫学生学日语。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fdbb4003d1194e2a8231616f986dc52b','41502657c6b84465aa2ff94e620ed234',1931,'伪满奉天省实业厅长','在辽阳地区强征土地，控制粮食购销，导致民众饥荒。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c1bc204a303b4ab0807732fa0a6dd7e2','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满奉天省财政厅长','协助日本发行伪币，搜刮辽阳民间财富，资助侵华战争。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('30c0852ac3a4400dbaf440a1d6681b67','b8f5150658fd47f0a48c92aacb628181',1932,'伪满黑龙江省长（短暂投敌）','一度投降日本，在辽阳地区发表亲日言论，后反正抗日。','省部级/大军区级要员','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d1e5ff90dece4462b8cf9f32eaac3fa7','87b0aba74b9b4c5f8a515bd9270d23b4',1932,'伪满参议府议长、伪满奉天省省长（继任）','在辽阳地区积极推行伪满政权，组织地方治安维持会，为日军提供情报并协助清剿抗日武装。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d29fa4ce2dc64b069528b88a8e096852','589ab27feed347c6944e6c001125dc02',1932,'伪辽阳县县长（后任伪奉天省民政厅长）','在辽阳任内强征民夫修建日军工事，强制收缴民间武器，并组织汉奸保安队协助日军镇压太子河两岸抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3b4948948c744253b94a5a298447fd80','21853206ad2b417598d1af0b4b3a4782',1931,'伪辽阳地方维持会会长','九一八后率先组织辽阳维持会，欢迎日军进驻，提供当地抗日志士名单，导致多名地下党员被捕牺牲。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1cbd974e27f0426fa366098d4c2e68b6','3b74f508628f475a8777ffb7e38a48a0',1933,'伪满经济部大臣（曾任奉天省实业厅长）','在辽阳、太子河地区推行经济统制，强征粮食和金属物资供日军军需，导致当地民众生活极度困苦。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3847beb87d4c4b558e0c15ce0ba359bb','360451ccb61f491bafdc1b28af3c6799',1934,'伪满交通部大臣（曾任奉天省教育厅长）','在辽阳推行奴化教育，强制学校使用日语教材，并组织学生参拜靖国神社，破坏当地抗日文化传统。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d26b38f215ba470e955083adf58d79a7','0639407f8320412e86eada632a47d380',1932,'伪辽阳警务处长','指挥伪警察在太子河沿岸设立检查站，搜捕抗日交通员，多次参与围剿抗日义勇军，杀害无辜百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5c64a1af88ea4d10bc867da48e044ac3','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满热河省长（曾任洮辽镇守使）','虽主要活动于热河，但其部队曾在辽阳、太子河地区参与“讨伐”抗日武装，烧毁村庄，掠夺财物。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ce516a610a7b44d0848465fd81f898fc','bde77533c68f469aa5eeb667ea3940ed',1931,'伪奉天市市长、伪立法院院长','原律师，九一八后投靠日军，任伪奉天市市长，后任伪满立法院院长，参与制定伪满法律。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('127826fd585c4fe0be91816683352522','589ab27feed347c6944e6c001125dc02',1931,'伪辽阳县维持会会长','辽阳当地士绅，日军占领辽阳后组织维持会，协助日军维持秩序，征收粮饷。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1147ee1c648a45e6bdbfea8c9dbc7625','21853206ad2b417598d1af0b4b3a4782',1932,'伪辽阳地区保安队队长','原土匪头目，被日军收编，任辽阳地区伪保安队队长，多次参与围剿抗日义勇军，残害百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5d1cf4813fdf49ca8bbec98ad5990583','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满热河省省长（曾驻辽阳一带）','原洮辽镇守使，九一八后投敌，在辽阳、辽西一带协助日军进攻抗日武装，后任伪热河省长。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('117a339bde1e45108d07c54b246b647c','c9dffc071fec4ce58fe1d611f26c28da',1933,'伪满辽阳宪兵队翻译官','精通日语，为日军宪兵队充当翻译，参与抓捕、刑讯抗日志士，民愤极大。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('586fef806e59404db66abc17b3b4e867','3cd55e29febc489d9f9a7f2f88db31bb',1935,'伪宏伟区（今宏伟区）日伪警察署署长','在辽阳宏伟地区（当时为农村）任伪警察署长，强征劳工，镇压反抗，为日军提供情报。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('805fbf902cc143b8a7a392a7c3c4fe38','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满洲国奉天省省长、伪第一军管区司令官','原东北军将领，九一八事变后投敌，任伪奉天省省长，参与镇压辽宁抗日义勇军，推行日伪殖民统治，在辽阳、弓长岭一带协助日军“讨伐”抗日武装。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0e622284554349788de4b93d1d240e70','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洲国热河省省长（曾驻辽阳一带）','原洮辽镇守使，九一八后投敌，多次率伪军配合日军在辽宁东部（含辽阳、弓长岭山区）围剿抗日义勇军，烧杀抢掠。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8b5253a0800343fca3643ea1eb910274','21853206ad2b417598d1af0b4b3a4782',1932,'伪满洲国奉天省辽阳县县长','投日后任辽阳县伪县长，推行保甲制度，强征劳工，为日军在弓长岭铁矿提供劳力和物资，镇压当地抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9066f89688d14ad08788e6bb8f247614','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满洲国立法院院长（原籍辽宁，活动涉及辽阳）','原奉系法律人士，投日后任伪立法院院长，参与制定伪满洲国法律，为日本殖民统治提供法理依据，其家族在辽阳有产业并协助日伪征粮。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a0807717d4a840ea9e8f1c5696fbbec0','360451ccb61f491bafdc1b28af3c6799',1937,'伪满洲国奉天省省长（后期）','继于芷山后任伪奉天省长，管辖辽阳、弓长岭地区，推行“粮谷出荷”政策，强征农民粮食，支持日本对弓长岭铁矿的掠夺。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('582313da155a4a56ae12451e1ecc25c7','5d5b588b85754731b7b48a6f383d6ce5',1933,'伪满洲国辽阳地区警察署署长','在辽阳、弓长岭一带任伪警察署长，多次带队抓捕抗日地下党员和义勇军家属，刑讯逼供，协助日军建立“无人区”。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('829b4fa2efe64017b9de23b19d016b81','5cce8fcbbcc043c2820499553d6999c1',1932,'伪满洲国奉天省警务厅特务科科长','负责辽阳、弓长岭地区特务工作，发展汉奸密探，破坏抗日组织，曾参与逮捕多名抗日志士并移交日军处决。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5a1547b788a04dbca11d84cc5e79d67c','9d25e1d3d8e543ee84de82f230352248',1931,'伪满洲国辽阳县商会会长','投靠日伪，组织商会为日军筹集军费，强迫商户“献金”，并协助日军在弓长岭矿区征用民夫，从中牟利。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c581b49f30374de58949bf525c7213ee','3cd55e29febc489d9f9a7f2f88db31bb',1938,'伪满洲国弓长岭铁矿矿警队队长','任弓长岭铁矿矿警队长，残酷镇压矿工反抗，克扣工资，殴打致死多名矿工，并协助日军封锁矿区消息。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2a32406aa8264165940e2c8f176eafe1','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满辽阳地区警务处长','在辽阳、文圣一带担任伪警务要职，协助日军搜捕抗日志士，破坏地下抗日组织，参与“治安肃正”行动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ca814890b1f4445da7933ec3d6d71f99','21853206ad2b417598d1af0b4b3a4782',1933,'伪满辽阳县县长','任伪辽阳县县长期间，强制推行“保甲制度”，强征劳工，为日军提供物资，并参与镇压辽阳地区抗日武装。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2d702572f5fd474a9296d00cd59d1363','0639407f8320412e86eada632a47d380',1937,'伪满辽阳地区宪兵队翻译官','为日军宪兵队充当翻译，参与审讯和刑讯抗日人士，直接导致多名地下党员牺牲。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dd4f003fc64a405daab2838be754863f','31f5d1beddc247798a41ecf2ef35664c',1931,'伪满文圣区维持会会长','在辽阳文圣区组织维持会，协助日军建立秩序，强征民夫修筑军事工事，并告密抗日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('929431288fe3444e91acc253678ed76a','87b0aba74b9b4c5f8a515bd9270d23b4',1931,'伪满参议府议长、伪满尚书府大臣','清末民初政客，九一八后投敌，参与策划伪满洲国成立，任伪参议府议长，为日本殖民统治出谋划策。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8452d2f24ca4424785164695d9f61bec','79b17193512846a1a5bde9f5df22c926',1931,'伪奉天省省长、伪满民政部大臣','原辽宁省政府主席，九一八后被日军软禁后投降，任伪奉天省省长，推行日伪各项反动法令。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a3dd91360c664cc48c8b3bdb85a8f217','875c22d678e24c21834a32caae69933c',1931,'伪满财政部总长、伪宫内府大臣','原吉林副司令长官，九一八时投降日军，参与建立伪满，任伪财政部总长，为日本掠夺东北资源效力。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fe229e24010a4ebc92ea8b32eaeb53f8','360451ccb61f491bafdc1b28af3c6799',1931,'伪满外交大臣、伪满驻日大使','原奉天交涉员，投日后历任伪满外交部长、驻日大使，协助日本控制伪满外交，签订卖国条约。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7ec3ca50b49644a99d14ae3dc39eca07','caae33d173854bf0a1b2b4f0db4f585a',1931,'伪满中央银行总裁','原东三省官银号总办，投日后任伪满中央银行总裁，发行伪币，搜刮民财，支持日本战争经济。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fbb82310063e418d8c2d875a578b3b7b','236b09af126745e997e5603fc3f56d0e',1931,'伪满新京特别市市长','原吉林旗人，投日后任伪满首都新京市长，协助日本建设殖民统治中心，镇压反满抗日活动。；原吉林铁路局局长，投敌后任伪满高官，曾负责伪满“治安肃正”工作，多次到黑龙江绥化地区督导“清乡”行动。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5719230e8d8744ea9d4bbe8d422956c1','142849ebf8614017a075f60e0d2e7e40',1931,'伪辽阳县长','九一八后投靠日军，任伪辽阳县县长，推行日伪保甲制度，强征劳工，镇压当地抗日民众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3b428d7a6e5a4797b774539c6c3780a4','273f6e7a021144a8a30e8e2816a00f4e',1931,'伪辽阳警务局长','任伪辽阳警务局长，协助日军搜捕抗日志士，破坏地下抗日组织，残害百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3d4fec8d5b4c43ffb76c7f6978d2dfe2','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满热河省长、伪满军政部顾问','原洮辽镇守使，九一八后率部投敌，任伪热河省长，参与镇压辽西、辽北抗日义勇军。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6bdbdf38665a4d4b93d17fe6124dbad0','41502657c6b84465aa2ff94e620ed234',1931,'伪满财政部大臣','原吉林省财政厅长，投日后任伪满财政部大臣，协助日本控制东北金融，推行经济掠夺政策。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('230ace72d31849e0851d1e579cfd7993','3b74f508628f475a8777ffb7e38a48a0',1931,'伪满实业部大臣','原奉天商会会长，投日后任伪满实业部大臣，为日本垄断东北工商业，出卖民族经济利益。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1464ab28a6bc4a16890ee0c94901dd18','b8f5150658fd47f0a48c92aacb628181',1932,'伪满黑龙江省长（短暂投敌后反正）','原黑龙江抗日将领，1932年一度投日任伪黑龙江省长，但不久反正抗日，故其汉奸身份短暂且存在争议。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1ba0e5f46415491c82d661d2d5d23625','f1c6013bde504b5a97029739c664d873',1931,'伪辽阳地方维持会会长','九一八后组织辽阳地方维持会，协助日军维持秩序，征收捐税，为日军提供物资。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('80898e64edf844efacd8c8371bc42801','84779a454ec74ec19985a1b53e006685',1931,'伪满奉天省省长、汉奸','九一八事变后投靠日本，任伪奉天省省长，协助日军维持殖民统治，镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a3a94f6964a44e3f9d225f71b03442ce','87b0aba74b9b4c5f8a515bd9270d23b4',1931,'伪满参议府议长、汉奸','曾任伪满参议府议长，积极参与伪满政权建立，为日本侵略政策服务。；曾任伪奉天省省长，后任伪满参议府议长，积极为日本侵略政策服务，参与伪满政权建设。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('340d672c802f485c8f4121185d187e09','77a789268c6f47b4a617cdb9e41180bd',1935,'伪满国务总理大臣、汉奸','原奉系将领，后投敌任伪满国务总理，全面配合日本对东北的殖民统治。；曾任伪满军政部总长，后任伪满国务总理大臣，全面配合日本对东北的殖民统治，包括鞍山千山地区。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('735785a998474b53a3bd2b8a170c428d','79b17193512846a1a5bde9f5df22c926',1932,'伪满奉天省省长、汉奸','继于冲汉后任伪奉天省省长，推行日伪政策，镇压抗日力量。；继于冲汉后任伪奉天省省长，推行日本殖民政策，协助日军清剿抗日义勇军。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d34b83d082e74561a831b97333ba4eb2','589ab27feed347c6944e6c001125dc02',1931,'伪辽阳县维持会会长（注：其活动主要在辽阳地区）','九一八后组织辽阳地方维持会，协助日军维持秩序，征收捐税供日军使用。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c62599709b6647ca92e4a4b332767ceb','21853206ad2b417598d1af0b4b3a4782',1932,'伪辽阳县长、汉奸','任伪辽阳县长期间，强征民夫修建日军工事，搜刮粮食资敌。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9c9af59ab32f4678883429b249bcc509','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满立法院院长、汉奸','参与伪满立法，为日本殖民统治提供法律依据，曾活动于辽阳一带。；曾任伪满立法院院长，参与制定伪满法律，为日本侵略合法化服务，活动范围涉及辽宁各地。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('64148dc104794969851bc64c9934688d','1ba31d558b934fbd83a28a8c2b446022',1933,'伪满热河省省长、汉奸（曾驻辽阳）','原东北军将领，叛国投敌，在辽阳等地协助日军清剿抗日义勇军。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b123f5b88550401f9f24571dca8a0c00','1d67ff455ffc47b8addcc485beb0ca34',1932,'伪满第一军管区司令、汉奸','率伪军驻防辽阳、鞍山地区，多次参与“讨伐”抗日武装。；驻防辽宁地区，指挥伪军多次进攻千山抗日根据地，残害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('988392a5326e4ef582d7d07ff471e9c4','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满辽阳警务处长、汉奸','指挥伪警察在辽阳白塔区一带搜捕抗日分子，实施白色恐怖。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f5bb70aef874407f8000e03f7a369a10','15b0ffb0c3064aa4a57d4d84ac82b7fa',1932,'伪满奉天省警务厅长、汉奸','负责伪奉天省（含辽阳）警务，协助日军建立保甲制度，镇压抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8e83240e247449f68db12e90cb0c905f','e409ef959281461b91e8ce1eef37d186',1932,'伪满军政部总长、汉奸（曾驻辽阳）','原东北军将领，投敌后任伪军政要职，参与策划对辽阳地区抗日力量的围剿。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ebbe822c218e40e68f4bb00003c90ebf','21853206ad2b417598d1af0b4b3a4782',1932,'伪满铁岭县县长','任伪铁岭县长期间，强征民夫修建日军工事，推行保甲制度，协助日军掠夺粮食资源，镇压抗日群众。；任铁岭县县长期间，强征农民粮食和劳工，为日军提供物资，并配合宪兵队镇压铁岭地区的抗日反满活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('89c9544a7f364f83856153da132ef5a1','0639407f8320412e86eada632a47d380',1933,'伪满昌图县县长','在昌图（今属铁岭市）任伪职，积极为日军提供情报，组织汉奸武装“自卫团”，参与围剿抗联杨靖宇部。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('36aa071d12a3465290c40f2ef43bc821','79b17193512846a1a5bde9f5df22c926',1931,'伪满奉天省省长（后任参议府议长）','原辽宁省政府主席，投敌后管辖铁岭地区，推行“粮谷出荷”政策，导致当地百姓饥荒，并协助日军清剿抗联。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c2bbca325b4743549123a33b4be8081c','5cce8fcbbcc043c2820499553d6999c1',1932,'伪满铁岭地区警务总署署长','在铁岭、开原、西丰等地建立特务网络，抓捕抗日志士，严刑逼供，制造多起惨案。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cd87b58eb4094c71a5cfa0bf75484220','24dc9b98732f49eda269037ee68c9c2f',1932,'伪满协和会铁岭支部长','利用协和会组织在铁岭宣传“王道乐土”，强迫民众参加“日满亲善”活动，检举抗日分子。','省部级/大军区级要员','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0673c98e060947bc8108c3d728fa12d1','589ab27feed347c6944e6c001125dc02',1932,'伪满铁岭县县长','原铁岭地方士绅，伪满成立后出任铁岭县县长，为日军征粮派夫，镇压当地抗日活动，强推“保甲连坐”制度。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3114225ca3ec443ba77f63e370f9b14d','21853206ad2b417598d1af0b4b3a4782',1932,'伪满开原县县长','原开原县商会会长，投日后任开原县县长，协助日军建立伪警察队，多次参与围剿抗日游击队，并强征劳工。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('724c5a075b904fe5841318c7c01c3137','5cce8fcbbcc043c2820499553d6999c1',1933,'伪满铁岭地区警备司令','原铁岭地方武装头目，投日后任伪警备司令，在铁岭、开原一带抓捕抗日志士，制造多起屠杀事件。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dd6b55d0bb41450a87dc818ef81402ad','87b0aba74b9b4c5f8a515bd9270d23b4',1931,'伪满参议府参议','原奉系政客，投日后参与伪满政权，在辽宁地区（含铁岭、开原）为日军出谋划策，协助建立地方伪组织。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d4d16b5585a245a29ecd5e1ca508c55d','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满铁岭县警察署署长','原铁岭县警察，投日后任伪警察署长，直接指挥抓捕抗日地下人员，多次参与“讨伐”行动，民愤极大。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('12fe89952b95488297a7418f98161ec8','3cd55e29febc489d9f9a7f2f88db31bb',1935,'伪满开原县协和会会长','原开原县地主，投日后任协和会会长，宣传“日满亲善”，强迫民众参加“勤劳奉仕”，为日军搜集情报。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cd54522e86f54de09db16abd1e3e9a83','89a5274e857d484894f7c702bf2f7f72',1933,'伪满铁岭县保安队队长','原铁岭县土匪头目，被日伪收编后任保安队长，在铁岭、开原交界处多次袭击抗日游击队，杀害无辜百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('da788ed163664062816a86716df07699','759cfb5f46624562bc0d114d5292cbca',1934,'伪满开原县警务科科长','原开原县警佐，投日后任警务科长，负责“治安肃正”，逮捕并刑讯抗日群众，参与“集团部落”建设。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3a9098e9e184405f905a50cb00346d03','a33e6385cb6c40c3a4c2153469b04453',1932,'伪满铁岭县教育局长','原铁岭县教育界人士，投日后任伪教育局长，强制推行日语教育，篡改历史教材，毒化青少年思想。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fb1e806451854a6f88a5e7e5e3d3925f','b8f5150658fd47f0a48c92aacb628181',1932,'伪满开原县自卫团团长','原开原县民团头目，投日后任自卫团长，配合日军“扫荡”，烧毁村庄，强征壮丁，罪行累累。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('407d104f9c4a48c8a8f190ddeefd2682','7ca60279616445fcaa58c2399291ebcb',1931,'伪满铁岭地区维持会会长','原铁岭县士绅，九一八后组织维持会迎接日军，后任伪职，为日军征粮派款，协助稳定伪政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5a5eb8ec3d6d47fa86bfea1c9fcdbb83','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满奉天省实业厅长','原辽宁实业界人物，投日后任伪实业厅长，在铁岭、开原等地推行经济掠夺政策，垄断粮食和矿产。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('03a76eda24aa427b9fc17134c470c4a2','142849ebf8614017a075f60e0d2e7e40',1933,'伪满开原县法院院长','原开原县司法人员，投日后任伪法院院长，以“反满抗日”罪名判处多人死刑，为虎作伥。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('266649973d3d4774be140c6fd5676433','273f6e7a021144a8a30e8e2816a00f4e',1936,'伪满铁岭县协和会事务长','原铁岭县商人，投日后任协和会事务长，组织“青少年团”，灌输军国主义思想，协助日军征兵。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1b5015c93f304b059a0da99b4d0f793d','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满奉天市市长、伪满立法院院长','原奉系政客，九一八后投敌，任伪奉天市市长，协助日军建立殖民统治，后任伪满立法院院长，参与制定奴化政策。；原奉系法律人士，九一八后投敌，任伪奉天市市长，后升任伪满立法院院长，在辽宁及鞍山地区推行日伪法律，镇压反满抗日活动。；曾任伪满奉天市市长，后升任伪满立法院院长，在辽宁地区（包括鞍山铁东）推行奴化教育和经济掠夺政策。；曾任伪满奉天市市长，管辖包括鞍山、铁西在内的地区，推行奴化教育，镇压反满抗日活动。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0d6a45c91ca943bcb40c73e414e63f39','360451ccb61f491bafdc1b28af3c6799',1931,'伪满奉天省省长','原东北军文职官员，投日后历任伪满要职，任伪奉天省省长期间，推行日伪“治安肃正”，在铁岭、昌图等地强征劳工、掠夺粮食。；原东北军文职官员，投敌后历任伪满奉天省省长，管辖铁岭、银州等县，推行日伪“治安肃正”政策，镇压抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('86df3b2511ca497a88901426e7c6d688','5cce8fcbbcc043c2820499553d6999c1',1932,'伪满铁岭县县长','铁岭本地士绅，投日后任伪铁岭县县长，协助日军建立保甲制度，强征民夫修筑公路和军事工事，镇压当地抗日活动。；原铁岭地方士绅，投日后任伪满铁岭县县长，协助日军建立保甲制度，强征劳工，搜刮粮食，迫害抗日家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e75549adfc6843c5ad4ea9af0d6f39b5','3cd55e29febc489d9f9a7f2f88db31bb',1932,'伪满昌图县县长','原昌图地方官员，投日后任伪昌图县县长，推行日伪“归屯并户”政策，制造无人区，配合日军清剿抗日武装。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f521f06ea7aa4fda9727d9112ca88cbd','41502657c6b84465aa2ff94e620ed234',1931,'伪满民生部大臣','原吉林教育厅长，投日后任伪满民生部大臣，推行奴化教育，在铁岭、昌图等地设立日语学校，强制灌输“王道乐土”思想。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('23ce6356e60d4c9cb329d4b9f6b6be6f','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1932,'伪满铁岭地区警务处处长','铁岭本地警察头目，投日后任伪铁岭警务处长，组织伪警察队，多次参与“讨伐”抗日游击队，杀害无辜百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('72c9d595e0ca4360aa392cbcdd74852c','21853206ad2b417598d1af0b4b3a4782',1932,'伪满昌图地区保安队队长','昌图地方恶霸，投日后组织伪保安队，配合日军扫荡，在昌图北部制造多起惨案，强抓壮丁补充伪军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9d7a1ffef71d458cbfd8b0da8875bebe','f1c6013bde504b5a97029739c664d873',1932,'伪满奉天省教育厅厅长','原奉天教育界人士，投日后任伪奉天省教育厅长，在铁岭、昌图推行殖民教育，篡改历史教材，禁止中国传统文化传播。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('108fd632a47c4d7d9101892461eed736','70cbcc058e6648678fa022e3a64b9cea',1933,'伪满铁岭县警察署署长','铁岭县伪警察头目，积极执行日伪“治安肃正”计划，在铁岭城乡设立检查站，逮捕抗日地下工作者。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0a8c808fb68c4f9ca519a26a0b95d0bc','d3b0ad724e144b199421e48418d30cc2',1934,'伪满昌图县协和会会长','昌图县协和会头目，协助日军进行思想宣传，组织“勤劳奉仕”运动，强迫当地农民为日军服劳役。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5c102d1f529d4082b89725f65742a955','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满铁岭县警务科警尉','在清河地区协助日军‘讨伐’抗日武装，抓捕抗日军民并刑讯逼供，参与制造多起惨案。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2b1fb8ec598a40a2be6b23e1255f6c26','1ba31d558b934fbd83a28a8c2b446022',1933,'伪满热河省省长（原籍铁岭清河）','早年投靠日军，后任伪满热河省省长，在清河地区有田产，曾协助日军清乡，镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('77bf43ff54904d89a5fd2fa7132bb31e','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满立法院院长（祖籍铁岭清河）','虽主要活动在伪满中央，但利用其铁岭清河籍贯影响，为日军在清河地区推行‘治安肃正’出谋划策。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('59152e5eee0c4cfca97288e3b2ab9486','84779a454ec74ec19985a1b53e006685',1931,'伪满监察院院长（曾任铁岭地区维持会头目）','九一八事变后，在铁岭清河一带组织地方维持会，为日军提供粮秣和情报，协助建立伪政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5e06d861736d4b7187714c8e12dac328','21853206ad2b417598d1af0b4b3a4782',1934,'伪满铁岭县清河城子警察署署长','在清河城子一带强征劳工，抓捕抗日嫌疑犯，并直接参与日军对清河沟游击队的围剿行动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9814e4630f5e4f1b9da8e5e31d7522d5','3cd55e29febc489d9f9a7f2f88db31bb',1937,'伪满清河地区自卫团团长','组织汉奸自卫团，配合日军在清河沿岸设卡盘查，多次袭击抗联小分队，杀害抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('babf3214da8e497587485c1a23a3052a','bedc991fdcff4254a3e2b0b24052d010',1938,'伪满铁岭县清河区区长','推行伪满‘保甲连坐’制度，强迫村民报告抗日分子行踪，并贪污勒索百姓，为日军征收军粮。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('344cb4f09a1142da8d1f20c7fac1fb68','58e0789e95bd4ebbbcd684f96190f03d',1940,'伪满清河地区特务情报员','化装成商人刺探抗联情报，多次向日军告密导致清河地区地下交通站被破坏，多名抗日志士被捕。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f704a78b249945148af0644b693c7455','be4d225703674480b87a2117d167f154',1941,'伪满铁岭县清河警察署特务股长','专门负责‘思想犯’侦缉，在清河地区逮捕进步教师和学生，酷刑审讯后移送抚顺监狱。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('20360bdfd63b40f0beccb3a860e2b492','8a4d102b74bb4301bbae296450e5c751',1935,'伪满清河地区协和会分会会长','利用协和会组织宣传‘日满亲善’，诱骗青年参加伪军，并协助日军在清河地区进行‘归屯并户’。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('439bb1bc555744e585fbb15b22c7c1bd','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满西丰县县长','任伪满西丰县县长期间，积极推行日伪殖民政策，强征劳工，镇压抗日活动，协助日军搜捕抗日志士。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('82c7357b75e649cc8d93218de0630d44','1ba31d558b934fbd83a28a8c2b446022',1933,'伪满热河省省长（原籍西丰）','原东北军将领，后投敌叛国，任伪满热河省省长，配合日军“围剿”抗日武装，在热河及辽北地区残害抗日军民。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('898d6f09daec4166ab7d9c9a9aeaadf3','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满立法院院长（原籍铁岭）','铁岭籍汉奸，积极参与伪满政权建设，为日本殖民统治出谋划策，推动“日满亲善”宣传，协助镇压东北抗日联军。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('633a731e66764bd7847280923c6244ca','84779a454ec74ec19985a1b53e006685',1932,'伪满监察院院长（原籍铁岭）','铁岭籍汉奸，曾任伪满监察院院长，积极效忠日本关东军，参与制定殖民政策，协助日军掠夺东北资源。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aed599bbaaff4697a14b0e98866e3f70','87b0aba74b9b4c5f8a515bd9270d23b4',1932,'伪满参议府议长（原籍辽阳，活动于铁岭）','在铁岭地区活动，任伪满参议府议长，积极推动“满洲国”建国，为日本侵略者张目，参与镇压抗日力量。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('93df307191e34ff8a2f0befcc3b15b99','495c45006f76462085be969c028fd535',1933,'伪满热河省警备司令（原籍西丰）','西丰籍汉奸，原奉系军阀，投日后任伪满热河省警备司令，率伪军配合日军“扫荡”抗日根据地，屠杀抗日群众。','市县厅局级','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c103971a931d4f00a7bc55bcfb1fe7cf','236b09af126745e997e5603fc3f56d0e',1932,'伪满铁道守备队司令（活动于铁岭）','在铁岭地区担任伪满铁道守备队司令，负责保护日军运输线，抓捕抗日地下工作者，破坏抗日组织。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3e58dad5b55c4b87b1d198f4bb545ba7','589ab27feed347c6944e6c001125dc02',1932,'伪满奉天省警务厅长（原籍铁岭）','铁岭籍汉奸，任伪满奉天省警务厅长，指挥伪警察协助日军“清乡”，在西丰、铁岭等地大肆逮捕抗日人士。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5897edc632d54e8ca11c18f3d1eb16d0','caae33d173854bf0a1b2b4f0db4f585a',1935,'伪满西丰县警务科科长','任西丰县警务科科长期间，积极执行日伪“治安肃正”计划，多次带队围剿西丰境内的抗日游击队，杀害多名抗联战士。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a241b8b410a642eda05bbc4f512f3331','c9dffc071fec4ce58fe1d611f26c28da',1931,'伪满铁岭县县长','1932年投靠日军，任伪铁岭县县长，协助日军推行“治安肃正”，镇压抗日武装，强征劳工，搜刮民财，为日军提供粮秣和情报。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7e81fe6333a94423918611bebc568468','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满热河省省长（曾驻铁岭地区）','原奉系军阀，九一八后公开投敌，在铁岭、调兵山一带协助日军围剿抗日义勇军，后任伪热河省长，其部队参与对辽北地区的“讨伐”。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5790c4100e554891ab444e6a2dc2f15f','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满奉天省高等法院院长（涉及铁岭司法）','汉奸法学家，参与伪满司法体系，对铁岭、调兵山地区抗日人士进行非法审判和迫害，积极为日本殖民统治提供法律依据。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7f3a586cd20448b1bd8e61936ac58171','1d67ff455ffc47b8addcc485beb0ca34',1932,'伪满第一军管区司令（辖铁岭地区）','原东北军将领，叛变后任伪满军第一军管区司令，驻防奉天（沈阳）及铁岭一带，多次指挥伪军“讨伐”调兵山、法库等地的抗日游击队，屠杀抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('56c690cf2511487eacded83d1e80d6dc','3a9e402192aa460fb51a927d874bb93e',1933,'伪满铁岭地区警察署长','铁岭本地人，投靠日伪后任警察署长，在调兵山、晓明镇等地设立情报网，抓捕抗日地下工作者，参与“归屯并户”和“三光”政策实施。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5dbc447c8ba54c17a473fad507e272d9','21853206ad2b417598d1af0b4b3a4782',1932,'伪满铁岭保安队队长','原土匪头目，被日军收编后任铁岭保安队长，在调兵山矿区镇压矿工反抗，强征民夫修筑军事工事，并配合日军扫荡周边村庄。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('283b34dcdc4e465abc34973c480a11ef','3cd55e29febc489d9f9a7f2f88db31bb',1931,'伪满调兵山维持会会长','调兵山（时称“大明”一带）地方士绅，日军占领后主动出任维持会长，为日军筹集粮款，出卖抗日义勇军情报，导致多支小股游击队被消灭。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c28a07f62cff45ec9f99ffdd26730753','77a789268c6f47b4a617cdb9e41180bd',1935,'伪满国务总理大臣（曾参与铁岭地区殖民统治决策）','作为伪满最高汉奸之一，其推行的“粮谷出荷”、“勤劳奉仕”等政策直接压榨铁岭、调兵山农民和矿工，造成大量平民死亡。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f178e00468b44e4890c47cdc9c6b5d48','3b74f508628f475a8777ffb7e38a48a0',1937,'伪满奉天省省长（辖铁岭）','在任期间强化铁岭地区的“保甲制度”，在调兵山一带推行“连坐”，并组织汉奸武装“自卫团”协助日军清乡，掠夺煤炭资源。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3b0498d2dd6f492b8a6d97cce6b36f8e','5cce8fcbbcc043c2820499553d6999c1',1938,'伪满铁岭县警务科科长','铁岭县警务实际负责人，在调兵山、孤家子等地设立多个警察分驻所，亲自审讯刑讯抗日嫌疑犯，曾一次逮捕并杀害12名抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('215fbeea717a4913ba0a2f0b20f41f85','c9dffc071fec4ce58fe1d611f26c28da',1931,'伪满奉天省警备司令官','原东北军营长，投敌后任伪满奉天省警备司令官，在铁岭、银州一带多次围剿抗日游击队，残害抗日军民。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('95a69323cceb40c4801f9fb64a33d5b5','21853206ad2b417598d1af0b4b3a4782',1933,'伪满银州地区警察署署长','原银州（今铁岭银州区）警察，投日后任伪警察署长，多次参与抓捕抗日地下工作者，严刑逼供，制造多起血案。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a0e9d5bf89fb4ffabc9fb359d93915f5','3cd55e29febc489d9f9a7f2f88db31bb',1932,'伪满铁岭保安队队长','原铁岭地方武装头目，投日后组织伪保安队，配合日军扫荡铁岭东部山区抗日根据地，烧毁村庄，杀害无辜百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0e801f408d9d48328b7f863a1c950e4e','79b17193512846a1a5bde9f5df22c926',1931,'伪满奉天省省长（早期）','原辽宁省主席，被日军俘虏后变节，任伪满奉天省省长，管辖铁岭地区，推行“归屯并户”，切断抗日武装与民众联系。；九一八事变后投敌，任伪奉天省省长，协助日军控制阜新等地区，镇压义勇军。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e7cf76fc589142d6ae187182c35b40ff','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满热河省省长、伪满锦州省省长','九一八事变后投靠日军，任伪满热河省省长，后调任伪满锦州省省长，镇压抗日力量，推行殖民统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('24bc5bc612ae452299d032aca691845e','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满立法院院长、伪满锦州省顾问','曾任伪满立法院院长，后任锦州省顾问，协助日军在锦州地区实施奴化教育和经济掠夺。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fefba3d637494ba08eda12c2e2918443','84779a454ec74ec19985a1b53e006685',1931,'伪满监察院院长、伪满锦州省参议','投靠日本后任伪满监察院院长，曾参与锦州地区伪政权建设，协助日军清剿抗日武装。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e53e6f2aa5a8455ca0e00aa1772ee4ad','87b0aba74b9b4c5f8a515bd9270d23b4',1931,'伪满奉天省省长、伪满锦州省高等法院院长','曾任伪满奉天省省长，后任锦州省高等法院院长，为日军镇压抗日民众提供司法支持。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1660fe1b8de247a88293871a3515386e','589ab27feed347c6944e6c001125dc02',1932,'伪满锦州省警务厅厅长','任伪满锦州省警务厅厅长期间，组织警察配合日军搜捕抗日分子，实施白色恐怖。；在锦州地区担任伪警务厅长，协助日军清剿抗日武装，抓捕地下抗日人员。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6fc88c61d7c14825b7881f4bc0ac36ba','21853206ad2b417598d1af0b4b3a4782',1933,'伪满锦州省协和会会长','担任伪满锦州省协和会会长，推行奴化宣传，强迫民众参加反共集会。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f74ec1c8981c449f9f47159cf4f15467','77a789268c6f47b4a617cdb9e41180bd',1931,'伪满国务总理大臣（曾兼锦州地区军事顾问）','伪满最高汉奸之一，曾参与策划锦州地区“治安肃正”行动，屠杀抗日军民。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e73ed54dd37e4d0ea8fea4a0570378ee','79b17193512846a1a5bde9f5df22c926',1931,'伪满奉天省省长（曾管辖锦州地区）','投日后任伪满奉天省省长，其辖区包括锦州，支持日军在锦州建立伪政权和军事据点。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c40451abd915413a873bf4207bfc088b','875c22d678e24c21834a32caae69933c',1931,'伪满财政部总长（曾参与锦州地区伪军整编）','伪满核心汉奸，参与组建伪满军，并协助日军在锦州地区收编土匪武装为伪军。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3758d269b87a45759b7839abbcc568a0','b8f5150658fd47f0a48c92aacb628181',1932,'伪满军政部总长（一度在锦州地区活动）','早期抗日，后一度投日，任伪满军政部总长，其部队曾在锦州地区配合日军行动。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f05a99d74df04d1cb7ae80f9df43b63f','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满锦州省实业厅厅长','任锦州省实业厅厅长期间，协助日本掠夺锦州地区矿产和粮食资源。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f5c05e147104463090444bc8fdad1150','5cce8fcbbcc043c2820499553d6999c1',1933,'伪满锦州省教育厅厅长','推行奴化教育，强制学校教授日语，删除中国历史内容，迫害爱国教师。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('69e47ef2a3044267933f4eb41d7f743c','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满锦州地区保安队队长','率保安队协助日军围剿锦州抗日游击队，多次制造屠杀事件。','基层头目','hanjian');
