INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bf9ddd26206f450aabbcc21acd4fad9a','177c17b9b440453fa41ed47b9ebbd502',1931,'伪满锦州地区土匪改编伪军头目','原土匪头目，投日后被编为伪军，在锦州地区烧杀抢掠，破坏抗日根据地。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('689e02465b954e11a245b74f88a054df','9e5ee50d4aeb4fba87b9ecc885685187',1934,'伪满锦州省警察署署长','指挥警察抓捕地下党员，破坏抗日组织，协助日军进行“大检举”。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0bae6b50381b4c8e892fc83869dff9c8','41502657c6b84465aa2ff94e620ed234',1932,'伪满锦州省民生厅厅长','推行“粮谷出荷”政策，强征锦州农民粮食，导致大量饿殍。；负责伪锦州省“民生”事务，实际推行粮食统制，导致黑山地区百姓饥荒，并强征民夫修筑军事工事。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7db86a969c0e41a8916c7256b3b5fc8d','f1c6013bde504b5a97029739c664d873',1933,'伪满锦州省法院审判官','以“反满抗日”罪名判处多名爱国人士死刑，充当日本司法帮凶。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('21aa99c0d0be4e2ba52faa605791fc1b','9d25e1d3d8e543ee84de82f230352248',1931,'伪满锦州省商会会长','为日军筹集军饷，强迫商户捐献物资，并告发抗日商人。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2fb791ec1cca432a9061759d6c7c9bfc','15b0ffb0c3064aa4a57d4d84ac82b7fa',1932,'伪满锦州省参事官','参与制定锦州地区“治安维持法”，协助日军建立保甲制度。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('848d32751d0d4efc92cdaea2e2282f5f','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洲国热河省省长、伪锦州省省长','九一八事变后投靠日军，曾任伪热河省省长，后调任伪锦州省省长，积极推行日伪殖民政策，镇压抗日力量。；原东北军将领，1933年投敌，任伪热河省省长，后转任伪锦州省省长，协助日军镇压抗日武装，推行殖民统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e608fe8c5c8a4699b56940f15bef6bb7','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满洲国立法院院长、伪锦州省省长（短暂）','曾任伪满洲国要职，参与筹建伪政权，后短暂担任伪锦州省省长，协助日军统治辽宁地区。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7b2519587f7f4a0cb76c57c29e41e663','589ab27feed347c6944e6c001125dc02',1932,'伪锦州省警务厅厅长','在伪锦州省任职期间，残酷镇压抗日义勇军和地下抗日组织，协助日军进行“治安肃正”。；原奉天警察头目，投日后负责锦州、凌河地区伪警察体系，残酷镇压抗日地下组织。','市县厅局级','hanjian');
