INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ee17ba743859442c96312c47e52deb84','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满洲国军政部大臣、伪锦州地区军事顾问','原东北军将领，投敌后参与组建伪军，在锦州、义县一带协助日军清剿抗日武装。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a656fe6ce7604bf8950007b88c3cdc05','5cce8fcbbcc043c2820499553d6999c1',1934,'伪锦州省民生厅厅长','主管伪锦州省“民生”事务，实际推行奴化教育，强制民众学习日语，灌输“日满亲善”思想。；负责推行“粮谷出荷”政策，在凌河地区强征粮食，导致民众饥荒。','市县厅局级','hanjian');
