INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e696627310ad42de9351e7e3e07533d5','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪锦州省保安队队长','率领伪保安队配合日军“扫荡”，在义县、北镇等地多次制造惨案，杀害无辜百姓。','基层头目','hanjian');
