INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6bf7b0b479554240adebafee109598ba','87b0aba74b9b4c5f8a515bd9270d23b4',1932,'伪满洲国参议府议长、伪锦州省参事','清末举人，投日后任伪满要职，在锦州地区推行奴化教育，协助日军清乡。','无明确职位或一般帮凶','hanjian');
