INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d78ec880c5054a02a8a734e1f39dbfc8','79b17193512846a1a5bde9f5df22c926',1932,'伪满洲国奉天省省长（曾兼管锦州）','原辽宁省主席，投日后任伪奉天省长，曾协调日军对锦州、凌河地区的“讨伐”行动。','省部级/大军区级要员','hanjian');
