INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8d5efae41f87426ca5fd4d2f18c7bfaa','1a8847af165d4d648f62d949fad6cb5a',1932,'伪满锦州省警务厅长','在锦州、凌海地区指挥伪警察，搜捕抗日志士，破坏地下组织，协助日军进行“讨伐”行动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('eb9e0416a26c4b3b8f123a3875b403ef','21853206ad2b417598d1af0b4b3a4782',1931,'伪满锦州地区保安队头目','组织汉奸武装，在凌海一带为日军带路，参与屠杀抗日军民，强征民夫修筑军事工事。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1aae84bf781c44fa935dd98277d1f040','177c17b9b440453fa41ed47b9ebbd502',1933,'伪满热河省（含锦州西部）伪军旅长','原土匪头目，投日后在辽西地区烧杀抢掠，配合日军进攻抗日根据地，残害百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3578b512b5884eebbf1283ada1494738','589ab27feed347c6944e6c001125dc02',1934,'伪满锦州省民生厅长','在锦州地区推行“粮谷出荷”政策，强抢农民粮食，导致凌海等地饥荒，并参与奴化教育。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f93a9f59e19a4c49b90a5d333fce6e57','5cce8fcbbcc043c2820499553d6999c1',1935,'伪满锦州省协和会事务长','在锦州、凌海组织协和会，宣传“日满亲善”，刺探抗日情报，破坏群众抗日组织。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b3a777de028e4defbc7582026c2459b7','15b0ffb0c3064aa4a57d4d84ac82b7fa',1931,'伪满锦州地区维持会会长（初期）','九一八后率先在锦州组织维持会，迎接日军，协助建立伪县政权，迫害爱国人士。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2a9ac36f1f304816bdb405deb20cc3f4','fd2c5f0abda941079651ec9eb1cc5c31',1932,'伪满锦县（今凌海）县长','在凌海地区强制推行“归屯并户”，制造无人区，配合日军围剿义勇军，征收苛捐杂税。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0148989748e44a17893047b6808b9860','6c5f2811c77d4f39b1ddb522f78f5e25',1933,'伪满锦县警察署长','在凌海地区抓捕抗日群众，严刑逼供，多次带队突袭抗日联络点，杀害地下党员。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2799c4fb637d4f6f818625bdad5ebcc2','54ed3d5811124de1a4f4c9e1d7ad39d8',1934,'伪满锦州省教育局长','在锦州、凌海学校推行日语教育和“王道乐土”宣传，篡改历史，毒化青少年思想。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a4549270db4749d79f87ff175e6a2442','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满热河省省长、伪锦州省省长','九一八事变后投敌，曾任伪满热河省省长，后调任伪锦州省省长，积极推行日伪殖民政策，镇压抗日力量。；九一八事变后投靠日本，历任伪满热河省省长、伪锦州省省长，积极推行日伪殖民政策，镇压抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7be3787ed2f749b4b01a785ad0601a98','589ab27feed347c6944e6c001125dc02',1932,'伪北镇县县长','投靠日军后任伪北镇县县长，协助日军清乡、征粮，迫害抗日家属，强征劳工。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e0bb433b1c0847178a6fdafd6cefa526','21853206ad2b417598d1af0b4b3a4782',1932,'伪锦州省警务厅厅长','在锦州地区组织伪警察，参与多次“讨伐”抗日义勇军行动，抓捕并杀害抗日志士。；在锦州及古塔一带指挥伪警察和特务，搜捕抗日志士，破坏地下交通线，参与制造多起屠杀事件。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4a47d81207264926a380d14da08934a9','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满立法院院长（曾活动于锦州）','虽主要任职于伪满中央，但曾赴锦州地区为日军“宣抚”工作，鼓吹“日满亲善”，协助建立伪政权。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fa62a07932dc48828484fabf29f635c5','84779a454ec74ec19985a1b53e006685',1931,'伪满监察院院长（曾参与锦州地区伪政权组建）','参与策划锦州地区伪政权建立，为日军占领锦州提供情报和行政支持。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('edea97364b394b96afcf6f7f28170b58','87b0aba74b9b4c5f8a515bd9270d23b4',1931,'伪满参议府议长（曾活动于辽西）','作为汉奸政客，多次到锦州、北镇等地游说地方士绅投日，协助日军维持治安。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3d829a5877eb47a68351470b426e0d92','77a789268c6f47b4a617cdb9e41180bd',1935,'伪满国务总理大臣（曾管辖锦州地区）','作为伪满最高行政长官，对锦州、北镇地区的伪政权负有直接领导责任，推行奴化教育和经济掠夺。；作为伪满最高行政首脑，全面推行日本殖民统治，其政策覆盖锦州、黑山地区，支持日军镇压抗日活动。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a179ee971e97451589f893ce7ced24bb','79b17193512846a1a5bde9f5df22c926',1931,'伪满奉天省省长（曾兼管锦州地区）','在任期间配合日军对锦州、北镇地区进行“治安肃正”，镇压抗日武装。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f647a3e21a784ca0b5d0df1e377f9fd1','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪锦州地区保安队队长','率伪保安队多次围剿北镇、黑山一带的抗日义勇军，杀害多名抗日群众。','基层头目','hanjian');
