INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('104bcceb7bc846bbb6d9250e41926a10','6c5f2811c77d4f39b1ddb522f78f5e25',1937,'伪锦州省教育厅厅长','在锦州地区推行日语教育和奴化课程，删除抗日内容，迫害爱国教师。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('22d5860f160b46aeb63ccfcb1c8e1ddc','b8f5150658fd47f0a48c92aacb628181',1932,'伪满军政部总长（后反正）','1932年曾一度投敌，在锦州地区与日军合作，但不久反正，此条仅记录其投敌期间行为。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('82c6359bcda04f988c3e675409eb2176','84779a454ec74ec19985a1b53e006685',1931,'伪满洲国监察院院长（曾任奉天省省长）','在辽宁地区（含锦州、古塔周边）推行日满协和会，组织“宣抚”工作，协助日军清乡，破坏抗日地下组织。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b75d452471b64c0f98cc75df418c58ee','87b0aba74b9b4c5f8a515bd9270d23b4',1931,'伪满洲国参议府议长（曾任奉天省省长）','作为汉奸政客，在辽宁各地（包括锦州）为伪满政权网罗旧官僚，参与制定奴化教育政策，镇压反满抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7e8baf7cc5b1449c85afaf86f70ba514','589ab27feed347c6944e6c001125dc02',1934,'伪锦州省省长（伪满时期）','在锦州、古塔地区主持伪省政，推行日伪“治安肃正”计划，强征劳工，配合日军对辽西抗日根据地进行“围剿”。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('41b65e05eaca4e288e00a2513c138fa0','875c22d678e24c21834a32caae69933c',1931,'伪满洲国宫内府大臣（曾任吉林省政府顾问）','虽主要活动于吉林，但曾参与对锦州地区伪军的整编和训练，为日军在辽西的军事行动提供支持。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('240e1bf9736549b49064e87f1a8b0fbc','236b09af126745e997e5603fc3f56d0e',1934,'伪锦州省民生厅厅长','在古塔地区推行奴化教育和“勤劳奉仕”制度，强征青年为日军服务，协助日伪进行思想控制。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('26f3683323a3478b9b0972c7aafd4d07','79b17193512846a1a5bde9f5df22c926',1931,'伪满洲国民政部总长、伪奉天省省长','辽宁沈阳人，九一八事变后被俘投敌，历任伪奉天省省长、伪满洲国民政部总长等职，参与伪满政权对辽宁地区的统治。；被俘后投敌，历任伪满民政部总长、伪奉天省省长等职，参与伪满政权建设，其政策影响涉及黑龙江地区。；原辽宁省主席，九一八事变后被日军扣押，后投降并出任伪奉天省省长、伪满民政部总长等职，参与伪满殖民统治，对东北包括黑龙江地区的伪政权运作有重要作用。；被日军俘获后投降，历任伪奉天省省长、伪民政部总长等职，参与伪满政权建设，推行日伪法令，镇压抗日民众。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d834761dd0644875bd1a0f99c98c03e8','e25c85c91f604ceda710a0637532c900',1931,'伪满洲国吉林省省长、伪第四军管区司令','辽宁人，原东北军将领，1931年投敌，历任伪吉林省省长、伪第四军管区司令等职，参与镇压辽宁、吉林抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('753439dc313e4ff88e103046f9801ce4','875c22d678e24c21834a32caae69933c',1931,'伪满洲国财政部总长、伪吉林省省长','辽宁沈阳人，清朝宗室，九一八事变后投敌，历任伪吉林省省长、伪财政部总长等职，为伪满政权重要成员。；九一八事变后率先投敌，主持伪吉林省军政，配合日军侵占黑龙江等地，为伪满初期重要汉奸之一。；九一八事变后率先投敌，以吉林省军政长官身份迎接日军进入吉林，后任伪满财政部总长、伪吉林省省长等职，积极参与伪满政权建设，其影响波及黑龙江地区。；九一八事变后率先投敌，协助日军侵占吉林，后任伪满财政总长等职，为日伪政权筹措资金，支持殖民统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9a3ee31d973646f1a3026a8f45c1c982','af99649b3f3a4c5382ec79666bf2647d',1931,'伪满洲国交通部大臣、伪锦州省省长','辽宁人，九一八事变后投敌，曾任伪锦州省省长，直接参与锦州地区伪政权统治，后任伪交通部大臣。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fbbcbddaf5c646a49243a33d27e31a66','c9dffc071fec4ce58fe1d611f26c28da',1931,'伪锦州省警务厅厅长、伪锦州省省长','辽宁锦州人，九一八事变后投敌，长期在锦州地区任职，历任伪锦州省警务厅厅长、伪锦州省省长，镇压当地抗日活动。','省部级/大军区级要员','hanjian');
