INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7a07c1b17c3f4f448781dffc856e8edb','e913aea565d54f398ad14deb4526d3a9',1932,'伪满交通部大臣（管辖阜新地区铁路运输）','负责伪满交通体系，为日军运输阜新煤炭和军事物资，便利日军对彰武等地的军事控制。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ee0c9b803a964375bc18ab3e20040f32','caae33d173854bf0a1b2b4f0db4f585a',1934,'伪满奉天省省长（阜新、彰武曾属奉天省）','任伪奉天省长期间，推行保甲制度，协助日军清剿抗日力量，强征阜新地区劳工。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f0f5e79a40a14b81b186697e30403bd9','5cce8fcbbcc043c2820499553d6999c1',1937,'伪满锦州省省长（彰武县曾属锦州省）','在彰武地区推行“粮谷出荷”政策，强征粮食，配合日军“讨伐”抗日游击队。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c826758c1dfc41e9a344f35bdd3ed57b','589ab27feed347c6944e6c001125dc02',1933,'伪满阜新县县长（1933-1937）','投靠日军后任阜新县伪县长，协助日军建立伪政权，强征民夫修建军事设施，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('468560f81a214b6f9fde1dea9417905a','21853206ad2b417598d1af0b4b3a4782',1933,'伪满彰武县县长（1933-1938）','任彰武伪县长期间，为日军提供情报，组织伪警察抓捕抗日志士，强征土地和粮食。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('462db60f625146ffab37d529a716acd5','41502657c6b84465aa2ff94e620ed234',1937,'伪满民生部大臣（曾管辖阜新劳工政策）','制定伪满劳工政策，导致大量阜新、彰武农民被强征为苦工，死于煤矿和军事工程。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f79f8831cd0845fb8eff7e944d6cbd9d','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满经济部大臣（阜新煤矿掠夺参与者）','参与策划阜新煤矿的“统制”经营，帮助日本垄断煤炭资源，压榨中国矿工。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('49b259cdb55242afb1dba2ed52e6b4db','360451ccb61f491bafdc1b28af3c6799',1932,'伪满外交部大臣（曾处理阜新地区外交事务）','为伪满政权辩护，协助日本在阜新、彰武地区建立殖民秩序，镇压反抗。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('48b52b2b681f4b008daa3dd2e7a9201f','77a789268c6f47b4a617cdb9e41180bd',1935,'伪满国务总理大臣（统辖阜新、彰武地区）','伪满最高行政头目，全面配合日本对阜新、彰武的殖民统治，签发多项迫害当地民众的法令。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b638094b9f584c9b9c1dfc4ab2b0f618','79b17193512846a1a5bde9f5df22c926',1932,'伪满参议府议长（曾参与阜新地区政策制定）','参与伪满高层决策，支持日军在阜新、彰武的“治安强化”运动，导致大量抗日人员被杀。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0e02ee697f4b48dc82ac1272adc807b1','875c22d678e24c21834a32caae69933c',1932,'伪满宫内府大臣（曾参与阜新地区皇产掠夺）','协助日本皇室和财阀侵占阜新地区土地和矿产资源，破坏当地经济。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('68fc92cbd97a460b954b40d5f24c3027','b8f5150658fd47f0a48c92aacb628181',NULL,'无','无','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dfd34dd7b57048358c15bebe0ebf0a60','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洲国军洮辽镇守使、伪热河省警备司令','九一八事变后投敌，率伪军配合日军进攻辽西、热河，其部队活动范围覆盖阜新周边地区，参与镇压抗日武装。；原为东北军将领，九一八事变后投敌，参与进攻黑龙江、热河等地，其伪军活动范围覆盖辽西、阜新周边地区，配合日军镇压抗日武装。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('776f4cdf74724b3895c7bbcdfafdb786','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满洲国军辽西地区警备司令','率伪军在辽西包括阜新、新邱一带执行治安肃正，镇压抗日民众，强征劳工。；原东北军军官，投敌后任伪军司令，在辽西阜新、朝阳地区配合日军扫荡抗日义勇军，强征劳工、掠夺资源。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e178beb833bc4656a9d77c90ae6cd52a','21853206ad2b417598d1af0b4b3a4782',1931,'伪满洲国军旅长、伪安奉地区警备司令','原东北军军官，投敌后率部在辽宁西部及阜新周边进行扫荡，残害抗日人员。；原东北军军官，1931年投敌，率伪军在辽宁东部及辽西地区围剿抗日武装，其部队曾活动于阜新、彰武一带。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('14bdec30ddee418e849460e2c26c5438','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满洲国立法院长、伪奉天市长','积极参与伪满洲国建立，在辽宁推行殖民统治，其政策影响包括阜新在内的辽宁各地。；九一八事变后投敌，参与伪满建国活动，任伪奉天市长期间在辽宁地区推行亲日政策，其活动涉及阜新周边。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('72bdb2954099439c89c8b72f9e7582d3','79b17193512846a1a5bde9f5df22c926',1931,'伪满洲国民政部大臣、伪奉天省长','原辽宁省主席，被俘后投敌，任伪奉天省长期间推行保甲连坐，镇压辽宁抗日活动，阜新地区亦在其管辖下。；原辽宁省主席，被俘后投敌，任伪奉天省长、伪满民政部大臣，参与推行殖民统治，其政策影响黑龙江地区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('752d92fc7a76442aa0f63c8b8d7cccb0','3d3728c118db4af09e7ec2e9b5412070',1930,'伪满洲国阜新县县长','任伪阜新县县长期间，配合日军征粮、征劳工，推行保甲制度，镇压当地抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('be34109ad7c74630ba96d7056ccbff0b','999302453e064cd2a62cc8e03232bdc7',1931,'伪阜新县维持会长','九一八事变后组织阜新县维持会，迎接日军占领，协助建立伪政权，搜捕抗日人士。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fe87c63fbc764d61a88431b244d5159e','fe7588d226fa430ea2eda3d08a162f2f',1930,'伪新邱煤矿警备队长','在新邱煤矿区担任伪警备队长，残酷压迫矿工，配合日军镇压矿工反抗，抓捕抗日地下工作者。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9f58fdca29cf4fc19129007479b11555','17ba4ca514844dcbb95b21c193e11290',1936,'伪满洲国阜新炭矿株式会社劳务系主任','负责新邱等煤矿劳工征募与管制，虐待劳工，强制劳动，导致大量矿工死亡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('afb005bb743e4a798ab97a392edc3519','1b0d93051c8343ec93855ecd4624a43f',1930,'伪阜新县警察署长','在阜新县及新邱地区执行治安肃正，抓捕抗日人员，刑讯逼供，残害百姓。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b2d985717cdc48938c5514ea05614a95','947e40126da44888a92dd5a7ee7d0256',1930,'伪满洲国军阜新地区警备队长','率伪军在阜新、新邱一带围剿抗日武装，烧毁村庄，杀害抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('37f9d1c58eb242c3817c80471f24e01f','3ecd2d6597904f268fe7636e66faec27',1930,'伪阜新县协和会长','在阜新推行协和会运动，进行奴化教育，协助日军控制民众思想，检举抗日分子。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('633ad749838e400f9bee552b89f6ba65','bf4f717904fb417898560044b3a2acb6',1930,'伪新邱保甲长','在新邱地区担任保甲长，为日军征粮、征丁，监视村民，迫害抗日家属。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b936cd7725cb45259527a2fd978d0528','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满洲国阜新市警察局局长','在阜新地区积极协助日本宪兵队镇压抗日武装，抓捕抗日志士，推行“治安肃正”政策，强征劳工开采阜新煤矿，造成大量矿工死亡。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4184706a74eb420689f1df3f54f1d5d8','1ba31d558b934fbd83a28a8c2b446022',1933,'伪满洲国热河省省长（管辖阜新地区）','原东北军将领，后投靠日本，任伪热河省省长期间，配合日军对阜新、海州地区进行殖民统治，强征民夫修建军事设施，镇压抗日义勇军。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('03c801ba914840e5b33f70a8f4740c49','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满洲国立法院院长（曾参与阜新地区殖民政策制定）','作为伪满高层，参与策划对阜新煤矿资源的掠夺性开采，支持日本“满炭”公司对海州矿区的控制，迫害当地矿工。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2d3ae7bac5904ac897e0aeecddfc196a','84779a454ec74ec19985a1b53e006685',1932,'伪满洲国监察院院长（曾负责阜新地区矿务监督）','协助日本关东军管理阜新、海州矿区，推行“以华制华”政策，组织汉奸矿警队镇压矿工反抗，克扣矿工口粮。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d5b6f462575145d6a69fb88ec78ff277','e913aea565d54f398ad14deb4526d3a9',1932,'伪满洲国交通部大臣（管辖阜新铁路运输）','负责将阜新海州煤矿的煤炭通过铁路运往日本，为日军战争机器提供资源，同时参与强制征调劳工修筑铁路，导致大量劳工死亡。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dc74a08d85b241c4a1c160cb705eefdb','360451ccb61f491bafdc1b28af3c6799',1937,'伪满洲国经济部大臣（主管阜新矿业开发）','积极推动日本对阜新海州露天煤矿的“重点开发”，签订掠夺性合同，压低矿工工资，造成矿区环境严重破坏和人员伤亡。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6e3c24ff55054929bea6ce72eb0ab32a','3b74f508628f475a8777ffb7e38a48a0',1934,'伪满洲国奉天省省长（阜新地区隶属奉天省时期）','在任期间配合日军对阜新地区进行“清乡”，组织汉奸保甲制度，强征青年为伪军，并协助日本企业霸占阜新矿区土地。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('760304fccdee45bfac3b8bb9a6ea0502','5cce8fcbbcc043c2820499553d6999c1',1933,'伪满洲国阜新县县长','直接执行日本殖民政策，强征农民土地给“满炭”公司，强迫村民迁出矿区，对反抗者进行残酷镇压，多次协助日军屠杀平民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('568e30eafc1648da96dcd05041b6f98b','21853206ad2b417598d1af0b4b3a4782',1935,'伪满洲国阜新市协和会会长','宣传“日满亲善”，组织汉奸团体刺探抗日情报，协助日军抓捕地下抗日分子，并参与“勤劳奉仕”运动，强迫民众无偿劳动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8d9484ee02f54e21b7af15acd20fa04a','589ab27feed347c6944e6c001125dc02',1936,'伪满洲国阜新矿务局总办（海州矿区实际管理者）','作为日本“满炭”公司代理人，负责海州露天矿的日常管理，制定严苛劳动制度，克扣矿工工资，导致矿难频发，死亡矿工被草草掩埋。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d947ea652f964629b1de043ae48b9711','77a789268c6f47b4a617cdb9e41180bd',1935,'伪满洲国国务总理大臣（名义上管辖阜新地区）','作为伪满最高行政长官，签署多项出卖阜新矿产资源的法令，支持日本关东军对海州地区的军事管制，对矿区抗日活动进行镇压。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cfa54364b703405fa5b7469547fc4af5','79b17193512846a1a5bde9f5df22c926',1932,'伪满洲国参议府议长（曾参与阜新地区殖民规划）','参与制定阜新地区“产业开发五年计划”，推动日本资本全面控制海州煤矿，协助日军建立矿区“无人区”，驱逐当地居民。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('237f934262d94e76be8b32d26b0ef440','79b17193512846a1a5bde9f5df22c926',1931,'伪满洲国民政部总长、伪奉天省长','原辽宁省政府主席，1931年被俘后投敌，任伪奉天省长期间推行保甲制、征集劳工，直接管辖阜新等县，配合日军掠夺煤炭资源。；九一八事变后投敌，历任伪奉天省长、伪满洲国民政部总长等职，参与伪满政权对东北包括黑龙江地区的统治。；原东北军将领，九一八事变后被俘投敌，历任伪奉天省长、伪民政部总长等职，参与伪满对东北地区的殖民统治。；辽宁沈阳人，九一八事变后被俘投敌，历任伪奉天省长、伪满民政部总长、参议府议长等职，为伪满核心汉奸之一。；原东北军将领，被俘后投敌，历任伪满民政部总长、奉天省长等职，参与伪满政权对东北人民的统治。；辽宁沈阳人，九一八事变后被俘投敌，历任伪奉天省长、伪满洲国民政部总长等职，协助日本推行殖民统治，其活动范围涉及东北全境。；九一八事变后被日军逮捕后变节投敌，出任伪奉天省长，后任伪满洲国民政部总长、参议府议长等职，参与制定和推行伪满各项殖民法令，其影响波及黑龙江地区。；辽宁沈阳人，九一八事变后被俘投敌，历任伪奉天省长、伪满洲国民政部总长、参议府议长等职，为伪满政权核心人物之一。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1702539d0522400db92f448f454c8438','d27510bc381c41f3a0ec4fba74ca2fea',1930,'伪阜新县县长','伪满时期任阜新县县长，推行保甲制、粮谷出荷、劳工征集等政策，直接配合日军对阜新煤矿的掠夺，镇压当地抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('317c0b1cffbb4305b8546fd14a07da65','999302453e064cd2a62cc8e03232bdc7',NULL,'伪阜新县维持会会长','九一八事变后组织阜新县维持会，迎接日军占领，协助建立伪政权，为日军提供物资与情报，压迫当地民众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1db65965714349d9a5dd736ba46b3674','fe7588d226fa430ea2eda3d08a162f2f',1930,'伪清河门保甲长','伪满时期任清河门地区保甲长，负责摊派捐税、征集劳工、监视民众，配合日伪军警镇压抗日分子，维护殖民统治。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('029161c92300406bb25c5469eafc87bf','b8f5150658fd47f0a48c92aacb628181',1932,'伪满洲国军政部总长（后反正抗日）','1932年一度投敌任伪满军政部总长，但同年即反正重新抗日；其短暂附逆期间涉及辽宁地区伪军政事务，后成为抗日将领。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('135f5414794a444eb7f8a305eb973060','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洲国热河省警备司令、伪满军上将','原为东北军将领，九一八事变后投敌，参与进攻热河、长城抗战，长期在辽西、阜新一带配合日军围剿抗日武装。；原东北军将领，九一八事变后投敌，率伪军配合日军进攻黑龙江，参与江桥战役对马占山部的作战，后任伪热河省警备司令等职。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cc35139fc42d46aa9296898bc4266092','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满洲国奉天省警备司令、伪满军上将','原东北军东边道镇守使，1931年投敌，率部在辽宁西部、阜新周边地区镇压抗日义勇军，后任伪满军政部大臣。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('42a27a922ce44f72b123c3f8ad8e6ea0','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满洲国阜新县县长、伪协和会阜新县会长','在阜新县推行保甲连坐、强征劳工、掠夺煤炭资源，配合日军在细河一带清乡，镇压抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8e155a64c51245fdb757c5ee7bb9548c','5f82d23ccd2e45fd9e59f76c92bcc9ad',1933,'伪蒙古军总司令、伪满洲国热河省警备军司令','率伪蒙古军活动于热河、辽西、阜新北部，配合日军扫荡抗日武装，强征物资，残害百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('608399482b794e42ad9e2aae85d9c774','177c17b9b440453fa41ed47b9ebbd502',1933,'伪满军旅长、土匪武装头目','原为土匪，投靠日军后活动于阜新、朝阳、锦州一带，烧杀抢掠，配合日军围剿抗日根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('495bde73056a42949b8a1c6f8edc6c40','79b17193512846a1a5bde9f5df22c926',1931,'伪满洲国民政部大臣、伪奉天省省长','原辽宁省主席，1931年被俘后投敌，任伪奉天省长期间在辽宁各地推行保甲、征粮、劳工政策，波及阜新。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('12515a8644dd4664bbd31ff97ada72e4','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满洲国立法院长、伪奉天市市长','积极参与伪满建国活动，在辽宁推行亲日教育、经济掠夺政策，影响包括阜新在内的辽宁各地。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('31a4df3fdcea47c7bb556733b401e009','eb688993f9ee49a7bbacda2253de406a',1936,'伪满洲国阜新炭矿株式会社理事长','管理阜新煤矿，强征中国劳工，实施残酷压榨，导致大量矿工死亡，配合日军掠夺煤炭资源。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('366c2a3b90e940ea971edacbabbae07e','d2b7a71572c34ce0943d2a891b842d96',1935,'伪阜新县警务科科长、伪警察大队长','在阜新县及细河地区指挥伪警察讨伐抗日武装，实施保甲连坐，抓捕抗日群众，罪行累累。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cbf2e69bb1264821b50ba6b8f82e06d0','36402d4671dc45b89ef970ce78ad4ab8',1937,'伪阜新县协和会事务长','在阜新推行奴化教育，组织亲日宣传，协助日军征劳工、征粮，控制细河一带民众。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0bb75a4f0ad04566b7f7b7a7cd1aa26d','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满洲国鞍山市长（一说为伪鞍山县长）','在鞍山地区担任伪职，配合日军掠夺鞍山铁矿资源，强征劳工，压迫当地民众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1d0f5a89a1f141bd9554c1497ca4c62d','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洲国热河省省长、伪满军事部大臣（曾活动于辽南）','原奉系军阀，投日后在辽南一带协助日军清剿抗日义勇军，后调任伪满中央要职。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('790e3737ff85464483b49af725b069c0','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满洲国立法院院长（原籍辽宁，曾参与鞍山地区殖民统治）','积极鼓吹“满洲独立”，参与伪满政权立法，为日本侵略提供法律依据，影响鞍山地区。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bfc6e084438a4d668604590c2b9a20cf','87b0aba74b9b4c5f8a515bd9270d23b4',1931,'伪满洲国参议府议长（辽宁籍，曾参与辽南政务）','清末民初政客，投靠日本后任伪满高官，参与策划对辽宁地区的殖民统治。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4a835e5bfe1c450085efb6fecb7e92a6','79b17193512846a1a5bde9f5df22c926',1931,'伪满洲国奉天省省长（后任伪满民政部大臣）','原奉天省主席，九一八后被俘投敌，在奉天（含鞍山地区）推行日伪政策，镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('37b6dee0699d477990b85139fd2d3737','875c22d678e24c21834a32caae69933c',1931,'伪满洲国财政部大臣、宫内府大臣（曾涉足辽南）','清室后裔，投日后参与伪满建国，协助日本控制辽宁经济资源，包括鞍山铁矿。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a9b64c7ec6c645cb950222ddc5f02627','84779a454ec74ec19985a1b53e006685',1932,'伪满洲国监察院院长（辽宁籍，曾参与鞍山地区事务）','原奉系官员，投日后任伪满监察院长，为日本在鞍山等地掠夺资源提供行政支持。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('709be5eb516b4a59986a8fc547b105d2','e913aea565d54f398ad14deb4526d3a9',1932,'伪满洲国交通部大臣（辽宁籍，曾负责辽南铁路）','投日后管理伪满交通，协助日军运输军事物资和掠夺鞍山钢铁资源。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2564bcc6a50640979fb629b60fdab393','caae33d173854bf0a1b2b4f0db4f585a',1932,'伪满洲国奉天省警务厅长（管辖鞍山地区）','负责奉天省（含鞍山）伪警察系统，抓捕抗日志士，镇压民众反抗。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aa02cddf576242048e3b9c333f385da0','93bb41424b15404cbf5d5f2b97e0bc0c',1931,'伪鞍山地方维持会会长（具体任职待考）','九一八后组织地方维持会，协助日军接管鞍山，维持殖民秩序。','基层维持会/地方自治头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4353a31ebc4a41cd89d95b840a6451f7','21853206ad2b417598d1af0b4b3a4782',1932,'伪鞍山保安队队长','率伪保安队配合日军扫荡鞍山周边抗日义勇军，残害百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('49366ec707884212bbd3defc64f5d269','875c22d678e24c21834a32caae69933c',1932,'伪满宫内府大臣、汉奸','积极参与伪满建国，曾任伪满财政部总长，后任宫内府大臣，对辽宁地区殖民统治有重要影响。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('becb682c02214c679b32649feaf317a2','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满奉天省实业厅厅长、汉奸','在伪奉天省任职期间，协助日本掠夺鞍山地区铁矿资源，压迫当地矿工。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('17ed6a00b7ec4315bf5a05136a28dfb1','589ab27feed347c6944e6c001125dc02',1932,'伪满奉天省警务厅厅长、汉奸','负责伪奉天省警察系统，镇压千山地区抗日武装，逮捕抗日志士。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2beaa88318564d87bb3ac2162a322b1b','21853206ad2b417598d1af0b4b3a4782',1932,'伪满鞍山地区保安队队长、汉奸','在鞍山地区组织伪保安队，协助日军维持治安，参与围剿抗日游击队。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('17f9986c18fc401cae6eeee9947922c8','1ba31d558b934fbd83a28a8c2b446022',1933,'伪满热河省省长、汉奸','虽主要活动于热河，但曾率伪军参与对辽宁千山地区抗日力量的清剿。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bc47629b50e545b481b1f07f99a9e909','c9dffc071fec4ce58fe1d611f26c28da',1937,'伪满鞍山宪兵队翻译、汉奸','在鞍山宪兵队担任翻译，协助日军审讯和迫害抗日人士，民愤极大。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('73abf7c943e64609bb8dc4ec5f2af2a9','3cd55e29febc489d9f9a7f2f88db31bb',1931,'伪满千山地区维持会会长、汉奸','九一八后组织千山地区维持会，为日军提供粮食物资，出卖抗日情报。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c991d06e779e468bb6814b4fc82f7c94','a2c03b81e5f2412bb86f5d5599c1687b',1933,'伪满鞍山铁矿监工、汉奸','在鞍山铁矿为日本监工，残酷虐待中国劳工，造成大量矿工死亡。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('301d3475dccc4074bb66a285b41c4687','2caaa8fc4c1d4c9cac6c3cc0c4b0508d',1931,'奉系军阀将领（后投日）、汉奸','虽早年是奉系，但九一八后曾与日本秘密接触，试图在辽宁地区建立傀儡政权，后因内部矛盾未果。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('160bde67f183415284b9008f6a08fbc4','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满奉天省省长、伪满第一军管区司令','原东北军旅长，叛变后任伪满奉天省（含鞍山、台安地区）最高军事长官，多次指挥伪军“讨伐”抗日义勇军，残害民众。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cb46be570d4f45af9220131b8fa5dc23','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满鞍山地区警务处长','在鞍山及台安一带组织伪警察和保甲制度，配合日军抓捕抗日人员，强征劳工，镇压反满抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2c664c3f01a245f9a4a93d6fbe4ac2df','21853206ad2b417598d1af0b4b3a4782',1933,'伪满台安县县长','在台安县推行伪满殖民政策，强制收缴民间枪支，组织“自卫团”协助日军清乡，迫害抗日家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('173da80c203e448b85a9c9802bbc238f','360451ccb61f491bafdc1b28af3c6799',1935,'伪满交通部大臣、伪满奉天省省长','在任奉天省长期间，强化对鞍山、台安等地的殖民统治，推动“粮谷出荷”和劳工统制，导致当地民众饥荒。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('243f868bad504a8a8a2eaa5a3f24f6ad','0639407f8320412e86eada632a47d380',1937,'伪满鞍山宪兵队翻译官','为日军宪兵队充当翻译，参与审讯和刑讯抗日志士，多次带队到台安地区抓捕地下抗日人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4496106b32974e9faa5a26d886ec6737','3cd55e29febc489d9f9a7f2f88db31bb',1938,'伪满台安地区“协和会”会长','积极宣传“日满亲善”，组织青少年奴化训练，告发抗日嫌疑分子，协助日军建立“集团部落”。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c5cdcca8c373437ab1d827ce857c72e9','77a789268c6f47b4a617cdb9e41180bd',1931,'伪满国务总理大臣（原奉系将领）','作为伪满最高行政首脑，其政策直接支配辽宁各地，包括鞍山、台安，支持日军“讨伐”和资源掠夺。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8deabeba7ed94dd3ba7eddda88e0dfa5','79b17193512846a1a5bde9f5df22c926',1931,'伪满参议府议长（原奉天省长）','九一八后投敌，参与策划伪满建国，在辽宁地区推行“治安维持法”，对鞍山、台安抗日活动进行镇压。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3fddd6759f9c4f7d9fd9c97a2bae1c6f','c9dffc071fec4ce58fe1d611f26c28da',1931,'伪满鞍山地区维持会会长','鞍山本地豪绅，日军占领鞍山后出任维持会会长，协助日军征粮、抓劳工，镇压当地抗日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ddc1e945afdc41728af6a8af4e42766e','21853206ad2b417598d1af0b4b3a4782',1932,'伪岫岩县县长','原岫岩县地方官员，投日后任伪县长，推行保甲制度，配合日军清乡，抓捕抗日志士，强征民夫修建军事设施。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e0ef6df0e79f4627b407d3751af4a567','a5cb29255d0649d1849f243b2af30472',1933,'伪岫岩县警务科科长','原岫岩警察，投日后任伪警务科长，组织伪警察队，多次参与对抗日武装的“讨伐”，杀害多名抗联侦察员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('15664814aaa049918d1e7d6da1f93087','54ed3d5811124de1a4f4c9e1d7ad39d8',1935,'伪满鞍山宪兵队翻译官','鞍山人，精通日语，任日军宪兵队翻译，参与审讯和刑讯抗日人士，直接导致多名地下党员牺牲。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aefef16ba3be4c1e9c0438131f83359b','4bf59a34c5e6486485b730a6f2636bcf',1934,'伪岫岩县保安团团长','地主武装头目，投日后任保安团长，率团丁配合日军扫荡，烧毁抗日村庄，掠夺百姓财物。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8e84a0ca29de4029bcc5d886720b3ee0','27058a945c504a2f853b049422d35340',1936,'伪满鞍山地区协和会会长','鞍山富商，任伪协和会会长，为日军宣传“王道乐土”，组织“献金”活动，资助日军军费。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('260005ac152f4fc6b0a98a2c9adb506e','5a9e800efe5a400492466b6f0ab8e7b6',1932,'伪岫岩县教育局长','原岫岩教育界人士，投日后任伪教育局长，强制推行奴化教育，删除中国历史教材，灌输亲日思想。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0f861250fe974179b3a58e7e62159280','84779a454ec74ec19985a1b53e006685',1931,'伪满鞍山铁矿株式会社总办','原鞍山铁矿中方经理，投日后任伪总办，为日军掠夺鞍山铁矿资源，强迫中国劳工超负荷劳动，造成大量死亡。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3df8906cd2964e04a73be8890c56ce13','13d0486d273d4095ad0df79a94a6d418',1932,'伪满岫岩地区“剿匪”司令','原地方民团首领，投日后任伪“剿匪”司令，专门围剿岫岩山区抗日义勇军，手段残忍，曾屠杀村民。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c73ea0d9b95b4ccd8422b11b1ef18f0a','b442da767bab48bc88e7be9ad4618895',1933,'伪满鞍山地区警察署署长','原鞍山巡警，投日后任伪警察署长，设立多处“留置场”（拘留所），严刑拷打抗日嫌疑犯，并协助日军抓捕抗联交通员。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5adda9ae105e4ec4a06854cb1c3c9863','589ab27feed347c6944e6c001125dc02',1932,'伪岫岩县财务局长','原岫岩县财务官员，投日后任伪财务局长，为日军征收各种苛捐杂税，搜刮民财，供给伪军和日军。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4450bd9c1a1043818aad80c0a519936d','7ca60279616445fcaa58c2399291ebcb',1933,'伪满参议府参议（曾涉辽宁地区）','原奉系将领，虽名义上未任伪职，但实际与日伪合作，其旧部在鞍山、岫岩地区组织伪军，间接助敌。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('de814a44fae74340a49f828000dc725e','5cce8fcbbcc043c2820499553d6999c1',1935,'伪满岫岩县协和会事务长','岫岩本地人，任伪协和会事务长，组织“青少年团”进行军事训练，为日军输送伪军兵源。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cb969a54bb67472ca7afa7e5ad6633c5','8c7ad815e8af49d29cdc263253ce9122',1934,'伪满鞍山地区“自卫团”总团长','鞍山郊区地主，投日后组织“自卫团”，配合日军封锁山区，切断抗联补给线，并参与屠杀抗日家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e6640dc2d50a4fc098502715b8ceea31','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满立法院院长（曾管辖辽宁司法）','原奉天律师，投日后任伪满立法院院长，制定镇压抗日活动的法令，其司法体系覆盖鞍山、岫岩地区。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6dc17b860c0f42bab56a44681b467b34','3b74f508628f475a8777ffb7e38a48a0',1938,'伪满鞍山地区“勤劳奉仕”总队长','鞍山商人，投日后任“勤劳奉仕”总队长，强征中国青壮年充当劳工，送往矿山和军事工地，致多人死亡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bc8f2aee570a4edd88648d7238f24718','77a789268c6f47b4a617cdb9e41180bd',1931,'伪满军政部大臣（兼）','已列，但需注意其曾直接下令伪军参与岫岩地区“讨伐”行动。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('efe0475694d44c08b812704a88bc2f6e','e1badd3fe14246acb4a3d2bf765b2db2',1932,'伪满司法部大臣（涉辽宁）','原北洋政府官员，投日后任伪满司法部大臣，其推行的“治安维持法”在鞍山、岫岩地区被用于迫害抗日人士。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1014e0c6a63f43a8ba3585204e668b5a','87b0aba74b9b4c5f8a515bd9270d23b4',1931,'伪满参议府议长（辽宁籍）','辽宁辽阳人，投日后任伪满参议府议长，虽居高位，但曾为日军在鞍山、岫岩地区建立伪政权出谋划策。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c687c10d53204462a670f8ff8e745e2f','15b0ffb0c3064aa4a57d4d84ac82b7fa',1933,'伪满鞍山地区“靖安军”顾问','原东北军军官，投日后任伪“靖安军”顾问，参与训练伪军，并随军到岫岩山区扫荡。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b16295f8e5604954a1df9b88a3abbd27','e409ef959281461b91e8ce1eef37d186',1932,'伪满军事部次长（涉辽宁）','原东北军参谋长，投日后任伪满军事部次长，负责指挥伪军镇压辽宁各地抗日武装，包括鞍山、岫岩地区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d1ec8ae4826b4f0dad05014987ec0cc5','875c22d678e24c21834a32caae69933c',1931,'伪满宫内府大臣（曾涉辽宁）','原吉林军将领，投日后任伪满宫内府大臣，虽非直接管辖鞍山、岫岩，但其伪军系统曾调兵至该地区作战。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4a6e40566d174b678b7bfa55438d14d8','c0860f9060d74dfba1674157f4596712',1932,'伪满第五军管区司令官（驻辽宁）','原东北军旅长，投日后任伪第五军管区司令官，驻防辽宁南部，多次率部进攻岫岩、鞍山一带的抗联部队。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('59b6def1db824ac2b3499fd74c25723a','142849ebf8614017a075f60e0d2e7e40',1934,'伪岫岩县警察大队大队长','原岫岩县警佐，投日后任伪警察大队长，率伪警参与“归屯并户”，制造无人区，切断抗日武装与百姓联系。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('37cce2f95c244b2e9f0c62cb6dbcfeab','3cd55e29febc489d9f9a7f2f88db31bb',1937,'伪满鞍山地区“宣抚班”班长','鞍山汉奸文人，任伪“宣抚班”班长，随日军到各村进行“宣抚”，诱骗百姓归顺日伪，出卖抗日情报。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ea0a5f550f874fb19ccd5e7fc86f4c74','6af8c3df19e545d4a3f1c03cb0186b18',1933,'伪岫岩县商会会长','岫岩大商户，投日后任伪商会会长，为日军筹集物资，并强迫商户“献金”，资助伪军购买武器。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4e68d865f81d47cc9774791098019d75','a2c03b81e5f2412bb86f5d5599c1687b',1939,'伪满鞍山地区“青年训练所”所长','鞍山教育汉奸，任伪青年训练所所长，对青年进行军事化奴化训练，为日军培养伪军后备力量。','无明确职位或一般帮凶','hanjian');
