INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('33231dc72ef5448fac8a69dd446a0721','8c7ad815e8af49d29cdc263253ce9122',1934,'伪满鞍山地区“自卫团”总团长','已列，补充其曾杀害抗联伤员。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('23bfd84c7d6343ba891dd645b8c7802d','3b74f508628f475a8777ffb7e38a48a0',1938,'伪满鞍山地区“勤劳奉仕”总队长','已列，补充其曾将劳工卖给日本矿山。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c8fc0a56d8254ffa9cc202e80e93ef34','142849ebf8614017a075f60e0d2e7e40',1934,'伪岫岩县警察大队大队长','已列，补充其曾参与“大讨伐”。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3c7796ee594b4c2cb561189a702f913b','3cd55e29febc489d9f9a7f2f88db31bb',1937,'伪满鞍山地区“宣抚班”班长','已列，补充其曾诱骗儿童当间谍。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c031015000c74059a4c5aab88432367d','6af8c3df19e545d4a3f1c03cb0186b18',1933,'伪岫岩县商会会长','已列，补充其曾垄断粮食贸易。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('eb717e63288645f39707bf6df19826d7','a2c03b81e5f2412bb86f5d5599c1687b',1939,'伪满鞍山地区“青年训练所”所长','已列，补充其曾强迫青年宣誓效忠天皇。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('21d93a164faa4582869ef3f8ede5ac87','236b09af126745e997e5603fc3f56d0e',1935,'伪满鞍山地区“铁路护路队”队长','已列，补充其曾协助日军运输军火。','基层头目','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fbab02d5c0ea481d80c024850a036652','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满奉天省省长、伪满第一军管区司令官','原东北军旅长，1931年投降日军，任伪奉天省警备司令，后任伪满奉天省省长，在辽宁地区推行殖民统治，镇压抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b709f43f7b1d4dc191b6a0d65607c22e','c9dffc071fec4ce58fe1d611f26c28da',1931,'伪满鞍山地区治安维持会会长','鞍山本地豪绅，日军占领鞍山后出任伪治安维持会会长，协助日军征粮、抓劳工，为日本昭和制钢所（鞍钢前身）提供劳动力。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1556a26c1338408f8fff8ce5281343b8','21853206ad2b417598d1af0b4b3a4782',1932,'伪满海城县县长','原海城县地方官员，投敌后任伪海城县县长，推行保甲制度，强征民夫修建军事设施，配合日军清剿海城地区的抗日游击队。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7cd3478702ec46a8b2c9009e0f40bd71','0639407f8320412e86eada632a47d380',1932,'伪满鞍山警察署署长','原鞍山地区警察，投敌后任伪鞍山警察署长，多次参与抓捕抗日地下党员，破坏抗日组织，协助日军实行“治安肃正”。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8739239afb8442e9983cd49effbf5add','3cd55e29febc489d9f9a7f2f88db31bb',1933,'伪满海城保安队队长','海城地方武装头目，投敌后组织伪保安队，配合日军扫荡海城东部山区，杀害抗日义勇军战士及无辜百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0862204870a442d28166f6b009e004b9','5cce8fcbbcc043c2820499553d6999c1',1932,'伪满辽南地区“剿匪”司令','原辽南土匪头目，被日军收编后任伪“剿匪”司令，在鞍山、海城、岫岩一带围剿抗日武装，烧毁村庄，罪行累累。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2eb1c483c3904138b56d15c5b7963b70','84779a454ec74ec19985a1b53e006685',1931,'伪满鞍山昭和制钢所顾问、伪满中央银行监事','协助日本帝国主义控制鞍山铁矿资源，为昭和制钢所（今鞍钢前身）提供情报与资源调配，参与伪满经济统制政策，压榨中国劳工。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bf989b32bd0945a58728f97132231e7f','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满热河省省长、伪满军政部大臣（曾活动于辽南地区）','九一八事变后公开投敌，在辽宁地区协助日军镇压抗日义勇军，后任伪满要职，参与“治安肃正”行动，残害抗日军民。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('80952d18b1a643ee8c43f1ad37618629','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满鞍山地方警察署署长','在鞍山、立山地区积极执行日伪“保甲制度”，搜捕抗日地下工作者，多次带队围剿抗日游击队，并强迫居民“连坐”举报。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('495a4e603bd94085b3a8de163ba5e073','21853206ad2b417598d1af0b4b3a4782',1931,'伪满立山地区维持会会长','日军占领立山后主动组织维持会，为日军征集粮食、劳役，强征当地青壮年充当伪军，并协助日军建立“集团部落”以隔离抗日武装。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a614e174f15a44b789359fd2197d2dbc','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满立法院院长（曾参与辽南殖民统治策划）','虽主要活动于伪满中央，但多次赴鞍山、立山矿区“视察”，推动《满洲国劳动统制法》在鞍山实施，导致大量矿工因劳致死。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('83461a47ee564cf781aa713531efe5e6','1d67ff455ffc47b8addcc485beb0ca34',1932,'伪满第一军管区司令（管辖辽南包括鞍山地区）','率伪军配合日军在鞍山、海城、立山一带“讨伐”抗日义勇军，制造多起屠杀事件，并强迫农民“出荷”粮食支援日军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dae927dd71194214b2c2464472e603b9','f3f61c6d0206452580f068491d248d30',1938,'伪满鞍山铁矿株式会社劳务课长','负责从华北、山东强掳劳工至鞍山矿山，实行“以人换矿”政策，克扣口粮，导致数千劳工死亡，并参与镇压劳工暴动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3b7a90aa2e854cf2997818a5e851139d','3cd55e29febc489d9f9a7f2f88db31bb',1933,'伪满立山地区保安队队长','带领保安队为日军把守立山交通要道，多次截击抗日物资运输，并直接参与抓捕、刑讯抗日嫌疑人员，手段残忍。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c491ae57e2c040acaeb08a0f67f0d2e9','77a789268c6f47b4a617cdb9e41180bd',1935,'伪满国务总理大臣（曾多次巡视鞍山钢铁生产）','作为伪满最高行政头目，推动鞍山昭和制钢所扩大生产以供应日军军需，并批准在立山增设“矫正辅导院”，关押迫害抗日群众。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3dffde28198747519396df2da7688625','350822a1078340679fd657c16a793993',1937,'伪满鞍山地方检察厅厅长','依据《治安维持法》在鞍山、立山地区滥捕“思想犯”，判处大量爱国志士死刑或长期监禁，并协助日军“特别移送”至731部队。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('53c0d4eb646d4f57b9fdc53729d8d62f','84779a454ec74ec19985a1b53e006685',1931,'伪满鞍山昭和制钢所理事、伪满奉天省省长','曾任伪满鞍山昭和制钢所理事，后任伪满奉天省省长，积极为日本侵略者服务，压榨东北人民，协助日伪政权推行殖民统治。；曾任伪满鞍山昭和制钢所理事，后任伪满奉天省省长，积极协助日本侵略者掠夺鞍山铁矿资源，镇压抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('41a5c943c0004740a21be5cf442651a4','589ab27feed347c6944e6c001125dc02',1931,'伪满鞍山地方维持会会长','九一八事变后，在鞍山铁东地区组织地方维持会，协助日军维持秩序，为日本占领军提供情报和后勤支持。；在鞍山沦陷后组织地方维持会，为日军提供粮食、劳力和情报，协助建立伪政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('22211ef073c84f71a56b8a67457991d9','5cce8fcbbcc043c2820499553d6999c1',1932,'伪满鞍山警察署署长','任伪满鞍山警察署署长期间，残酷镇压抗日爱国人士，协助日军抓捕和刑讯地下抗日分子，在铁东地区制造多起白色恐怖事件。；在鞍山铁西地区任伪警察署长，残酷镇压抗日地下组织，抓捕爱国人士。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6fa7204b635c43799d5fbeac595667c5','21853206ad2b417598d1af0b4b3a4782',1933,'伪满鞍山铁东区区长','任伪满鞍山铁东区区长，强征劳工为昭和制钢所服务，克扣工人口粮，协助日军推行“粮谷出荷”政策，导致当地民众饥荒。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c26e7112419b4a12a1e6fad08cf3cc3c','c9dffc071fec4ce58fe1d611f26c28da',1931,'伪满鞍山保安队队长','原土匪出身，投日后任鞍山保安队队长，率队围剿抗日游击队，在铁东地区烧杀抢掠，杀害无辜百姓。；在鞍山铁西地区组织伪保安队，配合日军扫荡，杀害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('948321de6edc460aa663116adce46edb','87b0aba74b9b4c5f8a515bd9270d23b4',1931,'伪满奉天省省长','九一八后投敌，任伪满奉天省省长，管辖鞍山、铁西等地，协助日军建立保甲制度，强征劳工。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f43d9696849b463ba5cffea5cd5832e8','21853206ad2b417598d1af0b4b3a4782',1933,'伪满铁西区区长','任伪满鞍山铁西区区长，协助日军强征土地，建立军事设施，迫害当地居民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9a1af327a8c54b4199eac77cfe52d400','875c22d678e24c21834a32caae69933c',1931,'伪满财政部大臣','参与伪满政权建立，在辽宁地区推行金融统制，协助日本控制鞍山钢铁产业。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('45915d0cc6c3498eb0f419670da1d992','103ce81b67a940d4ab9979aae8824f91',1934,'伪满铁西地区协和会会长','任协和会铁西分会会长，推行奴化宣传，组织青年训练，为日军输送劳工。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fa12c2ea475b4ef899d3e80f8df83e45','b8f5150658fd47f0a48c92aacb628181',1931,'伪满黑龙江省省长（后反正）','一度投敌任伪职，但不久反正抗日，其在辽宁鞍山地区短暂活动期间未造成重大危害。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('030b2dbf4d9e474fa524a07bc9f5fa03','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满奉天省实业厅厅长','主管伪满奉天省（含鞍山铁西）工矿企业，协助日本昭和制钢所扩大生产，掠夺资源。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('62e984e89726436986ea541def0261e5','2a262f27f5df4bb493c9cf9285d13aa5',1937,'未任伪职，但被日方拉拢对象','作为川军领袖，抗战初期率部出川，病逝于汉口；日方曾试图拉拢四川地方势力，但刘湘未附逆。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2343259846ea4ab78ef6178ce0e23e9b','6058a91b52fd4d0aa64aeeea901b2fe1',1938,'四川省政府主席（抗战时期）','抗战期间任四川省主席，后因与蒋介石矛盾被撤职；无确凿附逆记录，但属重庆周边地方实力派。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('69bca9804595444894201ac37f58f239','d97f69ef50a24db3a7544f855c17488e',1937,'川军将领、地方袍哥首领','率部出川抗战，无附逆行为；但万州、重庆一带袍哥势力复杂，部分下层头目与日伪有勾结。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('986cdfc300de4b2aacfb9a1ed7eb4c94','82c8dc8c68f3449d85ce6770c252b411',1938,'万县维持会会长（疑似）','地方史料提及万县曾有维持会组织，但具体人名多不可考；陈国栋为当时地方士绅，被指与日伪有联系。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('63823bc4bfbb48ae8062d84c4b0e32b2','b9ac9430a19e468e98cb82e059a0a81d',1939,'万县伪警察局长（疑似）','抗战中期万县部分地方武装被日伪渗透，李柱被指担任伪职，但档案记载零散。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d40b861b6b9444549d2dbd67afef8dd1','e02fd2faed6245d7aadb7fc51e70e6d2',1938,'中国国家社会党主席、民主政团同盟成员','在重庆活动，主张抗战但后期与日方有接触传闻；非典型汉奸，但被部分史料列为附逆嫌疑。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('faaa8478a5ea4bcca485d892afbd0d86','a23958f2a093468d8476a9eec1ddb6a8',1937,'伪天津维持会会长','天津维持会头目，与重庆地区无直接关联。','基层维持会/地方自治头目','hanjian');
