INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ab8845529fc44f08af8e0925711feca5','d2b840cc6fa142c8b5c30c100a11b64d',1938,'伪华北政务委员会绥靖总署督办、伪河北省省长','在华北伪政权中任职，参与日军对华北的统治与扫荡，其伪政权体系对陕西地区有间接影响。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fdb5beb1d14647dbadd30b940ee60582','41d2b197fedd4eefa3bd64d7cebe1523',1937,'伪河南省省长、伪华北政务委员会委员','投靠日本，在华北伪政权中任职，参与日军对华北的统治，其活动范围与陕西邻近。；原东北军将领，投敌后任伪职，在河南协助日军统治，镇压抗日活动，影响波及陕西宝鸡。','省部级/大军区级要员','hanjian');
