INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2e2691a7a5e64ef2946f1aa9b68de0f8','0367758e6b0a4e6e9be4392582958ec0',1937,'伪山西省省长','在山西伪政权中任职，协助日军维持占领区，其活动区域与陕西邻近。；山西伪政权要员，配合日军统治，其活动与陕西宝鸡抗日后方有间接关联。；投敌后任伪山西省省长，协助日军搜刮。；投靠日本，任伪山西省长，配合日军在山西及陕西周边地区的殖民统治。；在山西沦陷区任伪省长，配合日军统治。','省部级/大军区级要员','hanjian');
