INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a988ef9fd5f34c82a10a0b0eb1960ef0','a2c03b81e5f2412bb86f5d5599c1687b',1936,'伪勃利县保安队队长','率保安队配合日军“讨伐”抗联，在七台河一带烧毁村屯，杀害抗联后勤人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('43af46602f0c454cac5b5c9bac02d6d1','fe72ecc5532b4cd99a1666fe83854ad0',1937,'伪勃利县税捐局局长','为日军搜刮粮食和物资，强征“出荷粮”，导致当地百姓饥荒，并贪污抗日家属财产。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('83700aa5eff54720b1a98d56744a2ec3','811e6ae674ab4f35a21e56d287668b58',1938,'伪勃利县司法矫正局局长','主持“思想矫正”监狱，关押虐待抗日嫌疑分子，多次执行酷刑和秘密处决。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('378aa3a3ec9649afac4ed20801db07bf','6fee2b329ee54681a24b19e7abf091b7',1939,'伪勃利县特务股股长','建立特务情报网，侦破抗联地下联络站，导致勃利地区抗联组织遭受重大损失。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c07266ddc2704534ad4c153ef986bc98','382d6cd4374f4825b23e811f101eb963',1940,'伪勃利县自卫团团长','组织自卫团协助日军“清乡”，在七台河矿区抓捕劳工，迫害矿工中的抗日分子。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('77b310ce4ea147f8b27e44df3f713960','e25c85c91f604ceda710a0637532c900',1931,'伪满第四军管区司令、伪满治安部大臣','原吉林自卫军将领，后叛变投日，在黑龙江东部（含七台河、桃山周边）多次指挥“讨伐”抗日联军，屠杀抗日军民。；原吉林军将领，投日后在黑龙江地区（包括哈尔滨、大庆周边）率伪军多次“围剿”抗联第三路军，制造多起惨案，后升任伪满治安部大臣。；原东北军旅长，1932年投降日军，任伪满第四军管区司令（驻哈尔滨），后升任伪满治安部大臣，多次率伪军“讨伐”抗日联军，残害抗联将士。；原吉林自卫军将领，1932年投敌，任伪满第四军管区司令，驻防黑龙江地区，多次率伪军进攻绥化、肇东一带的抗联部队，后升任伪满治安部大臣。；原东北军旅长，叛变后率伪军多次围剿抗联，在鹤岗及周边地区实施“讨伐”，屠杀抗日军民。；原东北军团长，1932年投敌，在黑龙江、齐齐哈尔等地率伪军围剿抗日武装，制造多起惨案；原东北军军官，叛国投敌后任伪满第四军管区司令（驻齐齐哈尔），多次率伪军“讨伐”抗日联军，在拜泉、讷河等地制造多起惨案。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ac54fb80337a4fea9b3ce2ca51f12d6e','9dc1581eaee5417b8742c435470d1585',1933,'伪满勃利县县长（七台河地区曾属勃利县）','在勃利县（含今七台河、桃山一带）推行日伪殖民统治，强征劳工，配合日军清剿抗联，残害百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b39ebda9c3fd4b36ba557fbc68fd1b6a','4ae2b4fe56d3444f8a7f2c44a74a1d2f',1934,'伪满勃利县警务科科长','在桃山、七台河地区组织伪警察队，抓捕抗日地下工作者，参与制造多起屠杀事件。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('37faabee17d34eaeb9c605b3e7c153ba','747a2f8d75af4f88878f6678522d9ee0',1935,'伪满勃利县保安队队长','率伪保安队配合日军在七台河、桃山一带“扫荡”，烧毁村屯，杀害抗联伤员和群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1ae8712460ea47aebc7deeb54e59bea7','234634910eee40ddbd3896c4f6989e7e',1936,'伪满桃山警察署署长','在桃山地区设立情报网，多次告密导致抗联密营被破坏，直接参与逮捕和刑讯抗日志士。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dc935a20063640648749ff1d33dbf920','64961d28a8094edcad571a73a3644245',1937,'伪满七台河自卫团团长','组织地方汉奸武装，为日军带路，参与围剿抗联第三、第四军，抢夺百姓粮食资敌。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0a37cb04be7e417fb9b2d0ed171d1efc','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满黑龙江省省长（后任伪满经济部大臣）','在任期间管辖包括七台河、桃山在内的地区，积极推行日伪经济掠夺政策，强征土地和劳工。；原黑龙江省实业厅长，投敌后任伪省长，在齐齐哈尔及黑龙江地区推行日伪统治，强征粮食物资，迫害抗日军民。；原黑龙江省实业厅长，投敌后任伪省长，推行日伪经济掠夺政策，镇压反满抗日活动。；原黑龙江省实业厅长，投敌后任伪省长，协助日军推行“治安肃正”，强征粮食物资。；原黑龙江省实业家，投日后任伪满黑龙江省省长，管辖范围包括牡丹江、东宁等地，积极推行日伪经济统制，掠夺当地资源，协助日军镇压抗联。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9b96029fca5744db9b51930a9ed5a18e','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满立法院院长（早年曾任哈尔滨特别市市长）','虽主要活动于哈尔滨，但其伪政权体系覆盖黑龙江东部，对七台河、桃山地区的伪行政建制有直接影响。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('271a05e828db48afb8c5ffa3554f311e','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满热河省警备司令（原黑龙江地区军阀）','九一八事变后投靠日军，在黑龙江地区协助日军镇压抗日武装，后调任伪满热河省任职。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1896ffab639a4fbd81ea5cc6d15e37f3','e25c85c91f604ceda710a0637532c900',1932,'伪满第四军管区司令（驻黑龙江）','原东北军将领，叛变后任伪满军事要职，在黑龙江、七台河一带参与“讨伐”抗日联军，制造多起屠杀事件。；原东北军将领，叛变投日后在黑龙江地区围剿抗日联军，制造多起惨案。；原东北军将领，叛变后率伪军多次围剿抗联部队，在双鸭山、尖山周边地区实施“讨伐”行动。；原东北军将领，叛变投日，在黑龙江地区多次围剿抗日联军，制造多起惨案。；原吉林军将领，叛变后任伪军高官，多次率伪军“讨伐”绥化、兰西一带抗日武装，屠杀抗日军民。；原吉林军军官，投日后在黑龙江、松花江流域围剿抗联，制造多起屠杀事件。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7e3ecf7136044fdca3b2dd631bf7b332','9da1593202df46eaaaff3f45a6ad0b4f',1933,'伪满勃利县（含今茄子河区部分）警务科长','在勃利县及茄子河地区残酷镇压抗日地下组织，逮捕并杀害多名抗联交通员和爱国群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5014b4595b4945cebec93ce23c1bf686','247dfbbaa63247e6972f3f1e381eadf4',1935,'伪满七台河保甲长兼自卫团长','为日军提供抗联活动情报，组织汉奸武装袭击抗联小分队，强征劳工修建军事设施。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fe19264f9fc441579e07bd15266d156e','3a9e402192aa460fb51a927d874bb93e',1938,'伪满茄子河警察署署长','积极执行日军“归屯并户”政策，烧毁民房，制造无人区，并亲自拷打抗联嫌疑人员。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1a5cc8d75c7e41eaa771b3f9dc0a6344','811e6ae674ab4f35a21e56d287668b58',1940,'伪满勃利县协和会分会头目（活动于茄子河地区）','宣传“日满亲善”，诱骗青年参加伪军，并告发多名抗联地下联络员，致其牺牲。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('38ddb42b4f7246369d931eb80d741715','6fee2b329ee54681a24b19e7abf091b7',1941,'伪满七台河矿警队队长','在七台河煤矿区残酷镇压矿工反抗，配合日军抓捕抗联后勤人员，并参与迫害劳工。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f88ae9fb4399430fafe2c5ac729f2ab8','e25c85c91f604ceda710a0637532c900',1932,'伪满洲国第四军管区司令官','原东北军将领，投日后任伪满军事要职，曾率伪军参与“讨伐”抗日武装，活动范围涉及松花江下游及伊春周边地区。；曾任东北军将领，后投敌任伪满军事要职，参与镇压抗日武装，在黑龙江地区（含伊春、乌翠周边）执行日伪“讨伐”任务。；曾任东北军将领，后投敌任伪满军事要职，在黑龙江地区参与镇压抗日武装，其辖区曾涉及伊春、南岔一带的讨伐行动。；原东北军旅长，投敌后驻防哈尔滨地区，多次率伪军“讨伐”抗日游击队。；原吉林军将领，投日后任伪满军职，在哈尔滨及北满地区多次率伪军“讨伐”抗日武装，制造多起惨案。；原东北军将领，投日后驻防哈尔滨地区，多次率伪军进攻抗日联军，屠杀抗日军民。；原东北军旅长，投日后驻防哈尔滨地区，多次率伪军“讨伐”抗日游击队，制造多起惨案。；原东北军将领，投日后任伪满军事要职，在黑龙江地区围剿抗联。；原吉林军将领，投日后在哈尔滨、道外一带镇压抗日武装，多次围剿赵尚志等抗联部队。；原东北军将领，投日后任伪满第四军管区司令，驻防黑龙江地区，参与围剿抗日武装，镇压抗联活动。；原东北军旅长，投日后在黑龙江、牡丹江地区多次围剿抗日联军，制造多起惨案。；原东北军旅长，投日后在牡丹江、哈尔滨等地围剿抗联，制造多起屠杀事件。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1523714f991c4883b327b71e5d8d48ef','e17f492252c74d1eadd480596e66e6f4',1937,'伪伊春县警务科科长','在伊春地区推行日伪“治安肃正”政策，抓捕抗日地下工作者，协助日军建立“集团部落”，迫害当地抗联家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('45e52ba7c937419c8ffd5d9892143a5f','234634910eee40ddbd3896c4f6989e7e',1936,'伪汤原县（含今伊春部分地区）保安队队长','率伪保安队多次袭击抗联小分队，破坏密营，并参与对抗日群众的“讨伐”行动，造成抗联人员伤亡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7a7de06265ff47bfaf90e059592bc152','77a789268c6f47b4a617cdb9e41180bd',1935,'伪满洲国国务总理大臣（管辖黑龙江全省含伊春）','作为伪满最高行政首脑，签署多项镇压东北抗联的法令，其管辖体系覆盖伊春林区，支持日军对抗日武装的围剿。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c3af374e89c5428a9b93b5f6711b92ca','3b74f508628f475a8777ffb7e38a48a0',1932,'伪黑龙江省省长（辖区含伊春）','投日后任伪黑龙江省长，积极推行日伪殖民政策，组织地方伪政权配合日军“清剿”抗联，在伊春周边设立伪警察机构。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b2b2d2c2d6cc4fbc81e38a3c50a82da4','142849ebf8614017a075f60e0d2e7e40',1938,'伪伊春地区森林警察大队大队长','负责伊春林区“治安”，率森林警察搜捕抗联后方医院和密营，烧毁粮食储备，切断抗联补给线。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9655fdaeda1f458d9cc97037b8aa2369','247dfbbaa63247e6972f3f1e381eadf4',1939,'伪铁力县（今伊春代管）协和会会长','组织协和会宣传“日满亲善”，诱降抗联动摇分子，并收集抗联情报提供给日军，导致多处抗联联络点被破坏。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2df7c50afcfe4ac6b0f8f8cc07b7015c','bedc991fdcff4254a3e2b0b24052d010',1940,'伪伊春街（今伊春区）自卫团团长','组织地方自卫团配合日军巡逻，盘查过往行人，多次截获抗联物资，并参与对抗日嫌疑人的酷刑审讯。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e10b6c9c5fa3486db2c418b6fef32ba0','6fee2b329ee54681a24b19e7abf091b7',1937,'伪南岔（今伊春南岔区）警察署署长','在汤旺河流域抓捕抗联交通员，破坏地下交通线，并参与“归屯并户”行动，强迫山区居民迁入集中村。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7283a31f1f934506a5a6ba01113fc6fe','09b75081038c4b9a9e729a8c98d3d067',1941,'伪金山屯（今伊春金山屯区）山林队队长','率山林队为日军带路搜索抗联营地，在冬季破坏抗联雪地足迹，导致抗联第三军部分战士冻饿牺牲。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0bd502e2be4c41c993fceeb498a98122','5a42f897a627483f9ceda7a629ea37f8',1932,'伪满洲国滨江省省长、伪满洲国大臣','辽宁人，九一八后投敌，历任伪滨江省省长、伪满洲国司法部大臣等职，参与推行殖民统治与治安肃正，其伪政权管辖范围包括今黑龙江中南部及伊春部分林区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('acef61e9eea349d7b2f04d258b7fc6d8','4b486850921b4f33b616f1f8dcdef313',1931,'伪满洲国滨江省省长、伪满洲国大臣','原中东铁路督办，投敌后任伪滨江省省长、伪满洲国经济部大臣等，协助日本掠夺东北资源，包括小兴安岭林区木材。；辽宁人，九一八事变后投敌，历任伪滨江省省长、伪满洲国司法部大臣等职，在哈尔滨及周边地区推行伪满统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0a41785be1a74257be03d3146061acc2','350822a1078340679fd657c16a793993',1934,'伪满洲国三江省省长、伪满洲国大臣','伪满政客，曾任伪三江省省长、伪满洲国厚生部大臣等，参与对黑龙江东部及小兴安岭地区的殖民统治与资源掠夺。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('01b995f79d5b4ca484a9d23cb0c9d119','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满军将领、伪三江省军区司令','原东北军军官，投敌后任伪满军旅长、师长，活动于黑龙江东部及小兴安岭一带，参与围剿抗日联军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('496f6411dfa5468f8332e301a9600f72','a979dd19db7944cd9480e25931212232',1932,'伪满军将领、伪滨江省军区司令','原东北军军官，投敌后任伪满军军官，在滨江省及小兴安岭地区参与对东北抗日联军的作战。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4d05576c613c4c4bb8827ba6223cca6b','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满军将领、伪洮辽镇守使','原东北军骑兵师长，九一八后率先投敌，任伪满军将领，其部队曾活动于黑龙江地区，参与镇压抗日武装。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9168b7ec2e614cefb0e7c7eeee4d5be9','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满军将领、伪奉天省警备司令','原东北军军官，投敌后任伪满军上将，统辖伪军参与对东北抗日联军及黑龙江地区抗日武装的围剿。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('77e3b4d592884521a94c2250763a96a7','d9bb7f270e97437ba2d41b2afdb1e972',1932,'伪满军团长、伪通化省讨伐队头目','土匪出身，投敌后任伪满军团长，在吉林、黑龙江东部及小兴安岭南部参与围剿抗日联军，后被打死。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('eccc4991f3564701ad37d78df02c523b','21853206ad2b417598d1af0b4b3a4782',1932,'伪满军旅长、伪三江省讨伐队头目','原东北军军官，投敌后任伪满军旅长，在黑龙江东部及小兴安岭地区参与围剿抗日联军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6b5c3e923f8a4830987979b7e512f0e9','325b49bddc5a45b3977ab3f09444c867',1935,'伪满伊春地区伪警察署长','伪满时期在伊春林区担任伪警察头目，协助日军管理林区、镇压抗日群众，具体事迹散见于地方文史资料。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cebc68992b064098b1707468587340ac','811e6ae674ab4f35a21e56d287668b58',1934,'伪满汤原县伪警察大队长','在汤原、伊春一带任伪警察头目，参与围剿抗日联军，迫害抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('92afea13d93948958bd1d331c69d7d3b','03b075609fe849e4beb1b7c16002ef12',1934,'伪满汤原县伪县长','伪满时期任汤原县伪县长，管辖范围邻近伊春丰林地区，推行保甲连坐、掠夺林区资源。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('53d077fb857541a68ae6ef6168c4de0c','d56aceeb29fe4d6a9718f78ea8c7a5b5',1934,'伪满佛山县伪县长','伪满时期任佛山（今嘉荫）县伪县长，管辖范围与伊春北部接壤，协助日军推行殖民统治。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9af9ebcfb98b4eb4bb8f8a85687717dd','875c22d678e24c21834a32caae69933c',1931,'伪满洲国财政部大臣、伪吉林省长','清朝宗室，九一八后投敌，任伪吉林省长、伪满财政部大臣，参与建立伪满殖民统治体系，影响波及黑龙江地区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0c06803aab1f41c2bae1702913452b8f','44e5f00b1df64ad0b7492bfbdfcec121',1932,'伪满洲国外交部大臣','台湾人，投敌后任伪满外交部大臣，参与伪满对外交涉，为日本殖民统治服务。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('67f18491e5f04037bab0bf61192cda89','c613e850809e422da82ec02317b57e21',1937,'伪伊春县县长（或伪汤原县县长，辖区含今乌翠）','在伪县府任职期间，协助日军推行“集团部落”政策，强征劳工，搜捕抗联人员，为日伪统治效力。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1a3868fe181140a489f40267517007c0','1ba31d558b934fbd83a28a8c2b446022',1932,'伪满洲国热河省省长（曾活动于黑龙江地区）','原东北军将领，九一八后投敌，在黑龙江及伪满多地协助日军清剿抗日力量，其部队曾参与对伊春林区抗联的围剿。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('06643c044492452b9acad5aab8e3fef5','5f82d23ccd2e45fd9e59f76c92bcc9ad',1933,'伪蒙古军总司令（曾率部在黑龙江地区作战）','投日伪后，其骑兵部队曾配合日军在黑龙江北部（含小兴安岭一带）追击抗联，烧毁村屯，迫害百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8185a9641d9f4b628090594af611dcf4','a984ebfabbf64a5b8e1dfef2d68daa53',1932,'伪满洲国军政部顾问（原东北军旅长）','一度抗日后投敌，任伪满军事顾问，参与策划对黑龙江地区抗联部队的“讨伐”，其活动范围涉及伊春周边林区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('09f18a134adc404aa18d6b508c8d476b','31de533b3a41401aa4377d363cb1c1fc',1932,'伪满洲国吉林警备军司令（活动于黑龙江东部）','原东北军团长，投敌后率伪军配合日军在松花江下游及小兴安岭地区“扫荡”，破坏抗联密营。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('46c65e3c523d42839a4583ed74c0faa5','8bd659b1a1f24d64ae2bf011c50d3980',1932,'伪满洲国第四军管区参谋长','协助于琛澂指挥伪军，在伊春、乌翠一带的山区多次组织“搜山”行动，杀害抗联伤员和支援群众。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f51ed5f2c28547009802d1b9bc486c33','9dc1581eaee5417b8742c435470d1585',1938,'伪汤原县警察署署长（辖区含今乌翠）','积极执行日伪“治安肃正”，建立保甲制度，抓捕抗联交通员，并参与“归屯并户”强迫居民迁移。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a05e030e72ba4300b8df66c3cc45bc2f','3cd55e29febc489d9f9a7f2f88db31bb',1939,'伪伊春森林警察队队长','率森林警察为日军采伐木材提供保护，同时搜捕在林区活动的抗联小分队，破坏抗联后勤补给线。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4f1aeb6e762d481b9651e6f9155af2e1','77a789268c6f47b4a617cdb9e41180bd',1932,'伪满洲国国务总理大臣（黑龙江籍，影响覆盖全省）','作为伪满最高汉奸之一，全面推行日伪殖民政策，其政权体系直接管辖伊春、乌翠地区，支持“讨伐”抗联。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('59bf0e77caac4374a1b7d05815121f65','e25c85c91f604ceda710a0637532c900',1932,'伪满第四军管区司令官','曾任东北军将领，后投敌叛国，在黑龙江地区协助日军镇压抗日武装，参与“讨伐”东北抗联，罪行累累。；原东北军将领，后投敌任伪满军事要职，曾率伪军参与“讨伐”抗日武装，活动范围包括黑龙江地区，对伊春、友好一带的抗联部队进行过围剿。；原东北军军官，后投靠日军，任伪满第四军管区司令官，驻防黑龙江地区，多次率伪军围剿抗日联军。；原吉林自卫军将领，后投靠日军，任伪满第四军管区司令官，负责绥化、北林一带的“讨伐”行动，多次率伪军进攻抗日游击队，杀害抗日军民。；原东北军旅长，投日后任伪满第四军管区司令官，驻防黑龙江地区，多次率伪军围剿抗联部队。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9ce6b6921e9c4eb6b64db71d61a83488','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满热河省省长（曾活动于黑龙江）','原东北军将领，九一八事变后投降日军，在黑龙江及东北多地协助日军建立伪政权，参与围剿抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8a78f0f7424c421e82149f77154e69db','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满立法院院长（原籍黑龙江）','曾任伪满要职，为日本殖民统治出谋划策，参与制定奴化政策，对东北人民进行思想控制。；积极参与伪满政权建立，为日本殖民统治出谋划策，涉及黑龙江地区伪政权事务。；积极鼓吹“满洲独立”，参与伪满政权建立，为日本殖民统治出谋划策。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0b07342b1e7b40c4b88fc5c572259bd0','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满黑龙江省省长','原黑龙江省官员，投日后出任伪省长，积极推行日本殖民政策，镇压抗日活动，征收苛捐杂税。；原黑龙江省实业厅长，1932年投敌，任伪满黑龙江省省长，积极推行日伪殖民政策，协助日军清剿抗日力量。；原黑龙江省实业厅长，投日后任伪黑龙江省省长，管辖绥化北林，推行日伪法令，组织“自卫团”对抗抗联，强征粮税。；原黑龙江省实业厅长，1932年投敌，任伪满黑龙江省省长，管辖包括绥化、肇东在内的广大地区，积极推行日伪法令，强征劳工，镇压抗日活动。；原黑龙江省官员，投日后任伪省长，强征粮税，配合日军清剿抗联。；原黑龙江省实业厅长，投日后任伪满黑龙江省省长，管辖黑河、五大连池等地区，协助日军建立伪政权。；原黑龙江省实业厅长，投日后任伪满黑龙江省省长（省会齐齐哈尔），推行“保甲连坐”制度，强征粮草，配合日军“讨伐”马占山等抗日部队。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('42ee6940d4d240d184c332d3cfcec93b','4b486850921b4f33b616f1f8dcdef313',1932,'伪满滨江省省长（辖区含今哈尔滨及伊春部分地区）','原哈尔滨特别市市长，投日后任伪滨江省省长，协助日军建立保甲制度，迫害抗日军民。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ac69a6a247b94630abea51414b7ce2ec','41502657c6b84465aa2ff94e620ed234',1932,'伪满黑龙江省财政厅长','负责为日军搜刮黑龙江地区资源，强征劳工，为侵略战争提供经济支持。；在伪黑龙江省任职期间，负责为日军筹措军费，在绥化北林地区加征苛捐杂税，导致民不聊生，并协助日军掠夺粮食资源。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ab9ae89e838b44f28a272dce98b3e4d3','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1934,'伪满三江省警务厅长（辖区含伊春地区）','指挥伪警察和特务，配合日军对抗联进行残酷“讨伐”，杀害大量抗联战士及平民。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e924e11408e4455591ef2c4ffabc1015','5a42f897a627483f9ceda7a629ea37f8',1932,'伪满哈尔滨警察厅长','在哈尔滨及周边地区（含伊春方向）大肆搜捕抗日分子，严刑逼供，制造多起惨案。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('682d2cdfc6814d219748f9ec06bfdc7e','5cce8fcbbcc043c2820499553d6999c1',1939,'伪满北安省省长（辖区含伊春北部）','推行“集团部落”政策，强迫农民并村，制造无人区，切断抗联与群众联系。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6db436c44c5444ab9bf57f63a51a38e4','9dc1581eaee5417b8742c435470d1585',1935,'伪满伊春地区森林警察队长','率伪森林警察在伊春林区为日军采伐木材，同时搜捕抗联小分队，破坏抗联密营。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0698a1af72084104bf3e43f1bbde437f','7719dcbb58554065a23ca03d66a7c9ab',1934,'伪三江省省长','伪满时期三江省（含今伊春、南岔部分区域）行政长官，推行殖民统治，强征劳工，配合日军“治安肃正”行动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7601b5c49ac044f9956ddbb5313fbb4a','acf7dcdffeda4a0a87c947be2dd7f78a',1937,'伪三江省次长（日方实际控制）','作为日本关东军派任的伪省次长，实际掌控三江省政务，在伊春、南岔地区组织“归屯并户”，制造无人区，迫害抗联家属。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('837e15a2a2d84eb6a0a1d4ef11ec6c83','3a9e402192aa460fb51a927d874bb93e',1938,'伪伊春森林警察大队长','在伊春林区为日军服务，率伪警察配合讨伐抗联第三、第六军，破坏密营，抓捕地下交通员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6b0f6f57c4514b16a1949965c1474970','7c4f055fe1bf4b1ea64573ebbd87eeb8',1939,'伪南岔警察署署长','在南岔地区积极执行日伪“治安强化”政策，多次带队袭击抗联小分队，残害当地抗日群众。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cddccd7b35d048aca68a914639d7781c','234634910eee40ddbd3896c4f6989e7e',1940,'伪伊春街（镇）长','充当日本殖民统治基层代理人，强征民夫修建警备道路和碉堡，为日军提供粮食和情报。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1e3064333e0d49a19eb35f1aea48e823','247dfbbaa63247e6972f3f1e381eadf4',1941,'伪南岔协和会分会会长','在协和会名义下进行奴化宣传，组织“勤劳奉仕”队，强迫当地青年为日军劳役，并告发抗日分子。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('09e226908a1a45dc91ccbbfb84aaae93','6fee2b329ee54681a24b19e7abf091b7',1936,'伪三江省警务厅特务科警佐','专门负责伊春、南岔地区抗日情报搜集，多次破坏抗联地下联络站，逮捕并刑讯抗日志士。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f025bc0bcf6f4997b4a15049716bc73e','ad047ba203b243a1a02887456fd104bf',1937,'伪满伊春县县长（或地区维持会长）','在伊春地区担任伪职，协助日军推行“归屯并户”和“集团部落”政策，强征劳工采伐木材，迫害抗日群众，为日军提供物资和情报。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('df5af3ff02634e61a3aa477bf0c1f861','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满热河省省长（曾涉黑龙江）','原奉系军阀，九一八后公开投敌，虽主要活动于热河，但其伪军部队曾北调至黑龙江参与“治安肃正”，对伊春、友好周边抗联根据地造成破坏。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3c3c4ad4847e4aa79ab6f8071aab495b','5f82d23ccd2e45fd9e59f76c92bcc9ad',1933,'伪蒙古军总司令（涉黑龙江边境）','投日伪将领，曾率伪军配合关东军在黑龙江北部（含伊春邻近地区）扫荡抗联部队，参与建立伪政权，掠夺林业资源。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('250ec78befe64d7eba6025f886f8597c','3a9e402192aa460fb51a927d874bb93e',1938,'伪满警察署署长（伊春地区）','在伊春、友好一带任伪警察头目，残酷镇压抗日分子，抓捕并刑讯抗联地下工作者，协助日军实施“三光政策”，强征当地居民修筑军事工事。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8714faacc6ed470f82184113760edd9d','3cd55e29febc489d9f9a7f2f88db31bb',1940,'伪满协和会伊春分会会长','积极宣传“日满亲善”，组织汉奸团体刺探抗联情报，破坏抗日群众组织，为日军提供当地抗日武装活动线索，导致多名抗联战士牺牲。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f16ef20d0712487a87d05e9ba286275f','5a42f897a627483f9ceda7a629ea37f8',1930,'伪满洲国哈尔滨警察厅厅长、伪滨江省省长、伪新京特别市市长','早年投靠日本，历任伪满哈尔滨警察厅厅长、伪滨江省省长等职，参与镇压东北抗日活动，推行日伪统治政策，其活动范围覆盖黑龙江地区。；早年投靠日本侵略者，历任伪满哈尔滨警察厅厅长、伪滨江省省长等职，参与镇压东北抗日军民，推行日伪殖民统治，后任伪新京特别市市长，是伪满政权中级别较高的汉奸之一，其活动范围覆盖黑龙江地区。；早年投靠日本，历任伪满哈尔滨警察厅长、伪滨江省省长等职，参与镇压东北抗日活动，推行日伪殖民统治，为日本侵略者效力。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1f6cf95eb78747e48b9d722bf088d9fe','4b486850921b4f33b616f1f8dcdef313',1930,'伪满洲国滨江省省长、伪满洲国驻日本大使','历任伪滨江省省长等职，管理包括今伊春、嘉荫在内的黑龙江地区事务，推行日伪殖民统治。；投靠日本后历任伪滨江省省长等职，在黑龙江地区推行日伪统治，后任伪满驻日大使，为日本侵略政策辩护。；原中东铁路督办，投敌后任伪滨江省省长、伪驻日大使等职，参与日本对东北经济与交通的殖民控制。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2f9b06ae453444409a70338571f5deb0','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪滨江省警务厅厅长、伪满警察头目','在伪滨江省警务系统任职，参与镇压抗日武装，其警务活动覆盖黑龙江多地。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('11ffc36970ea4dd0aeed883c86e0c47b','cef7f82276954e0e89c27d2dc58933a5',1934,'伪三江省省长','任伪三江省省长期间，配合日军在黑龙江东部地区推行保甲、归屯并户等政策，镇压抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a4d9a86e47984e8d8181f60167fdf671','350822a1078340679fd657c16a793993',1930,'伪三江省省长、伪热河省省长','历任伪三江省省长等职，在黑龙江地区推行日伪统治，参与经济掠夺和治安肃正。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b5f5433ed34f4731a970b66fe492f8bd','e25c85c91f604ceda710a0637532c900',1931,'伪满洲国军上将、伪第四军管区司令官','率部投降日军，任伪军高级将领，参与围剿东北抗日联军，活动范围包括黑龙江地区。；黑龙江双城人，九一八事变后投敌，率伪军配合日军进攻哈尔滨及黑龙江各地，后任伪满第四军管区司令官，负责北满地区治安，其伪军活动范围覆盖伊春、大箐山一带。；原东北军将领，九一八事变后投敌，任伪满军高级将领，曾率伪军在三江地区（含佳木斯一带）参与围剿抗日武装。；原东北军将领，九一八事变后投敌，率伪军配合日军进攻哈尔滨、佳木斯等地，镇压抗日武装，后任伪满第四军管区司令官，管辖包括佳木斯在内的三江地区。；原东北军将领，九一八事变后投敌，任伪满军高级将领，曾率伪军配合日军在黑龙江、吉林等地围剿抗日武装，其军事活动范围覆盖佳木斯一带。；原东北军将领，九一八事变后投敌，任伪满军高级将领，参与围剿东北抗日武装，长期在黑龙江地区活动。；黑龙江双城人，九一八事变后投敌，历任伪吉林省剿匪司令、伪第四军管区司令官等职，率伪军配合日军镇压东北抗日武装，活动范围包括今黑龙江大庆一带。；黑龙江双城人，九一八事变后投敌，任伪吉林省剿匪司令，率伪军进攻哈尔滨等地，后任伪满洲国军上将、第四军管区司令官，在黑龙江地区参与镇压抗日武装。；原为东北军将领，九一八事变后投敌，参与组建伪军，率部在哈尔滨、绥化、望奎一带围剿抗日武装，后任伪第四军管区司令官，管辖包括绥化在内的北满地区。；原为东北军将领，九一八事变后投敌，参与组建伪军，曾任伪满洲国军政部大臣、第四军管区司令官，负责北满地区（含绥化、海伦一带）的伪军指挥与治安肃正，配合日军围剿抗日武装。；原为东北军将领，九一八事变后投敌，参与组建伪军，曾任伪满洲国军政部大臣、第四军管区司令官，负责北满地区\'讨伐\'抗日武装，其军事管辖范围覆盖绥化、绥棱一带。；原东北军将领，九一八事变后投敌，率伪军配合日军进攻哈尔滨及黑龙江各地，后任伪满军第四军管区司令官，驻防哈尔滨一带，镇压抗日武装。；原东北军将领，九一八事变后投敌，率伪军配合日军进攻黑龙江抗日武装，活动于哈尔滨、牡丹江、鸡西一带。；黑龙江双城人，九一八事变后投敌，率伪军配合日军进攻哈尔滨及黑龙江各地，后任伪满军上将、第四军管区司令官，其伪军活动范围覆盖松花江下游包括鹤岗、兴山地区。；原东北军将领，九一八事变后投敌，任伪满军高级将领，曾率伪军在三江地区（今鹤岗、佳木斯一带）围剿抗日武装，对黑龙江东部地区抗日力量造成较大破坏。；原东北军将领，九一八事变后投敌，率伪军配合日军进攻黑龙江抗日武装，其伪军活动范围覆盖松花江下游及鹤岗、萝北一带，参与镇压当地抗日力量。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e7dbdc69d0f948d0b97b0bbbbf461262','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1932,'伪满洲国军少将、伪滨江省警备司令','在伪滨江省指挥伪军配合日军讨伐抗日武装，其辖区涵盖今伊春、嘉荫一带。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8361cb5688b54faa97f888387e6caa2d','c276a824877f4dce865833533f6312bf',1930,'伪满洲国军少将、伪第三军管区司令官','任伪第三军管区司令官，负责黑龙江地区警备，参与镇压抗日联军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fa47b2bf30984ac99bfafe50461609e1','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洲国军上将、伪洮辽警备司令','九一八后投敌，率部配合日军进攻黑龙江，参与江桥战役等，为早期汉奸武装头目。；辽宁人，原东北军将领，九一八事变后投敌，率部进攻黑龙江，配合日军侵占齐齐哈尔等地，后任伪满洮辽警备司令，其伪军活动涉及黑龙江多地。；原东北军洮辽镇守使，九一八事变后投敌，率部配合日军进攻黑龙江，其部队活动范围涉及绥化以北地区，参与镇压抗日武装。；原东北军将领，九一八事变后投敌，率伪军进攻黑龙江抗日武装，其伪军活动范围一度覆盖黑龙江东部，包括鹤岗、萝北周边地区，参与镇压抗日力量。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b5cb636a7e9241b9a106f70ec2201b5c','3c793b1442ef48298a262b0d57814cab',1931,'伪满洲国军中将、伪黑龙江省警备司令','原东北军将领，投敌后任伪黑龙江省警备司令，配合日军镇压抗日武装。；原东北军骑兵旅长，九一八事变后投敌，任伪黑龙江省警备司令，配合日军镇压黑龙江抗日武装，其辖区包括伊春、大箐山周边地区。；原东北军骑兵旅长，江桥抗战后投敌，任伪黑龙江省警备司令，协助日军维持黑龙江地区殖民统治。；原东北军骑兵旅长，九一八事变后投敌，任伪黑龙江省警备司令，配合日军镇压黑龙江抗日武装，活动范围包括今大庆红岗一带。；黑龙江人，原为马占山部骑兵旅长，1932年投降日军，任伪黑龙江省警备司令，率伪军配合日军进攻抗日武装，后任伪满洲国军中将。；原东北军骑兵旅长，投敌后任伪黑龙江省警备司令，率部在绥化、望奎、海伦一带围剿抗日义勇军，后任伪满军政部次长。；原东北军骑兵旅长，投敌后任伪黑龙江省警备司令，驻齐齐哈尔，管辖黑龙江全省伪军，包括绥化、海伦地区，参与镇压抗日武装。；原东北军骑兵旅长，马占山抗日时叛变投敌，任伪黑龙江省警备司令，配合日军\'讨伐\'绥化、绥棱一带抗日力量。；原东北军骑兵旅长，九一八事变后投敌，任伪黑龙江省警备司令，配合日军镇压黑龙江抗日武装。；原东北军骑兵将领，投敌后任伪黑龙江省警备司令，率伪军配合日军进攻马占山等抗日部队，其辖区包括黑龙江东部，对鹤岗、萝北地区抗日活动进行镇压。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cff4c4045c9c40e0853d81aae503af99','76877234e49e40abbd0e65850b11abac',1930,'伪满洲国军少将、伪黑河省警备司令','在伪黑河省任职，负责边境警备，参与封锁抗日联军，活动范围接近伊春、嘉荫。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('746119cae1cc47a6838085db73ce2ac3','f87c32e3cfd34c3db4ef08c6befef768',1930,'伪嘉荫县县长','任伪嘉荫县县长，推行日伪政令，组织保甲，配合日军征粮、劳工等殖民统治。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5e15a0e91f73400fadffa3597d68837c','811e6ae674ab4f35a21e56d287668b58',1930,'伪伊春县维持会会长','在伊春地区组织维持会，协助日军建立伪政权，维持地方治安，镇压抗日群众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e882bc2d3ca341c882a2b8318eb34f00','92641ba25b9f4e6394f012e6513f5508',1930,'伪汤原县县长','任伪汤原县县长，辖区与伊春、嘉荫相邻，推行归屯并户，配合日军讨伐抗日联军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('055751b3853e4445b246fce674d3d9e3','0ce82afb041f4eb4a6fb886726d0274f',1930,'伪三江省警务厅特务科科长','在伪三江省警务系统负责特务活动，搜捕抗日人员，其活动涉及黑龙江东部包括伊春地区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a146a6d730344879a0b1271bf00cc9b6','4d8ee535e808458cb76e82411cc0e24a',1930,'伪佛山县县长','佛山县（今嘉荫县一部分）伪县长，推行日伪政策，协助日军管理边境地区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d4d8d1d3ae0f4de385ed7a33d7b5e66c','ce6592dca9c24419948035a80b3a694c',1930,'伪萝北县县长','萝北县与嘉荫接壤，任伪县长期间配合日军封锁黑龙江沿岸，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ab488cd78c5c41ac944e2ead6268eb5b','875c22d678e24c21834a32caae69933c',1931,'伪满洲国财政部总长、伪满洲国宫内府大臣','清朝宗室后裔，九一八事变后率先在吉林投敌，主持建立伪吉林省政权，后任伪满财政总长、宫内府大臣，其附逆行为对包括黑龙江在内的东北全境沦陷有直接影响。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bf1cec65fc904d858b61116af042e89b','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满洲国军中将、伪三江省省长','原东北军军官，投敌后任伪满军职，后任伪三江省省长，管辖松花江下游及小兴安岭地区，包括伊春、大箐山一带，配合日军围剿抗日联军。；原东北军军官，投敌后任伪满军中将，后任伪三江省省长，三江省辖境包括今鹤岗、兴山地区，其伪政权统治直接覆盖该区域。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e4cba3682dc344fda4d20e0dcd89604e','350822a1078340679fd657c16a793993',1932,'伪满洲国三江省省长、伪吉林省省长','辽宁人，投敌后历任伪满地方官员，曾任伪三江省省长，管辖范围包括伊春、大箐山地区，推行保甲制、经济统制，配合日军镇压抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('612fd03704c04baa8a035ee381f810a1','acf7dcdffeda4a0a87c947be2dd7f78a',1932,'伪满洲国三江省省长、伪文教部大臣','投敌后任伪满地方及中央官员，曾任伪三江省省长，管辖伊春、大箐山一带，推行奴化教育及经济掠夺政策。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1ee27dc9502d4e088979e2b5bf400d16','5a42f897a627483f9ceda7a629ea37f8',1931,'伪满洲国哈尔滨警察厅长、伪滨江省省长','投敌后长期在哈尔滨及滨江省任职，负责警务及地方行政，其管辖范围覆盖黑龙江中部，包括伊春、大箐山周边，参与镇压抗日活动。；长期在哈尔滨及滨江省任职，镇压抗日活动，其管辖范围接近绥化、庆安地区。；曾任伪哈尔滨警察厅长、伪滨江省省长，滨江省辖哈尔滨及周边，其警务系统影响黑龙江东部，参与镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f4ee5cd171ce4510bb1645571737c72d','c276a824877f4dce865833533f6312bf',1930,'伪满洲国滨江省警务厅长','投敌后任伪滨江省警务厅长，负责哈尔滨及周边地区治安，配合日军围剿抗日联军，其警务活动涉及伊春、大箐山地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('571f813a70b5486cb9c276730b1dc369','1801590af35e42d9a7a11e8b64d7b871',1930,'伪满洲国伊春地区维持会会长','伊春本地士绅，日军侵占伊春后出面组织维持会，协助日军征发劳工、物资，维持地方伪秩序，直接服务于大箐山、伊春一带的殖民统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ac64cf621bc948d6b4e7c234b935a47e','811e6ae674ab4f35a21e56d287668b58',1930,'伪满洲国汤原县警务科警长（伊春、大箐山周边）','伪汤原县警务人员，活动于小兴安岭东南麓，包括今伊春、大箐山一带，参与搜捕抗日联军及镇压民众，是当地伪警头目之一。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('31cee4622eae45dcbfe32d4a2609ddc1','92641ba25b9f4e6394f012e6513f5508',1930,'伪满洲国铁骊县（今铁力）保甲长','铁骊县（今铁力市，邻近伊春、大箐山）保甲长，推行保甲连坐，协助日军征粮、抓劳工，镇压当地抗日群众。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8c07e7ff36ae4708bafd1d2fb763fc25','4bf16c613ce64001bbcf1d60e3cc9f97',1930,'伪满洲国佛山县（今嘉荫）维持会副会长','佛山县（今嘉荫县，属伊春市）维持会头目，协助日军控制黑龙江沿岸，征发劳工、物资，配合日军封锁抗日联军。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e48fb4bd212746ed8607e52975b3f755','fe7588d226fa430ea2eda3d08a162f2f',1930,'伪满洲国伊春林业株式会社把头','伊春林区伪林业把头，为日军掠夺小兴安岭木材资源，残酷压榨伐木劳工，直接参与经济掠夺，活动范围覆盖大箐山地区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8ffa59f218dc4a66a74e9cdfd097e443','4b486850921b4f33b616f1f8dcdef313',1932,'伪满洲国滨江省省长、伪满驻日大使','原中东铁路督办，投敌后历任伪滨江省省长、伪满驻日大使等职，积极为日本侵略者服务，参与对黑龙江地区的殖民统治和经济掠夺。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dc78f0894d2e48d7add7e4bef93778c9','af99649b3f3a4c5382ec79666bf2647d',1932,'伪满洲国滨江省省长、伪满交通部大臣','投靠日本后历任伪滨江省省长、伪满交通部大臣等职，参与日伪在黑龙江地区的统治与交通控制，为日军侵略提供支持。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a443925dd9ed4473821bf28132c8ce31','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满军将领、伪滨江省警备司令','原东北军军官，投敌后任伪满军将领，率部在黑龙江地区参与围剿抗日武装，镇压抗日军民，是伪满军事系统的重要汉奸。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e824d4bab7824618b71fb42300d005ee','e25c85c91f604ceda710a0637532c900',1931,'伪满军上将、伪第四军管区司令官','九一八事变后投敌，历任伪满军要职，率部在黑龙江、吉林等地围剿抗日义勇军和东北抗日联军，是伪满军早期重要头目之一。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('91091a2276af4a768a0b61cb85d7e60f','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满军上将、伪洮辽警备司令','原东北军骑兵师长，九一八事变后投敌，率部进攻黑龙江抗日军队，参与江桥战役等对抗日武装的作战，是黑龙江地区早期著名汉奸。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('11ce8186137f4184865baa59420cd94f','3c793b1442ef48298a262b0d57814cab',1931,'伪满军将领、伪黑龙江省警备司令','原东北军军官，投敌后任伪黑龙江省警备司令等职，率部配合日军进攻马占山等抗日部队，参与镇压黑龙江抗日军民。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('53c9111ac23d4225ada56566da953f58','77aa4951751342b79a81e38d021b4396',1932,'伪满洲国黑龙江省公署厅长、伪满参议员','投敌后历任伪黑龙江省公署要职，参与日伪在黑龙江地区的行政统治，为日本殖民政策效力。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('966c9cb13098466ea1423a545d7e45a8','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满洲国滨江省省长、伪满经济部大臣','投靠日本后历任伪滨江省省长、伪满经济部大臣等职，参与对黑龙江地区的经济掠夺和殖民统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cbf980874cb549b4ab92c38094f813f2','17ba4ca514844dcbb95b21c193e11290',1932,'伪满洲国滨江省公署参事官、伪满协和会要员','在伪滨江省任职期间，积极参与伪满协和会活动，推行日本殖民思想宣传，协助日伪控制黑龙江地区民众。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('300f7b7010ec4236b714f0d74dfd4d36','3cd55e29febc489d9f9a7f2f88db31bb',1935,'伪满伊春地区伪警察署长','在伊春地区担任伪警察头目，配合日军和伪满军围剿东北抗日联军，镇压当地抗日群众，搜集抗日情报，是伊春地区直接参与日伪统治的汉奸。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('374b09aaaf034ae4b7f14b1ff60f6183','4bf16c613ce64001bbcf1d60e3cc9f97',1932,'伪满汤原县维持会会长','在汤原地区组织维持会，为日军筹粮筹款、提供情报，协助日军镇压汤原抗日游击队和当地抗日群众，其活动范围接近伊春汤旺地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ee6d0889609f4afe9d5309c8501e4357','b8764893f5374363b85230fe7aa74875',1933,'伪满汤原县伪县长','担任伪汤原县县长期间，推行日伪保甲制度，配合日军围剿抗日联军，征发劳工，掠夺当地资源，对汤旺河一带抗日根据地构成威胁。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('47ffdec839ec45958bae72e660c75808','0ce82afb041f4eb4a6fb886726d0274f',1937,'原东北抗日联军将领、后投敌任伪满军警佐','原为东北抗日联军第九军军长，1939年投敌叛变，后任伪满军警佐，带领日伪军围剿抗日联军，在黑龙江伊春、汤原一带活动，是著名的叛徒汉奸。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5a538485c34d4fd5ad6364d2c4b4279d','ee5c41cf755c4b6b860f8ba54a0a1a81',1939,'原东北抗日联军将领、后投敌任伪满劳工大队长','原为东北抗日联军第八军军长，1939年投敌叛变，后任伪满劳工大队长等职，配合日军镇压抗日力量，在黑龙江东部包括伊春地区活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a85db1e9ec3f4b9d876421e9426fb84e','f40b2577494c4a11aa6db201015f5aad',1935,'伪满汤原县警察署长','在汤原县任伪警察署长，直接参与对汤旺河抗日游击根据地的围剿，逮捕和杀害抗日群众，是当地伪警系统的重要汉奸。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b4fd0cf5b4ad4e09babe05db771a3511','9aa415aa423347cda5a38f82580ae533',1938,'原东北抗日联军第三军叛徒','部分抗联叛徒在伊春、汤原一带投敌后，为日军带路围剿抗联密营，出卖抗日将领，具体姓名因史料记载有限，但此类叛徒在汤旺地区活动确凿。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e4496b2a45894fc3a9cd84ca800ec171','af99649b3f3a4c5382ec79666bf2647d',1930,'伪满洲国滨江省省长、伪满洲国交通部大臣','曾任伪滨江省省长，在哈尔滨及周边地区推行日伪殖民统治，后任伪满交通部大臣，协助日军运输物资。','省部级/大军区级要员','hanjian');
