INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0569bcd556a04c0cb31d84716201740d','e25c85c91f604ceda710a0637532c900',1931,'伪满洲国军陆军上将、伪满军管区司令','九一八事变后投敌，任伪满军将领，在黑龙江地区参与镇压抗日义勇军和东北抗日联军。','基层头目','hanjian');
