INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7a946ad662ba439eb592cac4ad044d87','3c793b1442ef48298a262b0d57814cab',1931,'伪满洲国军陆军中将、伪满黑龙江省警备司令','原东北军骑兵旅长，投敌后任伪满黑龙江省警备司令，在黑龙江地区参与围剿抗日武装。','市县厅局级','hanjian');
