INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4236d5645d7c490b8cffd51f290d8763','6960ecf5067148b08c7571d02c447623',1930,'伪满洲国伊春地区伪警察署长','在伊春地区担任伪警察头目，配合日军维持治安，镇压当地抗日民众，推行保甲连坐制度。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9b0d709e04fc4c09a2915edf7e7c07cf','811e6ae674ab4f35a21e56d287668b58',1930,'伪满洲国汤原县伪县长','在汤原及伊春周边地区任伪县长，推行日伪政策，协助日军征粮、抓劳工，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ce8d6c448ede4086b5c680487782a824','3a9e402192aa460fb51a927d874bb93e',1930,'伪满洲国佛山县伪县长','在伊春北部佛山县任伪县长，配合日军统治，镇压当地抗日力量，推行殖民经济政策。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6658e9d7a61d481f9a59f2a6f2bade14','16ae22c71e1040b79c537d26d1814bef',1930,'伪满洲国铁骊县伪县长','在铁骊（今铁力）地区任伪县长，协助日军维持统治，镇压抗日民众，征收苛捐杂税。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('233157686c804a9699a2a09562b8590e','773c389cdc344708985c5427cd1d1689',1930,'伪满洲国嘉荫县伪县长','在嘉荫地区任伪县长，配合日军封锁黑龙江沿岸，镇压抗日活动，推行日伪法令。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0565835c98b54e988e5fccf55ceb86de','4bf16c613ce64001bbcf1d60e3cc9f97',1930,'伪满洲国伊春伪保甲长','在伊春地区担任伪保甲长，协助日军监控民众，举报抗日分子，推行保甲制度。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fa59fce4c68e46ef8c12f00c1c4274cd','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满洲国军政部大臣、伪奉天警备司令、伪第一军管区司令','原东北军将领，1931年投敌，组织伪军配合日军进攻抗日武装。后任伪满洲国军政部大臣、伪第一军管区司令等职，其军事指挥体系涉及黑龙江地区，包括伊春、铁力一带的伪军警“讨伐”行动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1e13beb99d784f47aa0488cf1dce0bb3','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满洲国军管区司令、伪军少将','原东北军军官，投敌后任伪军职，参与对黑龙江地区抗日联军和民众抗日武装的“讨伐”，其活动范围包括松花江下游及小兴安岭一带，与伊春、铁力地区接近。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6f3a422a859f4a58abef857644799f55','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满洲国经济部大臣、伪滨江省省长','辽宁金县人，九一八事变后投敌，历任伪滨江省省长、伪经济部大臣等职。滨江省辖境包括今哈尔滨及周边，其经济统制政策覆盖黑龙江多地，伊春、铁力地区的木材、矿产等资源被其伪政权体系掠夺。；原商人，投敌后任伪滨江省省长，管辖依兰等地，协助日军掠夺资源。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2b2da66fb58044549bef9da143c417ce','350822a1078340679fd657c16a793993',1932,'伪满洲国吉林省省长、伪间岛省省长','原东北军军官，投敌后历任伪吉林省省长、伪间岛省省长等职，参与伪满地方政权建设和对抗日武装的镇压。其伪政权活动范围虽主要在吉林，但与黑龙江东南部及伊春、铁力地区邻近，有行政和军事协同。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5ad593c59d39417981baa85bc40a6a97','3eb966fdcf364389b5302ef8a669f7ac',1932,'伪满洲国司法部大臣、伪滨江省省长','辽宁人，投敌后历任伪滨江省省长、伪司法部大臣等职。在滨江省任内推行保甲制、连坐法，镇压抗日民众，其辖区包括今哈尔滨及周边，对伊春、铁力地区有行政管辖关系。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('30873602fec740b5b787d96fdd8df815','5a42f897a627483f9ceda7a629ea37f8',1932,'伪满洲国滨江省省长、伪哈尔滨市市长','投敌后长期在伪滨江省任职，历任伪哈尔滨市市长、伪滨江省省长等职，推行伪满法令，协助日军征发劳工、掠夺物资，其行政体系覆盖黑龙江中南部，包括伊春、铁力一带。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d01efbd78ef54d85a5143ebf51e4ddf8','17ba4ca514844dcbb95b21c193e11290',1932,'伪满洲国滨江省公署参事官、伪三江省省长','投敌后历任伪滨江省公署参事官、伪三江省省长等职，参与伪满地方政权和对抗日联军的“讨伐”。三江省辖境包括松花江下游、小兴安岭东部，与伊春、铁力地区接壤。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('824e1ebf180a4f2b9573d33048ac5f01','acf7dcdffeda4a0a87c947be2dd7f78a',1932,'伪满洲国三江省省长、伪东安省省长','投敌后历任伪三江省省长、伪东安省省长等职，在任内配合日军对抗日联军进行“大讨伐”，推行“集团部落”政策，其辖区与伊春、铁力地区邻近，对当地抗日力量造成破坏。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('096333b6645e44dbaab73a4d86dae236','840818553d8c45c9bce18af1619ad433',1932,'伪满洲国黑河省省长','投敌后任伪黑河省省长，管辖黑龙江北部边境地区，配合日军封锁边境、镇压抗日活动。其辖区与伊春北部接壤，对铁力、伊春地区有间接影响。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('556b3375f8ba48ba8842ba9f1707584b','3b8b90f06590400bb0ca4b868b415901',1932,'伪满洲国黑河省省长、伪龙江省省长','投敌后历任伪黑河省省长、伪龙江省省长等职，在黑龙江地区推行伪满政策，协助日军征发劳工、掠夺资源，其行政体系覆盖黑龙江多地，与伊春、铁力地区有行政关联。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4985753e64f244ebbee6b1b5a6fbd80e','ab041ed0fab3486f832f81b1b4e8a6ea',1930,'伪铁力县公署县长','伪满洲国时期任铁力县县长，推行保甲制、粮谷出荷、劳工征发等政策，配合日军和伪警察镇压当地抗日民众，是铁力地区直接附逆的伪政权头目。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c3a856d1bf81478a971cbaf708030f18','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洲国热河省省长、伪军上将','原东北军将领，九一八事变后投敌，任伪军职，参与进攻黑龙江抗日武装。后任伪热河省省长，其军事活动曾涉及黑龙江地区，与伊春、铁力地区有间接关联。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c7c5b7c147b940738c2941a88274ea2f','3c793b1442ef48298a262b0d57814cab',1931,'伪满洲国黑龙江省省长、伪军中将','原东北军骑兵旅长，1931年投敌，任伪黑龙江省省长、伪军中将，配合日军进攻马占山等抗日部队。其伪政权管辖范围覆盖黑龙江大部，包括伊春、铁力地区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('019deb1bc2614515acce12ed478a53a4','76877234e49e40abbd0e65850b11abac',1932,'伪满洲国黑龙江省公署参事官、伪龙江省省长','投敌后历任伪黑龙江省公署参事官、伪龙江省省长等职，在黑龙江地区推行伪满法令，协助日军镇压抗日力量，其行政体系涉及伊春、铁力一带。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ad7e8a6900df420cbf48121b3cf7c87d','77aa4951751342b79a81e38d021b4396',1932,'伪满洲国黑龙江省公署厅长、伪滨江省省长','投敌后历任伪黑龙江省公署厅长、伪滨江省省长等职，参与伪满地方政权建设，推行保甲、征发劳工等政策，其活动范围覆盖黑龙江中南部，与伊春、铁力地区有行政关联。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5818f28948704d82a8763e1153acc580','a7782cdd2135413ca8cb5f5ed2ecc41b',1930,'伪铁力县警务科科长、伪警察大队长','伪满洲国时期在铁力县任伪警察头目，指挥伪警察配合日军“讨伐”抗日联军和民众抗日武装，抓捕抗日人员，推行保甲连坐，是铁力地区直接参与镇压的汉奸。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6367a57025b4421ba23c7c87b8f57442','773c389cdc344708985c5427cd1d1689',1930,'伪伊春县公署县长','伪满洲国时期任伊春县县长，推行伪满政策，协助日军掠夺小兴安岭森林资源，征发劳工，镇压当地抗日活动，是伊春地区直接附逆的伪政权头目。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('751dfd97af824060b11f499caeb85010','811e6ae674ab4f35a21e56d287668b58',1930,'伪伊春县警务科科长','伪满洲国时期在伊春县任伪警察头目，指挥伪警察配合日军“讨伐”抗日联军，抓捕抗日民众，推行保甲连坐，是伊春地区直接参与镇压的汉奸。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b742a00cc70342e4b61986ae63d5101e','e25c85c91f604ceda710a0637532c900',1934,'伪满洲国三江省省长','直接管辖佳木斯所在的三江省，积极协助日军“讨伐”抗日联军，推行保甲制度，强征劳工，镇压当地反满抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b039382528d440019b2ca925b8cbe91a','4b486850921b4f33b616f1f8dcdef313',1937,'伪满洲国三江省省长（后任民生部大臣）','在任三江省省长期间，强化日伪统治，配合日军大扫荡，破坏佳木斯周边抗日根据地，实施粮食统制，造成民众饥荒。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bf0adb8897b34ed386945f2096c6ca8a','350822a1078340679fd657c16a793993',1940,'伪满洲国三江省省长','继续推行日伪政策，在佳木斯地区组织“协和会”活动，协助日军抓捕抗日地下工作者，强推“出荷粮”政策。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('01ab1451a4514e1cbfe2c418ee3a51aa','41502657c6b84465aa2ff94e620ed234',1942,'伪满洲国三江省省长（后任财政部大臣）','在佳木斯地区强化经济统制，为日军提供物资支持，参与镇压抗日联军剩余力量，迫害爱国群众。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bd6b6fb4229148ed9b5c6b7a90165524','3eb966fdcf364389b5302ef8a669f7ac',1944,'伪满洲国三江省省长','日本投降前夕仍效忠伪满，在佳木斯组织“防卫队”，企图抵抗苏军，并协助日军销毁罪证。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4d7d3482ec9448d2bbfc4d379ccf839c','8bd659b1a1f24d64ae2bf011c50d3980',1937,'伪满洲国佳木斯市市长','作为佳木斯市最高伪职，推行奴化教育，强制市民学习日语，配合日军“治安肃正”，多次组织搜查抗日分子。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('68c61509d44448e3a941a1277d68cfdf','8208a36677824ebd82d3a160b4c94e50',1941,'伪满洲国佳木斯市市长','任内加强警察特务统治，建立“思想矫正院”，关押迫害反满抗日人士，为日军提供劳工作业。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9954343ff94a49e88cb4f42a040715b4','2f5eea6a482341d593f47d54e93defd6',1935,'伪满洲国佳木斯市警察局长','直接指挥警察特务，多次破坏佳木斯地下党组织，逮捕并刑讯抗日志士，参与“三江大讨伐”行动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('87bee68c077044408304d230132c116c','49d961e716a44386a49dea8e5fd2ef9e',1938,'伪满洲国佳木斯地区协和会会长','积极宣传“日满亲善”，组织“协和义勇奉公队”，协助日军收集情报，煽动民众告发抗日分子。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ab831f534830412ebea5ce2a51624ce7','3cd55e29febc489d9f9a7f2f88db31bb',1939,'伪满洲国佳木斯宪兵队翻译官','为日军宪兵队充当翻译，参与审讯和刑讯抗日联军被俘人员，直接导致多名志士牺牲。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cf9a1419d4294ab7978328524ac51f64','589ab27feed347c6944e6c001125dc02',1936,'伪满洲国桦川县县长（佳木斯周边）','在桦川（今属佳木斯）推行“集团部落”，烧毁民房，强迫农民并村，切断抗联与群众联系。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b53eb14bfcdd450dbc16702e46c936d5','bcecd19b25794b85830a153b6211b413',1937,'伪满洲国汤原县县长（佳木斯辖县）','配合日军围剿汤原抗日游击队，强征粮食和牲畜，镇压当地农民反日暴动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ab958c55dcc54c68a72a492269a01bd2','05121fe8761841ba942ff8fea7415403',1932,'伪满洲国依兰县县长','在依兰（今属佳木斯）协助日军建立伪政权，组织“自卫团”对抗抗联，征收苛捐杂税。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0900ee37860d473f92a108e3dd9795a6','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满洲国军中将、伪三江省军区司令','原东北军军官，投敌后任伪满军职，活动于三江省（今佳木斯地区）一带，参与镇压抗日联军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('84c7f99d269a47fe8c962c1520b7d6a8','acf7dcdffeda4a0a87c947be2dd7f78a',1931,'伪三江省省长','曾任伪三江省省长，省治设于佳木斯，负责该地区伪政权的行政统治，推行保甲制度、经济统制等附逆政策。；伪满时期曾任伪三江省省长，省公署驻佳木斯，管辖佳木斯、富锦、同江、抚远等地，推行日伪殖民统治，征发劳工、掠夺资源。；任伪三江省省长期间，推行伪满政策，其统治范围包括双鸭山、友谊地区。；曾任伪三江省省长，管辖范围包括今鹤岗地区，积极推行伪满殖民统治政策，配合日军征发劳工、掠夺煤炭资源，对当地民众实施高压统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4e1276ac48e140258c32fadf62ab5073','350822a1078340679fd657c16a793993',1930,'伪三江省省长、伪吉林省省长','伪满官僚，曾任伪三江省省长，驻佳木斯，主持该地区伪政权的行政事务，配合日军对三江地区抗日武装的镇压。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('01fa452f4909477ea22b087a6d0d64e3','840818553d8c45c9bce18af1619ad433',1930,'伪三江省民生厅厅长','在伪三江省（佳木斯）任职期间，推行奴化教育、经济统制等政策，协助日军巩固对三江地区的殖民统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f61cfef59ba140928a51633b314ce165','0ce82afb041f4eb4a6fb886726d0274f',1932,'伪三江省警察厅厅长、伪满军团长','原为抗日武装人员，后叛变投敌，任伪三江省警察厅厅长等职，在佳木斯一带参与围剿抗日联军，出卖抗日志士。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('90af7d128aa04e738216c0965d40bd18','ee5c41cf755c4b6b860f8ba54a0a1a81',1939,'伪三江省警察大队长、伪满军团长','原为东北抗日联军将领，1939年叛变投敌，任伪职，在佳木斯、勃利一带参与围剿抗日武装，后成为当地著名汉奸。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fe801be8cf464407bdeec8a9cdb96afa','f40b2577494c4a11aa6db201015f5aad',1930,'伪三江省警务厅厅长','在伪三江省（佳木斯）任职期间，负责警务与治安，配合日军镇压抗日活动，推行保甲连坐制度。；伪满时期任三江省警务厅厅长，驻佳木斯，统管三江地区伪警察系统，积极推行保甲连坐制度，配合日军镇压抗日力量，抓捕抗日志士。；任伪三江省警务厅厅长期间，指挥伪警察配合日军在双鸭山、友谊一带镇压抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('966d8586c8354e3eb81393648856d6cc','c276a824877f4dce865833533f6312bf',1930,'伪三江省协和会事务长','在佳木斯地区负责伪满协和会事务，推行奴化宣传、思想控制，协助日军巩固殖民统治。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e26d62a8582149979c407d2266e69e3f','eb688993f9ee49a7bbacda2253de406a',1930,'伪三江省实业厅厅长','在伪三江省（佳木斯）任职期间，推行经济统制政策，掠夺当地资源，为日军侵华战争服务。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ba77c0b108184009afdb4f3db9ccc297','b022a6d1c1a942248238e68563f4c3ea',1930,'伪三江省教育厅厅长','在佳木斯地区推行奴化教育，篡改历史，强制教授日语，毒害当地青少年。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('33577e3375b749949bfc8a1f7b1a6abc','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洲国军上将、伪热河省省长','原东北军将领，九一八事变后投敌，任伪满军职，其活动虽主要在热河，但作为伪满高级将领，其行为影响覆盖东北全境包括黑龙江。；原东北军将领，九一八事变后投敌，率伪军进攻黑龙江，后任伪满军上将，其伪军活动涉及黑龙江多地，包括松花江下游鹤岗、兴山一带。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d9d5ab37c79041ae8e221805c0dca28b','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满洲国军上将、伪奉天省警备司令官','原东北军将领，投敌后任伪满军高级职务，参与镇压东北各地抗日武装，其军事行动涉及黑龙江地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8f82e44354f54e879b29f8ce81f0da79','c0860f9060d74dfba1674157f4596712',1931,'伪满洲国军上将、伪吉林省警备司令官','原东北军将领，投敌后任伪满军职，参与围剿抗日武装，其活动范围涉及黑龙江部分地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('65fa2836f5c444b1b726980853687fec','12571fd3a6fa42cf9581b18a4b27a94e',1930,'伪三江省警务厅特务科科长','在佳木斯地区负责特务活动，搜捕抗日人员，破坏抗日地下组织。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c168e71e57bb4985bf3debf118e103ef','811e6ae674ab4f35a21e56d287668b58',1930,'伪三江省桦川县县长','在佳木斯附近桦川县任伪县长，推行保甲制度，征发劳工，配合日军掠夺当地资源。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3f4c99f98ac74044b3b5a2e9859fcd32','ac9966f13b7d47c388702cf4911eaa27',1930,'伪三江省富锦县县长','在佳木斯地区富锦县任伪县长，协助日军征粮、征工，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ad08a1f774b84ac78b888aab92d84da8','4bf16c613ce64001bbcf1d60e3cc9f97',1930,'伪三江省同江县县长','在同江地区任伪县长，推行殖民统治政策，配合日军对黑龙江沿岸抗日武装的封锁。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('064d5c3be8354901bab2c98622f97cdf','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满洲国军中将、伪三江省警备司令','原东北军军官，投敌后任伪军旅长、师长，驻防佳木斯、富锦一带，参与围剿东北抗日联军，镇压三江地区抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3e91bfef9c74447fb091185277df8771','4a71ce857bc64724acfaa74f2868edfd',1932,'伪满洲国军少将、伪三江省保安司令','原东北军军官，投敌后长期在佳木斯、三江地区任伪军要职，参与对东北抗日联军的围剿，1945年后继续与人民政权为敌。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6d903fed825842049b0684d854dff381','0ce82afb041f4eb4a6fb886726d0274f',1932,'伪三江省警务厅厅长、伪保安团头目','原为抗日武装人员，后叛变投敌，任伪三江省警务厅厅长等职，在佳木斯、依兰、勃利一带配合日军围剿抗日联军，残害抗日群众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('93ea7e3639114f5b847cd83b90fcfb0a','ee5c41cf755c4b6b860f8ba54a0a1a81',1939,'伪三江省保安团团长、伪满协和会头目','原东北抗日联军第八军军长，1939年叛变投敌，任伪三江省保安团团长等职，在佳木斯、勃利、依兰等地协助日军围剿抗日武装。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('70e27bb0fc5c45d59531e38748800d91','f40b2577494c4a11aa6db201015f5aad',1935,'伪三江省协和会会长','伪满时期任三江省协和会会长，驻佳木斯，配合日伪推行殖民思想宣传、劳工征集和物资统制，为日本侵略政策服务。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('561ddff3cd784ae08111663d740a552b','446ff4d42340466cb2eb4843c83a6976',1937,'伪佳木斯市市长','伪满时期曾任佳木斯市市长，推行日伪市政管理、保甲制度和物资配给，协助日军征发劳工、镇压抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('197176e3cb444cd3bc6fa48c12329191','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洲国军上将、伪热河省警备司令官','原东北军将领，九一八事变后投敌，率伪军配合日军进攻黑龙江、佳木斯等地，后任伪满军政要职，参与对东北抗日武装的镇压。；原东北军将领，九一八事变后投敌，任伪满军高级将领，其部队曾参与黑龙江地区军事行动，配合日军镇压抗日武装。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('46ae5aca33394d77a49aefc0ad530427','c0860f9060d74dfba1674157f4596712',1931,'伪满洲国军上将、伪牡丹江省警备司令官','原东北军将领，投敌后任伪满军要职，其指挥的伪军活动范围包括牡丹江、佳木斯一带，参与围剿抗日联军。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('72f1acf793d74592bbc92a851785067f','c276a824877f4dce865833533f6312bf',1935,'伪三江省警务厅特务科科长','伪满时期在三江省警务厅任职，驻佳木斯，负责特务情报工作，搜捕抗日人员，破坏中共地下组织和抗日群众团体。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7deeaf4e19f84f309829fe65513beb13','c904a3bb584e47459dd2323f9459412e',1934,'伪汤原县县长、伪三江省民政厅厅长','伪满时期历任汤原县县长、三江省民政厅厅长等职，在佳木斯及周边地区推行保甲连坐、劳工征集和粮食统制，配合日军殖民统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d5e8c9617449447da3b7dd87084e62cf','e25c85c91f604ceda710a0637532c900',1932,'伪满佳木斯地区警备司令、伪满第七军管区司令','镇压东北抗日联军，在佳木斯、同江等地推行‘归屯并户’，制造无人区，屠杀抗日军民。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('73fdff5e29014ce49bad9d9ed1f2bf19','12571fd3a6fa42cf9581b18a4b27a94e',1934,'伪满三江省省长（驻佳木斯）','在佳木斯地区实施殖民统治，强征劳工，配合日军‘讨伐’抗联，推行经济掠夺政策。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('576d0f49f5cc4bf7b5ce96562adf4799','41502657c6b84465aa2ff94e620ed234',1935,'伪满三江省次长（实际掌权者，日本人）','作为日本籍次长，主导佳木斯地区治安肃正，组织‘宣抚班’瓦解抗联，迫害地下党员。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0bb214c9f32445c4bbd0494303c142cc','350822a1078340679fd657c16a793993',1936,'伪满三江省警务厅厅长','指挥伪警察在佳木斯、同江等地搜捕抗联联络站，逮捕杀害多名抗日志士，参与‘三江大讨伐’。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1ea0ea5dc09b4318bf045bd094d3b426','bde77533c68f469aa5eeb667ea3940ed',1933,'伪满三江省高等法院院长','审判抗日人士，以‘反满抗日’罪名判处大量抗联战士及群众死刑或重刑，在佳木斯制造多起冤案。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('87c42559756c4e3db5d4e157a334bd44','589ab27feed347c6944e6c001125dc02',1932,'伪满同江县县长','在同江地区强制推行‘保甲制度’，组织汉奸自卫团，协助日军清剿抗联游击队，强征粮食支援日军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d53b9d8374344132b25a16b70243bd39','ba135ba1ef794aeba0fdad0065a31974',1933,'伪满同江县警务科科长','率伪警察多次袭击同江境内的抗联小分队，破坏地下交通线，逮捕并刑讯逼供抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8d07b87c0e45408c9e528b38eda91b35','1ba31d558b934fbd83a28a8c2b446022',1937,'伪满三江省协和会本部部长（驻佳木斯）','在佳木斯地区组织‘协和会’宣传奴化思想，搜集抗日情报，协助日军‘讨伐’抗联，迫害爱国学生。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('18dfe367ff094fd7927b95aec1c4dbef','3b74f508628f475a8777ffb7e38a48a0',1935,'伪满三江省实业厅厅长','在佳木斯、同江等地推行‘产业开发计划’，强占农民土地，为日军提供粮食和木材，压榨劳工。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3e8e2caf649e42e7bb5a0c31335a944e','5a42f897a627483f9ceda7a629ea37f8',1938,'伪满佳木斯市警察局局长','在佳木斯市区设立多处特务据点，破坏抗联地下组织，逮捕并杀害多名地下党员和进步青年。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('846449e4e62e41b1836a82cb3abb4261','3cd55e29febc489d9f9a7f2f88db31bb',1939,'伪满同江县协和会分会长','在同江农村组织‘协和会’分会，强迫农民检举抗日分子，配合日伪军‘讨伐’抗联，收缴民间武器。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d57d1c29ea234bada76e973e22747cc2','747a2f8d75af4f88878f6678522d9ee0',1940,'伪满三江省保安队队长（驻佳木斯）','率保安队参与‘三江大讨伐’，在佳木斯周边山区搜捕抗联战士，烧毁抗联密营，杀害伤员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bba920e30945429e9620abdfed13b2b1','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满洲国军中将、伪佳木斯地区警备司令','原东北军军官，投敌后任伪满军将领，曾驻防佳木斯地区，指挥伪军配合日军对东北抗日联军进行讨伐，镇压当地抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('40bccc10134b4b1c82e6be845aef60db','0ce82afb041f4eb4a6fb886726d0274f',1932,'伪三江省警务厅警佐、伪自卫团团长','原为东北抗日联军将领，后叛变投敌，任伪三江省警务厅警佐及伪自卫团团长，在佳木斯、依兰、勃利一带配合日军搜捕抗日人员，出卖抗日组织情报。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b2a38498954f4ebaa33b491e0a419ad7','ee5c41cf755c4b6b860f8ba54a0a1a81',1939,'伪三江省协和会会长、伪自卫军司令','原东北抗日联军第八军军长，1939年叛变投敌，任伪三江省协和会会长、伪自卫军司令，在佳木斯、勃利、依兰等地协助日军围剿抗联，残害抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8a1b9d6c2a93431dba42f588ac3b9f97','acf7dcdffeda4a0a87c947be2dd7f78a',1934,'伪三江省民生厅厅长、伪佳木斯市长','伪满时期长期在佳木斯任职，曾任伪三江省民生厅厅长、伪佳木斯市长，推行日本殖民经济政策，强征劳工、配给物资，协助日军掠夺当地资源。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('558b09c56d82405ebc41e492c896e05f','16ae22c71e1040b79c537d26d1814bef',1932,'伪佳木斯维持会会长','九一八事变后佳木斯沦陷初期，组织伪维持会并任会长，协助日军维持地方秩序、征发物资、招募伪军，为日军占领佳木斯提供地方支持。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('815e2b8fbde34956b6dda26132991e18','5762ca5794044116b48fdb68f6cd67b5',1933,'伪桦川县公署参事官、伪佳木斯街长','伪满时期在佳木斯及桦川一带任职，曾任伪桦川县公署参事官、伪佳木斯街长，协助日军推行街村制、保甲制，管理地方行政并配合经济掠夺。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('598d72e2a2524f208f1f2eb45e80a17f','77aa4951751342b79a81e38d021b4396',1935,'伪三江省教育厅厅长','伪满时期任三江省教育厅厅长，驻佳木斯，推行奴化教育，强制学校使用日语、篡改历史教材，向当地青少年灌输亲日思想。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('730f9bad8e70415384324fa28247fe8a','3cd55e29febc489d9f9a7f2f88db31bb',1936,'伪三江省实业厅厅长','伪满时期任三江省实业厅厅长，驻佳木斯，负责矿产、林业、农业资源开发，协助日本侵略者掠夺三江地区煤炭、木材和粮食。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fbd4d40d8f2b4829a5975399873dd4dd','c904a3bb584e47459dd2323f9459412e',1930,'伪汤原县警务科科长','伪满时期在汤原、佳木斯一带任伪警务科科长，指挥伪警察配合日军讨伐抗日联军，破坏抗日地下组织，抓捕抗日群众。；在汤原、佳木斯交界地区指挥伪警察讨伐队，参与围剿抗日联军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3e443553f32649c69a0ebb75e4dff08b','ce6592dca9c24419948035a80b3a694c',1932,'伪依兰县维持会会长','依兰沦陷后组织伪维持会并任会长，协助日军在依兰、佳木斯一带征粮、征夫，维持殖民统治秩序。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('80c4516255fc4eff97d7bfb4ce8e5e06','6960ecf5067148b08c7571d02c447623',1934,'伪勃利县保甲长、伪自卫团团长','伪满时期在勃利、佳木斯一带任保甲长及伪自卫团团长，推行保甲连坐，配合日军搜捕抗日人员，欺压当地百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('04d2b3aa1c1a4587839b195f71ee0795','e25c85c91f604ceda710a0637532c900',1932,'伪满洲国第四军管区司令官（驻佳木斯）','原东北军将领，1932年投敌，任伪满第四军管区司令，驻佳木斯，负责镇压三江地区抗日武装，多次围剿抗联部队。；吉林双城人，原东北军将领，后投日，任伪满第四军管区司令官，驻守佳木斯，镇压抗日武装，参与“讨伐”东北抗联。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('56a4339584614f3c98700a241d7b7f29','9da1593202df46eaaaff3f45a6ad0b4f',1934,'伪满洲国三江省省长','伪满三江省（辖佳木斯、富锦等县）省长，推行日伪“治安肃正”政策，组织保甲制度，协助日军屠杀抗联及平民。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('173390d8c679446e9f7936dba045f377','589ab27feed347c6944e6c001125dc02',1932,'伪满洲国富锦县县长','原地方士绅，投日后任富锦县伪县长，强征粮食、劳工，配合日军建立“集团部落”，迫害抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6131cd99f02f46f6a6af7097e12cc19a','b21d5a4d224a4173bdb0f2b366c98d70',1937,'伪满洲国佳木斯市市长','伪佳木斯市首任市长，推行奴化教育，强制收缴民间武器，协助日军特务机关监控反满抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('03ff6a4c26e74859a701f8e7356485cc','3cd55e29febc489d9f9a7f2f88db31bb',1935,'伪满洲国三江省警务厅厅长','负责三江省警察系统，指挥伪警察配合日军“讨伐”抗联，在富锦、同江等地制造多起屠杀事件。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c705e139e33f47c089f9b00863be2e75','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洲国热河省省长（曾参与三江地区军事）','原洮辽镇守使，投日后任伪满军政要职，曾派兵参与对佳木斯、富锦一带抗联的围剿。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2819f07a551e4390aa363bd1c4a5927d','236b09af126745e997e5603fc3f56d0e',1932,'伪满洲国交通部大臣（曾管辖三江地区铁路）','清肃亲王善耆之子，投日任伪满交通大臣，修建军事铁路连接佳木斯、富锦，用于日军运输兵力和物资。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5a781a9f727b4b6589eca9993a72e0cf','9371eb94ef6548c6887387e706c61a27',1938,'伪满洲国三江省次长（实际掌权）','日本关东军指派日系官员，名义次长实为最高决策者，主导三江省“讨伐”抗联计划，在富锦地区实施“三光政策”。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('00f4c7706c164ca98c25662a0adc05c1','c9dffc071fec4ce58fe1d611f26c28da',1933,'伪满洲国富锦县警察署署长','原土匪头目，投日后任富锦警察署长，率伪警多次袭击抗联密营，逮捕并杀害抗日志士数十人。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('90be2790596e406ba845289025cbaeb2','7868e0ef70cc402e853a8fe711e9b58a',1936,'伪满洲国佳木斯地区协和会会长','协和会地方头目，宣传“日满亲善”，组织汉奸团体搜集抗日情报，破坏地下抗日组织。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a2297378d1a0475aa82ebb2420443552','ba135ba1ef794aeba0fdad0065a31974',1932,'伪满洲国三江省保安队队长','原东北军下级军官，投日后任保安队长，在富锦、绥滨一带配合日军“扫荡”，烧毁村庄，杀害抗联伤员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c4135a3a0369403c864d3ec7be0f15c8','747a2f8d75af4f88878f6678522d9ee0',1934,'伪满洲国富锦县参事官（日系）','日本籍参事官，实际控制富锦县政，推行“粮谷出荷”政策，强征农民粮食，导致大量饿殍。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('24335baa219c4894a84bd8e0fe0f418d','bedc991fdcff4254a3e2b0b24052d010',1937,'伪满洲国佳木斯宪兵队翻译官','为日军宪兵队担任翻译，参与刑讯逼供抗联被捕人员，直接导致多名地下党员牺牲。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6e6f02ebb7d34c9e9f1fd598e7952451','3209482e2b374e2e956a404739d12a53',1938,'伪满洲国三江省教育长','推行奴化教育，强制学校使用日语教材，灌输“忠君爱国”思想，迫害爱国教师。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c17903b476604a81a989dac889ed3ac5','49d961e716a44386a49dea8e5fd2ef9e',1933,'伪满洲国富锦县自卫团团长','组织地方自卫团，协助日军封锁抗联交通线，在富锦北部山区多次伏击抗联小分队。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5559090c4e7044d3b7b8c77200c549d9','cd8e5ab701f04770ad28171753ae1ceb',1938,'伪满洲国佳木斯市警察局局长','指挥伪警在市区大肆搜捕抗日分子，破坏中共佳木斯地下组织，逮捕并杀害多名爱国人士。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('95bb64729e49457ab0bef5fbe86590f5','5568708bb9b44d7a93d6adfffc6882f0',1935,'伪满洲国三江省特务机关情报员','充当日军特务，伪装成商人潜入富锦、同江等地，刺探抗联情报，导致多处密营被毁。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2ec70a4f1fac4a1fbf31e65a2868dba7','77a789268c6f47b4a617cdb9e41180bd',1932,'伪满洲国富锦县商务会会长','富锦本地商人，投日后任商务会长，为日军筹集军饷物资，并强迫商户“献金”支持侵略战争。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f3d9e1feda5c4c8e80aeb08d111a676d','739683df748747c1835da884965aaf56',1932,'伪满洲国佳木斯地区“治安维持会”委员','九一八后率先组织维持会迎接日军，协助建立伪政权，后任伪满县公署科长，参与“归屯并户”。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6df0d9586f2f4419b4174f50a983dc7b','875c22d678e24c21834a32caae69933c',1931,'伪满洲国财政部总长、伪满吉林省长','清末宗室，九一八事变后率先投敌，组织伪吉林省政权，后任伪满财政总长等职，是伪满初期重要汉奸，其影响波及东北全境包括黑龙江地区。；清朝宗室后裔，九一八事变后率先投敌，引日军占领吉林，并参与策划建立伪满洲国，其影响波及东北全境包括黑龙江。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0bd9f522d5af4e86ac9f4c8c7936a140','e25c85c91f604ceda710a0637532c900',1931,'伪满洲国军上将、伪满军政部大臣','黑龙江双城人，九一八事变后投敌，率伪军进攻哈尔滨等地，后任伪满军政部大臣，参与镇压东北抗日武装，活动范围覆盖黑龙江多地。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7abac9196de2408fb8da1cb8c40e3251','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洲国军上将、伪满热河省长','辽宁盖平人，原东北军将领，九一八事变后投敌，率伪军进攻黑龙江，参与江桥战役对抗马占山部，后任伪满热河省长等职。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a626baa8de84402988b7caee55d3075f','3c793b1442ef48298a262b0d57814cab',1931,'伪满洲国军中将、伪满黑龙江省警备司令','原东北军骑兵旅长，九一八事变后投敌，任伪黑龙江省警备司令，配合日军进攻马占山部，活动于齐齐哈尔、佳木斯一带。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c02ea89d998b46bfa5c3f8832f6e348e','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满洲国军少将、伪满三江省警备司令','原东北军军官，投敌后任伪满三江省警备司令，三江省辖佳木斯、抚远等地，参与镇压当地抗日武装。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('16d19063596a47a0974dba8dd9b4f251','acf7dcdffeda4a0a87c947be2dd7f78a',1934,'伪满洲国三江省长','曾任伪满三江省长，三江省省会设于佳木斯，管辖抚远等县，推行日伪殖民统治，镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('26bf6430bce64f4988a00f30e3f56bd8','ab041ed0fab3486f832f81b1b4e8a6ea',1930,'伪满洲国三江省民生厅长','在伪满三江省任职，参与推行日伪经济统制与思想教化，活动于佳木斯及周边地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f85870f3d0e24690a61553b455dd2ada','9f6435babca8474caa7e795c474b02fa',1930,'伪抚远县县长','伪满时期任抚远县县长，推行日伪政令，协助日军征发劳工、物资，镇压当地抗日力量。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a76df39f6d1342cdbefc0620036f4967','0ce82afb041f4eb4a6fb886726d0274f',NULL,'伪满佳木斯维持会会长','佳木斯地方士绅，日军占领佳木斯后组织维持会，协助日军维持治安、征发物资，后任伪职。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5e3e6724cbe141ef9680c097e50aa6ff','681c737567064ea093246850a86a8801',1930,'伪满佳木斯商会会长','佳木斯商会会长，投靠日伪，协助推行经济统制，为日军筹集物资，压迫商户。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7d2b298c46594e9c95ce719c85f413e0','c904a3bb584e47459dd2323f9459412e',1930,'伪满汤原县县长','汤原县邻近佳木斯，任伪县长期间配合日军围剿抗日联军，推行保甲连坐，镇压民众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3db36d4d5efa4227b57ff7556203f2fd','16ae22c71e1040b79c537d26d1814bef',1930,'伪满富锦县县长','富锦县属三江省，邻近抚远，任伪县长期间协助日军掠夺资源、镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('48a4120614a2420ba8cff293ed31c37d','3bdba80d49bb4825b5d28f9292f2391f',1930,'伪满同江县县长','同江县邻近抚远，任伪县长期间推行日伪政令，协助日军控制黑龙江沿岸。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ba2f764e62bd4b128538c9c1e10b9244','df267ac50384432e93deee32f1fbc69c',NULL,'无（注：赵尚志为抗日英雄，此处不应列入）','无','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f671531f459c45f08ebeae3c5c2d5413','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满热河省省长（曾任洮辽镇守使，活动涉及黑龙江地区）','九一八事变后投敌，任伪满要职，协助日军镇压抗日武装，在黑龙江地区参与清乡和讨伐活动。；九一八事变后投敌，任伪满要职，协助日军镇压抗日力量，其势力范围曾涉及黑龙江部分地区。；九一八事变后投敌，任伪满要职，协助日军镇压抗日武装，其势力曾延伸至黑龙江部分地区。；九一八事变后投靠日本，任伪满要职，参与镇压抗日武装，其势力曾延伸至黑龙江部分地区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cc2c244674574d44b341f674effe639c','e25c85c91f604ceda710a0637532c900',1932,'伪满第四军管区司令（驻佳木斯）','原东北军将领，叛变后任伪满军事要职，在佳木斯及三江地区指挥伪军围剿抗联部队，制造多起惨案。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('adf8de24d13f49f989412a3f81aff1be','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满立法院院长（曾任哈尔滨特别市市长）','积极参与伪满政权建立，在哈尔滨及北满地区推行殖民政策，协助日本关东军镇压反满抗日力量。；参与伪满政权建立，在哈尔滨推行奴化政策，协助日本关东军控制北满。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e2866e35cf9e4ded814cc1b53d2242b5','4b486850921b4f33b616f1f8dcdef313',1932,'伪满民政部大臣（曾任哈尔滨特别市市长）','投日后在哈尔滨任职，后升任伪满中央要职，参与制定奴化政策，对黑龙江地区抗日活动进行残酷镇压。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4a935aaf94b44bbcb8974e47d52d6300','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1934,'伪满三江省省长（驻佳木斯）','在三江地区（含桦南）推行集团部落政策，制造无人区，配合日军对抗联进行“讨伐”，导致大量平民死亡。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5341ef5b041b4bfcbe6746c455ac0a0e','350822a1078340679fd657c16a793993',1937,'伪满三江省省长（后任伪满司法部大臣）','在佳木斯任职期间，强化保甲制度，组织伪警察和协和会，残酷镇压桦南、依兰等地的抗日地下组织。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ba1a29ade2a54150987033a63d9c20a5','3eb966fdcf364389b5302ef8a669f7ac',1934,'伪满三江省次长（实际掌权者，日本人）','作为日本籍次长，实际控制三江省行政，策划并实施对桦南山区抗联部队的多次围剿，推行毒化政策。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8627b9b9fb8f40c688958aafb20138bf','41502657c6b84465aa2ff94e620ed234',1932,'伪满财政部大臣（曾任黑龙江省长）','投日后在黑龙江地区任职，后升任伪满中央，协助日本掠夺黑龙江粮食、木材等资源，间接支持军事镇压。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('565e65a399c74d17a020cfd0d7422647','77a789268c6f47b4a617cdb9e41180bd',1931,'伪满国务总理大臣（曾任哈尔滨特别市市长）','作为伪满最高汉奸之一，在哈尔滨及黑龙江地区建立伪政权体系，全面配合日军侵略，对佳木斯、桦南等地抗日活动负有重大责任。；作为伪满最高汉奸之一，在黑龙江地区签署多项卖国协定，支持日军殖民统治。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ca20da5714a542abbde03072ede5150a','b8f5150658fd47f0a48c92aacb628181',1932,'伪满黑龙江省长（短暂投敌后反正）','1932年2月一度投降日军，任伪黑龙江省长，但4月反正，重新抗日。其短暂投敌行为在黑龙江地区造成一定影响。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('225a6de5cd84422583a2335e6314085e','3c793b1442ef48298a262b0d57814cab',1932,'伪满黑龙江省警备司令（后任伪满军政部大臣）','原黑龙江骑兵师长，投日后在齐齐哈尔地区镇压抗日义勇军，后升任伪满中央，参与策划对三江地区的“大讨伐”。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b02a017c7e3644feb468dd83ca1fb4e7','12571fd3a6fa42cf9581b18a4b27a94e',1932,'伪满第一军管区司令（驻哈尔滨）','在哈尔滨及北满地区指挥伪军对抗联进行多次围剿，其部队在桦南、勃利等地烧杀抢掠。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a4a81f9580df4cb49d5e1cba81c19b3a','c9dffc071fec4ce58fe1d611f26c28da',1933,'伪满混成旅旅长（活动于佳木斯地区）','率伪军在佳木斯、桦南一带追击抗联，参与“集团部落”建设，强迫农民迁入集中营式村落。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('183bfd82ece046a2af0e1ca30a741989','0ce82afb041f4eb4a6fb886726d0274f',1939,'伪满“讨伐”队指挥官（叛变后）','原抗联第九军军长，1939年叛变投敌，在桦南、依兰等地带领伪军和日军搜捕抗联人员，破坏地下交通线。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('713876f69d9342e89472038f79a6955a','ee5c41cf755c4b6b860f8ba54a0a1a81',1939,'伪满“讨伐”队指挥官（叛变后）','原抗联第八军军长，1939年叛变，在佳木斯、桦南地区为日军带路，诱降抗联战士，造成重大损失。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a77ce3cb00324454909353a82292746d','d4474058e68b4dfebf3f359250715ce8',1933,'伪满桦川县县长（桦南当时属桦川县）','在桦南地区推行日伪法令，组织伪自卫团，协助日军清剿抗联，强征劳工修筑军事工事。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cb2506e51cfc49b0aa78b8c77b7c0669','84d2f3477cec4c8d8c3c139b0999f8fa',1934,'伪满桦川县警务科长','在桦南一带建立伪警察网络，抓捕抗日群众，刑讯逼供，破坏抗联地下组织。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4f3e0798fb09486f88bcf14ad7561720','7868e0ef70cc402e853a8fe711e9b58a',1937,'伪满佳木斯市市长','在佳木斯市推行奴化教育，组织“协和会”，配合日军对桦南山区进行经济封锁。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('940881003eda4161abefacc474cee8ca','3cd55e29febc489d9f9a7f2f88db31bb',1935,'伪满三江省警务厅长','指挥伪警察在三江地区（含桦南）进行多次大搜捕，杀害抗联联络员和爱国群众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ce324c1d9ab144d299364b1b01a1a127','3a9e402192aa460fb51a927d874bb93e',1932,'伪桦川县县长','原桦川县地方士绅，日军占领后出任伪县长，协助日伪推行保甲制度，强征粮税，镇压当地抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3d444447260f45678e15096baa62474e','b21d5a4d224a4173bdb0f2b366c98d70',1933,'伪桦川县警务科科长','桦川本地人，投靠日伪后任警务科长，组织伪警察抓捕抗联地下工作者，破坏抗日组织。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0299812cec334f92a20fbd99ff70507f','a2c03b81e5f2412bb86f5d5599c1687b',1937,'伪佳木斯市市长（1937年后）','原佳木斯商会会长，日军占领后出任伪市长，为日军提供物资，推行“粮谷出荷”政策，压榨百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('493552dcc9654446a9abc7c82adc2f5c','41502657c6b84465aa2ff94e620ed234',1934,'伪三江省省长（省公署驻佳木斯）','辽宁辽阳人，原奉系官员，投日后任伪三江省省长，管辖佳木斯、桦川等县，配合日军“治安肃正”行动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9b3f9af048da4c9499de68f5d4ef1dc7','acf7dcdffeda4a0a87c947be2dd7f78a',1935,'伪三江省次长（实际掌权者，日本人）','日本关东军派任的省次长，虽为日籍，但作为伪政权核心人物，直接指挥佳木斯、桦川地区汉奸行政体系。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('321d678c56174ed6b8edac6ac72c8110','0ce72eece3db48fc91bb0e9928ba9e67',1936,'伪桦川县协和会会长','桦川地主出身，任协和会会长，宣传“日满亲善”，组织青年训练，为日军搜集抗日情报。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d5a571fc351b49f4b0728bf7b70d4960','3cd55e29febc489d9f9a7f2f88db31bb',1938,'伪佳木斯警察厅厅长','原东北警察，投日后任佳木斯警察厅长，多次率警队袭击抗联小分队，逮捕并刑讯抗日群众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fac72e384b2e4248bbbda33afea6dc7d','2228d7bd1de942ea89d581fa87cc8921',1937,'伪桦川县保安队队长','桦川本地土匪出身，被日伪收编后任保安队长，配合日军“扫荡”，杀害抗联伤员及平民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b539ca1d33684f66a7c3654f82d04f8b','119496e6aaf54fe6b12e02ea8ff51070',1939,'伪三江省警务厅特务科科长','负责佳木斯地区特务工作，建立情报网，破坏抗联地下联络站，导致多名抗联干部被捕牺牲。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c840a76b105542dfaab6ed9eb6f189dd','13da16444a1248f9a8be0d1160f17970',1933,'伪桦川县教育局长','推行奴化教育，强制学校使用日语教材，禁止中国历史教学，迫害爱国教师。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7fec7aa44d09461f88f2079899549ba4','b8f5150658fd47f0a48c92aacb628181',1932,'伪佳木斯地区“靖安军”指挥官','原地方武装头目，投日后任靖安军指挥官，参与围剿抗联第三军、第六军，烧毁村屯。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2551d3aa3170426086e5eb6a7a82c0f0','15bce57e594e4d2baa94695c4c20822e',1934,'伪桦川县司法科长','协助日伪审判抗日人士，判处多名抗联情报员死刑或重刑。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2dadbe9962804ad6b05b8c3316524015','3b74f508628f475a8777ffb7e38a48a0',1935,'伪三江省财政厅长','负责为日军搜刮粮食和物资，推行“出荷粮”制度，导致桦川、佳木斯地区农民饥荒。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('add05043bede4582a55bd0fdaaec8aba','4a71ce857bc64724acfaa74f2868edfd',1932,'伪满佳木斯地区警务统制委员会委员长、伪三江省警务厅厅长','在汤原、佳木斯一带大肆搜捕抗日联军，制造多起屠杀事件，亲自指挥破坏汤原县委地下组织，杀害抗联干部及群众数百人。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('04b8aefef06349a8ac11322c2a25ee29','e25c85c91f604ceda710a0637532c900',1934,'伪满三江省省长、伪满治安部大臣','在汤原、桦川等地推行“归屯并户”和“保甲连坐”，组织日伪军警围剿赵尚志、夏云杰领导的抗联部队，烧毁村屯数十个。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('62595972d4964361975d51fc742b876a','12571fd3a6fa42cf9581b18a4b27a94e',1936,'伪满三江省警务厅特务科科长','在汤原县建立庞大特务网络，收买叛徒破坏抗联地下交通站，逮捕并杀害汤原县委书记及多名区委干部。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d553a2a48c754c029d50c7560f22b83c','234634910eee40ddbd3896c4f6989e7e',1937,'伪汤原县县长','积极推行日伪“治安肃正”计划，组织伪警察队配合日军扫荡汤原抗日游击区，强征民夫修筑警备道路和碉堡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('72e9caab9da04756a4169a492b6f9615','764916e3dc534a258706aecb1a8a8de8',1938,'伪汤原县警务科警佐、讨伐队长','多次率伪警察队袭击抗联小分队，在汤原西部山区诱捕抗联伤员，并参与屠杀被俘人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('41a933ae78654513b9edb69593ef88f2','247dfbbaa63247e6972f3f1e381eadf4',1939,'伪三江省地方保安局特高课课长','专门负责侦破汤原、佳木斯地区抗联地下组织，策划“汤原事件”，逮捕地下党员和爱国群众百余人。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('781985e42a5f432a979a0f972e6e5c85','77a789268c6f47b4a617cdb9e41180bd',1935,'伪满国务总理大臣（曾兼任三江地区“协和会”顾问）','虽名义上为中央官员，但多次到佳木斯、汤原视察“治安工作”，督促地方伪政权强化对抗日力量的镇压。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('90a24f560bd2479d9cfd1e431ee14506','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满三江省次长（实际掌权者）','在汤原推行“集团部落”政策，将散居农民强制迁入集中营式部落，切断抗联与群众联系，导致大量平民饿死。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('32c5d9a4777e4d52b7601034cff9e81a','747a2f8d75af4f88878f6678522d9ee0',1933,'伪汤原县警察署署长','亲自带队抓捕抗联联络员，严刑逼供后处决，并参与“汤原大搜捕”行动，破坏多处秘密据点。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bde200d0db2a42e0b6d67a10c87b85ed','bedc991fdcff4254a3e2b0b24052d010',1936,'伪满佳木斯宪兵队翻译官兼密探','利用翻译身份刺探抗联情报，多次化装成商人进入汤原山区侦察，直接导致抗联第三军密营被日军袭击。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a4c64d7ba5674746ab1b49fb89eb1e87','382d6cd4374f4825b23e811f101eb963',1938,'伪汤原县协和会事务长','组织“宣抚班”到各村劝降抗联人员，诱骗多名意志薄弱者叛变，并参与建立“思想矫正院”关押爱国群众。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b4671ce05cc04d62896c923c658b78e5','13da16444a1248f9a8be0d1160f17970',1940,'伪三江省警务厅警备科科长','指挥日伪军警在汤原、依兰交界处设置封锁线，截击抗联运输队，并参与制造“四合村惨案”。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0015e924b38948cb9c4b461c1000c0bd','05fc90791f1d4180b138e1e88225f44c',1935,'伪汤原县自卫团团长','率领汉奸武装配合日军“讨伐”，在汤原北山一带杀害抗联战士及群众数十人，烧毁民房百余间。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9f3f08f9f38d466e89132b6efcc98e71','b2870c4c1e634ac391ca7e790e93f57c',1937,'伪满佳木斯市警察局特务股股长','在佳木斯市区及汤原县城镇布设眼线，逮捕抗联地下工作者，并参与刑讯逼供，手段残忍。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7e6d5e7b470540c3b0d2fd4eb0ab3f53','1b0d93051c8343ec93855ecd4624a43f',1939,'伪汤原县警务科翻译兼密探','多次伪装成货郎进入抗联活动区刺探情报，向日军报告抗联营地位置，导致多次突袭。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b4f5a43f2420445eab3213eba59bef20','328f6cb60ea243d0a7dda3e54edb87d3',1941,'伪三江省保安局特工','专门负责追捕抗联叛逃人员，在汤原县内暗杀多名疑似抗联同情者，制造白色恐怖。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b4866e7fecb24760945c4479a0351861','0973fad34cf14a55a1aa9feb69092d3f',1934,'伪汤原县山林警察队队长','熟悉汤原山区地形，长期带领山林警察队追踪抗联队伍，多次设伏袭击抗联后勤人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e4b635554c5d4a62b25e5014609db251','7c4f055fe1bf4b1ea64573ebbd87eeb8',1936,'伪满佳木斯地方检察厅检察官','参与审判被捕抗联战士，以“反满抗日”罪名判处多人死刑或重刑，并协助日伪当局“合法化”屠杀。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fef0faa0a24842ae9389f513a8ac8310','851cd0c5204e430e95eade9cc041539f',1940,'伪汤原县警务科警长','在汤原县南部村庄搜捕抗联伤员，发现后当场杀害，并参与抢掠百姓粮食供日军使用。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('76b1e277ca044c858d96f374d873b08b','f17b1284d94c4b0f8117597c8e82b98e',1942,'伪三江省协和会青年训练所所长','在汤原、佳木斯培训汉奸青年，灌输亲日思想，并组织青年团协助日军搜查抗联物资。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2d79e4498d2f41498c1c608da4f72ea4','e25c85c91f604ceda710a0637532c900',1932,'伪满洲国军上将、伪三江省省长','原东北军将领，投敌后任伪满军职，曾率伪军进攻吉林、黑龙江抗日武装，后任伪三江省省长，三江省辖境包括今佳木斯地区，直接参与对佳木斯一带抗日力量的镇压。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e20f3ae92e5e4da3a91b274a68dc26fb','350822a1078340679fd657c16a793993',1930,'伪三江省省长、伪满洲国司法部大臣','伪满官员，曾任伪三江省省长，管辖今佳木斯、双鸭山、鹤岗等地，推行保甲、集家并村等政策，镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('467dd6a857354e648b0777d9424f0e93','acf7dcdffeda4a0a87c947be2dd7f78a',1930,'伪三江省省长、伪满洲国文教部大臣','曾任伪三江省省长，后任伪满文教部大臣，在佳木斯地区推行奴化教育，配合日军围剿抗日武装。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('65e0c22249b5471d87c367b675adb2ce','c9dffc071fec4ce58fe1d611f26c28da',1930,'伪三江省警务厅厅长、伪满警察头目','在伪三江省任职期间，指挥伪警察配合日军对佳木斯周边抗日游击区进行扫荡，抓捕抗日人员。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3780429c777043daae19d33a615e4157','0ce82afb041f4eb4a6fb886726d0274f',1932,'伪三江省地方维持会会长、伪自卫团头目','佳木斯地区地主武装头目，投敌后组织维持会，协助日军维持地方统治，参与镇压当地抗日群众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('543346f276dd4e9d8471f743255dcc88','ee5c41cf755c4b6b860f8ba54a0a1a81',1930,'伪三江省依兰地区维持会头目、伪自卫团团长','原为抗日武装首领，后投降日军，在依兰、佳木斯一带组织伪自卫团，配合日军进攻抗日联军，是松花江下游地区著名叛徒。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e8473165873c4fda97e0f5b5481402d1','0ce82afb041f4eb4a6fb886726d0274f',1930,'伪三江省自卫团头目','与谢文东类似，原抗日武装人员后投敌，在佳木斯周边地区为日军搜集情报、带路围剿抗日联军。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b2f5c95da5364d4e977d737b1024e32c','4bf16c613ce64001bbcf1d60e3cc9f97',1932,'伪佳木斯市维持会会长','佳木斯地方士绅，日军占领佳木斯后出面组织维持会，为日军筹粮筹款、招募劳工，协助建立伪政权。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('21ec4f25628b42ff9089882612e99a42','681c737567064ea093246850a86a8801',1930,'伪佳木斯市商会会长、伪协和会佳木斯分会会长','佳木斯商界人物，投靠日伪，控制商会为日军经济掠夺服务，并通过协和会进行亲日宣传。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ec7d04fd7b8b459cbf0b6377b376720f','9f4bd3a76b224b08876bbb9d1dee5d5a',1930,'伪桦川县公署县长','桦川县辖今佳木斯郊区部分区域，任伪县长期间推行保甲制、抓劳工、征粮，配合日军统治。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d207ac55552047d9b8a1896d7edf72a5','9f6435babca8474caa7e795c474b02fa',1930,'伪桦川县警务局局长','在桦川县及佳木斯郊区一带指挥伪警察镇压抗日活动，抓捕抗日群众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b09f19d3f0dc43438d30d3680136960e','3bdba80d49bb4825b5d28f9292f2391f',1930,'伪汤原县公署县长','汤原县与佳木斯郊区接壤，任伪县长期间配合日军对汤原、佳木斯一带抗日游击区进行经济封锁和军事扫荡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9527dd0ced494bfdb56ba5e331a982f5','ce6592dca9c24419948035a80b3a694c',1930,'伪三江省协和会事务长','在佳木斯地区通过协和会组织亲日团体，进行奴化宣传，动员青年参加伪军。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f3a1df1fefea415292f1330bde1f3e44','382d6cd4374f4825b23e811f101eb963',1930,'伪佳木斯市警察署署长','直接负责佳木斯市区及郊区治安，抓捕抗日嫌疑人员，镇压地下抗日组织。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e069721f49a1429f8084c65f9e315434','75b15a9ebc9e4a71bf48b08e3d7244e4',1930,'伪三江省实业厅厅长','在佳木斯地区推行经济统制，掠夺粮食、木材等资源，为日军侵华战争服务。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2aae43c8c04e49d296d701aa1afac610','4a71ce857bc64724acfaa74f2868edfd',1940,'伪满洲国军第七军管区司令官','伪满军高级将领，所辖部队包括佳木斯地区，参与对东北抗日联军的围剿作战。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('967411f6164f4702b86dbf0c199886fe','a979dd19db7944cd9480e25931212232',1930,'伪三江省保安局局长','负责三江省地方保安武装，配合日军在佳木斯周边进行治安肃正，镇压抗日力量。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d484a4a0544e40028b2fa4322f786fa5','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满洲国军少将、伪三江省警备司令','原东北军军官，投敌后任伪满军职，在伪三江省（今黑龙江东部，含双鸭山地区）参与镇压抗日力量，推行保甲连坐。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b797cabfdf8b417daec338bc173fa239','5f82d23ccd2e45fd9e59f76c92bcc9ad',1933,'伪蒙古军总司令、伪满洲国军上将','热河地区投敌军阀，后任伪蒙古军总司令，配合日军在东北及内蒙古地区作战，其部曾活动于黑龙江周边。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('59654cfe4a844ce7b96166813b3953be','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洲国军上将、伪洮辽镇守使','原东北军洮辽镇守使，九一八事变后投敌，任伪满军职，参与进攻黑龙江抗日军队，在江桥抗战中与马占山部作战。；原东北军洮辽镇守使，九一八事变后投敌，率部配合日军进攻黑龙江，参与攻占齐齐哈尔等地，其伪军活动范围覆盖今大庆地区。；辽宁盖平人，九一八事变后投敌，任伪洮辽镇守使，率伪军进攻黑龙江，参与江桥战役配合日军进攻马占山部，后任伪满洲国军上将。；原东北军洮辽镇守使，九一八事变后投敌，率伪军进攻黑龙江，参与攻占哈尔滨、绥化等地，后任伪满热河省长。；原东北军骑兵师长，九一八事变后投敌，任伪洮辽镇守使，率部进攻黑龙江，参与江桥战役，其活动范围涉及黑龙江全省，包括绥化、海伦。；原东北军洮辽镇守使，九一八事变后投敌，率部配合日军进攻黑龙江，参与江桥战役对马占山部的作战，后任伪满军职。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bd448151b7fb4c759f7b75e636fc2a59','76877234e49e40abbd0e65850b11abac',1934,'伪满洲国军少将、伪三江省警务厅厅长','在伪三江省任职期间，推行保甲制度，配合日军围剿抗日联军，镇压双鸭山、佳木斯一带抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1bedcb0da7b24679b860b10cefc0927d','c276a824877f4dce865833533f6312bf',1932,'伪满洲国军少将、伪富锦县县长','在伪三江省富锦县（邻近双鸭山）任县长期间，强征劳工、粮食，配合日军修筑军事工程，镇压当地抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('338a31194cb547bfaa65223718e61f51','acf7dcdffeda4a0a87c947be2dd7f78a',1932,'伪满洲国文教部大臣、伪三江省省长','曾任伪三江省省长，推行奴化教育，强制使用日语，在双鸭山等地区协助日本进行文化侵略。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3b2996fecc414a74891d1feac1549b96','ab041ed0fab3486f832f81b1b4e8a6ea',1935,'伪满洲国三江省民生厅厅长','在伪三江省负责经济掠夺，强制征购粮食、煤炭，为日军提供物资，压榨双鸭山地区民众。；在伪三江省负责民生、教育等事务，推行奴化教育，强制征发劳工至鹤岗煤矿等地，为日军掠夺煤炭资源服务，是经济和教育领域附逆者。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4e1218d50a744de7a0483d23e61f745e','3cd55e29febc489d9f9a7f2f88db31bb',1939,'伪双鸭山炭矿株式会社社长','配合日本掠夺双鸭山煤炭资源，强征中国劳工，实施残酷管理，导致大量矿工死亡。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8a4b5e8814114f9e931ae78f859da755','c904a3bb584e47459dd2323f9459412e',1932,'伪双鸭山维持会会长','双鸭山地区早期投敌者，组织维持会迎接日军，协助建立伪政权，征发民夫、物资。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('36ea2b16b2ef4014bc909307e5f1377e','1b0d93051c8343ec93855ecd4624a43f',1934,'伪集贤县保甲长','在双鸭山周边集贤县任保甲长，推行连坐法，监视抗日分子，向日军提供情报。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ac53ac5c46d54556b045852f45cce6e6','fe7588d226fa430ea2eda3d08a162f2f',1935,'伪桦川县警务科科长','在桦川（邻近双鸭山）负责伪警察事务，参与围剿抗日联军，逮捕抗日群众。','基层头目','hanjian');
