INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f1acca0a94744b74a9b374cb6015d31d','dc00b1b0609b422d8d3682790dc40db3',1939,'伪双鸭山协和会分会会长','在双鸭山地区组织协和会活动，宣传“日满亲善”，配合日本殖民统治。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('73c83e83ae344a0ba8e53a767d248816','15aba61e822c4e50a3d0ac9384c005f1',1938,'伪满洲国军少尉、双鸭山伪警察署署长','在双鸭山地区任伪警察署长，搜捕抗日地下工作者，强征劳工。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4c4d22b8fdb94e9982f6793ea46454d5','92641ba25b9f4e6394f012e6513f5508',1940,'伪双鸭山炭矿劳务系主任','负责双鸭山煤矿劳工管理，虐待矿工，强制劳动，导致大量劳工死亡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('48bb50c2af5e41bfb13e83a36a72fb5e','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洲国热河省省长、伪洮辽镇守使','原东北军将领，九一八事变后投敌，任伪洮辽镇守使、伪热河省省长等职，其伪军活动涉及黑龙江地区。；辽宁盖平人，原东北军将领，九一八事变后投敌，任伪洮辽镇守使，率伪军进攻黑龙江，参与江桥战役配合日军侵略齐齐哈尔地区。；原东北军洮辽镇守使，1931年投敌，率部配合日军进攻黑龙江，参与江桥战役，后任伪热河省省长等职。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1c51622a1ceb403cb3d8054b3b125068','c0860f9060d74dfba1674157f4596712',1931,'伪满洲国吉林省警备司令、伪间岛省省长','原东北军将领，投敌后任伪吉林省警备司令等职，参与伪满在黑龙江地区的统治与围剿抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fa18bd16af7a4269b7cda2f225d7067c','af99649b3f3a4c5382ec79666bf2647d',1931,'伪满洲国交通部大臣、伪哈尔滨市长','投敌后历任伪哈尔滨市长、伪交通部大臣等职，其活动涉及黑龙江地区包括双鸭山、友谊一带的伪政权统治。；投敌后历任伪满交通部大臣、伪哈尔滨市长等职，参与伪满对黑龙江地区的统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('96d160155c1c404aaf81d7799f46fd98','d2b7a71572c34ce0943d2a891b842d96',1931,'伪满洲国哈尔滨警察厅厅长','任伪哈尔滨警察厅厅长期间，配合日军镇压抗日活动，其警务统治范围覆盖黑龙江地区。','市县厅局级','hanjian');
