INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3b8d5a679b9e47799c9662c90067d4ab','0ce82afb041f4eb4a6fb886726d0274f',1931,'伪三江省警务厅特务、伪军头目','原抗日武装人员，后投敌叛变，任伪三江省警务厅特务，配合日军在双鸭山、友谊一带围剿抗日联军。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a7c65e6318114403a7bf44ffd907d80b','ee5c41cf755c4b6b860f8ba54a0a1a81',1931,'伪三江省协和会会长、伪军头目','原抗日联军将领，1939年投敌叛变，任伪三江省协和会会长等职，配合日军在黑龙江东部包括双鸭山、友谊地区围剿抗日武装。','基层头目','hanjian');
