INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('25b912094bd74d849fb6e0f864d14ca1','696465bfcc3c423497568c64dfdb21b8',1931,'伪双鸭山炭矿株式会社劳务系主任','在双鸭山炭矿负责劳工管理，配合日军强征劳工，虐待矿工，为经济附逆者。','基层头目','hanjian');
