INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('32ca4ea767024783940085084efbbe04','4b486850921b4f33b616f1f8dcdef313',1932,'伪满滨江省省长（辖区含今双鸭山部分地区）','原哈尔滨特区长官，投敌后任伪滨江省长，配合日军清剿抗日武装，强征劳工。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f3b8e1b781084e798f4ccfc8e0fc3111','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1934,'伪满三江省省长（辖区含今双鸭山地区）','原东北军旅长，叛变后任伪三江省长，在双鸭山一带推行“集团部落”政策，制造无人区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f0169dfbe12c432b8d89cfebfa306d42','9dc1581eaee5417b8742c435470d1585',1937,'伪满三江省警务厅长（驻佳木斯，管辖四方台地区）','指挥伪警察讨伐队，在四方台、双鸭山等地多次袭击抗联部队，逮捕杀害抗日志士。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6b116cae1946405482cbc0fe6c34b683','41502657c6b84465aa2ff94e620ed234',1932,'伪满黑龙江省财政厅长（后任伪满民生部大臣）','原黑龙江省政府官员，投敌后负责为日军筹措军费，强征当地农民粮食，间接参与对双鸭山地区的经济控制。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4d180da1a4014f3eb695d9f7b30a9059','350822a1078340679fd657c16a793993',1935,'伪满三江省次长（实际掌权者，日本人顾问）','作为汉奸协助日本次长管理三江省，在四方台地区推行保甲制度，镇压抗日群众。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ed0982255eea4f699083562d4bfae772','77a789268c6f47b4a617cdb9e41180bd',1931,'伪满国务总理大臣（原籍辽宁，但长期控制黑龙江伪政权）','九一八事变后投敌，作为伪满最高汉奸之一，其政策直接影响双鸭山四方台地区，支持日军“讨伐”抗联。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1e54fd43191a4b7bb7d4cad24ce0a377','e25c85c91f604ceda710a0637532c900',1932,'伪满第四军管区司令官、伪满治安部大臣','原吉林自卫军将领，后投靠日军，任伪满第四军管区司令官，负责黑龙江东部（含双鸭山、宝山一带）的“讨伐”行动，屠杀抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('91d24674847c42dc84d0afd623e96e8a','9da1593202df46eaaaff3f45a6ad0b4f',1934,'伪满三江省省长','伪满三江省（辖今双鸭山、宝山部分地区）省长，积极推行日伪殖民政策，强征劳工，配合日军“治安肃正”计划。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8c4b0b6b24304b1c95e6f003eee09c6d','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1935,'伪满三江省警务厅厅长','在双鸭山、宝山地区组织伪警察和特务，搜捕抗日地下人员，破坏抗日组织，参与制造多起屠杀事件。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c8aee651d67641d4a7551f95eb445410','21853206ad2b417598d1af0b4b3a4782',1936,'伪满三江省协和会事务长','在宝山、双鸭山地区推行“协和会”奴化宣传，强迫民众参加“反共”集会，协助日军征粮抓丁。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0c7a546770fc4b6da6f289d35386ed27','3cd55e29febc489d9f9a7f2f88db31bb',1933,'伪满宝清县县长（宝山地区旧属宝清县）','任伪县长期间，强征土地，推行“粮谷出荷”，导致当地民众饥荒，并配合日军围剿抗联部队。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1bd7445bbb9943e4979add0685936463','bedc991fdcff4254a3e2b0b24052d010',1938,'伪满双鸭山炭矿株式会社理事','管理双鸭山煤矿，强制征用中国劳工，实行残酷的“人肉开采”，导致大量矿工死亡，并协助日军掠夺煤炭资源。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a5882bbdb9114f9f8528c1e0dae39742','77a789268c6f47b4a617cdb9e41180bd',1935,'伪满国务总理大臣（曾管辖黑龙江地区）','作为伪满最高行政首脑，其政策覆盖双鸭山、宝山地区，支持日军“讨伐”抗联，推行“粮谷出荷”和“劳工供出”制度。；原东北军将领，全面投日后任伪满总理，对包括绥化、明水在内的黑龙江地区实施殖民政策，签署多项卖国协定。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2585e414e0fa417fb195bb6f02fc56fc','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满财政部大臣、伪满三江省省长（前任）','曾任三江省省长，在双鸭山、宝山地区设立伪行政机构，组织“自卫团”对抗抗日武装，后升任伪满财政部大臣。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6c29331cc08d453c8a6ab0af547bce2b','350822a1078340679fd657c16a793993',1937,'伪满三江省警务厅特务科科长','在宝山、双鸭山地区建立特务情报网，逮捕抗日志士，严刑逼供，破坏抗联地下联络站。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fa21f0a996ed4bd2a38d22f1d14780b1','54cd75e9c3494c9db39d04a808a53ae8',1932,'伪宝清县警务科科长','投靠日军后任伪警务科长，参与围剿抗日武装，抓捕抗联地下工作者，协助日军推行“归屯并户”政策。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('89565fee2d7048ecbc294838f82bc8e9','7c4f055fe1bf4b1ea64573ebbd87eeb8',1934,'伪宝清县协和会会长','组织汉奸宣传队为日军侵略张目，强迫民众捐献物资，告密导致多名抗联交通员被捕牺牲。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e900329ea39b465eba31497c0f819dfc','bb9f3367044e403997a73a2007e0c137',1933,'伪宝清县保安队队长','率保安队配合日军“讨伐”抗联第七军，在宝清南部山区烧毁民房，杀害抗日群众家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2a146ef26a8e4b06bf646472013219d9','a2c03b81e5f2412bb86f5d5599c1687b',1937,'伪双鸭山炭矿株式会社矿警队长','为日军开采煤炭资源充当打手，镇压矿工反抗，多次向日军报告抗联活动线索，导致游击队袭击失败。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cae9723a4e8a41fc8693c95ab2c871f0','be101ae50c01499eb4d1ad9af8d79b62',1938,'伪双鸭山地区保甲长','协助日军强征劳工修筑军事工事，克扣劳工口粮，私通日军宪兵队，迫害抗日嫌疑分子。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7219999481f14418948222b19f168a0a','64961d28a8094edcad571a73a3644245',1935,'伪宝清县警察署署长','亲自审讯并酷刑折磨抗联被俘人员，提供情报导致抗联密营被毁，参与“三光”政策行动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ba5359c7a7da4e69bc51255d65f42f61','119496e6aaf54fe6b12e02ea8ff51070',1940,'伪双鸭山兴农合作社理事','为日军掠夺粮食和农产品，强迫农民“出荷”，对反抗者进行报复，勾结日伪军围剿抗联小分队。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6bdba6b55ef9411cae8611ae3ce03a96','b8f5150658fd47f0a48c92aacb628181',1936,'伪宝清县教育督学','推行奴化教育，强迫学校使用伪满教材，宣扬“日满亲善”，检举爱国教师和学生。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ef44e0e55c5c4eb08ddda6f1211ae6c2','38a3dacd45834c858a732edd8e6fde72',1939,'伪双鸭山地区自卫团团长','率自卫团协助日军封锁山区，截断抗联补给线，多次伏击抗联运输队，杀害多名抗联战士。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('189756b272b34da1ae9c4739b6abfa93','27058a945c504a2f853b049422d35340',1937,'伪宝清县司法科承审员','以“反满抗日”罪名判处抗日志士死刑或重刑，伪造证据陷害无辜百姓，为日军镇压提供法律借口。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('17d856db3398409bb4a865b6d6d29331','c613e850809e422da82ec02317b57e21',1933,'伪满双鸭山地区维持会会长（据地方史料记载）','在尖山一带为日军征集粮草、强征劳工，协助建立伪警察所，迫害抗日群众。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('01254f50fee74476a9353261b7650894','a46dc9727f3843558c64c0dabcbfa0be',1935,'伪满尖山警察署署长','充当日军耳目，多次带队抓捕抗联交通员，并参与“集团部落”建设，制造无人区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1d0ff4941ee8423eab2aad4d9cca741c','bb9f3367044e403997a73a2007e0c137',1937,'伪满双鸭山矿务局稽查队长','为日军掠夺煤炭资源服务，残酷镇压矿工反抗，向宪兵队告密地下抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d4911675c3974cab8fce916fb72d062e','baf2e11ff34f4d96a9f24dc1e0aacff5',1938,'伪满尖山自卫团团长','组织地方汉奸武装，配合日军扫荡抗联密营，杀害多名抗联伤员及群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('15d1ef7ce8c54d3fb5c3fffd84e6b49b','e25c85c91f604ceda710a0637532c900',1932,'伪满第四军管区司令、伪满三江省省长','原吉林自卫军将领，1932年投敌，历任伪满第四军管区司令、伪三江省省长，直接管辖今双鸭山岭东地区，多次率伪军“讨伐”抗日联军，残害抗联将士及百姓','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e8372e00bae64c5dadae4b0aa14be8f7','9dc1581eaee5417b8742c435470d1585',1934,'伪满三江省警务厅厅长','长期担任伪三江省警务厅厅长，负责该省（含今双鸭山岭东）的警察特务工作，组织“搜山”行动，抓捕抗日联军地下工作者，实施白色恐怖','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e27dbbaa891b44ecbd456405b797da2e','5f8f1bdeab2443a586dc30df423055ea',1935,'伪满富锦县县长（辖今双鸭山岭东部分地区）','在伪富锦县县长任内，积极推行日伪“归屯并户”政策，强征民夫修筑警备道路，配合日军封锁抗日游击区，导致岭东一带民众流离失所','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d2fda4ab67b24fd182a3db3088967fd5','dce0f04fe2544b429d2a3a770b5e8fa9',1936,'伪满宝清县警务科科长（辖今双鸭山岭东部分区域）','在宝清县任职期间，多次率伪警察队袭击抗联小分队，杀害抗日群众，并参与日伪“治安肃正”计划，在岭东山区设立多个警察分驻所','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e47fd4410eb54f2ba3472834fa7495d2','a02eed53805847c38d732cc4c1d4bd3a',1938,'伪满双鸭山炭矿株式会社矿长','作为日资煤矿的华人矿长，强制征用当地劳工开采煤炭，克扣工资，虐待矿工，为日军战争机器提供资源，其矿区位于今双鸭山岭东地区','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('263369020ef14099bd3525c8094562b3','3b74f508628f475a8777ffb7e38a48a0',1940,'伪满三江省省长（继任）','接任伪三江省省长，继续执行日伪“粮谷出荷”政策，在岭东地区强征粮食，导致民众饥荒，并配合关东军对抗日联军进行“大讨伐”','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('948476e31fe34be98608d6d462b50e0e','41502657c6b84465aa2ff94e620ed234',1937,'伪满民生部大臣（曾任伪三江省省长）','在任伪三江省省长期间，推行“保甲连坐”制度，在双鸭山岭东地区建立伪村公所，强迫居民领取“良民证”，严密监控抗日活动','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c35d16e6976f4ba9807be0214453a3aa','4b486850921b4f33b616f1f8dcdef313',1932,'伪满滨江省省长（管辖松花江下游部分地区）','虽主要驻哈尔滨，但其管辖范围曾延伸至松花江下游及今双鸭山岭东一带，积极组织伪警察和自卫团，协助日军清剿抗联第三军、第四军','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9b36e87374cc483c9b4757c6e071a0f0','4b486850921b4f33b616f1f8dcdef313',1932,'伪满滨江省省长（辖区含哈尔滨及周边）','原哈尔滨特区长官，叛国投敌，在滨江省（含双鸭山、集贤邻近地区）推行奴化政策，镇压反满抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cd672d88d21e4d1188dd75714ad62740','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1934,'伪满三江省省长（辖区含今双鸭山、集贤一带）','原东北军旅长，投日后任伪三江省省长，该省辖今双鸭山、集贤等地，积极组织“讨伐队”对抗联进行残酷围剿。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('53773228ff75411e9c6116d737bd0c52','41502657c6b84465aa2ff94e620ed234',1935,'伪满三江省次长（实际掌权者，日本人为主，但孙为汉奸代表）','在伪三江省任职期间，配合日军推行“集团部落”政策，烧毁民房，强迫居民并屯，切断抗联与群众联系。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('73e23403ecd648da8408d50179799783','350822a1078340679fd657c16a793993',1937,'伪满三江省警务厅长','在双鸭山、集贤等地区组织伪警察队，协助日军搜捕抗联地下组织，杀害无辜百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('76250776808d4215b7e8b58a49d7a079','77a789268c6f47b4a617cdb9e41180bd',1931,'伪满国务总理大臣（原籍辽宁，但长期控制黑龙江军政）','九一八事变后公开投敌，任伪满最高行政长官，其政策影响覆盖黑龙江全省，包括双鸭山、集贤地区。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3b70a5164a1f432e9758d01269c50403','79b17193512846a1a5bde9f5df22c926',1931,'伪满参议府议长（曾代理黑龙江军政）','原奉天省长，投日后参与伪满中枢决策，支持对黑龙江抗日力量的镇压。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ca9234e492ee4e13af8d1272cf97dfa5','875c22d678e24c21834a32caae69933c',1931,'伪满财政部总长（曾策划吉林独立，影响黑龙江东部）','皇族出身，主动勾结日本，其叛变行为带动了黑龙江东部地区部分旧军投敌。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('82317dcbc3244880a121403fcd801253','b8f5150658fd47f0a48c92aacb628181',NULL,'',NULL,'无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2a4e7261d87a4834a5cd7f35d8b1c9f9','7c4f055fe1bf4b1ea64573ebbd87eeb8',1932,'伪饶河县警务科科长','在饶河地区积极协助日军围剿抗日联军，多次提供情报并参与抓捕抗联战士，残害抗日志士。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3872f2c28d1243c5b140652e634e348b','247dfbbaa63247e6972f3f1e381eadf4',1935,'伪饶河县协和会会长','组织汉奸宣传队，鼓吹“日满亲善”，破坏抗日群众组织，强征劳工供日军使用。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('05edc3aa3fc84726906be5e5d96fbb68','bb9f3367044e403997a73a2007e0c137',1933,'伪饶河县保安队队长','率保安队配合日军“讨伐”抗联第七军，在饶河山区多次袭击抗联小分队，杀害多名抗联战士。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e3d16c338bca48e482eef81dd591327b','6bfa40620a3d41fda4caa5042af1c57d',1936,'伪饶河县警察署署长','在饶河县内实行保甲连坐制度，搜捕抗日地下党员，严刑逼供，导致多名抗日群众牺牲。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0e7ea1983835498e8406e276db78f92d','c4efe274f7cf45c49edcc34d968cfa46',1934,'伪饶河县自卫团团长','带领自卫团为日军带路，破坏抗联密营，抢夺粮食物资，并参与制造多起屠杀事件。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5c22c67440454ffe99c6f81a4d962ba5','baf2e11ff34f4d96a9f24dc1e0aacff5',1937,'伪饶河县特务股股长','专门收集抗联情报，收买叛徒，破坏抗联地下交通站，导致多名交通员被捕牺牲。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b7a26a09c2f54d73a17d37fea7baa534','46d781a3ecf94faf896b9d02cd561706',1938,'伪饶河县警备队副队长','参与日军“三光”政策行动，在饶河县大岱林场等地烧毁民房，杀害无辜百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('07d9bb0e108640faba48137ad45b085f','82c8dc8c68f3449d85ce6770c252b411',1939,'伪饶河县行政科科长','协助日军推行“集团部落”政策，强迫山区农民并屯，导致大量农田荒废，百姓流离失所。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cd0c9d7aecad45a08dc3b1c08e3504de','e25c85c91f604ceda710a0637532c900',1932,'伪满洲国第四军管区司令官、滨江省省长','原吉林军将领，投日后在哈尔滨地区镇压抗日游击队，参与“讨伐”赵尚志等抗联部队。；原东北军将领，1932年投敌，任伪满第四军管区司令，镇压抗日武装，后任滨江省（含哈尔滨）省长，推行日伪殖民政策。；原东北军将领，1932年投敌，任伪满第四军管区司令，镇压抗日武装，后任滨江省（含哈尔滨、巴彦）省长，推行日伪殖民政策。；原东北军将领，1932年投敌，任伪满第四军管区司令，镇压抗日武装，后任滨江省省长，统治哈尔滨及阿城地区，推行日伪殖民政策。；原东北军将领，1932年投敌，任伪满第四军管区司令，驻哈尔滨，镇压抗日武装，后任滨江省省长，推行日伪殖民政策。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8695089883ab48e19492d1f7d37a8aa5','c0860f9060d74dfba1674157f4596712',1932,'伪满洲国尚书府大臣、吉林警备司令','原吉林陆军军官，投日后在哈尔滨及吉林地区协助日军清剿抗日力量，参与建立伪满军事体系。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('20c70dfe2c1748ccb07375be94cb0a81','2acf7a5b9b5341578e1066b27394b2eb',1932,'伪满洲国滨江省省长、哈尔滨特别市市长','原东北军旅长，投日后历任伪哈尔滨市长等职，推行日伪统治政策，镇压反满抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0b1abf114b274c0b82d13252415c5b6b','4b486850921b4f33b616f1f8dcdef313',1932,'伪满洲国哈尔滨特别市市长、司法部大臣','原哈尔滨特区行政长官，投日后任伪市长，协助日军控制哈尔滨，参与经济掠夺和特务统治。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6ee95657415645eab976db64fb1b8a56','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满洲国立法院院长、哈尔滨特别市市长','原奉系法律顾问，投日后在哈尔滨推行伪满法律，参与镇压抗日活动，后任伪立法院长。；原奉系官员，投日后任伪哈尔滨市长，后升任伪立法院院长，积极为日本侵略辩护，参与“王道乐土”宣传。；积极参与伪满政权建立，在黑龙江地区推行奴化教育，协助日本关东军镇压反满抗日活动。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9dbd2e85ebcd41b9affd39b93580548e','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满洲国滨江省省长、经济部大臣','原哈尔滨商会会长，投日后任伪省长，协助日军控制哈尔滨经济，为日军筹措军需物资。；原哈尔滨商人，投日后历任伪滨江省省长、伪经济部大臣，为日本搜刮物资，镇压反满抗日活动。；原哈尔滨商会头目，投日后任伪滨江省省长，在哈尔滨及香坊地区协助日军经济掠夺，后任伪满经济部大臣。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ae194a454d5147f8a4a8fd6b34a91c56','3eb966fdcf364389b5302ef8a669f7ac',1932,'伪满洲国滨江省省长、民生部大臣','原吉林省政府官员，投日后在哈尔滨地区推行奴化教育和“勤劳奉仕”制度。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6fcad1ce1c734f8d8957dca9acf4ca61','41502657c6b84465aa2ff94e620ed234',1932,'伪满洲国财政部大臣、滨江省省长','原黑龙江省政府官员，投日后负责伪满财政，在哈尔滨地区强征捐税，搜刮民财。；原吉林省财政厅长，投日后历任伪滨江省省长、财政部大臣，推行伪币政策，掠夺资源，镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e84a76dfde3b48e8965dbe325c100281','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1932,'伪满洲国哈尔滨警察厅厅长','原哈尔滨警察头目，投日后指挥伪警察协助日军搜捕抗日地下组织，残害抗联人员及爱国群众。；原哈尔滨警察头目，投日后任伪警察厅长，直接指挥逮捕抗日志士，破坏地下组织，实施酷刑。；原哈尔滨警察头目，投敌后任伪警察厅长，在道里区设立特务机构，大肆搜捕地下党和抗联人员，制造多起惨案','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4a7630b9470047efacbca6dc52115cd0','5cce8fcbbcc043c2820499553d6999c1',1932,'伪满洲国哈尔滨宪兵队队长','原东北军宪兵军官，投日后任伪宪兵队长，在哈尔滨及周边地区实施“治安肃正”，屠杀抗日志士。；原奉系宪兵，投日后任伪哈尔滨宪兵队长，协助日军宪兵队搜捕抗联及地下党，参与“三光”政策。；原东北军宪兵军官，投日后任伪宪兵队长，在道里区残酷镇压抗日群众，参与“三江口惨案”等屠杀行动','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6b077f860eb1482382545bb9791b7eb1','5a42f897a627483f9ceda7a629ea37f8',1932,'伪满洲国哈尔滨警察局副局长、滨江省警务厅长','原哈尔滨警察，投日后积极协助日军破坏中共地下组织，参与制造多起逮捕和屠杀事件。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7eaacbeebad54d6cb42c0d721cc63110','249deb11cff046d48971926e13314723',1932,'伪满洲国哈尔滨保安局局长','原哈尔滨地方武装头目，投日后组织伪保安队，配合日军“讨伐”抗联第三路军。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('77f1181f56804e929d1b2912387ad15d','07ff958e7f18410f864975f09234ac7e',1932,'伪满洲国哈尔滨特务机关长（实际为日本关东军特务，但为华人）','（注：此名有争议，但历史记载有华人特务在哈尔滨活动）协助日军建立情报网，破坏抗日组织。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b7813a19ca29415aa424377faa0f3987','3cd55e29febc489d9f9a7f2f88db31bb',1935,'伪满洲国滨江省警务厅特务科科长','专门负责侦缉抗联地下联络站，逮捕多名抗联交通员，导致哈尔滨地区抗联组织严重受损。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7dc98860ac7743fc8cea60f1fca46075','589ab27feed347c6944e6c001125dc02',1932,'伪满洲国哈尔滨市公署总务处长','协助日伪推行“保甲制度”和“连坐法”，强化对哈尔滨市民的殖民控制。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('de0032b8da194c4f8bcd55183ffebe4c','77aa4951751342b79a81e38d021b4396',1932,'伪满洲国哈尔滨市公署财务局长','为日军征收“国防献金”，强占民产，支持日军在哈尔滨的军事建设。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a2c24b1caf244d829d4edfb42ee3fc33','9b39cebcf825472fabf4077c5ba9933f',1932,'伪满洲国哈尔滨地方检察厅厅长','以“反满抗日”罪名起诉爱国人士，判处大量抗联支持者死刑或重刑。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fad009f711c6401d9b8d3b4b595d5d49','b8f5150658fd47f0a48c92aacb628181',1932,'伪满洲国黑龙江省省长（短暂投敌后反正）','1932年一度投降日军任伪省长，但旋即反正抗日，故不列为长期汉奸，此处仅作历史备注。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a4f928f59bc34d00a2a9eca7af1df152','acf1216c06d7451fb9b7b977421bca95',1932,'伪满洲国黑龙江省警备司令（早期投日）','原黑龙江军将领，江桥抗战后投敌，协助日军稳定黑龙江局势，后失势。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a37dee67007b470ab46a7e327933368e','8d5ae3dc95aa404bbde64ff9057ec6fa',1936,'伪满洲国滨江省警务厅高等警察科主任','专门负责“思想犯”监控，逮捕大量进步青年和抗联情报员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('382cd0f045bd43ceb72d6efb84cfe71c','2228d7bd1de942ea89d581fa87cc8921',1932,'伪满洲国哈尔滨市公署教育局长','推行日语教育和“王道乐土”宣传，篡改历史教材，奴化哈尔滨青少年。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('40ce6bef20c54f60b1712b39768c5df1','98afdc5e6a0c418d9ffab1a9987f5444',1932,'伪满洲国哈尔滨市公署卫生局长','协助日军进行细菌战实验，提供哈尔滨平民作为“马路大”的名单。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b73fc025cd7c42f9a8ca9fcbd49f402f','77a789268c6f47b4a617cdb9e41180bd',NULL,'',NULL,'无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('04faf4a6a7cd48189bcc50455867de0e','e25c85c91f604ceda710a0637532c900',1932,'伪满洲国第四军管区司令官、伪滨江省省长','原东北军将领，1932年投敌，历任伪满军事要职，在哈尔滨、五常地区镇压抗日武装，协助日军推行“治安肃正”；原东北军将领，1932年投敌，任伪满第四军管区司令，驻哈尔滨，镇压抗日武装，后任伪滨江省省长，推行日伪殖民政策。；原东北军将领，投日后任伪满军事要职，参与镇压抗日武装，在哈尔滨及方正地区推行日伪统治，围剿抗联部队。；曾任东北军将领，后投敌叛国，在哈尔滨地区镇压抗日武装，协助日军推行殖民统治，参与“讨伐”抗联部队。；原东北军将领，投日后任伪满军事要职，参与镇压抗日武装，在黑龙江地区（含呼中周边）协助日军清剿抗联部队。；原东北军将领，投日后任伪满军事要职，参与镇压抗日武装，在黑龙江地区（含大兴安岭周边）推行日伪统治，围剿抗联部队。；原东北军旅长，投日后任伪满第四军管区司令，驻防黑龙江地区，多次率伪军“讨伐”抗日联军，杀害抗联战士及平民。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9b9dd62e8add4054b75e79402ba29e79','77a789268c6f47b4a617cdb9e41180bd',1931,'伪满洲国国务总理大臣（曾任哈尔滨特别市市长）','九一八事变后投敌，1932年任伪哈尔滨特别市市长，后升任伪满总理，全面配合日本殖民统治，对黑龙江地区抗日活动进行残酷镇压；原奉系军阀，九一八后投日，1932年任伪哈尔滨特别市市长，后升任伪满国务总理，全面协助日本统治东北。；原奉系军阀，九一八后投日，1932年任伪哈尔滨特别市市长，后升任伪国务总理，全面配合日本侵略政策，对黑龙江地区抗日活动进行残酷镇压。；原奉系军阀，1932年投敌，曾任伪哈尔滨特别市市长，后升任伪满国务总理，全面协助日本统治东北，包括黑龙江地区。；九一八事变后投日，1932年任伪哈尔滨特别市市长，后升任伪满国务总理，全面协助日本统治东北，包括黑龙江地区。；九一八事变后公开投敌，长期担任伪满最高行政长官，在哈尔滨及东北地区推行奴化政策，协助日军经济掠夺和军事镇压。；九一八事变后投敌，1932年任伪哈尔滨特别市市长，后升任伪国务总理，在道里区活动频繁，全面配合日本关东军统治，出卖东北主权；原奉系军阀，九一八后投日，1932年任伪哈尔滨特别市市长，后升任伪满国务总理，全面协助日本统治东北，包括黑龙江地区。；原东北军将领，九一八后投日，1932年任伪哈尔滨特别市市长，后升任伪满国务总理，全面协助日本统治东北，包括香坊地区。；原东北军将领，九一八后投敌，虽居高位，但早年任哈尔滨市长期间即与日军合作，其势力影响黑龙江全省，支持对大兴安岭地区的“讨伐”。；原东省特别区行政长官，九一八后投日，在哈尔滨及黑龙江地区组织伪政权，后任伪满总理，全面配合日军统治。；作为伪满最高汉奸之一，在黑龙江及全国范围内协助日军统治，对鸡西等地的殖民政策负有总责。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9f6f4864db5344c59b34c162bd3794dc','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满洲国黑龙江省省长、伪滨江省省长','原黑龙江省实业厅长，投敌后任伪省长，在哈尔滨、五常等地推行日伪法令，强征粮食物资，破坏抗日组织；原为地方官僚，投日后历任伪职，在黑龙江、哈尔滨地区积极执行日伪法令，参与“治安肃正”行动，迫害抗日军民。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5dd30f14bb5b4e189edcb449f6c386fb','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满洲国立法院院长（曾任哈尔滨特别市市长）','原奉系官僚，投敌后历任伪哈尔滨市长、伪立法院长，参与签订卖国条约，协助日本控制黑龙江地区；原奉系法律人士，投日后在哈尔滨及黑龙江地区推行伪满殖民统治，参与制定镇压抗日法令。；参与伪满政权创建，在黑龙江地区推行殖民政策，协助日本关东军镇压反满抗日活动。；在哈尔滨及黑龙江地区推行日伪法令，协助日本关东军建立殖民秩序，镇压反满抗日活动。；积极参与伪满政权建立，在哈尔滨及黑龙江地区推行奴化政策，协助日本关东军统治。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7235db96fd4f4de29df42436710a559b','4b486850921b4f33b616f1f8dcdef313',1932,'伪满洲国滨江省省长、伪哈尔滨特别市市长','原哈尔滨特区行政长官，投敌后任伪滨江省长，在五常等地组织“清乡”行动，逮捕杀害抗日军民；原哈尔滨特区行政长官，投日后任伪滨江省省长，推行奴化教育，协助日军建立特务组织，迫害宾县、哈尔滨地区爱国人士。；原哈尔滨特别市市长，投日后历任伪滨江省省长、伪哈尔滨市长，协助日军清剿抗日力量，强征劳工。；原为奉系官员，投日后在哈尔滨地区推行日伪统治，参与镇压反满抗日活动，协助日军控制交通和资源。；原哈尔滨特区行政长官，投日后任伪职，在道里区推行奴化教育，强征劳工，协助日军镇压反满抗日活动；在哈尔滨及黑龙江东部地区任职，协助日本特务机关镇压抗日活动，参与对大兴安岭周边木材资源的控制。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('54b6224827294eac8222d059046d5319','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1933,'伪满洲国第四军管区参谋长、伪滨江省警务厅长','原东北军军官，投敌后负责哈尔滨及周边地区警务，多次指挥围剿五常一带的抗联部队；在哈尔滨、通河一带指挥伪军和警察“讨伐”抗联第三路军等部队，制造多起屠杀事件，是日伪在黑龙江东部的重要帮凶。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('527f631649d845cf9b5e27a7c1cd01b4','9dc1581eaee5417b8742c435470d1585',1932,'伪满洲国五常县县长','在五常县任伪县长期间，推行保甲制度，强征民夫修建警备道路，配合日军讨伐抗联第三军','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3a0045ad1edf4a308bff9fc428ec210c','9e9bdebf184b48f4970abcbfdcb18a12',1934,'伪满洲国五常县警务科科长','在五常地区组织伪警察队，多次袭击抗联密营，抓捕地下交通员，杀害无辜百姓','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2c34025528a24486ac452e369143a01b','3cd55e29febc489d9f9a7f2f88db31bb',1932,'伪满洲国哈尔滨警察厅厅长','在哈尔滨大肆搜捕抗日分子，破坏中共满洲省委地下组织，刑讯逼供，制造多起惨案','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b3d03c93798e4987b6a14f7e471b3b3c','5cce8fcbbcc043c2820499553d6999c1',1933,'伪满洲国哈尔滨警察厅特务科科长','专门从事特务活动，在哈尔滨、五常等地安插密探，破坏抗联联络站，诱捕抗日志士','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7934977eb857409b952aa672b54b3ec2','338f801833204de29136634230b7aa4a',1935,'伪满洲国滨江省警务厅特务股长','在五常、阿城等地组织“特别搜查班”，多次参与围剿抗联第十一军，残害抗日群众','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c9650a5879484ecca596b00f8a076793','901487c3f4c24e3f8818888b93e28e45',1936,'伪满洲国五常县协和会会长','在五常推行“协和会”奴化宣传，组织“青年训练所”，强迫民众参加“勤劳奉仕”，为日军提供情报','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c3fa9325638848359533b33ac14fce19','ad047ba203b243a1a02887456fd104bf',1937,'伪满洲国哈尔滨宪兵队翻译官','为日本宪兵队充当翻译，参与审讯和拷打抗日志士，在五常地区协助日军“讨伐”行动','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3a931c3c85384a27a2ab653c757036bb','bedc991fdcff4254a3e2b0b24052d010',1938,'伪满洲国滨江省保安局局长','在哈尔滨及五常地区建立伪保安队，配合日军“三光政策”，烧毁抗联据点，屠杀平民','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('40b8c734757b46b4be77f22b28805a73','ba135ba1ef794aeba0fdad0065a31974',1933,'伪满洲国五常县自卫团团长','组织地方伪自卫团，在五常山区巡逻，多次与抗联小股部队交战，杀害抗联伤员和群众','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0061264a81434d21a6036f37b1aa28f0','1ba31d558b934fbd83a28a8c2b446022',1932,'伪满洲国热河省长（曾任黑龙江地区伪军头目）','原洮辽镇守使，投敌后率伪军在黑龙江、哈尔滨周边镇压抗日义勇军，后调任热河，但早期在五常地区有活动','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6fb46eea55d545ab92ef66ddebc306bf','3c793b1442ef48298a262b0d57814cab',1932,'伪满洲国黑龙江省警备司令','原东北军旅长，投敌后任伪警备司令，在哈尔滨、五常一带多次“围剿”抗日武装，杀害抗联将领；原为马占山部将，后叛变投日，在黑龙江、哈尔滨地区率伪军进攻抗日武装，协助日军建立“治安区”。；原黑龙江骑兵旅长，投日后任伪省警备司令，在齐齐哈尔及大兴安岭地区率伪军进攻马占山抗日军。；在牡丹江、绥芬河一带率伪军围剿抗日游击队，杀害抗联伤员。；原马占山部将，随马投日后留任伪职，后率伪军进攻抗日义勇军，在鹤岗周边烧杀。；原黑龙江省骑兵师长，投日后任伪警备司令，率伪军进攻黑河、嫩江地区抗日义勇军','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('68c75abdc7c04cde80f4102771a52cc6','b8f5150658fd47f0a48c92aacb628181',1932,'伪满洲国黑龙江省长（短暂投敌后反正）','曾一度投降日军，任伪黑龙江省长，在哈尔滨活动，后反正抗日，但投敌期间对抗日事业造成损害','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('35f580b427e64384b8ea40095baa28fa','c9dffc071fec4ce58fe1d611f26c28da',1933,'伪满洲国滨江省警备军旅长','率伪军驻防哈尔滨周边，多次参与对五常地区抗联第三、第六军的“讨伐”，烧毁村屯','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b9b35e09763949a7bd8c624068ac8600','a02eed53805847c38d732cc4c1d4bd3a',1935,'伪满洲国五常县司法科科长','在五常县伪法院任职，以“反满抗日”罪名判处多名爱国人士死刑或长期监禁','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('23cb4c35334648acb1040711c73b4276','1ba31d558b934fbd83a28a8c2b446022',1932,'伪满洲国军政部大臣、伪热河省长','原洮辽镇守使，1931年投敌，在黑龙江地区协助日军进攻抗日武装，后任伪满高官。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ef358dd024ca4297878e02ea8a82376e','c0860f9060d74dfba1674157f4596712',1932,'伪满洲国滨江省省长','原吉林陆军军官，投敌后任滨江省（含哈尔滨、依兰）省长，推行日伪殖民政策。；原吉林副都统，投日后任伪滨江省（辖哈尔滨）省长，协助日军推行“治安肃正”，强征劳工，镇压反满抗日活动。；原吉林陆军军官，投日后任滨江省（辖哈尔滨、双城）省长，推行日伪殖民政策，强征劳工。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('20a2ba20ade34fe38eadc03f6d882ab5','bde77533c68f469aa5eeb667ea3940ed',1932,'伪哈尔滨特别市市长','原律师，投敌后任哈尔滨市长，协助日军建立伪政权，镇压反日运动。；原奉系法律顾问，投日后任伪哈尔滨市长，为日军占领哈尔滨提供法律与行政支持，协助建立伪政权。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d0f4055fb2a441d8955bcada69c26543','4b486850921b4f33b616f1f8dcdef313',1932,'伪哈尔滨特别市市长、伪满民政部大臣','原哈尔滨地方官员，投敌后历任伪哈尔滨市长，后升任伪满大臣，参与奴化统治。；原哈尔滨特区行政长官，投日后任伪哈尔滨市长，后任伪满民政部大臣，参与制定奴化政策。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3c97e76726c94b23b5c10e17ce80aef4','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1932,'伪满洲国第四军管区参谋长','原东北军军官，投敌后驻哈尔滨，参与策划对依兰地区抗联的围剿。；原东北军军官，投日后在哈尔滨、道外地区策划“讨伐”行动，烧毁抗联密营，残害百姓。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f066d18febe94e999dcd0210312499fa','9dc1581eaee5417b8742c435470d1585',1932,'伪依兰县县长','投敌后任依兰县伪县长，强征民夫，配合日军建立“集团部落”。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8d9eb5494fa142bda01ff4dcc2a8e401','6960ecf5067148b08c7571d02c447623',1933,'伪依兰县警务科科长','原地方警察，投敌后任依兰警务科长，抓捕抗日志士，迫害百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8025416468c64deea9387f55266938ec','2bc86830c5bb4c098fdbd155863dc8ca',1932,'伪依兰县保安队队长','投敌后组织伪保安队，多次袭击抗联小分队，烧毁村庄。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8e5bce2f45db42029635d8944697a1b8','9e5ee50d4aeb4fba87b9ecc885685187',1932,'伪哈尔滨警察厅厅长','投敌后任哈尔滨警察厅长，指挥特务破坏地下抗日组织，逮捕大量爱国人士。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8bc295c600f64e2487b2561d69043426','5cce8fcbbcc043c2820499553d6999c1',1933,'伪哈尔滨宪兵队翻译官','为日军宪兵队充当翻译，参与审讯酷刑，直接迫害抗联被捕人员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b43c6d597fb8481fab1de75306cdef07','9d25e1d3d8e543ee84de82f230352248',1934,'伪哈尔滨协和会会长','投敌后任协和会哈尔滨分会会长，宣传“日满亲善”，瓦解民众抗日意志。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7a9296fc10ef48bdbdc08dc368d11cd0','b21d5a4d224a4173bdb0f2b366c98d70',1936,'伪依兰地区“讨伐”队指挥官','原土匪头目，投靠日军后率伪军“讨伐”依兰山区抗联，屠杀无辜村民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0a8b604eaef74969b00476684c02f7ff','7719dcbb58554065a23ca03d66a7c9ab',1932,'伪满洲国滨江省警务厅厅长','投敌后主管滨江省警务，在哈尔滨、依兰等地建立情报网，破坏抗联联络站。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f053b8ba728243aface349bfb0bc6d20','4b486850921b4f33b616f1f8dcdef313',1932,'伪满洲国滨江省省长、哈尔滨特别市市长','原哈尔滨特别市市长，投日后历任伪滨江省省长、哈尔滨特别市市长，为日军提供情报，参与经济掠夺。；原哈尔滨市政官员，投日后历任伪职，协助日本特务机关镇压反满抗日活动，控制哈尔滨经济命脉。；原哈尔滨特区行政长官，投日后任伪哈尔滨市长及滨江省长，参与奴化统治和经济掠夺。；原哈尔滨特区行政长官，投敌后任伪滨江省省长，参与建立日伪政权，镇压反满抗日活动。；原哈尔滨特区行政长官，投日后长期主政哈尔滨，协助日军建立731部队外围据点，强征劳工。；原哈尔滨特区行政长官，投日后主持哈尔滨市政，协助日本宪兵队搜捕地下党及抗联联络员。；原哈尔滨特别市市长，投日后任伪滨江省省长，管辖哈尔滨及香坊地区，积极推行日伪法令，镇压反满抗日活动。；原哈尔滨特区行政长官，投日后任伪滨江省省长，管辖哈尔滨及松嫩平原，协助日军清剿抗联，强征劳工。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4d74747716964bd0b86931f47946a773','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满洲国经济部大臣、滨江省省长','原哈尔滨商会会长，投日后任伪滨江省省长，协助日本控制东北经济，搜刮物资，迫害爱国商人。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('723cab1d50ba4b52aa1e4694b5fe31b0','5a42f897a627483f9ceda7a629ea37f8',1932,'伪满洲国哈尔滨地区警备司令','原东北军旅长，投日后任伪警备司令，率伪军配合日军围剿抗联，在哈尔滨周边制造无人区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3e9e9c09b0b843e1a8b4a4e7d5ad6634','af99649b3f3a4c5382ec79666bf2647d',1932,'伪满洲国哈尔滨特别市公署总务厅长','原哈尔滨市政官员，投日后任伪总务厅长，掌管市政实权，推行日本移民政策，强占民田。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8e08620d8f224b76b09f4f0ff146fbdb','1a8847af165d4d648f62d949fad6cb5a',1932,'伪满洲国滨江省警务厅长','原黑龙江警务人员，投日后任伪省警务厅长，组织特务网，多次破坏抗联联络站，逮捕地下党员。；在哈尔滨道外区设立特务机构，指挥警察抓捕抗日分子，破坏中共北满省委地下组织。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2f771e1e2ab5424490726d1cecdaccc6','b30fc52a859d476a9db7ad9473b27198',1932,'伪满洲国哈尔滨地方检察厅厅长','原司法系统官员，投日后任伪检察厅长，以“反满抗日”罪名起诉爱国人士，协助日军进行司法镇压。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0bc169b1a14e4571bc7af293022c5a83','0ce72eece3db48fc91bb0e9928ba9e67',1932,'伪满洲国哈尔滨高等法院院长','原吉林高等法院法官，投日后任伪高等法院院长，审判抗日志士，判处多起死刑，为日本殖民统治服务。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c8606a4b4ab7475692d8c3653e20db38','9d25e1d3d8e543ee84de82f230352248',1932,'伪满洲国哈尔滨协和会会长','原哈尔滨绅商，投日后任伪协和会会长，组织汉奸团体，宣传“日满亲善”，诱骗青年加入伪军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('47d6a327adcf48338ab1e24370aab77d','3cd55e29febc489d9f9a7f2f88db31bb',1932,'伪满洲国哈尔滨市警察局副局长','原哈尔滨警察，投日后任伪警察局副局长，直接参与抓捕赵尚志等抗联领导人，提供情报给日军。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a757db3e0c854f1a98f69cb637af3385','163200f37b864b0babee2ff7015ef547',1932,'伪满洲国哈尔滨保安局局长','原哈尔滨保安队头目，投日后任伪保安局长，配合日军“清乡”，屠杀无辜百姓，烧毁村庄。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c1af82abd45a45e08048dec1d5fa1032','249deb11cff046d48971926e13314723',1935,'伪满洲国哈尔滨地区“讨伐”队队长','原土匪头目，投日后组织伪“讨伐队”，在哈尔滨南岗及周边山区多次袭击抗联部队，杀害伤员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fc24dd1dd3074b92bc3d48b5c3341aa2','0ce82afb041f4eb4a6fb886726d0274f',1939,'伪满洲国“挺进军”司令（后叛变）','原抗联将领，1939年叛变投敌，任伪“挺进军”司令，率部围剿抗联，在哈尔滨地区进行破坏活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a7879cce84b54f1c91f6237e6273d950','ee5c41cf755c4b6b860f8ba54a0a1a81',1939,'伪满洲国“东北抗日联军”叛徒、伪军头目','原抗联第八军军长，1939年投敌，任伪军头目，在哈尔滨南岗及周边地区协助日军搜捕抗联人员。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aba4644039304698b8f5219f78a4f5ef','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满洲国立法院院长（曾任哈尔滨地方法院院长）','原奉系法律界人物，投日后参与伪满立法，曾为日本在哈尔滨的殖民统治提供法律依据。；原哈尔滨律师，投日后参与伪满政权建立，在哈尔滨、宾县地区协助日军制定殖民法律，迫害抗日民众。；原哈尔滨律师，投日后任伪哈尔滨地方法院院长，后升伪满立法院院长，为日伪司法镇压提供法律依据。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bc31753d68404b89befec00475116d92','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满洲国经济部大臣（曾任黑龙江省财政厅长）','原黑龙江财政官员，投日后主管伪满经济，在哈尔滨、双城地区推行经济统制，掠夺粮食资源。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2115c2b655de49829e1377f306478b8c','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1935,'伪满洲国滨江省警务厅厅长','负责哈尔滨及双城地区伪警察系统，多次参与抓捕抗日地下工作者，实施白色恐怖。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fe407b21d2d94b4fb732e96455826f18','5a42f897a627483f9ceda7a629ea37f8',1938,'伪满洲国哈尔滨警察厅厅长','原哈尔滨警察，投日后任伪警察头目，直接指挥镇压哈尔滨市内的抗日组织，逮捕大量爱国志士。','市县厅局级','hanjian');
