INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a288b5f2d0684ae7b767a854c801388e','350822a1078340679fd657c16a793993',1933,'伪满洲国滨江省公署参事官','在双城地区推行“保甲连坐”制度，协助日军建立“集团部落”，制造无人区。','无明确职位或一般帮凶','hanjian');
