INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1f123cde6c5c4e9ba56fe22ca4f8e022','922b606d45c647e8a82755373b3d3e91',1936,'伪满洲国双城县警务科科长','在双城地区建立伪警察网络，参与“讨伐”抗日联军，杀害多名抗联战士及群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('15564a4a81054780917c680a58b5f7a9','3cd55e29febc489d9f9a7f2f88db31bb',1938,'伪满洲国哈尔滨特别市公署总务厅长','协助日本关东军管理哈尔滨市政，推行奴化教育，压制反满抗日言论。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8c94ee4068844157a9f90696e8a34955','1a8847af165d4d648f62d949fad6cb5a',1935,'伪满洲国滨江省高等法院院长','在哈尔滨审判抗日志士，以“反满抗日”罪名判处大量爱国者死刑或重刑。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('32c3ec5efc754e12bd8892192d2c05a5','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满洲国立法院院长、哈尔滨律师协会会长','原奉系法律顾问，投日后参与伪满立法，曾任哈尔滨地区司法要职，为日伪统治提供法律依据。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7dbaf83e8d2a4bdeab1c4d7423edf28d','1a8847af165d4d648f62d949fad6cb5a',1932,'伪满洲国哈尔滨警察厅厅长','负责哈尔滨地区日伪警察特务工作，残酷镇压抗日地下组织，逮捕杀害多名爱国志士。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5bdfa4402bba4c5ea141e1ef9d266c88','5cce8fcbbcc043c2820499553d6999c1',1933,'伪满洲国滨江省警务厅厅长','在呼兰、哈尔滨等地组织清乡讨伐，配合日军围剿抗联，制造多起屠杀事件。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('be9cc485bb0742f6a9def7971a69646e','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1932,'伪满洲国第四军管区参谋长（驻哈尔滨）','原东北军军官，投日后参与指挥伪军对抗联部队作战，在呼兰地区多次“扫荡”。；原东北军军官，投日后任伪第四军管区参谋长，参与指挥对珠河（今尚志）等地的抗日游击队围剿。；原东北军军官，投敌后任伪军参谋长，参与指挥“讨伐”抗联第三军等部队，活动于巴彦、木兰一带。；原东北军参谋，投日后驻哈尔滨，参与制定“讨伐”抗联计划，在平房周边制造无人区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f4653716e7ee4e9380f33ca7f80661fc','9dc1581eaee5417b8742c435470d1585',1932,'伪满洲国呼兰县县长','在呼兰县推行保甲制度，强征劳工，协助日军建立“集团部落”，迫害抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('64da68f58af944118ee603bd99adc2c7','867c6916f92d4b7c8718fef20595b7f0',1933,'伪满洲国呼兰县警务科科长','在呼兰地区抓捕抗联地下联络员，破坏抗日组织，参与“三光”政策行动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9d9015c2321342f1afafd07d618b49f6','3cd55e29febc489d9f9a7f2f88db31bb',1932,'伪满洲国哈尔滨宪兵队翻译官','为日本宪兵队充当翻译，参与审讯酷刑，直接迫害抗日志士及无辜平民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0907ca92580d4700b734d142a168f341','22ff391e74ef42b8aa8cefb952b8b5ca',1934,'伪满洲国滨江省教育厅厅长','推行奴化教育，在哈尔滨、呼兰各学校强制灌输“日满亲善”，禁止中国历史教学。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('15fbb1a815d0428b8b60406ff506bcab','e25c85c91f604ceda710a0637532c900',1932,'伪满洲国滨江省省长、伪第四军管区司令','原东北军将领，1932年投敌，任伪滨江省省长，镇压抗日武装，协助日军推行殖民统治，在哈尔滨、宾县等地清剿抗联部队。；原东北军将领，1932年投敌，任伪滨江省省长，镇压抗日武装，推行日伪殖民政策，在哈尔滨道里区设伪公署，协助日军清剿抗联；原东北军将领，投降日军后任伪滨江省（含哈尔滨及周边）省长，协助日军镇压抗日武装，推行“归屯并户”政策，制造无人区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('374b0f36cb5e4a46808174fcf7b82918','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满洲国滨江省省长、伪经济部大臣','原黑龙江省实业厅长，投日后任伪滨江省省长，在哈尔滨、宾县地区强征粮食、劳工，为日军提供物资，镇压抗联活动。；原黑龙江省实业厅长，投敌后历任伪滨江省省长，在哈尔滨道里区设立经济统制机构，为日军搜刮物资，迫害爱国商人；原哈尔滨商界人物，投敌后历任伪滨江省省长、伪经济部大臣，协助日本推行经济统制与物资掠夺。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b52f497477f94dcb89d2ce5ee4f2f18f','1a8847af165d4d648f62d949fad6cb5a',1933,'伪滨江省警务厅厅长','原哈尔滨警察头目，投日后任伪警务厅长，指挥警察特务在哈尔滨、宾县等地大肆搜捕抗联地下组织，杀害多名抗日志士。','市县厅局级','hanjian');
