INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1b18f02f63e44a5ca47735c283dbaa1e','b21d5a4d224a4173bdb0f2b366c98d70',1932,'伪宾县县长','原宾县地方官僚，投日后任伪县长，为日军征收粮税，强抓壮丁，多次配合日军扫荡宾县抗日根据地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e970ce753b8a492ba1631f6c8c0aea80','a4aa7dd7a5d0402dbb74db914ec24d5c',1933,'伪宾县警察署署长','原宾县警察，投日后任伪署长，率警察队协助日军围剿赵尚志领导的抗联第三军，在宾县多处设立情报点，出卖抗日群众。','无明确职位或一般帮凶','hanjian');
