INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0b5b8a524e254fa7af729917486b854e','249deb11cff046d48971926e13314723',1934,'伪哈尔滨市协和会总务部长','原哈尔滨日伪特务，投日后负责协和会特务工作，在宾县发展汉奸线人，破坏抗联地下网络。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('69f3b05302814f6ca93c3fdb0e085cff','2016b53248c64842a17c70a8339a899b',1933,'伪宾县自卫团总团长','原宾县大地主，投日后组织自卫团，配合日军“清乡”，在宾县各村搜查抗联伤员，杀害无辜百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('04c33030c73b4e6b8b0667e824db0f34','77a789268c6f47b4a617cdb9e41180bd',1932,'伪满洲国国务总理大臣（曾任哈尔滨特区长官）','原奉系军阀，九一八后投日，1932年任伪哈尔滨特区长官，后升任伪满国务总理，全面协助日本统治东北，包括哈尔滨及尚志地区。','伪政权最高层/元首级','hanjian');
