INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1317ed29cc9d4cc6a41c4f49d8f3c5d7','bde77533c68f469aa5eeb667ea3940ed',1932,'伪哈尔滨特别市市长（后任伪立法院院长）','原奉系法律顾问，投日后任伪哈尔滨市长，协助日本建立殖民秩序，参与制定镇压抗日法令。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2f9bd9801a75484ab821ecfccc0a12e3','9dc1581eaee5417b8742c435470d1585',1934,'伪滨江省警务厅厅长','负责哈尔滨及周边地区警察特务系统，多次组织搜捕抗日地下组织，破坏尚志地区抗联联络站。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9259eec12aa84b3f925bb3a19447a0b4','1ba31d558b934fbd83a28a8c2b446022',1932,'伪满洲国热河省省长（曾任洮辽镇守使，活动涉及哈尔滨）','原奉系军阀，投日后在东北多地活动，曾协助日军镇压哈尔滨、尚志地区抗日武装，后任伪省长。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('92787a6db28b49bfb0e2898525498ebf','c0860f9060d74dfba1674157f4596712',1932,'伪满洲国吉林警备军司令（活动涉及哈尔滨地区）','原吉林军将领，投日后率伪军参与对哈尔滨东部及尚志（珠河）抗日根据地的多次讨伐。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b1a3976ca9d04bcaa93084a59209f83c','2acf7a5b9b5341578e1066b27394b2eb',1933,'伪满洲国滨江省警备司令','原东北军旅长，投日后任伪滨江省警备司令，驻哈尔滨，指挥伪军对尚志、延寿等地抗联部队进行围剿。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e94d9b7af4cc4f70a29295ac363a7e31','350822a1078340679fd657c16a793993',1932,'伪满洲国哈尔滨警察厅厅长','原哈尔滨警察头目，投日后任伪警察厅长，残酷镇压反满抗日人士，曾参与抓捕赵尚志部队交通员。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2bfc205665aa4ec1be284378f21540d3','41502657c6b84465aa2ff94e620ed234',1932,'伪满洲国滨江省实业厅厅长','原黑龙江省政府官员，投日后在哈尔滨推行日伪经济掠夺，强征尚志地区木材、粮食资敌。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fde3749e454f45a3bf992f932d9c4dea','5a42f897a627483f9ceda7a629ea37f8',1933,'伪满洲国哈尔滨警察局副局长','协助日伪特务机关，在哈尔滨市区及尚志县建立情报网，多次破坏抗联地下组织。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2c61fa23d63547b8b3a937e9852d3774','922b606d45c647e8a82755373b3d3e91',1933,'伪珠河县（今尚志市）县长','在尚志地区任伪县长期间，推行保甲制度，组织伪自卫团，配合日军烧毁抗联密营，杀害抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1f206c5a18cb499f892573f461e16667','4cf8aeaf6c0a489280d8b86e1245978a',1934,'伪珠河县警务科科长','在尚志地区指挥伪警察，多次袭击赵尚志领导的抗联第三军，逮捕并杀害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2f2d3ce476784b2da914df9a8ae901cd','247dfbbaa63247e6972f3f1e381eadf4',1935,'伪珠河县协和会会长','在尚志地区宣传奴化思想，组织告密网，协助日军清乡，导致多处抗联秘密联络点被破坏。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f9d0ae4e9d9b4668823436df263a8501','3cd55e29febc489d9f9a7f2f88db31bb',1936,'伪满洲国滨江省保安局特高课长','在哈尔滨及尚志地区专门从事反间谍和镇压抗联活动，曾策划诱捕抗联干部。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5eaf20e2a21e4df6a29f29684666063e','a2c03b81e5f2412bb86f5d5599c1687b',1932,'伪哈尔滨市公署参事','协助日伪当局管理哈尔滨市政，参与制定针对抗日活动的管制措施，并参与经济掠夺。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('869070d216014776a068a7a7a48d2df0','46f570699efd413fa741462847e46f14',1933,'伪滨江省教育厅厅长','在哈尔滨及尚志地区推行奴化教育，强制学校使用日伪教材，打压爱国师生。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('024f63dfcc8a4c43ae2bd2e77630a85a','bfa3041f6dc946d29ef2b18120b9c0da',1935,'伪珠河县警察署署长','在尚志地区多次率伪警围剿抗联小分队，并参与制造“集团部落”，隔离群众与抗联联系。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('614f4d1491e644dca2b3e23d57484230','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满洲国黑龙江省省长（辖巴彦）','原黑龙江省实业厅长，投敌后任伪黑龙江省省长，推行日伪“治安肃正”，围剿抗联。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('43797b34671448ee81f27287ede78acd','77aa4951751342b79a81e38d021b4396',1932,'伪黑龙江省公署参事、巴彦县伪县长','原巴彦县士绅，投敌后任巴彦县伪县长，协助日军清乡，抓捕抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('706f1f795f6841a397f7b4dd94c16adf','9dc1581eaee5417b8742c435470d1585',1933,'伪哈尔滨警察厅厅长','原哈尔滨警察，投敌后任伪警察厅长，残酷镇压地下党和抗日群众，制造多起逮捕屠杀事件。；在哈尔滨残酷镇压抗日地下组织，抓捕、刑讯抗日志士，协助日本宪兵队制造多起惨案。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fd6d54296798474c9782e4d14634ce8a','5cce8fcbbcc043c2820499553d6999c1',1932,'伪哈尔滨特别市公署总务厅长','原哈尔滨市政官员，投敌后负责伪市政日常管理，配合日本特务机关监控居民。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1222e7b4cbcd4086a7fc5a777f7237f9','5d820a5b2b114c0e8312a21493c45d60',1932,'伪巴彦县警务科长','原巴彦县警察，投敌后任伪警务科长，组织伪警察队，多次袭击抗联游击队，杀害无辜百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('51f8897e09aa43f39f52668b2c57b2b2','3cd55e29febc489d9f9a7f2f88db31bb',1934,'伪滨江省警务厅长','原吉林省警察，投敌后任伪滨江省警务厅长，统辖哈尔滨及周边（含巴彦）伪警，参与“讨伐”抗联。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e151179213ed4a18975d61b8da0cc41f','5a42f897a627483f9ceda7a629ea37f8',1935,'伪哈尔滨警察局特务科长','原哈尔滨警察，投敌后任特务科长，专门侦捕抗日分子，破坏地下组织，罪行累累。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8e902cc3e6d241d8a2ded5b8daa08e41','41502657c6b84465aa2ff94e620ed234',1932,'伪满洲国财政部大臣（曾任黑龙江省财政厅长）','原黑龙江省财政厅长，投敌后任伪财政要职，为日伪搜刮民财，支持“治安肃正”经费。；原黑龙江财政官员，投日后为日军筹措军费，在哈尔滨地区强征苛捐杂税，导致民不聊生。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('462b3fd9d1a74c568318b3ce92574b52','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洲国侍从武官长、伪热河省长','原洮辽镇守使，率先投日，参与组建伪军，在黑龙江、热河等地协助日军清剿抗日武装。；原洮辽镇守使，率先投日，率部进攻抗日义勇军，后任伪满要职，参与对黑龙江地区的殖民统治。；原洮辽镇守使，九一八后公开投日，率部配合日军进攻黑龙江，后任伪满要职。；原洮辽镇守使，1931年投日，在黑龙江地区参与镇压抗日义勇军，后任伪满要职。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('723769a850a24dfca56c5daef00559a1','2acf7a5b9b5341578e1066b27394b2eb',1932,'伪满洲国滨江省省长（哈尔滨地区）','原东北军师长，投日后任滨江省省长，管辖哈尔滨及平房一带，推行殖民政策，镇压反满抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('daa6341177a942b8a138017c167527b7','69f38ea2adad4635bb217a6e5aadda7e',1937,'伪哈尔滨特别市市长','原外交官，投日后任哈尔滨市长，配合日本特务机关搜捕抗日分子，管理平房地区治安。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7520d2a9c69e4cbc90ee683563d16de7','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满洲国立法院院长（曾任哈尔滨律师公会会长）','原哈尔滨著名律师，投日后参与伪满立法，为日本侵略提供法律依据，曾参与镇压哈尔滨学生反日运动。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1afa4a3d7aac44b79ac6785941460873','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满洲国经济部大臣（曾任黑龙江省长）','原黑龙江实业家，投日后任伪黑龙江省长，在哈尔滨地区推行经济统制，为日军筹措军费。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('60111da622584b98ae786be2734ae0ee','41502657c6b84465aa2ff94e620ed234',1932,'伪满洲国财政部大臣（曾任滨江省省长）','原吉林财政厅长，投日后任滨江省长，在哈尔滨及平房地区推行“保甲制度”，协助日军清乡。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e2fbd353011d490382c77655fadebaf5','350822a1078340679fd657c16a793993',1932,'伪满洲国滨江省警务厅长','原哈尔滨警察头目，投日后主管哈尔滨及平房地区警务，直接参与逮捕抗联地下工作者。；在哈尔滨及黑龙江各地组织警察特务，抓捕抗日志士，参与“七三一”部队相关人体实验的掩护工作。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c19774f812184fb18d5809cf20fe04c4','5a42f897a627483f9ceda7a629ea37f8',1933,'伪哈尔滨警察厅厅长','原哈尔滨警察，投日后任伪警察厅长，在平房地区设立多个警察分所，配合731部队“特别移送”实验人员。；指挥伪警察在哈尔滨及木兰等地抓捕抗日地下工作者，破坏抗联联络站。','市县厅局级','hanjian');
