INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bbf60ec44a274c068bc643b842caffe6','3cd55e29febc489d9f9a7f2f88db31bb',1935,'伪滨江省保安局局长','在哈尔滨及平房地区组织保安队，配合日军“扫荡”，杀害抗联伤员。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('332b28c0b1304ce88d83a8ab53f7728f','3b74f508628f475a8777ffb7e38a48a0',1932,'伪黑龙江省省长、伪滨江省省长','原黑龙江省实业厅长，投日后历任伪黑龙江省长、伪滨江省长（哈尔滨地区），积极为日军征粮、镇压反满抗日活动。；原黑龙江省实业厅长，投日后任伪省长，积极推行日伪殖民政策，在哈尔滨、方正等地组织清乡，迫害抗日军民。','省部级/大军区级要员','hanjian');
