INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7c96ae6b32304595b8e1958de3cc960f','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1932,'伪满第四军管区参谋长（驻哈尔滨）','原东北军军官，投日后在哈尔滨协助日军清剿抗联，参与策划多次“讨伐”行动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('151ee36d135d4bc399a9e88ef05dbc3e','5cce8fcbbcc043c2820499553d6999c1',1935,'伪哈尔滨警察厅特务科科长','专门负责反谍，破坏中共哈尔滨地下组织，逮捕多名抗联交通员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5a4d43b3be8a4b008c2de3096494c1ec','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满热河省长（曾活动于黑龙江地区）','原洮辽镇守使，投日后在黑龙江北部协助日军镇压马占山等抗日力量，后调任热河。；原洮辽镇守使，投日后在黑龙江北部协助日军清剿抗日武装，后调任热河。；原奉系军阀，投日后在多地任职，曾参与指挥对黑河、爱辉地区抗日武装的围剿。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('22dab67b561c4954bd5a1bae50f3348b','b8f5150658fd47f0a48c92aacb628181',1932,'伪黑龙江省省长（短暂，后反正）','1932年2月一度接受伪职，任伪黑龙江省长，但4月反正抗日，故严格意义上非终汉奸，但历史记录中列入。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5bb31e626d8741cfad2e5399d8c90242','3c793b1442ef48298a262b0d57814cab',1932,'伪黑龙江省警备司令（齐齐哈尔/黑龙江地区）','原马占山部旅长，1932年投日，任伪警备司令，在黑龙江北部围剿抗日义勇军。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d405a13114724b75a44d1bdc43a5544f','12571fd3a6fa42cf9581b18a4b27a94e',1933,'伪满第三军管区司令（驻齐齐哈尔，管辖黑龙江西部）','原东北军团长，投日后在黑龙江地区多次“讨伐”抗联，烧毁村屯。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5d7b6be96ef1433faf4ac14fc5ad784c','c9dffc071fec4ce58fe1d611f26c28da',1934,'伪满滨江省警务厅厅长','在哈尔滨及延寿等周边县推行保甲连坐，组织汉奸特务网，捕杀抗联后勤人员。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dbb576868c594c72bf091ac349535605','0a5ef2225c224dd4b656484ab871ff6a',1932,'伪延寿县县长','在延寿县为日军征粮、抓劳工，镇压当地抗日救国会，破坏抗联密营。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ca2e17c222084afc8a578f13ffe9da71','ba135ba1ef794aeba0fdad0065a31974',1933,'伪延寿县警察署署长','在延寿地区搜捕抗联战士，严刑拷打群众，提供情报导致多处抗联联络点被毁。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a5f7728d01a343db970a0e5e32272a09','a2c03b81e5f2412bb86f5d5599c1687b',1935,'伪延寿县协和会会长','在延寿推行奴化教育，组织“协和会”宣传亲日，告发抗日分子。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e34c80a91b114903979a38b7070c8b28','bedc991fdcff4254a3e2b0b24052d010',1936,'伪哈尔滨地区“讨伐”队队长','率汉奸武装在哈尔滨郊县（含延寿）追击抗联第三军，杀害多名抗联伤员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e01782e4a5274ad7a6799fbea3e6062e','3cd55e29febc489d9f9a7f2f88db31bb',1937,'伪满滨江省地方保安局局长','在哈尔滨及延寿等地建立情报网，破坏抗联地下兵站。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('88864850a31d47b8b4925ff72e3695d2','4b486850921b4f33b616f1f8dcdef313',1932,'伪哈尔滨特别市市长、伪滨江省省长','原哈尔滨特区行政长官，投日后任伪市长，协助日军建立特务统治，镇压反满抗日活动，参与经济掠夺。；曾任伪哈尔滨市长及滨江省省长，积极推行日伪统治，参与经济掠夺。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4e20872a3e3b44838ab61fa3ad35d6ca','3eb966fdcf364389b5302ef8a669f7ac',1937,'伪滨江省省长','原吉林省政府官员，投日后任伪滨江省省长，管辖哈尔滨及周边地区，推行“治安肃正”，对抗联进行多次讨伐。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1ff70ffe9fa84c709329988f11d75cf2','41502657c6b84465aa2ff94e620ed234',1935,'伪黑龙江省省长、伪滨江省省长','原黑龙江省政府委员，投日后历任伪省长，在方正地区设立伪警察机构，协助日军抓捕抗日志士。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a63b6c9dc4c447939afa776e689baaa1','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1933,'伪滨江省警务厅厅长','原哈尔滨警察头目，投日后负责伪滨江省警务，指挥警察与特务在哈尔滨、方正等地搜捕抗联地下组织。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0d254fdebb8649da9e2f5c36a739093c','5cce8fcbbcc043c2820499553d6999c1',1932,'伪哈尔滨警察厅厅长','原哈尔滨警察署长，投日后任伪警察厅长，直接参与制造多起屠杀事件，在方正地区实施“归屯并户”。；原哈尔滨警察头目，投日后任伪警察厅长，直接参与“四一五”大逮捕，杀害多名抗联地下工作者。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f1c9356ed60d474b95f583fae215f818','9dc1581eaee5417b8742c435470d1585',1932,'伪方正县县长','原方正县地方士绅，投日后任伪县长，为日军提供粮食物资，组织伪自卫团对抗抗联，迫害当地百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('17be40c1a46c433482256ce350ab37bf','867c6916f92d4b7c8718fef20595b7f0',1936,'伪方正县县长','投日后任方正县伪县长，配合日军“三光政策”，在方正山区多次带路围剿抗联第三军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3b5756a5feb44f18b992dd8c0576d799','3cd55e29febc489d9f9a7f2f88db31bb',1934,'伪方正县警务科科长','原方正县警察，投日后任伪警务科长，指挥警察抓捕抗联交通员，破坏地下联络站，杀害多名抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8d4f513125a341de9104235344a7badc','a2c03b81e5f2412bb86f5d5599c1687b',1938,'伪方正县协和会会长','投日后任伪协和会方正县会长，宣传“日满亲善”，组织汉奸团体，协助日军强征劳工与粮食。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2d5fb9726d5d4175a371e149bdd35e2e','1e54500c401c434486b34d8492fafd8c',1933,'伪哈尔滨保安队队长','原哈尔滨市警察，投日后任伪保安队长，参与镇压1933年哈尔滨电车工人罢工，在方正地区参与“讨伐”抗联。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('40a6d4e6db4d4ec389610c39007db711','5568708bb9b44d7a93d6adfffc6882f0',1935,'伪滨江省警备队队长','投日后任伪警备队长，在方正、通河一带多次袭击抗联小分队，杀害抗日伤员，抢夺百姓财物。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1c0d676338ae406891ed1214fd418f61','1ba31d558b934fbd83a28a8c2b446022',1932,'伪满热河省省长（曾活动于黑龙江地区）','原奉系军阀，投日后任伪满军事顾问，曾率伪军参与对哈尔滨、方正地区抗联的围剿，烧毁村屯。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cdb199e4780c4ee09302fdc05f612ff9','b8f5150658fd47f0a48c92aacb628181',1932,'伪黑龙江省省长（短暂投敌后反正）','1932年2月一度投日任伪省长，但同年4月反正抗日，其投日期间未在方正地区有重大恶行，故列为历史争议人物。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b3e2a2b0e3af4e2f94a886897cbcd4d5','3c793b1442ef48298a262b0d57814cab',1932,'伪黑龙江省警备司令','原黑龙江骑兵师长，投日后任伪警备司令，在哈尔滨周边及方正地区指挥伪军对抗联进行多次“清剿”。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('304ab14e9cf742e7988cf78b7cdb3803','880f860ec52b4dc6ad598533842d7cb9',1932,'伪海拉尔警备司令（短暂投敌）','1932年一度投日，但随即反正，未在方正地区活动，仅列名参考。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2046238138fa46e18114080a462a999e','b7f4958fab3a494e9991cc9a1976f427',1939,'伪方正县参事官（日本人顾问下的汉奸）','投日后任伪方正县参事官，协助日本参事官管理县政，强征民夫修筑警备道路，迫害抗联家属。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('614552dcf3d84557982b6aae236ae158','e25c85c91f604ceda710a0637532c900',1932,'伪满洲国黑龙江省省长、伪第四军管区司令','原东北军将领，投日后任伪黑龙江省长，协助日军镇压抗日武装，推行殖民政策。；原东北军将领，1932年投敌，任伪黑龙江省长，协助日军镇压抗日武装，推行殖民政策。','省部级/大军区级要员','hanjian');
