INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('119238d70ff94a2a916ab24c102ab1f6','3b74f508628f475a8777ffb7e38a48a0',1932,'伪黑龙江省财政厅长、伪滨江省省长','投日后历任伪职，在黑龙江及哈尔滨地区协助日军征收物资，镇压抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('96aade3dde5d4dd289d5b9de7d7b2565','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1932,'伪黑龙江省警务厅长','负责伪满警察系统，在黑龙江各地搜捕抗日人员，制造多起惨案。；组织伪警察配合日军“讨伐”抗联，抓捕杀害抗日志士，实施“归屯并户”。；原黑龙江省警察头目，投日后组织伪警察配合日军“讨伐”抗联，在绥化、明水地区抓捕抗日群众。；原黑龙江省警察头目，投敌后任伪警务厅长，在齐齐哈尔及昂昂溪地区大肆搜捕抗日分子，残害民众；原警察系统官员，投日后任警务厅长，指挥伪警察搜捕抗日分子，参与制造多起惨案。','市县厅局级','hanjian');
