INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a0042cc2c98742ce9b6bee258ade07fb','5cce8fcbbcc043c2820499553d6999c1',1932,'伪木兰县县长','在木兰县任伪县长期间，强征粮税，配合日军讨伐抗联第三军，残害百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dca5604334194ae1ac5dd9de46778d5a','ba135ba1ef794aeba0fdad0065a31974',1933,'伪木兰县警务科长','在木兰县组织伪警察队，多次参与围剿抗联赵尚志部队，杀害抗日群众。','基层头目','hanjian');
