INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4aa112d415124731aa6cab872d776460','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满洲国黑龙江省省长','原黑龙江省实业厅长，投日后任伪黑龙江省长，在哈尔滨地区推行日伪统治。；原黑龙江省实业厅长，投日后任伪省长，在齐齐哈尔及黑龙江各地推行“保甲连坐”，屠杀抗日群众。','省部级/大军区级要员','hanjian');
