INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cfbf5c351eb64c2c8f2449444bf1c6a4','bde77533c68f469aa5eeb667ea3940ed',1932,'伪哈尔滨特别市市长、伪立法院院长','早年留学日本，投敌后出任伪哈尔滨市长，协助日军建立殖民秩序，后升任伪满立法院院长，为日本侵略政策服务。；原奉系法律顾问，投日后任伪哈尔滨市长，在道里区推行日伪法令，镇压学生运动，参与策划对抗日志士的逮捕','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e9d6d12208764b5083b5dc8425d0e096','9dc1581eaee5417b8742c435470d1585',1935,'伪通河县县长','在通河县任内积极推行日伪“归屯并户”政策，强迫民众迁入集团部落，配合日军封锁抗联，导致当地百姓大量伤亡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('25e5e58d1e5d4e93b98084de011614e2','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洲国热河省省长（曾任黑龙江地区伪军头目）','原为洮辽镇守使，九一八后投敌，其部队在黑龙江、哈尔滨周边参与围剿抗日义勇军和抗联，烧杀抢掠无恶不作。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ad91126926074b71a7de998d118f1cf3','b8f5150658fd47f0a48c92aacb628181',1932,'伪满洲国军政部总长（短暂投敌后反正）','曾一度投降日军并出任伪职，在哈尔滨、齐齐哈尔地区活动，但不久反正抗日，故其汉奸身份具有短暂性，仍列入历史记录。；曾一度在哈尔滨道里区与日伪谈判并任伪职，但不久反正抗日，此条列为历史争议人物，其投敌期极短，主要活动在黑龙江地区','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fdbdd7e2e6d34683a22c9c7545f4c7dd','2acf7a5b9b5341578e1066b27394b2eb',1932,'伪满洲国滨江省省长','原东北军旅长，投日后任滨江省（辖哈尔滨）省长，推行日伪法令，强征劳工，迫害反满抗日人士。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8b6774704f634955be2b666e008c0248','bde77533c68f469aa5eeb667ea3940ed',1932,'伪哈尔滨特别市市长、伪满洲国立法院院长','原奉系法律顾问，投日后首任伪哈尔滨市长，后任伪满立法院院长，参与制定镇压抗日的法令。','伪政权最高层/元首级','hanjian');
