INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('73142b3f77f44a85b3c97b7322c9cf43','3cd55e29febc489d9f9a7f2f88db31bb',1932,'伪满洲国滨江省高等法院院长','在哈尔滨审判抗日志士，判处大量爱国者死刑或长期监禁，是日伪司法镇压的帮凶。','无明确职位或一般帮凶','hanjian');
