INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ee8cb5d539184b5ea26cda628ccc9df3','e52c0f125aab401ab1f40b3214908bd8',1933,'伪哈尔滨特别市警察局副局长','在道外区指挥特务活动，破坏抗联地下联络站，导致多名地下党员被捕牺牲。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b4c1c56967a7449e828cc8db442a38a7','9dc1581eaee5417b8742c435470d1585',1932,'伪哈尔滨道里区区长','原地方士绅，投日后任伪道里区区长，协助日伪推行保甲制度，强征捐税，出卖抗日情报，导致多名抗联战士牺牲','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('16497b9770c84412adba9bbb7b0d1b07','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洲国热河省省长（曾驻哈尔滨道里）','原洮辽镇守使，投敌后任伪省长，在哈尔滨道里区设有公馆，参与日伪高层决策，协助镇压东北抗日联军','省部级/大军区级要员','hanjian');
