INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('455ec56427564272834dd2b6dbcb50e2','355c8519368e49bca88dec6c9efb42e6',1933,'伪哈尔滨道里区保安队队长','地方恶霸投敌，任伪保安队长，在道里区欺压百姓，为日军提供劳工，参与抓捕抗日志士，民愤极大','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('265eefbc8beb4f65b68fdb19d4f8c7d0','7586e178e7504332969c36318cdc1806',1932,'伪满洲国哈尔滨市公署参事','原哈尔滨商会会长，投日后任伪参事，在道里区组织“协和会”，为日军募捐，宣传“日满亲善”，破坏抗日统一战线','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e0cbccaae5df4de3a5625f0cc171460e','9d25e1d3d8e543ee84de82f230352248',1934,'伪哈尔滨道里区协和会会长','原工商业主，投日后任协和会会长，在道里区组织汉奸团体，监视居民，强迫民众参加“庆祝”活动，协助日伪征兵','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('59a4f332c30c4a91ade2127dea493ed3','77aa4951751342b79a81e38d021b4396',1932,'伪满洲国哈尔滨高等法院院长','原司法界汉奸，在道里区审判抗日人士，以“反满抗日”罪名判处多人死刑或长期监禁，是日伪司法镇压的帮凶','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e4334216ae7449a1b88fa2d007e5d2ab','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满洲国滨江省省长、财政部大臣','原哈尔滨富商，投日后任伪滨江省省长，管辖哈尔滨、阿城等地，积极推行日伪经济统制，镇压反满抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dc294a04d9d747eda155aa2ed0702733','4b486850921b4f33b616f1f8dcdef313',1932,'伪满洲国滨江省省长、司法部大臣','原哈尔滨特区行政长官，投日后任伪滨江省省长，在哈尔滨地区协助日军建立伪政权，参与“治安肃正”行动。；原哈尔滨特别市市长，投日后在黑龙江地区推行奴化教育，协助日军清剿抗联。','省部级/大军区级要员','hanjian');
