INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0d2476e75dca429198d1211e33b6345b','3eb966fdcf364389b5302ef8a669f7ac',1932,'伪满洲国滨江省民政厅厅长、哈尔滨市市长','原吉林省政府官员，投日后任伪滨江省民政厅长，后任伪哈尔滨市长，负责城市治安和奴化教育。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7a33eb4edf804f758efc05fcc02e7692','5d820a5b2b114c0e8312a21493c45d60',1932,'伪哈尔滨警察厅厅长','原哈尔滨警察头目，投日后任伪警察厅长，直接指挥逮捕、刑讯抗日志士，制造多起惨案。','市县厅局级','hanjian');
