INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9452ea540f404f7f86a705443b2d69a3','5a9e800efe5a400492466b6f0ab8e7b6',1932,'伪哈尔滨特别市公署参事','原哈尔滨商会头目，投日后协助日伪经济统制，为日军筹集物资，出卖抗日情报。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b319f33c1d9247c9b5c04fa639789c97','41502657c6b84465aa2ff94e620ed234',1932,'伪满洲国财政部大臣（曾任滨江省财政厅长）','原黑龙江省财政官员，投日后任伪滨江省财政厅长，在哈尔滨、阿城地区强征苛捐杂税，搜刮民财。','市县厅局级','hanjian');
