INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d3e0c2e2c10d4816a957e76a053955cc','17ba4ca514844dcbb95b21c193e11290',1935,'伪滨江省警务厅厅长','在哈尔滨及香坊地区指挥伪警察和特务，参与多次大搜捕，破坏抗日组织，逮捕并杀害多名抗联战士及地下党员。','市县厅局级','hanjian');
