INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('88ebc6dd666541e393b21ab0997d9821','3c793b1442ef48298a262b0d57814cab',1932,'伪黑龙江省骑兵师长、伪兴安北省警备军司令','原马占山部旅长，投日后驻防大兴安岭地区，率伪骑兵围剿抗联第三路军。','市县厅局级','hanjian');
