INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3b417da3bd034dbfbfabd858178bd0c6','2eb96a1f022e434e830b2d5e2d6b720b',1932,'伪兴安北省省长（辖大兴安岭西部）','蒙古王公投日，任伪兴安北省省长，协助日军控制大兴安岭地区，征召伪蒙古军。','省部级/大军区级要员','hanjian');
