INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ddb47dce04ff4539a5f0f5349e0812bd','5cce8fcbbcc043c2820499553d6999c1',1932,'伪黑龙江省高等法院院长','审判抗日人士，判处抗联战士死刑，协助日军镇压加格达奇地区反抗。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9b8209835d8d4c5d8b17d12c8a9ad362','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满洲国立法院院长、伪哈尔滨特别市市长','原哈尔滨律师，投日后任伪哈尔滨市长，协助日军建立殖民统治，镇压当地反满抗日力量。；曾参与伪满建国，任哈尔滨市长期间协助日本控制北满，镇压反日力量，涉及黑龙江地区行政与司法。；积极参与伪满建国，曾任哈尔滨市长，协助日本关东军控制北满，镇压反满抗日活动，推行奴化教育。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('52594bbb268e442c82194b82d2c25ad8','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满洲国黑龙江省省长、伪经济部大臣','原黑龙江省实业厅长，投日后任伪省长，推行日伪经济掠夺政策，参与围剿大兴安岭地区抗联部队。；原黑龙江省实业厅长，投敌后任伪省长，为日军搜刮粮食、物资，支持“治安肃正”行动，对抗联根据地造成严重破坏。；辽宁金州人，投敌后历任伪黑龙江省长、经济部大臣，推行经济统制，为日军掠夺黑龙江资源服务。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('24d8df206ee94826ad9eb8d90fb641ab','4b486850921b4f33b616f1f8dcdef313',1932,'伪满洲国滨江省省长、伪司法部大臣','原哈尔滨特区行政长官，投日后任伪职，协助日军在黑龙江地区建立保甲制度，迫害抗日军民。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a28e7bd611b44708bab329161b3e3075','5a42f897a627483f9ceda7a629ea37f8',1932,'伪满洲国哈尔滨警察厅厅长、伪滨江省警务厅长','原哈尔滨警察，投日后任伪警头目，直接指挥特务警察搜捕抗联地下组织，在呼中及大兴安岭边缘地区进行“讨伐”。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('43b011ae4de64d4ebbb2289f15be7775','5cce8fcbbcc043c2820499553d6999c1',1934,'伪满洲国黑河省省长','原黑河地区官僚，投日后任伪省长，配合日军对黑龙江北部及大兴安岭林区进行封锁和“清剿”。；原黑河地区官僚，投日后任伪黑河省长，管辖大兴安岭北部及黑龙江沿岸，协助日军封锁抗联国际通道。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e5883954e0b941a6a7f49e1847907c0a','9bddbed4fd004b8dbc21ffa011e5e42c',1932,'伪满洲国兴安北省省长（辖呼伦贝尔及大兴安岭西麓）','原呼伦贝尔副都统，投日后任伪兴安北省省长，协助日军控制大兴安岭地区，镇压当地蒙古族和鄂伦春族抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3979ba1382f14f6bbffbd35a731d1866','dddf6075e9614f79add415cba2b3c0c4',1932,'伪满洲国兴安北省省长（早期）','原呼伦贝尔总管，投日后任伪省长，后因与日军产生矛盾被处决，但在任期间曾配合日军对大兴安岭地区进行统治。；蒙古族王公，投日后任伪省长，后因与日本关东军矛盾被处死。其在任期间参与大兴安岭地区的殖民统治。；蒙古族贵族，投日后任伪职，因与日本关东军矛盾被处死，但其在任期间参与对嫩江流域的殖民管理','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b30e3f78592b4f45903b5337550e00cb','2eb96a1f022e434e830b2d5e2d6b720b',1933,'伪满洲国兴安军司令官（驻大兴安岭地区）','蒙古族贵族，投日组织伪兴安骑兵，参与对大兴安岭抗日游击队的多次围剿，残害抗联战士及平民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('11cbee6fb5fb4b8ba29324ed0de5a2d7','25e14c6523f347349389d63d8a7056ac',1935,'伪满洲国兴安军第10团团长（驻呼中附近）','蒙古族军官，率伪军在大兴安岭呼中、呼玛一带搜捕抗联第三路军，烧毁村屯，屠杀支援抗联的百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('84a6b0b4ffb942e193841c449cfeb0a2','3a9e402192aa460fb51a927d874bb93e',1938,'伪满洲国黑河省警察讨伐队队长','原土匪头目，投日后任伪警察讨伐队长，专门在大兴安岭北麓和呼中林区追踪抗联部队，多次制造惨案。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('20869ec1c8364ee699298355c522d362','da6f17e868e9437188e6e2fe108446d0',1934,'伪满洲国呼玛县县长（辖呼中地区）','投日后任呼玛县伪县长，推行“集团部落”政策，强迫呼中地区鄂伦春族和汉族居民迁移，切断抗联补给。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a20b55b9c1214b2cb46f6ebf5434280a','1ba31d558b934fbd83a28a8c2b446022',1932,'伪满洲国热河省省长（曾参与黑龙江北部“讨伐”）','原奉系军阀，投日后任伪省长，曾派伪军协助日军在大兴安岭东部地区围剿抗联，烧毁多处密营。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('811b91a48f644180ab113437ae1bba93','5f82d23ccd2e45fd9e59f76c92bcc9ad',1933,'伪蒙古军总司令（活动范围含大兴安岭西麓）','原热河地方武装头目，投日后任伪蒙军司令，多次配合日军对大兴安岭地区抗日武装进行军事“扫荡”。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('57e06e9b191d4bdb9779cabced762d96','15bce57e594e4d2baa94695c4c20822e',1937,'伪满洲国黑河省警务厅特务科长','负责黑河及大兴安岭北部特务工作，组织密探潜入呼中林区，破坏抗联地下交通线，逮捕多名抗联联络员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('76ee015a9c1e49f9ba831033a68c535b','93f14e1340304e9cac4d12a04a6586a6',1939,'伪满洲国呼中地区山林警察队队长','原鄂伦春族猎户，投日后任山林警察队长，熟悉大兴安岭地形，引导日军袭击抗联第三路军后方基地。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8a1572583aba49e398ecc07cd84ba42c','700ea8f652a641d593ca58910042e249',1935,'伪满洲国漠河县县长（辖呼中西北部）','投日后任漠河伪县长，配合日军在黑龙江上游及大兴安岭林区设立检查站，截杀抗联运输队。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d5e50266d9b846e0a9216220187ed507','ab3dded23c7447adb919b9a8705e1bf9',1938,'伪满洲国呼玛县警察署署长','在呼中地区组织“自卫团”，协助日军搜捕抗联伤员，多次带队袭击抗联密营，杀害被俘人员。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0962336f6dc4402fb3fdde07eb888223','47cac7a73af140d39ff53133e8cfe760',1934,'伪满洲国兴安军骑兵旅旅长（驻大兴安岭南麓）','原东北军军官，投日后任伪骑兵旅长，率部在呼中、松岭等地追击抗联小分队，造成抗联重大损失。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('abdf2008ae044f99a5a8b9157a9b697a','e25c85c91f604ceda710a0637532c900',1932,'伪满洲国黑龙江省省长、伪满治安部大臣','曾任东北军将领，后投敌叛国，任伪黑龙江省长，积极推行日伪殖民政策，镇压抗日武装，参与“讨伐”东北抗联部队。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b71bd38d506548f995658f144ccf3e5d','77aa4951751342b79a81e38d021b4396',1932,'伪满洲国黑龙江省公署参事官、呼玛县县长','在呼玛地区任职期间，协助日军建立伪政权，强征劳工，搜刮粮食，迫害抗日军民，为日本侵略者提供情报。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a1fd3d94507e4999b56424f0c8f13dc0','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洲国热河省省长（曾长期在黑龙江活动）','原东北军将领，九一八事变后投敌，在黑龙江地区协助日军镇压抗日义勇军，后任伪省长，推行奴化教育。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6823806762254adbbc9f5cea08e244a8','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满洲国黑龙江省财政厅长、实业厅长','在黑龙江任职期间，为日军筹措军费，强征民间物资，参与建立经济统制体系，压榨当地百姓。；负责为日军筹措军费，强征粮食和物资，参与经济掠夺，迫害当地民众。；原黑龙江省官员，投日后负责经济掠夺，强征粮食、矿产，支持日军在鹤岗煤矿的剥削。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c6aa255bc22240858376bd673089825c','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1932,'伪满洲国黑龙江省警务厅长','指挥伪警察配合日军围剿抗联，在呼玛、漠河等地设立警察据点，逮捕杀害抗日志士。；在向阳区及周边组织伪警察，搜捕抗日分子，参与“讨伐”抗联行动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0c082c51d2294660b2863fa73716750e','b21d5a4d224a4173bdb0f2b366c98d70',1933,'伪满洲国呼玛县参事官（日本人实际控制下的汉奸代表）','在呼玛县协助日本参事官管理地方，强征当地鄂伦春族等少数民族为日军效力，破坏抗联后方基地。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('599417a26f8d4b889879ba3128c00b9e','a02eed53805847c38d732cc4c1d4bd3a',1934,'伪满洲国黑河省（含呼玛）警务科科长','组织伪警察队多次袭击抗联三路军后方机关，在呼玛河流域烧毁村屯，强迫居民归屯并户。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4f3aceceabeb45c3b397c280aa0526db','6960ecf5067148b08c7571d02c447623',1935,'伪满洲国呼玛县保安队队长','率保安队配合日军“讨伐”抗联，在呼玛县金山镇等地杀害抗联伤员，抢夺群众粮食。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('229e494160f447b3aa06309ecb8369aa','00da8d0b970f4c7eae5313bd1c3045e1',1936,'伪满洲国呼玛县兴安警察署署长','在大兴安岭地区搜捕抗联联络员，破坏地下交通线，曾亲自刑讯逼供抗日群众。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('30ef4c6990cf4fb49ed99371a317402d','8b9e32820b3b4045b0b76dd36d9d7f24',1937,'伪满洲国黑河省（呼玛地区）特务机关密探','长期潜伏在呼玛、漠河边境，向日军报告抗联及苏联情报，导致多支小分队被围歼。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('66987d40ced6450fb42082cb7a05a4a4','77a789268c6f47b4a617cdb9e41180bd',1932,'伪满洲国国务总理大臣、伪黑龙江省省长（早期）','原奉系将领，投日后任伪满最高行政长官，管辖黑龙江地区，全面配合日本殖民政策，支持对大兴安岭林区的资源掠夺。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1016e76f0be54021903c4dabbec753fd','3b74f508628f475a8777ffb7e38a48a0',1932,'伪黑龙江省省长、伪满洲国经济部大臣','原黑龙江省实业厅长，投日后任伪省长，协助日军清剿抗联，在塔河及大兴安岭地区推行“归屯并户”和物资统制。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('906db9dddce24b468a110e6a5200e18e','41502657c6b84465aa2ff94e620ed234',1933,'伪黑龙江省省长、伪满洲国财政部大臣','曾任伪黑龙江省长，负责北满地区行政，配合日本关东军对大兴安岭地区的军事“讨伐”和经济掠夺。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dfb633a1dfd348f59883af785819a3eb','350822a1078340679fd657c16a793993',1934,'伪满洲国黑河省省长','管辖黑龙江北部（含大兴安岭北麓），配合日军对抗联第三路军等部队的围剿，推行“治安肃正”政策。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('947cb00be9bf46a1b6d8141004a455e8','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1933,'伪满洲国黑河省警务厅长','在黑河及大兴安岭地区组织伪警察和特务，搜捕抗联地下人员，参与制造多起屠杀事件。；原黑河地区警察头目，投日后任伪警务厅长，在黑龙江北部及大兴安岭地区建立特务网络，逮捕抗联联络员，残害百姓。；原黑河警察头目，投日后任伪黑河省警务厅长，在漠河、呼玛及大兴安岭林区组织特务网，多次破坏抗联密营。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3abe7bdee54f4e049e3a29a247432886','1ba31d558b934fbd83a28a8c2b446022',1932,'伪满洲国热河省省长（曾驻黑龙江）、伪满军政部大臣','原洮辽镇守使，投日后在黑龙江西部及大兴安岭边缘地带参与镇压抗日义勇军，后任伪满军事高官。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('81363e1817c54cedbd4638301709a04a','b8f5150658fd47f0a48c92aacb628181',1932,'伪黑龙江省省长（短暂投日时期）','1932年2月一度投降日军，任伪黑龙江省长，但同年4月反正，重新抗日。其投日期间在齐齐哈尔及黑龙江地区活动，后恢复抗日身份。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('df44e8b44dd14846a644793178b44d48','3c793b1442ef48298a262b0d57814cab',1932,'伪黑龙江省警备司令、伪满骑兵师长','原马占山部将，随马占山投日后留任伪职，在黑龙江北部及大兴安岭地区参与“讨伐”抗联，后长期为日军效力。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b3922efd66654eb096989ab43092ca4f','12571fd3a6fa42cf9581b18a4b27a94e',1932,'伪满洲国兴安北省省长（辖大兴安岭西部）','管理呼伦贝尔及大兴安岭西麓地区，协助日本对鄂伦春等少数民族进行控制，并参与对抗联的军事行动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a9ff2a5ecc254a6c8cb653338281161b','6dec6f2201c84d729ec0c0b13ca17e6e',1932,'伪满洲国兴安东省省长（辖大兴安岭东麓）','管理大兴安岭东侧（含塔河邻近地区），配合日军“讨伐”抗联，推行保甲制度。；原达斡尔族贵族，投日后任伪兴安东省省长，管辖今黑龙江大兴安岭地区东部，为日军提供向导，参与“讨伐”抗联。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('82d8a92046cb459687772b8d5dd22009','122ebac0f99e4b85b2dfa0e9c0e16b0e',1933,'伪满洲国兴安北省警务厅长','在大兴安岭北部地区组织伪警察，参与搜捕抗联小分队，迫害当地少数民族。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1131a0212b7346089de39477a38656aa','25e14c6523f347349389d63d8a7056ac',1938,'伪满洲国兴安军司令官（驻大兴安岭地区）','指挥伪兴安军在大兴安岭林区对抗联进行多次“围剿”，后于1945年8月率部反正。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('309bfaee57ed4d6481b015bb6a410ebe','31abdc5e4e0a4ebdbe5f0b715a509863',1936,'伪满洲国黑河省民生厅长','在黑河及塔河周边推行“集团部落”政策，强制居民迁移，切断抗联与群众联系。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('70eeebe76b56402bab4360f9c6e2685f','b21d5a4d224a4173bdb0f2b366c98d70',1937,'伪满洲国黑河省参事官','作为日本关东军代理人，在大兴安岭北麓地区监督伪政权运作，参与对抗联的“冬季讨伐”。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('00cb1194656e4bd7a506248513287dc8','ab3dded23c7447adb919b9a8705e1bf9',1934,'伪满洲国漠河县县长（辖塔河西北）','在漠河及塔河邻近地区任伪县长，协助日军开采金矿，镇压当地抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1420b907948940a1bba01da7472bd8a2','93f14e1340304e9cac4d12a04a6586a6',1935,'伪满洲国呼玛县县长（辖塔河区域）','呼玛县（含今塔河部分）伪县长，配合日军对抗联三支队进行封锁，提供情报。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c582f76b25cd4b55bce36409d17b7c08','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洲国黑龙江省省长、伪满军政部大臣','原东北军将领，1932年投敌，出任伪黑龙江省省长，协助日军镇压抗日武装，推行殖民统治，后升任伪满军政部大臣。；九一八事变后投靠日本，任伪黑龙江省省长，镇压抗日武装，推行殖民统治，协助日军围剿抗联部队。；原东北军将领，1932年投敌，任伪黑龙江省省长，协助日军镇压抗日武装，推行殖民政策，参与“讨伐”抗联部队。；原东北军将领，1932年投敌，任伪黑龙江省长，协助日军镇压抗日武装，推行殖民政策。；九一八事变后投降日军，任伪黑龙江省省长，镇压抗日武装，协助日军建立伪满统治。；原东北军将领，1931年九一八事变后投敌，任伪黑龙江省省长，协助日军镇压抗日武装，推行殖民统治。；原东北军将领，1932年投敌，任伪黑龙江省长，协助日军镇压抗日武装，推行殖民统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9ffbb4a9edf3473395c8650ca24b0d7d','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满洲国立法院院长（曾任哈尔滨地区司法要职）','原奉系法律人士，投日后参与伪满政权建立，在哈尔滨及黑龙江地区推行伪法统，协助日本关东军镇压反满抗日活动。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b166320b39a74fccb69b26665f6ec106','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满洲国黑龙江省财政厅长、伪黑河省省长','原黑龙江省官僚，投日后历任伪省财政厅长、黑河省长，为日军搜刮物资，配合“讨伐”抗联，迫害当地居民。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f1c2994be4b941b3892935ed3d168266','41502657c6b84465aa2ff94e620ed234',1932,'伪满洲国黑龙江省民政厅长、伪牡丹江省省长','原黑龙江省议员，投日后在黑龙江多地任职，参与建立保甲制度，协助日军清乡，对抗联活动区域进行经济封锁。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c5ec9fec359640179edf3e23c0d40ae8','4b486850921b4f33b616f1f8dcdef313',1932,'伪满洲国黑龙江省省长（后任伪满民生部大臣）','原哈尔滨特别市市长，投日后任伪黑龙江省长，推行奴化教育，强征劳工，支持日军“治安肃正”行动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d8c6a6a8175344aaa66805cf6b70a125','350822a1078340679fd657c16a793993',1934,'伪满洲国三江省省长（辖今黑龙江东北部）','原吉林军官，投日后任三江省长，该地区含大兴安岭东麓，多次组织伪军配合日军围剿抗联第三路军。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f899e4ffae954bb0abbc954b18cb87f3','b21d5a4d224a4173bdb0f2b366c98d70',1932,'伪满洲国兴安北省省长（辖大兴安岭西部）','原呼伦贝尔地区蒙古族上层，投日后任伪兴安北省省长，管理大兴安岭西麓，协助日军控制鄂伦春等少数民族，阻挠抗联活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cd24b3dba62446dc99874a29911263c8','b4228f779da94d8393d6fc8edea729d0',1933,'伪满洲国兴安北省警务厅长','原呼伦贝尔警察，投日后任伪警务厅长，在大兴安岭北部地区搜捕抗联小分队，破坏地下交通线。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4b6231888a5f44f6b97a4b5d85aaa7a1','5e4e04133ce04e758b8ecd221f399b11',1934,'伪满洲国黑河省参事官','原黑龙江地方士绅，投日后任伪黑河省参事，参与制定“无人区”政策，强迫大兴安岭边缘居民迁移，断绝抗联补给。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ec5efa69d77947d0b6000a41581c3a62','1d67ff455ffc47b8addcc485beb0ca34',1932,'伪满洲国军政部大臣（曾任东边道镇守使，涉黑龙江南部）','原奉系将领，投日后任伪满军政要职，其指挥的伪军曾调往黑龙江地区参与镇压抗联，包括大兴安岭周边。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('112f6ddbfcbf4388af990fc5317444f2','c0860f9060d74dfba1674157f4596712',1932,'伪满洲国吉林省警备司令官（涉黑龙江交界地区）','原吉林军官，投日后率伪军多次越界进入黑龙江南部及大兴安岭余脉，配合日军“围剿”抗联。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d2979e04b69a4e618d894536fe256cbe','c9dffc071fec4ce58fe1d611f26c28da',1933,'伪满洲国黑龙江省保安局长','原黑龙江地方武装头目，投日后任伪保安局长，在新林及周边林区设立检查站，截杀抗联侦察员。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1db71eac257b421bad227228271dff80','3cd55e29febc489d9f9a7f2f88db31bb',1935,'伪满洲国大兴安岭地区护林队长','原林区把头，投日后任伪护林队长，为日军提供大兴安岭地形情报，引导日军袭击抗联密营。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ea511aeee92f4949bc488cd34677ba92','a768150d31d24b5d96b2c63eba0ed077',1933,'伪满洲国兴安北省警备军团长','原蒙古族军官，投日后率伪兴安军在大兴安岭北部巡逻，多次与抗联第三支队交战，杀害抗联战士。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d9500cba4d3f47e2a429a7be15b19ae7','15bce57e594e4d2baa94695c4c20822e',1934,'伪满洲国黑河省协和会事务长','原黑龙江教育界汉奸，投日后在协和会任职，在大兴安岭地区推行奴化宣传，诱降抗联意志薄弱者。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('22063fae05c64ddb890e9b704422a30d','3209482e2b374e2e956a404739d12a53',1932,'伪满洲国黑龙江省警务厅长','原黑龙江警察头目，投日后任伪警务厅长，组织特务队深入大兴安岭，破坏抗联后方基地。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0710b0da11614ec299aa12514bcf9c43','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洲国洮辽警备司令、伪满尚书府大臣','原洮南镇守使，九一八后公开投敌，在黑龙江西部及大兴安岭周边协助日军进攻抗日义勇军，后任伪满高官。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6ebbcce1e68940b098d8174f3eb3ec7f','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满洲国黑龙江省省长、经济部大臣','原黑龙江省实业厅长，投日后任伪黑龙江省长，在齐齐哈尔及大兴安岭地区推行日伪经济统制，掠夺木材矿产。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('118e4702a2fa4ecd99b4a2382223ab22','41502657c6b84465aa2ff94e620ed234',1933,'伪满洲国黑龙江省省长、民生部大臣','原黑龙江省政府委员，投日后历任伪黑龙江省长，在松岭及嫩江流域配合日军“讨伐”抗联，实施归屯并户。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ff04f4857bb84662984b3f9b35528925','9bddbed4fd004b8dbc21ffa011e5e42c',1932,'伪满洲国兴安东省省长（辖大兴安岭东麓）','原布特哈旗总管，投日后任伪兴安东省省长，在扎兰屯、松岭一带推行保甲制度，镇压鄂伦春等族抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f5fad1acd79f42ce889abe74969c1e84','6dec6f2201c84d729ec0c0b13ca17e6e',1933,'伪满洲国兴安东省省长（达斡尔族）','原达斡尔旗佐领，投日后任伪兴安东省省长，在大兴安岭地区组织伪警察队，参与搜捕抗联小分队。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2e1c1d8fa57b4e7d82b4f1d592532dc4','b4228f779da94d8393d6fc8edea729d0',1932,'伪满洲国兴安北省省长（辖大兴安岭西麓）','原索伦旗总管，投日后任伪兴安北省省长，在海拉尔至松岭一带协助日军建立“无人区”，迫害抗联联络员。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('adf24949e6244f84b8f20e36a347d12c','b8f5150658fd47f0a48c92aacb628181',1932,'伪满洲国黑龙江省长（短暂）','1932年2月一度接受伪满任命，任伪黑龙江省长，但旋即反正抗日，故不列为长期汉奸，此处仅作历史备注。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b12b9fd1132143fd93ec5b06bbfd5133','12571fd3a6fa42cf9581b18a4b27a94e',1933,'伪满洲国第四军管区参谋长','原东北军军官，投日后在黑龙江地区协助日军策划“讨伐”抗联，多次参与松岭、嫩江一带的扫荡行动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5c4d638ed95d407290e50614995d7a13','2eb96a1f022e434e830b2d5e2d6b720b',1932,'伪满洲国兴安军司令（蒙古族）','原呼伦贝尔蒙古贵族，投日后组建伪兴安骑兵师，在大兴安岭西麓及松岭地区参与围剿抗联三支队。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('74dcc0617d11419fab83841b4e411a25','25e14c6523f347349389d63d8a7056ac',1938,'伪满洲国兴安军团长（后反正）','原伪兴安军军官，在大兴安岭地区执行日伪任务，1944年率部起义投奔苏联，此前曾参与镇压当地抗日活动。；曾率伪兴安军参与镇压抗联，1944年率部反正，但此前有汉奸行为。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1bfb0d0f532641d797a3e9ed7a555867','64f7e2c362324f7c8ebbecd6fb02d6e4',1932,'伪满洲国兴安军顾问（蒙古族）','原蒙古王公子弟，投日后任伪兴安军高级顾问，在松岭、阿尔山一带协助日军训练伪军，对抗抗联。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('663d3f820dd44c39913b512b8cc88c44','a02eed53805847c38d732cc4c1d4bd3a',1935,'伪满洲国黑河省参事官','原黑河地方士绅，投日后任伪省参事，在漠河及大兴安岭北部为日军提供抗联情报，参与“归屯并户”。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e0005d113f534cfb976a694598274066','77a789268c6f47b4a617cdb9e41180bd',1932,'伪满洲国国务总理大臣（原籍辽宁，但在黑龙江长期活动）','曾任东省特别区（哈尔滨）长官，后投敌成为伪满最高行政首脑，签署多项卖国条约，配合日军统治黑龙江地区。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e4593ba367644478b277f3a3af436dac','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满洲国黑龙江省省长（1932-1933）','原黑龙江省实业厅长，投日后任伪省长，为日军筹措粮饷，协助镇压马占山等抗日义勇军。；原黑龙江省实业厅长，投日后出任伪黑龙江省长，协助日军建立殖民统治，镇压黑河、嫩江地区反日运动','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9a41f59ae5a740fdaf37526d41a4c882','77aa4951751342b79a81e38d021b4396',1932,'伪满洲国黑龙江省民政厅长、伪齐齐哈尔市长','在齐齐哈尔地区积极推行日伪殖民政策，参与“治安肃正”，迫害抗日军民。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3cfa3e4df6ca40babb7fe1eb6dc1c0f7','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1934,'伪满洲国黑河省省长','在黑河（今黑河市及大兴安岭部分地区）任伪省长，协助日军建立边境防御体系，强征劳工修筑军事工事。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f387e92e32a746a19d2c406cb3785037','b21d5a4d224a4173bdb0f2b366c98d70',1935,'伪满洲国黑河省次长（实际掌权日人，但李为汉奸）','长期在黑河地区任伪职，配合日本关东军对苏联情报战，迫害抗联人员。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('49d92eb3e3ff4d208041c911398c1598','e52c0f125aab401ab1f40b3214908bd8',1934,'伪满洲国三江省省长（管辖佳木斯及松花江下游，与黑龙江东部相关）','在三江地区推行“集团部落”，切断抗联与群众联系，导致大量平民死亡。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c84bdef8829244098f52d9ee5c6c6004','41502657c6b84465aa2ff94e620ed234',1932,'伪满洲国财政部大臣（曾任黑龙江财政厅长）','在黑龙江任职期间为日军搜刮物资，推行“粮谷出荷”政策，导致大兴安岭周边农民饥荒。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('21ab770ba52e456f8d31ad8f1409484c','3eb966fdcf364389b5302ef8a669f7ac',1932,'伪满洲国司法部大臣（曾任黑龙江高等法院院长）','在黑龙江司法系统内为日军服务，判处大量抗日人士死刑，破坏抗联地下组织。；在黑龙江地区审判抗日志士，以“反满抗日”罪名判处大量爱国者死刑或徒刑。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4773433aba834af3b2b14702423c047d','1ba31d558b934fbd83a28a8c2b446022',1932,'伪满洲国热河省长（原黑龙江洮南镇守使，活动于嫩江流域）','在嫩江、大兴安岭东南部地区率部投敌，协助日军进攻抗日义勇军，后转任热河伪职。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('051d49f48b5a46b3b6b288b3567a3c52','b8f5150658fd47f0a48c92aacb628181',1932,'伪满洲国黑龙江省长（1932年2月-4月短暂投日）','一度接受伪职，但旋即反正抗日，故历史评价复杂，此处仅作记录。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6396cb677f534be7b0871f8003834ba7','b7f4958fab3a494e9991cc9a1976f427',1935,'伪满洲国黑河省警务厅长','在漠河、呼玛等边境县组织警察队，协助日军封锁边境，杀害越境抗联战士。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('516bed469c984d7d9634c45fc65cffe0','dcc5e1c824d64fbc825eb60436bd3401',1938,'伪满洲国大兴安岭地区“讨伐队”队长','在大兴安岭原始森林中带领伪军追击抗联第三路军，烧毁山林，破坏抗联密营。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a9b8303f75204789b3293d00717e98ab','15bce57e594e4d2baa94695c4c20822e',1935,'伪满洲国漠河县县长','在漠河县（今漠河市）推行日伪统治，强征当地鄂伦春族和汉族百姓为日军修路、伐木，虐待劳工。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('67251ec7a2014e4c8c96c2cd618e90b7','80d67f99a8d04e52a1b2434f1d99805e',1937,'伪满洲国呼玛县县长（漠河邻近地区）','在呼玛、漠河一带配合日军“边境清剿”，杀害抗联联络员，没收抗日家属财产。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d670e4f1f9fd49969f67e06787d8c3fe','93f14e1340304e9cac4d12a04a6586a6',1939,'伪满洲国大兴安岭地区森林警察大队长','率森林警察为日军提供木材资源，并参与搜捕抗联小分队，在漠河林区多次设伏。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b87ec86623344ef3bc673467b170986e','47cac7a73af140d39ff53133e8cfe760',1932,'伪满洲国兴安北省警备军司令（活动于大兴安岭西部）','原东北军团长，投日后在呼伦贝尔及大兴安岭西部镇压蒙古族抗日武装，后反正。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9e791426b51941d2a9ada16323fb9049','3a9e402192aa460fb51a927d874bb93e',1936,'伪满洲国黑河省“治安军”团长','在黑河至漠河边境地带驻防，多次参与对苏联情报人员的搜捕，并杀害抗联交通员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0dd054c748244c1897e1027fb26c03d6','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满洲国奉天警备司令、伪满洲国军政部大臣','原东北军将领，九一八事变后率部投敌，任伪奉天警备司令、伪军政部大臣等职，参与镇压东北抗日武装，为伪满军事系统重要汉奸。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0758cc8592c34bc89cb7df28ad27864d','79b17193512846a1a5bde9f5df22c926',1931,'伪满洲国民政部总长、伪参议府议长','原辽宁省政府主席，九一八事变后被俘投敌，历任伪满洲国民政部总长、参议府议长等职，参与伪满殖民统治。；原辽宁省政府主席，被俘后投敌，参与伪满政权建设，影响遍及东北包括黑龙江。；辽宁沈阳人，九一八事变后被日军逮捕后投敌，历任伪奉天省长、伪满洲国民政部总长、参议府议长，为伪满政权重要汉奸，其行政体系覆盖东北包括黑龙江。；辽宁沈阳人，九一八事变后被日军扣押，后投降任伪奉天省长，继任伪满洲国民政部总长、参议府议长，为伪满政权重要附逆者，其管辖范围涵盖黑龙江等地民政事务。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bef55dd22c8049ddb1587871f807e741','d2b7a71572c34ce0943d2a891b842d96',1930,'伪满洲国滨江省警务厅厅长','在伪滨江省警务系统任职，参与搜捕、镇压抗日人员，推行保甲连坐与治安肃正政策。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f1d008f98fff4a4aad09e0718af6a87d','c276a824877f4dce865833533f6312bf',1930,'伪满洲国滨江省公署官员、伪协和会滨江省本部职员','在伪滨江省政权与协和会系统中活动，参与殖民宣传、民众控制与战时动员。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f90431fc2e2c4880a472a8b17117970c','1801590af35e42d9a7a11e8b64d7b871',1930,'伪满洲国肇州县公署县长','在大庆地区肇州一带任伪县长，执行日本殖民政令，征粮征工，配合日伪军警镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('12cb3fb895d54c4eafecd51f2d9be56b','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洲国洮辽镇守使、伪热河省警备司令','原东北军骑兵将领，九一八事变后投敌，参与进攻黑龙江抗日部队，后任伪洮辽镇守使、伪热河省警备司令，在东北西部包括大庆周边地区配合日军作战。；原东北军洮辽镇守使，九一八事变后投敌，任伪洮辽镇守使，率伪军配合日军进攻黑龙江，参与江桥战役对马占山部的作战，后任伪热河省警备司令，其活动直接涉及黑龙江地区。；原东北军洮辽镇守使，九一八事变后投敌，率部配合日军进攻黑龙江，参与江桥战役对马占山部的作战，后任伪热河省警备司令等职。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('73417f70a9b54d0dabf91c5400cb5abc','3c793b1442ef48298a262b0d57814cab',1931,'伪满洲国黑龙江省警备司令、伪第三军管区司令','原东北军黑龙江部队将领，马占山抗日时动摇投敌，任伪黑龙江省警备司令，参与瓦解抗日武装，控制黑龙江地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c96456df7aea41aeb5f2aacb4d9a41fc','12571fd3a6fa42cf9581b18a4b27a94e',1930,'伪满洲国黑龙江省长、伪参议府参议','在伪黑龙江省政权中任职，协助日本推行省政殖民化，参与治安肃正与物资统制。；原东北军军官，九一八事变后投敌，曾任伪黑龙江省长，参与伪满地方政权建设，其统治区域包括齐齐哈尔及龙沙地区。','省部级/大军区级要员','hanjian');
