INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0abc10a552114914acc9dc263fb8c988','1b0d93051c8343ec93855ecd4624a43f',1930,'伪满洲国林甸县警务局局长','在林甸地区警察系统任职，参与镇压抗日活动与民众控制。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('66be9959669a4f48aea94484b001a141','382d6cd4374f4825b23e811f101eb963',1930,'伪满洲国杜尔伯特旗警务科科长','在杜尔伯特旗警察系统任职，协助日本控制当地蒙古族民众，镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fadf0b93da8042af99ba632f4c095446','04a30faf78ef4e6fbf734ca880979bf8',1930,'伪满洲国郭尔罗斯后旗警务科科长','在郭尔罗斯后旗警察系统任职，参与日伪治安肃正与情报搜集。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5bdacc8c5cf540018938114ffd7ea706','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满立法院院长、伪满哈尔滨特别市市长','原奉系法律人士，九一八后积极参与伪满建国，曾任伪哈尔滨特别市市长（管辖今大庆部分地区），推行奴化教育，协助日本殖民统治。；原奉系政客，九一八后投日，曾任伪哈尔滨特别市市长，后任伪满立法院院长，积极推行奴化政策，协助日本殖民统治。；原奉系政客，九一八后投日，曾任伪哈尔滨市长，协助日军建立殖民统治，镇压反满抗日活动。；参与伪满政权建立，曾任哈尔滨市长，管辖包括鹤岗在内的区域，协助日本掠夺资源。；原奉系政客，投日后任伪哈尔滨特别市市长，在黑龙江地区推行日伪殖民政策，协助日军镇压反满抗日活动。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4afa83afb49942f9ba3015808476f6e2','4b486850921b4f33b616f1f8dcdef313',1932,'伪满哈尔滨特别市市长、伪满民政部大臣','原哈尔滨特区行政长官，投日后任伪哈尔滨市长，在黑龙江地区（含大庆一带）强制推行“保甲制”和“粮谷出荷”，压迫民众。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8970cc0e0a7c43f7ad1a6669e5015da4','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满黑龙江省省长、伪满经济部大臣','原黑龙江实业界人士，投日后任伪黑龙江省长（省会齐齐哈尔，管辖大庆地区），为日军搜刮粮食、木材，并协助镇压抗联活动。；原黑龙江省实业厅长，1932年投敌，任伪黑龙江省省长，后任伪满经济部大臣，为日军搜刮物资，镇压反满抗日活动。；原黑龙江省实业厅长，1932年投敌，任伪黑龙江省长期间，强征粮食物资，配合日军经济掠夺，迫害抗日军民。；原黑龙江省实业厅长，投日后任伪黑龙江省省长，在鹤岗矿区强化殖民统治，配合日军掠夺煤炭资源，镇压矿工反抗。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('17258b9e0c9147cba99acc594576a7ed','41502657c6b84465aa2ff94e620ed234',1932,'伪满黑龙江省省长、伪满财政部大臣','原黑龙江省政府官员，投日后历任伪黑龙江省长，在齐齐哈尔、大庆等地区推行“归屯并户”，制造无人区，对抗联进行经济封锁。；原黑龙江省财政厅长，投日后任伪黑龙江省省长，后任伪满财政部大臣，协助日本控制黑龙江经济命脉。；原黑龙江省财政厅长，投日后继任伪满黑龙江省省长，后升任伪满财政部大臣，在黑龙江地区推行经济掠夺政策。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5ae4f60f570e45b992f1c1d2e25363d9','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1932,'伪满滨江省警务厅长','原哈尔滨警察头目，投日后任伪滨江省（含哈尔滨、大庆部分地区）警务厅长，指挥伪警察配合日军逮捕、杀害抗联战士及爱国群众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f1eb6e5a13ae4f8a98a1ef8cec5a6472','9dc1581eaee5417b8742c435470d1585',1932,'伪满大同县（今大庆市大同区）县长','伪满时期大同县（今大庆大同区）汉奸县长，积极为日军征粮、抓劳工，镇压当地抗日活动，具体劣迹包括强征民夫修筑警备道路。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fde04b0d7eb84c0092ae414536452e8e','4b486850921b4f33b616f1f8dcdef313',1932,'伪满哈尔滨特别市市长、伪满民生部大臣','原哈尔滨特别市市长，1932年投敌，后任伪满民生部大臣，参与制定并实施对东北人民的奴役政策。；在哈尔滨任伪职期间，配合日军镇压反满抗日活动，推行保甲制度。','特别市市长','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e16b88de852542019cb3a27e56778641','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1934,'伪满滨江省省长（驻哈尔滨）','原东北地方官员，投日后任伪满滨江省省长，管辖哈尔滨及周边地区，积极推行日伪法令，镇压抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('876ebe5856654619bef72fe07bba5e7d','5a42f897a627483f9ceda7a629ea37f8',1932,'伪满哈尔滨警察厅厅长、伪满滨江省警务厅长','原哈尔滨警察头目，投日后任伪哈尔滨警察厅厅长，后升任滨江省警务厅长，大肆搜捕抗日志士，制造多起惨案。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4ab8368668d64d08a49c8ce0723015f8','5cce8fcbbcc043c2820499553d6999c1',1932,'伪满黑龙江省警务厅长','原黑龙江省警察头目，投日后任伪省警务厅长，组织伪警察配合日军“讨伐”抗联，残害百姓。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cf5bb6a3242c4cbea057bc16bd23eba7','77a789268c6f47b4a617cdb9e41180bd',1931,'伪满国务总理大臣（原黑龙江地区军阀）','原奉系将领，曾任黑龙江省长，九一八后投日，后任伪满国务总理大臣，虽主要活动于新京，但长期控制黑龙江伪政权，是头号汉奸。；虽主要活动于伪满中央，但出身黑龙江，长期控制北满伪政权，对肇州地区殖民统治负有直接责任。；九一八后投日，虽居高位，但早期在哈尔滨一带活动，支持日军占领黑龙江，其势力影响鹤岗、绥滨地区。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0ee9e33881904a89b09bef7525912fe4','b8f5150658fd47f0a48c92aacb628181',1932,'（注：曾短暂投日，后反正）','原黑龙江省代主席，1932年2月一度投降日军，任伪黑龙江省长，但4月反正抗日，故不列为固定汉奸，但历史上有投敌记录。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3e760dd8f93c4f25bedb6820ad2c61bb','12571fd3a6fa42cf9581b18a4b27a94e',1932,'伪满第三军管区司令（驻齐齐哈尔）','原东北军军官，投日后任伪满第三军管区司令，驻齐齐哈尔，多次率伪军进攻抗联，屠杀抗日军民。；原东北军军官，投日后驻守齐齐哈尔，指挥伪军多次“讨伐”抗联部队，在富裕县等地烧杀抢掠','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1459d1d8eb9b4ba9bfcb8083453ce662','c9dffc071fec4ce58fe1d611f26c28da',1935,'伪满滨江省警务厅长（后任）','原哈尔滨警察，投日后升任滨江省警务厅长，参与策划对东北抗联的“大讨伐”，抓捕大量地下党员。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('98c93b46cd3e4e4f8573e6d5b33ab942','b21d5a4d224a4173bdb0f2b366c98d70',1932,'伪满黑龙江省教育厅长','原黑龙江省教育界人士，投日后任伪省教育厅长，推行奴化教育，篡改历史，毒害青少年。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0cb36633c91249bc8610caa4bf97a0c7','77aa4951751342b79a81e38d021b4396',1932,'伪满黑龙江省民政厅长','原黑龙江省官员，投日后任伪省民政厅长，协助日伪建立保甲制度，强化殖民统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ff65a10fca094eebacc7910dd8dda6d2','3cd55e29febc489d9f9a7f2f88db31bb',1932,'伪满大庆地区（今大庆市）地方维持会长','原地方士绅，日军占领后出任大庆地区（当时为安达县、肇州县等）维持会长，为日军征粮派夫，欺压百姓。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aff26a811a794a73901d0fb856a39daf','dfa64805d7ab436da2e2db28a71517a2',1932,'伪满安达县县长（今大庆市安达市）','投日后任伪安达县县长，积极推行日伪苛政，强征劳工，协助日军镇压当地抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ab9eb308eca44d58a78ce46817929817','cd8e5ab701f04770ad28171753ae1ceb',1932,'伪满肇州县县长（今大庆市肇州县）','投日后任伪肇州县县长，组织伪县公署，配合日军“清乡”，迫害抗日家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('42da2b0caa6543a5b79cd295af58f0a9','ba135ba1ef794aeba0fdad0065a31974',1932,'伪满杜尔伯特旗旗长（今大庆市杜尔伯特蒙古族自治县）','原蒙古族上层，投日后任伪旗长，协助日军控制蒙古族地区，征募伪军。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('efe3cb5ec0bb49dab8538de2a3e43c7e','3c793b1442ef48298a262b0d57814cab',1931,'伪满洲国黑龙江省警备司令、伪满军政部次长','原东北军骑兵旅长，江桥抗战后随马占山一度抗日，后于1932年投敌，任伪黑龙江省警备司令，率伪军配合日军镇压黑龙江抗日武装，后任伪满军政部次长，其活动直接覆盖齐齐哈尔、大庆、杜尔伯特一带。；原东北军骑兵旅长，江桥抗战后投敌，任伪黑龙江省警备司令，配合日军镇压黑龙江抗日力量，后任伪满军政部次长。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d462b8d114574d7892facd4e160cfccf','c9dffc071fec4ce58fe1d611f26c28da',1931,'伪满洲国黑龙江省警备司令部司令、伪满军管区司令','原东北军军官，投敌后任伪黑龙江省警备司令部司令，统率伪军配合日军在黑龙江地区围剿抗日联军，其防区包括大庆、杜尔伯特周边地区。；原东北军军官，投敌后历任伪黑龙江省警备司令部司令等职，在齐齐哈尔及周边地区指挥伪军配合日军围剿抗日武装。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c93c5f9704774da9bf9e443cb8cde063','12571fd3a6fa42cf9581b18a4b27a94e',1931,'伪满洲国黑龙江省长、伪满参议府参议','原东北军军官，投敌后历任伪黑龙江省长、伪满参议府参议，参与伪满在黑龙江的殖民统治，推行保甲连坐、粮谷出荷等政策，其辖区涵盖大庆、杜尔伯特地区。；原东北军军官，投敌后任伪黑龙江省长，参与伪满在黑龙江地区的行政统治，后任伪满参议府参议。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f67c34cff0fa490fae3de3d6c2a701c0','3b74f508628f475a8777ffb7e38a48a0',1931,'伪满洲国黑龙江省长、伪满经济部大臣','原哈尔滨商人，投敌后任伪黑龙江省长，后任伪满经济部大臣，积极推行日本经济掠夺政策，在黑龙江地区强征粮食、劳工，其统治范围包括大庆、杜尔伯特一带。；辽宁金县人，九一八事变后投敌，历任伪黑龙江省长、伪满经济部大臣等职，参与对黑龙江的经济掠夺。；辽宁金州人，九一八事变后投敌，历任伪黑龙江省长、伪满经济部大臣等职，参与伪满经济统制与掠夺，活动涉及齐齐哈尔地区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('28e3cee13e7c49259f660f5e86ad722c','41502657c6b84465aa2ff94e620ed234',1931,'伪满洲国黑龙江省长、伪满财政部大臣','原东北军官员，投敌后任伪黑龙江省长，后任伪满财政部大臣，参与伪满财政搜刮，其省长任内统治覆盖大庆、杜尔伯特地区。；辽宁辽阳人，九一八事变后投敌，历任伪黑龙江省长、伪满财政部大臣等职，参与伪满财政搜刮。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5e4672e57efe4b008d8518e4ec3dc51a','77aa4951751342b79a81e38d021b4396',1932,'伪满洲国黑龙江省民政厅长、伪满参议','原东北军官员，投敌后任伪黑龙江省民政厅长，参与伪满地方政权建设，推行保甲制度，其活动范围覆盖大庆、杜尔伯特一带。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('44a7c72627fa421daa17c27ff4317f14','76877234e49e40abbd0e65850b11abac',1932,'伪满洲国杜尔伯特旗旗长','杜尔伯特旗蒙古王公后裔，投敌后任伪杜尔伯特旗旗长，配合日本殖民统治，在旗内推行保甲、征粮、征畜政策，直接涉及杜尔伯特地区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b512977748df4a098ca04f022b63ddc6','5432fbdab70b4846bf4358ef4c3d0c29',1932,'伪满洲国杜尔伯特旗旗长、伪满兴安局官员','杜尔伯特旗蒙古贵族，投敌后任伪杜尔伯特旗旗长，后任伪满兴安局官员，协助日本在杜尔伯特及周边地区推行殖民统治。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('529ce15c63e9427f9eb02ade0b0f2fef','7fcee729252d4d5a8389b143ba62d8b9',1932,'伪满洲国兴安南分省省长、伪满兴安局总裁','蒙古王公，投敌后任伪兴安南分省省长、伪满兴安局总裁，参与日本对东蒙地区的殖民统治，其影响范围涉及杜尔伯特等蒙古族聚居区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9d54162450ad4959a0713eae45eae45e','c904a3bb584e47459dd2323f9459412e',1932,'伪满洲国大庆地区维持会会长','地方士绅，投敌后任大庆地区维持会会长，协助日军建立基层伪政权，推行保甲连坐，为日军征粮征夫，直接涉及大庆地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4406fe377d634b3f8e04c7277c8aa48a','811e6ae674ab4f35a21e56d287668b58',1932,'伪满洲国肇州县维持会会长、伪肇州县县长','地方士绅，投敌后任伪肇州县维持会会长、县长，肇州即今大庆市辖区，其协助日军镇压抗日活动，推行殖民统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1103f0e48f5549cc8924beea0d2d6a93','167beb1e08ed47a1a746e3d21f6de621',1932,'伪满洲国安达县县长','投敌后任伪安达县县长，安达邻近大庆、杜尔伯特，其配合日军征粮、征劳工，推行保甲制度。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a8a01e40dbb64874a69964641ab9e972','325b49bddc5a45b3977ab3f09444c867',1932,'伪满洲国林甸县县长','投敌后任伪林甸县县长，林甸邻近大庆、杜尔伯特，其协助日军建立基层伪政权，推行粮谷出荷政策。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e67f1fad86044222897d9ccb90c736ad','105c4446aaf347b2a0ed658ef91afcc1',1932,'伪满洲国泰康县维持会会长','地方士绅，投敌后任伪泰康县维持会会长，泰康即今杜尔伯特蒙古族自治县前身之一，其直接协助日军在杜尔伯特地区建立殖民统治。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bd68b896f6d64221888fcf117e634f96','53466dea330145ff8fd78c5c7a73c092',1932,'伪满洲国杜尔伯特旗警务科长','蒙古族地方人员，投敌后任伪杜尔伯特旗警务科长，统领伪警察配合日军镇压抗日活动，直接涉及杜尔伯特地区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0a8df43804e041819703c3b0cccf3d4b','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满黑龙江省省长、伪满治安部大臣','九一八事变后投敌，任伪黑龙江省长，协助日军镇压抗日武装，推行殖民统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b70e33c69bb4402c94326782a0b4939b','e25c85c91f604ceda710a0637532c900',1932,'伪满第四军管区司令官、伪满黑龙江省警务厅长','率伪军多次围剿抗联部队，在黑龙江地区实施“讨伐”行动，残害抗日军民。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c8628eb4c5e04236ab14a1318e038c28','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满黑龙江省财政厅长、伪满经济部大臣','为日军筹措军费，强征粮食资源，参与经济掠夺，导致黑龙江地区民生凋敝。；原为地方士绅，投日后主管伪满财政，为日军侵华战争筹措军费，搜刮民财。；原黑龙江地方官员，投日后主管伪省财政，为日军侵华筹措资金，参与对黑河地区经济掠夺。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('add1d35b3c0a4d80b66109dd3e015faa','41502657c6b84465aa2ff94e620ed234',1932,'伪满黑龙江省教育厅长、伪满文教部大臣','推行奴化教育，强制学校教授日语，篡改历史，毒害青少年。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1573f5ffe9c64eb99a08d6cc0094937e','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1933,'伪满黑龙江省警务厅特务科长','在齐齐哈尔、大庆、林甸等地建立特务网络，抓捕抗联地下工作者，制造多起惨案。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('395542e2f7e34d48ba560e1aab8b003e','21853206ad2b417598d1af0b4b3a4782',1932,'伪满林甸县县长','在林甸县强征劳工，修建日军据点，配合日伪军“清乡”，杀害抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a05b4305621047dfabec05c6b341d0f6','5a42f897a627483f9ceda7a629ea37f8',1932,'伪满哈尔滨警察厅厅长','指挥警察镇压哈尔滨及周边地区反日运动，逮捕并杀害大量抗联情报人员。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('64aafa68acc449109825d3c98d1012ae','5cce8fcbbcc043c2820499553d6999c1',1933,'伪满黑龙江省警务厅长（驻齐齐哈尔）','在齐齐哈尔、大庆地区组织“治安肃正”，围剿抗联第三路军，烧毁村屯。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('436d9d48119d48708461a97306653a6f','8208a36677824ebd82d3a160b4c94e50',1934,'伪满林甸县警务科科长','在林甸县设立多处警察分驻所，抓捕抗联交通员，参与“归屯并户”政策。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fbaa071fb05946258a2e28cd870f574c','3eaf116c87a7417fadcbf5fe87b56f23',1932,'伪满肇州（含今大庆部分地区）县长','在肇州、大同（今大庆）一带强征民夫修筑警备道路，协助日军扫荡抗联。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fa478d6391c844e7bca82f06beaed620','3cd55e29febc489d9f9a7f2f88db31bb',1933,'伪满安达县（今大庆安达市）县长','在安达地区推行“粮谷出荷”，搜刮农民粮食，导致饥荒，并配合日军抓捕抗联。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7ddbade638c94cd093053f55b509fdc5','2bc86830c5bb4c098fdbd155863dc8ca',1932,'伪满杜尔伯特旗（今大庆杜尔伯特县）旗长','在蒙古族聚居区推行日伪“蒙地政策”，强征牲畜，破坏抗日民族统一战线。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('68fcc67da80146988d26cce204c61230','26ea20889bcc454897b4325f7985a0a8',1935,'伪满林甸县保安队队长','率保安队多次袭击抗联小分队，在林甸县境内杀害抗联伤员及支持抗联的农民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('afa31fbc3a6f4d808434373a31142cd5','08bfa75fc92246d79f88ea8f05c6f7c2',1936,'伪满齐齐哈尔市（含大庆部分地区）警察局特务股长','在齐齐哈尔及周边林甸、泰康（今大庆）地区发展密探，破坏抗联地下组织。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('45bfac8526b1472e8fcf80129bf9348f','8f4dec66a5db45bea1a3de63a6760cbf',1934,'伪满黑龙江省协和会（齐齐哈尔本部）总务部长','在黑龙江各地（含林甸、大庆）组织协和会宣传“日满亲善”，瓦解民众抗日意志。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('be3184c4bbdd41b09d2124dcdd25b984','c9dffc071fec4ce58fe1d611f26c28da',1931,'伪满洲国军中将、伪江防舰队司令','原东北军军官，九一八事变后投敌，曾任伪满洲国江防舰队司令、伪军管区司令等职，参与封锁松花江流域并配合日军讨伐抗日力量，活动涉及大庆周边地区。；原东北军军官，投敌后任伪江防舰队司令，率伪舰艇在松花江、黑龙江流域巡逻，配合日军封锁和镇压沿江抗日武装，活动范围包括萝北、鹤岗沿江地区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f01a86f75e484d1c84fcbb774cb1084b','76877234e49e40abbd0e65850b11abac',1931,'伪满洲国军少将、伪安达县警察大队长','在伪满时期于安达县（今大庆市安达地区，邻近红岗）担任伪警察大队长，协助日军维持治安、搜捕抗日人员，属地方伪警头目。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4875576fd184497587514759dc403012','56e668bf262e4d84a8cfe302e67fed6a',1931,'伪肇州县维持会会长','伪满时期在肇州县（今大庆市肇州县，邻近红岗）组织维持会，协助日军建立殖民统治秩序，推行保甲制度，为地方附逆者。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('21a0c61ade6048d4b470086d79e1688c','77aa4951751342b79a81e38d021b4396',1931,'伪满洲国黑龙江省公署参事官','伪满时期在黑龙江省公署任职，参与推行日本殖民政策，协助日军控制地方行政，其活动范围覆盖今大庆地区。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4b90040183ea49f680c9fd323fb88109','3b74f508628f475a8777ffb7e38a48a0',1931,'伪满洲国经济部大臣、伪黑龙江省长','辽宁金县人，九一八事变后投敌，历任伪黑龙江省长、伪经济部大臣等职，协助日本掠夺东北经济资源，其施政范围包括今大庆地区。；辽宁金县人，九一八事变后投敌，历任伪黑龙江省长、伪满洲国经济部大臣，在黑龙江地区推行经济统制政策，掠夺资源支持日军。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('352ffa4ddf4643c09aaddb8babb314f1','1ba31d558b934fbd83a28a8c2b446022',1931,'伪黑龙江省省长、伪满军政部大臣','九一八事变后投敌，任伪黑龙江省省长，协助日军镇压抗日武装，推行殖民统治。；原东北军将领，1932年投敌，任伪黑龙江省省长，协助日军镇压抗日武装，推行殖民统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4ba7e4af9f744833b81dd8b9edbff5c1','e25c85c91f604ceda710a0637532c900',1932,'伪满第四军管区司令官、伪滨江省省长','原东北军将领，叛变后任伪满军事要职，在黑龙江地区围剿抗联，制造多起惨案。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d71ab256eaa2463ba7cc84d5525f5a3d','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满立法院院长、伪哈尔滨特别市市长','参与伪满建国，曾任哈尔滨市长，协助日本控制北满经济与治安。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2d6d6ec861384aab820a720ef22a4bf3','3b74f508628f475a8777ffb7e38a48a0',1932,'伪黑龙江省财政厅长、伪满经济部大臣','投日后主管伪满财政，在黑龙江推行经济掠夺政策，强征粮食与劳工。；原哈尔滨商人，投日后负责伪满财政，在牡丹江地区设立“金融合作社”，掠夺当地资源。；原黑龙江省官员，投日后负责伪满财政搜刮，为日军侵华提供经济支持，在绥化、明水等地推行苛捐杂税。；原黑龙江省实业厅长，投敌后主管伪省财政，为日军搜刮物资，支持殖民经济，在齐齐哈尔地区推行经济统制；为日军掠夺黑龙江粮食、木材等资源，在讷河地区推行“出荷粮”政策，导致民众饥荒。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2e769dd30a624760bf0859aa18cb610b','41502657c6b84465aa2ff94e620ed234',1933,'伪黑龙江省省长、伪满民生部大臣','曾任伪黑龙江省长，配合日军“治安肃正”，镇压肇州等地抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0b81297a9d704649a52710d030bb00ff','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1932,'伪满黑龙江省警务厅长','指挥伪警察在肇州、大庆地区搜捕抗日志士，参与“三肇惨案”围剿。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a5251d24cb44456a85df60c473585e71','9dc1581eaee5417b8742c435470d1585',1935,'伪肇州县县长','在肇州任伪县长期间，强征民夫修建警备道路，协助日军清乡并迫害抗联家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('829734eaaab84618a1765bc6f584769f','b8f5150658fd47f0a48c92aacb628181',1932,'伪满黑龙江省长（短暂投敌后反正）','1932年一度投降日军任伪省长，但旋即反正抗日，故在汉奸名录中存争议，仍列此供参考。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1a6d971dc06e4b76b7458af09676091d','6154d7c5357c4a93bda292d584aae68f',1938,'伪肇东县警察署长（活动于肇州周边）','在肇州、肇东交界地区抓捕抗联交通员，破坏地下组织。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('60b46bb676e4497ba2f7cbe680f6ece9','3cd55e29febc489d9f9a7f2f88db31bb',1939,'伪满第三军管区旅长（驻防大庆地区）','率伪军参与“三肇地区”大讨伐，杀害抗联第三路军战士。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c537a31b3cff48138f893dce2c5d0da6','41502657c6b84465aa2ff94e620ed234',1932,'伪满黑龙江省省长、伪满民生部大臣','原黑龙江省财政厅长，投敌后历任伪满黑龙江省省长，后升任伪满民生部大臣，在黑龙江期间强征劳工、掠夺资源。；原黑龙江省财政厅长，投日后历任伪职，在黑龙江推行保甲制度，协助日军搜捕抗联地下组织。；原黑龙江省财政厅长，投敌后历任伪满黑龙江省省长，在绥化、肇东地区推行“保甲制度”和“集团部落”，配合日军对抗联进行经济封锁。；原东北军将领，叛变后任伪职，在鹤岗地区推行“保甲连坐”制度，镇压反满抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e7d32a1d2b254375a2220c22dbd04482','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1934,'伪满滨江省省长','原哈尔滨特别市市长，投敌后任伪满滨江省省长（辖今哈尔滨、大庆、肇源一带），协助日军建立保甲制度，镇压抗日活动。；原哈尔滨特区长官，投敌后任伪满滨江省省长，管辖区域包括肇东（时属滨江省），曾组织伪警察和自卫团在肇东一带搜捕抗日分子。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('47190ed596864655b837918134c701b5','4b486850921b4f33b616f1f8dcdef313',1932,'伪满滨江省省长、伪满外交部大臣','原哈尔滨特区行政长官，投敌后任伪满滨江省省长，后任伪满外交部大臣，在任期间推行“治安肃正”，迫害抗日军民。；原哈尔滨市市长，投敌后任伪满滨江省省长，肇东在其辖区内，曾多次到肇东视察“治安工作”，督促地方伪政权强化对民众的控制。；原哈尔滨特区行政长官，投日后任伪满滨江省省长（辖今哈尔滨、黑河部分地区），后任伪满外交部大臣。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a082394dccc6457c80ad80d27d4908a9','69f38ea2adad4635bb217a6e5aadda7e',1940,'伪满滨江省省长','原东北地方官员，投敌后任伪满滨江省省长，管辖肇源等县，配合日军进行“大讨伐”，残害抗联战士及群众。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c105e6a3d43f45f1a96c70e9c51f99f4','17ba4ca514844dcbb95b21c193e11290',1934,'伪满滨江省警务厅厅长','原哈尔滨警察头目，投敌后长期任伪满滨江省警务厅厅长，直接指挥警察特务在肇源、大庆等地搜捕抗日分子，制造多起惨案。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b4106e9384fd44b8915647279fcb3098','b8f5150658fd47f0a48c92aacb628181',NULL,'（注：马占山曾短暂投敌后反正，但非汉奸，故不列入）',NULL,'无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1b74922b039b4fb8bfb1c576a5e3cade','b21d5a4d224a4173bdb0f2b366c98d70',1932,'伪满肇州县县长','原肇州地方士绅，投敌后任伪满肇州县县长（今属大庆），强征民夫修建公路、碉堡，协助日军“讨伐”抗联。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2c2513fbb9b34226987f7cc71385147e','0ce72eece3db48fc91bb0e9928ba9e67',1933,'伪满肇源县县长','原肇源县商会会长，投敌后任伪满肇源县县长，推行“粮谷出荷”，搜刮民财，并告密导致抗联小分队被围。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('347d5928d1b240d4b1b41477031cdf3c','3cd55e29febc489d9f9a7f2f88db31bb',1935,'伪满肇源县警务科科长','原肇源县警察，投敌后任伪满肇源县警务科科长，亲自带队抓捕抗联交通员，刑讯逼供，杀害多名抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9490c3ce63174290b80bc8a4917b64ff','a2c03b81e5f2412bb86f5d5599c1687b',1932,'伪满大庆地区（萨尔图）维持会会长','原萨尔图地主武装头目，投敌后组织维持会，为日军提供情报，参与“清乡”行动，迫害当地抗日家属。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('06018fe5059e4136985e468d2defec7c','c9dffc071fec4ce58fe1d611f26c28da',1931,'伪满洲国军中将、伪辽河警备司令','原东北军军官，九一八事变后投敌，任伪军中将，在黑龙江、吉林地区参与围剿抗日义勇军。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('23acd8452cfa4ac788dad5d69e332321','77aa4951751342b79a81e38d021b4396',1932,'伪满洲国黑龙江省公署厅长','黑龙江人，投敌后任伪黑龙江省公署厅长，参与伪政权行政事务，协助日军推行保甲制度与物资统制。；黑龙江地方士绅，投敌后任伪黑龙江省公署要职，协助日军推行殖民政策，参与地方伪政权建设，活动于齐齐哈尔地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('444b59d67cb24824aa6e6e1a581a1972','76877234e49e40abbd0e65850b11abac',1932,'伪满洲国黑龙江省公署参事官','投敌后任伪黑龙江省公署参事官，参与伪政权决策，协助日军在黑龙江地区实施殖民统治。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('48c59fdd1d7146e599b4d1adbbffda85','6575bf6c75154079a0b0c04e45af6a26',1934,'伪满洲国滨江省公署省长','投敌后任伪滨江省公署省长，滨江省辖今哈尔滨及大庆部分地区，参与推行伪满政策，镇压抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ce6b0507c28444d79b70616087476dfd','69f38ea2adad4635bb217a6e5aadda7e',1932,'伪满洲国滨江省公署厅长','投敌后任伪滨江省公署厅长，参与伪政权行政，协助日军在滨江省（含今大庆地区）推行保甲连坐与物资掠夺。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('04eb2f5034c84748b2f9ba83e49d4d56','5a42f897a627483f9ceda7a629ea37f8',1932,'伪满洲国滨江省省长、伪哈尔滨市长','投敌后历任伪哈尔滨市长、伪滨江省省长，在哈尔滨及周边地区推行伪满政策，参与镇压抗日地下活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b259dffc420845d58dbbfb7132415eb2','02655509fcec4f358286297204a36c5b',1932,'伪满洲国滨江省警务厅厅长','投敌后任伪滨江省警务厅厅长，指挥伪警察在滨江省各地搜捕抗日人员，推行治安肃正。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4aa42feac5664b65aba39a9332824d38','3cd55e29febc489d9f9a7f2f88db31bb',1932,'伪满洲国肇州县公署县长','肇州（今属大庆市）人，投敌后任伪肇州县公署县长，在肇州及萨尔图一带推行伪满政令，协助日军征粮、抓劳工。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('99441d876e124cba8c8153483c5e70e2','20b763b7812d492bb30685da8eada260',1932,'伪满洲国肇州县公署参事官','投敌后任伪肇州县公署参事官，参与伪县政，协助日军在肇州地区实施保甲制度与物资统制。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d4d2e631c2214319a0581f86b4d6a667','1b0d93051c8343ec93855ecd4624a43f',1932,'伪满洲国安达县公署县长','安达（今属大庆市）人，投敌后任伪安达县公署县长，在安达及萨尔图一带推行伪满政策，协助日军掠夺资源。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('728c5787f60e46ce9a574f310dba1053','df4ac79bd5494ff9b25803f1ffee94c7',1932,'伪满洲国林甸县公署县长','林甸（今属大庆市）人，投敌后任伪林甸县公署县长，在林甸地区推行伪满政令，协助日军征粮、抓劳工。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8c5d1e2ba48343ef8cd937291390632f','0837a3474e904ef487f16512a0466cb2',1932,'伪满洲国杜尔伯特旗旗长','杜尔伯特旗（今属大庆市）投敌者，任伪旗长，协助日军在杜尔伯特地区推行殖民统治，掠夺畜牧资源。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0af3410aad9b43419c9c0dceaddb6914','06abf92069664601a139e2615e8f3245',1932,'伪满洲国萨尔图保保长','萨尔图（今大庆市萨尔图区）投敌者，任伪保长，协助日军在萨尔图一带推行保甲制度，征粮、抓劳工、监视抗日人员。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ac58816409194813a0f9b2fecc4d83b9','3a84db31af8b4226bd562e63f2788d3f',1932,'伪满洲国萨尔图警察分驻所所长','萨尔图投敌者，任伪警察分驻所所长，在萨尔图及周边地区搜捕抗日人员，配合日军维持殖民治安。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('729ff43792494e40b9711d6696eaaaee','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满洲国军政部大臣、伪满军上将','原东北军将领，1931年后投敌，历任伪奉天警备司令、伪军政部大臣等职，率伪军配合日军在东北包括黑龙江地区围剿抗日武装。；原东北军东边道镇守使，1931年九一八事变后投敌，组织伪军配合日军进攻抗日武装，后任伪满洲国军政部大臣、治安部大臣，统辖伪满军警镇压东北抗日联军，其伪军活动范围包括黑龙江、齐齐哈尔一带。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('62e503b298c0476a826304dfd20d9bbd','3c793b1442ef48298a262b0d57814cab',1931,'伪满洲国黑龙江省警备司令、伪满军中将','原东北军骑兵将领，江桥抗战后投敌，任伪黑龙江省警备司令，率伪军配合日军在黑龙江地区围剿抗日武装。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('63dbd86411ee4ed6a53bde2e569ab72b','c9dffc071fec4ce58fe1d611f26c28da',1931,'伪满洲国黑龙江省警备司令部军官、伪满军少将','原东北军军官，随程志远投敌，在伪黑龙江省警备司令部任职，参与对黑龙江地区抗日武装的围剿。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cc480fbdb48f4d24972d0ee020036dbc','3b74f508628f475a8777ffb7e38a48a0',1931,'伪满洲国黑龙江省长、伪滨江省长','原哈尔滨商人，九一八事变后投敌，历任伪黑龙江省长、伪滨江省长等职，参与伪满对黑龙江地区的殖民统治和经济掠夺。；辽宁金县人，1932年投敌，历任伪黑龙江省长、伪滨江省长、伪经济部大臣等职，在齐齐哈尔等地推行经济统制，为日军掠夺资源。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e9321bff009540e0b2ad51ad652e267f','41502657c6b84465aa2ff94e620ed234',1931,'伪满洲国黑龙江省长','原东北地方官员，九一八事变后投敌，曾任伪黑龙江省长，参与伪满对黑龙江地区的统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0641ba1012714d69a56c074bb76fe014','77aa4951751342b79a81e38d021b4396',1931,'伪满洲国黑龙江省公署官员、伪满协和会要员','原黑龙江地方士绅，九一八事变后投敌，在伪黑龙江省公署任职并参与伪满协和会活动，协助日军推行殖民统治。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('94661c95f3d84bca8313ebef7f5cede8','56e668bf262e4d84a8cfe302e67fed6a',1931,'伪满洲国大庆地区维持会会长','大庆地区地方士绅，日军侵占后组织维持会，协助日军维持地方秩序、征发物资，为伪政权在让胡路及周边地区的基层代理人。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3f39378c304a40a682584b2d6422c98c','4fb7b58e00cf47eba0110680d7e06ced',1931,'伪满洲国安达县（今大庆地区）伪县长','伪满时期任安达县县长，安达为今大庆市辖区之一，其伪政权统治覆盖让胡路周边地区，协助日军征粮、征兵、镇压抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3474b778dc4540f3b8e2fdc9ccc72172','811e6ae674ab4f35a21e56d287668b58',1931,'伪满洲国肇州县（今大庆地区）伪县长','伪满时期任肇州县县长，肇州为今大庆市辖区，其伪政权活动覆盖大庆南部包括让胡路周边，协助日军推行保甲制、征发劳工。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('896d6b7686824309a8d580e6f0d2a683','cc04262f46964da7a7d0010566743c38',1931,'伪满洲国林甸县（今大庆地区）伪县长','伪满时期任林甸县县长，林甸为今大庆市辖区，其伪政权活动覆盖大庆北部地区，协助日军征粮、维持治安。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('67f4d5910e934e7b8b6efa535d86d241','0837a3474e904ef487f16512a0466cb2',1931,'伪满洲国杜尔伯特旗旗长','伪满时期杜尔伯特旗（今大庆市杜尔伯特蒙古族自治县）旗长，协助日军在牧区推行殖民统治、征发牲畜物资。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9c532e9a1dae4d9a8b8c284f6316fa9d','5a42f897a627483f9ceda7a629ea37f8',1931,'伪满洲国哈尔滨警察厅长、伪滨江省长','原东北地方官员，九一八事变后投敌，历任伪哈尔滨警察厅长、伪滨江省长等职，其统治区域邻近大庆地区，参与镇压抗日活动。；投敌后历任伪哈尔滨警察厅长、伪滨江省长等职，镇压哈尔滨及周边地区抗日活动，其辖区与齐齐哈尔地区相邻。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bef45f092f8445fa89390b7470a5b129','e0fa5cbb0dbf470b9076660b25821cf6',1931,'伪满洲国协和会黑龙江省本部要员','伪满协和会黑龙江省本部负责人之一，在黑龙江各地包括大庆地区推行协和会运动，协助日军进行思想控制和殖民宣传。','无明确职位或一般帮凶','hanjian');
