INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d141635ab13e4b049c527e0d1cc955bf','c54605d788c84d09b99be7b0e7e3d0fb',1937,'伪牡丹江省次长（日本人实际掌权）','作为日本籍次长，实际控制伪牡丹江省行政，主导“治安肃正”行动，围剿抗日武装。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7f1931d5c1f34e30a3935c3835e90026','b21d5a4d224a4173bdb0f2b366c98d70',1938,'伪牡丹江市市长','任伪市长期间，协助日军建立保甲制度，推行“粮谷出荷”，强征民间粮食，迫害抗日家属。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1b0e8438d4b147bd96fb461ae68097de','1ba31d558b934fbd83a28a8c2b446022',1932,'伪满洲国军政部大臣（原黑龙江地区军阀）','早年投靠日军，在牡丹江地区协助日军镇压抗日义勇军，后任伪满高官，参与“讨伐”抗联部队。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ef3f67176f664c9ea3415ab1f8310c68','e25c85c91f604ceda710a0637532c900',1932,'伪满洲国第四军管区司令官（驻牡丹江）','率伪军多次围剿东北抗联第五军、第二路军，在牡丹江、宁安等地制造多起惨案。；原吉林自卫军将领，叛变后任伪军高官，在牡丹江地区围剿抗联部队，制造多起屠杀事件。；率伪军参与围剿东北抗日联军，在牡丹江地区多次发动“讨伐”行动，残害抗日军民。；原吉林自卫军将领，后投靠日军，在牡丹江地区围剿抗日联军，制造多起屠杀事件。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4595ecdb4c85410486ee00388ae6b75a','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满洲国立法院院长（曾任哈尔滨地区职务）','虽主要活动于新京，但曾参与牡丹江地区“土地奉上”运动，协助日本掠夺土地资源。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('54c5e3728a4942348cb1f5e79c6c8679','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满洲国经济部大臣（曾任黑龙江地区职务）','在牡丹江地区推行经济统制，强征木材、煤炭等战略物资，为日军侵华战争服务。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('090cd7aacaf3435ebab073c08b44e57a','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1937,'伪牡丹江省警务厅厅长','指挥伪警察配合日军“讨伐”抗联，逮捕、刑讯抗日志士，破坏地下党组织。','市县厅局级','hanjian');
