INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9d1529a3379143abaeb675ead0836036','abf27b7e86794a318f200e061ee7437f',1937,'伪宁安协和会会长','在宁安地区宣传“日满亲善”，诱骗青年参加伪军，收集抗联情报供日军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9205a6210188431fb8b045c1a53234e4','93f14e1340304e9cac4d12a04a6586a6',1938,'伪牡丹江地区自卫团团长','组织地方自卫团协助日军封锁山区，在牡丹江周边多次伏击抗联小分队。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('35889db6fc0d400fa6af81b9fdfec468','e25c85c91f604ceda710a0637532c900',1932,'伪满洲国第四军管区司令、伪滨江省省长','原东北军将领，后投敌，在牡丹江、林口地区多次指挥伪军对抗联第二、第五军进行“讨伐”，制造多起惨案。；原吉林自卫军将领，叛变后任伪军高官，在黑龙江、牡丹江地区多次率伪军“围剿”东北抗日联军，制造多起惨案。；原吉林自卫军将领，1932年率部投日，后任伪满第四军管区司令，管辖包括牡丹江地区，多次参与“讨伐”抗日联军，残害抗联将士。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('04a839fed15847379ebb857aef4bd67f','5f8f1bdeab2443a586dc30df423055ea',1937,'伪牡丹江省警务厅厅长','在牡丹江地区组织特务警察网，破坏抗联地下组织，逮捕并杀害多名抗联联络员和爱国群众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4ab93a2d2177420a8136a55535e80ccb','bedc991fdcff4254a3e2b0b24052d010',1938,'伪林口县县长','在林口县推行“集团部落”政策，强迫村民并屯，烧毁抗联支持村屯，协助日军封锁抗联粮食来源。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('66ba5791aca940b5b6b0d280f98d2e69','0ce82afb041f4eb4a6fb886726d0274f',1931,'原抗联第九军军长，后叛变投敌','1939年叛变后，在牡丹江、林口一带充当日军向导，诱降抗联人员，参与围剿抗联第二路军，导致多支小分队被消灭。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a5ff21111c8f403baabeb6998441dc94','ee5c41cf755c4b6b860f8ba54a0a1a81',1931,'原抗联第八军军长，后叛变投敌','1939年投敌后，在勃利、林口地区协助日军搜捕抗联，出卖抗联密营位置，致使抗联第八军余部几乎全灭。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c1fbdbaf834345b38ac8ada54a31b66c','e6820d2aa832490383c4cf59368c46e9',1935,'伪牡丹江省地方保安局局长','在林口、穆棱等地组建汉奸保安队，配合日军“讨伐”抗联，多次带队袭击抗联后方医院和密营。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('574dc1971b364830b4683fa45478f184','fa0718a4704242fd97cdb99928d55ecb',1940,'伪林口县警务科科长','在林口县实施“连坐”制度，抓捕抗联家属，严刑逼供，破坏抗联地方关系网，导致数十名抗联交通员牺牲。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bc4bd43915184b1a843560b0f36d6e3a','12c5379941bf4233979d59829a7c4ecd',1937,'伪牡丹江宪兵队翻译官兼密探','为日军宪兵队充当翻译，参与审讯抗联被俘人员，提供情报导致抗联第三军部分密营被摧毁。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3f648935a2614710809a9882927d8dc3','4d8ee535e808458cb76e82411cc0e24a',1933,'伪满林口地区自卫团团长','组织地方汉奸武装，协助日军封锁山区，多次伏击抗联小股部队，并杀害抗联伤病员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3ec4de2d3eab4280aac1ee4fd717cf9d','4b486850921b4f33b616f1f8dcdef313',1932,'伪满洲国滨江省省长、伪外交部大臣','原哈尔滨特别市市长，投日后任伪滨江省省长，管辖哈尔滨及牡丹江部分地区，配合日军清乡并屯，迫害抗联家属。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fe720ac6a3964079a38b9c727970f128','41502657c6b84465aa2ff94e620ed234',1933,'伪满洲国黑龙江省省长、伪民生部大臣','原黑龙江省政府委员，投日后历任伪职，在牡丹江地区推行“集团部落”政策，强迫农民并村，切断抗联与群众联系。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e6c78c30e1384cc282891ae5a10e6d8c','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1937,'伪满洲国牡丹江省省长','原东北军旅长，投日后任伪牡丹江省省长，管辖海林等地，组织伪警察和自卫团，配合日军“讨伐”抗联第五军等部队。；在牡丹江地区强制推行“粮谷出荷”，强征劳工修筑军事工事，配合日军“讨伐”抗联。；在牡丹江地区推行“集团部落”政策，制造无人区，协助日军清剿抗联部队。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('920f7398004a45f7909ffa1c5fd953dc','b21d5a4d224a4173bdb0f2b366c98d70',1937,'伪满洲国牡丹江省次长（实际掌权者）','日本关东军指派，虽为次长但掌握实权，在牡丹江、海林地区推行“保甲连坐”制度，残酷镇压抗日群众。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('717895e1ce8c4f3da5182538d057f6d9','bfa2dbb2076741f58aecc2fdf5c97944',1938,'伪牡丹江省警务厅厅长','负责牡丹江地区伪警察系统，多次组织特务侦捕抗联地下联络站，在海林、宁安等地杀害抗联战士及支持者。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3102a4d597af4b71b2c296054a45829c','29a829baea1349b69f8cf6b6d13c3bd9',1932,'伪海林县县长','投日后任海林县伪县长，协助日军建立伪政权，强征劳工修筑铁路和军事设施，对抗联活动区域进行经济封锁。','基层头目','hanjian');
