INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3707b375ad5d4ae69317705322726ea5','ab3dded23c7447adb919b9a8705e1bf9',1933,'伪满洲国陆军少将、牡丹江地区伪军司令','率伪军部队驻扎牡丹江，多次参与对海林、宁安一带抗联的“大讨伐”，烧毁村屯，屠杀抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('48a6d8c051704f2a83bb6499df69d758','45f8b1c05208496ea61194b01b85387d',1939,'伪牡丹江省地方保安局局长','负责地方武装和情报工作，在海林地区建立特务网，诱捕抗联人员，破坏抗联与地方百姓的联系。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2df9185751264354a553fea5f01ca05d','a71dbc85fdb841f3a07582c268129876',1937,'伪牡丹江省省长','原地方官僚，投日后任伪牡丹江省省长，推行日伪“治安肃正”，强征劳工，镇压反满抗日活动。','省部级/大军区级要员','hanjian');
