INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dd224ec087964aec86059ee87d83e5d5','3cd55e29febc489d9f9a7f2f88db31bb',1937,'伪爱民县警察署署长','率伪警察配合日军“讨伐”，在爱民山区烧毁民房，抓捕抗联交通员，并参与“集团部落”建设。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cdaeebc5220b46d5a5d1d6605fca4765','77a789268c6f47b4a617cdb9e41180bd',1932,'伪满洲国国务总理大臣（原黑龙江省将军）','作为伪满最高汉奸之一，虽常驻新京，但曾多次到牡丹江地区视察“治安”，支持日军对爱民等地的清剿。','伪政权最高层/元首级','hanjian');
