INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('75b2bac0134c47038ae400470b1c0a7f','e25c85c91f604ceda710a0637532c900',1932,'伪满第四军管区司令官、伪满滨江省省长','原吉林自卫军将领，1932年率部投敌，后任伪满军高官，在牡丹江、哈尔滨等地多次围剿东北抗日联军，制造多起惨案。','省部级/大军区级要员','hanjian');
