INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('98291acf88cc4b9793fbc54d0050da5b','811e6ae674ab4f35a21e56d287668b58',1936,'伪庆安县保甲长','庆安本地保甲长，为日军征粮、派夫，监视村民，协助镇压抗日地下活动。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('56a81c7544df492ea13d5c5864d300a8','fa081831868d44108b0d4038f9b531cd',1934,'伪绥化县教育会长','在绥化推行奴化教育，强制使用日语教材，宣传“日满亲善”。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('897e8809371c43fb81e020afbc8b1378','9f6435babca8474caa7e795c474b02fa',1933,'伪庆安县商会会长','协助日军统制庆安粮食、物资，为伪军提供补给，压迫当地商户。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9b398947c0764017a80a902268083502','e25c85c91f604ceda710a0637532c900',1932,'伪满第四军管区司令、伪滨江省省长','原东北军旅长，投日后在黑龙江地区围剿抗联，后任伪滨江省省长，参与“治安肃正”行动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2239a719870f4631a41e0895a7e7c5da','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满立法院院长（曾任哈尔滨地区司法要职）','早年留学日本，投靠日本关东军，在哈尔滨及黑龙江地区协助建立伪满司法体系，镇压反满抗日人士。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6e0a30b8e6584a63886ac6e0525e52b1','b21d5a4d224a4173bdb0f2b366c98d70',1932,'伪绥化县县长','原绥化地方士绅，投日后任伪县长，强制推行“归屯并户”，协助日军建立“集团部落”，迫害百姓。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('485c26151c3b4bf9a4c7a382933e17d7','79b17193512846a1a5bde9f5df22c926',1932,'伪满参议府议长（曾任黑龙江地区军政要职）','原奉系要员，投日后参与策划伪满政权，在黑龙江地区协助日军“清乡”，镇压抗日活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('998b5853b79c4396b0e08f5029c2686b','5cce8fcbbcc043c2820499553d6999c1',1933,'伪明水县警察署署长','原明水地方警察，投日后充当日军爪牙，多次带队搜捕抗联地下交通员，杀害无辜百姓。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('46d7aa54fc854b3b919afeaf96cd2595','3cd55e29febc489d9f9a7f2f88db31bb',1934,'伪绥化地区保安队队长','投靠日军后组织汉奸保安队，在绥化、明水一带袭击抗联小分队，烧毁村庄，抢夺粮食。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c88a9977fdd44de89f841e33a3dae679','77a789268c6f47b4a617cdb9e41180bd',1931,'伪满洲国国务总理大臣、伪参议府议长','辽宁台安人，九一八事变后公开投敌，历任伪黑龙江省省长、伪满洲国军政部总长、国务总理大臣，积极推行日本殖民政策，其势力覆盖黑龙江全境，包括绥化、望奎地区。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('54d7ad15e48c4aff9cb7205900164308','77aa4951751342b79a81e38d021b4396',1931,'伪黑龙江省维持会会长、伪省长','九一八事变后组织伪黑龙江省维持会，任会长，后任伪黑龙江省长，协助日军控制绥化、望奎等县，推行保甲连坐，镇压抗日活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c66edbf89a9a40c78254d5605a9ee3b5','3b74f508628f475a8777ffb7e38a48a0',1932,'伪黑龙江省长、伪满洲国经济部大臣','原为哈尔滨商人，投敌后任伪黑龙江省长，积极为日军筹粮筹款，在绥化、望奎等地推行经济统制，后任伪满经济部大臣。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e02e795bba8646158e5cdbfd1efd5136','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1932,'伪绥化县县长、伪绥化地区维持会会长','九一八事变后投敌，出任伪绥化县县长兼维持会会长，协助日军建立伪政权，征发劳工、粮食，镇压当地抗日救国会。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fa718875beb84b6b8b31922990906e21','56e668bf262e4d84a8cfe302e67fed6a',1933,'伪望奎县县长、伪望奎县警察署长','投敌后任伪望奎县县长，后兼警察署长，在望奎推行保甲制，搜捕抗日地下工作者，强征国兵和劳工，为日军提供情报。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e5b561fe2c144ea99fc2b0735a624f11','c9dffc071fec4ce58fe1d611f26c28da',1934,'伪绥化县警察大队长、伪滨江省警务厅警正','长期在绥化地区任伪警察头目，指挥伪警察配合日军讨伐队扫荡抗日联军，在望奎、绥棱等地制造多起惨案。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('46210b262bef4c62a5b8dce3f1b1cf73','811e6ae674ab4f35a21e56d287668b58',1935,'伪望奎县保甲长、伪协和会会长','望奎本地地主，投敌后任保甲长兼协和会会长，协助日军征粮、抓劳工，监视村民，迫害抗日家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('271d1835591b42078134db3ef2535fcb','5762ca5794044116b48fdb68f6cd67b5',1936,'伪绥化县教育会长、伪协和会绥化分会理事','在绥化教育界推行奴化教育，编写亲日教材，组织学生参拜神社，为日军培养顺民，是文化教育领域附逆者。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4a46152756174a1689baa4c6c720114e','9f6435babca8474caa7e795c474b02fa',1937,'伪望奎县商务会长、伪经济统制委员会委员','望奎商人，投敌后任商务会长，协助日军实施经济统制，低价强购粮食、物资，供给日军，压榨当地民众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('56ed236d056741fdab94a342360e4cff','105c4446aaf347b2a0ed658ef91afcc1',1938,'伪绥化县保安团长、伪滨江省保安总队副','组建伪保安团，配合日军在绥化、望奎、庆安等地讨伐抗日联军，杀害抗日军民，后升任伪滨江省保安总队副。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('829722b1d21b4e178ec83f067d5d8cf1','875c22d678e24c21834a32caae69933c',1931,'伪满洲国财政部大臣、吉林省长','清室宗亲，九一八事变后率先投敌，以吉林省长身份宣布独立，后任伪满财政部大臣，其附逆行为对包括黑龙江在内的东北全境产生恶劣影响。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('31d2cf77a9e84ae0ab20d659579fa9a5','79b17193512846a1a5bde9f5df22c926',1931,'伪满洲国民政部大臣、奉天省长','原辽宁省主席，被俘后投敌，历任伪奉天省长、民政部大臣，参与伪满殖民统治，其政策推行至黑龙江各地。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6734da59413448a398e143affda58e43','4b486850921b4f33b616f1f8dcdef313',1932,'伪满洲国滨江省长、驻哈尔滨特派员','原中东铁路督办，投敌后任伪滨江省长，管辖区域包括今哈尔滨及绥化部分地区，参与镇压抗日活动、推行保甲连坐。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d176a485f04243ceb43273f782519f8b','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满洲国军少将、伪第三军管区司令官','原东北军军官，投敌后任伪军旅长、第三军管区司令官，活动于北满地区，包括绥化、海伦一带，参与围剿东北抗日联军。','基层头目','hanjian');
