INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c7ca4ef612994fad833969b36a9b05e0','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1932,'伪满洲国军少将、伪绥化地区警备司令','投敌后任伪军团长、绥化地区警备司令，直接负责绥化、海伦一带的治安肃正，配合日军围剿抗日联军和地下抗日组织。','市县厅局级','hanjian');
