INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7c0a6fdc0b334c0a8d324304b481d751','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1930,'伪绥棱县公署县长','任伪绥棱县县长期间，推行保甲制度，配合日伪征粮、征兵，镇压当地抗日群众，维持殖民统治秩序。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('078d75c41e244510bd95f732c053a458','77aa4951751342b79a81e38d021b4396',1932,'伪绥化县维持会会长、伪绥化县长','九一八事变后组织绥化维持会，迎接日军进城，后任伪绥化县长，协助日伪推行殖民政策，搜捕抗日人员。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c23d2a9c6fe04614ba3894eee9387ef2','da40a6d1008540c1a3f0b3fba117291e',1930,'伪绥化县警务局长','任伪绥化县警务局长期间，指挥伪警察配合日军\'讨伐\'抗日联军，在绥棱、庆城一带搜捕抗日地下工作者。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('af69621f6e5c41e7ac5fe2438d1d4404','5762ca5794044116b48fdb68f6cd67b5',1932,'伪海伦县县长、伪绥化地区协和会会长','历任伪海伦县长、绥化地区协和会会长，积极推行\'王道乐土\'宣传，协助日伪征调劳工、粮食，支持殖民统治。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('51ab349476cc4cb2878beb1bd6133cf1','5a42f897a627483f9ceda7a629ea37f8',1932,'伪哈尔滨市长、伪滨江省长','历任伪哈尔滨市长、滨江省长，管辖范围包括绥化地区，推行日本殖民经济统制政策，压榨当地民众。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('429dd3e96e34417990cba2074dc167c1','acf7dcdffeda4a0a87c947be2dd7f78a',1932,'伪满洲国文教部大臣、伪黑龙江省教育厅长','长期在伪满教育系统任职，推行奴化教育，在黑龙江地区包括绥化各校强制日语教学，篡改历史，毒害青年。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f53b6b7255b8414caa50f9d1526220a3','a7782cdd2135413ca8cb5f5ed2ecc41b',1930,'伪绥棱县协和会事务长','任伪绥棱县协和会事务长，配合日伪进行思想控制、物资统制，动员当地青年参加伪军，协助镇压抗日活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7fa9e676906e4ae5be097ecf6ef1c137','3eb966fdcf364389b5302ef8a669f7ac',1940,'伪满黑龙江省省长','原东北军文职官员，投敌后任伪满黑龙江省省长，管辖绥化地区，积极推行“粮谷出荷”政策，导致绥化农民粮食被大量掠夺。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1d162e50d660406f8c9623221dbc1dba','4ae2b4fe56d3444f8a7f2c44a74a1d2f',1932,'伪满绥化县县长','原绥化地方士绅，日军占领绥化后出任伪县长，协助日军建立伪政权，组织“自卫团”对抗联进行清剿，强征民夫修筑公路和碉堡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('433fd7c843e349ffbf2c73a429d73806','ba135ba1ef794aeba0fdad0065a31974',1933,'伪满肇东县县长','原肇东县商会会长，投敌后任伪县长，积极为日军筹集军粮，镇压当地抗日武装，曾参与抓捕多名抗联地下交通员。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('22ad9b1f98654a75a34f071fa760d466','875c22d678e24c21834a32caae69933c',1932,'伪满宫内府大臣','原吉林省政府委员，九一八后投敌，曾率伪军参与对黑龙江地区的军事行动，其部队在绥化、肇东一带烧杀抢掠，对抗联进行残酷镇压。；原吉林军将领，投日后参与伪满统治，间接涉及黑龙江地区殖民管理。','无明确职位或一般帮凶','hanjian；traitors');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('200223033f9845c0acf61b10155f7e03','a984ebfabbf64a5b8e1dfef2d68daa53',1933,'伪满吉林军区司令','原东北军旅长，投敌后任伪满吉林军区司令，曾率伪军进入黑龙江绥化地区围剿抗联第三路军，制造多起惨案。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('52ba0b58fa624d92ad5ae3da99f46dbe','2acf7a5b9b5341578e1066b27394b2eb',1934,'伪满滨江省警务厅长','原哈尔滨警察厅长，投敌后任伪满滨江省警务厅长，直接指挥肇东、呼兰等地伪警察对抗联进行搜捕，曾下令处决多名抗日嫌疑犯。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('56a451d2760a4fa0b7d6e5d28d10d9bb','922b606d45c647e8a82755373b3d3e91',1935,'伪满绥化地区保安队长','原绥化土匪头目，被日军收编后任伪保安队长，带领伪军多次袭击抗联小分队，杀害抗日群众，在绥化、海伦一带民愤极大。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('54239a37e88c4dd0a53678f96830ec24','3cd55e29febc489d9f9a7f2f88db31bb',1936,'伪满肇东县警察署署长','原肇东地方恶霸，投靠日军后任伪警察署长，积极抓捕抗联情报人员，曾参与“三肇惨案”中对抗日群众的屠杀。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d6d53bfd49b44d7d8722237ed18cbb38','747a2f8d75af4f88878f6678522d9ee0',1937,'伪满绥化县协和会会长','原绥化富商，投敌后任伪协和会会长，协助日军进行奴化宣传，组织“勤劳奉仕队”为日军服劳役，强征青年充当伪军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5fbad469acf24cd6ac51046073a61c80','7bc0733973dc48289a125ec6e06eee05',1938,'伪满肇东县协和会会长','原肇东地主，投敌后任伪协和会会长，配合日军推行“粮谷出荷”，强迫农民交出粮食，导致当地多次发生饥荒。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ec765ffe652240e980cb67a1f5ce41cc','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满热河省省长（原籍青冈县）','九一八事变后投靠日军，任伪满热河省省长，协助日军镇压抗日武装，推行殖民统治。','省部级/大军区级要员','hanjian');
