INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b30c6b4f865644368c285bc2d5704d3b','3eaf116c87a7417fadcbf5fe87b56f23',1933,'伪青冈县警务科科长','指挥伪警察抓捕抗日地下工作者，破坏抗日组织，多次参与“清乡”行动。','基层头目','hanjian');
