INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a48a10af7a8e405d9c8f8558f85e0c8e','a2c03b81e5f2412bb86f5d5599c1687b',1937,'伪绥化地区宪兵队翻译官','为日军宪兵队充当翻译，参与刑讯逼供抗日志士，直接导致多名地下党员牺牲。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('544d6008cadd4736905bc0ca8618e863','183cdd75c53f44f090e2cfb638987622',1932,'鸡西地区伪满警察署署长','效忠伪满洲国，镇压抗日武装，抓捕抗联地下工作者，协助日军推行“归屯并户”政策。','无明确职位或一般帮凶','hanjian');
