INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('32fda187f6b24b8d9369d6e0454e666a','41502657c6b84465aa2ff94e620ed234',1932,'伪满洲国民生部大臣（曾任黑龙江省长）','在黑龙江推行“粮谷出荷”政策，强征粮食，导致民众饥荒，间接支援日军侵华。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d8a54440ec24435194a89372092a5ee7','5f8f1bdeab2443a586dc30df423055ea',1932,'密山县伪县长','任伪密山县县长期间，积极推行日伪殖民政策，协助日军镇压抗日武装，强征劳工，搜刮民财，为日本侵略者提供物资和情报。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('34a8ac403dc2433083c1101babbba47b','7d92af6f9a2e424cb6007e5d7eb83ff5',1933,'密山县伪警察署署长','指挥伪警察配合日军“讨伐”抗日联军，抓捕抗日志士，实施“归屯并户”，制造无人区，残害百姓。','无明确职位或一般帮凶','hanjian');
