INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4287350c00bd4871a48dba0b7033def8','3408c53c0e42419c8b915765fa592811',1935,'鸡西（鸡宁）县伪县长','在鸡西地区强制推行“粮谷出荷”，强征农民粮食，组织劳工为日军开采煤炭，镇压反满抗日活动，迫害矿工。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('52ee546ae7b14820b29af175170196ba','811e6ae674ab4f35a21e56d287668b58',1936,'鸡西煤矿伪矿长','管理鸡西煤矿期间，残酷压榨中国矿工，实行“人肉开采”，导致大量矿工死亡，并配合日军将矿工充当细菌实验对象。','无明确职位或一般帮凶','hanjian');
