INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('be24e9aef4e34a019cca3859b8e5d5eb','a97fc43114194788815ba7bf32d91402',1938,'伪鸡宁县兴农合作社理事长','鸡西地区经济附逆者，任伪兴农合作社理事长，协助日军统制粮食、掠夺农产品。','无明确职位或一般帮凶','hanjian');
