INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('54ab9deec8d2433686a443cffaaba583','764916e3dc534a258706aecb1a8a8de8',1933,'伪鸡宁县保安大队大队长','鸡西地区伪军头目，率伪保安大队协助日军围剿抗日武装，镇压民众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7c77ec7e87ae4c30b124695ec95f18b3','7c4f055fe1bf4b1ea64573ebbd87eeb8',1933,'伪满滴道煤矿矿长','任伪满滴道煤矿矿长期间，残酷压榨中国矿工，推行‘人肉开采’政策，导致大量矿工死于事故和疾病，并协助日军抓捕抗日分子。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f84cbbd77d534edebd7964d42b93d8ba','5568708bb9b44d7a93d6adfffc6882f0',1935,'伪滴道区警察署署长','效忠日本关东军，在滴道地区大肆搜捕抗日联军地下工作者，多次带队‘讨伐’抗联小分队，杀害无辜百姓，并强征劳工送往煤矿。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f023bdccf3bc48c488962237bc194b28','bb9f3367044e403997a73a2007e0c137',1937,'伪滴道保安队队长','协助日军维持‘治安’，参与镇压1938年滴道矿工暴动，事后按日军命令处决数十名矿工，并充当日军耳目，破坏抗联地下联络站。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('06fc333c18954eda8c2d23dd830bc12d','a2c03b81e5f2412bb86f5d5599c1687b',1938,'伪满鸡西县协和会会长','在鸡西地区积极推行奴化教育，组织‘协和会’宣传‘日满亲善’，为日军募集物资，并告发多名抗日群众，导致其被逮捕杀害。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b6a0d1e1b475482fbbdad7bd689dd801','d7404e20b4894fc5b66a2d88c815fd9a',1939,'伪满滴道炭矿劳务系主任','负责管理矿工‘劳务’，制定严苛的惩罚制度，克扣矿工口粮，将病弱矿工直接抛弃于‘万人坑’，并配合日军进行‘思想矫正’。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1dcb4d2cc4a64a47933cce5e006f24c8','34332cbbb74349ac846bff070035276e',1940,'伪滴道区公署副区长','协助日伪推行‘保甲连坐’制度，强征农民土地供日军修建军事设施，多次向日军提供抗联活动情报，致使抗联小分队遭伏击。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ce5a5db5fa4742c2a051e6d1d8ba7f11','46342daf1a484dfba81e138a2809ec0b',1936,'伪满鸡西宪兵队翻译','充当日军宪兵队翻译，参与审讯和刑讯抗日志士，多次歪曲供词制造冤案，并直接参与抓捕滴道地区的地下党员。','基层头目','hanjian');
