INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('eebe599c5e2145fb8ec202beff51addd','884290298a5240d6a539e00105d0e557',1939,'伪满滴道自卫团团长','组织地方自卫团协助日军扫荡，在滴道周边村庄烧杀抢掠，曾一次抓捕12名疑似抗联联络员的农民，全部移交日军处死。','基层头目','hanjian');
