INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3817ae507a0149bf8c375ac421ccce57','f95a1dca0527475aaeda26f11505e4ba',1935,'伪鸡冠山保保长','鸡冠山地区保长，执行日伪保甲制度，监视民众，举报抗日人员，协助日军维持地方统治。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2f719ba223b14c768d4118c87f239706','4fb7b58e00cf47eba0110680d7e06ced',1937,'伪鸡西县警察署署长','伪鸡西县警察头目，率伪警察配合日军搜捕抗日人员，镇压当地抗日活动，残害民众。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('75dacc07b1344fce99eeb800b1bf151d','da87decdc16449e7a61b523d5cd80631',1939,'伪东安省教育厅厅长','在东安省（含鸡西地区）推行奴化教育，篡改历史，强制教授日语，为日伪统治培养顺民。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8856351c507d4969bcebb2bb5ea3c0f1','82c8dc8c68f3449d85ce6770c252b411',1938,'伪满洲国协和会鸡西分会会长','在鸡西地区组织协和会，进行反动宣传，协助日军征劳工、征粮，监视民众思想。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ef514991a9a1495d89293a3f7809f4ce','5f8f1bdeab2443a586dc30df423055ea',1933,'伪鸡宁县县长','任伪鸡宁县（今鸡西地区）县长期间，积极推行日伪殖民政策，协助日军镇压抗日武装，强征劳工，掠夺当地煤炭资源。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f662b866f062402ebbffea564308e2e4','7c4f055fe1bf4b1ea64573ebbd87eeb8',1938,'伪麻山警察署署长','在麻山地区担任伪警察署长，多次参与围剿抗日游击队，抓捕并杀害抗日志士，为日军提供情报，欺压百姓。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('89dedb1e9f8d44479410ef1a6c3e9c29','bb9f3367044e403997a73a2007e0c137',1940,'伪鸡西地区保甲长','作为日伪基层保甲长，强征民夫修筑军事工事，搜刮百姓粮食，告发抗日群众，导致多人被捕牺牲。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('192933eae1344ea7b2453e6c7c3e1497','be101ae50c01499eb4d1ad9af8d79b62',1941,'伪麻山地区维持会会长','在麻山地区组织维持会，为日军筹集粮饷，协助日军“清乡”，迫害抗日家属，破坏抗日组织。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dc134646680945ce98dc15ed73cecffe','759cfb5f46624562bc0d114d5292cbca',1942,'伪鸡西宪兵队翻译','担任日军宪兵队翻译，参与审讯和酷刑迫害抗日志士，提供情报导致地下党组织被破坏。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6d801b5742894471ae40281f26bee53b','4b486850921b4f33b616f1f8dcdef313',1932,'伪满民政部大臣、伪满滨江省省长','原哈尔滨特区行政长官，投日后任伪职，在黑龙江地区推行奴化教育和经济统制。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e17f2a7fd452423e99fc180048a9d39b','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满财政部大臣、伪满黑龙江省省长','原黑龙江省实业厅长，投敌后任伪省长，协助日军征粮、抓劳工，用于鹤岗煤矿开采。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7001e3b2bd194069be3e99f8b8aa4415','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1934,'伪满三江省省长（辖鹤岗）','原依兰镇守使，投日后任伪三江省省长，管辖鹤岗矿区，协助日军强征矿工，迫害劳工。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4627c40e7c294e37b4b6b61453f13a29','350822a1078340679fd657c16a793993',1935,'伪满三江省次长、伪满吉林省省长','在伪三江省任职期间，直接参与对鹤岗地区抗联部队的围剿，并管理煤矿劳工。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c7d33bed7f5142509c2df912b8a06f40','3eb966fdcf364389b5302ef8a669f7ac',1937,'伪满三江省警务厅厅长','指挥伪警察在鹤岗地区搜捕抗日分子，破坏地下组织，实施白色恐怖。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a0e83d149f1d4452b84e6d3feccf02a7','36b224f130874075a493b942fa563224',1933,'伪满鹤岗煤矿株式会社理事长','负责鹤岗煤矿的掠夺性开采，强迫中国劳工劳动，造成大量矿工死亡。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('29605f41904a489cbc01dee723c811f2','1fa9cf4140ff4d4685c2f82bb6160799',1938,'伪满鹤岗煤矿次长','实际控制鹤岗煤矿生产，推行“以人换煤”政策，虐待矿工。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ed5bae7917fe4e38b9803fa66b273e32','b21d5a4d224a4173bdb0f2b366c98d70',1939,'伪满鹤岗县县长（1939年设县）','在鹤岗县推行伪满法令，组织“协和会”，协助日军征粮抓丁。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('306c95fe43f84fdcb0b4a050ed682d4b','e25c85c91f604ceda710a0637532c900',1932,'伪满第四军管区司令、伪满滨江省省长','原吉林军将领，投日后任伪满第四军管区司令，驻防哈尔滨及黑龙江地区，多次率伪军“讨伐”抗日联军，后任伪滨江省省长。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3babe7d177414f66aeaf0a9ce26cc1a2','4b486850921b4f33b616f1f8dcdef313',1932,'伪满滨江省省长、伪满司法部大臣','原哈尔滨特别市市长，投日后任伪滨江省省长，管辖鹤岗、东山等地区，积极推行“治安肃正”，捕杀抗日人员。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('88c656c9660041528b02afb153068015','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1932,'伪满黑龙江省警务厅厅长','原黑龙江省警察头目，投日后任伪省警务厅长，在鹤岗、东山地区建立伪警察网络，多次参与“讨伐”抗日联军，逮捕抗日志士。；原黑龙江省警察机构官员，投日后任伪满省警务厅厅长，在齐齐哈尔、拜泉等地组织特务网，抓捕抗日地下工作者，破坏抗日组织。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('70dadf4fa18b43c481dd3dba25b777f9','41502657c6b84465aa2ff94e620ed234',1934,'伪满黑龙江省公署参事、伪满鹤岗煤矿公司监事','原鹤岗煤矿中方管理人员，投日后任伪满鹤岗煤矿公司监事，协助日军强化对鹤岗煤矿的掠夺，压迫矿工，破坏抗日地下活动。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8770bb8255ab4a499f197516edfc2716','b21d5a4d224a4173bdb0f2b366c98d70',1935,'伪满鹤岗县县长（伪满时期鹤岗为县）','投日后任伪鹤岗县县长，在鹤岗、东山地区推行保甲制度，组织伪自卫团，配合日军“清乡”，多次围剿抗日游击队。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c282f7e863ac4748b3538215ec8a0c8f','77a789268c6f47b4a617cdb9e41180bd',1931,'伪满国务总理大臣（原黑龙江省省长）','原东北军将领，九一八后投敌，曾任伪黑龙江省省长，后升任伪满国务总理，虽主要活动于新京，但其早期在黑龙江（含鹤岗、东山地区）的伪政权建设中起核心作用。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bf41c6cdb47a4bc78aa4941dc4a256cc','b8f5150658fd47f0a48c92aacb628181',1932,'伪满黑龙江省省长（短暂投敌）','1932年2月一度投降日军，任伪黑龙江省省长，但同年4月反正，重新抗日。因短暂投敌，部分史料将其列入汉奸名录，但最终反正，故仅作备注。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('806a87ed8276405c9a8cb653352089f7','1ba31d558b934fbd83a28a8c2b446022',1932,'伪满洲国黑龙江省省长、伪满治安部大臣','原东北军将领，1932年投敌，任伪黑龙江省长，协助日军镇压抗日武装，推行殖民政策。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a76af053ab1240349eeab532af1ae755','e25c85c91f604ceda710a0637532c900',1932,'伪满洲国第四军管区司令官（驻黑龙江）','原东北军旅长，叛变后率伪军多次围剿东北抗联，在鹤岗、兴山（今鹤岗）一带制造惨案。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7f2eb585c2ed4ba4a810318b966dedf3','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满洲国立法院院长（曾涉黑龙江事务）','积极参与伪满政权建设，为日本殖民统治出谋划策，涉及黑龙江地区行政规划。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2ccb3a861a3f4222b2d54e29a4508de7','4b486850921b4f33b616f1f8dcdef313',1932,'伪满洲国滨江省省长（辖今哈尔滨及周边）','原哈尔滨特别市市长，投敌后任伪省长，镇压反满抗日活动，协助日本开拓团侵占土地。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7f83d7690cdb4ecea3813928236460e3','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1934,'伪满洲国三江省省长（辖今佳木斯、鹤岗一带）','在三江省推行“集团部落”政策，制造无人区，围剿抗联，对鹤岗矿区实施军事管制。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3098f7cbf42141779ab109ff70e127fd','350822a1078340679fd657c16a793993',1932,'伪满洲国兴安总省省长（辖兴安地区）','蒙古族投日分子，在兴安地区推行蒙满分离政策，组织伪兴安军协助日军镇压当地抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2357ec91e26a476681712fb464a52b2d','f4208529cb14438593c9984febac079f',1932,'伪满洲国兴安军司令官','蒙古王公出身，组建伪兴安骑兵，在兴安岭、嫩江流域多次袭击抗联和抗日民众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('15b586d8fa8a407a8690291ecd900f55','2eb96a1f022e434e830b2d5e2d6b720b',1932,'伪满洲国兴安北省省长','在兴安北省（今呼伦贝尔部分）为日军提供情报，协助镇压当地少数民族抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('de943f81b5e2481c94dba3d72547186d','dddf6075e9614f79add415cba2b3c0c4',1932,'伪满洲国兴安南省省长（后因反日被处决）','初期投日任伪省长，后因不满日本控制，暗中支持抗日，1936年被日军以“通苏”罪名处决。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3cb1ae86c03741bb8eb6ea50638d10e5','77a789268c6f47b4a617cdb9e41180bd',1932,'伪满洲国国务总理大臣（曾长期控制黑龙江军政）','原东三省特别区长官，全面投日，作为伪满最高汉奸之一，对黑龙江、鹤岗、兴安地区殖民统治负有总责。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('888627467c20406c966e6c5dc0fc4079','875c22d678e24c21834a32caae69933c',1932,'伪满洲国财政部总长（曾涉吉林、黑龙江交界）','原吉林军参谋长，策划吉林独立投日，参与伪满对黑龙江东部资源的掠夺。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('53886afea401439493e3d0d3bfdbebb4','b8f5150658fd47f0a48c92aacb628181',1932,'伪黑龙江省长（1932年4月-5月短暂投日）','一度投降日军任伪省长，但旋即反正抗日，故通常不列为最终汉奸，但历史记录中曾有此段。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3e821f304cad4ff097e56d0675495db7','12571fd3a6fa42cf9581b18a4b27a94e',1933,'伪满洲国第三军管区司令（驻齐齐哈尔）','在黑龙江西部及兴安地区围剿抗联，实施“三光”政策。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4c3904fa3c60401abd90d7590cb96654','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满洲国黑龙江省警务厅长','组织伪警察特务，在鹤岗矿区监视矿工，抓捕抗日地下人员。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b8d437ffa88346c3a70ad451b5a339b2','77aa4951751342b79a81e38d021b4396',1934,'伪满洲国三江省警务厅长','在佳木斯、鹤岗地区建立特务网络，破坏抗联地下联络站。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('31fe252718e74621b9fe5da91369fa89','b21d5a4d224a4173bdb0f2b366c98d70',1935,'伪满洲国兴安总省参事官','协助日军在兴安地区推行“并村”政策，强迫鄂伦春等族迁移。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8d8fa640f5894fc59021d8e0ffb754c8','acf7dcdffeda4a0a87c947be2dd7f78a',1934,'伪三江省民生厅厅长、伪三江省省长','伪满时期长期在三江省任职，历任民生厅厅长、省长等职，三江省省会佳木斯，辖今鹤岗、兴山一带，其推行日伪殖民统治、征发劳工等政策直接涉及该地区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5a2b16d611e54b649d0e837725b6105a','840818553d8c45c9bce18af1619ad433',1930,'伪三江省警务厅厅长','伪满时期任三江省警务厅厅长，负责该省警务、治安，配合日军镇压抗日力量，其辖区包括鹤岗、兴山地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4ab5810f7b994d6a8649fb1ba2d41ec4','9f6435babca8474caa7e795c474b02fa',1930,'伪鹤岗煤矿株式会社把头、伪兴山警察署嘱托','鹤岗煤矿地区汉奸把头，勾结日伪军警，残酷压榨矿工，迫害抗日人员，在兴山、鹤岗一带为日伪效力。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('96218b1baac94066b59724087514e4aa','0ce82afb041f4eb4a6fb886726d0274f',1932,'伪三江省依兰县自卫团总团长、伪军团长','原为抗日武装，后投降日军，任伪自卫团总团长、伪军团长，活动于松花江下游依兰、桦川、鹤岗一带，配合日军围剿抗日联军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8805485e62cd406b9137683222d464ae','ee5c41cf755c4b6b860f8ba54a0a1a81',1939,'伪三江省勃利县自卫团总团长、伪军团长','原为抗日联军将领，1939年投降日军，任伪自卫团总团长、伪军团长，活动于勃利、桦南、鹤岗一带，配合日军围剿抗联。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('49b56fffd5da4946a14bc7d8a16c5523','436c7bb566b04f88910f3c6d6b6ecf2b',1930,'伪鹤岗煤矿株式会社劳务系主任','在鹤岗煤矿充当日伪劳务管理人员，负责强征、管理矿工，迫害劳工，为日军掠夺煤炭资源服务。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('583a5abf18174840a4b9102aa3e52e4e','a872cc53a35f4bc48ed8b0deed3a7ed8',1930,'伪兴山保甲长','兴山地区伪保甲长，协助日伪征发劳工、征收物资、监视居民，迫害抗日群众。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5995b0bc8b244807bf6befc9b3704928','e25c85c91f604ceda710a0637532c900',1932,'伪满第四军管区司令官（驻佳木斯）','原东北军团长，投日后任伪满第四军管区司令官，司令部设于佳木斯，管辖包括鹤岗、汤原等地区，多次率伪军“讨伐”抗日联军，在鹤岗南山一带制造多起屠杀事件。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d44be182b3ad4cf6a583abe9eaf8fd95','c7860b02233843c585ba9e58000894e9',1938,'伪满鹤岗煤矿警察署署长','日本侵占鹤岗煤矿后，任伪警察署长，负责镇压矿工反抗，勾结日本宪兵队，在南山矿区抓捕并杀害抗日地下工作者及矿工，有“南山屠夫”之称。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5db4e99489444f319e5f0ee7e300e9d2','a46dc9727f3843558c64c0dabcbfa0be',1939,'伪满鹤岗保安队队长','原为地方土匪，投靠日军后任鹤岗保安队队长，协助日军在南山地区清乡，多次带队袭击抗联小分队，并参与“归屯并户”政策，烧毁民房，强征劳工。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('94a1289f6d61478299e5b2588aa80b7d','1e54500c401c434486b34d8492fafd8c',1940,'伪满汤原县鹤岗街公所所长','作为伪满基层行政头目，在鹤岗南山地区推行保甲制度，强制居民领取“良民证”，向日军提供抗联活动情报，并组织汉奸武装配合日军扫荡。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9326cd99ec0a452b956b552878a7a653','1733efb4824a42ddbf9cb8c18b981fa4',1941,'伪满鹤岗宪兵队翻译官','为日本宪兵队担任翻译，参与审讯和刑讯抗日志士，在南山地区多次指认抗联联络员，导致多名地下党员被捕牺牲。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('971ab16a207e4f4c9efb1fb6fcece347','811e6ae674ab4f35a21e56d287668b58',1942,'伪满鹤岗矿务局劳务科长','负责为日军强征劳工，在南山矿区实行“以人换煤”政策，克扣矿工口粮，虐待致死数百人，并告密矿工中的抗日组织。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('cb47d3b3703149139bc42bf3bfd06558','1ba31d558b934fbd83a28a8c2b446022',1932,'伪满洲国黑龙江省省长','1932年投靠日本，任伪黑龙江省省长，协助日军镇压抗日武装，推行殖民政策。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9291bcef8c264db3965c4661932e36fc','e25c85c91f604ceda710a0637532c900',1933,'伪满洲国第四军管区司令','原东北军将领，1933年叛变投日，在鹤岗、佳木斯一带围剿抗联部队，制造多起惨案。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fc95750d342143d993960fcf251815ce','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满洲国立法院院长（曾任黑龙江地区职务）','参与伪满政权建立，曾协助日本在黑龙江地区推行奴化教育，镇压反满抗日活动。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('495e15ca47ac4e98a8ef39b07c8b063b','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满洲国黑龙江省财政厅长','在鹤岗地区协助日军掠夺煤炭资源，强征劳工，迫害矿工。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b82d7a1851d643209b8c6009ce1523e2','41502657c6b84465aa2ff94e620ed234',1932,'伪满洲国黑龙江省民政厅长','协助日伪推行“保甲制”，在鹤岗矿区建立特务网络，迫害抗日群众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('186875e7b3b8483cb9b60390ab8cb1e6','350822a1078340679fd657c16a793993',1934,'伪满洲国黑龙江省协和会头目','在向阳地区组织协和会，宣传“日满亲善”，破坏抗日统一战线。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4972d3b26a1c4629a95eca8dcb262205','b21d5a4d224a4173bdb0f2b366c98d70',1933,'伪鹤岗煤矿矿长','为日军开采鹤岗煤炭，虐待矿工，提供资源支持侵华战争。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f14265555c38483a97e105946e55cf81','77a789268c6f47b4a617cdb9e41180bd',1935,'伪满洲国国务总理（曾管辖黑龙江）','作为伪满最高汉奸之一，其政策覆盖鹤岗、向阳地区，支持日军经济掠夺和军事镇压。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('18c5dc213df44a09b286a20c1294e401','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满洲国军少将、伪三江省警务厅厅长','长期在伪三江省（辖今鹤岗、佳木斯、双鸭山等地）任职，参与伪满地方警政与军事镇压，配合日军围剿东北抗日联军，是黑龙江东部地区重要附逆人物。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b747725c0db64df59545fa8c0ee199ec','ab041ed0fab3486f832f81b1b4e8a6ea',1932,'伪鹤岗煤矿株式会社理事长、伪满炭矿头目','在鹤岗煤矿地区为日军掠夺煤炭资源，残酷压榨矿工，配合伪满经济统制政策，是鹤岗地区经济领域重要附逆者。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0c79b12d8fd645d58a4fbcc5453de542','0ce82afb041f4eb4a6fb886726d0274f',1932,'伪三江省地方维持会会长、伪保甲长','在鹤岗及周边地区组织维持会，协助日军建立保甲制度，搜捕抗日人员，为伪满基层政权服务。','基层帮凶(维持会系统)','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('064070af40504f2683178524ee571bfa','77aa4951751342b79a81e38d021b4396',1936,'伪满洲国协和会三江省本部事务长','在伪三江省（含鹤岗地区）推行协和会殖民教化，宣传“日满亲善”，协助日军进行思想控制与情报搜集。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('556facaec3af4c5da2641109e9af1efd','3c793b1442ef48298a262b0d57814cab',1932,'伪满洲国军中将、伪江防舰队司令','在黑龙江地区任伪满军职，参与松花江、黑龙江流域的军事行动，配合日军封锁与围剿抗日联军，活动范围覆盖鹤岗周边水域。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6856766d4f0f4efa9f02b200edb9d8db','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满热河省省长（曾任黑龙江地区军事职务）','原东北军将领，九一八后投敌，在黑龙江地区协助日军镇压抗日武装，后任伪满高官。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d3ce172cc5324d299c3e0d3c05646404','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满立法院院长（曾任哈尔滨地区司法职务）','参与伪满政权建立，在哈尔滨等地推行殖民法律，协助镇压反满抗日活动。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2c0a14275fcd48e3bfd56a8c680d463e','41502657c6b84465aa2ff94e620ed234',1935,'伪满黑龙江省省长（后任伪满财政部大臣）','在黑龙江推行经济统制，掠夺资源，协助日军建立殖民统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a82ef93a17ef4eb1b4ea4c5e40b11e98','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1934,'伪满三江省省长（辖鹤岗、绥滨地区）','在三江地区（含绥滨、鹤岗）残酷镇压抗联，推行归屯并户，制造无人区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('80d09356a0204c4c9da8f23efbafb74f','acf7dcdffeda4a0a87c947be2dd7f78a',1937,'伪满三江省省长（后任伪满民生部大臣）','在鹤岗、绥滨一带强化保甲制度，抓捕抗日群众，配合日军“讨伐”行动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('07abfbbe91b24dc18fb64142793b4460','3eb966fdcf364389b5302ef8a669f7ac',1941,'伪满三江省省长（末期）','在绥滨、鹤岗地区强制劳工开采煤矿，迫害矿工，镇压反满活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5f7df038ad4748f4a3f194d0f5e24740','b21d5a4d224a4173bdb0f2b366c98d70',1932,'伪满鹤岗煤矿株式会社理事长','管理鹤岗煤矿，奴役中国矿工，为日军提供战略煤炭，造成大量矿工死亡。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b53a332416044c3f966c2dcdc77b4dbe','b8f5150658fd47f0a48c92aacb628181',1932,'伪满黑龙江省省长（短暂投日时期）','1932年2月一度投降日军，任伪省长，但4月反正，故不列入正式汉奸名录，此处仅作历史备注。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9b5a7e4267b54639bf9ca4c1750dbba5','12571fd3a6fa42cf9581b18a4b27a94e',1933,'伪满第四军管区司令（驻佳木斯，辖绥滨）','在佳木斯、绥滨、鹤岗一带指挥伪军多次围剿抗联，杀害抗联战士及平民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c565946e3a924de1a776b10c541cecdf','c9dffc071fec4ce58fe1d611f26c28da',1935,'伪满三江省警务厅长','在绥滨、鹤岗地区建立警察网络，抓捕抗联地下组织，实施酷刑。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8c693bfd84b64061ad68c779f03e91eb','fc768f7600844ca3b1149b426c41d8dd',1933,'伪满鹤岗县县长（伪满时期鹤岗为县）','在鹤岗推行“治安肃正”，强征民夫修筑警备道路，协助日军清乡。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('879201d256554da6b6aa2a88ad05d7a8','3cd55e29febc489d9f9a7f2f88db31bb',1934,'伪满绥滨县县长','在绥滨县组织“自卫团”，配合日军扫荡，强征粮食，迫害抗联家属。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c4f7039fda9048cd9477d6af0e28ab25','a2c03b81e5f2412bb86f5d5599c1687b',1936,'伪满绥滨县警务科科长','在绥滨县多次带队袭击抗联小分队，逮捕并杀害抗日志士。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d31516c34d424f6d809eefa1e1c1c61f','08e5273ef5cd4e63bb8877270c73bba6',1938,'伪满鹤岗煤矿劳务课长','负责从华北等地骗招劳工至鹤岗煤矿，克扣口粮，致数千劳工死亡。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e78cd78957a34fc79fce09d9a326a703','ba135ba1ef794aeba0fdad0065a31974',1939,'伪满三江省地方保安队队长','在绥滨、萝北一带为日军充当向导，参与“讨伐”抗联，烧毁村庄。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('feb0373143974ea19f59f55936a9cdb1','3a9e402192aa460fb51a927d874bb93e',1937,'伪满鹤岗地区“协和会”会长','宣传“日满亲善”，组织告密网，破坏抗日活动，协助日军抓捕反满分子。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b211783c8fef4f87980f64cf72006c34','544678d0c5554d9b9ad337282ed2ef07',1934,'伪满洲国军少将、伪三江省警务厅厅长','长期在伪三江省任职，负责警务和治安，伪三江省辖境包括今鹤岗、萝北等地，其指挥伪警察配合日军围剿抗日联军，镇压当地民众抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('903c3f0b9eca4b9b97da10317bd9d59d','acf7dcdffeda4a0a87c947be2dd7f78a',1937,'伪满洲国三江省省长','曾任伪三江省省长，管辖包括鹤岗、萝北在内的三江平原地区，推行日伪殖民统治政策，征发劳工、掠夺资源，配合日军对抗日联军进行经济封锁和军事围剿。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ee95ac887d5d4b40ba5a45d92c6dfe9b','9f6435babca8474caa7e795c474b02fa',1934,'伪萝北县县长','伪萝北县公署县长，直接负责萝北地区伪政权运作，推行保甲制度，征发劳工、粮食，配合日军和伪警察镇压当地抗日活动，是萝北地区主要附逆者。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f4df0792fc11446384cc70e8213ae645','1b0d93051c8343ec93855ecd4624a43f',1935,'伪萝北县警务局局长','伪萝北县警务负责人，指挥伪警察在萝北及周边地区搜捕抗日人员，实施保甲连坐，迫害抗日群众，配合日军维持殖民统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6bff43015f174de98530741a7b53bd36','4fb7b58e00cf47eba0110680d7e06ced',1936,'伪鹤岗煤矿株式会社劳务课课长','在鹤岗煤矿负责劳工征发和管理，配合日军强征中国劳工，实施残酷压榨，导致大量劳工死亡，是经济领域附逆者的典型。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ec369658196740c78812864ea88f6b70','3bdba80d49bb4825b5d28f9292f2391f',1932,'伪鹤岗街维持会会长','九一八事变后组织鹤岗街维持会，迎接日军占领，协助日军筹粮、征夫，维持地方秩序，为伪政权建立铺路。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d345a1da62724d04934492ceb036d35a','76877234e49e40abbd0e65850b11abac',1936,'伪满洲国军少将、伪三江省警务厅特务科科长','在伪三江省负责特务警察工作，派遣密探渗透抗日联军，破坏中共地下组织，其活动范围覆盖鹤岗、萝北一带，是镇压抗日力量的重要附逆者。','基层头目','hanjian');
