INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('049f9838f253493691c003baebc541a0','bde77533c68f469aa5eeb667ea3940ed',1932,'伪满立法院院长、哈尔滨特别市市长','原哈尔滨律师，投日后任伪满哈尔滨特别市市长，后升任伪满立法院院长，在哈尔滨及黑河地区推行日伪统治。','伪政权最高层/元首级','hanjian');
