INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('16350d4c983e4659a65d9ab3a77d95da','b8f5150658fd47f0a48c92aacb628181',1932,'（注：马占山曾一度投日，后反正，但按历史记录列入）伪满黑龙江省长（短暂）','原黑龙江省代主席，1932年2月一度投日任伪满黑龙江省长，但同年4月反正抗日，故其投日行为仅属短暂，后成为抗日英雄。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8f573257b5544e95b3c3ff2c1347df76','e25c85c91f604ceda710a0637532c900',1932,'伪满黑龙江省省长、伪满治安部大臣','曾任东北军将领，后投敌叛国，出任伪满黑龙江省长，积极推行日伪殖民政策，镇压抗日力量。；曾任东北军将领，后投敌叛国，任伪黑龙江省省长，积极推行日伪殖民政策，镇压抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2f5c9f2040644c5fb9d4ff47af3919a4','77aa4951751342b79a81e38d021b4396',1934,'伪满黑河省省长','在任期间协助日军建立黑河地区伪政权，强征劳工，掠夺资源，镇压抗联活动。；原黑河地区官僚，投日后任伪黑河省省长，协助日军统治黑河、爱辉地区，强征劳工，掠夺资源。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a15d37c0a28d4c5a926a8aa0486f2e0b','77a789268c6f47b4a617cdb9e41180bd',1932,'伪满国务总理大臣（曾任黑龙江省长）','原奉系将领，九一八后投敌，历任伪黑龙江省长、伪满国务总理，全面配合日本殖民统治。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f353c875c71345ec80e1f94583d65e6d','b8f5150658fd47f0a48c92aacb628181',1932,'伪满黑龙江省长（短暂）','1932年2月一度接受伪职，任伪黑龙江省长，但同年4月反正抗日，故不列为最终汉奸，但历史上有争议。','省部级/大军区级要员','hanjian');
