INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3183ce99bc394d878afb3efbc25c72f0','b8f5150658fd47f0a48c92aacb628181',1932,'伪满洲国黑龙江省省长（后反正抗日）','吉林怀德人，原东北军将领，江桥抗战后一度降日任伪黑龙江省省长，但不久即反正重新抗日，其短暂附逆期间与齐齐哈尔、克山地区有直接关联。；原东北军将领，江桥抗战后一度降日，任伪黑龙江省省长，但不久即反正重新抗日，其降日经历在齐齐哈尔、黑龙江地区有明确记载。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3157f48d6b9847d8b362264e908b3d59','3c793b1442ef48298a262b0d57814cab',1932,'伪满洲国黑龙江省警备司令、伪黑龙江省长','原东北军骑兵将领，马占山降日期间任伪黑龙江省警备司令，后任伪黑龙江省长，积极配合日军镇压黑龙江抗日力量，活动范围覆盖齐齐哈尔、克山等地。；原东北军骑兵旅长，1932年投敌，任伪黑龙江省警备司令，后任伪黑龙江省长，在齐齐哈尔地区积极推行伪化统治，镇压抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8bf98edf7d164b708b8d5cb27553e671','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满洲国黑龙江省警备司令部司令','原东北军军官，投敌后任伪黑龙江省警备司令部司令，协助日军维持黑龙江地区治安，镇压抗日武装，活动范围包括齐齐哈尔及周边克山等县。','市县厅局级','hanjian');
