INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('108ba258d6854652bb93a7aa9f986a87','02f0dacf55cf4095a949183cd365f6bf',1933,'伪满洲国克山县保甲长','克山地方保甲长，协助日军和伪县公署征收粮款、监视民众，举报抗日分子，维持基层殖民统治。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e2e29382e5854a21b65db11dd0832507','1b0d93051c8343ec93855ecd4624a43f',1933,'伪满洲国克山县自卫团团长','投敌后任伪克山县自卫团团长，率地方武装配合日军讨伐队进攻抗日游击队，镇压克山地区抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('daf4cf34f62f441b990900c5610bb233','e25c85c91f604ceda710a0637532c900',1932,'伪满洲国第四军管区司令官（驻齐齐哈尔）','原东北军将领，后投敌，任伪满军高级将领，驻防齐齐哈尔，负责镇压抗日武装，配合日军“讨伐”活动。；吉林双城人，原东北军将领，九一八后投敌，任伪满第四军管区（驻齐齐哈尔）司令官，负责镇压齐齐哈尔及周边抗日武装，多次参与“讨伐”抗联部队，残害抗日军民。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('92c652fa6d1744d7ae71e5d1ce62b0df','bde77533c68f469aa5eeb667ea3940ed',1931,'伪满洲国立法院院长（曾任黑龙江高等法院院长）','早年留学日本，后参与伪满建国，曾在齐齐哈尔司法系统任职，为日本殖民统治提供法律支持。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4c4c18e5386b4250a6bc5fec89150779','3b74f508628f475a8777ffb7e38a48a0',1932,'伪满洲国黑龙江省省长（驻齐齐哈尔）','原黑龙江省实业厅长，后投敌，任伪黑龙江省长，在齐齐哈尔推行日伪政令，强征物资，镇压反满抗日活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('94302763bb504b0e8240e15b4d98bc63','41502657c6b84465aa2ff94e620ed234',1934,'伪满洲国黑龙江省省长（后任财政部大臣）','继韩云阶后任伪黑龙江省长，驻齐齐哈尔，积极执行日本经济掠夺政策，强迫农民“出荷”粮食。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ccc1bf62504b4e4bb890b679530688a6','236b09af126745e997e5603fc3f56d0e',1937,'伪满洲国黑龙江省省长（后期）','清肃亲王善耆之子，投靠日本，任伪黑龙江省长，在齐齐哈尔地区强化治安，协助关东军围剿抗联。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a78ce34aa2d44b16b7ce22cb8afa1836','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1932,'伪满洲国黑龙江省警务厅长（驻齐齐哈尔）','原黑龙江省警察头目，投敌后任伪警务厅长，在齐齐哈尔及富拉尔基等地建立特务网络，抓捕抗日志士。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b31bac251b6a4a1ab4949646af1178f3','acf7dcdffeda4a0a87c947be2dd7f78a',1933,'伪满洲国齐齐哈尔市市长','任伪齐齐哈尔市长期间，推行奴化教育，强征劳工，为日军修建军事设施，迫害当地居民。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8efed67abd73465e9f3065ef5ce4cb31','68803f2fd5e44e7bbce3dfdf9f00f0e7',1932,'伪满洲国富拉尔基地区维持会会长','在富拉尔基（今齐齐哈尔市富拉尔基区）组织伪维持会，协助日军征粮、抓丁，报告抗日分子活动。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('164c4cb4a0fd474a934e56196f8c1370','b21d5a4d224a4173bdb0f2b366c98d70',1936,'伪满洲国黑龙江省协和会本部副本部长（驻齐齐哈尔）','负责在齐齐哈尔及富拉尔基地区宣传“日满亲善”，组织协和会，监控民众思想，强迫居民参加反共集会。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b308bebd9f48492d86dc6477e360aa60','3b74f508628f475a8777ffb7e38a48a0',1934,'伪满黑龙江省省长（1934-1937）','原黑龙江省实业厅长，投日后任伪省长，在齐齐哈尔、富裕一带强征粮税，镇压反满抗日活动','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9c08674b09c84f689f2dda3d702cbc0d','41502657c6b84465aa2ff94e620ed234',1937,'伪满黑龙江省省长（1937-1939）','原东北军文职官员，投日后任伪省长，在齐齐哈尔地区推行“治安肃正”，协助日军清剿抗联','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('0e7a6c2c8e384855b2a7442facb4d181','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1939,'伪满黑龙江省省长（1939-1942）','原黑龙江省政府参议，投日后任伪省长，在富裕县等地实施“归屯并户”，切断抗联与民众联系','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9e725ebcae9a4496b5e20ded7f0fc7a2','17ba4ca514844dcbb95b21c193e11290',1942,'伪满黑龙江省省长（1942-1945）','原黑龙江地方官僚，投日后任伪省长，在齐齐哈尔、富裕地区强抓劳工，供应日军军事工程','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('299485bcd7d0400893eabb0418312db6','4b486850921b4f33b616f1f8dcdef313',1932,'伪满黑龙江省省长（1932-1934）','原哈尔滨特别市市长，投日后首任伪黑龙江省长，在齐齐哈尔建立伪政权，镇压学生爱国运动','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8e7ddb0ed17549b2a348753fd0b1b91e','77a789268c6f47b4a617cdb9e41180bd',1931,'伪满国务总理大臣（1935-1945）','原东北军将领，1931年投敌，虽为伪满中央高官，但其势力范围涵盖黑龙江，对齐齐哈尔、富裕地区伪政权有直接控制','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4baca137d7ea497dbf1abe8414b5c59b','b8f5150658fd47f0a48c92aacb628181',1932,'伪满黑龙江省省长（1932年短暂投日）','原抗日将领，1932年2月一度投日任伪省长，但同年4月反正抗日，其短暂变节行为涉及齐齐哈尔地区','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('2504e3ed10fa43d9a7914ac75abb7255','c9dffc071fec4ce58fe1d611f26c28da',1933,'伪满富裕县县长（1933-1937）','原富裕县地方士绅，投日后任伪县长，协助日军建立保甲制度，强征军粮，迫害抗日家属','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('981edbc6a4be4510b2153821a6e90588','ba135ba1ef794aeba0fdad0065a31974',1937,'伪满富裕县县长（1937-1940）','原齐齐哈尔市警察署长，投日后调任富裕县，推行“连坐法”，多次配合日军突袭抗联秘密联络点','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9545e5609ea843329e1eafa597a6095a','a2c03b81e5f2412bb86f5d5599c1687b',1932,'伪满富裕县警察署署长','原富裕县民团头目，投日后任伪警察署长，抓捕抗联交通员，严刑逼供，杀害多名抗日群众','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('22044d3872cd4d6d85af2e95cff43f75','3cd55e29febc489d9f9a7f2f88db31bb',1932,'伪满齐齐哈尔市市长（1932-1935）','原齐齐哈尔商会会长，投日后任伪市长，为日军筹措军费，强征民夫修建军用机场','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a2c8fb111c294453a892ac4c63521ff7','2228d7bd1de942ea89d581fa87cc8921',1935,'伪满齐齐哈尔市市长（1935-1938）','原黑龙江省政府科长，投日后任伪市长，推行“粮谷出荷”，导致富裕地区农民饥荒','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b0ea09404d9b4a7496b0b4c99beff45a','46f570699efd413fa741462847e46f14',1938,'伪满齐齐哈尔市市长（1938-1941）','原齐齐哈尔中学教员，投日后任伪市长，建立奴化教育体系，强迫学生参加“勤劳奉仕”','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('137171abb93d4e89823e8ec00bc68fde','0ce72eece3db48fc91bb0e9928ba9e67',1941,'伪满齐齐哈尔市市长（1941-1945）','原伪满民政部官员，调任齐齐哈尔后，配合日军“特别治安”行动，在富裕县设立集中营','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('36fb93154e934b2aa818db57353c8a61','6960ecf5067148b08c7571d02c447623',1934,'伪满富裕县协和会会长','原富裕县地主，投日后任协和会会长，组织汉奸宣传队，煽动民众告发抗联活动','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('69a694abeb3a4ff9a3d7705477163d0f','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1932,'伪黑龙江省警务厅厅长（齐齐哈尔）','齐齐哈尔人，投日后任伪省警务厅厅长，组织伪警察和特务机构，大肆搜捕抗日地下工作者，破坏抗联地下联络站，制造多起血腥镇压事件。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('09fdf136392743029eb4eae1433d43c2','3b74f508628f475a8777ffb7e38a48a0',1932,'伪黑龙江省财政厅厅长（齐齐哈尔）','齐齐哈尔人，原为地方士绅，投日后主管伪省财政，为日军筹措军费，强征苛捐杂税，掠夺粮食资源，支援日本侵华战争。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('18d8d80c4005449cb34176e6b202b63a','3cd55e29febc489d9f9a7f2f88db31bb',1933,'伪齐齐哈尔市市长','齐齐哈尔本地人，投日后出任伪市长，推行日本殖民统治，实施保甲制度，强制居民领取“良民证”，协助日军清乡，镇压抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3c85a01ff88642cb842515ac5337617c','665f80372f694c89a3f815b06401a0bb',1932,'伪齐齐哈尔市警察局局长','齐齐哈尔人，投日后任伪警察局长，指挥伪警配合日军宪兵队，多次突袭抗联秘密据点，逮捕并刑讯抗日志士，双手沾满鲜血。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9799f8e536954635a12b00094b8395e7','338f801833204de29136634230b7aa4a',1934,'伪齐齐哈尔地区协和会头目','齐齐哈尔人，任伪协和会齐齐哈尔本部总务部长，积极宣传“日满亲善”，组织奴化教育，煽动民众告密，破坏抗日群众组织。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('06c3bd26336645398c165a38c908e060','93f14e1340304e9cac4d12a04a6586a6',1932,'伪黑龙江省保安队队长（齐齐哈尔）','齐齐哈尔人，投日后任伪保安队长，率伪军多次围剿抗联小分队，在嫩江流域烧毁村庄，屠杀抗日群众，罪行累累。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('22fdfa8c07174f4384e637e617b9b9e5','ba135ba1ef794aeba0fdad0065a31974',1933,'伪齐齐哈尔宪兵队翻译官','齐齐哈尔人，精通日语，为日本宪兵队充当翻译，参与审讯和酷刑迫害抗日志士，直接协助日军制造多起惨案。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ffdf494404fb4d7cb90f47217c98fbcd','77aa4951751342b79a81e38d021b4396',1932,'伪满齐齐哈尔市市长','曾任齐齐哈尔市伪市长，积极推行日伪殖民政策，强征劳工，为日军提供物资，协助镇压当地抗日活动。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c7b3d3bb449b4e1eaaafea46b6e62141','acf7dcdffeda4a0a87c947be2dd7f78a',1933,'伪满黑龙江省教育厅厅长','在齐齐哈尔地区推行奴化教育，强制学校教授日语，删除中国历史内容，迫害爱国教师，协助日伪进行思想控制。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ea3dd4b945a34da695d39fa7a08ba072','b21d5a4d224a4173bdb0f2b366c98d70',1932,'伪满拜泉县县长','任拜泉县伪县长期间，组织伪县公署，配合日军清乡，强征农民粮食，抓捕抗日联军联络员，向日军提供抗日武装情报。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('26526c16a6624d4796ba8415730a70e9','77a789268c6f47b4a617cdb9e41180bd',1931,'伪满国务总理大臣（曾任黑龙江地区伪职）','原东北军将领，九一八事变后投敌，曾任伪满黑龙江省省长（早期），后升任伪满国务总理，虽主要活动于新京，但其早期在黑龙江（含齐齐哈尔、拜泉）的伪政权建设中起关键作用，支持日军镇压抗日力量。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('1fe83c71e4fa4298bcbd69fa702473b4','b8f5150658fd47f0a48c92aacb628181',1932,'伪满黑龙江省省长（短暂投日时期）','1932年2月一度接受伪满任命，任伪黑龙江省省长（齐齐哈尔），但同年4月反正抗日，故其汉奸身份短暂且存争议，但历史档案中列入伪职名录。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e548afba3f1e4377b4e797000b4f90d7','e25c85c91f604ceda710a0637532c900',1932,'伪满洲国第一军管区司令官（驻齐齐哈尔）','原东北军将领，叛国投日，在齐齐哈尔地区围剿抗日武装，制造多起惨案，后任伪满治安部大臣','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5b784ea057684f50b81f5075a920a22f','b8f5150658fd47f0a48c92aacb628181',1932,'伪黑龙江省长（短暂投敌）','江桥抗战后一度诈降，任伪黑龙江省长，后反正抗日，但投敌期间为日伪效力，属争议人物','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d17e2f81232e49ba973461b685d7cb63','77aa4951751342b79a81e38d021b4396',1932,'伪黑龙江省公署参事、齐齐哈尔市长','原黑龙江省议员，积极投靠日军，参与组织伪政权，协助日军统治齐齐哈尔，镇压反满抗日活动','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('20ad3a8d6a9f487fa9b998495871aaef','3cd55e29febc489d9f9a7f2f88db31bb',1933,'伪昂昂溪警察署署长','在昂昂溪地区为日军效力，镇压铁路工人抗日活动，协助日军抓捕地下抗日人员，罪行累累','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c568d82817554073a15f5547301742ab','1ba31d558b934fbd83a28a8c2b446022',1932,'伪满热河省长（曾驻黑龙江）','原洮辽镇守使，九一八后投敌，在黑龙江北部及齐齐哈尔外围协助日军清剿抗日义勇军，后调任热河','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('eae2dc5c3fb546319cecb1b909613629','a984ebfabbf64a5b8e1dfef2d68daa53',1932,'伪满吉林警备司令（曾活动于黑龙江）','原东北军旅长，一度抗日后投敌，在黑龙江东部及齐齐哈尔周边参与围剿抗联，后任伪满要职','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('f1ef161de92f4ccdb1f4f6144bd6da64','2acf7a5b9b5341578e1066b27394b2eb',1932,'伪满军政部顾问（驻齐齐哈尔）','原奉系将领，投日后任伪满军事顾问，协助日军整编伪军，在齐齐哈尔地区训练伪军对抗抗联','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('826ac9ade2554e25b2c3e1d408e12359','3c793b1442ef48298a262b0d57814cab',1931,'伪满洲国黑龙江省省长、伪满军中将','原东北军骑兵第二旅旅长，江桥抗战后随马占山一度抗日，后叛变投敌，任伪黑龙江省省长、伪满军中将，协助日军镇压黑龙江抗日力量，其统治区域覆盖齐齐哈尔。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('fe24e4ac1d9c4489a85fea941f6fdeab','3b74f508628f475a8777ffb7e38a48a0',1931,'伪满洲国黑龙江省省长、伪满洲国经济部大臣','辽宁金县人，九一八事变后投敌，1932年任伪黑龙江省省长，后任伪满洲国经济部大臣、热河省省长等职，在黑龙江地区推行日本经济掠夺政策。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('76e68d8148b44c42be699966f84aad84','77aa4951751342b79a81e38d021b4396',1931,'伪满洲国黑龙江省公署厅长、伪满协和会要员','原黑龙江省官员，九一八事变后投敌，在伪黑龙江省公署任职，参与组织伪政权和协和会活动，协助日军控制齐齐哈尔及周边地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5ab9d87e4e944506988bb971fedc97a5','76877234e49e40abbd0e65850b11abac',1931,'伪满洲国齐齐哈尔警察厅厅长','伪满时期在齐齐哈尔警察系统任职，参与镇压齐齐哈尔地区抗日活动，搜捕抗日志士，推行保甲连坐制度。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('d8d35ebc4bf541248db87439c190c1a4','c904a3bb584e47459dd2323f9459412e',1931,'伪满洲国齐齐哈尔地区维持会会长','齐齐哈尔地方士绅，日军占领齐齐哈尔后出面组织维持会，协助日军维持地方秩序、征发物资，为伪政权建立提供地方支持。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('545f600cdeac46c6bdf2651039c0f009','56e668bf262e4d84a8cfe302e67fed6a',1931,'伪满洲国龙江省公署参事官、伪满协和会龙江省本部要员','在伪龙江省（辖齐齐哈尔地区）任职，参与推行伪满殖民政策，组织协和会进行奴化宣传，协助日军征发劳工和物资。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a3192c6b35744e039ef4b952a364a164','8faa98f8ed714b9bb0bd342396a2846a',1931,'伪满洲国龙江县县长','伪满时期任龙江县县长，管辖区域包括今齐齐哈尔市区及梅里斯一带，推行保甲制度，协助日军征粮征丁，镇压地方抗日活动。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('7be87a8e2df443a09772489fb5863044','350822a1078340679fd657c16a793993',1931,'伪满洲国龙江省省长','伪满时期曾任龙江省省长，管辖齐齐哈尔及周边地区，推行日本殖民统治政策，协助经济掠夺和劳工征发。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9b1d14a13de9496085c6a8fee8d3c0bc','5a42f897a627483f9ceda7a629ea37f8',1931,'伪满洲国龙江省省长、伪满洲国勤劳奉公部大臣','伪满时期历任龙江省省长、勤劳奉公部大臣等职，在齐齐哈尔地区推行劳工征发政策，为日本侵略战争提供人力物力支持。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('17449ba7606e48e484d03a977153c028','acf7dcdffeda4a0a87c947be2dd7f78a',1931,'伪满洲国龙江省教育厅厅长、伪满协和会要员','在伪龙江省教育系统任职，推行奴化教育，篡改历史教材，向齐齐哈尔地区学生灌输亲日思想，协助日军进行文化侵略。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('88a2a6f9e652434f9cc5c8e12d321e09','58810d67711e4176a4293723665a9ab6',1931,'伪满洲国齐齐哈尔铁路局警护队队长','在齐齐哈尔铁路系统任职，配合日军保护铁路运输，镇压铁路沿线抗日活动，参与搜捕抗日地下工作者。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('11c739c5f3ce45d9973165369579d625','3cd55e29febc489d9f9a7f2f88db31bb',1931,'伪满洲国梅里斯地区保长','伪满时期任梅里斯地区保长，协助日军征粮征丁，推行保甲连坐，监视当地居民，镇压抗日活动。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bd88f03924284fac90440828f1c0b0bb','c1e4fcc6b60c4b35a1723f46a2175972',1931,'伪满洲国龙江省协和会本部事务长','在伪龙江省协和会任职，组织亲日宣传和奴化教育活动，协助日军控制齐齐哈尔地区民众思想。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('3da233cb8430456aba228651acb8b336','6575bf6c75154079a0b0c04e45af6a26',1931,'伪满洲国齐齐哈尔市商会会长','伪满时期任齐齐哈尔市商会会长，协助日军征发物资、摊派款项，配合经济统制政策，为日军侵略提供经济支持。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5c3bc02bd9494032803cb6ccc955c001','cc04262f46964da7a7d0010566743c38',1931,'伪满洲国龙江省公署警务厅厅长','在伪龙江省警务系统任职，指挥伪警察镇压齐齐哈尔地区抗日活动，搜捕抗日人员，推行法西斯统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8e17d50757404d7a9d5f9a62ac2dc4e3','84779a454ec74ec19985a1b53e006685',1931,'伪满奉天省省长、伪满参议府议长','原奉系军阀官员，后投靠日本，任伪满奉天省省长，推行殖民政策，协助日军掠夺资源，镇压抗日力量。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e0d4c21d584049fcb2a81dbb77071d0c','41502657c6b84465aa2ff94e620ed234',1933,'伪满黑龙江省省长（1933-1935）','原黑龙江省财政厅长，投敌后任伪满黑龙江省省长，期间积极为日军征粮派夫，破坏抗日组织。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('007d8426293248fe86abae42e41122f3','ea7bda061c4b4fd1a90fa9ce5c3ebe58',1935,'伪满黑龙江省省长（1935-1937）','原东北军将领，投日后任伪满黑龙江省省长，协助日军清剿抗日武装，推行保甲制度。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('169ad7d884344e829371cc84d194cda0','e25c85c91f604ceda710a0637532c900',1937,'伪满黑龙江省省长（1937-1939）','原吉林军将领，投敌后任伪满黑龙江省省长，曾率伪军参与对抗日联军的围剿，在泰来、齐齐哈尔一带活动。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('23cb503c00ad4c7486101b9716a408d5','b8f5150658fd47f0a48c92aacb628181',1932,'伪满黑龙江省省长（1932年短暂任职）','原黑龙江省代主席，1932年2月一度投降日军，任伪满黑龙江省省长，但同年4月反正，重新抗日，故其投敌行为短暂且后反正，通常不列为汉奸，但历史记录中曾有此段。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('efa40c0cdf8c435aae9f980d2f68c46c','236b09af126745e997e5603fc3f56d0e',1932,'伪满齐齐哈尔市市长（1932-1933）','原黑龙江地方官员，投敌后任伪满齐齐哈尔市市长，协助日军维持治安，推行殖民统治。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9af9aff0d49a4947833740d93da68d86','3cd55e29febc489d9f9a7f2f88db31bb',1933,'伪满齐齐哈尔市市长（1933-1935）','原齐齐哈尔地方士绅，投日后任伪满齐齐哈尔市市长，参与奴化宣传和物资搜刮。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('aa31c177481d4c3787497491e57a09a1','29a829baea1349b69f8cf6b6d13c3bd9',1935,'伪满齐齐哈尔市市长（1935-1937）','原黑龙江省政府官员，投敌后任伪满齐齐哈尔市市长，配合日军清乡，迫害抗日家属。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ad9f080cba664d5ea200cdbacc36bdb7','77aa4951751342b79a81e38d021b4396',1932,'伪满泰来县县长（1932-1934）','原泰来县地方官员，投敌后任伪满泰来县县长，为日军提供情报，镇压当地抗日义勇军。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('16a51e81476b4953a0068ad529a53587','8d6005d96b0d49c5950907d37d701f40',1934,'伪满泰来县县长（1934-1936）','原泰来县士绅，投日后任伪满泰来县县长，推行“归屯并户”，切断抗日联军与群众联系。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4ee59e0655fa4ca9962d2b60df9bf86e','9b39cebcf825472fabf4077c5ba9933f',1932,'伪满泰来县警察署长','原泰来县警察，投敌后任伪满泰来县警察署长，率伪警抓捕抗日人员，参与多起屠杀事件。','无明确职位或一般帮凶','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('a11265d130be493da21ad0f885a2e64c','3a9e402192aa460fb51a927d874bb93e',1932,'伪满黑龙江地区保安队队长','原地方土匪头目，投日后任伪满保安队队长，在齐齐哈尔、泰来一带协助日军围剿抗日游击队，烧杀抢掠。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('c432b2af8ecb439386c6c7724f5e1152','1d67ff455ffc47b8addcc485beb0ca34',1931,'伪满洲国军政部大臣、伪第一军管区司令官','原东北军将领，九一八事变后投敌，任伪奉天警备司令、伪满洲国军政部大臣，统辖伪军参与镇压东北抗日武装，其军事活动范围包括黑龙江、齐齐哈尔地区。；原东北军将领，九一八事变后投敌，任伪奉天警备司令、伪军政部大臣，统辖伪军参与镇压东北抗日武装，其伪军活动范围包括黑龙江、齐齐哈尔地区。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('510cc48a42474c26afce246ad0bdf183','1ba31d558b934fbd83a28a8c2b446022',1931,'伪满洲国洮辽镇守使、伪热河省警备司令官','原东北军洮辽镇守使，九一八事变后投敌，率部配合日军进攻黑龙江，参与江桥战役对马占山部的作战，后任伪热河省警备司令官，是黑龙江地区早期投敌的伪军头目之一。；原东北军洮辽镇守使，九一八事变后投敌，率部配合日军进攻黑龙江，参与江桥战役对抗马占山抗日军，后任伪热河省警备司令官，为黑龙江地区早期汉奸武装头目之一。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6de2e9a37307460385db29d397734cc2','3c793b1442ef48298a262b0d57814cab',1931,'伪满洲国黑龙江省警备司令官、伪第三军管区司令官','原东北军骑兵旅长，江桥抗战后投敌，任伪黑龙江省警备司令官，率伪军配合日军镇压黑龙江抗日武装，其活动直接覆盖齐齐哈尔及甘南周边地区。；原东北军骑兵旅长，九一八事变后随马占山抗日，后于1932年投降日军，任伪黑龙江省警备司令官，率伪军配合日军镇压黑龙江抗日武装，直接活动于齐齐哈尔及龙沙地区。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('04a0f7d261e84adea31129c46f93cb99','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满洲国黑龙江省警备司令部参谋长、伪军管区司令','原东北军军官，随程志远投敌，任伪黑龙江省警备司令部要职，参与围剿黑龙江抗日联军，活动于齐齐哈尔一带。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('79c631217fc54a899b0890a45104fc61','3b74f508628f475a8777ffb7e38a48a0',1931,'伪满洲国黑龙江省长、伪经济部大臣','辽宁金县人，九一八事变后投敌，1932年任伪黑龙江省长，后任伪满洲国经济部大臣，在齐齐哈尔主持伪省政，推行日本殖民经济政策。；辽宁金州人，九一八事变后投敌，任伪黑龙江省长，后任伪经济部大臣，参与伪满经济统制与掠夺，其活动涉及齐齐哈尔地区。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e493e3dcaae84f939b137aafdcc4c28d','41502657c6b84465aa2ff94e620ed234',1932,'伪满洲国黑龙江省长、伪财政部大臣','辽宁辽阳人，九一八事变后投敌，曾任伪黑龙江省长，后任伪满洲国财政部大臣，参与伪满财政体系构建，其任职期间管辖齐齐哈尔地区。','省部级/大军区级要员','hanjian');
