INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4d412e072bbf4219934c95596f38861a','350822a1078340679fd657c16a793993',1931,'伪满洲国黑龙江省长、伪司法部大臣','辽宁人，投敌后历任伪黑龙江省长、伪司法部大臣，在齐齐哈尔推行伪满法令，镇压抗日活动。；原东北军军官，九一八事变后投敌，曾任伪黑龙江省长，后任伪司法部大臣，为伪满地方与中央政权附逆者，其统治涉及齐齐哈尔地区。','省部级/大军区级要员','hanjian');
