INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('406a3061fbe444f6802678bbb8b5069a','4b486850921b4f33b616f1f8dcdef313',1932,'伪满民政部大臣、伪滨江省省长（曾管辖讷河地区）','参与伪满政权建设，推行保甲制度，协助日军在讷河等地建立伪基层政权。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4a0a2a52f3d148ed969be6e3dd512b9e','77a789268c6f47b4a617cdb9e41180bd',1931,'伪满国务总理大臣（原黑龙江省军阀）','作为伪满最高汉奸之一，全面配合日军统治，其势力范围覆盖黑龙江包括齐齐哈尔、讷河地区。','伪政权最高层/元首级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('ec5550d4dd2f42598fee2eff10c3a08d','b8f5150658fd47f0a48c92aacb628181',1932,'伪满黑龙江省长（短暂投敌后反正）','一度投降日军任伪职，但不久反正抗日，其投敌行为在讷河地区有短暂影响。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('e1c658adc5f346c193f1ee24c097a96a','3c793b1442ef48298a262b0d57814cab',1932,'伪黑龙江省骑兵师长、伪满军政部次长','率伪骑兵在讷河、富裕一带追击抗联部队，杀害抗联第三路军指战员。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6c49e465cefb4e13863d7d0ecbdc71d8','b21d5a4d224a4173bdb0f2b366c98d70',1932,'伪讷河县县长','在讷河县推行日伪法令，组织伪自卫团，协助日军抓捕抗联地下工作者。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('dc2d74378e0d42c8b9b51d0e2396e8b8','3cd55e29febc489d9f9a7f2f88db31bb',1933,'伪讷河县警务科科长','指挥伪警察在讷河农村“扫荡”，烧毁抗联密营，逮捕并刑讯抗日群众。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8fc39935faa043baa28ff3b4000e2b9b','80d67f99a8d04e52a1b2434f1d99805e',1935,'伪讷河县协和会会长','宣传“日满亲善”，组织汉奸团体，刺探抗联情报，破坏抗日组织。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6424262e52e84685943478a88367b45c','3a9e402192aa460fb51a927d874bb93e',1934,'伪齐齐哈尔地区保安队队长','率保安队配合日军在讷河、克山交界处“讨伐”，杀害抗联战士多人。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('41902596073b4b4b950adf9257180f88','5f8f1bdeab2443a586dc30df423055ea',1932,'伪黑龙江省教育厅长','在齐齐哈尔、讷河推行奴化教育，强制学校教授日语，篡改历史教材。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('8acb117885b243cc8c779d99639515b5','41502657c6b84465aa2ff94e620ed234',1932,'伪满洲国黑龙江省长、伪财政部次长','辽宁辽阳人，1932年投敌，曾任伪黑龙江省长，后任伪财政部次长等职，参与伪满财政经济统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('868830c4f7ea4458836b21472d413b80','c9dffc071fec4ce58fe1d611f26c28da',1932,'伪满洲国齐齐哈尔警察厅厅长','在齐齐哈尔地区担任伪警察头目，负责维持治安、镇压抗日活动，配合日军搜捕抗日人员。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5d5ca1544d164496965d0e83bd02170a','350822a1078340679fd657c16a793993',1932,'伪满洲国齐齐哈尔市长、伪黑龙江省民政厅长','在齐齐哈尔地区任职，参与伪政权地方行政管理，推行保甲制度，协助日军控制地方。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('30f0f3f8c3544f629386a6569564d423','3cd55e29febc489d9f9a7f2f88db31bb',1931,'伪满洲国齐齐哈尔维持会会长','九一八事变后，在齐齐哈尔组织维持会，协助日军维持地方秩序，为伪政权建立做准备。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('b2c45326a3d24733a2641ae8b096e8e9','56e668bf262e4d84a8cfe302e67fed6a',1932,'伪满洲国铁锋地区保甲长','在铁锋地区担任伪保甲长，负责征收赋税、摊派劳工，协助日军控制基层社会。','一般帮凶/基层人员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('9f91e0b6339a4718942c9f5d020dd138','77aa4951751342b79a81e38d021b4396',1932,'伪满洲国黑龙江省教育厅长','在黑龙江地区推行奴化教育，篡改历史教材，宣传“日满亲善”，毒害青少年。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('19d99e9515a14e1199116b2a5ef2edf6','6876b4dc973441299b47d406050a627f',1932,'伪满洲国黑龙江省实业厅长','在黑龙江地区推行经济统制，协助日军掠夺粮食、矿产等资源，压榨当地民众。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('6fe3ad5832bd42e996d19486790f3a95','c9dffc071fec4ce58fe1d611f26c28da',1931,'伪满洲国黑龙江省警备司令部司令、伪第四军管区司令官','原东北军军官，九一八事变后投敌，任伪黑龙江省警备司令部司令，后任伪第四军管区司令官，驻齐齐哈尔，统辖伪军镇压黑龙江抗日力量。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('984480a04b0c409cb8bb697ef4ac3496','5a42f897a627483f9ceda7a629ea37f8',1931,'伪满洲国哈尔滨市长、伪滨江省长','辽宁人，九一八事变后投敌，长期在伪满地方政权任职，曾任哈尔滨市长、滨江省长，其活动范围接近黑龙江齐齐哈尔地区，参与伪满地方统治。','省部级/大军区级要员','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('5e44379711854733acb7d376a2f1bd2c','c276a824877f4dce865833533f6312bf',1931,'伪满洲国齐齐哈尔市长','伪满时期曾任齐齐哈尔市长，参与伪满地方行政管理，直接活动于齐齐哈尔及龙沙地区，为当地伪政权附逆者。','市县厅局级','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('4fad609c6eae463d8a824bd7fbac2561','c8661ee02d9e4364b8cda3581c64401d',1931,'伪满洲国齐齐哈尔市维持会会长','九一八事变后，在齐齐哈尔组织维持会，协助日军维持地方秩序，为日军侵占齐齐哈尔提供地方支持，直接活动于齐齐哈尔及龙沙地区。','基层维持会/地方自治头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('de4b6dba5e6840f583ad2d86cb6cbc12','56e668bf262e4d84a8cfe302e67fed6a',1931,'伪满洲国龙江县县长','伪满时期曾任龙江县县长，龙江县治所位于齐齐哈尔，其行政活动直接覆盖齐齐哈尔及龙沙地区，参与伪满地方统治与物资征调。','基层头目','hanjian');
INSERT INTO `crimerecords` (`Id`,`TraitorId`,`Year`,`Title`,`Process`,`Harm`,`SourceRef`) VALUES ('bcb2a57209c1470e83b06f1081ae92c3','cc04262f46964da7a7d0010566743c38',1931,'伪满洲国齐齐哈尔市商会会长','伪满时期任齐齐哈尔市商会会长，协助日军进行经济统制与物资征集，为当地经济领域附逆者，活动于齐齐哈尔及龙沙地区。','基层头目','hanjian');
